// p5.js 1.11 — self-contained, deterministic still painting.

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();

  paintGround();
  groundScumble();
  distantStrata();
  paintAbsence();
  paintBoundary();
  unravel();
  foregroundStrata();
  pigmentDust();
  canvasGrain();
}

function smooth(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function edge(a, s = 1) {
  const wobble =
    1 +
    0.024 * sin(3 * a + 0.8) +
    0.018 * sin(7 * a - 1.2) +
    0.009 * sin(13 * a);

  return {
    x: 810 + s * (
      415 * cos(a) * wobble +
      61 * sin(a) +
      12 * sin(2 * a)
    ),
    y: 885 + s * (
      632 * sin(a) * wobble +
      14 * cos(3 * a)
    )
  };
}

function contourPath(s) {
  const ctx = drawingContext;
  ctx.beginPath();
  for (let i = 0; i <= 360; i++) {
    const p = edge(TWO_PI * i / 360, s);
    if (i === 0) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  }
  ctx.closePath();
}

function paintGround() {
  const g = createGraphics(400, 500);
  g.pixelDensity(1);
  g.loadPixels();

  for (let y = 0; y < 500; y++) {
    for (let x = 0; x < 400; x++) {
      const u = x / 400;
      const v = y / 500;
      const n = noise(u * 5, v * 6);
      const fine = noise(x * 0.13, y * 0.13) - 0.5;
      const warmth = exp(
        -sq((u - 0.19) / 0.29) -
        sq((v - 0.46) / 0.46)
      );
      const lower = smooth(0.53, 0.99, v);
      const vignette = 1 - 0.21 * (
        sq((u - 0.5) * 1.5) + sq((v - 0.5) * 1.4)
      );
      const i = 4 * (x + y * 400);

      g.pixels[i] =
        (17 + 16 * n + 37 * warmth + 20 * lower + fine * 9) * vignette;
      g.pixels[i + 1] =
        (24 + 15 * n + 23 * warmth + 18 * lower + fine * 8) * vignette;
      g.pixels[i + 2] =
        (29 + 17 * n + 8 * warmth + 23 * lower + fine * 8) * vignette;
      g.pixels[i + 3] = 255;
    }
  }
  g.updatePixels();
  image(g, 0, 0, W, H);
  g.remove();
}

function groundScumble() {
  noFill();
  strokeCap(SQUARE);

  const colors = [
    [119, 101, 73],
    [69, 85, 89],
    [22, 33, 38],
    [153, 133, 96],
    [38, 49, 52]
  ];

  // Thin, dragged layers of underpainting.
  for (let i = 0; i < 11000; i++) {
    const x = random(W);
    const y = random(H);
    const c = random(colors);
    const n = noise(x * 0.003, y * 0.003);
    stroke(c[0], c[1], c[2], random(3, 17));
    strokeWeight(random(0.5, 3.5));
    const len = random(5, 56);
    line(x, y, x + (n - 0.5) * 15, y + len);
  }

  // Uneven deposits, rather than a uniformly smooth surface.
  noStroke();
  for (let i = 0; i < 21000; i++) {
    const x = random(W);
    const y = random(H);
    const c = random(colors);
    fill(c[0], c[1], c[2], random(3, 14));
    ellipse(x, y, random(1, 8), random(1, 4));
  }
}

function distantStrata() {
  noFill();
  for (let k = 0; k < 190; k++) {
    const y0 = random(1120, 1990);
    const warm = random() < 0.24;
    stroke(
      warm ? 139 : 93,
      warm ? 112 : 111,
      warm ? 77 : 117,
      random(4, 17)
    );
    strokeWeight(random(0.5, 2.2));

    beginShape();
    for (let x = -30; x <= W + 30; x += 15) {
      const y =
        y0 +
        16 * sin(x * 0.003 + y0 * 0.008) +
        33 * (noise(x * 0.002, y0 * 0.004) - 0.5);
      vertex(x, y);
    }
    endShape();
  }
}

function paintAbsence() {
  const ctx = drawingContext;

  // The center is opaque above, but loses its distinction below.
  ctx.save();
  contourPath(1.015);
  const wash = ctx.createLinearGradient(0, 240, 0, 1580);
  wash.addColorStop(0, "rgba(10,17,19,0.99)");
  wash.addColorStop(0.48, "rgba(9,16,19,0.99)");
  wash.addColorStop(0.72, "rgba(12,21,24,0.94)");
  wash.addColorStop(0.87, "rgba(20,29,31,0.51)");
  wash.addColorStop(1, "rgba(28,36,38,0)");
  ctx.fillStyle = wash;
  ctx.fill();

  contourPath(1.005);
  ctx.clip();

  // Subtle brushwork keeps the dark area material, not empty screen.
  noFill();
  for (let i = 0; i < 4300; i++) {
    const x = random(330, 1280);
    const y = random(220, 1530);
    const fade = 1 - smooth(1060, 1530, y);
    stroke(69, 78, 76, random(1, 7) * fade);
    strokeWeight(random(0.5, 2.2));
    const drift = 9 * (noise(x * 0.006, y * 0.004) - 0.5);
    line(x, y, x + drift, y + random(4, 61));
  }

  noStroke();
  for (let i = 0; i < 10500; i++) {
    const x = random(320, 1290);
    const y = random(220, 1500);
    const fade = 1 - smooth(1070, 1510, y);
    fill(112, 116, 100, random(1, 7) * fade);
    rect(x, y, random(0.5, 2), random(0.7, 3));
  }
  ctx.restore();
}

function paintBoundary() {
  noFill();
  strokeCap(ROUND);

  // Broad, bruised ochre beneath the surviving edge.
  for (let j = 0; j < 38; j++) {
    const s = 1.016 + j * 0.0024;
    stroke(111, 85, 51, 5 + 8 * sin(PI * j / 38));
    strokeWeight(random(2, 6));
    beginShape();
    for (let a = -3.73; a < -0.18; a += 0.018) {
      const p = edge(a, s);
      vertex(p.x, p.y);
    }
    endShape();
  }

  const umber = color(100, 79, 49);
  const ochre = color(172, 145, 96);
  const bone = color(224, 211, 168);

  // Hundreds of broken bristles form one imperfect membrane.
  for (let j = 0; j < 148; j++) {
    const t = j / 147;
    const s = 0.985 + 0.102 * t;
    const c = t < 0.62
      ? lerpColor(bone, ochre, t / 0.62)
      : lerpColor(ochre, umber, (t - 0.62) / 0.38);

    const start = random(-3.93, -3.49);
    const finish = random(-0.72, 0.18);
    const phase = random(100);
    strokeWeight(random(0.55, 1.9));

    let prev = null;
    for (let a = start; a < finish; a += 0.012) {
      const jitter = (noise(a * 5 + 30, j * 0.13) - 0.5) * 0.009;
      const p = edge(a, s + jitter);
      const leftness = pow((1 - cos(a)) / 2, 0.45);
      const topness = max(0, -sin(a));
      const strength = constrain(
        0.13 + 0.64 * leftness + 0.28 * topness, 0, 1
      );
      const breakup = noise(a * 17 + phase, j * 0.19);

      if (prev && breakup > 0.31 && random() > 0.035) {
        stroke(
          red(c), green(c), blue(c),
          random(23, 85) * strength
        );
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;
    }
  }

  // Cold remnants of the right edge, never a complete enclosure.
  for (let j = 0; j < 27; j++) {
    stroke(118, 140, 138, random(5, 21));
    strokeWeight(random(0.5, 1.4));
    const s = random(0.988, 1.025);
    let prev = null;

    for (let a = -0.48; a < 1.1; a += 0.016) {
      const p = edge(a, s);
      if (prev && noise(a * 9 + 40, j * 0.31) > 0.48) {
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;
    }
  }

  // Small lifted flakes along the old boundary.
  noStroke();
  for (let i = 0; i < 1700; i++) {
    const a = random(-3.7, -0.55);
    const p = edge(a, random(0.986, 1.087));
    if (noise(p.x * 0.018, p.y * 0.018) < 0.46) continue;
    fill(231, 215, 169, random(8, 48));
    push();
    translate(p.x, p.y);
    rotate(a + HALF_PI);
    ellipse(0, 0, random(0.5, 2.2), random(1, 6));
    pop();
  }
}

function unravel() {
  noFill();
  strokeCap(ROUND);

  // The membrane ceases to close and becomes ordinary horizontal matter.
  for (let i = 0; i < 175; i++) {
    const a = random(2.12, 2.62);
    const p = edge(a, random(0.995, 1.087));
    const length = random(200, 650);
    const sweep = random(-310, 390);
    const warmth = random();
    let prev = p;

    for (let j = 1; j <= 70; j++) {
      const t = j / 70;
      const bend = smooth(0.05, 0.92, t);
      const x =
        p.x + sweep * bend +
        26 * sin(t * PI) * (noise(i * 0.11, t * 3) - 0.5);
      const y =
        p.y + length * (1 - pow(1 - t, 2.5)) +
        9 * sin(t * 7 + i) * t;
      const alpha = (1 - t) * random(9, 38);

      stroke(
        137 + warmth * 60,
        122 + warmth * 46,
        90 + warmth * 26,
        alpha
      );
      strokeWeight(random(0.45, 1.35));
      if (random() > 0.13) line(prev.x, prev.y, x, y);
      prev = { x, y };
    }
  }

  // Sparse rust-colored residue on the opposite side.
  for (let i = 0; i < 55; i++) {
    const p = edge(random(0.49, 1.12), random(0.99, 1.04));
    stroke(143, 88, 61, random(7, 24));
    strokeWeight(random(0.6, 1.5));
    bezier(
      p.x, p.y,
      p.x - 30, p.y + 100,
      p.x + 150, p.y + 185,
      p.x + random(100, 290), p.y + random(150, 320)
    );
  }
}

function foregroundStrata() {
  noFill();
  strokeCap(SQUARE);

  // These marks cross the former interior and exterior without distinction.
  for (let i = 0; i < 510; i++) {
    const y0 = random(1280, 1960);
    const fade = smooth(1280, 1700, y0);
    const x0 = random(-160, 1400);
    const len = random(70, 660);
    const c = random([
      [95, 110, 112],
      [126, 123, 104],
      [57, 73, 80],
      [151, 130, 91],
      [29, 43, 49]
    ]);

    stroke(c[0], c[1], c[2], random(6, 25) * (0.3 + fade));
    strokeWeight(random(0.45, 2.3));
    beginShape();
    for (let j = 0; j <= 36; j++) {
      const x = x0 + len * j / 36;
      const y =
        y0 +
        15 * sin(x * 0.0032 + y0 * 0.008) +
        23 * (noise(x * 0.0025, y0 * 0.006) - 0.5);
      vertex(x, y);
    }
    endShape();
  }

  // A few broader scrapes bury portions of the loose filaments.
  for (let i = 0; i < 85; i++) {
    const x = random(150, 1350);
    const y = random(1490, 1890);
    stroke(48, 62, 68, random(5, 16));
    strokeWeight(random(3, 12));
    line(x, y, x + random(30, 240), y + random(-8, 8));
  }
}

function pigmentDust() {
  noStroke();

  for (let i = 0; i < 18000; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.012, y * 0.012);
    if (n < 0.42) continue;

    const bright = random() < 0.36;
    fill(
      bright ? 190 : 8,
      bright ? 174 : 17,
      bright ? 135 : 21,
      random(3, 15)
    );
    const r = random(0.45, 1.65);
    ellipse(x, y, r, r * random(0.6, 1.8));
  }
}

function canvasGrain() {
  loadPixels();

  // Fine pigment variation plus a barely visible woven support.
  for (let y = 0; y < H; y++) {
    const weft = (y % 4 === 0) ? -0.9 : 0.25;

    for (let x = 0; x < W; x++) {
      const i = 4 * (x + y * W);
      const warp = (x % 5 === 0) ? -0.7 : 0.15;
      const grain = random(-5.1, 5.1) + warp + weft;

      pixels[i] = constrain(pixels[i] + grain, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + grain * 0.91, 0, 255);
    }
  }
  updatePixels();
}

// p5.js 1.11 — self-contained, deterministic still painting

let boundary = [];
const W = 1600, H = 2000;
const CX = 875, CY = 865;
const RX = 447, RY = 630;
const TILT = -0.155;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  angleMode(RADIANS);
  strokeCap(ROUND);

  makeBoundary();
  paintGround();
  paintSediment();
  paintThreads();
  paintEdge();
  paintAbsence();
  paintLooseEnds();
  paperGrain();
}

function draw() {}

function edgePoint(a, scale = 1) {
  const uneven =
    1 + 0.027 * sin(3 * a + 0.8)
      + 0.014 * cos(5 * a - 0.6)
      + 0.006 * sin(11 * a);
  const x = RX * cos(a) * uneven * scale;
  const y = RY * sin(a) * uneven * scale;
  return createVector(
    CX + x * cos(TILT) - y * sin(TILT),
    CY + x * sin(TILT) + y * cos(TILT)
  );
}

function makeBoundary() {
  for (let i = 0; i < 480; i++) {
    boundary.push(edgePoint(TWO_PI * i / 480));
  }
}

function traceBoundary(scale = 1) {
  const ctx = drawingContext;
  ctx.beginPath();
  for (let i = 0; i < boundary.length; i++) {
    const p = boundary[i];
    const x = CX + (p.x - CX) * scale;
    const y = CY + (p.y - CY) * scale;
    if (i === 0) ctx.moveTo(x, y);
    else ctx.lineTo(x, y);
  }
  ctx.closePath();
}

function pigment(c, alpha) {
  const k = color(c);
  k.setAlpha(alpha);
  return k;
}

function paintGround() {
  const top = color("#cbc5af");
  const bottom = color("#697972");

  for (let y = 0; y < H; y++) {
    let t = pow(y / H, 1.55);
    stroke(lerpColor(top, bottom, t));
    line(0, y, W, y);
  }

  noStroke();
  const dust = [
    "#e4dbc1", "#f0e4c7", "#89968b",
    "#a9ac95", "#667e79", "#b7ad91"
  ];

  // Broad, translucent scumbling rather than a clean digital gradient.
  for (let i = 0; i < 5200; i++) {
    const x = random(-100, W + 100);
    const y = random(-100, H + 100);
    const n = noise(x * 0.0018, y * 0.0018);
    fill(pigment(dust[floor(n * dust.length) % dust.length], random(3, 13)));
    ellipse(x, y, random(35, 190), random(12, 90));
  }

  // An oblique, weathered wash at the left.
  for (let i = 0; i < 1400; i++) {
    const y = random(500, 2100);
    const spine = 225 + 0.10 * (y - 1100);
    const x = spine + randomGaussian(0, 130);
    fill(pigment(random(["#7b543e", "#a36040", "#ba7950"]), random(2, 12)));
    ellipse(x, y, random(20, 110), random(20, 150));
  }

  // Exposed grain and dragged bristle marks.
  for (let i = 0; i < 22000; i++) {
    const x = random(W), y = random(H);
    const n = noise(x * 0.008, y * 0.006);
    stroke(n > 0.5
      ? color(243, 230, 199, random(6, 22))
      : color(39, 61, 57, random(5, 17)));
    strokeWeight(random(0.4, 1.6));
    line(x, y, x + random(-2, 3), y + random(2, 13));
  }
}

function paintSediment() {
  noStroke();

  // Matter remains outside the absence: unorganized, without a center.
  for (let i = 0; i < 19000; i++) {
    const x = random(W);
    const y = random(H);
    const density = noise(x * 0.004, y * 0.004);
    if (random() > 0.15 + density * 0.45) continue;

    const warm = y > 1150 && x < 850;
    const c = warm
      ? random(["#a45f3b", "#cf9866", "#554b3a", "#e3c99b"])
      : random(["#556861", "#e7ddc2", "#8e927c", "#b8aa83"]);

    fill(pigment(c, random(15, 66)));
    const r = random(0.7, 3.0);
    ellipse(x, y, r * random(0.7, 2), r);
  }

  // A few broad, nearly erased mineral deposits.
  for (let i = 0; i < 150; i++) {
    const x = random(980, 1580);
    const y = random(90, 1810);
    fill(224, 219, 194, random(3, 10));
    ellipse(x, y, random(60, 210), random(8, 32));
  }
}

function threadPoint(t, p0, p1, p2, p3) {
  return createVector(
    bezierPoint(p0.x, p1.x, p2.x, p3.x, t),
    bezierPoint(p0.y, p1.y, p2.y, p3.y, t)
  );
}

function paintThreads() {
  const colors = [
    "#a04f35", "#c27b4d", "#d6ab73", "#e1c89b",
    "#764533", "#4e6158", "#d6b391", "#e6d9ba"
  ];

  // Separate, imperfect strands gather toward the lower boundary.
  for (let i = 0; i < 610; i++) {
    const a = random(0.70, 2.91);
    const end = edgePoint(a, 0.978);
    const start = createVector(
      randomGaussian(590, 360),
      random(1990, 2210)
    );

    const bend = map(a, 0.70, 2.91, 120, -230);
    const p1 = createVector(
      start.x + random(-140, 140),
      start.y - random(180, 430)
    );
    const p2 = createVector(
      end.x + bend + random(-60, 60),
      end.y + random(155, 355)
    );

    const c = random(colors);
    const weight = random() < 0.13 ? random(4, 10) : random(0.65, 3);
    const phase = random(TWO_PI);

    // Underpaint beneath each finer, broken strand.
    noFill();
    stroke(pigment(c, random(14, 30)));
    strokeWeight(weight * 3.4);
    bezier(
      start.x, start.y, p1.x, p1.y,
      p2.x, p2.y, end.x, end.y
    );

    let previous = start;
    for (let j = 1; j <= 110; j++) {
      const t = j / 110;
      const p = threadPoint(t, start, p1, p2, end);
      const taper = sin(PI * t);
      p.x += taper * (
        sin(t * 29 + phase) * 2.8 +
        (noise(i * 0.19, t * 9) - 0.5) * 11
      );

      if (random() > 0.095) {
        stroke(pigment(c, random(65, 170)));
        strokeWeight(weight * random(0.45, 1.05));
        line(previous.x, previous.y, p.x, p.y);
      }
      previous = p;
    }
  }

  // Short cross-grain traces imply a fabric, but never a literal object.
  for (let i = 0; i < 1750; i++) {
    const y = random(1510, H);
    const spread = map(y, 1510, H, 220, 570);
    const x = randomGaussian(660, spread * 0.52);
    stroke(pigment(random(colors), random(18, 70)));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(5, 30), y + random(-7, 9));
  }
}

function paintEdge() {
  noFill();

  // The rim is an accumulation of pigment, not a luminous portal.
  for (let i = 0; i < 4200; i++) {
    const a = random(TWO_PI);
    const p = edgePoint(a, 1 + abs(randomGaussian(0, 0.016)));
    const q = edgePoint(a + random(0.002, 0.017), 1.004);
    const lowerLeft = a > 1.1 && a < 3.15;

    stroke(pigment(
      lowerLeft
        ? random(["#ac764c", "#bba47b", "#514c3c"])
        : random(["#676e60", "#8d907a", "#b7b49a"]),
      random(10, 50)
    ));
    strokeWeight(random(0.5, 3));
    line(p.x, p.y, q.x, q.y);
  }
}

function paintAbsence() {
  const ctx = drawingContext;

  ctx.save();
  traceBoundary();
  ctx.fillStyle = "#171f1e";
  ctx.fill();
  ctx.clip();

  noStroke();

  // Almost-black layers retain the material surface of paint.
  // There are no stars, objects, or destination within the shape.
  for (let i = 0; i < 6500; i++) {
    const x = random(340, 1410);
    const y = random(170, 1560);
    const n = noise(x * 0.003, y * 0.003);
    fill(
      12 + n * 10,
      20 + n * 10,
      20 + n * 9,
      random(5, 18)
    );
    ellipse(x, y, random(18, 100), random(8, 40));
  }

  for (let i = 0; i < 19000; i++) {
    const x = random(330, 1410);
    const y = random(160, 1570);
    stroke(random() < 0.5
      ? color(72, 78, 67, random(3, 10))
      : color(4, 11, 12, random(4, 15)));
    strokeWeight(random(0.4, 1.4));
    line(x, y, x + random(1, 6), y - random(1, 4));
  }

  ctx.restore();
}

function paintLooseEnds() {
  // A sparse fringe rests outside the cut; it does not cross it.
  for (let i = 0; i < 180; i++) {
    const a = random(0.95, 2.85);
    const p = edgePoint(a, random(1.003, 1.016));
    const q = edgePoint(a + random(-0.012, 0.012), random(1.02, 1.07));

    stroke(pigment(
      random(["#e0c59a", "#b77f50", "#7f5942", "#c8b28b"]),
      random(35, 120)
    ));
    strokeWeight(random(0.45, 1.5));
    noFill();
    beginShape();
    vertex(p.x, p.y);
    quadraticVertex(
      p.x + random(-15, 15),
      p.y + random(6, 22),
      q.x, q.y
    );
    endShape();
  }

  noStroke();
  for (let i = 0; i < 900; i++) {
    const a = random(0.8, 3.0);
    const p = edgePoint(a, random(1.02, 1.18));
    fill(pigment(
      random(["#dbc69e", "#ae7048", "#455a53"]),
      random(20, 95)
    ));
    const s = random(0.8, 2.8);
    ellipse(p.x, p.y, s, s * random(0.6, 1.4));
  }
}

function paperGrain() {
  loadPixels();

  // Fine, colored grain and a restrained woven tooth across all layers.
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const index = 4 * (y * W + x);
      const grain = random(-4.1, 4.1);
      const tooth =
        (x % 5 === 0 ? -0.8 : 0.2) +
        (y % 7 === 0 ? -0.65 : 0.1);
      const v = grain + tooth;

      pixels[index] = constrain(pixels[index] + v, 0, 255);
      pixels[index + 1] = constrain(pixels[index + 1] + v * 0.94, 0, 255);
      pixels[index + 2] = constrain(pixels[index + 2] + v * 0.82, 0, 255);
    }
  }

  updatePixels();
}

// p5.js 1.11 — no assets required.
const W = 1600, H = 2000;
const CX = 790, CY = 855;
const RX = 435, RY = 650;
const TURN = -0.145;
let CT, ST;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();

  CT = cos(TURN);
  ST = sin(TURN);

  paintGround();
  groundScumbling();
  sediment();
  interior();
  wornContour();
  dispersal();
  surfaceGrain();
}

function clamp(v) {
  return Math.max(0, Math.min(1, v));
}

function blend(a, b, t) {
  t = clamp(t);
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

// Signed distance approximation. The lower-right edge loses cohesion.
function boundary(x, y) {
  const dx = x - CX, dy = y - CY;
  const u = dx * CT + dy * ST;
  const v = -dx * ST + dy * CT;
  const a = atan2(v / RY, u / RX);
  const r = sqrt(sq(u / RX) + sq(v / RY));
  const wear = clamp((y - 1060) / 490) *
               clamp((x - 610) / 510);
  const contour =
    6 * sin(3 * a + 0.8) +
    3 * sin(7 * a - 0.4) +
    9 * (noise(x * 0.009, y * 0.009) - 0.5);
  const breakup = wear *
    (26 + 155 * (noise(x * 0.018, y * 0.006) - 0.36));
  return (r - 1) * RX + contour + breakup;
}

function pointOnForm(a, scale = 1) {
  const u = RX * cos(a) * scale;
  const v = RY * sin(a) * scale;
  return {
    x: CX + u * CT - v * ST,
    y: CY + u * ST + v * CT
  };
}

function paintGround() {
  // A low-resolution underpainting, subsequently worked at canvas resolution.
  const img = createImage(800, 1000);
  img.loadPixels();

  for (let j = 0; j < img.height; j++) {
    for (let i = 0; i < img.width; i++) {
      const x = i * 2, y = j * 2;
      const cloud = noise(x * 0.0018, y * 0.0018);
      const small = noise(x * 0.025, y * 0.025);
      const d = boundary(x, y);

      let c = blend([167, 165, 148], [218, 204, 172], cloud);
      const blue = clamp((780 - y) / 850) *
        (0.22 + 0.42 * noise(x * 0.003, 8));
      c = blend(c, [103, 128, 136], blue);

      const earth = clamp((y - 1190) / 750);
      c = blend(c, [153, 111, 78], earth * 0.48);
      const stain = noise(x * 0.0025 + 30, y * 0.004);
      c = blend(c, [135, 118, 93],
        clamp((stain - 0.48) * 1.9) * 0.4);

      // A rubbed, chalky margin, not a luminous halo.
      const left = clamp((1100 - x) / 850);
      const margin = exp(-sq((d - 22) / 43)) *
        (0.16 + 0.53 * left) *
        (1 - clamp((y - 1180) / 450));
      c = blend(c, [234, 220, 187], margin);

      if (d < 7) {
        let ink = blend(
          [12, 23, 29],
          [31, 41, 43],
          noise(x * 0.004, y * 0.004)
        );
        ink = blend(ink, [40, 43, 38],
          clamp((y - 930) / 630) * 0.36);
        const innerWear = exp(-sq((d + 18) / 27));
        ink = blend(ink, [69, 69, 56], innerWear * 0.3);
        c = blend(c, ink, clamp((7 - d) / 15));
      }

      const vignette = clamp(
        sq((x - 800) / 1150) + sq((y - 1000) / 1550)
      );
      const grain = (small - 0.5) * 10 + random(-2.8, 2.8);
      const k = 4 * (j * img.width + i);
      for (let q = 0; q < 3; q++) {
        img.pixels[k + q] = constrain(
          c[q] + grain - vignette * 12, 0, 255
        );
      }
      img.pixels[k + 3] = 255;
    }
  }
  img.updatePixels();
  image(img, 0, 0, W, H);
}

function groundScumbling() {
  noFill();
  strokeCap(SQUARE);
  const pigments = [
    [238, 225, 193],
    [117, 130, 127],
    [139, 111, 79],
    [191, 175, 143],
    [98, 110, 107]
  ];

  for (let i = 0; i < 24000; i++) {
    const x = random(25, W - 25);
    const y = random(25, H - 25);
    if (boundary(x, y) < 25) continue;

    const p = random(pigments);
    const len = random(2, 23);
    stroke(...p, random(8, 30));
    strokeWeight(random(0.5, 2.7));
    const tilt = (noise(x * 0.004, y * 0.004) - 0.5) * 4;
    line(x, y, x + len, y + tilt);
  }

  // Sparse vertical remnants of the first wash.
  for (let i = 0; i < 180; i++) {
    const x = random(70, 1530);
    const y = random(80, 1790);
    const len = random(15, 130);
    if (boundary(x, y) < 45 ||
        boundary(x, y + len) < 45) continue;
    stroke(109, 100, 82, random(6, 15));
    strokeWeight(random(0.4, 1.1));
    line(x, y, x + random(-3, 3), y + len);
  }
}

function sediment() {
  noFill();
  strokeCap(ROUND);

  // The surrounding material does not stop at the form.
  for (let k = 0; k < 490; k++) {
    const base = random(1370, 1990);
    const start = random(-100, 500);
    const end = random(1120, 1710);
    const shade = random();
    if (shade < 0.38) stroke(84, 83, 68, random(10, 39));
    else if (shade < 0.76) stroke(230, 211, 172, random(15, 54));
    else stroke(146, 103, 65, random(12, 43));

    strokeWeight(random(0.45, 2.1));
    let open = false;
    for (let x = start; x <= end; x += 7) {
      const y = base +
        26 * sin(x * 0.003 + base * 0.009) +
        34 * (noise(x * 0.0035, base * 0.005) - 0.5);
      if (boundary(x, y) > 8) {
        if (!open) {
          beginShape();
          open = true;
        }
        vertex(x, y);
      } else if (open) {
        endShape();
        open = false;
      }
    }
    if (open) endShape();
  }
}

function interior() {
  strokeCap(ROUND);

  // Almost invisible brushwork gives the darkness weight, not stars.
  for (let i = 0; i < 21000; i++) {
    const x = random(260, 1330);
    const y = random(150, 1560);
    const d = boundary(x, y);
    if (d > -14) continue;

    const len = random(1, 11);
    const p = noise(x * 0.005, y * 0.004);
    if (p > 0.52) stroke(66, 72, 65, random(3, 13));
    else stroke(3, 13, 21, random(7, 25));
    strokeWeight(random(0.6, 2));
    line(x, y, x + len * 0.25, y + len);
  }

  for (let i = 0; i < 100; i++) {
    const x = random(420, 1020);
    const y = random(340, 1250);
    const len = random(30, 140);
    if (boundary(x, y) > -60 ||
        boundary(x + 6, y + len) > -60) continue;
    stroke(71, 73, 62, random(3, 8));
    strokeWeight(random(2, 7));
    line(x, y, x + 6, y + len);
  }
}

function wornContour() {
  noFill();
  strokeCap(ROUND);

  // Incomplete, hand-worn layers on the upper and left shoulder.
  for (let k = 0; k < 58; k++) {
    const scale = random(1.006, 1.085);
    const a0 = random(2.55, 4.8);
    const a1 = min(a0 + random(0.06, 0.68), 5.3);
    const pale = k % 4 !== 0;
    if (pale) stroke(229, 214, 177, random(15, 53));
    else stroke(111, 99, 73, random(15, 36));
    strokeWeight(random(0.5, 2.2));

    beginShape();
    for (let a = a0; a <= a1; a += 0.008) {
      const p = pointOnForm(a,
        scale + 0.004 * sin(a * 33 + k));
      vertex(p.x, p.y);
    }
    endShape();
  }

  // A little accumulated ochre, never an unbroken gold outline.
  for (let i = 0; i < 1800; i++) {
    const a = random(2.85, 4.77);
    const p = pointOnForm(a, random(0.993, 1.025));
    if (abs(boundary(p.x, p.y)) > 11) continue;
    stroke(188, 151, 92, random(10, 51));
    strokeWeight(random(0.5, 1.7));
    line(p.x, p.y, p.x + random(-2, 2), p.y + random(1, 4));
  }
}

function dispersal() {
  noStroke();

  // Fragments are denser near the failed edge, then indistinguishable
  // from the ordinary mineral texture of the ground.
  for (let i = 0; i < 12500; i++) {
    const t = pow(random(), 1.5);
    const y = 1160 + t * 675;
    const x = 1000 + 125 * t + randomGaussian() * (65 + 160 * t);
    if (x < 80 || x > 1510) continue;
    const d = boundary(x, y);
    if (d < -12 || d > 35 + t * 500) continue;
    if (random() > 0.82 - t * 0.58) continue;

    const size = random(0.6, 3.6) * (1.3 - 0.65 * t);
    if (random() < 0.72) {
      fill(27, 38, 38, random(15, 76) * (1 - t * 0.5));
    } else {
      fill(110, 87, 58, random(20, 64));
    }
    ellipse(x, y, size * random(1, 2.7), size);
  }

  // Small ground-colored losses cut into the lower edge.
  for (let i = 0; i < 2300; i++) {
    const x = random(730, 1290);
    const y = random(1110, 1560);
    const d = boundary(x, y);
    if (d < -35 || d > 12) continue;
    const probability = clamp((y - 1110) / 420);
    if (random() > probability) continue;
    fill(183, 164, 128, random(15, 69));
    const s = random(0.6, 3.2);
    ellipse(x, y, s * random(1, 4), s);
  }
}

function surfaceGrain() {
  strokeWeight(0.7);
  for (let i = 0; i < 115000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) stroke(255, 241, 211, random(3, 12));
    else stroke(25, 29, 27, random(3, 13));
    point(x, y);
  }

  // Barely visible tooth of a woven support.
  stroke(232, 218, 186, 3);
  strokeWeight(0.55);
  for (let x = 1; x < W; x += 4) line(x, 0, x, H);
  stroke(31, 35, 31, 3);
  for (let y = 1; y < H; y += 5) line(0, y, W, y);
}

// p5.js 1.11 — self-contained, still image
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

const ink = [19, 29, 35];
const blue = [49, 72, 79];
const gold = [186, 139, 78];
const bone = [218, 202, 161];
const clay = [130, 83, 60];

function mix(a, b, t) {
  t = constrain(t, 0, 1);
  return a.map((v, i) => lerp(v, b[i], t));
}

function pigment(c, a) {
  return color(c[0], c[1], c[2], a);
}

function shell(t, r) {
  const swell = 1 + 0.028 * sin(3 * t + 0.8)
                  + 0.017 * sin(7 * t - 1.1);
  return {
    x: 790 + 365 * r * cos(t) * swell
       + 36 * sin(t) - 22 * cos(2 * t),
    y: 855 + 570 * r * sin(t) * swell
       + 15 * cos(3 * t)
  };
}

function bottomDistance(t) {
  return abs(atan2(sin(t - HALF_PI), cos(t - HALF_PI)));
}

function shellColor(t, r) {
  const light = pow(constrain((-cos(t) + 1) / 2, 0, 1), 0.7);
  let c = mix(blue, gold, light);
  const edge = exp(-sq((r - 0.91) / 0.043));
  c = mix(c, bone, edge * (0.25 + light * 0.65));
  return mix(c, clay, 0.14 * (sin(t * 4) + 1));
}

function draw() {
  background(ink);

  // A deep, unevenly brushed ground.
  noFill();
  for (let y = -10; y < height + 10; y += 3) {
    const low = constrain((y - 1150) / 1000, 0, 1);
    const c = mix(ink, [57, 61, 57], low);
    stroke(c[0], c[1], c[2], 255);
    strokeWeight(4);
    line(0, y, width, y);
  }

  // Thin, broad scumbles: accumulated paint rather than illumination.
  noStroke();
  for (let i = 0; i < 13000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0019, y * 0.0022);
    let c = mix([27, 43, 50], [98, 89, 64], n);
    if (x > 1000) c = mix(c, ink, 0.45);
    fill(pigment(c, random(2, 10)));
    ellipse(x, y, random(15, 105), random(3, 30));
  }

  // A submerged mineral shelf, with no literal landscape horizon.
  for (let k = 0; k < 180; k++) {
    const y = 1420 + k * 3.6;
    const amount = sin(constrain(k / 180, 0, 1) * PI);
    let c = mix([59, 65, 61], [152, 139, 106], amount * 0.56);
    stroke(pigment(c, 22));
    strokeWeight(random(3, 12));
    noFill();
    beginShape();
    for (let x = -40; x <= 1640; x += 24) {
      const wave = 24 * noise(x * 0.0028, k * 0.026);
      vertex(x, y + wave + 10 * sin(x * 0.004 + k * 0.03));
    }
    endShape();
  }

  // The enclosure casts no factual shadow; its dark surrounds are paint.
  noStroke();
  for (let k = 90; k > 0; k--) {
    fill(10, 19, 25, 2.3);
    beginShape();
    for (let t = 0; t < TWO_PI; t += 0.035) {
      const p = shell(t, 1.03 + k * 0.0025);
      vertex(p.x + 20, p.y + 13);
    }
    endShape(CLOSE);
  }

  // Empty center, slightly irregular and entirely without a depicted object.
  for (let k = 0; k < 55; k++) {
    const r = 0.905 - k * 0.002;
    fill(13 + k * 0.045, 23 + k * 0.035, 29 + k * 0.025, 20);
    beginShape();
    for (let t = 0; t < TWO_PI; t += 0.025) {
      const p = shell(t, r);
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }

  // Buried, broad underpainting of the remaining wall.
  noFill();
  for (let j = 0; j < 200; j++) {
    const r = random(0.87, 1.15);
    const start = random(TWO_PI);
    const length = random(0.12, 0.65);
    if (bottomDistance(start + length / 2) < 0.48) continue;
    stroke(pigment(shellColor(start, r), random(7, 19)));
    strokeWeight(random(4, 13));
    beginShape();
    for (let t = start; t <= start + length; t += 0.018) {
      const p = shell(t, r);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Thousands of short fibers make a worn, layered, almost bodily surface.
  for (let i = 0; i < 25500; i++) {
    const t = random(TWO_PI);
    const r = constrain(randomGaussian(1.005, 0.071), 0.846, 1.19);
    const d = bottomDistance(t);
    const survival = map(d, 0, 0.73, 0.025, 1, true);
    if (random() > survival) continue;
    if (r > 1.12 && random() < 0.55) continue;

    const arc = random(0.004, 0.044);
    const c = shellColor(t, r);
    const a = random(12, 62) * survival;
    stroke(pigment(c, a));
    strokeWeight(random(0.45, 2.8));
    beginShape();
    for (let s = 0; s <= 4; s++) {
      const tt = t + arc * s / 4;
      const rr = r + 0.0018 * sin(s * 1.7 + i);
      const p = shell(tt, rr);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Fine cracks and lacunae: darkness already inhabits the material.
  for (let i = 0; i < 1400; i++) {
    const t = random(TWO_PI);
    if (bottomDistance(t) < 0.5) continue;
    const r = random(0.89, 1.14);
    const p = shell(t, r);
    const q = shell(t + random(0.006, 0.034), r + random(-0.006, 0.006));
    stroke(14, 24, 29, random(20, 85));
    strokeWeight(random(0.5, 2.5));
    line(p.x, p.y, q.x, q.y);
  }

  // Loose fibers turn downward, then sideways, becoming ordinary sediment.
  for (let i = 0; i < 9500; i++) {
    const t = random(0.46, 2.72);
    const p = shell(t, random(0.90, 1.13));
    const u = pow(random(), 0.8);
    const destinationX = 800 + (p.x - 800) * 1.85 + randomGaussian(0, 190);
    const destinationY = random(1540, 1870);
    const x = lerp(p.x, destinationX, u);
    const y = lerp(p.y, destinationY, u);

    // Preserve the open, unfilled bottom of the cavity.
    if (y < 1320 && abs(x - 790) < 180) continue;

    const c = mix(shellColor(t, 1), [132, 130, 107], u);
    const a = (1 - u * 0.70) * random(7, 40);
    stroke(pigment(c, a));
    strokeWeight(random(0.5, 2.3));

    const angle = lerp(HALF_PI, x < 800 ? PI : 0, u);
    const len = random(2, 16) * (0.5 + u);
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }

  // The final stratum crosses the whole canvas: no longer a separate body.
  for (let i = 0; i < 12500; i++) {
    const x = random(-20, width + 20);
    const y = randomGaussian(1702, 112);
    if (y < 1450 || y > 1940) continue;
    const n = noise(x * 0.005, y * 0.009);
    const c = mix([43, 56, 57], [171, 153, 112], n);
    stroke(pigment(c, random(7, 29)));
    strokeWeight(random(0.4, 2));
    const length = random(3, 43);
    line(x, y, x + length, y + random(-1.5, 1.5));
  }

  // Sparse exposed flecks, chiefly on the light-bearing side.
  noStroke();
  for (let i = 0; i < 850; i++) {
    const t = random(2.0, 4.65);
    const r = random(0.87, 1.14);
    if (bottomDistance(t) < 0.65) continue;
    const p = shell(t, r);
    fill(pigment(mix(gold, bone, random()), random(22, 80)));
    ellipse(p.x, p.y, random(0.7, 2.7), random(1, 4.6));
  }

  // Matte grain and a restrained darkening at the canvas edges.
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = 4 * (y * width + x);
      const grain = random(-3.5, 3.5);
      const edge = pow(
        constrain(dist(x, y, 800, 1000) / 1280, 0, 1), 3
      ) * 0.16;
      pixels[i]     = constrain(pixels[i]     * (1 - edge) + grain, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * (1 - edge) + grain, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * (1 - edge) + grain, 0, 255);
    }
  }
  updatePixels();
}

// p5.js 1.11 — self-contained still painting
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  const ctx = drawingContext;

  // A continuous field: the interior and exterior share this ground.
  let ground = ctx.createLinearGradient(0, 0, 300, height);
  ground.addColorStop(0, "#111f28");
  ground.addColorStop(0.48, "#233638");
  ground.addColorStop(0.78, "#303d39");
  ground.addColorStop(1, "#49483d");
  ctx.fillStyle = ground;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let y = random(height);
    fill(
      random(38, 68),
      random(53, 77),
      random(53, 75),
      random(1, 5)
    );
    ellipse(x, y, random(100, 650), random(80, 440));
  }

  // Quiet, uneven pigment deposits rather than a smooth digital field.
  for (let i = 0; i < 78000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.006, y * 0.006);
    if (random() < n) {
      fill(111, 119, 106, random(2, 10));
    } else {
      fill(5, 17, 23, random(3, 13));
    }
    rect(x, y, random(0.5, 3.5), random(1, 5));
  }

  // Almost erased horizontal traces continue through the empty center.
  noFill();
  for (let i = 0; i < 145; i++) {
    let y = random(220, 1810);
    stroke(128, 137, 121, random(1, 5));
    strokeWeight(random(0.4, 1.3));
    let x = random(-100, 500);
    bezier(
      x, y,
      x + 370, y - random(3, 18),
      x + 710, y + random(2, 15),
      x + random(900, 1500), y + random(-6, 6)
    );
  }

  // A soft, asymmetric stain beneath the material.
  noStroke();
  for (let i = 36; i > 0; i--) {
    fill(7, 16, 20, 1.5);
    ellipse(805, 1010, 720 + i * 12, 1020 + i * 15);
  }

  sediment();
  looseFibers();

  // The membrane is made from short, overlapping strokes of pigment.
  // f moves from its outer edge to its inner edge.
  const radialSteps = 158;
  const angularSteps = 610;

  noStroke();
  for (let j = 0; j < radialSteps; j++) {
    let f = j / radialSteps;
    let nextF = (j + 1.65) / radialSteps;

    for (let k = 0; k < angularSteps; k++) {
      let t = -HALF_PI + TWO_PI * k / angularSteps;
      let dt = TWO_PI / angularSteps * 1.35;
      let distanceFromTear = abs(t - HALF_PI);
      let tear = 0.115 + 0.29 * f;

      if (distanceFromTear < tear) continue;

      let raggedness = noise(f * 29, t * 8 + 50);
      if (distanceFromTear < tear + 0.18 &&
          raggedness < map(distanceFromTear, tear, tear + 0.18, 0.8, 0)) {
        continue;
      }

      let a = membrane(t, f);
      let b = membrane(t + dt, f);
      let c = membrane(t + dt, nextF);
      let d = membrane(t, nextF);
      let col = pigment(t, f);

      fill(col[0], col[1], col[2], random(172, 239));
      quad(a.x, a.y, b.x, b.y, c.x, c.y, d.x, d.y);
    }
  }

  // Long dry-brush ridges give the surface a folded, mineral character.
  noFill();
  for (let i = 0; i < 1050; i++) {
    let f = random(0.015, 0.99);
    let t = random(-HALF_PI, PI * 1.5);
    let length = random(0.015, 0.19);
    let col = pigment(t, f);
    let bright = random() < 0.59;
    let shift = bright ? random(10, 42) : -random(15, 48);

    stroke(col[0] + shift, col[1] + shift, col[2] + shift,
           random(25, 105));
    strokeWeight(random(0.35, 2.1));

    beginShape();
    let drawing = false;
    for (let q = 0; q <= 12; q++) {
      let angle = t + length * q / 12;
      if (abs(angle - HALF_PI) < 0.14 + 0.31 * f) {
        if (drawing) {
          endShape();
          beginShape();
          drawing = false;
        }
        continue;
      }
      let p = membrane(angle, f);
      vertex(p.x, p.y);
      drawing = true;
    }
    endShape();
  }

  // Small chips along the failing lower edges.
  noStroke();
  for (let i = 0; i < 2300; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let f = random();
    let t = HALF_PI + side * random(0.19, 0.63);
    let p = membrane(t, f);
    let fall = pow(random(), 2.2) * 340;
    let col = pigment(t, f);
    let x = p.x + randomGaussian() * (10 + fall * 0.14);
    let y = p.y + fall;
    fill(col[0], col[1], col[2], random(12, 100) * (1 - fall / 430));
    ellipse(x, y, random(0.5, 3.4), random(1, 5));
  }

  // A handful of restrained, broken highlights on the illuminated rim.
  for (let i = 0; i < 125; i++) {
    let t = random(2.8, 4.4);
    let f = random(0.12, 0.38);
    let p = membrane(t, f);
    let q = membrane(t + random(0.002, 0.013), f);
    stroke(238, 225, 190, random(35, 130));
    strokeWeight(random(0.5, 1.8));
    line(p.x, p.y, q.x, q.y);
  }

  // Final canvas tooth. This affects every region, including the absence.
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let index = 4 * (x + y * width);
      let grain = random(-3.2, 3.2);
      let weave = (x % 3 === 0 ? 0.8 : -0.35)
                + (y % 4 === 0 ? 0.6 : -0.2);
      pixels[index] += grain + weave;
      pixels[index + 1] += grain + weave;
      pixels[index + 2] += grain + weave;
    }
  }
  updatePixels();
}

function membrane(t, f) {
  // Slightly tilted, asymmetrical contours; never a perfect ellipse.
  let ripple = 7 * sin(5 * t + 0.4)
             + 3 * sin(11 * t - 0.8);
  let ox = 795 + (453 + ripple) * cos(t)
               + 43 * sin(t) + 17 * sin(2 * t);
  let oy = 865 + (635 + ripple * 0.7) * sin(t)
               + 14 * cos(3 * t);

  let ix = 839 + 271 * cos(t)
               + 34 * sin(t) + 10 * sin(2 * t + 0.3);
  let iy = 845 + 491 * sin(t) + 9 * cos(3 * t);

  let wrinkle = sin(f * PI) *
    (4 * sin(17 * t + f * 11) + 2 * sin(39 * t - f * 8));

  return {
    x: lerp(ox, ix, f) + wrinkle * cos(t),
    y: lerp(oy, iy, f) + wrinkle * sin(t)
  };
}

function pigment(t, f) {
  let light = pow((1 + cos(t - 3.65)) * 0.5, 1.55);
  let crest = pow(max(0, sin(PI * f)), 0.65);
  let folds = 13 * sin(f * 25 + 2.3 * sin(t * 3))
            + 5 * sin(f * 63 - t * 7);
  let mottling = 18 * (noise(f * 17, t * 5 + 60) - 0.5);
  let value = 39 + 131 * light + 31 * crest + folds + mottling;
  let innerShadow = 33 * pow(f, 8);
  let warm = pow(max(0, cos(t - 0.4)), 4);

  return [
    value + 15 + 27 * warm - innerShadow,
    value + 13 - 3 * warm - innerShadow,
    value - 1 - 17 * warm - innerShadow
  ];
}

function looseFibers() {
  noFill();
  for (let i = 0; i < 420; i++) {
    let f = random();
    let side = random() < 0.55 ? -1 : 1;
    let t = HALF_PI + side * (0.12 + 0.29 * f + random(0, 0.09));
    let p = membrane(t, f);
    let length = random(45, 410) * (1 - 0.25 * f);
    let drift = side * random(12, 100) + random(-55, 55);
    let col = pigment(t, f);

    stroke(col[0], col[1], col[2], random(12, 65));
    strokeWeight(random(0.35, 1.6));
    bezier(
      p.x, p.y - 15,
      p.x - side * 15, p.y + length * 0.32,
      p.x + drift * 0.2, p.y + length * 0.78,
      p.x + drift, p.y + length
    );
  }
}

function sediment() {
  noStroke();
  for (let i = 0; i < 19000; i++) {
    let y = random(1420, 1950);
    let depth = (y - 1420) / 530;
    let x = randomGaussian(805, 210 + depth * 220);
    let n = noise(x * 0.009, y * 0.018);
    if (random() > depth * 0.65 + 0.08 || n < 0.33) continue;

    fill(
      random(102, 146),
      random(101, 132),
      random(81, 106),
      random(4, 26)
    );
    ellipse(x, y, random(1, 6), random(0.4, 1.8));
  }

  for (let i = 0; i < 380; i++) {
    let y = random(1660, 1940);
    let x = random(120, 1450);
    stroke(151, 139, 110, random(3, 14));
    strokeWeight(random(0.4, 1));
    line(x, y, x + random(4, 85), y + random(-1.5, 1.5));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  // Background gradient
  let top = color(6, 8, 22);
  let bot = color(28, 22, 40);
  for (let y = 0; y < height; y++) {
    stroke(lerpColor(top, bot, pow(y / height, 1.4)));
    line(0, y, width, y);
  }

  // Faint field of threads: the world the knot is made of
  strokeWeight(1);
  for (let i = 0; i < 4200; i++) {
    let x = random(-100, width + 100);
    let y = random(-100, height + 200);
    let a = random(8, 22);
    stroke(120, 140, 190, a);
    for (let s = 0; s < 90; s++) {
      let d = flowDir(x, y);
      let nx = x + d.x * 4;
      let ny = y + d.y * 4;
      line(x, y, nx, ny);
      x = nx; y = ny;
    }
  }

  let cx = 800, cy = 1380;

  // Soft glow around the knot
  noStroke();
  for (let r = 520; r > 0; r -= 6) {
    let t = 1 - r / 520;
    fill(200, 150, 90, 2.2 * t * t);
    ellipse(cx, cy, r * 2.1, r * 1.9);
  }

  // The knot and its unravelling
  blendMode(ADD);
  let gold = color(245, 190, 105);
  let pale = color(255, 230, 180);
  let blue = color(110, 135, 190);

  for (let i = 0; i < 750; i++) {
    let theta = random(TWO_PI);
    let baseR = 90 + pow(random(), 0.7) * 220;
    let loops = random(0.4, 4.5) * TWO_PI;
    let stays = random() < 0.28;
    if (stays) loops = random(2, 6) * TWO_PI;
    let dirSign = random() < 0.85 ? 1 : -1;
    let seed = random(1000);
    let w = random(0.6, 1.6);
    strokeWeight(w);

    let traveled = 0;
    let px, py;
    let r = baseR;
    let tight = lerpColor(gold, pale, random(0.6));
    // Circling phase
    while (traveled < loops) {
      r = baseR + (noise(seed, theta * 0.6) - 0.5) * 120;
      let x = cx + cos(theta) * r * 1.08;
      let y = cy + sin(theta) * r * 0.95;
      if (px !== undefined) {
        stroke(red(tight), green(tight), blue_(tight), 26);
        line(px, py, x, y);
      }
      px = x; py = y;
      theta += 0.025 * dirSign;
      traveled += 0.025;
    }
    if (stays) continue;

    // Release phase: drift into the field
    let vx = -sin(theta) * dirSign * 3;
    let vy = cos(theta) * dirSign * 3;
    let steps = floor(random(250, 650));
    let x = px, y = py;
    for (let k = 0; k < steps; k++) {
      let d = flowDir(x, y);
      vx = lerp(vx, d.x * 3, 0.025);
      vy = lerp(vy, d.y * 3, 0.025);
      let nx = x + vx, ny = y + vy;
      let f = k / steps;
      let c = lerpColor(tight, blue, min(1, f * 1.6));
      let a = lerp(26, 4, pow(f, 0.7));
      strokeWeight(lerp(w, 0.8, f));
      stroke(red(c), green(c), blue_(c), a);
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (x < -50 || x > width + 50 || y < -50 || y > height + 50) break;
    }
  }
  blendMode(BLEND);

  // Gentle vignette
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(0, 0, 0, 1.2);
    strokeWeight(4);
    let m = i * 3;
    rect(-m + 900, -m + 900, width + 2 * m - 1800, height + 2 * m - 1800);
  }
  for (let i = 0; i < 160; i++) {
    stroke(0, 0, 0, i * 0.012);
    strokeWeight(6);
    rect(i * 3, i * 3, width - i * 6, height - i * 6);
  }

  // Grain
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = (random() - 0.5) * 10;
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();
}

function blue_(c) {
  return blue(c);
}

function flowDir(x, y) {
  let a = noise(x * 0.0014, y * 0.0014) * TWO_PI * 2.2;
  let dx = cos(a);
  let dy = sin(a) - 0.85;
  let m = sqrt(dx * dx + dy * dy) || 1;
  return { x: dx / m, y: dy / m };
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Background: deep night gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    stroke(lerp(12, 22, t), lerp(13, 30, t), lerp(24, 44, t));
    line(0, y, width, y);
  }

  // The wide field: faint horizontal threads, the sea all things return to
  noFill();
  for (let k = 0; k < 170; k++) {
    let y0 = 1180 + k * 4.8 + random(-3, 3);
    stroke(110, 135, 160, map(k, 0, 170, 12, 38));
    strokeWeight(1);
    beginShape();
    for (let x = -20; x <= width + 20; x += 8) {
      let yy = y0 + 40 * (noise(x * 0.0015, k * 0.04) - 0.5) + 6 * sin(x * 0.004 + k * 0.1);
      vertex(x, yy);
    }
    endShape();
  }

  const cx = 800, cy = 680;

  // Soft glow behind the core
  noStroke();
  for (let k = 40; k > 0; k--) {
    fill(255, 170, 90, 2.2);
    ellipse(cx, cy, 40 + k * 16, 40 + k * 16);
  }

  // Rings of the self, each loosening at the bottom; outer ones loosen most
  const N = 70;
  for (let i = N - 1; i >= 0; i--) {
    let f = i / (N - 1);
    let r = 40 + i * 5.6;
    let gap = 0.1 + pow(f, 1.4) * 1.45 * PI;
    let rot = random(-0.18, 0.18);
    let aStart = HALF_PI + gap / 2 + rot;
    let aEnd = HALF_PI + TWO_PI - gap / 2 + rot;

    // warm color: pale gold at core to vermilion at edge
    let wr = lerp(255, 205, f), wg = lerp(214, 72, f), wb = lerp(140, 42, f);

    for (let s = 0; s < 2; s++) {
      let dr = random(-1.8, 1.8);
      let cr = wr + random(-12, 12), cg = wg + random(-12, 12), cb = wb + random(-10, 10);
      let sw = random(1.0, 1.8);
      strokeWeight(sw);
      stroke(cr, cg, cb, 190);

      let da = 2.5 / r;
      let px = null, py = null;
      let pts = [];
      for (let a = aStart; a <= aEnd; a += da) {
        let rr = (r + dr) * (1 + 0.045 * (noise(cos(a) + 2, sin(a) + 2, i * 0.08 + s) - 0.5));
        let x = cx + cos(a) * rr;
        let y = cy + sin(a) * rr;
        if (px !== null) line(px, py, x, y);
        pts.push([x, y]);
        px = x; py = y;
      }
      if (pts.length < 3) continue;

      // Left end: thread continues backward
      let p0 = pts[0], p1 = pts[1];
      let d0x = p0[0] - p1[0], d0y = p0[1] - p1[1];
      // Right end: thread continues forward
      let q0 = pts[pts.length - 1], q1 = pts[pts.length - 2];
      let d1x = q0[0] - q1[0], d1y = q0[1] - q1[1];

      let side0 = p0[0] < cx ? -1 : 1;
      let side1 = q0[0] < cx ? -1 : 1;
      if (abs(p0[0] - cx) < 30) side0 = random() < 0.5 ? -1 : 1;
      if (abs(q0[0] - cx) < 30) side1 = random() < 0.5 ? -1 : 1;

      tail(p0[0], p0[1], d0x, d0y, side0, cr, cg, cb, 1200 + random(0, 760), i * 3.1 + s, sw);
      tail(q0[0], q0[1], d1x, d1y, side1, cr, cg, cb, 1200 + random(0, 760), i * 3.1 + s + 50, sw);
    }
  }

  // A few motes drifting off the outer edge
  noStroke();
  for (let k = 0; k < 500; k++) {
    let a = random(TWO_PI);
    let rr = 380 + abs(randomGaussian()) * 120;
    let x = cx + cos(a) * rr + random(-20, 20);
    let y = cy + sin(a) * rr + abs(randomGaussian()) * 140;
    let t = constrain((y - 400) / 900, 0, 1);
    fill(lerp(230, 140, t), lerp(110, 160, t), lerp(60, 185, t), random(30, 90));
    let s = random(1, 3);
    ellipse(x, y, s, s);
  }

  // Grain
  for (let k = 0; k < 60000; k++) {
    let v = random(255);
    fill(v, v, v, random(4, 10));
    rect(random(width), random(height), 1, 1);
  }
}

function tail(x, y, dx, dy, side, cr, cg, cb, targetY, seed, sw) {
  let m = sqrt(dx * dx + dy * dy) || 1;
  dx /= m; dy /= m;
  const coolR = 128, coolG = 156, coolB = 182;
  const speed = 3;
  strokeWeight(sw);
  for (let step = 0; step < 2400; step++) {
    let n = noise(x * 0.003, y * 0.003, seed) - 0.5;
    let tx, ty;
    if (y < targetY - 160) {
      tx = side * 0.28 + n * 1.6;
      ty = 1;
    } else {
      tx = side;
      ty = (targetY - y) * 0.012 + n * 0.7;
    }
    let tm = sqrt(tx * tx + ty * ty) || 1;
    tx /= tm; ty /= tm;
    dx = lerp(dx, tx, 0.035);
    dy = lerp(dy, ty, 0.035);
    // gentle wander
    let ang = n * 0.09;
    let ndx = dx * cos(ang) - dy * sin(ang);
    let ndy = dx * sin(ang) + dy * cos(ang);
    dx = ndx; dy = ndy;
    let dm = sqrt(dx * dx + dy * dy) || 1;
    dx /= dm; dy /= dm;

    let nx = x + dx * speed;
    let ny = y + dy * speed;

    let t = constrain(step / 650, 0, 1);
    let te = t * t * (3 - 2 * t);
    let a = lerp(175, 55, te);
    let edge = min(nx, width - nx);
    if (edge < 200) a *= max(0, edge / 200);
    stroke(lerp(cr, coolR, te), lerp(cg, coolG, te), lerp(cb, coolB, te), a);
    line(x, y, nx, ny);

    x = nx; y = ny;
    if (x < -30 || x > width + 30 || y > height + 30) break;
  }
}

const W = 1600, H = 2000, HZ = 1250, PX = 950;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function topY(x) {
  const s = x < PX ? 430 : 165;
  const A = 640;
  const w = (noise(x * 0.01, 3) - 0.5) * 30 * exp(-sq((x - PX) / 300));
  return HZ - A * exp(-sq((x - PX) / s)) + w;
}

function skyCol(y) {
  const t = y / HZ;
  const a = color(6, 8, 22), b = color(38, 36, 72), c = color(222, 164, 116);
  if (t < 0.6) return lerpColor(a, b, t / 0.6);
  return lerpColor(b, c, pow((t - 0.6) / 0.4, 1.6));
}

function draw() {
  // --- Sky ---
  for (let y = 0; y <= HZ; y++) {
    stroke(skyCol(y));
    line(0, y, W, y);
  }

  // --- Distant stars ---
  noStroke();
  for (let i = 0; i < 1500; i++) {
    const x = random(W);
    const y = pow(random(), 1.6) * 1100;
    const a = map(y, 0, 1100, 220, 10) * random(0.3, 1);
    fill(255, 240, 215, a);
    circle(x, y, random(0.8, 2.6));
  }

  // --- Low light behind the wave ---
  blendMode(ADD);
  noStroke();
  for (let r = 1000; r > 10; r -= 10) {
    fill(255, 165, 100, 2.2);
    ellipse(PX, HZ, r * 1.6, r);
  }
  blendMode(BLEND);

  // --- Sea ---
  for (let y = HZ; y < H; y += 3) {
    const ty = (y - HZ) / (H - HZ);
    const base = lerpColor(color(70, 62, 88), color(4, 7, 16), pow(ty, 0.5));
    let x = -50;
    while (x < W) {
      const len = random(30, 130) * (0.6 + ty);
      const n = noise(x * 0.004, y * 0.03);
      const spread = 110 + (y - HZ) * 0.55;
      const refl = exp(-sq((x - PX) / spread)) * (1 - ty * 0.85);
      let c = lerpColor(base, color(245, 185, 130), constrain(refl * n * 1.3, 0, 1));
      c = lerpColor(c, color(0, 0, 0), (1 - n) * 0.35);
      stroke(red(c), green(c), blue(c), 210);
      strokeWeight(random(1.5, 3.5) * (0.7 + ty));
      line(x, y, x + len, y + random(-0.6, 0.6));
      x += len * random(0.5, 0.9);
    }
  }

  // --- Wave body ---
  const deep = color(10, 32, 50), shallow = color(95, 170, 165), lit = color(238, 210, 160);
  for (let x = 60; x < 1560; x += 2) {
    const ty = topY(x);
    if (HZ - ty < 3) continue;
    const slope = (topY(x + 1) - topY(x - 1)) / 2;
    const bottom = 1300;
    let y = ty;
    while (y < bottom) {
      const t = (y - ty) / (bottom - ty);
      let c = lerpColor(shallow, deep, pow(t, 0.55));
      const height = (HZ - ty) / 640;
      c = lerpColor(c, lit, pow(1 - t, 4) * 0.6 * height);
      const nn = noise(x * 0.02, y * 0.02);
      c = lerpColor(c, color(0, 10, 20), (1 - nn) * 0.3);
      const ang = atan(slope) * (1 - t * 0.8) + (nn - 0.5) * 0.4;
      const len = random(10, 26);
      stroke(red(c), green(c), blue(c), 190);
      strokeWeight(random(1.5, 3));
      line(x, y, x + cos(ang) * len, y + sin(ang) * len);
      y += random(5, 12);
    }
  }

  // --- Crest foam ---
  noStroke();
  for (let i = 0; i < 9000; i++) {
    const x = randomGaussian(PX - 40, 260);
    const ty = topY(x);
    const h = (HZ - ty) / 640;
    if (h < 0.05) continue;
    const y = ty + abs(randomGaussian(0, 12 + 20 * (1 - h)));
    fill(240, 242, 232, random(30, 140) * h);
    circle(x, y, random(1, 3.5));
  }

  // --- Foam where the wave meets the sea ---
  for (let i = 0; i < 1600; i++) {
    const x = random(150, 1500);
    const y = HZ + abs(randomGaussian(0, 30)) + 20;
    const a = random(20, 90) * exp(-sq((x - PX) / 500));
    stroke(225, 225, 215, a);
    strokeWeight(random(1, 2.5));
    line(x, y, x + random(10, 40), y);
  }

  // --- Spray rising into stars ---
  noStroke();
  for (let i = 0; i < 5200; i++) {
    let x = randomGaussian(PX + 20, 140);
    let y = topY(x) + random(0, 12);
    if (HZ - y < 120) continue;
    const steps = floor(pow(random(), 1.8) * 260) + 4;
    let lastX = x, lastY = y;
    for (let s = 0; s < steps; s++) {
      const n = noise(x * 0.0018, y * 0.0018, 7);
      const ang = -HALF_PI - 0.35 + (n - 0.5) * 2.6;
      x += cos(ang) * 6;
      y += sin(ang) * 6;
      if (y < 15 || x < 0 || x > W) break;
      lastX = x; lastY = y;
      if (s % 3 === 0) {
        const rise = constrain((topY(PX) - y) / 600, 0, 1);
        const c = lerpColor(color(235, 242, 238), color(255, 228, 190), rise);
        fill(red(c), green(c), blue(c), 26 * (1 - rise * 0.75));
        circle(x, y, lerp(2.6, 1.0, rise));
      }
    }
    const rise = constrain((topY(PX) - lastY) / 600, 0, 1);
    fill(255, 238, 205, lerp(110, 230, rise));
    circle(lastX, lastY, random(1.2, 2.8));
    if (random() < 0.08 * rise) {
      fill(255, 220, 170, 30);
      circle(lastX, lastY, random(6, 12));
    }
  }

  // --- Grain ---
  noStroke();
  for (let i = 0; i < 50000; i++) {
    fill(random() < 0.5 ? 0 : 255, random(4, 12));
    rect(random(W), random(H), 1.5, 1.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
