  for (let i = 0; i < 9000; i++) {
    let x = random(width), y = random(height);
    stroke(endCol[0], endCol[1], endCol[2], random(8, 55));
    strokeWeight(random(0.8, 2.4));
    point(x, y);
  }

  // Soft warm glow of the held form
  noStroke();
  for (let r = 700; r > 0; r -= 6) {
    fill(255, 140, 60, 1.1);
    ellipse(cx, cy, r * 0.8, r);
  }
  for (let r = 260; r > 0; r -= 4) {
    fill(255, 200, 140, 1.2);
    ellipse(cx, cy, r * 0.8, r);
  }

  // The strands: orbiting the center, then released into the field
  const N = 2400, steps = 260;
  for (let i = 0; i < N; i++) {
    let ang = random(TWO_PI);
    let rr = pow(random(), 0.55);
    let release = floor(pow(random(), 0.75) * 300);
    let x = cx + cos(ang) * rr * 230;
    let y = cy + sin(ang) * rr * 300;
    let px = x, py = y;
    let released = false, since = 0;
    let dir = random() < 0.5 ? 1 : -1;

    for (let s = 0; s < steps; s++) {
      if (s < release) {
        // Held: circling, gathered into a self
        ang += dir * 0.014 * (1.25 - rr);
        let wob = (noise(cos(ang) + 2, sin(ang) + 2, i * 0.003) - 0.5) * 0.22;
        let r2 = rr + wob;
        x = cx + cos(ang) * r2 * 230;
        y = cy + sin(ang) * r2 * 300;
        stroke(255, 185, 105, 13);
        strokeWeight(1.3);
        line(px, py, x, y);
      } else {
        // Released: drifting, cooling, dispersing
        released = true;
        since++;
        let t = constrain(since / 200, 0, 1);
        let a = noise(x * 0.0016, y * 0.0016, 5) * TWO_PI * 1.6;
        let vx = cos(a) * 3.2 + (x - cx) * 0.004;
        let vy = sin(a) * 3.2 + 3.6 + t * 1.5;
        x += vx;
        y += vy;
        let cr = lerp(255, endCol[0], pow(t, 0.6));
        let cg = lerp(185, endCol[1], pow(t, 0.6));
        let cb = lerp(105, endCol[2], pow(t, 0.6));
        stroke(cr, cg, cb, 13 * (1 - t * 0.75));
        strokeWeight(1.3 * (1 - t * 0.55));
        line(px, py, x, y);
        if (x < -20 || x > width + 20 || y > height + 20) break;
      }
      px = x;
      py = y;
    }

    // Where each strand comes to rest, it becomes one more mote among many
    if (released) {
      stroke(endCol[0] + 30, endCol[1] + 30, endCol[2] + 30, random(60, 140));
      strokeWeight(random(1.4, 2.6));
      point(x, y);
    }
  }

  blendMode(BLEND);

  // Gentle vignette
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(0, 0, 0, 2.2);
    strokeWeight(6);
    rect(-i * 2 + 600, -i * 2 + 600, width - 1200 + i * 4, height - 1200 + i * 4);
  }
}

const W = 1600, H = 2000, HOR = 760, BASE = 1400;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function crestY(x) {
  let w = x < 880 ? 430 : 260;
  let h = 330 * exp(-pow((x - 880) / w, 2));
  h += 45 * exp(-pow((x - 880) / 70, 2));
  h += 18 * sin(x * 0.012) * exp(-pow((x - 880) / 600, 2));
  return BASE - 20 - h;
}

function heightAt(x) { return BASE - 20 - crestY(x); }

function draw() {
  // ---- Sky ----
  let stops = [
    [0, color(6, 8, 22)],
    [380, color(20, 26, 58)],
    [620, color(70, 60, 90)],
    [720, color(170, 105, 95)],
    [HOR, color(235, 175, 115)]
  ];
  for (let y = 0; y <= HOR; y++) {
    let c;
    for (let i = 0; i < stops.length - 1; i++) {
      if (y >= stops[i][0] && y <= stops[i + 1][0]) {
        let t = (y - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        c = lerpColor(stops[i][1], stops[i + 1][1], t);
      }
    }
    stroke(c);
    line(0, y, W, y);
  }

  // sky texture
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let x = random(W), y = random(HOR);
    let n = noise(x * 0.002, y * 0.004);
    fill(120, 110, 150, 10 * n);
    ellipse(x, y, random(20, 80), random(4, 12));
  }

  // stars
  for (let i = 0; i < 1100; i++) {
    let x = random(W), y = pow(random(), 1.4) * 640;
    let a = map(y, 0, 640, 230, 20) * random(0.3, 1);
    let s = random() < 0.04 ? random(2.2, 3.4) : random(0.8, 1.8);
    fill(210, 220, 255, a);
    circle(x, y, s);
  }

  // ---- Sea ----
  fill(12, 22, 40);
  rect(0, HOR, W, H - HOR);
  for (let i = 0; i < 22000; i++) {
    let t = pow(random(), 1.5);
    let y = HOR + t * (H - HOR);
    let x = random(-50, W + 50);
    let len = map(y, HOR, H, 5, 70);
    let wgt = map(y, HOR, H, 0.8, 4);
    let n = noise(x * 0.004, y * 0.01);
    let c = lerpColor(color(10, 20, 38), color(32, 52, 78), n);
    let pathW = map(y, HOR, H, 40, 520);
    let d = abs(x - 820) / pathW;
    let glow = exp(-d * d) * map(y, HOR, H, 1, 0.25);
    if (random() < glow * 0.8) {
      c = lerpColor(c, color(240, 175, 115), random(0.4, 0.9) * glow);
    }
    let haze = map(y, HOR, HOR + 120, 1, 0, true);
    c = lerpColor(c, color(150, 105, 105), haze * 0.6);
    stroke(red(c), green(c), blue(c), 200);
    strokeWeight(wgt);
    line(x - len / 2, y, x + len / 2, y + random(-0.5, 0.5));
  }

  // horizon glow line
  for (let i = 0; i < 6; i++) {
    stroke(255, 200, 140, 40 - i * 6);
    strokeWeight(1);
    line(0, HOR + i, W, HOR + i);
  }

  // ---- Wave body ----
  noStroke();
  fill(14, 27, 46);
  beginShape();
  vertex(0, BASE + 30);
  for (let x = 0; x <= W; x += 4) vertex(x, crestY(x));
  vertex(W, BASE + 30);
  endShape(CLOSE);

  for (let i = 0; i < 16000; i++) {
    let x = random(0, W);
    let cy = crestY(x);
    let y = random(cy, BASE + 30);
    let t = (y - cy) / (BASE + 30 - cy);
    let slope = (crestY(x + 3) - crestY(x - 3)) / 6;
    let ang = atan(slope) * (1 - t);
    let h = heightAt(x);
    let lit = exp(-t * 4) * constrain(h / 330, 0, 1);
    let n = noise(x * 0.006, y * 0.012);
    let c = lerpColor(color(12, 24, 42), color(30, 55, 78), n);
    c = lerpColor(c, color(85, 140, 145), lit * 0.8);
    let backGlow = exp(-pow((x - 860) / 220, 2)) * exp(-t * 6);
    c = lerpColor(c, color(230, 180, 130), backGlow * 0.45);
    let len = random(12, 40);
    stroke(red(c), green(c), blue(c), 170);
    strokeWeight(random(1.5, 3.5));
    push();
    translate(x, y);
    rotate(ang);
    line(-len / 2, 0, len / 2, 0);
    pop();
  }

  // foreground sea over the wave's base
  for (let i = 0; i < 9000; i++) {
    let y = random(BASE - 10, H);
    let x = random(-50, W + 50);
    let len = map(y, BASE, H, 30, 80);
    let n = noise(x * 0.004, y * 0.01 + 50);
    let c = lerpColor(color(9, 18, 34), color(28, 46, 70), n);
    let a = map(y, BASE - 10, BASE + 60, 60, 210, true);
    stroke(red(c), green(c), blue(c), a);
    strokeWeight(random(2, 5));
    line(x - len / 2, y, x + len / 2, y + random(-1, 1));
  }

  // ---- Foam on crest ----
  noStroke();
  for (let i = 0; i < 5000; i++) {
    let x = randomGaussian(880, 200);
    let h = heightAt(x);
    if (h < 50) continue;
    let y = crestY(x) + abs(randomGaussian(0, 6 + (330 - h) * 0.02));
    let a = map(h, 50, 375, 20, 200);
    fill(235, 240, 238, a * random(0.3, 1));
    circle(x, y, random(1, 3.5));
  }

  // ---- Spray dissolving into stars ----
  for (let i = 0; i < 1800; i++) {
    let px = randomGaussian(880, 110);
    let py = crestY(px) - random(4);
    let steps = floor(random(30, 260));
    let s = random(3, 6);
    let seed = random(1000);
    for (let k = 0; k < steps; k++) {
      let f = k / steps;
      let ang = -HALF_PI + (noise(px * 0.003, py * 0.003, seed * 0.001) - 0.5) * 2.4 + 0.3;
      px += cos(ang) * s;
      py += sin(ang) * s;
      s *= 0.998;
      if (py < 10) break;
      let c = lerpColor(color(240, 242, 240), color(180, 195, 240), f);
      let a = 60 * pow(1 - f, 1.3) + 4;
      fill(red(c), green(c), blue(c), a);
      circle(px, py, lerp(3.2, 0.9, f));
    }
    // each droplet ends as a point of light
    if (py > 10) {
      fill(220, 228, 255, random(120, 230));
      circle(px, py, random(1, 2.6));
    }
  }

  // ---- Grain and vignette ----
  for (let i = 0; i < 40000; i++) {
    let v = random(255);
    fill(v, v, v, 8);
    rect(random(W), random(H), 1.5, 1.5);
  }
  noFill();
  for (let r = 0; r < 300; r++) {
    stroke(0, 0, 0, map(r, 0, 300, 2.2, 0));
    strokeWeight(3);
    rect(r * 1.5, r * 1.5, W - r * 3, H - r * 3);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 1. THE VAST BACKGROUND
  loadPixels();
  let topColor = color(5, 7, 12);      // Deep cosmic obsidian
  let midColor = color(15, 22, 32);    // Midnight slate
  let botColor = color(45, 38, 35);    // Warm earthen umber

  for (let y = 0; y < height; y++) {
    let nY = y / height;
    let c;
    if (nY < 0.72) {
      c = lerpColor(topColor, midColor, pow(nY / 0.72, 1.2));
    } else {
      c = lerpColor(midColor, botColor, pow((nY - 0.72) / 0.28, 1.5));
    }
    let rBase = red(c);
    let gBase = green(c);
    let bBase = blue(c);

    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;
      let grain = random(-5, 5);
      pixels[idx]     = constrain(rBase + grain, 0, 255);
      pixels[idx + 1] = constrain(gBase + grain, 0, 255);
      pixels[idx + 2] = constrain(bBase + grain, 0, 255);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  // 2. THE UPPER SILENCE (The Cosmos / The Whole)
  // Faint, timeless geometry and distant dust
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 60; i++) {
    stroke(140, 170, 210, random(1, 3.5));
    strokeWeight(random(1, 3));
    let rx = width * 0.5 + random(-300, 300);
    let ry = height * 0.25 + random(-200, 200);
    let r = random(200, 1600);
    circle(rx, ry, r);
  }

  for (let i = 0; i < 6000; i++) {
    let x = random(width);
    let y = random(height * 0.85);
    let n = noise(x * 0.002, y * 0.002);
    if (n > 0.45) {
      let alpha = map(y, 0, height * 0.85, 35, 0) * pow(n, 2);
      stroke(200, 220, 255, alpha);
      strokeWeight(random(0.5, 2.2));
      point(x, y);
    }
  }

  // 3. THE RADIANT CORE (The Tension of Living Form)
  let cx = width * 0.5;
  let cy = height * 0.72;

  for (let r = 700; r > 0; r -= 4) {
    let inter = map(r, 700, 0, 0, 1);
    let c = lerpColor(color(180, 70, 30, 0), color(255, 210, 150, 5), pow(inter, 2.2));
    fill(c);
    noStroke();
    circle(cx + random(-2, 2), cy + random(-2, 2), r * 2);
  }

  // 4. THE SHADOW OF SEPARATION (Grounding / Gravity)
  blendMode(MULTIPLY);
  for (let i = 0; i < 300; i++) {
    fill(10, 8, 12, random(5, 15));
    noStroke();
    let x = cx + randomGaussian() * 260;
    let y = cy + 60 + abs(randomGaussian() * 180);
    let w = random(80, 400);
    let h = random(30, 120);
    ellipse(x, y, w, h);
  }

  // 5. THE THRESHOLD (The Horizon of Dissolution)
  blendMode(SCREEN);
  for (let i = 0; i < 150; i++) {
    let y = cy + randomGaussian() * 35;
    let w = random(200, width * 0.9);
    let x = cx + randomGaussian() * 150;
    stroke(170, 200, 225, random(1, 5));
    strokeWeight(random(0.5, 2.5));
    line(x - w / 2, y, x + w / 2, y);
  }

  // 6. THE UNBINDING (Ascent and Dispersion of Essence)
  let numStreams = 6500;
  let palette = [
    color(255, 240, 210), // Incandescent ivory
    color(245, 175, 95),  // Living gold
    color(215, 95, 55),   // Arterial vermilion
    color(150, 55, 65),   // Deep carmine
    color(75, 115, 145),  // Twilight slate
    color(145, 195, 215), // Ether cyan
    color(40, 55, 80)     // Void indigo
  ];

  blendMode(ADD);
  for (let i = 0; i < numStreams; i++) {
    // Spawn in a dense horizontal vessel-like knot at the core
    let angle = random(TWO_PI);
    let radius = abs(randomGaussian()) * 110;
    let startX = cx + cos(angle) * radius * 2.0;
    let startY = cy + sin(angle) * radius * 0.45;

    let x = startX;
    let y = startY;

    // Base color determined by proximity to the hot center
    let distFromCenter = dist(startX, startY, cx, cy);
    let cIndex = constrain( floor(map(distFromCenter, 0, 280, 0, 3.5)), 0, 3 );
    let baseC = palette[cIndex];
    let targetC = palette[floor(random(4, 7))];

    let maxSteps = random(120, 750);
    let stepSize = random(1.5, 3.2);
    let offset = random(100); // Individual variance

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;
      let heightFactor = map(y, cy, 0, 0, 1, true);

      // Multi-scale curl/flow noise
      let n1 = noise(x * 0.0025, y * 0.0025, offset * 0.01);
      let n2 = noise(x * 0.012, y * 0.012, step * 0.005);

      // Tightly bound at the bottom, expansive and drifting at the top
      let spread = map(heightFactor, 0, 1, 0.35, 2.6);
      let flowAngle = -HALF_PI + (n1 - 0.5) * PI * spread + (n2 - 0.5) * 1.2;

      // Subtle inward pull right above the core (the bottleneck of release)
      if (heightFactor > 0.02 && heightFactor < 0.25) {
        let pull = (cx - x) * 0.004;
        flowAngle += pull;
      }

      x += cos(flowAngle) * stepSize;
      y += sin(flowAngle) * stepSize;

      // Color shifts from warm vitality to cool infinite ether
      let currentC = lerpColor(baseC, targetC, pow(progress, 0.75));

      // Alpha peaks mid-flight, vanishes softly at ends
      let alpha = sin(progress * PI) * map(heightFactor, 0, 1, 26, 5);

      stroke(red(currentC), green(currentC), blue(currentC), alpha);
      let sw = map(progress, 0, 1, 2.6, 0.4) * (1 + n2 * 0.5);
      strokeWeight(sw);
      point(x, y);

      // Occasional dispersion into drifting ashes/sparks
      if (random() < 0.004 && heightFactor > 0.15) {
        strokeWeight(random(1.5, 4.0));
        stroke(230, 245, 255, alpha * 3.5);
        point(x + random(-12, 12), y + random(-12, 12));
      }
    }
  }

  // 7. THE KNOT OF BEING (Dense entangled filaments at the core)
  // Representing the complex, heavy structure of a living life before release
  blendMode(BLEND);
  for (let i = 0; i < 800; i++) {
    let x = cx + randomGaussian() * 140;
    let y = cy + randomGaussian() * 35;
    let steps = random(20, 60);

    let isDark = random() < 0.65;
    let c = isDark ? color(18, 12, 16, random(60, 160)) : color(255, 220, 170, random(30, 90));
    stroke(c);
    strokeWeight(random(0.8, 3.0));
    noFill();

    beginShape();
    for (let s = 0; s < steps; s++) {
      curveVertex(x, y);
      let n = noise(x * 0.015, y * 0.015, i * 0.1);
      // Swirling, horizontal containment
      let a = n * TWO_PI * 2;
      x += cos(a) * 5;
      y += sin(a) * 2.5;
    }
    endShape();
  }

  // 8. THE EARTHLY REMAINS (Descending mineral settling)
  for (let i = 0; i < 1800; i++) {
    let x = cx + randomGaussian() * 280;
    let y = cy + abs(randomGaussian()) * 160;
    let steps = random(30, 140);

    let c = lerpColor(color(110, 65, 45), color(12, 15, 20), map(y, cy, height, 0, 1, true));

    for (let s = 0; s < steps; s++) {
      let p = s / steps;
      let n = noise(x * 0.008, y * 0.008);
      let a = HALF_PI + (n - 0.5) * 1.4;
      x += cos(a) * 2;
      y += sin(a) * 2;

      stroke(red(c), green(c), blue(c), sin(p * PI) * 45);
      strokeWeight(map(p, 0, 1, 3.5, 0.5));
      point(x, y);
    }
  }

  // 9. FINAL ATMOSPHERIC GLAZE (Vignette)
  blendMode(MULTIPLY);
  noFill();
  for (let r = 1200; r < 2600; r += 6) {
    let alpha = map(r, 1200, 2600, 0, 50);
    stroke(6, 8, 12, alpha);
    strokeWeight(8);
    circle(cx, height * 0.5, r);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Background: Deep Void to Luminous Ether
  drawBackground();

  // 2. Subtle Background Nebula / Dust
  drawBackgroundMist();

  // 3. The Horizon / Threshold of Dissolution
  drawThresholdGlow();

  // 4. The Ascending & Unraveling Essence (Particles/Threads)
  drawTheUnbinding();

  // 5. Foreground Anchors (The Heavy Earth / Rooted Form)
  drawEarthlyAnchors();

  // 6. Final Atmospheric Texture / Grain
  applyCanvasTexture();
}

function drawBackground() {
  // Vertical gradient with subtle noise distortion
  loadPixels();
  let cTop = color(238, 235, 224);       // Warm alabaster/bone light
  let cUpperMid = color(155, 175, 182);  // Pale celadon/spirit blue
  let cLowerMid = color(32, 42, 58);     // Deep twilight indigo
  let cBottom = color(12, 8, 12);        // Heavy obsidian/earth

  for (let y = 0; y < height; y++) {
    let ny = y / height;
    let baseCol;
    if (ny < 0.35) {
      baseCol = lerpColor(cTop, cUpperMid, easeInOutQuad(ny / 0.35));
    } else if (ny < 0.72) {
      baseCol = lerpColor(cUpperMid, cLowerMid, easeInOutQuad((ny - 0.35) / 0.37));
    } else {
      baseCol = lerpColor(cLowerMid, cBottom, easeInOutQuad((ny - 0.72) / 0.28));
    }

    let rBase = red(baseCol);
    let gBase = green(baseCol);
    let bBase = blue(baseCol);

    for (let x = 0; x < width; x++) {
      // Subtle organic wave in the background gradient
      let n = noise(x * 0.002, y * 0.002) * 18 - 9;
      let idx = (x + y * width) * 4;
      pixels[idx] = constrain(rBase + n, 0, 255);
      pixels[idx + 1] = constrain(gBase + n, 0, 255);
      pixels[idx + 2] = constrain(bBase + n, 0, 255);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();
}

function drawBackgroundMist() {
  noStroke();
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let ny = y / height;

    let r = random(80, 350);
    let alpha = random(2, 8);

    if (ny < 0.5) {
      fill(245, 242, 235, alpha);
    } else {
      fill(15, 20, 30, alpha * 1.5);
    }

    // Draw soft layered circles
    circle(x, y, r);
    circle(x + random(-30, 30), y + random(-30, 30), r * 0.6);
  }
}

function drawThresholdGlow() {
  // A warm, quiet glow right where the dense form breaks apart (around y = 1350)
  blendMode(ADD);
  noStroke();
  let cx = width * 0.5;
  let cy = height * 0.66;

  for (let i = 0; i < 150; i++) {
    let rad = map(i, 0, 150, 900, 50);
    let col = lerpColor(color(80, 30, 15, 1.5), color(220, 160, 100, 3), i / 150);
    fill(col);
    ellipse(cx + random(-20, 20), cy + random(-10, 10), rad * 1.2, rad * 0.6);
  }
  blendMode(BLEND);
}

function drawTheUnbinding() {
  // The core structure: thousands of flow-field trajectories starting from a dense, knotted
  // core in the lower center, rising, parting, and dissolving into the upper canvas.

  let numStrands = 3200;
  let centerX = width * 0.5;
  let startY = height * 0.78;

  for (let i = 0; i < numStrands; i++) {
    // Determine strand type: 0 = heavy root/vessel, 1 = transitional ember, 2 = ascending spirit/light
    let progressBias = random(1);

    // Starting positions clustered in a dense, slightly asymmetrical organic knot
    let angle = random(TWO_PI);
    let radius = pow(random(1), 2) * 260;
    let x = centerX + cos(angle) * radius;
    let y = startY + sin(angle) * (radius * 0.6) + random(-50, 150);

    // Color palettes for the transformation
    let cLife = color(140, 28, 22);     // Deep arterial crimson
    let cEarth = color(35, 20, 18);     // Dark umber/clot
    let cGold = color(235, 175, 95);    // Fleeting amber/vital spark
    let cAsh = color(130, 145, 155);    // Cooling ash/mist
    let cEther = color(248, 246, 240);  // Pure weightless light

    let steps = floor(random(180, 750));
    let strandSeed = random(10000);

    for (let s = 0; s < steps; s++) {
      let normStep = s / steps;
      let ny = y / height;

      // Calculate flow angle
      // Lower down: tight, swirling, inward-pulling tension (life holding itself together)
      // Higher up: open, vertical, gently billowing waves (release)
      let noiseScale = map(ny, 1.0, 0.0, 0.006, 0.0012);
      let nVal = noise(x * noiseScale, y * noiseScale, strandSeed * 0.0001);

      let upwardPull = -HALF_PI; // Straight up
      let swirlAngle = nVal * TWO_PI * 4;

      // Tension factor: high at bottom, zero at top
      let tension = constrain(map(ny, 0.85, 0.35, 1.0, 0.0), 0, 1);
      tension = easeInOutQuad(tension);

      // Pull towards center when in the lower 'living' zone
      let dx = centerX - x;
      let dy = (height * 0.72) - y;
      let toCenterAngle = atan2(dy, dx);

      // Combine forces
      let moveAngle;
      if (ny > 0.65) {
        // Knotted, pulsing core
        moveAngle = lerpAngle(swirlAngle, toCenterAngle, 0.45) + random(-0.2, 0.2);
        // Gradually force upward escape
        moveAngle = lerpAngle(moveAngle, upwardPull, pow(normStep, 1.5) * 0.7);
      } else {
        // Ascending and spreading out into the void
        let spread = map(x - centerX, -width/2, width/2, -0.6, 0.6);
        let gentleWave = map(nVal, 0, 1, -0.9, 0.9);
        moveAngle = upwardPull + gentleWave * (1 - tension * 0.5) + spread * (1 - ny);
      }

      // Step size increases as it becomes lighter/freer
      let speed = map(ny, 1.0, 0.0, 1.5, 4.2);
      x += cos(moveAngle) * speed;
      y += sin(moveAngle) * speed;

      // Determine color based on vertical position (the threshold of death)
      let currentCol;
      if (ny > 0.72) {
        currentCol = lerpColor(cEarth, cLife, noise(i, s * 0.02));
      } else if (ny > 0.58) {
        let t = map(ny, 0.72, 0.58, 0, 1);
        let base = lerpColor(cLife, cGold, t);
        currentCol = lerpColor(base, cAsh, noise(x * 0.01, y * 0.01) * 0.5);
      } else if (ny > 0.35) {
        let t = map(ny, 0.58, 0.35, 0, 1);
        currentCol = lerpColor(cGold, cAsh, t);
        if (random() < 0.3) currentCol = lerpColor(currentCol, cEther, t * 0.8);
      } else {
        let t = constrain(map(ny, 0.35, 0.05, 0, 1), 0, 1);
        currentCol = lerpColor(cAsh, cEther, t);
      }

      // Alpha & Weight: Dense and opaque at the bottom, gossamer and fading at the top
      let alpha = sin(normStep * PI); // Fade in and out along the strand
      let heightFade = constrain(map(ny, 0.15, 0.02, 1, 0), 0, 1);

      let weight = map(ny, 0.9, 0.1, 3.2, 0.5) * map(normStep, 0, 1, 1.2, 0.2);
      let finalAlpha = alpha * heightFade * map(ny, 0.9, 0.1, 90, 18);

      strokeWeight(max(0.3, weight));
      stroke(red(currentCol), green(currentCol), blue(currentCol), finalAlpha);
      point(x, y);

      // Occasional "release" motes—sparks of memory/matter drifting off as the form unbinds
      if (ny < 0.68 && ny > 0.2 && random() < 0.0035) {
        drawDriftingMote(x, y, ny, currentCol);
      }
    }
  }
}

function drawDriftingMote(x, y, ny, baseCol) {
  push();
  noStroke();
  let r = random(2, 7) * map(ny, 0.7, 0.2, 1.2, 0.4);
  let alpha = random(30, 110) * map(ny, 0.7, 0.2, 1, 0.3);

  // Soft glow around mote
  fill(red(baseCol), green(baseCol), blue(baseCol), alpha * 0.25);
  circle(x, y, r * 3.5);

  // Core of mote
  fill(255, 250, 240, alpha);
  circle(x, y, r);
  pop();
}

function drawEarthlyAnchors() {
  // Deep, heavy shadow structures at the very bottom—representing the physical vessel/earth
  // left behind, grounding the composition.
  noStroke();
  let cx = width * 0.5;
  let by = height;

  for (let i = 0; i < 800; i++) {
    let x = random(width);
    let distFromCenter = abs(x - cx) / (width * 0.5);

    // Mound shape in the center, tapering to the edges
    let maxH = map(pow(distFromCenter, 1.8), 0, 1, height * 0.26, height * 0.08);
    let y = height - random(maxH);

    let n = noise(x * 0.005, y * 0.005);
    let col = lerpColor(color(8, 6, 10), color(28, 16, 20), n);

    fill(red(col), green(col), blue(col), random(15, 45));

    // Draw organic, horizontal-ish strata/roots
    let w = random(20, 160);
    let h = random(8, 45);

    push();
    translate(x, y);
    rotate(map(x - cx, -width/2, width/2, 0.35, -0.35) + (n - 0.5) * 0.5);
    ellipse(0, 0, w, h);
    pop();
  }

  // A few stark, dark filaments reaching up from the base, snapping/fading at the threshold
  for (let i = 0; i < 180; i++) {
    let x = cx + random(-450, 450) * pow(random(1), 1.5);
    let y = height;
    let steps = random(100, 320);

    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let angle = -HALF_PI + (noise(x * 0.008, y * 0.008, i) - 0.5) * 2.2;
      x += cos(angle) * 2;
      y += sin(angle) * 2;

      let w = (1 - t) * 3.5;
      strokeWeight(w);
      stroke(12, 8, 12, (1 - t) * 140);
      point(x, y);
    }
  }
}

function applyCanvasTexture() {
  // Adds a fine painterly grain across the entire piece to unify the dark void and the light
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Fine tooth grain
      let grain = random(-7, 7);

      // Subtle canvas weave
      let weave = (sin(x * 0.8) + sin(y * 0.8)) * 1.5;

      let delta = grain + weave;

      pixels[idx] = constrain(pixels[idx] + delta, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + delta, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + delta, 0, 255);
    }
  }
  updatePixels();
}

// Helper: Smooth easing
function easeInOutQuad(t) {
  return t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t;
}

// Helper: Shortest-path angle interpolation
function lerpAngle(a, b, step) {
  let delta = b - a;
  while (delta < -PI) delta += TWO_PI;
  while (delta > PI) delta -= TWO_PI;
  return a + delta * step;
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(7, 9, 14);

  // 1. Deep void & descending light wash
  drawBackgroundWash();

  // 2. Distant cosmic dust & quiet stars
  drawStarfield();

  // 3. The Horizon / The Threshold
  drawThreshold();

  // 4. The Vessel (dark organic roots/base holding the life-knot)
  drawVessel();

  // 5. The Unbinding (ascending and dissolving threads of life)
  drawUnbindingThreads();

  // 6. The Core (the final intense ember of gathered being)
  drawCoreGlow();

  // 7. Released Motes (sparks and ashes drifting into the infinite)
  drawDriftingMotes();

  // 8. Fine oil-paint texture / canvas grain
  applyCanvasTexture();
}

function drawBackgroundWash() {
  loadPixels();
  let cx = width * 0.5;
  let cy = height * 0.68;

  for (let y = 0; y < height; y++) {
    let ny = y / height;
    for (let x = 0; x < width; x++) {
      let nx = x / width;

      // Radial distance from the life-center
      let d = dist(x, y, cx, cy) / (width * 0.85);

      // Subtle organic variation
      let n = noise(nx * 2.5, ny * 2.5) * 0.12;
      let val = constrain(1.0 - d + n, 0, 1);

      // Vertical gradient for the abyss above and earth below
      let abyss = smoothstep(0.0, 0.75, ny);

      // Base palette: Deep obsidian-indigo to warm umber-slate near the core
      let r = lerp(5, 22, abyss) + pow(val, 3) * 65;
      let g = lerp(7, 20, abyss) + pow(val, 3.5) * 42;
      let b = lerp(13, 28, abyss) + pow(val, 2.5) * 55;

      // Darken the very bottom (the earthly anchor)
      if (ny > 0.68) {
        let ground = map(ny, 0.68, 1.0, 1.0, 0.15);
        r *= ground;
        g *= ground;
        b *= ground;
      }

      let idx = (y * width + x) * 4;
      pixels[idx] = r;
      pixels[idx + 1] = g;
      pixels[idx + 2] = b;
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();
}

function drawStarfield() {
  noStroke();
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(height * 0.72);
    // Fewer stars near the bottom threshold, more in the deep upper void
    let prob = 1.0 - (y / (height * 0.72));
    if (random() < prob) {
      let s = random(0.5, 2.2);
      let a = random(15, 110) * prob;
      fill(215, 225, 245, a);
      circle(x, y, s);
    }
  }

  // Nebulous veils in the upper canvas
  blendMode(SCREEN);
  for (let i = 0; i < 400; i++) {
    let x = random(width * 0.1, width * 0.9);
    let y = random(height * 0.05, height * 0.65);
    let d = dist(x, y, width * 0.5, height * 0.4);
    if (d < width * 0.42) {
      let rad = random(60, 240);
      let col = random() < 0.6 ? color(25, 45, 70, 3) : color(65, 45, 55, 3);
      fill(col);
      circle(x, y, rad);
    }
  }
  blendMode(BLEND);
}

function drawThreshold() {
  let ty = height * 0.68;
  blendMode(ADD);
  for (let i = 0; i < 120; i++) {
    let yOff = randomGaussian(0, 18);
    let w = random(width * 0.2, width * 0.95);
    let x1 = width * 0.5 - w * 0.5 + random(-50, 50);
    let x2 = width * 0.5 + w * 0.5 + random(-50, 50);

    let alpha = map(abs(yOff), 0, 40, 12, 0);
    stroke(180, 145, 110, max(0, alpha));
    strokeWeight(random(0.5, 2.5));
    line(x1, ty + yOff, x2, ty + yOff);
  }
  blendMode(BLEND);
}

function drawVessel() {
  // The dark, tangled form of physical existence below the threshold
  let cx = width * 0.5;
  let cy = height * 0.68;

  noFill();
  for (let i = 0; i < 1600; i++) {
    let angle = random(PI * 0.05, PI * 0.95);
    let rad = abs(randomGaussian(0, 180));
    let x = cx + cos(angle) * rad * 1.4;
    let y = cy + sin(angle) * rad * 0.6 + random(0, 350);

    stroke(4, 5, 8, random(40, 160));
    strokeWeight(random(1, 6));

    beginShape();
    for (let step = 0; step < 30; step++) {
      vertex(x, y);
      let n = noise(x * 0.004, y * 0.004, i * 0.01);
      let a = map(n, 0, 1, -PI, PI) + PI * 0.5;
      // Pull slightly toward the core
      let toCore = atan2(cy - y, cx - x);
      a = lerp(a, toCore, 0.35);
      x += cos(a) * 8;
      y += sin(a) * 8;
    }
    endShape();
  }

  // Dense dark silhouette right below the knot
  noStroke();
  for (let i = 0; i < 300; i++) {
    let x = cx + randomGaussian(0, 140);
    let y = cy + random(10, 280);
    let r = random(30, 130);
    fill(5, 6, 10, random(20, 60));
    circle(x, y, r);
  }
}

function drawUnbindingThreads() {
  let cx = width * 0.5;
  let cy = height * 0.68;

  // Palette representing transition: Warm Gold/Cinnabar -> Bone/Rose -> Teals/Slates -> Deep Indigo
  let lifeColors = [
    color(255, 235, 190), // Incandescent memory
    color(240, 175, 105), // Warm gold
    color(210, 105, 75),  // Terracotta / lifeblood
    color(225, 215, 205)  // Bone / parchment
  ];

  let etherColors = [
    color(120, 165, 180), // Pale spirit slate
    color(70, 120, 145),  // Deepening cyan-grey
    color(85, 75, 125),   // Twilight violet
    color(30, 45, 80)     // Void blue
  ];

  // 4200 individual threads unspooling upward
  for (let i = 0; i < 4200; i++) {
    // Originate tightly around the knot
    let startAngle = random(TWO_PI);
    let startR = abs(randomGaussian(0, 75));
    let x = cx + cos(startAngle) * startR * 1.3;
    let y = cy + sin(startAngle) * startR * 0.65;

    let cStart = random(lifeColors);
    let cEnd = random(etherColors);

    let maxSteps = int(random(140, 520));
    let speed = random(2.2, 4.0);
    let swBase = random(0.4, 2.6);

    // Unique noise offset for coherent yet separating strands
    let streamGroup = floor(random(18));
    let nOff = streamGroup * 100 + random(25);

    for (let s = 0; s < maxSteps; s++) {
      let t = s / maxSteps; // 0 at knot, 1 at dissolution

      // Multi-scale curl/flow field
      let n1 = noise(x * 0.0018, y * 0.0018, nOff * 0.01);
      let n2 = noise(x * 0.006, y * 0.006, i * 0.002);

      // Base direction is upward (-HALF_PI)
      // At the bottom (t near 0), threads swirl tightly; higher up, they drift apart and ascend smoothly
      let swirl = map(n1, 0, 1, -PI * 1.1, PI * 1.1) * (1.0 - t * 0.35);
      let fine = map(n2, 0, 1, -PI * 0.4, PI * 0.4);

      // Slight outward expansion as it rises into the upper canvas
      let centerOffset = (x - cx) / (width * 0.5);
      let expansion = centerOffset * t * 0.6;

      let angle = -HALF_PI + swirl + fine + expansion;

      // Early steps are pulled back toward the knot, creating a braided tension
      if (t < 0.22) {
        let pullAngle = atan2(cy - y, cx - x) + HALF_PI * (i % 2 === 0 ? 1 : -1);
        angle = lerp(angle, pullAngle, (0.22 - t) * 2.5);
      }

      let nx = x + cos(angle) * speed;
      let ny = y + sin(angle) * speed;

      // Color and opacity evolution
      let c = lerpColor(cStart, cEnd, pow(t, 0.65));
      let alpha = sin(t * PI) * map(swBase, 0.4, 2.6, 55, 18);

      // Switch blend modes softly by boosting luminosity near the core
      if (t < 0.25) {
        blendMode(ADD);
        alpha *= 0.65;
      } else {
        blendMode(BLEND);
      }

      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(swBase * (1.0 - t * 0.75));
      line(x, y, nx, ny);

      x = nx;
      y = ny;

      // Stop if off-canvas
      if (x < 40 || x > width - 40 || y < 40) break;
    }
  }
  blendMode(BLEND);
}

function drawCoreGlow() {
  let cx = width * 0.5;
  let cy = height * 0.68;

  // The intense, peaceful radiance at the exact point of letting go
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 250; i++) {
    let r = map(i, 0, 250, 420, 4);
    let x = cx + randomGaussian(0, r * 0.08);
    let y = cy + randomGaussian(0, r * 0.05);

    let t = i / 250;
    let c = lerpColor(color(180, 90, 50), color(255, 245, 220), pow(t, 1.5));
    let alpha = map(t, 0, 1, 1.5, 8);

    fill(red(c), green(c), blue(c), alpha);
    ellipse(x, y, r * 1.3, r * 0.85);
  }

  // Fine luminous filaments knotted inside the core
  noFill();
  for (let i = 0; i < 350; i++) {
    let a1 = random(TWO_PI);
    let a2 = a1 + random(-PI * 0.8, PI * 0.8);
    let r1 = abs(randomGaussian(0, 55));
    let r2 = abs(randomGaussian(0, 75));

    let x1 = cx + cos(a1) * r1 * 1.4;
    let y1 = cy + sin(a1) * r1 * 0.7;
    let x2 = cx + cos(a2) * r2 * 1.4;
    let y2 = cy + sin(a2) * r2 * 0.7;

    let cx1 = cx + randomGaussian(0, 60);
    let cy1 = cy + randomGaussian(0, 40);
    let cx2 = cx + randomGaussian(0, 60);
    let cy2 = cy + randomGaussian(0, 40);

    stroke(255, 235, 200, random(10, 45));
    strokeWeight(random(0.4, 1.4));
    bezier(x1, y1, cx1, cy1, cx2, cy2, x2, y2);
  }

  blendMode(BLEND);
}

function drawDriftingMotes() {
  let cx = width * 0.5;
  let cy = height * 0.68;

  // Fragments of light and ash rising and dispersing
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 1600; i++) {
    // Distributed along an upward expanding cone
    let hNorm = pow(random(1), 1.25); // More concentrated near the knot, sparser above
    let y = map(hNorm, 0, 1, cy + 40, height * 0.04);

    let spread = map(hNorm, 0, 1, 70, width * 0.36);
    let x = cx + randomGaussian(0, spread);

    // Sway with the same noise field as the threads
    let n = noise(x * 0.002, y * 0.002);
    x += map(n, 0, 1, -60, 60);

    let sz = random(0.8, 4.2) * (1.0 - hNorm * 0.5);

    // Color shifts from warm ember to cool starlight as it ascends
    let cWarm = color(255, 210, 150);
    let cCool = color(150, 200, 235);
    let c = lerpColor(cWarm, cCool, pow(hNorm, 0.8));

    let alpha = random(40, 210) * (1.0 - hNorm * 0.65);

    // Soft halo
    fill(red(c), green(c), blue(c), alpha * 0.22);
    circle(x, y, sz * 3.5);

    // Bright core
    fill(red(c), green(c), blue(c), alpha);
    circle(x, y, sz);
  }

  blendMode(BLEND);

  // Dark ash particles near the lower edges of the release (returning to earth)
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = cx + randomGaussian(0, 240);
    let y = cy + randomGaussian(0, 110);
    let sz = random(1, 3.5);
    fill(12, 14, 20, random(80, 200));
    circle(x, y, sz);
  }
}

function applyCanvasTexture() {
  // Subtle organic grain to unify the digital strokes into a tactile painting
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (y * width + x) * 4;

      // Fine weave + random tooth
      let weave = ((x % 3 === 0) || (y % 3 === 0)) ? 2 : -1;
      let grain = random(-6, 6) + weave;

      // Soft vignette at the edges of the canvas
      let dx = (x - width * 0.5) / (width * 0.5);
      let dy = (y - height * 0.5) / (height * 0.5);
      let vig = constrain(1.0 - pow(dx * dx + dy * dy, 1.4) * 0.28, 0, 1);

      pixels[idx]     = constrain((pixels[idx] + grain) * vig, 0, 255);
      pixels[idx + 1] = constrain((pixels[idx + 1] + grain) * vig, 0, 255);
      pixels[idx + 2] = constrain((pixels[idx + 2] + grain) * vig, 0, 255);
    }
  }
  updatePixels();
}

function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Background: Deep, primordial void transitioning to a quiet, warm abyss
  background(7, 9, 14);

  drawBackgroundAtmosphere();

  // 2. The Threshold / Horizon of earthly weight
  drawGroundAndRoots();

  // 3. The Core & The Unspooling (Life force dissolving into the infinite)
  drawDissolution();

  // 4. The Vessel (The fragile boundary of the self, opening up)
  drawVessel();

  // 5. Final atmospheric integration and canvas texture
  drawStardust();
  applyCanvasTexture();
}

function drawBackgroundAtmosphere() {
  // Subtle large-scale washes of color using circles with very low opacity
  noStroke();

  // Upper expanse - deep indigo and slate
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let r = random(200, 800);
    let d = dist(x, y, width * 0.5, height * 0.4);
    let factor = map(d, 0, 1200, 1, 0, true);

    fill(18 + factor * 20, 24 + factor * 25, 38 + factor * 30, 3);
    circle(x, y, r);
  }

  // Central glow - the warmth of the departing essence
  for (let i = 0; i < 300; i++) {
    let x = width * 0.5 + randomGaussian(0, 250);
    let y = height * 0.55 + randomGaussian(0, 350);
    let r = random(100, 600);
    fill(180, 130, 90, 2.5);
    circle(x, y, r);
  }

  // Lower depths - heavy umber and obsidian
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height * 0.65, height + 200);
    let r = random(200, 700);
    fill(5, 4, 7, 15);
    circle(x, y, r);
  }
}

function drawGroundAndRoots() {
  // The heavy, structured reality at the bottom where the vessel rests
  push();
  blendMode(MULTIPLY);
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = random(height * 0.72, height);
    let w = random(50, 300);
    let h = random(2, 15);
    fill(12, 10, 15, random(10, 40));
    noStroke();
    rect(x, y, w, h, 5);
  }
  pop();

  // Pale, calcified root-like structures anchoring the base, fading out
  strokeWeight(1);
  for (let i = 0; i < 600; i++) {
    let x = width * 0.5 + randomGaussian(0, 300);
    let y = random(height * 0.75, height * 0.95);

    stroke(90, 80, 75, random(10, 40));
    noFill();
    beginShape();
    for (let s = 0; s < 40; s++) {
      vertex(x, y);
      let angle = noise(x * 0.005, y * 0.005) * TWO_PI * 2;
      // Pull generally downwards and outwards
      x += cos(angle) * 2 + (x - width * 0.5) * 0.005;
      y += abs(sin(angle)) * 2 + 0.5;
    }
    endShape();
  }
}

function drawDissolution() {
  // Thousands of fine threads rising from the vessel, losing their golden
  // warmth and coherence as they ascend into the cool, vast flow field.

  let numThreads = 4500;
  let originX = width * 0.5;
  let originY = height * 0.74;

  for (let i = 0; i < numThreads; i++) {
    // Start within the bounds of the vessel
    let angleOffset = random(TWO_PI);
    let radiusOffset = sqrt(random()) * 140;
    let x = originX + cos(angleOffset) * radiusOffset;
    let y = originY + sin(angleOffset) * (radiusOffset * 0.4);

    let maxSteps = int(random(150, 950));

    // Color palettes for the transition
    // Start: Incandescent gold / warm ivory / deep ember
    let cStart = color(255, random(190, 230), random(140, 180));
    if (random() < 0.2) cStart = color(220, 90, 50); // occasional arterial ember

    // Mid: Cool ash / pale slate / dusty violet
    let cMid = color(120, random(130, 150), random(160, 180));

    // End: Deep void blue / faint starlight
    let cEnd = color(30, 45, 70);

    let weight = random(0.4, 2.2);
    let alphaBase = random(8, 35);

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;

      // Calculate color based on height/progress
      let currentColor;
      if (progress < 0.35) {
        currentColor = lerpColor(cStart, cMid, map(progress, 0, 0.35, 0, 1));
      } else {
        currentColor = lerpColor(cMid, cEnd, map(progress, 0.35, 1, 0, 1));
      }

      // Alpha fades in slightly, then fades out completely at the top
      let a = alphaBase * sin(progress * PI);
      if (progress < 0.1) a = map(progress, 0, 0.1, 0, alphaBase);

      stroke(red(currentColor), green(currentColor), blue(currentColor), a);
      strokeWeight(weight * (1 - progress * 0.7));

      let prevX = x;
      let prevY = y;

      // Flow field mathematics:
      // Tightly bound and vertical near the origin, expansive and curling higher up
      let nScale = 0.0018;
      let n = noise(x * nScale, y * nScale, i * 0.0001);

      // Base upward angle is -HALF_PI
      // As y decreases (goes up), turbulence increases
      let heightFactor = map(y, originY, 0, 0.1, 2.5, true);
      let angle = -HALF_PI + (n - 0.48) * PI * heightFactor;

      // Add a gentle overarching S-curve drift to the whole composition
      let globalDrift = sin(y * 0.003) * 0.6;

      let stepSize = 2.2;
      x += cos(angle) * stepSize + globalDrift;
      y += sin(angle) * stepSize;

      // Slight pull towards the center just above the vessel (necking effect)
      if (y > height * 0.55 && y < originY) {
        x = lerp(x, width * 0.5, 0.008);
      }

      line(prevX, prevY, x, y);

      // Occasional shedding of "spores" or dust motes as the thread dissolves
      if (progress > 0.4 && random() < 0.008) {
        noStroke();
        fill(red(currentColor), green(currentColor), blue(currentColor), a * 2.5);
        circle(x + random(-15, 15), y + random(-15, 15), random(1, 3.5));
      }
    }
  }

  // Intense, quiet core light right at the threshold of the vessel
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 150; i++) {
    let r = map(i, 0, 150, 300, 10);
    fill(255, 210, 160, 1.2);
    ellipse(originX, originY - 20, r, r * 0.6);
  }
  pop();
}

function drawVessel() {
  // The physical form: a dark, weathered, nested structure at the bottom center,
  // like a broken cocoon, aribcage, or an ancient bowl, fracturing open at the top.

  let cx = width * 0.5;
  let cy = height * 0.76;

  // Dark shadowy mass of the body/vessel
  noStroke();
  for (let i = 0; i < 400; i++) {
    let angle = random(PI * 0.05, PI * 0.95); // Bottom hemisphere mostly
    let radX = random(20, 220);
    let radY = random(10, 110);
    let x = cx + cos(angle) * radX;
    let y = cy + sin(angle) * radY;

    fill(10, 8, 12, random(20, 60));
    circle(x, y, random(20, 80));
  }

  // Textured ribs/shards of the vessel holding the light, breaking apart
  for (let i = 0; i < 1200; i++) {
    let t = random(1);
    // Concentrate on the lower arc, opening up at the top
    let aStart = random(-0.2, PI + 0.2);
    let rBase = 160 + randomGaussian(0, 25);

    let x = cx + cos(aStart) * rBase * 1.2;
    let y = cy + sin(aStart) * rBase * 0.55;

    // Color of the vessel: bone, charcoal, dried earth, with gold leaf edges
    let isRim = (y < cy - 10) && (abs(x - cx) < 160);

    if (isRim && random() < 0.4) {
      // Illuminated broken edges catching the escaping light
      stroke(240, 190, 130, random(30, 90));
      strokeWeight(random(0.5, 2));
    } else if (random() < 0.3) {
      // Bone / Ash highlights
      stroke(110, 105, 100, random(20, 50));
      strokeWeight(random(0.5, 1.5));
    } else {
      // Deep charcoal structure
      stroke(15, 12, 18, random(40, 100));
      strokeWeight(random(1, 3.5));
    }

    noFill();
    beginShape();
    for (let s = 0; s < 25; s++) {
      vertex(x, y);
      // Curve inward towards the bottom center to form a cup/cradle
      let toCenterAngle = atan2(cy + 40 - y, cx - x);
      let n = noise(x * 0.01, y * 0.01, i) * 1.5;
      x += cos(toCenterAngle + n - 0.75) * 4;
      y += sin(toCenterAngle + n - 0.75) * 2;
    }
    endShape();
  }

  // Fragments of the vessel floating upward, caught in the draft of the spirit
  for (let i = 0; i < 180; i++) {
    let x = cx + randomGaussian(0, 110);
    let y = random(height * 0.35, cy - 20);

    // Fragments get smaller as they rise
    let size = map(y, height * 0.35, cy, 1, 14);

    // Distance from the central column
    let dFromCenter = abs(x - (cx + sin(y * 0.003) * 50));
    if (dFromCenter < 180) {
      push();
      translate(x, y);
      rotate(noise(x * 0.01, y * 0.01) * TWO_PI);

      // Dark shard with a lit bottom edge (lit from below)
      noStroke();
      fill(20, 18, 24, map(y, height * 0.35, cy, 20, 220));
      beginShape();
      vertex(-size, -size * 0.5);
      vertex(size, -size * 0.2);
      vertex(size * 0.5, size);
      vertex(-size * 0.8, size * 0.6);
      endShape(CLOSE);

      // Lit edge
      stroke(255, 210, 160, map(y, height * 0.35, cy, 0, 150));
      strokeWeight(0.8);
      line(size * 0.5, size, -size * 0.8, size * 0.6);
      pop();
    }
  }
}

function drawStardust() {
  // The upper realm where the threads have completely dissolved into quiet universality
  noStroke();
  for (let i = 0; i < 2000; i++) {
    let x = random(width);
    let y = random(height * 0.65);

    // Density is higher near the top and along the central vapor trail
    let n = noise(x * 0.003, y * 0.003);
    if (n > 0.42) {
      let alpha = map(y, 0, height * 0.65, 120, 0) * (n - 0.4);

      if (random() < 0.8) {
        fill(200, 215, 235, alpha);
      } else {
        fill(245, 210, 180, alpha); // Faint memory of warmth
      }

      let r = random(0.5, 2.2);
      circle(x, y, r);
    }
  }
}

function applyCanvasTexture() {
  // Gives the piece a tactile, painterly finish (linen weave + organic grain)
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);

  for (let i = 0; i < totalPixels; i += 4) {
    let pxIndex = i / 4;
    let x = pxIndex % (width * d);
    let y = floor(pxIndex / (width * d));

    // Subtle linen weave pattern
    let weaveX = sin(x * 0.8) * 3;
    let weaveY = sin(y * 0.8) * 3;

    // Organic film grain
    let grain = random(-10, 10);

    // Vignette to deepen the edges
    let distFromCenter = dist(x, y, width * 0.5, height * 0.5);
    let vignette = map(distFromCenter, 400, 1200, 0, -18, true);

    let mod = (weaveX + weaveY) * 0.4 + grain * 0.6 + vignette;

    pixels[i]     = constrain(pixels[i] + mod, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + mod, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + mod, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(HSB, 360, 100, 100, 1.0);
  background(225, 45, 5);

  drawCosmicVoid();
  drawCoreGlow();
  drawDenseMatter();
  drawUnbindingThreads();
  drawThresholdVessel();
  drawSoulMotes();
  drawStardustAndGrain();
}

// 1. The vast, quiet ocean of the background
function drawCosmicVoid() {
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    let yn = y / height;

    // Shift from deep pelagic teal/indigo at top to warm umber-black at bottom
    let h = lerp(215, 240, n) + (yn > 0.7 ? (yn - 0.7) * 80 : 0);
    let s = lerp(35, 65, n);
    let b = lerp(14, 3, pow(yn, 0.8)) * (0.5 + 0.7 * n);

    // Subtle clearing down the center for the ascent
    let centerDist = abs(x - width * 0.5) / (width * 0.5);
    if (y < height * 0.75) {
      b += (1 - centerDist) * 5 * (1 - yn);
    }

    fill(h % 360, s, constrain(b, 2, 25), 0.04);

    push();
    translate(x, y);
    rotate(n * TWO_PI);
    ellipse(0, 0, random(120, 450), random(80, 300));
    pop();
  }
}

// 2. The soft halo where form transitions into spirit
function drawCoreGlow() {
  blendMode(SCREEN);
  noStroke();
  let cx = width * 0.5;
  let cy = height * 0.73;

  // Threshold warmth
  for (let i = 0; i < 150; i++) {
    let r = map(i, 0, 150, 900, 30);
    let h = map(i, 0, 150, 205, 38);
    let s = map(i, 0, 150, 60, 35);
    let b = map(i, 0, 150, 8, 25);
    fill((h + 360) % 360, s, b, 0.012);
    ellipse(cx + random(-15, 15), cy + random(-10, 10), r * 1.4, r * 0.8);
  }

  // Ascending column of pale light
  for (let i = 0; i < 120; i++) {
    let y = random(height * 0.1, height * 0.75);
    let yn = map(y, height * 0.1, height * 0.75, 0, 1);
    let x = cx + (noise(y * 0.002, 9) - 0.5) * 350 * (1 - yn * 0.6);
    let w = map(yn, 0, 1, 700, 220);
    let h = map(yn, 0, 1, 195, 42);
    fill(h, 30, 18, 0.01);
    ellipse(x, y, w, random(200, 500));
  }
  blendMode(BLEND);
}

// 3. The entangled, heavy architecture of living matter at the base
function drawDenseMatter() {
  let cx = width * 0.5;
  let baseY = height * 0.75;

  // Deep shadow washes to ground the base
  noStroke();
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(baseY - 120, height);
    let d = dist(x, y, cx, baseY);
    let n = noise(x * 0.004, y * 0.004);
    fill(25, 50, 4, 0.08);
    ellipse(x, y, random(60, 220), random(40, 120));
  }

  // Sinew, roots, and bone-like strata
  for (let i = 0; i < 3200; i++) {
    let t = pow(random(), 1.3);
    let x = cx + (random() - 0.5) * width * (0.25 + 0.85 * t);
    let arch = pow(abs(x - cx) / (width * 0.5), 1.6) * 260;
    let y = baseY + t * (height - baseY) + arch - 30;

    if (y > height + 50) continue;

    let n = noise(x * 0.005, y * 0.005);
    let distFromThreshold = constrain((y - (baseY - 40)) / (height - baseY), 0, 1);

    let h, s, b, alp;
    let roll = random();
    if (roll < 0.45) {
      // Dried blood, rust, and clay (the body's warmth)
      h = lerp(8, 28, n);
      s = lerp(65, 80, distFromThreshold);
      b = lerp(42, 8, distFromThreshold);
      alp = random(0.15, 0.4);
    } else if (roll < 0.8) {
      // Bone, ash, and parchment (structure)
      h = lerp(32, 48, n);
      s = lerp(22, 45, distFromThreshold);
      b = lerp(75, 15, distFromThreshold);
      alp = random(0.12, 0.35);
    } else {
      // Deep void fissures
      h = 225;
      s = 50;
      b = 5;
      alp = 0.55;
    }

    noFill();
    stroke(h, s, b, alp);
    strokeWeight(random(0.8, 3.8) * (1 - distFromThreshold * 0.4));

    // Draw organic, knotted Bezier fibers pulling toward the center threshold
    let pullX = lerp(x, cx, 0.25 * (1 - distFromThreshold));
    let pullY = y - random(25, 110) * (1 - distFromThreshold * 0.6);
    let angle = (noise(x * 0.008, y * 0.008) - 0.5) * PI;

    let x2 = pullX + cos(angle - HALF_PI) * random(20, 80);
    let y2 = pullY + sin(angle - HALF_PI) * random(20, 80);
    let x3 = x2 + (noise(i * 0.1) - 0.5) * 90;
    let y3 = y2 - random(15, 70);

    beginShape();
    vertex(x, y);
    bezierVertex(pullX, pullY, x2, y2, x3, y3);
    endShape();
  }
}

// 4. The Unbinding: 12,000 threads of form untying and rising into the void
function drawUnbindingThreads() {
  let numThreads = 12000;
  let cx = width * 0.5;
  let baseY = height * 0.74;

  noFill();

  for (let i = 0; i < numThreads; i++) {
    // Gaussian-like clustering at the center
    let spread = (random() + random() + random() - 1.5) * 0.66;
    let startX = cx + spread * 680;
    let arch = pow(abs(startX - cx) / 550, 2) * 140;
    let startY = baseY + arch + random(-25, 140);

    let x = startX;
    let y = startY;

    // Color temperament of this thread (0 = arterial/gold, 1 = bone/cyan/spirit)
    let cType = constrain(map(abs(startX - cx), 0, 380, 0.15, 0.85) + random(-0.25, 0.25), 0, 1);

    // Some threads release early, some travel almost to the top
    let maxSteps = int(random(35, 290) * (1 - abs(spread) * 0.45));
    let stepLen = random(3.5, 6.5);

    for (let s = 0; s < maxSteps; s++) {
      let progress = s / maxSteps;
      let alt = constrain(map(y, baseY + 100, height * 0.04, 0, 1), 0, 1);

      // Multi-scale curl/flow field
      let n1 = noise(x * 0.0022, y * 0.0022);
      let n2 = noise(x * 0.009, y * 0.009, i * 0.0005);

      // Base upward angle with lyrical S-curve drift
      let drift = (n1 - 0.48) * PI * 1.15 + (n2 - 0.5) * 0.65;

      // Gently funnel inward near the threshold, then fan out into infinity above
      let centerBias = 0;
      if (alt < 0.28) {
        centerBias = (cx - x) * 0.0028 * (1 - alt / 0.28);
      } else {
        centerBias = (x - cx) * 0.0009 * ((alt - 0.28) / 0.72);
      }

      let angle = -HALF_PI + drift + centerBias;
      let nx = x + cos(angle) * stepLen;
      let ny = y + sin(angle) * stepLen;

      // Color alchemy along the ascent
      let h, sat, bri;
      if (alt < 0.18) {
        // Erupting from clay, rust, and bone into incandescent gold
        let t = alt / 0.18;
        h = lerp(lerp(14, 34, cType), 42, t);
        sat = lerp(75, 25, t);
        bri = lerp(25, 98, t);
      } else if (alt < 0.55) {
        // Cooling from gold/ivory into spectral silver and paleverdigris
        let t = (alt - 0.18) / 0.37;
        h = lerp(42, lerp(175, 205, cType), t);
        sat = lerp(22, 38, t);
        bri = lerp(98, 78, t);
      } else {
        // Dissolving into deep indigo and pelagic night
        let t = (alt - 0.55) / 0.45;
        h = lerp(lerp(175, 205, cType), 228, t);
        sat = lerp(38, 60, t);
        bri = lerp(78, 18, t);
      }

      let fadeIn = constrain(s / 12.0, 0, 1);
      let fadeOut = pow(1 - progress, 1.5);
      let alpha = fadeIn * fadeOut * (alt < 0.22 ? 0.14 : 0.075);

      // Rare, bright filaments of pure memory
      if (i % 19 === 0 && alt < 0.45) {
        bri = 100;
        sat *= 0.45;
        alpha *= 1.8;
      }

      let sw = map(progress, 0, 1, 2.2, 0.35) * (i % 9 === 0 ? 1.5 : 0.85);

      stroke(h, sat, bri, alpha);
      strokeWeight(sw);
      line(x, y, nx, ny);

      x = nx;
      y = ny;

      if (y < 30 || x < 30 || x > width - 30) break;
    }
  }
}

// 5. The Horizontal Vessel: a quiet, reclining cadence at the threshold
function drawThresholdVessel() {
  let cx = width * 0.5;
  let cy = height * 0.745;

  // Luminous mist pooling along the horizon of release
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 450; i++) {
    let spread = (random() + random() - 1.0) * 480;
    let x = cx + spread;
    let curveY = pow(abs(spread) / 480, 1.8) * 70;
    let y = cy + curveY + random(-25, 25);

    let distFactor = 1 - abs(spread) / 480;
    let h = lerp(25, 46, distFactor + random(-0.1, 0.1));
    let s = lerp(60, 18, distFactor);
    let b = lerp(20, 85, pow(distFactor, 1.5));

    fill(h, s, b, 0.025 * distFactor);
    ellipse(x, y, random(30, 140), random(8, 30));
  }
  blendMode(BLEND);

  // Delicate, fracturing rib/hull arcs — a form laying down its weight
  noFill();
  for (let i = 0; i < 380; i++) {
    let w = random(80, 680);
    let x1 = cx - w * random(0.3, 0.6);
    let x2 = cx + w * random(0.3, 0.6);
    let yOffset = map(w, 80, 680, -15, 95) + random(-18, 18);
    let y1 = cy + yOffset + pow(abs(x1 - cx) / 450, 2) * 80;
    let y2 = cy + yOffset + pow(abs(x2 - cx) / 450, 2) * 80;

    let ctrlY = cy + yOffset - random(10, 55);

    let isLight = random() < 0.65;
    if (isLight) {
      stroke(random(34, 48), random(15, 35), random(75, 100), random(0.08, 0.28));
    } else {
      stroke(random(15, 25), random(50, 80), random(10, 25), random(0.2, 0.45));
    }
    strokeWeight(random(0.5, 2.2));

    beginShape();
    vertex(x1, y1);
    bezierVertex(
      lerp(x1, x2, 0.33), ctrlY + random(-15, 15),
      lerp(x1, x2, 0.66), ctrlY + random(-15, 15),
      x2, y2
    );
    endShape();
  }
}

// 6. Embers of consciousness lifting and cooling into stars
function drawSoulMotes() {
  let cx = width * 0.5;
  let baseY = height * 0.74;
  noStroke();

  for (let i = 0; i < 2400; i++) {
    let t = pow(random(), 1.35);
    let y = map(t, 0, 1, baseY + 50, height * 0.03);

    // Follow the same organic S-curve column as the threads
    let n = noise(cx * 0.0022, y * 0.0022);
    let columnCenter = cx + (n - 0.48) * 480 * t;
    let spread = (random() + random() + random() - 1.5) * (240 + t * 650);
    let x = columnCenter + spread;

    let h, s, b;
    if (t < 0.22) {
      h = random(32, 48);
      s = random(15, 45);
      b = 100;
    } else if (t < 0.6) {
      h = random() < 0.6 ? random(38, 52) : random(175, 200);
      s = random(12, 35);
      b = random(85, 100);
    } else {
      h = random(190, 225);
      s = random(15, 45);
      b = random(60, 95);
    }

    let sz = random(0.8, 3.6) * (1 - t * 0.45);
    let alp = random(0.25, 0.85) * (1 - t * 0.35);

    // Occasional soft halo around larger motes
    if (random() < 0.09) {
      fill(h, s, b, alp * 0.14);
      ellipse(x, y, sz * 6, sz * 6);
      fill(h, s * 0.5, 100, alp * 0.3);
      ellipse(x, y, sz * 2.5, sz * 2.5);
    }

    fill(h, s * 0.7, b, alp);
    ellipse(x, y, sz, sz * random(1.0, 1.8));
  }
}

// 7. Distant stillness and tactile canvas grain
function drawStardustAndGrain() {
  noStroke();

  // High, silent stars in the upper void
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(height * 0.7);
    let yn = 1 - (y / (height * 0.7));
    fill(random(195, 230), random(10, 30), random(70, 100), random(0.15, 0.6) * yn);
    let r = random(0.6, 2.0);
    ellipse(x, y, r, r);
  }

  // Fine mineral texture across the entire painting
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = (random() - 0.5) * 14;
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
  ellipseMode(CENTER);
  strokeCap(ROUND);
  noLoop();

  ground();
  air();
  form();
  unbinding();
  sediment();
  glaze();
  grain();
}

function draw() {}

function spine(t) {
  t = constrain(t, 0, 1);
  let y = lerp(1688, 560, t);
  let x = lerp(690, 835, t);
  x += sin(t * 3.1) * 28;
  x += (noise(t * 1.7, 2.2) - 0.5) * 90;
  y += (noise(t * 2.4, 8.0) - 0.5) * 26;
  return { x: x, y: y };
}

function girth(t) {
  t = constrain(t, 0, 1);
  let w = lerp(214, 7, pow(t, 1.12));
  w += sin(t * PI) * 34 * (1 - t);
  w *= 0.92 + noise(t * 5.0) * 0.2;
  return w;
}

function ground() {
  noFill();
  for (let y = 0; y < height; y++) {
    let yn = y / height;
    let hue = lerp(232, 18, pow(yn, 0.85));
    let sat = lerp(28, 42, yn) + (noise(0.2, yn * 4.0) - 0.5) * 8;
    let bri = lerp(5.5, 7.5, yn);
    let veil = exp(-pow((yn - 0.16) / 0.045, 2));
    bri += veil * 11;
    sat = lerp(sat, 12, veil * 0.7);
    hue = lerp(hue, 205, veil * 0.55);
    let low = constrain((yn - 0.72) / 0.28, 0, 1);
    hue = lerp(hue, 16, low * 0.65);
    sat += low * 10;
    bri += low * 2.5;
    stroke(hue, sat, bri, 100);
    strokeWeight(1);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 70; i++) {
    let x = random(width);
    let y = random(height);
    let cold = y / height < 0.45;
    fill(
      cold ? random(220, 250) : random(8, 28),
      cold ? random(10, 30) : random(20, 45),
      random(4, 14),
      random(3, 9)
    );
    ellipse(x, y, random(180, 700), random(80, 380));
  }
}

function air() {
  noStroke();
  for (let i = 0; i < 10; i++) {
    fill(22, 35, 28, 2.2);
    ellipse(760, 1380, 980 - i * 50, 1280 - i * 40);
  }
  for (let i = 0; i < 6; i++) {
    fill(205, 18, 22, 2.4);
    ellipse(980, 340, 1200, 420);
  }
}

function form() {
  noStroke();
  for (let t = 0; t <= 1.001; t += 0.0035) {
    let p = spine(t);
    let rad = girth(t);
    for (let s = 0; s < 16; s++) {
      let ang = random(TWO_PI);
      let dist = pow(random(), 0.55) * rad;
      let x = p.x + cos(ang) * dist * (0.85 + noise(t * 3.0, s * 0.2) * 0.3);
      let y = p.y + sin(ang) * dist * 0.62;
      let edge = constrain(dist / rad, 0, 1);
      let heart = exp(-pow((t - 0.30) / 0.16, 2)) * exp(-pow(edge / 0.45, 2));
      let hue = lerp(12, 34, constrain(1 - edge, 0, 1));
      hue = lerp(hue, 32, t * 0.4) + heart * 6;
      let sat = lerp(48, 22, pow(1 - edge, 0.8)) - heart * 14 - t * 8;
      let bri = lerp(10, 46, pow(1 - edge, 1.35));
      bri += heart * 48;
      bri *= lerp(1, 0.55, pow(t, 1.4));
      let rr = lerp(rad * 0.28, 6, edge) * random(0.7, 1.25);
      fill(hue, constrain(sat, 0, 100), constrain(bri, 0, 100), lerp(4.5, 16, pow(1 - edge, 0.7)));
      ellipse(x, y, rr, rr * random(0.65, 1.35));
    }
  }

  for (let i = 0; i < 900; i++) {
    let t = pow(random(), 0.85);
    let p = spine(t);
    let rad = girth(t);
    let edge = random();
    let ang = random(TWO_PI);
    let x = p.x + cos(ang) * rad * edge * 0.9;
    let y = p.y + sin(ang) * rad * edge * 0.55;
    let heart = exp(-pow((t - 0.30) / 0.18, 2)) * (1 - edge);
    let len = random(12, 46) * (1 - edge * 0.4);
    let rot = (noise(t * 4.0, i * 0.01) - 0.5) * 1.4 + 0.24;
    let bri = constrain(lerp(12, 55, 1 - edge) + heart * 40 - t * 18, 0, 100);
    stroke(
      lerp(14, 36, 1 - edge) + t * 6,
      constrain(40 - heart * 12 - t * 6, 6, 70),
      bri,
      random(5, 14)
    );
    strokeWeight(random(1.2, 5.5));
    push();
    translate(x, y);
    rotate(rot);
    line(-len / 2, 0, len / 2, 0);
    pop();
  }

  for (let t = 0.08; t < 0.82; t += 0.008) {
    let p = spine(t);
    let rad = girth(t);
    let x = p.x - rad * 0.72 + noise(t * 6.0) * 10;
    let y = p.y + (noise(t * 3.0, 4) - 0.5) * 12;
    stroke(200, 15, lerp(40, 18, t), random(6, 16));
    strokeWeight(random(1, 3));
    line(x, y, x + random(-6, 4), y + random(8, 22));
  }

  noStroke();
  let h = spine(0.29);
  for (let i = 0; i < 14; i++) {
    let rr = random(8, 36);
    fill(32, random(18, 40), random(78, 98), random(8, 18));
    ellipse(h.x + random(-10, 10), h.y + random(-16, 12), rr, rr * 1.3);
  }
  fill(40, 12, 100, 22);
  ellipse(h.x, h.y, 10, 14);
}

function unbinding() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    let t = random(0.42, 1);
    let p = spine(t);
    let rad = girth(t);
    fill(235, 22, random(3, 8), random(6, 14));
    ellipse(
      p.x + random(0, rad * 1.15),
      p.y + random(-rad * 0.3, rad * 0.3),
      random(30, 170),
      random(16, 90)
    );
  }

  for (let i = 0; i < 2400; i++) {
    let t = random(0.2, 1.08);
    let tc = constrain(t, 0, 1);
    let p = spine(tc);
    let rad = girth(tc);
    let rise = pow(random(), 0.45);
    let spread = rise * lerp(20, 520, tc);
    let ang = -HALF_PI + random(-0.55, 1.05);
    let x = p.x + cos(ang) * spread + (noise(i * 0.02, t) - 0.5) * 70;
    let y = p.y + sin(ang) * spread * lerp(0.55, 1.15, tc);
    if (random() < 0.35) {
      x = p.x + random(-rad, rad * 1.2);
      y = p.y + random(-rad * 0.4, rad * 0.3) - random(10, 80) * tc;
    }
    let life = constrain(1 - spread / 560, 0, 1) * constrain(1.15 - t, 0, 1);
    noStroke();
    fill(
      lerp(26, 215, constrain(t * 0.75 + rise * 0.25, 0, 1)),
      lerp(36, 10, tc),
      lerp(62, 18, tc),
      life * random(8, 26)
    );
    let rr = random(1.1, 3.8) * (random() < 0.08 ? 2.4 : 1);
    ellipse(x, y, rr, rr);
  }

  for (let i = 0; i < 220; i++) {
    let t = random(0.38, 1);
    let p = spine(t);
    let rad = girth(t);
    let ang = -HALF_PI + random(-0.4, 0.85);
    let len = random(30, 260) * t;
    let x = p.x + random(-rad * 0.6, rad);
    let y = p.y + random(-18, 18);
    stroke(lerp(24, 210, t), lerp(32, 10, t), lerp(50, 22, t), random(3, 11));
    strokeWeight(random(0.4, 1.8));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

function sediment() {
  noStroke();
  for (let i = 0; i < 40; i++) {
    fill(14, random(30, 55), random(4, 10), random(8, 16));
    ellipse(random(420, 1080), random(1580, 1960), random(180, 640), random(30, 90));
  }
  for (let i = 0; i < 18; i++) {
    fill(8, 35, 6, 10);
    ellipse(720 + random(-80, 80), 1760 + random(-30, 40), random(200, 480), random(24, 50));
  }
}

function glaze() {
  noStroke();
  fill(222, 25, 12, 6);
  rect(0, 0, width, height * 0.48);
  fill(16, 35, 12, 7);
  rect(0, height * 0.62, width, height * 0.38);
}

function grain() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (y * width + x);
      let g = (random() - 0.5) * 18;
      let dx = (x - width * 0.46) / (width * 0.5);
      let dy = (y - height * 0.64) / (height * 0.5);
      let vig = dx * dx * 0.65 + dy * dy;
      let dark = vig * 26;
      pixels[i] = constrain(pixels[i] + g - dark, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + g * 0.92 - dark, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + g * 0.8 - dark * 0.8, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255);
  noLoop();
  paint();
}

function draw() {}

function columnX(t) {
  return 708 + Math.sin(t * 1.65) * 18 - t * 30;
}

function columnY(t) {
  return lerp(800, 1435, t);
}

function halfWidth(t) {
  return lerp(16, 158, Math.pow(t, 0.72)) + noise(t * 2.8, 7.1) * 12;
}

function spineRGB(t, edge) {
  let r = lerp(148, 208, t);
  let g = lerp(162, 186, t);
  let b = lerp(174, 158, t);
  r = lerp(r, 62, edge * 0.78);
  g = lerp(g, 70, edge * 0.72);
  b = lerp(b, 86, edge * 0.5);
  return [r, g, b];
}

function wallEdge(y) {
  return 286 + noise(y * 0.0026, 4.0) * 210 + Math.sin(y * 0.0037) * 12;
}

function paint() {
  paintVoid();
  paintWall();
  paintShore();
  paintColumn();
  embedHem();
  paintFolds();
  paintUnmaking();
  paintWater();
  paintReflection();
  paintEmberEcho();
  paintWaterline();
  paintForeground();
  paintAirScratches();
  finishSurface();
}

function paintVoid() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let lift = Math.sin(y * 0.004) * 1.4;
    let r = lerp(8, 20, Math.pow(t, 0.85)) + lift;
    let g = lerp(9, 16, t) + lift * 0.4;
    let b = lerp(16, 18, t);
    stroke(r, g, b);
    strokeWeight(1);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 36; i++) {
    fill(22, 28, 46, random(4, 10));
    ellipse(random(200, 1500), random(40, 980), random(260, 820), random(160, 420));
  }
  fill(28, 34, 54, 12);
  ellipse(980, 430, 900, 520);
  for (let i = 0; i < 18; i++) {
    fill(42, 24, 28, random(3, 7));
    ellipse(random(860, 1560), random(980, 1280), random(180, 520), random(40, 140));
  }
}

function paintWall() {
  for (let y = 140; y < 1390; y++) {
    let edge = wallEdge(y);
    let topFade = constrain((y - 140) / 320, 0, 1);
    let botFade = constrain((1390 - y) / 90, 0, 1);
    let fade = topFade * botFade;
    let n = noise(y * 0.007, 1.3);
    stroke(34 + n * 26, 27 + n * 8, 24, 58 * fade);
    strokeWeight(1.5);
    line(0, y, edge, y);
    if (random() < 0.035) {
      stroke(88, 46, 36, 26 * fade);
      let x1 = random(8, edge * 0.75);
      line(x1, y, x1 + random(16, 84), y + random(-1, 1));
    }
  }
  for (let i = 0; i < 420; i++) {
    let y = random(260, 1340);
    let edge = wallEdge(y);
    let x = random(0, edge - 6);
    stroke(16 + random(28), 14, 14, random(8, 30));
    strokeWeight(random(0.4, 2.1));
    line(x, y, x + random(-2, 2), y + random(18, 90));
  }
  noStroke();
  for (let i = 0; i < 40; i++) {
    let y = random(480, 1280);
    let edge = wallEdge(y);
    fill(12, 10, 12, random(10, 22));
    ellipse(random(20, edge * 0.7), y, random(30, 90), random(8, 20));
  }
}

function paintShore() {
  noStroke();
  for (let i = 0; i < 56; i++) {
    fill(150 + random(30), 62 + random(24), 26, random(4, 11));
    ellipse(random(740, 1560), random(1268, 1355), random(160, 680), random(14, 46));
  }
  fill(206, 146, 72, 9);
  ellipse(1210, 1316, 760, 36);
  fill(120, 48, 32, 8);
  ellipse(860, 1328, 420, 28);

  rectMode(CENTER);
  for (let i = 0; i < 520; i++) {
    let x = random(40, 1550);
    let y = random(1228, 1372);
    let roll = random();
    let r, g, b, a;
    if (roll < 0.2) {
      r = 102; g = 40; b = 32; a = random(20, 46);
    } else if (roll < 0.4) {
      r = 142; g = 96; b = 46; a = random(16, 38);
    } else if (roll < 0.55) {
      r = 58; g = 60; b = 38; a = random(14, 34);
    } else if (roll < 0.72) {
      r = 176; g = 154; b = 126; a = random(8, 22);
    } else if (roll < 0.86) {
      r = 36; g = 26; b = 24; a = random(16, 36);
    } else {
      r = 196; g = 118; b = 48; a = random(10, 24);
    }
    if (x < 430) {
      r *= 0.5;
      g *= 0.55;
      b *= 0.55;
      a *= 0.65;
    }
    push();
    translate(x, y);
    rotate(random(-0.55, 0.22));
    fill(r, g, b, a);
    rect(0, 0, random(14, 128), random(2.5, 10), 1);
    pop();
  }
  rectMode(CORNER);
}

function paintColumn() {
  noStroke();
  for (let t = 0.04; t <= 1; t += 0.012) {
    let c = spineRGB(t, 0);
    let a = lerp(5, 15, t);
    if (t < 0.16) a *= t / 0.16;
    fill(c[0], c[1], c[2], a);
    ellipse(columnX(t), columnY(t), halfWidth(t) * 1.35, 42);
  }

  for (let s = 0; s < 1280; s++) {
    let t = random();
    if (random() < 0.5) t = lerp(0.22, 1, random());
    if (t < 0.24 && random() < ((0.24 - t) / 0.24) * 0.88) continue;
    let hw = halfWidth(t);
    let nx = random(-1, 1);
    nx = Math.sign(nx) * Math.pow(Math.abs(nx), 0.52);
    let x = columnX(t) + nx * hw;
    let y = columnY(t);
    let edge = Math.abs(nx);
    let rgb = spineRGB(t, edge);
    if (nx > 0.12 && t > 0.48) {
      rgb[0] = Math.min(255, rgb[0] + 26);
      rgb[1] = Math.min(255, rgb[1] + 8);
      rgb[2] = Math.max(0, rgb[2] - 10);
    }
    let a = lerp(32, 8, edge);
    if (t < 0.2) a *= t / 0.2;
    a *= random(0.5, 1);
    stroke(rgb[0], rgb[1], rgb[2], a);
    strokeWeight(random(0.5, 1.7));
    let len = random(10, 46) * lerp(0.45, 1, t);
    line(x + random(-1, 1), y, x + random(-1.4, 1.4), y + len);
  }

  for (let s = 0; s < 200; s++) {
    let t = random(0.16, 0.96);
    let x = columnX(t) - halfWidth(t) + random(-8, 6);
    let y = columnY(t);
    stroke(10, 9, 12, random(8, 28));
    strokeWeight(random(0.8, 2.3));
    line(x, y, x + random(-2, 1), y + random(14, 36));
  }
}

function embedHem() {
  for (let i = 0; i < 140; i++) {
    let t = random(0.78, 1);
    let x = columnX(t) + random(-halfWidth(t), halfWidth(t) * 0.8);
    let y = columnY(t) + random(-6, 8);
    stroke(146, 84, 42, random(8, 22));
    strokeWeight(random(0.8, 2.4));
    line(x, y, x + random(-24, 32), y + random(-2, 2));
  }
}

function paintFolds() {
  for (let f = 0; f < 6; f++) {
    let offset = lerp(-0.42, 0.46, f / 5);
    let phase = f * 1.8;
    for (let t = 0.2; t < 0.94; t += 0.007) {
      if (random() < 0.28) continue;
      let x = columnX(t) + offset * halfWidth(t) + Math.sin(t * 16 + phase) * 3.5;
      let y = columnY(t);
      stroke(32, 28, 34, random(5, 14));
      strokeWeight(random(0.4, 1.2));
      line(x, y, x + random(-1, 1), y + random(7, 15));
    }
  }
}

function paintUnmaking() {
  for (let i = 0; i < 2200; i++) {
    let u = Math.pow(random(), 1.55);
    let n = noise(i * 0.035, u * 1.4);
    if (n < 0.36 && u > 0.12) continue;
    let y = lerp(900, 48, u);
    let drift = random() < 0.78 ? random(0, 1) : random(-0.55, 0.05);
    let x = columnX(0.08) + drift * lerp(12, 300, u);
    x += (noise(u * 3.1, i * 0.01) - 0.5) * lerp(16, 90, u);
    let cool = constrain(u * 1.05, 0, 1);
    let r = lerp(206, 132, cool);
    let g = lerp(190, 146, cool);
    let b = lerp(170, 162, cool);
    let a = lerp(30, 0, Math.pow(u, 0.8)) * map(n, 0.36, 1, 0.35, 1, true);
    a *= random(0.45, 1);
    if (a < 1.2) continue;
    if (random() < 0.62) {
      stroke(r, g, b, a);
      strokeWeight(random(0.35, 1.15));
      let rise = random(3, 16) * (1 - u * 0.7);
      line(x, y, x + random(-2, 5), y - rise);
    } else {
      noStroke();
      fill(r, g, b, a);
      ellipse(x, y, random(0.8, 2.8), random(1.2, 4.2));
    }
  }
  noStroke();
  for (let i = 0; i < 16; i++) {
    fill(150, 156, 166, random(3, 7));
    ellipse(random(520, 980), random(180, 640), random(80, 180), random(28, 70));
  }
}

function paintWater() {
  for (let y = 1336; y < height; y++) {
    let t = (y - 1336) / (height - 1336);
    let n = noise(y * 0.012, 2.4);
    let r = lerp(18, 5, t) + n * 3;
    let g = lerp(18, 7, t) + n * 2;
    let b = lerp(16, 11, t);
    stroke(r, g, b, 78);
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (let i = 0; i < 640; i++) {
    let y = random(1352, 1988);
    let x = random(width);
    let g = noise(x * 0.0022, y * 0.008);
    stroke(16 + g * 18, 20 + g * 8, 22, random(5, 14));
    strokeWeight(1);
    line(x, y, x + random(24, 200), y + random(-0.4, 0.4));
  }
}

function paintReflection() {
  for (let i = 0; i < 980; i++) {
    let wy = random(1355, 1745);
    let dist = (wy - 1355) / (1745 - 1355);
    if (noise(wy * 0.018, i * 0.02) < 0.34) continue;
    let t = lerp(0.98, 0.5, dist);
    if (t < 0.56 && random() < 0.55) continue;
    let hw = halfWidth(t) * lerp(0.82, 0.36, dist);
    let ripple = Math.sin(wy * 0.19 + dist * 5) * (2 + dist * 11);
    ripple += (noise(wy * 0.028, 9.2) - 0.5) * 24;
    let nx = random(-1, 1);
    let x = columnX(t) + ripple + nx * hw;
    let rgb = spineRGB(t, Math.abs(nx));
    let a = lerp(18, 3, dist) * random(0.35, 1);
    stroke(rgb[0] * 0.62, rgb[1] * 0.68, rgb[2] * 0.8, a);
    strokeWeight(random(0.5, 1.45));
    line(x, wy, x + random(6, 24) * (1 - dist * 0.4), wy + random(-0.7, 0.7));
  }
}

function paintEmberEcho() {
  for (let i = 0; i < 280; i++) {
    let wy = random(1358, 1680);
    let dist = (wy - 1358) / 340;
    if (random() < dist * 0.55) continue;
    let x = random(900, 1520) + Math.sin(wy * 0.12) * 8;
    stroke(170, 96, 42, lerp(16, 2, dist) * random(0.4, 1));
    strokeWeight(random(0.6, 1.6));
    line(x, wy, x + random(10, 48), wy + random(-0.5, 0.5));
  }
}

function paintWaterline() {
  for (let x = 60; x < 1540; ) {
    let flicker = noise(x * 0.012, 8.5);
    let gap = random(3, 16);
    if (flicker > 0.32) {
      stroke(214, 186, 146, 16 + flicker * 36);
      strokeWeight(random(0.4, 1.5));
      let len = random(5, 26) * flicker;
      let y = 1344 + Math.sin(x * 0.021) * 1.6;
      line(x, y, x + len, y + random(-0.8, 0.8));
    }
    x += gap;
  }
}

function paintForeground() {
  for (let y = 1765; y < height; y++) {
    let a = map(y, 1765, height, 18, 100);
    stroke(3, 4, 7, a);
    strokeWeight(1);
    line(0, y, width, y);
  }
  noStroke();
  fill(5, 5, 7, 36);
  ellipse(260, 1910, 780, 240);
  ellipse(1180, 1955, 900, 220);
  fill(4, 4, 6, 28);
  ellipse(780, 1980, 1100, 160);
}

function paintAirScratches() {
  for (let i = 0; i < 48; i++) {
    let x = random(40, 520);
    let y = random(30, 280);
    stroke(36, 40, 52, random(3, 9));
    strokeWeight(random(0.4, 1));
    line(x, y, x + random(-10, 8), y + random(30, 120));
  }
}

function finishSurface() {
  loadPixels();
  const d = pixelDensity();
  const w = width * d;
  const h = height * d;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const idx = 4 * (y * w + x);
      const nx = x / w - 0.43;
      const ny = y / h - 0.46;
      let v = nx * nx * 1.28 + ny * ny * 1.02;
      let darken = 0;
      if (v > 0.07) darken = (v - 0.07) * 230;
      if (darken > 96) darken = 96;
      const grain = (random() - 0.5) * 13;
      const warm = y / h;
      pixels[idx] = clamp8(pixels[idx] - darken + grain + warm * 1.5);
      pixels[idx + 1] = clamp8(pixels[idx + 1] - darken + grain);
      pixels[idx + 2] = clamp8(pixels[idx + 2] - darken * 0.9 + grain - warm);
    }
  }
  updatePixels();
}

function clamp8(v) {
  return v < 0 ? 0 : v > 255 ? 255 : v;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noiseDetail(3, 0.5);
  noLoop();
}

function draw() {
  paintAtmosphere();
  paintMoon();
  paintOccult();
  paintThreads();
  paintGround();
  paintDune();
  paintAsh();
  paintPool();
  paintWarmth();
  paintSilenceMotes();
  paintGrain();
  paintVignette();
  paintLimb();
  paintLastHeat();
}

function paintAtmosphere() {
  noFill();
  for (let y = 0; y < 2000; y++) {
    let t = y / 2000;
    let r, g, b;
    if (t < 0.48) {
      let u = t / 0.48;
      r = lerp(10, 20, u);
      g = lerp(9, 16, u);
      b = lerp(12, 18, u);
    } else if (t < 0.68) {
      let u = (t - 0.48) / 0.2;
      r = lerp(20, 42, u * u);
      g = lerp(16, 28, u);
      b = lerp(18, 24, u);
    } else {
      let u = (t - 0.68) / 0.32;
      r = lerp(42, 12, u);
      g = lerp(28, 10, u);
      b = lerp(24, 11, u);
    }
    let n = noise(y * 0.0035, 0.4);
    stroke(r + n * 7, g + n * 5, b + n * 3, 255);
    line(0, y, 1600, y);
  }

  noStroke();
  for (let i = 0; i < 90; i++) {
    let x = random(1600);
    let y = random(1400);
    let w = random(180, 640);
    let h = random(30, 160);
    let a = random(4, 12);
    fill(18 + random(10), 16 + random(8), 18 + random(6), a);
    ellipse(x, y, w, h);
  }

  strokeCap(ROUND);
  noFill();
  for (let i = 0; i < 36; i++) {
    let y = random(40, 900);
