    let n = noise(cos(a) * 1.35 + seed, sin(a) * 1.35 + seed * 0.7);
    let rr = r * (0.965 + 0.05 * n);
    vertex(cx + cos(a) * rr, cy + sin(a) * rr);
  }
  endShape(CLOSE);
}

