}

function skyRGB(y) {
  let t = constrain(y / 2000, 0, 1);
  let r, g, b;
  if (t < 0.58) {
    let u = pow(t / 0.58, 0.9);
    r = lerp(5, 15, u);
    g = lerp(6, 13, u);
    b = lerp(11, 22, u);
  } else if (t < 0.78) {
    let u = (t - 0.58) / 0.2;
    r = lerp(15, 34, u);
    g = lerp(13, 22, u);
    b = lerp(22, 24, u);
  } else {
    let u = (t - 0.78) / 0.22;
    r = lerp(34, 16, u);
    g = lerp(22, 11, u);
    b = lerp(24, 12, u);
  }
  return [r, g, b];
}

function groundRGB(y) {
  let t = constrain((y - 1500) / 500, 0, 1);
  return [lerp(32, 8, t), lerp(20, 7, t), lerp(18, 7, t)];
}

function glazeSky() {
  background(5, 6, 10);
  for (let pass = 0; pass < 5; pass++) {
    for (let y = 0; y < height; y += 5) {
      let c = skyRGB(y);
      let n = noise(y * 0.007, pass * 0.6);
      let rr = c[0] + (n - 0.5) * 9;
      let gg = c[1] + (n - 0.5) * 7;
      let bb = c[2] + (noise(y * 0.015, pass * 1.3) - 0.5) * 11;
      stroke(rr, gg, bb, 15 + pass * 3);
      let x = -40;
      while (x < width) {
        let len = 100 + noise(x * 0.0035, y * 0.008, pass) * 280;
        let yy = y + (noise(x * 0.0025, pass * 1.4) - 0.5) * 7;
        strokeWeight(3 + noise(x * 0.008, y * 0.01, pass) * 6);
        line(x, yy, x + len, yy + (noise(y * 0.04, x * 0.002, pass) - 0.5) * 4);
        x += len * 0.64;
      }
    }
  }
}

