function paintAsh(x, y, fade) {
  if (fade < 0.05) return;
  let roll = random();
  let r, g, b;
  if (roll < 0.16) {
    r = 128;
    g = 138;
    b = 148;
  } else if (roll < 0.84) {
    r = 188;
    g = 170;
    b = 148;
  } else {
    r = 108;
    g = 94;
    b = 82;
  }
  if (x < CX) {
    r += 12;
    g += 8;
    b += 3;
  } else if (x > CX + 90) {
    r -= 8;
    b += 10;
  }
  let a = random(26, 96) * fade;
  let ang = y > HY + 500 ? random(HALF_PI - 0.55, HALF_PI + 0.55) : random(TWO_PI);
  let len = random(1.4, 5.8);
  stroke(r, g, b, a);
  strokeWeight(random(0.45, 1.55));
  line(x, y, x + cos(ang) * len, y + sin(ang) * len * 0.62);
  if (random() < 0.3) {
    noStroke();
    fill(r, g, b, a * 0.45);
    ellipse(x, y, random(0.8, 2.2), random(0.7, 1.8));
  }
}

function qbez(a, b, c, t) {
  let u = 1 - t;
  return u * u * a + 2 * u * t * b + t * t * c;
}

function qbezD(a, b, c, t) {
  return 2 * (1 - t) * (b - a) + 2 * t * (c - b);
}

function scatterAlong(x1, y1, mx, my, x2, y2, n, rad0, rad1, dissolveStart, spray) {
  for (let i = 0; i <= n; i++) {
    let t = i / n;
    let x = qbez(x1, mx, x2, t);
    let y = qbez(y1, my, y2, t);
    let dx = qbezD(x1, mx, x2, t);
    let dy = qbezD(y1, my, y2, t);
    let len = mag(dx, dy);
    if (len < 0.001) len = 1;
    let px = -dy / len;
    let py = dx / len;
    let rad = lerp(rad0, rad1, t);
    let keep = 1;
    if (t > dissolveStart) {
      keep = lerp(1, 0.04, (t - dissolveStart) / (1 - dissolveStart));
      let c = skyRGB(y);
      noStroke();
      fill(c[0] + 3, c[1] + 3, c[2] + 4, 36 * (1 - keep));
      ellipse(x, y, rad * 2.4, rad * 1.7);
    }
    let breathe = (noise(x * 0.012, y * 0.012) - 0.5) * 7;
    for (let k = 0; k < 6; k++) {
      if (random() > keep * 0.96) continue;
      let side = random() < 0.5 ? -1 : 1;
      let off = rad * lerp(0.5, 1.12, random()) * side;
      paintAsh(
        x + px * off + breathe + randomGaussian() * 1.5,
        y + py * off + randomGaussian() * 1.5,
        keep
      );
    }
    if (random() < keep * 0.35) {
      let side = random() < 0.5 ? -1 : 1;
      paintAsh(x + px * rad * 1.65 * side, y + py * rad * 1.65 * side, keep * 0.4);
    }
  }
  if (spray) {
    for (let i = 0; i < 130; i++) {
      let ang = random(-2.65, -0.15);
      let d = random(4, 155) * random();
      paintAsh(x2 + cos(ang) * d, y2 + sin(ang) * d * 0.85, (1 - d / 155) * 0.6);
    }
  }
}

function headAndShoulders() {
  for (let pass = 0; pass < 3; pass++) {
    for (let a = 0; a < TWO_PI; a += 0.04) {
      let wob = noise(cos(a) * 1.7 + 3, sin(a) * 1.7 + pass) * 8;
      let rx = 56 + wob;
      let ry = 74 + wob * 0.55;
      let x = CX + cos(a) * rx;
      let y = HY + sin(a) * ry;
      let crown = sin(a) < -0.12;
      if (crown && random() < 0.6) {
        let c = skyRGB(y - 12);
        noStroke();
        fill(c[0] + 2, c[1] + 2, c[2] + 3, 34);
        ellipse(x, y - 6, 18, 12);
        let lift = random(12, 260);
        paintAsh(
          x + random(-lift * 0.12, lift * 0.42),
          y - lift,
          constrain(1 - lift / 270, 0, 1) * 0.75
        );
        continue;
      }
      paintAsh(x + randomGaussian() * 1.3, y + randomGaussian() * 1.3, 1);
    }
  }
  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    paintAsh(CX - 15 + t * 4, HY + 62 + t * 58, 0.85);
    paintAsh(CX + 16 + t * 6, HY + 62 + t * 56, 0.85);
  }
  for (let a = 0.12; a < PI - 0.12; a += 0.028) {
    let x = CX + 8 + cos(a) * 146;
    let y = HY + 176 - sin(a) * 50;
    for (let k = 0; k < 4; k++) {
      paintAsh(x + randomGaussian() * 2, y + randomGaussian() * 1.6, 1);
    }
    if (random() < 0.45) {
      stroke(202, 186, 164, random(18, 48));
      strokeWeight(random(0.8, 1.8));
      line(x - 4, y, x + random(4, 12), y + random(-1.5, 1.5));
    }
  }
}

function afterthought() {
  for (let i = 0; i < 240; i++) {
    let y = random(320, HY - 30);
    let reach = constrain((HY - 50 - y) / (HY - 50 - 320), 0, 1);
    if (random() > pow(1 - reach, 1.4)) continue;
    let x = CX + randomGaussian() * (16 + reach * 78);
    paintAsh(x, y, (1 - reach) * 0.5);
  }
