function skyColor(y) {
  const t = constrain(y / 1280, 0, 1);
  let r, g, b;
  if (t < 0.42) {
    const u = t / 0.42;
    r = lerp(32, 118, u * u);
    g = lerp(40, 116, u);
    b = lerp(54, 126, u);
  } else if (t < 0.76) {
    const u = (t - 0.42) / 0.34;
    r = lerp(118, 214, u);
    g = lerp(116, 170, u);
    b = lerp(126, 146, u);
  } else {
    const u = (t - 0.76) / 0.24;
    r = lerp(214, 230, u);
    g = lerp(170, 188, u);
    b = lerp(146, 150, u);
  }
  const rose = Math.exp(-Math.pow((y - 1165) / 150, 2));
  r += rose * 28;
  g += rose * 6;
  b -= rose * 12;
  return [r, g, b];
}

