function limb(x, y, angle, len, depth, kind) {
  const maxDepth = kind === "tree" ? 9 : 7;
  if (len < 6 || depth > maxDepth) {
    tip(x, y, angle, kind);
    return;
  }

  const segs = Math.max(4, Math.floor(len / 9));
  let px = x;
  let py = y;
  let lastA = angle;
  const bend = (noise(x * 0.007 + depth, y * 0.007, kind === "tree" ? 1.3 : 9.3) - 0.5) * 0.5;

  for (let i = 0; i < segs; i++) {
    const t = i / segs;
    const a = angle + bend * t;
    lastA = a;
    const segLen = len / segs;
    const nx = px + Math.cos(a) * segLen;
    const ny = py + Math.sin(a) * segLen;
    const base = kind === "tree" ? 58 : 20;
    const thick = Math.max(0.45, base * Math.pow(0.64, depth) * (1 - t * 0.32));
    const n = noise(px * 0.012, py * 0.012);
    const j = (n - 0.5) * Math.min(2.2, thick * 0.1);
    const jx = -Math.sin(a) * j;
    const jy = Math.cos(a) * j;

    if (kind === "tree") stroke(24 + n * 26, 14 + n * 10, 8, 235);
    else {
      const fade = constrain(map(py, 1300, 1960, 205, 16), 8, 220);
      stroke(64 + n * 55, 34 + n * 18, 20, fade);
    }
    strokeWeight(thick);
    line(px + jx, py + jy, nx + jx, ny + jy);

    if (kind === "tree" && thick > 5) {
      stroke(116, 74, 46, 30);
      strokeWeight(Math.max(0.4, thick * 0.16));
      line(px - thick * 0.2, py, nx - thick * 0.2, ny);
      stroke(8, 5, 4, 36);
      strokeWeight(Math.max(0.4, thick * 0.22));
      line(px + thick * 0.2, py, nx + thick * 0.2, ny);
    }

    px = nx;
    py = ny;
  }

  if (kind === "tree" && depth > 3 && random() < 0.1) return;

  if (kind === "tree" && depth === 0) {
    const spreads = [-0.74, 0.0, 0.66];
    const lens = [198, 276, 186];
    for (let f = 0; f < 3; f++) {
      limb(px, py, lastA + spreads[f] + random(-0.05, 0.05), lens[f], 1, kind);
    }
    return;
  }

  let forks;
  if (kind === "root") {
    forks = depth < 2 ? 2 : random() < 0.4 ? 1 : 0;
    if (py > 1880) forks = 0;
  } else if (depth < 4) {
    forks = random() < 0.84 ? 2 : 1;
  } else if (depth < 7) {
    forks = random() < 0.52 ? 2 : 1;
  } else {
    forks = random() < 0.26 ? 1 : 0;
  }

  for (let f = 0; f < forks; f++) {
    let spread = random(0.15, 0.6);
    if (random() < 0.5) spread *= -1;
    if (forks === 1) spread *= 0.28;
    let na = lastA + spread;
    if (kind === "tree") {
      const lim = depth < 6 ? 0.2 : 0.58;
      if (na > -lim) na = -lim - random(0.02);
      if (na < -Math.PI + lim) na = -Math.PI + lim + random(0.02);
    } else {
      if (na < 0.22) na = 0.22 + random(0.04);
      if (na > Math.PI - 0.22) na = Math.PI - 0.22 - random(0.04);
    }
    limb(px, py, na, len * random(0.64, 0.78), depth + 1, kind);
  }
}

function tip(x, y, angle, kind) {
  if (kind === "tree" && random() < 0.2 && y < 1260) {
    push();
    translate(x, y);
    rotate(angle + random(-0.6, 0.6));
    noStroke();
    fill(random(150, 182), random(78, 104), random(32, 52), random(140, 210));
    ellipse(0, 0, random(5, 9), random(2.2, 3.8));
    pop();
  }
  if (kind === "root" && random() < 0.28 && y < 1940) {
    noStroke();
    fill(170 + random(50), 78 + random(40), 32, random(18, 50));
    ellipse(x, y, random(1.5, 5.5), random(1.5, 4));
  }
}

function drawVignette() {
  noFill();
