function drawGround() {
  noStroke();
  fill(10, 9, 10, 240);
  beginShape();
  vertex(0, height);
  curveVertex(0, height - 140);
  curveVertex(250, height - 170);
  curveVertex(550, height - 95);
  curveVertex(900, height - 190);
  curveVertex(1300, height - 130);
  curveVertex(1600, height - 170);
  vertex(width, height);
  endShape(CLOSE);

  strokeWeight(1.1);
  for (let i = 0; i < 160; i++) {
    let x = random(0, width);
