function drawHead() {
  push();
  translate(800, 830);

  noStroke();
  fill(34, 30, 24, 220);
  ellipse(0, 0, 32, 26);

  noFill();
  strokeWeight(0.7);
  let N = 300;
  for (let i = 0; i < N; i++) {
    let baseAngle = map(i, 0, N, 0, TWO_PI);
    let angle = baseAngle + (noise(i * 0.04, 1.7) - 0.5) * 0.4;
    let side = cos(baseAngle);

    if (side > 0.25 && random() < 0.35) continue;

    let r;
    if (side > 0.2) {
      r = 145 + (noise(i * 0.06, 2.2) - 0.5) * 30 + random(-15, 25);
    } else {
      r = 210 + (noise(i * 0.06, 2.2) - 0.5) * 40 + random(-20, 45);
    }

    let x = cos(angle) * r;
    let y = sin(angle) * r * 0.92;

    stroke(200, 195, 178, random(90, 180));
    bezier(
      0, 0,
      cos(angle) * r * 0.25 + random(-8, 8),
      sin(angle) * r * 0.25 + random(-8, 8),
      x * 0.7 + random(-6, 6),
      y * 0.7 + random(-6, 6),
      x, y
    );

    if (random() < 0.4) {
      noStroke();
      fill(85, 78, 58, 160);
      ellipse(x, y, 3.5, 2.5);
      noFill();
    }

    drawFluff(x, y, angle, r * 0.33 + random(4, 18), random(100, 190));
  }
  pop();
}

function drawFluff(x, y, baseAngle, len, alpha) {
  stroke(238, 233, 220, alpha);
  let branches = 8;
  for (let j = 0; j < branches; j++) {
    let a = baseAngle + random(-0.85, 0.85);
    let l = len * random(0.6, 1.5);
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }
}

function drawFloatingSeeds() {
  let count = 150;
  for (let i = 0; i < count; i++) {
    let angle = -PI / 2 + random(-0.5, 1.2);
    let dist = random(230, 1250);
    let sx = 800 + cos(angle) * dist + random(-80, 80);
    let sy = 830 + sin(angle) * dist + random(-50, 50);

    if (sx < 80 || sx > width - 80 || sy < 80 || sy > height - 200) continue;

    if (dist < 520 && random() < 0.2) {
      stroke(170, 165, 150, 18);
      strokeWeight(1);
      line(800 + cos(angle) * 230, 830 + sin(angle) * 230, sx, sy);
    }

    let size = random(3, 9);
    let alpha = map(dist, 230, 1250, 220, 30);
    drawFloatingSeed(sx, sy, size, alpha);
  }
}

function drawFloatingSeed(sx, sy, size, alpha) {
  noStroke();
  fill(72, 64, 48, alpha);
  ellipse(sx, sy, size * 0.35, size * 0.5);

  let fx = sx;
  let fy = sy - size * 0.35;
  noFill();
  stroke(238, 232, 218, alpha);
  strokeWeight(0.8);
  let branches = 9;
  for (let j = 0; j < branches; j++) {
    let a = -PI / 2 + random(-0.85, 0.85);
    let l = size * random(1.8, 4.2);
    line(fx, fy, fx + cos(a) * l, fy + sin(a) * l);
  }
}

function drawForegroundDust() {
  noStroke();
  for (let i = 0; i < 220; i++) {
    let x = random(0, width);
    let y = random(height - 300, height - 40);
    let alpha = random(5, 40);
    fill(180, 170, 150, alpha);
    ellipse(x, y, random(1, 3), random(1, 3));
  }
  for (let i = 0; i < 60; i++) {
    let x = random(0, width);
    let y = random(0, height);
    let alpha = random(10, 50);
    fill(0, 0, 0, alpha);
    ellipse(x, y, random(2, 7));
  }
}

// p5.js 1.11 — 1600 × 2000 still image
function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();
}

function draw() {
  // Deep gradient: cold near-black above, faint warm earth below
  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    fill(lerp(230, 35, t), lerp(20, 25, t), lerp(3, 9, t), 1);
    rect(0, y, width, 1);
  }

  // Soft clouds of living color near the bottom
  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(height * 0.62, height * 1.05);
    let rad = random(100, 520);
    let hue = random(360);
    fill(hue, 55, 70, random(0.015, 0.055));
    ellipse(x, y, rad);
  }

  // The black aperture: an unlit threshold
  let cx = width / 2;
  let cy = height * 0.22;
  for (let i = 0; i < 70; i++) {
    let r = 520 - i * 7;
    let a = map(i, 0, 70, 0.013, 0.85);
    fill(0, 0, 0, a);
    ellipse(cx, cy, r, r * 1.35);
  }

  // Unraveling threads
  strokeCap(ROUND);
  let N = 1000;
  for (let idx = 0; idx < N; idx++) {
    let startX = random(140, 1460);
    let startY = height + random(20, 700);
    // Most threads stay low; only a few climb into the dark
    let endY = height * (1 - pow(random(1), 3.4));
    let hue = random(360);
    let segments = int(random(28, 58));
    let pullStrength = constrain(map(endY, height, 0, 0, 1), 0, 1);

    let xPrev = startX;
    let yPrev = startY;

    for (let s = 1; s <= segments; s++) {
      let t = s / segments;
      let y = lerp(startY, endY, t);
      let baseX = lerp(startX, cx, t * pullStrength * 0.92);

      let n = noise(idx * 0.008, t * 2.6);
      let wiggle = (n - 0.5) * 210 * (1 - t * 0.8);
      let x = baseX + wiggle;

      let alpha = 1 - pow(t, 2.4);
      let sat = lerp(85, 5, t);
      let bri = lerp(88, 14, t);
      stroke(hue, sat, bri, alpha);
      strokeWeight(lerp(2.8, 0.35, t));
      line(xPrev, yPrev, x, y);

      xPrev = x;
      yPrev = y;
    }
  }

  // Residual dust orbiting the threshold
  for (let i = 0; i < 700; i++) {
    let angle = random(TWO_PI);
    let r = random(230, 450);
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.28;
    fill(40, 10, 80, random(0.02, 0.18));
    noStroke();
    ellipse(x, y, random(1, 5));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  background(10, 10, 12);
  noStroke();

  const numParticles = 15000;
  const particles = [];
  const center = createVector(800, 1000);

  for (let i = 0; i < numParticles; i++) {
    let base = randomPointInFigure();
    let dist = base.dist(center);
    let noiseVal = noise(base.x * 0.005, base.y * 0.005);
    let dispMag = (dist * dist) * 0.0008 + noiseVal * 150;
    let dir = p5.Vector.sub(base, center).heading();
    let angle = dir + random(-0.6, 0.6);
    let dispVec = p5.Vector.fromAngle(angle).mult(dispMag);
    let pos = p5.Vector.add(base, dispVec);
    particles.push({
      x: pos.x,
      y: pos.y,
      dispMag: dispMag
    });
  }

  for (let p of particles) {
    let t = constrain(p.dispMag / 500, 0, 1);
    let r = lerp(220, 15, t);
    let g = lerp(120, 15, t);
    let b = lerp(60, 25, t);
    let alpha = 255 * pow(1 - t, 2);
    let size = lerp(4, 1, t);
    fill(r, g, b, alpha);
    ellipse(p.x, p.y, size, size);
  }

  noLoop();
}

function draw() {
  // drawing is complete in setup()
}

function randomPointInFigure() {
  let r = random(100);
  let x, y;

  if (r < 15) { // head
    let angle = random(TWO_PI);
    let rad = random(120);
    x = 800 + rad * cos(angle);
    y = 700 + rad * sin(angle);
  } else if (r < 45) { // torso
    x = random(680, 920);
    y = random(820, 1200);
  } else if (r < 55) { // left arm
    let t = random(1);
    let baseX = 680 + t * (550 - 680);
    let baseY = 850 + t * (1050 - 850);
    let dx = 550 - 680;
    let dy = 1050 - 850;
    let perpX = -dy;
    let perpY = dx;
    let len = sqrt(perpX * perpX + perpY * perpY);
    let offset = random(-20, 20);
    x = baseX + (perpX / len) * offset;
    y = baseY + (perpY / len) * offset;
  } else if (r < 65) { // right arm
    let t = random(1);
    let baseX = 920 + t * (1050 - 920);
    let baseY = 850 + t * (1050 - 850);
    let dx = 1050 - 920;
    let dy = 1050 - 850;
    let perpX = -dy;
    let perpY = dx;
    let len = sqrt(perpX * perpX + perpY * perpY);
    let offset = random(-20, 20);
    x = baseX + (perpX / len) * offset;
    y = baseY + (perpY / len) * offset;
  } else if (r < 82.5) { // left leg
    let t = random(1);
    let baseX = 750 + t * (700 - 750);
    let baseY = 1200 + t * (1600 - 1200);
    let dx = 700 - 750;
    let dy = 1600 - 1200;
    let perpX = -dy;
    let perpY = dx;
    let len = sqrt(perpX * perpX + perpY * perpY);
    let offset = random(-20, 20);
    x = baseX + (perpX / len) * offset;
    y = baseY + (perpY / len) * offset;
  } else { // right leg
    let t = random(1);
    let baseX = 850 + t * (900 - 850);
    let baseY = 1200 + t * (1600 - 1200);
    let dx = 900 - 850;
    let dy = 1600 - 1200;
    let perpX = -dy;
    let perpY = dx;
    let len = sqrt(perpX * perpX + perpY * perpY);
    let offset = random(-20, 20);
    x = baseX + (perpX / len) * offset;
    y = baseY + (perpY / len) * offset;
  }

  return createVector(x, y);
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
