}

function draw() {
  const cx = 800;
  const cy = 980;

  // Background gradient
  let ctx = drawingContext;
  ctx.save();
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, '#07070e');
  bg.addColorStop(0.45, '#0f0f18');
  bg.addColorStop(0.75, '#1c1a1e');
  bg.addColorStop(1, '#2a211d');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // Soft color patches
  noStroke();
  for (let i = 0; i < 130; i++) {
    let x = random(width);
    let y = random(height);
    let rad = random(120, 520);
    let rnd = random();
    if (rnd < 0.34) {
      fill(20, 20, 40, 20);
    } else if (rnd < 0.67) {
      fill(45, 38, 30, 16);
    } else {
      fill(12, 12, 28, 28);
    }
    ellipse(x, y, rad, rad);
  }

  // Smoky flow field
  noFill();
  for (let i = 0; i < 4200; i++) {
    let x = random(width);
    let y = random(height);
    if (dist(x, y, cx, cy) < 290) continue;
    let angle = noise(x * 0.003, y * 0.003, 2) * TWO_PI * 2;
    let len = random(3, 24);
    let alpha = random(5, 30);
    stroke(170, 175, 190, alpha);
    strokeWeight(random(0.4, 1.2));
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }

  // Swirling rings around the threshold
  noFill();
  for (let r = 260; r < 1350; r += 2.5) {
    let t = map(r, 260, 1350, 0, 1);
    let alpha = map(r, 260, 1350, 48, 7);

    if (t < 0.18) {
      stroke(202, 196, 186, alpha * 2.1);
    } else if (t < 0.42) {
      stroke(150, 150, 165, alpha * 1.9);
    } else if (t < 0.7) {
      stroke(110, 105, 122, alpha * 1.5);
    } else {
      stroke(62, 56, 68, alpha);
    }

    strokeWeight(map(r, 260, 1350, 2.1, 0.4));
    beginShape();
    for (let a = 0; a <= TWO_PI + 0.05; a += 0.04) {
      let xc = cos(a);
      let yc = sin(a);
      let n1 = noise(xc * 1.4 + 3, yc * 1.4 + 3, r * 0.0035);
      let n2 = noise(xc * 1.1 + 8, yc * 1.1 + 8, r * 0.0025 + 99);
      let sw = sin(a * 10 + r * 0.015) * (1 - t) * 14;
      let rr = r + (n1 - 0.5) * 140 * (1 - t * 0.55) + (n2 - 0.5) * 110 * t + sw;
      vertex(cx + rr * xc, cy + rr * yc);
    }
    endShape(CLOSE);
  }

  // Pale halo around the door
  noFill();
  for (let i = 0; i < 10; i++) {
    let d = i * 6;
    stroke(202, 196, 186, map(i, 0, 9, 55, 0));
    strokeWeight(1.6);
    beginShape();
    vertex(cx - (160 + d), cy + (420 + d));
    bezierVertex(cx - (190 + d), cy + (100 + d), cx - (230 + d), cy - (250 + d), cx, cy - (350 + d));
    bezierVertex(cx + (230 + d), cy - (250 + d), cx + (190 + d), cy + (100 + d), cx + (160 + d), cy + (420 + d));
    endShape();
  }

  // Central black doorway
  noStroke();
  fill(0, 0, 0);
  beginShape();
  vertex(cx - 160, cy + 420);
  bezierVertex(cx - 190, cy + 100, cx - 230, cy - 250, cx, cy - 350);
  bezierVertex(cx + 230, cy - 250, cx + 190, cy + 100, cx + 160, cy + 420);
  endShape(CLOSE);

  // Subtle texture inside the doorway
  noStroke();
  for (let i = 0; i < 700; i++) {
    let a = random(TWO_PI);
    let r = sqrt(random()) * 200;
    let x = cx + r * cos(a);
    let y = cy + r * sin(a) * 1.3;
    let c = random(0, 9);
    stroke(c, c, c, random(12, 45));
    strokeWeight(random(0.3, 1.3));
    point(x, y);
  }

  // Foreground dark earth
  noStroke();
  fill(5, 4, 7, 230);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 5) {
    let y = height * 0.72 + 260 * noise(x * 0.005, 11) + 90 * noise(x * 0.015, 22) - 20;
    vertex(x, y);
  }
  vertex(width, height);
  endShape(CLOSE);

  // Grass strokes
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let baseY = height * 0.74 + 250 * noise(x * 0.005, 11) + 80 * noise(x * 0.015, 22) - 20;
    if (baseY < height * 0.76) continue;
    let h = random(10, 55);
    let sway = sin(x * 0.01) * 8;
    stroke(8, 6, 12, 190);
    strokeWeight(random(1, 2.5));
    line(x, baseY, x + sway, baseY - h);
  }

  // Embers and ash
  blendMode(ADD);
  for (let i = 0; i < 1600; i++) {
    let a = random(TWO_PI);
    let r = 260 + sqrt(random()) * 1200;
    let x = cx + r * cos(a);
    let y = cy + r * sin(a) * 1.1;
    let ang = atan2(y - cy, x - cx) + map(r, 260, 1400, 0.1, 1.2);
    x += cos(ang) * 8;
    y += sin(ang) * 8;

    let warm = random();
    if (warm < 0.58) {
      stroke(220, 210, 190, random(30, 90));
    } else {
      stroke(175, 130, 90, random(20, 70));
    }
    strokeWeight(random(0.3, 2));
    point(x, y);
  }
  blendMode(BLEND);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;
  const cx = width / 2;
  const horizon = 1500;
  const mainTop = 220;
  const mainBot = 1480;
  const reflTop = 1520;
  const reflBot = 1950;

  drawBackground(ctx);
  drawClouds(ctx);
  drawGlow(ctx, cx, 850, 750, 'rgba(170,190,240,0.08)', 'rgba(170,190,240,0)');
  drawGlow(ctx, cx, 850, 320, 'rgba(255,240,210,0.10)', 'rgba(255,240,210,0)');
  drawGlow(ctx, cx, 1700, 500, 'rgba(140,160,220,0.05)', 'rgba(140,160,220,0)');

  // Luminous field around the threshold
  portalLayer(ctx, cx, mainTop, mainBot, 130, 330, 70, 140, 160, 220, 0.05, 0);
  portalLayer(ctx, cx, mainTop, mainBot, 100, 300, 60, 170, 190, 240, 0.08, 10);
  portalLayer(ctx, cx, mainTop, mainBot, 70, 270, 50, 200, 210, 255, 0.13, 20);
  portalLayer(ctx, cx, mainTop, mainBot, 45, 240, 45, 220, 225, 255, 0.22, 30);
  portalLayer(ctx, cx, mainTop, mainBot, 25, 200, 35, 240, 240, 255, 0.35, 40);
  portalLayer(ctx, cx, mainTop, mainBot, 12, 160, 28, 255, 245, 220, 0.55, 50);
  portalLayer(ctx, cx, mainTop, mainBot, 5, 120, 20, 255, 250, 240, 0.80, 60);

  // The dark core of death itself
  darkPortalLayer(ctx, cx, mainTop + 30, mainBot - 30, 40, 210, 55, 0.25, 70);
  darkPortalLayer(ctx, cx, mainTop + 30, mainBot - 30, 30, 170, 45, 0.45, 80);
  darkPortalLayer(ctx, cx, mainTop + 30, mainBot - 30, 18, 130, 35, 0.70, 90);
  darkPortalLayer(ctx, cx, mainTop + 30, mainBot - 30, 8, 80, 25, 0.95, 100);

  // Reflection in still water
  portalLayer(ctx, cx, reflTop, reflBot, 110, 270, 60, 120, 140, 200, 0.03, 110);
  portalLayer(ctx, cx, reflTop, reflBot, 80, 220, 50, 150, 170, 220, 0.05, 120);
  portalLayer(ctx, cx, reflTop, reflBot, 50, 170, 40, 190, 200, 240, 0.08, 130);
  portalLayer(ctx, cx, reflTop, reflBot, 25, 120, 30, 220, 225, 255, 0.12, 140);
  darkPortalLayer(ctx, cx, reflTop + 20, reflBot - 20, 25, 100, 30, 0.25, 150);

  drawHorizon(ctx, horizon);
  drawParticles(ctx, cx, mainTop, mainBot, 1.0);
  drawParticles(ctx, cx, reflTop, reflBot, 0.55);
  drawDust(ctx);
  drawGrain(ctx);
  drawVignette(ctx);
}

function drawBackground(ctx) {
  let grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, '#08090f');
  grad.addColorStop(0.35, '#12141d');
  grad.addColorStop(0.55, '#1b1e28');
  grad.addColorStop(0.75, '#0c0e14');
  grad.addColorStop(1, '#050608');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
}

function drawClouds(ctx) {
  for (let i = 0; i < 24; i++) {
    let x = random(200, width - 200);
    let y = random(100, height - 100);
    let rad = random(150, 500);
    let r = 150 + random(0, 50);
    let g = 160 + random(0, 40);
    let b = 220;
    let alpha = random(0.015, 0.055);
    let grad = ctx.createRadialGradient(x, y, 0, x, y, rad);
    grad.addColorStop(0, `rgba(${r},${g},${b},${alpha.toFixed(3)})`);
    grad.addColorStop(1, `rgba(${r},${g},${b},0)`);
    ctx.fillStyle = grad;
    ctx.fillRect(x - rad, y - rad, rad * 2, rad * 2);
  }
}

function drawGlow(ctx, x, y, r, color0, color1) {
  let grad = ctx.createRadialGradient(x, y, 0, x, y, r);
  grad.addColorStop(0, color0);
  grad.addColorStop(1, color1);
  ctx.fillStyle = grad;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function makePortalGradient(ctx, topY, botY, r, g, b, alpha) {
  let a1 = (alpha * 0.4).toFixed(3);
  let a2 = alpha.toFixed(3);
  let grad = ctx.createLinearGradient(0, topY, 0, botY);
  grad.addColorStop(0, `rgba(${r},${g},${b},0)`);
  grad.addColorStop(0.18, `rgba(${r},${g},${b},${a1})`);
  grad.addColorStop(0.5, `rgba(${r},${g},${b},${a2})`);
  grad.addColorStop(0.82, `rgba(${r},${g},${b},${a1})`);
  grad.addColorStop(1, `rgba(${r},${g},${b},0)`);
  return grad;
}

function makeDarkGradient(ctx, topY, botY, alpha) {
  let a1 = (alpha * 0.3).toFixed(3);
  let a2 = alpha.toFixed(3);
  let grad = ctx.createLinearGradient(0, topY, 0, botY);
  grad.addColorStop(0, 'rgba(2,2,6,0)');
  grad.addColorStop(0.15, `rgba(2,2,6,${a1})`);
  grad.addColorStop(0.5, `rgba(2,2,10,${a2})`);
  grad.addColorStop(0.85, `rgba(2,2,6,${a1})`);
  grad.addColorStop(1, 'rgba(2,2,6,0)');
  return grad;
}

function portalLayer(ctx, cx, topY, botY, baseHalf, envHalf, jagged, r, g, b, alpha, seedOff) {
  let grad = makePortalGradient(ctx, topY, botY, r, g, b, alpha);
  let step = 6;
  ctx.beginPath();
  ctx.moveTo(cx, topY);
  for (let y = topY + step; y < botY; y += step) {
    let t = (y - topY) / (botY - topY);
    let env = Math.sin(Math.PI * Math.pow(t, 0.85)) * envHalf;
    let n = noise(y * 0.008 + seedOff, seedOff);
    let off = (n - 0.5) * jagged * Math.sin(Math.PI * t);
    let hw = Math.max(0.2, baseHalf + env + off);
    ctx.lineTo(cx - hw, y);
  }
  ctx.lineTo(cx, botY);
  for (let y = botY - step; y > topY; y -= step) {
    let t = (y - topY) / (botY - topY);
    let env = Math.sin(Math.PI * Math.pow(t, 0.85)) * envHalf;
    let n = noise(y * 0.008 + seedOff, seedOff + 777);
    let off = (n - 0.5) * jagged * Math.sin(Math.PI * t);
    let hw = Math.max(0.2, baseHalf + env + off);
    ctx.lineTo(cx + hw, y);
  }
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();
}

function darkPortalLayer(ctx, cx, topY, botY, baseHalf, envHalf, jagged, alpha, seedOff) {
  let grad = makeDarkGradient(ctx, topY, botY, alpha);
  let step = 6;
  ctx.beginPath();
  ctx.moveTo(cx, topY);
  for (let y = topY + step; y < botY; y += step) {
    let t = (y - topY) / (botY - topY);
    let env = Math.sin(Math.PI * Math.pow(t, 0.85)) * envHalf;
    let n = noise(y * 0.008 + seedOff, seedOff);
    let off = (n - 0.5) * jagged * Math.sin(Math.PI * t);
    let hw = Math.max(0.2, baseHalf + env + off);
    ctx.lineTo(cx - hw, y);
  }
  ctx.lineTo(cx, botY);
  for (let y = botY - step; y > topY; y -= step) {
    let t = (y - topY) / (botY - topY);
    let env = Math.sin(Math.PI * Math.pow(t, 0.85)) * envHalf;
    let n = noise(y * 0.008 + seedOff, seedOff + 777);
    let off = (n - 0.5) * jagged * Math.sin(Math.PI * t);
    let hw = Math.max(0.2, baseHalf + env + off);
    ctx.lineTo(cx + hw, y);
  }
  ctx.closePath();
  ctx.fillStyle = grad;
  ctx.fill();
}

function drawHorizon(ctx, y) {
  let grad = ctx.createLinearGradient(0, y - 12, 0, y + 12);
  grad.addColorStop(0, 'rgba(140,160,220,0)');
  grad.addColorStop(0.5, 'rgba(170,190,240,0.10)');
  grad.addColorStop(1, 'rgba(140,160,220,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, y - 12, width, 24);
  ctx.fillStyle = 'rgba(170,190,240,0.03)';
  ctx.fillRect(0, y - 1, width, 2);
}

function drawParticles(ctx, cx, yTop, yBot, fade) {
  for (let i = 0; i < 5500; i++) {
    let y = random(yTop - 120, yBot + 120);
    y = constrain(y, 5, height - 5);
    let t = constrain((y - yTop) / (yBot - yTop), 0, 1);
    let env = Math.sin(Math.PI * t) * 850;
    let spread = 100 + env * (0.1 + random());
    if (random() < 0.5) spread = -spread;
    let x = cx + spread * (0.3 + random() * 0.7);
    if (x < 10 || x > width - 10 || y < 10 || y > height - 10) continue;

    let dx = (cx - x) * 0.004 + (random() - 0.5) * 0.55;
    let dy = ((yTop + yBot) / 2 - y) * 0.001 + (random() - 0.5) * 0.55;
    let len = random(0.3, 2.6);
    let alpha = random(1, 18) * fade;
    if (alpha < 0.3) continue;

    let choice = random();
    let r, g, b;
    if (choice < 0.65) { r = 190; g = 200; b = 230; }
    else if (choice < 0.88) { r = 255; g = 225; b = 180; }
    else { r = 130; g = 150; b = 210; }

    ctx.strokeStyle = `rgba(${r},${g},${b},${(alpha / 255).toFixed(3)})`;
    ctx.lineWidth = random(0.2, 1.0);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + dx * len, y + dy * len);
    ctx.stroke();
  }
}

function drawDust(ctx) {
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let rad = random(0.3, 2.0);
    let a = random(4, 30);
    let c = random(180, 230);
    ctx.fillStyle = `rgba(${c},${c + 10},${c + 20},${(a / 255).toFixed(3)})`;
    ctx.beginPath();
    ctx.arc(x, y, rad, 0, Math.PI * 2);
    ctx.fill();
  }
}

function drawGrain(ctx) {
  for (let i = 0; i < 8000; i++) {
    let x = random(width);
    let y = random(height);
    let c = floor(random(140, 240));
    let a = random(1, 8);
    ctx.fillStyle = `rgba(${c},${c + 5},${c + 15},${(a / 255).toFixed(3)})`;
    ctx.fillRect(x, y, random(0.5, 1.5), random(0.5, 1.5));
  }
}

function drawVignette(ctx) {
  let grad = ctx.createRadialGradient(width / 2, height / 2, height * 0.25, width / 2, height / 2, height * 0.85);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.65)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
}

const W = 1600, H = 2000;
const AX = 0.500 * W, AY = 0.285 * H, AR = 0.19 * W;
const BX = 0.565 * W, BY = 0.352 * H, BR = 0.115 * W;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  background(8, 9, 15);
  paintBackground();
  paintHalo();
  paintVeils();
  paintThreads();
  paintWisps();
  paintAsh();
  paintGrain();
  paintVignette();
  noLoop();
}

function sstep(a, b, x) {
  let u = constrain((x - a) / (b - a), 0, 1);
  return u * u * (3 - 2 * u);
}

function mix3(a, b, f) {
  f = constrain(f, 0, 1);
  return [a[0] + (b[0] - a[0]) * f, a[1] + (b[1] - a[1]) * f, a[2] + (b[2] - a[2]) * f];
}

function paintBackground() {
  noStroke();
  let top = [27, 24, 34], mid = [14, 15, 24], bot = [5, 6, 11];
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let c = t < 0.42 ? mix3(top, mid, sstep(0, 0.42, t)) : mix3(mid, bot, sstep(0.42, 1, t));
    let f = 1 + (noise(y * 0.006) - 0.5) * 0.05;
    fill(c[0] * f, c[1] * f, c[2] * f);
    rect(0, y, W, 1);
  }
  noStroke();
  for (let i = 0; i < 12; i++) {
    let x = random(W), y = random(H), r = random(280, 860);
    fill(random() < 0.5 ? color(74, 84, 116, 3) : color(96, 74, 58, 3));
    ellipse(x, y, r * 1.35, r);
  }
}

function paintHalo() {
  noFill();
  blendMode(ADD);
  let cx = W * 0.5, cy = AY;
  for (let i = 0; i < 44; i++) {
    let f = i / 43;
    let r = lerp(70, 620, f);
    stroke(118, 80, 48, 4.4 * (1 - f) + 0.3);
    strokeWeight(24);
    ellipse(cx, cy, r * 2, r * 1.62);
  }
  blendMode(BLEND);
}

function fieldVec(x, y, holding, zoff, orbW) {
  let t = y / H;
  let nx = x / W;

  let dx = x - AX, dy = y - AY;
  let d = Math.sqrt(dx * dx + dy * dy) + 0.001;
  let wA = 1.75 * Math.exp(-(d * d) / (AR * AR * 2.2)) * (1 - sstep(0.40, 0.62, t));
  wA *= (holding ? 1.30 : 1.0) * orbW;
  let vx = wA * (-dy / d);
  let vy = wA * (dx / d);

  let dx2 = x - BX, dy2 = y - BY;
  let d2 = Math.sqrt(dx2 * dx2 + dy2 * dy2) + 0.001;
  let wB = 1.0 * Math.exp(-(d2 * d2) / (BR * BR * 2.2)) * (1 - sstep(0.42, 0.60, t)) * orbW;
  vx += wB * (dy2 / d2);
  vy += wB * (-dx2 / d2);

  let na = noise(nx * 3.2 + 7.3, t * 3.2 + 2.1, zoff) * TWO_PI * 2 - TWO_PI;
  let wN = 0.30 + 1.15 * Math.exp(-((t - 0.50) * (t - 0.50)) / 0.028) + 0.12 * (1 - sstep(0.65, 0.90, t));
  vx += wN * Math.cos(na);
  vy += wN * Math.sin(na);

  let wD = 0.16 + 2.5 * sstep(0.36, 0.78, t);
  if (holding) wD *= 0.10;
  vy += wD;

  if (holding) {
    let pull = 0.22 * constrain((d - AR * 0.62) / AR, 0, 1.3);
    vx += (-dx / d) * pull;
    vy += (-dy / d) * pull;
    if (d < AR * 0.30) {
      let push = 0.16 * (1 - d / (AR * 0.30));
      vx += (dx / d) * push;
      vy += (dy / d) * push;
    }
  } else if (d < AR * 1.7) {
    vx += (dx / d) * 0.07;
    vy += (dy / d) * 0.05;
  }

  let off = x - W / 2;
  if (Math.abs(off) > W * 0.40) {
    vx -= (off > 0 ? 1 : -1) * 0.6 * sstep(W * 0.40, W * 0.52, Math.abs(off));
  }

  let m = Math.sqrt(vx * vx + vy * vy) + 0.0001;
  return { x: vx / m, y: vy / m };
}

function threadColor(t, warm) {
  let ember = [214, 122, 70];
  let gold = [232, 195, 120];
  let bone = [236, 229, 210];
  let wc = warm < 0.55 ? mix3(ember, gold, warm / 0.55) : mix3(gold, bone, (warm - 0.55) / 0.45);
  let cc = mix3([94, 106, 134], [126, 128, 136], warm);
  let c = mix3(wc, cc, sstep(0.36, 0.75, t));
  let dim = 1 - 0.35 * sstep(0.45, 0.90, t);
  return [c[0] * dim, c[1] * dim, c[2] * dim];
}

function paintVeils() {
  strokeCap(ROUND);
  for (let i = 0; i < 34; i++) {
    let a = random(TWO_PI);
    let r = AR * random(0.2, 0.85);
    let x = AX + Math.cos(a) * r, y = AY + Math.sin(a) * r * 0.85;
    let zoff = random(100);
    let steps = Math.floor(random(130, 210));
    let wgt = random(26, 68);
    let al = random(2.0, 4.2);
    for (let s = 0; s < steps; s++) {
      let holding = s < 55;
      let v = fieldVec(x, y, holding, zoff, holding ? 1 : Math.max(0.2, Math.exp(-(s - 55) / 90)));
      let nx2 = x + v.x * 4.6, ny2 = y + v.y * 4.6;
      let t = y / H;
      let fade = 1 - sstep(0.52, 0.78, t);
      if (fade < 0.02) break;
      let c = mix3([66, 50, 40], [40, 50, 72], sstep(0.34, 0.70, t));
      stroke(c[0], c[1], c[2], al * fade);
      strokeWeight(wgt);
      line(x, y, nx2, ny2);
      x = nx2; y = ny2;
      if (y > H * 0.9 || x < -60 || x > W + 60 || y < -60) break;
    }
  }
}

function paintThreads() {
  strokeCap(ROUND);
  let N = 500;
  for (let i = 0; i < N; i++) {
    let a = random(TWO_PI);
    let r = AR * (0.25 + 0.65 * Math.sqrt(random()));
    let x = AX + Math.cos(a) * r * 1.05;
    let y = AY + Math.sin(a) * r * 0.85;

    let permanent = random() < 0.14;
    let hold = permanent ? 1e9 : Math.floor(random(70, 300));
    let maxSteps = Math.floor(hold > 1e8 ? random(340, 520) : hold + random(360, 500));
    let warm = random();
    let baseA = random(15, 28);
    let wgt = random(0.75, 1.45);
    let speed = random(2.1, 2.9);
    let zoff = random(100);

    if (random() < 0.08) { warm = 1.0; baseA *= 1.5; wgt *= 0.7; }

    let relAge = -1;
    for (let s = 0; s < maxSteps; s++) {
      let holding = s < hold;
      let orbW = 1;
      if (!holding) {
        if (relAge < 0) relAge = 0;
        orbW = Math.max(0.14, Math.exp(-relAge / 120));
        relAge++;
      }
      let v = fieldVec(x, y, holding, zoff, orbW);
      let t = y / H;
      let sp = speed * (holding ? 1.0 : (1.05 - 0.5 * sstep(0.35, 0.85, t)));
      let nx2 = x + v.x * sp;
      let ny2 = y + v.y * sp;
      let fade = 1 - sstep(0.58, 0.85, t);
      if (fade < 0.03) break;
      let c = threadColor(t, warm);
      stroke(c[0], c[1], c[2], baseA * fade);
      strokeWeight(wgt * (holding ? 1.0 : constrain(map(t, 0.38, 0.85, 1.0, 0.55), 0.55, 1.0)));
      line(x, y, nx2, ny2);
      x = nx2;
      y = ny2;
      if (y > H * 0.92 || y < -30 || x < -30 || x > W + 30) break;
    }
  }
}

function paintWisps() {
  strokeCap(ROUND);
  for (let i = 0; i < 12; i++) {
    let x = AX + random(-AR * 0.55, AR * 0.55);
    let y = AY - AR * random(0.15, 0.75);
    let steps = Math.floor(random(50, 110));
    let drift = random(-0.35, 0.35);
    let zoff = random(100);
    for (let s = 0; s < steps; s++) {
      let f = s / steps;
      let wob = (noise(x * 0.008 + zoff, y * 0.008) - 0.5) * 2.2;
      let nx2 = x + drift + wob;
      let ny2 = y - random(1.6, 2.8);
      stroke(186, 182, 196, 6.5 * (1 - f));
      strokeWeight(0.8);
      line(x, y, nx2, ny2);
      x = nx2; y = ny2;
    }
  }
}

function paintAsh() {
  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(152, 154, 164, 2.4);
    ellipse(W * 0.5 + random(-70, 70), H * (0.855 + i * 0.011), W * 1.45, random(36, 84));
  }
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 15000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.56) fill(0, 0, 0, random(3, 11));
    else fill(236, 233, 226, random(1.5, 5));
    rect(x, y, random() < 0.86 ? 1 : 2, 1);
  }
}

function paintVignette() {
  noFill();
  let cx = W / 2, cy = H * 0.47;
  for (let i = 0; i < 64; i++) {
    let f = i / 63;
    stroke(2, 3, 7, 1.6 + 9 * (1 - f));
    strokeWeight(26);
    ellipse(cx, cy, lerp(W * 2.7, W * 1.05, f), lerp(H * 2.5, H * 1.02, f));
  }
}

// THE STILL LINE — a painting about death as the end of difference.
// p5.js 1.11 · 1600 x 2000 · still image · nothing written anywhere in the image.

const W = 1600, H = 2000, LINE_Y = 820;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  paintGround();       // the field: ember above, slate at the line, depth below
  paintAir();          // warm breath above, cold hush beneath
  paintTheLiving();    // the bright stratum
  paintTheLine();      // the only edge in the painting
  paintTheCrossed();   // reflections that fail, the sinking
  paintTheSettled();   // the dark that is made of everyone
  paintLastCrossing(); // one mark still warm, halfway through
}

/* ---------- the field ---------- */
function paintGround() {
  const stops = [
    [0.00, 13, 8, 9],
    [0.16, 31, 17, 14],
    [0.29, 54, 29, 22],
    [0.41, 12, 13, 19],
    [0.54, 7, 9, 14],
    [0.76, 4, 5, 9],
    [1.00, 2, 2, 5],
  ];
  const rowR = [], rowG = [], rowB = [];
  for (let y = 0; y < H; y++) {
    const t = y / H;
    let k = 0;
    while (k < stops.length - 2 && t > stops[k + 1][0]) k++;
    const a = stops[k], b = stops[k + 1];
    let u = (t - a[0]) / (b[0] - a[0]);
    u = u * u * (3 - 2 * u);
    rowR[y] = lerpN(a[1], b[1], u);
    rowG[y] = lerpN(a[2], b[2], u);
    rowB[y] = lerpN(a[3], b[3], u);
  }
  const colF = [];
  for (let x = 0; x < W; x++) {
    const d = Math.abs(x - W / 2) / (W * 0.52);
    colF[x] = Math.max(0.56, 1 - 0.40 * Math.pow(Math.min(d, 1.25), 2.3));
  }
  loadPixels();
  for (let y = 0; y < H; y++) {
    const rr = rowR[y], gg = rowG[y], bb = rowB[y];
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4;
      const f = colF[x];
      const d = (hash2(x, y) - 0.5) * 13; // grain, keeps the dark from going flat
      pixels[i] = rr * f + d;
      pixels[i + 1] = gg * f + d;
      pixels[i + 2] = bb * f + d;
      pixels[i + 3] = 255;
    }
  }
  updatePixels();
}

/* ---------- atmosphere ---------- */
function paintAir() {
  blendMode(ADD);
  glow(800, 585, 640, 255, 148, 66, 11);
  glow(800, 552, 380, 255, 190, 110, 9);
  glow(800, 905, 470, 70, 100, 150, 4);
  blendMode(BLEND);
}

function glow(cx, cy, rad, r, g, b, maxA) {
  noFill();
  for (let rr = rad; rr > 4; rr -= 7) {
    const t = 1 - rr / rad;
    stroke(r, g, b, maxA * t * t);
    strokeWeight(9);
    circle(cx, cy, rr * 2);
  }
}

/* ---------- the living stratum ---------- */
function paintTheLiving() {
  for (let i = 0; i < 6400; i++) {
    let x = random() < 0.72 ? randomGaussian(800, 330) : random(70, 1530);
    const cy = 565 - 55 * Math.exp(-Math.pow((x - 800) / 430, 2));
    let y = randomGaussian(cy, 122);
    if (y < 150) y = 150 + random() * 70;
    if (y > 806) y = 806 - random() * 50;
    const n = noise(x * 0.0022 + 7.3, y * 0.0036 + 2.1);
    if (n < 0.35 && random() < 0.78) continue; // breathing gaps in the swarm
    const u = random();
    let col;
    if (u < 0.16) col = [124, 44, 32];
    else if (u < 0.42) col = [198, 102, 44];
    else if (u < 0.72) col = [226, 166, 88];
    else if (u < 0.93) col = [233, 221, 197];
    else col = [255, 242, 214];
    const near = constrain((y - 380) / 430, 0, 1);
    col = mix3(col, [64, 52, 64], near * 0.30); // cooler as it nears the line
    let a = (26 + 130 * random() * random()) * (1 - near * 0.25);
    if (u > 0.9) a += 46;
    let len = 3 + 30 * Math.pow(random(), 1.6);
    let ang = (noise(x * 0.004 + 31, y * 0.004) - 0.5) * 1.15 + (random() - 0.5) * 0.2;
    if (random() < 0.055) { // sparks turning upward
      ang = -HALF_PI + (random() - 0.5) * 0.5;
      len *= 0.6;
      a = Math.min(a + 40, 210);
    }
    mark(x, y, len, ang, 0.6 + 1.7 * random(), col[0], col[1], col[2], a);
  }
  // the heart of the stratum
  for (let i = 0; i < 820; i++) {
    const x = randomGaussian(800, 150);
    const y = randomGaussian(514, 52);
    const col = random() < 0.5 ? [236, 224, 200] : [255, 238, 206];
    mark(x, y, 2 + 12 * random(), (random() - 0.5) * 0.8,
      0.7 + 1.1 * random(), col[0], col[1], col[2], 70 + 120 * random() * random());
  }
  // sparks risen above
  noStroke();
  for (let i = 0; i < 260; i++) {
    const x = randomGaussian(800, 300);
    const y = 165 + Math.pow(random(), 1.4) * 380;
    fill(255, 236, 206, map(y, 165, 545, 7, 80));
    circle(x, y, 0.8 + 2.1 * random() * random());
  }
}

/* ---------- the only edge ---------- */
function paintTheLine() {
  for (let i = 0; i < 26; i++) { // cold breath just under the surface
    stroke(118, 138, 166, 3.4 * (1 - i / 26));
    strokeWeight(2.2);
    line(60, LINE_Y + 5 + i * 2.2, W - 60, LINE_Y + 5 + i * 2.2);
  }
  const step = 4;
  const nPts = Math.floor((W - 52) / step) + 1;
  const ys = [], al = [];
  for (let k = 0; k < nPts; k++) {
    const x = 26 + k * step;
    ys.push(LINE_Y + (noise(x * 0.004 + 3.3) - 0.5) * 7);
    al.push(10 + 62 * Math.pow(noise(x * 0.006 + 11.7), 2.2)); // intermittent
  }
  for (let k = 1; k < nPts; k++) {
    const x0 = 26 + (k - 1) * step, x1 = 26 + k * step;
    stroke(2, 3, 10, al[k] * 0.4);
    strokeWeight(1.7);
    line(x0, ys[k - 1] + 2.8, x1, ys[k] + 2.8);
    stroke(172, 182, 196, al[k]);
    strokeWeight(1.25);
    line(x0, ys[k - 1], x1, ys[k]);
  }
}

/* ---------- what crosses ---------- */
function paintTheCrossed() {
  // reflections that fail immediately
  for (let i = 0; i < 900; i++) {
    const x = randomGaussian(800, 330);
    const yUp = randomGaussian(700, 70);
    if (yUp < 560 || yUp > 812) continue;
    const y = LINE_Y + (LINE_Y - yUp) * 0.55 + random() * 4;
    const col = mix3([214, 160, 96], [40, 52, 70], 0.62);
    mark(x, y, 3 + 16 * Math.pow(random(), 1.4), (random() - 0.5) * 0.25,
      0.7 + random(), col[0], col[1], col[2], 14 + 30 * random());
  }
  // the sinking: same matter, cooling, slowing, spreading
  for (let i = 0; i < 2500; i++) {
    const depth = Math.pow(random(), 1.55);
    const y = LINE_Y + 14 + depth * 420;
    const x = randomGaussian(800, 300 + depth * 360);
    const n = noise(x * 0.002 + 17.1, y * 0.003 + 5.9);
    if (n < 0.3 && random() < 0.7) continue;
    const u = random();
    let warm;
    if (u < 0.3) warm = [150, 72, 44];
    else if (u < 0.7) warm = [190, 120, 66];
    else warm = [205, 170, 130];
    const col = mix3(warm, [30, 40, 58], 0.45 + 0.5 * depth);
    const a = (92 - 76 * depth) * (0.45 + 0.55 * random());
    mark(x, y, 6 + 26 * Math.pow(random(), 1.3) * (1 + depth * 0.8),
      (random() - 0.5) * (0.4 / (1 + depth * 3)), 0.6 + 1.2 * random(),
      col[0], col[1], col[2], a);
  }
  // last trails still falling
  for (let i = 0; i < 120; i++) {
    const x = random(140, 1460);
    const y0 = LINE_Y + 3 + random() * 8;
    const len = 50 + Math.pow(random(), 1.7) * 320;
    const drift = (noise(x * 0.01 + 40) - 0.5) * 26;
    stroke(116, 136, 164, 5 + 8 * random());
    strokeWeight(0.7 + 0.6 * random());
    line(x, y0, x + drift, y0 + len);
  }
}

/* ---------- the dark that is made of everyone ---------- */
function paintTheSettled() {
  // long faint strata: geology of everyone
  for (let i = 0; i < 42; i++) {
    const y = 1250 + Math.pow(random(), 1.1) * 640;
    stroke(38, 46, 62, 4.5 + 5.5 * random());
    strokeWeight(1 + 1.4 * random());
    let px = 40, py = y;
    for (let x = 66; x <= W - 40; x += 26) {
      const yy = y + (noise(x * 0.006 + y * 0.13) - 0.5) * 10;
      line(px, py, x, yy);
      px = x; py = yy;
    }
  }
  // settled marks, nearly indistinguishable from the dark
  for (let i = 0; i < 3600; i++) {
    const t = Math.pow(random(), 0.85);
    const y = 1170 + t * 760;
    const x = random(50, 1550);
    const n = noise(x * 0.0025 + 29, y * 0.0025 + 8);
    if (n < 0.28 && random() < 0.6) continue;
    let col = [26, 32, 46];
    if (random() < 0.06) col = mix3(col, [96, 64, 46], 0.25 + 0.4 * random()); // a warm memory
    mark(x, y, 16 + 150 * Math.pow(random(), 1.9), (random() - 0.5) * 0.05,
      0.5 + 0.8 * random(), col[0], col[1], col[2], (5 + 15 * random()) * (1 - t * 0.55));
  }
}

/* ---------- one mark still warm, halfway through ---------- */
function paintLastCrossing() {
  blendMode(ADD);
  glow(856, 902, 44, 255, 170, 96, 10);
  blendMode(BLEND);
  mark(856, 902, 20, -0.18, 1.5, 236, 158, 84, 150);
  mark(856, 902, 8, -0.18, 0.9, 255, 232, 196, 120);
}

/* ---------- helpers ---------- */
function mark(x, y, len, ang, w, r, g, b, a) {
  stroke(r, g, b, a);
  strokeWeight(w);
  const dx = Math.cos(ang) * len * 0.5, dy = Math.sin(ang) * len * 0.5;
  line(x - dx, y - dy, x + dx, y + dy);
}

function mix3(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function lerpN(a, b, t) { return a + (b - a) * t; }

function hash2(x, y) {
  let h = Math.imul(x, 374761393) + Math.imul(y, 668265263) | 0;
  h = Math.imul(h ^ (h >>> 13), 1274126177);
  h ^= h >>> 16;
  return (h >>> 0) / 4294967296;
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  const W = 1600, H = 2000;
  const CX = 800, CY = 640, R = 330;        // the closed sun
  const HZ = 1240;                          // horizon
  const MX = 800, MY = 2 * HZ - CY;         // mirrored sun in the water
  const ctx = drawingContext;
  const clamp01 = (v) => constrain(v, 0, 1);

  background(3, 4, 8);

  // ---------- tonal bands ----------
  const skyStops = [
    [0, 4, 5, 10],
    [380, 7, 10, 20],
    [720, 12, 16, 32],
    [1010, 16, 18, 37],
    [1150, 24, 21, 34],
    [1240, 33, 26, 30],
  ];
  const waterStops = [
    [1240, 29, 23, 27],
    [1310, 13, 13, 21],
    [1600, 7, 8, 14],
    [2000, 3, 4, 8],
  ];

  function bandColor(stops, y) {
    if (y <= stops[0][0]) return [stops[0][1], stops[0][2], stops[0][3]];
    for (let i = 0; i < stops.length - 1; i++) {
      const a = stops[i], b = stops[i + 1];
      if (y <= b[0]) {
        const t = (y - a[0]) / (b[0] - a[0]);
        return [
          lerp(a[1], b[1], t),
          lerp(a[2], b[2], t),
          lerp(a[3], b[3], t),
        ];
      }
    }
    const l = stops[stops.length - 1];
    return [l[1], l[2], l[3]];
  }

  // ---------- base fields ----------
  noStroke();
  for (let y = 0; y < HZ; y += 2) {
    const c = bandColor(skyStops, y);
    const m = (noise(0.7, y * 0.013) - 0.5) * 10;
    fill(c[0] + m, c[1] + m, c[2] + m);
    rect(0, y, W, 2);
  }
  for (let y = HZ; y < H; y += 2) {
    const c = bandColor(waterStops, y);
    const m = (noise(5.2, y * 0.017) - 0.5) * 6;
    fill(c[0] + m, c[1] + m, c[2] + m);
    rect(0, y, W, 2);
  }

  // ---------- brushed sky ----------
  strokeCap(ROUND);
  for (let i = 0; i < 1300; i++) {
    const y = random(0, HZ);
    const c = bandColor(skyStops, y);
    const x = random(W);
    const len = random(24, 190);
    const lift = random() < 0.12 ? random(8, 22) : random(-6, 8);
    stroke(c[0] + lift, c[1] + lift, c[2] + lift + 2, random(3, 9));
    strokeWeight(random(1, 3.2));
    const dy = random(-2.5, 2.5);
    line(x - len / 2, y - dy / 2, x + len / 2, y + dy / 2);
  }
  for (let i = 0; i < 24; i++) {
    const x = random(W), y = random(HZ);
    const r = random(180, 560);
    ctx.filter = "blur(46px)";
    const tone = random();
    if (tone < 0.55) fill(16, 22, 48, 7);
    else if (tone < 0.8) fill(30, 24, 44, 6);
    else fill(8, 12, 24, 8);
    noStroke();
    ellipse(x, y, r * 2, r * random(1.1, 1.8));
  }
  ctx.filter = "none";

  // ---------- stars that appear in totality ----------
  for (let i = 0; i < 110; i++) {
    const x = random(W), y = random(0, 1000);
    if (dist(x, y, CX, CY) < 560) continue;
    const s = random(0.8, 2.4);
    const a = random(14, 60);
    noStroke();
    fill(205, 212, 230, a);
    ellipse(x, y, s, s);
    if (random() < 0.12) {
      stroke(205, 212, 230, a * 0.5);
      strokeWeight(0.6);
      const g = s * random(3, 6);
      line(x - g, y, x + g, y);
      line(x, y - g, x, y + g);
    }
  }

  // ---------- last warmth at the horizon ----------
  noStroke();
  for (let y = 1140; y < HZ; y += 2) {
    const t = (y - 1140) / (HZ - 1140);
    fill(150, 88, 58, 30 * pow(t, 2.4));
    rect(0, y, W, 2);
  }
  ctx.filter = "blur(3px)";
  for (let y = HZ - 14; y < HZ; y += 2) {
    const t = (y - (HZ - 14)) / 14;
    fill(224, 204, 164, 12 + 40 * t);
    rect(0, y, W, 2);
  }
  ctx.filter = "none";

  // ---------- corona ----------
  blendMode(ADD);
  ctx.filter = "blur(70px)";
  noStroke();
  fill(198, 182, 146, 12);
  ellipse(CX, CY, R * 3.6);
  fill(220, 206, 170, 14);
  ellipse(CX, CY, R * 2.5);
  ctx.filter = "blur(26px)";
  noFill();
  stroke(240, 228, 198, 46);
  strokeWeight(30);
  ellipse(CX, CY, R * 2 + 10);
  ctx.filter = "blur(9px)";
  stroke(250, 243, 224, 90);
  strokeWeight(11);
  ellipse(CX, CY, R * 2 + 3);
  ctx.filter = "blur(5px)";
  stroke(235, 160, 110, 34);
  strokeWeight(6);
  ellipse(CX, CY, R * 2 + 4);
  ctx.filter = "blur(2px)";
  stroke(255, 250, 238, 150);
  strokeWeight(3);
  ellipse(CX, CY, R * 2);
  ctx.filter = "none";

  // streamers
  for (let i = 0; i < 1150; i++) {
    const a = random(TWO_PI);
    const nx = noise(4 + cos(a) * 1.35, 4 + sin(a) * 1.35);
    const len = (26 + 240 * pow(nx, 2.1)) * random(0.7, 1.25);
    const r0 = R + random(1, 7);
    const warm = clamp01(len / 300);
    stroke(
      lerp(250, 206, warm),
      lerp(243, 188, warm),
      lerp(226, 150, warm),
      random(5, 20)
    );
    strokeWeight(random(0.6, 2.2));
    line(
      CX + cos(a) * r0, CY + sin(a) * r0,
      CX + cos(a) * (r0 + len), CY + sin(a) * (r0 + len)
    );
  }
  for (let i = 0; i < 100; i++) {
    const a = random(TWO_PI);
    const len = random(160, 480);
    const r0 = R + random(0, 5);
    stroke(238, 226, 196, random(4, 9));
    strokeWeight(random(0.5, 1.1));
    line(
      CX + cos(a) * r0, CY + sin(a) * r0,
      CX + cos(a) * (r0 + len), CY + sin(a) * (r0 + len)
    );
  }
  blendMode(BLEND);

  // ---------- the void itself ----------
  noStroke();
  ctx.filter = "blur(1.5px)";
  fill(3, 4, 9);
  ellipse(CX, CY, R * 2);
  ctx.filter = "none";
  fill(2, 3, 7);
  ellipse(CX, CY, R * 2 - 3);
  for (let i = 0; i < 1700; i++) {
    const rr = (R - 8) * sqrt(random());
    const aa = random(TWO_PI);
    const x = CX + cos(aa) * rr;
    const y = CY + sin(aa) * rr;
    if (random() < 0.6) fill(0, 0, 2, random(20, 55));
    else fill(13, 16, 26, random(10, 26));
    ellipse(x, y, random(0.8, 2.2));
  }

  // ---------- water ----------
  function waterLight(x, y) {
    const d = dist(x, y, MX, MY);
    let ring = clamp01(1 - abs(d - R) / 135);
    ring = pow(ring, 1.7);
    let pillar =
      clamp01(1 - (y - HZ) / 430) * clamp01(1 - abs(x - CX) / 440) * 0.55;
    let b = max(ring * 0.95, pillar);
    if (d < R - 26) b *= 0.05;
    else if (d < R) b *= map(d, R - 26, R, 0.05, 1);
    b *= map(y, 1780, 2000, 1, 0.45, true);
    return clamp01(b);
  }

  const pale = [236, 224, 194];
  const dusk = [26, 30, 46];
  for (let i = 0; i < 5600; i++) {
    const y = HZ + 4 + pow(random(), 0.92) * (H - HZ - 8);
    const x = random(W);
    const b = waterLight(x, y);
    const len = random(12, 130) * (0.55 + 0.9 * b);
    const t = pow(b, 1.15);
    const rC = lerp(dusk[0], pale[0], t);
    const gC = lerp(dusk[1], pale[1], t);
    const bC = lerp(dusk[2], pale[2], t);
    const alpha =
      b > 0.04 ? random(6, 14) + 44 * b * random(0.4, 1.1) : random(4, 9);
    const w = clamp01(1 - (y - HZ) / 120) * 0.5;
    stroke(rC + 20 * w, gC + 2 * w, bC - 8 * w, alpha);
    strokeWeight(random(0.8, 2.6));
    line(x - len / 2, y, x + len / 2, y + random(-1, 1));
  }
  for (let i = 0; i < 260; i++) {
    const y = HZ + random(4, 60);
    const x = random(W);
    const len = random(120, 460);
    stroke(210, 198, 172, random(4, 12));
    strokeWeight(random(0.7, 1.6));
    line(x - len / 2, y, x + len / 2, y);
  }

  // ---------- the water cannot mirror the void ----------
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, HZ, W, H - HZ);
  ctx.clip();

  blendMode(ADD);
  ctx.filter = "blur(30px)";
  noStroke();
  fill(228, 216, 188, 26);
  ellipse(CX, HZ + 30, 560, 110);
  ctx.filter = "none";
  blendMode(BLEND);

  // the mirrored sun: darkness rising from below
  ctx.filter = "blur(4px)";
  noStroke();
  fill(1, 2, 6, 235);
  ellipse(MX, MY, R * 2);
  ctx.filter = "none";
  fill(1, 2, 5, 200);
  ellipse(MX, MY, R * 2 - 8);
  for (let i = 0; i < 260; i++) {
    let x, y;
    do {
      x = MX + random(-R, R);
      y = random(MY - R, H);
    } while (dist(x, y, MX, MY) > R - 10);
    stroke(3, 4, 9, random(25, 80));
    strokeWeight(random(0.8, 2.4));
    const len = random(16, 130);
    line(x - len / 2, y, x + len / 2, y);
  }

  // only the halo is reflected
  blendMode(ADD);
  ctx.filter = "blur(14px)";
  noFill();
  stroke(232, 220, 192, 60);
  strokeWeight(16);
  ellipse(MX, MY, R * 2);
  ctx.filter = "blur(4px)";
  stroke(248, 241, 222, 100);
  strokeWeight(5);
  ellipse(MX, MY, R * 2);
  ctx.filter = "blur(1px)";
  stroke(255, 251, 240, 130);
  strokeWeight(2);
  ellipse(MX, MY, R * 2);
  ctx.filter = "none";
  for (let i = 0; i < 420; i++) {
    const a = random(PI, TWO_PI);
    const x = MX + cos(a) * (R + random(-6, 6));
    const y = MY + sin(a) * (R + random(-6, 6));
    if (y < HZ) continue;
    stroke(250, 242, 222, random(10, 60));
    strokeWeight(random(0.7, 2));
    const len = random(8, 40);
    line(x - len / 2, y, x + len / 2, y);
  }
  blendMode(BLEND);
  ctx.restore();

  // abyss fade
  noStroke();
  for (let y = 1830; y < H; y += 2) {
    const t = (y - 1830) / (H - 1830);
    fill(2, 3, 6, 60 * t);
    rect(0, y, W, 2);
  }

  // ---------- the seam of the horizon ----------
  for (let x = 0; x < W; x += 5) {
    const y1 = HZ + (noise(x * 0.012) - 0.5) * 3;
    const y2 = HZ + (noise((x + 5) * 0.012) - 0.5) * 3;
    stroke(216, 202, 170, 64);
    strokeWeight(1.5);
    line(x, y1, x + 5, y2);
  }
  ctx.filter = "blur(2px)";
  stroke(230, 216, 182, 30);
  strokeWeight(3);
  line(0, HZ, W, HZ);
  ctx.filter = "none";

  // ---------- falling ash ----------
  for (let i = 0; i < 170; i++) {
    const x = random(W);
    const y = random(40, H - 120);
    if (dist(x, y, CX, CY) < R + 14) continue;
    const a = random(10, 52) * (y > HZ ? 0.5 : 1);
    noStroke();
    fill(212, 208, 200, a);
    ellipse(x, y, random(0.8, 2.6));
    if (random() < 0.16) {
      stroke(212, 208, 200, a * 0.35);
      strokeWeight(0.7);
      line(x, y, x + random(-2, 2), y - random(9, 26));
    }
  }

  // ---------- vignette ----------
  noStroke();
  for (let i = 0; i < 70; i++) {
    const xoff = i * 5;
    const a = 90 * pow(1 - i / 70, 2.2);
    fill(2, 3, 6, a);
    rect(xoff, 0, 5, H);
    rect(W - xoff - 5, 0, 5, H);
  }
  for (let i = 0; i < 50; i++) {
    const yoff = i * 5;
    const a = 80 * pow(1 - i / 50, 2.2);
    fill(2, 3, 6, a);
    rect(0, yoff, W, 5);
    rect(0, H - yoff - 5, W, 5);
  }

  // ---------- canvas grain ----------
  for (let i = 0; i < 9000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.55) fill(0, 0, 0, random(5, 13));
    else fill(220, 216, 205, random(3, 9));
    rect(x, y, 1, 1);
  }
  for (let i = 0; i < 34; i++) {
    const y = random(H);
    stroke(180, 176, 168, random(2, 5));
    strokeWeight(1);
    line(0, y, W, y + random(-3, 3));
  }
  for (let i = 0; i < 18; i++) {
    const x = random(W);
    stroke(180, 176, 168, random(2, 4));
    strokeWeight(1);
    line(x, 0, x + random(-3, 3), H);
  }
}

// UNBECOMING — a painting of death as dissolution
// p5.js 1.11, still image, 1600 x 2000

const W = 1600, H = 2000;
const BONE = [233, 227, 213];
const ASH  = [160, 153, 143];
const UMBR = [96, 77, 60];
const COAL = [36, 31, 30];
const GOLD = [208, 178, 124];

function mix(a, b, t) {
  t = constrain(t, 0, 1);
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function sway(y) { return (noise(y * 0.0035 + 40.7) - 0.5) * 44; }

function halfWidth(y) {
  const K = [
    [745, 34], [800, 62], [858, 172], [905, 240], [1010, 214],
    [1160, 168], [1260, 150], [1400, 176], [1560, 156],
    [1700, 128], [1800, 96], [1852, 34]
  ];
  if (y < K[0][0] || y > K[K.length - 1][0]) return 0;
  for (let i = 0; i < K.length - 1; i++) {
    if (y >= K[i][0] && y <= K[i + 1][0]) {
      const t = (y - K[i][0]) / (K[i + 1][0] - K[i][0]);
      const s = 0.5 - 0.5 * cos(PI * t);
      return lerp(K[i][1], K[i + 1][1], s);
    }
  }
  return 0;
}

function headAt(y) {
  const cy = 645, ry = 114, rx = 99;
  const d = abs(y - cy);
  if (d >= ry) return 0;
  return rx * sqrt(1 - (d / ry) * (d / ry));
}

function figurePoint() {
  for (let t = 0; t < 40; t++) {
    if (random() < 0.16) {
      const a = random(TWO_PI), r = sqrt(random());
      return { x: 800 + sway(645) * 0.6 + cos(a) * r * 99, y: 645 + sin(a) * r * 114, edge: r };
    }
    const y = 750 + pow(random(), 0.92) * (1850 - 750);
    const w = halfWidth(y);
    if (w < 10) continue;
    const spread = y > 1650 ? 1.18 : 1.0;
    const r = sqrt(random()) * spread;
    const side = random() < 0.5 ? -1 : 1;
    return { x: 800 + sway(y) + side * r * w, y: y, edge: min(r, 1) };
  }
  return null;
}

function upperPoint() {
  for (let t = 0; t < 40; t++) {
    const y = random(600, 1150);
    if (y < 758) {
      const w = headAt(y);
      if (w < 6) continue;
      return { x: 800 + sway(645) * 0.6 + random(-w, w), y: y };
    }
    const w = halfWidth(y);
    if (w < 10) continue;
    return { x: 800 + sway(y) + random(-w, w), y: y };
  }
  return { x: 800, y: 900 };
}

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(8, 9, 14);
  paintBackground();
  paintGlow();
  paintRing();
  paintDustFar();
  paintGroundAsh();
  paintVeil();
  paintPlume(520, false);   // departing substance, behind the body
  paintFigure();
  paintPlume(330, true);    // a few strands crossing in front
  paintFall();
  paintGrain();
  vignette();
}

function paintBackground() {
  noStroke();
  for (let y = 0; y < H; y += 2) {
    const c = mix([7, 9, 16], [19, 14, 11], y / H); // cold void above, warm earth below
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 2);
  }
  for (let i = 0; i < 300; i++) {
    const x = random(W), y = random(H);
    const n = noise(x * 0.0011 + 3, y * 0.0011);
    const r = random(140, 380);
    if (n > 0.52) fill(24, 18, 14, 2.5); else fill(9, 13, 21, 2.5);
    ellipse(x, y, r * 1.35, r * 0.85);
  }
}

function paintGlow() {
  noStroke();
  for (let i = 0; i < 46; i++) {
    const r = lerp(980, 120, i / 45);
    fill(58, 47, 37, 1.5);
    ellipse(800, 1040, r * 1.02, r * 1.32);
  }
}

function paintRing() {
  // an eclipse behind the head: a sun gone into memory
  push();
  blendMode(ADD);
  const cx = 800, cy = 600, R = 330;
  for (let i = 0; i < 2600; i++) {
    const a = random(TWO_PI);
    const rr = R + random(-9, 9) + (noise(cos(a) * 2 + 10, sin(a) * 2 + 10) - 0.5) * 14;
    const tw = noise(a * 3.1, 5.5);
    stroke(214, 196, 160, (6 + 20 * tw) * 0.5);
    strokeWeight(random(0.6, 1.6));
    point(cx + cos(a) * rr, cy + sin(a) * rr);
  }
  for (let i = 0; i < 900; i++) {
    const a = random(TWO_PI);
    const rr = R + 34 + random(-14, 14);
    stroke(190, 176, 150, 4);
    strokeWeight(0.8);
    point(cx + cos(a) * rr, cy + sin(a) * rr);
  }
  pop();
  blendMode(BLEND);
}

function paintDustFar() {
  noStroke();
  for (let i = 0; i < 1400; i++) {
    const x = random(W), y = random(H);
    if (noise(x * 0.003, y * 0.003) > 0.55) {
      fill(180, 176, 166, random(2, 7));
      ellipse(x, y, random(0.8, 2.2));
    }
  }
}

function paintGroundAsh() {
  noStroke();
  for (let i = 0; i < 5; i++) {
    fill(10, 9, 10, 5);
    ellipse(800, 1862, 1500 + i * 40, 220 + i * 14);
  }
  for (let i = 0; i < 2400; i++) {
    const a = random(TWO_PI), r = pow(random(), 0.62);
    fill(148, 140, 126, random(2.5, 8.5));
    const d = random(0.8, 2.6);
    ellipse(800 + cos(a) * r * 560, 1812 + sin(a) * r * 86, d, d);
  }
  for (let i = 0; i < 420; i++) {
    const x = 800 + random(-1, 1) * pow(random(), 1.6) * 780;
    fill(140, 133, 120, random(2, 5));
    ellipse(x, 1790 + random(150), random(0.7, 1.8));
  }
}

function paintVeil() {
  // soft body of smoke along the plume's path
  noStroke();
  for (let i = 0; i < 200; i++) {
    const p = upperPoint();
    let x = p.x, y = p.y;
    const dir = random() < 0.86 ? -1 : 1;
    for (let s = 0; s < 26; s++) {
      const n = noise(x * 0.0016 + 3.1, y * 0.0016);
      const ang = n * 4.4 * PI;
      x += (cos(ang) * 0.8 + dir * 1.0) * 9;
      y += (sin(ang) * 0.8 - 1.8) * 9;
      if (random() < 0.5) {
        fill(120, 116, 108, 2.0);
        ellipse(x, y, random(40, 110), random(30, 80));
      }
      if (y < 40 || x < -40 || x > W + 40) break;
    }
  }
}

function paintPlume(count, front) {
  for (let i = 0; i < count; i++) {
    const p = upperPoint();
    let x = p.x, y = p.y;
    const dir = random() < 0.86 ? -1 : 1;
    const steps = 26 + floor(random(64));
    const gold = random() < 0.05;
    const base = gold ? GOLD : (random() < 0.5 ? BONE : ASH);
    const wgt = random(0.5, 1.35);
    const a0 = (front ? random(9, 21) : random(5, 13)) * (gold ? 1.25 : 1);
    for (let s = 0; s < steps; s++) {
      const n = noise(x * 0.0016 + 3.1, y * 0.0016);
      const ang = n * 4.4 * PI;
      const m = 2.4 + noise(x * 0.01 + 7, y * 0.01) * 2.6;
      const nx = x + (cos(ang) * 0.8 + dir * 1.05) * m;
      const ny = y + (sin(ang) * 0.8 - 1.85) * m;
      const fade = 1 - s / steps;
      stroke(base[0], base[1], base[2], a0 * fade);
      strokeWeight(wgt * (0.45 + 0.55 * fade));
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (y < -20 || x < -30 || x > W + 30) break;
    }
  }
}

function paintFigure() {
  // underpainting: the soft mass of the shrouded form
  noStroke();
  for (let i = 0; i < 2800; i++) {
    const p = figurePoint();
    if (!p) continue;
    const up = constrain(map(p.y, 1400, 560, 0, 1), 0, 1);
    if (p.edge < 0.85 && noise(p.x * 0.01 + 9, p.y * 0.01) > 0.86 - up * 0.20 && random() < 0.7) continue;
    fill(52, 45, 39, 6 + random() * 6);
    const s = random(9, 26);
    ellipse(p.x, p.y, s * 0.8, s * 1.15);
  }
  // shroud folds
  strokeWeight(1);
  for (let i = 0; i < 1300; i++) {
    const p = figurePoint();
    if (!p || p.edge > 0.8) continue;
    stroke(30, 26, 25, 7);
    line(p.x, p.y, p.x + random(-2, 2), p.y + random(6, 24));
  }
  // chalk-and-ash particles of the body
  noStroke();
  for (let i = 0; i < 46000; i++) {
    const p = figurePoint();
    if (!p) continue;
    const up = constrain(map(p.y, 1400, 540, 0, 1), 0, 1);
    if (p.edge < 0.88 && noise(p.x * 0.011, p.y * 0.011) > 0.84 - up * 0.24) continue;
    const rim = constrain((p.edge - 0.70) / 0.30, 0, 1);
    const left = p.x < 800 ? 1 : 0.5;
    let c = mix(COAL, [88, 80, 72], 0.35 + 0.55 * noise(p.x * 0.006, p.y * 0.006));
    c = mix(c, ASH, up * 0.35);
    c = mix(c, BONE, rim * rim * (0.35 + 0.6 * left));
    if (random() < 0.008) c = GOLD;
    let al = 13 + 20 * rim + random(8);
    if (p.y > 1660) al *= map(p.y, 1660, 1855, 1, 0.12);
    al *= 0.55 + 0.45 * (1 - up * 0.5);
    fill(c[0], c[1], c[2], al);
    const d = 0.9 + random(1.7) + rim * 0.6;
    ellipse(p.x, p.y, d, d * random(0.9, 1.4));
  }
  // rim light: the edge still remembering a shape
  for (let y = 536; y < 1840; y += 2.6) {
    for (const s of [-1, 1]) {
      const w = y < 758 ? headAt(y) : halfWidth(y);
      if (w < 4) continue;
      const cx = y < 758 ? 800 + sway(645) * 0.6 : 800 + sway(y);
      if (random() < 0.25) continue;
      const up = constrain(map(y, 1400, 540, 0, 1), 0, 1);
      const c = mix(ASH, BONE, 0.3 + 0.6 * random());
      let al = (8 + random(16)) * (s < 0 ? 1 : 0.55) * (0.5 + 0.5 * up);
      if (y > 1700) al *= map(y, 1700, 1840, 1, 0.25);
      fill(c[0], c[1], c[2], al);
      const d = 0.8 + random(1.6);
      ellipse(cx + s * (w + random(-2.5, 2.5)), y + random(-1.5, 1.5), d, d);
    }
  }
  // the face as absence
  for (let i = 0; i < 150; i++) {
    const a = random(TWO_PI), r = sqrt(random()) * 0.55;
    fill(24, 21, 22, 7);
    ellipse(800 + sway(645) * 0.6 + cos(a) * r * 99, 645 + sin(a) * r * 114, random(6, 16));
  }
}

function paintFall() {
  // what settles: ash dropping back to the ground
  for (let i = 0; i < 620; i++) {
    const y0 = random(1050, 1820);
    const w = halfWidth(y0);
    if (w < 8) continue;
    const s = random() < 0.5 ? -1 : 1;
    let x = 800 + sway(y0) + s * w * random(0.7, 1.02);
    let y = y0;
    const steps = 7 + floor(random(16));
    for (let j = 0; j < steps; j++) {
      const nx = x + (noise(x * 0.02, y * 0.02) - 0.5) * 3 + s * 0.5;
      const ny = y + 1.8 + random(3.2);
      stroke(150, 143, 130, 9 * (1 - j / steps));
      strokeWeight(random(0.5, 1.2));
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (y > 1858) break;
    }
  }
}

function paintGrain() {
  strokeWeight(1);
  for (let i = 0; i < 24000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.55) stroke(0, 0, 0, random(5, 15));
    else stroke(198, 194, 184, random(2, 6));
    point(x, y);
  }
}

function vignette() {
  noStroke();
  for (let y = 0; y < 330; y += 2) {
    fill(4, 5, 10, 24 * pow(1 - y / 330, 1.7));
    rect(0, y, W, 2);
  }
  for (let y = H - 280; y < H; y += 2) {
    fill(5, 4, 7, 20 * pow((y - (H - 280)) / 280, 1.7));
    rect(0, y, W, 2);
  }
  for (const c of [[0, 0], [W, 0], [0, H], [W, H]]) {
    for (let i = 0; i < 26; i++) {
      fill(4, 5, 10, 2.3);
      const r = (920 - i * 34) * 1.6;
      ellipse(c[0], c[1], r, r);
    }
  }
}

const CX = 800, CY = 780, R = 340;
let deadX, deadY;

function setup() {
