}

function paintOrbits() {
  for (let m = 0; m < 2; m++) {
    let rr = R * (1.45 + m * 0.4);
    for (let i = 0; i < 420; i++) {
      let a = lerp(PI * 0.14, PI * 0.86, random());
      let jd = (noise(a * 2.5 + m * 20) - 0.5) * 24;
      stroke(150, 160, 186, random(4, 13));
      strokeWeight(random(0.8, 1.8));
