      ellipse(x + random(-4, 4), b + (n - 0.5) * 70, 64, 26 + n * 70);
    }
  }
}

function paintGlowOfMany() {
  radial(800, 1560, 720, [
    [0, 'rgba(150,84,40,0.10)'],
    [0.6, 'rgba(120,66,34,0.05)'],
    [1, 'rgba(0,0,0,0)']
  ]);
}

function strandColor(t) {
  const stops = [
    [0.00, [228, 150, 78]],
    [0.35, [214, 178, 132]],
    [0.62, [198, 188, 174]],
    [0.85, [160, 166, 184]],
    [1.00, [128, 136, 158]]
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    let t0 = stops[i][0], c0 = stops[i][1];
    let t1 = stops[i + 1][0], c1 = stops[i + 1][1];
    if (t <= t1) {
      let f = (t - t0) / (t1 - t0);
      return [lerp(c0[0], c1[0], f), lerp(c0[1], c1[1], f), lerp(c0[2], c1[2], f)];
    }
  }
  return stops[stops.length - 1][1];
}

function strandAlpha(t, boost) {
  let rise = Math.sin(Math.min(t * 4, 1) * HALF_PI);
  return 105 * boost * rise * Math.pow(1 - t, 1.1);
}

function paintStrands() {
  for (let s = 0; s < 150; s++) {
    let a = random() < 0.6
      ? lerp(PI * 0.30, PI * 0.70, random())
      : lerp(PI * 0.06, PI * 0.94, random());
    let ex = CX + cos(a) * R, ey = CY + sin(a) * R;
    let x0 = constrain(ex + random(-430, 430), 40, 1560);
    let y0 = random(1690, 1950);
    drawStrand(x0, y0, ex, ey, random(-1, 1) * random(60, 220), random(1.1, 2.6), random(0.6, 1.1), 10);
  }
}

function drawStrand(x0, y0, ex, ey, curl, w0, boost, jit) {
  let mx = (x0 + ex) / 2 + curl + random(-40, 40);
  let my = (y0 + ey) / 2 + random(-60, 20);
  let steps = 46;
  let pvx = null, pvy = null;
  for (let k = 0; k <= steps; k++) {
    let t = k / steps, u = 1 - t;
    let bx = u * u * x0 + 2 * u * t * mx + t * t * ex;
    let by = u * u * y0 + 2 * u * t * my + t * t * ey;
    let damp = 1 - t * 0.6;
    bx += (noise(bx * 0.02 + 300, by * 0.02) - 0.5) * jit * damp;
    by += (noise(by * 0.02 + 300, bx * 0.02) - 0.5) * jit * damp;
    if (pvx !== null) {
      let c = strandColor(t);
      stroke(c[0], c[1], c[2], strandAlpha(t, boost));
      strokeWeight(lerp(w0, 0.5, t));
      line(pvx, pvy, bx, by);
    }
    if (k > 2 && k < steps - 2 && random() < 0.1) {
      let c = strandColor(t);
      noStroke();
      fill(c[0], c[1], c[2], min(strandAlpha(t, boost) * 1.7, 160));
      ellipse(bx, by, random(1.5, 3.4));
    }
    pvx = bx; pvy = by;
  }
}

function paintNewlyDead() {
  let a = PI * 0.5 + random(-0.06, 0.06);
  let ex = CX + cos(a) * R, ey = CY + sin(a) * R;
  drawStrand(deadX, deadY, ex, ey, random(-70, 70), 3.1, 1.35, 20);
  noStroke();
  for (let i = 0; i < 10; i++) {
    fill(190, 190, 200, random(8, 22));
    ellipse(deadX + random(-7, 7), deadY - random(0, 22), random(1.5, 4));
  }
  noFill();
  stroke(226, 196, 150, 60);
  strokeWeight(2);
  arc(CX, CY, R * 2, R * 2, a - 0.03, a + 0.03);
}

function paintCrowd() {
  radial(800, 2080, 820, [
    [0, 'rgba(98,54,26,0.34)'],
    [0.6, 'rgba(60,34,20,0.14)'],
    [1, 'rgba(0,0,0,0)']
  ]);
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = random(width), y = random(1848, 1996);
    fill(32 + random(22), 23 + random(13), 17, 8 + random(18));
    rect(x, y, random(20, 150), random(0.6, 2.1));
  }
  const rows = [
    { y: 1840, s: 0.60, n: 60, d: 0.50 },
    { y: 1870, s: 0.78, n: 68, d: 0.70 },
    { y: 1902, s: 1.00, n: 74, d: 0.90 },
    { y: 1938, s: 1.18, n: 66, d: 1.00 }
  ];
  for (let r = 0; r < rows.length; r++) {
    let row = rows[r];
    for (let i = 0; i < row.n; i++) {
      if (r === 3 && i === Math.floor(row.n / 2)) {
        drawFigure(deadX, row.y, row.y - deadY, row.d, true);
        continue;
      }
      drawFigure(random(28, 1572), row.y + random(-6, 6), random(44, 128) * row.s, row.d, false);
    }
  }
}

function drawFigure(x, baseY, h, d, gone) {
  let sway = (noise(x * 0.05) - 0.5) * 9;
  for (let k = 0; k < 4; k++) {
    let xx = x + random(-2.4, 2.4);
    stroke(22, 18, 24, (26 + random(22)) * d);
    strokeWeight(random(2.4, 5));
    line(xx, baseY, xx + sway, baseY - h);
  }
  if (gone) return;
  let hx = x + sway, hy = baseY - h;
  let dim = random() < 0.12 ? random(0.25, 0.5) : 1;
  let fr = random(9, 22) * (0.6 + 0.4 * dim);
  radial(hx, hy, fr, [
    [0, 'rgba(255,198,122,' + (0.5 * d * dim).toFixed(3) + ')'],
    [0.35, 'rgba(240,150,70,' + (0.2 * d * dim).toFixed(3) + ')'],
    [1, 'rgba(0,0,0,0)']
  ]);
  noStroke();
  fill(255, 226, 170, 210 * d * dim);
  ellipse(hx, hy, random(1.7, 3.1));
}

function vignette() {
  lin(0, 0, 0, 300, [[0, 'rgba(2,2,6,0.5)'], [1, 'rgba(2,2,6,0)']]);
  lin(0, height, 0, height - 260, [[0, 'rgba(2,2,4,0.5)'], [1, 'rgba(2,2,4,0)']]);
  lin(0, 0, 230, 0, [[0, 'rgba(2,2,5,0.45)'], [1, 'rgba(2,2,5,0)']]);
  lin(width, 0, width - 230, 0, [[0, 'rgba(2,2,5,0.45)'], [1, 'rgba(2,2,5,0)']]);
  radial(0, 0, 640, [[0, 'rgba(0,0,4,0.4)'], [1, 'rgba(0,0,0,0)']]);
  radial(width, 0, 640, [[0, 'rgba(0,0,4,0.4)'], [1, 'rgba(0,0,0,0)']]);
  radial(0, height, 640, [[0, 'rgba(0,0,4,0.4)'], [1, 'rgba(0,0,0,0)']]);
  radial(width, height, 640, [[0, 'rgba(0,0,4,0.4)'], [1, 'rgba(0,0,0,0)']]);
}

function grain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = (random() - 0.5) * 15;
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();
}

function radial(cx, cy, r, stops) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.save();
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function lin(x0, y0, x1, y1, stops) {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(x0, y0, x1, y1);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.save();
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

const C = { x: 800, y: 960 };

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);

  drawGround();
  drawWashes();
  drawWeave();
  drawHalo();
  drawUnbinding();
  drawAbsence();
  drawGrain();
  drawVignette();
}

function chooseInk() {
  const r = random();
  if (r < 0.22) return [202, 188, 157];
  if (r < 0.40) return [164, 119, 85];
  if (r < 0.55) return [139, 91, 79];
  if (r < 0.76) return [112, 137, 139];
  if (r < 0.91) return [75, 105, 119];
  return [178, 156, 112];
}

function drawGround() {
  const top = color(17, 27, 35);
  const middle = color(38, 35, 32);
  const bottom = color(9, 16, 22);

  for (let y = 0; y < height; y++) {
    const t = y / (height - 1);
    let c;
    if (t < 0.5) {
      c = lerpColor(top, middle, t / 0.5);
    } else {
      c = lerpColor(middle, bottom, (t - 0.5) / 0.5);
    }
    stroke(c);
    line(0, y, width, y);
  }

  const ctx = drawingContext;

  let glow = ctx.createRadialGradient(690, 730, 40, 690, 730, 1040);
  glow.addColorStop(0, "rgba(174,139,96,0.22)");
  glow.addColorStop(0.42, "rgba(133,105,78,0.09)");
  glow.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, width, height);

  glow = ctx.createRadialGradient(1120, 1430, 20, 1120, 1430, 820);
  glow.addColorStop(0, "rgba(77,111,119,0.12)");
  glow.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, width, height);
}

function drawWashes() {
  noFill();
  strokeCap(ROUND);

  for (let i = 0; i < 38; i++) {
    const p = chooseInk();
    const y = random(-180, 2180);
    const drift = random(-420, 420);

    stroke(p[0], p[1], p[2], random(3, 10));
    strokeWeight(random(35, 145));
    bezier(
      -240, y,
      330, y + random(-250, 250),
      1120, y + drift,
      1840, y + random(-220, 220)
    );
  }
}

function drawWeave() {
  noFill();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  for (let i = 0; i < 165; i++) {
    const bx = map(i, 0, 164, -90, 1690) + random(-12, 12);
    const phase = random(10, 90);
    const p = chooseInk();
    let alpha = random(8, 25);

    if (i % 19 === 0) {
      alpha *= 1.7;
      strokeWeight(random(2.4, 4.4));
    } else {
      strokeWeight(random(0.45, 1.8));
    }

    stroke(p[0], p[1], p[2], alpha);
    beginShape();

    for (let y = -150; y <= 2150; y += 28) {
      const dx = bx - C.x;
      const side = dx < 0 ? -1 : 1;
      const bend = side * 175 *
        exp(-sq((y - C.y) / 475)) *
        exp(-sq(dx / 730));

      const x = bx
        + 25 * sin(y * 0.0018 + phase)
        + 65 * (noise(phase, y * 0.0015) - 0.5)
        + bend;

      vertex(x, y);
    }
    endShape();
  }

  for (let i = 0; i < 116; i++) {
    const by = map(i, 0, 115, -80, 2080) + random(-13, 13);
    const phase = random(20, 100);
    const p = chooseInk();

    stroke(p[0], p[1], p[2], random(5, 17));
    strokeWeight(random(0.45, 1.65));
    beginShape();

    for (let x = -160; x <= 1760; x += 32) {
      const dy = by - C.y;
      const side = dy < 0 ? -1 : 1;
      const bend = side * 135 *
        exp(-sq((x - C.x) / 630)) *
        exp(-sq(dy / 710));

      const y = by
        + 23 * sin(x * 0.0021 + phase)
        + 58 * (noise(x * 0.0014, phase) - 0.5)
        + bend;

      vertex(x, y);
    }
    endShape();
  }
}

function drawHalo() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(C.x, C.y, 225, C.x, C.y, 735);

  g.addColorStop(0, "rgba(3,6,8,0.72)");
  g.addColorStop(0.43, "rgba(7,9,10,0.48)");
  g.addColorStop(0.53, "rgba(211,181,133,0.17)");
  g.addColorStop(0.68, "rgba(121,137,128,0.065)");
  g.addColorStop(1, "rgba(0,0,0,0)");

  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function drawUnbinding() {
  noFill();
  strokeCap(ROUND);

  for (let i = 0; i < 540; i++) {
    const a = random(TWO_PI);
    const r = 330 + pow(random(), 1.65) * 710;
    const direction = random() < 0.5 ? -1 : 1;
    const span = random(0.025, 0.24);
    const drift = random(-65, 65);
    const lift = random(-24, 24);
    const phase = random(TWO_PI);
    const p = chooseInk();

    let alpha = map(r, 330, 1040, 72, 4) * random(0.45, 1);
    let weight = random(0.5, 2.2);

    if (random() < 0.07) {
      alpha *= 1.8;
      weight *= 1.8;
    }

    stroke(p[0], p[1], p[2], alpha);
    strokeWeight(weight);
    beginShape();

    for (let j = 0; j <= 22; j++) {
      const t = j / 22;
      const aa = a + direction * span * t;
      const rr = r + drift * (t - 0.5) + sin(PI * t) * lift;
      const flutter = 4 * sin(t * TWO_PI + phase);

      vertex(
        C.x + cos(aa) * (rr + flutter),
        C.y + sin(aa) * (rr + flutter) * 1.08
      );
    }
    endShape();
  }

  for (let i = 0; i < 125; i++) {
    const a = random(TWO_PI);
    const r0 = random(325, 480);
    const len = random(70, 430);
    const phase = random(TWO_PI);
    const p = chooseInk();

    stroke(p[0], p[1], p[2], random(8, 37));
    strokeWeight(random(0.5, 1.8));
    beginShape();

    for (let j = 0; j <= 25; j++) {
      const t = j / 25;
      const rr = r0 + len * t;
      const aa = a
        + 0.045 * sin(t * PI + phase) * t
        + 0.018 * sin(t * 7 + phase);

      vertex(
        C.x + cos(aa) * rr,
        C.y + sin(aa) * rr * 1.08
      );
    }
    endShape();
  }

  for (let i = 0; i < 1050; i++) {
    const a = random(TWO_PI);
    const r = 335 + pow(random(), 1.9) * 690;
    const x = C.x + cos(a) * r + random(-8, 8);
    const y = C.y + sin(a) * r * 1.08 + random(-8, 8);
    const p = chooseInk();

    stroke(p[0], p[1], p[2], random(5, 42));
    strokeWeight(random(0.5, 2.1));
    point(x, y);
  }
}

function traceOpening(radius) {
  beginShape();

  for (let i = 0; i <= 240; i++) {
    const a = TWO_PI * i / 240;
    const n = noise(8 + cos(a) * 1.45, 8 + sin(a) * 1.45);
    const r = radius
      + 8 * sin(a * 3 + 0.7)
      + 5 * sin(a * 7 + 1.2)
      + 18 * (n - 0.5);

    vertex(
      C.x + cos(a) * r,
      C.y + sin(a) * r * 1.08
    );
  }

  endShape(CLOSE);
}

function drawAbsence() {
  noStroke();

  drawingContext.save();
  drawingContext.shadowColor = "rgba(0,0,0,0.72)";
  drawingContext.shadowBlur = 58;
  fill(12, 14, 14, 235);
  traceOpening(331);
  drawingContext.restore();

  fill(5, 8, 10);
  traceOpening(311);

  fill(7, 10, 12, 150);
  traceOpening(286);
}

function drawGrain() {
