function formPoint(a, offset = 0) {
  const wobble = 1 + 0.052 * sin(3 * a + 0.7) + 0.025 * sin(7 * a - 0.4);
  const rx = 350 * wobble + offset;
  const ry = 485 * (1 + 0.035 * cos(5 * a)) + offset;
  return {
    x: 780 + rx * cos(a) + 32 * sin(a) - 18 * cos(2 * a),
    y: 795 + ry * sin(a)
  };
}

function paintGround() {
  const top = color(8, 11, 18);
  const middle = color(23, 22, 26);
  const bottom = color(6, 9, 13);

  noStroke();
  for (let y = 0; y < height; y += 5) {
    const t = y / height;
    const c = t < 0.56
      ? lerpColor(top, middle, t / 0.56)
      : lerpColor(middle, bottom, (t - 0.56) / 0.44);
    fill(c);
    rect(0, y, width, 6);
  }

  const washes = [
    [48, 57, 70],
    [74, 62, 52],
    [29, 38, 48],
    [83, 77, 65]
  ];

  for (let i = 0; i < 850; i++) {
    const c = washes[floor(random(washes.length))];
    push();
    translate(random(width), random(height));
    rotate(random(-0.16, 0.16));
    fill(c[0], c[1], c[2], random(1.5, 5.5));
    ellipse(0, 0, random(70, 520), random(8, 95));
    pop();
  }

  for (let i = 0; i < 1500; i++) {
    const x = random(width);
    const y = random(height);
    stroke(116, 108, 94, random(1.5, 5));
    strokeWeight(random(1, 12));
    line(x, y, x + random(-7, 7), y + random(12, 120));
  }
}

function paintHalo() {
  noStroke();
  for (let i = 0; i < 120; i++) {
    const t = i / 119;
    fill(111, 99, 80, 0.32 + 0.18 * t);
    ellipse(
      775,
      835,
      lerp(1190, 210, t),
      lerp(1450, 360, t)
    );
  }

  for (let i = 0; i < 55; i++) {
    const t = i / 54;
    fill(67, 83, 94, 0.22);
    ellipse(725, 760, lerp(970, 300, t), lerp(1180, 420, t));
  }
}

function paintInterior() {
  noStroke();
  for (let k = 0; k < 7; k++) {
    fill(143, 137, 120, 2.2);
    beginShape();
    for (let j = 0; j <= 180; j++) {
      const p = formPoint((j / 180) * TWO_PI, -k * 2.2);
      vertex(p.x, p.y);
    }
    endShape(CLOSE);
  }

  const pigments = [
    [209, 200, 174],
    [157, 174, 177],
    [179, 139, 96],
    [101, 113, 121],
    [224, 211, 177],
    [61, 63, 67]
  ];

  for (let i = 0; i < 1550; i++) {
    const a = random(TWO_PI);
    const r = sqrt(random()) * 0.96;
    const edge = formPoint(a);
    const x = 780 + (edge.x - 780) * r;
    const y = 795 + (edge.y - 795) * r;
    const lower = constrain((y - 920) / 360, 0, 1);

    if (random() < lower * 0.78) continue;

    const c = pigments[floor(random(pigments.length))];
    const size = random(4, 34) * (random() < 0.08 ? 2.6 : 1);

    push();
    translate(x, y);
    rotate(random(-0.55, 0.55));
    fill(c[0], c[1], c[2], random(2, 11) * (1 - lower * 0.72));
    ellipse(0, 0, size * random(1.2, 3.4), size * random(0.25, 0.85));
    pop();
  }

  for (let i = 0; i < 250; i++) {
    const a = random(TWO_PI);
    const r = sqrt(random()) * 0.87;
    const edge = formPoint(a);
    let x = 780 + (edge.x - 780) * r;
    let y = 795 + (edge.y - 795) * r;
    const c = pigments[floor(random(5))];
    const steps = floor(random(10, 42));
    const weight = random(0.5, 2.5);

    for (let j = 0; j < steps; j++) {
      const oldX = x;
      const oldY = y;
      const angle = -HALF_PI
        + 0.75 * sin((x - 780) / 230)
        + (noise(x * 0.0024, y * 0.0024) - 0.5) * 2.7;
      const step = random(5, 10);
      x += cos(angle) * step;
      y += sin(angle) * step;

      const test = sq((x - 780) / 365) + sq((y - 795) / 500);
      if (test > 0.93 || y > 1210) break;

      stroke(c[0], c[1], c[2], random(4, 17));
      strokeWeight(weight);
      line(oldX, oldY, x, y);
    }
  }

  for (let i = 0; i < 85; i++) {
    const x = random(510, 1050);
    const y = random(420, 1080);
    if (sq((x - 780) / 350) + sq((y - 795) / 485) > 0.8) continue;

    stroke(213, 201, 172, random(2, 7));
    strokeWeight(random(6, 24));
    noFill();
    bezier(
      x, y,
      x + random(-90, 90), y - random(30, 130),
      x + random(-100, 100), y - random(90, 210),
      x + random(-70, 70), y - random(150, 260)
    );
  }
}

function paintUnbinding() {
  const colors = [
    [190, 181, 153],
    [139, 157, 163],
    [172, 128, 86],
    [105, 113, 119]
  ];

  for (let i = 0; i < 370; i++) {
    const a = random(0.025, PI - 0.025);
    const start = formPoint(a, random(-13, 16));
    if (start.y < 930 && random() < 0.62) continue;

    const length = random(100, 640) * (0.72 + 0.28 * sin(a));
    const drift = cos(a) * random(55, 270) + random(-95, 95);
    const phase = random(TWO_PI);
    const c = colors[floor(random(colors.length))];
    const weight = random(0.45, 2.1);
    const steps = 38;

    const position = (t) => ({
      x: start.x
        + drift * t
        + sin(t * 5.5 + phase) * 38 * t
        + (noise(start.x * 0.004 + t * 1.7, phase) - 0.5) * 55 * t,
      y: start.y + length * t + sin(t * PI) * 18 * sin(phase)
    });

    for (let j = 0; j < steps; j++) {
      const t0 = j / steps;
      const t1 = (j + 1) / steps;
      if (random() < 0.08 + t0 * 0.43) continue;

      const p0 = position(t0);
      const p1 = position(t1);
      stroke(c[0], c[1], c[2], random(8, 38) * pow(1 - t0, 1.25));
      strokeWeight(max(0.2, weight * (1 - t0 * 0.82)));
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }

  for (let i = 0; i < 5100; i++) {
    const a = random(0, PI);
    const start = formPoint(a, random(-35, 35));
    const t = pow(random(), 0.72);
    const reach = random(120, 690);
    const spread = (
      cos(a) * random(35, 245) +
      randomGaussian(0, 45 + 125 * t)
    ) * t;

    const x = start.x + spread + sin(t * 7 + a * 3) * 28 * t;
    const y = start.y + reach * t;

    if (x < 45 || x > width - 45 || y < 0 || y > 1930) continue;
    if (random() > 0.28 + 0.72 * (1 - t)) continue;

    const c = colors[floor(random(colors.length))];
    stroke(c[0], c[1], c[2], random(6, 48) * pow(1 - t, 1.1));
    strokeWeight(random(0.4, 2.2) * (1 - 0.5 * t));
    point(x, y);
  }
}

function paintMembrane() {
  const bone = [218, 208, 180];
  const ash = [155, 176, 181];
  const ochre = [190, 145, 99];
  const gray = [105, 117, 126];

  for (let i = 0; i < 2250; i++) {
    const a = random(-PI, PI);
    const lower = max(0, sin(a));
    if (random() < pow(lower, 1.35) * 0.94) continue;

    const offset = randomGaussian(0, 7 + lower * 15);
    let span = random(0.008, 0.052);
    if (random() < 0.055) span *= 3.2;

    const p = formPoint(a, offset);
    let c = bone;
    const choice = random();
    if (choice < 0.24) c = ash;
    else if (choice < 0.39) c = ochre;
    else if (choice < 0.52) c = gray;

    const broad = random() < 0.055;
    stroke(
      c[0],
      c[1],
      c[2],
      random(16, 80) * (1 - lower * 0.82) * (broad ? 0.22 : 1)
    );
    strokeWeight(broad ? random(4, 12) : random(0.45, 2.5));
    noFill();

    beginShape();
    for (let j = 0; j <= 5; j++) {
      const q = formPoint(a + span * (j / 5), offset);
      vertex(q.x, q.y);
    }
    endShape();
  }

  for (let i = 0; i < 420; i++) {
    const a = random(TWO_PI);
    const lower = max(0, sin(a));
    if (random() < lower * 0.8) continue;
    const p = formPoint(a, randomGaussian(0, 24));
    stroke(205, 197, 172, random(5, 31) * (1 - lower));
    strokeWeight(random(0.4, 1.7));
    point(p.x, p.y);
  }
}

function paintSediment() {
  for (let i = 0; i < 620; i++) {
    const y = random(1420, 1870);
    const depth = (y - 1420) / 450;
    const x = randomGaussian(785, 175 + depth * 285);
    if (x < 30 || x > width - 30) continue;

    const w = random(4, 78) * (0.45 + depth);
    const warm = random() < 0.7;
    if (warm) stroke(137, 117, 90, random(2, 10));
    else stroke(105, 126, 134, random(2, 8));

    strokeWeight(random(0.4, 2.2));
    line(x - w / 2, y, x + w / 2, y + random(-1.2, 1.2));
  }

  noStroke();
  for (let i = 0; i < 45; i++) {
    fill(5, 8, 12, 1.4);
    rect(0, 1500 + i * 11, width, 13);
  }
}

function paintGrain() {
