const FORM_TOP = 430;
const FORM_BOTTOM = 1600;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255);
  noLoop();
  smooth();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  paintGround();

  softWash(800, 1030, 730, 910, [82, 101, 96], 110, 0.8);
  softWash(850, 990, 520, 740, [137, 120, 84], 90, 0.72);

  paintCurrents();
  paintReleased();

  softWash(800, 1060, 330, 615, [9, 14, 17], 105, 1.65);

  paintVessel();
  paintFragments();
  paintReturn();
  paintSurface();
}

function paintGround() {
  const upper = color(16, 24, 29);
  const middle = color(29, 34, 33);
  const lower = color(35, 27, 23);

  noStroke();
  for (let y = 0; y < height; y += 8) {
    const t = y / height;
    const c = t < 0.58
      ? lerpColor(upper, middle, t / 0.58)
      : lerpColor(middle, lower, (t - 0.58) / 0.42);
    fill(c);
    rect(0, y, width, 9);
  }

  const groundColors = [
    [80, 96, 94],
    [112, 102, 77],
    [46, 64, 69],
    [129, 117, 91],
    [26, 31, 33]
  ];

  noFill();
  for (let i = 0; i < 1700; i++) {
    const x = random(-180, width);
    const y = random(height);
    const len = random(70, 570);
    const bend = random(-32, 32);
    const c = groundColors[floor(random(groundColors.length))];

    stroke(c[0], c[1], c[2], random(2.5, 10));
    strokeWeight(random(2, 19));
    bezier(
      x, y,
      x + len * 0.33, y + bend,
      x + len * 0.68, y - bend * 0.45,
      x + len, y + random(-13, 13)
    );
  }

  for (let i = 0; i < 6500; i++) {
    const x = random(width);
    const y = random(height);
    const c = groundColors[floor(random(groundColors.length))];
    stroke(c[0], c[1], c[2], random(3, 12));
    strokeWeight(random(0.4, 1.5));
    line(x, y, x + random(2, 15), y + random(-2, 2));
  }
}

function softWash(cx, cy, rx, ry, c, layers, alpha) {
  noStroke();
  for (let i = layers; i > 0; i--) {
    const t = i / layers;
    fill(c[0], c[1], c[2], alpha);
    ellipse(cx, cy, rx * 2 * t, ry * 2 * t);
  }
}

function paintCurrents() {
  const colors = [
    [130, 141, 127],
    [155, 135, 96],
    [86, 111, 111],
    [183, 172, 137]
  ];

  noFill();
  for (let j = 0; j < 190; j++) {
    const y0 = map(j, 0, 189, -40, 2040) + random(-8, 8);
    const c = colors[floor(random(colors.length))];
    const centrality = 1 - constrain(abs(y0 - 1030) / 1100, 0, 1);

    stroke(c[0], c[1], c[2], random(4, 11) + centrality * 7);
    strokeWeight(random(0.45, 1.35));
    beginShape();

    for (let x = -50; x <= 1650; x += 20) {
      const dx = x - 800;
      const dy = y0 - 1030;
      const g = exp(-(dx * dx) / 250000 - (dy * dy) / 650000);
      const n = noise(x * 0.0018 + 3, y0 * 0.002) - 0.5;
      const y = y0 + n * 29 + 92 * g * sin(dy * 0.004);
      vertex(x, y);
    }
    endShape();
  }
}

function vesselWidth(y) {
  const t = constrain(
    (FORM_BOTTOM - y) / (FORM_BOTTOM - FORM_TOP),
    0,
    1
  );
  return 42 + 320 * pow(max(0, sin(PI * t * 0.88)), 0.8);
}

function paintReleased() {
  const palette = fiberPalette();

  noFill();
  for (let i = 0; i < 195; i++) {
    const y0 = random(450, 880);
    const side = random() < 0.5 ? -1 : 1;
    const q = random(0.7, 1.04);
    const x0 = 800 + side * q * vesselWidth(y0);
    const len = random(220, 770);
    const drift = side * random(40, 285) + random(-65, 65);
    const sway = random(-120, 120);
    const c = palette[floor(random(palette.length))];
    const baseAlpha = random(11, 40);
    const baseWeight = random(0.45, 1.65);

    let px = x0;
    let py = y0;

    for (let j = 1; j <= 46; j++) {
      const t = j / 46;
      const x = x0
        + drift * pow(t, 1.15)
        + sway * sin(PI * t)
        + 14 * (noise(i * 0.17, t * 2.4) - 0.5) * t;
      const y = y0 - len * t + 20 * sin(PI * t);

      stroke(c[0], c[1], c[2], baseAlpha * pow(1 - t, 1.3));
      strokeWeight(baseWeight * (1 - 0.55 * t));
      line(px, py, x, y);
      px = x;
      py = y;
    }
  }

  for (let i = 0; i < 520; i++) {
    const y = random(65, 960);
    const spread = map(y, 65, 960, 560, 130);
    const x = 800 + randomGaussian() * spread * 0.48;
    if (x < 0 || x > width) continue;

    const c = palette[floor(random(palette.length))];
    const fade = map(y, 65, 960, 0.25, 1);
    stroke(c[0], c[1], c[2], random(3, 17) * fade);
    strokeWeight(random(0.4, 1.25));
    line(x, y, x + random(-4, 4), y - random(1, 8));
  }
}

function fiberPalette() {
  return [
    [199, 192, 161],
    [177, 181, 158],
    [126, 151, 145],
    [158, 126, 82],
    [91, 113, 112],
    [215, 199, 158]
  ];
}

function paintVessel() {
  const palette = fiberPalette();

  for (let i = 0; i < 410; i++) {
    const side = random() < 0.5 ? -1 : 1;
    const q = random(0.52, 1.045);
    const yStart = FORM_BOTTOM + random(-60, 115);
    let yEnd = FORM_TOP + random(-45, 270);
    if (random() < 0.18) yEnd += random(120, 290);

    let c = palette[floor(random(palette.length))];
    if (side < 0 && random() < 0.48) c = palette[4];
    if (side > 0 && random() < 0.42) c = palette[0];

    let baseAlpha = random(17, 57);
    if (q > 0.93) baseAlpha *= 1.35;
    baseAlpha *= side > 0 ? 1.08 : 0.86;

    let baseWeight = random(0.45, 1.8);
    if (random() < 0.08) {
      baseWeight = random(2.2, 4.1);
      baseAlpha *= 0.34;
    }

    const phase = random(1000);
    const steps = 92;
    let started = false;
    let px = 0;
    let py = 0;

    for (let j = 0; j <= steps; j++) {
      const p = j / steps;
      const y = lerp(yStart, yEnd, p);
      const qq = q + 0.04 * (noise(phase, y * 0.004) - 0.5);
      const waver = 15 * (noise(phase + 20, y * 0.003) - 0.5)
        + 5 * sin(y * 0.008 + phase);
      const x = 800 + side * qq * vesselWidth(y) + waver;

      if (started && random() > 0.045) {
        const a = baseAlpha
          * (1 - 0.72 * p)
          * (0.65 + 0.35 * sin(PI * p))
          * random(0.65, 1);
        stroke(c[0], c[1], c[2], a);
        strokeWeight(baseWeight * random(0.75, 1.15));
        line(px, py, x, y);
      }

      px = x;
      py = y;
      started = true;
    }
  }

  noFill();
  for (let i = 0; i < 185; i++) {
    const y = random(520, 1545);
    const side = random() < 0.5 ? -1 : 1;
    const w = vesselWidth(y);
    const x1 = 800 + side * w * random(0.5, 0.7);
    const x2 = 800 + side * w * random(0.88, 1.03);
    const c = palette[floor(random(palette.length))];

    stroke(c[0], c[1], c[2], random(5, 20));
    strokeWeight(random(0.4, 1.05));
    bezier(
      x1, y,
      x1 + side * 25, y - 18,
      x2 - side * 18, y + 22,
      x2, y + random(-20, 20)
    );
  }
}

function paintFragments() {
  const palette = fiberPalette();

  for (let i = 0; i < 370; i++) {
    const y = random(470, 1510);
    const likelihood = map(y, FORM_TOP, FORM_BOTTOM, 0.95, 0.25);
    if (random() > likelihood) continue;

    const side = random() < 0.5 ? -1 : 1;
    const distance = vesselWidth(y) + pow(random(), 2) * 155;
    const x = 800 + side * distance + random(-10, 10);
    const len = random(2, 15);
    const c = palette[floor(random(palette.length))];

    stroke(c[0], c[1], c[2], random(5, 27));
    strokeWeight(random(0.45, 1.35));
    line(
      x, y,
      x + side * len * random(0.25, 0.8),
      y - len * random(0.35, 1)
    );
  }
}

function paintReturn() {
  const palette = fiberPalette();

  noFill();
  for (let i = 0; i < 430; i++) {
    const x = random(-50, 1650);
    const y = random(1620, 2040);
    const len = random(30, 260);
    const c = random() < 0.55 ? palette[3] : palette[2];

    stroke(c[0], c[1], c[2], random(3, 13));
    strokeWeight(random(0.6, 3.2));
    bezier(
      x, y,
      x + len * 0.3, y + random(-12, 12),
      x + len * 0.7, y + random(-12, 12),
      x + len, y + random(-6, 6)
    );
  }

  for (let i = 0; i < 135; i++) {
    const x0 = 800 + randomGaussian() * 52;
    const y0 = random(1490, 1635);
    const x3 = 800 + randomGaussian() * 310;
    const y3 = random(1740, 2070);
    const x1 = x0 + random(-105, 105);
    const y1 = y0 + random(60, 175);
    const x2 = x3 + random(-85, 85);
    const y2 = y3 - random(40, 145);
    const c = palette[floor(random(palette.length))];
    const baseAlpha = random(8, 32);
    const baseWeight = random(0.45, 1.55);

    let px = x0;
    let py = y0;

    for (let j = 1; j <= 38; j++) {
      const t = j / 38;
      const u = 1 - t;
      const x = u * u * u * x0
        + 3 * u * u * t * x1
        + 3 * u * t * t * x2
        + t * t * t * x3;
      const y = u * u * u * y0
        + 3 * u * u * t * y1
        + 3 * u * t * t * y2
        + t * t * t * y3;

      stroke(c[0], c[1], c[2], baseAlpha * pow(1 - t, 0.8));
      strokeWeight(baseWeight * (1 - 0.45 * t));
      line(px, py, x, y);
      px = x;
      py = y;
    }
  }
}

function paintSurface() {
  for (let i = 0; i < 15000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.5) {
      stroke(225, 218, 195, random(1.5, 5.5));
    } else {
      stroke(0, 0, 0, random(2, 6));
    }
    strokeWeight(random(0.35, 0.9));
    point(x, y);
  }

  for (let i = 0; i < 900; i++) {
    const x = random(width);
    const y = random(height);
    stroke(210, 204, 183, random(1.5, 4));
    strokeWeight(random(0.3, 0.65));
    line(x, y, x + random(4, 24), y + random(-1, 1));
  }
}

const C = { x: 800, y: 1030, rx: 350, ry: 515 };

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  noLoop();

  paintGround();
  paintCurrents();
  paintAbsence();
  paintVignette();
}

function paintGround() {
  const top = color(8, 16, 25);
  const middle = color(20, 29, 35);
  const bottom = color(28, 21, 24);

  for (let y = 0; y <= height; y += 3) {
    let c;
    if (y < 1040) {
      c = lerpColor(top, middle, y / 1040);
    } else {
      c = lerpColor(middle, bottom, (y - 1040) / 960);
    }
    stroke(c);
    strokeWeight(3);
    line(0, y, width, y);
  }

  const ctx = drawingContext;
  let glow = ctx.createRadialGradient(
    735, 1060, 40,
    770, 1050, 1090
  );
  glow.addColorStop(0, "rgba(100,79,65,0.20)");
  glow.addColorStop(0.38, "rgba(60,70,70,0.15)");
  glow.addColorStop(0.74, "rgba(28,48,58,0.08)");
  glow.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, width, height);

  const grainColors = [
    [116, 119, 113],
    [150, 128, 103],
    [61, 87, 98],
    [184, 164, 130],
    [39, 57, 69]
  ];

  for (let i = 0; i < 34000; i++) {
    const x = random(-20, width + 20);
    const y = random(-20, height + 20);
    const dx = (x - C.x) / 405;
    const dy = (y - C.y) / 590;

    if (dx * dx + dy * dy < 1) continue;

    const c = grainColors[floor(random(grainColors.length))];
    const n = noise(x * 0.003, y * 0.003);
    const len = random(1, 10) * (0.5 + n);

    stroke(c[0], c[1], c[2], random(3, 13));
    strokeWeight(random(0.35, 1.25));
    line(x, y, x + random(-2.5, 2.5), y + len);
  }

  for (let i = 0; i < 850; i++) {
    const x = random(width);
    const y = random(height);
    const dx = (x - C.x) / 430;
    const dy = (y - C.y) / 620;

    if (dx * dx + dy * dy < 1) continue;

    const warm = random() < 0.35;
    stroke(
      warm ? 174 : 102,
      warm ? 142 : 128,
      warm ? 103 : 130,
      random(4, 11)
    );
    strokeWeight(random(0.5, 1.4));
    line(x, y, x + random(-12, 12), y + random(8, 38));
  }
}

function paintCurrents() {
  const families = [
    [
      [58, 83, 99],
      [139, 163, 156],
      [72, 99, 103]
    ],
    [
      [88, 103, 109],
      [220, 201, 163],
      [153, 116, 89]
    ],
    [
      [76, 87, 96],
      [181, 137, 101],
      [190, 119, 76]
    ],
    [
      [53, 78, 104],
      [106, 137, 148],
      [82, 85, 98]
    ]
  ];

  const currents = [];
  const count = 248;

  for (let i = 0; i < count; i++) {
    const r = random();
    let family;
    let alpha;

    if (r < 0.40) {
      family = 0;
      alpha = random(35, 88);
    } else if (r < 0.64) {
      family = 1;
      alpha = random(48, 116);
    } else if (r < 0.78) {
      family = 2;
      alpha = random(38, 94);
    } else {
      family = 3;
      alpha = random(32, 80);
    }

    currents.push({
      base: map(i, 0, count - 1, -130, 1730) + random(-3.4, 3.4),
      phase: random(0, 40),
      family: family,
      alpha: alpha,
      weight: random(0.55, 1.85) + (random() < 0.08 ? random(0.8, 1.8) : 0)
    });
  }

  noFill();

  for (let i = 0; i < currents.length; i += 7) {
    const q = currents[i];
    const c = families[q.family][1];

    stroke(c[0], c[1], c[2], 5);
    strokeWeight(q.weight * 8 + 5);
    beginShape();
    for (let y = -60; y <= height + 60; y += 26) {
      const p = flowPoint(q.base, y, q.phase);
      vertex(p.x, p.y);
    }
    endShape();
  }

  for (const q of currents) {
    let previous = flowPoint(q.base, -60, q.phase);

    for (let y = -46; y <= height + 60; y += 14) {
      const p = flowPoint(q.base, y, q.phase);
      const dry = noise(q.base * 0.012, y * 0.009, q.phase);

      if (dry > 0.075) {
        const c = currentColor(y, families[q.family]);
        const energy = exp(-pow((y - C.y) / 880, 2));
        const variation = 0.58 + 0.58 * noise(
          q.base * 0.006,
          y * 0.004,
          q.phase + 12
        );
        const a = q.alpha * (0.42 + 0.80 * energy) * variation;

        stroke(c[0], c[1], c[2], a);
        strokeWeight(
          q.weight * (0.82 + 0.34 * noise(y * 0.006, q.phase))
        );
        line(previous.x, previous.y, p.x, p.y);
      }

      previous = p;
    }
  }
}

function flowPoint(baseX, y, phase) {
  const d = baseX - C.x;
  const side = d < 0 ? -1 : 1;
  const u = (y - C.y) / C.ry;
  let radius = 0;

  if (abs(u) < 1) {
    radius = C.rx * pow(max(0, 1 - u * u), 0.58);
  }

  const radial = sqrt(d * d + radius * radius);
  let x = C.x + side * radial;

  const clearance = radial - radius;
  const freedom = constrain(clearance / 95, 0, 1);

  const slowDrift =
    24 * sin(y * 0.0016 + baseX * 0.0023 + phase);
  const smallDrift =
    24 * (noise(baseX * 0.004 + 10, y * 0.0022, phase) - 0.5);

  x += (slowDrift + smallDrift) * freedom;

  return { x: x, y: y };
}

function currentColor(y, family) {
  if (y < C.y) {
    let t = constrain(y / C.y, 0, 1);
    t = t * t * (3 - 2 * t);
    return mixColor(family[0], family[1], t);
  } else {
    let t = constrain((y - C.y) / (height - C.y), 0, 1);
    t = t * t * (3 - 2 * t);
    return mixColor(family[1], family[2], t);
  }
}

function mixColor(a, b, t) {
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function paintAbsence() {
  const ctx = drawingContext;

  ctx.save();
  ctx.translate(C.x, C.y);
  ctx.scale(1, C.ry / C.rx);

  const radius = C.rx * 1.22;
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, radius);

  g.addColorStop(0, "rgba(5,10,16,1)");
  g.addColorStop(0.70, "rgba(5,10,16,1)");
  g.addColorStop(0.83, "rgba(6,11,17,0.98)");
  g.addColorStop(1, "rgba(6,11,17,0)");

  ctx.fillStyle = g;
  ctx.fillRect(-radius, -radius, radius * 2, radius * 2);
  ctx.restore();
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(
    800, 970, 460,
    800, 1000, 1220
  );

  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(0.66, "rgba(0,0,0,0.04)");
  g.addColorStop(0.86, "rgba(0,0,0,0.20)");
  g.addColorStop(1, "rgba(0,0,0,0.52)");

  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  angleMode(RADIANS);
  background(9, 12, 18);

  paintGround();
  paintField();
  paintUnderweave();
  paintFibres();
  paintFragments();
  paintVignette();
  paintGrain();
}

function paintGround() {
  const top = color(8, 12, 19);
  const middle = color(17, 19, 24);
  const bottom = color(25, 18, 19);

  noStroke();
  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    let c;
    if (t < 0.56) {
      c = lerpColor(top, middle, t / 0.56);
    } else {
      c = lerpColor(middle, bottom, (t - 0.56) / 0.44);
    }
    fill(c);
    rect(0, y, W, 5);
  }

  for (let i = 0; i < 620; i++) {
    const x = random(-100, W + 100);
    const y = random(-100, H + 100);
    const r = random(70, 310);
    if (random() < 0.52) {
      fill(39, 46, 59, random(1, 4));
    } else {
      fill(70, 45, 38, random(1, 3.5));
    }
    ellipse(x, y, r * random(1.1, 2.8), r * random(0.45, 1.15));
  }

  const ctx = drawingContext;
  const halo = ctx.createRadialGradient(790, 920, 60, 790, 920, 900);
  halo.addColorStop(0, "rgba(123,101,76,0.15)");
  halo.addColorStop(0.42, "rgba(74,71,68,0.075)");
  halo.addColorStop(1, "rgba(0,0,0,0)");
  ctx.save();
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function paintField() {
  for (let i = 0; i < 10800; i++) {
    const x = random(-20, W + 20);
    const y = random(-20, H + 20);
    const n = noise(x * 0.0015, y * 0.0015, 8.2);
    const a = HALF_PI + (n - 0.5) * 2.5;
    const len = random(2, 17);

    if (n < 0.5) {
      stroke(85, 96, 108, random(2, 8));
    } else {
      stroke(111, 96, 81, random(2, 7));
    }

    strokeWeight(random(0.35, 1.05));
    line(
      x - cos(a) * len * 0.5,
      y - sin(a) * len * 0.5,
      x + cos(a) * len * 0.5,
      y + sin(a) * len * 0.5
    );
  }
}

function pigment() {
  const r = random();
  if (r < 0.28) return [198, 190, 168];
  if (r < 0.48) return [144, 157, 157];
  if (r < 0.64) return [108, 128, 139];
  if (r < 0.80) return [173, 137, 91];
  if (r < 0.92) return [139, 79, 62];
  return [220, 211, 184];
}

function formPoint(t, u, phase = 0, sway = 0, drift = 0) {
  const tt = constrain(t, 0, 1);
  const s = max(0, sin(PI * pow(tt, 0.9)));
  const envelope = 22 + 400 * pow(s, 0.72);
  const q = pow(constrain((t - 0.5) / 0.6, 0, 1), 1.35);
  const center = 790 + 62 * sin(tt * PI * 1.35 - 0.65) - 55 * tt;

  let x = center + u * envelope;
  x += sin(t * 10.5 + phase) * sway * (0.25 + 0.75 * s);
  x += (noise(u * 2.7 + 20, t * 2.5, phase * 0.03) - 0.5) * 20 * s;
  x += q * q * (u * 180 + drift * 240);
  x += q * 35 * sin(phase + t * 17);

  const y = 285 + t * 1260 + sin(phase + t * 8) * 7 + q * q * drift * 130;
  return { x, y, q };
}

function paintUnderweave() {
  push();
  blendMode(SCREEN);
  noStroke();

  for (let i = 0; i < 380; i++) {
    const t = random(0.04, 1.0);
    const u = random(-1, 1);
    const p = formPoint(
      t,
      u,
      random(TWO_PI),
      random(5, 25),
      random(-1, 1)
    );
    const c = pigment();
    fill(c[0], c[1], c[2], random(1.2, 4.5));

    push();
    translate(p.x, p.y);
    rotate(random(-0.16, 0.16));
    ellipse(0, 0, random(35, 130), random(75, 210));
    pop();
  }

  pop();
}

function paintFibres() {
  for (let i = 0; i < 1180; i++) {
    let u = random(-1, 1);
    if (random() < 0.36) {
      u = (random() < 0.5 ? -1 : 1) * random(0.55, 1);
    }
    const boost = random() < 0.12 ? 1.75 : 1;
    fibre(u, boost);
  }

  for (let i = 0; i < 170; i++) {
    const side = i % 2 === 0 ? -1 : 1;
    fibre(side * random(0.9, 1.035), 1.35);
  }
}

function fibre(u, boost) {
  const phase = random(TWO_PI);
  const sway = random(3, 20);
  const drift = random(-1, 1);
  const start = random(-0.02, 0.1);
  const end = random(0.8, 1.14);
  const steps = 132;
  const c = pigment();
  const baseAlpha = random(18, 48) * boost;
  let weight = random(0.45, 1.18) * (boost > 1 ? 1.12 : 1);

  if (boost > 1.5) {
    weight = random(0.9, 1.75);
  }

  let previous = null;

  for (let j = 0; j <= steps; j++) {
    const t = lerp(start, end, j / steps);
    if (t < 0) {
      previous = null;
      continue;
    }

    const breakup = constrain((t - 0.5) / 0.62, 0, 1);
    const gap = 0.012 + pow(breakup, 1.55) * 0.88;

    if (random() < gap) {
      previous = null;
      continue;
    }

    const p = formPoint(t, u, phase, sway, drift);

    if (previous) {
      const modulation = 0.7 + 0.5 * noise(u * 5 + 40, t * 6, phase);
      let a = baseAlpha * (1 - 0.78 * breakup) * modulation;
      if (abs(u) < 0.18) a *= 0.7;

      stroke(c[0], c[1], c[2], a);
      strokeWeight(weight * (0.75 + 0.35 * noise(t * 8, phase)));
      line(previous.x, previous.y, p.x, p.y);
    }

    previous = p;
  }
}

function paintFragments() {
  for (let i = 0; i < 3600; i++) {
    const t = random(0.55, 1.2);
    const u = random(-1.1, 1.1);
    const drift = random(-1, 1);
    const p = formPoint(t, u, random(TWO_PI), random(4, 30), drift);
    const fade = 1 - constrain((t - 0.58) / 0.72, 0, 1);
    const c = pigment();
    const len = random(1, 7);

    stroke(c[0], c[1], c[2], random(8, 44) * fade);
    strokeWeight(random(0.4, 1.8));
    line(
      p.x,
      p.y,
      p.x + random(-3, 3) + drift * len,
      p.y + len
    );
  }

  for (let i = 0; i < 300; i++) {
    const x = randomGaussian(790, 350);
    const y = randomGaussian(1480, 250);
    if (x < 0 || x > W || y < 0 || y > H) continue;

    const c = pigment();
    stroke(c[0], c[1], c[2], random(3, 15));
    strokeWeight(random(0.4, 1.2));
    point(x, y);
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const vignette = ctx.createRadialGradient(
    W * 0.5,
    H * 0.48,
    480,
    W * 0.5,
    H * 0.48,
    1250
  );
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.62, "rgba(0,0,0,0.05)");
  vignette.addColorStop(1, "rgba(0,0,0,0.48)");

  ctx.save();
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function paintGrain() {
  for (let i = 0; i < 26000; i++) {
    const x = random(W);
    const y = random(H);

    if (random() < 0.48) {
      stroke(225, 218, 199, random(1, 4));
    } else {
      stroke(0, 0, 0, random(2, 7));
    }

    strokeWeight(random(0.3, 0.8));
    if (random() < 0.75) {
      point(x, y);
    } else {
      line(x, y, x + random(-1.5, 1.5), y + random(0.5, 2.5));
    }
  }
}

// The Last Coherence — a figure mid-dissolution:
// ash falls, sparks rise, the heart is the last thing holding.

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

const HEART = { x: 800, y: 1010 };

function draw() {
  background(10, 11, 16);

  paintGround();      // dark painterly field
  paintAtmosphere();  // soft glows
  paintStars();       // the far field of the dead / unborn
  paintHalo();        // broken ring around the heart

  blendMode(BLEND);
  paintAsh();         // what falls
  paintSettling();    // the bank below

  blendMode(ADD);
  paintPlume();       // breath leaving
  paintFigure();      // the last coherent body
  paintSparks();      // what rises
  paintHeart();       // the ember
  paintSeeds();       // what death feeds

  blendMode(BLEND);
  paintVignette();
  paintGrain();
}

/* ---------- helpers ---------- */

function radialGlow(x, y, r, cr, cg, cb, a) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, "rgba(" + cr + "," + cg + "," + cb + "," + a + ")");
  g.addColorStop(1, "rgba(" + cr + "," + cg + "," + cb + ",0)");
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function sampleSeg(x1, y1, x2, y2, w1, w2) {
  const t = random();
  const x = lerp(x1, x2, t), y = lerp(y1, y2, t);
  const w = lerp(w1, w2, t);
  const dx = x2 - x1, dy = y2 - y1;
  const L = sqrt(dx * dx + dy * dy) || 1;
  const off = (random() + random() - 1) * w * 0.7;
  return { x: x + (-dy / L) * off, y: y + (dx / L) * off };
}

function samplePrim(pr) {
  if (pr.circle) {
    const a = random(TWO_PI);
    const rr = sqrt(random());
    return { x: pr.x + cos(a) * pr.rx * rr, y: pr.y + sin(a) * pr.ry * rr };
  }
  return sampleSeg(pr.x1, pr.y1, pr.x2, pr.y2, pr.w1, pr.w2);
}

/* ---------- the field ---------- */

function groundColor(x, y) {
  const n1 = noise(x * 0.0012, y * 0.0012);
  const n2 = noise(x * 0.004 + 40, y * 0.004 + 40);
  const warm = constrain((y / height) * 1.3 - 0.18, 0, 1);
  const m = n1 * 0.72 + warm * 0.28;
  let r = lerp(10, 30, m);
  let g = lerp(14, 21, m);
  let b = lerp(26, 15, m);
  const t = noise(x * 0.0021 + 200, y * 0.0021 + 200);
  if (t > 0.6) {
    const k = (t - 0.6) * 1.4;
    r -= 4 * k; g += 6 * k; b += 6 * k;
  }
  const aura = constrain(1 - dist(x, y, 800, 1040) / 620, 0, 1) * 0.55;
  r += aura * 16; g += aura * 14; b += aura * 11;
  r += (n2 - 0.5) * 7; g += (n2 - 0.5) * 6; b += (n2 - 0.5) * 6;
  return [r, g, b];
}

function paintGround() {
  noStroke();
  for (let i = 0; i < 3200; i++) { // glazes
    const x = random(width), y = random(height);
    const r = 30 + random(80);
    const c = groundColor(x, y);
    fill(c[0], c[1], c[2], 8);
    ellipse(x, y, r * 2, r * 1.35);
  }
  for (let i = 0; i < 9000; i++) { // scumble
    const x = random(width), y = random(height);
    const a = noise(x * 0.0011, y * 0.0011 + 100) * TWO_PI + random(-0.6, 0.6);
    const l = 14 + random(42);
    const c = groundColor(x, y);
    const lift = random() < 0.5 ? 9 : -6;
    stroke(c[0] + lift, c[1] + lift, c[2] + lift * 0.8, 11);
    strokeWeight(0.8 + random(2));
    line(x - cos(a) * l * 0.5, y - sin(a) * l * 0.5,
         x + cos(a) * l * 0.5, y + sin(a) * l * 0.5);
  }
  noStroke();
}

function paintAtmosphere() {
  blendMode(ADD);
  radialGlow(800, 250, 950, 24, 32, 50, 0.5);   // cool, above
  radialGlow(800, 1030, 480, 62, 38, 16, 0.5);  // warmth around the body
  radialGlow(800, 1810, 760, 40, 24, 12, 0.45); // the warm dark below
  blendMode(BLEND);
}

function paintStars() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 850; i++) {
    const y = pow(random(), 1.8) * 1500;
    const x = random(width);
    const s = random();
    const a = (14 + 70 * pow(random(), 2.2)) * (1 - y / 2200);
    fill(190 + s * 45, 200 + s * 28, 214 + s * 20, a);
    ellipse(x, y, 1 + s * 1.8, 1 + s * 1.8);
  }
  for (let i = 0; i < 620; i++) { // faint drifting band
    const t = random();
    const bx = lerp(260, 1340, t), by = lerp(150, 640, t);
    const off = (random() + random() - 1) * 150;
    fill(196, 204, 222, random(8, 30));
    ellipse(bx + off * 0.75, by - off * 0.6, 1.3, 1.3);
  }
  for (let i = 0; i < 6; i++) { // a few bright ones
    const x = random(120, 1480);
    const y = pow(random(), 1.6) * 900;
    radialGlow(x, y, 16, 200, 210, 235, 0.4);
    fill(235, 240, 250, 230);
    ellipse(x, y, 2.2, 2.2);
  }
  blendMode(BLEND);
}

function paintHalo() {
  blendMode(ADD);
  noFill();
  strokeWeight(1.1);
  for (const rr of [312, 352]) {
    let a0 = random(TWO_PI);
    const segs = 3 + floor(random() * 2);
    for (let s = 0; s < segs; s++) {
      const span = random(0.5, 1.6);
      stroke(214, 188, 142, 11);
      arc(HEART.x, HEART.y, rr * 2, rr * 2, a0, a0 + span);
      a0 += span + random(0.25, 0.9);
    }
  }
  blendMode(BLEND);
}

/* ---------- what falls ---------- */

function ashSpawn() {
  const r = random();
  if (r < 0.4) return sampleSeg(800, 1200, 800, 1315, 86, 110);
  if (r < 0.7) return sampleSeg(766, 1320, 738, 1630, 46, 22);
  return sampleSeg(834, 1320, 862, 1630, 46, 22);
}

function paintAsh() {
  blendMode(BLEND);
  strokeCap(ROUND);
  strokeWeight(1.2);
  for (let i = 0; i < 620; i++) {
    const p = ashSpawn();
    let x = p.x + random(-10, 10), y = p.y + random(-10, 10);
    let vx = random(-10, 12), vy = random(8, 30);
    let al = random(26, 60);
    const steps = 3 + floor(random() * 4);
    for (let s = 0; s < steps; s++) {
      const na = noise(x * 0.0024, y * 0.0024 + 500) * TWO_PI * 2;
      vx = vx * 0.85 + cos(na) * 9;
      vy = vy * 0.85 + sin(na) * 9 + 5;
      const nx = x + vx, ny = y + vy;
      stroke(112, 98, 88, al);
      line(x, y, nx, ny);
      x = nx; y = ny;
      al *= 0.62;
      if (al < 5) break;
    }
  }
}

function paintSettling() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 520; i++) { // warm haze bank
    const t = random();
    const y = lerp(1560, 1980, pow(t, 0.8));
    const x = 800 + (random() + random() - 1) * (320 + (y - 1560) * 0.55);
    const r = 20 + random(55);
    fill(58, 42, 33, 10);
    ellipse(x, y, r * 2, r * 0.8);
  }
  for (let i = 0; i < 420; i++) { // motes
    const y = random(1620, 1990);
    const x = 800 + (random() + random() - 1) * (240 + (y - 1600) * 0.7);
    fill(105, 90, 78, random(10, 30));
    ellipse(x, y, random(1.5, 4.5), random(1.5, 4.5));
  }
}

/* ---------- the body ---------- */

function paintPlume() {
  noStroke();
  for (let i = 0; i < 300; i++) {
    const t = random();
    const y = 630 - t * random(430);
    const drift = (noise(t * 2.6 + 9.2, 3.7) - 0.5) * 300 * t;
    const x = 800 + drift + (random() + random() - 1) * (26 + t * 60);
    const r = 16 + t * 62;
    fill(212, 198, 178, 3.5);
    ellipse(x, y, r * 2, r * 1.25);
  }
}

function paintFigure() {
  const prims = [
    { circle: true, x: 800, y: 705, rx: 58, ry: 72, n: 980, coh: 0.62, alpha: 18, len: 7 },
    { x1: 800, y1: 775, x2: 800, y2: 832, w1: 34, w2: 30, n: 140, coh: 0.74, alpha: 16, len: 7 },
    { x1: 692, y1: 876, x2: 908, y2: 876, w1: 88, w2: 88, n: 800, coh: 0.9, alpha: 22, len: 9 },
    { x1: 800, y1: 898, x2: 800, y2: 1200, w1: 124, w2: 86, n: 2600, coh: 1, alpha: 23, len: 10 },
    { x1: 800, y1: 1200, x2: 800, y2: 1318, w1: 86, w2: 112, n: 720, coh: 0.8, alpha: 18, len: 9 },
    { x1: 766, y1: 1320, x2: 738, y2: 1632, w1: 46, w2: 22, n: 620, coh: 0.3, alpha: 9, len: 11 },
    { x1: 834, y1: 1320, x2: 862, y2: 1632, w1: 46, w2: 22, n: 620, coh: 0.3, alpha: 9, len: 11 },
    { x1: 710, y1: 896, x2: 672, y2: 1232, w1: 42, w2: 20, n: 560, coh: 0.55, alpha: 14, len: 9 },
    { x1: 890, y1: 896, x2: 928, y2: 1232, w1: 42, w2: 20, n: 560, coh: 0.55, alpha: 14, len: 9 },
  ];
  for (const pr of prims) {
    for (let i = 0; i < pr.n; i++) {
      const p = samplePrim(pr);
      const diss = 1 - pr.coh;
      const x = p.x + (random() + random() - 1) * 30 * diss;
      const y = p.y + (random() + random() - 1) * 30 * diss;

      let ang;
      if (pr.circle) {
        ang = atan2(y - pr.y, x - pr.x) + HALF_PI;
        if (random() < 0.3) ang += HALF_PI * (random() < 0.5 ? 1 : -1);
        ang += random(-0.45, 0.45);
      } else {
        ang = atan2(pr.y2 - pr.y1, pr.x2 - pr.x1) + random(-0.3, 0.3);
      }

      let r = 236, g = 220, b = 188;
      if (pr.coh < 0.55) {
        const k = constrain((0.55 - pr.coh) / 0.55, 0, 1) * 0.8;
        r = lerp(r, 152, k); g = lerp(g, 130, k); b = lerp(b, 110, k);
      }
      const hb = constrain(1 - dist(x, y, HEART.x, HEART.y) / 300, 0, 1);
      r = lerp(r, 255, hb * 0.45);
      g = lerp(g, 208, hb * 0.32);
      b = lerp(b, 168, hb * 0.25);
      if (random() < 0.05) { r = 226; g = 152; b = 92; } // ember flecks

      const v = random(-13, 13);
      const a = pr.alpha * random(0.55, 1.2) * lerp(1, 0.42, diss);
      const l = pr.len * random(0.5, 1.35);
      stroke(r + v, g + v, b + v * 0.8, a);
      strokeWeight(1.4 + random(1.3));
      line(x - cos(ang) * l, y - sin(ang) * l,
           x + cos(ang) * l, y + sin(ang) * l);
    }
  }
}

/* ---------- what rises ---------- */

function paintSparks() {
  strokeCap(ROUND);
  for (let i = 0; i < 980; i++) {
    const rsel = random();
    let p;
    if (rsel < 0.55) {
      const a = random(TWO_PI);
      const rr = sqrt(random());
      p = { x: 800 + cos(a) * 58 * rr, y: 705 + sin(a) * 72 * rr };
    } else if (rsel < 0.8) {
      p = sampleSeg(692, 876, 908, 876, 88, 88);
    } else {
      p = sampleSeg(800, 898, 800, 1040, 124, 100);
    }

    let x = p.x + random(-6, 6);
    let y = p.y + random(-6, 6);
    const longTrip = random() < 0.07;
    let vx = random(-14, 14) + (x - 800) * 0.06;
    let vy = -(random(16, 46) + (longTrip ? 40 : 0));
    const steps = (longTrip ? 7 : 3) + floor(random() * 6);
    let al = random(30, 120);
    strokeWeight(1.1 + random(0.8));

    for (let s = 0; s < steps; s++) {
      const na = noise(x * 0.0023, y * 0.0023, i * 0.017) * TWO_PI * 2;
      vx = vx * 0.84 + cos(na) * 15;
      vy = vy * 0.84 + sin(na) * 15 - 5;
      const nx = x + vx, ny = y + vy;
      const cool = constrain((760 - ny) / 700, 0, 1);
      stroke(lerp(230, 186, cool), lerp(218, 202, cool), lerp(198, 220, cool), al);
      line(x, y, nx, ny);
      x = nx; y = ny;
      al *= 0.74;
      if (al < 6) break;
    }

    // a few sparks are taken back as stars
    if (y < 560 && random() < 0.16) {
      radialGlow(x, y, 15, 210, 215, 235, 0.35);
      noStroke();
      fill(238, 242, 250, 220);
      ellipse(x, y, 2.1, 2.1);
      strokeWeight(1.1 + random(0.8));
    }
  }
}

/* ---------- the heart, the ember seeds ---------- */

function paintHeart() {
  radialGlow(HEART.x, HEART.y, 250, 185, 92, 38, 0.5);
  radialGlow(HEART.x, HEART.y, 95, 235, 135, 62, 0.8);
  noStroke();
  fill(255, 208, 140, 230);
  ellipse(HEART.x, HEART.y, 22, 22);
  fill(255, 246, 226, 255);
  ellipse(HEART.x, HEART.y, 10, 10);
  strokeWeight(1.5);
  for (let i = 0; i < 170; i++) { // ember brush
    const a = random(TWO_PI);
    const rr = pow(random(), 0.6) * 46;
    const x = HEART.x + cos(a) * rr;
    const y = HEART.y + sin(a) * rr * 0.9;
    const ang = a + random(-0.5, 0.5);
    const l = 2 + random(5);
    stroke(lerp(250, 214, random()), lerp(170, 120, random()),
           lerp(110, 70, random()), random(40, 110));
    line(x - cos(ang) * l, y - sin(ang) * l,
         x + cos(ang) * l, y + sin(ang) * l);
  }
}

function paintSeeds() {
  noStroke();
  for (let i = 0; i < 26; i++) { // buried warm points in the bank
    const y = random(1660, 1960);
    const x = 800 + (random() + random() - 1) * 420;
    const a = random(30, 90);
    radialGlow(x, y, 10, 190, 110, 50, (a / 255) * 0.5);
    fill(228, 148, 84, a);
    ellipse(x, y, 1.8, 1.8);
  }
}

/* ---------- unifying ---------- */

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 1010, 560, 800, 1010, 1520);
  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(0.72, "rgba(0,0,0,0.12)");
  g.addColorStop(1, "rgba(0,0,0,0.52)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  const t = ctx.createLinearGradient(0, 0, 0, 340);
  t.addColorStop(0, "rgba(0,0,0,0.3)");
  t.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = t;
  ctx.fillRect(0, 0, width, 340);
}

function paintGrain() {
  strokeWeight(1);
  for (let i = 0; i < 21000; i++) {
    const x = random(width), y = random(height);
    if (random() < 0.55) stroke(random(200, 255), 7);
    else stroke(random(0, 70), 7);
    point(x, y);
  }
}

// THE UNBINDING
// A self of warm pattern, quietly coming undone, returning to the dark
// field it was borrowed from. Still image. p5.js 1.11, 1600 x 2000.

const W = 1600, H = 2000, CX = 800;

// The body: a skeleton of light, a union of capsules.
const SPINE = [
  [800,  790, 138],   // shoulders
  [800,  900, 120],   // chest
  [800, 1000, 100],   // waist
  [800, 1090,  94],
  [800, 1180, 110],   // hips
  [800, 1255, 100]    // where the torso lets go
];
let PARTS = [];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  buildBody();
}

function draw() {
  paintField();    // the dark field that holds everything
  paintAura();     // warmth the pattern lends to the space around it
  blendMode(ADD);
  paintRing();     // a barely-there circle: the field permits a shape, briefly
  paintDormant();  // everything else, at rest
  paintGhost();    // faint ember underglow of the silhouette
  paintPlume();    // what has already come undone, falling and cooling
  paintBody();     // the self, still holding
  paintRising();   // the last warmth leaving upward
  vignette();
  grain();
}

function buildBody() {
  PARTS = [];
  PARTS.push({ ax: 800, ay: 568,  bx: 800, by: 568,  r0: 64, r1: 64 });  // head
  PARTS.push({ ax: 800, ay: 624,  bx: 800, by: 710,  r0: 30, r1: 31 });  // neck
  for (let i = 0; i < SPINE.length - 1; i++) {
    const a = SPINE[i], b = SPINE[i + 1];
    PARTS.push({ ax: a[0], ay: a[1], bx: b[0], by: b[1], r0: a[2], r1: b[2] });
  }
  for (let s = -1; s <= 1; s += 2) {
    PARTS.push({ ax: 800 + s * 128, ay: 782,  bx: 800 + s * 163, by: 990,  r0: 26, r1: 21 });
    PARTS.push({ ax: 800 + s * 163, ay: 990,  bx: 800 + s * 177, by: 1188, r0: 21, r1: 15 });
    PARTS.push({ ax: 800 + s * 177, ay: 1192, bx: 800 + s * 177, by: 1192, r0: 16, r1: 16 });
  }
}

function segDist(px, py, ax, ay, bx, by) {
  const vx = bx - ax, vy = by - ay;
  const wx = px - ax, wy = py - ay;
  const L = vx * vx + vy * vy || 1;
  const t = constrain((wx * vx + wy * vy) / L, 0, 1);
  return Math.hypot(wx - t * vx, wy - t * vy);
}

function bodyDepth(x, y) {          // > 0 inside the body; larger = deeper
  let best = -1e9;
  for (const p of PARTS) {
    const r = (p.r0 + p.r1) * 0.5;
    const d = r - segDist(x, y, p.ax, p.ay, p.bx, p.by);
    if (d > best) best = d;
  }
  return best;
}

function frontY(x) {                // the ragged line where coherence ends
  return 1250 + (noise(x * 0.005, 7.3) - 0.5) * 130;
}

// temperature: cold ash -> rust -> ember -> amber -> pale gold
const RAMP = [
  [0.00,  52,  56,  66],
  [0.16,  92,  72,  66],
  [0.34, 148,  74,  46],
  [0.55, 222, 112,  54],
  [0.78, 255, 178,  96],
  [1.00, 255, 246, 218]
];

function emberColor(t) {
  t = constrain(t, 0, 1);
  for (let i = 1; i < RAMP.length; i++) {
    if (t <= RAMP[i][0]) {
      const a = RAMP[i - 1], b = RAMP[i];
      const f = (t - a[0]) / (b[0] - a[0]);
      return [lerp(a[1], b[1], f), lerp(a[2], b[2], f), lerp(a[3], b[3], f)];
    }
  }
  const l = RAMP[RAMP.length - 1];
  return [l[1], l[2], l[3]];
}

function paintField() {
  noStroke();
  const g = drawingContext.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, 'rgb(7,8,15)');
  g.addColorStop(0.45, 'rgb(11,12,20)');
  g.addColorStop(0.80, 'rgb(6,6,10)');
  g.addColorStop(1.00, 'rgb(3,3,5)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function blob(x, y, r, c, a) {
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0.0, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
  g.addColorStop(0.5, `rgba(${c[0]},${c[1]},${c[2]},${a * 0.42})`);
  g.addColorStop(1.0, `rgba(${c[0]},${c[1]},${c[2]},0)`);
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, r * 2, r * 2);
}

function smear(x, y, r, ang, c, a) {
  drawingContext.save();
  drawingContext.translate(x, y);
  drawingContext.rotate(ang);
  drawingContext.scale(1, 0.22);
  const g = drawingContext.createRadialGradient(0, 0, 0, 0, 0, r);
  g.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
  g.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
  drawingContext.fillStyle = g;
  drawingContext.fillRect(-r, -r, r * 2, r * 2);
  drawingContext.restore();
}

function paintAura() {
  blob(180, 120, 640, [22, 30, 50], 0.10);        // cold corners
  blob(1420, 120, 640, [22, 30, 50], 0.10);
  blob(800, 1700, 1050, [24, 32, 54], 0.10);      // the receiving dark
  blob(800, 1990, 1000, [66, 70, 82], 0.05);      // settled ash haze
  blob(800, 640, 460, [142, 92, 44], 0.11);       // warmth around the head
  blob(800, 880, 680, [104, 66, 34], 0.10);       // warmth around the chest
  blob(800, 1290, 380, [186, 96, 42], 0.08);      // the glow of release
  for (let i = 0; i < 22; i++) {                  // painterly breath in the field
    smear(random(80, W - 80), random(120, H - 120),
          random(120, 420), random(-0.35, 0.35),
          [70, 84, 110], random(0.02, 0.05));
  }
  for (let i = 0; i < 8; i++) {
    smear(CX + random(-380, 380), random(560, 1240),
          random(90, 220), random(-0.4, 0.4),
          [120, 82, 46], random(0.02, 0.045));
  }
}

function paintRing() {
  noStroke();
  const cy = 880, R = 560;
  for (let i = 0; i <= 720; i++) {
    const a = TWO_PI * i / 720;
    const nx = Math.cos(a), ny = Math.sin(a);
    const n = noise(nx * 1.7 + 9.2, ny * 1.7 + 4.1);
    const al = 15 * pow(n, 3.4);
    if (al > 1.5) {
      fill(138, 156, 188, al);
      circle(CX + nx * R, cy + ny * R, 1.5);
    }
  }
}

function paintDormant() {
  noStroke();
  for (let i = 0; i < 320; i++) {
    const x = random(30, W - 30), y = random(30, H - 30);
    const n = noise(x * 0.0025, y * 0.0025);
    fill(116, 128, 150, random(3, 13) * (0.35 + 0.75 * n * n));
    circle(x, y, random(0.8, 2.3));
  }
}

function paintGhost() {
  noStroke();
  for (let y = 500; y <= 1360; y += 4) {
    for (let x = 560; x <= 1040; x += 4) {
      if (bodyDepth(x, y) > 2) {
        const c = emberColor(map(y, 520, frontY(x), 0.4, 0.9));
        fill(c[0], c[1], c[2], 4 + 5 * noise(x * 0.02, y * 0.02));
        circle(x, y, 5.5);
      }
    }
  }
}

function paintPlume() {
  noStroke();
  const pts = [];
  let tries = 0;
  while (pts.length < 18000 && tries < 400000) {
    tries++;
    const x0 = random(580, 1020);
    const y0 = random(960, 1360);
    const d = bodyDepth(x0, y0);
    if (d <= 0 || y0 < frontY(x0) - 70) continue;
    if (random() > Math.min(1, d / 20)) continue;

    const fall = 8 + pow(random(), 1.55) * 690;
    const esc = random() < 0.035;                     // a few escape far
    const wn = noise(x0 * 0.006, y0 * 0.006, fall * 0.0025);
    const amp = (120 + fall * (esc ? 2.3 : 1.05)) * (0.7 + 0.6 * noise(x0 * 0.01, 3.3));
    let x = x0 + (wn - 0.5) * amp * 2 + fall * 0.06;
    let y = y0 + fall * (0.88 + 0.24 * noise(x0 * 0.01, y0 * 0.01));
    x += (noise(x * 0.004, y * 0.004) - 0.5) * 90;    // slow drift of ash

    let t = Math.max(0, 1 - fall / 640);
    t *= 0.72 + 0.28 * noise(x * 0.01, y * 0.01);
    const fade = constrain((1965 - y) / 220, 0, 1);   // gone into the field
    t *= fade;
    pts.push({
      x: x, y: y,
      c: emberColor(t),
      d: random(0.9, 2.4) + (random() < 0.03 ? random(1.5, 2.5) : 0),
      a: (3 + pow(t, 1.5) * 30) * fade,
      t: t
    });
  }
  pts.sort((p, q) => p.t - q.t);                      // dimmest first
  for (const q of pts) {
    if (q.a < 0.5) continue;
    fill(q.c[0], q.c[1], q.c[2], q.a);
    circle(q.x, q.y, q.d);
  }
  for (let i = 0; i < 130; i++) {                     // live embers in the fall
    const q = pts[floor(random(pts.length))];
    if (!q || q.t < 0.18 || q.t > 0.85) continue;
    const s = random(4, 11);
    fill(q.c[0], q.c[1], q.c[2], 10);
    circle(q.x, q.y, s * 2.4);
    fill(min(255, q.c[0] + 40), min(255, q.c[1] + 30), q.c[2], 26);
    circle(q.x, q.y, s * 0.8);
  }
}

function paintBody() {
  noStroke();
  const pts = [];
  let tries = 0;
  while (pts.length < 16000 && tries < 320000) {
    tries++;
    const x = random(556, 1044);
    const y = random(498, 1330);
    const d = bodyDepth(x, y);
    if (d <= 0) continue;
    const fy = frontY(x);
    if (y > fy + 6) continue;                                    // already falling
    const p = Math.min(1, d / 24) * (0.5 + 0.9 * noise(x * 0.02, y * 0.02));
    if (random() > p) continue;
    const c = constrain((fy - y + 20) / 110, 0, 1);              // coherence
    const sway = noise(x * 0.05, y * 0.05, 3.1) - 0.5;
    const drop = noise(x * 0.03, y * 0.03, 8.7);
    const px = x + sway * (6 + (1 - c) * 40);
    const py = y + (drop - 0.5) * (5 + (1 - c) * 30) + (1 - c) * 26 * drop;

    let heat = 0.5 + 0.5 * Math.min(1, d / 38);
    heat += 0.35 * Math.max(0, 1 - Math.hypot(px - 800, py - 930) / 85); // the heart
    if (y > fy - 120) heat += 0.55 * (1 - (fy - y) / 120);               // the rim of release
    const pale = Math.max(0, 1 - Math.hypot(x - 800, y - 568) / 70);     // the head
    const t = constrain(heat * lerp(0.82, 1, pale), 0, 1);
    const ccol = emberColor(t);
    ccol[0] = lerp(ccol[0], 252, 0.40 * pale);
    ccol[1] = lerp(ccol[1], 253, 0.45 * pale);
    ccol[2] = lerp(ccol[2], 255, 0.55 * pale);
    pts.push({
      x: px, y: py, c: ccol,
      d: random(1.1, 2.8) + (random() < 0.05 ? random(1.5, 3) : 0),
      a: 9 + t * 20
    });
  }
  for (const q of pts) {
    fill(q.c[0], q.c[1], q.c[2], q.a * 0.35);
    circle(q.x, q.y, q.d * 2);       // soft halo
    fill(q.c[0], q.c[1], q.c[2], q.a);
    circle(q.x, q.y, q.d);           // core
  }
}

function paintRising() {
  noStroke();
  let n = 0, tries = 0;
  while (n < 240 && tries < 20000) {
    tries++;
    const x0 = random(560, 1044);
    const y0 = random(470, 1300);
    const d = bodyDepth(x0, y0);
    if (d < -46 || d > 24) continue;     // just off the skin of the self
    const rise = 26 + pow(random(), 1.35) * 440;
    const wob = (noise(x0 * 0.008, y0 * 0.008) - 0.5) * (36 + rise * 0.55);
    const x = x0 + wob * 0.6;
    const y = y0 - rise;
    const t = 0.62 * Math.max(0, 1 - rise / 470) + 0.1;
    const fade = constrain((y - 60) / 160, 0, 1);
    const c = emberColor(constrain(t, 0, 1));
    fill(c[0], c[1], c[2], (4 + 10 * t) * fade);
    circle(x, y, random(0.9, 1.9));
    n++;
  }
}

function vignette() {
  blendMode(BLEND);
  const g = drawingContext.createRadialGradient(800, 960, 430, 800, 1020, 1420);
  g.addColorStop(0.00, 'rgba(0,0,0,0)');
  g.addColorStop(0.62, 'rgba(1,1,2,0.14)');
  g.addColorStop(1.00, 'rgba(1,1,2,0.52)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function grain() {
  noStroke();
  for (let i = 0; i < 70000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.7) fill(148, 158, 176, random(2, 7));
    else fill(0, 0, 0, random(2, 6));
    rect(x, y, 1, 1);
  }
}

// THE SETTLING
// A painting about death: a warm storm of organized marks
// thins, cools, and settles through one pale seam into stillness.
// p5.js 1.11 — still image, 1600 x 2000

const SEAM = 1340;            // the threshold line
const COLD = [72, 86, 100];   // what warm marks become

const WARM = [
  [122, 34, 22, 0.15],
  [158, 64, 30, 0.22],
  [193, 98, 38, 0.22],
  [214, 140, 60, 0.17],
  [228, 190, 120, 0.14]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);
  paint();
}

function paint() {
  backgroundBase();  // smoky ground: warm above, cold below
  mottle();          // underpainting breath
  topGlow();         // the storm carries its own light
  gestures();        // long winds through the mass
  storm();           // the living marks
  sediment();        // what they become
  runnels();         // last threads through the surface
  seamLine();        // the instant itself
  deepFade();        // the floor goes dark
  vignette();
  grain();
}

// ---------- ground ----------

function backgroundBase() {
  noStroke();
  const stops = [
    [0.00, 36, 20, 12],
    [0.30, 27, 21, 17],
    [0.55, 21, 21, 22],
    [0.67, 16, 18, 21],
    [0.73, 13, 16, 20],
    [1.00, 7, 10, 15]
  ];
  for (let y = 0; y < 2000; y += 2) {
    const t = y / 2000;
    const c = gradColor(stops, t);
    const j = (noise(0.13, y * 0.006) - 0.5) * 7;
    fill(c[0] + j, c[1] + j, c[2] + j);
    rect(0, y, 1600, 2.2);
  }
}

function mottle() {
  noStroke();
  for (let i = 0; i < 520; i++) {
    const x = random(-100, 1700);
    const y = random(-80, 2080);
    const r = random(70, 360);
    let c;
    const k = random();
    if (y < 1050) {
      c = k < 0.34 ? [42, 26, 16] : (k < 0.67 ? [25, 15, 10] : [58, 36, 22]);
    } else {
      c = k < 0.34 ? [15, 18, 23] : (k < 0.67 ? [21, 25, 31] : [9, 12, 16]);
    }
    if (y > 1450 && random() < 0.06) c = [55, 34, 22]; // a faint memory of warmth
    fill(c[0], c[1], c[2], random(5, 12));
    ellipse(x, y, r, r * random(0.45, 1));
  }
}

function topGlow() {
  blendMode(ADD);
  noStroke();
  for (let i = 12; i >= 1; i--) {
    const k = i / 12;
    fill(190, 110, 48, 1.6);
    ellipse(820, 40, 400 + 1500 * k, 180 + 700 * k);
  }
  blendMode(BLEND);
}

// ---------- the living storm ----------

function gestures() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 7; i++) {
    const x0 = random(-120, 500);
    const y0 = random(-60, 480);
    const x3 = random(900, 1700);
    const y3 = random(480, 1290);
    const cx1 = lerp(x0, x3, 0.3) + random(-320, 320);
    const cy1 = lerp(y0, y3, 0.3) + random(-220, 220);
    const cx2 = lerp(x0, x3, 0.7) + random(-320, 320);
    const cy2 = lerp(y0, y3, 0.7) + random(-220, 220);
    stroke(215, 165, 105, random(4, 9));
    strokeWeight(random(1.5, 3.5));
    bezier(x0, y0, cx1, cy1, cx2, cy2, x3, y3);
  }
  blendMode(BLEND);
}

function gauss2(x, y, cx, cy, sx, sy) {
  const dx = (x - cx) / sx;
  const dy = (y - cy) / sy;
  return exp(-0.5 * (dx * dx + dy * dy));
}

function density(x, y) {
  let g = 0;
  g += gauss2(x, y, 640, 340, 430, 280) * 1.0;   // the great mass
  g += gauss2(x, y, 1160, 200, 270, 180) * 0.5;  // upper wing
  g += gauss2(x, y, 300, 720, 250, 210) * 0.42;  // trailing wing
  g += gauss2(x, y, 820, 980, 340, 230) * 0.34;  // descending column
  return min(1, g + 0.1);
}

function pickWarm() {
  const r = random();
  let acc = 0;
  for (const c of WARM) {
    acc += c[3];
    if (r < acc) return c;
  }
  return WARM[1];
}

function fieldVec(x, y) {
  let a = noise(x * 0.0011, y * 0.0011, 4.7) * TWO_PI * 2.3;
  a += (noise(x * 0.007, y * 0.007, 9.3) - 0.5) * 1.1; // fine turbulence
  let vx = cos(a);
  let vy = sin(a);
  const drift = constrain(map(y, -100, SEAM, 0.6, -0.15), -0.3, 0.8);
  vx += drift;
  const db = constrain(map(y, 100, SEAM, 0.05, 1), 0.05, 1);
  vy = lerp(vy, 1.1, db * 0.75);                     // gravity grows below
  const conv = constrain(map(y, SEAM - 520, SEAM, 0, 1), 0, 1) * 0.6;
  vx += conv * ((790 - x) / 420);                    // funnel toward the seam
  const calm = constrain(map(y, SEAM - 140, SEAM, 0, 0.85), 0, 0.85);
  vx *= 1 - calm;                                    // horizontal motion dies
  return [vx, vy];
}

function storm() {
  const spawn = [];
  let guard = 0;
  while (spawn.length < 3200 && guard < 300000) {
    guard++;
    const x = random(-80, 1680);
    const y = random(-140, 1290);
    if (random() < density(x, y)) spawn.push([x, y]);
  }
  for (const p of spawn) strokePath(p[0], p[1], "mass");
  for (let i = 0; i < 520; i++) {                    // dark currents for depth
    const p = spawn[floor(random(spawn.length))];
    strokePath(p[0] + (random() - 0.5) * 60, p[1] + (random() - 0.5) * 60, "shadow");
  }
  blendMode(ADD);
  for (let i = 0; i < 380; i++) {                    // luminous streams
    const p = spawn[floor(random(spawn.length))];
    strokePath(p[0], p[1] + (random() - 0.5) * 90, "lum");
  }
  for (let i = 0; i < 240; i++) {                    // sparks
    const p = spawn[floor(random(spawn.length))];
    strokePath(p[0], p[1], "spark");
  }
  blendMode(BLEND);
}

function strokePath(x0, y0, kind) {
  const ember = kind === "mass" && random() < 0.07;  // a few cross the line
  let col, steps, baseA, baseW, coolK, coldEnd;
  if (kind === "mass") {
    col = pickWarm();
    steps = floor(random(10, 34));
    baseA = random(16, 46);
    baseW = random(1.0, 3.4);
    coolK = 0.88;
    coldEnd = COLD;
  } else if (kind === "shadow") {
    col = [15, 9, 6];
    steps = floor(random(8, 26));
    baseA = random(26, 55);
    baseW = random(1.5, 4.2);
    coolK = 0.9;
    coldEnd = [10, 13, 18];
  } else if (kind === "lum") {
    col = [212, 152, 82];
    steps = floor(random(40, 88));
    baseA = random(3, 7);
    baseW = random(1.0, 2.2);
    coolK = 0.92;
    coldEnd = [40, 48, 60];
  } else {
    col = [246, 228, 192];
    steps = floor(random(4, 10));
    baseA = random(38, 90);
    baseW = random(1.0, 1.9);
    coolK = 0.45;                                    // embers stay warm
    coldEnd = COLD;
  }
  let x = x0, y = y0;
  for (let s = 0; s < steps; s++) {
    const v = fieldVec(x, y);
    const L = max(sqrt(v[0] * v[0] + v[1] * v[1]), 0.0001);
    const calm = constrain(map(y, SEAM - 140, SEAM, 0, 1), 0, 1);
    const sp = 3.0 * (1 - 0.55 * calm) * (0.8 + random() * 0.4);
    const nx = x + (v[0] / L) * sp;
    const ny = y + (v[1] / L) * sp;
    const q = constrain(map(ny, SEAM - 470, SEAM, 0, 1), 0, 1);
    const cseg = mix(col, coldEnd, q * coolK);       // cooling toward the seam
    let a = baseA * (1 - 0.45 * (s / steps)) * (1 - q * q * 0.82);
    if (ny > SEAM) a *= constrain(map(ny, SEAM, SEAM + 70, 0.5, 0), 0, 0.5);
    a *= 0.7 + random() * 0.6;                       // speckled paint texture
    const w = max(baseW * (0.3 + 0.7 * sin(PI * (s + 1) / steps)), 0.4);
    if (a > 0.4) {
      stroke(cseg[0], cseg[1], cseg[2], a);
      strokeWeight(w);
      line(x, y, nx, ny);
    }
    x = nx;
    y = ny;
    if (y > SEAM + (ember ? 68 : 4)) break;          // motion stops at the line
    if (x < -160 || x > 1760) break;
  }
}

// ---------- the stillness below ----------

function sediment() {
  noStroke();
  const centers = [[640, 430], [1160, 270], [300, 250], [820, 340]];
  const wts = [1.0, 0.5, 0.42, 0.35];
  const tot = wts[0] + wts[1] + wts[2] + wts[3];
  for (let i = 0; i < 15000; i++) {
    const yr = pow(random(), 1.9);                   // denser near the surface
    let y = SEAM + 12 + yr * 640;
    if (y > 1996) y = 1996;
    const depth = (y - SEAM) / 660;
    const r = random();
    let acc = 0;
    let c = centers[0];
    for (let k = 0; k < 4; k++) {
      acc += wts[k] / tot;
      if (r < acc) { c = centers[k]; break; }
    }
    const spread = c[1] * (1 + depth * 0.55);
    const x = c[0] + (random() - 0.5) * 2 * spread;
    const st = noise(x * 0.0025, y * 0.012, 5.5);    // depositional strata
    let col;
    if (random() < 0.02) col = [105, 66, 48];        // rare warm ghost
    else col = mix([80, 94, 108], [44, 52, 64], random());
    let a = (2 + (1 - depth) * 16 + random() * 7) * (0.45 + 0.75 * st);
    a *= map(y, 1900, 2000, 1, 0.15);
    const rr = 0.8 + random() * 1.5;
    fill(col[0], col[1], col[2], a);
    if (y < SEAM + 80) ellipse(x, y, rr, rr * 2.4);  // still falling
    else ellipse(x, y, rr * 1.15, rr);               // at rest
  }
}

function runnels() {
  const centers = [640, 1160, 300, 820, 640, 820, 460, 1000];
  for (let i = 0; i < 9; i++) {
    const x0 = centers[floor(random(centers.length))] + (random() - 0.5) * 160;
    const len = random(90, 380);
    const ph = random(100);
    const a0 = random(4, 9);
    for (let j = 0; j < len; j += 3) {
      const t = j / len;
      const x = x0 + (noise((j + ph) * 0.013, 3.1) - 0.5) * 26;
      const y = SEAM + 3 + j;
      const a = a0 * (1 - t) * (0.6 + 0.4 * noise(j * 0.05, x0 * 0.01));
      const c = mix([86, 100, 114], [40, 48, 60], t);
      stroke(c[0], c[1], c[2], a);
      strokeWeight(1 + (1 - t) * 1.6);
      line(x, y, x, y + 4);
    }
  }
}

// ---------- the threshold ----------

function seamLine() {
  blendMode(ADD);
  noStroke();
  for (let i = -16; i <= 16; i++) {                  // soft glow band
    const fall = exp(-(i * i) / (2 * 6.5 * 6.5));
    fill(210, 196, 170, 3 * fall);
    rect(0, SEAM + i * 2.4 - 1.2, 1600, 2.6);
  }
  blendMode(BLEND);                                  // break the glow unevenly
  for (let i = 0; i < 10; i++) {
    fill(9, 10, 12, random(30, 70));
    rect(random(-20, 1500), SEAM - 34 + random(-4, 4), random(60, 240), random(30, 62));
  }
  blendMode(ADD);                                    // the hairline: the instant
  noFill();
  let px = -10, py = null;
  for (let x = -10; x <= 1610; x += 6) {
    const yy = SEAM + (noise(x * 0.006, 8.8) - 0.5) * 5;
    const mod = 0.35 + 0.65 * noise(x * 0.0021, 2.2);
    if (py !== null) {
      stroke(255, 249, 236, 200 * mod);
      strokeWeight(1.2 + 1.2 * mod);
      line(px, py, x, yy);
      stroke(255, 249, 236, 30 * mod);
      strokeWeight(1);
      line(px, py + 5, x, yy + 5);
    }
    px = x;
    py = yy;
  }
  for (let i = 0; i < 14; i++) {                     // where light gathers
    const cx = random(120, 1480);
    const r0 = random(4, 9);
    const yy = SEAM + (noise(cx * 0.006, 8.8) - 0.5) * 5;
    for (let k = 6; k >= 1; k--) {
      fill(232, 205, 150, 2.5);
      ellipse(cx, yy, r0 * k * 2.2, r0 * k * 0.9);
    }
    fill(255, 244, 214, 40);
    ellipse(cx, yy, 3, 1.6);
  }
  blendMode(BLEND);
}

// ---------- finishing ----------

function deepFade() {
  noStroke();
  for (let y = 1740; y < 2000; y += 4) {
    const t = (y - 1740) / 260;
    fill(4, 6, 9, 66 * t * t);
    rect(0, y, 1600, 4.4);
  }
}

function vignette() {
  noStroke();
  for (let i = 0; i < 120; i += 2) {
    const a = ((120 - i) / 120) * 26;
    fill(3, 3, 4, a);
    rect(i, 0, 2, 2000);
    rect(1598 - i, 0, 2, 2000);
  }
  for (let j = 0; j < 130; j += 2) {
    const a = ((130 - j) / 130) * 30;
    fill(3, 3, 4, a);
    rect(0, j, 1600, 2);
    rect(0, 1998 - j, 1600, 2);
  }
}

function grain() {
  strokeWeight(1);
  for (let i = 0; i < 60000; i++) {
    const x = random(1600);
    const y = random(2000);
    if (random() < 0.5) stroke(252, 244, 228, random(1, 6));
    else stroke(0, 0, 0, random(1, 7));
    point(x, y);
  }
}

// ---------- utils ----------

function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function gradColor(stops, t) {
  for (let i = 0; i < stops.length - 1; i++) {
    const a = stops[i], b = stops[i + 1];
    if (t >= a[0] && t <= b[0]) {
      const k = (t - a[0]) / (b[0] - a[0] + 1e-9);
      return [a[1] + (b[1] - a[1]) * k, a[2] + (b[2] - a[2]) * k, a[3] + (b[3] - a[3]) * k];
    }
  }
  const l = stops[stops.length - 1];
  return [l[1], l[2], l[3]];
}

// "What the Light Bends Around" — a still painting, 1600 x 2000.

const W = 1600;
const H = 2000;
const CX = 782;   // the heart of the void
const CY = 818;
const RD = 490;   // its radius

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);

  background(5, 6, 13);

  paintSky();

  blendMode(ADD);
  drawField();     // the river of light, bent around the stillness
  drawTheDying();  // the threads that end at the rim
  drawDust();

  blendMode(BLEND);
  drawVoid();

  blendMode(ADD);
  drawRim();

  blendMode(BLEND);
  grainAndVignette();
}

/* ---------------- helpers ---------------- */

function smoothstep(a, b, x) {
  const t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function distToVoid(x, y) {
  return Math.hypot(x - CX, y - CY) - RD;
}

function depthFade(y) {
  if (y <= CY + 60) return 1;
  return lerp(1, 0.36, constrain((y - CY - 60) / (H - CY - 60), 0, 1));
}

// light runs warm and bright at the rim of the void, cool and dim far away
function lightColor(dr, ember, n) {
  let t = constrain(map(dr, -20, 560, 0, 1), 0, 1);
  t = Math.pow(t, 0.85);
  let r = lerp(255, 102, t);
  let g = lerp(214, 122, t);
  let b = lerp(152, 182, t);
  const hot = constrain(map(dr, 90, -20, 0, 1), 0, 1);
  r = lerp(r, 255, hot * 0.6);
  g = lerp(g, 244, hot * 0.6);
  b = lerp(b, 228, hot * 0.6);
  if (ember) {
    g = lerp(g, 116, 0.7);
    b = lerp(b, 50, 0.7);
  }
  const v = (n - 0.5) * 34;
  return [constrain(r + v, 0, 255), constrain(g + v * 0.8, 0, 255), constrain(b + v * 0.6, 0, 255)];
}

// potential flow: a uniform downward stream parted by a cylinder.
// the world literally moves around the void; nothing enters it.
function flowDir(x, y) {
  const dx = x - CX;
  const dy = y - CY;
  let r2 = dx * dx + dy * dy;
  const a2 = RD * RD;
  if (r2 < a2) r2 = a2;
  const r4 = r2 * r2;
  let vx = (-2 * a2 * dx * dy) / r4;
  let vy = 1 + (a2 * (dx * dx - dy * dy)) / r4;
  const sp = Math.hypot(vx, vy);
  const s = 0.0011;
  vx += (noise(x * s, y * s, 3.7) - 0.5) * 0.85;            // breath
  vy += (noise(x * s + 40.3, y * s + 17.9, 8.1) - 0.5) * 0.85;
  const m = Math.hypot(vx, vy) || 1e-6;
  return { dx: vx / m, dy: vy / m, sp: sp };
}

/* ---------------- layers ---------------- */

function paintSky() {
  const ctx = drawingContext;

  const base = ctx.createLinearGradient(0, 0, 0, H);
  base.addColorStop(0, '#05060e');
  base.addColorStop(0.45, '#0a0b17');
  base.addColorStop(0.8, '#0c0a15');
  base.addColorStop(1, '#0e0b12');
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, W, H);

  ctx.globalCompositeOperation = 'lighter';

  // soft washes, cold with a few embers
  const washes = [
    [72, 62, 132, 0.10], [42, 82, 152, 0.08], [112, 62, 92, 0.07],
    [152, 92, 52, 0.05], [62, 112, 122, 0.06], [132, 102, 62, 0.05],
    [82, 72, 162, 0.08], [162, 122, 72, 0.05], [52, 92, 142, 0.07],
    [142, 72, 62, 0.06], [92, 62, 122, 0.08], [122, 142, 92, 0.04],
    [62, 132, 112, 0.05], [102, 82, 142, 0.06], [132, 96, 60, 0.05],
    [70, 100, 150, 0.06]
  ];
  for (let i = 0; i < washes.length; i++) {
    const w = washes[i];
    const x = random(-160, W + 160);
    const y = random(-160, H + 160);
    const rad = random(340, 780);
    const rg = ctx.createRadialGradient(x, y, 0, x, y, rad);
    rg.addColorStop(0, 'rgba(' + w[0] + ',' + w[1] + ',' + w[2] + ',' + w[3] + ')');
    rg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(x - rad, y - rad, rad * 2, rad * 2);
  }

  // the light enters at the top
  const source = ctx.createRadialGradient(CX + 40, -160, 80, CX + 40, -160, 950);
  source.addColorStop(0, 'rgba(255,232,190,0.14)');
  source.addColorStop(0.5, 'rgba(255,220,170,0.05)');
  source.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = source;
  ctx.fillRect(0, 0, W, 950);

  // corona: the living brighten against the edge
  const corona = ctx.createRadialGradient(CX, CY, RD * 0.96, CX, CY, RD * 2.15);
  corona.addColorStop(0, 'rgba(255,216,150,0.22)');
  corona.addColorStop(0.16, 'rgba(255,202,126,0.11)');
  corona.addColorStop(0.45, 'rgba(212,172,120,0.045)');
  corona.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = corona;
  ctx.fillRect(0, 0, W, H);

  ctx.globalCompositeOperation = 'source-over';
}

function flowStroke(x, y, steps, baseStep, bright, ember) {
  let px = x;
  let py = y;
  for (let i = 0; i < steps; i++) {
    const f = flowDir(px, py);
    const step = baseStep * (0.6 + 0.5 * f.sp);
    const nx = px + f.dx * step;
    const ny = py + f.dy * step;
    const dr = distToVoid(nx, ny);
    if (dr < 1) break;                       // never cross the threshold
    const u = i / steps;
    const fade = smoothstep(0, 0.2, u) * (1 - smoothstep(0.6, 1, u));
    const rim = 0.55 + 1.75 * Math.exp(-Math.max(dr, 0) / 130);
    const al = bright * 42 * fade * rim * depthFade(ny);
    if (al < 2) break;
    const c = lightColor(dr, ember, noise(px * 0.002, py * 0.002));
    stroke(c[0], c[1], c[2], al);
    strokeWeight(1.1 + 1.3 * noise(px * 0.001 + 9, py * 0.001 + 4) * (0.6 + 0.6 * bright));
    line(px, py, nx, ny);
    px = nx;
    py = ny;
  }
}

function drawField() {
  noFill();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  // the ambient river, everywhere
  for (let i = 0; i < 1500; i++) {
    const x = random(-60, W + 60);
    const y = random(-60, H + 60);
    if (distToVoid(x, y) < 10) continue;
    flowStroke(x, y, int(random(20, 62)), random(3.2, 6.0), 0.5 + random(0.55), random() < 0.09);
  }

  // the living gather at the edge
  for (let i = 0; i < 1050; i++) {
    const a = random(TWO_PI);
    const rr = RD + 12 + Math.pow(random(), 1.8) * 270;
    const x = CX + Math.cos(a) * rr;
    const y = CY + Math.sin(a) * rr;
    if (y < -70 || y > H + 70) continue;
    flowStroke(x, y, int(random(28, 72)), random(3.0, 5.6), 0.7 + random(0.6), random() < 0.1);
  }

  // long, dim braids in the outer dark
  for (let i = 0; i < 130; i++) {
    const x = random(-80, W + 80);
    const y = random(-80, H + 80);
    if (distToVoid(x, y) < 330) continue;
    flowStroke(x, y, int(random(70, 130)), random(5.5, 8.5), 0.26 + random(0.24), random() < 0.05);
  }
}

function gutterColor(remaining) {
  let r = 255, g = 209, b = 140;
  if (remaining < 150) {
    const k = 1 - remaining / 150;
    g = lerp(g, 243, k * 0.8);
    b = lerp(b, 224, k * 0.8);
  }
  if (remaining < 34) {
    const k = 1 - Math.max(remaining, 0) / 34;
    g = lerp(g, 124, k * 0.85);
    b = lerp(b, 60, k * 0.85);
  }
  return [r, g, b];
}

function drawTheDying() {
  noFill();
  strokeCap(ROUND);

  // threads that fall straight in and gutter out at the rim
  for (let i = 0; i < 170; i++) {
    const dx = random(-0.72, 0.72) * RD;
    const x = CX + dx;
    const rimY = CY - Math.sqrt(Math.max(RD * RD - dx * dx, 1));
    const startY = rimY - random(120, 640);
    const stepLen = 3.4 + random(2.4);
    const wobble = random(0.35, 1.15);
    const phase = random(TWO_PI);
    const baseAl = random(28, 50);
    const weight = random(0.9, 1.7);

    let travel = 0;
    for (let s = 0; s < 340; s++) {
      travel += stepLen;
      const ny = startY + travel;
      if (ny > H + 20) break;
      const off = Math.sin(phase + travel * 0.0052) * 21 * wobble;
      const nx = x + off;
      const remaining = distToVoid(nx, ny);
      if (remaining < 0) break;              // gone

      let flare = 1;
      if (remaining < 130) flare = 1 + 1.6 * (1 - remaining / 130);
      let al = baseAl * flare;
      if (remaining < 26) al *= Math.max(remaining, 0) / 26;
      al *= 0.35 + 0.65 * Math.min(travel / 140, 1);
      if (al < 2) break;

      const prevOff = Math.sin(phase + (travel - stepLen) * 0.0052) * 21 * wobble;
      const c = gutterColor(remaining);
      stroke(c[0], c[1], c[2], al);
      strokeWeight(weight * (0.8 + 0.35 * flare));
      line(x + prevOff, ny - stepLen, nx, ny);
    }
  }
}

function drawDust() {
  noStroke();
  for (let i = 0; i < 9000; i++) {
    const x = random(W);
    const y = random(H);
    if (distToVoid(x, y) < 3) continue;
    const n = noise(x * 0.0016, y * 0.0016);
    if (n < 0.37 && random() < 0.72) continue;   // let it clump
    const dr = distToVoid(x, y);
    const c = lightColor(dr, random() < 0.05, n);
    const rim = 0.5 + 1.7 * Math.exp(-Math.max(dr, 0) / 160);
    const al = (9 + random(30)) * rim * (0.45 + 0.75 * n) * depthFade(y);
    if (al < 2) continue;
    fill(c[0], c[1], c[2], al);
    circle(x, y, random(1.2, 3.4));
  }
}

function drawVoid() {
  noStroke();
  fill(0, 0, 0, 90);          // a breath of dark pressed outward
  circle(CX, CY, (RD + 11) * 2);
  fill(0, 0, 0);              // the absence itself
  circle(CX, CY, RD * 2);
}

function wobblyRing(r, n, amp, col, wgt) {
  noFill();
  stroke(col[0], col[1], col[2], col[3]);
  strokeWeight(wgt);
  beginShape();
  for (let i = 0; i <= n; i++) {
    const a = (i / n) * TWO_PI;
    const rr = r + (noise(Math.cos(a) * 3.1 + 7.7, Math.sin(a) * 3.1 + 2.3, 1.3) - 0.5) * 16 * amp;
    vertex(CX + Math.cos(a) * rr, CY + Math.sin(a) * rr);
  }
  endShape(CLOSE);
}

function drawRim() {
  // soft halos
  wobblyRing(RD + 9, 260, 1, [255, 214, 150, 13], 10);
  wobblyRing(RD + 4, 320, 0.7, [255, 227, 172, 22], 4.5);

  // the crisp, broken circle — a line held by a hand
  const segs = 520;
  for (let i = 0; i < segs; i++) {
    const a0 = (i / segs) * TWO_PI;
    const a1 = ((i + 1) / segs) * TWO_PI;
    const n = noise(Math.cos(a0) * 2.3 + 11, Math.sin(a0) * 2.3 + 5, 4.4);
    if (n < 0.33) continue;                     // gaps
    const rr = RD + 1 + (n - 0.5) * 5;
    const x0 = CX + Math.cos(a0) * rr;
    const y0 = CY + Math.sin(a0) * rr;
    const x1 = CX + Math.cos(a1) * rr;
    const y1 = CY + Math.sin(a1) * rr;
    stroke(255, 238, 206, 120 + 135 * n);
    strokeWeight(0.9 + 1.7 * n);
    line(x0, y0, x1, y1);
  }

  // coronal streamers: light sweeping around and past the void
  noFill();
  for (let i = 0; i < 250; i++) {
    const a = random(TWO_PI);
    const r0 = RD + 1 + Math.pow(random(), 2) * 9;
    let px = CX + Math.cos(a) * r0;
    let py = CY + Math.sin(a) * r0;
    const steps = int(random(46, 132));
    const stepLen = 3.8 + random(2.6);
    const bright = 0.45 + random(0.75);
    for (let s = 0; s < steps; s++) {
      const f = flowDir(px, py);
      const nx = px + f.dx * stepLen;
      const ny = py + f.dy * stepLen;
      const dr = distToVoid(nx, ny);
      if (dr < 0.5) break;
      const u = s / steps;
      const fade = smoothstep(0, 0.16, u) * (1 - smoothstep(0.55, 1, u));
      const fall = Math.exp(-dr / 55);
      stroke(255, 236, 202, 95 * bright * fade * (0.3 + 0.7 * fall));
      strokeWeight(0.8 + 1.3 * fall);
      line(px, py, nx, ny);
      px = nx;
      py = ny;
    }
  }

  // sparks and dust heaped at the edge
  noStroke();
  for (let i = 0; i < 2400; i++) {
    const a = random(TWO_PI);
    const rr = RD + 1.5 + Math.pow(random(), 2.4) * 30;
    const x = CX + Math.cos(a) * rr;
    const y = CY + Math.sin(a) * rr;
    const dr = rr - RD;
    const c = lightColor(dr, random() < 0.12, noise(x * 0.004, y * 0.004));
    fill(c[0], c[1], c[2], (60 + random(120)) * Math.exp(-dr / 14) + 8);
    circle(x, y, random(1.4, 4.2));
  }
}

function grainAndVignette() {
  noStroke();
  // grain everywhere except inside the void —
  // the one smooth, empty place in the whole painting
  for (let i = 0; i < 26000; i++) {
    const x = random(W);
    const y = random(H);
    if (distToVoid(x, y) < -2) continue;
    if (random() < 0.55) fill(255, 246, 232, random(1, 4));
    else fill(0, 0, 0, random(1, 5));
    rect(x, y, 1.5, 1.5);
  }

  const ctx = drawingContext;
  const g = ctx.createRadialGradient(W / 2, H * 0.47, H * 0.3, W / 2, H * 0.47, H * 0.8);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(2,2,8,0.45)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

// THE UNBINDING — a still painting (p5.js 1.11)
// A robed figure made of embers holds together from the feet up,
// while everything above the waist loosens into drifting motes
// that cool from amber to ash to slate and join the vast field.
// Below, still water briefly keeps a broken reflection.

const W = 1600;
const H = 2000;

const FX = 760;                                  // figure axis
const HEADX = FX, HEADY = 1078, HEADRX = 37, HEADRY = 48;
const SOLID_Y = 1560;                            // below this the body holds
const GONE_Y = 1120;                             // above this fully released
const MIRROR_Y = 1806;                           // still water line
const L0 = 1500;                                 // nominal dispersal distance

const STOPS = [
  [238, 160, 88],   // warm gold
  [188, 104, 60],   // ember
  [128, 92, 84],    // ash
  [96, 108, 132],   // cold slate
  [70, 84, 108]     // deep cold
];

let maskG, blurG;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  buildMask();
}

function draw() {
  paintSky();
  paintAtmosphere();
  paintDistantGhosts();
  paintField();
  paintWater();
  paintDissolution();
  paintGhostHead();
  paintGlows();
  paintVeil();
  paintGrain();
  paintVignette();
  noLoop();
}

// ---------- figure silhouette (white on black, then blurred) ----------

function buildMask() {
  maskG = createGraphics(W, H);
  maskG.background(0);
  maskG.noStroke();
  maskG.fill(255);
  drawFigure(maskG);

  const bw = W / 4, bh = H / 4;
  blurG = createGraphics(bw, bh);
  blurG.image(maskG, 0, 0, bw, bh);
  blurG.loadPixels();
}

function drawFigure(g) {
  g.rect(FX - 17, 1096, 34, 88);              // neck
  g.push();                                    // bowed head
  g.translate(FX, HEADY);
  g.rotate(0.055);
  g.ellipse(0, 0, HEADRX * 2, HEADRY * 2);
  g.pop();

  g.beginShape();                              // robe
  g.vertex(FX - 18, 1156);
  g.bezierVertex(FX - 58, 1170, FX - 86, 1196, FX - 92, 1242);
  g.bezierVertex(FX - 98, 1342, FX - 106, 1430, FX - 124, 1548);
  g.bezierVertex(FX - 144, 1668, FX - 156, 1714, FX - 166, 1764);
  g.bezierVertex(FX - 118, 1786, FX - 58, 1796, FX, 1796);
  g.bezierVertex(FX + 58, 1796, FX + 118, 1786, FX + 166, 1764);
  g.bezierVertex(FX + 156, 1714, FX + 144, 1668, FX + 124, 1548);
  g.bezierVertex(FX + 106, 1430, FX + 98, 1342, FX + 92, 1242);
  g.bezierVertex(FX + 86, 1196, FX + 58, 1170, FX + 18, 1156);
  g.endShape(CLOSE);

  g.ellipse(FX - 74, 1252, 66, 50);            // shoulders
  g.ellipse(FX + 74, 1252, 66, 50);
  g.ellipse(FX, 1772, 356, 46);                // hem pooling on the ground
}

function fieldAt(x, y) {
  const bw = blurG.width, bh = blurG.height;
  const bx = constrain(round(x / 4), 1, bw - 2);
  const by = constrain(round(y / 4), 1, bh - 2);
  let s = 0;
  for (let dy = -1; dy <= 1; dy++)
    for (let dx = -1; dx <= 1; dx++)
      s += blurG.pixels[4 * ((by + dy) * bw + (bx + dx))];
  return s / 9;                                // interior-ness 0..255
}

function sampleInside(x0, x1, y0, y1, minF) {
  for (let t = 0; t < 50; t++) {
    const x = random(x0, x1);
    const y = random(y0, y1);
    const f = fieldAt(x, y);
    if (f >= minF) return { x: x, y: y, f: f };
  }
  return null;
}

// ---------- helpers ----------

function smoothstep(e0, e1, x) {
  const t = constrain((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

function coolColor(t) {
  t = constrain(t, 0, 1) * (STOPS.length - 1);
  const i = floor(t);
  const f = t - i;
  const a = STOPS[i], b = STOPS[min(i + 1, STOPS.length - 1)];
  return [lerp(a[0], b[0], f), lerp(a[1], b[1], f), lerp(a[2], b[2], f)];
}

function radialBlob(cx, cy, r, cr, cg, cb, a) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(cx, cy, 0, cx, cy, r);
  g.addColorStop(0, 'rgba(' + cr + ',' + cg + ',' + cb + ',' + a + ')');
  g.addColorStop(1, 'rgba(' + cr + ',' + cg + ',' + cb + ',0)');
  ctx.fillStyle = g;
  ctx.fillRect(cx - r, cy - r, r * 2, r * 2);
}

function flowDir(x, y, len) {
  let ang = -HALF_PI + 0.20;                                   // rising, leaning right
  ang += (noise(x * 0.0012, y * 0.0012) - 0.5) * 1.6;          // slow turbulence
  const h = constrain((1600 - y) / 1250, 0, 1);
  ang += 0.55 * h * h;                                         // bends further right high up
  return [x + cos(ang) * len, y + sin(ang) * len];
}

// ---------- painting passes ----------

function paintSky() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, '#05070e');   // cold void above
  g.addColorStop(0.42, '#070a13');
  g.addColorStop(0.68, '#0c0c0e');
  g.addColorStop(0.86, '#150f09');
  g.addColorStop(1.00, '#1b140a');   // warm earth below
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function paintAtmosphere() {
  // warmth around the intact body
  radialBlob(FX, 1420, 640, 255, 132, 62, 0.10);
  radialBlob(FX, 1480, 300, 255, 178, 96, 0.07);
  radialBlob(FX, 1850, 380, 255, 140, 70, 0.05);
  // cold breaths high up
  radialBlob(300, 320, 800, 66, 86, 128, 0.05);
  radialBlob(1350, 180, 700, 70, 92, 134, 0.055);
  // a milky current running to the upper right, where the released go
  for (let i = 0; i <= 20; i++) {
    const t = i / 20;
    const cx = lerp(820, 1520, t) + (noise(t * 5.1) - 0.5) * 120;
    const cy = lerp(1000, 70, t) + (noise(t * 5.1 + 40) - 0.5) * 120;
    radialBlob(cx, cy, 150 + 90 * t, 148, 168, 204, 0.028 + 0.012 * (1 - t));
  }
}

function paintDistantGhosts() {
  // others, long dispersed, barely there
  const spots = [
    { x: 140, base: 1420, h: 620, a: 1.0 },
    { x: 330, base: 1290, h: 520, a: 0.8 },
    { x: 470, base: 1560, h: 700, a: 0.55 },
    { x: 1415, base: 1250, h: 560, a: 0.7 },
    { x: 1215, base: 1500, h: 640, a: 0.5 }
  ];
  noStroke();
  for (const s of spots) {
    radialBlob(s.x, s.base - 60, 90, 120, 134, 160, 0.05 * s.a);
    for (let i = 0; i < 46; i++) {
      const t = pow(random(), 1.4);
      const y = s.base - t * s.h;
      const drift = (noise(s.x * 0.01, t * 2) - 0.5) * 60 * t;
      fill(150, 166, 196, (1 - t) * 9 * s.a);
      circle(s.x + drift, y, random(0.6, 1.3));
    }
  }
}

function paintField() {
  noStroke();
  // the ambient field: everyone who has already dispersed
  for (let i = 0; i < 1300; i++) {
    const x = random(W);
    const y = random(1780);
    const warm = random() < 0.14;               // a little warmth still clings to some
    let a = random(7, 34);
    let d = random(0.6, 1.6);
    if (random() < 0.03) { a = random(30, 52); d = random(1.6, 2.3); }
    if (warm) fill(186, 158, 128, a * 0.7);
    else fill(146, 162, 190, a);
    circle(x, y, d);
  }
  // motes riding the current
  const ax = 840, ay = 980, bx = 1530, by = 90;
  const dx = bx - ax, dy = by - ay;
  const len = sqrt(dx * dx + dy * dy);
  const ux = dx / len, uy = dy / len;
  for (let i = 0; i < 800; i++) {
    const t = pow(random(), 0.9);
    const spread = 70 + 170 * t;
    const off = (random() + random() + random() - 1.5) / 1.5 * spread;
    const x = ax + ux * t * len - uy * off;
    const y = ay + uy * t * len + ux * off;
    const tt = min(t * 2.4, 1);
    const cr = lerp(206, 148, tt);
    const cg = lerp(146, 166, tt);
    const cb = lerp(92, 196, tt);
    fill(cr, cg, cb, random(8, 28) * (1.1 - 0.55 * t));
    circle(x, y, random(0.6, 1.5));
  }
}

function paintWater() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, MIRROR_Y, 0, H);
  g.addColorStop(0, '#0e0c0b');
  g.addColorStop(0.5, '#090a0d');
  g.addColorStop(1, '#050608');
  ctx.fillStyle = g;
  ctx.fillRect(0, MIRROR_Y, W, H - MIRROR_Y);

  // a breath of light along the water line
  const gb = ctx.createLinearGradient(0, MIRROR_Y - 16, 0, MIRROR_Y + 16);
  gb.addColorStop(0, 'rgba(150,170,200,0)');
  gb.addColorStop(0.5, 'rgba(150,170,200,0.06)');
  gb.addColorStop(1, 'rgba(150,170,200,0)');
  ctx.fillStyle = gb;
  ctx.fillRect(0, MIRROR_Y - 16, W, 32);

  // the shadow the figure rests in
  ctx.save();
  ctx.translate(FX, MIRROR_Y - 6);
  ctx.scale(1, 0.16);
  const gs = ctx.createRadialGradient(0, 0, 20, 0, 0, 310);
  gs.addColorStop(0, 'rgba(0,0,0,0.55)');
  gs.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = gs;
  ctx.fillRect(-310, -310, 620, 620);
  ctx.restore();

  // warmth carried into the water
  radialBlob(FX, 1900, 300, 255, 130, 60, 0.05);

  // broken shimmer
  noStroke();
  for (let i = 0; i < 60; i++) {
    const x = FX + (random() + random() + random() - 1.5) / 1.5 * 190;
    const y = MIRROR_Y + 10 + random(140);
    fill(210, 130, 66, random(5, 18));
    rect(x, y, 1.2, random(5, 22));
  }
}

function paintDissolution() {
  noStroke();
  const body = [];
  for (let i = 0; i < 48000; i++) {
    const p = sampleInside(FX - 210, FX + 210, 1010, 1800, 55);
    if (!p) continue;
    const rel = 1 - smoothstep(GONE_Y, SOLID_Y, p.y);
    const escaped = random() < min(1, rel + (1 - p.f / 255) * 0.18);
    body.push({ x: p.x, y: p.y, f: p.f, rel: rel, escaped: escaped });
  }

  // released motes first, so the body reads on top where they overlap
  for (const b of body) if (b.escaped) drawReleased(b);

  // the part that still holds together
  for (const b of body) if (!b.escaped) drawBodyDot(b, false);

  // dense core of the intact lower body
  for (let i = 0; i < 12000; i++) {
    const p = sampleInside(FX - 170, FX + 170, 1500, 1798, 40);
    if (p) drawBodyDot(p, true);
  }

  // the water briefly keeps the shape of what remained
  for (const b of body) {
    if (b.escaped || b.y < MIRROR_Y - 190) continue;
    if (random() < 0.45) continue;
    const ry = 2 * MIRROR_Y - b.y;
    if (ry < MIRROR_Y + 4 || ry > H - 6) continue;
    const wob = (noise(b.x * 0.02, ry * 0.01) - 0.5) * 14;
    const w = b.f / 255;
    fill(140 + 70 * w, 78 + 40 * w, 44 + 26 * w, random(18, 52));
    circle(b.x + wob, ry, random(1.0, 2.0));
  }
}

function drawBodyDot(p, corePass) {
  const w = p.f / 255;
  let c;
  const pick = random();
  if (w > 0.72 && pick < 0.3) c = [255, 213, 148];
  else if (w > 0.5 && pick < 0.6) c = [238, 160, 88];
  else if (w > 0.28) c = [176, 100, 54];
  else c = [128, 66, 42];
  const dk = constrain((p.y - 1640) / 160, 0, 1) * 0.45;      // grounded in shadow
  c = [c[0] * (1 - dk), c[1] * (1 - dk), c[2] * (1 - dk)];
  const a = random() < 0.75 ? 255 : random(150, 230);
  const d = corePass ? random(1.1, 2.1) : random(1.5, 3.1);
  fill(c[0], c[1], c[2], a);
  circle(p.x, p.y, d);
}

function drawReleased(b) {
  const effRel = max(b.rel, 0.12);

  // a few specks simply settle
  if (random() < 0.05 && b.y > 1250) {
    let px = b.x, py = b.y;
    const target = MIRROR_Y - 4 + random(0, 46);
    const step = (target - b.y) / 10;
    for (let s = 0; s < 10; s++) {
      px += (noise(px * 0.01, py * 0.01) - 0.5) * 16;
      py += step;
    }
    const c = coolColor(0.85);
    fill(c[0], c[1], c[2], random(26, 60));
    circle(px, py, random(0.7, 1.5));
    return;
  }

  // long departures leave a faint thread
  const far = b.rel > 0.25 && random() < 0.09;
  const L = far ? L0 * 1.9 : L0 * effRel * pow(random(), 1.35);

  if (far) {
    let px = b.x, py = b.y;
    const n = 42;
    for (let s = 0; s < n; s++) {
      const st = flowDir(px, py, L / n);
      px = st[0]; py = st[1];
      if (s % 3 === 1) {
        const t = constrain(s / n, 0, 1);
        const c = coolColor(0.35 + 0.6 * t);
        fill(c[0], c[1], c[2], random(3, 9));
        circle(px, py, random(0.6, 1.2));
      }
    }
    return;
  }

  // ordinary released mote: one position along its drift
  let px = b.x + (random() - 0.5) * 8;
  let py = b.y + (random() - 0.5) * 8;
  for (let s = 0; s < 16; s++) {
    const st = flowDir(px, py, L / 16);
    px = st[0]; py = st[1];
  }
  const t = constrain(L / 1150, 0, 1);
  const c = coolColor(t);
  const a = lerp(190, 22, pow(t, 0.8));
  const d = lerp(2.4, 0.8, t);
  fill(c[0], c[1], c[2], a);
  circle(px, py, d);
}

function paintGhostHead() {
  // a warm afterimage where the head was, already thinning
  noStroke();
  radialBlob(HEADX, HEADY - 10, 150, 255, 150, 80, 0.05);
  for (let i = 0; i < 900; i++) {
    const a = random(TWO_PI);
    const rr = sqrt(random());
    const x = HEADX + cos(a) * rr * HEADRX + (random() - 0.5) * 18;
    const y = HEADY + sin(a) * rr * HEADRY - random(0, 80) * rr;
    const c = coolColor(random(0.18, 0.55));
    fill(c[0], c[1], c[2], random(18, 60));
    circle(x, y + (random() - 0.5) * 16, random(0.8, 1.9));
  }
}

function paintGlows() {
  for (let i = 0; i < 70; i++) {
    const p = sampleInside(FX - 150, FX + 150, 1250, 1720, 120);
    if (!p) continue;
    radialBlob(p.x, p.y, random(18, 62), 255, 168, 84, random(0.03, 0.07));
  }
  for (let i = 0; i < 10; i++) {
    const p = sampleInside(FX - 90, FX + 90, 1350, 1650, 190);
    if (!p) continue;
    radialBlob(p.x, p.y, random(10, 26), 255, 214, 130, 0.09);
  }
}

function paintVeil() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, 760);
  g.addColorStop(0, 'rgba(9,13,24,0.32)');
  g.addColorStop(1, 'rgba(9,13,24,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, 760);
  const g2 = ctx.createLinearGradient(0, H - 170, 0, H);
  g2.addColorStop(0, 'rgba(2,3,6,0)');
  g2.addColorStop(1, 'rgba(2,3,6,0.5)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, H - 170, W, 170);
}

function paintGrain() {
  const ctx = drawingContext;
  for (let i = 0; i < 26000; i++) {
    const x = random(W), y = random(H);
    const a = random(2, 7);
    ctx.fillStyle = random() < 0.5
      ? 'rgba(255,250,240,' + a + ')'
      : 'rgba(0,0,0,' + (a + 2) + ')';
    ctx.fillRect(x, y, 1, 1);
  }
}

function paintVignette() {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(W / 2, H * 0.44);
  ctx.scale(1, 1.28);
  const g = ctx.createRadialGradient(0, 0, 520, 0, 0, 1300);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(4,7,13,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(-W, -H, W * 2, H * 2);
  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

const W = 1600, H = 2000;
const WATER_Y = 1640;
const GLOW_X = 800, GLOW_Y = 540;

function paint() {
  const ctx = drawingContext;

  // 1. background gradient — cold dark above, warm dark below
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, '#0a0c15');
  g.addColorStop(0.45, '#0e0d12');
  g.addColorStop(0.70, '#14110f');
  g.addColorStop(0.82, '#171310');
  g.addColorStop(1.00, '#07070b');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // distant dust in the dark field
  noStroke();
  for (let i = 0; i < 160; i++) {
    fill(226, 220, 205, random(0.03, 0.12) * 255);
    circle(random(W), random(0, 1050), random(1, 2.4));
  }

  // 2. the pale glow
  radialGlow(GLOW_X, GLOW_Y, 620, [
    [0.00, 'rgba(242,237,222,0.80)'],
    [0.22, 'rgba(230,222,200,0.34)'],
    [0.55, 'rgba(205,198,182,0.10)'],
    [1.00, 'rgba(205,198,182,0)']
  ]);
  radialGlow(GLOW_X, GLOW_Y, 210, [
    [0.00, 'rgba(252,249,240,0.95)'],
    [1.00, 'rgba(252,249,240,0)']
  ]);

  // faint rings — ripples in still air
  noFill();
  for (let r = 190; r <= 780; r += 74) {
    stroke(232, 226, 206, 7);
    strokeWeight(1.4);
    ellipse(GLOW_X, GLOW_Y, r * 2, r * 1.92);
  }

  // soft column of light between the figure and the glow
  noStroke();
  for (let i = 0; i < 4; i++) {
    fill(228, 220, 198, 6 + i * 3);
    ellipse(GLOW_X + (noise(i * 3.3) - 0.5) * 120, 1030, 460 - i * 70, 950);
  }

  // 3. ground darkening toward the shore
  g = ctx.createLinearGradient(0, 1000, 0, WATER_Y + 40);
  g.addColorStop(0, 'rgba(24,19,14,0)');
  g.addColorStop(1, 'rgba(24,19,14,0.75)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1000, W, WATER_Y + 40 - 1000);

  // terrain streaks
  for (let i = 0; i < 340; i++) {
    const y = random(1280, WATER_Y - 6);
    const x = random(0, W - 120);
    stroke(30, 25, 20, random(14, 40));
    strokeWeight(random(1, 3));
    line(x, y, x + random(20, 140), y + random(-2, 2));
  }
  noStroke();

  // 4. water
  g = ctx.createLinearGradient(0, WATER_Y, 0, H);
  g.addColorStop(0, '#0c0e13');
  g.addColorStop(1, '#04050a');
  ctx.fillStyle = g;
  ctx.fillRect(0, WATER_Y, W, H - WATER_Y);

  // waterline
  stroke(210, 208, 200, 14);
  strokeWeight(2);
  line(0, WATER_Y, W, WATER_Y);
  noStroke();

  // clipped reflections in the water
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, WATER_Y, W, H - WATER_Y);
  ctx.clip();
  radialGlow(GLOW_X, WATER_Y + 130, 430, [
    [0, 'rgba(235,228,208,0.14)'],
    [1, 'rgba(235,228,208,0)']
  ]);
  for (let L = 0; L < 5; L++) {
    fill(198, 180, 143, 4);
    ellipse(700, 2 * WATER_Y - 1512, 660 - L * 40, 90 - L * 8);
  }
  for (let i = 0; i < 70; i++) {
    const x = GLOW_X + (noise(i * 0.17) - 0.5) * 760;
    const len = random(50, 430);
    const w = random(2, 13);
    const a = random(0.04, 0.12);
    const gg = ctx.createLinearGradient(0, WATER_Y, 0, WATER_Y + len);
    gg.addColorStop(0, 'rgba(228,220,198,' + a + ')');
    gg.addColorStop(1, 'rgba(228,220,198,0)');
    ctx.fillStyle = gg;
    ctx.fillRect(x, WATER_Y, w, len);
  }
  ctx.restore();

  // mist above the waterline
  noStroke();
  fill(220, 214, 196, 10);
  ellipse(W / 2, WATER_Y - 8, 1560, 80);

  // 5. shadow beneath the figure
  fill(0, 0, 0, 90);
  ellipse(700, 1602, 700, 46);

  // 6. the reclining figure, dissolving at its edges
  const bodyCol = color(200, 182, 145);
  const shadeCol = color(138, 120, 90);
  const hiCol = color(238, 228, 202);
  softBlob(700, 1512, 330, 60, bodyCol, 9, 0.15, 1);   // torso, tapering toward the feet
  softBlob(372, 1500, 52, 46, bodyCol, 9, 0.15, 0);     // head
  softBlob(560, 1536, 95, 24, bodyCol, 7, 0.12, 1);     // arm
  softBlob(680, 1494, 265, 22, hiCol, 5, 0.10, 1);      // light along the top
  softBlob(705, 1532, 295, 32, shadeCol, 5, 0.10, 1);   // underside shade

  // 7. rising particles — the self loosening, drifting up toward the light
  for (let i = 0; i < 1300; i++) {
    const x0 = random(340, 1060);
    const y0 = random(1430, 1516);
    const t = pow(random(1), 1.35);
    const yTop = random(420, 640);
    const py = y0 - t * (y0 - yTop);
    const px = x0 + (noise(i * 0.013, t * 3.1) - 0.5) * 300 * t + (GLOW_X - x0) * 0.30 * t * t;
    const a = pow(1 - t, 1.7) * random(0.25, 0.95);
    let s = random(1, 4.6) * (1 - t * 0.45);
    const r = random(1);
    let c;
    if (r < 0.80) c = [233, 225, 203];
    else if (r < 0.95) c = [214, 178, 118];
    else c = [180, 76, 44];
    if (random(1) < 0.035) s += random(6, 13);
    noStroke();
    fill(c[0], c[1], c[2], a * 255);
    circle(px, py, s);
    if (s > 8) {
      radialGlow(px, py, s * 4.5, [
        [0, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + (a * 0.30) + ')'],
        [1, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0)']
      ]);
    }
  }

  // 8. foreground grasses in the bottom corners
  noFill();
  for (let i = 0; i < 52; i++) {
    const right = i % 2 === 0;
    const x = right ? random(1230, W) : random(0, 360);
    const y = random(1850, H + 10);
    const h = random(70, 200);
    const lean = random(-46, 46);
    stroke(4, 5, 7, random(110, 210));
    strokeWeight(random(2, 5));
    beginShape();
    vertex(x, y);
    bezierVertex(x + lean * 0.3, y - h * 0.4, x + lean * 0.7, y - h * 0.8, x + lean, y - h);
    endShape();
  }

  // 9. film grain
  noStroke();
  for (let i = 0; i < 15000; i++) {
    if (random(1) < 0.5) fill(255, 255, 255, random(2, 9));
    else fill(0, 0, 0, random(2, 11));
    rect(random(W), random(H), random(1, 2.2), random(1, 2.2));
  }

  // 10. vignette
  const vg = ctx.createRadialGradient(W / 2, 950, 480, W / 2, 1000, 1480);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.68, 'rgba(0,0,0,0.16)');
  vg.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

function radialGlow(x, y, r, stops) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (let i = 0; i < stops.length; i++) g.addColorStop(stops[i][0], stops[i][1]);
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function softBlob(cx, cy, rx, ry, c, layers, aMax, taper) {
  noStroke();
  const n = 72;
  for (let L = 1; L <= layers; L++) {
    const f = L / layers;
    const spread = 1 + (1 - f) * 0.38;
    const a = aMax * (0.35 + 0.65 * f);
    fill(red(c), green(c), blue(c), a * 255);
    beginShape();
    for (let i = 0; i <= n; i++) {
      const t = (i / n) * TWO_PI;
      const wob = 1 + 0.16 * (noise(cos(t) * 2.1 + cx * 0.013, sin(t) * 2.1 + cy * 0.013 + L * 7.7) - 0.5);
      let xr = rx * spread * wob;
      let yr = ry * spread * wob;
      if (taper > 0) {
        const m = Math.max(0, Math.cos(t));
        xr *= 1 - 0.38 * m * taper;
        yr *= 1 - 0.22 * m * taper;
      }
      vertex(cx + Math.cos(t) * xr, cy + Math.sin(t) * yr);
    }
    endShape(CLOSE);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

const CX = 800;
const DOOR_HW = 180;
const ARCH_Y = 620;
const DOOR_BASE = 1560;

const petalCols = [
  [201, 160, 168],
  [216, 179, 106],
  [185, 138, 110],
  [143, 122, 143],
  [224, 201, 143]
];

const groundCols = [
  [58, 44, 52],
  [74, 56, 38],
  [44, 38, 54],
  [84, 64, 42],
  [66, 48, 40]
];

function doorPath(hw, base) {
  const c = drawingContext;
  c.beginPath();
  c.moveTo(CX - hw, base);
  c.lineTo(CX - hw, ARCH_Y);
  c.arc(CX, ARCH_Y, hw, PI, 0);
  c.lineTo(CX + hw, base);
  c.closePath();
}

function petal(px, py, s, ang, col, a, glow) {
  push();
  translate(px, py);
  rotate(ang);
  noStroke();
  if (glow) blendMode(ADD);
  fill(col[0], col[1], col[2], a * 255);
  ellipse(0, 0, s, s * 0.42);
  pop();
  blendMode(BLEND);
}

function branch(x, y, ang, len, w, depth) {
  if (depth === 0) {
    noStroke();
    for (let k = 0; k < 3; k++) {
      fill(46 + random(22), 34 + random(16), 42 + random(16), 210);
      ellipse(x + random(-16, 16), y + random(-16, 16), random(8, 17), random(5, 10));
    }
    return;
  }
  const nx = x + cos(ang) * len;
  const ny = y + sin(ang) * len;
  stroke(12, 10, 18, 235);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, nx, ny);
  branch(nx, ny, ang + random(-0.5, 0.4), len * 0.72, w * 0.62, depth - 1);
  branch(nx, ny, ang + random(-0.2, 0.55), len * 0.72, w * 0.62, depth - 1);
}

function solidFigure(dx, dy, col, alpha) {
  push();
  translate(dx, dy);
  noStroke();
  fill(col[0], col[1], col[2], alpha);
  ellipse(CX, 1332, 110, 80);
  ellipse(CX, 1268, 104, 150);
  stroke(col[0], col[1], col[2], alpha);
  strokeCap(ROUND);
  strokeWeight(38);
  line(CX - 6, 1332, CX - 30, 1556);
  line(CX + 6, 1332, CX + 30, 1556);
  strokeWeight(22);
  line(CX - 48, 1218, CX - 62, 1406);
  line(CX + 48, 1218, CX + 64, 1396);
  pop();
}

function draw() {
  const c = drawingContext;

  // background
  let bg = c.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0, '#0a0c18');
  bg.addColorStop(0.55, '#11132a');
  bg.addColorStop(1, '#191521');
  c.fillStyle = bg;
  c.fillRect(0, 0, width, height);

  // ambient color blobs
  noStroke();
  const blobs = [[70, 58, 110, 7], [110, 70, 60, 6], [50, 60, 100, 6], [120, 80, 70, 5], [60, 45, 80, 6]];
  for (const b of blobs) {
    fill(b[0], b[1], b[2], b[3]);
    ellipse(random(width), random(height), random(500, 1100));
  }

  // faint dust in the dark upper air
  for (let i = 0; i < 170; i++) {
    noStroke();
    fill(170, 185, 230, random(0.04, 0.15) * 255);
    circle(random(width), random(0, 720), random(1, 2.6));
  }

  // floor
  let fg = c.createLinearGradient(0, 1440, 0, height);
  fg.addColorStop(0, '#262031');
  fg.addColorStop(1, '#0c0a11');
  c.fillStyle = fg;
  c.beginPath();
  c.moveTo(0, height);
  c.lineTo(0, 1500);
  for (let x = 0; x <= width; x += 32) {
    c.lineTo(x, 1500 + noise(x * 0.006, 7) * 110);
  }
  c.lineTo(width, height);
  c.closePath();
  c.fill();

  // doorway glow
  blendMode(ADD);
  for (let i = 9; i >= 1; i--) {
    c.fillStyle = 'rgba(255,180,95,' + (0.012 + (10 - i) * 0.010).toFixed(3) + ')';
    doorPath(DOOR_HW + i * 20, DOOR_BASE + i * 12);
    c.fill();
  }
  c.fillStyle = 'rgba(255,200,120,0.08)';
  c.beginPath();
  c.ellipse(CX, ARCH_Y - DOOR_HW - 40, 620, 280, 0, 0, TWO_PI);
  c.fill();
  blendMode(BLEND);

  // doorway core
  let dg = c.createLinearGradient(0, ARCH_Y - DOOR_HW, 0, DOOR_BASE);
  dg.addColorStop(0, '#fff6dd');
  dg.addColorStop(0.55, '#ffdf9e');
  dg.addColorStop(1, '#f0a95e');
  c.fillStyle = dg;
  doorPath(DOOR_HW, DOOR_BASE);
  c.fill();

  let ig = c.createLinearGradient(0, ARCH_Y - 120, 0, DOOR_BASE);
  ig.addColorStop(0, 'rgba(255,252,240,0.95)');
  ig.addColorStop(1, 'rgba(255,224,160,0.8)');
  c.fillStyle = ig;
  doorPath(DOOR_HW - 70, DOOR_BASE);
  c.fill();

  // arch outline
  c.strokeStyle = 'rgba(255,232,185,0.28)';
  c.lineWidth = 3;
  doorPath(DOOR_HW, DOOR_BASE);
  c.stroke();

  // light spilling onto the floor
  blendMode(ADD);
  let sg = c.createLinearGradient(0, DOOR_BASE, 0, height);
  sg.addColorStop(0, 'rgba(255,205,130,0.5)');
  sg.addColorStop(0.6, 'rgba(255,190,110,0.12)');
  sg.addColorStop(1, 'rgba(255,190,110,0)');
  c.fillStyle = sg;
  c.beginPath();
  c.moveTo(CX - DOOR_HW, DOOR_BASE);
  c.lineTo(CX + DOOR_HW, DOOR_BASE);
  c.lineTo(CX + 640, height);
  c.lineTo(CX - 640, height);
  c.closePath();
  c.fill();
  for (let i = 0; i < 14; i++) {
    const yy = DOOR_BASE + random(30, height - DOOR_BASE - 20);
    const spread = map(yy, DOOR_BASE, height, 200, 620);
    c.fillStyle = 'rgba(255,215,150,' + random(0.03, 0.08).toFixed(3) + ')';
    c.beginPath();
    c.ellipse(CX + random(-spread * 0.5, spread * 0.5), yy, random(80, 260), random(6, 14), 0, 0, TWO_PI);
    c.fill();
  }
  blendMode(BLEND);

  // threshold stone
  noStroke();
  fill(38, 32, 48);
  roundRect(CX - 200, DOOR_BASE - 14, 400, 42, 6);
  stroke(255, 220, 170, 110);
  strokeWeight(2);
  line(CX - 194, DOOR_BASE - 12, CX + 194, DOOR_BASE - 12);

  // fallen leaves on the ground
  for (let i = 0; i < 48; i++) {
    const py = random(DOOR_BASE - 4, height - 8);
    const px = CX + randomGaussian() * (300 + (py - DOOR_BASE) * 0.55);
    petal(px, py, random(11, 26), random(TWO_PI), random(groundCols), random(0.35, 0.7), false);
  }

  // figure shadow
  noStroke();
  fill(8, 6, 12, 120);
  ellipse(CX + 26, DOOR_BASE + 14, 210, 32);

  // figure: rim light, then dark solid lower body
  solidFigure(-5, -5, [255, 214, 160], 150);
  solidFigure(0, 0, [14, 11, 20], 235);

  // upper body dissolving into dark motes
  for (let i = 0; i < 300; i++) {
    const t = pow(i / 300, 1.25);
    const y = 1210 - t * 420;
    const spread = 26 + t * 190;
    const px = CX + (noise(i * 0.35, 2.5) - 0.5) * 2 * spread + t * 55;
    const s = map(t, 0, 1, 8, 1.6) * random(0.6, 1.4);
    const a = 0.65 * (1 - t * 0.35) + 0.1;
    noStroke();
    fill(15, 12, 22, a * 255);
    circle(px, y, s);
  }
  // dissolving head
  for (let i = 0; i < 60; i++) {
    const a = random(TWO_PI);
    const r = random(0, 46);
    fill(15, 12, 22, random(0.25, 0.7) * 255);
    circle(CX + 20 + cos(a) * r, 1085 + sin(a) * r * 1.15, random(2, 7));
  }

  // glowing motes rising through and beyond the doorway
  blendMode(ADD);
  for (let i = 0; i < 240; i++) {
    const t = pow(i / 240, 1.15);
    const y = 1230 - t * 560;
    const spread = 30 + t * 240;
    const px = CX + (noise(i * 0.31 + 9, 4.2) - 0.5) * 2 * spread + t * 80;
    const s = map(t, 0, 1, 5, 1.2) * random(0.6, 1.5);
    const a = 0.5 * (1 - t * 0.55);
    fill(255, 218, 155, a * 255);
    circle(px, y, s);
  }
  for (let i = 0; i < 90; i++) {
    fill(255, 226, 180, random(0.04, 0.16) * 255);
    circle(CX + randomGaussian() * 190, 760 - random(0, 520), random(1, 3));
  }
  blendMode(BLEND);

  // drifting petals
  for (let i = 0; i < 130; i++) {
    const py = random(-40, 1720);
    const px = CX + randomGaussian() * 470;
    const d = dist(px, py, CX, 950);
    const br = constrain(map(d, 180, 950, 1, 0.28), 0.28, 1);
    const col = random(petalCols);
    const inside = py > 430 && py < DOOR_BASE && abs(px - CX) < DOOR_HW - 10;
    petal(px, py, random(7, 19), random(TWO_PI), col, inside ? random(0.5, 0.9) : 0.12 + 0.45 * br, inside);
  }

  // bare branches from the top corners
  branch(-40, 60, 0.35, 150, 10, 5);
  branch(1640, 40, PI - 0.3, 150, 10, 5);

  // vignette
  const vg = c.createRadialGradient(CX, 980, 320, CX, 1000, 1330);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.72, 'rgba(4,3,9,0.28)');
  vg.addColorStop(1, 'rgba(2,2,6,0.62)');
  c.fillStyle = vg;
  c.fillRect(0, 0, width, height);

  // film grain
  strokeWeight(1);
  for (let i = 0; i < 5200; i++) {
    const v = random(255);
    stroke(v, v, v, random(4, 11));
    point(random(width), random(height));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  const W = 1600, H = 2000;
  const cx = 800, cy = 620, moonR = 265;
  const horizonY = 1330, waterY = 1615;
  const ctx = drawingContext;

  // ---- SKY ----
  let g = ctx.createLinearGradient(0, 0, 0, horizonY);
  g.addColorStop(0, '#04050c');
  g.addColorStop(0.55, '#0a0e1d');
  g.addColorStop(0.85, '#1a2236');
  g.addColorStop(1, '#2b3450');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, horizonY + 2);

  // bruised cloud texture
  for (let i = 0; i < 90; i++) {
    const x = random(W), y = random(horizonY * 0.92);
    const r = random(160, 640);
    const lit = noise(i * 0.37 + 2.2, 7.7) > 0.5;
    const a = random(0.02, 0.055);
    const rg = ctx.createRadialGradient(x, y, 0, x, y, r);
    rg.addColorStop(0, lit ? 'rgba(110,130,180,' + a + ')' : 'rgba(0,0,12,' + a * 1.8 + ')');
    rg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }

  // 360-degree afterglow along the horizon beneath the eclipse
  ctx.save();
  ctx.translate(cx, horizonY);
  ctx.scale(1, 0.16);
  let hg = ctx.createRadialGradient(0, 0, 0, 0, 0, 760);
  hg.addColorStop(0, 'rgba(255,176,120,0.20)');
  hg.addColorStop(0.5, 'rgba(226,150,120,0.08)');
  hg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = hg;
  ctx.fillRect(-760, -760, 1520, 1520);
  ctx.restore();

  // ---- STARS ----
  for (let i = 0; i < 240; i++) {
    const x = random(W), y = random(horizonY - 40);
    if (dist(x, y, cx, cy) < moonR + 40) continue;
    const a = random(0.25, 0.95) * (1 - (y / horizonY) * 0.4);
    const s = random(0.7, 2.6);
    ctx.fillStyle = 'rgba(228,236,255,' + a + ')';
    ctx.beginPath(); ctx.arc(x, y, s / 2, 0, Math.PI * 2); ctx.fill();
    if (random() < 0.07) {
      ctx.strokeStyle = 'rgba(228,236,255,' + a * 0.5 + ')';
      ctx.lineWidth = 0.8;
      ctx.beginPath();
      ctx.moveTo(x - s * 2.6, y); ctx.lineTo(x + s * 2.6, y);
      ctx.moveTo(x, y - s * 2.6); ctx.lineTo(x, y + s * 2.6);
      ctx.stroke();
    }
  }

  // ---- CORONA ----
  let halo = ctx.createRadialGradient(cx, cy, moonR * 0.85, cx, cy, moonR + 560);
  halo.addColorStop(0, 'rgba(255,238,196,0.30)');
  halo.addColorStop(0.22, 'rgba(255,222,164,0.13)');
  halo.addColorStop(0.55, 'rgba(190,190,250,0.05)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(cx - moonR - 560, cy - moonR - 560, (moonR + 560) * 2, (moonR + 560) * 2);

  for (let r = moonR + 64; r >= moonR + 2; r -= 2) {
    const t = (r - moonR) / 64;
    const a = 0.36 * (1 - t) * (1 - t);
    ctx.fillStyle = 'rgba(255,246,218,' + a + ')';
    ctx.beginPath(); ctx.arc(cx, cy, r, 0, Math.PI * 2); ctx.fill();
  }

  ctx.lineCap = 'round';
  for (let i = 0; i < 300; i++) {
    const a = random(Math.PI * 2);
    const n = noise(cos(a) * 3 + 10, sin(a) * 3 + 10);
    const len = 26 + pow(n, 1.7) * random(70, 320) + random(0, 50);
    const x0 = cx + cos(a) * (moonR - 6), y0 = cy + sin(a) * (moonR - 6);
    const x1 = cx + cos(a) * (moonR + len), y1 = cy + sin(a) * (moonR + len);
    const mx = (x0 + x1) / 2 + cos(a + Math.PI / 2) * len * random(-0.14, 0.14);
    const my = (y0 + y1) / 2 + sin(a + Math.PI / 2) * len * random(-0.14, 0.14);
    const warm = random();
    const col = warm > 0.62 ? '255,240,198' : (warm > 0.3 ? '214,222,255' : '255,250,236');
    ctx.strokeStyle = 'rgba(' + col + ',' + random(0.05, 0.28) * (0.35 + n * 0.65) + ')';
    ctx.lineWidth = random(0.6, 3.4);
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.quadraticCurveTo(mx, my, x1, y1);
    ctx.stroke();
  }

  // ---- BIRDS ----
  ctx.strokeStyle = 'rgba(6,7,12,0.8)';
  let placed = 0;
  while (placed < 8) {
    const bx = random(120, 640), by = random(140, 460);
    if (dist(bx, by, cx, cy) < moonR + 90) continue;
    const s = random(6, 15), flap = random(0.25, 0.85);
    ctx.lineWidth = random(1.2, 2.4);
    ctx.beginPath();
    ctx.moveTo(bx - s, by);
    ctx.quadraticCurveTo(bx - s * 0.4, by - s * flap, bx, by);
    ctx.quadraticCurveTo(bx + s * 0.4, by - s * flap, bx + s, by);
    ctx.stroke();
    placed++;
  }

  // ---- MOON DISC (faint earthshine, not pure black) ----
  let mg = ctx.createRadialGradient(cx - 70, cy - 80, moonR * 0.1, cx, cy, moonR);
  mg.addColorStop(0, '#3d4457');
  mg.addColorStop(0.55, '#1c2029');
  mg.addColorStop(1, '#07080c');
  ctx.fillStyle = mg;
  ctx.beginPath(); ctx.arc(cx, cy, moonR, 0, Math.PI * 2); ctx.fill();

  ctx.save();
  ctx.beginPath(); ctx.arc(cx, cy, moonR - 1, 0, Math.PI * 2); ctx.clip();
  for (let i = 0; i < 70; i++) {
    const a = random(Math.PI * 2), d = random(moonR * 0.88);
    const x = cx + cos(a) * d, y = cy + sin(a) * d, r = random(18, 95);
    const dark = random() > 0.42;
    const rg = ctx.createRadialGradient(x, y, 0, x, y, r);
    rg.addColorStop(0, dark ? 'rgba(4,5,9,0.30)' : 'rgba(125,135,160,0.10)');
    rg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = rg;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  ctx.restore();

  // ---- DIAMOND RING ----
  const da = -Math.PI * 0.32;
  const dx = cx + cos(da) * moonR, dy = cy + sin(da) * moonR;
  let dg = ctx.createRadialGradient(dx, dy, 0, dx, dy, 160);
  dg.addColorStop(0, 'rgba(255,255,255,0.95)');
  dg.addColorStop(0.1, 'rgba(255,252,238,0.6)');
  dg.addColorStop(0.4, 'rgba(255,232,176,0.16)');
  dg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = dg;
  ctx.fillRect(dx - 160, dy - 160, 320, 320);
  ctx.fillStyle = 'rgba(255,255,255,0.98)';
  ctx.beginPath(); ctx.arc(dx, dy, 9, 0, Math.PI * 2); ctx.fill();
  ctx.strokeStyle = 'rgba(255,255,255,0.65)';
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  ctx.moveTo(dx - 64, dy); ctx.lineTo(dx + 64, dy);
  ctx.moveTo(dx, dy - 64); ctx.lineTo(dx, dy + 64);
  ctx.stroke();

  // ---- LAND ----
  let lg = ctx.createLinearGradient(0, horizonY, 0, H);
  lg.addColorStop(0, '#242b3a');
  lg.addColorStop(0.3, '#151a25');
  lg.addColorStop(1, '#080a10');
  ctx.fillStyle = lg;
  ctx.fillRect(0, horizonY, W, H - horizonY);

  // distant treeline
  ctx.fillStyle = '#0b0e15';
  ctx.beginPath();
  ctx.moveTo(0, horizonY + 6);
  for (let x = 0; x <= W; x += 7) {
    const n = noise(x * 0.011, 3.3);
    let y = horizonY - n * 44;
    if (noise(x * 0.045, 9.1) > 0.87) y -= 30;
    ctx.lineTo(x, y);
  }
  ctx.lineTo(W, horizonY + 50);
  ctx.lineTo(0, horizonY + 50);
  ctx.closePath();
  ctx.fill();

  // ---- BARE TREES ----
  function tree(x, y, angle, len, wdt, depth) {
    if (depth <= 0 || len < 5) return;
    const x2 = x + cos(angle) * len, y2 = y + sin(angle) * len;
    ctx.strokeStyle = 'rgba(5,6,10,' + Math.min(0.95, 0.55 + depth * 0.06) + ')';
    ctx.lineWidth = wdt;
    ctx.lineCap = 'round';
    ctx.beginPath(); ctx.moveTo(x, y); ctx.lineTo(x2, y2); ctx.stroke();
    const nb = depth > 4 ? 2 : (random() > 0.35 ? 2 : 1);
    for (let i = 0; i < nb; i++) {
      tree(x2, y2, angle + random(-0.6, 0.6) + (i === 0 ? -0.28 : 0.28),
           len * random(0.6, 0.8), Math.max(0.6, wdt * 0.62), depth - 1);
    }
  }
  tree(245, waterY + 40, -Math.PI / 2 + 0.07, 150, 9, 7);
  tree(1395, waterY + 50, -Math.PI / 2 - 0.06, 175, 10, 7);
  tree(1120, waterY + 20, -Math.PI / 2 + 0.12, 95, 6, 6);
  tree(520, waterY + 26, -Math.PI / 2 - 0.14, 80, 5, 6);

  // ---- WATER: broken moonlight path ----
  for (let i = 0; i < 260; i++) {
    const y = waterY + 6 + random(H - waterY - 12);
    const t = (y - waterY) / (H - waterY);
    const wob = (noise(y * 0.018, 5.5) - 0.5) * 70;
    const wdt = random(10, 70) * (0.35 + t * 1.1);
    const alpha = 0.22 * (1 - t * 0.72) * random(0.35, 1);
    ctx.fillStyle = 'rgba(255,238,198,' + alpha + ')';
    ctx.fillRect(cx + wob - wdt / 2 + random(-1, 1) * (30 + t * 300), y, wdt, random(2, 5.5));
  }

  ctx.save();
  ctx.translate(cx, waterY + 8);
  ctx.scale(1, 0.32);
  let gg = ctx.createRadialGradient(0, 0, 0, 0, 0, 430);
  gg.addColorStop(0, 'rgba(255,232,182,0.22)');
  gg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = gg;
  ctx.fillRect(-430, -430, 860, 860);
  ctx.restore();

  for (let i = 0; i < 180; i++) {
    const y = waterY + random(H - waterY);
    ctx.fillStyle = 'rgba(0,0,0,' + random(0.06, 0.24) + ')';
    ctx.fillRect(random(W), y, random(40, 280), 1.3);
  }

  // shoreline mist
  let mist = ctx.createLinearGradient(0, waterY - 30, 0, waterY + 90);
  mist.addColorStop(0, 'rgba(150,165,200,0)');
  mist.addColorStop(0.5, 'rgba(150,165,200,0.06)');
  mist.addColorStop(1, 'rgba(150,165,200,0)');
  ctx.fillStyle = mist;
  ctx.fillRect(0, waterY - 30, W, 120);

  // foreground darkening
  let fg = ctx.createLinearGradient(0, H - 150, 0, H);
  fg.addColorStop(0, 'rgba(3,4,7,0)');
  fg.addColorStop(1, 'rgba(3,4,7,0.85)');
  ctx.fillStyle = fg;
  ctx.fillRect(0, H - 150, W, 150);

  // vignette
  let vg = ctx.createRadialGradient(W / 2, H * 0.42, H * 0.22, W / 2, H * 0.5, H * 0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.52)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  // film grain
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const gr = random(-8, 8);
    pixels[i]     = constrain(pixels[i] + gr, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + gr, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + gr, 0, 255);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
}

function draw() {
  const W = width, H = height, cx = W / 2, cy = H * 0.47;

  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    const c = lerpColor(color(10, 11, 20), color(2, 3, 7), t);
    stroke(c);
    line(0, y, W, y);
  }
  noStroke();
  for (let i = 0; i < 1600; i++) {
    const x = random(W), y = random(H), r = random(18, 130);
    fill(random(12, 34), random(10, 26), random(22, 52), random(6, 20));
    ellipse(x, y, r, r * random(0.35, 1));
  }

  const maxR = 1180;
  for (let r = maxR; r > 0; r -= 5) {
    const t = 1 - r / maxR;
    const a = map(t, 0, 1, 0, 118) * (0.62 + 0.38 * noise(r * 0.012));
    const c = lerpColor(color(255, 246, 220), color(112, 132, 188), r / maxR);
    fill(red(c), green(c), blue(c), a);
    ellipse(cx, cy, r * 1.22, r * 0.92);
  }
  for (let y = 120; y < 1720; y += 3) {
    const d = abs(y - cy);
    const a = constrain(map(d, 0, 860, 150, 0), 0, 150);
    const w = 24 + 74 * exp(-d / 520);
    fill(255, 250, 232, a * 0.34);
    rect(cx - w / 2, y, w, 3);
  }

  function gapHalf(y) {
    return 18 + 34 * noise(y * 0.0021 + 7);
  }
  function edge(y) {
    return cx + (noise(y * 0.0032) - 0.5) * 132 + sin(y * 0.008) * 10;
  }

  fill(7, 7, 11);
  beginShape();
  vertex(0, 0);
  for (let y = 0; y <= H; y += 8) vertex(edge(y) - gapHalf(y), y);
  vertex(0, H);
  endShape(CLOSE);
  beginShape();
  vertex(W, 0);
  for (let y = 0; y <= H; y += 8) vertex(edge(y) + gapHalf(y), y);
  vertex(W, H);
  endShape(CLOSE);

  for (let i = 0; i < 170; i++) {
    const y = random(H);
    const side = random() < 0.5 ? -1 : 1;
    let x = edge(y) + side * (gapHalf(y) + 2);
    let yy = y;
    const dark = random() < 0.72;
    strokeWeight(random(0.5, 2.1));
    stroke(dark ? color(0, 0, 0, random(70, 150)) : color(225, 230, 245, random(10, 34)));
    for (let s = 0; s < 7; s++) {
      const nx = x + side * random(18, 95);
      const ny = yy + random(-28, 28);
      line(x, yy, nx, ny);
      x = nx; yy = ny;
    }
  }

  const gy = H * 0.76;
  for (let y = gy; y < H; y += 3) {
    const t = (y - gy) / (H - gy);
    const c = lerpColor(color(24, 28, 44, 0), color(2, 3, 6, 235), t);
    noStroke();
    fill(red(c), green(c), blue(c), alpha(c));
    rect(0, y, W, 3);
  }
  for (let y = gy + 4; y < H; y += 7) {
    const t = (y - gy) / (H - gy);
    const w = 20 + 70 * (1 - t) * (0.4 + 0.6 * noise(y * 0.02));
    const a = 70 * (1 - t) * noise(y * 0.013 + 3);
    noStroke();
    fill(255, 248, 228, a);
    rect(cx - w / 2, y, w, 3);
  }

  for (let i = 0; i < 1150; i++) {
    const x = random(W), y = random(H);
    const d = abs(x - edge(y));
    const near = constrain(map(d, 0, 240, 1, 0), 0, 1);
    const n = noise(x * 0.01, y * 0.01);
    const s = random(0.6, 3.4) * (0.7 + near);
    const a = 14 + near * 215 * (0.35 + 0.65 * n);
    if (near > 0.34) fill(244, 238, 222, a);
    else fill(150, 160, 185, a * 0.55);
    noStroke();
    ellipse(x, y, s, s * random(1.2, 3.4));
  }
  for (let i = 0; i < 70; i++) {
    const x = cx + random(-70, 70) * (0.5 + noise(i));
    const y = cy + random(-420, 420);
    noStroke();
    fill(255, 250, 235, random(5, 16));
    ellipse(x, y, random(8, 34), random(8, 34));
  }

  const vr = Math.sqrt(W * W + H * H) / 2;
  noStroke();
  for (let r = vr; r > 0; r -= 10) {
    const a = map(r, 0, vr, 0, 150);
    fill(0, 0, 0, a);
    ellipse(W / 2, H / 2, r * 2, r * 2);
  }

  noLoop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const W = 1600, H = 2000;
  const CX = 800, EY = 730, ER = 330;   // eclipse center + radius
  const POOL = 1520;                     // waterline
  const ctx = drawingContext;

  function gauss() { return (random() + random() + random() - 1.5) / 1.5; }

  // 1 — deep space base
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#02030a');
  g.addColorStop(0.4, '#0a0e26');
  g.addColorStop(0.72, '#121838');
  g.addColorStop(1, '#04050d');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // 2 — nebula clouds
  noStroke();
  const neb = [[26,34,84],[46,38,98],[18,52,110],[66,46,112],[30,62,122],[80,60,130]];
  for (let i = 0; i < 300; i++) {
    const c = neb[(random(neb.length)) | 0];
    fill(c[0], c[1], c[2], random(9, 24));
    ellipse(random(W), random(H * 0.8), random(150, 580), random(80, 420));
  }

  // 3 — stars
  for (let i = 0; i < 1100; i++) {
    const x = random(W), y = random(POOL - 60);
    const s = random(0.6, 2.4);
    stroke(220 + random(35), 225 + random(30), 255, random(60, 220));
    strokeWeight(s);
    point(x, y);
    if (random() < 0.045) {
      blendMode(ADD);
      noStroke();
      fill(200, 220, 255, random(18, 40));
      ellipse(x, y, s * random(6, 12), s * random(6, 12));
      blendMode(BLEND);
    }
  }

  // 4 — motes orbiting the dark sun
  blendMode(ADD);
  for (let i = 0; i < 460; i++) {
    const a = random(TWO_PI);
    const r = ER + 22 + pow(random(1), 1.6) * 340;
    const x = CX + cos(a) * r;
    const y = EY + sin(a) * r * 0.97;
    const warm = map(sin(a), -1, 1, 0.35, 1);
    noStroke();
    fill(255, 205 + random(40), 150 + random(70), random(14, 70) * warm);
    const s = random(1.2, 4.2);
    ellipse(x, y, s, s);
  }

  // 5 — corona glow + spikes
  for (let i = 0; i < 240; i++) {
    const a = random(TWO_PI);
    const r = ER - 6 + pow(random(1), 2.0) * 300;
    const x = CX + cos(a) * r, y = EY + sin(a) * r;
    const fall = map(sin(a), -1, 1, 0.3, 1);
    fill(255, 200 + random(45), 135 + random(70), map(r, ER, ER + 300, 46, 0, true) * fall);
    const s = random(8, 30);
    ellipse(x, y, s, s * random(0.8, 1));
  }
  for (let i = 0; i < 380; i++) {
    const a = random(TWO_PI);
    const r0 = ER - 4 + random(10);
    const r1 = r0 + random(24, 210) * pow(random(1), 1.4);
    const fall = map(sin(a), -1, 1, 0.25, 1);
    stroke(255, 214 + random(40), 150 + random(60), random(10, 55) * fall);
    strokeWeight(random(0.6, 2.4));
    line(CX + cos(a) * r0, EY + sin(a) * r0, CX + cos(a) * r1, EY + sin(a) * r1);
  }
  blendMode(BLEND);

  // 6 — the dark disc, faintly earthlit, rim of hidden light
  noStroke();
  fill(3, 4, 10);
  ellipse(CX, EY, ER * 2, ER * 2);
  for (let i = 0; i < 240; i++) {
    const a = random(TWO_PI), r = sqrt(random(1)) * (ER - 4);
    fill(38 + random(30), 46 + random(30), 86 + random(40), random(3, 9));
    ellipse(CX + cos(a) * r, EY + sin(a) * r, random(2, 7), random(2, 7));
  }
  noFill();
  stroke(255, 232, 195, 200); strokeWeight(3.2);
  arc(CX, EY, ER * 2 - 2, ER * 2 - 2, PI * 0.22, PI * 0.78);
  stroke(255, 210, 160, 70); strokeWeight(9);
  arc(CX, EY, ER * 2 + 6, ER * 2 + 6, PI * 0.3, PI * 0.7);
  stroke(120, 150, 255, 26); strokeWeight(5);
  arc(CX, EY, ER * 2 + 2, ER * 2 + 2, PI * 1.18, PI * 1.82);

  // 7 — light pouring down into the water
  blendMode(ADD);
  for (let i = 0; i < 48; i++) {
    const t = i / 47;
    const y = lerp(EY + ER - 30, POOL + 30, t);
    const w = lerp(70, 300, pow(t, 1.4));
    noStroke();
    fill(255, 205 + random(30), 150 + random(60), 10 * (1 - abs(t - 0.35) * 1.4) + 4);
    ellipse(CX + gauss() * 18, y, w, 46);
  }
  for (let i = 0; i < 2600; i++) {
    const t = pow(random(1), 1.35);
    const y = lerp(EY + ER - 20, POOL + 40, t);
    const spread = lerp(24, 290, pow(t, 1.6));
    const x = CX + gauss() * spread + noise(t * 4, i * 0.01) * 40 - 20;
    stroke(lerp(255, 150, t), lerp(212, 168, t), lerp(158, 238, t), (1 - t * 0.75) * random(50, 170));
    strokeWeight(random(1, 3.4));
    point(x, y);
  }
  for (let i = 0; i < 620; i++) {
    const t = pow(random(1), 1.5);
    const y = lerp(EY + ER, POOL + 20, t);
    const x = CX + gauss() * lerp(20, 260, t);
    noStroke();
    fill(255, 215, 165, random(8, 26) * (1 - t * 0.6));
    const s = random(6, 22);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 70; i++) {
    noStroke();
    fill(150, 170, 255, random(5, 13));
    ellipse(random(W * 0.15, W * 0.85), random(POOL - 120, POOL + 30), random(90, 260), random(18, 46));
  }
  blendMode(BLEND);

  // 8 — dark treeline at the horizon
  noStroke();
  fill(7, 9, 22);
  for (let x = -120; x < W + 140; x += random(46, 96)) {
    ellipse(x, POOL - 4, random(150, 300), random(26, 64));
  }
  fill(3, 4, 10);
  for (let x = -100; x < W + 120; x += random(34, 80)) {
    ellipse(x, POOL + 4, random(130, 260), random(30, 74));
  }

  // 9 — the still pool
  g = ctx.createLinearGradient(0, POOL, 0, H);
  g.addColorStop(0, '#080b18');
  g.addColorStop(0.25, '#05070f');
  g.addColorStop(1, '#020308');
  ctx.fillStyle = g;
  ctx.fillRect(0, POOL, W, H - POOL);

  // 10 — reflection: glow, streaks, sinking motes, ripples, shimmer
  blendMode(ADD);
  noStroke();
  fill(255, 222, 172, 46);
  ellipse(CX, POOL + 10, 380, 62);
  fill(255, 240, 210, 60);
  ellipse(CX, POOL + 8, 190, 30);
  for (let i = 0; i < 340; i++) {
    const t = random(1);
    const y = POOL + 4 + t * (H - POOL - 12);
    const x = CX + gauss() * lerp(14, 300, pow(t, 1.25));
    stroke(255, 206 + random(40), 148 + random(60), lerp(64, 6, t) * (0.4 + random(0.6)));
    strokeWeight(random(1, 3));
    line(x, y, x + random(-2.5, 2.5), y + random(3, 16));
  }
  for (let i = 0; i < 520; i++) {
    const t = pow(random(1), 1.5);
    const y = POOL + lerp(2, 330, t);
    const x = CX + gauss() * lerp(28, 250, t);
    stroke(205, 220, 255, (1 - t) * 80 + 8);
    strokeWeight(random(1, 2.4));
    line(x, y, x, y + random(2, 6));
  }
  noFill();
  for (let i = 0; i < 9; i++) {
    const rr = 70 + i * 58;
    stroke(255, 216, 170, 34 - i * 3.4);
    strokeWeight(1.6);
    ellipse(CX, POOL + 26 + i * 7, rr * 2.2, rr * 0.3);
  }
  for (let i = 0; i < 150; i++) {
    const y = POOL + random(H - POOL);
    const x = random(W);
    const near = 1 - min(1, abs(x - CX) / 500);
    stroke(lerp(120, 255, near), lerp(140, 208, near), lerp(230, 155, near), random(4, 14));
    strokeWeight(1);
    line(x, y, x + random(18, 130), y);
  }
  blendMode(BLEND);

  // 11 — seeds of what remains, waking in the dark water
  for (let i = 0; i < 120; i++) {
    const x = constrain(CX + gauss() * 400, 60, W - 60);
    const y = POOL + random(10, 400);
    const a = random(90, 220);
    if (random() < 0.32) {
      blendMode(ADD);
      noStroke();
      fill(215, 250, 220, 26);
      ellipse(x, y, random(10, 22), random(10, 22));
      blendMode(BLEND);
    }
    noStroke();
    fill(216 + random(39), 250, 214 + random(40), a);
    const s = random(1.4, 3.4);
    ellipse(x, y, s, s);
    if (random() < 0.4) {
      stroke(190, 238, 190, a * 0.8);
      strokeWeight(1);
      line(x, y, x + random(-4, 4), y - random(5, 12));
      line(x, y, x + random(-5, 5), y - random(4, 10));
    }
  }

  // 12 — reeds at the waterline
  for (let i = 0; i < 36; i++) {
    const bx = random(W);
    const by = POOL + random(6, 40);
    const h = random(50, 170);
    const lean = random(-30, 30);
    stroke(2, 3, 8, 235);
    strokeWeight(random(1.2, 2.6));
    line(bx, by, bx + lean, by - h);
    if (random() < 0.5) {
      noStroke();
      fill(4, 6, 12);
      ellipse(bx + lean, by - h, random(4, 8), random(8, 14));
    }
  }

  // 13 — foreground grasses, silhouetted
  for (let i = 0; i < 54; i++) {
    let bx;
    if (random() < 0.55) bx = random() < 0.5 ? random(W * 0.24) : W - random(W * 0.24);
    else bx = random(W);
    const by = H + random(4, 30);
    const h = random(130, 400);
    const lean = random(-110, 110);
    stroke(2, 4, 9, 240);
    strokeWeight(random(1.6, 4.2));
    noFill();
    bezier(bx, by, bx + lean * 0.3, by - h * 0.45, bx + lean * 0.8, by - h * 0.85, bx + lean * 1.25, by - h);
    if (random() < 0.55) {
      noStroke();
      fill(3, 5, 11);
      ellipse(bx + lean * 1.25, by - h, random(7, 15), random(4, 8));
      stroke(96, 116, 176, 55);
      strokeWeight(1);
      line(bx + lean * 1.25 - 3, by - h - 2, bx + lean * 1.25 + 3, by - h + 2);
    }
  }

  // 14 — film grain
  for (let i = 0; i < 22000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) stroke(255, 255, 255, random(0, 5));
    else stroke(0, 0, 0, random(0, 8));
    strokeWeight(1);
    point(x, y);
  }

  // 15 — vignette
  const v = ctx.createRadialGradient(CX, 880, 380, CX, 980, 1480);
  v.addColorStop(0, 'rgba(0,0,0,0)');
  v.addColorStop(0.68, 'rgba(0,0,6,0.16)');
  v.addColorStop(1, 'rgba(0,0,8,0.62)');
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);
}

// p5.js 1.11 — self-contained, still image
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  atmosphere();
  distantLight();
  banks();
  water();
  submergedRoots();
  ferry();
  foreground();
  surfaceGrain();
}

function atmosphere() {
  noFill();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let c;
    if (t < 0.30) {
      c = lerpColor(color(78, 78, 70), color(38, 59, 58), t / 0.30);
    } else {
      c = lerpColor(color(38, 59, 58), color(13, 32, 35), (t - 0.30) / 0.70);
    }
    stroke(c);
    strokeWeight(3);
    line(0, y, width, y);
  }

  // Broken, softly rubbed pigment.
  noStroke();
  for (let i = 0; i < 12500; i++) {
    let x = random(width), y = random(height);
    let n = noise(x * 0.002, y * 0.003);
    fill(104 + 24 * n, 111 + 15 * n, 94 + 16 * n, random(2, 9));
    ellipse(x, y, random(12, 80), random(2, 13));
  }
}

function distantLight() {
  noStroke();
  for (let r = 320; r > 118; r -= 3) {
    fill(185, 162, 113, 0.8);
    ellipse(614, 298, r * 2, r * 1.78);
  }

  // A rubbed-out disk rather than a sharply drawn sun.
  for (let i = 0; i < 9500; i++) {
    let a = random(TWO_PI);
    let r = sqrt(random()) * 134;
    let x = 614 + cos(a) * r;
    let y = 298 + sin(a) * r;
    let edge = constrain((134 - r) / 24, 0, 1);
    fill(184 + random(-16, 12), 162 + random(-12, 9), 114, 13 * edge);
    ellipse(x, y, random(3, 15), random(2, 8));
  }

  // Thin veils cross the light.
  for (let i = 0; i < 150; i++) {
    let y = random(160, 470);
    stroke(58, 72, 66, random(3, 13));
    strokeWeight(random(1, 5));
    line(random(240, 480), y, random(760, 1040), y + random(-5, 5));
  }
}

function leftEdge(y) {
  return 110 + 300 * exp(-y / 420) +
    56 * noise(y * 0.004) + 40 * sin(y * 0.003);
}

function rightEdge(y) {
  return 1470 - 310 * exp(-y / 490) -
    75 * noise(40 + y * 0.003);
}

function banks() {
  noStroke();
  fill(25, 34, 32);
  beginShape();
  vertex(0, 360);
  for (let y = 360; y <= 2000; y += 18) vertex(leftEdge(y), y);
  vertex(0, 2000);
  endShape(CLOSE);

  fill(30, 34, 30);
  beginShape();
  vertex(1600, 310);
  for (let y = 310; y <= 2000; y += 18) vertex(rightEdge(y), y);
  vertex(1600, 2000);
  endShape(CLOSE);

  for (let i = 0; i < 8000; i++) {
    let y = random(345, 2000);
    let side = random() < 0.5;
    let x = side ? random(0, leftEdge(y)) : random(rightEdge(y), 1600);
    let rusty = noise(x * 0.011, y * 0.008);
    stroke(52 + rusty * 40, 43 + rusty * 15, 31 + rusty * 8, random(8, 32));
    strokeWeight(random(1, 5));
    line(x, y, x + random(-18, 18), y - random(3, 36));
  }

  // Withered bank grasses, kept subordinate to the central linen.
  for (let i = 0; i < 430; i++) {
    let y = random(560, 1990);
    let left = random() < 0.5;
    let x = left ? leftEdge(y) - random(5, 90) :
                   rightEdge(y) + random(5, 90);
    let h = random(18, 115) * map(y, 560, 2000, 0.4, 1.2);
    let lean = random(-35, 35);
    noFill();
    stroke(105, 95, 64, random(12, 42));
    strokeWeight(random(0.6, 2));
    bezier(x, y, x + lean * 0.2, y - h * 0.4,
      x + lean, y - h * 0.8, x + lean * 1.2, y - h);
  }
}

function water() {
  // Horizontal brushwork preserves the water's stillness.
  for (let i = 0; i < 12000; i++) {
    let y = random(420, 2000);
    let x = random(leftEdge(y), rightEdge(y));
    let gleam = exp(-sq((x - (640 + y * 0.05)) / 210));
    stroke(104 + gleam * 54, 119 + gleam * 27,
      107 + gleam * 5, random(3, 15));
    strokeWeight(random(0.6, 2.6));
    let w = random(6, 65) * map(y, 420, 2000, 0.4, 1.4);
    line(x - w / 2, y, x + w / 2, y + random(-1.5, 1.5));
  }

  // Broken wake, displaced from the vessel.
  push();
  translate(798, 1083);
  rotate(0.47);
  noFill();
  for (let i = 0; i < 31; i++) {
    let w = 425 + i * 12;
    let h = 1300 + i * 10;
    stroke(126, 139, 118, map(i, 0, 30, 17, 1));
    strokeWeight(random(0.8, 2));
    arc(0, 15, w, h, 0.16, 1.28);
    arc(0, 15, w, h, 2.0, 3.02);
    arc(0, 15, w, h, 3.48, 4.35);
  }
  pop();
}

function root(x, y, len, angle, depth) {
  let ex = x + cos(angle) * len;
  let ey = y + sin(angle) * len;
  let bend = random(-0.26, 0.26) * len;
  noFill();
  stroke(139, 139, 104, 12 + depth * 3);
  strokeWeight(0.5 + depth * 0.43);
  bezier(x, y, x + bend, y + len * 0.36,
    ex - bend, ey - len * 0.2, ex, ey);
  if (depth > 0) {
    root(ex, ey, len * random(0.55, 0.75), angle + random(-0.55, 0.30), depth - 1);
    root(ex, ey, len * random(0.38, 0.66), angle + random(0.2, 0.85), depth - 1);
  }
}

function submergedRoots() {
  for (let i = 0; i < 7; i++) {
    root(520 + random(-60, 60), 1510 + random(-20, 35),
      random(100, 180), random(0.85, 2.1), 4);
  }
}

function pathFill(path, ink) {
  drawingContext.fillStyle = ink;
  drawingContext.fill(path);
}

function ferry() {
  push();
  translate(800, 1050);
  rotate(0.47);

  const hull = new Path2D(
    "M 0 -635 C 90 -570 192 -340 207 -90 " +
    "C 224 220 140 490 0 660 " +
    "C -141 504 -218 218 -204 -90 " +
    "C -192 -342 -98 -568 0 -635 Z"
  );
  const well = new Path2D(
    "M 0 -584 C 71 -515 161 -306 173 -77 " +
    "C 188 205 112 448 0 590 " +
    "C -113 444 -181 202 -173 -77 " +
    "C -164 -310 -75 -516 0 -584 Z"
  );

  // A wet, soft shadow under the wood.
  drawingContext.shadowColor = "rgba(3,15,17,0.65)";
  drawingContext.shadowBlur = 46;
  drawingContext.shadowOffsetX = 15;
  drawingContext.shadowOffsetY = 24;
  pathFill(hull, "#453f2d");
  drawingContext.shadowBlur = 0;
  drawingContext.shadowOffsetX = 0;
  drawingContext.shadowOffsetY = 0;

  drawingContext.save();
  drawingContext.clip(hull);
  for (let i = 0; i < 2100; i++) {
    let x = random(-215, 215), y = random(-640, 670);
    stroke(114, 93, 54, random(8, 34));
    strokeWeight(random(0.7, 2.4));
    line(x, y, x + random(-7, 7), y + random(8, 100));
  }
  drawingContext.restore();

  pathFill(well, "#111e1e");

  drawingContext.save();
  drawingContext.clip(well);
  for (let y = -540; y < 600; y += 100) {
    stroke(78, 68, 44, 60);
    strokeWeight(11);
    line(-190, y, 190, y + 15);
    stroke(8, 17, 17, 140);
    strokeWeight(5);
    line(-190, y + 9, 190, y + 24);
  }
  drawingContext.restore();

  // Intermittent light on the worn gunwale.
  noFill();
  stroke(159, 137, 88, 100);
  strokeWeight(2);
  bezier(-4, -612, -108, -451, -200, -76, -157, 260);
  stroke(124, 112, 76, 75);
  bezier(6, -603, 156, -349, 207, 161, 50, 550);

  linen();
  flowers();

  // A loose end of linen, caught on the stern.
  noFill();
  stroke(158, 160, 136, 110);
  strokeWeight(3);
  bezier(-18, 405, -52, 471, 47, 478, 4, 554);
  stroke(183, 177, 146, 75);
  strokeWeight(1);
  bezier(-19, 405, -56, 481, 48, 483, 6, 559);

  pop();
}

function linen() {
  const cloth = new Path2D(
    "M -4 -415 " +
    "C -62 -418 -87 -376 -77 -330 " +
    "C -73 -305 -66 -293 -80 -279 " +
    "C -133 -255 -150 -188 -145 -117 " +
    "C -138 -47 -125 26 -133 102 " +
    "C -147 191 -114 262 -87 312 " +
    "C -75 343 -93 373 -57 408 " +
    "C -31 439 27 435 53 409 " +
    "C 86 378 67 344 87 305 " +
    "C 114 246 139 160 125 82 " +
    "C 115 13 139 -68 141 -140 " +
    "C 142 -211 112 -261 70 -279 " +
    "C 52 -291 69 -316 71 -341 " +
    "C 77 -382 44 -414 -4 -415 Z"
  );

  drawingContext.shadowColor = "rgba(0,8,9,0.8)";
  drawingContext.shadowBlur = 22;
  drawingContext.shadowOffsetX = 17;
  drawingContext.shadowOffsetY = 12;
  pathFill(cloth, "#b4b39a");
  drawingContext.shadowBlur = 0;
  drawingContext.shadowOffsetX = 0;
  drawingContext.shadowOffsetY = 0;

  drawingContext.save();
  drawingContext.clip(cloth);

  noStroke();
  // Small scumbled strokes model the linen without outlining anatomy.
  for (let i = 0; i < 16000; i++) {
    let x = random(-155, 155), y = random(-425, 445);
    let ridge = 0.5 + 0.5 * sin(x * 0.065 + sin(y * 0.011) * 2.2);
    let light = constrain(1 - abs(x + 35) / 220, 0, 1);
    let n = noise(x * 0.025 + 20, y * 0.014 + 30);
    fill(130 + light * 72 + ridge * 19,
         137 + light * 63 + ridge * 16,
         122 + light * 48 + ridge * 11, random(12, 39));
    ellipse(x, y, random(2, 8), random(6, 28) * (0.5 + n));
  }

  // Long folds follow the weight of the covered body.
  for (let i = 0; i < 25; i++) {
    let x = -140 + i * 11.6;
    let y = random(-277, -180);
    noFill();
    stroke(57, 78, 75, random(18, 43));
    strokeWeight(random(2, 7));
    bezier(x, y, x - 38, -30, x + 54, 176,
      x * 0.48 - 7, random(360, 438));
    stroke(230, 222, 185, random(25, 65));
    strokeWeight(random(0.7, 2.5));
    bezier(x - 4, y, x - 42, -30, x + 50, 176,
      x * 0.48 - 11, 422);
  }

  // Soft folds around the covered head; deliberately no face.
  for (let i = 0; i < 23; i++) {
    noFill();
    stroke(82, 99, 89, 6);
    strokeWeight(3);
    bezier(-72 + i * 0.4, -357,
      -63, -289 + i, 44, -276 + i, 73, -340);
  }
  stroke(234, 225, 190, 75);
  strokeWeight(2);
  bezier(-49, -387, -25, -410, 20, -402, 39, -383);

  // Fine transverse creases.
  for (let i = 0; i < 95; i++) {
    let y = random(-260, 410), x = random(-130, 100);
    let l = random(9, 52);
    stroke(239, 229, 193, random(8, 30));
    strokeWeight(random(0.5, 1.2));
    line(x, y, x + l, y + random(3, 14));
  }
  drawingContext.restore();
}

function flowers() {
  // A small, hand-cut branch laid across the chest.
  noFill();
  stroke(63, 68, 41);
  strokeWeight(4);
  bezier(-76, -83, -19, -137, 46, -195, 107, -300);

  let blooms = [
    [-49, -122, 14], [-16, -168, 17], [30, -195, 12],
