function surfaceGrain() {
  // Fine canvas tooth, applied over every painted layer.
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (y * width + x);
      let tooth = random(-3.5, 3.5);
      let weave = (x % 4 === 0 ? -1.5 : 0) +
                  (y % 5 === 0 ? 1.1 : 0);
      pixels[i]     = constrain(pixels[i] + tooth + weave, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + tooth + weave, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + tooth + weave, 0, 255);
    }
  }
  updatePixels();
}

// Self-contained sketch for p5.js 1.11.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;
  background(20, 36, 39);
  strokeCap(ROUND);

  // An underpainting, cool overhead and oxidized near the water.
  let sky = ctx.createLinearGradient(0, 0, 0, 1130);
  sky.addColorStop(0, "#10292e");
  sky.addColorStop(0.43, "#354b49");
  sky.addColorStop(0.77, "#77715a");
  sky.addColorStop(1, "#a08a65");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, width, 1130);

  // Broken, slightly directional brushwork.
  for (let i = 0; i < 38000; i++) {
    let x = random(width), y = random(1130);
    let n = noise(x * 0.003, y * 0.004);
    let warm = y / 1130;
    stroke(
      82 + 65 * warm + n * 30,
      100 + 29 * warm + n * 16,
      91 + 9 * warm,
      random(3, 15)
    );
    strokeWeight(random(1, 4));
    line(x, y, x + random(4, 30), y + random(-5, 3));
  }

  // Veils of cloud, without hard boundaries.
  noStroke();
  for (let i = 0; i < 2400; i++) {
    let x = random(-100, 1700);
    let y = 390 + 160 * noise(x * 0.0018) + randomGaussian(0, 120);
    fill(23, 45, 47, 3);
    ellipse(x, y, random(90, 290), random(12, 55));
  }

  // A worn gold sun.
  const sunX = 1053, sunY = 579, sunR = 224;
  for (let r = 270; r > sunR; r -= 4) {
    fill(193, 158, 93, 1.8);
    circle(sunX, sunY, r * 2);
  }

  ctx.save();
  ctx.beginPath();
  ctx.arc(sunX, sunY, sunR, 0, TWO_PI);
  ctx.clip();

  let gold = ctx.createLinearGradient(850, 350, 1200, 830);
  gold.addColorStop(0, "#dbc28a");
  gold.addColorStop(0.5, "#c3a46b");
  gold.addColorStop(1, "#a88a56");
  ctx.fillStyle = gold;
  ctx.fillRect(800, 330, 510, 510);

  for (let i = 0; i < 10500; i++) {
    let x = random(825, 1280), y = random(350, 810);
    stroke(random() < 0.5 ? color(242, 220, 162, 24)
                               : color(92, 86, 60, 20));
    strokeWeight(random(0.6, 2.5));
    line(x, y, x + random(2, 13), y + random(-2, 2));
  }
  ctx.restore();

  // The far shore is deliberately almost unreadable.
  for (let layer = 0; layer < 5; layer++) {
    fill(38 + layer * 3, 56 + layer * 2, 52, 95);
    noStroke();
    beginShape();
    vertex(0, 1130);
    for (let x = 0; x <= width; x += 12) {
      let y = 985 + layer * 24
            - noise(x * 0.003, layer * 1.7) * (145 - layer * 19);
      vertex(x, y);
    }
    vertex(width, 1130);
    endShape(CLOSE);
  }

  // Distant upright traces.
  for (let i = 0; i < 75; i++) {
    let x = random(width);
    let base = 1015 + random(-20, 15);
    let h = random(28, 170);
    stroke(38, 55, 51, 70);
    strokeWeight(random(1, 4));
    line(x, base, x + random(-4, 4), base - h);
  }

  cypress(120, 1055, 1240, 103, 0.23);
  cypress(344, 1040, 1010, 76, 0.13);
  cypress(1465, 1070, 1200, 106, -0.13);
  cypress(1555, 1070, 890, 74, -0.15);

  // Water covers the feet of the trees.
  let water = ctx.createLinearGradient(0, 1025, 0, 2000);
  water.addColorStop(0, "#52635b");
  water.addColorStop(0.22, "#243e40");
  water.addColorStop(0.65, "#152f34");
  water.addColorStop(1, "#0c242c");
  ctx.fillStyle = water;
  ctx.fillRect(0, 1040, width, 960);

  for (let i = 0; i < 17000; i++) {
    let x = random(width), y = random(1040, 2000);
    let depth = (y - 1040) / 960;
    let n = noise(x * 0.004, y * 0.016);
    stroke(57 + n * 28, 80 + n * 24, 77 + n * 20, random(5, 25));
    strokeWeight(random(0.5, 2.7));
    let w = random(4, 28) * (0.6 + depth * 2);
    line(x, y, x + w, y + random(-0.7, 0.7));
  }

  // Fractured sunlight: narrow and increasingly scarce.
  for (let i = 0; i < 1900; i++) {
    let y = random(1040, 1900);
    let t = (y - 1040) / 860;
    let center = 1053 + 25 * sin(y * 0.012);
    let x = center + randomGaussian(0, 40 + t * 95);
    let a = (1 - t) * random(5, 30);
    stroke(184, 156, 98, a);
    strokeWeight(random(0.6, 2.4));
    line(x, y, x + random(3, 27) * (1 + t), y);
  }

  // Tree reflections, interrupted rather than mirrored literally.
  for (let i = 0; i < 2100; i++) {
    let side = random() < 0.65 ? random([120, 344]) : 1465;
    let y = random(1050, 2000);
    let d = (y - 1050) / 950;
    let x = side + 30 * sin(y * 0.023) + randomGaussian(0, 32 + d * 38);
    stroke(8, 27, 30, random(5, 25));
    strokeWeight(random(1, 4));
    line(x, y, x + random(8, 60), y);
  }

  // The boat's displaced darkness.
  noStroke();
  for (let i = 0; i < 32; i++) {
    fill(3, 17, 23, 3.5);
    ellipse(795, 1430, 1170 - i * 13, 220 - i * 4);
  }

  // Black wooden hull, its bow lifted toward the sun.
  const hull = new Path2D(
    "M 229 1238 " +
    "C 470 1283 1086 1243 1344 1169 " +
    "C 1283 1295 1174 1392 1012 1430 " +
    "C 716 1480 375 1413 229 1238 Z"
  );
  let hullPaint = ctx.createLinearGradient(0, 1210, 0, 1450);
  hullPaint.addColorStop(0, "#263634");
  hullPaint.addColorStop(0.35, "#172728");
  hullPaint.addColorStop(1, "#091b23");
  ctx.fillStyle = hullPaint;
  ctx.fill(hull);

  ctx.save();
  ctx.clip(hull);
  for (let i = 0; i < 1600; i++) {
    let x = random(220, 1350), y = random(1200, 1470);
    stroke(110, 107, 75, random(2, 14));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(15, 80), y - random(1, 6));
  }
  noFill();
  for (let j = 0; j < 5; j++) {
    stroke(116, 108, 74, 30 - j * 3);
    strokeWeight(2);
    bezier(250, 1262 + j * 23,
           590, 1402 + j * 16,
           1120, 1320 + j * 20,
           1320, 1202 + j * 14);
  }
  ctx.restore();

  noFill();
  stroke(155, 135, 91, 150);
  strokeWeight(4);
  bezier(235, 1238, 525, 1290, 1117, 1238, 1340, 1172);
  stroke(9, 24, 27, 220);
  strokeWeight(9);
  bezier(265, 1241, 575, 1265, 1080, 1229, 1306, 1190);

  // One continuous winding sheet; no face is exposed.
  const cloth = new Path2D(
    "M 390 1234 " +
    "C 439 1202 473 1155 546 1146 " +
    "C 625 1134 666 1158 727 1140 " +
    "C 815 1114 895 1124 955 1095 " +
    "C 960 1056 981 1022 1020 1020 " +
    "C 1063 1017 1100 1043 1118 1080 " +
    "C 1129 1104 1153 1123 1182 1145 " +
    "C 1212 1164 1232 1185 1263 1206 " +
    "C 1181 1229 1109 1234 1034 1245 " +
    "C 995 1278 995 1346 968 1412 " +
    "C 946 1474 918 1516 872 1546 " +
    "C 878 1494 839 1477 817 1435 " +
    "C 794 1381 798 1329 767 1295 " +
    "C 672 1281 579 1289 502 1264 " +
    "C 456 1254 417 1256 390 1234 Z"
  );

  let linen = ctx.createLinearGradient(730, 1060, 895, 1510);
  linen.addColorStop(0, "#e0d5b9");
  linen.addColorStop(0.25, "#cfc7ae");
  linen.addColorStop(0.52, "#989e91");
  linen.addColorStop(0.8, "#76887f");
  linen.addColorStop(1, "#506f6d");
  ctx.fillStyle = linen;
  ctx.fill(cloth);

  ctx.save();
  ctx.clip(cloth);

  // Long folds follow the covered body.
  noFill();
  for (let i = 0; i < 52; i++) {
    let t = i / 51;
    stroke(239, 225, 191, random(9, 28));
    strokeWeight(random(2, 8));
    bezier(
      408, 1226 + t * 40,
      605, 1096 + t * 162,
      921, 1191 + t * 90,
      1084, 1070 + t * 143
    );
  }

  const folds = [
    [492, 1190, 612, 1165, 717, 1228, 806, 1226],
    [553, 1242, 673, 1263, 716, 1233, 842, 1256],
    [967, 1108, 1025, 1113, 1048, 1166, 1114, 1189],
    [999, 1046, 1026, 1083, 1064, 1088, 1089, 1130],
    [829, 1213, 852, 1294, 819, 1388, 888, 1498],
    [938, 1190, 897, 1298, 967, 1351, 892, 1533],
    [1008, 1221, 942, 1270, 991, 1399, 904, 1491]
  ];
  for (let f of folds) {
    stroke(54, 77, 75, 40);
    strokeWeight(19);
    bezier(...f);
    stroke(62, 82, 77, 73);
    strokeWeight(4);
    bezier(...f);
    stroke(234, 224, 193, 47);
    strokeWeight(2);
    bezier(f[0] - 7, f[1], f[2] - 7, f[3],
           f[4] - 7, f[5], f[6] - 7, f[7]);
  }

  // Dry paint and visible linen grain.
  for (let i = 0; i < 16000; i++) {
    let x = random(385, 1270), y = random(1015, 1550);
    stroke(random() < 0.55 ? color(248, 235, 204, 15)
                                : color(48, 73, 72, 12));
    strokeWeight(random(0.4, 1.5));
    line(x, y, x + random(1, 5), y + random(2, 8));
  }
  ctx.restore();

  // A broken highlight on the crown and shoulder.
  noFill();
  stroke(244, 228, 191, 125);
  strokeWeight(2.5);
  bezier(963, 1080, 979, 1005, 1069, 1000, 1113, 1075);

  // The cloth unravels into submerged, branching roots.
  for (let i = 0; i < 24; i++) {
    let x = random(865, 933);
    let y = random(1472, 1526);
    let endY = random(1620, 1840);
    let endX = x + random(-170, 190);
    let bend = random(-75, 75);
    stroke(149, 168, 147, random(22, 65));
    strokeWeight(random(0.7, 2.2));
    bezier(x, y, x + bend, y + 90,
           endX - bend, endY - 70, endX, endY);

    let branchY = lerp(y, endY, 0.67);
    let branchX = lerp(x, endX, 0.65);
    stroke(133, 157, 140, 25);
    strokeWeight(0.8);
    bezier(branchX, branchY,
           branchX + bend, branchY + 25,
           branchX + bend * 1.3, branchY + 65,
           branchX + bend * 1.5, branchY + 105);
  }

  // Water passes over the roots.
  for (let i = 0; i < 140; i++) {
    let y = random(1500, 1855);
    let x = random(650, 1120);
    stroke(18, 46, 51, random(35, 95));
    strokeWeight(random(1, 4));
    line(x, y, x + random(15, 95), y);
  }

  // Quiet concentric disturbances beside the hull.
  noFill();
  for (let i = 0; i < 12; i++) {
    stroke(124, 146, 127, 32 - i * 1.8);
    strokeWeight(1);
    arc(798, 1440, 1050 + i * 39, 118 + i * 23,
        0.08, PI - 0.12);
  }

  // Small floating leaves, sparse enough to read individually.
  for (let i = 0; i < 19; i++) {
    let x = random(180, 1430), y = random(1520, 1920);
    push();
    translate(x, y);
    rotate(random(-0.4, 0.4));
    noStroke();
    fill(151, 122, 72, random(65, 140));
    beginShape();
    vertex(-8, 0);
    bezierVertex(-1, -5, 9, -3, 14, 0);
    bezierVertex(5, 3, -3, 4, -8, 0);
    endShape(CLOSE);
    pop();
  }

  // Darkened edges and a final tooth of pigment.
  let vignette = ctx.createRadialGradient(840, 980, 350, 800, 1000, 1280);
  vignette.addColorStop(0, "rgba(3,15,20,0)");
  vignette.addColorStop(0.67, "rgba(3,15,20,0.06)");
  vignette.addColorStop(1, "rgba(3,15,20,0.52)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 65000; i++) {
    let x = random(width), y = random(height);
    fill(random() < 0.5 ? color(231, 216, 174, 7)
                             : color(3, 18, 24, 10));
    rect(x, y, random(0.5, 1.6), random(0.7, 2.5));
  }
}

function cypress(x, base, h, w, lean) {
  noStroke();
  fill(13, 32, 34, 225);
  beginShape();
  vertex(x - w * 0.28, base);
  bezierVertex(x - w * 0.2, base - h * 0.35,
               x + lean * h - w * 0.08, base - h * 0.8,
               x + lean * h, base - h);
  bezierVertex(x + lean * h + w * 0.1, base - h * 0.8,
               x + w * 0.16, base - h * 0.3,
               x + w * 0.3, base);
  endShape(CLOSE);

  for (let i = 0; i < 1700; i++) {
    let t = random(0.12, 0.98);
    let y = base - h * t;
    let center = x + lean * h * pow(t, 1.8);
    let spread = w * pow(sin(PI * t), 0.8) * (0.6 + 0.4 * t);
    let xx = center + randomGaussian(0, spread * 0.36);
    fill(15 + random(0, 13), 34 + random(0, 14),
         35 + random(0, 11), random(12, 48));
    ellipse(xx, y, random(7, 27), random(15, 59));
  }

  noFill();
  stroke(112, 113, 82, 30);
  strokeWeight(2);
  bezier(x + 5, base, x - 5, base - h * 0.3,
         x + lean * h, base - h * 0.7,
         x + lean * h, base - h * 0.94);
}

// p5.js 1.11 — no external assets
function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  background(29, 36, 36);
  paintGround();
  distantShore();
  water();
  reflection();

  push();
  translate(800, 1175);
  rotate(-0.145);
  boat();
  shroud();
  offering();
  pop();

  foreground();
  grain();
}

function paintGround() {
  // A brushed ground, warm above and almost blue-black below.
  const stops = [
    [0, [68, 66, 55]],
    [470, [76, 79, 67]],
    [860, [43, 57, 53]],
    [1350, [25, 39, 39]],
    [2000, [15, 27, 29]]
  ];

  for (let y = 0; y < height; y++) {
    let k = 0;
    while (k < stops.length - 2 && y > stops[k + 1][0]) k++;
    let t = constrain(
      (y - stops[k][0]) / (stops[k + 1][0] - stops[k][0]), 0, 1
    );
    let a = stops[k][1], b = stops[k + 1][1];
    stroke(
      lerp(a[0], b[0], t),
      lerp(a[1], b[1], t),
      lerp(a[2], b[2], t)
    );
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 21000; i++) {
    let x = random(width), y = random(height);
    let n = noise(x * 0.003, y * 0.004);
    fill(120 + n * 30, 119 + n * 22, 91 + n * 18, random(2, 8));
    ellipse(x, y, random(8, 90), random(2, 15));
  }

  // A remote, tarnished disc, partly erased by atmosphere.
  noStroke();
  for (let r = 170; r > 78; r -= 3) {
    fill(185, 166, 112, 1.3);
    ellipse(1090, 394, r * 2, r * 2);
  }
  fill(166, 155, 112, 92);
  ellipse(1090, 394, 154, 154);
  fill(184, 171, 125, 35);
  ellipse(1083, 388, 138, 140);

  const ctx = drawingContext;
  ctx.save();
  ctx.beginPath();
  ctx.arc(1090, 394, 77, 0, TWO_PI);
  ctx.clip();
  for (let i = 0; i < 1200; i++) {
    fill(83, 92, 77, random(3, 15));
    ellipse(random(1000, 1180), random(310, 480),
            random(2, 24), random(1, 5));
  }
  ctx.restore();

  for (let i = 0; i < 95; i++) {
    let y = random(270, 560);
    fill(88, 94, 78, random(2, 7));
    ellipse(random(650, 1380), y, random(180, 650), random(5, 24));
  }
}

function distantShore() {
  // Far trees lose their feet in the mist.
  noStroke();
  for (let i = 0; i < 100; i++) {
    let x = random(-40, 1640);
    let base = 715 + 32 * noise(x * 0.005);
    let h = random(60, 350);
    let w = random(9, 35);
    fill(36, 48, 43, random(13, 38));
    beginShape();
    vertex(x - w, base);
    bezierVertex(x - w * 0.7, base - h * 0.5,
                 x - 3, base - h * 0.8, x, base - h);
    bezierVertex(x + 5, base - h * 0.64,
                 x + w, base - h * 0.4, x + w, base);
    endShape(CLOSE);
  }

  // Close cypresses make a broken, asymmetrical frame.
  cypress(-20, 815, 1040, 140);
  cypress(118, 730, 940, 87);
  cypress(226, 686, 765, 61);
  cypress(1504, 790, 1080, 120);
  cypress(1608, 883, 1180, 143);
  cypress(1408, 693, 685, 52);

  noStroke();
  fill(22, 35, 32, 180);
  beginShape();
  vertex(0, 660);
  bezierVertex(100, 670, 200, 727, 365, 750);
  bezierVertex(262, 786, 126, 812, 0, 860);
  endShape(CLOSE);

  fill(23, 36, 33, 160);
  beginShape();
  vertex(1600, 650);
  bezierVertex(1480, 696, 1370, 739, 1255, 753);
  bezierVertex(1373, 775, 1500, 803, 1600, 850);
  endShape(CLOSE);

  for (let i = 0; i < 240; i++) {
    let x = random(width), y = random(694, 820);
    stroke(119, 126, 104, random(2, 9));
    strokeWeight(random(1, 5));
    line(x, y, x + random(35, 260), y + random(-2, 2));
  }
}

function cypress(x, base, h, w) {
  noStroke();
  fill(18, 31, 28, 190);
  beginShape();
  vertex(x - w * 0.55, base);
  for (let j = 0; j <= 36; j++) {
    let t = j / 36;
    let bulge = pow(sin(t * PI / 2), 0.75);
    vertex(x - w * bulge * random(0.67, 1.03), base - h + h * t);
  }
  for (let j = 36; j >= 0; j--) {
    let t = j / 36;
    let bulge = pow(sin(t * PI / 2), 0.75);
    vertex(x + w * bulge * random(0.65, 1.03), base - h + h * t);
  }
  endShape(CLOSE);

  for (let i = 0; i < 550; i++) {
    let t = random(0.08, 1);
    let xx = x + random(-1, 1) * w * pow(t, 0.7) * 0.72;
    let yy = base - h + t * h;
    stroke(49, 60, 44, random(5, 22));
    strokeWeight(random(1, 3));
    line(xx, yy, xx + random(-6, 6), yy + random(9, 42));
  }
}

function water() {
  for (let i = 0; i < 8500; i++) {
    let y = random(765, 2000);
    let x = random(-100, 1700);
    let depth = (y - 765) / 1235;
    let n = noise(x * 0.004, y * 0.009);
    stroke(79 + n * 40, 95 + n * 24, 84 + n * 17,
           random(3, 14));
    strokeWeight(random(0.6, 2.6));
    let len = random(4, 55) * (0.6 + depth);
    line(x, y, x + len, y + random(-0.8, 0.8));
  }

  // Dim vertical trace of the distant light.
  for (let i = 0; i < 400; i++) {
    let y = random(790, 1080);
    let spread = map(y, 790, 1080, 30, 105);
    let x = 1090 + randomGaussian() * spread;
    stroke(160, 145, 93, random(2, 13));
    strokeWeight(random(1, 3));
