  p.bezierCurveTo(-364, -201, -320, -185, -297, -160);
  p.bezierCurveTo(-245, -204, -199, -208, -153, -184);
  p.bezierCurveTo(-40, -142, 69, -134, 178, -93);
  p.bezierCurveTo(260, -70, 340, -58, 404, -25);
  p.bezierCurveTo(436, -9, 458, 9, 466, 28);
  p.bezierCurveTo(280, 58, 89, 54, -68, 41);
  p.bezierCurveTo(-234, 49, -378, 26, -432, -12);
  p.bezierCurveTo(-449, -27, -457, -43, -458, -62);
