  g.addColorStop(0.38, "#c7c7ad");
  g.addColorStop(0.73, "#929f91");
  g.addColorStop(1, "#576f6b");
  ctx.fillStyle = g;
  ctx.fillRect(-520, -240, 1050, 340);

