  bezierVertex(-449, -181, -369, -199, -315, -151);
  bezierVertex(-342, -130, -354, -69, -402, -39);
  bezierVertex(-431, -42, -451, -68, -461, -99);
  endShape(CLOSE);

  fill(69, 91, 87, 90);
  beginShape();
  vertex(-321, -159);
  bezierVertex(-302, -123, -306, -69, -354, -18);
  bezierVertex(-304, -33, -260, -90, -271, -178);
  endShape(CLOSE);

  fill(242, 231, 198, 100);
  beginShape();
  vertex(-279, -169);
  bezierVertex(-230, -210, -185, -188, -153, -175);
  bezierVertex(-78, -139, 42, -132, 137, -96);
  bezierVertex(25, -111, -80, -91, -160, -75);
  bezierVertex(-212, -87, -258, -120, -279, -169);
  endShape(CLOSE);

  fill(60, 85, 83, 65);
  beginShape();
  vertex(-247, 28);
  bezierVertex(-177, -21, -113, -78, -40, -108);
  bezierVertex(-79, -50, -124, -7, -148, 44);
  endShape(CLOSE);

  fill(242, 232, 202, 83);
  beginShape();
  vertex(-145, 30);
  bezierVertex(-67, -61, -24, -103, 40, -111);
  bezierVertex(101, -94, 163, -85, 218, -62);
  bezierVertex(116, -61, 25, -16, -17, 39);
  endShape(CLOSE);

  fill(57, 80, 78, 70);
  beginShape();
  vertex(90, 47);
  bezierVertex(167, 6, 232, -24, 299, -51);
  bezierVertex(272, -5, 251, 25, 246, 52);
  endShape(CLOSE);

  // Each fold has a soft trough and a broken raised edge.
  let folds = [
    [-446,-111, -429,-72, -411,-38, -376,-12],
    [-332,-151, -327,-105, -339,-65, -372,-19],
    [-278,-162, -260,-105, -225,-67, -202,27],
    [-218,-182, -198,-137, -163,-115, -117,-95],
    [-88,-125, -124,-70, -190,-10, -231,24],
    [-18,-115, -56,-63, -94,-9, -121,39],
    [107,-99, 72,-65, 28,-4, 11,44],
    [182,-76, 153,-46, 119,13, 96,46],
    [282,-51, 237,-22, 209,13, 197,46],
    [347,-34, 327,-5, 321,18, 331,42],
