function leaf(x, y, angle, size, col, alpha) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(col[0], col[1], col[2], alpha);
  beginShape();
  vertex(-size * 0.7, 0);
  bezierVertex(-size * 0.1, -size * 0.45,
               size * 0.55, -size * 0.35, size, 0);
  bezierVertex(size * 0.25, size * 0.35,
               -size * 0.25, size * 0.35, -size * 0.7, 0);
  endShape(CLOSE);
  stroke(211, 167, 91, alpha * 0.45);
  strokeWeight(0.8);
  line(-size * 0.6, 0, size * 0.8, 0);
  pop();
}

function foreground() {
  // A sparse diagonal drift carries the eye beyond the vessel.
  const leaves = [
    [1255, 1428, -0.3, 18],
    [1148, 1514, 0.5, 12],
    [1300, 1602, -0.7, 24],
    [1005, 1709, 0.1, 16],
    [1110, 1817, 0.8, 27],
    [932, 1880, -0.4, 11]
  ];
  for (let a of leaves) {
    noStroke();
    fill(4, 17, 20, 100);
    ellipse(a[0] + 4, a[1] + 6, a[3] * 2.4, 9);
    noFill();
    stroke(125, 131, 106, 26);
    strokeWeight(1);
    arc(a[0], a[1] + 3, a[3] * 4, 14, 0, PI);
    leaf(a[0], a[1], a[2], a[3], [151, 98, 45], 190);
  }

  // Dark reeds at the near edge, cropped rather than ornamental.
  for (let i = 0; i < 43; i++) {
    let x = random(-70, 215);
    let y = random(1900, 2110);
    let h = random(65, 280);
    noFill();
    stroke(8, 20, 22, random(90, 190));
    strokeWeight(random(2, 5));
    bezier(x, y, x + 8, y - h * 0.4,
           x + 25, y - h * 0.75, x + random(20, 80), y - h);
  }

  // Glazed edges gently hold the composition.
  noFill();
  for (let i = 0; i < 95; i++) {
    stroke(5, 12, 15, 0.65);
    strokeWeight(8);
    rect(i * 2, i * 2, width - i * 4, height - i * 4);
  }
}

function grain() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (y * width + x);
      let g = random(-4.2, 4.2);
      // Slight canvas tooth, subordinate to the painted forms.
      let tooth = ((x % 3 === 0) ? -0.65 : 0.25)
                + ((y % 4 === 0) ? -0.6 : 0.2);
      pixels[i]     = constrain(pixels[i]     + g + tooth, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + g + tooth, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + g + tooth, 0, 255);
    }
  }
  updatePixels();
}

// p5.js 1.11 — self-contained, static painting
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  background(24, 34, 37);
  sky();
  distantWood();
  moon();
  river();
  foregroundTrees();
  boatReflection();
  boat();
  shroud();
  reeds();
  floatingLeaf();
  patina();
}

function sky() {
  noFill();
  for (let y = 0; y < 1150; y++) {
    let t = y / 1150;
    let n = noise(y * 0.008) * 9;
    stroke(25 + 39 * t + n, 35 + 40 * t + n, 39 + 34 * t + n);
    line(0, y, width, y);
  }

  // Broad, nearly dry atmospheric brushwork.
  noStroke();
  for (let i = 0; i < 13000; i++) {
    let x = random(width), y = random(1130);
    let light = noise(x * 0.002, y * 0.003);
    fill(114, 127, 120, random(2, 9) * light);
    ellipse(x, y, random(10, 95), random(2, 13));
  }

  for (let i = 0; i < 55; i++) {
    let y = random(740, 1110);
    fill(151, 157, 137, 3);
    ellipse(random(500, 1200), y, random(650, 1500), random(20, 95));
  }
}

function distantWood() {
  noStroke();
  for (let i = 0; i < 110; i++) {
    let x = random(width);
    let h = random(100, 480);
    let w = random(8, 27);
    fill(36, 54, 53, random(25, 75));
    beginShape();
    vertex(x - w, 1080);
    bezierVertex(x - w * 0.6, 960, x - w, 1080 - h * 0.7, x, 1080 - h);
    bezierVertex(x + w, 1080 - h * 0.65, x + w * 0.5, 980, x + w, 1080);
    endShape(CLOSE);
  }

  for (let i = 0; i < 2200; i++) {
    let x = random(width), y = random(1000, 1130);
    fill(29, 48, 46, random(5, 18));
    ellipse(x, y, random(10, 80), random(2, 12));
  }
}

function moon() {
  const x = 997, y = 466, r = 142;
  noStroke();

  for (let d = 560; d > 280; d -= 7) {
    fill(189, 172, 119, 1.5);
    ellipse(x, y, d, d);
  }

  fill(183, 170, 126);
  ellipse(x, y, r * 2, r * 2);

  const ctx = drawingContext;
  ctx.save();
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.clip();

  for (let i = 0; i < 11000; i++) {
    let px = random(x - r, x + r);
    let py = random(y - r, y + r);
    let n = noise(px * 0.019, py * 0.019);
    fill(71, 91, 80, 5 + n * 26);
    ellipse(px, py, random(1, 13), random(1, 5));
  }

  // The lower disk disappears into the atmosphere.
  for (let yy = y - r; yy < y + r; yy++) {
    let a = map(yy, y - r, y + r, 0, 94);
    stroke(59, 76, 72, a);
    line(x - r, yy, x + r, yy);
  }
  ctx.restore();
}

function river() {
  noFill();
  for (let y = 1090; y < height; y++) {
    let t = (y - 1090) / 910;
    stroke(44 - 24 * t, 62 - 29 * t, 60 - 25 * t);
    line(0, y, width, y);
  }

  for (let i = 0; i < 21000; i++) {
    let y = random(1090, height);
    let x = random(width);
    let t = (y - 1090) / 910;
    let n = noise(x * 0.004, y * 0.016);
    stroke(85 + n * 25, 105 + n * 19, 97 + n * 12, random(4, 22));
    strokeWeight(random(0.5, 2.3));
    let len = random(4, 45) * (0.35 + t);
    line(x, y, x + len, y + random(-1, 1));
  }

  // A broken, widening path of light.
  for (let i = 0; i < 4300; i++) {
    let y = random(1095, 1910);
    let t = (y - 1095) / 815;
    let spread = 30 + t * 170;
    let x = 997 - t * 80 + randomGaussian() * spread;
    let a = (1 - t * 0.78) * random(4, 27);
    stroke(182, 173, 130, a);
    strokeWeight(random(0.6, 2));
    line(x, y, x + random(3, 34) * (0.4 + t), y);
  }

  stroke(151, 158, 131, 28);
  strokeWeight(1);
  line(390, 1105, 1290, 1105);
}

function cypress(x, base, h, w, col) {
  noStroke();
  fill(...col);
  beginShape();
  vertex(x - w * 0.65, base);
  bezierVertex(x - w, base - h * 0.25,
               x - w * 0.48, base - h * 0.77,
               x + w * 0.03, base - h);
  bezierVertex(x + w * 0.55, base - h * 0.72,
               x + w, base - h * 0.27,
               x + w * 0.6, base);
  endShape(CLOSE);

  for (let i = 0; i < 1450; i++) {
    let t = random();
    let yy = base - h * t;
    let envelope = pow(sin(PI * t), 0.65) * w * 0.72;
    let xx = x + randomGaussian() * envelope * 0.45;
    fill(col[0] + random(-4, 9),
         col[1] + random(-3, 10),
         col[2] + random(-3, 8), random(12, 55));
    ellipse(xx, yy, random(3, 16), random(5, 27));
  }

  stroke(col[0] + 17, col[1] + 20, col[2] + 15, 45);
  strokeWeight(2);
  line(x + w * 0.12, base, x + w * 0.04, base - h * 0.69);
}

function foregroundTrees() {
  cypress(-35, 1175, 1180, 150, [15, 29, 30]);
  cypress(134, 1120, 930, 97, [20, 36, 35]);
  cypress(309, 1108, 645, 58, [29, 45, 42]);
