function hullPath(c) {
  c.beginPath();
  c.moveTo(233, 1326);
  c.bezierCurveTo(508, 1398, 1024, 1439, 1372, 1382);
  c.bezierCurveTo(1274, 1539, 1080, 1610, 815, 1578);
  c.bezierCurveTo(530, 1554, 335, 1497, 233, 1326);
  c.closePath();
}

function boat() {
  const c = drawingContext;
  c.save();
  hullPath(c);
  let g = c.createLinearGradient(0, 1330, 0, 1600);
  g.addColorStop(0, "#514b38");
  g.addColorStop(0.3, "#302f27");
  g.addColorStop(1, "#111e20");
  c.fillStyle = g;
  c.fill();
  c.clip();

  for (let i = 0; i < 3000; i++) {
    let x = random(220, 1390), y = random(1330, 1600);
    stroke(127, 109, 74, random(2, 16));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(7, 90), y + random(0, 8));
  }

  noFill();
  for (let j = 0; j < 5; j++) {
    stroke(7, 19, 21, 100);
    strokeWeight(2);
    bezier(230, 1351 + j * 34, 580, 1480 + j * 23,
           1090, 1538 + j * 15, 1375, 1397 + j * 35);
    stroke(143, 119, 76, 30);
    strokeWeight(1);
    bezier(230, 1348 + j * 34, 580, 1477 + j * 23,
           1090, 1535 + j * 15, 1375, 1394 + j * 35);
  }
  c.restore();

  // Interior: the cloth sits within, rather than atop, the hull.
  noStroke();
  fill(15, 25, 25);
  beginShape();
  vertex(251, 1328);
  bezierVertex(535, 1301, 1130, 1336, 1356, 1382);
  bezierVertex(1120, 1460, 561, 1408, 251, 1328);
  endShape(CLOSE);

  noFill();
  stroke(137, 117, 77, 145);
  strokeWeight(5);
  bezier(235, 1327, 560, 1403, 1100, 1455, 1370, 1383);
  stroke(190, 164, 111, 65);
  strokeWeight(1.5);
  bezier(247, 1325, 561, 1397, 1105, 1448, 1365, 1380);
}

function clothPath(c) {
  c.beginPath();
  c.moveTo(427, 1323);
  c.bezierCurveTo(449, 1296, 458, 1274, 477, 1257);
  c.bezierCurveTo(478, 1215, 512, 1190, 551, 1198);
  c.bezierCurveTo(588, 1198, 613, 1220, 624, 1252);
  c.bezierCurveTo(661, 1241, 706, 1246, 744, 1270);
  c.bezierCurveTo(816, 1274, 881, 1308, 948, 1323);
  c.bezierCurveTo(1013, 1332, 1049, 1354, 1099, 1359);
  c.bezierCurveTo(1135, 1358, 1178, 1377, 1214, 1396);
  c.bezierCurveTo(1154, 1415, 1094, 1419, 1039, 1401);
  c.bezierCurveTo(965, 1406, 903, 1398, 851, 1394);
  c.bezierCurveTo(792, 1405, 742, 1384, 692, 1387);
  c.bezierCurveTo(637, 1394, 597, 1367, 561, 1364);
  c.bezierCurveTo(510, 1362, 461, 1349, 427, 1323);
  c.closePath();
}

function shroud() {
  const c = drawingContext;
  c.save();
  clothPath(c);
  let g = c.createLinearGradient(660, 1200, 620, 1410);
  g.addColorStop(0, "#ddd9ba");
  g.addColorStop(0.33, "#c3c8ae");
  g.addColorStop(0.72, "#949f91");
  g.addColorStop(1, "#566e69");
  c.fillStyle = g;
  c.fill();
  c.clip();

  noStroke();
  for (let i = 0; i < 12000; i++) {
    let x = random(420, 1220), y = random(1190, 1420);
    let n = noise(x * 0.012, y * 0.019);
    fill(n > 0.5 ? 235 : 56, n > 0.5 ? 229 : 82,
         n > 0.5 ? 199 : 79, random(2, 10));
    ellipse(x, y, random(2, 15), random(1, 5));
  }

  // Long folds follow the weight and length of the body.
  noFill();
  for (let i = 0; i < 95; i++) {
    let x = random(590, 1110);
    let y = 1254 + (x - 590) * 0.21 + random(-10, 25);
    let endX = x + random(-85, 65);
    let endY = random(1374, 1426);
    stroke(42, 68, 66, random(7, 23));
    strokeWeight(random(1, 6));
    bezier(x, y, x - 12, y + 30, endX - 25, endY - 25, endX, endY);
    stroke(241, 233, 201, random(7, 25));
    strokeWeight(random(0.6, 2));
    bezier(x + 5, y, x - 7, y + 30,
           endX - 20, endY - 25, endX + 5, endY);
  }

  // Quiet concentric folds cover the head; no face is exposed.
  for (let i = 0; i < 22; i++) {
    stroke(78, 98, 87, 13);
    strokeWeight(random(1, 3));
    bezier(477 + i * 2, 1270,
           480 + i * 1.5, 1204 + i,
           575 + i, 1200 + i * 2,
           608 + i * 1.4, 1305 + i * 3);
  }

  stroke(244, 235, 202, 100);
  strokeWeight(2);
  bezier(482, 1248, 489, 1208, 533, 1195, 568, 1210);
  bezier(650, 1260, 699, 1250, 729, 1273, 769, 1280);
  c.restore();

  // A narrow, uneven hem.
  noFill();
  stroke(207, 205, 174, 86);
  strokeWeight(1.4);
  bezier(438, 1325, 515, 1364, 551, 1343, 599, 1371);
  bezier(856, 1390, 976, 1389, 1085, 1421, 1206, 1395);
}

