// p5.js 1.11 — self-contained, still image
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  noStroke();

  paintSky();
  paintMoon();
  paintDistance();
  paintWater();
  paintSubmergedBranches();
  paintBoat();
  paintShroud();
  paintMoth();
  finishSurface();
}

function paintSky() {
  const upper = color(25, 36, 42);
  const lower = color(106, 116, 111);

  for (let y = 0; y < 1090; y += 2) {
    let t = y / 1090;
    let c = lerpColor(upper, lower, pow(t, 1.4));
    fill(red(c), green(c), blue(c));
    rect(0, y, width, 3);
  }

  // Thin, rubbed layers of atmospheric pigment.
  for (let i = 0; i < 23000; i++) {
    let x = random(width);
    let y = random(1100);
    let n = noise(x * 0.002, y * 0.003);
    fill(156 + n * 25, 159 + n * 17, 142 + n * 12, random(2, 9));
    ellipse(x, y, random(8, 95), random(1, 6));
  }

  // Smoky edges keep the illumination inside the painting.
  for (let i = 0; i < 6500; i++) {
    let x = random(width);
    let y = random(1120);
    let edge = pow(abs(x - 800) / 800, 2);
    fill(13, 27, 33, 9 * edge);
    ellipse(x, y, random(30, 170), random(5, 35));
  }
}

function paintMoon() {
  const cx = 850, cy = 492, r = 192;

  for (let d = 520; d > 384; d -= 6) {
    fill(185, 160, 109, 2);
    ellipse(cx, cy, d, d);
  }

  fill(181, 164, 120);
  ellipse(cx, cy, r * 2);

  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.arc(cx, cy, r, 0, TWO_PI);
  drawingContext.clip();

  for (let i = 0; i < 12500; i++) {
    let x = random(cx - r, cx + r);
    let y = random(cy - r, cy + r);
    let n = noise(x * 0.018, y * 0.018);
    fill(104 + 105 * n, 96 + 92 * n, 70 + 69 * n, random(10, 40));
    ellipse(x, y, random(1, 7), random(1, 4));
  }

  // A veil crosses the lower portion of the sun.
  for (let y = 480; y < 710; y += 2) {
    fill(72, 87, 89, map(y, 480, 710, 0, 105));
    rect(cx - r - 2, y, r * 2 + 4, 3);
  }
  drawingContext.restore();
}

function paintDistance() {
  for (let layer = 0; layer < 4; layer++) {
    let base = 855 + layer * 55;
    fill(55 - layer * 5, 73 - layer * 6, 77 - layer * 6, 90);
    beginShape();
    vertex(0, 1100);
    for (let x = 0; x <= width; x += 12) {
      let y = base - noise(x * 0.0028, layer * 5) * 125;
      vertex(x, y);
    }
    vertex(width, 1100);
    endShape(CLOSE);
  }

  // Almost-erased trees on the far shore.
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let y = 950 + noise(x * 0.005) * 45;
    let h = random(12, 75);
    fill(36, 56, 61, random(12, 40));
    triangle(x - h * 0.09, y, x, y - h, x + h * 0.09, y);
  }

  for (let i = 0; i < 1600; i++) {
    let x = random(width);
    let y = random(850, 1080);
    fill(150, 157, 143, random(2, 7));
    ellipse(x, y, random(60, 350), random(1, 8));
