}

function paintWater() {
  for (let y = 1010; y < height; y += 2) {
    let t = (y - 1010) / 990;
    let c = lerpColor(color(55, 77, 81), color(12, 28, 35), t);
    fill(c);
    rect(0, y, width, 3);
  }

  // Broken, shallow brushstrokes establish the water's plane.
  for (let i = 0; i < 27000; i++) {
    let y = random(1010, 2000);
    let x = random(width);
    let t = (y - 1010) / 990;
    let n = noise(x * 0.009, y * 0.025);
    stroke(64 + n * 40, 88 + n * 31, 91 + n * 27, random(6, 24));
    strokeWeight(random(0.5, 2.5));
    let len = random(3, 35) * (0.4 + t * 2);
    line(x, y, x + len, y + random(-1, 1));
  }

  // The sun's reflection is dispersed, never a solid column.
  for (let i = 0; i < 3900; i++) {
    let y = random(1015, 1990);
    let t = (y - 1015) / 975;
    let spread = 30 + t * 145;
    let x = 850 + sin(y * 0.018) * 17 + randomGaussian() * spread;
    stroke(174, 151, 99, random(4, 24) * (1 - t * 0.45));
    strokeWeight(random(0.6, 2));
    line(x, y, x + random(3, 25 + t * 40), y);
  }
  noStroke();

  // The vessel's diffuse shadow.
  for (let i = 0; i < 36; i++) {
    fill(5, 17, 24, 4);
    ellipse(805, 1500, 1130 - i * 13, 180 - i * 3);
  }
}

function root(x, y, angle, len, weight, depth) {
  if (depth <= 0 || len < 7) return;
  let bend = random(-0.32, 0.32);
  let ex = x + cos(angle + bend) * len;
  let ey = y + sin(angle + bend) * len;
  noFill();
  stroke(83, 104, 99, 25 + depth * 3);
  strokeWeight(weight);
  bezier(
    x, y,
    x + cos(angle) * len * 0.35,
    y + sin(angle) * len * 0.35,
    ex - cos(angle + bend) * len * 0.25,
    ey - sin(angle + bend) * len * 0.25,
    ex, ey
  );
  root(ex, ey, angle + bend + random(-0.3, 0.3),
       len * 0.77, weight * 0.68, depth - 1);
  if (depth > 2) {
    root(ex, ey, angle + bend + random([-1, 1]) * random(0.35, 0.8),
         len * 0.55, weight * 0.52, depth - 1);
  }
}

function paintSubmergedBranches() {
