function finishSurface() {
  // Fine canvas tooth and a restrained edge-darkening.
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let index = 4 * (y * width + x);
      let dx = (x - 800) / 800;
      let dy = (y - 1000) / 1000;
      let vignette = 1 - 0.15 * pow(constrain(
        (dx * dx + dy * dy) / 2, 0, 1), 1.3);
      let tooth = random(-3.2, 3.2)
        + (x % 3 === 0 ? 0.8 : -0.3)
        + (y % 4 === 0 ? 0.6 : 0);
      pixels[index] = constrain(pixels[index] * vignette + tooth, 0, 255);
      pixels[index + 1] = constrain(pixels[index + 1] * vignette + tooth, 0, 255);
      pixels[index + 2] = constrain(pixels[index + 2] * vignette + tooth, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

const stops = [
  [0, [8, 10, 30]],
  [500, [22, 24, 58]],
  [950, [52, 42, 84]],
  [1220, [120, 78, 98]],
  [1340, [196, 128, 92]],
  [1410, [232, 170, 110]]
];

function skyCol(y) {
  y = constrain(y, 0, 1410);
  for (let i = 0; i < stops.length - 1; i++) {
    let a = stops[i], b = stops[i + 1];
    if (y >= a[0] && y <= b[0]) {
      let t = (y - a[0]) / (b[0] - a[0]);
      return [lerp(a[1][0], b[1][0], t), lerp(a[1][1], b[1][1], t), lerp(a[1][2], b[1][2], t)];
    }
  }
  return stops[stops.length - 1][1];
}

function draw() {
  // Sky gradient
  for (let y = 0; y < 1420; y++) {
    let c = skyCol(y);
    stroke(c[0], c[1], c[2]);
    line(0, y, width, y);
  }

  // Painterly sky strokes
  for (let i = 0; i < 11000; i++) {
    let x = random(-50, width + 50), y = random(1420);
    let c = skyCol(y + random(-50, 50));
    let n = noise(x * 0.003, y * 0.003);
    let k = map(n, 0, 1, 0.8, 1.2);
    stroke(c[0] * k, c[1] * k, c[2] * k, 38);
    strokeWeight(random(2, 7));
    let ang = (noise(x * 0.0015, y * 0.004) - 0.5) * 0.7;
    let len = random(20, 70);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  // Stars
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = random(width), y = pow(random(), 1.6) * 1150;
    let a = map(y, 0, 1150, 220, 10) * random(0.3, 1);
    let r = random() < 0.05 ? random(3, 5) : random(1, 2.5);
    fill(255, 245, 225, a * 0.25);
    ellipse(x, y, r * 4);
    fill(255, 248, 235, a);
    ellipse(x, y, r);
  }

  // Low glow near horizon
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(1100, 1400, 10, 1100, 1400, 700);
  g.addColorStop(0, 'rgba(255,190,120,0.35)');
  g.addColorStop(1, 'rgba(255,190,120,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 700, width, 800);

  // Distant hills
  fill(30, 22, 38);
  noStroke();
  beginShape();
  vertex(0, 1500);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, 1395 - noise(x * 0.003, 5) * 70);
  }
  vertex(width, 1500);
  endShape(CLOSE);

  // Field
  for (let y = 1360; y < 2000; y++) {
    let t = map(y, 1360, 2000, 0, 1);
    stroke(lerp(28, 8, t), lerp(24, 9, t), lerp(34, 14, t));
    line(0, y + noise(y) * 0, width, y);
  }
  // Re-draw hills edge softly over field top
  fill(24, 19, 32);
  noStroke();
  beginShape();
  vertex(0, 1450);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, 1415 - noise(x * 0.005, 9) * 35);
  }
  vertex(width, 1450);
  endShape(CLOSE);

  // Grass
  noFill();
  for (let i = 0; i < 7000; i++) {
    let x = random(-20, width + 20);
    let y = random(1400, 2040);
    let t = map(y, 1400, 2000, 0, 1);
    let h = lerp(12, 110, t) * random(0.5, 1.2);
    let lean = (noise(x * 0.004, y * 0.004) - 0.4) * h * 0.8;
    let warm = map(y, 1400, 1700, 1, 0, true);
    stroke(lerp(18, 90, warm * random(0.3, 1)), lerp(22, 60, warm * random(0.3, 1)), lerp(20, 50, warm), random(90, 200));
    strokeWeight(lerp(1, 3, t));
    bezier(x, y, x, y - h * 0.4, x + lean * 0.5, y - h * 0.7, x + lean, y - h);
  }

  // Stem
  noFill();
  stroke(70, 80, 62);
  strokeWeight(9);
  bezier(900, 2050, 890, 1650, 760, 1300, 762, 985);
  stroke(150, 140, 110, 120);
  strokeWeight(2.5);
  bezier(904, 2050, 894, 1650, 766, 1300, 766, 985);

  const HX = 762, HY = 965;

  // Halo around head
  let g2 = ctx.createRadialGradient(HX, HY, 5, HX, HY, 320);
  g2.addColorStop(0, 'rgba(255,235,210,0.12)');
  g2.addColorStop(1, 'rgba(255,235,210,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(HX - 340, HY - 340, 680, 680);

  // Generate seeds on sphere
  let w = createVector(0.72, -0.66, 0.15).normalize();
  let seeds = [];
  for (let i = 0; i < 190; i++) {
    let u = random(-1, 1), th = random(TWO_PI);
    let s = sqrt(1 - u * u);
    let d = createVector(s * cos(th), s * sin(th), u);
    let gone = d.dot(w) > -0.15 && random() < 0.9;
    seeds.push({ d: d, gone: gone, L: 175 * random(0.88, 1.04) });
  }
  seeds.sort((a, b) => a.d.z - b.d.z);

  // Receptacle
  noStroke();
  fill(95, 72, 50);
  ellipse(HX, HY, 46, 42);
  fill(130, 100, 70, 160);
  ellipse(HX - 5, HY - 5, 26, 22);

  for (let sd of seeds) {
    let d = sd.d;
    let px = d.x, py = d.y;
    let front = map(d.z, -1, 1, 0.35, 1);
    if (sd.gone) {
      fill(50, 36, 26, 200 * front);
      ellipse(HX + px * 18, HY + py * 16, 4, 4);
      continue;
    }
    let tx = HX + px * sd.L, ty = HY + py * sd.L;
    let ax = HX + px * 34, ay = HY + py * 34;
    // achene
    stroke(70, 52, 36, 230 * front);
    strokeWeight(4);
    line(HX + px * 16, HY + py * 16, ax, ay);
    // beak
    stroke(225, 215, 195, 170 * front);
    strokeWeight(1.2);
    line(ax, ay, tx, ty);
    // pappus
    let base = atan2(py, px);
    let plen = 46;
    noStroke();
    fill(255, 240, 220, 10 * front);
    ellipse(tx, ty, 80, 80);
    for (let f = 0; f < 30; f++) {
      let an = base + random(-1.5, 1.5);
      let l = plen * random(0.6, 1) * map(abs(an - base), 0, 1.5, 1, 0.75);
      stroke(250, 244, 232, random(60, 140) * front);
      strokeWeight(random(0.6, 1.3));
      line(tx, ty, tx + cos(an) * l, ty + sin(an) * l);
    }
  }

  // Rising seeds becoming stars
  for (let i = 0; i < 62; i++) {
    let t = i / 61;
    let x = 860 + t * 600 + sin(t * 6.5 + 1) * 110 + random(-90, 90) * (0.2 + t);
    let y = 860 - pow(t, 0.85) * 800 + random(-50, 50);
    let s = lerp(1.0, 0.12, pow(t, 0.8));
    let a = lerp(235, 150, t);
    if (t < 0.8) floatingSeed(x, y, s, random(-0.5, 0.5) + 0.2, a);
    if (t > 0.45) {
      let b = map(t, 0.45, 1, 0, 1);
      noStroke();
      fill(255, 245, 225, 40 * b);
      ellipse(x, y - 8 * s, 18 * b + 4);
      fill(255, 250, 238, 230 * b);
      ellipse(x, y - 8 * s, 2.5 + 2 * b);
    }
  }

  // A few seeds returning to earth
  floatingSeed(1180, 1250, 0.8, -1.0, 200);
  floatingSeed(430, 1560, 0.9, 1.3, 140);
  floatingSeed(1250, 1700, 1.0, -1.4, 110);

  // Vignette
  let g3 = ctx.createRadialGradient(800, 1000, 500, 800, 1000, 1400);
  g3.addColorStop(0, 'rgba(0,0,0,0)');
  g3.addColorStop(1, 'rgba(0,0,8,0.65)');
  ctx.fillStyle = g3;
  ctx.fillRect(0, 0, width, height);

  // Grain
  for (let i = 0; i < 60000; i++) {
    stroke(random() < 0.5 ? 0 : 255, 10);
    strokeWeight(1);
    point(random(width), random(height));
  }
}

function floatingSeed(x, y, s, rot, a) {
  push();
  translate(x, y);
  rotate(rot);
  // glow
  noStroke();
  fill(255, 240, 220, a * 0.06);
  ellipse(0, -10 * s, 90 * s, 90 * s);
  // stalk
  stroke(230, 220, 200, a * 0.8);
  strokeWeight(max(0.6, 1.2 * s));
  line(0, 0, 0, 52 * s);
  // achene
  stroke(80, 60, 40, a);
  strokeWeight(max(1, 4 * s));
  line(0, 46 * s, 0, 64 * s);
  // umbrella
  for (let f = 0; f < 28; f++) {
    let an = -HALF_PI + random(-1.45, 1.45);
    let l = 40 * s * random(0.65, 1);
    stroke(252, 246, 236, a * random(0.4, 0.75));
    strokeWeight(max(0.5, 1.1 * s));
    line(0, 0, cos(an) * l, sin(an) * l + 6 * s);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // --- Sky gradient ---
  const cTop = color(6, 8, 24);
  const cMid = color(36, 34, 74);
  const cLow = color(150, 92, 86);
  const cHor = color(214, 140, 84);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.55) c = lerpColor(cTop, cMid, t / 0.55);
    else if (t < 0.8) c = lerpColor(cMid, cLow, (t - 0.55) / 0.25);
    else c = lerpColor(cLow, cHor, (t - 0.8) / 0.12);
    stroke(c);
    line(0, y, width, y);
  }

  // --- Grain ---
  noStroke();
  for (let i = 0; i < 60000; i++) {
    fill(255, 255, 255, random(3, 9));
    rect(random(width), random(height), 1.5, 1.5);
  }

  // --- Stars ---
  for (let i = 0; i < 420; i++) {
    let x = random(width);
    let y = pow(random(), 1.6) * 1300;
    let a = map(y, 0, 1300, 220, 30) * random(0.4, 1);
    let r = random(1, 3.2);
    fill(255, 245, 225, a * 0.25);
    circle(x, y, r * 4);
    fill(255, 248, 235, a);
    circle(x, y, r);
  }

  const hx = 720, hy = 820;

  // --- Soft glow around head ---
  for (let r = 700; r > 0; r -= 6) {
    fill(255, 220, 180, 2.2 * (1 - r / 700));
    circle(hx, hy - 60, r);
  }

  // --- Distant hill ---
  fill(30, 22, 34);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, 1760 + (noise(x * 0.002) - 0.5) * 120);
  }
  vertex(width, height);
  endShape(CLOSE);

  // --- Stem (bowed) ---
  const P = [[1000, 2050], [1020, 1500], [600, 1300], [hx, hy + 24]];
  for (let i = 0; i < 400; i++) {
    let t1 = i / 400, t2 = (i + 1) / 400;
    let x1 = bezierPoint(P[0][0], P[1][0], P[2][0], P[3][0], t1);
    let y1 = bezierPoint(P[0][1], P[1][1], P[2][1], P[3][1], t1);
    let x2 = bezierPoint(P[0][0], P[1][0], P[2][0], P[3][0], t2);
    let y2 = bezierPoint(P[0][1], P[1][1], P[2][1], P[3][1], t2);
    let w = lerp(16, 7, t1);
    stroke(48, 44, 46);
    strokeWeight(w);
    line(x1, y1, x2, y2);
    stroke(190, 140, 110, 90);
    strokeWeight(w * 0.25);
    line(x1 + w * 0.3, y1, x2 + w * 0.3, y2);
  }

  // --- Bent-back bracts ---
  stroke(52, 48, 48);
  strokeWeight(4);
  noFill();
  for (let i = 0; i < 9; i++) {
    let a = map(i, 0, 8, 0.3, PI - 0.3);
    let sx = hx + cos(a + PI) * 22;
    let sy = hy + 18;
    bezier(sx, sy, sx + cos(a + PI) * 30, sy + 10,
           sx + cos(a + PI) * 40, sy + 40, sx + cos(a + PI) * 30 + random(-8, 8), sy + 70 + random(-10, 10));
  }

  // --- Drifting seeds ---
  let drifting = [];
  for (let i = 0; i < 170; i++) {
    let t = pow(random(), 0.85);
    let px = hx - 380 * t + (noise(i * 0.31, t * 2) - 0.5) * 900 * t + random(-30, 30);
    let py = hy - 80 - t * 1000 + random(-50, 50);
    drifting.push({ x: px, y: py, t: t });
  }
  drifting.sort((a, b) => b.t - a.t);
  for (let d of drifting) {
    if (d.y < -20) continue;
    if (d.t > 0.86) {
      noStroke();
      fill(255, 245, 230, 40);
      circle(d.x, d.y, 10);
      fill(255, 250, 240, 200);
      circle(d.x, d.y, 2.6);
    } else {
      let s = lerp(0.95, 0.22, d.t) * random(0.85, 1.1);
      let al = lerp(235, 110, d.t);
      drawSeed(d.x, d.y, PI / 2 + random(-0.6, 0.6), s, al);
    }
  }

  // --- Bare receptacle ---
  noStroke();
  fill(196, 178, 150);
  ellipse(hx, hy, 64, 54);
  fill(226, 212, 186);
  ellipse(hx - 8, hy - 8, 34, 24);
  for (let i = 0; i < 70; i++) {
    let a = random(TWO_PI), r = sqrt(random()) * 26;
    fill(120, 100, 84, 180);
    circle(hx + cos(a) * r, hy + sin(a) * r * 0.85, 2.4);
  }

  // --- Last clinging seeds ---
  let clinging = [2.0, 2.35, 2.7, 3.1, 0.55, 0.9, 1.25, 1.6, 4.4, -0.2];
  for (let a of clinging) {
    let bx = hx + cos(a) * 24, by = hy + sin(a) * 20;
    drawSeed(bx, by, a + PI, 1.0, 240);
  }

  // --- Fallen seeds in the grass, beginning to sprout ---
  for (let i = 0; i < 7; i++) {
    let x = random(150, 1450), y = random(1880, 1960);
    stroke(220, 200, 170, 160);
    strokeWeight(2);
    line(x, y, x + 10, y + 3);
    stroke(90, 130, 80, 200);
    strokeWeight(2.5);
    noFill();
    bezier(x, y, x - 4, y - 14, x + 4, y - 24, x + 2, y - 34);
    noStroke();
    fill(100, 145, 85, 210);
    ellipse(x + 6, y - 34, 10, 5);
    ellipse(x - 3, y - 32, 9, 4);
  }

  // --- Foreground grass ---
  noFill();
  for (let i = 0; i < 700; i++) {
    let x = random(-50, 1650);
    let h = random(80, 360) * (0.6 + noise(x * 0.004) * 0.8);
    let lean = random(-90, 90) + (noise(x * 0.01) - 0.5) * 120;
    let c = random(10, 24);
    stroke(c, c * 0.85, c * 1.2);
    strokeWeight(random(2, 6));
    bezier(x, height + 10, x, height - h * 0.4, x + lean * 0.5, height - h * 0.8, x + lean, height - h);
  }
  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let h = random(120, 320);
    let lean = random(-60, 60);
    stroke(230, 150, 90, 50);
    strokeWeight(1.2);
    bezier(x, height, x, height - h * 0.4, x + lean * 0.5, height - h * 0.8, x + lean, height - h);
  }
}

function drawSeed(x, y, a, s, al) {
  push();
  translate(x, y);
  rotate(a);
  // seed body
  noStroke();
  fill(150, 120, 95, al);
  ellipse(-7 * s, 0, 18 * s, 4.5 * s);
  // beak
  stroke(235, 225, 205, al);
  strokeWeight(max(0.6, 1.3 * s));
  line(0, 0, 90 * s, 0);
  // pappus filaments
  strokeWeight(max(0.4, 0.75 * s));
  let n = 28;
  for (let i = 0; i < n; i++) {
    let ang = map(i, 0, n - 1, -1.25, 1.25) + random(-0.05, 0.05);
    let len = 56 * s * random(0.85, 1.05);
    let ex = 90 * s + cos(ang) * len, ey = sin(ang) * len;
    stroke(240, 232, 215, al * 0.85);
    line(90 * s, 0, ex, ey);
    noStroke();
    fill(255, 250, 240, al * 0.7);
    circle(ex, ey, 1.8 * s + 0.6);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function skyCol(y) {
  const c0 = color(10, 14, 44);
  const c1 = color(40, 44, 92);
  const c2 = color(118, 86, 120);
  const c3 = color(232, 166, 104);
  let t = constrain(y / 1580, 0, 1);
  if (t < 0.45) return lerpColor(c0, c1, t / 0.45);
  if (t < 0.8) return lerpColor(c1, c2, (t - 0.45) / 0.35);
  return lerpColor(c2, c3, (t - 0.8) / 0.2);
}

function draw() {
  // Sky gradient
  for (let y = 0; y < 1620; y++) {
    stroke(skyCol(y));
    line(0, y, width, y);
  }

  // Painterly sky strokes
  for (let i = 0; i < 6000; i++) {
    let x = random(width), y = random(1600);
    let c = skyCol(y + random(-40, 40));
    let a = noise(x * 0.002, y * 0.002) * TWO_PI * 0.5 - 0.25;
    stroke(red(c) + random(-8, 8), green(c) + random(-8, 8), blue(c) + random(-8, 8), 50);
    strokeWeight(random(2, 7));
    let L = random(20, 70);
    line(x, y, x + cos(a) * L, y + sin(a) * L * 0.3);
  }

  // Horizon glow
  noStroke();
  for (let r = 900; r > 0; r -= 10) {
    fill(255, 190, 120, 3);
    ellipse(1150, 1580, r * 2.2, r * 0.9);
  }

  // Stars
  for (let i = 0; i < 520; i++) {
    let x = random(width);
    let y = pow(random(), 1.7) * 1250;
    let s = random(1, 3);
    let a = random(80, 230) * (1 - y / 1500);
    fill(255, 245, 225, a * 0.15);
    ellipse(x, y, s * 5, s * 5);
    fill(255, 248, 235, a);
    ellipse(x, y, s, s);
  }

  // Distant hills
  fill(30, 24, 42);
  beginShape();
  vertex(0, 2000);
  for (let x = 0; x <= width; x += 8) {
    vertex(x, 1545 + noise(x * 0.002, 5) * 80 - 30);
  }
  vertex(width, 2000);
  endShape(CLOSE);

  fill(20, 17, 28);
  beginShape();
  vertex(0, 2000);
  for (let x = 0; x <= width; x += 8) {
    vertex(x, 1610 + noise(x * 0.003, 20) * 60);
  }
  vertex(width, 2000);
  endShape(CLOSE);

  // Field gradient
  for (let y = 1660; y < 2000; y++) {
    let t = (y - 1660) / 340;
    stroke(lerpColor(color(22, 18, 30), color(8, 8, 12), t));
    line(0, y, width, y);
  }

  // Grass
  noFill();
  for (let i = 0; i < 3200; i++) {
    let bx = random(-20, width + 20);
    let by = random(1630, 2060);
    let h = random(25, 130) * map(by, 1630, 2060, 0.5, 1.4);
    let lean = (noise(bx * 0.004, by * 0.004) - 0.4) * 60;
    let warm = random() < 0.25;
    if (warm) stroke(150, 105, 80, 70);
    else stroke(random(10, 30), random(10, 26), random(18, 34), 200);
    strokeWeight(random(1, 3));
    bezier(bx, by, bx, by - h * 0.4, bx + lean * 0.5, by - h * 0.7, bx + lean, by - h);
  }

  // Stem
  noFill();
  stroke(60, 66, 54);
  strokeWeight(12);
  bezier(770, 2060, 745, 1720, 610, 1470, 640, 1215);
  stroke(168, 172, 146, 200);
  strokeWeight(4);
  bezier(766, 2060, 741, 1720, 606, 1470, 636, 1215);

  const cx = 640, cy = 1200;

  // Soft glow around head
  noStroke();
  for (let r = 260; r > 0; r -= 8) {
    fill(255, 240, 220, 3);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // Remaining seeds
  for (let i = 0; i < 110; i++) {
    let th = map(i, 0, 110, 0, TWO_PI) + random(-0.03, 0.03);
    let inGap = th > PI * 1.05 && th < PI * 1.92;
    let nearGap = (th > PI * 0.9 && th < PI * 1.05) || (th > PI * 1.92 || th < 0.15);
    if (inGap) continue;
    if (nearGap && random() < 0.5) continue;
    let r = random(118, 138);
    drawSeed(cx + cos(th) * r, cy + sin(th) * r, th + HALF_PI, 1, r, 225);
  }

  // Receptacle
  fill(110, 96, 74);
  ellipse(cx, cy, 34, 34);
  fill(150, 132, 100);
  ellipse(cx - 4, cy - 4, 16, 16);

  // Drifting seeds becoming stars
  for (let i = 0; i < 170; i++) {
    let t = pow(random(), 1.25);
    let px = cx + 40 + t * 660 + (noise(t * 3, 9) - 0.5) * 320;
    let py = cy - 60 - t * 1100;
    let spread = 20 + t * 280;
    let x = px + randomGaussian() * spread * 0.6;
    let y = py + randomGaussian() * spread * 0.35;
    let s = lerp(0.9, 0.1, t);
    let a = lerp(225, 90, pow(t, 0.8));
    if (t > 0.55) {
      let k = (t - 0.55) / 0.45;
      noStroke();
      fill(255, 240, 210, 18 * k);
      ellipse(x, y, 40 * k + 6, 40 * k + 6);
      fill(255, 250, 238, 200 * k);
      ellipse(x, y, 2 + 2.5 * k, 2 + 2.5 * k);
    }
    if (t < 0.92) {
      drawSeed(x, y, random(-0.4, 0.6) + 0.25, s, 70, a * (t > 0.55 ? 1 - (t - 0.55) / 0.4 : 1));
    }
  }

  // Grain
  for (let i = 0; i < 90000; i++) {
    let x = random(width), y = random(height);
    stroke(random() < 0.5 ? 0 : 255, random(6, 16));
    strokeWeight(1);
    point(x, y);
  }

  // Vignette
  noFill();
  for (let i = 0; i < 300; i++) {
    stroke(0, 0, 0, map(i, 0, 300, 0, 2.2));
    strokeWeight(6);
    rect(-i * 3 + 900, -i * 3 + 900, width - 1800 + i * 6, height - 1800 + i * 6);
  }
}

function drawSeed(x, y, rot, s, stalk, a) {
  if (a <= 2) return;
  push();
  translate(x, y);
  rotate(rot);
  stroke(235, 228, 214, a * 0.85);
  strokeWeight(max(0.5, 1.4 * s));
  line(0, 0, 0, stalk * s);
  noStroke();
  fill(96, 82, 60, a);
  ellipse(0, stalk * s, 4 * s + 1, 14 * s + 1);
  noStroke();
  fill(255, 248, 235, a * 0.07);
  ellipse(0, -22 * s, 100 * s, 70 * s);
  let n = 24;
  for (let k = 0; k <= n; k++) {
    let ang = map(k, 0, n, -1.4, 1.4) + random(-0.04, 0.04);
    let L = 50 * s * random(0.82, 1.12);
    let dx = sin(ang) * L, dy = -cos(ang) * L;
    stroke(248, 244, 236, a * 0.75);
    strokeWeight(0.5 + 0.7 * s);
    line(0, 0, dx, dy);
    stroke(255, 252, 245, a);
    strokeWeight(1 + 1.5 * s);
    point(dx, dy);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // Sky gradient
  const stops = [
    [0.0, color(6, 8, 26)],
    [0.35, color(24, 26, 64)],
    [0.62, color(78, 60, 98)],
    [0.82, color(196, 120, 96)],
    [0.95, color(236, 178, 112)],
    [1.0, color(244, 196, 128)]
  ];
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    for (let i = 0; i < stops.length - 1; i++) {
      if (t >= stops[i][0] && t <= stops[i + 1][0]) {
        let u = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        c = lerpColor(stops[i][1], stops[i + 1][1], u);
      }
    }
    stroke(c);
    line(0, y, width, y);
  }

  // Background stars
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = pow(random(), 1.8) * 1300;
    let a = map(y, 0, 1300, 220, 0) * random(0.3, 1);
    fill(255, 250, 235, a);
    circle(x, y, random(0.8, 2.6));
  }

  // Distant hills
  noStroke();
  fill(70, 44, 60, 200);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, 1760 - noise(x * 0.0015) * 140);
  }
  vertex(width, height);
  endShape(CLOSE);

  fill(38, 26, 40);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, 1860 - noise(x * 0.002 + 50) * 90);
  }
  vertex(width, height);
  endShape(CLOSE);

  // Grass silhouettes
  noFill();
  for (let i = 0; i < 1100; i++) {
    let x = random(-50, width + 50);
    let base = height + 10;
    let h = random(60, 300) * (0.6 + noise(x * 0.004) * 0.8);
    let bend = random(-90, 90);
    stroke(18 + random(10), 14 + random(8), 24 + random(10));
    strokeWeight(random(1.5, 4.5));
    bezier(x, base, x, base - h * 0.4, x + bend * 0.5, base - h * 0.8, x + bend, base - h);
  }

  // Head position
  const hx = 620, hy = 1300;

  // Stem
  stroke(30, 24, 30);
  strokeWeight(11);
  noFill();
  bezier(700, height + 20, 690, 1780, 580, 1550, hx, hy + 20);
  stroke(70, 60, 60, 120);
  strokeWeight(3);
  bezier(703, height + 20, 694, 1780, 586, 1550, hx + 3, hy + 20);

  // Soft halo around head
  noStroke();
  for (let r = 420; r > 0; r -= 12) {
    fill(255, 225, 190, 3);
    circle(hx, hy, r);
  }

  // Attached seeds (the remaining half)
  for (let i = 0; i < 170; i++) {
    let a = random(-PI, PI);
    let inGap = a > -PI * 0.78 && a < PI * 0.08;
    if (inGap && random() < 0.9) continue;
    let bx = hx + cos(a) * 20;
    let by = hy + sin(a) * 20;
    seed(bx, by, a, random(125, 150), 1, 210, true);
  }

  // Receptacle
  noStroke();
  fill(96, 72, 54);
  circle(hx, hy, 52);
  for (let i = 0; i < 60; i++) {
    let a = random(TWO_PI), r = random(22);
    fill(60, 44, 36);
    circle(hx + cos(a) * r, hy + sin(a) * r, 3);
  }

  // Drifting seeds becoming stars
  for (let i = 0; i < 130; i++) {
    let t = pow(random(), 0.85);
    let y = hy - 120 - t * 1240;
    let x = hx + 90 + t * 620 + (noise(i * 0.27, t * 2.2) - 0.5) * 900 * (0.25 + t);
    x = constrain(x, 40, width - 40);
    let s = lerp(0.85, 0.1, t);
    let fade = constrain(map(t, 0.5, 0.95, 230, 0), 0, 230);
    let glow = constrain(map(t, 0.35, 1, 0, 1), 0, 1);
    let tilt = (noise(i * 0.5, 9) - 0.5) * 1.2;

    if (glow > 0) {
      noStroke();
      for (let r = 70 * glow + 6; r > 1; r -= 3) {
        fill(255, 240, 210, 7 * glow);
        circle(x, y - 40 * s, r);
      }
      fill(255, 250, 235, 255 * glow);
      circle(x, y - 40 * s, 2 + 3 * glow);
    }
    if (fade > 2) {
      seed(x, y, -HALF_PI + tilt, 130, s, fade, false);
    }
  }

  // Film grain
  noStroke();
  for (let i = 0; i < 60000; i++) {
    fill(random() < 0.5 ? 0 : 255, 10);
    rect(random(width), random(height), 1, 1);
  }
}

function seed(x, y, a, len, s, alph, attached) {
  let tx = x + cos(a) * len * s;
  let ty = y + sin(a) * len * s;
  // Body
  noStroke();
  fill(110, 84, 62, alph);
  push();
  translate(x, y);
  rotate(a);
  ellipse(attached ? 4 : 0, 0, 14 * s, 4 * s);
  pop();
  // Stalk
  stroke(240, 230, 212, alph * 0.85);
  strokeWeight(max(0.6, 1.3 * s));
  line(x, y, tx, ty);
  // Pappus
  let n = 24;
  for (let k = 0; k < n; k++) {
    let fa = a + map(k, 0, n - 1, -1.25, 1.25) + random(-0.05, 0.05);
    let fl = len * 0.5 * s * random(0.8, 1.1);
    let ex = tx + cos(fa) * fl;
    let ey = ty + sin(fa) * fl;
    stroke(250, 244, 230, alph * 0.6);
    strokeWeight(max(0.4, 0.9 * s));
    line(tx, ty, ex, ey);
    noStroke();
    fill(255, 250, 240, alph * 0.7);
    circle(ex, ey, max(0.8, 2.2 * s));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // Sky gradient: deep indigo to dusky rose at horizon
  let top = color(10, 12, 38);
  let mid = color(48, 40, 88);
  let low = color(150, 88, 82);
  let hor = color(214, 150, 108);
  for (let y = 0; y < height; y++) {
    let c;
    if (y < 900) c = lerpColor(top, mid, y / 900);
    else if (y < 1450) c = lerpColor(mid, low, (y - 900) / 550);
    else c = lerpColor(low, hor, min(1, (y - 1450) / 250));
    stroke(c);
    line(0, y, width, y);
  }

  // Soft mist bands near horizon
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = 1450 + random(-200, 250);
    let n = noise(x * 0.003, y * 0.006);
    fill(240, 190, 160, 6 * n);
    ellipse(x, y, 260 * n + 60, 40 * n + 10);
  }

  // Stars
  for (let i = 0; i < 420; i++) {
    let x = random(width);
    let y = pow(random(), 1.6) * 1300;
    let b = random(60, 220) * (1 - y / 1500);
    fill(235, 230, 255, b);
    circle(x, y, random(0.8, 2.6));
  }

  // Distant hills silhouette
  fill(40, 28, 44);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 10) {
    vertex(x, 1640 + noise(x * 0.002) * 120 - 60);
  }
  vertex(width, height);
  endShape(CLOSE);

  let hx = 760, hy = 1160;

  // Ghost of the full seed sphere: absence
  for (let k = 0; k < 140; k++) {
    let th = random(TWO_PI);
    let r1 = 26, r2 = 175 + random(-10, 10);
    stroke(230, 220, 240, 10);
    strokeWeight(1);
    line(hx + cos(th) * r1, hy + sin(th) * r1, hx + cos(th) * r2, hy + sin(th) * r2);
  }
  noFill();
  stroke(230, 220, 240, 14);
  circle(hx, hy, 360);

  // Stem
  noFill();
  stroke(30, 34, 28);
  strokeWeight(11);
  bezier(700, 2050, 690, 1700, 800, 1450, hx, hy + 18);
  stroke(70, 80, 60, 120);
  strokeWeight(3);
  bezier(704, 2050, 694, 1700, 804, 1450, hx + 3, hy + 18);

  // Drifting seeds rising into stars
  let N = 150;
  for (let i = 0; i < N; i++) {
    let t = pow(i / N, 0.85);
    let spread = 40 + t * 520;
    let x = hx + 60 + t * 520 + (noise(i * 0.3, 1) - 0.5) * spread * 2;
    let y = hy - 120 - t * 1080 + (noise(i * 0.3, 7) - 0.5) * spread * 0.9;
    let s = lerp(1.0, 0.18, t) * random(0.8, 1.1);
    let al = lerp(230, 70, t);
    let tilt = (noise(i * 0.5, 3) - 0.5) * 1.4 + 0.25;
    if (t > 0.55) glow(x, y - 40 * s, map(t, 0.55, 1, 0, 1));
    seed(x, y, tilt, s, al);
  }

  // Remaining seeds still attached: the few that hold on
  let remain = [-2.6, -2.25, -1.95, 2.3, 2.7, 3.0, 1.9, -0.6, 0.15];
  for (let th of remain) {
    let bx = hx + cos(th) * 24;
    let by = hy + sin(th) * 24;
    seed(bx, by, th + HALF_PI, 1.35, 235);
  }

  // Receptacle: bare, pitted head
  noStroke();
  fill(120, 96, 72);
  circle(hx, hy, 52);
  for (let k = 0; k < 60; k++) {
    let a = random(TWO_PI), r = random(22);
    fill(70, 52, 40, 200);
    circle(hx + cos(a) * r, hy + sin(a) * r, 2.5);
  }
  fill(255, 220, 180, 40);
  circle(hx - 8, hy - 8, 18);

  // Foreground grass silhouettes
  for (let i = 0; i < 650; i++) {
    let x = random(-50, width + 50);
    let h = random(120, 480) * (0.6 + noise(x * 0.004) * 0.8);
    let lean = (noise(x * 0.01, 5) - 0.4) * 160;
    stroke(12 + random(10), 9 + random(8), 18 + random(10));
    strokeWeight(random(2, 5));
    noFill();
    bezier(x, height + 10, x, height - h * 0.4, x + lean * 0.5, height - h * 0.8, x + lean, height - h);
  }
  noStroke();
  fill(10, 8, 16);
  rect(0, 1940, width, 60);
}

function glow(x, y, k) {
  noStroke();
  for (let r = 30; r > 0; r -= 3) {
    fill(240, 230, 255, 6 * k);
    circle(x, y, r * (0.5 + k));
  }
  fill(255, 250, 255, 200 * k);
  circle(x, y, 2 + 2 * k);
}

function seed(x, y, a, s, al) {
  push();
  translate(x, y);
  rotate(a);
  let L = 62 * s;
  stroke(232, 222, 210, al);
  strokeWeight(max(0.6, 1.4 * s));
  line(0, 0, 0, -L);
  noStroke();
  fill(96, 72, 52, al);
  ellipse(0, 7 * s, 5 * s, 16 * s);
  stroke(242, 236, 228, al * 0.75);
  strokeWeight(max(0.4, 0.9 * s));
  let n = 30;
  for (let k = 0; k < n; k++) {
    let ang = -HALF_PI + map(k, 0, n - 1, -1.35, 1.35);
    let r = 46 * s * (0.88 + random(0.24));
    let ex = cos(ang) * r;
    let ey = -L + sin(ang) * r * 0.85;
    line(0, -L, ex, ey);
    point(ex, ey);
  }
  pop();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Deep void background
  background(7, 9, 14);

  // 2. Subtle atmospheric glow and subterranean depth
  drawAtmosphere();

  // 3. The Horizon / Threshold line
  drawHorizon();

  // 4. The Ascending Soul / Dissolving Essence (Additive blending for luminance)
  blendMode(ADD);
  drawAscendingCurrents();
  drawCoreHalo();
  blendMode(BLEND);

  // 5. The Earthly Vessel (Dark, fractured monolith at the threshold)
  drawVessel();

  // 6. Final drifting embers and ash
  drawParticles();

  // 7. Painterly texture overlay (Canvas grain and subtle vignette)
  applyTexture();
}

function drawAtmosphere() {
  noStroke();
  // Create a painterly gradient backdrop using large soft circles
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let r = random(150, 500);

    if (y < 1450) {
      // Upper realm: hints of deep slate blue and bruised violet
      let c1 = color(14, 19, 30, 8);
      let c2 = color(28, 22, 36, 8);
      fill(lerpColor(c1, c2, n));
    } else {
      // Lower realm: abyssal, heavy warm-black
      fill(6, 5, 8, 18);
    }
    circle(x, y, r);
  }
}

function drawHorizon() {
  // The quiet line separating the heavy नीचे (below) from the vast ऊपर (above)
  for (let i = 0; i < 400; i++) {
    let y = randomGaussian(1450, 15);
    let x1 = random(0, width * 0.4);
    let x2 = random(width * 0.6, width);
    strokeWeight(random(0.5, 2));
    stroke(35, 45, 60, random(5, 20));
    line(x1, y, x2, y);
  }

  // Reflections in the dark water/ground below
  for (let i = 0; i < 800; i++) {
    let y = random(1450, height);
    let distFromCenter = abs(y - 1450);
    let spread = map(y, 1450, height, 150, 600);
    let x = randomGaussian(width / 2, spread);
    let w = random(20, 150);

    strokeWeight(random(0.5, 2.5));
    // Faint gold and cyan reflections
    if (random() < 0.3) {
      stroke(160, 110, 60, map(y, 1450, height, 15, 2));
    } else {
      stroke(40, 65, 80, map(y, 1450, height, 12, 1));
    }
    line(x - w / 2, y, x + w / 2, y);
  }
}

function drawCoreHalo() {
  // The moment of release - a soft, warm glow at the base of the unthreading
  noStroke();
  for (let i = 0; i < 150; i++) {
    let r = random(20, 450);
    let alpha = map(r, 20, 450, 8, 0.5);
    fill(180, 110, 55, alpha);
    let x = randomGaussian(width / 2, 40);
    let y = randomGaussian(1350, 60);
    circle(x, y, r);
  }
}

function drawAscendingCurrents() {
  // Thousands of fine threads unspooling from the vessel into the ether
  let numStreams = 3200;

  let cWarm1 = color(230, 140, 60);  // Amber life-force
  let cWarm2 = color(255, 220, 160); // Pale gold spirit
  let cCool1 = color(70, 130, 160);  // Spectral cyan
  let cCool2 = color(120, 110, 170); // Violet memory
  let cFade = color(15, 25, 40);     // Dissolving into night

  noFill();

  for (let i = 0; i < numStreams; i++) {
    // Originate near the monolith's upper half
    let x = randomGaussian(width / 2, 55);
    let y = random(1150, 1480);

    // Choose initial color identity for this thread
    let randC = random();
    let startCol;
    if (randC < 0.45) startCol = cWarm1;
    else if (randC < 0.75) startCol = cWarm2;
    else startCol = cCool1;

    let steps = random(150, 750);
    let sw = random(0.4, 2.2);
    strokeWeight(sw);

    let noiseScale = 0.0025;
    // Slight individual variance in how each thread reads the flow field
    let noiseOffset = random(100); 

    for (let s = 0; s < steps; s++) {
      let progress = s / steps;

      // Flow field angle: mostly upward (-PI/2), meandering more as it rises
      let n = noise(x * noiseScale, y * noiseScale, noiseOffset * 0.01);
      let angleSpread = map(y, 1450, 0, PI * 0.2, PI * 1.1);
      let angle = -HALF_PI + (n - 0.5) * angleSpread;

      //Gentle pull away from the center at the very top (expansion)
      if (y < 800) {
        let pull = (x - width / 2) * 0.0005;
        angle += pull;
      }

      let speed = map(progress, 0, 1, 1.5, 3.5);
      let nx = x + cos(angle) * speed;
      let ny = y + sin(angle) * speed;

      // Color transition along the thread's life
      let currentCol;
      if (progress < 0.3) {
        currentCol = lerpColor(startCol, cCool2, map(progress, 0, 0.3, 0, 1));
      } else {
        currentCol = lerpColor(cCool2, cFade, map(progress, 0.3, 1, 0, 1));
      }

      // Fade in at start, fade out at the end
      let alpha = sin(progress * PI) * map(sw, 0.4, 2.2, 18, 6);

      stroke(red(currentCol), green(currentCol), blue(currentCol), alpha);
      line(x, y, nx, ny);

      x = nx;
      y = ny;

      if (y < -50 || x < -50 || x > width + 50) break;
    }
  }
}

function drawVessel() {
  // The physical form left behind: dark, heavy, eroding at the top
  // Rendered with dense, textured horizontal/angled strokes like palette knife marks

  let baseY = 1480;
  let topY = 1120;

  for (let y = topY; y < baseY; y += 0.4) {
    let progress = map(y, topY, baseY, 0, 1); // 0 at top, 1 at bottom

    // Width of the figure: narrower at top, wider and rooted at base
    let profile = pow(progress, 0.7) * 90 + 15;

    // Noise distorts the edges, much more distortion at the top (dissolving)
    let edgeDistort = (noise(y * 0.03) - 0.5) * map(progress, 0, 1, 120, 20);
    let centerShift = (noise(y * 0.01) - 0.5) * 40;

    let cx = width / 2 + centerShift;

    // Probability of drawing decreases at the top (fracturing into nothing)
    if (random() > pow(progress, 0.35) * 1.1) continue;

    let x1 = cx - profile + edgeDistort * random(0.5, 1.5);
    let x2 = cx + profile + edgeDistort * random(0.5, 1.5);

    // Break the line into segments to let the inner glow shine through cracks
    let segments = floor(random(1, 5));
    for (let seg = 0; seg < segments; seg++) {
      let sx1 = lerp(x1, x2, seg / segments) + random(-10, 10);
      let sx2 = lerp(x1, x2, (seg + 1) / segments) + random(-10, 10);

      // Leave gaps near the top
      if (progress < 0.6 && random() < 0.4) continue;

      strokeWeight(random(1, 5));

      // Deep charcoal, obsidian, and dried-earth tones
      let cDark = color(10, 8, 12, random(150, 240));
      let cEdge = color(45, 30, 25, random(100, 180));

      stroke(lerpColor(cEdge, cDark, progress));

      // Slight tilt to the brushwork
      let tilt = random(-4, 4);
      line(sx1, y, sx2, y + tilt);
    }
  }

  // Grounding shadow beneath the vessel
  noStroke();
  for (let i = 0; i < 300; i++) {
    fill(4, 4, 7, random(10, 30));
    let w = random(50, 500);
    let h = random(5, 40);
    let x = randomGaussian(width / 2, 120);
    let y = randomGaussian(1475, 15);
    ellipse(x, y, w, h);
  }
}

function drawParticles() {
  // Final sparks of memory and ash drifting in the void
  for (let i = 0; i < 1800; i++) {
    let y = random(50, 1500);
    // Spread widens towards the top of the canvas
    let spread = map(y, 1500, 0, 60, 650);
    let x = randomGaussian(width / 2, spread);

    // Filter out some particles using noise to create natural clumping
    let n = noise(x * 0.005, y * 0.005);
    if (n < 0.38) continue;

    let distToSource = dist(x, y, width / 2, 1300);

    if (random() < 0.65) {
      // Luminous embers (Additive feel)
      blendMode(ADD);
      noStroke();
      let r = random(1, 4.5);
      let alpha = map(y, 0, 1500, 20, 180) * random(0.5, 1);

      if (distToSource < 400 && random() < 0.7) {
        fill(255, 190, 120, alpha); // Bright gold near the vessel
      } else {
        fill(130, 180, 210, alpha * 0.7); // Cool starlight higher up
      }
      circle(x, y, r);

      // Soft halo around larger embers
      if (r > 3.0) {
        fill(200, 140, 90, alpha * 0.2);
        circle(x, y, r * 4);
      }
      blendMode(BLEND);
    } else {
      // Dark ash / flaking matter (mostly lower down)
      if (y > 600) {
        noStroke();
        fill(15, 14, 18, random(100, 220));
        let s = random(1.5, 5);
        push();
        translate(x, y);
        rotate(random(TWO_PI));
        rect(0, 0, s, s * random(0.4, 1.8));
        pop();
      }
    }
  }
}

function applyTexture() {
  // 1. Fine canvas weave/scratches
  strokeWeight(0.5);
  for (let i = 0; i < 25000; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(2, 12);
    if (random() < 0.5) {
      stroke(255, 250, 240, random(2, 5));
    } else {
      stroke(0, 0, 0, random(4, 10));
    }
    // Mostly vertical and horizontal tooth
    if (random() < 0.5) {
      line(x, y, x + len, y);
    } else {
      line(x, y, x, y + len);
    }
  }

  // 2. Pixel-level film grain and subtle vignette for cohesion
  loadPixels();
  let cx = width / 2;
  let cy = height / 2;
  let maxDist = dist(0, 0, cx, cy);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Distance from center for vignette
      let d = dist(x, y, cx, cy);
      let vig = map(pow(d / maxDist, 1.8), 0, 1, 1, 0.35);

      // Grain
      let grain = random(-10, 10);

      pixels[idx] = constrain(pixels[idx] * vig + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Deep Abyssal Background
  background(7, 9, 14);

  // 2. Atmospheric Nebula & Depth
  drawAtmosphere();

  // 3. The Horizon / The Threshold
  drawThreshold();

  // 4. The Ascending Soul-Currents (Flow Field)
  drawAscensionCurrents();

  // 5. The Shroud / Boat & The Dissolving Vessel
  drawTheVessel();

  // 6. The Water Reflections (Below the Threshold)
  drawReflections();

  // 7. Celestial Dust & Final Texture
  drawStardust();
  drawCanvasGrain();
}

function drawAtmosphere() {
  noStroke();

  // Deep indigo and bruised violet washes
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(200, 700);

    // Shift colors based on vertical position
    let col;
    if (y < 800) {
      col = color(15, 22, 38, 4); // Upper void: cold deep blue
    } else if (y < 1400) {
      col = color(42, 28, 48, 5); // Mid: bruised plum/violet
    } else {
      col = color(8, 12, 18, 8);  // Lower: dark water
    }

    fill(col);
    circle(x, y, r);
  }

  // Central warm glow of the spirit
  for (let i = 0; i < 150; i++) {
    let x = randomGaussian(800, 180);
    let y = randomGaussian(1150, 200);
    let r = random(100, 500);
    fill(180, 110, 60, 2.5);
    circle(x, y, r);
  }

  // High altitude pale light (the destination)
  for (let i = 0; i < 100; i++) {
    let x = randomGaussian(800, 250);
    let y = randomGaussian(300, 200);
    let r = random(150, 600);
    fill(160, 190, 210, 2);
    circle(x, y, r);
  }
}

function drawThreshold() {
  // Subtle mist along the water line at y = 1400
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = randomGaussian(1400, 40);
    let w = random(200, 800);
    let h = random(10, 60);
    fill(120, 130, 150, 1.5);
    noStroke();
    ellipse(x, y, w, h);
  }
}

function drawAscensionCurrents() {
  // Thousands of silky threads rising from the vessel's position
  let numStreams = 3200;

  for (let i = 0; i < numStreams; i++) {
    // Originate mostly near the center-bottom (the vessel)
    let startX = randomGaussian(800, 160);
    let startY = randomGaussian(1320, 60);

    let x = startX;
    let y = startY;

    let steps = random(150, 750);

    // Color palette for the rising essence
    let isGold = random() < 0.65;
    let cStart, cEnd;

    if (isGold) {
      cStart = color(255, 200, 120); // Warm life-gold
      cEnd = color(90, 140, 180);    // Fading into ether-blue
    } else {
      cStart = color(220, 130, 110); // Rose/ash
      cEnd = color(40, 30, 60);      // Deep void violet
    }

    let weight = random(0.4, 2.2);
    strokeWeight(weight);
    noFill();

    // Draw the stream step by step for color modulation
    for (let s = 0; s < steps; s++) {
      let progress = s / steps;

      // Flow field math: pull towards center, then spiral out at the top
      let n = noise(x * 0.0025, y * 0.0025, i * 0.0005);
      let angle = -HALF_PI + map(n, 0, 1, -PI * 0.45, PI * 0.45);

      // Gentle inward pull in the middle, outward at the very top
      let centerPull = (800 - x) * 0.0015;
      if (y < 500) centerPull = (x - 800) * 0.001; 
      angle += centerPull;

      let nextX = x + cos(angle) * 2.2;
      let nextY = y + sin(angle) * 2.2;

      // Alpha fades in then out
      let alpha = sin(progress * PI) * map(weight, 0.4, 2.2, 35, 12);

      let curCol = lerpColor(cStart, cEnd, progress);
      curCol.setAlpha(alpha);
      stroke(curCol);

      line(x, y, nextX, nextY);

      x = nextX;
      y = nextY;

      // Occasional ember/ash breakaway
      if (random() < 0.003 && y < 1100) {
        noStroke();
        fill(255, 230, 190, alpha * 2.5);
        circle(x + random(-15, 15), y + random(-15, 15), random(1.5, 4.5));
      }
    }
  }
}

function drawTheVessel() {
  // A ghostly, half-dissolved gondola/shroud at the threshold (y = 1360)
  push();
  translate(800, 1370);

  // 1. Dark hull / shadow base
  noStroke();
  for (let i = 0; i < 200; i++) {
    let t = random(-1, 1);
    let x = t * 320;
    let y = pow(t, 2) * 35 + randomGaussian(0, 12);
    let w = random(40, 150) * (1 - abs(t) * 0.7);
    let h = random(8, 25);
    fill(6, 8, 12, 25);
    ellipse(x, y, w, h);
  }

  // 2. The Reclining Figure / Core of Light (dissolving)
  for (let i = 0; i < 1200; i++) {
    let t = random(-0.6, 0.6);
    let x = t * 280 + randomGaussian(0, 15);
    // Arching slightly upward in the center like a chest/head
    let bodyCurve = -exp(-pow(t * 3, 2)) * 35; 
    let y = bodyCurve + randomGaussian(0, 12);

    let distFromCenter = abs(t);
    let c = lerpColor(color(255, 240, 200, 30), color(160, 90, 70, 10), distFromCenter * 1.5);

    fill(c);
    let r = random(3, 22) * (1 - distFromCenter);
    circle(x, y - 10, r);
  }

  // 3. Crisp, fragile remnants of the physical form (bone/gold leaf texture)
  stroke(255, 235, 190, 60);
  noFill();
  for (let i = 0; i < 300; i++) {
    let x = randomGaussian(0, 90);
    let y = randomGaussian(-25, 15);
    strokeWeight(random(0.5, 1.5));
    let len = random(5, 25);
    let ang = random(-PI * 0.2, PI * 0.2);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  pop();
}

function drawReflections() {
  // The dark water from y = 1380 to 2000
  // Horizontal painterly strokes reflecting the light above
  for (let y = 1380; y < height; y += 1.5) {
    let depth = map(y, 1380, height, 0, 1);
    let numRipples = map(depth, 0, 1, 35, 8);

    for (let i = 0; i < numRipples; i++) {
      // Spread gets wider as it comes toward the bottom of the canvas, or narrows like a pillar
      let spread = map(depth, 0, 1, 180, 90);
      let x = randomGaussian(800, spread);
      let w = random(20, 180) * (1 - depth * 0.5);
      let h = random(1, 4);

      let distFromCenter = abs(x - 800);

      // Determine reflection color based on proximity to center
      let c;
      if (distFromCenter < 180 && random() < (1 - depth)) {
        // Warm golden reflection of the soul
        c = lerpColor(color(230, 160, 90, 18), color(40, 50, 70, 8), depth);
      } else {
        // Cold abyssal water ripples
        c = lerpColor(color(30, 40, 60, 15), color(5, 7, 12, 30), depth);
      }

      noStroke();
      fill(c);
      ellipse(x, y + random(-2, 2), w, h);
    }
  }

  // Sinking ash / memories going downward into the water
  for (let i = 0; i < 400; i++) {
    let x = randomGaussian(800, 140);
    let y = random(1380, 1950);
    let depth = map(y, 1380, 1950, 0, 1);

    stroke(180, 140, 110, (1 - depth) * 35);
    strokeWeight(random(0.5, 1.5));
    line(x, y, x, y + random(5, 30));
  }
}

function drawStardust() {
  // The upper expanse where the threads become stars
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(0, 1400);

    // Concentrate more along the central ascending column
    if (random() < 0.6) {
      x = randomGaussian(800, 220);
    }

    let n = noise(x * 0.005, y * 0.005);
    if (n > 0.35) {
      let heightFactor = 1 - (y / 1400);
      let alpha = random(20, 180) * heightFactor;

      noStroke();
      if (random() < 0.2) {
        // Bright star-like embers
        fill(255, 245, 220, alpha);
        circle(x, y, random(1.5, 3.5));
        // Halo
        fill(255, 210, 150, alpha * 0.2);
        circle(x, y, random(6, 14));
      } else {
        // Fine dust
        fill(170, 200, 230, alpha * 0.6);
        circle(x, y, random(0.5, 2));
      }
    }
  }
}

function drawCanvasGrain() {
  // Subtle oil-on-linen texture over the whole piece
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);

  for (let i = 0; i < totalPixels; i += 4) {
    let grain = random(-9, 9);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();

  // Very subtle dark vignette at the edges to frame the ascension
  noFill();
  for (let i = 0; i < 80; i++) {
    stroke(4, 6, 10, map(i, 0, 80, 40, 0));
    strokeWeight(4);
    rect(i * 2, i * 2, width - i * 4, height - i * 4);
  }
}

function setup() {
  pixelDensity(1);
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Deep void background with textured atmosphere
  background(7, 9, 13);
  drawAtmosphere();

  // 2. The silent threshold (horizon of stillness)
  drawHorizon();

  // 3. The reclining shrouded form (earth-bound vessel)
  drawRecumbentForm();

  // 4. The unthreading (soul/memory dissolving upward)
  drawDissolution();

  // 5. Final embers & ash rising into the upper void
  drawEmbers();

  // 6. Subtle oil-canvas tooth and vignette
  applyCanvasTexture();
}

function drawAtmosphere() {
  noStroke();
  // Soft vertical washes of indigo, abyssal teal, and umber
  for (let i = 0; i < 1800; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    let w = random(120, 480);
    let h = random(80, 320);

    let yRatio = y / height;
    let r = lerp(6, 22, yRatio) + n * 10;
    let g = lerp(8, 20, yRatio) + n * 10;
    let b = lerp(14, 28, yRatio) + n * 14;

    fill(r, g, b, 10);
    ellipse(x, y, w, h);
  }

  // Faint vertical sanctuary glow in the center
  for (let r = 1300; r > 0; r -= 20) {
    let alpha = map(r, 0, 1300, 3.5, 0);
    fill(42, 34, 28, alpha);
    ellipse(width * 0.5, height * 0.62, r * 0.85, r * 1.45);
  }
}

function drawHorizon() {
  let hy = height * 0.78;

  // Heavy lower shadow (the earth / water below)
  noStroke();
  for (let y = hy; y < height; y += 3) {
    let inter = map(y, hy, height, 0, 1);
    let c = lerpColor(color(14, 15, 20, 180), color(4, 5, 7, 255), inter);
    fill(c);
    rect(0, y, width, 4);
  }

  // Faint, broken horizon streaks
  for (let i = 0; i < 600; i++) {
    let x = random(width * 0.05, width * 0.95);
    let y = hy + randomGaussian(0, 6);
    let len = random(30, 220);
    let distFromCenter = abs(x - width * 0.5) / (width * 0.5);
    let alpha = (1 - distFromCenter) * random(8, 30);

    stroke(85, 72, 58, alpha);
    strokeWeight(random(0.5, 2.0));
    line(x - len * 0.5, y, x + len * 0.5, y);
  }
}

function getBodySpine(t) {
  // t goes from 0 (head, left) to 1 (feet, right)
  let x = lerp(width * 0.27, width * 0.73, t);
  let baseY = height * 0.775;

  // Profile of a draped, recumbent figure
  let head = exp(-pow((t - 0.10) / 0.055, 2)) * 58;
  let chest = exp(-pow((t - 0.30) / 0.11, 2)) * 88;
  let knees = exp(-pow((t - 0.60) / 0.13, 2)) * 50;
  let feet = exp(-pow((t - 0.84) / 0.05, 2)) * 34;

  let h = head + chest + knees + feet;
  return { x: x, y: baseY - h * 0.55, h: h };
}

function drawRecumbentForm() {
  // Underlying dark mass of the bier and shroud
  noStroke();
  for (let i = 0; i < 5500; i++) {
    let t = random(0.02, 0.96);
    let spine = getBodySpine(t);

    let spreadY = randomGaussian(0, spine.h * 0.36 + 8);
    let px = spine.x + randomGaussian(0, 18);
    let py = spine.y + spreadY;

    // Keep mostly above the slab line
    if (py > height * 0.795) py = height * 0.795 - random(0, 12);

    let n = noise(px * 0.008, py * 0.008);
    let light = map(py, spine.y - spine.h * 0.6, height * 0.79, 1, 0);
    light = constrain(light, 0, 1);

    // Colors: bone, warm ash, raw umber, deep slate shadow
    let r = lerp(16, 175, pow(light, 1.5)) + n * 25;
    let g = lerp(18, 155, pow(light, 1.6)) + n * 20;
    let b = lerp(24, 130, pow(light, 1.7)) + n * 15;

    // Fade toward the feet and head
    let edgeFade = sin(constrain(map(t, 0.02, 0.96, 0, PI), 0, PI));
    let alpha = random(12, 38) * edgeFade;

    fill(r, g, b, alpha);
    push();
    translate(px, py);
    rotate(random(-0.25, 0.25) + (t - 0.4) * 0.2);
    ellipse(0, 0, random(18, 75), random(5, 22));
    pop();
  }

  // Inner warm heart-glow (the last remnant of vitality in the chest)
  let chestSpine = getBodySpine(0.31);
  for (let r = 340; r > 0; r -= 8) {
    let inter = map(r, 0, 340, 1, 0);
    fill(225, 145, 75, pow(inter, 2.2) * 8);
    ellipse(chestSpine.x, chestSpine.y - 10, r * 1.4, r * 0.85);
  }
}

function drawDissolution() {
  // Thousands of fine painterly threads unspooling from the body into the dark
  let numStrands = 2600;

  for (let i = 0; i < numStrands; i++) {
    // Concentrate origin points around the chest and head
    let t = constrain(randomGaussian(0.36, 0.19), 0.06, 0.90);
    let spine = getBodySpine(t);

    let x = spine.x + randomGaussian(0, 16);
    let y = spine.y - spine.h * random(0.05, 0.48) + randomGaussian(0, 8);

    // Strand length: longest above the chest/heart
    let centerWeight = exp(-pow((t - 0.34) / 0.22, 2));
    let maxSteps = int(random(50, 290) * (0.35 + 0.95 * centerWeight));

    // Palette selection for each thread
    let seed = random(1);
    let cStart, cEnd;
    if (seed < 0.28) {
      // Warm gold & amber light
      cStart = color(238, 188, 120);
      cEnd = color(75, 58, 72);
    } else if (seed < 0.65) {
      // Pale bone & silver ash
      cStart = color(210, 202, 190);
      cEnd = color(40, 48, 62);
    } else if (seed < 0.88) {
      // Muted ochre & dry rose
      cStart = color(175, 125, 98);
      cEnd = color(28, 30, 42);
    } else {
      // Deep charcoal shadow threads
      cStart = color(35, 36, 44);
      cEnd = color(12, 14, 20);
    }

    let baseWeight = random(0.4, 2.4);

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;

      // Flow field: rises upward, gently pulls inward, then disperses high up
      let n1 = noise(x * 0.0028, y * 0.0028, i * 0.0005);
      let n2 = noise(x * 0.009, y * 0.009 + 100);

      let angle = - HALF_PI + (n1 - 0.48) * 2.1 + (n2 - 0.5) * 0.7;

      // Subtle chimney pull toward the central axis at mid-height
      let centerPull = (width * 0.46 - x) * 0.0009 * (1 - progress);
      let vx = cos(angle) * 3.2 + centerPull;
      let vy = sin(angle) * 3.2 - 1.15;

      let nx = x + vx;
      let ny = y + vy;

      // Alpha bell curve
      let alpha = sin(progress * PI) * map(centerWeight, 0, 1, 22, 62);
      let col = lerpColor(cStart, cEnd, pow(progress, 0.75));
      col.setAlpha(alpha);

      stroke(col);
      strokeWeight(baseWeight * (1 - progress * 0.75));
      line(x, y, nx, ny);

      x = nx;
      y = ny;
    }
  }
}

function drawEmbers() {
  // Weightless flecks of ash, dust, and dying sparks ascending
  noStroke();
  for (let i = 0; i < 1600; i++) {
    let progress = pow(random(1), 1.35); // More dense near the body, sparser at the top
    let y = map(progress, 0, 1, height * 0.74, height * 0.05);

    // Horizontal spread widens as it rises, following a soft S-curve
    let curveOffset = sin(y * 0.0028) * 75;
    let spread = map(y, height * 0.75, height * 0.05, 190, 440);
    let x = width * 0.46 + curveOffset + randomGaussian(0, spread * 0.55);

    let n = noise(x * 0.005, y * 0.005);
    if (n > 0.36) {
      let isGold = random(1) < 0.35;
      let sz = random(0.8, 3.8) * (1 - progress * 0.45);
      let alpha = random(30, 150) * (1 - progress * 0.65);

      if (isGold) {
        fill(245, 200, 135, alpha);
        // Soft halo on brighter gold motes
        if (sz > 2.4) {
          fill(240, 180, 110, alpha * 0.22);
          ellipse(x, y, sz * 4.5, sz * 4.5);
          fill(252, 222, 165, alpha);
        }
      } else {
        fill(185, 182, 178, alpha * 0.65);
      }
      ellipse(x, y, sz, sz * random(0.8, 1.4));
    }
  }

  // Deep shadow reflections below the body (still water / abyss)
  for (let i = 0; i < 750; i++) {
    let x = random(width * 0.22, width * 0.78);
    let y = random(height * 0.78, height * 0.95);
    let distY = (y - height * 0.78) / (height * 0.17);
    let alpha = (1 - distY) * random(6, 20);

    stroke(160, 140, 115, alpha);
    strokeWeight(random(0.5, 1.8));
    let len = random(15, 95) * (1 - distY * 0.6);
    line(x - len, y, x + len, y);
  }
}

function applyCanvasTexture() {
  // Fine linen weave & organic oil grain via direct pixel manipulation
  loadPixels();
  let w = width;
  let h = height;
  let cx = w * 0.5;
  let cy = h * 0.55;
  let maxDist = dist(0, 0, cx, cy);

  for (let y = 0; y < h; y++) {
    let weaveY = (y % 3 === 0) ? 3 : 0;
    for (let x = 0; x < w; x++) {
      let idx = (x + y * w) * 4;

      // Vignette darkening toward edges
      let d = dist(x, y, cx, cy) / maxDist;
      let vig = pow(constrain(1 - d * 0.55, 0, 1), 0.45);

      // Subtle canvas tooth + organic grain
      let weaveX = (x % 3 === 0) ? 3 : 0;
      let grain = random(-7, 7) + (weaveX + weaveY - 3) * 0.45;

      pixels[idx]     = constrain(pixels[idx] * vig + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(7, 9, 14);

  drawBackgroundAtmosphere();
  drawHorizonAndWater();
  drawTheVessel();
  drawAscendingSpirit();
  drawWaterReflections();
  drawDustAndEmbers();
  applyCanvasTexture();
}

function drawBackgroundAtmosphere() {
  noStroke();

  // Deep void at the top, warming slightly near the horizon
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let r = lerp(6, 22, pow(t, 1.5));
    let g = lerp(8, 25, pow(t, 1.5));
    let b = lerp(14, 32, pow(t, 1.2));

    // Horizon glow around y = 1400
    let distToHorizon = abs(y - 1400);
    if (distToHorizon < 600) {
      let glow = pow(1 - distToHorizon / 600, 2.5);
      r += glow * 35;
      g += glow * 28;
      b += glow * 20;
    }

    fill(r, g, b, 150);
    rect(0, y, width, 4);
  }

  // Painterly atmospheric clouds using noise
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let n = noise(x * 0.002, y * 0.002);

    let distToCenter = dist(x, y, width * 0.5, 1100);
    let radial = constrain(1 - distToCenter / 900, 0, 1);

    if (n > 0.4) {
      let alpha = (n - 0.4) * radial * 18;
      fill(40 + radial * 40, 45 + radial * 30, 60 + radial * 20, alpha);
      let w = random(50, 250);
      let h = random(20, 100);
      ellipse(x, y, w, h);
    }
  }
}

function drawHorizonAndWater() {
  let horizonY = 1400;

  // Dark water base
  for (let y = horizonY; y < height; y++) {
    let t = (y - horizonY) / (height - horizonY);
    let r = lerp(25, 4, pow(t, 0.7));
    let g = lerp(24, 6, pow(t, 0.7));
    let b = lerp(30, 10, pow(t, 0.7));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // Subtle ripples in the abyss
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let y = random(horizonY, height);
    let t = (y - horizonY) / (height - horizonY);
    let x = random(width);
    let n = noise(x * 0.005, y * 0.02);

    let w = random(20, 150) * (1 + t * 2);
    let h = random(1, 4) * (1 + t);

    if (n > 0.5) {
      fill(5, 7, 12, 80);
    } else {
      fill(45, 40, 50, 15 * (1 - t));
    }
    ellipse(x, y, w, h);
  }
}

function drawTheVessel() {
  // A sunken, decaying barge/shroud resting on the water line
  let cx = width * 0.5;
  let cy = 1410;

  noStroke();

  // Shadow beneath
  for (let i = 0; i < 500; i++) {
    fill(2, 3, 6, 30);
    let x = cx + randomGaussian() * 220;
    let y = cy + 10 + abs(randomGaussian() * 25);
    ellipse(x, y, random(40, 150), random(5, 20));
  }

  // The physical remains / heavy matter (earthy, ashen, decaying gold)
  for (let i = 0; i < 3000; i++) {
    let angle = random(PI);
    let rad = randomGaussian() * 180;
    let x = cx + cos(angle) * rad;
    let y = cy - abs(sin(angle) * rad * 0.25) + random(-10, 15);

    // Keep it concentrated near the center
    let d = abs(x - cx);
    if (d > 380) continue;

    let n = noise(x * 0.01, y * 0.01);

    // Color palette of ash, dried bone, and oxidized bronze
    let r = lerp(20, 90, n) + random(-10, 10);
    let g = lerp(18, 70, n) + random(-10, 10);
    let b = lerp(22, 65, n) + random(-10, 10);

    // Darker at the edges and bottom
    let edgeFade = 1 - constrain(d / 350, 0, 1);
    r *= edgeFade;
    g *= edgeFade;
    b *= edgeFade;

    fill(r, g, b, random(40, 120));

    push();
    translate(x, y);
    rotate(random(-0.2, 0.2));
    rectMode(CENTER);
    rect(0, 0, random(5, 35), random(2, 12), 2);
    pop();
  }
}

function drawAscendingSpirit() {
  // Thousands of gossamer threads unspooling from the vessel into the upper dark
  let cx = width * 0.5;
  let startY = 1405;

  // Layer 1: Broad, smoky, melancholic trails (indigo, slate, muted violet)
  for (let i = 0; i < 900; i++) {
    let x = cx + randomGaussian() * 140;
    let y = startY + random(-10, 10);

    let steps = random(150, 500);
    let gloom = random(0.2, 0.8);

    for (let s = 0; s < steps; s++) {
      let progress = s / steps;

      // Flow field using 3D noise
      let n1 = noise(x * 0.002, y * 0.002, i * 0.01);
      let n2 = noise(x * 0.005, y * 0.005, 100);

      let angle = -HALF_PI + map(n1, 0, 1, -1.2, 1.2) * pow(progress, 0.7);

      // Gentle pull back toward the center in the middle, then splaying out at the top
      let centerPull = (cx - x) * 0.003 * sin(progress * PI);

      x += cos(angle) * 2.5 + centerPull + map(n2, 0, 1, -1, 1);
      y += sin(angle) * 2.5;

      let alpha = sin(progress * PI) * 12 * (1 - progress * 0.5);
      let r = lerp(60, 20, progress) * gloom;
      let g = lerp(65, 35, progress) * gloom;
      let b = lerp(80, 65, progress) * gloom;

      noStroke();
      fill(r, g, b, alpha);
      let sz = map(progress, 0, 1, 8, 45);
      ellipse(x, y, sz, sz);
    }
  }

  // Layer 2: The vital essence - fine, luminous filaments (pale gold, bone white, cyan-grey)
  for (let i = 0; i < 1600; i++) {
    let spread = randomGaussian() * 110;
    let x = cx + spread;
    let y = startY + random(-5, 10) - abs(spread * 0.15);

    // Height of ascension varies; center goes highest
    let maxSteps = map(abs(spread), 0, 200, 750, 200, true) * random(0.4, 1.3);

    let isGold = random() < 0.35;
    let isBright = random() < 0.1;

    beginShape();
    noFill();
    for (let s = 0; s < maxSteps; s++) {
      let progress = s / maxSteps;

      // Wavering upward trajectory
      let n = noise(x * 0.003, y * 0.003, i * 0.005);
      let fineNoise = noise(x * 0.02, y * 0.02);

      let drift = map(n, 0, 1, -1.5, 1.5);
      // Create an hourglass / chalice constriction around y = 1100
      let constriction = 0;
      if (y > 900 && y < 1350) {
        constriction = (cx - x) * 0.008;
      } else if (y <= 900) {
        // Splay outward into the void at the top
        constriction = (x - cx) * 0.003;
      }

      x += drift + constriction + map(fineNoise, 0, 1, -0.5, 0.5);
      y -= random(1.2, 2.2);

      // Color and opacity dynamics
      let alpha = sin(progress * PI);
      alpha = pow(alpha, 0.5) * map(s, 0, maxSteps, 90, 0);

      if (isBright) {
        stroke(255, 245, 225, alpha * 1.4);
        strokeWeight(map(progress, 0, 1, 1.8, 0.3));
      } else if (isGold) {
        let r = lerp(220, 140, progress);
        let g = lerp(180, 150, progress);
        let b = lerp(120, 170, progress);
        stroke(r, g, b, alpha * 0.8);
        strokeWeight(map(progress, 0, 1, 1.5, 0.2));
      } else {
        // Ashen / spectral blue-white
        let r = lerp(180, 70, progress);
        let g = lerp(175, 90, progress);
        let b = lerp(170, 120, progress);
        stroke(r, g, b, alpha * 0.6);
        strokeWeight(map(progress, 0, 1, 1.2, 0.2));
      }

      // Draw segment by segment to allow variable strokeWeight and color
      point(x, y);

      // Occasional dissolution into dust along the path
      if (random() < 0.015 && progress > 0.4) {
        noStroke();
        fill(240, 220, 190, alpha * 1.5);
        let pSize = random(1, 3.5);
        ellipse(x + random(-8, 8), y + random(-8, 8), pSize, pSize);
      }
    }
    endShape();
  }

  // Layer 3: Intense core glow right where the body breaks apart
  for (let i = 0; i < 400; i++) {
    let x = cx + randomGaussian() * 65;
    let y = startY - abs(randomGaussian() * 60) + 10;
    let d = dist(x, y, cx, startY - 20);
    let alpha = map(d, 0, 150, 35, 0, true);

    noStroke();
    fill(255, 215, 160, alpha);
    ellipse(x, y, random(10, 60), random(10, 80));
  }
}

function drawWaterReflections() {
  let cx = width * 0.5;
  let horizonY = 1400;

  // Broken, weeping reflections of the golden ascension in the dark water
  for (let y = horizonY + 15; y < height; y += 2) {
    let t = (y - horizonY) / (height - horizonY);

    // Reflection spreads wider as it comes closer, then fades into the abyss
    let spread = 60 + t * 220;
    let numStrokes = floor(map(t, 0, 1, 25, 3));

    for (let i = 0; i < numStrokes; i++) {
      let x = cx + randomGaussian() * spread;
      let n = noise(x * 0.02, y * 0.05);

      if (n > 0.35) {
        let distFromCenter = abs(x - cx);
        let intensity = constrain(1 - distFromCenter / (spread * 1.8), 0, 1);
        let depthFade = pow(1 - t, 1.8);

        let alpha = intensity * depthFade * 70 * n;

        // Warm gold near the boat, shifting to cold ghostly grey-blue deeper down
        let r = lerp(230, 80, t);
        let g = lerp(185, 95, t);
        let b = lerp(130, 120, t);

        noStroke();
        fill(r, g, b, alpha);

        let w = random(15, 80) * (1 + t * 1.5) * intensity;
        let h = random(1, 3.5);
        ellipse(x, y + random(-2, 2), w, h);
      }
    }
  }
}

function drawDustAndEmbers() {
  // Starseed / embers of memory drifting in the upper void
  let cx = width * 0.5;

  for (let i = 0; i < 1200; i++) {
    // Concentrated in an inverted cone above the vessel
    let y = random(50, 1400);
    let heightFactor = map(y, 1400, 50, 0.2, 1.5);
    let x = cx + randomGaussian() * (220 * heightFactor);

    if (x < 0 || x > width) continue;

    let n = noise(x * 0.005, y * 0.005);
    if (n > 0.45) {
      let sz = random(0.8, 3.2);
      let alpha = map(y, 50, 1400, 40, 220) * random(0.3, 1);

      // Soft halo
      noStroke();
      fill(255, 220, 180, alpha * 0.2);
      ellipse(x, y, sz * 4, sz * 4);

      // Core
      if (random() < 0.5) {
        fill(255, 240, 210, alpha);
      } else {
        fill(180, 200, 230, alpha * 0.8);
      }
      ellipse(x, y, sz, sz);
    }
  }

  // A few solitary, larger motes of light near the very top (acceptance / peace)
  for (let i = 0; i < 35; i++) {
    let x = cx + randomGaussian() * 350;
    let y = random(80, 700);

    for (let r = 25; r > 0; r -= 2) {
      fill(240, 230, 210, map(r, 25, 0, 1, 15));
      noStroke();
      ellipse(x, y, r, r);
    }
    fill(255, 250, 240, 200);
    ellipse(x, y, 2.5, 2.5);
  }
}

function applyCanvasTexture() {
  // Gives the piece a tactile, oil-on-linen feel and unifies the darks
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Subtle linen weave pattern + organic grain
      let weave = (sin(x * 1.5) + sin(y * 1.5)) * 1.5;
      let grain = random(-6, 6);

      // Vignette to deepen the edges into pure stillness
      let d = dist(x, y, width * 0.5, height * 0.55);
      let maxD = dist(0, 0, width * 0.5, height * 0.55);
      let vignette = map(pow(d / maxD, 1.8), 0, 1, 1, 0.35);

      pixels[idx] = constrain((pixels[idx] + grain + weave) * vignette, 0, 255);
      pixels[idx + 1] = constrain((pixels[idx + 1] + grain + weave) * vignette, 0, 255);
      pixels[idx + 2] = constrain((pixels[idx + 2] + grain + weave) * vignette, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 1. THE ABYSSAL BACKGROUND
  background(7, 9, 14);

  noStroke();
  for (let i = 0; i < 3500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    let r = map(n, 0, 1, 80, 450);

    let depth = map(y, 0, height, 0, 1);
    let c1 = color(22, 18, 30, 6); // Upper void (faint violet-black)
    let c2 = color(5, 12, 16, 8);  // Lower void (deep abyssal teal-black)
    let c = lerpColor(c1, c2, depth + random(-0.2, 0.2));

    fill(c);
    ellipse(x, y, r * random(0.8, 1.5), r * random(0.8, 1.5));
  }

  // 2. THE DISTANT THRESHOLD (Ambient Glow)
  blendMode(SCREEN);
  for (let i = 0; i < 150; i++) {
    let x = width * 0.5 + randomGaussian(0, 220);
    let y = random(100, 1450);
    let r = random(100, 500);
    let progress = map(y, 200, 1450, 1, 0); 
    let c = lerpColor(color(80, 50, 30, 2), color(25, 45, 55, 2), progress);
    fill(c);
    ellipse(x, y, r, r * 1.4);
  }

  // 3. THE ASCENDING SPIRIT (Golden/Bone Smoke)
  let numStreams = 2800;
  for (let i = 0; i < numStreams; i++) {
    let t = random(1);
    // Concentrate streams near the torso/head of the reclining figure
    let x = map(t, 0, 1, 450, 1150) + randomGaussian(0, 60);
    let y = getBodyY(x) + random(-10, 30);

    let maxSteps = int(random(150, 950));
    // Higher streams near the center/chest
    let centerBias = 1 - abs(x - 750) / 500;
    maxSteps *= map(constrain(centerBias, 0, 1), 0, 1, 0.4, 1.4);

    let cStart = color(255, 220, 170, 14); // Warm soul-light
    let cMid = color(190, 210, 220, 8);    // Pale bone/ash
    let cEnd = color(60, 80, 105, 0);      // Fading into the void

    noFill();
    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;
      let c;
      if (progress < 0.35) {
        c = lerpColor(cStart, cMid, progress / 0.35);
      } else {
        c = lerpColor(cMid, cEnd, (progress - 0.35) / 0.65);
      }

      // Occasional bright filaments
      if (i % 40 === 0 && progress < 0.5) {
        c = lerpColor(c, color(255, 250, 240, 35), 0.6);
      }

      stroke(c);
      strokeWeight(map(progress, 0, 1, random(0.5, 2.5), 0.1));

      let n1 = noise(x * 0.0025, y * 0.0025, i * 0.005);
      let n2 = noise(x * 0.008, y * 0.008, 100 + i * 0.005);

      // Angle pulls generally upward (-PI/2) with curling turbulence
      let angle = - HALF_PI + map(n1, 0, 1, -1.1, 1.1) + map(n2, 0, 1, -0.4, 0.4);

      // Gentle pull toward the central vertical axis as it rises
      let pullToCenter = (width * 0.52 - x) * 0.0015 * progress;

      let nx = x + cos(angle) * 2.2 + pullToCenter;
      let ny = y + sin(angle) * 2.2;

      line(x, y, nx, ny);
      x = nx;
      y = ny;
    }
  }

  // 4. THE MORTAL VESSEL (Reclining & Dissolving)
  blendMode(BLEND);

  // Deep shadow beneath the figure (the slab/earth)
  noStroke();
  for (let i = 0; i < 600; i++) {
    let x = random(200, 1400);
    let baseY = getBodyY(x) + random(30, 250);
    let w = random(80, 350);
    let h = random(15, 60);
    fill(4, 6, 9, random(15, 40));
    ellipse(x, baseY, w, h);
  }

  // Painterly strokes forming the shroud and body
  for (let i = 0; i < 4500; i++) {
    let x = random(300, 1300);
    let topY = getBodyY(x);
    let bottomY = 1520 + map(noise(x * 0.005), 0, 1, -30, 30);

    if (topY < bottomY) {
      let y = random(topY, bottomY);
      let depthInBody = map(y, topY, bottomY, 0, 1);

      let n = noise(x * 0.01, y * 0.01);
      // Drapery folds
      let fold = sin((x * 0.015) + n * 4 + (y * 0.005));

      let cHighlight = color(150, 160, 165, random(20, 60)); // Cold stone/linen highlight
      let cMid = color(50, 62, 72, random(30, 80));          // Ashen slate
      let cShadow = color(10, 14, 20, random(50, 120));      // Deep hollow

      let c;
      if (depthInBody < 0.2 && fold > 0) {
        c = lerpColor(cHighlight, cMid, depthInBody * 5);
        // Warm glow near the chest where the spirit leaves
        if (x > 550 && x < 900) {
          c = lerpColor(c, color(210, 170, 130, 50), map(abs(x - 720), 0, 180, 0.7, 0));
        }
      } else {
        c = lerpColor(cMid, cShadow, map(fold, 1, -1, 0, 1));
        c = lerpColor(c, cShadow, depthInBody);
      }

      fill(c);
      push();
      translate(x, y);
      // Strokes follow the contour of the body
      let slope = (getBodyY(x + 5) - getBodyY(x - 5)) / 10.0;
      rotate(atan(slope) + random(-0.15, 0.15));
      let w = random(15, 70);
      let h = random(3, 14);
      ellipse(0, 0, w, h);
      pop();
    }
  }

  // 5. THE HEART-EMBER & RIBCAGE ECHOES
  blendMode(ADD);
  for (let i = 0; i < 400; i++) {
    let x = randomGaussian(710, 90);
    let y = getBodyY(x) + randomGaussian(15, 25);
    let r = random(5, 45);
    fill(255, 190, 120, random(2, 10));
    ellipse(x, y, r * 2, r * 0.8);
  }

  // Subtle skeletal/structural lines dissolving upward
  for (let i = 0; i < 180; i++) {
    let startX = random(520, 950);
    let startY = getBodyY(startX) + random(5, 60);
    stroke(220, 200, 180, random(10, 35));
    strokeWeight(random(0.5, 2));
    noFill();
    beginShape();
    let cx = startX;
    let cy = startY;
    for (let s = 0; s < 30; s++) {
      vertex(cx, cy);
      cx += (noise(cx * 0.02, cy * 0.02) - 0.5) * 8;
      cy -= random(2, 6);
    }
    endShape();
  }

  // 6. DRIFTING ASH & EMBERS (The Final Dispersion)
  for (let i = 0; i < 900; i++) {
    let x = random(250, 1350);
    let y = random(150, 1480);

    // Keep particles mostly within the rising column
    let distFromCenter = abs(x - 800);
    let allowedWidth = map(y, 150, 1500, 550, 300);

    if (distFromCenter < allowedWidth + randomGaussian(0, 100)) {
      let yNorm = map(y, 150, 1480, 0, 1);
      let sz = random(1, 4.5) * map(yNorm, 0, 1, 0.5, 1.2);

      if (random(1) < 0.3) {
        // Warm ember
        fill(255, 210, 150, random(30, 150) * yNorm);
      } else {
        // Cold ash
        fill(180, 200, 220, random(20, 90));
      }
      ellipse(x, y, sz, sz * random(0.8, 1.5));
    }
  }

  // 7. FOREGROUND STILLNESS (Dark Water / Reflections at the base)
  blendMode(BLEND);
  for (let i = 0; i < 1200; i++) {
    let y = random(1460, height);
    let x = random(width);
    let w = random(50, 300);
    let h = random(1, 4);

    let depth = map(y, 1460, height, 0, 1);
    let c = lerpColor(color(12, 18, 24, 60), color(3, 5, 8, 150), depth);

    // Faint reflection of the light above
    if (abs(x - 750) < 300 && random(1) < 0.2) {
      c = lerpColor(c, color(120, 100, 85, 25), (1 - depth) * 0.5);
    }

    fill(c);
    rect(x - w/2, y, w, h, 2);
  }

  // 8. CANVAS TEXTURE & OIL GLAZE
  applyCanvasTexture();
}

// Defines the topography of the reclining, shrouded figure
function getBodyY(x) {
  let base = 1500;
  if (x < 300 || x > 1300) return base;

  // Normalize x across the body length (300 to 1300)
  let t = (x - 300) / 1000.0;

  // Anatomical mounds (Head, Chest, Pelvis, Knees, Feet)
  let head   = 75 * exp(-pow((t - 0.14) / 0.055, 2));
  let neck   = -15 * exp(-pow((t - 0.20) / 0.03, 2));
  let chest  = 115 * exp(-pow((t - 0.36) / 0.11, 2));
  let pelvis = 70 * exp(-pow((t - 0.56) / 0.09, 2));
  let knees  = 45 * exp(-pow((t - 0.74) / 0.08, 2));
  let feet   = 60 * exp(-pow((t - 0.90) / 0.035, 2));

  // Overall shroud arch
  let arch = sin(t * PI) * 45;

  // Organic erosion/noise
  let erosion = map(noise(x * 0.008), 0, 1, -18, 18);

  return base - (head + neck + chest + pelvis + knees + feet + arch) + erosion;
}

// Applies a tactile, museum-grade finish (linen weave + vignette + grain)
function applyCanvasTexture() {
  // Subtle vertical and horizontal linen threads
  strokeWeight(1);
  for (let x = 0; x < width; x += 3) {
    stroke(255, 255, 255, random(1, 3.5));
    line(x, 0, x, height);
  }
  for (let y = 0; y < height; y += 3) {
    stroke(0, 0, 0, random(2, 5));
    line(0, y, width, y);
  }

  // Pixel-level organic grain & vignette
  loadPixels();
  let cx = width * 0.5;
  let cy = height * 0.45;
  let maxDist = dist(0, 0, cx, cy);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Distance for vignette
      let d = dist(x, y, cx, cy);
      let vig = map(pow(d / maxDist, 1.8), 0, 1, 1, 0.25);

      // Film/Oil grain
      let grain = random(-9, 9);

      pixels[idx]     = constrain(pixels[idx] * vig + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255);
  noLoop();
}

function draw() {
  background(7, 6, 11);
  drawSky();
  drawStars();
  drawVeil();
  drawHorizonGlow();
  drawHills();
  drawMoon();
  drawMist();
  drawWater();
  drawShore();
  drawTree(420, shoreY(420) + 8);
  drawGrass();
  drawStones();
  drawFigure(1096, shoreY(1096) - 2);
  drawFlowers();
  drawFallingPetals();
  drawMotes();
  drawVignette();
  drawGrain();
}

function shoreY(x) {
  return 1596 + noise(x * 0.0027, 6.4) * 42 + sin(x * 0.008) * 5;
}

function drawSky() {
  for (let y = 0; y < height; y++) {
    let c;
    if (y < 1364) {
      let t = y / 1364;
      c = lerpColor(color(6, 6, 14), color(26, 18, 44), pow(t, 0.8));
      c = lerpColor(c, color(58, 32, 46), pow(t, 2.4));
    } else {
      let u = (y - 1364) / (height - 1364);
      c = lerpColor(color(34, 20, 28), color(8, 7, 9), pow(u, 0.65));
    }
    let n = noise(0.4, y * 0.0035);
    stroke(
      red(c) + (n - 0.5) * 8,
      green(c) + (n - 0.5) * 5,
      blue(c) + (n - 0.5) * 7
    );
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (let i = 0; i < 280; i++) {
    let y = random(40, 1280);
    let x = random(width);
    stroke(255, random(3, 9));
    strokeWeight(random(0.4, 1.4));
    line(x, y, x + random(16, 70), y + random(-1.5, 1.5));
  }
}

function drawStars() {
  for (let i = 0; i < 86; i++) {
    let x = random(30, width - 30);
    let y = random(30, 860);
    if (dist(x, y, 1216, 372) < 120) continue;
    stroke(230, 220, 200, random(30, 150));
    strokeWeight(random(0.6, 1.7));
    point(x, y);
  }
}

function drawVeil() {
  noStroke();
  for (let i = 0; i < 14; i++) {
    fill(14, 12, 26, random(4, 11));
    ellipse(random(width), random(80, 900), random(220, 680), random(22, 64));
  }
}

function drawHorizonGlow() {
  noStroke();
  for (let i = 200; i > 0; i -= 3) {
    fill(186, 96, 52, map(i, 0, 200, 7, 0));
    ellipse(990, 1362, i * 13.5, i * 1.15);
  }
  for (let i = 0; i < 70; i++) {
    let x = random(620, 1360);
    let y = random(1310, 1388);
    stroke(210, 150, 90, random(8, 22));
    strokeWeight(random(1, 2.4));
    line(x, y, x + random(20, 90), y + random(-1, 1));
  }
}

function drawHills() {
  noStroke();
  fill(62, 40, 58, 150);
  beginShape();
  vertex(0, 1388);
  for (let x = 0; x <= width; x += 16) {
    vertex(x, 1172 + noise(x * 0.0021, 1.15) * 78);
  }
  vertex(width, 1388);
  endShape(CLOSE);

  fill(16, 12, 18, 242);
  beginShape();
  vertex(0, 1410);
  for (let x = 0; x <= width; x += 12) {
    vertex(x, 1268 + noise(x * 0.0033, 2.7) * 42 + sin(x * 0.0022) * 14);
  }
  vertex(width, 1440);
  endShape(CLOSE);

  noFill();
  stroke(176, 108, 70, 36);
  strokeWeight(1.6);
  beginShape();
  for (let x = 0; x <= width; x += 12) {
    vertex(x, 1268 + noise(x * 0.0033, 2.7) * 42 + sin(x * 0.0022) * 14);
  }
  endShape();
}

function drawMoon() {
  let mx = 1216;
  let my = 372;
  noStroke();
  for (let i = 210; i > 0; i -= 4) {
    fill(186, 168, 140, map(i, 0, 210, 3, 11));
    ellipse(mx, my, i * 2.1, i * 2.1);
  }
  for (let a = 0; a < TWO_PI; a += 0.09) {
    let rr = 86 * random(0.96, 1.05);
    fill(236, 222, 198, random(30, 80));
    ellipse(mx + cos(a) * rr, my + sin(a) * rr, random(7, 16), random(5, 12));
  }
  fill(226, 212, 188);
  ellipse(mx, my, 164, 164);
  fill(204, 192, 170, 170);
  ellipse(mx - 16, my + 8, 132, 136);
  fill(160, 148, 132, 55);
  ellipse(mx - 22, my - 18, 48, 34);
  ellipse(mx + 30, my + 24, 28, 20);
  ellipse(mx - 4, my + 38, 20, 14);
  for (let i = 0; i < 7; i++) {
    fill(16, 12, 28, random(10, 28));
    ellipse(mx - 62 + random(-8, 24), my + random(-50, 50), random(28, 70), random(16, 36));
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 12; i++) {
    fill(140, 104, 86, 5);
    ellipse(random(width), 1348 + random(-16, 22), random(480, 1300), random(26, 70));
  }
}

function drawWater() {
  for (let y = 1356; y < 1710; y++) {
    let u = constrain((y - 1356) / 300, 0, 1);
    let c = lerpColor(color(38, 24, 32), color(9, 9, 12), u);
    stroke(c);
    strokeWeight(1);
    line(0, y, width, y);
  }

  let yEnd = shoreY(1096) - 16;
  for (let y = 1372; y < 1635; y += 3) {
    let wob = noise(y * 0.02, 3.3) * 5;
    stroke(6, 8, 12, 70);
    strokeWeight(1.15);
    line(0, y + wob, width, y + wob);

    let t = constrain((y - 1372) / (yEnd - 1372), 0, 1);
    let cx = lerp(990, 1090, t) + sin(y * 0.045) * 7;
    let half = lerp(12, 108, t);
    let a = lerp(64, 0, pow(t, 1.35));
    if (a > 2 && y < yEnd) {
      let cuts = 3 + int(t * 5);
      for (let k = 0; k < cuts; k++) {
        let x1 = cx - half + random(0, half * 1.3);
        let len = random(8, half * 0.7) * (1 - t * 0.5);
        stroke(204, 124, 66, a * random(0.45, 1));
        strokeWeight(random(0.8, 2.1));
        line(x1, y + random(-1, 1), x1 + len, y + random(-1, 1));
      }
    }

    if (y < 1565 && y % 6 < 4) {
      let mx = 1216 + sin(y * 0.06) * 5;
      let ma = map(y, 1372, 1565, 36, 0);
      stroke(196, 186, 168, ma);
      strokeWeight(random(0.6, 1.5));
      line(mx - random(2, 7), y, mx + random(2, 8), y);
    }
  }
}

function drawShore() {
  noStroke();
  for (let x = 0; x <= width; x += 2) {
    let y = shoreY(x);
    fill(11, 8, 10);
    rect(x, y, 3, height - y);
  }
  for (let i = 0; i < 520; i++) {
    let x = random(width);
    let y = random(shoreY(x), height);
    stroke(36, 24, 22, random(8, 24));
    strokeWeight(random(0.5, 1.6));
    line(x, y, x + random(12, 48), y + random(-1, 1));
  }
}

function drawTree(x, y) {
  push();
  translate(x, y);
  strokeCap(ROUND);
  stroke(14, 10, 12, 245);
  strokeWeight(5);
  line(0, 0, -86, 52);
  line(-6, 6, -36, 64);
  line(6, 2, 62, 44);
  line(2, 4, 22, 70);

  let px = 0;
  let py = 0;
  for (let i = 1; i <= 32; i++) {
    let t = i / 32;
    let nx = sin(t * PI) * 18 + (noise(t * 3.2, 4.4) - 0.5) * 14;
    let ny = -t * 610;
    stroke(17, 12, 14, 245);
    strokeWeight(lerp(36, 8, t));
    line(px, py, nx, ny);
    px = nx;
    py = ny;
  }
  for (let i = 0; i < 36; i++) {
    let t = random(0.08, 0.82);
    let bx = sin(t * PI) * 18;
    let by = -t * 610;
    stroke(46, 32, 30, 70);
    strokeWeight(1);
    line(bx - 9, by, bx + 7, by + random(-2, 2));
  }
  push();
  translate(px, py);
  branch(148, 0);
  pop();
  push();
  translate(sin(0.42 * PI) * 18, -0.42 * 610);
  rotate(radians(-62));
  branch(78, 2);
  pop();
  push();
  translate(sin(0.62 * PI) * 16, -0.62 * 610);
  rotate(radians(48));
  branch(64, 3);
  pop();
  pop();
}

function branch(len, depth) {
  if (len < 8 || depth > 9) {
    if (random() < 0.14) {
      push();
      rotate(random(-0.9, 0.9));
      noStroke();
      fill(random(124, 158), random(58, 78), random(30, 42), random(140, 200));
      ellipse(0, -8, random(4, 7), random(10, 16));
      pop();
    }
    return;
  }
  stroke(15, 11, 13, 235);
  strokeWeight(map(len, 8, 148, 0.7, 8));
  line(0, 0, 0, -len);
  translate(0, -len);
  let forks = depth < 4 && random() < 0.3 ? 3 : 2;
  let spread = random(16, 32);
  for (let i = 0; i < forks; i++) {
    push();
    let mid = forks == 1 ? 0 : -spread + (i * (spread * 2)) / (forks - 1);
    rotate(radians(mid + random(-9, 9)));
    branch(len * random(0.67, 0.79), depth + 1);
    pop();
  }
}

function drawGrass() {
  for (let i = 0; i < 160; i++) {
    let x = random(30, width - 30);
    let y = random(1680, 1990);
    stroke(24, 30, 18, random(40, 100));
    strokeWeight(1);
    line(x, y, x + random(-2, 2), y - random(8, 24));
  }
