function lily(x, y, sc, rot, wilt, tone) {
  let petal;
  if (tone === 0) petal = color(214, 202, 184, 225);
  else if (tone === 1) petal = color(198, 176, 146, 215);
  else petal = color(158, 124, 118, 200);

  push();
  translate(x, y);
  rotate(rot * 0.15);
  stroke(32, 40, 26, 165);
  strokeWeight(2.1 * sc);
  noFill();
  bezier(0, 4 * sc, -12 * sc, 36 * sc, 10 * sc, 72 * sc, -2 * sc, 118 * sc);
  noStroke();
  fill(28, 38, 22, 150);
  push();
  translate(-2 * sc, 52 * sc);
  rotate(-0.9);
  ellipse(8 * sc, 0, 7 * sc, 18 * sc);
  pop();

  push();
  rotate(wilt * 0.8);
  let n = wilt > 0.75 ? 5 : 6;
  for (let i = 0; i < n; i++) {
    push();
    rotate((i * TWO_PI) / n + 0.08);
    fill(petal);
    ellipse(0, -15 * sc, 10 * sc, 28 * sc);
    fill(255, 28);
    ellipse(-1.5 * sc, -16 * sc, 2.4 * sc, 10 * sc);
    pop();
  }
  fill(86, 58, 28, 210);
  ellipse(0, 0, 7 * sc, 7 * sc);
  stroke(130, 86, 34, 160);
  strokeWeight(0.8);
  for (let i = 0; i < 5; i++) {
    let a = random(TWO_PI);
    line(0, 0, cos(a) * 4.5 * sc, sin(a) * 4.5 * sc);
  }
  pop();
  pop();
}

