function branch(x, y, len, angle, depth) {
  if (depth > 10 || len < 3) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(26 + depth, 16, 18, 230);
  strokeWeight(map(depth, 0, 10, 16, 0.5));
  line(x, y, x2, y2);
  if (depth < 3) {
    stroke(170, 110, 70, 40);
    strokeWeight(1.2);
    line(x + 4, y, x2 + 3, y2);
  }
  let spread = 0.42 + random(-0.06, 0.08);
  let shrink = 0.66 + random(-0.04, 0.04);
  branch(x2, y2, len * shrink, angle - spread, depth + 1);
  branch(x2, y2, len * (shrink - 0.04), angle + spread * 0.9, depth + 1);
  if (random() < 0.28 && depth > 1) {
    branch(x2, y2, len * 0.48, angle + random(-0.3, 0.3), depth + 1);
  }
}

