function skyColor(y) {
  if (y < horizon - 220) {
    var u = y / (horizon - 220);
    return color(lerp(4, 18, u), lerp(8, 16, u), lerp(12, 24, pow(u, 0.8)));
  } else if (y < horizon - 50) {
    var u2 = (y - (horizon - 220)) / 170;
    var k = pow(u2, 1.35);
    return color(lerp(18, 156, k), lerp(16, 64, k), lerp(24, 30, u2));
  } else if (y < horizon + 40) {
    var u3 = (y - (horizon - 50)) / 90;
    return color(lerp(156, 46, u3), lerp(64, 22, u3), lerp(30, 18, u3));
  }
  var u4 = constrain((y - horizon) / (height - horizon), 0, 1);
  return color(lerp(28, 6, u4), lerp(16, 6, u4), lerp(14, 7, u4));
}

function sky() {
  var y, c, drift, i, y2, x2, c2, w, len;
  for (y = 0; y < height; y++) {
    c = skyColor(y);
    drift = (noise(y * 0.012, 20) - 0.5) * 8;
    stroke(red(c) + drift, green(c) + drift * 0.4, blue(c) + drift * 0.2);
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (i = 0; i < 3600; i++) {
    y2 = random(horizon + 90);
    x2 = random(width);
    c2 = skyColor(y2);
    w = (noise(x2 * 0.003, y2 * 0.01) - 0.5) * 24;
    stroke(red(c2) + w, green(c2) + w * 0.35, blue(c2), random(10, 30));
    strokeWeight(random(6, 34));
    len = random(28, 210);
    line(x2, y2, x2 + len, y2 + random(-1.6, 1.6));
  }
}

