function farTrees() {
  var xs = [130, 240, 340, 690, 1042, 1368, 1496];
  var i, x, y, s, top;
  for (i = 0; i < xs.length; i++) {
    x = xs[i];
    y = ridgeY(x) + 1;
    s = 0.65 + noise(x * 0.02, 9) * 0.7;
    if (x > 1000 && x < 1090) s = 1.55;
    top = y - 52 * s;
    stroke(5, 4, 7, 220);
    strokeWeight(1.5 * s);
    line(x, y, x + s * 1.5, top + 8);
    strokeWeight(0.7 * s);
    line(x, y - 16 * s, x - 13 * s, y - 34 * s);
    line(x + 1, y - 20 * s, x + 14 * s, y - 40 * s);
    line(x + s, y - 32 * s, x - 8 * s, y - 54 * s);
    line(x + s, y - 30 * s, x + 10 * s, y - 56 * s);
    line(x + s * 1.5, top + 8, x - 4 * s, top - 8);
  }
}

