function pathCenter(y) {
  var t = constrain((y - horizon) / (height - horizon), 0, 1);
  return lerp(730, 348, pow(t, 0.85)) + sin(t * 7.0) * 14 * (1 - t);
}

function path() {
  var y, t, cx, w;
  for (y = horizon + 24; y < 1900; y += 2) {
    t = (y - horizon) / (height - horizon);
    cx = pathCenter(y);
    w = lerp(5, 84, pow(t, 0.78));
    if (inRiver(cx, y)) continue;
    stroke(64, 40, 26, 14 + (1 - t) * 12);
    strokeWeight(1);
    line(cx - w / 2, y, cx + w / 2, y);
  }
}

function riverCenter(y) {
  var t = constrain((y - horizon) / (height - horizon), 0, 1);
  return lerp(1110, 840, t) + sin(t * 2.1) * 54 + (noise(t * 1.6, 8.0) - 0.5) * 36;
}

function riverHalfWidth(y) {
  var t = constrain((y - horizon) / (height - horizon), 0, 1);
  return lerp(6, 250, pow(t, 0.7));
}

function inRiver(x, y) {
  if (y < horizon) return false;
  return Math.abs(x - riverCenter(y)) < riverHalfWidth(y);
}

function river() {
  var y, cx, hw, t;
  noStroke();
  for (y = horizon; y < height; y += 2) {
    cx = riverCenter(y);
    hw = riverHalfWidth(y);
    t = constrain((y - horizon) / (height - horizon), 0, 1);
    fill(5 + t * 4, 7 + t * 2, 13, 238);
    rect(cx - hw, y, hw * 2 + 1, 3);
    fill(0, 0, 0, 55);
    rect(cx - hw, y, 7, 3);
    rect(cx + hw - 7, y, 7, 3);
    fill(18, 20, 28, 28);
    rect(cx - hw * 0.42, y, hw * 0.84, 3);
  }
}

function reflection() {
  var y, cx, t, n, span, a, j;
  for (y = horizon + 6; y < height - 30; y += 3) {
    cx = riverCenter(y);
    t = (y - horizon) / (height - horizon);
    n = noise(y * 0.02, 3.3);
    if (n < 0.4) continue;
    span = (1 - t) * map(n, 0.4, 1, 3, 20);
    a = (1 - t) * (1 - t) * 140 * n;
    stroke(214, 128, 54, a);
    strokeWeight(random(0.5, 1.7));
    j = (noise(y * 0.05, 1.4) - 0.5) * 18 * t;
    line(cx + j - span * 0.15, y, cx + j + span, y);
  }
}

