    bezier(
      x + i * 0.7, y,
      x + 5 + n * 8, y - h * 0.35,
      x + 9, y - h * 0.68,
      x + 12, y - h
    );
  }
  stroke(8, 6, 6, 180);
  strokeWeight(bulk * 0.34);
  line(x, y + 4, x - 46, y + 28);
  line(x + 4, y + 2, x + 34, y + 22);
