function grow(x, y, len, ang, depth, w) {
  var n, nx, ny, bend, mx, my, warmth, s1, s2, leafA, gy;
  if (len < 2.6 || depth <= 0) {
    if (random() < 0.5) {
      leafA = random(55, 145);
      gy = constrain(map(y, horizon - 180, horizon + 24, 0, 1), 0, 1);
      noStroke();
      fill(lerp(92, 174, gy), lerp(28, 74, gy), lerp(24, 32, gy), leafA);
      push();
      translate(x, y);
      rotate(random(TWO_PI));
      ellipse(0, 0, random(3, 6), random(7, 13));
      pop();
    }
    return;
  }
  n = noise(x * 0.008, y * 0.008, depth * 0.2);
  nx = x + cos(ang) * len;
  ny = y + sin(ang) * len;
  bend = (n - 0.5) * len * 0.36;
  mx = (x + nx) / 2 + cos(ang + HALF_PI) * bend;
  my = (y + ny) / 2 + sin(ang + HALF_PI) * bend * 0.35;
  warmth = constrain(map((y + ny) / 2, horizon - 200, horizon + 30, 0, 1), 0, 1);
  stroke(12 + warmth * 38, 9 + warmth * 14, 11, 215);
  strokeWeight(max(0.55, w));
  line(x, y, mx, my);
  line(mx, my, nx, ny);
  if (w > 2.4) {
    stroke(58, 34, 24, 26 + warmth * 34);
    strokeWeight(max(0.35, w * 0.16));
    line(x + 1, y, nx + 1, ny);
  }
  s1 = 0.2 + n * 0.4;
  s2 = 0.16 + (1 - n) * 0.36;
  grow(nx, ny, len * random(0.64, 0.78), ang - s1, depth - 1, w * 0.66);
  grow(nx, ny, len * random(0.6, 0.75), ang + s2, depth - 1, w * 0.62);
  if (depth > 5 && random() < 0.26) {
    grow(mx, my, len * random(0.34, 0.5), ang + random(-0.55, 0.55), depth - 3, w * 0.42);
  }
}

