function skyColor(y) {
  let t = constrain(y / 1400, 0, 1);
  let c0 = color(5, 6, 14);
  let c1 = color(16, 15, 30);
  let c2 = color(38, 26, 40);
  let c3 = color(84, 44, 40);
  let c4 = color(168, 92, 60);
  if (t < 0.55) return lerpColor(c0, c1, t / 0.55);
  if (t < 0.82) return lerpColor(c1, c2, (t - 0.55) / 0.27);
  if (t < 0.94) return lerpColor(c2, c3, (t - 0.82) / 0.12);
  return lerpColor(c3, c4, (t - 0.94) / 0.06);
}

function drawSky() {
  for (let y = 0; y < 1460; y++) {
    let c = skyColor(y);
    let n = noise(0.15, y * 0.0028);
    stroke(
      red(c) + (n - 0.5) * 12,
      green(c) + (n - 0.5) * 8,
      blue(c) + (n - 0.5) * 10
    );
    strokeWeight(1);
    line(0, y, width, y);
  }
  for (let i = 0; i < 520; i++) {
    let y = random(20, 1320);
    let c = skyColor(y);
    stroke(red(c), green(c), blue(c), random(10, 28));
    strokeWeight(random(10, 36));
    let x = random(width);
    let len = random(50, 220);
    let ang = random(-0.12, 0.12);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

