function drawFigure() {
  const cx = 500;
  const headY = 1568;
  noStroke();

  for (let y = headY + 34; y < headY + 250; y += 2) {
    let k = (y - (headY + 34)) / 250;
    let half = 14 + sin(min(k, 0.22) / 0.22 * HALF_PI) * 46;
    if (k > 0.28) half = lerp(60, 42, min(1, (k - 0.28) / 0.4));
    let alpha = 215;
    let spread = 0;
    if (k > 0.58) {
      let f = (k - 0.58) / 0.42;
      alpha = lerp(215, 0, pow(f, 0.85));
      spread = f * 42;
      half += f * 18;
    }
    let sway = (noise(y * 0.02, 5) - 0.5) * 8;
    for (let j = 0; j < 8; j++) {
      let x = cx + sway + random(-half - spread, half + spread);
      fill(12 + random(6), 10, 12, alpha * random(0.4, 1));
      ellipse(x, y + random(-1, 1), random(7, 16), random(4, 10));
    }
    if (alpha > 18) {
      fill(186, 112, 74, alpha * 0.2);
      ellipse(cx + sway - half + 1, y, 2.5, 6);
      fill(186, 168, 146, alpha * 0.16);
      ellipse(cx + sway + half - 1, y, 2.5, 6);
    }
  }

  for (let i = 0; i < 150; i++) {
    let a = random(TWO_PI);
    let rx = abs(cos(a)) * random(8, 24);
    let ry = abs(sin(a)) * random(10, 30);
    fill(11, 9, 11, random(150, 235));
    ellipse(cx + cos(a) * rx * 0.85, headY + sin(a) * ry * 0.9 - 2, random(6, 13), random(7, 14));
