  for (let i = 0; i < 14; i++) {
    fill(176, 164, 148, random(16, 36));
    ellipse(cx + 15 + random(0, 5), headY + random(-10, 16), 2.4, 5);
  }

  for (let i = 0; i < 36; i++) {
    let t = random();
    fill(190, 178, 166, lerp(40, 0, t));
    ellipse(cx + 24 + t * 80 + random(-6, 6), headY + 64 + t * 30 + random(-12, 16), random(1.4, 3.2), random(1.4, 3));
  }

  for (let i = 0; i < 80; i++) {
    let y = headY + 190 + random(70);
    fill(150, 142, 138, random(4, 16));
    ellipse(cx + random(-50, 50), y, random(16, 40), random(6, 12));
