function lerpArr(a, b, t) {
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function bandColor(stops, t) {
  if (t <= stops[0][0]) return stops[0][1];
  for (var i = 1; i < stops.length; i++) {
    if (t <= stops[i][0]) {
      var u = (t - stops[i - 1][0]) / (stops[i][0] - stops[i - 1][0]);
      u = u * u * (3 - 2 * u);
      return lerpArr(stops[i - 1][1], stops[i][1], u);
    }
  }
  return stops[stops.length - 1][1];
}

function paintSky(horizon) {
  var stops = [
    [0.00, [6, 8, 16]],
    [0.16, [14, 15, 28]],
    [0.38, [32, 20, 40]],
    [0.58, [58, 26, 40]],
    [0.76, [108, 40, 34]],
    [0.90, [176, 74, 40]],
    [1.00, [236, 164, 92]]
  ];
  noFill();
  for (var y = 0; y < horizon; y++) {
    var t = y / horizon;
    var wobble = (noise(y * 0.007, 1.2) - 0.5) * 0.04;
    var c = bandColor(stops, constrain(t + wobble, 0, 1));
    var drift = (noise(y * 0.02, 4) - 0.5) * 12;
    stroke(c[0] + drift, c[1] + drift * 0.35, c[2], 255);
    strokeWeight(1);
    line(0, y, width, y);
  }
}

function paintSea(horizon) {
  var stops = [
    [0.00, [124, 64, 42]],
    [0.05, [52, 30, 32]],
    [0.16, [16, 18, 26]],
    [0.42, [8, 11, 18]],
    [1.00, [4, 5, 8]]
  ];
  noFill();
  for (var y = horizon; y < height; y++) {
    var t = (y - horizon) / (height - horizon);
    var wobble = (noise(y * 0.01, 9) - 0.5) * 0.02;
    var c = bandColor(stops, constrain(t + wobble, 0, 1));
    stroke(c[0], c[1], c[2], 255);
    strokeWeight(1);
    line(0, y, width, y);
  }
}

function scumble(x, y, rx, ry, col, n, ang) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  for (var i = 0; i < n; i++) {
    var px = random(-rx, rx);
    var py = random(-ry, ry);
    if ((px * px) / (rx * rx) + (py * py) / (ry * ry) > 1) continue;
    fill(col[0], col[1], col[2], col[3] * random(0.35, 1));
    ellipse(px, py, random(12, 40), random(2, 7));
  }
  pop();
}

function scumbleField(count, y0, y1, rgb, a0, a1, rx0, rx1, ry0, ry1) {
  for (var i = 0; i < count; i++) {
    scumble(
      random(width),
      random(y0, y1),
      random(rx0, rx1),
      random(ry0, ry1),
      [rgb[0], rgb[1], rgb[2], random(a0, a1)],
      64,
      random(-0.45, 0.45)
    );
  }
}

