function ridgeY(x) {
  if (ridge.length === 0) return 0;
  if (x <= ridge[0].x) return ridge[0].y;
  if (x >= ridge[ridge.length - 1].x) return height;
  for (var i = 1; i < ridge.length; i++) {
    if (x <= ridge[i].x) {
      var u = (x - ridge[i - 1].x) / (ridge[i].x - ridge[i - 1].x);
      return lerp(ridge[i - 1].y, ridge[i].y, u);
    }
  }
  return height;
}

function drawHeadland() {
  ridge = [];
  var x;
  for (x = 0; x <= 560; x += 6) {
    var n = noise(x * 0.011, 3.3);
    var base = lerp(800, 1260, x / 560);
    var y = base + sin(x * 0.021) * 62 + sin(x * 0.006) * 34 + (n - 0.5) * 26 - 36;
    ridge.push({ x: x, y: y });
  }

  noStroke();
  fill(16, 12, 18);
  beginShape();
  vertex(0, height);
  vertex(0, ridge[0].y);
  for (var i = 0; i < ridge.length; i++) vertex(ridge[i].x, ridge[i].y);
  vertex(520, 1480);
  vertex(280, 1760);
  vertex(0, 1840);
  endShape(CLOSE);

  fill(8, 7, 10, 170);
  beginShape();
  vertex(0, height);
  vertex(0, ridge[0].y + 48);
  for (var j = 0; j < ridge.length; j++) vertex(ridge[j].x - 8, ridge[j].y + 42);
  vertex(430, 1620);
  vertex(0, 1900);
  endShape(CLOSE);

  for (var k = 0; k < 900; k++) {
    var sx = random(0, 500);
    var sy = random(860, 1880);
    if (sy < ridgeY(sx)) continue;
    stroke(22, 16, 18, random(18, 48));
    strokeWeight(random(0.8, 1.8));
    line(sx, sy, sx + random(-10, 16), sy + random(-3, 5));
  }

  noFill();
  stroke(198, 112, 66, 80);
  strokeWeight(1.6);
  beginShape();
  for (var a = 0; a < ridge.length; a++) vertex(ridge[a].x, ridge[a].y);
  endShape();
  stroke(255, 196, 150, 36);
  strokeWeight(1);
  beginShape();
  for (var b = 0; b < ridge.length; b++) vertex(ridge[b].x, ridge[b].y - 1);
  endShape();
}

function cloth(cx, top, bottom, halfW, seedOff, col) {
  noStroke();
  fill(col[0], col[1], col[2], col[3]);
  beginShape();
  var steps = 16;
  var i, t, y, bulge, n;
  for (i = 0; i <= steps; i++) {
    t = i / steps;
    y = lerp(top, bottom, t);
    bulge = sin(t * PI);
    n = (noise(seedOff, t * 2.7) - 0.5) * 14;
    vertex(cx - halfW * 0.16 * bulge + n * 0.3, y);
  }
  for (i = steps; i >= 0; i--) {
    t = i / steps;
    y = lerp(top, bottom, t);
    bulge = sin(t * PI);
    n = (noise(seedOff + 8, t * 2.7) - 0.5) * 16;
    vertex(cx + halfW * bulge + n, y);
  }
  endShape(CLOSE);
}

