function drawTable() {
  let topY = 1570;
  noStroke();
  fill(24, 16, 11);
  rect(0, topY, width, height - topY);
  fill(38, 25, 16);
  rect(0, topY, width, 16);

  for (let i = 0; i < 60; i++) {
    let y = topY + 30 + i * 7;
    stroke(70, 48, 28, random(15, 60));
    strokeWeight(random(1, 3));
    noFill();
    beginShape();
    for (let x = 0; x <= width; x += 100) {
      curveVertex(x, y + random(-4, 4));
    }
    endShape();
  }
}

function drawGlow(x, y) {
  noStroke();
  for (let r = 520; r > 0; r -= 20) {
    let alpha = map(r, 0, 520, 22, 0);
    fill(255, 228, 190, alpha);
    ellipse(x, y, r * 1.4, r * 2);
  }
}

function drawHourglass(x, baseY, s) {
  let h = s * 1.7;
  noStroke();

  fill(40, 27, 17);
  ellipse(x, baseY - h, s * 0.55, s * 0.18);
  rect(x - s * 0.55, baseY - h - s * 0.05, s * 1.1, s * 0.18);

  ellipse(x, baseY, s * 0.55, s * 0.18);
  rect(x - s * 0.55, baseY - s * 0.1, s * 1.1, s * 0.18);

  stroke(55, 38, 21);
  strokeWeight(s * 0.06);
  line(x - s * 0.42, baseY - h, x - s * 0.32, baseY);
  line(x + s * 0.42, baseY - h, x + s * 0.32, baseY);

  noStroke();
  fill(190, 210, 215, 40);
  stroke(220, 230, 235, 120);
  strokeWeight(2);
  ellipse(x, baseY - h * 0.62, s * 0.8, s * 0.85);
  ellipse(x, baseY - h * 0.2, s * 0.8, s * 0.85);

  fill(190, 210, 215, 50);
  rect(x - s * 0.1, baseY - h * 0.42, s * 0.2, s * 0.4);

  noStroke();
  fill(148, 106, 72);
  beginShape();
  curveVertex(x - s * 0.28, baseY - h * 0.72);
  curveVertex(x - s * 0.2, baseY - h * 0.62);
  curveVertex(x + s * 0.22, baseY - h * 0.68);
  curveVertex(x + s * 0.28, baseY - h * 0.55);
  curveVertex(x - s * 0.28, baseY - h * 0.55);
  endShape(CLOSE);

  beginShape();
  vertex(x - s * 0.3, baseY - h * 0.25);
  vertex(x + s * 0.3, baseY - h * 0.25);
  vertex(x + s * 0.22, baseY - h * 0.12);
  vertex(x, baseY - h * 0.05);
  vertex(x - s * 0.22, baseY - h * 0.12);
  endShape(CLOSE);

  noFill();
  stroke(220, 230, 235, 90);
  ellipse(x, baseY - h * 0.62, s * 0.8, s * 0.85);
  ellipse(x, baseY - h * 0.2, s * 0.8, s * 0.85);
  noStroke();
}

function drawCandle(x, baseY, s) {
  noStroke();

  fill(58, 41, 24);
  ellipse(x, baseY, s * 0.8, s * 0.2);
  rect(x - s * 0.8, baseY - s * 0.15, s * 1.6, s * 0.18);

  fill(52, 36, 20);
  rect(x - s * 0.2, baseY - s * 1.0, s * 0.4, s * 0.85);

  fill(72, 54, 30);
  ellipse(x, baseY - s * 1.0, s * 0.6, s * 0.18);
  rect(x - s * 0.6, baseY - s * 1.18, s * 1.2, s * 0.22);

  fill(226, 212, 186);
  beginShape();
  vertex(x - s * 0.24, baseY - s * 1.18);
  vertex(x - s * 0.21, baseY - s * 2.45);
  vertex(x + s * 0.21, baseY - s * 2.45);
  vertex(x + s * 0.24, baseY - s * 1.18);
  endShape(CLOSE);

  fill(130, 108, 82, 120);
  rect(x + s * 0.1, baseY - s * 2.45, s * 0.11, s * 1.27);

  fill(226, 212, 186);
  noStroke();
  ellipse(x - s * 0.12, baseY - s * 1.75, s * 0.09, s * 0.4);
  ellipse(x + s * 0.18, baseY - s * 1.45, s * 0.1, s * 0.3);

  stroke(20, 12, 8);
  strokeWeight(5);
  line(x, baseY - s * 2.45, x, baseY - s * 2.6);
  noStroke();
}

function drawSmoke(x, y) {
  for (let i = 0; i < 11; i++) {
    let off = random(-15, 15);
    stroke(150, 145, 140, random(20, 70));
    strokeWeight(random(2, 8));
    noFill();
    beginShape();
    curveVertex(x + off, y);
    curveVertex(x + off + random(-25, 25), y - 50);
    curveVertex(x + off + random(-45, 45), y - 120);
    curveVertex(x + off + random(-65, 65), y - 210);
    curveVertex(x + off + random(-85, 85), y - 330);
    curveVertex(x + off + random(-100, 100), y - 500);
    endShape();
  }
}

function drawSkull(cx, cy, s) {
  let h = s * 1.15;

  stroke(40, 25, 15, 200);
  strokeWeight(3);
  fill(208, 190, 162);
  beginShape();
  curveVertex(cx, cy - h * 0.98);
  curveVertex(cx - s * 0.78, cy - h * 0.78);
  curveVertex(cx - s * 0.96, cy - h * 0.1);
  curveVertex(cx - s * 0.72, cy + h * 0.26);
  curveVertex(cx - s * 0.45, cy + h * 0.66);
  curveVertex(cx, cy + h * 0.98);
  curveVertex(cx + s * 0.45, cy + h * 0.66);
  curveVertex(cx + s * 0.72, cy + h * 0.26);
  curveVertex(cx + s * 0.96, cy - h * 0.1);
  curveVertex(cx + s * 0.78, cy - h * 0.78);
  curveVertex(cx, cy - h * 0.98);
  endShape(CLOSE);

  noStroke();
  fill(55, 35, 22, 95);
  beginShape();
  curveVertex(cx + s * 0.05, cy - h * 0.85);
  curveVertex(cx + s * 0.55, cy - h * 0.75);
  curveVertex(cx + s * 0.92, cy - h * 0.1);
  curveVertex(cx + s * 0.68, cy + h * 0.25);
  curveVertex(cx + s * 0.42, cy + h * 0.65);
  curveVertex(cx + s * 0.05, cy + h * 0.9);
  curveVertex(cx, cy + h * 0.98);
  curveVertex(cx, cy - h * 0.98);
  endShape(CLOSE);

  fill(245, 232, 205, 80);
  beginShape();
  curveVertex(cx - s * 0.05, cy - h * 0.9);
  curveVertex(cx - s * 0.5, cy - h * 0.8);
  curveVertex(cx - s * 0.85, cy - h * 0.15);
  curveVertex(cx - s * 0.6, cy + h * 0.2);
  curveVertex(cx - s * 0.3, cy + h * 0.6);
  curveVertex(cx - s * 0.05, cy + h * 0.9);
  curveVertex(cx, cy + h * 0.98);
  curveVertex(cx, cy - h * 0.98);
  endShape(CLOSE);

  drawEyeSocket(cx - s * 0.4, cy - h * 0.2, s * 0.42, s * 0.5);
  drawEyeSocket(cx + s * 0.4, cy - h * 0.2, s * 0.42, s * 0.5);

  noStroke();
  fill(24, 14, 10);
  beginShape();
  vertex(cx, cy + h * 0.05);
  bezierVertex(cx - s * 0.13, cy + h * 0.15, cx - s * 0.22, cy + h * 0.35, cx, cy + h * 0.4);
  bezierVertex(cx + s * 0.22, cy + h * 0.35, cx + s * 0.13, cy + h * 0.15, cx, cy + h * 0.05);
  endShape(CLOSE);

  let my = cy + h * 0.58;
  stroke(70, 50, 35, 220);
  strokeWeight(3);
  line(cx - s * 0.38, my, cx + s * 0.38, my);
  for (let i = -5; i <= 5; i++) {
    let tx = cx + i * s * 0.065;
    line(tx, my - 4, tx, my + 5);
  }

  noFill();
  stroke(215, 200, 170, 140);
  strokeWeight(2);
  beginShape();
  for (let i = -6; i <= 6; i++) {
    let tx = cx + i * s * 0.06;
    curveVertex(tx, my - (i % 2 === 0 ? 6 : 3));
  }
  endShape();

  stroke(70, 50, 35, 130);
  strokeWeight(2);
  noFill();
  for (let i = 0; i < 3; i++) {
    beginShape();
    let x1 = cx + random(-s * 0.2, s * 0.2);
    let y1 = cy - h * 0.75;
    curveVertex(x1, y1);
    curveVertex(x1 + random(-s * 0.1, s * 0.1), y1 + h * 0.08);
    curveVertex(x1 + random(-s * 0.2, s * 0.25), y1 + h * 0.16);
    endShape();
  }
  noStroke();
}

function drawEyeSocket(x, y, w, h) {
  noStroke();
  fill(28, 17, 12);
  ellipse(x, y, w, h);
  fill(8, 5, 4, 200);
  ellipse(x, y + h * 0.08, w * 0.78, h * 0.88);
  noFill();
  stroke(235, 225, 195, 110);
  strokeWeight(4);
  arc(x, y - h * 0.35, w * 1.05, h * 1.1, PI, TWO_PI);
  noStroke();
}

function drawRoses() {
  drawRose(610, 1460, 58, color(96, 22, 22));
  drawRose(980, 1440, 52, color(70, 18, 20));
  drawRose(500, 1540, 48, color(82, 24, 26));
  drawRose(1110, 1530, 55, color(88, 20, 22));
  drawRose(740, 1555, 42, color(64, 16, 18));
}

function drawRose(x, y, size, col) {
  stroke(45, 38, 24, 220);
  strokeWeight(size * 0.12);
  noFill();
  beginShape();
  vertex(x, y);
  bezierVertex(x + size * 0.1, y + size * 0.5, x + size * 0.25, y + size * 0.9, x + size * 0.1, y + size * 1.4);
  endShape();

  noStroke();
  fill(col);
  for (let i = 0; i < 7; i++) {
    let a = TWO_PI * (i / 7) + random(-0.3, 0.3);
    let px = x + cos(a) * size * 0.45;
    let py = y + sin(a) * size * 0.45;
    ellipse(px, py, size * 0.65, size * 0.65);
  }

  fill(red(col) * 0.7, green(col) * 0.7, blue(col) * 0.7, 220);
  for (let i = 0; i < 6; i++) {
    let a = TWO_PI * (i / 6) + random(-0.2, 0.2);
    let px = x + cos(a) * size * 0.2;
    let py = y + sin(a) * size * 0.2;
    ellipse(px, py, size * 0.45, size * 0.45);
  }

  fill(15, 8, 6);
  ellipse(x, y, size * 0.35, size * 0.35);
}

function drawMoth(x, y, s) {
  noStroke();

  fill(255, 240, 210, 10);
  ellipse(x, y, s * 2.5, s * 2.5);

  fill(45, 38, 32, 230);
  beginShape();
  vertex(x - s * 0.05, y);
  bezierVertex(x - s * 1.3, y - s * 0.9, x - s * 1.9, y - s * 0.25, x - s * 1.2, y + s * 0.3);
  bezierVertex(x - s * 0.9, y + s * 0.6, x - s * 0.35, y + s * 0.3, x - s * 0.05, y);
  endShape(CLOSE);

  beginShape();
  vertex(x + s * 0.05, y);
  bezierVertex(x + s * 1.3, y - s * 0.9, x + s * 1.9, y - s * 0.25, x + s * 1.2, y + s * 0.3);
  bezierVertex(x + s * 0.9, y + s * 0.6, x + s * 0.35, y + s * 0.3, x + s * 0.05, y);
  endShape(CLOSE);

  fill(38, 31, 27, 230);
  beginShape();
  vertex(x - s * 0.1, y + s * 0.2);
  bezierVertex(x - s * 0.9, y + s * 0.8, x - s * 1.2, y + s * 1.5, x - s * 0.3, y + s * 1.6);
  bezierVertex(x - s * 0.1, y + s * 1.5, x - s * 0.05, y + s * 0.7, x - s * 0.1, y + s * 0.2);
  endShape(CLOSE);

  beginShape();
  vertex(x + s * 0.1, y + s * 0.2);
  bezierVertex(x + s * 0.9, y + s * 0.8, x + s * 1.2, y + s * 1.5, x + s * 0.3, y + s * 1.6);
  bezierVertex(x + s * 0.1, y + s * 1.5, x + s * 0.05, y + s * 0.7, x + s * 0.1, y + s * 0.2);
  endShape(CLOSE);

  fill(60, 48, 36);
  ellipse(x, y, s * 0.2, s * 1.1);

  fill(70, 60, 45);
  ellipse(x, y - s * 0.5, s * 0.16, s * 0.16);

  fill(230, 225, 200, 220);
  ellipse(x, y - s * 0.3, s * 0.12, s * 0.16);

  fill(20, 15, 12);
  ellipse(x - s * 0.06, y - s * 0.3, s * 0.04, s * 0.05);
  ellipse(x + s * 0.06, y - s * 0.3, s * 0.04, s * 0.05);

  noFill();
  stroke(180, 170, 140, 80);
  strokeWeight(2);
  arc(x - s * 0.8, y - s * 0.2, s * 0.6, s * 0.5, PI, TWO_PI);
  arc(x + s * 0.8, y - s * 0.2, s * 0.6, s * 0.5, PI, TWO_PI);
  noStroke();
}

function drawFloatingPetals() {
  noStroke();
  fill(80, 18, 18, 180);
  for (let i = 0; i < 18; i++) {
    let x = random(420, 1250);
    let y = random(300, 1350);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(12, 28), random(7, 14));
    pop();
  }
}

function drawVignette() {
  noFill();
  for (let r = 2400; r > 400; r -= 25) {
    let t = (2400 - r) / 2000;
    let alpha = 7 * (1 - t * t);
    stroke(0, 0, 0, alpha);
    strokeWeight(40);
    ellipse(width / 2, height / 2, r, r * 1.25);
  }
}

const W = 1600;
const H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255);
  pixelDensity(1);
}

function draw() {
  drawPainting();
  noLoop();
}

function drawPainting() {
  drawSky();
  drawStars();
  drawMoon(380, 360, 140);
  drawMoonReflection();
  drawShore();
  drawWater();
  drawBoatAndFigure();
  drawLantern(640, 1450);
  drawLanternReflection(640);
  drawMist();
  drawGrain();
}

function drawSky() {
  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let c = lerpColor(color(6, 8, 16), color(24, 26, 36), t);
    fill(c);
    rect(0, y, W, 1);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 220; i++) {
    let x = random(W);
    let y = random(0, H * 0.55);
    let s = random(1, 2.6);
    let a = random(30, 160);
    fill(240, 240, 230, a);
    ellipse(x, y, s, s);
  }
}

function drawMoon(x, y, r) {
  noStroke();
  for (let i = 12; i > 0; i--) {
    let a = map(i, 0, 12, 5, 22);
    fill(220, 225, 235, a);
    ellipse(x, y, r * 2 + i * 16, r * 2 + i * 16);
  }
  fill(215, 220, 228);
  ellipse(x, y, r * 2, r * 2);
  fill(185, 192, 202, 70);
  ellipse(x - r * 0.25, y - r * 0.2, r * 0.85, r * 0.65);
  ellipse(x + r * 0.3, y + r * 0.25, r * 0.7, r * 0.5);
  fill(210, 215, 225, 60);
  ellipse(x - r * 0.15, y + r * 0.1, r * 0.5, r * 0.4);
}

function drawMoonReflection() {
  noStroke();
  let baseX = 380;
  for (let i = 0; i < 35; i++) {
    let yy = 1320 + i * 14;
    if (yy > H) break;
    let w = random(18, 60);
    let a = map(i, 0, 35, 70, 0);
    fill(220, 225, 230, a);
    ellipse(baseX + random(-40, 40), yy, w, 9);
  }
}

function drawShore() {
  noStroke();
  fill(16, 20, 22);
  beginShape();
  vertex(0, 1300);
  for (let x = 0; x <= W; x += 10) {
    let y = 1170 + noise(x * 0.005, 20) * 90;
    vertex(x, y);
  }
  vertex(W, 1300);
  endShape(CLOSE);
}

function drawWater() {
  noStroke();
  for (let y = 1300; y < H; y++) {
    let t = (y - 1300) / (H - 1300);
    let c = lerpColor(color(18, 24, 30), color(5, 7, 10), t);
    fill(c);
    rect(0, y, W, 1);
  }
  stroke(180, 200, 210, 18);
  strokeWeight(1);
  for (let i = 0; i < 90; i++) {
    let y = 1350 + i * 9;
    if (y > H) break;
    let x1 = random(W);
    let x2 = x1 + random(30, 150);
    line(x1, y, x2, y);
  }
  noStroke();
}

function drawBoatAndFigure() {
  drawBoat();
  drawFigure();
  drawPole();
}

function drawBoat() {
  noStroke();
  fill(0, 0, 0, 70);
  ellipse(800, 1600, 620, 130);

  fill(28, 20, 15);
  stroke(10, 8, 6);
  strokeWeight(4);
  beginShape();
  vertex(540, 1510);
  bezierVertex(570, 1585, 660, 1610, 800, 1610);
  bezierVertex(940, 1610, 1030, 1585, 1060, 1510);
  bezierVertex(1030, 1485, 970, 1460, 800, 1460);
  bezierVertex(630, 1460, 570, 1485, 540, 1510);
  endShape(CLOSE);
  noStroke();

  fill(16, 12, 9, 130);
  beginShape();
  vertex(580, 1510);
  bezierVertex(600, 1480, 630, 1470, 800, 1470);
  bezierVertex(970, 1470, 1000, 1480, 1020, 1510);
  bezierVertex(1000, 1490, 970, 1475, 800, 1475);
  bezierVertex(630, 1475, 600, 1490, 580, 1510);
  endShape(CLOSE);

  stroke(50, 40, 35, 80);
  strokeWeight(2);
  line(580, 1490, 1020, 1490);
  noStroke();
}

function drawFigure() {
  fill(7, 6, 5);
  noStroke();
  ellipse(800, 1300, 110, 120);
  beginShape();
  vertex(740, 1340);
  bezierVertex(700, 1420, 710, 1500, 760, 1540);
  vertex(840, 1540);
  bezierVertex(890, 1500, 900, 1420, 860, 1340);
  bezierVertex(830, 1370, 770, 1370, 740, 1340);
  endShape(CLOSE);
  fill(14, 12, 10, 160);
  ellipse(800, 1300, 70, 80);
}

function drawPole() {
  stroke(30, 24, 20, 200);
  strokeWeight(10);
  line(830, 1400, 1000, 1600);
  noStroke();
}

function drawLantern(x, y) {
  noStroke();
  for (let r = 120; r > 20; r -= 10) {
    let a = map(r, 20, 120, 80, 4);
    fill(255, 180, 80, a);
    ellipse(x, y, r * 2, r * 2);
  }
  rectMode(CENTER);
  fill(30, 22, 16);
  rect(x, y, 36, 60, 6);
  fill(255, 200, 120, 220);
  rect(x, y - 5, 24, 38, 3);
  fill(20, 16, 12);
  rect(x, y - 36, 40, 12, 4);
  rect(x, y + 36, 40, 10, 4);
  rectMode(CORNER);
}

function drawLanternReflection(x) {
  noStroke();
  for (let i = 0; i < 45; i++) {
    let yy = 1560 + i * 10;
    if (yy > H) break;
    let w = random(10, 45);
    let a = map(i, 0, 45, 110, 0);
    fill(255, 180, 80, a);
    ellipse(x + random(-25, 25), yy, w, 9);
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    let x = (i * 173) % W;
    let y = 1200 + (i * 97) % 700;
    let w = 180 + (i % 7) * 60;
    let h = 45 + (i % 5) * 22;
    let a = 5 + (i % 6) * 2;
    fill(200, 210, 222, a);
    ellipse(x, y, w, h);
  }
}

function drawGrain() {
  randomSeed(1);
  noStroke();
  for (let i = 0; i < 12000; i++) {
    let x = random(W);
    let y = random(H);
    let a = random(6, 24);
    fill(255, 255, 255, a);
    rect(x, y, 1, 1);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  drawPainting();
}

function draw() {}

function drawPainting() {
  drawBackground();
  drawNiche();
  drawTable();
  drawFallenRose();
  drawSkull(650, 1350);
  drawCandle(1000, 1580, 330);
  drawSmoke(1000, 1238);
  drawScatteredPetals();
  drawVignette();
}

function drawBackground() {
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let c = lerpColor(color(20, 19, 24), color(5, 5, 8), t);
    fill(c);
    rect(0, y, width, 2);
  }

  for (let i = 0; i < 180; i++) {
    let x = noise(i * 0.1, 3) * width;
    let y = noise(i * 0.1, 4) * height * 0.6;
    let r = 80 + noise(i * 0.1, 5) * 180;
    fill(0, 0, 0, 8);
    ellipse(x, y, r);
  }

  drawRadialGlow(1150, 600, 900, color(90, 80, 60, 25), 25);
}

function drawRadialGlow(x, y, maxR, col, steps) {
  noStroke();
  for (let i = 0; i < steps; i++) {
    let r = maxR - i * (maxR / steps);
    let a = alpha(col) * pow(1 - r / maxR, 2);
    fill(red(col), green(col), blue(col), a);
    ellipse(x, y, r * 2);
  }
}

function drawNiche() {
  noStroke();
  fill(30, 25, 23);
  arc(650, 650, 640, 600, PI, TWO_PI);
  rect(330, 650, 640, 850);

  fill(20, 17, 15);
  arc(650, 650, 580, 540, PI, TWO_PI);
  rect(360, 650, 580, 840);

  noFill();
  stroke(80, 70, 60, 80);
  strokeWeight(5);
  arc(650, 650, 640, 600, PI, TWO_PI);
  line(330, 650, 330, 1500);
  line(970, 650, 970, 1500);
  noStroke();
}

function drawTable() {
  const yTop = 1580;
  noStroke();

  for (let y = yTop; y < height; y += 3) {
    let t = (y - yTop) / (height - yTop);
    let c = lerpColor(color(42, 29, 21), color(12, 8, 6), t);
    fill(c);
    rect(0, y, width, 4);
  }

  stroke(0, 0, 0, 90);
  strokeWeight(7);
  line(0, yTop, width, yTop);

  stroke(120, 90, 65, 70);
  strokeWeight(2);
  line(0, yTop + 3, width, yTop + 3);

  noFill();
  for (let i = 0; i < 70; i++) {
    let yy = yTop + 8 + i * 5 + noise(i * 0.1) * 10;
    stroke(0, 0, 0, 12 + noise(i * 0.2) * 35);
    strokeWeight(1.5);
    line(0, yy, width, yy + noise(i) * 8);
  }
  noStroke();
}

function drawSkull(cx, cy) {
  noStroke();
  fill(0, 0, 0, 80);
  ellipse(cx, 1570, 280, 55);

  noStroke();
  fill(215, 198, 168);
  ellipse(cx, cy - 40, 300, 300);

  fill(185, 165, 135);
  ellipse(cx - 130, cy - 30, 80, 190);
  ellipse(cx + 130, cy - 30, 80, 190);

  fill(225, 210, 180);
  ellipse(cx - 75, cy - 90, 100, 60);
  ellipse(cx + 75, cy - 90, 100, 60);

  fill(195, 178, 148);
  ellipse(cx - 120, cy + 10, 75, 55);
  ellipse(cx + 120, cy + 10, 75, 55);

  fill(208, 188, 158);
  beginShape();
  vertex(cx - 110, cy + 10);
  vertex(cx + 110, cy + 10);
  vertex(cx + 120, cy + 115);
  vertex(cx - 120, cy + 115);
  endShape(CLOSE);

  fill(185, 165, 135);
  ellipse(cx, cy + 150, 185, 115);

  fill(140, 120, 95, 80);
  ellipse(cx, cy + 190, 170, 60);

  fill(240, 225, 198, 90);
  ellipse(cx - 50, cy - 110, 150, 130);

  fill(140, 115, 90, 70);
  ellipse(cx - 145, cy - 20, 70, 150);
  ellipse(cx + 145, cy - 20, 70, 150);

  for (let i = 0; i < 60; i++) {
    let mx = cx - 120 + noise(i * 0.1, 7) * 240;
    let my = cy - 160 + noise(i * 0.1, 8) * 300;
    fill(180, 160, 130, 20);
    ellipse(mx, my, 8 + noise(i * 0.3) * 20, 4 + noise(i * 0.5) * 12);
  }

  drawEyeSocket(cx - 75, cy - 50, 85, 95);
  drawEyeSocket(cx + 75, cy - 50, 85, 95);

  noStroke();
  fill(65, 40, 32);
  beginShape();
  vertex(cx - 20, cy + 20);
  vertex(cx + 20, cy + 20);
  vertex(cx + 27, cy + 60);
  vertex(cx, cy + 82);
  vertex(cx - 27, cy + 60);
  endShape(CLOSE);

  fill(18, 13, 11);
  rect(cx - 95, cy + 105, 190, 28, 3);
  drawTeeth(cx, cy + 105, 150, 22, 8);
  drawTeeth(cx, cy + 140, 125, 20, 7);

  stroke(20, 15, 13);
  strokeWeight(4);
  line(cx - 95, cy + 127, cx + 95, cy + 127);

  stroke(90, 70, 55, 110);
  strokeWeight(2);
  line(cx - 95, cy - 150, cx - 65, cy - 100);
  line(cx + 75, cy - 170, cx + 95, cy - 110);
  noStroke();
}

function drawEyeSocket(x, y, w, h) {
  noStroke();
  fill(45, 28, 22);
  ellipse(x, y, w, h);
  fill(20, 12, 9);
  ellipse(x, y + 4, w * 0.72, h * 0.78);
  fill(8, 5, 4);
  ellipse(x, y + 7, w * 0.48, h * 0.55);

  noFill();
  stroke(225, 210, 182, 130);
  strokeWeight(4);
  arc(x, y - 5, w * 1.05, h * 0.85, PI * 1.12, PI * 1.88);
  noStroke();
}

function drawTeeth(cx, cy, w, h, n) {
  noStroke();
  fill(220, 205, 180);
  rect(cx - w / 2, cy - h / 2, w, h, 3);

  stroke(110, 90, 75, 120);
  strokeWeight(2);
  line(cx - w / 2, cy - h / 2, cx - w / 2, cy + h / 2);
  for (let i = 1; i < n; i++) {
    let x = cx - w / 2 + i * (w / n);
    line(x, cy - h / 2, x, cy + h / 2);
  }
  line(cx + w / 2, cy - h / 2, cx + w / 2, cy + h / 2);

  noStroke();
  fill(0, 0, 0, 25);
  rect(cx - w / 2, cy + h / 4, w, h / 2, 2);
}

function drawCandle(x, baseY, h) {
  noStroke();
  fill(0, 0, 0, 80);
  ellipse(x, baseY + 8, 160, 35);

  fill(150, 110, 80);
  stroke(90, 65, 45);
  strokeWeight(5);
  ellipse(x, baseY, 180, 35);

  fill(120, 85, 60);
  noStroke();
  arc(x, baseY - 12, 140, 30, PI, TWO_PI);

  let cw = 80;
  let topY = baseY - h;

  noStroke();
  fill(218, 203, 178);
  rect(x - cw / 2, topY, cw, h, 8);

  fill(245, 230, 205, 140);
  rect(x - cw / 2 + 8, topY + 5, cw * 0.2, h - 10, 4);

  fill(170, 150, 125, 100);
  rect(x + cw / 2 - 25, topY + 5, 18, h - 10, 4);

  fill(242, 227, 202);
  ellipse(x, topY, cw, 22);

  fill(225, 208, 183);
  rect(x - 35, topY + 70, 22, 90, 10);
  rect(x + 18, topY + 160, 20, 75, 9);

  fill(245, 230, 205, 100);
  rect(x - 30, topY + 80, 10, 40, 5);

  stroke(35, 30, 28);
  strokeWeight(6);
  line(x, topY, x + 3, topY - 14);

  noFill();
  stroke(40, 35, 30);
  strokeWeight(5);
  arc(x + 3, topY - 12, 20, 20, -0.2, PI - 0.3);
  noStroke();
}

function drawSmoke(x, y) {
  noStroke();
  let px = x;
  let py = y;

  for (let i = 0; i < 260; i++) {
    let t = i / 260;
    px += (noise(i * 0.018, 0) - 0.5) * 13;
    py -= 3.6 + t * 1.5;
    let rad = 5 + t * 55;
    let alpha = 34 * (1 - t);
    fill(205, 210, 220, alpha);
    ellipse(px, py, rad, rad * 1.4);
  }
}

function drawFallenRose() {
  noStroke();
  fill(0, 0, 0, 70);
  ellipse(430, 1590, 170, 45);

  stroke(70, 55, 40);
  strokeWeight(7);
  noFill();
  bezier(200, 1350, 320, 1450, 360, 1560, 430, 1560);

  stroke(65, 50, 35);
  strokeWeight(5);
  line(290, 1430, 300, 1415);
