function drawSkull() {
  noStroke();
  let bone = color(225, 210, 185);
  let boneShadow = color(180, 158, 135);
  let boneDark = color(130, 108, 90);
  let boneHighlight = color(250, 240, 225);

  // cranium
  fill(bone);
  beginShape();
  vertex(610, 980);
  bezierVertex(570, 800, 630, 620, 800, 610);
  bezierVertex(970, 620, 1030, 800, 990, 980);
  bezierVertex(960, 1090, 910, 1130, 800, 1130);
  bezierVertex(690, 1130, 640, 1090, 610, 980);
  endShape(CLOSE);

  // side shading
  fill(boneShadow);
  ellipse(650, 900, 100, 160);
  ellipse(950, 900, 100, 160);

  // temple hollows
  fill(boneDark);
  ellipse(660, 780, 60, 100);
  ellipse(940, 780, 60, 100);

  // cheekbone highlights
  fill(boneHighlight);
  ellipse(700, 950, 90, 60);
  ellipse(900, 950, 90, 60);

  // eye sockets
  fill(25, 18, 14);
  beginShape();
  vertex(700, 840);
  bezierVertex(680, 790, 700, 750, 740, 760);
  bezierVertex(780, 770, 810, 800, 820, 830);
  bezierVertex(830, 860, 800, 880, 760, 890);
  bezierVertex(720, 895, 690, 880, 700, 840);
  endShape(CLOSE);
  beginShape();
  vertex(900, 840);
  bezierVertex(920, 790, 900, 750, 860, 760);
  bezierVertex(820, 770, 790, 800, 780, 830);
  bezierVertex(770, 860, 800, 880, 840, 890);
  bezierVertex(880, 895, 910, 880, 900, 840);
  endShape(CLOSE);

  // nasal cavity
  fill(20, 14, 12);
  beginShape();
  vertex(800, 900);
  bezierVertex(775, 910, 770, 960, 800, 990);
  bezierVertex(830, 960, 825, 910, 800, 900);
  endShape(CLOSE);

  // upper jaw
  fill(bone);
  rect(700, 1080, 200, 60, 10);
  // upper teeth
  fill(240, 230, 215);
  for (let x = 710; x < 890; x += 18) {
    rect(x, 1090, 12, 45, 3);
  }
  stroke(boneDark);
  strokeWeight(2);
  for (let x = 710; x < 890; x += 18) {
    line(x, 1090, x, 1135);
  }
  noStroke();

  // lower jaw
  fill(bone);
  beginShape();
  vertex(680, 1150);
  bezierVertex(690, 1300, 720, 1450, 800, 1450);
  bezierVertex(880, 1450, 910, 1300, 920, 1150);
  bezierVertex(900, 1210, 860, 1260, 800, 1260);
  bezierVertex(740, 1260, 700, 1210, 680, 1150);
  endShape(CLOSE);
  // lower teeth
  fill(240, 230, 215);
  for (let x = 720; x < 880; x += 18) {
    rect(x, 1220, 12, 40, 3);
  }
  stroke(boneDark);
  strokeWeight(2);
  for (let x = 720; x < 880; x += 18) {
    line(x, 1220, x, 1260);
  }
  noStroke();

  // forehead highlights
  fill(boneHighlight);
  ellipse(800, 700, 140, 90);
  ellipse(760, 750, 80, 60);
  ellipse(840, 750, 80, 60);

  // cracks
  stroke(100, 80, 65, 150);
  strokeWeight(1.5);
  noFill();
  beginShape();
  vertex(700, 700);
  bezierVertex(720, 720, 710, 760, 730, 800);
  endShape();
  beginShape();
  vertex(880, 680);
  bezierVertex(870, 710, 890, 730, 880, 760);
  endShape();
  noStroke();
}

function drawRose() {
  noStroke();
  // shadow
  fill(0, 0, 0, 60);
  ellipse(370, 1490, 180, 70);
  // stem
  stroke(50, 65, 40);
  strokeWeight(9);
  noFill();
  beginShape();
  vertex(300, 1500);
  bezierVertex(340, 1400, 400, 1350, 460, 1250);
  bezierVertex(500, 1180, 480, 1130, 450, 1100);
  endShape();
  // thorns
  stroke(50, 65, 40);
  strokeWeight(5);
  line(380, 1380, 360, 1350);
  line(420, 1300, 440, 1270);
  // leaves
  fill(55, 70, 45);
  noStroke();
  ellipse(390, 1390, 70, 30);
  ellipse(430, 1310, 70, 30);
  // drooping rose head
  push();
  translate(450, 1120);
  rotate(0.6);
  for (let i = 0; i < 7; i++) {
    rotate(TWO_PI / 7);
    fill(100 + i * 8, 20, 25, 220);
    ellipse(35, 0, 80, 45);
  }
  pop();
  // inner petals
  fill(130, 25, 30);
  ellipse(450, 1120, 90, 90);
  fill(170, 35, 40);
  ellipse(450, 1115, 60, 60);
  fill(200, 45, 50);
  ellipse(450, 1110, 35, 35);
  fill(90, 20, 25);
  ellipse(450, 1110, 18, 18);
  // falling petals
  fill(110, 25, 30, 200);
  ellipse(410, 1240, 35, 22);
  ellipse(340, 1320, 30, 20);
  ellipse(380, 1290, 28, 18);
  ellipse(320, 1400, 25, 16);
}

function drawCandle() {
