function drawSmoke() {
  noFill();
  for (let j = 0; j < 5; j++) {
    stroke(220, 220, 220, 50 - j * 8);
    strokeWeight(3 - j * 0.4);
    beginShape();
    for (let i = 0; i < 30; i++) {
      let t = i / 29;
      let n = noise(t * 2 + j * 0.5, j);
      let x = 1150 + (n - 0.5) * 80 + t * 50;
      let y = 1200 - t * 320;
      vertex(x, y);
    }
    endShape();
  }
}

function drawVignette() {
