function drawSmokeLayer() {
  let s = createGraphics(width, height);
  s.noStroke();
  drawSmokePlume(s);
  drawSkull(s);
  drawDisintegratingWisps(s);
  s.filter(BLUR, 6);
  image(s, 0, 0);
}

function drawSmokePlume(s) {
  let cx = 800;
  let startY = 1160;

  for (let k = 0; k < 10; k++) {
    s.stroke(185, 175, 165, random(10, 30));
    s.strokeWeight(random(12, 40));
    s.noFill();
    s.beginShape();
    for (let i = 0; i <= 30; i++) {
      let t = i / 30;
      let y = startY - t * 360;
      let x = cx + (noise(t * 3.0 + k * 0.7) - 0.5) * 150 * t + sin(t * TWO_PI * 1.6 + k) * 55 * t;
      s.curveVertex(x, y);
    }
    s.endShape();
  }

  for (let i = 0; i < 200; i++) {
    let t = random(0, 1);
    let y = startY - t * 370;
    let x = cx + sin(t * TWO_PI * 1.4) * 85 * t + random(-35, 35);
    let r = random(12, 50) * (1 - t * 0.4);
    s.fill(185, 175, 165, random(2, 10));
    s.ellipse(x, y, r, r);
  }
}

function drawSkull(s) {
  let cx = 800;
  let cy = 800;
  let w = 500;
  let h = 620;

  s.noStroke();
  for (let j = 0; j < 3; j++) {
    s.fill(205, 192, 174, 18);
    s.ellipse(cx, cy - 0.16 * h, 0.78 * w, 0.74 * h);
    s.ellipse(cx, cy + 0.04 * h, 0.64 * w, 0.50 * h);
    s.ellipse(cx, cy + 0.22 * h, 0.46 * w, 0.42 * h);
  }

  for (let i = 0; i < 10000; i++) {
    let x = cx + random(-0.55 * w, 0.55 * w);
    let y = cy + random(-0.6 * h, 0.6 * h);
    if (isInsideSkull(x, y, cx, cy, w, h)) {
      let a = random(2, 16);
      let r = random(1, 7);
      s.fill(218, 208, 192, a);
      s.ellipse(x, y, r, r);
    }
  }

  s.fill(235, 225, 205, 14);
  s.ellipse(cx - 0.1 * w, cy - 0.28 * h, 0.45 * w, 0.35 * h);
}

function isInsideSkull(x, y, cx, cy, w, h) {
  let dx = (x - cx) / w;
  let dy = (y - cy) / h;

  let c1 = (dx * dx) / (0.39 * 0.39) + ((dy + 0.16) * (dy + 0.16)) / (0.46 * 0.46) <= 1;
  let c2 = (dx * dx) / (0.32 * 0.32) + ((dy - 0.04) * (dy - 0.04)) / (0.26 * 0.26) <= 1;
  let c3 = (dx * dx) / (0.24 * 0.24) + ((dy - 0.26) * (dy - 0.26)) / (0.24 * 0.24) <= 1;

  let eyeL = ((dx + 0.19) * (dx + 0.19)) / (0.10 * 0.10) + ((dy + 0.03) * (dy + 0.03)) / (0.12 * 0.12) <= 1;
  let eyeR = ((dx - 0.19) * (dx - 0.19)) / (0.10 * 0.10) + ((dy + 0.03) * (dy + 0.03)) / (0.12 * 0.12) <= 1;
  let nose = (dx * dx) / (0.055 * 0.055) + ((dy - 0.1) * (dy - 0.1)) / (0.095 * 0.095) <= 1;

  return (c1 || c2 || c3) && !eyeL && !eyeR && !nose;
}

