function softBlob(x, y, w, h, r, g, b, a, n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let t = n === 1 ? 1 : i / (n - 1);
    let s = 1.35 - 0.35 * t;
    fill(r, g, b, (a / n) * (0.5 + t));
    ellipse(x, y, max(w * s, 1), max(h * s, 1));
  }
}

function softRRect(x, y, w, h, rad, r, g, b, a, n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let t = n === 1 ? 1 : i / (n - 1);
    let pad = (1 - t) * 80;
    fill(r, g, b, (a / n) * (0.5 + t));
    rect(x - pad, y - pad, w + pad * 2, h + pad * 2, rad + pad * 0.6);
  }
}

