function mix(a, b, t) {
  return [
    a[0] + (b[0] - a[0]) * t,
    a[1] + (b[1] - a[1]) * t,
    a[2] + (b[2] - a[2]) * t
  ];
}

function halfWidth(y) {
  if (y < 608) return 0;
  if (y < 772) {
    let t = (y - 690) / 82;
    let v = 1 - t * t;
    return v > 0 ? 66 * sqrt(v) : 0;
  }
  if (y < 830) return lerp(26, 34, (y - 772) / 58);
  if (y < 930) {
    let t = (y - 830) / 100;
    t = t * t * (3 - 2 * t);
    return lerp(34, 190, t);
  }
  if (y < 1350) {
    let t = (y - 930) / 420;
    return lerp(190, 148, t) + 6 * sin(t * 3.1);
  }
  let t = (y - 1350) / 440;
  t = t * t * (3 - 2 * t);
  return lerp(148, 238, t);
}

function cohesion(y, u) {
  let base;
  if (y > 1180) base = 1;
  else {
    let t = (1180 - y) / 574;
    base = 1 - 0.85 * pow(t, 1.25);
  }
  if (u > 0.3) base *= 0.8;
  return constrain(base, 0.06, 1);
}

function paintBackground() {
