  noStroke();
  for (let y = 0; y < H; y++) {
    let t = y / H, c;
    if (t < 0.42) c = mix(top, mid, t / 0.42);
    else c = mix(mid, bot, (t - 0.42) / 0.58);
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 1.5);
  }
  for (let i = 0; i < 260; i++) {
    let x = random(W), y = random(H), r = random(60, 320);
    let dark = random() < 0.5;
    fill(dark ? 2 : 26, dark ? 3 : 30, dark ? 5 : 42, random(2, 5));
    ellipse(x, y, r * 1.6, r);
