function figure() {
  const CX = 800;
  for (let i = 0; i < 24000; i++) {
    let y = random(606, 1795);
    let w = halfWidth(y) * (0.93 + 0.14 * noise(y * 0.02));
    if (w < 2) continue;
    let u = random(-1, 1);
    let x = u * w;
    if (random() > cohesion(y, u)) continue;
    let px = CX + x;
    if (y < 1400 && noise(px * 0.006, y * 0.006) > 0.88) continue;
    let light = 0.5 + 0.32 * (-u) + 0.22 * ((1795 - y) / 1190);
    light = constrain(light + (noise(px * 0.008, y * 0.008) - 0.5) * 0.3, 0, 1);
    let c = mix([120, 128, 146], [231, 225, 210], light);
    let a = random(28, 120) * (0.55 + 0.45 * light);
    stroke(c[0], c[1], c[2], a);
    strokeWeight(random(0.7, 2.3));
    let ang = -HALF_PI + (noise(px * 0.004, y * 0.004) - 0.5) * 1.0;
    let L = random(5, 17);
    line(px - cos(ang) * L * 0.5, y - sin(ang) * L * 0.5,
         px + cos(ang) * L * 0.5, y + sin(ang) * L * 0.5);
  }
}

function risingAsh() {
  for (let k = 0; k < 620; k++) {
    let y0 = 1210 - pow(random(), 0.85) * 600;
    let w = halfWidth(y0);
    let x = 800 + random(-1, 1) * max(w, 20) * 1.05;
    let y = y0;
    let steps = int(random(28, 110));
    let s0 = random(30, 70);
    let sz = random(0.8, 2.6);
    let warm = random() < 0.05;
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let ang = -HALF_PI + (noise(x * 0.0016, y * 0.0016) - 0.5) * 1.8 + 0.24;
      x += cos(ang) * random(3.2, 6.5);
      y += sin(ang) * random(3.2, 6.5);
      let a = s0 * (1 - t) * (1 - t) + 2;
      if (warm && t < 0.4) stroke(224, 158, 102, a);
      else stroke(205, 208, 214, a);
      strokeWeight(sz * (1 - t * 0.7));
      point(x, y);
    }
  }
  for (let k = 0; k < 150; k++) {
    let x = 800 + random(-140, 260), y = random(320, 860);
    let steps = int(random(50, 120));
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      let ang = -HALF_PI + (noise(x * 0.0013 + 9.7, y * 0.0013) - 0.5) * 1.5 + 0.2;
      x += cos(ang) * 4.2;
      y += sin(ang) * 4.2;
      stroke(185, 192, 204, (1 - t) * 12);
      strokeWeight(random(1, 2.4));
      point(x, y);
    }
  }
  noStroke();
  for (let k = 0; k < 150; k++) {
    let x = 800 + random(-60, 420), y = random(180, 1150);
    let r = random(3, 9);
    fill(190, 196, 206, random(5, 14));
    ellipse(x, y, r * 2.4, r * 1.6);
  }
}

function fallingFlakes() {
