let RIBS = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  paintScene();
  noLoop();
}

function paintScene() {
  drawBackground();
  drawRays();
  drawDeepFade();
  drawMarineSnow(0.62);
  drawGhostWhale();
  drawDescentDust();
  drawSedimentBack();
  drawContactShadow();
  drawSkeleton();
  drawSkull();
  drawSedimentFront();
  drawLife();
  drawBubbles();
  drawFishSchool();
  drawMarineSnow(0.38);
  drawGrain();
  drawVignette();
}

function drawBackground() {
  noStroke();
  let top = color(5, 9, 18), mid = color(10, 22, 38);
  let low = color(7, 15, 26), deep = color(2, 4, 9);
  for (let y = 0; y < 2000; y++) {
    let t = y / 2000, c;
    if (t < 0.30) c = lerpColor(top, mid, t / 0.30);
    else if (t < 0.62) c = lerpColor(mid, low, (t - 0.30) / 0.32);
    else c = lerpColor(low, deep, (t - 0.62) / 0.38);
    fill(c);
    rect(0, y, 1600, 1);
  }
  for (let i = 0; i < 26; i++) {
    let x = random(1600), y = random(1400), r = random(160, 420);
    let cc = random() < 0.5 ? [16, 34, 52] : [6, 14, 26];
    softBlob(x, y, r, cc, random(6, 14));
  }
}

function softBlob(x, y, r, c, a) {
  noStroke();
  for (let k = 1; k > 0.15; k -= 0.2) {
    fill(c[0], c[1], c[2], a * k);
    ellipse(x, y, r * 2 * k, r * 1.7 * k);
  }
}

function drawRays() {
  push();
  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  for (let i = 0; i < 8; i++) {
    let x0 = 140 + i * 190 + random(-60, 60);
    let wTop = random(26, 70);
    let drift = 260 + random(-80, 140);
    let len = 1150 + random(-200, 250);
    let a = random(3.5, 8);
    let slices = 30;
    for (let s = 0; s < slices; s++) {
      let t0 = s / slices, t1 = (s + 1) / slices;
      let y0 = t0 * len, y1 = t1 * len;
      let xa = x0 + drift * t0, xb = xa + wTop * (1 + t0 * 2.4);
      let xc = x0 + drift * t1, xd = xc + wTop * (1 + t1 * 2.4);
      fill(130, 190, 205, a * (1 - t0) * (0.7 + 0.6 * noise(i * 3 + s)));
      beginShape();
      vertex(xa, y0); vertex(xb, y0); vertex(xd, y1); vertex(xc, y1);
      endShape(CLOSE);
    }
  }
  pop();
}

function drawDeepFade() {
  noStroke();
  for (let y = 0; y < 2000; y += 2) {
    let t = y / 2000;
    let a = t > 0.35 ? map(t, 0.35, 1, 0, 120) : 0;
    fill(2, 4, 9, a);
    rect(0, y, 1600, 2);
  }
}

function drawMarineSnow(mul) {
  noStroke();
  let n = floor(750 * mul);
  for (let i = 0; i < n; i++) {
    let x = random(1600), y = random(2000);
    let d = noise(x * 0.0015, y * 0.0015);
    let s = 0.6 + d * 2.6 + (random() < 0.04 ? random(2, 3.5) : 0);
    fill(170, 196, 208, (8 + 26 * d) * mul);
    ellipse(x, y, s, s * random(0.7, 1.2));
  }
}

function drawGhostWhale() {
  push();
  translate(920, 470);
  rotate(-0.21);
  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  let L = 1020, HW = 150;
  fill(60, 150, 160, 9);
  ellipse(0, 0, 1000, 430);
  for (let i = 0; i < 5; i++) {
    let t = 0.12 + i * 0.18;
    let x = -L / 2 + t * L;
    let w = HW * sin(PI * (0.16 + 0.84 * t));
    fill(70, 150, 160, 7);
    ellipse(x, 0, w * 3.6, w * 2.2);
  }
  for (let i = 0; i < 1500; i++) {
    let t = pow(random(), 0.9);
    let w = HW * sin(PI * (0.16 + 0.84 * t));
    if (w < 6) w = 6;
    let s = random(-1, 1);
    s = Math.sign(s) * pow(abs(s), 0.75);
    let x = -L / 2 + t * L + random(-6, 6);
    let y = s * w;
    let sz = random(0.8, 3.6);
    let a = random(5, 30) * (0.6 + 0.7 * sin(PI * t));
    let cc = random();
    if (cc < 0.55) fill(168, 214, 224, a);
    else if (cc < 0.85) fill(120, 232, 206, a);
    else fill(235, 248, 250, a);
    circle(x, y, sz);
  }
  for (let side of [-1, 1]) {
    for (let i = 0; i < 210; i++) {
      let u = pow(random(), 0.8);
      let ang = side * (0.62 + 0.35 * u) + random(-0.10, 0.10);
      let len = 200 * u;
      let x = L / 2 - cos(ang) * len * 0.9;
      let y = sin(ang) * len * 0.8;
      fill(140, 220, 218, random(4, 22) * (1 - u * 0.5));
      circle(x + random(-5, 5), y + random(-5, 5), random(0.8, 3));
    }
  }
  for (let i = 0; i < 120; i++) {
    let u = random();
    let x = -L / 2 + 0.34 * L - u * 130;
    let y = HW * 0.72 * sin(PI * (0.16 + 0.84 * 0.34)) + u * 120 + random(-8, 8);
    fill(150, 220, 220, random(4, 16));
    circle(x, y, random(0.8, 2.6));
  }
  for (let i = 0; i < 90; i++) {
    let t = random(0.06, 0.94);
    fill(220, 246, 250, random(8, 26));
    circle(-L / 2 + t * L + random(-4, 4), random(-5, 5), random(1, 2.6));
  }
  fill(210, 250, 245, 60);
  circle(-L / 2 + L * 0.10, HW * 0.16, 4);
  pop();
}

function drawDescentDust() {
  push();
  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  for (let i = 0; i < 300; i++) {
    let t = pow(random(), 1.2);
    let bx = lerp(980, 880, t) + (noise(i * 0.35) - 0.5) * (40 + 260 * t);
    let by = lerp(600, 1010, t) + random(-14, 14);
    let a = 22 * (1 - t) + 3;
    let sz = 0.8 + random(2.2) * (1 - t * 0.5);
    if (random() < 0.3) fill(120, 235, 205, a);
    else fill(190, 225, 232, a);
    circle(bx, by, sz);
  }
  pop();
}

function sedimentY(x) {
  return 1526 + 26 * noise(x * 0.0021 + 7.3) + 9 * sin(x * 0.0038 + 1.2);
}

function drawSedimentBack() {
  noStroke();
  fill(7, 9, 13);
  beginShape();
  vertex(0, 2000);
  for (let x = 0; x <= 1600; x += 16) vertex(x, sedimentY(x));
  vertex(1600, 2000);
  endShape(CLOSE);
  noFill();
  stroke(58, 82, 86, 34);
  strokeWeight(2);
  beginShape();
  for (let x = 0; x <= 1600; x += 16) vertex(x, sedimentY(x));
  endShape();
}

function drawContactShadow() {
  noStroke();
  for (let k = 5; k > 0; k--) {
    fill(2, 3, 6, 16);
    ellipse(880, 1568, 1250 * k / 5, 150 * k / 5);
  }
  drawingContext.globalCompositeOperation = 'lighter';
  for (let k = 4; k > 0; k--) {
    fill(30, 110, 100, 5);
    ellipse(880, 1585, 1100 * k / 4, 150 * k / 4);
  }
  drawingContext.globalCompositeOperation = 'source-over';
}

function spinePoint(t) {
  let x = bezierPoint(452, 762, 1085, 1432, t);
  let y = bezierPoint(1502, 1452, 1460, 1522, t);
  return [x, y];
}

function drawCarcassMound() {
  noStroke();
  fill(10, 14, 20, 220);
  beginShape();
  vertex(470, sedimentY(470) + 28);
  for (let x = 470; x <= 1400; x += 18) {
    let t = constrain((x - 452) / 980, 0, 1);
    let sy = bezierPoint(1502, 1452, 1460, 1522, t);
    vertex(x, sy - 8 + noise(x * 0.02) * 14);
  }
  vertex(1400, sedimentY(1400) + 28);
  endShape(CLOSE);
  push();
  drawingContext.globalCompositeOperation = 'lighter';
  noFill();
  stroke(80, 180, 165, 16);
  strokeWeight(2);
  beginShape();
  for (let x = 480; x <= 1390; x += 22) {
    let t = constrain((x - 452) / 980, 0, 1);
    let sy = bezierPoint(1502, 1452, 1460, 1522, t);
    vertex(x, sy - 6 + noise(x * 0.02) * 14);
  }
  endShape();
  pop();
}

function drawSkeleton() {
  drawCarcassMound();
  for (let i = 0; i < 14; i++) {
    let t = 0.10 + i * (0.70 / 13);
    let p = spinePoint(t);
    let tt = i / 13;
    let h = (150 + 400 * pow(sin(PI * tt), 0.9)) * 0.8;
    let pts = ribPoints(p[0] + 24, p[1] - 8, h, -0.18, i + 40, 1);
    strokeCurve(pts, 9, 4, [74, 86, 92], 0, 0, 120);
  }
  for (let i = 0; i <= 30; i++) {
    let t = i / 30;
    let p = spinePoint(t);
    let x = p[0], y = p[1];
    let w = lerp(31, 9, pow(t, 1.15));
    noStroke();
    fill(198, 190, 170);
    ellipse(x, y, w, w * 0.84);
    fill(112, 116, 110, 130);
    ellipse(x + w * 0.14, y + w * 0.13, w * 0.72, w * 0.55);
    stroke(208, 200, 180);
    strokeWeight(w * 0.26);
    line(x - 2, y - w * 0.30, x - 3 - w * 0.12, y - w * 0.30 - w * 0.52);
  }
  drawTail();
  let brokenMap = { 3: 0.55, 8: 0.66 };
  for (let i = 0; i < 14; i++) {
    let t = 0.10 + i * (0.70 / 13);
    let p = spinePoint(t);
    let tt = i / 13;
    let h = 170 + 430 * pow(sin(PI * tt), 0.9) + (noise(i * 7.7) - 0.5) * 80;
    let trunc = brokenMap[i] !== undefined ? brokenMap[i] : 1;
    let lean = -0.30 + tt * 0.16;
    let pts = ribPoints(p[0], p[1], h, lean, i, trunc);
    let w0 = 14 + 7 * sin(PI * tt);
    let w1 = w0 * 0.44;
    let bvar = (noise(i * 13.3) - 0.5) * 16;
    strokeCurve(pts, w0 + 4, w1 + 3, [22, 28, 32], 4, 5, 190);
    strokeCurve(pts, w0, w1, [213 + bvar, 205 + bvar, 185 + bvar * 0.6], 0, 0, 255);
    strokeCurve(pts, w0 * 0.38, w0 * 0.15, [244, 239, 222], -2, -2, 200);
    if (trunc < 1) {
      let e = pts[pts.length - 1];
      noStroke();
      fill(30, 34, 36, 200);
      circle(e[0], e[1], w1 * 1.6);
      let gy = sedimentY(e[0]) + 30;
      stroke(206, 198, 178, 220);
      strokeWeight(4);
      line(e[0] + 26, gy, e[0] + 60, gy + 6);
      strokeWeight(3);
      line(e[0] + 8, gy + 14, e[0] + 30, gy + 20);
    }
    RIBS.push({ pts: pts, base: p });
  }
}

function drawTail() {
  let a = spinePoint(0.985), b = spinePoint(1);
  let dx = b[0] - a[0], dy = b[1] - a[1];
  let m = sqrt(dx * dx + dy * dy);
  dx /= m; dy /= m;
  let x = b[0], y = b[1];
  for (let i = 0; i < 7; i++) {
    let w = 8.5 - i * 1.0;
    x += dx * (16 + i * 3);
    y += dy * (16 + i * 3) + sin(i * 1.7) * 1.5;
    noStroke();
    fill(190, 182, 162, 235 - i * 14);
    ellipse(x, y, w, w * 0.8);
  }
  let baseAng = atan2(dy, dx);
  for (let k = -2; k <= 2; k++) {
    if (k === 0) continue;
    let ang = baseAng + k * 0.42;
    let len = 58 - abs(k) * 12;
    let ex = x + cos(ang) * len, ey = y + sin(ang) * len;
    stroke(196, 188, 168, 150);
    strokeWeight(2.4);
    line(x, y, ex, ey);
    noStroke();
    fill(214, 206, 186, 150);
    circle(ex, ey, 3);
  }
}

function ribPoints(bx, by, h, lean, idx, trunc) {
  let pts = [];
  let ang = -PI / 2 + lean;
  let steps = max(6, floor((h / 13) * trunc));
  let curl = 0.010 + 0.013 * noise(idx * 3.1 + 5);
  let x = bx, y = by;
  for (let s = 0; s <= steps; s++) {
    pts.push([x, y]);
    let wob = (noise(idx * 9.7 + s * 0.28) - 0.5) * 0.045;
    ang -= curl * (0.45 + s / steps) + wob;
    x += cos(ang) * 13;
    y += sin(ang) * 13;
  }
  return pts;
}

function strokeCurve(pts, w0, w1, col, ox, oy, alpha) {
  noFill();
  stroke(col[0], col[1], col[2], alpha);
  for (let i = 0; i < pts.length - 1; i++) {
    let tt = pts.length > 2 ? i / (pts.length - 2) : 0;
    strokeWeight(lerp(w0, w1, tt));
    line(pts[i][0] + ox, pts[i][1] + oy, pts[i + 1][0] + ox, pts[i + 1][1] + oy);
  }
}

function drawSkull() {
  noStroke();
  fill(2, 3, 6, 60);
  ellipse(280, 1560, 430, 60);
  fill(211, 203, 183);
  stroke(40, 44, 46, 120);
  strokeWeight(2);
  beginShape();
  vertex(468, 1468);
  bezierVertex(486, 1430, 472, 1400, 438, 1392);
  bezierVertex(340, 1378, 190, 1432, 112, 1487);
  bezierVertex(100, 1493, 101, 1500, 114, 1503);
  bezierVertex(210, 1516, 360, 1502, 452, 1486);
  bezierVertex(466, 1482, 470, 1476, 468, 1468);
  endShape(CLOSE);
  noFill();
  stroke(70, 76, 78, 120);
  strokeWeight(7);
  beginShape();
  vertex(130, 1500);
  bezierVertex(230, 1514, 360, 1500, 448, 1484);
  endShape();
  stroke(243, 238, 222, 170);
  strokeWeight(4);
  beginShape();
  vertex(120, 1488);
  bezierVertex(220, 1438, 340, 1386, 436, 1396);
  endShape();
  noStroke();
  fill(32, 36, 38, 235);
  ellipse(404, 1444, 30, 22);
  fill(18, 22, 24);
  ellipse(404, 1446, 18, 13);
  noFill();
