function glow(x, y, r, c, a) {
  push();
  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  fill(c[0], c[1], c[2], a * 0.22);
  circle(x, y, r * 2);
  fill(c[0], c[1], c[2], a * 0.5);
  circle(x, y, r * 1.1);
  fill(min(255, c[0] + 70), min(255, c[1] + 70), min(255, c[2] + 70), a);
  circle(x, y, r * 0.45);
  pop();
}

function anemone(x, y, r, c) {
  glow(x, y, r * 3.4, c, 26);
  glow(x, y, r * 1.3, [225, 255, 248], 34);
  let n = floor(r * 0.7) + 8;
  for (let i = 0; i < n; i++) {
    let a = -PI / 2 + random(-1.05, 1.05);
    let len = r * random(1.1, 2.2);
    let sw = random(-0.7, 0.7);
    noFill();
    stroke(c[0], c[1], c[2], 150);
    strokeWeight(1.5);
    let px = x, py = y;
    beginShape();
    vertex(px, py);
    for (let s = 1; s <= 6; s++) {
      let tt = s / 6;
      let aa = a + sw * tt;
      px = x + cos(aa) * len * tt;
      py = y + sin(aa) * len * tt;
      vertex(px, py);
    }
    endShape();
    noStroke();
    fill(240, 255, 250, 235);
    circle(px, py, 2.6);
  }
  noStroke();
  fill(c[0], c[1], c[2], 180);
  ellipse(x, y + 2, r * 1.15, r * 0.55);
}

function osedax(rib) {
  let pts = rib.pts;
  let n = floor(random(3, 6));
  for (let k = 0; k < n; k++) {
    let idx = floor(pts.length * random(0.3, 0.68));
    let x = pts[idx][0], y = pts[idx][1];
    glow(x, y, 9, [255, 130, 60], 22);
    let m = floor(random(2, 5));
    for (let j = 0; j < m; j++) {
      let ang = random(-PI, 0);
      let seg = random(4, 7);
      noFill();
      stroke(255, random(105, 165), random(45, 90), 215);
      strokeWeight(1.7);
      let px = x, py = y;
      beginShape();
      vertex(px, py);
      for (let s = 0; s < 5; s++) {
        ang += random(-0.5, 0.5);
        px += cos(ang) * seg;
        py += sin(ang) * seg;
        vertex(px, py);
      }
      endShape();
      noStroke();
      fill(255, 224, 185, 225);
      circle(px, py, 2.2);
    }
  }
}

function brittle(x, y, r) {
  glow(x, y, r * 1.2, [150, 150, 200], 12);
  for (let a = 0; a < 5; a++) {
    let ang = a * TWO_PI / 5 + random(-0.15, 0.15) - PI / 2;
    let curlDir = (a % 2 === 0) ? 0.13 : -0.13;
    let px = x, py = y;
    let steps = 13;
    for (let s = 0; s < steps; s++) {
      let t = s / steps;
      ang += curlDir * t;
      let segLen = r * 0.16 * (1 - t * 0.55);
      let nx = px + cos(ang) * segLen;
      let ny = py + sin(ang) * segLen;
      stroke(184, 180, 206, 205);
      strokeWeight(lerp(4.6, 1, t));
      line(px, py, nx, ny);
      px = nx; py = ny;
    }
  }
  noStroke();
  fill(208, 204, 226);
  circle(x, y, r * 0.36);
  fill(120, 118, 150, 160);
  circle(x + 1, y + 1, r * 0.18);
}

function drawLife() {
  drawingContext.globalCompositeOperation = 'lighter';
  for (let i = 0; i < 7; i++) {
    let x = random(320, 1420);
    let y = random(1580, 1700);
    glow(x, y, random(50, 120), [70, 150, 135], 16);
  }
  drawingContext.globalCompositeOperation = 'source-over';
  let anemIdx = [1, 4, 6, 9, 12];
  for (let j = 0; j < anemIdx.length; j++) {
    let rb = RIBS[anemIdx[j]];
    let ax = rb.base[0] + random(-14, 14);
    let ay = sedimentY(ax) + 34 + random(-4, 8);
    anemone(ax, ay, random(15, 27), [96, 240, 208]);
  }
  anemone(150, 1556, 20, [96, 240, 208]);
  anemone(1120, sedimentY(1120) + 60, 16, [255, 190, 120]);
  let wormIdx = [2, 5, 9, 11];
  for (let j = 0; j < wormIdx.length; j++) osedax(RIBS[wormIdx[j]]);
  brittle(560, 1720, 34);
  brittle(1210, 1672, 27);
  brittle(1400, 1790, 40);
  for (let c = 0; c < 4; c++) {
    let rb = RIBS[[0, 5, 7, 13][c]];
    let p = rb.pts[floor(rb.pts.length * 0.25)];
    for (let i = 0; i < 26; i++) {
      noStroke();
      fill(205, 224, 218, random(60, 150));
      circle(p[0] + random(-26, 26), p[1] + random(-20, 20), random(1.2, 2.6));
    }
  }
}

