function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  strokeCap(ROUND);

  const SKY = [[0, '#05060a'], [0.45, '#0c0d15'], [0.8, '#1b1116'], [1, '#2a1315']];
  const GND = [[0, '#221018'], [0.12, '#150d12'], [0.45, '#0b080c'], [1, '#050407']];

  function ramp(stops, t) {
    t = constrain(t, 0, 1);
    for (let i = 0; i < stops.length - 1; i++) {
      if (t <= stops[i + 1][0]) {
        let u = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        return lerpColor(color(stops[i][1]), color(stops[i + 1][1]), u);
      }
    }
    return color(stops[stops.length - 1][1]);
  }

  function horizon(x) { return 1250 + 22 * noise(x * 0.002 + 9.7) - 11; }

  // --- sky, painted in short strokes ---
  for (let y = -10; y < 1280; y += 8) {
    for (let x = -10; x < 1610; x += 16) {
      let base = ramp(SKY, y / 1250);
      let j = noise(x * 0.004, y * 0.006) - 0.5;
      let c = lerpColor(base, j > 0 ? color('#ffffff') : color('#000000'), abs(j) * 0.14);
      let ang = (noise(x * 0.01 + 40, y * 0.01) - 0.5) * 0.8;
      let L = 16 + random(20);
      stroke(c); strokeWeight(6 + random(6));
      line(x, y, x + cos(ang) * L, y + sin(ang) * L * 0.4);
    }
  }

  // --- ghost moon, dissolving ---
  let mx = 396, my = 330, mr = 118;
  noFill();
  for (let i = 0; i < 760; i++) {
    let rr = mr * (0.3 + 0.75 * pow(random(), 0.6)) * (random() < 0.15 ? 1.5 : 1);
    let a0 = random(TWO_PI);
    let da = 0.25 + random(1.5);
    let py = my + sin(a0) * rr * 0.96;
    if (py > my + mr * 0.25 && random() < 0.55) continue;
    let c = lerpColor(color('#b7ab94'), color('#57504a'), random());
    c.setAlpha(3 + random(6));
    stroke(c); strokeWeight(1 + random(2.2));
    beginShape();
    let st = 5 + floor(random(5));
    for (let s = 0; s <= st; s++) {
      let a = a0 + da * s / st;
      vertex(mx + cos(a) * rr, my + sin(a) * rr * 0.96);
    }
    endShape();
  }

  // --- ground ---
  for (let y = 1246; y < 2010; y += 8) {
    for (let x = -10; x < 1610; x += 14) {
      let t = (y - 1250) / 750;
      let base = ramp(GND, t);
      let j = noise(x * 0.005 + 100, y * 0.007) - 0.5;
      let c = lerpColor(base, j > 0 ? color('#3a2a20') : color('#000000'), abs(j) * 0.5 * (1 - t * 0.6));
      let ang = (noise(x * 0.008, y * 0.02 + 70) - 0.5) * 0.35;
      let L = 14 + random(26);
      stroke(c); strokeWeight(5 + random(6));
      line(x, y, x + cos(ang) * L, y + sin(ang) * L);
    }
  }

  // --- ember band along the horizon ---
  for (let x = 60; x < 1540; x += 7) {
    let hy = horizon(x);
    let g = exp(-sq((x - 800) / 540));
    let n = 2 + floor(random(3));
    for (let k = 0; k < n; k++) {
      let yy = hy - 3 - random(24);
      let c = lerpColor(color('#7c2c18'), color('#d9873c'), noise(x * 0.02, yy * 0.03));
      c.setAlpha((5 + 26 * g) * random(0.4, 1));
      stroke(c); strokeWeight(1.4 + random(2.2));
      line(x, yy, x + 12 + random(42), yy + random(-2, 2));
    }
    if (random() < 0.45) {
      let c = color('#4a1a12'); c.setAlpha(4 + random(6));
      stroke(c); strokeWeight(1.5 + random(2));
      let yy = hy + 6 + random(14);
      line(x, yy, x + 10 + random(30), yy + random(-1.5, 1.5));
    }
  }

  // --- dead grass ---
  for (let i = 0; i < 650; i++) {
    let x = random(1600);
    let y = 1290 + pow(random(), 1.3) * 680;
    let h = 6 + random(22);
    let lean = random(-0.3, 0.3);
    let c = lerpColor(color('#241318'), color('#54301f'), random());
    c.setAlpha(18 + random(40));
    stroke(c); strokeWeight(1 + random());
    line(x, y, x + lean * h, y - h);
  }

  // --- the shrouded body ---
  const BODY = [
    [296, 1672], [338, 1606], [372, 1520], [404, 1498], [444, 1502], [474, 1548],
    [506, 1566], [556, 1520], [620, 1502], [712, 1494], [806, 1508], [884, 1516],
    [968, 1512], [1046, 1528], [1130, 1552], [1216, 1568], [1288, 1586],
    [1330, 1606], [1352, 1672]
  ];
  function topY(x) {
    x = constrain(x, BODY[0][0] + 1, BODY[BODY.length - 1][0] - 1);
    let i = 0;
    while (i < BODY.length - 2 && BODY[i + 1][0] < x) i++;
    let p0 = BODY[max(i - 1, 0)], p1 = BODY[i], p2 = BODY[i + 1], p3 = BODY[min(i + 2, BODY.length - 1)];
    let u = constrain((x - p1[0]) / (p2[0] - p1[0]), 0, 1);
    return 0.5 * ((2 * p1[1]) + (-p0[1] + p2[1]) * u +
      (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u * u +
      (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u * u * u);
  }

  // shadow pooled beneath
  for (let i = 0; i < 800; i++) {
    let x = 280 + random(1100);
    let y = 1672 + randomGaussian() * 9 + 5;
    let c = color('#040305'); c.setAlpha(14 + random(22));
    stroke(c); strokeWeight(5 + random(9));
    line(x, y, x + 18 + random(46), y + random(-2, 2));
  }

  // base silhouette
  noStroke(); fill('#a79c89');
  beginShape();
  vertex(298, 1676);
  for (let x = 300; x <= 1350; x += 6) vertex(x, topY(x));
  vertex(1352, 1676);
  endShape(CLOSE);

  // impasto shading
  for (let x = 300; x <= 1350; x += 1.8) {
    let ty = topY(x);
    let bot = 1672;
    let h = bot - ty;
    if (h < 5) continue;
    let seg = 3 + floor(random(2));
    for (let s = 0; s < seg; s++) {
      let yy = ty + random(h * 0.9);
      let hr = 1 - (yy - ty) / h;
      let lit = lerpColor(color('#5c5348'), color('#d9cfbc'), pow(hr, 1.4));
      let c = lerpColor(lit, color('#0d0b0d'), (1 - hr) * 0.35 + noise(x * 0.05, yy * 0.05) * 0.15);
      c.setAlpha(150 + random(90));
      stroke(c); strokeWeight(2.2 + random(2.4));
      let L = h * random(0.3, 0.8);
      let lean = (noise(x * 0.03, yy * 0.03) - 0.5) * 0.5;
      line(x + random(-1.5, 1.5), yy, x + lean * L + random(-1.5, 1.5), yy + L);
    }
  }

  // rim of last light along the contour
  for (let x = 312; x <= 1338; x += 8) {
    let y1 = topY(x - 5), y2 = topY(x + 5);
    let ang = atan2(y2 - y1, 10);
    let c = lerpColor(color('#f2e6cb'), color('#d99a55'), 0.25 + 0.35 * exp(-sq((x - 780) / 420)));
    c.setAlpha(90 + random(110));
    stroke(c); strokeWeight(1.6 + random(1.8));
    let L = 7 + random(9);
    let yc = topY(x) - 1;
    line(x - cos(ang) * L / 2, yc - sin(ang) * L / 2, x + cos(ang) * L / 2, yc + sin(ang) * L / 2);
  }

  // --- the departing swarm ---
  function spineX(t) { return 780 + (noise(t * 2.3 + 3.1) - 0.5) * 520 * pow(t, 0.9) + 170 * pow(t, 1.6); }
  function spineY(t) { return lerp(1505, 118, pow(t, 0.96)); }
  function spread(t) { return 26 + 560 * pow(t, 1.4); }

  // warm column of rising air
  for (let j = 0; j < 260; j++) {
    let t = pow(random(), 0.85);
    let x = spineX(t) + randomGaussian() * spread(t) * 0.45;
    let y = spineY(t) + randomGaussian() * 18;
    let c = lerpColor(color('#2a1718'), color('#472517'), noise(j * 0.2));
    c.setAlpha(4 + random(7));
    stroke(c); strokeWeight(10 + random(22));
    line(x, y, x + random(-6, 6), y - (24 + random(50)));
  }

  // dark breath leaving the chest
  for (let j = 0; j < 70; j++) {
    let t = random(0, 0.26);
    let x = spineX(t) + randomGaussian() * spread(t) * 0.35;
    let y = spineY(t);
    let c = color('#0b090d'); c.setAlpha(7 + random(11));
    stroke(c); strokeWeight(12 + random(24));
    line(x, y, x + random(-10, 10), y - (26 + random(58)));
  }

  for (let i = 0; i < 950; i++) {
    let t = pow(random(), 1.12);
    let strag = random() < 0.05 ? 2.1 : 1;
    let x = spineX(t) + randomGaussian() * spread(t) * 0.5 * strag;
    let y = spineY(t) + randomGaussian() * spread(t) * 0.16 * strag;
    let w = lerp(30, 3.6, pow(t, 1.02)) * random(0.7, 1.3);
    let ang = (noise(i * 0.13, 7) - 0.5) + (spineX(min(t + 0.03, 1)) - spineX(t)) * 0.006;
    let pale = t > 0.68 && random() < 0.16;
    let c;
    if (pale) { c = color('#c9bfae'); c.setAlpha(40 + random(70)); }
    else {
      c = lerpColor(color('#141014'), color('#54180f'), noise(i * 0.61, 3));
      c.setAlpha(t < 0.7 ? 200 + random(55) : lerp(230, 70, (t - 0.7) / 0.3));
    }
    push();
    translate(x, y);
    rotate(ang);
    noFill(); stroke(c); strokeWeight(max(1.1, w * 0.16));
    let f1 = random(-0.55, 1), f2 = random(-0.55, 1);
    bezier(0, 0, -w * 0.3, -w * (0.1 + 0.35 * f1), -w * 0.72, -w * (0.15 + 0.6 * f1), -w, w * (0.06 - 0.32 * f1));
    bezier(0, 0, w * 0.3, -w * (0.1 + 0.35 * f2), w * 0.72, -w * (0.15 + 0.6 * f2), w, w * (0.06 - 0.32 * f2));
    if (w > 12 && !pale) { noStroke(); fill(c); circle(0, 0, w * 0.22); }
    pop();
  }

  // ash becoming stars
  noStroke();
  for (let j = 0; j < 430; j++) {
    let t = 0.5 + 0.5 * pow(random(), 0.8);
    let x = spineX(t) + randomGaussian() * spread(t) * 0.6;
    let y = spineY(t) + randomGaussian() * 20;
    let c = color('#d8ccb2'); c.setAlpha(15 + random(75));
    fill(c); circle(x, y, 1 + random(2.6));
  }
  for (let j = 0; j < 130; j++) {
    let c = color('#cfc3ab'); c.setAlpha(8 + random(20));
    fill(c); circle(random(1600), random(900), 0.8 + random(1.8));
  }

  // canvas tooth
  for (let j = 0; j < 5200; j++) {
    let pal = random() < 0.5;
    let c = color(pal ? '#e8dcc4' : '#000000');
    c.setAlpha(3 + random(pal ? 8 : 11));
    stroke(c); strokeWeight(0.8 + random(1.2));
    let x = random(1600), y = random(2000);
    let L = 2 + random(7), a = random(TWO_PI);
    line(x, y, x + cos(a) * L, y + sin(a) * L);
  }

  // vignette
  function edgeStroke(x, y, ang) {
    let c = color('#030204'); c.setAlpha(7 + random(15));
    stroke(c); strokeWeight(24 + random(46));
    let L = 40 + random(90);
    line(x, y, x + cos(ang) * L, y + sin(ang) * L);
  }
  for (let j = 0; j < 420; j++) edgeStroke(random(1600), pow(random(), 2.2) * 300, HALF_PI + random(-0.3, 0.3));
  for (let j = 0; j < 420; j++) edgeStroke(random(1600), 2000 - pow(random(), 2.2) * 320, -HALF_PI + random(-0.3, 0.3));
  for (let j = 0; j < 330; j++) edgeStroke(pow(random(), 2.2) * 260, random(2000), random(-0.3, 0.3));
  for (let j = 0; j < 330; j++) edgeStroke(1600 - pow(random(), 2.2) * 260, random(2000), PI + random(-0.3, 0.3));
}

let W = 1600, H = 2000;
let FX = 800, FY = 470;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  strokeCap(ROUND);
  noLoop();

  background(9, 6, 5);
  ambientWash();
  drawDrape();
  drawSurface();
  castShadow(810, 1470, 360, 58, 150);
  castShadow(470, 1630, 120, 26, 110);
  drawCandle();
  drawSkull();
  drawRose();
  drawGlow();
  drawFlame();
  drawSmoke();
  drawMoth();
  drawMotes();
  vignette();
  grain();
}

function ambientWash() {
  noStroke();
  for (let r = 2100; r > 200; r -= 40) {
    let t = map(r, 2100, 200, 0, 1);
    let c = lerpColor(color(8, 5, 5), color(46, 26, 16), t);
    fill(red(c), green(c), blue(c), 5);
    ellipse(800, 780, r * 1.5, r * 1.7);
  }
}

function drawDrape() {
  for (let x = -10; x < W + 10; x += 5) {
    let f1 = noise(x * 0.0032, 3.7);
    let f2 = noise(x * 0.011, 9.2);
    let fold = 0.5 + 0.38 * sin(x * 0.013 + f1 * 7.0) + 0.22 * sin(x * 0.041 + f2 * 5.0);
    fold = constrain(fold, 0, 1);
    for (let y = -10; y < H + 10; y += 34) {
      let d = dist(x, y, FX, FY);
      let lit = constrain(1 - d / 1250, 0, 1);
      lit = lit * lit;
      let b = (0.05 + 0.95 * lit) * (0.3 + 0.7 * fold);
      let yy = y + noise(x * 0.05, y * 0.008) * 14;
      stroke(lerp(24, 130, b), lerp(7, 40, b), lerp(9, 30, b), 115);
      strokeWeight(random(2.6, 6.4));
      line(x + random(-2, 2), yy, x + random(-3, 3), yy + 42);
    }
  }
  for (let i = 0; i < 26; i++) {
    let x = random(W), y = random(-50, H);
    stroke(6, 3, 4, 60);
    strokeWeight(random(10, 22));
    line(x, y, x + random(-30, 30), y + random(200, 500));
  }
}

function drawSurface() {
  for (let y = 1428; y < 1800; y += 4) {
    let band = constrain((y - 1428) / 46, 0, 1) * constrain((1800 - y) / 90, 0, 1);
    for (let x = 40; x < 1560; x += 24) {
      let d = dist(x, y, FX, 1500);
      let lit = pow(constrain(1 - d / 820, 0, 1), 1.8);
      stroke(lerp(13, 96, lit), lerp(8, 54, lit), lerp(9, 34, lit), 20 + 90 * band);
      strokeWeight(random(2.4, 5.6));
      let xx = x + random(-6, 6);
      line(xx, y + random(-2, 2), xx + random(18, 42), y + random(-2, 2));
    }
  }
}

function castShadow(x, y, rx, ry, a) {
  noStroke();
  fill(3, 2, 2, a * 0.22); ellipse(x, y, rx * 2.6, ry * 2.4);
  fill(3, 2, 2, a * 0.35); ellipse(x, y, rx * 1.9, ry * 1.7);
  fill(3, 2, 2, a * 0.5);  ellipse(x, y, rx * 1.2, ry * 1.1);
}

function drawCandle() {
  let cx = 800, top = 560, base = 975, r = 66;
  for (let i = 0; i < 3200; i++) {
    let x = cx + (random() + random() - 1) * r;
    let y = random(top + 6, base);
    let nx = (x - cx) / r;
    let edge = sqrt(max(0, 1 - nx * nx));
    let n = noise(x * 0.03, y * 0.015);
    let b = constrain(edge * (0.55 + 0.6 * n), 0, 1);
    let warm = constrain(1 - (y - top) / 430, 0, 1);
    let c = lerpColor(color(40, 27, 18), color(210, 182, 132), b);
    c = lerpColor(c, color(240, 200, 128), warm * 0.45 * b);
    stroke(red(c), green(c), blue(c), 95);
    strokeWeight(random(2.4, 5.2));
    line(x, y, x + random(-1.6, 1.6), y + random(10, 30));
  }
  stroke(28, 18, 12, 150); strokeWeight(3);
  line(cx - r + 2, top + 14, cx - r + 4, base - 20);
  line(cx + r - 2, top + 14, cx + r - 4, base - 20);
  noStroke();
  fill(196, 164, 116); ellipse(cx, top, r * 2, 34);
  fill(238, 205, 142); ellipse(cx, top, r * 1.72, 26);
  fill(250, 228, 168); ellipse(cx - 6, top - 1, r * 1.1, 15);
  drip(cx - r + 6, top + 8, 66, 208, 178, 128);
  drip(cx + r - 8, top + 16, 96, 200, 168, 120);
  drip(cx - 26, top + 4, 40, 224, 196, 140);
  stroke(16, 10, 7); strokeWeight(5); noFill();
  bezier(cx, top - 2, cx + 2, top - 16, cx + 6, top - 30, cx + 4, top - 46);
}

function drip(x, y, len, r, g, b) {
  noStroke();
  fill(r, g, b, 235);
  ellipse(x, y + len * 0.45, 15, len);
  ellipse(x, y + len, 17, 17);
  fill(r + 18, g + 14, b + 8, 200);
  ellipse(x - 2.5, y + len * 0.4, 5, len * 0.8);
}

function skullColor(gx, gy) {
  let d = dist(gx, gy, FX, FY);
  let lit = pow(constrain(1 - (d - 150) / 1000, 0, 1), 1.4);
  let droop = map(gy, 870, 1510, 1.0, 0.5);
  let mot = 0.8 + 0.4 * noise(gx * 0.011, gy * 0.011);
  let b = constrain(lit * droop * mot + 0.05, 0, 1);
  return lerpColor(color(23, 15, 11), color(228, 208, 164), b);
}

function drawSkull() {
  let ox = 400, oy = 830, bw = 800, bh = 740;

  function inside(gx, gy) {
    if (sq((gx - 800) / 285) + sq((gy - 1150) / 270) <= 1) return true;
    if (sq((gx - 585) / 78) + sq((gy - 1272) / 58) <= 1) return true;
    if (sq((gx - 1015) / 78) + sq((gy - 1272) / 58) <= 1) return true;
    if (sq((gx - 800) / 196) + sq((gy - 1338) / 152) <= 1) return true;
    return false;
  }

  let g = createGraphics(bw, bh);
  g.pixelDensity(1);
  g.clear();
  g.strokeCap(ROUND);

  let n = 0, tries = 0;
  while (n < 9500 && tries < 42000) {
    tries++;
    let gx = random(430, 1170), gy = random(850, 1560);
    if (!inside(gx, gy)) continue;
    n++;
    let ang = atan2(gy - 1150, gx - 800) + HALF_PI;
    let len = random(18, 52);
    let c = skullColor(gx, gy);
    g.stroke(red(c), green(c), blue(c), random(60, 130));
    g.strokeWeight(random(4.5, 13));
    g.line(gx - cos(ang) * len * 0.5 - ox, gy - sin(ang) * len * 0.5 - oy,
           gx + cos(ang) * len * 0.5 - ox, gy + sin(ang) * len * 0.5 - oy);
  }
  for (let i = 0; i < 1300; i++) {
    let gx = random(560, 1040), gy = random(1320, 1540);
    if (!inside(gx, gy)) continue;
    g.stroke(16, 10, 8, random(40, 90));
    g.strokeWeight(random(5, 12));
    g.line(gx - ox, gy - oy, gx + random(-14, 14) - ox, gy + random(4, 20) - oy);
  }
  for (let i = 0; i < 380; i++) {
    let a = random(PI * 1.06, TWO_PI - PI * 0.06);
    let rr = random(0.93, 0.98);
    let gx = 800 + cos(a) * 285 * rr;
    let gy = 1150 + sin(a) * 270 * rr;
    let tang = a + HALF_PI;
    let len = random(8, 22);
    g.stroke(240, 224, 182, random(90, 180));
    g.strokeWeight(random(2.5, 5));
    g.line(gx - cos(tang) * len - ox, gy - sin(tang) * len - oy,
           gx + cos(tang) * len - ox, gy + sin(tang) * len - oy);
  }

  let m = createGraphics(bw, bh);
  m.pixelDensity(1);
  m.clear();
  m.noStroke();
  m.fill(255);
  m.ellipse(800 - ox, 1150 - oy, 570, 540);
  m.ellipse(585 - ox, 1272 - oy, 156, 116);
  m.ellipse(1015 - ox, 1272 - oy, 156, 116);
  m.ellipse(800 - ox, 1338 - oy, 392, 304);

  let img = g.get();
  img.mask(m.get());
  image(img, ox, oy);

  noStroke();
  fill(18, 11, 8, 120);
  ellipse(800, 1152, 520, 116);

  for (let s = -1; s <= 1; s += 2) {
    push();
    translate(800 + s * 114, 1238);
    rotate(s * 0.07);
    fill(16, 10, 8, 230); ellipse(0, 0, 176, 138);
    fill(6, 4, 3); ellipse(2 * s, 2, 138, 104);
    noFill(); stroke(96, 100, 116, 70); strokeWeight(4);
    arc(0, 12, 92, 58, PI * 0.12, PI * 0.88);
    pop();
  }

  noStroke();
  fill(8, 5, 4);
  triangle(800, 1284, 770, 1362, 830, 1362);
  ellipse(780, 1354, 42, 50);
  ellipse(820, 1354, 42, 50);
  noFill(); stroke(190, 160, 116, 90); strokeWeight(3);
  line(792, 1286, 776, 1340);

  noFill(); stroke(14, 9, 7, 110); strokeWeight(16);
  arc(600, 1318, 130, 120, PI * 0.15, PI * 0.85);
  arc(1000, 1318, 130, 120, PI * 0.15, PI * 0.85);

  fill(12, 7, 6, 220);
  ellipse(800, 1442, 270, 88);
  for (let i = 0; i < 8; i++) {
    let x = 800 + (i - 3.5) * 32;
    let y = 1430 + sq((i - 3.5) / 3.5) * 12;
    let lit = 1 - abs(i - 3.5) / 5.2;
    let c = lerpColor(color(96, 78, 56), color(206, 184, 140), 0.35 + 0.5 * lit);
    noStroke(); fill(c);
    rect(x - 12, y - 24, 24, 50, 9);
    fill(20, 12, 9, 120);
    rect(x - 12, y + 12, 24, 14, 6);
  }
  fill(10, 6, 5, 170);
  ellipse(800, 1486, 250, 40);
  noFill(); stroke(120, 74, 40, 55); strokeWeight(9);
  arc(800, 1452, 220, 70, PI * 0.15, PI * 0.85);

  stroke(24, 16, 11, 200); strokeWeight(2.6); noFill();
  beginShape();
  let cx0 = 852, cy0 = 902;
  vertex(cx0, cy0);
  for (let i = 1; i <= 8; i++) {
    cx0 += random(-16, 6);
    cy0 += random(16, 30);
    vertex(cx0, cy0);
  }
  endShape();
  stroke(24, 16, 11, 130); strokeWeight(1.8);
  line(838, 1010, 862, 1052);
}

function drawRose() {
  noFill();
  stroke(52, 52, 32, 220); strokeWeight(7);
  bezier(486, 1596, 640, 1622, 770, 1668, 926, 1724);
  stroke(24, 26, 14, 180); strokeWeight(2.6);
  bezier(488, 1601, 640, 1628, 770, 1674, 924, 1730);
  noStroke(); fill(40, 40, 24);
  triangle(690, 1640, 700, 1652, 678, 1654);
  leaf(588, 1610, 0.5, 62);
  leaf(812, 1688, -0.35, 54);

  push();
  translate(468, 1568);
  rotate(-0.42);
  for (let i = 0; i < 10; i++) {
    let a = i * TWO_PI / 10 + noise(i * 4.7) * 0.5;
    let pr = 62 + noise(i * 2.3) * 30;
    push();
    rotate(a);
    let c = lerpColor(color(112, 28, 38), color(42, 8, 13), noise(i * 6.1));
    noStroke(); fill(c);
    ellipse(pr * 0.62, 0, pr * 1.35, pr * 0.86);
    noFill(); stroke(146, 48, 56, 70); strokeWeight(2);
    arc(pr * 0.62, 0, pr * 1.35, pr * 0.86, -HALF_PI * 0.7, HALF_PI * 0.7);
    pop();
  }
  noStroke();
  fill(58, 10, 17); ellipse(0, 0, 92, 84);
  fill(30, 5, 10); ellipse(3, 2, 56, 52);
  noFill(); stroke(130, 40, 48, 120); strokeWeight(2.4);
  arc(0, 0, 66, 60, 0.3, 3.6);
  arc(4, 3, 34, 32, 2.6, 6.1);
  pop();

  petal(636, 1706, 0.7, 40);
  petal(352, 1678, -0.9, 46);
  petal(948, 1618, 2.2, 34);
}

function leaf(x, y, a, len) {
  push();
  translate(x, y); rotate(a);
  noStroke(); fill(38, 42, 22);
  ellipse(len * 0.5, 0, len, len * 0.36);
  stroke(20, 24, 12, 160); strokeWeight(1.6);
  line(0, 0, len, 0);
  pop();
}

function petal(x, y, a, s) {
  push();
  translate(x, y); rotate(a);
  noStroke();
  fill(74, 16, 24, 235); ellipse(0, 0, s * 1.5, s * 0.8);
  fill(38, 8, 12, 200); ellipse(s * 0.2, s * 0.1, s * 0.9, s * 0.42);
  pop();
}

function drawGlow() {
  noStroke();
  for (let r = 700; r > 30; r -= 16) {
    let t = map(r, 700, 30, 0, 1);
    fill(255, 168, 84, lerp(1.2, 20, t * t));
    ellipse(FX, FY, r * 2, r * 2.06);
  }
  fill(255, 150, 70, 10);
  ellipse(800, 1200, 1500, 1200);
}

function drawFlame() {
  let layers = [
    [70, 226, 96, 24, 150],
    [52, 255, 150, 44, 190],
    [34, 255, 202, 92, 220],
    [18, 255, 240, 190, 240]
  ];
  noStroke();
  for (let L of layers) {
    let s = L[0], lean = 5 * (s / 40);
    fill(L[1], L[2], L[3], L[4]);
    beginShape();
    vertex(FX + lean, FY - s * 1.95);
    bezierVertex(FX + s * 0.8, FY - s * 0.7, FX + s * 0.62, FY + s * 0.55, FX, FY + s * 0.8);
    bezierVertex(FX - s * 0.62, FY + s * 0.55, FX - s * 0.8, FY - s * 0.7, FX + lean, FY - s * 1.95);
    endShape(CLOSE);
  }
  fill(88, 110, 190, 120); ellipse(FX, FY + 44, 40, 30);
  fill(120, 140, 220, 90); ellipse(FX, FY + 40, 26, 20);
}

function drawSmoke() {
  noStroke();
  for (let s = 0; s < 3; s++) {
    for (let t = 0; t < 1; t += 0.005) {
      let y = FY - 140 - t * 460;
      let wob = (noise(t * 2.4 + s * 9.1, s * 4.7) - 0.5) * 2;
      let x = FX + wob * (14 + t * 150) + sin(t * 8 + s * 2.1) * 10 * t;
      fill(148, 150, 160, (1 - t) * 13 + 2);
      let w = 5 + t * 30;
      ellipse(x + s * 6 - 6, y, w, w * 0.74);
    }
  }
}

function drawMoth() {
  push();
  translate(1042, 632);
  rotate(0.55);
  noStroke();
  fill(30, 24, 19, 235); ellipse(0, 0, 13, 34);
  push(); rotate(-0.5); fill(40, 32, 24, 220); ellipse(-17, -5, 40, 24); pop();
  push(); rotate(0.45); fill(36, 28, 21, 220); ellipse(16, -6, 38, 22); pop();
  noFill(); stroke(200, 150, 90, 90); strokeWeight(2);
  arc(-14, -8, 34, 18, PI * 0.9, PI * 1.6);
  pop();
}

function drawMotes() {
  noStroke();
  for (let i = 0; i < 130; i++) {
    let a = random(TWO_PI);
    let r = pow(random(), 0.7) * 620;
    let x = FX + cos(a) * r;
    let y = FY + sin(a) * r * 1.15;
    let near = 1 - r / 620;
    fill(255, 214, 150, 20 + 150 * near * random(0.4, 1));
    let s = random(1.2, 3.6);
    ellipse(x, y, s, s);
  }
}

function vignette() {
  noFill();
  for (let i = 0; i < 110; i++) {
    let inset = i * 3.0;
    let a = 55 * pow(1 - i / 110, 1.6);
    if (a < 0.5) break;
    stroke(4, 2, 2, a);
    strokeWeight(3.4);
    rect(inset, inset, W - inset * 2, H - inset * 2);
  }
  noStroke();
  fill(3, 2, 2, 46);
  ellipse(0, 0, 900, 900);
  ellipse(W, 0, 900, 900);
  ellipse(0, H, 1000, 1000);
  ellipse(W, H, 1000, 1000);
}

function grain() {
  noStroke();
  for (let i = 0; i < 24000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.55) fill(0, 0, 0, random(4, 11));
    else fill(214, 196, 168, random(3, 8));
    let s = random(0.8, 2.4);
    rect(x, y, s, s);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noLoop();
}

function draw() {
  background(9, 15, 20);
  paintGround();
  paintAperture();
  paintWater();
  paintHorizon();
  paintLightReflection();
  paintBoatReflection();
  paintSeeds();
  paintBoat();
  paintForeground();
  paintSurface();
}

function paintGround() {
  const top = color(9, 14, 22);
  const horizon = color(42, 55, 56);
  const bottom = color(7, 20, 27);

  noStroke();
  for (let y = 0; y < height; y += 4) {
    let c;
    if (y < 960) {
      c = lerpColor(top, horizon, pow(y / 960, 0.8));
    } else {
      c = lerpColor(horizon, bottom, (y - 960) / 1040);
    }
    fill(c);
    rect(0, y, width, 5);
  }

  for (let i = 0; i < 2800; i++) {
    const x = random(width);
    const y = random(980);
    const n = noise(x * 0.0025, y * 0.003);
    stroke(
      17 + n * 35,
      23 + n * 37,
      30 + n * 34,
      random(4, 18)
    );
    strokeWeight(random(2, 22));
    line(x, y, x + random(-85, 85), y + random(-4, 4));
  }
}

function paintAperture() {
  const c = drawingContext;

  c.save();
  c.translate(850, 650);
  c.scale(1, 1.45);
  const glow = c.createRadialGradient(0, 0, 5, 0, 0, 560);
  glow.addColorStop(0, "rgba(235,216,172,0.50)");
  glow.addColorStop(0.18, "rgba(193,183,151,0.24)");
  glow.addColorStop(0.52, "rgba(119,137,127,0.09)");
  glow.addColorStop(1, "rgba(50,70,72,0)");
  c.fillStyle = glow;
  c.fillRect(-650, -650, 1300, 1300);
  c.restore();

  for (let i = 0; i < 520; i++) {
    const x = randomGaussian(850, 95);
    const y = random(215, 975);
    const d = abs(x - 850);
    const a = (1 - d / 270) * random(4, 20);
    if (a <= 0) continue;
    stroke(211, 199, 164, a);
    strokeWeight(random(1, 10));
    line(x, y, x + random(-4, 4), y + random(12, 115));
  }

  noStroke();
  fill(213, 204, 175, 235);
  beginShape();
  vertex(850, 218);
  bezierVertex(833, 340, 817, 488, 814, 650);
  bezierVertex(810, 790, 811, 892, 823, 970);
  vertex(885, 970);
  bezierVertex(879, 830, 883, 690, 875, 548);
  bezierVertex(870, 410, 860, 300, 850, 218);
  endShape(CLOSE);

  fill(239, 226, 190, 155);
  beginShape();
  vertex(851, 270);
  bezierVertex(842, 430, 838, 610, 840, 790);
  bezierVertex(841, 860, 844, 920, 847, 965);
  vertex(862, 965);
  bezierVertex(859, 790, 862, 610, 858, 455);
  bezierVertex(856, 375, 854, 315, 851, 270);
  endShape(CLOSE);

  for (let i = 0; i < 170; i++) {
    const y = random(500, 955);
    const x = 850 + random(-29, 29);
    stroke(
      random() < 0.5 ? 246 : 157,
      random() < 0.5 ? 229 : 158,
      random() < 0.5 ? 198 : 139,
      random(8, 30)
    );
    strokeWeight(random(1, 5));
    line(x, y, x + random(-2, 2), min(970, y + random(8, 58)));
  }
}

function paintWater() {
  const nearHorizon = color(23, 45, 48);
  const nearForeground = color(5, 17, 24);

  noStroke();
  for (let y = 940; y < height; y += 4) {
    const t = (y - 940) / 1060;
    fill(lerpColor(nearHorizon, nearForeground, t));
    rect(0, y, width, 5);
  }

  for (let i = 0; i < 5600; i++) {
    const y = random(950, 2005);
    const t = (y - 950) / 1055;
    const x = random(-50, 1650);
    const n = noise(x * 0.004, y * 0.008);
    const len = random(8, 48) + t * random(15, 150);

    if (random() < 0.72) {
      stroke(
        24 + n * 34,
        47 + n * 35,
        51 + n * 34,
        random(10, 43)
      );
    } else {
      stroke(3, 13, 20, random(18, 65));
    }

    strokeWeight(random(0.6, 2.2) + t * random(0.5, 4));
    line(x, y, x + len, y + random(-2, 2) * (0.3 + t));
  }

  for (let i = 0; i < 90; i++) {
    const y = random(1080, 1990);
    const t = (y - 1080) / 910;
    stroke(3, 13, 18, random(12, 35));
    strokeWeight(random(3, 10));
    line(random(-100, 1400), y, random(300, 1800), y + random(-4, 4) * t);
  }
}

function paintHorizon() {
  noStroke();
  fill(7, 21, 25, 245);

  beginShape();
  vertex(0, 1010);
  vertex(0, 954);
  for (let x = 0; x <= 792; x += 16) {
    vertex(x, 945 + noise(x * 0.015, 2) * 27);
  }
  vertex(812, 1010);
  endShape(CLOSE);

  beginShape();
  vertex(914, 1010);
  for (let x = 914; x <= 1600; x += 16) {
    vertex(x, 946 + noise(x * 0.014, 7) * 25);
  }
  vertex(1600, 1010);
  endShape(CLOSE);

  for (let i = 0; i < 100; i++) {
    const x = random(width);
    if (abs(x - 850) < 70) continue;
    stroke(79, 91, 82, random(8, 28));
    strokeWeight(random(0.5, 2));
    line(x, random(956, 982), x + random(8, 70), random(956, 982));
  }
}

function paintLightReflection() {
  for (let y = 962; y < 1870; y += random(4, 10)) {
    const t = (y - 950) / 920;
    const spread = 35 + 400 * t;
    const center = 850 + sin(y * 0.012) * 18;
    const count = 1 + floor(random(4));

    for (let j = 0; j < count; j++) {
      const x = center + randomGaussian(0, spread * 0.38);
      const len = random(8, 45) + t * random(10, 95);
      const a = (1 - t) * random(20, 72) + 4;

      if (random() < 0.25) {
        stroke(225, 211, 175, a);
      } else {
        stroke(151, 160, 143, a * 0.8);
      }

      strokeWeight(random(0.8, 3.5) + t * 1.5);
      line(x - len / 2, y, x + len / 2, y + random(-1.5, 1.5));
    }
  }

  for (let i = 0; i < 170; i++) {
    const y = random(980, 1860);
    const t = (y - 980) / 880;
    const x = 850 + randomGaussian(0, 40 + 170 * t);
    stroke(5, 22, 27, random(25, 75));
    strokeWeight(random(1, 4));
    line(x, y, x + random(12, 85), y);
  }
}

function paintBoatReflection() {
  for (let i = 0; i < 230; i++) {
    const y = random(1560, 1800);
    const t = (y - 1560) / 240;
    const x = randomGaussian(790, 220 * (1 - t) + 45);
    const len = random(15, 130) * (1 - t * 0.55);

    if (random() < 0.15 && y < 1700) {
      stroke(169, 171, 151, random(8, 26));
    } else {
      stroke(2, 10, 15, random(25, 90) * (1 - t * 0.5));
    }

    strokeWeight(random(1, 6));
    line(x - len / 2, y, x + len / 2, y + random(-2, 2));
  }
}

function paintSeeds() {
  for (let i = 0; i < 36; i++) {
    const y = random(410, 1330);
    const spread = map(y, 410, 1330, 40, 220);
    const x = 850 + randomGaussian(0, spread * 0.55);
    const s = random(2, 6.5);
    const insideLight = y < 950 && abs(x - 850) < 48;

    push();
    translate(x, y);
    rotate(random(-1.2, 1.2));

    if (insideLight) {
      stroke( sixty(),  sixty(), 48, random(35, 80));
    } else {
      stroke(208, 199, 165, random(30, 105));
    }

    strokeWeight(random(0.7, 1.5));
    line(-s, 0, s, 0);
    noFill();
    arc(0, -s * 0.35, s * 1.4, s * 1.1, PI, TAU);
    pop();
  }
}

function sixty() {
  return 60;
}

function traceHull(c) {
  c.beginPath();
  c.moveTo(350, 1400);
  c.bezierCurveTo(590, 1435, 1010, 1400, 1240, 1325);
  c.bezierCurveTo(1175, 1455, 1040, 1555, 815, 1590);
  c.bezierCurveTo(600, 1625, 430, 1540, 350, 1400);
  c.closePath();
}

function traceShroud(c) {
  c.beginPath();
  c.moveTo(480, 1403);
  c.bezierCurveTo(545, 1370, 600, 1350, 675, 1348);
  c.bezierCurveTo(760, 1344, 825, 1324, 890, 1288);
  c.bezierCurveTo(920, 1270, 945, 1253, 977, 1252);
  c.bezierCurveTo(1028, 1250, 1055, 1280, 1050, 1313);
  c.bezierCurveTo(1046, 1340, 1016, 1357, 973, 1366);
  c.bezierCurveTo(846, 1395, 670, 1432, 535, 1420);
  c.bezierCurveTo(510, 1418, 492, 1412, 480, 1403);
  c.closePath();
}

function paintBoat() {
  const c = drawingContext;

  c.save();
  traceHull(c);
  const hullGradient = c.createLinearGradient(0, 1370, 0, 1620);
  hullGradient.addColorStop(0, "rgb(52,46,37)");
  hullGradient.addColorStop(0.35, "rgb(28,29,27)");
  hullGradient.addColorStop(1, "rgb(7,17,21)");
  c.fillStyle = hullGradient;
  c.fill();
  c.clip();

  for (let i = 0; i < 430; i++) {
    const x = random(340, 1250);
    const y = random(1360, 1610);
    stroke(
      random() < 0.65 ? 113 : 8,
      random() < 0.65 ? 91 : 19,
      random() < 0.65 ? 63 : 23,
      random(5, 28)
    );
    strokeWeight(random(1, 5));
    line(x, y, x + random(12, 105), y + random(-3, 3));
  }

  for (let i = 0; i < 8; i++) {
    noFill();
    stroke(126, 100, 67, 16 + i * 2);
    strokeWeight(2);
    bezier(
      405,
      1460 + i * 12,
      640,
      1585 - i * 3,
      1010,
      1555 - i * 8,
      1165,
      1400 + i * 5
    );
  }
  c.restore();

  traceHull(c);
  c.strokeStyle = "rgba(105,88,65,0.55)";
  c.lineWidth = 4;
  c.stroke();

  noStroke();
  fill(36, 35, 31);
  beginShape();
  vertex(375, 1405);
  bezierVertex(600, 1432, 1000, 1384, 1200, 1340);
  bezierVertex(1000, 1424, 680, 1470, 440, 1435);
  endShape(CLOSE);

  c.save();
  traceShroud(c);
  const clothGradient = c.createLinearGradient(0, 1245, 0, 1440);
  clothGradient.addColorStop(0, "rgb(226,220,195)");
  clothGradient.addColorStop(0.48, "rgb(190,198,186)");
  clothGradient.addColorStop(1, "rgb(112,137,140)");
  c.fillStyle = clothGradient;
  c.fill();
  c.clip();

  for (let i = 0; i < 360; i++) {
    const x = random(470, 1060);
    const y = random(1245, 1435);
    if (random() < 0.55) {
      stroke(238, 229, 201, random(4, 20));
    } else {
      stroke( sixty(), 93, 101, random(4, 18));
    }
    strokeWeight(random(0.6, 3));
    line(x, y, x + random(-10, 28), y + random(-2, 8));
  }

  noFill();
  stroke(65, 94, 100, 75);
  strokeWeight(7);
  bezier(510, 1405, 630, 1370, 760, 1398, 948, 1325);
  bezier(580, 1365, 650, 1390, 710, 1390, 795, 1345);
  bezier(760, 1340, 820, 1360, 900, 1340, 1000, 1285);

  stroke(236, 227, 199, 105);
  strokeWeight(5);
  bezier(525, 1388, 650, 1348, 770, 1370, 895, 1300);
  bezier(905, 1280, 954, 1260, 1012, 1275, 1030, 1305);

  stroke(78, 103, 107, 60);
  strokeWeight(4);
  bezier(930, 1270, 980, 1295, 1000, 1330, 1010, 1350);
  bezier(625, 1355, 650, 1378, 655, 1400, 670, 1420);
  c.restore();

  traceShroud(c);
  c.strokeStyle = "rgba(54,76,80,0.65)";
  c.lineWidth = 3;
  c.stroke();

  noFill();
  stroke(13, 21, 23, 230);
  strokeWeight(15);
  bezier(350, 1400, 590, 1435, 1010, 1400, 1240, 1325);
  stroke(139, 115, 80, 155);
  strokeWeight(4);
  bezier(350, 1397, 590, 1432, 1010, 1397, 1240, 1322);
