function paintForeground() {
  for (let side = 0; side < 2; side++) {
    const left = side === 0;

    for (let i = 0; i < 31; i++) {
      const baseX = left ? random(-30, 235) : random(1365, 1630);
      const baseY = random(1810, 2070);
      const h = random(170, 650);
      const lean = (left ? 1 : -1) * random(-45, 170);
      const tipX = baseX + lean;
      const tipY = baseY - h;

      noFill();
      stroke(3, 11, 15, random(155, 245));
      strokeWeight(random(2, 8));
      bezier(
        baseX,
        baseY,
        baseX + lean * 0.12,
        baseY - h * 0.35,
        tipX - lean * 0.22,
        tipY + h * 0.25,
        tipX,
        tipY
      );

      if (random() < 0.28) {
        push();
        translate(tipX, tipY);
        rotate(lean * 0.002);
        noStroke();
        fill(7, 16, 18, random(170, 240));
        ellipse(0, -12, random(4, 8), random(20, 38));
        pop();
      }

      if (random() < 0.22) {
        const yy = baseY - h * random(0.3, 0.65);
        const xx = baseX + lean * random(0.2, 0.55);
        stroke(5, 15, 18, 190);
        strokeWeight(3);
        line(xx, yy, xx + (left ? 1 : -1) * random(25, 85), yy - random(20, 70));
      }
    }
  }
}

function paintSurface() {
  for (let i = 0; i < 18000; i++) {
    const v = random() < 0.5 ? 235 : 0;
    stroke(v, v, v, random(2, 9));
    strokeWeight(random(0.4, 1.3));
    point(random(width), random(height));
  }

  for (let i = 0; i < 1100; i++) {
    const x = random(width);
    const y = random(height);
    stroke(190, 181, 155, random(2, 7));
    strokeWeight(random(0.4, 1));
    line(x, y, x + random(-16, 16), y + random(-1, 1));
  }

  const c = drawingContext;
  c.save();
  const vignette = c.createRadialGradient(800, 960, 280, 800, 1000, 1280);
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.66, "rgba(0,0,0,0.08)");
  vignette.addColorStop(1, "rgba(0,0,0,0.52)");
  c.fillStyle = vignette;
  c.fillRect(0, 0, width, height);
  c.restore();
}

