  strokeWeight(5);
  bezier(1260, 1832, 1190, 1840, 1140, 1870, 1070, 1890);
  stroke(142, 139, 100, 75);
  strokeWeight(2);
  bezier(1258, 1829, 1180, 1842, 1130, 1868, 1070, 1887);

  noStroke();
  fill(64, 80, 58, 150);
  push();
  translate(1185, 1850);
  rotate(-0.45);
  ellipse(0, 0, 55, 16);
  pop();

  push();
  translate(1065, 1890);
  for (let i = 0; i < 6; i++) {
