}

function bareBranch(x, y, len, angle, depth) {
  if (depth <= 0) return;

  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;

  stroke(30, 45, 43, map(depth, 1, 7, 35, 125));
  strokeWeight(depth * 1.35);
  line(x, y, x2, y2);

  if (depth > 1) {
    bareBranch(
      x2,
      y2,
      len * random(0.62, 0.78),
      angle - random(0.18, 0.47),
      depth - 1
    );
    bareBranch(
      x2,
      y2,
      len * random(0.58, 0.76),
      angle + random(0.18, 0.5),
      depth - 1
    );
  }
}

let branches = [];
let bloomSites = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);

  paintBackground();
  paintGround();

  buildTree();
  drawSkeleton();
  drawRoots();
  drawBranches();
  drawBlossoms();
  drawDriftingPetals();

  paintVignette();
  paintGrain();
}

function paintBackground() {
