function buildTree() {
  branches = [];
  bloomSites = [];
  growBranch(655, 1550, 292, -HALF_PI + 0.035, 62, 8);
}

function growBranch(x, y, len, ang, w, depth) {
  let a = ang + random(-0.065, 0.065);
  let x2 = x + cos(a) * len;
  let y2 = y + sin(a) * len;

  let bend = random(-0.16, 0.16);
  let cx = (x + x2) * 0.5 - sin(a) * len * bend;
  let cy = (y + y2) * 0.5 + cos(a) * len * bend;

  branches.push({ x, y, cx, cy, x2, y2, w, depth });

  if (depth <= 1) {
    bloomSites.push({
      x: x2,
      y: y2,
      s: random(7, 14),
      terminal: depth === 0
    });

    if (random() < 0.55) {
      bloomSites.push({
        x: lerp(x, x2, 0.72) + random(-9, 9),
        y: lerp(y, y2, 0.72) + random(-9, 9),
        s: random(6, 11),
        terminal: false
      });
    }
  }

  if (depth === 0) return;

  growBranch(
    x2,
    y2,
    len * random(0.70, 0.79),
    a + random(-0.18, 0.18),
    w * 0.70,
    depth - 1
  );

  let side = random() < 0.5 ? -1 : 1;
  growBranch(
    x2,
    y2,
    len * random(0.53, 0.69),
    a + side * random(0.39, 0.67),
    w * 0.56,
    depth - 1
  );

  if (depth < 5 && random() < 0.17) {
    growBranch(
      x2,
      y2,
      len * random(0.43, 0.57),
      a - side * random(0.48, 0.78),
      w * 0.43,
      depth - 1
    );
  }
}

function branchPath(b) {
  beginShape();
  vertex(b.x, b.y);
  quadraticVertex(b.cx, b.cy, b.x2, b.y2);
  endShape();
}

function drawBranches() {
  noFill();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  for (let b of branches) {
    stroke(5, 11, 13, 205);
    strokeWeight(b.w + 7);
    branchPath(b);

    if (b.w < 4) {
      stroke(126, 128, 107, 225);
    } else {
      stroke(78, 79, 66, 245);
    }
    strokeWeight(b.w);
    branchPath(b);

    stroke(184, 177, 139, b.w < 4 ? 100 : 64);
    strokeWeight(max(0.7, b.w * 0.13));
    branchPath(b);

    if (b.w > 9 && random() < 0.8) {
      let t = random(0.2, 0.8);
      let x = lerp(b.x, b.x2, t);
      let y = lerp(b.y, b.y2, t);
      stroke(23, 29, 26, 150);
      strokeWeight(random(1.5, 3.5));
      line(
        x - b.w * 0.25,
        y - random(3, 12),
        x + b.w * 0.18,
        y + random(5, 18)
      );
    }
  }

  noStroke();
  fill(38, 42, 34, 230);
  ellipse(655, 1544, 96, 42);
}

function drawRoots() {
  let targets = [
    [330, 1630], [410, 1750], [540, 1840], [710, 1815],
    [890, 1810], [1060, 1740], [1230, 1660], [1070, 1510],
    [890, 1445], [760, 1405], [510, 1440], [280, 1710],
    [1360, 1760], [960, 1900]
  ];

  noFill();
  strokeCap(ROUND);

  for (let target of targets) {
    let x1 = 655 + random(-26, 26);
    let y1 = 1535 + random(-8, 20);
    let x2 = target[0] + random(-25, 25);
    let y2 = target[1] + random(-18, 18);
    let c1x = lerp(x1, x2, 0.28) + random(-75, 75);
    let c1y = lerp(y1, y2, 0.28) + random(-45, 45);
    let c2x = lerp(x1, x2, 0.68) + random(-70, 70);
    let c2y = lerp(y1, y2, 0.68) + random(-45, 45);
    let w = random(4, 11);

    stroke(5, 10, 11, 190);
    strokeWeight(w + 5);
    bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);

    stroke(104, 91, 62, 190);
    strokeWeight(w);
    bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);

    stroke(178, 151, 94, 65);
    strokeWeight(max(1, w * 0.2));
    bezier(x1, y1, c1x, c1y, c2x, c2y, x2, y2);

    for (let j = 0; j < 2; j++) {
      let t = random(0.42, 0.76);
      let mt = 1 - t;
      let px =
        mt * mt * mt * x1 +
        3 * mt * mt * t * c1x +
        3 * mt * t * t * c2x +
        t * t * t * x2;
      let py =
        mt * mt * mt * y1 +
        3 * mt * mt * t * c1y +
        3 * mt * t * t * c2y +
        t * t * t * y2;

      stroke(91, 81, 57, 145);
      strokeWeight(random(1.2, 3.2));
      bezier(
        px, py,
        px + random(-35, 35), py + random(-10, 30),
        px + random(-65, 65), py + random(20, 65),
        px + random(-95, 95), py + random(35, 105)
      );
    }
  }
}

function longBone(x1, y1, x2, y2, w) {
  strokeCap(ROUND);

  stroke(6, 12, 13, 215);
  strokeWeight(w + 8);
  line(x1, y1, x2, y2);

  stroke(181, 171, 141, 245);
  strokeWeight(w);
  line(x1, y1, x2, y2);

  stroke(229, 216, 177, 105);
  strokeWeight(max(1, w * 0.18));
  line(x1 - 1, y1 - 2, x2 - 1, y2 - 2);

  for (let p of [[x1, y1], [x2, y2]]) {
    noStroke();
    fill(7, 13, 14, 220);
    ellipse(p[0], p[1], w * 1.55, w * 1.45);
    fill(190, 180, 148, 245);
    ellipse(p[0], p[1], w * 1.18, w * 1.08);
    fill(225, 213, 176, 75);
    ellipse(p[0] - 2, p[1] - 2, w * 0.45, w * 0.35);
  }
}

function drawSkeleton() {
  longBone(462, 1484, 590, 1398, 21);
  longBone(590, 1398, 765, 1428, 15);
  drawHand(786, 1430, 0.10, 0.85);

  longBone(466, 1660, 592, 1768, 22);
  longBone(592, 1768, 770, 1738, 15);
  drawHand(792, 1734, -0.18, 0.88);

  longBone(920, 1532, 1125, 1462, 29);
  longBone(1150, 1464, 1345, 1497, 20);
  drawFoot(1365, 1500, 0.12);

  longBone(928, 1640, 1128, 1718, 30);
  longBone(1152, 1714, 1350, 1684, 20);
  drawFoot(1370, 1680, -0.15);

  drawPelvis();
  drawSpine();
  drawRibs();
  drawSkull();
}

function drawSpine() {
  for (let i = 0; i < 21; i++) {
    let x = 386 + i * 24;
    let y = 1574 + sin(i * 0.45) * 5;

    noStroke();
    fill(7, 13, 14, 220);
    ellipse(x, y, 28, 33);
    fill(180, 170, 140, 245);
    ellipse(x, y, 20, 25);
    fill(222, 208, 169, 80);
    ellipse(x - 3, y - 4, 7, 9);
  }

  noFill();
  stroke(184, 174, 143, 230);
  strokeWeight(12);
  bezier(410, 1568, 430, 1505, 464, 1460, 510, 1452);
  bezier(410, 1580, 430, 1640, 464, 1682, 510, 1690);
}

function drawRib(x, y, side, span, reach) {
  noFill();
  strokeCap(ROUND);

  for (let pass = 0; pass < 2; pass++) {
    if (pass === 0) {
      stroke(7, 13, 14, 215);
      strokeWeight(15);
    } else {
      stroke(190, 180, 148, 235);
      strokeWeight(8);
    }

    bezier(
      x, y,
      x - 30, y + side * span * 0.48,
      x + 12, y + side * span,
      x + reach, y + side * span * 0.84
    );

    bezier(
      x + reach, y + side * span * 0.84,
      x + reach + 34, y + side * span * 0.68,
      x + reach + 28, y + side * 30,
      x + reach + 4, y + side * 20
    );
  }
}

function drawRibs() {
  let spans = [82, 110, 137, 151, 145, 125, 96];

  for (let i = 0; i < 7; i++) {
    let x = 464 + i * 40;
    drawRib(x, 1572, -1, spans[i], 76);
    drawRib(x, 1578, 1, spans[i], 76);
  }

  noFill();
  stroke(204, 192, 156, 210);
  strokeWeight(10);
  bezier(575, 1573, 620, 1558, 692, 1560, 756, 1575);
}

function drawPelvis() {
  for (let side of [-1, 1]) {
    noStroke();
    fill(8, 14, 15, 220);
    beginShape();
    vertex(830, 1578);
    bezierVertex(
      804, 1578 + side * 25,
      812, 1578 + side * 116,
      866, 1578 + side * 120
    );
    bezierVertex(
      927, 1578 + side * 116,
      940, 1578 + side * 48,
      906, 1578 + side * 20
    );
    bezierVertex(
      878, 1578 + side * 4,
      850, 1578 + side * 5,
      830, 1578
    );
    endShape(CLOSE);

    fill(184, 173, 141, 245);
    beginShape();
    vertex(837, 1578);
    bezierVertex(
      818, 1578 + side * 28,
      824, 1578 + side * 101,
      867, 1578 + side * 106
    );
    bezierVertex(
      913, 1578 + side * 101,
      925, 1578 + side * 49,
      900, 1578 + side * 27
    );
    bezierVertex(
      875, 1578 + side * 12,
      852, 1578 + side * 12,
      837, 1578
    );
    endShape(CLOSE);

    fill(30, 35, 30, 245);
    ellipse(872, 1578 + side * 59, 43, 51);
  }

  noStroke();
  fill(197, 185, 150, 240);
  ellipse(908, 1580, 48, 72);
  fill(99, 93, 73, 160);
  ellipse(914, 1580, 14, 42);
}

function drawSkull() {
  push();
  translate(270, 1570);
  rotate(-0.09);

  noStroke();
  fill(7, 13, 14, 230);
  beginShape();
  vertex(75, 69);
  bezierVertex(111, 18, 88, -64, 43, -94);
  bezierVertex(-5, -126, -69, -94, -86, -52);
  vertex(-101, -38);
  vertex(-91, -20);
  vertex(-120, 0);
  vertex(-94, 14);
  vertex(-102, 31);
  vertex(-76, 36);
  vertex(-73, 61);
  bezierVertex(-42, 94, 28, 101, 75, 69);
  endShape(CLOSE);

  fill(194, 183, 150, 250);
  beginShape();
  vertex(68, 62);
  bezierVertex(99, 17, 79, -57, 38, -84);
  bezierVertex(-4, -113, -61, -84, -76, -48);
  vertex(-91, -35);
  vertex(-81, -17);
  vertex(-108, 0);
  vertex(-83, 12);
  vertex(-91, 25);
  vertex(-66, 30);
  vertex(-64, 54);
  bezierVertex(-37, 82, 24, 90, 68, 62);
