  vertex(47, -72);
  bezierVertex(5, -99, -46, -75, -59, -43);
  bezierVertex(-21, -63, 23, -57, 47, -72);
  endShape(CLOSE);

  fill(20, 28, 27, 255);
  push();
  translate(-42, -29);
  rotate(-0.18);
  ellipse(0, 0, 42, 51);
  pop();

  beginShape();
  vertex(-80, 3);
  vertex(-94, 14);
  vertex(-73, 18);
  endShape(CLOSE);

  noFill();
  stroke(70, 68, 55, 220);
  strokeWeight(4);
  bezier(-68, 40, -34, 53, 9, 57, 55, 43);

  for (let i = 0; i < 6; i++) {
    let x = -59 + i * 18;
    stroke(83, 78, 61, 210);
    strokeWeight(3);
    line(x, 39 + sin(i) * 3, x - 1, 56 + sin(i) * 3);
  }

  stroke(91, 85, 65, 180);
  strokeWeight(3);
  bezier(21, -83, 12, -62, 27, -48, 15, -30);
  bezier(15, -30, 6, -20, 11, -10, 2, 1);

  pop();
