function drawHand(x, y, angle, sc) {
  push();
  translate(x, y);
  rotate(angle);
  scale(sc);

  longBone(-8, 0, 28, 0, 8);

  for (let i = -2; i <= 2; i++) {
    let yy = i * 8;
    let len = 45 - abs(i) * 5;
    longBone(28, yy * 0.55, 48, yy, 4.2);
    longBone(48, yy, 48 + len * 0.55, yy + i * 1.8, 3.3);
    longBone(
      48 + len * 0.55,
      yy + i * 1.8,
      48 + len,
      yy + i * 2.8,
      2.6
    );
  }

  pop();
}

function drawFoot(x, y, angle) {
  push();
  translate(x, y);
  rotate(angle);

  longBone(-10, 0, 30, 0, 11);

  for (let i = -2; i <= 2; i++) {
    let yy = i * 10;
    let len = 45 - abs(i) * 6;
    longBone(25, yy * 0.4, 48, yy, 4.5);
    longBone(48, yy, 48 + len, yy + i * 2, 3.4);
  }

  pop();
}

function drawBlossoms() {
  for (let site of bloomSites) {
    if (site.x < -60 || site.x > width + 60) continue;
    if (site.y < -60 || site.y > 1580) continue;
    if (random() > (site.terminal ? 0.72 : 0.43)) continue;

    drawBlossom(site.x, site.y, site.s);

    if (random() < 0.28) {
      drawBlossom(
        site.x + random(-18, 18),
        site.y + random(-16, 16),
        site.s * random(0.65, 0.9)
      );
    }
  }
}

function drawBlossom(x, y, s) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  noStroke();

  for (let i = 0; i < 5; i++) {
    push();
    rotate(i * TWO_PI / 5);
    fill(224, 220, 194, random(165, 225));
    ellipse(0, -s * 0.55, s * 0.82, s * 1.18);
    fill(246, 235, 202, 65);
    ellipse(-s * 0.12, -s * 0.72, s * 0.25, s * 0.48);
    pop();
  }

  fill(164, 132, 72, 225);
  ellipse(0, 0, s * 0.42, s * 0.42);
  fill(235, 204, 130, 180);
  ellipse(-s * 0.07, -s * 0.08, s * 0.14, s * 0.14);

  pop();
}

function drawDriftingPetals() {
  for (let i = 0; i < 125; i++) {
    let x = randomGaussian(790, 350);
    let y = random(260, 1880);

    if (x < 20 || x > 1580) continue;

    let s = random(3, 10);
    let alpha = map(y, 260, 1880, 175, 70);
    drawPetal(x, y, s, random(TWO_PI), alpha);
  }

  for (let i = 0; i < 48; i++) {
    let x = random(180, 1450);
    let y = random(1480, 1870);
    drawPetal(x, y, random(3, 8), random(TWO_PI), random(55, 130));
  }
}

function drawPetal(x, y, s, a, alpha) {
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(224, 216, 184, alpha);

  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.9, -s * 0.5, s * 0.75, s * 0.65, 0, s);
  bezierVertex(-s * 0.3, s * 0.35, -s * 0.4, -s * 0.55, 0, -s);
  endShape(CLOSE);

  pop();
}

function paintVignette() {
  let ctx = drawingContext;
  let v = ctx.createRadialGradient(800, 970, 480, 800, 970, 1370);
  v.addColorStop(0, "rgba(0,0,0,0)");
  v.addColorStop(0.7, "rgba(2,7,9,0.10)");
  v.addColorStop(1, "rgba(2,6,8,0.53)");
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);
}

function paintGrain() {
