  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  let sky = ctx.createLinearGradient(0, 0, 0, height);
  sky.addColorStop(0, "#10131d");
  sky.addColorStop(0.28, "#202b36");
  sky.addColorStop(0.43, "#526064");
  sky.addColorStop(0.55, "#263b42");
  sky.addColorStop(1, "#071217");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, width, height);

  // Dry, horizontal marks in the night sky.
  for (let i = 0; i < 7000; i++) {
    let x = random(width);
    let y = random(0, 930);
    let n = noise(x * 0.003, y * 0.004);
    if (n > 0.52) {
      stroke(126, 137, 139, random(3, 13));
    } else {
      stroke(3, 8, 17, random(4, 16));
    }
    strokeWeight(random(1, 5));
    line(x, y, x + random(8, 75), y + random(-3, 3));
  }

  // A sparse, almost erased firmament.
  noStroke();
  for (let i = 0; i < 75; i++) {
    let x = random(60, 1540);
    let y = random(50, 690);
    let a = random(18, 85) * (1 - y / 1000);
    fill(211, 211, 190, a);
    ellipse(x, y, random(1, 2.8));
  }

  // Moon and its wide, subdued halo.
  const mx = 1010;
  const my = 405;
  noStroke();
  for (let r = 300; r > 110; r -= 6) {
    fill(211, 204, 172, map(r, 300, 110, 0.4, 9));
    ellipse(mx, my, r * 2);
  }

  let moon = ctx.createRadialGradient(970, 365, 8, mx, my, 112);
  moon.addColorStop(0, "#e2dcc0");
  moon.addColorStop(0.65, "#c9c6ac");
  moon.addColorStop(1, "#929b91");
  ctx.fillStyle = moon;
  ctx.beginPath();
  ctx.arc(mx, my, 108, 0, TWO_PI);
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(mx, my, 107, 0, TWO_PI);
  ctx.clip();
  for (let i = 0; i < 520; i++) {
    let x = random(mx - 115, mx + 115);
    let y = random(my - 115, my + 115);
    fill( fifty(), 74, 76, random(2, 13));
    ellipse(x, y, random(3, 28), random(2, 16));
  }
  ctx.restore();

  // A cloud passing beneath the moon, without quite extinguishing it.
  for (let i = 0; i < 120; i++) {
    let x = random(745, 1220);
    let y = random(442, 535);
    stroke(24, 33, 44, random(5, 20));
    strokeWeight(random(3, 15));
    line(x, y, x + random(35, 230), y + random(-5, 5));
  }

  ridge(775, 105, color(35, 47, 53), 2.1);
  ridge(815, 72, color(24, 39, 44), 5.7);
  ridge(850, 48, color(15, 30, 34), 9.2);

  // Water.
  let water = ctx.createLinearGradient(0, 785, 0, height);
  water.addColorStop(0, "#526262");
  water.addColorStop(0.12, "#283f45");
  water.addColorStop(0.5, "#132a32");
  water.addColorStop(1, "#08191f");
  ctx.fillStyle = water;
  ctx.fillRect(0, 785, width, height - 785);

  for (let i = 0; i < 6800; i++) {
    let y = random(805, height);
    let t = riverT(y);
    let l = edgeL(y);
    let r = edgeR(y);
    if (r <= l) continue;
    let x = random(l, r);
    let len = random(4, 28 + 150 * t);
    let n = noise(x * 0.008, y * 0.011);
    if (n > 0.52) {
      stroke(103, 124, 123, random(5, 23));
    } else {
      stroke(2, 14, 22, random(7, 30));
    }
    strokeWeight(random(0.7, 2.8));
    line(x, y, x + len, y + random(-2, 2));
  }

  // The reflection is broken into separate touches of light.
  for (let i = 0; i < 1400; i++) {
    let y = random(812, 1840);
    let t = riverT(y);
    let center = lerp(955, 835, t) + 35 * sin(t * 5);
    let spread = 9 + 155 * t;
    let x = center + randomGaussian() * spread * 0.38;
    if (x < edgeL(y) || x > edgeR(y)) continue;
    let len = random(3, 12 + 95 * t);
    stroke(211, 202, 159, random(7, 42) * (1 - 0.28 * t));
    strokeWeight(random(0.8, 3.2));
    line(x - len / 2, y, x + len / 2, y + random(-1.5, 1.5));
  }

  bankShape(-1);
  bankShape(1);

  // Uneven shorelines and dark, grassy bank texture.
  for (let side of [-1, 1]) {
    for (let pass = 0; pass < 3; pass++) {
      noFill();
      stroke(77 + pass * 8, 82 + pass * 6, 67, 30 - pass * 5);
      strokeWeight(2 + pass);
      beginShape();
      for (let y = 805; y <= height + 20; y += 15) {
        let x = bankEdge(side, y) + side * pass * 8;
        vertex(x, y);
      }
      endShape();
    }
  }

  for (let i = 0; i < 7200; i++) {
    let y = random(850, height);
    let t = riverT(y);
    let side = random() < 0.5 ? -1 : 1;
    let edge = bankEdge(side, y);
    let x = edge + side * random(5, 310) * (0.3 + t);
    if (x < -20 || x > width + 20) continue;
    stroke(random(20, 48), random(34, 58), random(32, 48), random(20, 80));
    strokeWeight(random(0.7, 3.5));
    line(x, y, x + random(-12, 12), y - random(2, 24) * (0.4 + t));
  }

  // Mist low enough to touch both land and water.
  noStroke();
  for (let i = 0; i < 75; i++) {
    fill(160, 169, 158, random(2, 9));
    ellipse(random(250, 1370), random(795, 1040), random(220, 950), random(8, 42));
  }

  drawReeds();

  for (let i = 0; i < 58; i++) {
    let y = random(1270, 1990);
    let t = riverT(y);
    let side = random() < 0.5 ? -1 : 1;
    let x = bankEdge(side, y) + side * random(25, 175) * (0.4 + t);
    if (x < 15 || x > width - 15) continue;
    drawFlower(x, y, random(30, 75) + 55 * t, 3.2 + 5.5 * t);
  }

  // Petals already given to the current.
  noStroke();
  for (let i = 0; i < 25; i++) {
    let y = random(1250, 1920);
    let x = riverCenter(y) + random(-180, 180) * riverT(y);
    if (x < edgeL(y) || x > edgeR(y)) continue;
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(199, 197, 166, random(35, 105));
    ellipse(0, 0, random(3, 8), random(7, 15));
    pop();
  }

  drawWake();

  // Shadow and dark reflection beneath the empty hull.
  push();
  translate(880, 1474);
  rotate(-0.12);
  noStroke();
  fill(0, 7, 12, 95);
  hullPath(1.05);
  pop();

  push();
  translate(865, 1450);
  rotate(-0.12);

  fill(78, 73, 61);
  stroke(151, 140, 109, 175);
  strokeWeight(4);
  hullPath(1);

  noStroke();
  fill(19, 29, 32);
  hullPath(0.82);

  noFill();
  stroke(190, 175, 133, 85);
  strokeWeight(3);
  hullPath(0.98);

  // Long inner planks.
  stroke(113, 104, 80, 135);
  strokeWeight(3);
  bezier(-4, -225, -92, -135, -127, 55, -77, 183);
  bezier(4, -225, 92, -135, 127, 55, 77, 183);

  stroke(56, 62, 56, 180);
  strokeWeight(2);
  bezier(-12, -204, -67, -115, -91, 65, -55, 192);
  bezier(12, -204, 67, -115, 91, 65, 55, 192);

  // Ribs visible in the hollow.
  noFill();
  stroke(105, 101, 81, 100);
  for (let yy of [-145, 5, 153]) {
    arc(0, yy, yy === 5 ? 218 : 175, 54, 0.08 * PI, 0.92 * PI);
  }

  // Two vacant seats.
  noStroke();
  fill(104, 93, 70);
  quad(-91, -89, 91, -89, 99, -55, -99, -55);
  fill(91, 82, 64);
  quad(-105, 72, 105, 72, 103, 108, -103, 108);

  stroke(184, 164, 118, 75);
  strokeWeight(2);
  line(-87, -86, 87, -86);
  line(-99, 75, 99, 75);
  stroke(38, 39, 34, 120);
  line(-79, -70, 80, -70);
  line(-89, 93, 89, 93);

  // An unattended oar resting inside the boat.
  push();
  translate(39, 3);
  rotate(0.075);
  stroke(132, 116, 83, 190);
  strokeWeight(7);
  line(0, -187, 0, 188);
  noStroke();
  fill(112, 99, 73);
  beginShape();
  vertex(-7, 174);
  vertex(7, 174);
  vertex(18, 228);
  vertex(0, 247);
  vertex(-18, 228);
  endShape(CLOSE);
  stroke(185, 161, 111, 65);
  strokeWeight(1.5);
  line(-1, -176, -1, 225);
  pop();

  pop();

  // Ripples at the bow, then silence.
  noFill();
  stroke(183, 188, 165, 38);
  strokeWeight(2);
  arc(833, 1205, 128, 38, 1.12 * PI, 1.88 * PI);
  arc(833, 1212, 190, 55, 1.15 * PI, 1.85 * PI);

  let vignette = ctx.createRadialGradient(800, 960, 360, 800, 960, 1270);
  vignette.addColorStop(0, "rgba(2,5,9,0)");
  vignette.addColorStop(0.72, "rgba(2,5,9,0.12)");
  vignette.addColorStop(1, "rgba(1,4,8,0.7)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // Fine pigment grain over the completed image.
  for (let i = 0; i < 28000; i++) {
    let v = random() < 0.5 ? 230 : 0;
    stroke(v, v, v, random(2, 8));
    strokeWeight(random(0.5, 1.3));
    point(random(width), random(height));
  }
}

function fifty() {
  return 57;
}

function ridge(base, amp, c, off) {
  noStroke();
  fill(c);
  beginShape();
  vertex(-30, 930);
  for (let x = -30; x <= width + 30; x += 18) {
    let y = base - amp * noise(x * 0.003 + off, off)
      - 19 * noise(x * 0.012, off + 4);
    vertex(x, y);
  }
  vertex(width + 30, 980);
  vertex(-30, 980);
  endShape(CLOSE);
}

function riverT(y) {
  return constrain((y - 800) / 1200, 0, 1);
}

function riverCenter(y) {
  let t = riverT(y);
  return 800 + 130 * sin(t * 3.4) - 50 * t;
}

function riverHalf(y) {
  let t = riverT(y);
  return 55 + 780 * pow(t, 1.35);
}

function edgeL(y) {
  return riverCenter(y) - riverHalf(y);
}

function edgeR(y) {
  return riverCenter(y) + riverHalf(y);
}

function bankEdge(side, y) {
  let t = riverT(y);
  let rough = (noise(y * 0.012, side * 4.3) - 0.5) * (8 + 45 * t);
  return side < 0 ? edgeL(y) + rough : edgeR(y) + rough;
}

function bankShape(side) {
  noStroke();
  fill(side < 0 ? color(9, 20, 21) : color(8, 18, 19));
  beginShape();
  if (side < 0) {
    vertex(-25, 780);
    for (let y = 780; y <= height + 20; y += 12) {
      vertex(bankEdge(side, y), y);
    }
    vertex(-25, height + 25);
  } else {
    vertex(width + 25, 780);
    for (let y = 780; y <= height + 20; y += 12) {
      vertex(bankEdge(side, y), y);
    }
    vertex(width + 25, height + 25);
  }
  endShape(CLOSE);
}

function drawReeds() {
  for (let i = 0; i < 540; i++) {
    let y = 950 + pow(random(), 0.62) * 1050;
    let t = riverT(y);
    let side = random() < 0.5 ? -1 : 1;
    let x = bankEdge(side, y) + side * random(0, 170) * (0.25 + t);
    if (x < -40 || x > width + 40) continue;

    let h = random(25, 70) + t * random(35, 215);
    let lean = random(-45, 45) * (0.3 + t);
    let tx = x + lean;
    let ty = y - h;

    noFill();
    stroke(random(13, 31), random(25, 43), random(25, 36), random(130, 230));
    strokeWeight(random(0.8, 2.2) + t * 1.4);
    bezier(x, y, x + lean * 0.1, y - h * 0.35,
      x + lean * 0.8, y - h * 0.75, tx, ty);

    if (random() < 0.17) {
      push();
      translate(tx, ty);
      rotate(lean * 0.012);
      noStroke();
      fill(38, 43, 34, 210);
      ellipse(0, 0, 4 + 5 * t, 17 + 19 * t);
      pop();
    }

    if (random() < 0.25) {
      stroke(27, 42, 34, 145);
      strokeWeight(1 + t);
      bezier(x, y, x - lean * 0.3, y - h * 0.25,
        x - 25 * t, y - h * 0.5, x - 38 * t, y - h * 0.58);
    }
  }
}

function drawFlower(x, y, h, s) {
  let lean = random(-18, 18);
  noFill();
  stroke( seventy(), 96, 73, 155);
  strokeWeight(1.4);
  bezier(x, y, x - 3, y - h * 0.4,
    x + lean, y - h * 0.7, x + lean, y - h);

  push();
  translate(x + lean, y - h);
  rotate(random(TWO_PI));
  noStroke();
  for (let k = 0; k < 5; k++) {
    push();
    rotate(k * TWO_PI / 5);
    fill(198, 201, 179, random(115, 190));
    ellipse(0, -s * 0.62, s * 0.72, s * 1.18);
    pop();
  }
  fill(158, 144, 100, 180);
  ellipse(0, 0, s * 0.65);
  pop();
}

function seventy() {
  return 73;
}

function drawWake() {
  noFill();
  for (let i = 0; i < 17; i++) {
    let cy = 1685 + i * 20;
    let cx = 895 - i * 3;
    stroke(142, 161, 155, 32 - i * 1.25);
    strokeWeight(1.2 + i * 0.05);
    arc(cx, cy, 240 + i * 43, 30 + i * 4,
      0.08 * PI, 0.92 * PI);
  }

  for (let i = 0; i < 8; i++) {
    stroke(117, 143, 143, 22 - i);
    strokeWeight(1.4);
    bezier(760 - i * 3, 1570 + i * 10,
      650 - i * 14, 1710,
      560 - i * 20, 1830,
      430 - i * 24, 1990);
    bezier(1000 + i * 3, 1570 + i * 10,
      1100 + i * 13, 1710,
      1200 + i * 18, 1830,
      1370 + i * 21, 1990);
  }
}

function hullPath(sc) {
  beginShape();
  vertex(0, -260 * sc);
  bezierVertex(100 * sc, -180 * sc, 155 * sc, -30 * sc, 140 * sc, 110 * sc);
  bezierVertex(130 * sc, 205 * sc, 80 * sc, 250 * sc, 0, 260 * sc);
  bezierVertex(-80 * sc, 250 * sc, -130 * sc, 205 * sc, -140 * sc, 110 * sc);
  bezierVertex(-155 * sc, -30 * sc, -100 * sc, -180 * sc, 0, -260 * sc);
  endShape(CLOSE);
}

let twigs = [];

function setup() {
