      61 + n * 35,
      69 + n * 30,
      random(2, 10)
    );
    strokeWeight(random(1, 8));
    line(x, y, x + random(35, 260), y + random(-3, 3));
  }

  noStroke();
  for (let r = 680; r > 390; r -= 10) {
    const a = map(r, 680, 390, 0, 18);
