  bezierVertex(460, 1475, 490, 1500, 505, 1522);
  bezierVertex(575, 1482, 680, 1472, 780, 1490);
  bezierVertex(860, 1500, 920, 1528, 990, 1532);
  bezierVertex(1080, 1534, 1160, 1550, 1228, 1582);
  bezierVertex(1250, 1593, 1265, 1612, 1240, 1628);
  bezierVertex(1170, 1650, 1070, 1642, 982, 1648);
  bezierVertex(860, 1660, 790, 1680, 700, 1670);
  bezierVertex(615, 1660, 560, 1632, 505, 1628);
  bezierVertex(450, 1650, 390, 1645, 354, 1608);
  endShape(CLOSE);

  fill(53, 59, 58, 42);
  ellipse(407, 1556, 76, 96);

  noFill();
  stroke(202, 194, 169, 58);
  strokeWeight(4);
  bezier(500, 1525, 610, 1485, 700, 1490, 790, 1512);
  stroke(199, 190, 165, 35);
  strokeWeight(3);
  bezier(540, 1550, 650, 1530, 720, 1575, 805, 1648);
  bezier(720, 1510, 790, 1540, 830, 1590, 850, 1660);
  bezier(895, 1540, 960, 1575, 1040, 1585, 1155, 1618);
  stroke(45, 50, 49, 48);
  bezier(488, 1580, 590, 1605, 625, 1635, 710, 1660);

  for (let i = 0; i < 18; i++) {
    const side = i % 2 === 0 ? -1 : 1;
    const x0 = 742 + random(-30, 30);
    const y0 = 1540 + random(-10, 35);
    const x3 = 742 + side * random(120, 590);
    const y3 = random(1630, 1830);
    const x1 = x0 + side * random(20, 90);
