  }
}

function branch(x, y, len, ang, w, depth) {
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  const bend = random(-0.22, 0.22) * len;
  const cx = (x + x2) / 2 + cos(ang + HALF_PI) * bend;
  const cy = (y + y2) / 2 + sin(ang + HALF_PI) * bend;

  noFill();
  stroke(14, 16, 18, 248);
  strokeWeight(w);
  beginShape();
  vertex(x, y);
  quadraticVertex(cx, cy, x2, y2);
  endShape();

  if (w > 5) {
    stroke(119, 84, 52, 30);
    strokeWeight(max(1, w * 0.09));
    beginShape();
    vertex(x, y);
    quadraticVertex(cx, cy, x2, y2);
    endShape();
  }

  if (depth <= 0 || len < 16) {
    twigs.push({ x: x2, y: y2, a: ang });
    return;
  }

  branch(
    x2, y2,
    len * random(0.68, 0.77),
    ang - random(0.20, 0.57),
    w * 0.68,
    depth - 1
  );

  branch(
    x2, y2,
    len * random(0.68, 0.77),
    ang + random(0.20, 0.57),
    w * 0.68,
    depth - 1
  );

  if (depth > 5 && random() < 0.13) {
    branch(
      x2, y2,
      len * random(0.52, 0.64),
      ang + random(-0.16, 0.16),
      w * 0.5,
      depth - 1
    );
  }
}

