}

// "The Last Grain" — a memento mori
// p5.js 1.11 — still image, 1600 x 2000

const W = 1600, H = 2000, CX = 800;
const Y_TOP = 300, Y_WAIST = 1000, Y_BOT = 1700;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  paint();
  noLoop();
}

function paint() {
  background(6, 6, 10);
  drawBackground();
  drawBackGlows();
  drawFloorShadow();
  drawGlassHaze();
  drawBottomSand();
  drawTopSand();
  drawStream();
  drawInteriorDust();
  drawGlass();
  drawCaps();
  drawWisp();
  drawEscapedGrains();
  drawAmbientMotes();
  drawVignette();
  drawGrain();
}

// ---------- geometry ----------

function halfW(y) {
  if (y <= Y_WAIST) {
    let t = constrain((y - Y_TOP) / (Y_WAIST - Y_TOP), 0, 1);
    let u = 1 - t;
    return 40 + 110 * u * u + 233 * 4 * t * u;
  }
  let s = constrain((y - Y_WAIST) / (Y_BOT - Y_WAIST), 0, 1);
  return 40 + 110 * s * s + 233 * 4 * s * (1 - s);
}

function sandSurface(x) {
  let dx = x - CX;
  let peak = 100 * Math.exp(-(dx * dx) / (175 * 175));
  let dune = 40 * (noise(dx * 0.01 + 40) - 0.5);
  let edge = 26 * Math.pow(Math.min(Math.abs(dx) / 300, 1), 2);
  return 1402 - peak + dune + edge;
}

function moundSurface(x) {
  let dx = x - CX;
  return 962 - 26 * Math.exp(-(dx * dx) / (100 * 100)) + 16 * (noise(dx * 0.02 + 80) - 0.5);
}

// ---------- atmosphere ----------

function softBlob(x, y, r, c) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + c[3] + ')');
  g.addColorStop(1, 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',0)');
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function drawBackground() {
  noStroke();
  for (let y = 0; y < H; y += 4) {
    let k = y / H;
    fill(lerp(16, 6, k), lerp(17, 6, k), lerp(25, 10, k));
    rect(0, y, W, 4.5);
  }
  for (let i = 0; i < 26; i++) {
    softBlob(random(W), random(H), random(220, 520), [28, 33, 48, 0.10]);
  }
  for (let i = 0; i < 10; i++) {
    softBlob(random(250, 1350), random(500, 1600), random(260, 620), [72, 48, 30, 0.07]);
  }
  softBlob(190, 260, 460, [44, 52, 76, 0.08]);
}

function drawBackGlows() {
  softBlob(CX, 1120, 640, [150, 104, 58, 0.15]);
  softBlob(CX, 1000, 360, [120, 84, 48, 0.10]);
  softBlob(CX, 1330, 300, [200, 140, 80, 0.08]);
}

function drawFloorShadow() {
  let ctx = drawingContext;
  ctx.save();
  ctx.translate(CX, 1832);
