// Whale Fall - a painting about death
// p5.js 1.11 - still image - 1600 x 2000

const W = 1600;
const H = 2000;
const TX = 780;   // whale pivot
const TY = 770;
const TA = 80;    // degrees, sinking head-down

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);
  paint();
}

function paint() {
  const ctx = drawingContext;
  background(4, 14, 20);
  water(ctx);
  raysOfLight(ctx);
  snowField(1500, 0, H, 34, 3.2, 192, 216, 224);
  fallStreaks(230);
  whale(ctx);
  bubbles();
  plume(ctx);
  abyss(ctx);
  jellies();
  snowField(620, 260, H, 26, 3.4, 205, 228, 233);
  finish(ctx);
}

// ---------- water column: light dies with depth ----------
function water(ctx) {
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, '#315e6b');
  g.addColorStop(0.20, '#1c4250');
  g.addColorStop(0.45, '#0f2a35');
  g.addColorStop(0.72, '#081a24');
  g.addColorStop(1.00, '#040d13');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  let r = ctx.createRadialGradient(730, -480, 80, 730, -480, 1600);
  r.addColorStop(0.00, 'rgba(150,200,208,0.30)');
  r.addColorStop(0.55, 'rgba(130,180,190,0.10)');
  r.addColorStop(1.00, 'rgba(130,180,190,0)');
  ctx.fillStyle = r;
  ctx.fillRect(0, 0, W, 1500);

  r = ctx.createRadialGradient(680, 2100, 100, 680, 2100, 1200);
  r.addColorStop(0.00, 'rgba(45,115,112,0.14)');
  r.addColorStop(1.00, 'rgba(45,115,112,0)');
  ctx.fillStyle = r;
  ctx.fillRect(0, 1200, W, 800);
  ctx.restore();
}

function raysOfLight(ctx) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const beams = [
    [170, 70, 150, 980, 0.050, 0.16],
    [420, 36, 74, 790, 0.066, 0.13],
    [645, 95, 175, 1060, 0.052, 0.11],
    [905, 44, 92, 830, 0.068, 0.09],
    [1130, 74, 125, 920, 0.044, 0.07],
    [1360, 32, 62, 700, 0.054, 0.05],
  ];
  for (const b of beams) {
    const x = b[0], tw = b[1], bw = b[2], len = b[3], a = b[4], sl = b[5];
    ctx.save();
    ctx.translate(x, -40);
    ctx.rotate(sl);
    const g = ctx.createLinearGradient(0, 0, 0, len);
    g.addColorStop(0.0, 'rgba(185,225,228,' + a + ')');
    g.addColorStop(0.55, 'rgba(175,215,220,' + a * 0.42 + ')');
    g.addColorStop(1.0, 'rgba(175,215,220,0)');
    ctx.fillStyle = g;
    ctx.beginPath();
    ctx.moveTo(-tw / 2, 0);
    ctx.lineTo(tw / 2, 0);
    ctx.lineTo(bw / 2, len);
    ctx.lineTo(-bw / 2, len);
    ctx.closePath();
    ctx.fill();
    ctx.restore();
  }
  ctx.restore();
}

// ---------- drifting snow of the deep ----------
function snowField(n, y0, y1, aMax, sMax, cr, cg, cb) {
  noStroke();
