// ---------- the whale ----------
function whale(ctx) {
  ctx.save();
  push();
  translate(TX, TY);
  rotate(radians(TA));

  const body = new Path2D();
  traceBody(body);
  const fluke = new Path2D();
  traceFluke(fluke);
  const flipper = new Path2D();
  traceFlipper(flipper);

  // ghost-light halo
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineJoin = 'round';
  ctx.lineWidth = 100;
  ctx.strokeStyle = 'rgba(150,185,195,0.045)';
  ctx.stroke(body);
  ctx.stroke(fluke);
  ctx.lineWidth = 36;
  ctx.strokeStyle = 'rgba(175,210,220,0.10)';
  ctx.stroke(body);
  ctx.stroke(fluke);
  ctx.restore();

  // body: pale at the tail (still near light), dim at the head (leading into dark)
  let g = ctx.createLinearGradient(-620, -70, 600, 70);
  g.addColorStop(0.00, '#b7d0d7');
  g.addColorStop(0.35, '#93b0ba');
  g.addColorStop(0.75, '#6d8b96');
  g.addColorStop(1.00, '#516671');
  ctx.fillStyle = g;
  ctx.fill(body);

  // fluke: highest part, catching the last of the surface light
  g = ctx.createLinearGradient(-470, 0, -700, 0);
  g.addColorStop(0.0, '#9db8c0');
  g.addColorStop(0.55, '#c3d9de');
  g.addColorStop(1.0, '#d8e9ec');
  ctx.fillStyle = g;
  ctx.fill(fluke);

  // painterly work, clipped inside the shapes
  ctx.save();
  ctx.clip(body);
  paintBodyDetail();
  ctx.restore();
  ctx.save();
  ctx.clip(fluke);
  paintFlukeDetail();
  ctx.restore();

  // rim light along the light-facing edges
  const rim = ctx.createLinearGradient(620, 90, -690, -170);
  rim.addColorStop(0.0, 'rgba(205,228,232,0.06)');
  rim.addColorStop(0.6, 'rgba(215,238,242,0.28)');
  rim.addColorStop(1.0, 'rgba(228,246,250,0.55)');
  ctx.lineWidth = 4;
  ctx.strokeStyle = rim;
  ctx.stroke(body);
  ctx.lineWidth = 3.5;
  ctx.stroke(fluke);

  // pectoral flipper, in shadow, drawn last (nearest)
  g = ctx.createLinearGradient(310, 40, 40, 270);
  g.addColorStop(0.0, 'rgba(46,68,78,0.97)');
  g.addColorStop(1.0, 'rgba(26,45,55,0.92)');
  ctx.fillStyle = g;
  ctx.fill(flipper);
  ctx.lineWidth = 2.5;
  ctx.strokeStyle = 'rgba(125,158,168,0.35)';
  ctx.stroke(flipper);
  ctx.save();
  ctx.clip(flipper);
