// life arriving at the body
function colonize(ctx) {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  noStroke();
  // faint luminous mats beginning
  for (let i = 0; i < 6; i++) {
    glowDot(random(-260, 330), random(-30, 90), random(70, 130), random(0.06, 0.12), pickGlow(2));
  }
  // lights gathering along each rib
  for (let x = 300; x >= -140; x -= 55) {
    const n = 4 + floor(random(4));
    for (let i = 0; i < n; i++) {
      const t = random(0.15, 0.97);
      const u = 1 - t;
      const gx = u * u * x + 2 * u * t * (x + 34) + t * t * (x - 52) + random(-16, 16);
      const gy = u * u * -56 + 2 * u * t * 8 + t * t * 64 + random(-13, 13);
      glowDot(gx, gy, random(7, 26), random(0.25, 0.55), pickGlow(1));
    }
  }
  // sparks leaving the belly, joining the descent
  for (let i = 0; i < 26; i++) {
    const x = random(-300, 340);
    const by = bellyY(x);
    glowDot(x + random(-30, 30), by + random(6, 60), random(3, 9), random(0.22, 0.5), pickGlow(1));
  }
  // a few at the mouth
  for (let i = 0; i < 10; i++) {
    const t = random();
    glowDot(lerp(545, 310, t) + random(-25, 25), lerp(4, 58, t) + random(-18, 18), random(3, 8), random(0.2, 0.45), pickGlow(1));
  }
  ctx.restore();
}

function pickGlow(kind) {
  const r = random();
  if (kind === 2) return r < 0.7 ? [120, 190, 178] : [150, 180, 170];
  if (r < 0.72) return [186, 240, 226];
  if (r < 0.88) return [140, 222, 208];
  if (r < 0.96) return [110, 205, 220];
  return [238, 226, 196];
}

function bellyY(x) {
  const pts = [[-340, 68], [-200, 92], [-120, 102], [0, 106], [150, 104], [350, 88], [500, 44], [560, 6]];
  if (x <= pts[0][0]) return 40;
  for (let i = 1; i < pts.length; i++) {
    if (x <= pts[i][0]) {
      const t = (x - pts[i - 1][0]) / (pts[i][0] - pts[i - 1][0]);
      return lerp(pts[i - 1][1], pts[i][1], t);
    }
  }
  return 0;
}

function glowDot(x, y, r, ca, col) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0.0, 'rgba(' + col[0] + ',' + col[1] + ',' + col[2] + ',' + ca + ')');
  g.addColorStop(0.4, 'rgba(' + col[0] + ',' + col[1] + ',' + col[2] + ',' + ca * 0.32 + ')');
  g.addColorStop(1.0, 'rgba(' + col[0] + ',' + col[1] + ',' + col[2] + ',0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
  if (ca > 0.45 && random() < 0.6) {
    noStroke();
    fill(236, 252, 248, min(255, ca * 220));
    circle(x + random(-1.5, 1.5), y + random(-1.5, 1.5), random(1.5, 3.2));
  }
}

