    if (pick < 0.32) {
      let a = random(Math.PI * 2), rr = Math.sqrt(random());
      x0 = 800 + Math.cos(a) * 30 * rr;
      y0 = 1149 + Math.sin(a) * 36 * rr;
    } else if (pick < 0.45) {
      y0 = random(1206, 1262);
      x0 = 800 + random(-1, 1) * hw(y0);
    } else {
      y0 = random(1262, 1335);
      x0 = 800 + random(-1, 1) * hw(y0) * 0.92;
    }
    let base = Math.min(Math.max((y0 - 1340) / (1112 - 1340), 0), 1);
    let t = base * random(0.35, 1.1) + (noise(x0 * 0.01, y0 * 0.01, 1) - 0.5) * 0.3;
