      let r = 2.3 * (1 - j * 0.09);
      ellipse(pos[0], pos[1], r, r);
    }
  }
  blendMode(BLEND);

  // ---------------- ash sifting back down ----------------
  noStroke();
  for (let i = 0; i < 90; i++) {
    let x = 800 + (random() + random() - 1) * 520;
    let y = random(1180, 1608);
    fill(196, 190, 182, random(35, 120));
    ellipse(x, y, random(0.8, 2.2), random(0.7, 1.8));
  }
  for (let i = 0; i < 80; i++) {
    let x = 800 + (random() + random() - 1) * 300;
