  // ---------------- vignette ----------------
  let vg = ctx.createRadialGradient(800, 980, 620, 800, 980, 1560);
  vg.addColorStop(0, 'rgba(4,5,9,0)');
  vg.addColorStop(1, 'rgba(4,5,9,0.42)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
  let bgd = ctx.createLinearGradient(0, 1780, 0, H);
  bgd.addColorStop(0, 'rgba(0,0,0,0)');
  bgd.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = bgd;
  ctx.fillRect(0, 1780, W, 220);

  // ---------------- grain of the canvas ----------------
  loadPixels();
  let px = pixels;
  let sd = 88675123;
  for (let i = 0; i < px.length; i += 4) {
    sd ^= sd << 13; sd ^= sd >>> 17; sd ^= sd << 5;
    let v = (((sd >>> 0) % 2000) / 1000 - 1) * 7.5;
    px[i] += v; px[i + 1] += v; px[i + 2] += v;
  }
  updatePixels();
}

// ---------- helpers ----------

function crestY(x) {
  return 1668 - 70 * Math.exp(-((x - 800) * (x - 800)) / 441800);
}

function ramp(stops, y) {
  if (y <= stops[0][0]) return stops[0].slice(1);
  for (let i = 0; i < stops.length - 1; i++) {
    if (y >= stops[i][0] && y <= stops[i + 1][0]) {
      let f = (y - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return [lerp(stops[i][1], stops[i + 1][1], f),
              lerp(stops[i][2], stops[i + 1][2], f),
              lerp(stops[i][3], stops[i + 1][3], f)];
    }
  }
  return stops[stops.length - 1].slice(1);
}

function softBlob(cx, cy, w, h, r, g, b, a) {
  let ctx = drawingContext;
  push();
  translate(cx, cy);
  scale(w / 200, h / 200);
  let gr = ctx.createRadialGradient(0, 0, 0, 0, 0, 100);
  gr.addColorStop(0, 'rgba(' + r + ',' + g + ',' + b + ',' + a + ')');
  gr.addColorStop(0.55, 'rgba(' + r + ',' + g + ',' + b + ',' + (a * 0.6) + ')');
  gr.addColorStop(1, 'rgba(' + r + ',' + g + ',' + b + ',0)');
  ctx.fillStyle = gr;
  ctx.beginPath();
  ctx.arc(0, 0, 100, 0, Math.PI * 2);
  ctx.fill();
  pop();
}

function bird(x, y, s) {
  push();
  translate(x, y);
  rotate(random(-0.22, 0.22));
  scale(s / 40);
  noFill();
  stroke(12, 13, 18, 235);
  strokeWeight(3.1);
  beginShape();
  vertex(-40, 2);
  bezierVertex(-22, -17, -8, -5, 0, 0);
  bezierVertex(8, -5, 22, -17, 40, 2);
  endShape();
  stroke(12, 13, 18, 120);
  strokeWeight(2.4);
  beginShape();
  vertex(-36, 7);
  bezierVertex(-19, -8, -8, -1, 0, 4);
  bezierVertex(8, -1, 19, -8, 36, 7);
  endShape();
  pop();
}

function tree(x, y, h, depth) {
  branchy(x, y, -HALF_PI + random(-0.06, 0.06), h * 0.36, 6, depth);
}

function branchy(x, y, ang, len, wgt, d) {
  let x2 = x + Math.cos(ang) * len;
  let y2 = y + Math.sin(ang) * len;
  stroke(10, 9, 12, 235);
  strokeWeight(wgt);
  line(x, y, x2, y2);
  if (d <= 0) return;
  let spread = random(0.3, 0.75);
  branchy(x2, y2, ang - spread + random(-0.15, 0.1), len * random(0.6, 0.75), wgt * 0.6, d - 1);
  branchy(x2, y2, ang + spread + random(-0.1, 0.15), len * random(0.6, 0.75), wgt * 0.6, d - 1);
  if (random() < 0.3) {
    branchy(x2, y2, ang + random(-0.35, 0.35), len * random(0.5, 0.65), wgt * 0.5, d - 1);
  }
}

function hw(y) {
  let pts = [[1198, 13], [1212, 22], [1242, 61], [1252, 62], [1285, 63], [1335, 58], [1400, 50], [1458, 45]];
  if (y <= pts[0][0]) return pts[0][1];
  for (let i = 0; i < pts.length - 1; i++) {
    if (y >= pts[i][0] && y <= pts[i + 1][0]) {
      let f = (y - pts[i][0]) / (pts[i + 1][0] - pts[i][0]);
      return lerp(pts[i][1], pts[i + 1][1], f);
    }
  }
  return pts[pts.length - 1][1];
}

function bodyPath(ctx) {
  ctx.beginPath();
  ctx.moveTo(797, 1196);
  ctx.quadraticCurveTo(813, 1198, 815, 1212);
  ctx.quadraticCurveTo(862, 1222, 863, 1252);
  ctx.bezierCurveTo(864, 1288, 858, 1335, 851, 1400);
  ctx.quadraticCurveTo(846, 1432, 846, 1458);
  ctx.quadraticCurveTo(844, 1520, 842, 1588);
  ctx.quadraticCurveTo(842, 1597, 852, 1602);
  ctx.lineTo(812, 1602);
  ctx.quadraticCurveTo(810, 1590, 809, 1560);
  ctx.quadraticCurveTo(807, 1500, 807, 1472);
  ctx.quadraticCurveTo(806, 1462, 800, 1460);
  ctx.closePath();
}

function sparkPos(x0, y0, t) {
  let rise = t * (240 + 560 * t);
  let y = y0 - rise;
  let sw = noise(x0 * 0.004 + 7, y0 * 0.003, t * 0.9 + 0.3) - 0.5;
  let cx = (noise(4.7 + t * 1.3, 9.1, 0.5) - 0.5) * 110 * t;
  let x = x0 + cx + sw * (60 + 560 * t);
  return [x, y];
}

function emberColor(t) {
  let st = [
    [0.0, 55, 22, 16, 0.9],
    [0.22, 140, 52, 22, 0.95],
    [0.45, 214, 104, 36, 0.95],
    [0.70, 248, 176, 92, 0.85],
    [0.90, 255, 226, 178, 0.55],
    [1.05, 255, 246, 228, 0.0]
  ];
  if (t <= st[0][0]) return [st[0][1], st[0][2], st[0][3], st[0][4]];
  for (let i = 0; i < st.length - 1; i++) {
    if (t >= st[i][0] && t <= st[i + 1][0]) {
      let f = (t - st[i][0]) / (st[i + 1][0] - st[i][0]);
      return [lerp(st[i][1], st[i + 1][1], f),
              lerp(st[i][2], st[i + 1][2], f),
              lerp(st[i][3], st[i + 1][3], f),
              lerp(st[i][4], st[i + 1][4], f)];
    }
  }
  let l = st[st.length - 1];
  return [l[1], l[2], l[3], l[4]];
}

// BETWEEN FLAME AND SMOKE
// A nearly spent candle; one guttering flame; the first smoke;
// a moth that has always known the way.

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  paintAll();
}

function draw() {}

// ---- composition anchors ----
const FX = 812;  // flame heart
const FY = 1492;

// ---- helpers ----
function blot(x, y, ang, ln, wd, r, g, b, a) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(r, g, b, a);
  ellipse(0, 0, ln, wd);
  pop();
}

function glowAdd(x, y, R, cr, cg, cb, total) {
  blendMode(ADD);
  noStroke();
  const steps = 84;
  const a = total / steps;
  for (let i = steps; i > 0; i--) {
    const rad = R * i / steps;
    fill(cr, cg, cb, a);
    ellipse(x, y, rad * 2, rad * 2);
  }
  blendMode(BLEND);
}

// ---- the painting ----
function paintAll() {
  background(7, 7, 11);

  ambientDarkness();
  table();
  dishAndCandle();
  smoke();

  glowAdd(790, 175, 400, 130, 165, 215, 34);  // cold light the smoke dissolves toward
  glowAdd(FX, FY, 560, 255, 138, 55, 105);    // the candle's reach
  glowAdd(816, 1512, 190, 255, 185, 110, 70); // heat around the flame

  moth();
  petals();
  flame();
  ashMotes();
  vignette();
  grain();
}

// ---- the darkness breathes ----
function ambientDarkness() {
  for (let i = 0; i < 2400; i++) {
    const x = random(width);
    const y = random(height);
    const tw = noise(x * 0.0012 + 40, y * 0.0012 + 40);
    blot(x, y, random(TWO_PI), random(70, 260), random(20, 70),
         lerp(8, 19, tw), lerp(9, 12, tw), lerp(20, 8, tw), 6);
  }
  for (let i = 0; i < 1400; i++) { // faint vapour drifting high in the dark
    const x = random(width);
    const y = random(1500);
    const a = noise(x * 0.0025, y * 0.0025) * TWO_PI;
    blot(x, y, a, random(50, 170), random(6, 16), 25, 29, 40, 5);
  }
}

// ---- the table and its reflection ----
function table() {
  const TY = 1758;
  for (let i = 0; i < 2200; i++) {
    const y = random(TY, height);
    const x = random(-40, width + 40);
    const refl = exp(-sq(x - 830) / 22000) * max(0, 1 - (y - TY) / 300);
    blot(x, y, random(-0.05, 0.05), random(40, 140), random(3, 10),
         lerp(5, 105, refl), lerp(4, 62, refl), lerp(6, 30, refl), 26);
  }
  glowAdd(830, 1830, 300, 255, 130, 55, 46); // light pooling on the surface
  glowAdd(862, 1912, 120, 255, 120, 50, 26); // a smear of the flame, upside down
}

// ---- the candle ----
function waxCol(x, y) {
  const d = dist(x, y, FX, FY - 20);
  let lum = pow(constrain(1 - d / 340, 0, 1), 2.0);
  const u = (x - 800) / 44;
  lum *= 1 - 0.5 * u * u; // roundness of the wax
  lum = constrain(lum, 0, 1);
  return [lerp(24, 252, lum), lerp(19, 240, lum), lerp(17, 212, lum)];
}

function drip(x0, y0, x1, y1, w0, w1) {
  const n = 46;
  for (let i = 0; i < n; i++) {
    const t = i / (n - 1);
    const x = lerp(x0, x1, t) + (noise(t * 6 + 30) - 0.5) * 5;
    const y = lerp(y0, y1, t);
    const w = lerp(w0, w1, t);
    const c = waxCol(x + (x < 800 ? -6 : 6), y);
    blot(x, y, HALF_PI + random(-0.06, 0.06), w * 1.7, w,
         c[0] * 1.12, c[1] * 1.1, c[2] * 1.08, 110);
  }
  const c = waxCol(x1 + (x1 < 800 ? -6 : 6), y1);
  blot(x1, y1, 0, w0 * 2.1, w0 * 1.35, c[0] * 1.1, c[1] * 1.08, c[2], 140);
}

function dishAndCandle() {
  for (let i = 0; i < 900; i++) { // dish body
    const ang = random(TWO_PI);
    const rr = pow(random(), 0.7);
    blot(800 + cos(ang) * rr * 158, 1752 + sin(ang) * rr * 26,
         random(TWO_PI), random(14, 44), random(6, 16), 11, 9, 8, 40);
  }
  for (let i = 0; i < 250; i++) { // molten wax at the foot
    const ang = random(TWO_PI);
    const rr = pow(random(), 0.8);
    const lum = 1 - rr * 0.7;
    blot(800 + cos(ang) * rr * 66, 1748 + sin(ang) * rr * 12,
         random(TWO_PI), random(8, 22), random(4, 9),
         lerp(30, 220, lum), lerp(22, 150, lum), lerp(16, 80, lum), 34);
  }
  for (let i = 0; i < 220; i++) { // lit crest of the near rim
    const th = random(PI * 0.12, PI * 0.88);
    const lum = 0.35 + 0.65 * sin(th);
    blot(800 + cos(th) * 152, 1752 + sin(th) * 24, th + HALF_PI,
         random(8, 20), random(3, 7),
         lerp(40, 235, lum), lerp(28, 150, lum), lerp(18, 70, lum), 60);
  }
  for (let i = 0; i < 340; i++) { // column underpainting
    const y = random(1548, 1732);
    const wob = (noise(y * 0.02 + 80) - 0.5) * 10;
    const x = random(758 + wob, 842 - wob);
    const c = waxCol(x, y);
    blot(x, y, HALF_PI, random(20, 60), random(6, 14), c[0], c[1], c[2], 90);
  }
  for (let i = 0; i < 2400; i++) { // column strokes
    const y = random(1548, 1734);
    const wob = (noise(y * 0.02 + 80) - 0.5) * 10;
    const x = random(756 + wob, 844 - wob);
    const c = waxCol(x, y);
    blot(x, y, HALF_PI + random(-0.1, 0.1), random(12, 34), random(3, 8),
         c[0], c[1], c[2], random(30, 75));
  }
  for (let i = 0; i < 60; i++) { // the leaning flame kisses the right shoulder
    const y = random(1550, 1650);
    const x = 840 + (noise(y * 0.02 + 80) - 0.5) * 10 + random(-2, 2);
    const c = waxCol(x, y);
    blot(x, y, HALF_PI, random(6, 16), random(2, 4),
         c[0] * 1.25 + 20, c[1] * 1.2 + 15, c[2] * 1.1 + 10, 80);
  }
  for (let i = 0; i < 420; i++) { // the melted crown
    const ang = random(TWO_PI);
    const rr = pow(random(), 0.6);
    const x = 800 + cos(ang) * rr * 54;
    const y = 1546 + sin(ang) * rr * 11 + 6;
    const d = dist(x, y, 818, 1500);
    const lum = pow(constrain(1 - d / 240, 0, 1), 1.1);
    blot(x, y, random(TWO_PI), random(10, 26), random(4, 10),
         lerp(70, 255, lum), lerp(60, 250, lum), lerp(50, 225, lum), 70);
  }
  drip(764, 1552, 760, 1636, 15, 7);
  drip(842, 1552, 845, 1592, 13, 6);
  drip(824, 1554, 826, 1575, 10, 5);

  stroke(14, 10, 9); // the bent wick
  strokeWeight(4.5);
  noFill();
  bezier(800, 1550, 802, 1542, 808, 1534, 817, 1527);
}

// ---- the smoke ----
function smokePath(t) {
  const y = lerp(1416, 150, pow(t, 0.92));
  const sway = sin(t * 4.4 + 0.4) * (14 + 66 * t) + sin(t * 9.3 + 1.2) * 16 * t;
  const wander = (noise(t * 2.7 + 10) - 0.5) * 300 * t;
  const x = 852 + sway + wander - 26 * t;
  const w = 10 + 200 * pow(t, 1.55);
  return { x: x, y: y, w: w };
}

function smoke() {
  noStroke();
  for (let i = 0; i < 9000; i++) {
    const t = random();
    const dis = constrain((t - 0.72) / 0.28, 0, 1);
    if (random() < dis * 0.8) continue; // it forgets its shape on the way
    const p = smokePath(t);
    const p2 = smokePath(min(1, t + 0.02));
    const ang = atan2(p2.y - p.y, p2.x - p.x);
    const off = (random() + random() - 1) * p.w * 0.5;
    const x = p.x + off;
    const y = p.y + random(-10, 10) * (1 + t);
    const litW = pow(1 - t, 2.2);
    const r = lerp(56, 185, litW);
    const g = lerp(62, 148, litW);
    const b = lerp(76, 116, litW);
    const al = lerp(4, 13, pow(1 - t, 1.4));
    const ln = lerp(7, 30, pow(t, 0.8)) * random(0.6, 1.4);
    const wd = lerp(3, 12, t) * random(0.7, 1.3);
    blot(x, y, ang + random(-0.3, 0.3), ln, wd, r, g, b, al);
  }
  for (let i = 0; i < 900; i++) { // last flecks
    const t = random(0.65, 1);
    const p = smokePath(t);
    const x = p.x + (random() + random() - 1) * p.w * 1.1;
    const y = p.y + random(-30, 30);
    const fade = 1 - constrain((t - 0.65) / 0.35, 0, 1) * 0.85;
    blot(x, y, random(TWO_PI), random(2, 5), random(2, 4), 90, 96, 112, 10 * fade);
  }
}

// ---- the moth ----
function moth() {
  const mx = 622, my = 1236;
  const dir = atan2(FY - 60 - my, FX - 20 - mx);
  push();
  translate(mx, my);
  rotate(dir);
  blendMode(ADD);        // warm rim on the flame-facing side
  push();
  translate(6, 2);
  scale(1.07);
  mothShape(255, 160, 80, 70);
  pop();
  blendMode(BLEND);
  mothShape(11, 9, 10, 255); // the dark body
  noFill();
  stroke(11, 9, 10, 255);
  strokeWeight(3);
  bezier(43, -3, 55, -9, 62, -14, 68, -20);
  bezier(43, 3, 55, 7, 62, 11, 68, 14);
  stroke(255, 170, 90, 160);
  strokeWeight(1.6);
  bezier(44, -4, 56, -10, 63, -15, 70, -22);
  bezier(44, 4, 56, 8, 63, 12, 70, 16);
  pop();
  blendMode(ADD); // wing dust
  noStroke();
  for (let i = 0; i < 46; i++) {
    fill(255, 165, 85, random(6, 22));
    ellipse(mx + random(-95, 55), my + random(-85, 85), random(1, 3), random(1, 3));
  }
  blendMode(BLEND);
}

function mothShape(r, g, b, a) {
  noStroke();
  fill(r, g, b, a);
  beginShape(); // upper wing
  vertex(10, -5);
  bezierVertex(-6, -34, -38, -68, -60, -76);
  bezierVertex(-72, -58, -58, -26, -34, -10);
  bezierVertex(-22, -6, -8, -5, 10, -5);
  endShape(CLOSE);
  beginShape(); // lower wing
  vertex(10, 6);
  bezierVertex(-4, 28, -24, 54, -36, 62);
  bezierVertex(-44, 46, -32, 22, -14, 10);
  bezierVertex(-6, 7, 2, 6, 10, 6);
  endShape(CLOSE);
  ellipse(2, 0, 64, 16);  // abdomen
  ellipse(30, 0, 22, 15); // thorax
  ellipse(38, 0, 13, 12); // head
}

// ---- fallen petals, ash ----
function petals() {
  petal(1075, 1848, 1.5, 0.65);
  petal(1200, 1902, 1.15, -0.45);
  petal(985, 1905, 1.0, 0.9);
  for (let i = 0; i < 40; i++) {
    blot(random(760, 1010), random(1790, 1870), random(TWO_PI),
         random(2, 6), random(1, 3), 90, 85, 75, random(20, 60));
  }
}

function petal(x, y, s, rot) {
  const d = dist(x, y, 812, 1600);
  const lit = constrain(1.25 - d / 500, 0.12, 1);
  push();
  translate(x, y);
  rotate(rot);
  scale(s);
  noStroke();
  fill(13, 9, 8, 255);
  beginShape();
  vertex(0, -16);
  bezierVertex(13, -8, 13, 10, 0, 18);
  bezierVertex(-13, 10, -13, -8, 0, -16);
  endShape(CLOSE);
  blendMode(ADD); // the edge that still catches the light
  noFill();
  stroke(255, 150, 70, 140 * lit);
  strokeWeight(2.2);
  beginShape();
  vertex(-13, 0);
  bezierVertex(-13, -8, -10, -13, 0, -16);
  endShape();
  beginShape();
  vertex(-13, 0);
  bezierVertex(-13, 8, -10, 13, 0, 18);
  endShape();
  blendMode(BLEND);
  pop();
}

// ---- the flame ----
function flameX(t) { return lerp(810, 852, pow(t, 1.3)); }
function flameY(t) { return lerp(1532, 1416, t); }
function flameAng() { return atan2(-116, 42); }
function flameW(t) {
  return (10 + 30 * pow(max(0, sin(PI * pow(t, 0.62))), 1.1)) * pow(1 - t, 0.55) + 4;
}

function flame() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 500; i++) { // aura of the fire
    const t = pow(random(), 0.7);
    const wout = flameW(t) * (1.7 + random() * 0.8);
    const x = flameX(t) + (random() + random() - 1) * wout * 0.5;
    blot(x, flameY(t) + random(-8, 8), flameAng() + random(-0.25, 0.25),
         random(10, 26), random(6, 14), 150, 45, 8, 10);
  }
  for (let i = 0; i < 1700; i++) { // body of the fire
    const t = pow(random(), 0.85);
    const w = flameW(t);
    const q = abs(random() + random() - 1);
    const x = flameX(t) + (random() + random() - 1) * w * 0.5;
    const heat = constrain((1 - q) * (1 - t * 0.75), 0, 1);
    const r = lerp(200, 255, heat);
    const g = lerp(60, 238, pow(heat, 1.35));
    const b = lerp(10, 190, pow(heat, 2.2));
    const al = lerp(14, 40, heat);
    blot(x, flameY(t) + random(-7, 7), flameAng() + random(-0.2, 0.2),
         random(9, 22) * (1.2 - t * 0.5), random(4, 9), r, g, b, al);
  }
  glowAdd(824, 1514, 30, 255, 235, 180, 200); // white heart
  blendMode(ADD);
  for (let i = 0; i < 60; i++) { // blue root at the wick
    blot(815 + random(-14, 14), 1528 + random(-8, 4), flameAng(),
         random(6, 14), random(4, 8), 30, 90, 255, 14);
  }
  noStroke();
  fill(255, 225, 170, 230); // ember on the wick's tip
  ellipse(817, 1527, 7, 7);
  blendMode(BLEND);
}

// ---- embers and ash adrift ----
function ashMotes() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 110; i++) {
    let x, y;
    if (i < 70) {
      const t = random(0.15, 1);
      const p = smokePath(t);
      x = p.x + (random() + random() - 1) * p.w * 1.7;
      y = p.y + random(-40, 40);
    } else {
      x = random(width);
      y = random(1400);
    }
    fill(255, 160, 90, random(5, 20));
    ellipse(x, y, random(1, 2.6), random(1, 2.6));
  }
  blendMode(BLEND);
}

// ---- vignette ----
function vignette() {
  const vg = createGraphics(width, height);
  const ctx = vg.drawingContext;
  const grd = ctx.createRadialGradient(800, 1050, 430, 800, 1050, 1500);
  grd.addColorStop(0, 'rgba(0,0,0,0)');
  grd.addColorStop(0.55, 'rgba(2,2,6,0.18)');
  grd.addColorStop(1, 'rgba(2,2,6,0.78)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, width, height);
  image(vg, 0, 0);
}

// ---- canvas tooth ----
function grain() {
  noStroke();
  for (let i = 0; i < 38000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.6) {
      const v = random(0, 45);
      fill(v, v, v, random(3, 9));
    } else {
      const v = random(120, 230);
      fill(v, v, v, random(2, 6));
    }
    rect(x, y, 1.5, 1.5);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function poolHalfW(y) {
  const H = 2000;
  let t = constrain((y - 1414) / (H - 1414), 0, 1);
  return 124 + 330 * pow(t, 1.2);
}

function draw() {
  const W = 1600, H = 2000;
  const HORIZON = 1260;
  const ctx = drawingContext;
  background(12, 12, 24);

  // ---------- SKY ----------
  let sky = ctx.createLinearGradient(0, 0, 0, HORIZON);
  sky.addColorStop(0.0, '#12132e');
  sky.addColorStop(0.35, '#2b2350');
  sky.addColorStop(0.62, '#5c3a63');
  sky.addColorStop(0.82, '#b85f4d');
  sky.addColorStop(1.0, '#e89a58');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, HORIZON + 2);

  // stars
  noStroke();
  for (let i = 0; i < 260; i++) {
    let x = random(W);
    let y = random(0, HORIZON * 0.72);
    let a = map(y, 0, HORIZON * 0.72, 220, 15);
    fill(232, 236, 255, a);
    circle(x, y, random(1, 2.6));
  }

  // hazy moon
  let mg = ctx.createRadialGradient(330, 330, 10, 330, 330, 180);
  mg.addColorStop(0, 'rgba(235,230,210,0.35)');
  mg.addColorStop(1, 'rgba(235,230,210,0)');
  ctx.fillStyle = mg;
  ctx.fillRect(150, 150, 360, 360);
  fill(235, 230, 210, 185);
  circle(330, 330, 88);

  // thin clouds
  for (let i = 0; i < 40; i++) {
    let x = random(W), y = random(200, HORIZON - 100);
    let w = random(120, 420), h = random(14, 40);
    let warm = map(y, 200, HORIZON - 100, 0, 1);
    let c = lerpColor(color(60, 50, 100), color(255, 150, 90), warm);
    fill(red(c), green(c), blue(c), random(18, 42));
    ellipse(x, y, w, h);
  }

  // distant birds
  stroke(20, 18, 40, 160);
  strokeWeight(3);
  noFill();
  const birds = [[1120, 430, 1], [1210, 385, 0.8], [1300, 455, 1.2], [1050, 500, 0.7], [1260, 320, 0.6]];
  for (const b of birds) {
    let bx = b[0], by = b[1], w = 16 * b[2];
    beginShape();
    vertex(bx - w, by);
    quadraticVertex(bx - w * 0.5, by - w * 0.55, bx, by);
    quadraticVertex(bx + w * 0.5, by - w * 0.55, bx + w, by);
    endShape();
  }

  // ---------- HILLS ----------
  noStroke();
  fill(22, 31, 26);
  beginShape();
  vertex(0, HORIZON + 60);
  for (let x = 0; x <= W; x += 10) {
    let y = HORIZON - 20 - noise(x * 0.003) * 110 - noise(x * 0.012 + 50) * 45;
    vertex(x, y);
  }
  vertex(W, HORIZON + 60);
  endShape(CLOSE);

  // ---------- FIELD ----------
  let fg = ctx.createLinearGradient(0, HORIZON - 60, 0, H);
  fg.addColorStop(0, '#2a3a2c');
  fg.addColorStop(0.25, '#223126');
  fg.addColorStop(1, '#0d1510');
  ctx.fillStyle = fg;
  ctx.fillRect(0, HORIZON - 60, W, H - HORIZON + 60);

  // dark grass
  for (let i = 0; i < 6500; i++) {
    let x = random(W);
    let t = random(1);
    let y = HORIZON + 10 + pow(t, 1.6) * (H - HORIZON - 10);
    let h = map(y, HORIZON, H, 4, 55) * random(0.6, 1.3);
    let sway = (noise(x * 0.01, y * 0.01) - 0.5) * 10;
    let c = lerpColor(color(24, 36, 28), color(58, 82, 60), noise(x * 0.005, y * 0.005));
    stroke(red(c), green(c), blue(c), random(140, 220));
    strokeWeight(map(y, HORIZON, H, 1, 2.6));
    line(x, y, x + sway, y - h);
  }

  // ---------- LIGHT POOL ON GROUND ----------
  blendMode(ADD);
  for (let y = 1414; y < H; y += 6) {
    let t = (y - 1414) / (H - 1414);
    let halfW = 124 + 330 * pow(t, 1.2);
    let a = 70 * (1 - t * 0.8) + 8;
    noStroke();
    fill(255, 190, 100, a);
    rect(890 - halfW, y, halfW * 2, 6);
  }
  let hg = ctx.createRadialGradient(890, 1414, 10, 890, 1414, 320);
  hg.addColorStop(0, 'rgba(255,220,150,0.55)');
  hg.addColorStop(1, 'rgba(255,220,150,0)');
  ctx.fillStyle = hg;
  ctx.fillRect(570, 1094, 640, 640);
  blendMode(BLEND);

  // warm-lit grass inside the pool
  for (let i = 0; i < 2200; i++) {
    let y = random(1418, H);
    let hw = poolHalfW(y);
    let x = 890 + random(-1, 1) * hw * 0.98;
    let t = (y - 1414) / (H - 1414);
    let h = map(y, 1414, H, 10, 60) * random(0.6, 1.2);
    let sway = (noise(x * 0.01, y * 0.01) - 0.5) * 12;
    let warm = lerpColor(color(120, 100, 40), color(255, 205, 120), random(0.2, 1) * (1 - t * 0.4));
    stroke(red(warm), green(warm), blue(warm), random(120, 200));
    strokeWeight(map(y, 1414, H, 1, 2.4));
    line(x, y, x + sway, y - h);
  }

  // contact shadow under door
  noStroke();
  fill(0, 0, 0, 80);
  ellipse(890, 1448, 360, 28);

  // ---------- DOOR GLOW ----------
  blendMode(ADD);
  let dg = ctx.createRadialGradient(890, 1140, 40, 890, 1140, 560);
  dg.addColorStop(0, 'rgba(255,200,120,0.5)');
  dg.addColorStop(1, 'rgba(255,200,120,0)');
  ctx.fillStyle = dg;
  ctx.fillRect(330, 580, 1120, 1120);
  blendMode(BLEND);

  // ---------- DOOR FRAME ----------
  noStroke();
  fill(32, 22, 15);
  rect(740, 840, 300, 600);
  stroke(16, 10, 7, 200);
  strokeWeight(2);
  for (let i = 1; i < 9; i++) line(740 + i * 33, 842, 740 + i * 33, 1438);
  for (let i = 1; i < 18; i++) line(742, 840 + i * 33, 1038, 840 + i * 33);

  // ---------- BRIGHT OPENING ----------
  let og = ctx.createLinearGradient(0, 866, 0, 1414);
  og.addColorStop(0, '#fff7e0');
  og.addColorStop(0.55, '#ffe3a6');
  og.addColorStop(1, '#ffb765');
  ctx.fillStyle = og;
  ctx.fillRect(766, 866, 248, 548);
  blendMode(ADD);
  let ih = ctx.createRadialGradient(890, 1150, 20, 890, 1150, 260);
  ih.addColorStop(0, 'rgba(255,255,240,0.8)');
  ih.addColorStop(1, 'rgba(255,255,240,0)');
  ctx.fillStyle = ih;
  ctx.fillRect(630, 890, 520, 520);
  blendMode(BLEND);

  // ---------- FIGURE IN THE LIGHT ----------
  noStroke();
  fill(24, 15, 10, 232);
  rect(879, 1038, 22, 20);
  beginShape();
  vertex(870, 1052);
  bezierVertex(838, 1080, 826, 1230, 824, 1414);
  vertex(956, 1414);
  bezierVertex(954, 1230, 942, 1080, 910, 1052);
  endShape(CLOSE);
  ellipse(890, 1012, 54, 60);
  // warm rim on the figure
  noFill();
  stroke(255, 220, 150, 150);
  strokeWeight(3);
  beginShape();
  vertex(956, 1414);
  bezierVertex(954, 1230, 942, 1080, 910, 1052);
  endShape();
  arc(890, 1012, 54, 60, -HALF_PI, HALF_PI);

  // ---------- OPEN DOOR PANEL ----------
  noStroke();
  fill(40, 28, 19);
  beginShape();
  vertex(766, 866);
  vertex(588, 930);
  vertex(588, 1478);
  vertex(766, 1414);
  endShape(CLOSE);
  stroke(20, 13, 9, 220);
  strokeWeight(2);
  for (let i = 1; i < 5; i++) {
    let f = i / 5;
    line(lerp(766, 588, f), lerp(866, 930, f), lerp(766, 588, f), lerp(1414, 1478, f));
  }
  noFill();
  stroke(180, 190, 230, 90);
  strokeWeight(3);
  line(588, 930, 588, 1478);
  noStroke();
  fill(255, 215, 150, 190);
  circle(622, 1192, 10);
  fill(30, 20, 12, 200);
  circle(622, 1192, 4);

  // lintel highlight + light leak along the gap
  stroke(255, 210, 140, 160);
  strokeWeight(3);
  line(740, 841, 1040, 841);
  stroke(255, 225, 160, 210);
  strokeWeight(4);
  line(766, 868, 766, 1412);
  noStroke();
  fill(255, 236, 190, 240);
  rect(766, 1408, 248, 8);

  // ---------- FOREGROUND GRASS ----------
  for (let i = 0; i < 260; i++) {
    let x = random(560, 1220);
    let y = random(1408, 1480);
    stroke(8, 13, 9, 230);
    strokeWeight(random(2, 4));
    line(x, y, x + random(-14, 14), y - random(30, 80));
  }
  for (let i = 0; i < 300; i++) {
    let x = random(W);
    let y = random(1750, H);
    stroke(7, 11, 8, 235);
    strokeWeight(random(2.5, 5));
    line(x, y, x + random(-16, 16), y - random(50, 110));
  }

  // ---------- DUST MOTES ----------
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 200; i++) {
    let y = random(880, 1440);
    let hw = 90 + (y - 880) * 0.30;
    let x = 890 + random(-1, 1) * hw;
    let a = map(dist(x, y, 890, 1150), 60, 420, 200, 10, true);
    fill(255, 230, 180, a);
    circle(x, y, random(1, 4.5));
  }
  for (let i = 0; i < 90; i++) {
    let y = random(1420, 1900);
    let x = 890 + random(-1, 1) * poolHalfW(y) * 0.9;
    fill(255, 215, 150, random(30, 110));
    circle(x, y - random(0, 40), random(1, 3.5));
  }
  blendMode(BLEND);

  // ---------- VIGNETTE + GRAIN ----------
  let vg = ctx.createRadialGradient(800, 980, 420, 800, 1000, 1250);
  vg.addColorStop(0, 'rgba(4,4,10,0)');
  vg.addColorStop(1, 'rgba(4,4,10,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  noStroke();
  for (let i = 0; i < 14000; i++) {
    if (random() < 0.5) fill(255, 255, 255, 5);
    else fill(0, 0, 0, 6);
    rect(random(W), random(H), 1.4, 1.4);
  }
}

let tips = [];
let leafPalette = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  leafPalette = [
    color(125, 106, 47),
    color(156, 90, 42),
    color(168, 120, 56),
    color(110, 90, 38),
    color(138, 122, 58),
    color(140, 70, 40)
  ];
  paintSky();
  paintSun();
  paintHills();
  paintGround();
  paintMist();
  paintPath();
  paintTree();
  paintCanopy();
  paintFlyers();
  paintForeground();
  vignette();
  grain();
}

function gradientColor(stops, t) {
  for (let i = 1; i < stops.length; i++) {
    if (t <= stops[i][0]) {
      const p0 = stops[i - 1][0], c0 = stops[i - 1][1];
      const p1 = stops[i][0], c1 = stops[i][1];
      return lerpColor(c0, c1, (t - p0) / (p1 - p0));
    }
  }
  return stops[stops.length - 1][1];
}

function paintSky() {
  const H = 1420;
  const stops = [
    [0.00, color(13, 18, 44)],
    [0.30, color(34, 42, 86)],
    [0.55, color(78, 74, 116)],
    [0.75, color(140, 104, 110)],
    [0.90, color(205, 146, 92)],
    [1.00, color(238, 196, 122)]
  ];
  noStroke();
  for (let y = 0; y < H; y += 3) {
    fill(gradientColor(stops, y / H));
    rect(0, y, 1600, 3);
  }
  for (let i = 0; i < 140; i++) {
    const y = random(40, 1260);
    const x = random(-250, 1850);
    let c;
    if (y > 720) {
      c = random() < 0.6 ? color(238, 190, 140, random(8, 20)) : color(120, 80, 90, random(8, 18));
    } else {
      c = random() < 0.6 ? color(8, 12, 36, random(10, 24)) : color(120, 130, 170, random(6, 16));
    }
    fill(c);
    ellipse(x, y, random(140, 560), random(8, 34));
  }
  for (let i = 0; i < 70; i++) {
    fill(255, 250, 235, random(20, 90));
    circle(random(1600), random(480), random(1, 2.4));
  }
}

function paintSun() {
  const sx = 1160, sy = 560;
  noStroke();
  for (let i = 0; i < 14; i++) {
    fill(240, 200, 130, 5);
    push();
    translate(sx, sy);
    rotate(random(TWO_PI));
    const len = random(500, 1100);
    triangle(0, 0, len, -random(30, 90), len, random(30, 90));
    pop();
  }
  for (let r = 460; r > 50; r -= 14) {
    fill(244, 198, 120, 4 + (1 - r / 460) * 26);
    circle(sx, sy, r * 2);
  }
  for (let r = 92; r > 30; r -= 8) {
    fill(255, 240, 205, 90);
    circle(sx + random(-2, 2), sy + random(-2, 2), r * 2);
  }
  fill(255, 248, 225, 235);
  circle(sx, sy, 62);
}

function ridge(baseY, amp, col) {
  fill(col);
  noStroke();
  beginShape();
  vertex(-50, 2100);
  for (let x = -50; x <= 1650; x += 20) {
    vertex(x, baseY + noise(x * 0.004, baseY * 0.001) * amp - amp / 2);
  }
  vertex(1650, 2100);
  endShape(CLOSE);
}

function paintHills() {
  ridge(1330, 90, color(74, 60, 88));
  ridge(1395, 70, color(38, 32, 48));
}

function paintGround() {
  const stops = [
    [0.0, color(46, 36, 26)],
    [0.5, color(28, 22, 16)],
    [1.0, color(14, 11, 9)]
  ];
  noStroke();
  for (let y = 1420; y < 2000; y += 3) {
    fill(gradientColor(stops, (y - 1420) / 580));
    rect(0, y, 1600, 3);
  }
  for (let i = 0; i < 900; i++) {
    const x = random(1600), y = random(1420, 2000);
    stroke(random() < 0.5 ? color(60, 48, 32, random(10, 30)) : color(20, 16, 12, random(10, 30)));
    strokeWeight(random(1, 2.5));
    const l = random(8, 40);
    line(x, y, x + random(-l, l) * 0.5, y - random(0, l * 0.3));
  }
  noStroke();
}

function paintMist() {
  noStroke();
  fill(240, 200, 140, 18);
  ellipse(1160, 1420, 520, 60);
  for (let i = 0; i < 40; i++) {
    fill(235, 205, 160, random(4, 12));
    ellipse(random(1600), random(1330, 1470), random(200, 700), random(10, 30));
  }
}

function paintPath() {
  noStroke();
  const x0 = 430, y0 = 1840, x1 = 1320, y1 = 1445;
  const cx = 860, cy = 1580;
  for (let i = 0; i < 70; i++) {
    const t = i / 69;
    const qx = (1 - t) * (1 - t) * x0 + 2 * (1 - t) * t * cx + t * t * x1 + noise(i * 0.3) * 60 - 30;
    const qy = (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * cy + t * t * y1;
    const w = lerp(170, 16, t) * (0.8 + noise(i * 0.5) * 0.5);
    fill(224, 192, 142, 13);
    ellipse(qx, qy, w, w * 0.3);
  }
}

function paintTree() {
  tips = [];
  strokeCap(ROUND);
  branch(400, 1815, -HALF_PI, 240, 54, 7);
}

function branch(x, y, angle, len, wid, depth) {
  let cx = x, cy = y, a = angle;
  const steps = max(2, int(len / 24));
  for (let s = 0; s < steps; s++) {
    a += random(-0.08, 0.08);
    const nx = cx + cos(a) * (len / steps);
    const ny = cy + sin(a) * (len / steps);
    const wHere = wid * (1 - 0.55 * s / steps);
    for (let l = 0; l < 3; l++) {
      const shade = random();
      let c;
      if (shade < 0.68) c = color(16 + random(12), 13 + random(9), 9 + random(7), 235);
      else if (shade < 0.9) c = color(42, 29, 18, 210);
      else c = color(126, 84, 42, 80);
      stroke(c);
      strokeWeight(wHere * random(0.6, 1.05));
      const ox = random(-wHere * 0.35, wHere * 0.35);
      const oy = random(-wHere * 0.35, wHere * 0.35);
      line(cx + ox, cy + oy, nx + ox, ny + oy);
    }
    cx = nx; cy = ny;
  }
  if (depth === 0 || wid < 1.4) {
    tips.push([cx, cy]);
    return;
  }
  if (depth <= 3) tips.push([cx, cy]);
  let n = 2;
  if (depth >= 6 && random() < 0.4) n = 3;
  for (let i = 0; i < n; i++) {
    const spread = map(i, 0, n - 1, -0.55, 0.55);
    const na = constrain(a + spread + random(-0.22, 0.22), -PI + 0.32, -0.32);
    branch(cx, cy, na, len * random(0.58, 0.74), wid * random(0.56, 0.66), depth - 1);
  }
}

function paintCanopy() {
  noStroke();
  for (const p of tips) {
    const tx = p[0], ty = p[1];
    fill(15, 12, 9, 110);
    ellipse(tx + random(-8, 8), ty + random(-8, 8), random(46, 90), random(30, 60));
    const n = int(random(6, 14));
    for (let i = 0; i < n; i++) {
      fill(random(leafPalette), random(150, 235));
      push();
      translate(tx + random(-42, 42), ty + random(-30, 30));
      rotate(random(TWO_PI));
      const s = random(4, 10);
      ellipse(0, 0, s * 1.7, s);
      pop();
    }
  }
}

function paintFlyers() {
  const sx = 1160, sy = 560;
  for (let i = 0; i < 110; i++) {
    const t = random(0.12, 0.97);
    const p0 = random(tips);
    const x0 = p0[0] + random(-40, 40);
    const y0 = p0[1] + random(-30, 30);
    const x1 = sx + random(-110, 130);
    const y1 = sy + random(-90, 90);
    const cx = (x0 + x1) / 2 + random(-160, 160);
    const cy = min(y0, y1) - random(120, 420);
    const x = (1 - t) * (1 - t) * x0 + 2 * (1 - t) * t * cx + t * t * x1;
    const y = (1 - t) * (1 - t) * y0 + 2 * (1 - t) * t * cy + t * t * y1;
    const dx = 2 * (1 - t) * (cx - x0) + 2 * t * (x1 - cx);
    const dy = 2 * (1 - t) * (cy - y0) + 2 * t * (y1 - cy);
    const ang = atan2(dy, dx);
    const size = lerp(2.5, 8, t);
    push();
    translate(x, y);
    rotate(ang);
    if (t < 0.5) {
      noStroke();
      fill(random(leafPalette), random(180, 240));
      rotate(random(-0.6, 0.6));
      ellipse(0, 0, size * 1.7, size);
    } else {
      noFill();
      stroke(20, 16, 24, 210);
      strokeWeight(map(size, 2.5, 8, 1.2, 2.6));
      const s = size * 1.9;
      const flap = sin(noise(i * 3.7) * TWO_PI) * 0.35;
      beginShape();
      vertex(-s, 0);
      quadraticVertex(-s * 0.5, -s * (0.75 + flap), 0, -s * 0.15);
      quadraticVertex(s * 0.5, -s * (0.75 + flap), s, 0);
      endShape();
    }
    pop();
  }
}

function paintForeground() {
  for (let i = 0; i < 500; i++) {
    const x = random(1600), y = random(1500, 2000);
    stroke(random() < 0.5 ? color(30, 34, 20, random(40, 110)) : color(12, 12, 8, random(40, 110)));
    strokeWeight(random(1, 2.2));
    line(x, y, x + random(-6, 6), y - random(8, 34));
  }
  noStroke();
  for (let i = 0; i < 220; i++) {
    const x = random(1600);
    const bias = constrain((x - 100) / 500, 0, 1);
    if (random() > 0.75 - bias * 0.5) continue;
    fill(random(leafPalette), random(120, 220));
    push();
    translate(x, random(1440, 1990));
    rotate(random(TWO_PI));
    const s = random(4, 11);
    ellipse(0, 0, s * 1.6, s * 0.9);
    pop();
  }
}

function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 950, 500, 800, 1000, 1350);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(4,3,8,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1600, 2000);
}

function grain() {
  noStroke();
  for (let i = 0; i < 6000; i++) {
    if (random() < 0.5) fill(255, 255, 255, random(4, 14));
    else fill(0, 0, 0, random(4, 14));
    circle(random(1600), random(2000), random(0.6, 1.8));
  }
}

