}

function skyColor(y) {
  for (let i = 0; i < skyStops.length - 1; i++) {
    let a = skyStops[i];
    let b = skyStops[i + 1];
    if (y <= b[0]) {
      let t = map(y, a[0], b[0], 0, 1, true);
      return lerpColor(a[1], b[1], t);
    }
  }
  return skyStops[skyStops.length - 1][1];
}

function paintSky() {
  noStroke();
  for (let y = 0; y <= 1400; y += 2) {
    fill(skyColor(y));
    rect(0, y, width, 3);
  }
  for (let i = 0; i < 240; i++) {
    let y = random(0, 1360);
    let x = random(-150, width);
    let len = random(80, 400);
    let c = lerpColor(skyColor(y), color(205, 175, 195), random(0, 0.28));
    stroke(red(c), green(c), blue(c), random(8, 20));
    strokeWeight(random(5, 16));
    line(x, y, x + len, y + random(-9, 9));
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 210; i++) {
