function ridgeY(x) {
  return 1372 - noise(x * 0.0016, 3.7) * 46 - noise(x * 0.008, 1.1) * 12;
}

function paintHorizon() {
  noStroke();
  for (let i = 0; i < 30; i++) {
    fill(216, 186, 192, 7);
    rect(0, 1322 + i * 3, width, 4);
  }
  fill(24, 19, 44);
  beginShape();
  vertex(0, 1412);
  for (let x = 0; x <= width; x += 16) vertex(x, ridgeY(x));
  vertex(width, 1412);
  endShape(CLOSE);
  fill(15, 12, 32);
  for (let x = -4; x < width; x += 7) {
    let y = ridgeY(x);
    let h = 5 + noise(x * 0.012, 9.2) * 24;
    triangle(x, y + 3, x + 3.5, y - h, x + 7, y + 3);
  }
  branch(862, ridgeY(862) + 4, -HALF_PI, 36, 5.5, 5);
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 5) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  stroke(13, 10, 26);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, x2, y2);
  let n = depth > 3 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    branch(x2, y2, angle + random(-0.85, 0.85), len * random(0.58, 0.76), Math.max(w * 0.62, 0.8), depth - 1);
  }
}

function paintField() {
