function paintPath() {
  noStroke();
  for (let i = 0; i < 48; i++) {
    let t = i / 48;
    let y = lerp(1394, height + 12, t);
    let cx = lerp(1000, 795, t);
    let wdt = lerp(46, 620, t) * (0.85 + noise(i * 0.4, 2.2) * 0.35);
    fill(228, 210, 180, 22 * (1 - t * 0.5));
    ellipse(cx, y, wdt, wdt * 0.05 + 10);
  }
  for (let i = 0; i < 42; i++) {
    let t = i / 42;
    let y = lerp(1990, 1690, t);
    let cx = lerp(795, 766, t) + noise(i * 0.7, 5.5) * 26 - 13;
    fill(6, 5, 12, 55 * (1 - t));
    ellipse(cx, y, 7, 4);
  }
  for (let i = 0; i < 1200; i++) {
    let t = Math.pow(random(), 0.75);
    let y = lerp(1398, height, t);
    let cx = lerp(1000, 795, t);
    let wdt = lerp(46, 620, t);
    let x = cx + random(-wdt / 2, wdt / 2);
    stroke(242, 228, 198, random(25, 85));
    strokeWeight(random(1, 2.6));
    line(x, y, x + random(-4, 4), y - random(3, 11));
