}

function paintFieldStrokes() {
  let top = color(72, 53, 84);
  let bot = color(9, 7, 16);
  for (let i = 0; i < 7500; i++) {
    let x = random(width);
    let y = random(1390, height);
    let t = map(y, 1390, height, 0, 1, true);
    let base = lerpColor(top, bot, t);
    let c = lerpColor(base, color(150, 132, 178), random(0, 0.3));
    let py = map(y, 1386, height, 0, 1, true);
    let px = lerp(1000, 795, py);
    let wdt = lerp(46, 620, py);
    let g = 0.012;
    if (Math.abs(x - px) < wdt / 2 + 90) g += 0.11;
    if (dist(x, y, 1000, 1330) < 430) g += 0.07;
    if (y < 1560 && x > 1020 && random() < 0.05) {
      stroke(200, 190, 225, random(40, 90));
    } else if (random() < g) {
      stroke(219, 184, 128, random(70, 150));
    } else {
      stroke(red(c), green(c), blue(c), random(45, 125));
    }
    strokeWeight(random(1, 2.4));
    let len = map(y, 1390, height, 3, 15, true);
    line(x, y, x + random(-3, 3), y - len * random(0.7, 1.3));
  }
}

