function paintVignette() {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(width / 2, height * 0.52, height * 0.3,
    width / 2, height * 0.52, height * 0.82);
  g.addColorStop(0, 'rgba(4,3,10,0)');
  g.addColorStop(0.72, 'rgba(4,3,10,0.16)');
  g.addColorStop(1, 'rgba(3,2,8,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 9000; i++) {
    if (random() < 0.5) fill(255, 255, 255, random(2, 7));
    else fill(0, 0, 0, random(3, 9));
    rect(random(width), random(height), 1.4, 1.4);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

const HORIZON = 1520;

function gradientAt(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    const t0 = stops[i][0], c0 = stops[i][1];
    const t1 = stops[i + 1][0], c1 = stops[i + 1][1];
    if (t >= t0 && t <= t1) {
      return lerpColor(c0, c1, (t - t0) / (t1 - t0));
    }
  }
  return stops[stops.length - 1][1];
}

function draw() {
  background(16, 20, 42);

  // ---- sky ----
  const skyStops = [
    [0.00, color(14, 18, 40)],
    [0.34, color(48, 46, 86)],
    [0.58, color(110, 68, 96)],
    [0.78, color(196, 112, 74)],
    [1.00, color(244, 176, 104)]
  ];
  for (let y = 0; y <= HORIZON; y++) {
    stroke(gradientAt(skyStops, y / HORIZON));
    line(0, y, width, y);
  }

  // painterly sky strokes
  noStroke();
  for (let i = 0; i < 1400; i++) {
    const y = random(HORIZON);
    const base = gradientAt(skyStops, y / HORIZON);
    const b = random(-18, 18);
    fill(constrain(red(base) + b, 0, 255),
         constrain(green(base) + b, 0, 255),
         constrain(blue(base) + b, 0, 255),
         random(16, 42));
    ellipse(random(width), y, random(30, 150), random(2, 7));
  }

  // fading stars
  for (let i = 0; i < 160; i++) {
    const y = random(0, 620);
    fill(255, 250, 240, random(14, 80) * (1 - y / 700));
    circle(random(width), y, random(0.6, 2.2));
  }

  // ---- sun ----
  const sunX = 1060, sunY = 1418;
  for (let r = 620; r > 130; r -= 16) {
    fill(252, 188, 116, map(r, 130, 620, 46, 3));
    circle(sunX, sunY, r * 2);
  }
  fill(253, 224, 156);
  circle(sunX, sunY, 268);
  fill(255, 240, 196);
  circle(sunX, sunY, 210);

  // ---- hills ----
  hillLayer(1500, 90, color(84, 52, 74));
  hillLayer(1516, 60, color(58, 36, 56));

  // ---- ground ----
  const gndStops = [
    [0.00, color(96, 58, 52)],
    [0.25, color(56, 36, 40)],
    [1.00, color(13, 11, 17)]
  ];
  for (let y = HORIZON; y <= height; y++) {
    stroke(gradientAt(gndStops, (y - HORIZON) / (height - HORIZON)));
    line(0, y, width, y);
  }
  for (let i = 0; i < 1600; i++) {
    const y = random(HORIZON, height);
    const base = gradientAt(gndStops, (y - HORIZON) / (height - HORIZON));
    const b = random(-14, 14);
    fill(constrain(red(base) + b, 0, 255),
         constrain(green(base) + b, 0, 255),
         constrain(blue(base) + b, 0, 255),
         random(14, 36));
    ellipse(random(width), y, random(40, 200), random(2, 8));
  }
  // warm path of light on the ground
  for (let i = 0; i < 60; i++) {
    const y = random(HORIZON + 10, height - 20);
    const spread = map(y, HORIZON, height, 30, 260);
    fill(244, 176, 104, random(8, 26));
    ellipse(sunX + random(-spread, spread), y, random(20, 90), random(3, 8));
  }

  // mist at the horizon
  for (let i = 0; i < 30; i++) {
    fill(240, 190, 140, random(4, 12));
    ellipse(random(width), random(HORIZON - 30, HORIZON + 20), random(120, 420), random(8, 26));
  }

  // ---- bare tree ----
  strokeCap(ROUND);
  branch(520, 1600, -HALF_PI, 170, 17);

  // ---- seated figure ----
  drawFigure(830, 1760);

  // ---- leaves: falling and fallen ----
  const leafPalette = [
    color(228, 152, 72), color(198, 110, 58), color(152, 82, 50),
    color(242, 192, 112), color(122, 62, 42), color(210, 130, 70)
  ];
  for (let i = 0; i < 150; i++) {
    const c = random(leafPalette);
    fill(red(c), green(c), blue(c), random(150, 230));
    const s = random(6, 17);
    push();
    translate(random(240, 1360), random(420, 1960));
    rotate(random(TWO_PI));
    ellipse(0, 0, s, s * 0.45);
    pop();
  }

  // ---- birds leaving ----
  stroke(28, 24, 38);
  strokeWeight(3.2);
  noFill();
  for (let i = 0; i < 9; i++) {
    const s = random(9, 20);
    push();
    translate(random(880, 1520), random(130, 640));
    rotate(random(-0.25, 0.25));
    arc(-s * 0.7, -s * 0.15, s * 1.5, s * 1.3, PI * 1.05, PI * 1.95);
    arc(s * 0.7, -s * 0.15, s * 1.5, s * 1.3, PI * 1.05, PI * 1.95);
    pop();
  }

  // ---- canvas grain ----
  noStroke();
  for (let i = 0; i < 26000; i++) {
    const v = random(255);
    fill(v, v, v, random(3, 9));
    circle(random(width), random(height), random(0.5, 1.6));
  }

  // ---- vignette ----
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(
    width / 2, height * 0.42, height * 0.2,
    width / 2, height * 0.5, height * 0.78
  );
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(4,3,9,0.52)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function hillLayer(baseY, amp, c) {
  fill(c);
  noStroke();
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 16) {
    vertex(x, baseY - noise(x * 0.0022, baseY * 0.013) * amp);
  }
  vertex(width, height);
  endShape(CLOSE);
}

function branch(x, y, angle, len, w) {
  if (w < 1.1 || len < 10) return;
  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;
  strokeWeight(w);
  const shade = random(-8, 8);
  stroke(constrain(26 + shade, 0, 255),
         constrain(18 + shade, 0, 255),
         constrain(22 + shade, 0, 255));
  line(x, y, x2, y2);
  const n = 2 + floor(random(2));
  for (let i = 0; i < n; i++) {
    const na = angle + random(-0.75, 0.75) + (i - (n - 1) / 2) * 0.55;
    branch(x2, y2, na, len * random(0.6, 0.8), w * 0.66);
  }
}

function drawFigure(cx, baseY) {
  noStroke();
  fill(0, 0, 0, 90);
  ellipse(cx, baseY + 18, 170, 30);

  // cloak
  fill(203, 193, 213);
  beginShape();
  vertex(cx - 62, baseY);
  bezierVertex(cx - 78, baseY - 90, cx - 46, baseY - 150, cx, baseY - 158);
  bezierVertex(cx + 46, baseY - 150, cx + 78, baseY - 90, cx + 62, baseY);
  bezierVertex(cx + 30, baseY + 8, cx - 30, baseY + 8, cx - 62, baseY);
  endShape(CLOSE);

  // cloak shading
  fill(160, 150, 172, 120);
  ellipse(cx - 22, baseY - 60, 50, 90);

  // hooded head
  fill(216, 207, 224);
  circle(cx, baseY - 178, 52);
  fill(96, 88, 108);
  ellipse(cx - 4, baseY - 172, 30, 36);

  // rim light from the sun
  noFill();
  stroke(252, 208, 148, 150);
  strokeWeight(4);
  arc(cx + 6, baseY - 182, 56, 56, -1.2, 0.9);
  arc(cx + 24, baseY - 96, 90, 120, -0.9, 0.5);
}

function setup(){
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function branch(x, y, ang, len, w, depth){
  if (depth <= 0 || len < 7) return;
  const x2 = x + cos(ang)*len;
  const y2 = y + sin(ang)*len;
  stroke(13, 10, 22, 240);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, x2, y2);
  const n = depth > 6 ? 3 : 2;
  for (let i = 0; i < n; i++){
    const spread = random(0.28, 0.8);
    const na = ang + random(-spread, spread) + (i - (n-1)/2)*0.4;
    branch(x2, y2, na, len*random(0.6, 0.78), w*0.66, depth-1);
  }
}

function poppy(x, y, s){
  const lean = random(-7, 7);
  const px = x + lean, py = y - s*2.1;
  stroke(30, 52, 30, 210);
  strokeWeight(max(1.5, s*0.1));
  line(x, y, px, py);
  noStroke();
  for (let i = 0; i < 5; i++){
    const a = (i/5)*TWO_PI + random(-0.25, 0.25);
    const shade = random(-28, 28);
    fill(148+shade, 22+shade*0.4, 36+shade*0.3, 240);
    push();
    translate(px, py);
    rotate(a);
    ellipse(s*0.5, 0, s*0.95, s*0.55);
    pop();
  }
  fill(18, 10, 14);
  circle(px, py, s*0.4);
  fill(246, 232, 176, 150);
  for (let i = 0; i < 7; i++){
    const a = random(TWO_PI), d = random(s*0.12, s*0.3);
    circle(px+cos(a)*d, py+sin(a)*d, max(1, s*0.06));
  }
}

function draw(){
  const W = 1600, H = 2000;
  const ctx = drawingContext;
  background(10, 8, 18);

  let sky = ctx.createLinearGradient(0, 0, 0, 1560);
  sky.addColorStop(0.00, '#0b0918');
  sky.addColorStop(0.42, '#221a3a');
  sky.addColorStop(0.72, '#46305a');
  sky.addColorStop(1.00, '#6d4a64');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, 1560);

  noStroke();
