// p5.js 1.11
// 无文字、无外部资源；运行后生成静态图像。

const W = 1600, H = 2000;
const TAU = Math.PI * 2;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();

  paintGround();
  paintSediment(false);
  paintShadow();
  paintInterior();
  paintShell();
  paintDisintegration();
  paintSediment(true);
  paintGrain();
}

// u = 0 为内缘，u = 1 为外缘。
// 轮廓刻意偏离对称：它是一层曾经保持完整的物质。
function contour(t, u) {
  const ct = Math.cos(t), st = Math.sin(t);
  const n = noise(3.8 + ct * 1.65, 5.2 + st * 1.65);
  const wobble = (n - 0.5) * 27;
  const rx = 316 + 132 * u;
  const ry = 505 + 163 * u;
  const taper = 1 - 0.115 * st;

  return {
    x: 790 + ct * (rx + wobble) * taper
       - st * 37 + u * 9 * Math.sin(t * 3),
    y: 815 + st * (ry + wobble)
       + 13 * Math.cos(t * 2) + u * 12 * ct
  };
}

function pathContour(u) {
  const ctx = drawingContext;
  ctx.beginPath();
  for (let i = 0; i <= 800; i++) {
    const p = contour(i / 800 * TAU, u);
    if (i === 0) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  }
  ctx.closePath();
}

function paintGround() {
  const img = createImage(800, 1000);
  img.loadPixels();

  for (let y = 0; y < img.height; y++) {
    for (let x = 0; x < img.width; x++) {
      const xx = x * 2, yy = y * 2;
      const broad = noise(x * 0.006, y * 0.006);
      const fine = noise(x * 0.074, y * 0.074);
      const mist = Math.exp(
        -sq((xx - 710) / 760) - sq((yy - 1080) / 940)
      );
      const edge = Math.min(
        1, Math.hypot((xx - 800) / 1060, (yy - 1000) / 1350)
      );
      const g = random(-2.4, 2.4);
      const k = broad * 9 + fine * 3 + mist * 5 - edge * 6;
      const i = (y * img.width + x) * 4;
      img.pixels[i]     = 15 + k + g;
      img.pixels[i + 1] = 23 + k + g;
      img.pixels[i + 2] = 26 + k + g;
      img.pixels[i + 3] = 255;
    }
  }
  img.updatePixels();
  image(img, 0, 0, W, H);

  // 薄而不规则的底料刷痕。
  for (let i = 0; i < 19000; i++) {
    const x = random(W), y = random(H);
    const warm = noise(x * 0.004, y * 0.004) > 0.54;
    stroke(warm ? color(111, 91, 66, 8) : color(72, 98, 99, 8));
    strokeWeight(random(0.5, 1.8));
    line(x, y, x + random(-3, 3), y + random(2, 23));
  }
}

function paintShadow() {
  noStroke();
  for (let j = 22; j >= 0; j--) {
    const ctx = drawingContext;
    pathContour(1 + j * 0.012);
    ctx.fillStyle = "rgba(4,10,12,0.025)";
    ctx.fill();
  }
}

function paintInterior() {
  const ctx = drawingContext;
  ctx.save();
  pathContour(0.025);
  ctx.clip();

  noStroke();
  fill(8, 14, 17);
  rect(200, 200, 1200, 1400);

  // 空缺并非纯黑；极低反差保留画布的物质性。
  for (let i = 0; i < 25000; i++) {
    const x = random(420, 1180);
    const y = random(260, 1380);
    const v = noise(x * 0.008, y * 0.008);
    stroke(45 + v * 10, 58 + v * 9, 60 + v * 8, random(3, 13));
    strokeWeight(random(0.5, 1.4));
    line(x, y, x + random(-2, 2), y + random(1, 7));
  }
  ctx.restore();
}

function paintShell() {
  const A = 1150;
  const B = 64;
  const mesh = [];

  for (let a = 0; a <= A; a++) {
    const row = [];
    const t = a / A * TAU;
    for (let b = 0; b <= B; b++) {
      row.push(contour(t, b / B));
    }
    mesh.push(row);
  }

  noStroke();

  for (let a = 0; a < A; a++) {
    const t = (a + 0.5) / A * TAU;
    const st = Math.sin(t), ct = Math.cos(t);
    const erosion = constrain((st - 0.37) / 0.63, 0, 1);

    for (let b = 0; b < B; b++) {
      const u = (b + 0.5) / B;
      const field = noise(
        11 + ct * 5.3,
        17 + st * 5.3,
        u * 5.4
      );

      // 下缘不是被切断，而是在不同深度逐层失去连续性。
      const survival = 1 - erosion * 1.13;
      if (field > survival + 0.13) continue;
      if (erosion > 0.55 && random() < erosion * 0.24) continue;

      const ridge = Math.exp(-sq((u - 0.39) / 0.30));
      const light = 0.68 + 0.23 * (-ct) - 0.10 * st;
      const striation =
        0.86 +
        0.11 * Math.sin(u * 128 + noise(ct + 4, st + 7) * 8) +
        0.08 * Math.sin(u * 311 + t * 4);

      let value = ridge * light * striation;
      value *= 0.78 + field * 0.40;
      value *= 1 - erosion * 0.35;
      value = constrain(value, 0, 1);

      const mineral = noise(40 + ct * 9, 40 + st * 9, u * 4);
      const rust = mineral > 0.59 ? (mineral - 0.59) * 140 : 0;
      const scratch = random(-5, 5);

      fill(
        36 + value * 188 + rust + scratch,
        43 + value * 172 - rust * 0.40 + scratch,
        43 + value * 136 - rust * 0.72 + scratch,
        245
      );

      const p = mesh[a][b], q = mesh[a + 1][b];
      const r = mesh[a + 1][b + 1], s = mesh[a][b + 1];
      quad(p.x, p.y, q.x, q.y, r.x, r.y, s.x, s.y);
    }
  }

  // 细小的干刷裂隙，避免光滑、金属般的表面。
  for (let i = 0; i < 6800; i++) {
    const t = random(TAU), u = random(0.09, 0.90);
    if (Math.sin(t) > 0.52) continue;

    const p = contour(t, u);
    const q = contour(t + random(0.002, 0.018), u + random(-0.007, 0.007));
    const pale = random() < 0.40;

    stroke(pale ? color(231, 218, 178, 36) : color(18, 26, 27, 57));
    strokeWeight(random(0.45, 1.65));
    line(p.x, p.y, q.x, q.y);
  }
}

function paintDisintegration() {
  noStroke();

  // 从壳的下部脱落；越向下，颗粒越暗、越细。
  for (let i = 0; i < 15000; i++) {
    const t = random(0.34, Math.PI - 0.34);
    const u = random();
    const p = contour(t, u);
    const fall = pow(random(), 1.9) * 410;
    const x = p.x + randomGaussian() * (8 + fall * 0.20);
    const y = p.y + fall;
    if (y > 1775 || y < 1110) continue;

    const fade = constrain(1 - fall / 440, 0, 1);
    const luminosity = random(0.28, 0.94) * fade;
    const alpha = random(15, 125) * fade;
    const size = random(0.65, 3.3) * (0.45 + fade);

    fill(
      49 + luminosity * 154,
      48 + luminosity * 142,
      40 + luminosity * 109,
      alpha
    );

    if (random() < 0.16) {
      triangle(x, y, x + size * 2.2, y + size * 0.5,
               x + size * 0.4, y + size * 2.7);
    } else {
      ellipse(x, y, size, size * random(0.6, 1.8));
    }
  }

  // 少量铁锈色的残片，没有血液的鲜艳。
  for (let i = 0; i < 230; i++) {
    const t = random(0.5, 2.65);
    const p = contour(t, random(0.2, 0.85));
    const y = p.y + random(10, 260);
    fill(133, 79, 45, random(25, 90));
    ellipse(p.x + randomGaussian() * 35, y, random(1, 4), random(1, 5));
  }
}

function paintSediment(foreground) {
  const count = foreground ? 2400 : 3000;

  for (let i = 0; i < count; i++) {
    const y = 1635 + randomGaussian() * 67;
    const x = 800 + randomGaussian() * 340;
    if (x < 90 || x > 1510) continue;

    const central = Math.exp(-sq((x - 800) / 440));
    const layer = noise(y * 0.055, 31);
    const alpha = (foreground ? 18 : 9) * central * layer;

    stroke(151, 133, 99, alpha);
    strokeWeight(random(0.5, 1.7));

    const len = random(4, 105) * (0.4 + central);
    line(x, y, x + len, y + random(-0.7, 0.7));
  }

  if (!foreground) return;

  noStroke();
  for (let i = 0; i < 6500; i++) {
    const x = 805 + randomGaussian() * 265;
    const y = 1655 + randomGaussian() * 37;
    const a = random(6, 49);
    fill(148, 126, 88, a);
    const d = random(0.5, 2);
    ellipse(x, y, d, d * 0.65);
  }

  // 沉积继续变得稀薄，没有清晰的地平线。
  for (let i = 0; i < 1100; i++) {
    const x = random(170, 1440), y = random(1740, 1890);
    fill(100, 105, 95, random(3, 13));
    circle(x, y, random(0.5, 1.6));
  }
}

function paintGrain() {
  const grain = createImage(800, 1000);
  grain.loadPixels();

  for (let i = 0; i < grain.pixels.length; i += 4) {
    const bright = random() > 0.49;
    const v = bright ? 224 : 4;
    grain.pixels[i] = v;
    grain.pixels[i + 1] = v;
    grain.pixels[i + 2] = bright ? 212 : 6;
    grain.pixels[i + 3] = random(3, 12);
  }

  grain.updatePixels();
  image(grain, 0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  // 无字的底色：石灰、烟灰与潮湿的土。
  const bg = ctx.createLinearGradient(180, 0, 1300, 2000);
  bg.addColorStop(0, "#d5ccba");
  bg.addColorStop(0.42, "#a8a294");
  bg.addColorStop(0.75, "#77796e");
  bg.addColorStop(1, "#343e3c");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 18000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0027, y * 0.0027);
    fill(n > 0.5 ? 226 : 48, n > 0.5 ? 214 : 58,
         n > 0.5 ? 189 : 55, random(2, 9));
    ellipse(x, y, random(4, 32), random(2, 14));
  }

  // 被磨损的底层笔迹。
  noFill();
  for (let i = 0; i < 3200; i++) {
    const x = random(width);
    const y = random(height);
    const len = random(6, 80);
    stroke(55, 62, 57, random(3, 16));
    strokeWeight(random(0.4, 1.3));
    beginShape();
    for (let j = 0; j <= 4; j++) {
      const xx = x + j * len / 4;
      vertex(xx, y + noise(xx * 0.008, y * 0.006) * 12);
    }
    endShape();
  }

  // 后景沉积：没有起点，也没有目的地。
  sediment(1270, 28, false);

  // 空缺外围的漫漶阴影。
  noStroke();
  for (let i = 34; i >= 0; i--) {
    fill(23, 29, 26, 2.5);
    contour(1.29 + i * 0.006, 8, 18);
  }

  const minerals = [
    "#55594e", "#777867", "#b3ac91", "#d1c3a0",
    "#96886b", "#80634e", "#bd9870", "#d8c9a6",
    "#696a59", "#a79f83", "#daceb2", "#8c7960"
  ];

  // 层层包围的材料，保留了曾经拥有中心的姿态。
  for (let i = 0; i < 190; i++) {
    const s = map(i, 0, 189, 1.285, 0.835);
    const index = floor(
      noise(i * 0.19, 7) * minerals.length * 1.7
    ) % minerals.length;
    let c = color(minerals[index]);

    if (i > 162) {
      c = lerpColor(c, color("#333b34"), (i - 162) / 40);
    }

    const g = ctx.createLinearGradient(360, 370, 1220, 1470);
    g.addColorStop(0, lerpColor(c, color("#e1d6b9"), 0.28).toString());
    g.addColorStop(0.47, c.toString());
    g.addColorStop(1, lerpColor(c, color("#26332e"), 0.42).toString());
    ctx.fillStyle = g;
    contour(s);
  }

  // 矿层中的细裂、擦痕和纤维。
  noFill();
  for (let i = 0; i < 8600; i++) {
    const a = random(TWO_PI);
    const s = random(0.848, 1.279);
    const len = random(0.006, 0.072);
    const pale = random() < 0.58;

    if (pale) {
      stroke(235, 222, 186, random(13, 68));
    } else {
      stroke(31, 41, 35, random(15, 80));
    }

    strokeWeight(random(0.35, 1.45));
    beginShape();
    for (let j = 0; j <= 5; j++) {
      const p = form(a + len * j / 5, s);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // 少量不连续的赭红夹层。
  for (let i = 0; i < 95; i++) {
    const a = random(PI * 0.93, PI * 1.72);
    const s = random(0.91, 1.23);
    stroke(139, 73, 45, random(35, 110));
    strokeWeight(random(0.7, 2.4));
    beginShape();
    const span = random(0.015, 0.13);
    for (let j = 0; j <= 12; j++) {
      const p = form(a + span * j / 12, s);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // 中心没有景物、星光或出口。
  noStroke();
  const hollow = ctx.createLinearGradient(490, 490, 1040, 1440);
  hollow.addColorStop(0, "#111b19");
  hollow.addColorStop(0.5, "#131c19");
  hollow.addColorStop(1, "#202923");
  ctx.fillStyle = hollow;
  contour(0.833);

  // 边缘残留的微光不是来自内部。
  noFill();
  for (let k = 0; k < 9; k++) {
    stroke(207, 193, 157, 35 - k * 3);
    strokeWeight(0.7);
    beginShape();
    for (let j = 0; j <= 150; j++) {
      const a = map(j, 0, 150, PI * 0.93, PI * 1.66);
      const p = form(a, 0.839 + k * 0.0015);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // 外侧剥落的颗粒。它们不进入空缺。
  noStroke();
  for (let i = 0; i < 3300; i++) {
    const a = random(TWO_PI);
    const distance = pow(random(), 2.7) * 0.37;
    const p = form(a, 1.29 + distance);
    if (p.y > 1650 || p.x < 100 || p.x > 1510) continue;

    const c = random([
      [202, 187, 151], [97, 98, 80],
      [147, 112, 78], [48, 61, 52]
    ]);
    fill(c[0], c[1], c[2], random(20, 105));
    const r = random(0.5, 3.5) * (1.2 - distance);
    ellipse(p.x, p.y, r, r * random(0.45, 1.4));
  }

  // 形状的下缘被普通的地层接走。
  sediment(1535, 35, true);

  // 沉积中遗留的断裂细线。
  noFill();
  for (let i = 0; i < 160; i++) {
    const x = random(330, 1250);
    const y = random(1640, 1930);
    stroke(192, 180, 145, random(12, 47));
    strokeWeight(random(0.4, 1));
    beginShape();
    const length = random(15, 170);
    for (let j = 0; j <= 12; j++) {
      const xx = x + length * j / 12;
      vertex(xx, y + 6 * noise(xx * 0.018, y * 0.01));
    }
    endShape();
  }

  // 整张画共享同一层纸粒，避免中心成为光滑的符号。
  grain();
}

function form(a, s) {
  const irregular =
    1 +
    0.035 * sin(a * 3 + 0.7) +
    0.018 * sin(a * 7 - 1.1) +
    0.026 * (noise(2 + cos(a) * 1.6, 2 + sin(a) * 1.6) - 0.5);

  const yy = 562 * sin(a) * s * irregular;
  const xx = 353 * cos(a) * s * irregular;
  const ripple = 2.8 * sin(a * 19 + s * 26) +
                 1.5 * sin(a * 37 - s * 18);

  return {
    x: 792 + xx + yy * 0.115 + ripple * cos(a),
    y: 910 + yy + ripple * sin(a)
  };
}

function contour(s, dx = 0, dy = 0) {
  // 直接使用 Canvas 路径，保留当前渐变填色。
  const ctx = drawingContext;
  ctx.beginPath();
  for (let j = 0; j <= 360; j++) {
    const p = form(j / 360 * TWO_PI, s);
    if (j === 0) ctx.moveTo(p.x + dx, p.y + dy);
    else ctx.lineTo(p.x + dx, p.y + dy);
  }
  ctx.closePath();
  ctx.fill();
}

function sediment(top, count, foreground) {
  const palette = foreground
    ? ["#515c50", "#69705d", "#8b8970", "#434f45",
       "#777a63", "#a2997a", "#3b4840"]
    : ["#8a8b77", "#727c6b", "#989780", "#626f61"];

  for (let k = 0; k < count; k++) {
    const base = top + k * (foreground ? 15 : 19);
    const c = color(palette[k % palette.length]);
    c.setAlpha(foreground ? 220 : 92);
    fill(c);
    noStroke();

    beginShape();
    for (let x = -40; x <= width + 40; x += 16) {
      const y = base +
        27 * sin(x * 0.003 + k * 0.085) +
        48 * (noise(x * 0.0024, k * 0.09 + 20) - 0.5);
      vertex(x, y);
    }
    vertex(width + 40, height + 40);
    vertex(-40, height + 40);
    endShape(CLOSE);

    noFill();
    stroke(211, 198, 160, foreground ? 39 : 22);
    strokeWeight(k % 5 === 0 ? 1.5 : 0.65);
    beginShape();
    for (let x = -40; x <= width + 40; x += 12) {
      const y = base +
        27 * sin(x * 0.003 + k * 0.085) +
        48 * (noise(x * 0.0024, k * 0.09 + 20) - 0.5);
      vertex(x, y);
    }
    endShape();
  }
}

function grain() {
  loadPixels();
  let seed = 1701;
  for (let i = 0; i < pixels.length; i += 4) {
    seed = (Math.imul(seed, 1664525) + 1013904223) >>> 0;
    const n = ((seed >>> 24) / 255 - 0.5);
    const strength = pixels[i] < 40 ? 3 : 10;
    const g = n * strength;
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g * 0.85, 0, 255);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function draw() {}

function clamp01(x) {
  return Math.max(0, Math.min(1, x));
}

function smooth(a, b, x) {
  let t = clamp01((x - a) / (b - a));
  return t * t * (3 - 2 * t);
}

function haze(x, y, rx, ry, rgb, strength) {
  const c = drawingContext;
  c.save();
  c.translate(x, y);
  c.scale(rx, ry);
  const g = c.createRadialGradient(0, 0, 0, 0, 0, 1);
  g.addColorStop(0, `rgba(${rgb},${strength})`);
  g.addColorStop(1, `rgba(${rgb},0)`);
  c.fillStyle = g;
  c.fillRect(-1, -1, 2, 2);
  c.restore();
}

// 每根线共享一个形体，但有各自的偏移与终点。
function filament(u, t, phase) {
  const breadth = 430 * Math.pow(Math.max(0, Math.sin(PI * t)), 0.69);
  const axis = 773 + 81 * Math.sin(t * 4.0) - 112 * t;
  const tension = Math.pow(Math.sin(PI * t), 1.1);
  const ripple =
    Math.sin(t * 23 + phase) * 11 +
    Math.sin(t * 61 + phase * 0.6) * 3.2;

  return {
    x: axis + u * breadth +
       ripple * tension +
       28 * Math.sin(t * 8 + u * 3) * tension,
    y: 255 + 1290 * t +
       31 * Math.sin(u * 3 + t * 5) * tension
  };
}

function paint() {
  const c = drawingContext;

  // 深色底层。
  const ground = c.createLinearGradient(0, 0, 500, height);
  ground.addColorStop(0, "#272b29");
  ground.addColorStop(0.34, "#30312c");
  ground.addColorStop(0.69, "#171c1d");
  ground.addColorStop(1, "#101619");
  c.fillStyle = ground;
  c.fillRect(0, 0, width, height);

  haze(450, 570, 800, 990, "137,115,79", 0.17);
  haze(1170, 850, 630, 1050, "73,96,105", 0.13);
  haze(810, 650, 560, 760, "190,175,139", 0.065);

  // 放大的低分辨率色层，模拟底料中不均匀的吸收。
  const underpaint = createGraphics(400, 500);
  underpaint.pixelDensity(1);
  underpaint.loadPixels();
  for (let y = 0; y < 500; y++) {
    for (let x = 0; x < 400; x++) {
      const n = noise(x * 0.019, y * 0.019);
      const m = noise(x * 0.071 + 100, y * 0.071);
      const i = 4 * (y * 400 + x);
      const pale = n > 0.49;
      underpaint.pixels[i] = pale ? 145 : 5;
      underpaint.pixels[i + 1] = pale ? 131 : 10;
      underpaint.pixels[i + 2] = pale ? 108 : 14;
      underpaint.pixels[i + 3] =
        Math.abs(n - 0.49) * 105 + m * 10;
    }
  }
  underpaint.updatePixels();
  image(underpaint, 0, 0, width, height);
  underpaint.remove();

  // 无身体的薄层：不是实体轮廓，而是一点积存的亮度。
  c.save();
  const membrane = c.createLinearGradient(530, 270, 1030, 1430);
  membrane.addColorStop(0, "rgba(222,210,174,0.035)");
  membrane.addColorStop(0.26, "rgba(205,196,161,0.12)");
  membrane.addColorStop(0.58, "rgba(154,151,129,0.055)");
  membrane.addColorStop(1, "rgba(109,123,123,0)");

  c.beginPath();
  for (let k = 0; k <= 140; k++) {
    const p = filament(-1, k / 140, 0);
    if (k === 0) c.moveTo(p.x, p.y);
    else c.lineTo(p.x, p.y);
  }
  for (let k = 140; k >= 0; k--) {
    const p = filament(1, k / 140, 0);
    c.lineTo(p.x, p.y);
  }
  c.closePath();
  c.fillStyle = membrane;
  c.fill();
  c.restore();

  // 横向关系隐约可见，不形成规整网格。
  c.lineWidth = 0.65;
  for (let row = 0; row < 185; row++) {
    const t = random(0.045, 0.9);
    const alpha = random(0.018, 0.075) *
                  (1 - smooth(0.52, 0.91, t));
    c.strokeStyle = `rgba(203,194,160,${alpha})`;
    c.beginPath();

    for (let k = 0; k <= 90; k++) {
      const u = -0.99 + 1.98 * k / 90;
      const p = filament(u, t, 1.5);
      const sag = 28 * (1 - u * u) *
                  Math.sin(t * 11 + row * 0.09);
      if (k === 0) c.moveTo(p.x, p.y + sag);
      else c.lineTo(p.x, p.y + sag);
    }
    c.stroke();
  }

  // 纵向细线：不同时消失，也没有落向同一个出口。
  for (let i = 0; i < 760; i++) {
    const u = random(-1, 1);
    const phase = random(TWO_PI);
    const begin = random(0.008, 0.075);
    const end = random(0.73, 0.99);
    const weight = random(0.45, 1.55);
    const baseAlpha = random(0.09, 0.36);
    const warm = random() < 0.76;
    const rgb = warm ? "222,209,171" : "158,183,184";
    const steps = 145;
    let previous = filament(u, begin, phase);

    c.lineWidth = weight;
    c.lineCap = "round";

    for (let k = 1; k <= steps; k++) {
      const t = begin + (end - begin) * k / steps;
      const p = filament(u, t, phase);
      const emergence = smooth(begin, begin + 0.065, t);
      const extinction = 1 - smooth(end - 0.21, end, t);
      const depth = 1 - smooth(0.48, 0.99, t);
      const breath = 0.55 + 0.45 * noise(i * 0.17, t * 10);
      const alpha = baseAlpha * emergence * extinction *
                    depth * breath;

      if (alpha > 0.003) {
        c.strokeStyle = `rgba(${rgb},${alpha})`;
        c.beginPath();
        c.moveTo(previous.x, previous.y);
        c.lineTo(p.x, p.y);
        c.stroke();
      }
      previous = p;
    }
  }

  // 少量哑金色磨损，只在仍有牵连的地方留存。
  for (let i = 0; i < 1250; i++) {
    const t = random(0.11, 0.76);
    const u = random(-1, 1);
    const p = filament(u, t, random(TWO_PI));
    const fade = 1 - smooth(0.45, 0.79, t);
    c.fillStyle = `rgba(202,169,110,${random(0.025, 0.15) * fade})`;
    c.beginPath();
    c.ellipse(
      p.x + random(-5, 5),
      p.y + random(-6, 6),
      random(0.4, 1.4),
      random(0.7, 3.1),
      random(-0.5, 0.5),
      0, TWO_PI
    );
    c.fill();
  }

  // 暗色擦痕穿入形体，使消失不是整齐的一条切口。
  for (let i = 0; i < 95; i++) {
    const y = random(870, 1470);
    const x = random(390, 1180);
    const amount = smooth(850, 1450, y);
    haze(
      x, y,
      random(45, 150),
      random(15, 70),
      "17,24,26",
      random(0.025, 0.13) * amount
    );
  }

  // 下方没有事件：各层逐渐成为同一种深色。
  const silence = c.createLinearGradient(0, 1050, 0, 1700);
  silence.addColorStop(0, "rgba(15,22,25,0)");
  silence.addColorStop(0.35, "rgba(15,22,25,0.16)");
  silence.addColorStop(0.72, "rgba(15,22,25,0.62)");
  silence.addColorStop(1, "rgba(15,22,25,0.92)");
  c.fillStyle = silence;
  c.fillRect(0, 1050, width, height - 1050);

  // 边缘压暗，不添加边框。
  const vignette = c.createRadialGradient(
    800, 850, 390, 800, 900, 1320
  );
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.65, "rgba(0,0,0,0.035)");
  vignette.addColorStop(1, "rgba(0,0,0,0.36)");
  c.fillStyle = vignette;
  c.fillRect(0, 0, width, height);

  // 全画幅细颗粒；下方仍是颜料，而非空白屏幕。
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      const i = 4 * (y * width + x);
      const grain = random(-2.7, 2.7);
      const tooth = ((x + y * 3) % 7 === 0) ? -0.65 : 0;
      pixels[i] = constrain(pixels[i] + grain + tooth, 0, 255);
      pixels[i + 1] = constrain(
        pixels[i + 1] + grain * 0.91 + tooth, 0, 255
      );
      pixels[i + 2] = constrain(
        pixels[i + 2] + grain * 0.79 + tooth, 0, 255
      );
    }
  }
  updatePixels();
}

const W = 1600;
const H = 2000;
let boundary = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
}

function draw() {
  makeBoundary();
  paintGround();

  // 宽而干涩的底层笔触。
  for (let i = 0; i < 230; i++) {
    const row = random(-500, 2300);
    const start = random(-240, 1100);
    const length = random(180, 1100);
    const warm = random();
    stroke(
      104 + warm * 58,
      73 + warm * 42,
      42 + warm * 23,
      random(3, 13)
    );
    strokeWeight(random(3, 19));
    noFill();
    beginShape();
    for (let x = start; x <= start + length; x += 16) {
      const p = flow(x, row);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // 密集但不整齐的纤维；每根都有不同的磨损。
  for (let row = -550; row < 2420; row += random(3.2, 6.6)) {
    const tone = random();
    const c = [
      113 + tone * 94,
      82 + tone * 77,
      48 + tone * 49
    ];
    const thickness = random(0.45, 1.65);
    const phase = random(1000);
    const start = random(-250, 70);
    const end = random(1580, 1860);

    noFill();
    strokeWeight(thickness);

    for (let x = start; x < end; x += 72) {
      if (noise(x * 0.012, phase) < 0.25) continue;

      const p = flow(x, row);
      const light = illumination(p.x, p.y);
      stroke(c[0], c[1], c[2], (9 + 57 * light) * random(0.45, 1));

      beginShape();
      for (let t = x; t <= x + 76; t += 9) {
        const q = flow(t, row);
        const tremor = (noise(t * 0.037, phase) - 0.5) * 3.4;
        vertex(q.x, q.y + tremor);
      }
      endShape();
    }
  }

  // 少量较亮的长线，像尚未褪尽的记忆。
  for (let i = 0; i < 85; i++) {
    const row = random(80, 1790);
    const start = random(-150, 500);
    const end = random(1000, 1760);
    stroke(215, 176, 111, random(12, 38));
    strokeWeight(random(0.55, 1.1));
    noFill();
    beginShape();
    for (let x = start; x <= end; x += 8) {
      const p = flow(x, row);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // 横向磨痕使表面近似旧织物，而不是光滑的数字曲线。
  for (let i = 0; i < 13500; i++) {
    const x = random(W);
    const y = random(H);
    const light = illumination(x, y);
    const bright = random() < 0.37;
    if (bright) {
      stroke(202, 170, 117, random(3, 17) * light);
    } else {
      stroke(9, 15, 17, random(5, 24));
    }
    strokeWeight(random(0.4, 1.4));
    const len = random(2, 17);
    line(x, y, x + len, y + len * 0.31);
  }

  // 所有纹路都在这里停止。
  noStroke();
  fill(8, 12, 14);
  beginShape();
  for (const p of boundary) vertex(p.x, p.y);
  endShape(CLOSE);

  // 暗部保留极轻的颜料颗粒，但没有内部景象。
  drawingContext.save();
  boundaryPath();
  drawingContext.clip();
  for (let i = 0; i < 27000; i++) {
    const x = random(440, 1330);
    const y = random(350, 1690);
    stroke(57, 65, 65, random(1, 5));
    strokeWeight(random(0.4, 1.1));
    point(x, y);
  }
  drawingContext.restore();

  // 边缘只留下断续的磨损，不画完整的发光轮廓。
  drawingContext.save();
  outsideClip();

  for (let i = 0; i < boundary.length; i++) {
    const p = boundary[i];
    const leftness = constrain((920 - p.x) / 350, 0, 1);
    if (random() > leftness * 0.72) continue;

    const q = boundary[(i + 1) % boundary.length];
    const dx = p.x - 880;
    const dy = p.y - 1010;
    const d = sqrt(dx * dx + dy * dy);
    const nx = dx / d;
    const ny = dy / d;

    for (let k = 0; k < 3; k++) {
      const offset = random(0.5, 8);
      stroke(185, 139, 77, random(9, 36) * leftness);
      strokeWeight(random(0.5, 1.8));
      line(
        p.x + nx * offset,
        p.y + ny * offset,
        q.x + nx * offset,
        q.y + ny * offset
      );
    }
  }

  // 残余颜料向右下方散失，没有重新组成另一种形体。
  noStroke();
  for (let i = 0; i < 5500; i++) {
    const t = pow(random(), 1.6);
    const x = 1030 + 430 * t + randomGaussian() * (35 + 105 * t);
    const y = 1360 + 410 * t + randomGaussian() * (60 + 80 * t);
    const a = (1 - t) * random(8, 47);
    fill(173, 133, 79, a);
    const r = random(0.5, 2.2);
    ellipse(x, y, r, r * random(0.6, 1.7));
  }

  drawingContext.restore();

  // 最后一层纸面颗粒，统一明暗区域的材质。
  for (let i = 0; i < 105000; i++) {
    const x = random(W);
    const y = random(H);
    const light = random() < 0.48;
    stroke(light ? 219 : 0, light ? 203 : 0, light ? 171 : 0,
           random(1, 5));
    strokeWeight(random(0.35, 1));
    point(x, y);
  }

  // 极轻的暗角，不添加画框。
  noFill();
  for (let i = 0; i < 95; i++) {
    stroke(3, 8, 10, 0.75);
    strokeWeight(2);
    rect(i, i, W - i * 2, H - i * 2);
  }
}

function flow(x, row) {
  const y =
    row +
    0.30 * (x - 800) +
    86 * sin(x * 0.0038 + row * 0.0023) +
    34 * sin(x * 0.0071 - row * 0.0031) +
    43 * (noise(x * 0.0018, row * 0.002 + 10) - 0.5);

  return {
    x: x + 9 * sin(row * 0.011 + x * 0.002),
    y: y
  };
}

function illumination(x, y) {
  const a = sq((x - 470) / 720);
  const b = sq((y - 860) / 1120);
  return 0.13 + 0.87 * exp(-a - b);
}

function makeBoundary() {
  const angle = -0.105;
  const ca = cos(angle);
  const sa = sin(angle);

  for (let i = 0; i < 420; i++) {
    const t = TWO_PI * i / 420;
    const irregularity =
      1 +
      0.038 * sin(3 * t + 0.8) +
      0.022 * sin(5 * t - 0.4) +
      0.009 * sin(11 * t);

    let x = 323 * cos(t) * irregularity;
    let y = 564 * sin(t) * (1 + 0.028 * cos(3 * t));
    x += 20 * sin(t) + 10 * sin(2 * t);

    boundary.push({
      x: 880 + x * ca - y * sa,
      y: 1010 + x * sa + y * ca
    });
  }
}

function boundaryPath() {
  const ctx = drawingContext;
  ctx.beginPath();
  ctx.moveTo(boundary[0].x, boundary[0].y);
  for (let i = 1; i < boundary.length; i++) {
    ctx.lineTo(boundary[i].x, boundary[i].y);
  }
  ctx.closePath();
}

function outsideClip() {
  const ctx = drawingContext;
  ctx.beginPath();
  ctx.rect(0, 0, W, H);
  ctx.moveTo(boundary[0].x, boundary[0].y);
  for (let i = 1; i < boundary.length; i++) {
    ctx.lineTo(boundary[i].x, boundary[i].y);
  }
  ctx.closePath();
  ctx.clip("evenodd");
}

function paintGround() {
  const g = createGraphics(400, 500);
  g.pixelDensity(1);
  g.loadPixels();

  for (let y = 0; y < g.height; y++) {
    for (let x = 0; x < g.width; x++) {
      const wx = x * 4;
      const wy = y * 4;
      const light = illumination(wx, wy);
      const cloud = noise(x * 0.014, y * 0.014);
      const mottling = noise(x * 0.067 + 30, y * 0.067);
      const grain = random(-3, 3);
      const pigment = light * (0.48 + cloud * 0.75);
      const stain = (mottling - 0.5) * 14;

      const j = 4 * (x + y * g.width);
      g.pixels[j]     = 13 + 75 * pigment + stain + grain;
      g.pixels[j + 1] = 20 + 49 * pigment + stain * 0.7 + grain;
      g.pixels[j + 2] = 23 + 23 * pigment + stain * 0.4 + grain;
      g.pixels[j + 3] = 255;
    }
  }

  g.updatePixels();
  image(g, 0, 0, W, H);
  g.remove();
}

// p5.js 1.11
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  background(25, 33, 37);
  const ctx = drawingContext;
  const palette = [
    [156, 105, 79],
    [184, 153, 110],
    [111, 133, 135],
    [78, 98, 107],
    [160, 157, 135],
    [71, 78, 76]
  ];

  // 沉积的底色。
