    const warm = constrain((y - 900) / 1100, 0, 1);
    fill(
      32 + n * 28 + warm * 12,
      40 + n * 27,
      43 + n * 24 - warm * 5,
      random(5, 19)
    );
    ellipse(x, y, random(5, 35), random(3, 19));
  }

  // 布面上几乎被磨平的短痕。
  for (let i = 0; i < 16000; i++) {
    const x = random(width);
    const y = random(height);
    stroke(164, 158, 136, random(3, 15));
    strokeWeight(random(0.4, 1.2));
    line(x, y, x + random(2, 12), y + random(-1.2, 1.2));
  }

  // 缺席的形状：不规则、略微倾斜，没有光环。
  const hole = new Path2D();
  const boundary = [];
  const cx = 828;
  const cy = 908;
  const rotation = -0.115;

  for (let i = 0; i < 360; i++) {
