    const irregularity =
      1 +
      0.032 * sin(3 * t + 0.8) +
      0.019 * sin(7 * t - 0.6) +
      0.011 * (noise(3 + cos(t) * 2, 3 + sin(t) * 2) - 0.5);

    const ex = 366 * cos(t) * irregularity *
      (1 + 0.055 * sin(t));
    const ey = 531 * sin(t) * irregularity;
    const x = cx + ex * cos(rotation) - ey * sin(rotation);
    const y = cy + ex * sin(rotation) + ey * cos(rotation);

