    } else {
      fill(99, 108, 105, 2 + n * 5);
    }
    ellipse(x, y, random(1, 9), random(0.6, 4));
  }

  for (let i = 0; i < 100; i++) {
    const x = random(420, 1230);
    const y = random(360, 1460);
    stroke(117, 121, 112, random(2, 7));
    strokeWeight(0.5);
    line(x, y, x + random(8, 42), y + random(-2, 2));
  }
  ctx.restore();

  // 所有织线在同一块缺席处被截断，绝不穿过它。
  const outside = new Path2D();
  outside.rect(0, 0, width, height);
  outside.addPath(hole);

  ctx.save();
  ctx.clip(outside, "evenodd");
  strokeCap(ROUND);
  noFill();

  function strand(baseX, phase, amplitude, thickness, rgb, opacity) {
    let previous = null;
    const top = random(60, 250);
    const bottom = random(1870, 2040);

    for (let y = top; y <= bottom; y += 9) {
      const depth = y / height;
      const wander =
        amplitude * sin(y * 0.0038 + phase) +
        32 * sin(y * 0.008 + phase * 1.9) +
        40 * (noise(baseX * 0.006, y * 0.002) - 0.5);

      const lean = 62 * sin(depth * PI) * sin(phase * 0.7);
      const x = baseX + wander + lean;
      const grain = noise(baseX * 0.018 + 20, y * 0.019);
      const a = opacity * (0.30 + 0.70 * depth) *
        (0.38 + 0.62 * grain);

      if (previous) {
        stroke(rgb[0], rgb[1], rgb[2], a);
        strokeWeight(thickness * (0.7 + grain * 0.6));
        line(previous.x, previous.y, x, y);
      }
      previous = { x, y };
    }
  }

  // 宽而干涩的旧颜料，埋在细线下面。
  for (let i = 0; i < 76; i++) {
    strand(
      random(135, 1480),
      random(TWO_PI),
      random(28, 108),
      random(9, 31),
      random(palette),
      random(7, 23)
    );
  }

  // 经线：带有重量、偏斜和不均匀的磨损。
  for (let i = 0; i < 290; i++) {
    strand(
      map(i, 0, 289, 95, 1505) + random(-13, 13),
      random(TWO_PI),
      random(13, 78),
      random(0.65, 2.8),
      random(palette),
      random(65, 150)
    );
  }

  // 纬线：间断地连起仍然存在的部分。
  for (let row = 0; row < 136; row++) {
    const baseY = map(row, 0, 135, 126, 1935) + random(-7, 7);
    const phase = random(TWO_PI);
    const col = random(palette);
    const weight = random(0.45, 1.65);
    let last = null;

    for (let x = 70; x <= 1530; x += 8) {
      const bend =
        17 * sin(x * 0.006 + phase) +
        28 * (noise(x * 0.003, baseY * 0.009) - 0.5);
      const y = baseY + bend;
      const wear = noise(x * 0.018, baseY * 0.022);

      if (last && wear > 0.31) {
        stroke(
          col[0], col[1], col[2],
          18 + 54 * wear * (0.35 + 0.65 * baseY / height)
        );
        strokeWeight(weight);
        line(last.x, last.y, x, y);
      }
      last = { x, y };
    }
  }

  // 下部更密的纠缠：没有一个可辨认的生命形象。
  for (let i = 0; i < 170; i++) {
    const x = random(170, 1440);
    const y = random(1480, 1960);
    const col = random(palette);
    stroke(col[0], col[1], col[2], random(20, 65));
    strokeWeight(random(0.5, 1.7));
    noFill();
    bezier(
      x - random(10, 110), y + random(15, 80),
      x + random(-150, 120), y - random(55, 160),
      x + random(-100, 170), y + random(25, 110),
      x + random(10, 105), y - random(25, 110)
    );
  }

  // 少数纤维在切口外留下短暂的毛边。
  for (let i = 0; i < 300; i++) {
    const p = random(boundary);
    let dx = p.x - cx;
    let dy = p.y - cy;
    const d = sqrt(dx * dx + dy * dy);
    dx /= d;
    dy /= d;

    const len = random(2, 17);
    const col = random(palette);
    stroke(col[0], col[1], col[2], random(18, 75));
    strokeWeight(random(0.4, 1.2));
    line(
      p.x + dx * random(0, 3),
      p.y + dy * random(0, 3),
      p.x + dx * len + random(-3, 3),
      p.y + dy * len + random(-3, 3)
    );
  }

  // 深色的磨损，避免织物显得过于完整。
  for (let i = 0; i < 8500; i++) {
    const x = random(width);
    const y = random(height);
    stroke(18, 26, 30, random(10, 44));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(-3, 3), y + random(2, 14));
  }

  // 四周的沉暗由稀薄笔触叠出，不形成装饰性画框。
  noFill();
  for (let i = 0; i < 90; i++) {
    stroke(13, 20, 24, 2.8);
    strokeWeight(3);
    rect(i * 1.1, i * 1.25,
         width - i * 2.2, height - i * 2.5);
  }
  ctx.restore();

  // 最后一层统一的细颗粒。
  noStroke();
  for (let i = 0; i < 44000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.5) fill(239, 228, 205, random(3, 11));
    else fill(8, 15, 20, random(3, 12));
    ellipse(x, y, random(0.5, 1.7), random(0.5, 1.5));
  }
}

const W = 1600, H = 2000;
const cx = 800, cy = 800, R = 470;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function sstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

// 一点"是自己"的程度：在圆内且未被溶解时接近 1
function identity(x, y) {
  let d = dist(x, y, cx, cy);
  let inside = 1 - sstep(R * 0.82, R * 1.04, d);
  let n = noise(x * 0.004, y * 0.004, 7.3);
  let t = (y - (cy - R * 0.15)) / (R * 1.5) + (n - 0.5) * 0.7;
  let keep = 1 - constrain(t, 0, 1);
  keep = keep * keep * (3 - 2 * keep);
  return inside * keep;
}

function flowAngle(x, y, w) {
  // 外部的河：大体向下，缓慢蜿蜒
  let fa = HALF_PI + (noise(x * 0.0011, y * 0.0011) - 0.5) * 2.4;
  // 内部的年轮：绕中心旋转
  let ta = atan2(y - cy, x - cx) + HALF_PI;
  let vx = lerp(cos(fa), cos(ta), w);
  let vy = lerp(sin(fa), sin(ta), w);
  return atan2(vy, vx);
}

function draw() {
  background(238, 232, 220);

  // 纸面颗粒
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = random(-9, 9) + (noise((i / 4) % W * 0.01, floor(i / 4 / W) * 0.01) - 0.5) * 14;
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();

  // 形体背后极淡的暖光
  noStroke();
  for (let r = R * 1.35; r > 0; r -= 6) {
    fill(214, 168, 108, 1.6);
    ellipse(cx, cy - 20, r * 2, r * 2);
  }

  // 流线
  const N = 9500;
  for (let k = 0; k < N; k++) {
    let x, y;
    if (k < 3800) {
      let a = random(TWO_PI);
      let rr = R * sqrt(random());
      x = cx + cos(a) * rr;
      y = cy + sin(a) * rr;
    } else {
      x = random(-100, W + 100);
      y = random(-150, H + 50);
    }
    let steps = 110;
    for (let s = 0; s < steps; s++) {
      let w = identity(x, y);
      let ang = flowAngle(x, y, w);
      let len = 2.3;
      let nx = x + cos(ang) * len;
      let ny = y + sin(ang) * len;
      let fadeEnds = sin(PI * s / steps);
      let r = lerp(72, 96, w);
      let g = lerp(84, 54, w);
      let b = lerp(98, 30, w);
      let al = lerp(30, 72, w) * (0.35 + 0.65 * fadeEnds);
      stroke(r, g, b, al);
      strokeWeight(lerp(0.8, 1.25, w));
      line(x, y, nx, ny);
      x = nx;
      y = ny;
      if (x < -150 || x > W + 150 || y < -200 || y > H + 100) break;
    }
  }

  // 溶解边缘：向下飘散的微粒
  noStroke();
  for (let i = 0; i < 4200; i++) {
    let a = random(TWO_PI);
    let rr = R * 1.05 * sqrt(random());
    let x = cx + cos(a) * rr;
    let y = cy + sin(a) * rr;
    let w = identity(x, y);
    if (w > 0.04 && w < 0.75) {
      let drift = random() * (1 - w) * 380;
      let px = x + (noise(x * 0.01, y * 0.01) - 0.5) * drift * 0.6;
      let py = y + drift;
      let sz = random(0.8, 2.6) * (0.5 + w);
      fill(120, 72, 38, 40 + 90 * w);
      ellipse(px, py, sz, sz);
    }
  }

  // 暗角
  let ctx = drawingContext;
  let grad = ctx.createRadialGradient(cx, 950, 350, cx, 1000, 1450);
  grad.addColorStop(0, 'rgba(40,34,28,0)');
  grad.addColorStop(1, 'rgba(40,34,28,0.38)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
}

// 水绕过的地方
const W = 1600, H = 2000;
const cx = 800, cy = 760;   // 缺席的中心
const ra = 165, rb = 250;   // 缺席的形状（竖直的椭圆）

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // 背景：墨蓝，越往下越深
  noFill();
  for (let y = 0; y < H; y++) {
    let t = y / H;
    let c1 = color(18, 22, 36);
    let c2 = color(7, 8, 15);
    let c = lerpColor(c1, c2, t);
    // 缺席附近有一点暖意
    let d = abs(y - cy) / 900;
    let warm = max(0, 1 - d) * 0.25;
    c = lerpColor(c, color(40, 34, 32), warm);
    stroke(c);
    line(0, y, W, y);
  }

  // 柔和的光晕：缺席是亮的
  noStroke();
  for (let i = 140; i >= 0; i--) {
    let s = 1 + (i / 140) * 2.6;
    fill(255, 232, 196, 2.2);
    ellipse(cx, cy, ra * 2 * s, rb * 2 * s);
  }
  for (let i = 40; i >= 0; i--) {
    let s = 0.7 + (i / 40) * 0.32;
    fill(250, 240, 222, 10);
    ellipse(cx, cy, ra * 2 * s, rb * 2 * s);
  }

  // 流线
  const N = 1500;
  const step = 2.4;
  strokeWeight(0.9);
  noFill();
  for (let i = 0; i < N; i++) {
    let x = map(i, 0, N, -80, W + 80) + random(-1.2, 1.2);
    let y = -10;
    let pts = [[x, y]];
    for (let k = 0; k < 1200; k++) {
      let v = vel(x, y);
      if (v === null) break;
      x += v[0] * step;
      y += v[1] * step;
      pts.push([x, y]);
      if (pts.length >= 18) {
        drawChunk(pts);
        pts = [pts[pts.length - 1]];
      }
      if (y > H + 10 || x < -120 || x > W + 120) break;
    }
    if (pts.length > 1) drawChunk(pts);
  }

  // 尾迹中漂浮的微光
  noStroke();
  for (let i = 0; i < 900; i++) {
    let dy = pow(random(), 1.6) * 1200;
    let spread = ra * 0.9 + dy * 0.18;
    let px = cx + randomGaussian() * spread * 0.45;
    let py = cy + rb * 0.9 + dy;
    let a = 70 * exp(-dy / 700);
    fill(255, 225, 175, a);
    let r = random(0.8, 2.4);
    ellipse(px, py, r, r);
  }

  // 颗粒质感
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = random(-7, 7);
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

// 绕过椭圆的势流 + 轻微的噪声 + 下游的尾迹
function vel(x, y) {
  let dx = x - cx, dy = y - cy;
  let q = dx / ra, p = dy / rb;
  let r2 = p * p + q * q;
  if (r2 < 1.01) return null;
  let A = p * p - q * q;
  let B = 2 * p * q;
  let m = A * A + B * B + 1e-6;
  let vy = 1 - A / m;
  let vx = -B / m * 0.9;

  // 整个世界的缓慢摆动
  let n = noise(x * 0.0012, y * 0.0012);
  vx += (n - 0.5) * 0.5;

  // 尾迹：下游的扰动，逐渐平息
  if (dy > 0) {
    let spread = ra * 1.2 + dy * 0.16;
    let w = exp(-dy / 950) * exp(-(dx * dx) / (2 * spread * spread));
    vx += (noise(x * 0.005, y * 0.0035, 7) - 0.5) * 3.2 * w;
    vy *= 1 - 0.35 * w;
  }

  let len = sqrt(vx * vx + vy * vy);
  if (len < 0.02) return null;
  return [vx / len, vy / len];
}

function drawChunk(pts) {
  let mid = pts[floor(pts.length / 2)];
  let mx = mid[0], my = mid[1];
  let q = (mx - cx) / ra, p = (my - cy) / rb;
  let d = sqrt(p * p + q * q);
  let prox = exp(-max(0, d - 1) * 1.4);

  // 尾迹因子
  let wake = 0;
  if (my > cy) {
    let dy = my - cy;
    let spread = ra * 1.2 + dy * 0.16;
    wake = exp(-dy / 1100) * exp(-((mx - cx) * (mx - cx)) / (2 * spread * spread));
  }

  let cool = color(140, 156, 184);
  let warm = color(246, 214, 162);
  let t = constrain(prox * 0.9 + wake * 0.6, 0, 1);
  let c = lerpColor(cool, warm, t);
  let fade = 1 - constrain((my - 1500) / 700, 0, 0.45);
  c.setAlpha((34 + 95 * prox + 40 * wake) * fade);
  stroke(c);

  beginShape();
  for (let pt of pts) vertex(pt[0], pt[1]);
  endShape();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function fieldAngle(x, y) {
  let base = HALF_PI * 0.9;
  return base +
    (noise(x * 0.0011, y * 0.0011) - 0.5) * 2.6 +
    (noise(x * 0.004 + 50, y * 0.004 + 20) - 0.5) * 0.6;
}

function angDiff(target, a) {
  return atan2(sin(target - a), cos(target - a));
}

const COOL = [95, 110, 135];

function strand(x, y, dir, len, warm, w0) {
  for (let i = 0; i < len; i++) {
    let t = i / len;
    let fa = fieldAngle(x, y);
    dir += angDiff(fa, dir) * (0.008 + 0.14 * t * t);
    let nx = x + cos(dir) * 2.2;
    let ny = y + sin(dir) * 2.2;
    let k = pow(t, 0.7);
    let r = lerp(warm[0], COOL[0], k);
    let g = lerp(warm[1], COOL[1], k);
    let b = lerp(warm[2], COOL[2], k);
    let a = 210 * pow(1 - t, 1.3);
    stroke(r, g, b, a);
    strokeWeight(lerp(w0, 0.4, t));
    line(x, y, nx, ny);
    if (random() < 0.012) {
      noStroke();
      fill(r, g, b, a * 0.8);
      circle(nx + random(-6, 6), ny + random(-6, 6), random(1, 2.6));
      noFill();
    }
    x = nx; y = ny;
    if (x < -50 || x > width + 50 || y < -50 || y > height + 50) break;
  }
}

function draw() {
  // background gradient
  for (let y = 0; y < height; y++) {
    let t = y / height;
    stroke(lerp(16, 26, t), lerp(18, 30, t), lerp(26, 40, t));
    line(0, y, width, y);
  }

  // the world: an ever-flowing field
  noFill();
  for (let i = 0; i < 6000; i++) {
    let x = random(-100, width + 100);
    let y = random(-200, height);
    let len = floor(random(60, 200));
    stroke(110, 125, 150, random(10, 26));
    strokeWeight(random(0.5, 1.1));
    beginShape();
    for (let s = 0; s < len; s++) {
      vertex(x, y);
      let a = fieldAngle(x, y);
      x += cos(a) * 2;
      y += sin(a) * 2;
    }
    endShape();
  }

  let cx = 800, cy = 800;

  // faint warmth around the living pattern
  noStroke();
  for (let i = 70; i > 0; i--) {
    fill(220, 170, 110, 1.6);
    ellipse(cx, cy, i * 15, i * 15 * 1.05);
  }

  // the life: a unique whorl, loosening from the outside in
  noFill();
  let rMin = 24, rMax = 480;
  for (let r = rMin; r <= rMax; r += 6) {
    let rn = (r - rMin) / (rMax - rMin);
    let warm = [lerp(242, 205, rn), lerp(228, 145, rn), lerp(200, 85, rn)];
    let ox = cx + (noise(r * 0.005, 1) - 0.5) * 40;
    let oy = cy + (noise(r * 0.005, 2) - 0.5) * 40;
    let phiR = HALF_PI * 0.85 + (noise(r * 0.01, 7) - 0.5) * 0.6;
    let gapW = lerp(0.03, 2.3, pow(rn, 1.3)) * (0.7 + 0.6 * noise(r * 0.02, 3));
    let a0 = phiR + gapW / 2;
    let a1 = phiR - gapW / 2 + TWO_PI;

    let rad = (th) =>
      r * (1 + 0.08 * sin(2 * th)) +
      (noise(cos(th) * 1.2 + 10, sin(th) * 1.2 + 10, r * 0.004) - 0.5) * 60 * (0.3 + rn);

    let n = floor(r * 0.9) + 40;
    stroke(warm[0], warm[1], warm[2], 205);
    strokeWeight(lerp(1.6, 1.2, rn));
    beginShape();
    for (let i = 0; i <= n; i++) {
      let th = lerp(a0, a1, i / n);
      let rr = rad(th);
      vertex(ox + cos(th) * rr, oy + sin(th) * rr);
    }
    endShape();

    // the two broken ends let go
    let rr0 = rad(a0), rr1 = rad(a1);
    strand(ox + cos(a0) * rr0, oy + sin(a0) * rr0, a0 - HALF_PI, floor(random(200, 520)), warm, 1.4);
    strand(ox + cos(a1) * rr1, oy + sin(a1) * rr1, a1 + HALF_PI, floor(random(200, 520)), warm, 1.4);

    // what was in the gap is already drifting
    let cnt = floor(gapW * r / 22);
    for (let k = 0; k < cnt; k++) {
      let th = phiR + random(-gapW / 2, gapW / 2);
      let rr = rad(th) + random(-3, 3);
      let d = th + (random() < 0.5 ? HALF_PI : -HALF_PI) + random(-0.3, 0.3);
      strand(ox + cos(th) * rr, oy + sin(th) * rr, d, floor(random(80, 380)), warm, 1.1);
    }
  }

  // vignette
  let ctx = drawingContext;
  let grd = ctx.createRadialGradient(cx, cy + 200, 300, cx, cy + 200, 1500);
  grd.addColorStop(0, 'rgba(10,12,18,0)');
  grd.addColorStop(1, 'rgba(8,9,14,0.6)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, width, height);

  // grain
  for (let i = 0; i < 50000; i++) {
    stroke(random(255), random(6, 14));
    strokeWeight(1);
    point(random(width), random(height));
  }
}

let CX = 800, CY = 720, R = 330;
let cTop, cMid, cBot;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  cTop = color(14, 18, 34);
  cMid = color(40, 46, 68);
  cBot = color(172, 168, 162);
}

function bgAt(y) {
  let t = constrain(y / height, 0, 1);
  if (t < 0.55) return lerpColor(cTop, cMid, t / 0.55);
  return lerpColor(cMid, cBot, pow((t - 0.55) / 0.45, 1.3));
}

function warm() {
  let n = random();
  let a = color(236, 178, 126);
  let b = color(196, 96, 82);
  let c = color(250, 222, 180);
  return n < 0.5 ? lerpColor(a, b, random()) : lerpColor(a, c, random());
}

function draw() {
  // background field
  for (let y = 0; y < height; y++) {
    stroke(bgAt(y));
    line(0, y, width, y);
  }

  // drifting flow of the surrounding world
  for (let i = 0; i < 5000; i++) {
    let x = random(width), y = random(height);
    let c = bgAt(y);
    let r = red(c) + random(-18, 18), g = green(c) + random(-18, 18), b = blue(c) + random(-10, 25);
    stroke(r, g, b, 30);
    strokeWeight(random(0.6, 1.8));
    for (let k = 0; k < 40; k++) {
      let ang = noise(x * 0.0015, y * 0.0015) * TWO_PI * 2;
      let nx = x + cos(ang) * 2.2, ny = y + sin(ang) * 2.2;
      line(x, y, nx, ny);
      x = nx; y = ny;
    }
  }

  // faint glow of the form
  noStroke();
  for (let r = 1100; r > 0; r -= 12) {
    fill(210, 140, 105, 2.2);
    ellipse(CX, CY + (1100 - r) * 0.02, r, r * 1.05);
  }

  // the warm interior: still a whole, mostly
  for (let i = 0; i < 26000; i++) {
    let rr = R * sqrt(random());
    let a = random(TWO_PI);
    let s = sin(a);
    let d = rr / R;
    if (s > 0 && random() < s * d * 0.85) continue;
    let x = CX + cos(a) * rr, y = CY + s * rr;
    let c = warm();
    c.setAlpha(random(70, 150));
    stroke(c);
    strokeWeight(random(1, 3.2));
    point(x, y);
  }

  // dissolving: what was inside becomes the field
  for (let i = 0; i < 4200; i++) {
    let a = random(PI * 0.03, PI * 0.97);
    let rr = R * (0.55 + 0.5 * random());
    let x = CX + cos(a) * rr, y = CY + sin(a) * rr;
    let steps = floor(40 + pow(random(), 2) * 420);
    let c0 = warm();
    let sp = random(1.6, 2.8);
    for (let k = 0; k < steps; k++) {
      let t = k / steps;
      let ang = noise(x * 0.002, y * 0.002 + 100) * TWO_PI * 1.6;
      let vx = cos(ang) * 1.2 + (x - CX) * 0.0018;
      let vy = sin(ang) * 1.0 + sp;
      let nx = x + vx, ny = y + vy;
      let c = lerpColor(c0, bgAt(ny), pow(t, 0.6));
      c.setAlpha(150 * (1 - t) + 18);
      stroke(c);
      strokeWeight(lerp(2.2, 0.6, t));
      line(x, y, nx, ny);
      x = nx; y = ny;
      if (y > height) break;
    }
  }

  // scattered motes below: which one was it?
  for (let i = 0; i < 9000; i++) {
    let y = lerp(CY + R, height, pow(random(), 0.8));
    let x = CX + randomGaussian() * (250 + (y - CY) * 0.45);
    let t = constrain((y - CY - R) / (height - CY - R), 0, 1);
    let c = lerpColor(warm(), bgAt(y), 0.35 + t * 0.6);
    c.setAlpha(140 * (1 - t * 0.7));
    stroke(c);
    strokeWeight(random(0.8, 2.2));
    point(x, y);
  }

  // the membrane: held at the top, released at the bottom
  for (let pass = 0; pass < 3; pass++) {
    for (let a = 0; a < TWO_PI; a += 0.0035) {
      let s = sin(a);
      let keep = map(s, -1, 1, 1, 0.03);
      if (random() > keep) continue;
      let rr = R + (noise(a * 3, pass) - 0.5) * 8 + (s > 0 ? s * random(0, 40) : 0);
      let x = CX + cos(a) * rr, y = CY + s * rr;
      let x2 = CX + cos(a + 0.006) * rr, y2 = CY + sin(a + 0.006) * rr;
      stroke(252, 218, 178, 170 * keep + 25);
      strokeWeight(1 + keep * 2);
      line(x, y, x2, y2);
    }
  }

  // grain
  for (let i = 0; i < 70000; i++) {
    stroke(random() < 0.5 ? 255 : 0, random(6, 16));
    strokeWeight(1);
    point(random(width), random(height));
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  // —— 夜的底色：竖向渐变 ——
  let top = color(6, 8, 20);
  let bot = color(20, 16, 30);
  for (let y = 0; y < height; y++) {
    stroke(lerpColor(top, bot, y / height));
    line(0, y, width, y);
  }

  // —— 周围的长流：万物共同的流场 ——
  strokeWeight(1);
  for (let i = 0; i < 7000; i++) {
    let x = random(-100, width + 100);
    let y = random(-100, height + 100);
    let a0 = random(4, 12);
    stroke(120, 140, 185, a0);
    for (let s = 0; s < 90; s++) {
      let ang = fieldAngle(x, y);
      let nx = x + cos(ang) * 3;
      let ny = y + sin(ang) * 3 - 0.8;
      line(x, y, nx, ny);
      x = nx; y = ny;
    }
  }

  // —— 微尘 ——
  noStroke();
  for (let i = 0; i < 2500; i++) {
    fill(170, 185, 220, random(10, 60));
    let r = random(0.6, 1.8);
    circle(random(width), random(height), r);
  }

  let cx = 800, cy = 1300;

  // —— 漩涡背后的微光 ——
  for (let r = 520; r > 0; r -= 4) {
    let t = 1 - r / 520;
    fill(255, 170, 90, 1.2 * t * t * 3);
    ellipse(cx, cy, r * 2, r * 2.5);
  }

  // —— 一个“自我”：聚拢、旋转、然后松开 ——
  blendMode(ADD);
  let warm = color(255, 185, 105);
  let cool = color(110, 135, 190);
  let STEPS = 520;

  for (let i = 0; i < 3200; i++) {
    let a = random(TWO_PI);
    let r = abs(randomGaussian(0, 110)) + 8;
    r = min(r, 380);
    // 越靠外，越早离开；最核心的几乎不离开
    let leaveFactor = map(r, 0, 380, 1.6, 0.15);
    let leaveStep = floor(random(0, STEPS) * leaveFactor);
    let x = cx + cos(a) * r;
    let y = cy + sin(a) * r * 1.25;
    let vx = 0, vy = 0;
    let left = false;
    let since = 0;
    let w = random(0.6, 1.6);
    let dir = 1;

    for (let s = 0; s < STEPS; s++) {
      let px = x, py = y;
      if (s < leaveStep) {
        a += dir * 1.6 / max(r, 18);
        x = cx + cos(a) * r;
        y = cy + sin(a) * r * 1.25;
      } else {
        if (!left) {
          left = true;
          let sp = 1.6 / max(r, 18) * r;
          vx = -sin(a) * sp;
          vy = cos(a) * sp * 1.25;
        }
        since++;
        let ang = fieldAngle(x, y);
        let k = min(1, since / 120);
        vx = lerp(vx, cos(ang) * 2.4, 0.04 + 0.04 * k);
        vy = lerp(vy, sin(ang) * 2.4 - 1.1, 0.04 + 0.04 * k);
        x += vx;
        y += vy;
      }

      let cool_t = min(1, since / 260);
      let c = lerpColor(warm, cool, cool_t);
      let alpha = left ? map(cool_t, 0, 1, 26, 3) : 20;
      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(left ? w * (1 - cool_t * 0.6) : w);
      line(px, py, x, y);
    }
  }

  // —— 仍在燃烧的核心 ——
  noStroke();
  for (let r = 90; r > 0; r -= 2) {
    let t = 1 - r / 90;
    fill(255, 210, 150, 3 + t * 6);
    ellipse(cx, cy, r * 2, r * 2.4);
  }
  for (let i = 0; i < 400; i++) {
    let rr = abs(randomGaussian(0, 28));
    let aa = random(TWO_PI);
    fill(255, 230, 190, random(20, 70));
    circle(cx + cos(aa) * rr, cy + sin(aa) * rr * 1.25, random(1, 2.5));
  }
  blendMode(BLEND);

  // —— 颗粒与暗角 ——
  for (let i = 0; i < 60000; i++) {
    let v = random(255);
    fill(v, v, v, 6);
    rect(random(width), random(height), 1, 1);
  }
  noFill();
  for (let i = 0; i < 260; i++) {
    stroke(0, 0, 0, 3.2);
    strokeWeight(6);
    ellipse(width / 2, height / 2, width * 0.9 + i * 8, height * 0.9 + i * 8);
  }
}

function fieldAngle(x, y) {
  let n = noise(x * 0.0013, y * 0.0013);
  return -HALF_PI + (n - 0.5) * TWO_PI * 1.6;
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  background(6, 7, 12);

  // 1. 绘制深空背景与低频星云纹理
  drawCosmicBackground();

  // 2. 设置混合模式为叠加，表现能量与光的消散
  blendMode(ADD);

  // 3. 绘制上升的灵魂/物质流（从具象结构到无形流体）
  drawAscendingStreams();

  // 4. 绘制生命的核心：下方的温暖紧绷的几何有机体，正在向上瓦解
  drawCoreAndDissolution();

  // 5. 绘制虚空的吸积与星尘：上方的冷冽、广阔与静谧
  drawVoidDust();

  // 6. 恢复正常混合模式，绘制一些遮挡性的暗物质微粒，增加空间纵深
  blendMode(BLEND);
  drawDarkMatter();

  // 7. 边缘暗角处理，让视线聚焦于中心的转化过程
  drawVignette();
}

function drawCosmicBackground() {
  noStroke();
  for (let y = 0; y < height; y += 4) {
    let inter = map(y, 0, height, 0, 1);
    // 上方是极深的虚空蓝黑，下方带有一丝极暗的暖褐（生命的土壤）
    let c = lerpColor(color(4, 6, 14), color(18, 10, 12), pow(inter, 1.5));
    fill(c);
    rect(0, y, width, 4);
  }

  // 背景星云噪点
  loadPixels();
  let d = pixelDensity();
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      let n = noise(x * 0.0015, y * 0.0015);
      let n2 = noise(x * 0.01, y * 0.01);
      let idx = 4 * ((y * d) * width * d + (x * d));

      let yRatio = y / height;
      // 在画布中部偏上制造一片微弱的冷色星云
      let cloud = pow(n, 3) * 35 * (1 - yRatio);
      // 在下方制造温暖的辉光基底
      let warmth = pow(n, 2) * 25 * pow(yRatio, 2);

      pixels[idx] += warmth + cloud * 0.4 + (n2 - 0.5) * 8;
      pixels[idx + 1] += warmth * 0.6 + cloud * 0.7 + (n2 - 0.5) * 8;
      pixels[idx + 2] += cloud * 1.2 + (n2 - 0.5) * 8;
    }
  }
  updatePixels();
}

function drawCoreAndDissolution() {
  let cx = width * 0.5;
  let cy = height * 0.82;

  // 生命核心的底层辉光
  noStroke();
  for (let r = 600; r > 0; r -= 5) {
    let alpha = map(r, 600, 0, 0, 4);
    fill(255, 100, 40, alpha);
    ellipse(cx, cy, r * 1.6, r * 1.2);
  }

  // 生成生命结构的节点
  let nodes = [];
  let numNodes = 1400;

  for (let i = 0; i < numNodes; i++) {
    // 越往下越密集，越往上越发散
    let t = pow(random(1), 1.6); 
    let y = map(t, 0, 1, height * 0.95, height * 0.15);

    // 宽度随着高度增加而先收拢（阈限）再极度扩张（消融）
    let normY = map(y, height * 0.95, height * 0.15, 0, 1);
    let spread;
    if (normY < 0.3) {
      // 生命形态的包裹感
      spread = sin(map(normY, 0, 0.3, 0.2, PI)) * 350;
    } else {
      // 越过死亡阈限后的消散
      spread = pow(normY - 0.2, 2.2) * 1800 + 80;
    }

    // 加入柏林噪声的扭曲，模拟洋流或风
    let angle = noise(y * 0.003, i * 0.01) * TWO_PI * 2;
    let rad = (randomGaussian() * 0.4) * spread;
    let x = cx + cos(angle) * rad + (noise(y * 0.005) - 0.5) * 300 * normY;

    nodes.push({x: x, y: y, normY: normY, size: random(1, 5)});
  }

  // 绘制连接线（秩序与结构的象征）
  // 只在下部（生）紧密连接，向上逐渐断裂（死）
  for (let i = 0; i < nodes.length; i++) {
    let n1 = nodes[i];
    if (n1.normY > 0.65) continue; // 高处不再有结构连接

    let maxDist = map(n1.normY, 0, 0.65, 90, 20);
    let connectChance = map(n1.normY, 0, 0.65, 0.8, 0.05);

    for (let j = i + 1; j < nodes.length; j++) {
      let n2 = nodes[j];
      let d = dist(n1.x, n1.y, n2.x, n2.y);
      if (d < maxDist && random(1) < connectChance) {
        let alpha = map(d, 0, maxDist, 120, 0) * pow(1 - n1.normY / 0.65, 1.5);

        // 颜色从炽热的金红（生之渴望）过渡到苍白的青紫（消逝）
        let c = getTransitionColor(n1.normY, alpha);
        stroke(c);
        strokeWeight(map(n1.normY, 0, 0.65, 1.5, 0.3));
        line(n1.x, n1.y, n2.x, n2.y);
      }
    }
  }

  // 绘制节点本身（物质微粒）
  noStroke();
  for (let i = 0; i < nodes.length; i++) {
    let n = nodes[i];
    let alpha = map(n.normY, 0, 1, 220, 30);
    let c = getTransitionColor(n.normY, alpha);
    fill(c);

    // 下方的粒子棱角分明（几何感），上方的粒子化为柔和的圆点
    if (n.normY < 0.25 && random(1) < 0.5) {
      push();
      translate(n.x, n.y);
      rotate(random(TWO_PI));
      rectMode(CENTER);
      rect(0, 0, n.size * 2.5, n.size * 2.5);
      pop();
    } else {
      ellipse(n.x, n.y, n.size * 2, n.size * 2);
      // 发光光晕
      if (random(1) < 0.3) {
        fill(red(c), green(c), blue(c), alpha * 0.2);
        ellipse(n.x, n.y, n.size * 8, n.size * 8);
      }
    }
  }

  // 底部核心的几何神圣感（象征生命精密的构造）
  strokeWeight(0.8);
  noFill();
  for (let i = 0; i < 60; i++) {
    let r = random(50, 380);
    let a1 = random(TWO_PI);
    let a2 = a1 + random(0.2, PI * 0.8);
    // 越靠上圆环越破碎
    let yOffset = random(-150, 100);
    let collapse = map(yOffset, -150, 100, 0.2, 1);
    stroke(255, 180, 100, random(20, 90) * collapse);

    push();
    translate(cx, cy + yOffset);
    rotate(noise(i) * PI);
    scale(1, random(0.4, 0.9)); // 透视感椭圆
    arc(0, 0, r * 2, r * 2, a1, a2);
    pop();
  }
}

function drawAscendingStreams() {
  // 模拟生命能量解绑后，顺着宇宙暗流飘散的轨迹
  let numStreams = 3500;
  noFill();

  for (let i = 0; i < numStreams; i++) {
    // 起点集中在下方的生命核心区，以及中部的过渡区
    let startY = random(height * 0.3, height * 0.92);
    let normStartY = map(startY, height * 0.92, height * 0.1, 0, 1);

    let spread = pow(normStartY, 2) * 900 + 150;
    let startX = width * 0.5 + randomGaussian() * spread * 0.5;

    let x = startX;
    let y = startY;

    let steps = random(40, 180);
    let strokeW = random(0.3, 2.2);
    strokeWeight(strokeW);

    beginShape();
    for (let s = 0; s < steps; s++) {
      let normY = constrain(map(y, height * 0.9, height * 0.05, 0, 1), 0, 1);

      // 越往上越透明，融入虚空
      let fadeIn = constrain(s / 15, 0, 1);
      let fadeOut = constrain((steps - s) / 30, 0, 1);
      let heightFade = pow(1 - normY * 0.85, 1.5);
      let alpha = 35 * fadeIn * fadeOut * heightFade;

      let c = getTransitionColor(normY, alpha);
      stroke(c);
      vertex(x, y);

      // 噪声场控制流向：总体向上，但随着高度增加，横向的涡流变大
      let nScale = map(normY, 0, 1, 0.004, 0.0015);
      let angle = noise(x * nScale, y * nScale, i * 0.0005) * TWO_PI * 2;

      // 向上牵引的力（死亡的不可逆性）
      let upForce = map(normY, 0, 1, -2.5, -1.2);
      // 横向消散的力
      let sideForce = cos(angle) * map(normY, 0, 1, 0.8, 3.5);

      x += sideForce + (x - width * 0.5) * 0.002 * normY; // 轻微向外扩张
      y += upForce + sin(angle) * 1.2;
    }
    endShape();
  }
}

function drawVoidDust() {
  // 上方虚空中的微粒，它们是曾经的生命，也是未来的星辰
  noStroke();
  for (let i = 0; i < 6000; i++) {
    let y = pow(random(1), 1.4) * height * 0.85; // 偏向上方
    let x = random(width);

    // 利用噪声让星尘形成隐约的星云带
    let n = noise(x * 0.002, y * 0.002);
    if (random(1) > n * 1.4) continue;

    let normY = map(y, height * 0.85, 0, 0.2, 1);
    let distFromCenter = abs(x - width * 0.5) / (width * 0.5);

    let alpha = random(10, 120) * n * (1 - distFromCenter * 0.5);
    let c = getTransitionColor(normY, alpha);

    fill(c);
    let sz = random(0.5, 2.8);
    ellipse(x, y, sz, sz);

    // 极少数明亮的微粒，如同最后的回响
    if (random(1) < 0.015) {
      fill(200, 230, 255, alpha * 0.4);
      ellipse(x, y, sz * 6, sz * 6);
      fill(255, 255, 255, alpha * 1.5);
      ellipse(x, y, sz * 1.2, sz * 1.2);
    }
  }
}

function drawDarkMatter() {
  // 在生与死的交界处（阈限），绘制一些吸光的暗色絮状物，增强解构的戏剧性
  noStroke();
  for (let i = 0; i < 400; i++) {
    let y = random(height * 0.45, height * 0.95);
    let normY = map(y, height * 0.95, height * 0.45, 0, 1);
    let spread = map(normY, 0, 1, 250, 700);
    let x = width * 0.5 + randomGaussian() * spread * 0.4;

    let n = noise(x * 0.005, y * 0.005);
    fill(6, 7, 12, random(40, 150) * n);

    push();
    translate(x, y);
    rotate(noise(x * 0.01, y * 0.01) * TWO_PI);
    let w = random(10, 60) * (1 - normY * 0.5);
    let h = random(4, 20);
    ellipse(0, 0, w, h);
    pop();
  }
}

function drawVignette() {
  // 四周压暗，制造深邃的凝视感
  noFill();
  for (let i = 0; i < 250; i++) {
    let alpha = map(i, 0, 250, 180, 0);
    stroke(4, 5, 9, alpha * 0.15);
    strokeWeight(4);
    rect(i * 2, i * 2, width - i * 4, height - i * 4, 300 - i);
  }
}

// 核心色彩哲学：从生命的炽热（金、琥珀、深红）过渡到阈限的苍白（骨白、淡紫），最终归于虚空的深邃（青蓝、幽蓝）
function getTransitionColor(normY, alpha) {
  normY = constrain(normY, 0, 1);
  let c1 = color(255, 90, 30);   // 生命核心：炽热红橙
  let c2 = color(255, 190, 90);  // 生命张力：琥珀金
  let c3 = color(230, 220, 240); // 死亡阈限：褪色之白/淡紫（灵魂脱壳的瞬间）
  let c4 = color(90, 160, 210);  // 消散之中：星云青蓝
  let c5 = color(30, 60, 130);   // 归于宇宙：深空幽蓝

  let res;
  // 加入一点随机偏移，让色彩交织而不生硬
  let t = constrain(normY + randomGaussian() * 0.04, 0, 1);

  if (t < 0.2) {
    res = lerpColor(c1, c2, map(t, 0, 0.2, 0, 1));
  } else if (t < 0.45) {
    res = lerpColor(c2, c3, map(t, 0.2, 0.45, 0, 1));
  } else if (t < 0.75) {
    res = lerpColor(c3, c4, map(t, 0.45, 0.75, 0, 1));
  } else {
    res = lerpColor(c4, c5, map(t, 0.75, 1.0, 0, 1));
  }

  res.setAlpha(alpha);
  return res;
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);

  // 1. 绘制深邃的背景渐变（从底部的生命暗红到顶部的宇宙深蓝与纯黑）
  drawBackground();

  // 2. 绘制远景的星云与虚空肌理
  drawVoidNebula();

  // 3. 绘制生死交界的水平面/帷幕（The Threshold）
  drawThresholdVeil();

  // 4. 绘制生命之网的构建与消散（核心意象）
  drawUnbindingThreads();

  // 5. 绘制升腾的灵魂微粒与消散的余烬
  drawAscendingDust();

  // 6. 绘制绝对寂静的几何光环（象征永恒的秩序与归宿）
  drawEternalHalo();

  // 7. 画面整体质感叠加（胶片颗粒感）
  applyGrain();
}

function drawBackground() {
  noFill();
  for (let y = 0; y < height; y++) {
    let inter = y / height;
    let h, s, b;
    if (inter < 0.65) {
      // 上部：深邃虚空（深紫蓝到暗黑）
      let subInter = map(inter, 0, 0.65, 0, 1);
      h = lerp(230, 215, subInter);
      s = lerp(65, 50, subInter);
      b = lerp(3, 12, pow(subInter, 1.5));
    } else {
      // 下部：生命基底（从深青过渡到温暖的暗琥珀色）
      let subInter = map(inter, 0.65, 1, 0, 1);
      h = lerp(215, 22, pow(subInter, 0.8));
      s = lerp(50, 75, subInter);
      b = lerp(12, 16, subInter);
    }
    stroke(h, s, b);
    line(0, y, width, y);
  }
}

function drawVoidNebula() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 450; i++) {
    let x = random(width);
    let y = random(height * 0.85);
    let n = noise(x * 0.0015, y * 0.0015);
    let r = n * 450 + 50;

    let h = map(y, 0, height * 0.85, 240, 195) + random(-15, 15);
    let s = random(30, 60);
    let b = random(5, 15);
    let alpha = map(y, 0, height * 0.85, 0.004, 0.015) * n;

    // 越靠近中心轴线越亮
    let distToCenter = abs(x - width / 2);
    alpha *= map(distToCenter, 0, width / 2, 1.5, 0.2);

    fill(h, s, b, alpha);
    circle(x, y, r);
  }
  blendMode(BLEND);
}

function drawThresholdVeil() {
  blendMode(ADD);
  let baseY = height * 0.62;

  for (let i = 0; i < 180; i++) {
    let yOffset = randomGaussian(0, 60);
    let y = baseY + yOffset;
    let alpha = map(abs(yOffset), 0, 150, 0.04, 0.0);
    if (alpha <= 0) continue;

    stroke(200, 30, 80, alpha);
    strokeWeight(random(0.5, 2.5));
    noFill();

    beginShape();
    for (let x = 0; x <= width; x += 20) {
      let n = noise(x * 0.002, y * 0.01, i * 0.1);
      let wave = (n - 0.5) * 120;
      // 边缘衰减
      let edgeFade = sin(map(x, 0, width, 0, PI));
      vertex(x, y + wave * edgeFade);
    }
    endShape();
  }
  blendMode(BLEND);
}

function drawUnbindingThreads() {
  blendMode(ADD);
  let numThreads = 2400;
  let coreX = width / 2;
  let coreY = height * 0.86;

  for (let i = 0; i < numThreads; i++) {
    // 起点集中在底部中心（代表紧密聚合的个体生命）
    let angle = random(PI, TWO_PI);
    let radius = abs(randomGaussian(0, 180));
    let x = coreX + cos(angle) * radius * 1.6;
    let y = coreY + sin(angle) * radius * 0.4 + random(-30, 150);

    // 赋予每条生命线不同的初始色彩（黄金、赤铜、象牙白）
    let startHue = random(20, 48);
    let endHue = random(185, 230); // 消散时的灵魂蓝/银白
    let steps = int(random(350, 950));

    let prevX = x;
    let prevY = y;

    for (let s = 0; s < steps; s++) {
      let progress = s / steps;
      let heightFactor = constrain(map(y, height * 0.9, height * 0.15, 0, 1), 0, 1);

      // 噪声场控制流动
      let n1 = noise(x * 0.0025, y * 0.0025, i * 0.0005);
      let n2 = noise(x * 0.008, y * 0.008, 100 + i * 0.001);

      // 底部向中心收拢，产生纠缠感；上部向外扩散，产生解脱感
      let centerPull = 0;
      if (heightFactor < 0.38) {
        // 生之纠缠
        centerPull = (coreX - x) * 0.006 * (0.38 - heightFactor);
      } else {
        // 死之释然（越过临界线后轻轻散开）
        centerPull = (x - coreX) * 0.0015 * (heightFactor - 0.38);
      }

      let flowAngle = -HALF_PI + (n1 - 0.5) * PI * 1.1 + (n2 - 0.5) * 0.6;
      let speed = map(heightFactor, 0, 1, 1.2, 2.8);

      x += cos(flowAngle) * speed + centerPull;
      y += sin(flowAngle) * speed * 0.95;

      // 越过临界区（height * 0.62）时，线条开始断裂，化作虚无
      let breakProb = map(heightFactor, 0.3, 0.9, 0.0, 0.65);
      if (random() < breakProb) {
        prevX = x;
        prevY = y;
        continue;
      }

      // 颜色与透明度的演变
      let h = lerp(startHue, endHue, pow(heightFactor, 1.4));
      let sat = lerp(85, 15, pow(heightFactor, 1.8));
      let bri = lerp(95, 100, heightFactor);

      // 线条两头淡出，中间明亮
      let alpha = sin(progress * PI) * map(heightFactor, 0, 1, 0.09, 0.015);
      let sw = map(heightFactor, 0, 1, 1.6, 0.4) * sin(progress * PI);

      stroke(h, sat, bri, alpha);
      strokeWeight(sw);
      line(prevX, prevY, x, y);

      // 在断裂或转折处偶尔留下光点（记忆的结晶）
      if (heightFactor > 0.35 && random() < 0.003) {
        noStroke();
        fill(h, sat * 0.5, 100, alpha * 3);
        circle(x, y, random(1.5, 4));
      }

      prevX = x;
      prevY = y;

      if (y < 50 || x < 50 || x > width - 50) break;
    }
  }

  // 底部生命核心的高光（生之炽热）
  noStroke();
  for (let r = 600; r > 0; r -= 10) {
    let alpha = map(r, 600, 0, 0, 0.012);
    fill(35, 80, 90, alpha);
    ellipse(coreX, coreY + 40, r * 1.8, r * 0.7);
  }

  blendMode(BLEND);
}

function drawAscendingDust() {
  blendMode(ADD);
  noStroke();

  // 升腾的微粒（从临界线向上飘散）
  let numParticles = 5500;
  for (let i = 0; i < numParticles; i++) {
    let y = random(height * 0.05, height * 0.75);
    let heightNorm = map(y, height * 0.75, height * 0.05, 0, 1);

    // 水平分布受高斯分布与噪声共同影响，形成烟雾状上升结构
    let spread = map(heightNorm, 0, 1, 220, 550);
    let x = width / 2 + randomGaussian(0, spread);

    // 用噪声剔除部分粒子，形成空灵的通道
    let n = noise(x * 0.004, y * 0.004);
    if (n < 0.38) continue;

    let h = lerp(40, 210, pow(heightNorm, 0.9)) + random(-10, 10);
    let s = lerp(70, 5, heightNorm);
    let b = 100;

    let size = random(0.6, 2.8) * map(heightNorm, 0, 1, 1.2, 0.5);
    let alpha = random(0.05, 0.45) * (1 - pow(heightNorm, 2.5));

    // 绘制造型：柔和的光晕+明亮的核心
    fill(h, s, b, alpha * 0.25);
    circle(x, y, size * 4);
    fill(h, s * 0.5, b, alpha);
    circle(x, y, size);
  }
  blendMode(BLEND);
}

function drawEternalHalo() {
  // 画面上方代表“大寂静/虚空本源”的暗月与光环
  let cx = width / 2;
  let cy = height * 0.24;
  let radius = 240;

  // 1. 中心绝对的静默（吸光的深渊，但边缘温柔）
  noStroke();
  for (let r = radius * 1.5; r > 0; r -= 2) {
    let inter = r / (radius * 1.5);
    let alpha = map(pow(1 - inter, 2), 0, 1, 0, 0.15);
    fill(230, 55, 4, alpha);
    circle(cx, cy, r * 2);
  }

  // 2. 寂静之环（由极其细腻的微光纤维构成的圆环，下方开口以接纳升腾的灵魂）
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 900; i++) {
    let r = radius + randomGaussian(0, 12);
    let a1 = random(TWO_PI);
    let a2 = a1 + random(0.05, 0.4);

    // 环的底部（HALF_PI 附近）逐渐消隐，仿佛向下方敞开大门
    let distToBottom = abs(atan2(sin(a1) - sin(HALF_PI), cos(a1) - cos(HALF_PI)));
    let bottomFade = smoothstep(0.1, 1.2, distToBottom);

    // 环的顶部最亮，象征归宿
    let topGlow = map(sin(a1), -1, 1, 1.5, 0.3);

    let alpha = random(0.01, 0.05) * bottomFade * topGlow;
    stroke(205, 15, 95, alpha);
    strokeWeight(random(0.4, 1.5));
    arc(cx, cy, r * 2, r * 2, a1, a2);
  }

  // 3. 垂落的垂直微光（虚空对生命的温柔牵引）
  for (let i = 0; i < 160; i++) {
    let x = cx + randomGaussian(0, radius * 0.9);
    let yStart = cy + random(-radius * 0.5, radius * 1.2);
    let len = random(80, 450);

    let distFromCenter = abs(x - cx);
    let alpha = map(distFromCenter, 0, radius * 1.5, 0.035, 0.002);

    strokeWeight(random(0.4, 1.0));
    for (let y = yStart; y < yStart + len; y += 4) {
      let p = (y - yStart) / len;
      let curAlpha = alpha * sin(p * PI);
      stroke(200, 10, 100, curAlpha);
      point(x, y);
    }
  }
  blendMode(BLEND);
}

function applyGrain() {
  // 赋予画面古典油画/胶片的颗粒质感，消除数字冰冷感
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);

  for (let i = 0; i < totalPixels; i += 4) {
    let grain = (random() - 0.5) * 14;
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0.0, 1.0);
  return t * t * (3.0 - 2.0 * t);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 背景：从深邃的虚空到物质底层的微光
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r = lerp(4, 24, pow(t, 1.8));
    let g = lerp(6, 15, pow(t, 1.8));
    let b = lerp(14, 22, pow(t, 1.8));
    stroke(r, g, b);
    line(0, y, width, y);
  }

  // 2. 远景星尘：已经归还给宇宙的微粒
  for (let i = 0; i < 15000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    if (random() < n) {
      let a = map(y, 0, height, 60, 10) * random(0.2, 1);
      stroke(180, 200, 230, a);
      strokeWeight(random(0.5, 2.2));
      point(x, y);
    }
  }

  // 定义生命的颜色（温暖、沉重、凝聚）与消逝的颜色（轻盈、冷冽、自由）
  let lifeColors = [
    color(220, 65, 45),   // 血脉之红
    color(245, 155, 60),  // 琥珀之金
    color(190, 130, 100), // 尘土之赭
    color(130, 35, 50)    // 深邃之紫红
  ];
  let deathColors = [
    color(130, 175, 220), // 苍穹之蓝
    color(160, 215, 210), // 幽魂之青
    color(220, 230, 245), // 星辰之白
    color(80, 100, 150)   // 寂静之靛
  ];

  // 核心形态中心（生之凝聚点）
  let cx = width * 0.5;
  let cy = height * 0.76;

  // 3. 底层光晕：生命最后的余温与消散的灵光
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 200; i++) {
    let r = random(50, 650);
    let angle = random(TWO_PI);
    let ox = cx + cos(angle) * random(0, 120);
    let oy = cy + sin(angle) * random(0, 100);
    fill(30, 12, 8, 2);
    circle(ox, oy, r);
  }
  for (let i = 0; i < 150; i++) {
    let x = cx + random(-450, 450);
    let y = random(height * 0.15, height * 0.75);
    let r = random(100, 500);
    fill(8, 16, 28, 1.5);
    circle(x, y, r);
  }

  // 4. 主体：万千丝缕的解构与升华
  let numStrands = 3200;

  for (let i = 0; i < numStrands; i++) {
    // 起点：在中心区域形成一个复杂的拓扑结（生命的形态）
    let t = random(TWO_PI);
    let u = random(TWO_PI);
    let rad = random(20, 280) * pow(random(), 0.6);

    let x = cx + cos(t) * rad + sin(u * 3) * 45;
    let y = cy + sin(t) * rad * 0.75 + cos(u * 2) * 45;

    let cLife = random(lifeColors);
    let cDeath = random(deathColors);

    let maxSteps = int(random(300, 1400));
    let stepSize = random(1.5, 3.0);
    let strandWeight = random(0.4, 2.2);
    let isDustEmitter = random() < 0.25;

    for (let s = 0; s < maxSteps; s++) {
      let progress = s / maxSteps;
      let heightFactor = constrain(map(y, cy + 150, height * 0.05, 0, 1), 0, 1);

      // 混合进度：由时间进度与空间高度共同决定
      let state = constrain( progress * 0.65 + heightFactor * 0.55, 0, 1);

      // 颜色从温暖的纠缠过渡到冷冽的释放
      let c = lerpColor(cLife, cDeath, pow(state, 0.85));

      // 透明度：两头淡，中间浓，顶部化作虚无
      let alpha = sin(progress * PI) * map(state, 0, 1, 55, 12);
      if (y < height * 0.25) {
        alpha *= map(y, 0, height * 0.25, 0, 1);
      }

      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(strandWeight * (1 - state * 0.7));
      point(x, y);

      // 在解构的过程中，剥落出独立的微粒（尘埃与光点）
      if (isDustEmitter && state > 0.35 && random() < 0.018) {
        let dustDist = random(5, 80) * state;
        let dustAngle = random(TWO_PI);
        let dx = x + cos(dustAngle) * dustDist;
        let dy = y + sin(dustAngle) * dustDist;
        strokeWeight(random(0.8, 3.2) * (1 - state * 0.5));
        stroke(red(cDeath), green(cDeath), blue(cDeath), alpha * 2.5);
        point(dx, dy);
      }

      // 动力学演进：计算下一帧位置
      // 1) 凝聚力：围绕中心的旋转力场（维持生命形态的惯性）
      let dxCenter = x - cx;
      let dyCenter = y - cy;
      let angleCenter = atan2(dyCenter, dxCenter);
      let orbitalAngle = angleCenter + HALF_PI + sin(s * 0.03) * 0.6;

      // 2) 熵增与消散：柏林噪声构成的上升气流
      let n1 = noise(x * 0.0025, y * 0.0025, i * 0.0005);
      let n2 = noise(x * 0.008, y * 0.008, 100 + i * 0.001);
      let upAngle = -HALF_PI + map(n1, 0, 1, -PI * 0.55, PI * 0.55) + map(n2, 0, 1, -0.4, 0.4);

      // 根据状态权重合成运动方向
      let bindWeight = pow(1 - state, 2.2); // 束缚力随高度迅速衰减
      let vx = cos(orbitalAngle) * bindWeight + cos(upAngle) * (1 - bindWeight);
      let vy = sin(orbitalAngle) * bindWeight + sin(upAngle) * (1 - bindWeight);

      // 向上的宿命牵引
      vy -= 0.45 * state;

      // 越往高处，边界越模糊，横向扩散越自由
      vx += (noise(y * 0.01, s * 0.02) - 0.5) * 2.2 * state;

      x += vx * stepSize;
      y += vy * stepSize;

      if (y < 0 || x < 0 || x > width) break;
    }
  }

  // 5. 核心裂隙与骨骼感：在密集的底部刻画深邃的暗部，象征形体的瓦解
  blendMode(BLEND);
  for (let i = 0; i < 450; i++) {
    let t = random(TWO_PI);
    let rad = random(0, 260) * pow(random(), 0.8);
    let x = cx + cos(t) * rad;
    let y = cy + sin(t) * rad * 0.7;

    stroke(8, 6, 12, random(60, 160));
    strokeWeight(random(0.8, 3.5));
    noFill();
    beginShape();
    for (let s = 0; s < 50; s++) {
      vertex(x, y);
      let n = noise(x * 0.012, y * 0.012, i);
      let a = n * TWO_PI * 2;
      x += cos(a) * 2.5;
      y += sin(a) * 2.5 - 1.2; // 裂隙同样向上蔓延
    }
    endShape();
  }

  // 6. 升华的灵魂微光：在画面中上部点缀纯粹的光斑，如同消散后的顿悟与平静
  blendMode(ADD);
  for (let i = 0; i < 500; i++) {
    let x = cx + randomGaussian() * 320;
    let y = random(height * 0.05, height * 0.75);
    let distToCenter = dist(x, y, cx, cy);

    if (distToCenter < 900) {
      let c = random(deathColors);
      let a = map(y, height * 0.05, height * 0.75, 15, 70) * random(0.3, 1);
      let sz = random(1.5, 5);

      noStroke();
      fill(red(c), green(c), blue(c), a * 0.25);
      circle(x, y, sz * 4);
      fill(240, 250, 255, a);
      circle(x, y, sz * 0.8);
    }
  }

  // 7. 暗角与胶片颗粒：赋予画面庄重、永恒的质感
  blendMode(BLEND);
  loadPixels();
  let d = pixelDensity();
  let halfW = width / 2;
  let halfH = height / 2;
  let maxDist = dist(0, 0, halfW, halfH);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let distFromCenter = dist(x, y, halfW, halfH);
      let vig = map(distFromCenter, maxDist * 0.45, maxDist, 1, 0.25, true);
      let grain = random(-7, 7);

      for (let dy = 0; dy < d; dy++) {
        for (let dx = 0; dx < d; dx++) {
          let idx = 4 * ((y * d + dy) * width * d + (x * d + dx));
          pixels[idx] = constrain(pixels[idx] * vig + grain, 0, 255);
          pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
          pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
        }
      }
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 绘制深邃的宇宙与以太背景
  drawBackground();

  // 使用加法混合模式，表现能量的叠加与消散
  blendMode(ADD);

  // 2. 绘制“生”的残响：底部中心纠缠、炽热、复杂的结构
  drawLifeNexus();

  // 3. 绘制“死”的过程：边界消融，纤维向上舒展、冷却、化作虚空中的微光
  drawDissolutionStreams();

  // 4. 绘制离散的灵魂微粒与星尘
  drawEtherealDust();

  // 恢复默认混合模式，叠加一层极其微弱的暗角与质感
  blendMode(BLEND);
  drawVignette();
}

function drawBackground() {
  background(3, 5, 12);
  noStroke();

  // 用巨大的半透明圆制造深海与夜空般的渐变氛围
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(200, 900);

    let n = noise(x * 0.001, y * 0.001);
    let yRatio = y / height;

    let c;
    if (yRatio < 0.4) {
      // 顶部：寒冷而宁静的午夜蓝与紫灰
      c = lerpColor(color(6, 10, 24, 4), color(18, 28, 48, 4), n);
    } else if (yRatio < 0.75) {
      // 中部：过渡的深青与幽蓝
      c = lerpColor(color(8, 20, 38, 5), color(25, 45, 65, 5), n);
    } else {
      // 底部：深沉的暗红与褐黑，孕育生命之火的土壤
      let distToCenter = abs(x - width / 2) / (width / 2);
      if (distToCenter < 0.5) {
        c = lerpColor(color(45, 12, 18, 6), color(15, 8, 20, 5), distToCenter * 2);
      } else {
        c = color(5, 6, 14, 6);
      }
    }
    fill(c);
    circle(x, y, r);
  }
}

function drawLifeNexus() {
  let cx = width / 2;
  let cy = height * 0.80;

  // 核心的温暖光晕
  noStroke();
  for (let r = 600; r > 0; r -= 15) {
    let ratio = 1 - r / 600;
    let c = lerpColor(color(120, 20, 40, 0), color(255, 160, 80, 5 * ratio), ratio);
    fill(c);
    circle(cx, cy, r * 1.4);
  }

  // 纠缠的生命脉络（被束缚的能量）
  let numStrands = 2200;
  for (let i = 0; i < numStrands; i++) {
    let angle = random(TWO_PI);
    // 越靠近中心越密集
    let rad = pow(random(1), 1.8) * 320;
    let x = cx + cos(angle) * rad;
    let y = cy + sin(angle) * rad * 0.85;

    let steps = int(random(50, 140));
    for (let s = 0; s < steps; s++) {
      let dx = cx - x;
      let dy = cy - y;
      let distToCenter = sqrt(dx * dx + dy * dy);

      // 旋转向量 + 向心引力
      let pullAngle = atan2(dy, dx);
      let n = noise(x * 0.004, y * 0.004, i * 0.01);
      let moveAngle = pullAngle + HALF_PI * 0.92 + (n - 0.5) * 2.8;

      let nx = x + cos(moveAngle) * 3.5;
      let ny = y + sin(moveAngle) * 3.5;

      // 颜色：中心是耀眼的白金，外围是血红与紫红
      let cRatio = constrain(distToCenter / 320, 0, 1);
      let c;
      if (cRatio < 0.35) {
        c = lerpColor(color(255, 250, 220), color(255, 150, 50), cRatio / 0.35);
      } else if (cRatio < 0.75) {
        c = lerpColor(color(255, 150, 50), color(190, 30, 65), (cRatio - 0.35) / 0.4);
      } else {
        c = lerpColor(color(190, 30, 65), color(60, 15, 75), (cRatio - 0.75) / 0.25);
      }

      let alpha = sin(map(s, 0, steps, 0, PI)) * (1 - cRatio * 0.5) * 22;
      c.setAlpha(alpha);

      stroke(c);
      strokeWeight(map(cRatio, 0, 1, 2.2, 0.5));
      line(x, y, nx, ny);

      x = nx;
      y = ny;
    }
  }
}

function drawDissolutionStreams() {
  let cx = width / 2;
  let cy = height * 0.80;

  let numStreams = 4200;
  for (let i = 0; i < numStreams; i++) {
    // 从生命核心的上半部分及内部生发
    let startAngle = random(PI * 0.8, TWO_PI * 1.1);
    let startRad = pow(random(1), 0.7) * 260;
    let x = cx + cos(startAngle) * startRad;
    let y = cy + sin(startAngle) * startRad * 0.7;

    let maxSteps = int(random(200, 680));
    let id = i * 0.005;

    for (let s = 0; s < maxSteps; s++) {
      let progress = s / maxSteps;
      let yRatio = constrain(map(y, cy, 80, 0, 1), 0, 1);

      // 柏林噪声控制流向：底部湍急纠缠，顶部平滑宽广
      let nScale = lerp(0.0035, 0.0008, yRatio);
      let n1 = noise(x * nScale, y * nScale, id);
      let n2 = noise(x * 0.01 + 200, y * 0.01, id);

      // 基础方向向上 (-HALF_PI)
      let angleVariance = map(yRatio, 0, 1, PI * 1.1, PI * 0.45);
      let angle = -HALF_PI + (n1 - 0.48) * angleVariance + (n2 - 0.5) * 0.4 * (1 - yRatio);

      // 越往上，受两侧虚空的吸引越向四周扩散
      let centerOffset = (x - cx) / (width * 0.5);
      angle += centerOffset * yRatio * 0.55;

      let speed = lerp(2.2, 4.0, yRatio);
      let nx = x + cos(angle) * speed;
      let ny = y + sin(angle) * speed;

      // 色彩随高度演变：金红(生) -> 幽紫(过渡) -> 冰蓝/青白(消融与宁静)
      let c;
      if (yRatio < 0.18) {
        c = lerpColor(color(255, 160, 70), color(210, 45, 80), yRatio / 0.18);
      } else if (yRatio < 0.42) {
        c = lerpColor(color(210, 45, 80), color(95, 50, 140), (yRatio - 0.18) / 0.24);
      } else if (yRatio < 0.72) {
        c = lerpColor(color(95, 50, 140), color(45, 150, 195), (yRatio - 0.42) / 0.30);
      } else {
        c = lerpColor(color(45, 150, 195), color(210, 235, 255), (yRatio - 0.72) / 0.28);
      }

      // 透明度：两头淡，中间亮；随高度逐渐稀释
      let fadeEnds = sin(progress * PI);
      let heightFade = map(yRatio, 0, 1, 1, 0.25);
      let alpha = fadeEnds * heightFade * 16;

      // 在高处，实线逐渐断裂成虚化的粒子点（形态的彻底瓦解）
      if (yRatio > 0.45 && random() < (yRatio - 0.45) * 0.65) {
        if (random() < 0.12) {
          noStroke();
          c.setAlpha(alpha * 2.8);
          fill(c);
          let d = random(1, 3.8) * (1 - yRatio * 0.4);
          circle(nx + random(-8, 8) * yRatio, ny + random(-8, 8) * yRatio, d);
        }
      } else {
        c.setAlpha(alpha);
        stroke(c);
        strokeWeight(lerp(1.6, 0.35, yRatio));
        line(x, y, nx, ny);
      }

      x = nx;
      y = ny;

      if (y < 30 || x < 30 || x > width - 30) break;
    }
  }
}

function drawEtherealDust() {
  noStroke();
  let cx = width / 2;
  let cy = height * 0.80;

  // 1. 升腾并消散的微光（记忆与能量的碎片）
  for (let i = 0; i < 6500; i++) {
    let y = random(40, height - 100);
    let yRatio = map(y, cy, 40, 0, 1);

    // 分布呈倒锥形向上展开，直至铺满整个天际
    let spread = map(constrain(yRatio, 0, 1), 0, 1, 240, width * 0.75);
    let x = cx + randomGaussian(0, spread * 0.55);

    if (x < 0 || x > width) continue;

    let n = noise(x * 0.005, y * 0.005);
    if (n < 0.32 && yRatio < 0.75) continue;

    let c;
    if (yRatio < 0.2) {
      c = color(255, 190, 120);
    } else if (yRatio < 0.55) {
      c = lerpColor(color(210, 90, 140), color(90, 175, 220), (yRatio - 0.2) / 0.35);
    } else {
      c = lerpColor(color(130, 210, 245), color(245, 250, 255), constrain((yRatio - 0.55) / 0.45, 0, 1));
    }

    let alpha = random(8, 55) * (1 - abs(x - cx) / (width * 0.65));
    let sz = random(0.6, 3.2);

    // 少数微粒带有柔和的光晕，如同远去的星辰
    if (random() < 0.045) {
      c.setAlpha(alpha * 0.18);
      fill(c);
      circle(x, y, sz * 7);
      c.setAlpha(alpha * 0.45);
      fill(c);
      circle(x, y, sz * 3);
      c.setAlpha(min(255, alpha * 2.5));
      fill(c);
      circle(x, y, sz);
    } else {
      c.setAlpha(alpha);
      fill(c);
      circle(x, y, sz);
    }
  }

  // 2. 画面最顶端的寂静光雾——回归宇宙本源的宁静
  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(0, height * 0.45);
    let r = random(80, 350);
    let alpha = map(y, 0, height * 0.45, 3.5, 0);
    fill(170, 215, 255, alpha);
    circle(x, y, r);
  }
}

function drawVignette() {
  noFill();
  // 边缘压暗，使视线聚焦于从生到死的垂直升华之旅
  for (let i = 0; i < 150; i++) {
    let alpha = map(i, 0, 150, 45, 0);
    stroke(2, 3, 8, alpha);
    strokeWeight(4);
    rect(i * 2, i * 2, width - i * 4, height - i * 4, 20);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  // 1. 背景：从深邃的虚空到大地般的沉重底层
  drawBackground();

  // 2. 远景：宇宙的呼吸与星云（归宿）
  drawNebula();

  // 3. 灵魂与物质的丝线：从聚合走向消散的过程
  drawDissolvingThreads();

  // 4. 生之结构：下方正在崩解的、试图维持边界的几何体
  drawLifeStructure();

  // 5. 归还的微尘：上升的光点与飘散的碎片
  drawAscendingDust();

  // 6. 质感处理：赋予画面永恒而静谧的肌理
  applyTexture();
}

function drawBackground() {
  noFill();
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    let c;
    if (inter < 0.65) {
      // 上方：深邃的宇宙蓝黑与暗青
      let subInter = map(inter, 0, 0.65, 0, 1);
      c = lerpColor(color(4, 6, 14), color(14, 24, 38), pow(subInter, 1.3));
    } else {
      // 下方：沉入泥土般的焦茶色与暗琥珀
      let subInter = map(inter, 0.65, 1, 0, 1);
      c = lerpColor(color(14, 24, 38), color(28, 16, 12), pow(subInter, 1.5));
    }
    stroke(c);
    line(0, y, width, y);
  }
}

function drawNebula() {
  blendMode(SCREEN);
  noStroke();

  // 绘制深空中的柔和光晕，象征无限的整体
  for (let i = 0; i < 450; i++) {
    let x = random(width);
    let y = random(height * 0.85);
    let n = noise(x * 0.0015, y * 0.0015);

    if (n > 0.4) {
      let radius = map(n, 0.4, 1, 80, 500);
      let alpha = map(y, 0, height * 0.85, 6, 0) * map(n, 0.4, 1, 0.3, 1.2);

      if (random() < 0.6) {
        fill(30, 85, 115, alpha); // 幽灵青
      } else if (random() < 0.8) {
        fill(55, 45, 95, alpha);  // 暮光紫
      } else {
        fill(140, 100, 65, alpha * 0.7); // 遥远的星尘金
      }
      circle(x, y, radius);
    }
  }

  // 中心上升通道的微光
  for (let y = 300; y < 1700; y += 15) {
    let w = map(y, 300, 1700, 900, 300);
    let alpha = map(sin(map(y, 300, 1700, 0, PI)), 0, 1, 0, 4);
    fill(180, 140, 100, alpha);
    ellipse(width * 0.5 + (noise(y * 0.005) - 0.5) * 200, y, w, 150);
  }
}

function drawDissolvingThreads() {
  blendMode(ADD);
  noFill();

  let numThreads = 3200;
  let coreX = width * 0.5;
  let coreY = 1620;

  for (let i = 0; i < numThreads; i++) {
    // 起点集中在下方的“个体”核心内
    let r = pow(random(1), 0.7) * 320;
    let angle = random(TWO_PI);
    let x = coreX + cos(angle) * r;
    // 底部略微扁平的椭圆分布
    let y = coreY + sin(angle) * (r * 0.55);

    let life = random(180, 750);
    let cType = random(1);

    // 决定丝线的初始色彩：生命的炽热与记忆的黄金
    let startC, midC, endC;
    if (cType < 0.45) {
      startC = color(230, 95, 40);  // 生命余烬
      midC = color(245, 195, 110);  // 记忆之金
      endC = color(60, 150, 190);   // 苍穹之青
    } else if (cType < 0.8) {
      startC = color(180, 50, 45);  // 血脉之红
      midC = color(160, 130, 190);  // 过渡之紫
      endC = color(190, 225, 255);  // 纯粹之白
    } else {
      startC = color(255, 170, 80);
      midC = color(100, 180, 170);
      endC = color(30, 70, 120);
    }

    for (let step = 0; step < life; step++) {
      let progress = step / life;
      let heightFactor = constrain(map(y, 1750, 150, 0, 1), 0, 1);

      // 颜色随高度和步数逐渐冷却、纯化
      let currentC;
      if (heightFactor < 0.45) {
        currentC = lerpColor(startC, midC, map(heightFactor, 0, 0.45, 0, 1));
      } else {
        currentC = lerpColor(midC, endC, map(heightFactor, 0.45, 1, 0, 1));
      }

      // 透明度：两头淡，中间亮
      let alpha = sin(progress * PI) * map(heightFactor, 0, 1, 35, 10);
      currentC.setAlpha(alpha);
      stroke(currentC);
      strokeWeight(map(progress, 0, 1, 1.6, 0.2));

      let oldX = x;
      let oldY = y;

      // 运动逻辑：从底部的几何束缚，到中部的盘旋纠缠，再到顶部的自由消散
      let nScale = map(y, 1800, 0, 0.004, 0.0012);
      let n = noise(x * nScale, y * nScale, i * 0.0005);

      // 基础向上升腾的角度
      let flowAngle = -HALF_PI + (n - 0.5) * TWO_PI * map(heightFactor, 0, 1, 0.7, 2.2);

      // 在中下部形成向心又离心的旋涡感（挣脱束缚）
      let distFromCenter = x - coreX;
      if (y > 900) {
        // 试图维持形态的向心力
        flowAngle -= (distFromCenter * 0.0015) * map(y, 900, 1800, 0, 1);
      } else {
        // 彻底放开后的向外扩散
        flowAngle += (distFromCenter * 0.0008) * map(y, 900, 0, 0, 1);
      }

      let speed = map(heightFactor, 0, 1, 1.8, 3.8);
      x += cos(flowAngle) * speed;
      y += sin(flowAngle) * speed - 0.6; // 永恒的向上浮力

      line(oldX, oldY, x, y);

      if (y < -50 || x < -50 || x > width + 50) break;
    }
  }
}

function drawLifeStructure() {
  let coreX = width * 0.5;
  let coreY = 1620;

  // 1. 绘制暗色实体块：代表肉体、执念与沉重的物质边界
  blendMode(BLEND);
  for (let i = 0; i < 450; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(1), 0.85) * 340;
    let x = coreX + cos(angle) * r;
    let y = coreY + sin(angle) * (r * 0.55);

    // 越往上，碎片越稀少、越破碎
    if (y < 1550 && random() < map(y, 1550, 1300, 0.2, 0.95)) continue;

    push();
    translate(x, y);
    // 越往上旋转越混乱，下方则相对规整
    let rot = (y > 1600) ? floor(random(4)) * HALF_PI + random(-0.1, 0.1) : random(TWO_PI);
    rotate(rot);

    let size = map(r, 0, 340, 65, 12) * map(y, 1350, 1800, 0.3, 1.2);

    // 沉重的暗色与金色的裂痕边缘
    let depth = map(y, 1400, 1800, 0, 1);
    fill(lerpColor(color(28, 22, 24, 210), color(10, 7, 9, 245), depth));

    if (random() < 0.4) {
      // 裂痕中的微光，仿佛结构内部正在融化
      stroke(210, 130, 60, map(y, 1400, 1800, 140, 40));
      strokeWeight(0.8);
    } else {
      stroke(45, 35, 35, 180);
      strokeWeight(0.5);
    }

    // 绘制不规则的几何切面
    beginShape();
    let sides = int(random(3, 6));
    for (let s = 0; s < sides; s++) {
      let a = (s / sides) * TWO_PI;
      let rad = size * random(0.5, 1.1);
      vertex(cos(a) * rad, sin(a) * rad);
    }
    endShape(CLOSE);
    pop();
  }

  // 2. 几何网格线：试图将一切锁住的“生之秩序”，在上方断裂
  blendMode(ADD);
  strokeWeight(0.7);
  for (let i = 0; i < 180; i++) {
    let r = random(40, 360);
    let a1 = random(TWO_PI);
    let a2 = a1 + random(0.1, 0.6);

    let x1 = coreX + cos(a1) * r;
    let y1 = coreY + sin(a1) * (r * 0.55);
    let x2 = coreX + cos(a2) * r;
    let y2 = coreY + sin(a2) * (r * 0.55);

    if (y1 < 1500) {
      // 向上飘起、断裂的线条
      y1 -= pow(1500 - y1, 1.2) * 0.3;
      y2 -= pow(1500 - y2, 1.2) * 0.3 + random(-30, 30);
    }

    let alpha = map(min(y1, y2), 1300, 1800, 0, 90);
    stroke(240, 180, 110, alpha);
    line(x1, y1, x2, y2);
  }

  // 3. 核心深处的最后一点余温
  noStroke();
  for (let r = 250; r > 0; r -= 10) {
    fill(220, 80, 30, map(r, 250, 0, 0, 4));
    ellipse(coreX, coreY + 20, r * 1.6, r * 0.9);
  }
}

function drawAscendingDust() {
  blendMode(ADD);

  // 1. 正在脱离本体的微小几何碎片（中下层）
  for (let i = 0; i < 350; i++) {
    let y = random(850, 1600);
    let spread = map(y, 1600, 850, 280, 550);
    let x = width * 0.5 + randomGaussian() * (spread * 0.45);

    let size = map(y, 1600, 850, 9, 1.5) * random(0.5, 1.5);
    let alpha = map(y, 1600, 850, 180, 20);

    fill(255, 200, 130, alpha);
    noStroke();

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    beginShape();
    for (let s = 0; s < 3; s++) {
      let a = (s / 3) * TWO_PI + random(-0.3, 0.3);
      vertex(cos(a) * size, sin(a) * size);
    }
    endShape(CLOSE);
    pop();
  }

  // 2. 化作永恒的星尘与光点（中上层直至天际）
  for (let i = 0; i < 2200; i++) {
    let y = pow(random(1), 1.3) * 1650;
    let x;

    // 下方聚拢于上升通道，上方铺满整个宇宙
    if (y > 600) {
      let spread = map(y, 1650, 600, 180, 650);
      x = width * 0.5 + randomGaussian() * (spread * 0.5);
    } else {
      let spread = map(y, 600, 0, 650, 900);
      x = lerp(width * 0.5 + randomGaussian() * (spread * 0.5), random(width), map(y, 600, 0, 0.2, 0.9));
    }

    let n = noise(x * 0.004, y * 0.004);
    let d = random(0.8, 3.8);

    // 光点颜色随高度从暖金变为清冷的星光
    let cWarm = color(255, 215, 160);
    let cCool = color(170, 225, 255);
    let c = lerpColor(cCool, cWarm, constrain(map(y, 200, 1500, 0, 1) + random(-0.2, 0.2), 0, 1));

    let alpha = map(n, 0, 1, 30, 220) * map(y, 0, 1650, 0.8, 1);
    c.setAlpha(alpha);
    fill(c);
    circle(x, y, d);

    // 少数特别明亮的光点，带有柔和的光晕（如同重获自由的灵魂节点）
    if (random() < 0.045 && y < 1400) {
      let glowSize = d * random(4, 12);
      c.setAlpha(alpha * 0.15);
      fill(c);
      circle(x, y, glowSize);

      c.setAlpha(alpha * 0.05);
      fill(c);
      circle(x, y, glowSize * 2.2);

      // 极微弱的十字星芒，仅在最高处出现
      if (y < 700 && random() < 0.4) {
        stroke(220, 240, 255, alpha * 0.4);
        strokeWeight(0.6);
        let len = glowSize * 1.2;
        line(x - len, y, x + len, y);
        line(x, y - len, x, y + len);
        noStroke();
      }
    }
  }
}

function applyTexture() {
  // 1. 四周暗角，让视线聚焦于上升与消散的过程
  blendMode(MULTIPLY);
  noFill();
  for (let i = 0; i < 250; i++) {
    let alpha = map(i, 0, 250, 90, 0);
    stroke(5, 7, 12, alpha);
    strokeWeight(4);
    rect(i * 2, i * 2, width - i * 4, height - i * 4, 250 - i);
  }

  // 2. 细腻的画布颗粒感，消除数字图像的冰冷
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);
  for (let i = 0; i < totalPixels; i += 4) {
    let grain = (random() - 0.5) * 14;
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  paint();
}

function paint() {
  background(8, 9, 14);
  skyAndWater();
  clouds();
  lightBridge();
  disc(1048, 1096, 228);
  horizonMist();
  figure();
  submerge();
  reflection();
  motes();
  ripples();
  reeds();
  vignette();
  grain();
}

function skyAndWater() {
  for (let y = 0; y < height; y++) {
    let n = noise(0.4, y * 0.008);
    if (y < 1120) {
      let u = y / 1120;
      let e = pow(u, 1.45);
      let r = lerp(14, 168, e) + n * 10;
      let g = lerp(16, 104, pow(u, 1.2)) + n * 6;
      let b = lerp(32, 70, pow(u, 0.8));
      if (y > 980) {
        let k = (y - 980) / 140;
        r = lerp(r, 188, k * 0.55);
        g = lerp(g, 118, k * 0.35);
        b = lerp(b, 86, k * 0.2);
      }
      stroke(r, g, b);
    } else {
      let v = (y - 1120) / 880;
      let r = lerp(36, 5, pow(v, 0.72)) + n * 3;
      let g = lerp(34, 6, pow(v, 0.72));
      let b = lerp(46, 10, pow(v, 0.6));
      stroke(r, g, b);
    }
    line(0, y, width, y);
  }
}

function clouds() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    let x = random(width);
    let y = random(40, 820);
    let w = random(180, 760);
    let h = random(24, 110);
    let a = random(6, 18);
    fill(52 + random(-8, 8), 46, 58, a);
    ellipse(x, y, w, h);
    fill(28, 30, 42, a * 0.6);
    ellipse(x + 20, y + 8, w * 0.7, h * 0.6);
  }
}

function lightBridge() {
  noStroke();
  for (let i = 0; i < 14; i++) {
    let x = lerp(1060, 620, i / 13);
    fill(214, 156, 102, 4);
    ellipse(x, 1104, 520 - i * 12, 200 - i * 4);
  }
  for (let i = 0; i < 10; i++) {
    fill(230, 190, 140, 3);
    ellipse(1048, lerp(280, 1090, i / 9), 180 + i * 28, 220);
  }
}

function disc(cx, cy, rad) {
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let a = random(TWO_PI);
    let rr = rad * pow(random(), 0.5);
    let x = cx + cos(a) * rr * 1.04;
    let y = cy + sin(a) * rr * 0.82;
    let k = constrain(rr / rad, 0, 1);
    let colr = lerp(248, 168, k);
    let colg = lerp(224, 96, k);
    let colb = lerp(186, 64, k);
    let al = lerp(42, 6, k);
