function figure() {
  noStroke();
  for (let i = 0; i < 36; i++) {
    fill(16, 14, 20, 16);
    ellipse(592 + random(-18, 12), lerp(960, 1480, i / 36), 200 - i * 2, 90);
  }

  fill(40, 34, 42, 170);
  ellipse(612, 958, 70, 34);
  fill(186, 160, 136, 235);
  ellipse(622, 986, 58, 76);
  fill(232, 208, 178, 80);
  ellipse(638, 982, 26, 58);

  for (let i = 0; i < 2600; i++) {
    let t = random();
    if (t > 0.5 && random() < (t - 0.5) * 1.15) continue;

    let y = lerp(948, 1630, t);
    let x = 620 + sin(t * 3.0) * 14;
    let half;

    if (t < 0.1) half = 22;
    else if (t < 0.16) half = 12;
    else if (t < 0.34) half = lerp(76, 46, (t - 0.16) / 0.18);
    else if (t < 0.5) half = lerp(46, 58, (t - 0.34) / 0.16);
    else {
      let side = random() < 0.5 ? -1 : 1;
      x += side * lerp(14, 40, (t - 0.5) / 0.5);
      half = lerp(20, 6, (t - 0.5) / 0.5);
    }

    let jx = random(-half, half);
    let dissolve = constrain((t - 0.4) / 0.48, 0, 1);
    if (jx < 0) dissolve = constrain(dissolve + 0.28, 0, 1);
    if (random() < dissolve * 0.45) continue;

    x += jx * (1 - dissolve * 0.25);
    x += random(-1, 1) * dissolve * 42;
    y += random(-1, 1) * dissolve * 22;

    let light = constrain(map(jx, -half, half, 0.05, 1), 0, 1);
    light *= 1 - dissolve * 0.65;
    let r = lerp(58, 212, light);
    let g = lerp(54, 178, light);
    let b = lerp(66, 146, light);
    r = lerp(r, 48, dissolve * 0.45);
    g = lerp(g, 50, dissolve * 0.45);
    b = lerp(b, 58, dissolve * 0.35);
    let a = lerp(210, 16, dissolve);
    if (t < 0.16) a = max(a, 180);

    fill(r, g, b, a);
    let s = lerp(11, 2.4, dissolve) * random(0.65, 1.25);
    ellipse(x, y, s, s * random(0.75, 1.45));
  }

  for (let side = -1; side <= 1; side += 2) {
    for (let i = 0; i < 320; i++) {
      let t = random();
      let dissolve = constrain(0.15 + t * 0.8, 0, 1);
      if (random() < dissolve * 0.42) continue;
      let y = lerp(1110, 1405, t);
      let x = 620 + side * lerp(62, 118, t);
      x += sin(t * 5.0 + side) * 5;
      x += random(-1, 1) * dissolve * 18;
      y += random(-1, 1) * dissolve * 10;
      fill(
        lerp(176, 64, dissolve),
        lerp(146, 62, dissolve),
        lerp(118, 70, dissolve),
        lerp(150, 14, dissolve)
      );
      ellipse(x, y, random(3.5, 9), random(5, 13));
    }
  }
}

