function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
  colorMode(RGB, 255);

  const y0 = 900;
  const y1 = 1610;
  const fieldW = 80;
  const fieldH = 100;
  const field = new Array(fieldW * fieldH);
  for (let j = 0; j < fieldH; j++) {
    for (let i = 0; i < fieldW; i++) {
      field[j * fieldW + i] = noise(i * 0.17, j * 0.13);
    }
  }

  const bandCenter = new Array(160);
  for (let i = 0; i < 160; i++) {
    bandCenter[i] = 508 + (noise(i * 0.21, 4.4) - 0.5) * 30;
  }

  const faceT = 0.072;
  const faceX = spineX(faceT);
  const faceY = lerp(y0, y1, faceT);

  loadPixels();
  for (let y = 0; y < 2000; y++) {
    const yn = y / 2000;
    let br, bg, bb;
    if (yn < 0.18) {
      const u = yn / 0.18;
      br = lerp(7, 16, u);
      bg = lerp(9, 15, u);
      bb = lerp(16, 26, u);
    } else if (yn < 0.42) {
      const u = (yn - 0.18) / 0.24;
      br = lerp(16, 23, u);
      bg = lerp(15, 18, u);
      bb = lerp(26, 24, u);
    } else if (yn < 0.844) {
      const u = (yn - 0.42) / 0.424;
      br = lerp(23, 9, u);
      bg = lerp(18, 7, u);
      bb = lerp(24, 8, u);
    } else {
      const u = (yn - 0.844) / 0.156;
      br = lerp(9, 3, u);
      bg = lerp(7, 3, u);
      bb = lerp(8, 4, u);
    }

    for (let x = 0; x < 1600; x++) {
      const xn = x / 1600;
      const fv = sampleField(field, fieldW, fieldH, xn, yn);
      const bandC = bandCenter[x >> 4];
      const dist = y - bandC;
      const band = Math.exp(-(dist * dist) / (2 * 24 * 24));

      let r = br + (fv - 0.5) * 18 + band * 50;
      let g = bg + (fv - 0.5) * 16 + band * 56;
      let b = bb + (fv - 0.5) * 15 + band * 66;

      const ex = (x - 804) / 190;
      const ey = (y - 1368) / 100;
      const ember = Math.exp(-(ex * ex + ey * ey));
      r += ember * 26;
      g += ember * 9;
      b -= ember * 3;

      const px = (x - 800) / 250;
      const py = (y - 1230) / 390;
      const pres = Math.exp(-(px * px * 0.8 + py * py));
      r -= pres * 8;
      g -= pres * 7;
      b -= pres * 4;

      const fdx = (x - faceX) / 48;
      const fdy = (y - faceY) / 64;
      const hole = Math.exp(-(fdx * fdx + fdy * fdy));
      r -= hole * 12;
      g -= hole * 10;
      b -= hole * 9;

      const vx = (xn - 0.5) * 1.22;
      const vy = (yn - 0.46) * 1.06;
      const vig = Math.min(1, vx * vx + vy * vy);
      const vm = 1 - vig * 0.64;
      r *= vm;
      g *= vm;
      b *= vm;

      const grain = (random() - 0.5) * 11;
      r += grain;
      g += grain * 0.94;
      b += grain * 0.88;

      const idx = (y * 1600 + x) * 4;
      pixels[idx] = constrain(r, 0, 255);
      pixels[idx + 1] = constrain(g, 0, 255);
      pixels[idx + 2] = constrain(b, 0, 255);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();

  noFill();
  for (let i = 0; i < 70; i++) {
    const y = random(40, 860);
    stroke(18 + random(14), 20 + random(10), 28 + random(14), random(5, 12));
    strokeWeight(random(10, 34));
    line(random(-80, 280), y, random(1320, 1680), y + (noise(i * 0.3) - 0.5) * 16);
  }
  for (let i = 0; i < 36; i++) {
    const y = random(1100, 1680);
    stroke(28, 20, 16, random(4, 9));
    strokeWeight(random(12, 40));
    line(random(-40, 360), y, random(1200, 1660), y + (noise(i * 0.4, 2) - 0.5) * 10);
  }
  noStroke();

  for (let n = 0; n < 160; n++) {
    const u = Math.pow(random(), 0.75);
    const y = lerp(220, 1120, u);
    const x = 800 + (random() - 0.5) * lerp(340, 90, u);
    fill(168, 166, 160, random(2, 5));
    ellipse(x, y, random(18, 54), random(12, 34));
  }

  for (let n = 0; n < 52000; n++) {
    const t = Math.pow(random(), 0.8);
    const y = lerp(y0, y1, t);
    const cx = spineX(t);
    const hw = halfWidth(t) * (0.76 + noise(t * 6.0, 2.2) * 0.48);
    let x = cx + (random() - 0.5) * 2 * hw;
    const up = 1 - t;
    if (random() < 0.3) {
      const dir = x < cx ? -1 : 1;
      x += dir * random() * (10 + up * 160 + t * t * 36);
    }
    const fdx = (x - faceX) / 52;
    const fdy = (y - faceY) / 68;
    if (fdx * fdx + fdy * fdy < 1 && random() > 0.03) continue;

    const nr = noise(x * 0.011, y * 0.011);
    const cool = constrain((980 - y) / 420, 0, 1);
    let r = lerp(186, 228, nr) * lerp(1, 0.8, cool);
    let g = lerp(164, 208, nr) * lerp(0.98, 0.86, cool);
    let b = lerp(138, 186, nr) * lerp(0.92, 0.94, cool);
    const sink = constrain((t - 0.7) / 0.3, 0, 1);
    r = lerp(r, 62, sink * 0.62);
    g = lerp(g, 54, sink * 0.62);
    b = lerp(b, 48, sink * 0.55);
    const alpha = lerp(58, 14, up) * lerp(1, 0.28, sink) * (0.5 + random() * 0.75);
    const rad = random() < 0.07 ? random(3.2, 6.5) : random(1.05, 2.5);
    fill(r, g, b, rad > 3.2 ? alpha * 0.32 : alpha);
    ellipse(x, y, rad, rad);
  }

  for (let n = 0; n < 22000; n++) {
    const u = Math.pow(random(), 0.58);
    const y = lerp(140, y0 + 30, u);
    const spread = lerp(460, 80, u);
    const x = 800 + (random() + random() + random() - 1.5) * spread * 0.82;
    const nr = noise(x * 0.008, y * 0.01);
    fill(
      lerp(124, 196, nr),
      lerp(132, 190, nr),
      lerp(146, 184, nr),
      u * u * random(5, 15)
    );
    ellipse(x, y, random(0.8, 2.3), random(0.8, 2.3));
  }

  for (let n = 0; n < 4600; n++) {
    const a = random(TWO_PI);
    if (Math.sin(a) < 0 && random() < 0.52) continue;
    const j = 0.9 + random() * 0.62;
    const x = faceX + Math.cos(a) * 54 * j + (random() - 0.5) * 7;
    const y = faceY + Math.sin(a) * 70 * j + (random() - 0.5) * 7;
    fill(206, 192, 172, random(8, 34));
    ellipse(x, y, random(0.8, 2.1), random(0.8, 2.1));
  }

  for (let n = 0; n < 640; n++) {
    const t = random(0.04, 0.82);
    const y = lerp(y0, y1, t);
    const x = spineX(t) + (random() - 0.5) * halfWidth(t) * 0.65;
    fill(232, 220, 204, random(36, 88));
    ellipse(x, y, random(0.7, 1.6), random(0.7, 1.6));
  }

  const emberX = spineX(0.58) + 4;
  const emberY = lerp(y0, y1, 0.6);
  for (let i = 26; i >= 1; i--) {
    fill(96, 34, 14, 3);
    ellipse(emberX, emberY, i * 6.4, i * 3.6);
  }
  for (let i = 8; i >= 1; i--) {
    fill(186, 96, 42, 7);
    ellipse(emberX, emberY, i * 2.1, i * 1.3);
  }
  fill(232, 190, 132, 46);
  ellipse(emberX, emberY, 2.4, 1.6);

  for (let y = 1694; y < 2000; y += 2) {
    stroke(2, 2, 3, 8 + (y - 1694) / 10);
    strokeWeight(2);
    line(0, y, 1600, y + (noise(y * 0.02, 9) - 0.5) * 4);
  }
  for (let x = 0; x < 1600; x++) {
    const y = 1690 + (noise(x * 0.009, 12) - 0.5) * 11;
    stroke(118, 108, 96, 26);
    strokeWeight(1);
    point(x, y);
  }
  noStroke();

  for (let n = 0; n < 1600; n++) {
    const x = 800 + (random() + random() + random() - 1.5) * 280;
    const y = 1686 + random() * 16 + Math.abs(x - 800) * 0.012;
    fill(176, 160, 140, random(8, 26));
    ellipse(x, y, random(1, 3.2), random(0.5, 1.3));
  }

  for (let n = 0; n < 2600; n++) {
    const t = lerp(0.42, 0.98, random());
    const srcY = lerp(y0, y1, t);
    const srcX = spineX(t) + (random() - 0.5) * halfWidth(t) * 0.7;
    const y = 1702 + (1690 - srcY) * 0.2 + random() * 8;
    if (y < 1704 || y > 1970) continue;
    fill(58, 56, 54, random(3, 11));
    ellipse(srcX + (random() - 0.5) * 12, y, random(0.8, 1.8), random(2.2, 5.5));
  }
}

function spineX(t) {
  return 800 + (noise(t * 1.8, 3.2) - 0.5) * 34;
}

function halfWidth(t) {
  if (t < 0.09) return lerp(34, 68, t / 0.09);
  if (t < 0.15) return lerp(68, 56, (t - 0.09) / 0.06);
  if (t < 0.19) return lerp(56, 20, (t - 0.15) / 0.04);
  if (t < 0.3) return lerp(20, 128, (t - 0.19) / 0.11);
  if (t < 0.4) return lerp(128, 82, (t - 0.3) / 0.1);
  if (t < 0.58) return lerp(82, 68, (t - 0.4) / 0.18);
  if (t < 0.74) return lerp(68, 86, (t - 0.58) / 0.16);
  if (t < 0.88) return lerp(86, 28, (t - 0.74) / 0.14);
  return lerp(28, 8, (t - 0.88) / 0.12);
}

function sampleField(field, w, h, xn, yn) {
  const fx = xn * (w - 1);
  const fy = yn * (h - 1);
  let i = Math.floor(fx);
  let j = Math.floor(fy);
  if (i < 0) i = 0;
  if (j < 0) j = 0;
  if (i > w - 2) i = w - 2;
  if (j > h - 2) j = h - 2;
  const tx = fx - i;
  const ty = fy - j;
  const a = field[j * w + i];
  const b = field[j * w + i + 1];
  const c = field[(j + 1) * w + i];
  const d = field[(j + 1) * w + i + 1];
  return a + (b - a) * tx + (c - a) * ty + (a - b - c + d) * tx * ty;
}

