    const y = lerp(rootY, 560, t) - random(0, 8);
    const wander = (noise(t * 1.6, 1.8) - 0.5) * 80;
    const fray = Math.pow(t, 1.45) * 220;
    const spread = lerp(22, 40, t) + fray;
    const x = rootX + wander + randomGaussian() * spread + Math.sin(t * 6.2) * 10 * t;
    const rr = lerp(154, 78, t) + random(-7, 7);
    const gg = lerp(130, 86, t) + random(-7, 7);
    const bb = lerp(108, 98, t) + random(-6, 6);
    const a = lerp(18, 0, Math.pow(t, 0.7)) * random(0.4, 1);
    stroke(rr, gg, bb, a);
    strokeWeight(lerp(1.7, 0.4, t) * random(0.6, 1.15));
    if (random() < lerp(0.62, 0.08, t)) {
      const dir = random() < 0.5 ? -1 : 1;
      line(x, y, x + random(4, 18) * dir, y + random(-0.8, 0.8));
    } else {
      const rise = lerp(3, 16, t) * random(0.45, 1);
      line(x, y, x + random(-1, 1) * (1 + t * 5), y - rise);
    }
  }

  for (let i = 0; i < 70; i++) {
    const t = random(0.72, 1);
    const y = lerp(rootY, 340, t);
    const x = rootX + randomGaussian() * (30 + t * 160);
    stroke(150, 132, 114, random(8, 36));
    strokeWeight(random(0.8, 1.8));
    point(x, y);
  }

  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 28; i++) {
    const y = random(430, 860);
    const x = rootX + randomGaussian() * 70;
    fill(36, 22, 12);
    ellipse(x, y, random(1.4, 2.6), random(1.4, 2.6));
  }
  blendMode(BLEND);

  noStroke();
  for (let i = 0; i < 12; i++) {
    fill(5, 6, 10, 10);
    rect(0, 0, width, 6 + i * 3);
    rect(0, height - (5 + i * 2), width, 5 + i * 2);
    rect(0, 0, 6 + i * 4, height);
    rect(width - (6 + i * 4), 0, 6 + i * 4, height);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function edgeAt(x) {
  return 1362
    + noise(x * 0.00128, 2.4) * 228
    + noise(x * 0.0054, 7.1) * 30
    + sin(x * 0.0024) * 12;
}

function draw() {
  strokeCap(ROUND);
  strokeJoin(ROUND);

  for (let y = 0; y < height; y++) {
    let t = y / height;
    let r, g, b;
    if (t < 0.48) {
      let u = t / 0.48;
      r = lerp(8, 24, u);
      g = lerp(10, 18, u);
      b = lerp(24, 32, u);
    } else if (t < 0.7) {
      let u = (t - 0.48) / 0.22;
      r = lerp(24, 52, pow(u, 0.8));
      g = lerp(18, 26, u);
      b = lerp(32, 28, u);
    } else {
      let u = (t - 0.7) / 0.3;
      r = lerp(52, 11, pow(u, 0.85));
      g = lerp(26, 7, u);
      b = lerp(28, 9, u);
    }
    let n = noise(0.35, y * 0.0037);
    strokeWeight(1);
    stroke(r + (n - 0.5) * 7, g + (n - 0.5) * 4, b + (n - 0.5) * 5);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 22; i++) {
    let x = 180 + noise(i * 0.31, 1.7) * 1240;
    let y = 90 + noise(i * 0.47, 3.3) * 980;
    let rad = 220 + noise(i * 0.2, 5) * 460;
    let warm = noise(i * 0.9, 8.2) > 0.58;
    for (let k = 7; k >= 1; k--) {
      if (warm) fill(92, 40, 26, 2.2 + k * 0.35);
      else fill(16, 26, 46, 2.4 + k * 0.28);
      ellipse(
        x + (noise(i, k) - 0.5) * 50,
        y + (noise(k, i) - 0.5) * 30,
        rad * (0.45 + k * 0.12),
        rad * (0.28 + k * 0.08)
      );
    }
  }

  let cx = 728;
  let coreY = 1116;

  noStroke();
  for (let i = 0; i < 46; i++) {
    fill(118, 62, 34, 2.4);
    ellipse(cx + 8, 1040, 160 + i * 11, 980 - i * 8);
  }

  for (let i = 0; i < 26; i++) {
    fill(7, 9, 16, 9);
    ellipse(470 + i * 6.5, 990 + noise(i * 0.4) * 70, 120, 640);
  }

  for (let i = 0; i < 2200; i++) {
    let u = pow(random(), 0.82);
    let y = lerp(690, 1490, u);
    let near = exp(-pow(y - coreY, 2) / (2 * 168 * 168));
    let rise = constrain((980 - y) / 280, 0, 1);
    let spread = 24 + (1 - near) * 74 + rise * 86;
    let x = cx + (random() + random() - 1) * spread + (noise(y * 0.004, 2.2) - 0.5) * 26;
    let lift = constrain(near * 0.85 + (1 - rise) * 0.15, 0, 1);
    let rr = lerp(78, 228, lift);
    let gg = lerp(42, 176, lift);
    let bb = lerp(32, 112, lift);
    fill(rr, gg, bb, 4.5 + lift * 6.5);
    let s = 18 + random() * 34 * (0.65 + lift);
    ellipse(x, y, s * 0.72, s * 1.42);
  }

  for (let i = 0; i < 1600; i++) {
    let y = lerp(760, 1420, pow(random(), 1.05));
    let near = exp(-pow(y - coreY, 2) / (2 * 120 * 120));
    let spread = 10 + (1 - near) * 28 + max(0, 940 - y) * 0.05;
    let x = cx + 6 + (random() + random() + random() - 1.5) * spread;
    fill(lerp(140, 255, near), lerp(92, 214, near), lerp(62, 150, near), 7 + near * 12);
    ellipse(x, y, 7 + random() * 10, 16 + random() * 22);
  }

  for (let i = 0; i < 380; i++) {
    let y = 860 + random() * 420;
    let x = cx - 8 + (random() - 0.5) * 22;
    fill(42, 24, 20, 11);
    ellipse(x, y, 3.5, 18 + random() * 46);
  }

  for (let i = 0; i < 280; i++) {
    let a = random(TWO_PI);
    let rad = pow(random(), 0.42) * 30;
    fill(255, 224, 176, 7);
    ellipse(cx + 10 + cos(a) * rad, coreY + sin(a) * rad * 0.66, 16, 11);
  }
  for (let i = 0; i < 70; i++) {
    fill(255, 242, 214, 9);
    ellipse(cx + 10 + random(-7, 7), coreY + random(-4, 4), 7, 5);
  }

  noStroke();
  for (let i = 0; i < 900; i++) {
    let y0 = random(700, 1080);
    let x = cx + random(-36, 64);
    let y = y0;
    let steps = int(random(8, 26));
    for (let k = 0; k < steps; k++) {
      let u = k / max(1, steps - 1);
      x += 2.1 + noise(i * 0.02, k * 0.08) * 2.4;
      y -= 1.35 + noise(k * 0.05, i * 0.01) * 1.1;
      let cool = constrain((920 - y) / 380, 0, 1);
      let a = (1 - u) * (10 + (y0 > 900 ? 4 : 0)) * (1 - cool * 0.35);
      fill(lerp(206, 146, cool), lerp(154, 166, cool), lerp(104, 186, cool), a);
      ellipse(x, y, lerp(7, 1.6, u), lerp(5, 1.4, u));
    }
  }

  for (let s = 0; s < 18; s++) {
    let x = 620 + random(-80, 360);
    let y = 430 + random(0, 280);
    for (let k = 0; k < 54; k++) {
      let ang = noise(s * 0.35, k * 0.025) * 2.2 - 0.35;
      x += cos(ang) * 3.4;
      y += sin(ang) * 1.1 - 0.85;
      stroke(186, 196, 206, 7 * (1 - k / 54));
      strokeWeight(1.15);
      point(x, y);
    }
  }

  for (let i = 0; i < 240; i++) {
    let y = 1180 + random() * 220;
    let x = 560 + random() * 160;
    fill(92, 42, 30, 8);
    noStroke();
    ellipse(x, y + random(30), 4, 16 + random() * 28);
  }

  for (let x = 0; x < width; x++) {
    let edge = edgeAt(x);
    stroke(86, 40, 26, 16);
    strokeWeight(1);
    line(x, edge - 10, x, edge + 8);
    stroke(18, 10, 11, 128);
    line(x, edge, x, edge + 46);
    stroke(7, 5, 6, 232);
    line(x, edge + 22, x, height);
    if (noise(x * 0.013, 3.3) > 0.66) {
      stroke(4, 3, 4, 70);
      line(x, edge + 40, x, height);
    }
  }

  noStroke();
  for (let i = 0; i < 160; i++) {
    let x = random(width);
    let e = edgeAt(x);
    if (noise(x * 0.02, 11) > 0.42) {
      fill(168, 92, 54, random(8, 20));
      ellipse(x, e + random(-4, 6), random(2, 9), random(1.5, 3));
    }
  }

  for (let x = 0; x < 200; x++) {
    stroke(0, 0, 0, map(x, 0, 200, 42, 0));
    strokeWeight(1);
    line(x, 0, x, height);
    line(width - 1 - x, 0, width - 1 - x, height);
  }
  for (let y = 0; y < 140; y++) {
    stroke(0, 0, 0, map(y, 0, 140, 36, 0));
    line(0, y, width, y);
  }
  for (let y = 0; y < 90; y++) {
    stroke(0, 0, 0, map(y, 0, 90, 28, 0));
    line(0, height - 1 - y, width, height - 1 - y);
  }

  for (let i = 0; i < 14000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.45) stroke(244, 232, 214, random(2, 8));
    else stroke(0, 0, 0, random(3, 12));
    strokeWeight(random() < 0.85 ? 1 : 1.6);
    point(x, y);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);
  drawField();
  drawPool();
  drawForm();
  drawThread();
  drawDispersal();
  drawFailedReflection();
  drawGrain();
  drawVignette();
}

function drawField() {
  noFill();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    let r = lerp(6, 24, Math.pow(t, 0.8));
    let g = lerp(8, 20, Math.pow(t, 0.9));
    let b = lerp(15, 22, t);
    if (t > 0.62) {
      let u = (t - 0.62) / 0.38;
      r = lerp(r, 12, u);
      g = lerp(g, 10, u);
      b = lerp(b, 9, u);
    }
    stroke(r, g, b);
    strokeWeight(2);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 36; i++) {
    let y = noise(i * 0.17, 0.4) * height * 0.92;
    let h = 40 + noise(i * 0.31, 1.7) * 220;
    let a = 4 + noise(i * 0.2, 3.1) * 10;
    fill(18, 22, 32, a);
    rect(-20, y, width + 40, h);
  }
}

function drawPool() {
  noStroke();
  for (let i = 16; i >= 1; i--) {
    let k = i / 16;
    fill(2, 2, 4, 16);
    ellipse(700, 1788, 1100 * k, 340 * k);
  }
  for (let i = 8; i >= 1; i--) {
    fill(0, 0, 0, 10);
    ellipse(690, 1800, 620 * i / 8, 120 * i / 8);
  }
}

function drawForm() {
  noStroke();
  let cx = 640;
  let base = 1340;

  for (let i = 0; i < 70; i++) {
    let t = i / 70;
    let y = lerp(base + 20, 1680, t);
    let x = cx + (noise(i * 0.13, 4) - 0.5) * 90;
    fill(72, 48, 32, lerp(22, 3, t));
    ellipse(x, y, lerp(70, 460, t), 22 + t * 36);
  }

  fill(86, 58, 36, 7);
  ellipse(cx, 1180, 520, 760);

  for (let i = 0; i < 260; i++) {
    let t = i / 260;
    let y = lerp(820, base, Math.pow(t, 0.82));
    let n = noise(t * 3.2, 2.4);
    let fray = Math.pow(1 - t, 1.35);
    let x = cx + (n - 0.5) * lerp(14, 86, fray + (1 - t) * 0.2);
    let rad = lerp(18, 54, t) * (0.75 + n * 0.5);
    rad *= 1 + fray * 1.1;
    let R = lerp(168, 248, t) - fray * 55;
    let G = lerp(176, 220, t) - fray * 30;
    let B = lerp(186, 176, t) + fray * 18;
    let a = lerp(5, 26, t) * (1 - fray * 0.45);
    fill(R, G, B, a);
    ellipse(x, y, rad * (1.1 + fray), rad * (1.55 - fray * 0.3));
  }

  for (let k = 7; k >= 1; k--) {
    fill(255, 214, 160, 8);
    ellipse(cx + 4, 1248, 26 * k, 64 * k);
  }
  fill(255, 238, 216, 58);
  ellipse(cx + 2, 1272, 14, 34);
  fill(255, 246, 232, 80);
  ellipse(cx + 1, 1276, 6, 14);
}

function drawThread() {
  noStroke();
  let x = 646;
  let y = 1268;
  for (let i = 0; i < 210; i++) {
    let t = i / 210;
    x += (noise(t * 4.2, 8) - 0.46) * 7;
    y -= 3.6 + t * 2.4;
    if (noise(t * 7, 1.2) < 0.16 + t * 0.25) continue;
    let a = (1 - t) * (18 + noise(t * 9, 6) * 28);
    fill(226, 198, 158, a);
    let s = lerp(3.2, 0.45, t);
    ellipse(x, y, s, s * 1.4);
  }
}

function drawDispersal() {
  noStroke();
  for (let i = 0; i < 7200; i++) {
    let srcY = lerp(860, 1290, Math.pow(random(), 0.72));
    let life = random();
    if (random() < 0.42) life = Math.pow(random(), 1.8);
    let ang = -HALF_PI + random(-0.55, 0.72);
    let dist = life * random(40, 1040);
    let x = 650 + Math.cos(ang) * dist + (noise(i * 0.008, 2) - 0.5) * 50;
    let y = srcY + Math.sin(ang) * dist * random(0.55, 1.25);
    if (y < 8 || y > height - 8 || x < 0 || x > width) continue;
    let cool = constrain(life + (y < 900 ? 0.15 : 0), 0, 1);
    let R = lerp(232, 118, cool);
    let G = lerp(204, 128, cool);
    let B = lerp(164, 148, cool);
    let a = (1 - life) * random(16, 78);
    if (y > 1500) a *= 0.25;
    fill(R, G, B, a);
    let s = lerp(2.4, 0.35, life) * random(0.45, 1.35);
    ellipse(x, y, s, s);
  }
}

function drawFailedReflection() {
  noStroke();
  for (let i = 0; i < 48; i++) {
    let x = 690 + random(-70, 55);
    let y = 1736 + random(-8, 36);
    let w = random(10, 54);
    fill(110, 82, 56, random(4, 13));
    ellipse(x, y, w, random(1.5, 4.5));
  }
  for (let i = 0; i < 18; i++) {
    let gap = random(18, 70);
    fill(90, 78, 64, random(3, 8));
    ellipse(660 + i * 8 + gap * 0.2, 1762 + noise(i) * 10, gap, 2);
  }
}

function drawGrain() {
  noStroke();
  for (let i = 0; i < 20000; i++) {
    let x = random(width);
    let y = random(height);
    let v = random(40, 230);
    fill(v, v, v, random(6, 18));
    rect(x, y, 1.15, 1.15);
  }
}

function drawVignette() {
  noFill();
  for (let i = 0; i < 28; i++) {
    stroke(0, 0, 0, 7);
    strokeWeight(28);
    rect(i * 10, i * 12, width - i * 20, height - i * 18);
  }
  for (let y = 0; y < 420; y += 3) {
    stroke(0, map(y, 0, 420, 26, 0));
    strokeWeight(3);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(0, 8);
    ellipse(0, 0, 1500 + i * 60, 1500);
    ellipse(width, 0, 1300, 1400);
    ellipse(width, height, 1200, 900);
  }
}

let spiralParticles = [];
let risingParticles = [];
let ashParticles = [];
let branches = [];
let bgBlobs = [];
let fallStreams = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  initBgBlobs();
  initSpiralParticles();
  initRisingParticles();
  initAshParticles();
  initBranches();
  initFallStreams();
}

function initBgBlobs() {
  bgBlobs = [];
  for (let i = 0; i < 220; i++) {
    bgBlobs.push({
      x: random(0, 1600),
      y: random(0, 2000),
      r: random(30, 260),
      ratio: random(0.4, 1.2),
      alpha: random(3, 12),
      dark: random(1) < 0.7
    });
  }
}

function initSpiralParticles() {
  spiralParticles = [];
  for (let i = 0; i < 1600; i++) {
    let theta = random(0, 7 * PI);
    spiralParticles.push({
      theta: theta,
      type: random(1),
      size: random(0.4, 2.8),
      alpha: random(20, 160),
      trail: int(random(2, 6))
    });
  }
}

function initRisingParticles() {
  risingParticles = [];
  for (let i = 0; i < 200; i++) {
    risingParticles.push({
      x: 800 + random(-280, 280),
      y: random(160, 720),
      s: random(0.3, 2.2),
      a: random(10, 100)
    });
  }
}

function initAshParticles() {
  ashParticles = [];
  for (let i = 0; i < 2000; i++) {
    ashParticles.push({
      x: random(0, 1600),
      y: random(1500, 2000),
      s: random(0.4, 2.6),
      a: random(5, 70),
      type: int(random(3))
    });
  }
}

function initBranches() {
  branches = [];
  for (let i = 0; i < 70; i++) {
    branches.push({
      x: random(0, 1600),
      y0: random(1620, 1980),
      len: random(80, 420),
      sway: random(-80, 80),
      w: random(0.4, 2.2),
      a: random(25, 80)
    });
  }
}

function initFallStreams() {
  fallStreams = [];
  for (let i = 0; i < 50; i++) {
    fallStreams.push({
      x: 800 + random(-300, 300),
      yStart: random(1100, 1400),
      yEnd: random(1500, 1800),
      seed: random(100),
      alpha: random(15, 45)
    });
  }
}

function draw() {
  background(8, 7, 14);

  drawBgBlobs();
  drawVeils();
  drawCentralVoid();
  drawLightColumn();
  drawSpiralParticles();
  drawFallingStreams();
  drawBranches();
  drawGroundGradual();
  drawAshParticles();
  drawRisingParticles();
}

function drawBgBlobs() {
  noStroke();
  for (let b of bgBlobs) {
    if (b.dark) {
      fill(14, 11, 20, b.alpha);
    } else {
      fill(42, 28, 36, b.alpha);
    }
    ellipse(b.x, b.y, b.r, b.r * b.ratio);
  }
}

function drawVeils() {
  stroke(180, 175, 210, 8);
  strokeWeight(1);
  noFill();
  for (let i = 0; i < 80; i++) {
    let baseX = i * 20 + 10;
    beginShape();
    for (let y = 0; y <= 2000; y += 20) {
      let n = noise(i * 0.08, y * 0.0025);
      let off = (n - 0.5) * 180 * sin(map(y, 0, 2000, 0, PI));
      vertex(baseX + off, y);
    }
    endShape();
  }
}

function drawCentralVoid() {
  let cx = 800;
  let cy = 900;
  let R = 640;

  let grad = drawingContext.createRadialGradient(cx, cy, 30, cx, cy, R);
  grad.addColorStop(0, 'rgba(2,3,9,0.96)');
  grad.addColorStop(0.25, 'rgba(8,7,16,0.90)');
  grad.addColorStop(0.6, 'rgba(32,18,30,0.55)');
  grad.addColorStop(0.85, 'rgba(80,35,45,0.18)');
  grad.addColorStop(1, 'rgba(100,50,60,0)');
  drawingContext.fillStyle = grad;
  noStroke();
  drawingContext.beginPath();
  drawingContext.arc(cx, cy, R, 0, TWO_PI);
  drawingContext.fill();

  let coreGrad = drawingContext.createRadialGradient(cx, cy, 10, cx, cy, 260);
  coreGrad.addColorStop(0, 'rgba(0,0,0,0.98)');
  coreGrad.addColorStop(0.8, 'rgba(3,2,5,0.90)');
  coreGrad.addColorStop(1, 'rgba(10,6,15,0)');
  drawingContext.fillStyle = coreGrad;
  drawingContext.beginPath();
  drawingContext.arc(cx, cy, 260, 0, TWO_PI);
  drawingContext.fill();
}

function drawLightColumn() {
  noStroke();
  blendMode(ADD);
  for (let i = 0; i < 50; i++) {
    let t = i / 50;
    let y = 1000 + t * 800;
    let w = 240 * (1 - t * 0.45);
    let alpha = 22 * (1 - t);
    fill(150, 80, 95, alpha);
    ellipse(800, y, w, 35);
  }
  blendMode(BLEND);
}

function drawSpiralParticles() {
  let cx = 800;
  let cy = 900;
  let yScale = 0.42;
  blendMode(ADD);
  noStroke();
  for (let p of spiralParticles) {
    for (let k = 0; k < p.trail; k++) {
      let tt = p.theta - k * 0.09;
      if (tt < 0) break;
      let rr = map(tt, 0, 7 * PI, 170, 780);
      let x = cx + rr * cos(tt);
      let y = cy + rr * sin(tt) * yScale;
      let s = p.size * (1 - k * 0.12);
      let a = p.alpha * (1 - k * 0.16);
      let c = particleColor(p.type, a);
      fill(c);
      ellipse(x, y, s, s);
    }
  }
  blendMode(BLEND);
}

function particleColor(type, a) {
  if (type < 0.35) return color(210, 200, 190, a);
  if (type < 0.6) return color(135, 140, 165, a);
  if (type < 0.8) return color(190, 105, 85, a);
  return color(225, 190, 120, a);
}

function drawFallingStreams() {
  noFill();
  for (let s of fallStreams) {
    stroke(130, 90, 100, s.alpha);
    strokeWeight(0.8);
    beginShape();
    for (let t = 0; t <= 1; t += 0.04) {
      let y = lerp(s.yStart, s.yEnd, t);
      let drift = (noise(s.seed, t * 2) - 0.5) * 130 * (1 - t * 0.6);
      vertex(s.x + drift, y);
    }
    endShape();
  }
}

function drawBranches() {
  noFill();
  for (let b of branches) {
    stroke(70, 46, 42, b.a);
    strokeWeight(b.w);
    beginShape();
    vertex(b.x, b.y0);
    for (let t = 1; t <= 10; t++) {
      let tt = t / 10;
      let y = b.y0 - b.len * tt;
      let xoff = b.sway * sin(tt * PI) + (noise(b.x * 0.01, tt * 2) - 0.5) * 30;
      vertex(b.x + xoff, y);
    }
    endShape();
  }
}

function drawGroundGradual() {
  noStroke();
  for (let y = 1520; y < 2000; y += 12) {
    let t = map(y, 1520, 2000, 0, 1);
    fill(30 + 28 * t, 20 + 12 * t, 22 + 10 * t, 22);
    rect(0, y, 1600, 12);
  }
}

function drawAshParticles() {
