  bg.addColorStop(0, '#e2dbd0');
  bg.addColorStop(0.45, '#83796f');
  bg.addColorStop(1, '#08080a');
  drawingContext.fillStyle = bg;
  drawingContext.fillRect(0, 0, width, height);
}

function drawHaloContours() {
  const cx = width * 0.5;
  const cy = height * 0.54;
  noFill();
  for (let i = 0; i < 70; i++) {
    let r = 230 + i * 8;
    let alpha = map(i, 0, 70, 34, 0);
    stroke(235, 223, 200, alpha);
    strokeWeight(0.6);
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let n = noise(cos(a) * 0.7 + 5, sin(a) * 0.7 + 5);
      let rr = r + (n - 0.5) * 70;
      vertex(cx + cos(a) * rr * 1.28, cy + sin(a) * rr * 0.82);
    }
    endShape(CLOSE);
  }
}

function drawParticles() {
  const cx = width * 0.5;
  const cy = height * 0.54;
  noStroke();
  for (let i = 0; i < 7000; i++) {
    let t = pow(random(1), 1.8);
    let radius = 220 + t * 1330;
    let angle = random(TWO_PI);
    let x = cx + cos(angle) * radius * 1.28;
    let y = cy + sin(angle) * radius * 0.82 - radius * 0.14;
    let n1 = noise(x * 0.004, y * 0.004);
    let n2 = noise(x * 0.004 + 80, y * 0.004 + 80);
    x += (n1 - 0.5) * 180;
    y += (n2 - 0.5) * 180;
    let d = dist(x, y, cx, cy);
    if (d < 200 || x < 0 || x > width || y < 0 || y > height) continue;
    let a = constrain(map(d, 220, 1400, 0, 120), 0, 120);
    let w = constrain(map(d, 240, 1000, 30, 200), 30, 200);
    fill(w * 0.95, w * 0.85, w * 0.75, a);
    let s = random(0.7, 3.2);
    ellipse(x, y, s, s);
  }
}

function drawFilaments() {
  const cx = width * 0.5;
  const cy = height * 0.54;
  for (let i = 0; i < 3300; i++) {
    let t = pow(random(1), 1.9);
    let radius = 260 + t * 1180;
    let angle = random(TWO_PI);
    let x = cx + cos(angle) * radius * 1.28;
    let y = cy + sin(angle) * radius * 0.82 - radius * 0.14;
    let d = dist(x, y, cx, cy);
    if (d < 250 || x < 0 || x > width || y < 0 || y > height) continue;
    let n1 = noise(x * 0.005, y * 0.005);
    x += (n1 - 0.5) * 140;
    y += (noise(x * 0.005 + 100, y * 0.005 + 100) - 0.5) * 140;
    let dx = -sin(angle);
    let dy = cos(angle) * 0.82;
    let len = random(4, 18) * constrain(map(d, 250, 1000, 0.5, 1), 0.5, 1);
    let a = constrain(map(d, 260, 1400, 60, 130), 0, 130);
    let w = constrain(map(d, 300, 1000, 30, 185), 30, 185);
    stroke(w, w * 0.85, w * 0.72, a);
    strokeWeight(random(0.4, 1.4));
    line(x, y, x + dx * len, y + dy * len);
  }
}

function drawVoid() {
  const cx = width * 0.5;
  const cy = height * 0.54;
  const halo = drawingContext.createRadialGradient(cx, cy, 0, cx, cy, 900);
  halo.addColorStop(0, 'rgba(0,0,0,0.95)');
  halo.addColorStop(0.3, 'rgba(0,0,0,0.55)');
  halo.addColorStop(0.65, 'rgba(0,0,0,0.12)');
  halo.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = halo;
  drawingContext.fillRect(0, 0, width, height);

  noStroke();
  fill(0, 0, 0, 255);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.07) {
    let n = noise(cos(a) * 0.7 + 8, sin(a) * 0.7 + 8);
    let rr = 185 + n * 80;
    vertex(cx + cos(a) * rr * 1.3, cy + sin(a) * rr * 0.9);
  }
  endShape(CLOSE);
}

function drawRim() {
  const cx = width * 0.5;
