const W = 1600;
const H = 2000;
let motes = [];
let veils = [];
let floats = [];

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);

  for (let i = 0; i < 400; i++) {
    let x = constrain(randomGaussian(W * 0.5, W * 0.14), W * 0.15, W * 0.85);
    let y = random(H * 0.45, H * 0.96);
    let s = random(0.3, 2.8);
    let a = random(10, 80);
    let warmth = random(180, 255);
    let trail = random(2, 26);
    let drift = randomGaussian(0, 0.4);
    motes.push({ x, y, s, a, warmth, trail, drift });
  }

  for (let i = 0; i < 120; i++) {
    veils.push({
      y: random(-80, H + 80),
      amp: random(50, 280),
      phase: random(0, TWO_PI),
      alpha: random(3, 14)
    });
  }

  for (let i = 0; i < 60; i++) {
    floats.push({
      x: random(W * 0.25, W * 0.75),
      baseY: random(H * 0.55, H),
      length: random(180, 650),
      amp: random(15, 90),
      phase: random(0, TWO_PI),
      alpha: random(2, 10)
    });
  }
}

function draw() {
  noStroke();
  drawBackground();
  drawAbyss();
  drawVeils();
  drawFloats();
  drawPlume();
  drawEmberOrigin();
  drawMotes();
  drawVignette();
  noLoop();
}

function drawBackground() {
  let g = drawingContext.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#010102');
  g.addColorStop(0.25, '#050506');
  g.addColorStop(0.55, '#080708');
  g.addColorStop(0.8, '#0e0909');
  g.addColorStop(1, '#1a0d0c');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function drawAbyss() {
  let g = drawingContext.createRadialGradient(W * 0.5, H * 0.30, 30, W * 0.5, H * 0.30, 700);
  g.addColorStop(0, 'rgba(0,0,0,0.85)');
  g.addColorStop(0.45, 'rgba(0,0,0,0.38)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function drawVeils() {
  for (let v of veils) {
    stroke(215, 205, 195, v.alpha);
    noFill();
    beginShape();
    for (let x = 0; x <= W; x += 32) {
      let n = noise(x * 0.0025, v.y * 0.005, v.phase);
      let y = v.y + sin(x * 0.004 + v.phase) * v.amp * 0.35 + (n - 0.5) * v.amp;
      vertex(x, y);
    }
    endShape();
  }
}

function drawFloats() {
  for (let v of floats) {
    stroke(225, 210, 195, v.alpha);
    noFill();
    beginShape();
    let steps = floor(v.length / 18);
    for (let i = 0; i <= steps; i++) {
      let t = i / steps;
      let y = v.baseY - t * v.length;
      if (y < H * 0.12) break;
      let n = noise(v.x * 0.004, y * 0.005, v.phase);
      let x = v.x + (n - 0.5) * v.amp * 2 + sin(y * 0.006 + v.phase) * v.amp * 0.5;
      vertex(x, y);
    }
    endShape();
  }
}

function drawPlume() {
  let g1 = drawingContext.createLinearGradient(0, H, 0, 0);
  g1.addColorStop(0, 'rgba(80,50,42,0.45)');
  g1.addColorStop(0.3, 'rgba(125,90,80,0.28)');
  g1.addColorStop(0.6, 'rgba(170,145,135,0.10)');
  g1.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g1;
  drawOnePlume(0.16, 290, 3.3, 7.7);

  let g2 = drawingContext.createLinearGradient(0, H, 0, 0);
  g2.addColorStop(0, 'rgba(220,190,170,0.20)');
  g2.addColorStop(0.45, 'rgba(190,160,140,0.09)');
  g2.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g2;
  drawOnePlume(0.34, 130, 11.2, 23.5);
}

function drawOnePlume(topRel, halfMax, nz1, nz2) {
  let bottomY = H * 0.99;
  let topY = H * topRel;
  let steps = 260;
  let leftPts = [];
  let rightPts = [];

  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let y = lerp(bottomY, topY, t);
    let p = 1 - t;
    let half = 24 + halfMax * pow(p, 1.75);
    let nx = noise(t * 1.3, nz1);
    let nw = noise(t * 1.2, nz2);
    let cx = W * 0.5 + (nx - 0.5) * 380 * pow(p, 2.1);
    let left = cx - half * (0.65 + 0.55 * nw);
    let right = cx + half * (0.65 + 0.55 * (1 - nw));
    leftPts.push({ x: left, y: y });
    rightPts.push({ x: right, y: y });
  }

  drawingContext.beginPath();
  drawingContext.moveTo(leftPts[0].x, leftPts[0].y);
  for (let i = 1; i < leftPts.length; i++) drawingContext.lineTo(leftPts[i].x, leftPts[i].y);
  for (let i = rightPts.length - 1; i >= 0; i--) drawingContext.lineTo(rightPts[i].x, rightPts[i].y);
  drawingContext.closePath();
  drawingContext.fill();
}

function drawEmberOrigin() {
  let g = drawingContext.createRadialGradient(W / 2, H * 0.93, 10, W / 2, H * 0.93, 460);
  g.addColorStop(0, 'rgba(255,220,190,0.18)');
  g.addColorStop(0.4, 'rgba(210,160,135,0.08)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);

  let e = drawingContext.createRadialGradient(W / 2, H * 0.93, 1, W / 2, H * 0.93, 55);
  e.addColorStop(0, 'rgba(255,235,215,0.25)');
  e.addColorStop(0.5, 'rgba(255,200,165,0.09)');
  e.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = e;
  drawingContext.fillRect(0, 0, W, H);
}

function drawMotes() {
  for (let p of motes) {
    let t = constrain((H - p.y) / (H * 0.55), 0, 1);
    let alpha = p.a * pow(1 - t, 0.8);
    if (alpha <= 1) continue;

    if (p.trail > 10) {
      stroke(255, 230, 205, alpha * 0.22);
      strokeWeight(max(0.4, p.s * 0.45));
      line(p.x, p.y, p.x + p.drift, p.y - p.trail * (0.3 + 0.7 * t));
    }

    noStroke();
    fill(255, 220, 190, alpha * 0.07);
    ellipse(p.x, p.y, p.s * 7, p.s * 7);
    fill(255, 225, 200, alpha * 0.18);
    ellipse(p.x, p.y, p.s * 3, p.s * 3);
    fill(p.warmth, p.warmth - 12, p.warmth - 35, alpha * 0.75);
    ellipse(p.x, p.y, p.s, p.s);
  }
}

function drawVignette() {
  let g = drawingContext.createRadialGradient(W / 2, H * 0.5, H * 0.25, W / 2, H * 0.5, H * 0.78);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.7, 'rgba(0,0,0,0.30)');
  g.addColorStop(1, 'rgba(0,0,0,0.72)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

const W = 1600;
const H = 2000;
let THREADS = [];
let DUST = [];
let HORIZON = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  initialize();
  drawArtwork();
  noLoop();
}

function draw() {
}

function initialize() {
  THREADS = [];
  for (let i = 0; i < 160; i++) {
    let fromY = random(620, 1410);
    let t = constrain((fromY - 620) / (1410 - 620), 0, 1);
    let w = figureWidth(t);
    let cx = axisX(fromY);
    let side = random(1) < 0.5 ? -1 : 1;
    let edge = cx + side * (w / 2 + random(-8, 40));
    let upward = random(1) < 0.82;
    let x2 = 800 + randomGaussian(0, upward ? 480 : 360);
    x2 = constrain(x2, 60, W - 60);
    let y2 = upward ? random(120, 640) : random(1490, 1960);
    let cx1 = edge + random(-240, 240);
    let cy1 = fromY + (upward ? -random(80, 420) : random(80, 320));
    let cx2 = x2 + random(-220, 220);
    let cy2 = y2 + (upward ? random(60, 330) : -random(70, 330));
    THREADS.push({
      x1: edge, y1: fromY,
      x2: x2, y2: y2,
      cx1: cx1, cy1: cy1,
      cx2: cx2, cy2: cy2,
      w: random(0.25, 1.2),
      a: random(16, 74),
      cool: random(1) < 0.28,
      depth: random(1) < 0.72 ? 'front' : 'back'
    });
  }

  DUST = [];
  for (let i = 0; i < 4400; i++) {
    let y = random(1) < 0.7 ? random(180, 1220) : random(1220, 1620);
    let spread = dustSpread(y);
    let x = 800 + randomGaussian(0, spread * 0.58);
    if (x < -40 || x > W + 40) continue;
    let normDist = Math.abs(x - 800) / (spread + 1);
    let size = random(0.2, 4.6) * (0.32 + 0.68 / (1 + normDist * 2.0));
    let alpha = random(6, 175) * (0.35 + 0.65 / (1 + normDist * 2.0));
    DUST.push({
      x: x, y: y,
      size: size,
      alpha: alpha,
      kind: random(1),
      cool: random(1) < 0.24
    });
  }

  HORIZON = [];
  for (let i = 0; i < 170; i++) {
    let y = random(1450, 1980);
    let t = 1 - (y - 1450) / 530;
    HORIZON.push({
      y: y,
      x: random(-200, W + 200),
      len: random(40, 560) * (0.4 + 0.6 * t),
      w: random(0.3, 1.5),
      a: random(2, 22) * t
    });
  }
}

function dustSpread(y) {
  let d = (y - 840) / 520;
  let g = Math.exp(-d * d * 1.6);
  let base = 130 + 440 * g;
  if (y < 380) base = 210 + 340 * (380 - y) / 220;
  if (y > 1360) base = 220 - 80 * ((y - 1360) / 300);
  return Math.max(60, base);
}

function figureWidth(t) {
  t = constrain(t, 0, 1);
  let main = 470 * Math.pow(Math.sin(Math.PI * t), 1.3);
  let undulation = 70 * Math.sin(3.0 * Math.PI * t) * Math.sin(Math.PI * t);
  return Math.max(10, 28 + main + undulation);
}

function axisX(y) {
  return 800 + (noise(y * 0.004, 13) - 0.5) * 150;
}

function edgeOffset(y, seed) {
  let t = constrain((y - 600) / (1420 - 600), 0, 1);
  let local = 0.2 + 0.8 * Math.pow(Math.sin(Math.PI * t), 1.2);
  return (noise(y * 0.012, seed) - 0.5) * 120 * local;
}

function drawArtwork() {
  drawBackground();
  drawHaze();
  drawThreads('back');
  drawDarkForm();
  drawRimLight();
  drawThreads('front');
  drawDust();
  drawPool();
  drawVignette();
}

function drawBackground() {
  noStroke();
  let top = color(5, 6, 12);
  let bottom = color(13, 14, 21);
  for (let y = 0; y < H; y += 2) {
    let c = lerpColor(top, bottom, y / H);
    fill(c);
    rect(0, y, W, 2);
  }
}

function drawHaze() {
  push();
  noStroke();
  blendMode(SCREEN);
  let ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  let g = ctx.createRadialGradient(800, 880, 30, 800, 880, 1300);
  g.addColorStop(0, 'rgba(198,178,150,0.20)');
  g.addColorStop(0.3, 'rgba(127,125,145,0.09)');
  g.addColorStop(0.65, 'rgba(50,58,80,0.035)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

  for (let k = 0; k < 110; k++) {
    let y = 580 + k * 8.2;
    let d = (y - 960) / 500;
    let t = Math.exp(-d * d);
    let w = 120 + 500 * t;
    let h = 5 + 27 * t;
    fill(192, 174, 150, 2 + 7 * t);
    ellipse(800, y, w, h);
  }
  pop();
}

function drawDarkForm() {
  let y1 = 600, y2 = 1420, step = 5;
  drawFormPath(y1, y2, step, 70, 6, 0.0);
  drawFormPath(y1, y2, step, 42, 14, 1.3);
  drawFormPath(y1, y2, step, 16, 40, 2.7);
  drawFormPath(y1, y2, step, 0, 220, 3.1);
}

function drawFormPath(y1, y2, step, expand, alpha, seedOff) {
  noStroke();
  fill(4, 5, 10, alpha);
  beginShape();
  for (let y = y1; y <= y2; y += step) {
    let t = (y - y1) / (y2 - y1);
    let w = figureWidth(t) + expand;
    let cx = axisX(y);
    let nL = edgeOffset(y, 31 + seedOff * 17);
    vertex(cx - w / 2 + nL, y);
  }
  for (let y = y2; y >= y1; y -= step) {
    let t = (y - y1) / (y2 - y1);
    let w = figureWidth(t) + expand;
    let cx = axisX(y);
    let nR = edgeOffset(y, 47 + seedOff * 17);
    vertex(cx + w / 2 + nR, y);
  }
  endShape(CLOSE);
}

function drawRimLight() {
  push();
  blendMode(SCREEN);
  noFill();
  let y1 = 600, y2 = 1420;
  let prevLX = null, prevLY = null;
  let prevRX = null, prevRY = null;

  for (let y = y1; y <= y2; y += 5) {
    let t = (y - y1) / (y2 - y1);
    let w = figureWidth(t);
    let cx = axisX(y);
    let nL = edgeOffset(y, 121);
    let nR = edgeOffset(y, 163);
    let xL = cx - w / 2 + nL;
    let xR = cx + w / 2 + nR;
    let pulse = Math.sin(Math.PI * t);
    let aL = 110 * Math.pow(pulse, 0.8);
    let aR = 80 * Math.pow(pulse, 0.75);

    strokeWeight(2.6);
    stroke(235, 212, 175, aL * 0.14);
    point(xL - 7, y);
    strokeWeight(1.5);
    stroke(228, 205, 166, aL * 0.65);
    point(xL, y);

    strokeWeight(2.4);
    stroke(150, 165, 195, aR * 0.11);
    point(xR + 7, y);
    strokeWeight(1.4);
    stroke(165, 180, 205, aR * 0.55);
    point(xR, y);

    if (prevLX !== null) {
      strokeWeight(1.0);
      stroke(228, 205, 166, aL * 0.4);
      line(prevLX, prevLY, xL, y);
      stroke(165, 180, 205, aR * 0.35);
      line(prevRX, prevRY, xR, y);
    }

    prevLX = xL;
    prevLY = y;
    prevRX = xR;
    prevRY = y;
  }
  pop();
}

function drawThreads(depth) {
  push();
  blendMode(SCREEN);
  noFill();

  for (let th of THREADS) {
    if (th.depth !== depth) continue;

    if (th.cool) {
      stroke(160, 178, 205, th.a * 0.22);
    } else {
      stroke(218, 198, 168, th.a * 0.22);
    }
    strokeWeight(th.w * 2.0);
    bezier(th.x1, th.y1, th.cx1, th.cy1, th.cx2, th.cy2, th.x2, th.y2);

    if (th.cool) {
      stroke(160, 178, 205, th.a * 0.55);
    } else {
      stroke(218, 198, 168, th.a * 0.55);
    }
    strokeWeight(th.w);
    bezier(th.x1, th.y1, th.cx1, th.cy1, th.cx2, th.cy2, th.x2, th.y2);
  }

  pop();
}

function drawDust() {
  push();
  blendMode(SCREEN);

  for (let p of DUST) {
    if (p.kind >= 0.22) continue;
    let n = noise(p.x * 0.0025, p.y * 0.0025, 99);
    let ang = n * Math.PI * 3.2;
    let len = p.size * 2.4 + 1.2;
    strokeWeight(p.size * 0.45);
    if (p.cool) stroke(165, 185, 215, p.alpha * 0.8);
    else stroke(220, 199, 165, p.alpha * 0.8);
    line(p.x, p.y, p.x - Math.cos(ang) * len, p.y - Math.sin(ang) * len);
  }

  noStroke();
  for (let p of DUST) {
    if (p.kind < 0.22) continue;
    if (p.cool) fill(168, 190, 218, p.alpha);
    else fill(218, 196, 164, p.alpha);
    ellipse(p.x, p.y, p.size, p.size);

    if (p.size > 2.4) {
      fill(255, 244, 220, p.alpha * 0.6);
      ellipse(p.x, p.y, p.size * 0.35, p.size * 0.35);
    }
  }

  pop();
}

function drawPool() {
  push();
  noStroke();
  for (let y = 1460; y < H; y += 8) {
    let t = (y - 1460) / (H - 1460);
    fill(3, 4, 9, 35 * t);
    rect(0, y, W, 8);
  }

  blendMode(SCREEN);
  for (let h of HORIZON) {
    strokeWeight(h.w);
    stroke(210, 195, 170, h.a * 0.7);
    line(h.x - h.len / 2, h.y, h.x + h.len / 2, h.y);
  }
  pop();
}

function drawVignette() {
  let ctx = drawingContext;
  ctx.save();
  ctx.globalCompositeOperation = 'source-over';
  let g = ctx.createRadialGradient(800, 980, 300, 800, 980, 1900);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.55, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.74)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  const ctx = drawingContext;
  const W = 1600, H = 2000;

  // ---- 深色底 ----
  let bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0.00, '#141119');
  bg.addColorStop(0.42, '#0d0c11');
  bg.addColorStop(1.00, '#060609');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  let aura = ctx.createRadialGradient(800, 700, 60, 800, 700, 1000);
  aura.addColorStop(0.0, 'rgba(158,138,126,0.105)');
  aura.addColorStop(0.5, 'rgba(120,108,116,0.05)');
  aura.addColorStop(1.0, 'rgba(0,0,0,0)');
  ctx.fillStyle = aura;
  ctx.fillRect(0, 0, W, H);

  function pickColor() {
    const r = random();
    if (r < 0.72) return [213 + random(-16, 8), 203 + random(-16, 8), 187 + random(-18, 6)];
    if (r < 0.83) return [148 + random(-10, 10), 158 + random(-10, 10), 176 + random(-10, 10)];
    if (r < 0.91) return [194 + random(-14, 10), 156 + random(-12, 10), 102 + random(-12, 8)];
    if (r < 0.965) return [166 + random(-14, 10), 82 + random(-10, 8), 64 + random(-8, 8)];
    return [98 + random(-8, 8), 94 + random(-8, 8), 102 + random(-8, 8)];
  }

  const CLOTH_L = 195, CLOTH_R = 1405, CLOTH_T = 96;
  function edgeY(x) { return 438 + 94 * noise(x * 0.0042 + 3.7); }

  // ---- 经线（垂落之物）----
  const threads = [];
  for (let x0 = CLOTH_L; x0 <= CLOTH_R; x0 += 10) {
    const col = pickColor();
    const A = 128 + random(58);
    const startY = CLOTH_T - 14 - random(72);
    const release = edgeY(x0) + random(-5, 9);
    let life;
    const r = random();
    if (r < 0.07) life = 60 + random(90);
    else if (r < 0.82) life = 170 + Math.pow(random(), 1.6) * 640;
    else life = 520 + random(420);
    const endY = Math.min(release + life, 1290 + random(80));
    threads.push({
      x0, col, A, startY, release, endY,
      fadeMode: random() < 0.52,
      lean: (noise(x0 * 0.05, 7.7) - 0.5) * 2,
      nseed: random(1000)
    });
  }
  threads.push({ // 最后一根，独自最久
    x0: 800 + random(-6, 6), col: [206, 205, 208], A: 195,
    startY: CLOTH_T - 30, release: edgeY(800), endY: 1545 + random(30),
    fadeMode: true, last: true,
    lean: (noise(800 * 0.05, 7.7) - 0.5) * 2, nseed: random(1000)
  });

  function threadX(t, y) {
    if (y <= t.release) return t.x0 + (noise(t.nseed, y * 0.06) - 0.5) * 3.2;
    const d = y - t.release;
    const amp = Math.min(t.last ? 30 : 52, 3 + d * 0.055);
    return t.x0 + (noise(t.nseed, y * 0.0085) - 0.5) * 2 * amp + d * 0.05 * t.lean;
  }

  for (const t of threads) {
    let px = null, py = null;
    const step = t.last ? 4 : 5.5;
    for (let y = t.startY; y <= t.endY; y += step) {
      const x = threadX(t, y);
      let a = t.A * constrain(map(y, t.startY, t.startY + 95, 0, 1), 0, 1);
      const fadeLen = t.last ? 300 : 170;
      if (t.fadeMode && y > t.endY - fadeLen) a *= map(y, t.endY - fadeLen, t.endY, 1, 0);
      if (!t.fadeMode && y > t.endY - 10) a *= map(y, t.endY - 10, t.endY, 1, 0.72);
      const d = Math.max(0, y - t.release);
      const baseW = t.last ? 1.15 : Math.max(0.42, 1.55 - d * 0.0011);
      const w = baseW * constrain(map(y, t.startY, t.startY + 90, 0.35, 1), 0.35, 1);
      if (px !== null && a > 0.6) {
        stroke(t.col[0], t.col[1], t.col[2], a);
        strokeWeight(w);
        line(px, py, x, y);
      }
      px = x; py = y;
    }
    if (!t.fadeMode && !t.last) { // 骤然成结
      noStroke();
      fill(t.col[0], t.col[1], t.col[2], t.A * 0.8);
      ellipse(px, py, 3.4, 4.0);
    }
    if (!t.last && !t.fadeMode && random() < 0.3) { // 断口起毛
      const nf = 2 + floor(random(2));
      for (let f = 0; f < nf; f++) {
        let ang = HALF_PI + random(-0.62, 0.62);
        let fx = px, fy = py;
        const len = 24 + random(52);
        for (let s = 0; s < 6; s++) {
          ang += random(-0.22, 0.22);
          const nx = fx + Math.cos(ang) * len / 6;
          const ny = fy + Math.sin(ang) * len / 6;
          stroke(t.col[0], t.col[1], t.col[2], t.A * 0.42 * (1 - s / 6));
          strokeWeight(0.55);
          line(fx, fy, nx, ny);
          fx = nx; fy = ny;
        }
      }
    }
  }

  // ---- 纬线（维系之物，先退场）----
  for (let y = CLOTH_T + 4; y < 552; y += 6.1 + random(1.6)) {
    if (y > edgeY(800) + 40 && random() < 0.35) continue;
    const rowA = (88 + random(64)) * constrain(map(y, 70, 168, 0.08, 1), 0.08, 1);
    const rc = random() < 0.8
      ? [216 + random(-12, 8), 206 + random(-12, 8), 190 + random(-14, 6)]
      : [188 + random(-12, 8), 176 + random(-12, 8), 168 + random(-12, 8)];
    const wy = 1.35 + random(0.75) + (random() < 0.1 ? 0.4 : 0);
    const ph = random(1000);
    const ml = 4 + random(14), mr = 4 + random(14);
    let sx = null, sy = null;
    for (let x = CLOTH_L + ml; x <= CLOTH_R - mr; x += 7) {
      const on = y < edgeY(x) + random(-5, 5) && noise(x * 0.021, y * 0.061) < 0.94;
      if (on) {
        const yy = y + (noise(ph + x * 0.02) - 0.5) * 3.4;
        const aa = rowA * (0.72 + 0.28 * noise(x * 0.03, ph));
        if (sx !== null) {
          stroke(rc[0], rc[1], rc[2], aa);
          strokeWeight(wy);
          line(sx, sy, x, yy);
        }
        sx = x; sy = yy;
      } else { sx = null; sy = null; }
    }
  }

  // ---- 织纹里偶发的亮 ----
  for (let i = 0; i < 260; i++) {
    const x = CLOTH_L + 10 * floor(random((CLOTH_R - CLOTH_L) / 10));
    const y = 120 + random(300);
    if (y < edgeY(x) - 8) {
      stroke(232, 226, 214, 26 + random(30));
      strokeWeight(1.3);
      line(x, y, x, y + 2.5 + random(3));
    }
  }

  // ---- 已脱落的游丝 ----
  for (let i = 0; i < 46; i++) {
    let fx = random(120, 1480), fy = random(470, 1520);
    let ang = HALF_PI + random(-1.1, 1.1);
    const len = 16 + random(46);
    const grey = random() < 0.5;
    const al = 12 + random(24);
    for (let s = 0; s < 5; s++) {
      ang += random(-0.3, 0.3);
      const nx = fx + Math.cos(ang) * len / 5;
      const ny = fy + Math.sin(ang) * len / 5;
      stroke(grey ? 190 : 150, grey ? 184 : 150, grey ? 172 : 152, al * (1 - s / 5.5));
      strokeWeight(0.6);
      line(fx, fy, nx, ny);
      fx = nx; fy = ny;
    }
  }

  // ---- 沉落的灰 ----
  noStroke();
  for (const t of threads) {
    if (t.last) continue;
    const ex = threadX(t, t.endY);
    const k = floor(random(2, 6));
    for (let i = 0; i < k; i++) {
      const dy = 14 + Math.pow(random(), 1.5) * 240;
      fill(t.col[0], t.col[1], t.col[2], (4 + random(8)) * 0.9);
      ellipse(ex + random(-9, 9) + random(-6, 6) * (dy / 240), t.endY + dy,
        1 + random(1.4), 1 + random(1.4));
    }
  }
  for (let i = 0; i < 70; i++) {
    fill(190, 182, 172, 2.5 + random(4));
    ellipse(random(150, 1450), random(1580, 1960), 1 + random(1.2), 1 + random(1.2));
  }

  // ---- 颗粒 ----
  noStroke();
  for (let i = 0; i < 21000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.56) fill(0, 0, 0, 3 + random(11));
    else fill(255, 246, 236, 2 + random(8));
    rect(x, y, random() < 0.04 ? 2 : 1, 1);
  }

  // ---- 收束的暗 ----
  let topShade = ctx.createLinearGradient(0, 0, 0, 300);
  topShade.addColorStop(0, 'rgba(4,3,7,0.5)');
  topShade.addColorStop(1, 'rgba(4,3,7,0)');
  ctx.fillStyle = topShade;
  ctx.fillRect(0, 0, W, 300);

  let botShade = ctx.createLinearGradient(0, 1560, 0, H);
  botShade.addColorStop(0, 'rgba(3,3,6,0)');
  botShade.addColorStop(1, 'rgba(3,3,6,0.42)');
  ctx.fillStyle = botShade;
  ctx.fillRect(0, 1560, W, H - 1560);

  let vig = ctx.createRadialGradient(800, 880, 540, 800, 980, 1620);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(0.6, 'rgba(3,3,6,0.16)');
  vig.addColorStop(1, 'rgba(2,2,5,0.55)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, W, H);
}

// 万流归寂 —— 死亡是承接万物的寂静之器
// p5.js 1.11 · 1600 × 2000 · 静态图像

const BONE  = [216, 203, 182];
const ROSE  = [185, 143, 130];
const OCHRE = [196, 166, 120];
const ASH   = [142, 139, 132];
const SLATE = [88, 94, 104];
const NIGHT = [18, 20, 27];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  baseGradient();
  upperGlow();
  washes();
  upperArcs();
  threads();
  leaves();
  motes();
  speckles();
  basin();
  settled();
  grain();
  vignette();
}

function colStr(c, a) {
  return 'rgba(' + (c[0] | 0) + ',' + (c[1] | 0) + ',' + (c[2] | 0) + ',' + a + ')';
}
function mixc(a, b, t) {
  t = constrain(t, 0, 1);
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}
function ss(a, b, t) {
  t = constrain((t - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}
function softEllipse(x, y, rx, ry, c, a) {
  const ctx = drawingContext;
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, ry / rx);
  const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
  g.addColorStop(0, colStr(c, a));
  g.addColorStop(1, colStr(c, 0));
  ctx.fillStyle = g;
  ctx.fillRect(-rx, -rx, rx * 2, rx * 2);
  ctx.restore();
}

// 基底：从温亮的生之众相，一路沉入冷寂的黑
function baseGradient() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, 2000);
  const stops = [
    [0.00, '#D6C7B1'], [0.10, '#CBB59C'], [0.22, '#B99F8F'],
    [0.36, '#99928B'], [0.50, '#6F7076'], [0.63, '#4A4E58'],
    [0.75, '#282C36'], [0.86, '#13151D'], [1.00, '#07080D']
  ];
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1600, 2000);
}

function upperGlow() {
  softEllipse(820, 300, 780, 620, [252, 240, 216], 0.30);
  softEllipse(820, 230, 400, 320, [255, 248, 228], 0.28);
  softEllipse(420, 520, 420, 300, [226, 196, 160], 0.10);
  softEllipse(1220, 560, 430, 310, [214, 178, 150], 0.10);
}

function washes() {
  const warm = [BONE, ROSE, OCHRE, [224, 206, 180], [205, 160, 120]];
  const cool = [ASH, SLATE, [70, 76, 88], [54, 58, 70]];
  for (let i = 0; i < 40; i++) {
    const y = random(-80, 2100);
    let c, a;
    if (y < 760) { c = random(warm); a = random(0.05, 0.13); }
    else if (y < 1380) { c = random(cool); a = random(0.05, 0.12); }
    else { c = random([[20, 22, 30], [14, 16, 22], [30, 26, 30]]); a = random(0.10, 0.20); }
    const r = random(180, 520);
    softEllipse(random(-100, 1700), y, r, r * random(0.55, 1), c, a);
  }
  drawingContext.globalCompositeOperation = 'multiply';
  for (let i = 0; i < 7; i++) {
    softEllipse(random(200, 1400), random(700, 1400), random(260, 520), random(140, 300), [112, 116, 124], random(0.10, 0.20));
  }
  drawingContext.globalCompositeOperation = 'source-over';
}

// 上方的微光弧：与下方静水的涟漪互为镜像——生亦是一圈 passing 的涟漪
function upperArcs() {
  noFill();
  strokeWeight(1.1);
  const R = [300, 430, 570];
  for (let i = 0; i < 3; i++) {
    stroke(colStr([250, 240, 220], (14 - i * 3) / 255));
    arc(800, 190, R[i] * 2, R[i] * 2, PI * 0.12, PI * 0.88, OPEN);
  }
}

// 生命的丝线：各自出发，各自在半途断散
function threads() {
  const warms = [BONE, ROSE, OCHRE, [228, 214, 190], [206, 158, 116]];
  for (let i = 0; i < 86; i++) {
    const x0 = random(60, 1540), y0 = random(30, 600);
    const yEnd = lerp(730, 1690, pow(random(), 1.35));
    const col = random(warms);
    const wBase = random(0.9, 2.4);
    const aBase = random(52, 108);
    const off = random(100);
    let x = x0, y = y0;
    let a = HALF_PI + random(-0.35, 0.35);
    while (y < yEnd) {
      const p = (y - y0) / (yEnd - y0);
      a = lerp(a, HALF_PI, 0.10) + (noise(x * 0.0022, y * 0.0022, off) - 0.5) * 0.85;
      const s = random(5, 9);
      const nx = x + cos(a) * s, ny = y + sin(a) * s;
      const gap = p > 0.68 && random() < map(p, 0.68, 1, 0.04, 0.78);
      if (!gap) {
        let c = mixc(col, ASH, constrain(p * 0.9, 0, 1));
        if (y > 1320) c = mixc(c, SLATE, constrain((y - 1320) / 300, 0, 0.8));
        stroke(colStr(c, (aBase / 255) * (1 - ss(0.66, 1, p))));
        strokeWeight(wBase * (1 - p * 0.72));
        line(x, y, nx, ny);
      }
      if (random() < 0.05) {
        noStroke();
        fill(colStr(mixc(col, ASH, 0.4), 0.14));
        circle(x + random(-6, 6), y + random(-4, 4), 1.4);
      }
      x = nx; y = ny;
      if (x < -60 || x > 1660 || y > 1720) break;
    }
    if (y < 1700) {
      noStroke();
      const k = floor(random(6, 16));
      for (let j = 0; j < k; j++) {
        fill(colStr(mixc(col, ASH, 0.75), random(0.08, 0.28)));
        circle(x + random(-24, 24), y + random(-6, 30), random(1, 2.6));
      }
    }
  }
}

// 叶片：越往下越解体，碎成飘落的尘
function leaves() {
  const cols = [BONE, ROSE, OCHRE, [222, 200, 172], [190, 150, 120]];
  for (let i = 0; i < 26; i++) {
    const x = random(110, 1490), y = random(150, 880);
    const s = random(26, 72);
    const diss = constrain((y - 430) / 420 + random(-0.15, 0.25), 0, 1);
    const c = random(cols);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    if (diss < 0.55) {
      noStroke();
      fill(colStr(c, 0.16 + 0.16 * (1 - diss)));
      beginShape();
      vertex(0, -s * 0.5);
      for (let t = 0; t <= 1.001; t += 0.06) {
        const w = s * 0.30 * pow(sin(PI * min(t, 1)), 0.85);
        vertex(w, s * (min(t, 1) - 0.5));
      }
      for (let t = 1; t >= -0.001; t -= 0.06) {
        const w = s * 0.30 * pow(sin(PI * max(t, 0)), 0.85);
        vertex(-w, s * (max(t, 0) - 0.5));
      }
      endShape(CLOSE);
      stroke(colStr(mixc(c, ASH, 0.3), 0.20));
      strokeWeight(0.8);
      line(0, -s * 0.5, 0, s * 0.5);
    } else {
      noStroke();
      const nDots = floor(lerp(60, 12, diss));
      for (let d = 0; d < nDots; d++) {
        const t = random();
        const w = s * 0.30 * pow(sin(PI * t), 0.85) * random(-1, 1);
        fill(colStr(c, random(0.08, 0.30)));
        circle(w, s * (t - 0.5), random(1, 2.4));
      }
      for (let d = 0; d < floor(3 + 5 * (1 - diss)); d++) {
        fill(colStr(mixc(c, ASH, 0.6), random(0.10, 0.25)));
        circle(random(-s * 0.3, s * 0.3), s * 0.5 + random(6, 70), random(1, 2));
      }
    }
    pop();
  }
}

// 光屑：被下方的暗器轻轻吸引，一路褪色、沉降
function motes() {
  const warms = [BONE, ROSE, OCHRE, [226, 210, 186], [198, 150, 112]];
  for (let i = 0; i < 1300; i++) {
    let x = random(20, 1580), y = random(20, 950);
    let vx = random(-0.4, 0.4), vy = random(0.5, 1.3);
    const base = random(warms);
    const pts = [[x, y]];
    for (let k = 0; k < 340; k++) {
      vx += (noise(x * 0.0016, y * 0.0016) - 0.5) * 0.5;
      if (y > 880) vx += (800 - x) * 0.00012;
      vx *= 0.94;
      vy = constrain(vy + 0.012 + (y > 1200 ? 0.01 : 0), 0.5, 3.0);
      x += vx; y += vy;
      if (k % 3 === 0) pts.push([x, y]);
      if (y > 1875 || x < -70 || x > 1670) break;
    }
    noFill();
    const CH = 14;
    for (let c0 = 0; c0 < pts.length - 1; c0 += CH) {
      const end = min(c0 + CH, pts.length - 1);
      const mid = pts[(c0 + end) >> 1];
      const t = constrain((mid[1] - 40) / 1800, 0, 1);
      let cc = mixc(base, ASH, constrain(t * 1.25, 0, 1));
      if (t > 0.7) cc = mixc(cc, NIGHT, ((t - 0.7) / 0.3) * 0.8);
      stroke(colStr(cc, lerp(0.34, 0.10, t)));
      strokeWeight(lerp(1.8, 0.85, t));
      beginShape();
      for (let q = c0; q <= end; q++) vertex(pts[q][0], pts[q][1]);
      endShape();
    }
  }
}

function speckles() {
  noStroke();
  for (let i = 0; i < 900; i++) {
    const y = random() < 0.62 ? random(60, 820) : random(820, 1700);
    const x = random(20, 1580);
    const t = constrain(y / 1800, 0, 1);
    fill(colStr(mixc([236, 224, 200], [90, 96, 108], t), random(0.05, 0.20) * (1 - t * 0.5)));
    circle(x, y, random(1, 2.4));
  }
}

// 底部的器：温厚的黑暗，一圈圈凝止的水纹
function basin() {
  softEllipse(800, 2015, 1520, 980, [5, 6, 10], 0.97);
  softEllipse(800, 1880, 940, 540, [7, 8, 13], 0.90);
  softEllipse(800, 1745, 560, 330, [128, 58, 42], 0.12);

  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 1462, 0, 1596);
  g.addColorStop(0, 'rgba(148,158,182,0)');
  g.addColorStop(0.5, 'rgba(148,158,182,0.07)');
  g.addColorStop(1, 'rgba(148,158,182,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1462, 1600, 134);

  noFill();
  const R = [[300, 74, 0.07], [520, 128, 0.06], [780, 192, 0.05], [1090, 268, 0.04]];
  for (const r of R) {
    stroke(colStr([152, 162, 184], r[2]));
    strokeWeight(1.2);
    ellipse(800, 1722, r[0] * 2, r[1] * 2);
  }
  stroke(colStr([214, 164, 124], 0.05));
  strokeWeight(1);
  ellipse(800, 1708, 360, 88);
}

// 沉入器底的最后余烬
function settled() {
  noStroke();
  for (let i = 0; i < 110; i++) {
    const x = 800 + (random() + random() - 1) * 640;
    const y = random(1540, 1860);
    const deep = constrain((y - 1540) / 320, 0, 1);
    fill(colStr([226, 192, 150], lerp(0.16, 0.03, deep) * random(0.5, 1)));
    circle(x, y, random(1, 2.4));
  }
}

function grain() {
  const ctx = drawingContext;
  for (let i = 0; i < 15000; i++) {
    const x = random(1600), y = random(2000);
    ctx.fillStyle = y < 1250
      ? colStr([40, 36, 30], random(0.03, 0.09))
      : colStr([180, 186, 200], random(0.02, 0.06));
    ctx.fillRect(x, y, 1, 1);
  }
}

function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(800, 960, 600, 800, 980, 1560);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.66, 'rgba(6,7,11,0.08)');
  g.addColorStop(1, 'rgba(3,4,7,0.44)');
  ctx.fillStyle = g;
