  ctx.fillRect(0, 0, 1600, 210);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();

  const W = width;
  const H = height;
  const cx = W * 0.5;
  const voidY = H * 0.36;
  const lineY = H * 0.655;

  paintBackground(W, H);
  paintUpperMist(W, H, cx, voidY, lineY);
  paintVoid(cx, voidY);
  paintDescendingThreads(cx, lineY, W);
  paintThreshold(W, cx, lineY);
  paintBelow(W, H, lineY);
  paintParticles(cx, lineY, W, voidY);
  paintGrain(W, H);
  vignette(W, H, cx);
}

function sampleGradient(stops, t) {
  if (t <= stops[0][0]) return stops[0][1];
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      const amt = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(stops[i][1], stops[i + 1][1], amt);
    }
  }
  return stops[stops.length - 1][1];
}

function paintBackground(W, H) {
  noStroke();
  const stops = [
    [0.0, color(254, 72, 3, 1)],
    [0.24, color(246, 62, 6, 1)],
    [0.48, color(230, 46, 9, 1)],
    [0.655, color(216, 26, 12, 1)],
    [0.76, color(224, 30, 5, 1)],
    [1.0, color(16, 20, 2, 1)]
  ];
  for (let y = 0; y < H; y += 2) {
    const t = y / H;
    fill(sampleGradient(stops, t));
    rect(0, y, W, 3);
  }
}

function paintUpperMist(W, H, cx, voidY, lineY) {
  noStroke();
  for (let i = 0; i < 900; i++) {
    const x = random(W);
    const y = random(-40, lineY * 0.98);
    const n = noise(x * 0.0013, y * 0.0013);
    if (n < 0.34) continue;
    const d = dist(x, y, cx, voidY);
    let a = map(d, 80, W * 0.9, 0.05, 0.0);
    a *= map(n, 0.34, 0.95, 0.0, 1.0) * random(0.18, 1.0);
    if (a <= 0) continue;
    const hue = 225 + noise(i * 0.013) * 40;
    fill(hue, 34, 16, a);
    ellipse(x + random(-40, 40), y + random(-24, 24), random(28, 190), random(10, 62));
  }
}

function paintVoid(cx, voidY) {
  noStroke();
  const maxR = 565;

  for (let r = maxR * 1.45; r > maxR * 0.55; r -= 3) {
    const t = map(r, maxR * 1.45, maxR * 0.55, 0, 1);
    fill(235, 55, 8, 0.008 + t * 0.02);
    ellipse(cx, voidY, r * 1.14, r * 1.22);
  }

  for (let r = maxR; r > 0; r -= 2) {
    const t = r / maxR;
    fill(243, 84, 2, map(t, 1, 0, 0.005, 0.18));
    ellipse(cx, voidY, r * 1.06, r * 1.16);
  }

  fill(246, 100, 1, 0.42);
  ellipse(cx, voidY, maxR * 0.68, maxR * 0.80);

  for (let i = 0; i < 720; i++) {
    const ang = random(TWO_PI);
    const rr = maxR * random(0.94, 1.16);
    const x = cx + cos(ang) * rr * 1.05;
    const y = voidY + sin(ang) * rr * 1.16;
    if (random() < 0.06) fill(42, 18, 74, random(0.006, 0.03));
    else fill(216, 20, 70, random(0.004, 0.026));
    ellipse(x, y, random(0.45, 1.8), random(0.45, 1.8));
  }
}

function paintDescendingThreads(cx, lineY, W) {
  for (let i = 0; i < 190; i++) {
    const x0 = cx + random(-1, 1) * W * 0.46;
    const y0 = random(-70, lineY * 0.62);
    const y1 = lineY + random(-26, 44);
    const segments = int(random(9, 26));
    const hue = random() < 0.82 ? 219 + random(-18, 30) : 42 + random(-10, 12);
    const sat = hue > 100 ? 24 : 14;
    const bri = hue > 100 ? 70 : 82;
    strokeWeight(random(0.35, 1.2));

    for (let s = 0; s < segments; s++) {
      const t0 = s / segments;
      const t1 = (s + 1) / segments;
      const yy0 = lerp(y0, y1, t0);
      const yy1 = lerp(y0, y1, t1);
      const converge0 = lerp(x0, cx + (x0 - cx) * 0.10, t0);
      const converge1 = lerp(x0, cx + (x0 - cx) * 0.10, t1);
      const xA = converge0 + (noise(i * 0.061, t0 * 1.7) - 0.5) * 58;
      const xB = converge1 + (noise(i * 0.061, t1 * 1.7) - 0.5) * 58;
      const a = map(t0, 0, 1, 0.003, 0.075) * random(0.45, 1.2);
      stroke(hue, sat, bri, a);
      line(xA, yy0, xB, yy1);
    }
  }
}

function paintThreshold(W, cx, lineY) {
  noFill();

  for (let i = 0; i < 225; i++) {
    const base = lineY + random(-36, 36);
    const amp = random(3, 42);
    const off = random(1000);
    const core = i < 20;
    const hue = random() < 0.85 ? 46 + random(-10, 12) : 212 + random(-14, 20);
    const sat = hue > 100 ? 10 : 7;
    const bri = hue > 100 ? 68 : 88;
    const a = core ? random(0.03, 0.08) : random(0.004, 0.032);
    stroke(hue, sat, bri, a);
    strokeWeight(core ? random(0.65, 1.5) : random(0.3, 1.75));
    beginShape();
    for (let x = -80; x <= W + 80; x += 36) {
      const n = noise(x * 0.00065 + off, i * 0.052);
      const d = abs(x - cx) / (W * 0.5);
      const sag = (1 - d) * (1 - d) * 26 * noise(x * 0.0011 + off + 40);
      vertex(x, base + (n - 0.5) * amp * 2 + sag);
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 210; i++) {
    const x = random(W);
    const y = lineY + random(-64, 74);
    const hue = random() < 0.8 ? 47 : 214;
    const sat = random(4, 10);
    const bri = random(62, 92);
    fill(hue, sat, bri, random(0.002, 0.016));
    ellipse(x, y, random(40, 380), random(3, 24));
  }
}

function paintBelow(W, H, lineY) {
  noStroke();

  for (let y = lineY; y < H; y += 3) {
    const t = (y - lineY) / (H - lineY);
    fill(238, 50, 3, t * 0.30);
    rect(0, y, W, 4);
  }

  for (let i = 0; i < 480; i++) {
    const x = random(W);
    const y = lineY + random(4, 430);
    const len = random(5, 125);
    const a = map(y, lineY, lineY + 430, 0.032, 0.002) * random(0.25, 1.0);
    const hue = random() < 0.8 ? 46 : 218;
    stroke(hue, 8, 76, a);
    strokeWeight(random(0.25, 1.15));
    line(x, y, x + random(-4, 4), y + len);
  }

  noStroke();
  for (let y = lineY + 300; y < H; y += 4) {
    const t = (y - (lineY + 300)) / (H - (lineY + 300));
    fill(240, 60, 2, t * 0.46);
    rect(0, y, W, 5);
  }
}

function paintParticles(cx, lineY, W, voidY) {
  push();
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 4300; i++) {
    const t = pow(random(), 1.35);
    const y = lerp(-80, lineY + 95, t);
    let spread = map(y, -80, lineY, W * 0.58, W * 0.07);
    spread = max(spread, W * 0.045);
    const x = cx + random(-1, 1) * spread + (noise(i * 0.011, y * 0.001) - 0.5) * 140;

    const dVoid = dist(x, y, cx, voidY);
    const voidFade = constrain(map(dVoid, 120, 540, 0.0, 1.0), 0, 1);
    let a = map(y, -80, lineY, 0.008, 0.135);
    a *= voidFade * random(0.22, 1.2);
    if (a <= 0.001) continue;

    const warm = random() < 0.075;
    const hue = warm ? 39 + random(-8, 10) : 219 + random(-26, 36);
    const sat = warm ? random(18, 30) : random(5, 24);
    const bri = random(58, 97);
    fill(hue, sat, bri, a);

    let s = random(0.55, 2.2);
    if (random() < 0.028) s = random(2.2, 4.4);
    ellipse(x, y, s, s);
  }

  blendMode(BLEND);

  for (let i = 0; i < 820; i++) {
    const x = random(W);
    const y = lineY + random(16, 640);
    const a = map(y, lineY, lineY + 640, 0.04, 0.003) * random(0.2, 1.0);
    fill(46, 7, 84, a);
    ellipse(x, y, random(0.4, 1.7), random(0.4, 1.7));
  }

  pop();
}

function paintGrain(W, H) {
  noStroke();
  for (let i = 0; i < 8200; i++) {
    const x = random(W);
    const y = random(H);
    if (random() < 0.68) {
      fill(242, 65, 2, random(0.004, 0.034));
    } else {
      fill(48, 8, 90, random(0.002, 0.02));
    }
    rect(x, y, random(0.4, 1.5), random(0.4, 1.5));
  }
}

function vignette(W, H, cx) {
  const ctx = drawingContext;

  const radial = ctx.createRadialGradient(
    cx, H * 0.43, H * 0.15,
    cx, H * 0.48, H * 0.86
  );
  radial.addColorStop(0, 'rgba(0,0,0,0)');
  radial.addColorStop(0.60, 'rgba(2,3,8,0.18)');
  radial.addColorStop(1, 'rgba(1,2,5,0.72)');
  ctx.fillStyle = radial;
  ctx.fillRect(0, 0, W, H);

  const vertical = ctx.createLinearGradient(0, 0, 0, H);
  vertical.addColorStop(0, 'rgba(1,2,6,0.48)');
  vertical.addColorStop(0.16, 'rgba(1,2,6,0)');
  vertical.addColorStop(0.82, 'rgba(0,0,0,0)');
  vertical.addColorStop(1, 'rgba(0,0,0,0.68)');
  ctx.fillStyle = vertical;
  ctx.fillRect(0, 0, W, H);
}

// 万物垂落之处 —— 死亡本身
const W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  strokeCap(ROUND);
  colorMode(RGB, 255);

  paintBackground();
  paintWeave();
  const threads = buildThreads();
  paintThreadGlows(threads);
  paintThreadCores(threads);
  paintFray(threads);
  paintDispersal(threads);
  paintAmbientDust();
  paintGrain();
  paintVignette();
}

function smooth01(t) { t = constrain(t, 0, 1); return t * t * (3 - 2 * t); }

function pickWarm() {
  const p = [[232,178,110],[218,142,92],[226,120,96],[236,196,140],[204,102,84],[228,162,118]];
  return p[floor(random(p.length))];
}

function paintBackground() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.00, '#181014');
  g.addColorStop(0.14, '#120d13');
  g.addColorStop(0.45, '#0a090f');
  g.addColorStop(0.78, '#060609');
  g.addColorStop(1.00, '#040407');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  const halo = ctx.createRadialGradient(W/2, -H*0.18, 40, W/2, -H*0.18, H*0.55);
  halo.addColorStop(0.00, 'rgba(216,150,86,0.18)');
  halo.addColorStop(0.55, 'rgba(150,84,64,0.07)');
  halo.addColorStop(1.00, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, W, H);

  noStroke();
  for (let i = 0; i < 3800; i++) {
    const x = random(W), y = random(H);
    const n = noise(x * 0.0022, y * 0.0022);
    if (n > 0.58) { fill(198, 188, 176, random(2, 5)); rect(x, y, random(1, 3), random(1, 3)); }
    else if (n < 0.40) { fill(2, 2, 8, random(3, 7)); rect(x, y, random(2, 5), random(2, 5)); }
  }
}

function paintWeave() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 0, 300);
  g.addColorStop(0.00, 'rgba(228,170,100,0.20)');
  g.addColorStop(0.55, 'rgba(178,108,80,0.08)');
  g.addColorStop(1.00, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, 300);

  blendMode(ADD);
  noFill();
  const palette = [[238,192,128],[216,140,96],[232,216,182],[198,112,92],[244,228,198],[180,98,88],[226,168,118]];
  for (let i = 0; i < 112; i++) {
    const yBase = 16 + i * 1.5 + random(-2, 2);
    const c = palette[i % palette.length];
    stroke(c[0], c[1], c[2], random(36, 130));
    strokeWeight(random(0.6, 2.3));
    beginShape();
    for (let x = -24; x <= W + 24; x += 14) {
      const y = yBase + sin(x * 0.006 + i * 0.73) * 2.6 + (noise(x * 0.01, i * 0.37) - 0.5) * 8;
      vertex(x, y);
    }
    endShape();
  }
  stroke(250, 232, 200, 40);
  strokeWeight(2.4);
  beginShape();
  for (let x = -24; x <= W + 24; x += 12) {
    vertex(x, 8 + sin(x * 0.004) * 3 + (noise(x * 0.012) - 0.5) * 5);
  }
  endShape();
  blendMode(BLEND);
}

function buildThreads() {
  const N = 140;
  const threads = [];
  for (let i = 0; i < N; i++) {
    const x0 = lerp(64, W - 64, (i + 0.5) / N) + random(-13, 13);
    const startY = 118 + random(-28, 42);
    const endY = lerp(H * 0.30, H * 0.86, pow(random(), 0.9));
    const w0 = random(0.9, 3.0);
    const warm = random() < 0.72 ? pickWarm() : [228, 216, 198];
    const seed = random(1000);
    const sway = random(9, 32);
    const drift = random(-1, 1);
    const pts = [];
    for (let y = startY; y <= endY; y += 4) {
      const t = (y - startY) / (endY - startY);
      const nx = (noise(seed + y * 0.004) - 0.5) * 2;
      const x = x0 + nx * sway * (0.35 + t * 0.9) + sin(y * 0.017 + seed * 3) * 1.4;
      pts.push({ x, y, t });
    }
    pts.push({ x: pts[pts.length - 1].x, y: endY, t: 1 });
    threads.push({ x0, startY, endY, w0, warm, seed, sway, drift, pts });
  }
  return threads;
}

function threadColor(th, t) {
  const bone = [208, 202, 190], ash = [124, 124, 124];
  let c;
  if (t < 0.55) {
    const k = smooth01(t / 0.55);
    c = [lerp(th.warm[0], bone[0], k), lerp(th.warm[1], bone[1], k), lerp(th.warm[2], bone[2], k)];
  } else {
    const k = smooth01((t - 0.55) / 0.45);
    c = [lerp(bone[0], ash[0], k), lerp(bone[1], ash[1], k), lerp(bone[2], ash[2], k)];
  }
  return c;
}

function paintThreadGlows(threads) {
  blendMode(ADD);
  noFill();
  for (const th of threads) {
    const c = threadColor(th, 0.3);
    stroke(c[0], c[1], c[2], 9);
    strokeWeight(th.w0 * 5 + 3);
    beginShape();
    for (const p of th.pts) vertex(p.x, p.y);
    endShape();
    stroke(c[0], c[1], c[2], 6);
    strokeWeight(th.w0 * 9 + 6);
    beginShape();
    for (let i = 0; i < th.pts.length; i += 3) vertex(th.pts[i].x, th.pts[i].y);
    endShape();
  }
  blendMode(BLEND);
}

function paintThreadCores(threads) {
  blendMode(ADD);
  for (const th of threads) {
    const pts = th.pts;
    for (let i = 1; i < pts.length; i++) {
      const p0 = pts[i - 1], p1 = pts[i];
      const t = p1.t;
      const fadeIn = smooth01(t / 0.06);
      const fadeOut = 1 - smooth01((t - 0.86) / 0.14);
      const a = 230 * fadeIn * fadeOut;
      if (a < 2) continue;
      const c = threadColor(th, t);
      stroke(c[0], c[1], c[2], a);
      strokeWeight(lerp(th.w0, th.w0 * 0.30, t));
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
  blendMode(BLEND);
}

function paintFray(threads) {
  blendMode(ADD);
  for (const th of threads) {
    const pts = th.pts;
    const nB = floor(random(2, 6));
    for (let b = 0; b < nB; b++) {
      const idx = floor(random(pts.length * 0.78, pts.length - 1));
      const p = pts[idx];
      const dir = (random() < 0.5 ? -1 : 1) * random(0.35, 1.0) + th.drift * 0.3;
      const L = random(16, 64);
      const steps = floor(L / 4);
      const c = threadColor(th, p.t);
      let x = p.x, y = p.y;
      for (let s = 0; s < steps; s++) {
        const k = s / steps;
        const nx = x + dir * 3 + (noise(x * 0.05, y * 0.05) - 0.5) * 3;
        const ny = y + 4 + (noise(y * 0.05 + 40, x * 0.05) - 0.5) * 2;
        stroke(c[0], c[1], c[2], (1 - k) * 90 * (1 - p.t * 0.4));
        strokeWeight(lerp(0.9, 0.25, k));
        line(x, y, nx, ny);
        x = nx; y = ny;
      }
    }
  }
  blendMode(BLEND);
}

function paintDispersal(threads) {
  blendMode(ADD);
  noStroke();
  for (const th of threads) {
    const xe = th.pts[th.pts.length - 1].x;
    const nH = floor(random(2, 5));
    for (let h = 0; h < nH; h++) {
      const r = random(18, 70);
      fill(190, 180, 168, random(2.5, 6));
      ellipse(xe + random(-24, 24), th.endY + random(-10, 80), r * 2, r * 2 * random(1.1, 1.7));
    }
    const n = floor(map(th.w0, 0.9, 3, 26, 64));
    for (let j = 0; j < n; j++) {
      let T = random(30, 240) * (0.5 + th.w0 * 0.25);
      const maxT = H * 0.965 - th.endY;
      if (T > maxT) T = maxT;
      if (T < 8) continue;
      const K = floor(random(4, 8));
      const drift = th.drift * random(0.3, 1.2) + random(-0.4, 0.4);
      const px0 = xe + random(-5, 5);
      const size0 = random(0.8, 2.3);
      const warm = random() < 0.3;
      const c = warm ? [216, 196, 170] : [186, 188, 190];
      for (let k = 0; k < K; k++) {
        const u = (k + 1) / K;
        const y = th.endY + T * pow(u, 1.15) + random(-2, 2);
        const x = px0 + drift * T * u + (noise(px0 * 0.02, u * 3 + th.seed) - 0.5) * 34 * u;
        const a = (1 - u) * random(28, 95);
        const s = size0 * (1 - u * 0.75);
        fill(c[0], c[1], c[2], a);
        ellipse(x, y, s * 2.2, s * 2.2);
      }
    }
  }
  blendMode(BLEND);
}

function paintAmbientDust() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 800; i++) {
    const x = random(W);
    const y = random(H * 0.25, H);
    const d = noise(x * 0.001, y * 0.001);
    if (d < 0.42) continue;
    const a = random(2, 8) * map(y, H * 0.25, H, 1, 0.5);
    fill(180, 186, 196, a);
    const s = random(0.6, 1.8);
    ellipse(x, y, s, s);
  }
  blendMode(BLEND);
}

function paintGrain() {
  noStroke();
  for (let i = 0; i < 20000; i++) {
    const x = random(W), y = random(H);
    const g = random(255);
    if (g > 128) fill(g, g, g, random(1.5, 5));
    else fill(0, 0, 4, random(2, 6));
    rect(x, y, 1, 1);
  }
  for (let i = 0; i < 1500; i++) {
    const x = random(W), y = random(H);
    fill(random(255) > 128 ? color(210, 205, 195, random(2, 4)) : color(0, 0, 6, random(2, 5)));
    rect(x, y, 2, 2);
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(W * 0.5, H * 0.42, H * 0.30, W * 0.5, H * 0.46, H * 1.05);
  g.addColorStop(0.0, 'rgba(2,2,4,0)');
  g.addColorStop(0.7, 'rgba(2,2,4,0.10)');
  g.addColorStop(1.0, 'rgba(1,1,3,0.52)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

let W = 1600;
let H = 2000;
let GATE_X = 800;
let GATE_Y = 880;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  colorMode(RGB, 255);
  noLoop();
  paint();
}

function paint() {
  baseGradient();
  washes();
  halo();
  rift();
  thread();
  wanderers();
  streams();
  ash();
  vignette();
  grain();
}

function baseGradient() {
  let ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.0, '#020107');
  g.addColorStop(0.32, '#060411');
  g.addColorStop(0.60, '#0a0614');
  g.addColorStop(0.83, '#130b15');
  g.addColorStop(1.0, '#1b1217');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function washes() {
  push();
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 55; i++) {
    let x = random(W);
    let y = random(H * 0.45, H);
    let warm = x < W * 0.5 + random(-120, 120);
    if (warm) {
      fill(126, 54, 32, random(2, 7));
    } else {
      fill(46, 58, 90, random(2, 6));
    }
    ellipse(x, y, random(180, 760), random(60, 240));
  }

  for (let i = 0; i < 36; i++) {
    let x = random(W);
    let y = random(0, H * 0.52);
    fill(54, 74, 118, random(2, 5));
    ellipse(x, y, random(220, 880), random(70, 260));
  }

  pop();
}

function radialGradient(x, y, r, stops, mode) {
  push();
  if (mode !== undefined) blendMode(mode);
  noStroke();

  let ctx = drawingContext;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (let i = 0; i < stops.length; i++) {
    g.addColorStop(stops[i][0], stops[i][1]);
  }

  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(x, y, r, 0, TWO_PI);
  ctx.fill();
  pop();
}

function halo() {
  radialGradient(GATE_X, GATE_Y, 950, [
    [0, 'rgba(220,228,255,0.16)'],
    [0.20, 'rgba(160,176,225,0.09)'],
    [0.55, 'rgba(84,94,138,0.035)'],
    [1, 'rgba(0,0,0,0)']
  ], ADD);

  radialGradient(GATE_X, H * 0.90, 880, [
    [0, 'rgba(132,52,26,0.12)'],
    [1, 'rgba(0,0,0,0)']
  ], ADD);

  radialGradient(GATE_X, H * 0.18, 620, [
    [0, 'rgba(90,110,160,0.08)'],
    [1, 'rgba(0,0,0,0)']
  ], ADD);
}

function rift() {
  push();
  blendMode(ADD);
  noStroke();

  slit(GATE_X, 225, 1625, 92, 112, 128, 172, 5.5, 11.7);
  slit(GATE_X, 245, 1605, 55, 165, 178, 214, 8.5, 29.3);
  slit(GATE_X, 265, 1585, 28, 221, 228, 246, 14, 43.1);
  slit(GATE_X, 280, 1570, 11, 249, 250, 255, 26, 57.9);

  blendMode(BLEND);
  slit(GATE_X, 300, 1555, 3.2, 2, 2, 7, 65, 71.4);

  blendMode(ADD);
  for (let i = 0; i < 620; i++) {
    let t = random();
    let y = lerp(250, 1605, t);
    let envelope = pow(sin(t * PI), 0.9);
    let spread = 8 + envelope * 86;
    let x = GATE_X + random(-1, 1) * spread;
    let a = random(4, 24) * (0.35 + envelope);
    let sz = random(0.7, 2.5);

    fill(228, 234, 252, a);
    ellipse(x, y, sz, sz);

    if (random() < 0.05) {
      fill(255, 255, 255, a * 0.22);
      ellipse(x, y, sz * 4, sz * 4);
    }
  }

  pop();
}

function slit(x, top, bottom, baseW, r, g, b, a, seedOff) {
  fill(r, g, b, a);
  beginShape();

  for (let y = top; y <= bottom; y += 10) {
    let t = (y - top) / (bottom - top);
    let envelope = pow(sin(t * PI), 0.85);
    let n = noise(seedOff + y * 0.0058);
    let hw = baseW * (0.12 + envelope) * (0.45 + n * 1.25);
    vertex(x - hw, y);
  }

  for (let y = bottom; y >= top; y -= 10) {
    let t = (y - top) / (bottom - top);
    let envelope = pow(sin(t * PI), 0.85);
    let n = noise(seedOff + 97.31 + y * 0.0058);
    let hw = baseW * (0.12 + envelope) * (0.45 + n * 1.25);
    vertex(x + hw, y);
  }

  endShape(CLOSE);
}

function thread() {
  push();
  noFill();
  strokeCap(ROUND);

  for (let pass = 0; pass < 3; pass++) {
    let wgt = pass === 0 ? 6.5 : pass === 1 ? 2.6 : 1.05;
    let alph = pass === 0 ? 16 : pass === 1 ? 34 : 68;
    stroke(142, 18, 22, alph);
    strokeWeight(wgt);

    let prev = leftThreadPoint(0);
    for (let i = 1; i <= 120; i++) {
      let t = i / 120;
      let p = leftThreadPoint(t);
      if (noise(13.1 + i * 0.11) > 0.13) {
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;
    }
  }

  for (let pass = 0; pass < 2; pass++) {
    let wgt = pass === 0 ? 3.5 : 1.0;
    let alph = pass === 0 ? 15 : 42;
    stroke(150, 22, 26, alph);
    strokeWeight(wgt);

    let prev = rightThreadPoint(0);
    for (let i = 1; i <= 100; i++) {
      let t = i / 100;
      let p = rightThreadPoint(t);
      let keep = noise(87.7 + i * 0.17) > (0.35 + t * 0.28);
      if (keep) {
        line(prev.x, prev.y, p.x, p.y);
      }
      prev = p;
    }
  }

  noStroke();
  blendMode(ADD);
  fill(255, 78, 28, 10);
  ellipse(132, 1868, 230, 230);
  fill(255, 120, 44, 30);
  ellipse(132, 1868, 52, 52);
  fill(255, 216, 170, 60);
  ellipse(132, 1868, 12, 12);

  pop();
}

function leftThreadPoint(t) {
  let x = lerp(135, GATE_X - 52, pow(t, 1.13));
  let y = lerp(1870, GATE_Y + 46, pow(t, 1.62));
  x += (noise(83.21 + t * 6.8) - 0.5) * 90 * (1 - t * 0.8);
  y += (noise(27.77 + t * 5.2) - 0.5) * 230 * (1 - t * 0.62);
  return {
    x: x,
    y: y
  };
}

function rightThreadPoint(t) {
  let x = lerp(GATE_X + 58, 1495, pow(t, 1.08));
  let y = lerp(GATE_Y + 22, 1372, pow(t, 1.36));
  x += (noise(19.4 + t * 7.3) - 0.5) * 145 * t;
  y += (noise(65.1 + t * 6.1) - 0.5) * 260 * t;
  return {
    x: x,
    y: y
  };
}

function wanderers() {
  push();
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 26; i++) {
    let x = GATE_X + random(-1, 1) * (70 + random(460));
    let y = lerp(H * 0.95, H * 0.26, pow(random(), 1.35));
    let d = abs(x - GATE_X);
    let closeness = 1 - constrain(d / 680, 0, 1);
    let sz = random(6, 36) * (0.45 + closeness);
    let a = random(3, 10) + closeness * 14;

    fill(212, 224, 248, a);
    ellipse(x, y, sz, sz);

    fill(255, 255, 255, a * 0.6);
    ellipse(x, y, sz * 0.28, sz * 0.28);

    if (random() < 0.35) {
      fill(255, 130, 50, a * 0.35);
      ellipse(x + random(-20, 20), y + random(-20, 20), sz * 0.7, sz * 0.7);
    }
  }

  pop();
}

function streams() {
  push();
  blendMode(ADD);
  noStroke();

  let warm = [255, 106, 34];
  let pale = [229, 234, 250];
  let ash = [106, 110, 128];
  let count = 650;

  for (let i = 0; i < count; i++) {
    let x = random(30, W - 30);
    let y = random(H * 0.50, H + 60);
    let steps = floor(random(36, 78));
    let stepLen = random(7, 15);
    let sizeBase = random(0.75, 2.5);
    let personal = random(1000);

    for (let s = 0; s < steps; s++) {
      let dx = GATE_X - x;
      let dy = GATE_Y - y;
      let d = max(1, sqrt(dx * dx + dy * dy));

      let n1 = noise(x * 0.0015 + personal, y * 0.0015) * 2 - 1;
      let n2 = noise(x * 0.0015 + 51.7, y * 0.0015 + personal * 0.01) * 2 - 1;

      let pull = map(constrain(d, 0, 1350), 0, 1350, 0.17, 0.45);

      x += (dx / d) * pull * stepLen + n1 * 7.5;
      y += (dy / d) * pull * stepLen + n2 * 7.5 - 0.65;

      if (d < 24) break;

      if (s % 2 === 0) {
        let closeness = 1 - constrain(d / 1350, 0, 1);
        let fade = s / steps;
        let a = (2 + closeness * 28) * (1 - fade * 0.55) * random(0.35, 1.0);

        let rr, gg, bb;
        if (closeness < 0.46) {
          let u = closeness / 0.46;
          rr = lerp(warm[0], pale[0], u);
          gg = lerp(warm[1], pale[1], u);
          bb = lerp(warm[2], pale[2], u);
        } else {
          let u = (closeness - 0.46) / 0.54;
          rr = lerp(pale[0], ash[0], u);
          gg = lerp(pale[1], ash[1], u);
          bb = lerp(pale[2], ash[2], u);
        }

        fill(rr, gg, bb, a);
        let sz = sizeBase * (0.6 + closeness * 2.2) * random(0.7, 1.35);
        ellipse(x, y, sz, sz);

        if (closeness > 0.72 && random() < 0.10) {
          fill(250, 251, 255, a * 0.30);
          ellipse(x, y, sz * 3.5, sz * 3.5);
        }
      }
    }
  }

  pop();
}

function ash() {
  push();
  blendMode(BLEND);
  noStroke();

  for (let i = 0; i < 3200; i++) {
    let x = GATE_X + randomGaussian(0, 240);
    let y = random(230, 1880);
    let d = abs(x - GATE_X);
    let p = map(d, 0, 850, 0.95, 0.12);

    if (random() < p) {
      let g = random(110, 205);
      let warmShift = random(-16, 18);
      let a = random(4, 26) * map(d, 0, 850, 1, 0.35);

      fill(g + warmShift, g + warmShift * 0.55, g, a);
      let sz = random(0.6, 2.4);
      ellipse(x, y, sz, sz);
    }
  }

  for (let i = 0; i < 1600; i++) {
    let x = random(W);
    let y = random(H * 0.2, H);
    fill(18, 18, 26, random(3, 12));
    rect(x, y, random(0.7, 2.0), random(0.7, 2.0));
  }

  pop();
}

function vignette() {
  push();
  blendMode(BLEND);

  radialGradient(GATE_X, H * 0.47, 1500, [
    [0, 'rgba(0,0,0,0)'],
    [0.62, 'rgba(0,0,0,0)'],
    [1, 'rgba(0,0,0,0.62)']
  ], BLEND);

  let ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, 'rgba(0,0,0,0.58)');
  g.addColorStop(0.16, 'rgba(0,0,0,0)');
  g.addColorStop(0.82, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.64)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  pop();
}

function grain() {
  push();
  blendMode(BLEND);
  noStroke();

  for (let i = 0; i < 17000; i++) {
    let x = random(W);
    let y = random(H);
    let n = noise(x * 0.012, y * 0.012);
    let a = random(2, 15);

    if (n > 0.58) {
      fill(235, 238, 250, a * 0.55);
    } else if (n < 0.28) {
      fill(0, 0, 0, a * 1.45);
    } else {
      fill(160, 168, 190, a * 0.4);
    }

    rect(x, y, random(0.5, 1.7), random(0.5, 1.7));
  }

  pop();
}

const CX = 720;
const CY = 980;
const RING_R = 520;
const A0 = 0.62;
const A1 = Math.PI * 2 - 0.62;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  background(5, 7, 10);
  paintGround();
  paintQuietCenter();
  paintBoundary();
  paintRelease();
  paintDust();
  paintSurface();
}

function ringPoint(a, r) {
  const wobble =
    8 * Math.sin(3 * a + 0.4) +
    4 * Math.sin(7 * a - 0.8) +
    (noise(Math.cos(a) * 1.7 + 3.1, Math.sin(a) * 1.7 + 7.2) - 0.5) * 14;

  return {
    x: CX + (r + wobble) * Math.cos(a),
    y: CY + (r + wobble) * 1.015 * Math.sin(a)
  };
}

function paintGround() {
  const ctx = drawingContext;
  ctx.save();

  let ground = ctx.createRadialGradient(690, 900, 40, 760, 960, 1300);
  ground.addColorStop(0, "#151b20");
  ground.addColorStop(0.35, "#0d1319");
  ground.addColorStop(0.72, "#080c11");
  ground.addColorStop(1, "#040609");
  ctx.fillStyle = ground;
  ctx.fillRect(0, 0, width, height);

  let halo = ctx.createRadialGradient(CX, CY, 280, CX, CY, 770);
  halo.addColorStop(0, "rgba(0,0,0,0)");
  halo.addColorStop(0.62, "rgba(117,127,124,0.025)");
  halo.addColorStop(0.82, "rgba(155,144,119,0.035)");
  halo.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  for (let i = 0; i < 6500; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.002, y * 0.002);
    if (random() > 0.45 + n * 0.35) continue;
    stroke(145, 157, 160, random(2, 9));
    strokeWeight(random(0.35, 1.05));
    point(x, y);
  }
}

function paintQuietCenter() {
  const ctx = drawingContext;
  ctx.save();
  const quiet = ctx.createRadialGradient(CX, CY, 30, CX, CY, 455);
  quiet.addColorStop(0, "rgba(2,4,7,0.58)");
  quiet.addColorStop(0.68, "rgba(3,5,8,0.32)");
  quiet.addColorStop(1, "rgba(3,5,8,0)");
  ctx.fillStyle = quiet;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

function paintBoundary() {
  noFill();

  for (let i = 0; i < 520; i++) {
    const baseR = RING_R + randomGaussian() * 23 + random(-12, 12);
    const start = A0 + random(-0.02, 0.035);
    const loss = Math.pow(random(), 3) * 0.48;
    const end = A1 - loss;
    const phase = random(TWO_PI);
    const localNoise = random(80);
    const choice = random();

    if (choice < 0.76) {
      stroke(184, 193, 190, random(7, 25));
    } else if (choice < 0.91) {
      stroke(211, 192, 156, random(7, 24));
    } else {
      stroke(118, 148, 158, random(6, 20));
    }

    strokeWeight(random(0.45, 1.35));
    beginShape();

    const steps = 180;
    for (let j = 0; j <= steps; j++) {
      const a = lerp(start, end, j / steps);
      const tremor =
        (noise(a * 1.9 + localNoise, i * 0.013) - 0.5) * 10 +
        2.2 * Math.sin(a * 11 + phase);
      const p = ringPoint(a, baseR + tremor);
      vertex(p.x, p.y);
    }
    endShape();
  }

  for (let i = 0; i < 2300; i++) {
    const q = random();
    const a = lerp(A0, A1, q);

    if (q > 0.86 && random() < map(q, 0.86, 1, 0, 0.8)) {
      continue;
    }

    const r = RING_R + randomGaussian() * 36;
    const len = random(0.008, 0.06) * (random() < 0.08 ? 2.2 : 1);
    const warm = random() < 0.24;

    if (warm) {
      stroke(220, 198, 158, random(14, 62));
    } else {
      stroke(199, 205, 197, random(12, 68));
    }

    strokeWeight(random(0.45, 1.45));
    beginShape();
    for (let j = 0; j <= 5; j++) {
      const aa = a + len * (j / 5 - 0.5);
      const p = ringPoint(aa, r + Math.sin(j * 1.7 + i) * 1.8);
      vertex(p.x, p.y);
    }
    endShape();
  }

  for (let i = 0; i < 28; i++) {
    const centerA = random(A0 + 0.35, A1 - 0.5);
    const arcLength = random(0.08, 0.45);
    const r = RING_R + random(-40, 40);
    stroke(224, 216, 190, random(18, 48));
    strokeWeight(random(0.8, 1.8));
    beginShape();

    for (let j = 0; j <= 50; j++) {
      const a = centerA + arcLength * (j / 50 - 0.5);
      const p = ringPoint(a, r + Math.sin(a * 13 + i) * 2);
      vertex(p.x, p.y);
    }
    endShape();
  }
}

function cubicPoint(p0, p1, p2, p3, t) {
  const u = 1 - t;
  return {
    x:
      u * u * u * p0.x +
      3 * u * u * t * p1.x +
      3 * u * t * t * p2.x +
      t * t * t * p3.x,
    y:
      u * u * u * p0.y +
      3 * u * u * t * p1.y +
      3 * u * t * t * p2.y +
      t * t * t * p3.y
  };
}

function paintRelease() {
  const ctx = drawingContext;
  ctx.save();
  const haze = ctx.createRadialGradient(1190, 930, 10, 1190, 930, 510);
  haze.addColorStop(0, "rgba(174,157,126,0.035)");
  haze.addColorStop(0.5, "rgba(133,146,147,0.018)");
  haze.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = haze;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  for (let i = 0; i < 320; i++) {
    const upper = random() < 0.76;
    const a = upper
      ? A1 - Math.pow(random(), 2) * 0.72
      : A0 + Math.pow(random(), 2) * 0.35;

    const p0 = ringPoint(a, RING_R + randomGaussian() * 28);
    const tx = upper ? -Math.sin(a) : Math.sin(a);
    const ty = upper ? Math.cos(a) : -Math.cos(a);
    const len = 60 + Math.pow(random(), 1.7) * 560;
    const side = upper ? -1 : 1;
    const driftY =
      (noise(i * 0.19, 4.2) - 0.5) * len * 0.9 +
      side * len * random(-0.08, 0.18);

    const p1 = {
      x: p0.x + tx * len * 0.22,
      y: p0.y + ty * len * 0.22
    };
    const p2 = {
      x: p0.x + len * 0.55,
      y: p0.y + driftY * 0.7 + (noise(i * 0.11, 9.1) - 0.5) * 90
    };
    const p3 = {
      x: p0.x + len * random(0.7, 1.08),
      y: p0.y + driftY
    };

    const palette = random();
    let cr;
    let cg;
    let cb;

    if (palette < 0.65) {
      cr = 193;
      cg = 199;
      cb = 190;
    } else if (palette < 0.9) {
      cr = 218;
      cg = 190;
      cb = 145;
    } else {
      cr = 125;
      cg = 153;
      cb = 161;
    }

    const baseAlpha =
      random(12, 46) * map(len, 60, 620, 1, 0.45, true);
    const weight = random(0.45, 1.35);
    const segments = 56;

    for (let j = 0; j < segments; j++) {
      const t0 = j / segments;
      const t1 = (j + 1) / segments;
      const q0 = cubicPoint(p0, p1, p2, p3, t0);
      const q1 = cubicPoint(p0, p1, p2, p3, t1);
      const fade = Math.pow(1 - t0, 1.55);

      stroke(cr, cg, cb, baseAlpha * fade);
      strokeWeight(Math.max(0.22, weight * (1 - t0 * 0.78)));
      line(q0.x, q0.y, q1.x, q1.y);
    }
  }
}

function paintDust() {
  for (let i = 0; i < 8000; i++) {
    const upper = random() < 0.72;
    const a = upper
      ? A1 - Math.pow(random(), 2) * 0.85
      : A0 + Math.pow(random(), 2) * 0.45;

    const p = ringPoint(a, RING_R + randomGaussian() * 42);
    const d = Math.pow(random(), 2.2) * 560;
    const fade = Math.pow(Math.max(0, 1 - d / 590), 1.8);
    if (fade <= 0) continue;

    const x = p.x + d * (0.65 + random() * 0.55);
    const y =
      p.y +
      (noise(i * 0.043, 2.7) - 0.5) * d * 1.5 +
      (upper ? -1 : 1) * d * random(-0.1, 0.18);

    const alpha = random(6, 60) * fade;
    const size = random(0.5, 2.2) * (random() < 0.035 ? 1.7 : 1);
    const warm = random() < 0.3;

    if (random() < 0.1 && d > 20) {
      if (warm) {
        stroke(220, 192, 148, alpha);
      } else {
        stroke(184, 198, 195, alpha);
      }
      strokeWeight(Math.max(0.25, size * 0.55));
      line(x, y, x + random(1, 5), y + random(-1, 1));
    } else {
      noStroke();
      if (warm) {
        fill(220, 192, 148, alpha);
      } else {
        fill(184, 198, 195, alpha);
      }
      circle(x, y, size);
    }
  }
}

function paintSurface() {
  const ctx = drawingContext;
