const CX = 780;
const BASE_Y = 1640;
const FORM_H = 1290;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();

  paintGround();
  paintField();
  paintShadow();
  paintBody();
  paintReleasedThreads();
  paintFragments();
}

function paintGround() {
  const ctx = drawingContext;

  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, "#d7d8cf");
  g.addColorStop(0.43, "#e8e0cf");
  g.addColorStop(1, "#c4b8a3");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  g = ctx.createRadialGradient(740, 850, 40, 740, 850, 1280);
  g.addColorStop(0, "rgba(255,249,229,0.62)");
  g.addColorStop(0.5, "rgba(244,235,214,0.12)");
  g.addColorStop(1, "rgba(48,50,46,0.20)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 23000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.58) {
      stroke(54, 56, 50, random(2, 8));
    } else {
      stroke(255, 251, 237, random(3, 12));
    }
    strokeWeight(random(0.35, 1.05));
    point(x, y);
  }

  for (let i = 0; i < 1100; i++) {
    const x = random(width);
    const y = random(height);
    const len = random(4, 42);
    stroke(74, 70, 59, random(2, 6));
    strokeWeight(random(0.3, 0.65));
    line(x, y, x + len, y + random(-1.2, 1.2));
  }
}

function paintField() {
  noFill();
  for (let i = 0; i < 44; i++) {
    const y0 = 65 + i * 45 + random(-11, 11);
    stroke(62, 68, 63, random(4.5, 8));
    strokeWeight(random(0.45, 0.8));
    beginShape();
    for (let x = -40; x <= width + 40; x += 28) {
      const d = (x - CX) / 520;
      const bend = 18 * Math.exp(-d * d) * sin((y0 - 930) * 0.004);
      const y = y0 + 7 * sin(x * 0.0023 + i * 0.71) + bend;
      vertex(x, y);
    }
    endShape();
  }
}

function paintShadow() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    const k = i / 60;
    fill(48, 44, 36, 0.55);
    ellipse(CX, 1688, 440 * (1 - k) + 30, 32 * (1 - k) + 4);
  }
}

function profileWidth(t) {
  if (t <= 0) return 0;
  if (t >= 1) return 198 + (t - 1) * 520;
  return 365 * pow(sin(PI * 0.84 * t), 0.82);
}

function strandPoint(u, t, phase) {
  const w = profileWidth(t);
  const release = max(0, t - 0.62);

  let x = CX + u * w;
  x += sin(phase + t * 6.2) * (3 + 23 * t);
  x += (noise(u * 2.7 + 4.1, t * 2.1 + phase * 0.03) - 0.5) * 34 * t;
  x += sin(phase * 0.7 + t * 3.3) * 240 * pow(release, 1.4);
  x += u * 180 * pow(max(0, t - 0.82), 1.2);

  const y = BASE_Y - FORM_H * t + sin(phase + t * 5) * 12 * t;
  return { x, y };
}

function chooseInk() {
  const r = random();
  if (r < 0.53) return [32, 41, 40];
  if (r < 0.75) return [63, 55, 43];
  if (r < 0.91) return [105, 82, 49];
  return [145, 124, 85];
}

function paintBody() {
  for (let i = 0; i < 560; i++) {
    const u = random(-1, 1);
    const phase = random(TWO_PI);
    let endT = random(0.68, 1.07);
    if (random() < 0.16) endT = random(1.04, 1.17);

    const c = chooseInk();
    let baseAlpha = random(18, 46);
    if (i % 19 === 0) baseAlpha = random(45, 62);

    const weight = random(0.45, 1.2) * (i % 37 === 0 ? 1.55 : 1);
    const steps = 100;

    for (let j = 0; j < steps; j++) {
      const t0 = endT * j / steps;
      const t1 = endT * (j + 1) / steps;

      if (t0 > endT - 0.2 && noise(i * 0.37, j * 0.21) < 0.22) {
        continue;
      }

      const p0 = strandPoint(u, t0, phase);
      const p1 = strandPoint(u, t1, phase);
      const localFade = 1 - soften(max(0.5, endT - 0.32), endT, t0);
      const highFade = 1 - 0.62 * soften(0.73, 1.17, t0);
      const a = baseAlpha * localFade * highFade;

      if (a < 0.45) continue;

      stroke(c[0], c[1], c[2], a);
      strokeWeight(weight * (1 - 0.58 * soften(0.65, 1.17, t0)));
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
}

function paintReleasedThreads() {
  for (let i = 0; i < 175; i++) {
    const t = random(0.65, 1.03);
    const u = random(-1, 1);
    const phase = random(TWO_PI);
    const p = strandPoint(u, t, phase);
    const c = chooseInk();

    const reach = random(80, 370);
    const side = random() < 0.5 ? -1 : 1;
    const ex = p.x + u * random(40, 240) + side * random(-70, 190)
      + randomGaussian() * 35;
    const ey = p.y - reach + random(-35, 80);

    const c1x = p.x + sin(phase) * random(20, 70);
    const c1y = p.y - random(30, 110);
    const c2x = ex + random(-120, 120);
    const c2y = ey + random(50, 190);

    const baseAlpha = random(9, 27);
    const weight = random(0.35, 0.9);
    const steps = 44;

    for (let j = 0; j < steps; j++) {
      const q0 = j / steps;
      const q1 = (j + 1) / steps;

      if (q0 > 0.55 && noise(i * 0.41, j * 0.29) < 0.18) continue;

      const a0 = cubic(p.x, c1x, c2x, ex, q0);
      const b0 = cubic(p.y, c1y, c2y, ey, q0);
      const a1 = cubic(p.x, c1x, c2x, ex, q1);
      const b1 = cubic(p.y, c1y, c2y, ey, q1);

      const fadeIn = soften(0, 0.12, q0);
      const alpha = baseAlpha * fadeIn * pow(1 - q0, 1.35);
      stroke(c[0], c[1], c[2], alpha);
      strokeWeight(weight * (1 - 0.45 * q0));
      line(a0, b0, a1, b1);
    }
  }
}

function paintFragments() {
  noStroke();

  for (let i = 0; i < 4400; i++) {
    const t = 0.53 + pow(random(), 0.82) * 0.77;
    const u = random(-1, 1);
    const opening = soften(0.55, 1.28, t);
    const spread = 22 + 185 * opening;

    let x = CX + u * profileWidth(t) + randomGaussian() * spread * 0.46;
    x += 55 * sin(t * 9 + u * 4) * soften(0.65, 1.1, t);

    const y = BASE_Y - FORM_H * t
      + randomGaussian() * (10 + 42 * opening);

    if (x < -10 || x > width + 10 || y < -10 || y > height + 10) continue;

    const c = chooseInk();
    const alpha = (1 - soften(0.61, 1.3, t)) * random(8, 42);
    let r = random(0.45, 1.55);
    if (random() < 0.035) r = random(1.8, 3.4);

    fill(c[0], c[1], c[2], alpha);
    ellipse(x, y, r, r * random(0.7, 1.8));
  }

  for (let i = 0; i < 105; i++) {
    const t = random(0.75, 1.18);
    const u = random(-1, 1);
    const opening = soften(0.65, 1.18, t);
    const x = CX + u * profileWidth(t)
      + randomGaussian() * (35 + 100 * opening);
    const y = BASE_Y - FORM_H * t + randomGaussian() * 35;
    const c = chooseInk();
    const len = random(2, 10);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    stroke(c[0], c[1], c[2], random(8, 28));
    strokeWeight(random(0.45, 1.1));
    line(-len * 0.5, 0, len * 0.5, random(-2, 2));
    pop();
  }
}

function cubic(a, b, c, d, t) {
  const mt = 1 - t;
  return mt * mt * mt * a
    + 3 * mt * mt * t * b
    + 3 * mt * t * t * c
    + t * t * t * d;
}

function soften(a, b, x) {
  const t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const paperTop = color(238, 234, 223);
  const paperBottom = color(207, 198, 180);

  for (let y = 0; y < height; y += 4) {
    const t = pow(y / height, 1.35);
    const c = lerpColor(paperTop, paperBottom, t);
    stroke(c);
    strokeWeight(4);
    line(0, y, width, y);
  }

  for (let i = 0; i < 85000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.52) {
      stroke(255, 251, 239, random(3, 15));
    } else {
      stroke(54, 46, 37, random(2, 9));
    }
    strokeWeight(random(0.3, 1.15));
    point(x, y);
  }

  for (let i = 0; i < 1500; i++) {
    const x = random(width);
    const y = random(height);
    stroke(78, 67, 52, random(2, 7));
    strokeWeight(random(0.25, 0.65));
    line(x, y, x + random(3, 18), y + random(-1.2, 1.2));
  }

  strokeJoin(ROUND);
  strokeCap(ROUND);
  blendMode(MULTIPLY);

  const washColors = [
    [26, 42, 47],
    [50, 61, 59],
    [139, 65, 45],
    [172, 121, 62]
  ];

  for (let i = 0; i < 52; i++) {
    const sx = random(-240, 1840);
    const pts = makePath(
      sx,
      random(TWO_PI),
      random(30, 105),
      random(0.002, 0.005),
      random(-0.11, 0.11),
      random(-0.03, 0.12)
    );
    const rgb = washColors[floor(random(washColors.length))];
    const c = color(rgb[0], rgb[1], rgb[2], random(4, 11));
    strokePath(pts, c, random(28, 105));
  }

  const inks = [
    [20, 34, 40],
    [35, 48, 50],
    [57, 63, 58],
    [74, 69, 58]
  ];
  const ends = [];

  for (let i = 0; i < 1250; i++) {
    let sx;
    if (random() < 0.36) {
      sx = randomGaussian(820, 440);
    } else {
      sx = random(-170, 1770);
    }

    const pts = makePath(
      sx,
      random(TWO_PI),
      random(12, 72),
      random(0.0024, 0.0064),
      random(-0.13, 0.13),
      random(-0.045, 0.14)
    );

    const warmth = 0.05 + 0.55 * exp(-sq((sx - 830) / 430));
    const r = random();
    let rgb;

    if (r < warmth * 0.42) {
      rgb = [151, 60, 40];
    } else if (r < warmth) {
      rgb = [181, 128, 65];
    } else {
      rgb = inks[floor(random(inks.length))];
    }

    let alpha = random(25, 78);
    let weight = random(0.42, 1.18);

    if (random() < 0.085) {
      alpha = random(90, 148);
      weight = random(1.1, 1.85);
    }

    const c = color(rgb[0], rgb[1], rgb[2], alpha);
    strokePath(pts, c, weight);

    if (pts.length > 1) {
      ends.push({
        p: pts[pts.length - 1],
        rgb: rgb
      });
    }
  }

  blendMode(BLEND);

  for (let i = 0; i < 175; i++) {
    const sx = random(-120, 1720);
    const pts = makePath(
      sx,
      random(TWO_PI),
      random(18, 68),
      random(0.0025, 0.0058),
      random(-0.1, 0.1),
      random(-0.02, 0.12)
    );
    const c = color(249, 240, 213, random(22, 72));
    strokePath(pts, c, random(0.4, 0.95));
  }

  blendMode(MULTIPLY);

  for (let i = 0; i < 7; i++) {
    const sx = random(470, 1210);
    const pts = makePath(
      sx,
      random(TWO_PI),
      random(24, 55),
      random(0.0027, 0.0048),
      random(-0.07, 0.07),
      random(0.02, 0.1)
    );
    const c = color(143, 48, 32, random(105, 175));
    strokePath(pts, c, random(1.35, 2.35));
  }

  blendMode(BLEND);
  noStroke();

  for (const e of ends) {
    if (random() < 0.48) {
      fill(e.rgb[0], e.rgb[1], e.rgb[2], random(25, 82));
      circle(e.p.x, e.p.y, random(0.65, 2.15));
    }
  }

  for (let i = 0; i < 18000; i++) {
    const x = random(width);
    const y = random(height);
    stroke(245, 238, 219, random(2, 8));
    strokeWeight(random(0.3, 0.8));
    point(x, y);
  }
}

function boundary(x) {
  const arch = 770 + 0.00019 * sq(x - 800);
  return arch + 26 * (noise(x * 0.0035, 19.7) - 0.5);
}

function makePath(sx, phase, amp, freq, drift, pull) {
  const pts = [];
  let y = height + 50;

  for (let k = 0; k < 290; k++) {
    const travelled = height + 50 - y;
    const p = constrain(travelled / 1400, 0, 1);

    let x = sx + drift * travelled;
    x += sin(y * freq + phase) * amp;
    x += sin(y * freq * 0.37 + phase * 1.91) * amp * 0.65;
    x += (noise(sx * 0.0017 + 37.1, y * 0.0024 + phase * 0.07) - 0.5) * 110;
    x += (800 - sx) * pull * p * p;

    pts.push({ x: x, y: y });

    if (y <= boundary(x)) {
      break;
    }
    y -= 7;
  }

  return pts;
}

function strokePath(pts, c, weight) {
  if (pts.length < 2) return;
  noFill();
  stroke(c);
  strokeWeight(weight);
  beginShape();
  for (const p of pts) {
    vertex(p.x, p.y);
  }
  endShape();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function smoothStep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function draw() {
  const W = width;
  const H = height;
  colorMode(RGB, 255);

  const top = color(25, 30, 46);
  const middle = color(13, 17, 25);
  const bottom = color(21, 25, 31);

  for (let y = 0; y < H; y++) {
    const t = y / H;
    let c;
    if (t < 0.64) {
      c = lerpColor(top, middle, smoothStep(0, 0.64, t));
    } else {
      c = lerpColor(middle, bottom, smoothStep(0.64, 1, t));
    }
    const n = (noise(3.7, y * 0.004) - 0.5) * 4;
    stroke(red(c) + n, green(c) + n, blue(c) + n);
    strokeWeight(1);
    line(0, y, W, y);
  }

  noStroke();
  for (let i = 70; i > 0; i--) {
    const t = i / 70;
    fill(94, 80, 67, 0.20 + 0.15 * (1 - t));
    ellipse(
      W * 0.49 + sin(i * 0.08) * 20,
      H * 0.30,
      i * 24,
      i * 30
    );
  }

  const stillA = color(58, 66, 75);
  const stillB = color(29, 35, 43);

  for (let i = 0; i < 26000; i++) {
    const x = random(-10, W + 10);
    const y = random(1210, H);
    const emergence = smoothStep(1210, 1430, y);
    if (random() > emergence) continue;

    const depth = (y - 1210) / (H - 1210);
    const c = lerpColor(
      stillA,
      stillB,
      constrain(depth * 0.65 + random(-0.08, 0.08), 0, 1)
    );
    const v = random(-5, 5);
    fill(red(c) + v, green(c) + v, blue(c) + v, random(5, 16));

    let r = random(0.55, 1.55);
    if (random() < 0.06) r *= 1.4;
    circle(x, y, r);
  }

  for (let i = 0; i < 150; i++) {
    const y = 1120 + i * 2.2;
    const u = i / 149;
    stroke(11, 15, 22, sin(PI * u) * 2.2);
    strokeWeight(1);
    line(0, y, W, y);
  }

  const palette = [
    color(218, 211, 187),
    color(202, 165, 116),
    color(139, 166, 166),
    color(172, 119, 113),
    color(184, 183, 170),
    color(115, 143, 153)
  ];
  const ash = color(71, 80, 90);

  for (let i = 0; i < 230; i++) {
    let x0;
    if (random() < 0.45) {
      x0 = randomGaussian(W * 0.5, W * 0.24);
    } else {
      x0 = random(W * 0.06, W * 0.94);
    }
    x0 = constrain(x0, 35, W - 35);

    let y0 = random(90, 650);
    if (i % 9 === 0) y0 = random(-60, 180);

    const stopY = random(1050, 1325);
    const step0 = random(3.0, 5.2);
    let w = random(0.55, 1.55);
    if (random() < 0.12) w = random(1.8, 2.7);

    const base = palette[floor(random(palette.length))];
    let alpha0 = random(38, 92);
    if (w > 1.8) alpha0 *= 0.72;

    const z = random(1000);
    const lean = random(-0.34, 0.34);
    const pts = [{ x: x0, y: y0 }];

    let x = x0;
    let y = y0;

    for (let s = 0; s < 520; s++) {
      const calm = 1 - 0.82 * smoothStep(720, 1270, y);
      const field =
        (noise(x * 0.0017, y * 0.0016, z) - 0.5) * 1.45;
      const wave = sin(s * 0.022 + z) * 0.09;
      const ang = HALF_PI + (lean + field + wave) * calm;
      const speed =
        step0 * (1 - 0.58 * smoothStep(760, 1300, y));

      x += cos(ang) * speed;
      y += sin(ang) * speed;
      pts.push({ x: x, y: y });

      if (y >= stopY || x < -80 || x > W + 80) break;
    }

    if (pts.length < 20) continue;

    const branches = [];
    const branchCount = floor(random(1, 5));

    for (let b = 0; b < branchCount; b++) {
      const ix = floor(
        random(pts.length * 0.12, pts.length * 0.66)
      );
      const p = pts[ix];
      if (!p || p.y > 950) continue;

      const side = random() < 0.5 ? -1 : 1;
      let bx = p.x;
      let by = p.y;
      const ba = HALF_PI + side * random(0.38, 0.95);
      const bpts = [{ x: bx, y: by }];
      const bl = floor(random(16, 50));

      for (let s = 0; s < bl; s++) {
        const n =
          (noise(bx * 0.002, by * 0.002, z + b + 4) - 0.5) *
          0.8;
        const aa = ba + n * 0.45;
        const bs =
          step0 *
          random(0.55, 0.82) *
          (1 - (s / bl) * 0.35);

        bx += cos(aa) * bs;
        by += sin(aa) * bs;
        bpts.push({ x: bx, y: by });

        if (by > 1120) break;
      }
      branches.push(bpts);
    }

    for (const bpts of branches) {
      for (let j = 1; j < bpts.length; j++) {
        const p = bpts[j - 1];
        const q = bpts[j];
        const u = j / (bpts.length - 1);
        const dying = smoothStep(790, 1230, p.y);
        const c = lerpColor(base, ash, dying * 0.8);
        const a =
          alpha0 * 0.34 * sin(PI * u) * (1 - dying * 0.7);

        stroke(red(c), green(c), blue(c), a);
        strokeWeight(
          max(0.35, w * 0.42 * (1 - u * 0.55))
        );
        line(p.x, p.y, q.x, q.y);
      }
    }

    for (let j = 1; j < pts.length; j++) {
      const p = pts[j - 1];
      const q = pts[j];
      const u = j / (pts.length - 1);
      const appear = smoothStep(0, 0.08, u);
      const vanish = 1 - smoothStep(0.68, 1, u);
      const dying = smoothStep(
        790,
        1320,
        (p.y + q.y) * 0.5
      );
      const c = lerpColor(base, ash, dying * 0.9);
      const a =
        alpha0 * appear * vanish * (1 - 0.80 * dying);

      if (a < 0.3) continue;

      if (w > 1.5 && j % 2 === 0) {
        stroke(red(c), green(c), blue(c), a * 0.055);
        strokeWeight(w * 6);
        line(p.x, p.y, q.x, q.y);
      }

      stroke(red(c), green(c), blue(c), a);
      strokeWeight(
        max(0.3, w * (1 - 0.55 * dying) * (1 - 0.3 * u))
      );
      line(p.x, p.y, q.x, q.y);
    }
  }

  for (let i = 0; i < 120; i++) {
    const y = 1180 + i * 2.4;
    const u = i / 119;
    stroke(15, 19, 26, sin(PI * u) * 3.2);
    strokeWeight(1);
    line(0, y, W, y);
  }

  for (let i = 0; i < 46000; i++) {
    const x = random(W);
    const y = random(H);
    if (random() < 0.48) {
      stroke(185, 192, 197, random(1.5, 5));
    } else {
      stroke(0, 0, 0, random(2, 7));
    }
    strokeWeight(random() < 0.96 ? 1 : 1.4);
    point(x, y);
  }

  noStroke();
  for (let i = 0; i < 140; i++) {
    const d = i * 3;
    const a = 12 * (1 - i / 140);
    fill(3, 6, 11, a);
    rect(0, d, W, 3);
    rect(0, H - d - 3, W, 3);
    rect(d, 0, 3, H);
    rect(W - d - 3, 0, 3, H);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const cx = 800;
  const cy = 765;
  const rx = 492;
  const ry = 548;

  paintGround(cx, cy);
  paintQuietField();
  paintMembrane(cx, cy, rx, ry);
  paintLooseThreads(cx, cy, rx, ry);
  paintDust(cx, cy, rx, ry);
  paintVignette();
  paintSurfaceGrain();
}

function paintGround(cx, cy) {
  background(7, 9, 11);
  const ctx = drawingContext;

  const vertical = ctx.createLinearGradient(0, 0, 0, height);
  vertical.addColorStop(0, "#07090c");
  vertical.addColorStop(0.46, "#111214");
  vertical.addColorStop(1, "#06080a");
  ctx.fillStyle = vertical;
  ctx.fillRect(0, 0, width, height);

  const glow = ctx.createRadialGradient(cx, cy - 40, 30, cx, cy, 940);
  glow.addColorStop(0, "rgba(109,94,67,0.13)");
  glow.addColorStop(0.42, "rgba(61,59,51,0.085)");
  glow.addColorStop(0.76, "rgba(24,29,31,0.035)");
  glow.addColorStop(1, "rgba(0,0,0,0)");
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, width, height);
}

function paintQuietField() {
  noFill();
  strokeWeight(0.65);

  for (let i = 0; i < 72; i++) {
    const baseY = 1200 + i * 10.2 + random(-3, 3);
    const alpha = 7 * Math.sin(PI * (i + 1) / 73);
    stroke(133, 140, 137, alpha);
    beginShape();

    for (let x = -80; x <= width + 80; x += 22) {
      const n = noise(x * 0.0018, i * 0.09 + 40);
      const y = baseY + (n - 0.5) * 28 + 8 * sin(x * 0.002 + i * 0.08);
      vertex(x, y);
    }
    endShape();
  }
}

function membranePoint(a, off, cx, cy, rx, ry) {
  const s = Math.max(0, sin(a));
  const d = Math.pow(s, 1.65);
  const ca = cos(a);
  const sa = sin(a);

  const wobble =
    1 +
    0.014 * sin(3 * a + 0.8) +
    0.008 * sin(7 * a - 0.4) +
    0.016 * (noise(ca * 2.1 + 11, sa * 2.1 + 7) - 0.5);

  let x = cx + (rx + off) * ca * wobble;
  let y = cy + (ry + off * 1.04) * sa * wobble;
  x += 12 * sin(2 * a + 0.2);

  const n1 = noise(ca * 2.6 + off * 0.008 + 30, sa * 2.6 + 30);
  const n2 = noise(ca * 3.1 + 71, sa * 3.1 + off * 0.006 + 19);

  x += d * d * ((n1 - 0.5) * 210 + 35 * sin(a * 5 + off * 0.02));
  y += d * d * (35 + 170 * n2);

  return [x, y, d];
}

function paintMembrane(cx, cy, rx, ry) {
  const count = 68;
  const steps = 720;

  for (let i = 0; i < count; i++) {
    const band = i / (count - 1);
    const off = map(i, 0, count - 1, -54, 54) + random(-0.45, 0.45);
    const baseAlpha = 24 + 57 * Math.pow(band, 1.35);
    const weight = random(0.45, 0.95);

    const r = lerp(137, 220, band);
    const g = lerp(148, 209, band);
    const b = lerp(148, 183, band);

    strokeWeight(weight);

    for (let j = 0; j < steps; j++) {
      const a1 = -PI + TWO_PI * j / steps;
      const a2 = -PI + TWO_PI * (j + 1) / steps;
      const p1 = membranePoint(a1, off, cx, cy, rx, ry);
      const p2 = membranePoint(a2, off, cx, cy, rx, ry);
      const d = (p1[2] + p2[2]) * 0.5;

      let keep = true;
      if (d > 0) {
        const gap = noise(cos(a1) * 3.8 + i * 0.043 + 50, sin(a1) * 3.8 + 90);
        keep = gap > Math.pow(d, 1.05) * 0.92;
      }

      if (keep) {
        const upperLight = 0.72 + 0.28 * Math.max(0, -sin(a1));
        const alpha = baseAlpha * (1 - 0.76 * d) * upperLight;
        stroke(r, g, b, alpha);
        line(p1[0], p1[1], p2[0], p2[1]);
      }
    }
  }

  strokeWeight(1.05);
  for (let j = 0; j < 520; j++) {
    const t1 = j / 520;
    const t2 = (j + 1) / 520;
    const a1 = PI + PI * t1;
    const a2 = PI + PI * t2;
    const p1 = membranePoint(a1, 55.5, cx, cy, rx, ry);
    const p2 = membranePoint(a2, 55.5, cx, cy, rx, ry);
    const alpha = 48 + 66 * Math.sin(PI * t1);
    stroke(229, 218, 190, alpha);
    line(p1[0], p1[1], p2[0], p2[1]);
  }
}

function paintLooseThreads(cx, cy, rx, ry) {
  strokeWeight(0.65);

  for (let i = 0; i < 34; i++) {
    const a = random(0.16, PI - 0.16);
    const s = sin(a);
    const off = random(-45, 60);
    const p = membranePoint(a, off, cx, cy, rx, ry);

    const len = random(160, 560) * (0.4 + 0.6 * s);
    const drift = random(-140, 140) + (p[0] - cx) * random(0.05, 0.22);
    const phase = random(TWO_PI);
    const bow = random(-60, 60);
    const stopAt = random(0.55, 1);

    let px = p[0];
    let py = p[1];

    for (let j = 1; j <= 70; j++) {
      const t = j / 70;
      if (t > stopAt) break;

      const x =
        p[0] +
        drift * Math.pow(t, 1.2) +
        sin(t * 5 + phase) * 36 * t +
        (noise(i * 0.3, t * 2.5) - 0.5) * 70 * t;
      const y = p[1] + len * t + bow * sin(PI * t);

      if (noise(t * 3 + i, 88) > 0.18) {
        const alpha = 38 * (1 - t) * (0.35 + 0.65 * s);
        stroke(178, 177, 158, alpha);
        line(px, py, x, y);
      }
      px = x;
      py = y;
    }
  }
}

function paintDust(cx, cy, rx, ry) {
  for (let i = 0; i < 21000; i++) {
    const a = random(0.04, PI - 0.04);
    const s = sin(a);

    if (random() > 0.18 + 0.82 * Math.pow(s, 0.7)) continue;

    const off = randomGaussian() * 36;
    const p = membranePoint(a, off, cx, cy, rx, ry);
    const t = Math.pow(random(), 0.72);
    const reach = random(120, 690) * (0.3 + 0.7 * s);
    const spread = 12 + 100 * t;

    const x =
      p[0] +
      (p[0] - cx) * 0.25 * t +
      randomGaussian() * spread * 0.45 +
      45 * (noise(i * 0.013, t * 3.2) - 0.5) * t;
    const y = p[1] + reach * t + randomGaussian() * 10;

    if (y > 1900) continue;

    let alpha = random(12, 75) * Math.pow(1 - t, 1.4) * (0.35 + 0.65 * s);
    if (y > 1650) alpha *= map(y, 1650, 1900, 1, 0);

    const size = random() < 0.035 ? random(1.6, 2.6) : random(0.45, 1.35);
    strokeWeight(size);

    const q = random();
    if (q < 0.12) {
      stroke(190, 158, 108, alpha * 0.8);
    } else if (q < 0.32) {
      stroke(115, 137, 142, alpha * 0.8);
    } else {
      stroke(202, 198, 178, alpha);
    }
    point(x, y);
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const v = ctx.createRadialGradient(800, 860, 520, 800, 860, 1260);
  v.addColorStop(0, "rgba(0,0,0,0)");
  v.addColorStop(0.75, "rgba(0,0,0,0.06)");
  v.addColorStop(1, "rgba(0,0,0,0.52)");
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, width, height);
}

function paintSurfaceGrain() {
  for (let i = 0; i < 50000; i++) {
    const x = random(width);
    const y = random(height);
    strokeWeight(random(0.35, 0.9));

    if (random() < 0.5) {
      stroke(220, 211, 190, random(1.5, 4.5));
    } else {
      stroke(0, 0, 0, random(2, 7));
    }
    point(x, y);
  }
}

randomSeed(1);
noiseSeed(1);

const W = 1600;
const H = 2000;
const MOONX = 800;   // 暗月中心
const MOONY = 580;
const MOONR = 440;
const COREX = 800;   // 生命核心（聚集处）
const COREY = 1760;
const PLUME_TOP = 1030;    // 弥散的终点（月下缘附近）
const PLUME_BOTTOM = 1730; // 起点

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  drawBackground();
  drawStars();
  drawMoon();
  drawMoonDust();
  drawCorona();
  drawPlume();
  drawThread();
  drawCore();
  drawVignette();
}

// 可复现的高斯采样（基于受 seed 控制的 random()）
function gauss() {
  let u = 0, v = 0;
  while (u === 0) u = random();
  while (v === 0) v = random();
  return Math.sqrt(-2 * Math.log(u)) * Math.cos(TWO_PI * v);
}

function drawBackground() {
  noStroke();
  const cTop = color(4, 6, 12);
  const cBot = color(12, 16, 28);
  for (let y = 0; y < H; y++) {
    fill(lerpColor(cTop, cBot, y / (H - 1)));
    rect(0, y, W, 1);
  }
}

// 背景星尘：弥散后的粒子与它们无从分辨
function drawStars() {
  noStroke();
  for (let i = 0; i < 900; i++) {
    const x = random(W);
    const y = random(H);
    const b = random();
    const s = 0.6 + b * 1.8;
    fill(185 + random(45), 195 + random(50), 220 + random(35), 4 + b * b * 42);
    ellipse(x, y, s, s);
  }
}

// 暗月：死亡本身，完整、安静、不动声色
function drawMoon() {
  noStroke();
  fill(2, 3, 8);
  ellipse(MOONX, MOONY, MOONR * 2, MOONR * 2);
}

// 月内极暗的微尘：死亡内部并非空无
function drawMoonDust() {
  noStroke();
  for (let i = 0; i < 420; i++) {
    const a = random(TWO_PI);
    const r = Math.sqrt(random()) * (MOONR - 16);
    const x = MOONX + Math.cos(a) * r;
    const y = MOONY + Math.sin(a) * r;
    fill(28, 44, 74, 3 + random(11));
    ellipse(x, y, 0.8 + random(2.4), 0.8 + random(2.4));
  }
}

// 月缘光环：与生命同色的最后一圈暖光
function drawCorona() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 7; i++) {
    const k = i / 6;
    const r = MOONR + 2 + i * 12;
    stroke(255, 214, 150, Math.pow(1 - k, 2.1) * 55);
    strokeWeight(13);
    ellipse(MOONX, MOONY, r * 2, r * 2);
  }
  for (let i = 0; i < 4; i++) {
    const r = MOONR - 1 - i * 3;
    stroke(200, 120, 70, 26 - i * 6);
    strokeWeight(2.5);
    ellipse(MOONX, MOONY, r * 2, r * 2);
  }
  noStroke();
  for (let i = 0; i < 26; i++) {
    const a = random(TWO_PI);
    const r = MOONR + 1 + random(6);
    const x = MOONX + Math.cos(a) * r;
    const y = MOONY + Math.sin(a) * r;
    const s = 1.3 + random(2.6);
    fill(255, 236, 200, 55 + random(75));
    ellipse(x, y, s, s);
  }
  blendMode(BLEND);
}

// 烟柱中轴：t=0 在核心，t=1 到达月缘，t>1 为穿越暗月的延伸
function axisX(t) {
  const tc = constrain(t, 0, 1);
  const wander = (noise(t * 3.1 + 7) - 0.5) * lerp(70, 340, tc);
  const curl = (noise(t * 7.3, 3) - 0.5) * 130 * Math.min(t, 1.6);
  return COREX + wander + curl;
}

function yOfT(t) {
  return PLUME_BOTTOM - t * (PLUME_BOTTOM - PLUME_TOP);
}

// 温度的散逸：暖金 → 白 → 冷青 → 暗蓝
function plumeColor(t) {
  const st = [
    [0.0, 255, 208, 140],
    [0.3, 255, 232, 200],
    [0.65, 160, 190, 224],
    [1.0, 82, 112, 166],
    [1.6, 45, 66, 108]
  ];
  if (t <= st[0][0]) return [st[0][1], st[0][2], st[0][3]];
  for (let i = 0; i < st.length - 1; i++) {
    if (t <= st[i + 1][0]) {
      const k = (t - st[i][0]) / (st[i + 1][0] - st[i][0]);
      return [
        lerp(st[i][1], st[i + 1][1], k),
        lerp(st[i][2], st[i + 1][2], k),
        lerp(st[i][3], st[i + 1][3], k)
      ];
    }
  }
  const e = st[st.length - 1];
  return [e[1], e[2], e[3]];
}

function placePlumeParticle(x, y, t, mul, size, dim) {
  const c = plumeColor(t);
  let a = lerp(170, 30, constrain(t, 0, 1)) * mul * (0.45 + random(0.75));
  if (dim) a *= 0.65;
  if (dist(x, y, MOONX, MOONY) < MOONR - 2) a *= 0.22; // 没入月面
  fill(c[0], c[1], c[2], a);
  ellipse(x, y, size, size);
}

// 上升的烟：丝缕 + 雾
function drawPlume() {
  blendMode(ADD);
  noStroke();
  for (let s = 0; s < 260; s++) {
    const side = random(-1, 1);
    const phase = random(500);
    const tStart = random(0.2);
    const tEnd = tStart + 0.55 + random(0.45);
    const n = 10 + floor(random(36));
    for (let j = 0; j < n; j++) {
      const t = lerp(tStart, tEnd, j / Math.max(1, n - 1));
      const sigma = lerp(55, 230, constrain(t, 0, 1));
      const x = axisX(t) + side * sigma * 0.6
              + (noise(phase + t * 4.5) - 0.5) * 150 * Math.min(t, 1)
              + gauss() * 9;
      const y = yOfT(t) + gauss() * 14;
      placePlumeParticle(x, y, t, 0.62, 1.4 + random(1.7), false);
    }
  }
  for (let i = 0; i < 18000; i++) {
    const t = Math.pow(random(), 1.7);
    const sigma = lerp(55, 230, t);
    let x = axisX(t) + gauss() * sigma * 0.72;
    let y = yOfT(t) + gauss() * lerp(22, 55, t);
    let drifter = false;
    if (t > 0.45 && random() < 0.07) { // 被带走的碎屑
      const dir = random() < 0.5 ? -1 : 1;
      x += dir * (150 + random(430));
      y -= random(110);
      drifter = true;
    }
    const size = lerp(4.6, 1.7, t) * (0.6 + random(0.8));
    placePlumeParticle(x, y, t, 1.0, size, drifter);
  }
  blendMode(BLEND);
}

// 穿过暗月的一缕：极暗，但存在
function drawThread() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 520; i++) {
    const t = 1 + Math.pow(random(), 1.15) * 1.35;
    const widen = lerp(26, 60, constrain((t - 1) / 1.35, 0, 1));
    const x = axisX(t) + gauss() * widen + (noise(t * 5 + 30) - 0.5) * 60;
    const y = yOfT(t) + gauss() * 12;
    const c = plumeColor(t);
    let a = lerp(42, 20, constrain((t - 1) / 1.35, 0, 1)) * (0.5 + random(0.7));
    if (dist(x, y, MOONX, MOONY) < MOONR - 2) a *= 0.8;
    fill(c[0], c[1], c[2], a);
    const s = 1.2 + random(1.8);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 8; i++) { // 少数仍可辨认的证词
    const t = 1 + random(1.25);
    const x = axisX(t) + gauss() * 22;
    const y = yOfT(t) + gauss() * 9;
    fill(120, 160, 215, 46);
    ellipse(x, y, 2.2, 2.2);
  }
  blendMode(BLEND);
}

// 核心：一次短暂的、温热的聚集
function drawCore() {
  blendMode(ADD);
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(COREX, COREY - 20, 0, COREX, COREY - 20, 520);
  g.addColorStop(0, 'rgba(255,216,150,0.55)');
  g.addColorStop(0.16, 'rgba(255,196,130,0.22)');
  g.addColorStop(0.45, 'rgba(200,160,110,0.07)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(COREX - 520, COREY - 540, 1040, 1040);
  noStroke();
  for (let i = 0; i < 2200; i++) {
    let x = COREX + gauss() * 62;
    let y = COREY - 24 + gauss() * 56;
    x += (noise(x * 0.008, y * 0.008) - 0.5) * 100;
    y += (noise(x * 0.01, y * 0.012, 9) - 0.5) * 80;
    const d = dist(x, y, COREX, COREY - 20);
    const k = constrain(1 - d / 300, 0, 1);
    const s = 1.2 + random(3.4) + k * 2.4;
    const a = (50 + random(110)) * (0.25 + k * 0.9);
    fill(255, 208 + random(30), 150 + random(50), a);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 16; i++) {
    const x = COREX + gauss() * 40;
    const y = COREY - 24 + gauss() * 38;
    fill(255, 240, 214, 210);
    const s = 3.5 + random(3.5);
    ellipse(x, y, s, s);
