// 余温 —— 一幅关于死亡本身的静态画
// 上：存在最浓处（燃烧的涡旋） 中：下坠稀释 下：近乎虚无，只余一粒余烬

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  paint();
}

function draw() {}

/* ---------- 调色锚点：从余烬到深渊 ---------- */
const K0 = [234, 140, 68];   // 余烬亮
const K1 = [160, 63, 35];    // 血赭
const K2 = [98, 63, 51];     // 灰褐
const K3 = [53, 49, 56];     // 冷灰
const K4 = [27, 26, 33];     // 深渊边缘

function mix(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t,
          a[1] + (b[1] - a[1]) * t,
          a[2] + (b[2] - a[2]) * t];
}

// 深度 t：0 = 核心最浓，1 = 虚无
function depthColor(t, a) {
  t = constrain(t, 0, 1);
  let c;
  if (t < 0.22)      c = mix(K0, K1, t / 0.22);
  else if (t < 0.50) c = mix(K1, K2, (t - 0.22) / 0.28);
  else if (t < 0.78) c = mix(K2, K3, (t - 0.50) / 0.28);
  else               c = mix(K3, K4, (t - 0.78) / 0.22);
  return color(c[0], c[1], c[2], a === undefined ? 255 : a);
}

function driftX(y) { // 下坠流的蜿蜒中心线
  return 800 + (noise(y * 0.0016) - 0.5) * 300;
}

function spreadOf(y) { // 越下坠越散开
  return min(250 + (y - 500) * 0.36, 640);
}

/* ================= 主绘制 ================= */
function paint() {
  /* ---- 1. 背景：向下沉入黑暗 ---- */
  noStroke();
  for (let y = 0; y < 2000; y += 10) {
    let c = mix([27, 21, 25], [9, 8, 11], y / 2000);
    fill(c[0], c[1], c[2]);
    rect(0, y, 1600, 10.5);
  }
  // 虚空中的暗斑
  for (let i = 0; i < 26; i++) {
    let x = random(1600), y = random(2000), r = random(60, 220);
    let dark = random() < 0.5;
    fill(dark ? 6 : 22, dark ? 5 : 18, dark ? 8 : 22, 14);
    circle(x, y, r * 2);
  }
  // 底层细颗粒
  for (let i = 0; i < 3000; i++) {
    let b = random(8, 20);
    fill(b, b - 2, b + 2, random(4, 9));
    rect(random(1600), random(2000), random(1, 2.4), random(1, 2.4));
  }

  /* ---- 2. 核心环境光 ---- */
  let g = drawingContext.createRadialGradient(800, 470, 60, 800, 470, 760);
  g.addColorStop(0, 'rgba(232,130,58,0.30)');
  g.addColorStop(0.4, 'rgba(150,60,34,0.12)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, 1600, 2000);

  /* ---- 3. 存在之核：燃烧的涡旋 ---- */
  coreStrokes(4200);
  coreArcs(120);
  breathingVoids(12);   // 核内的呼吸孔洞
  coreStrokes(3000);    // 叠加层，盖过孔洞边缘

  // 内层余烬光
  let g2 = drawingContext.createRadialGradient(800, 470, 20, 800, 470, 300);
  g2.addColorStop(0, 'rgba(255,170,90,0.18)');
  g2.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g2;
  drawingContext.fillRect(0, 0, 1600, 2000);

  warmDust(700);        // 核周围散出的暖尘

  /* ---- 4. 下坠：物质被一寸寸松开 ---- */
  fallingStream(11000);
  threads(14);          // 少数保持连贯、被拉入黑暗的长丝

  /* ---- 5. 灰烬微粒 ---- */
  ashSpecks(4500);

  /* ---- 6. 冷雾 ---- */
  noStroke();
  for (let i = 0; i < 4; i++) {
    fill(27, 29, 38, 10);
    ellipse(800 + (noise(i * 7.7) - 0.5) * 260,
            1120 + i * 230, 1150 - i * 100, 340);
  }

  /* ---- 7. 胶片颗粒 ---- */
  for (let i = 0; i < 5000; i++) {
    fill(236, 221, 204, random(3, 10));
    rect(random(1600), random(2000), 1.4, 1.4);
  }
  for (let i = 0; i < 3200; i++) {
    fill(0, 0, 0, random(4, 13));
    rect(random(1600), random(2000), 1.5, 1.5);
  }

  /* ---- 8. 压暗：上方与下方皆是虚空 ---- */
  let top = drawingContext.createLinearGradient(0, 0, 0, 420);
  top.addColorStop(0, 'rgba(4,3,6,0.55)');
  top.addColorStop(1, 'rgba(4,3,6,0)');
  drawingContext.fillStyle = top;
  drawingContext.fillRect(0, 0, 1600, 420);

  let bot = drawingContext.createLinearGradient(0, 2000, 0, 1350);
  bot.addColorStop(0, 'rgba(2,2,4,0.55)');
  bot.addColorStop(1, 'rgba(2,2,4,0)');
  drawingContext.fillStyle = bot;
  drawingContext.fillRect(0, 0, 1600, 2000);

  let vg = drawingContext.createRadialGradient(800, 820, 380, 800, 1050, 1500);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.7, 'rgba(4,3,6,0.22)');
  vg.addColorStop(1, 'rgba(3,2,5,0.62)');
  drawingContext.fillStyle = vg;
  drawingContext.fillRect(0, 0, 1600, 2000);

  /* ---- 9. 最后一粒余烬 ---- */
  let ex = driftX(1928) + 30;
  noStroke();
  fill(70, 46, 34, 40);   circle(ex, 1932, 18);
  fill(110, 70, 48, 70);  circle(ex, 1932, 8);
  fill(178, 118, 78, 230); circle(ex, 1932, 2.6);
}

/* ---------- 存在之核：切向涡流笔画 ---------- */
function coreStrokes(n) {
  let cx = 800, cy = 470;
  strokeCap(ROUND);
  for (let i = 0; i < n; i++) {
    let x = cx + (random() + random() + random() - 1.5) * 460;
    let y = cy + (random() + random() + random() - 1.5) * 380;
    let d = dist(x, y, cx, cy);
    let t = constrain(d / 560, 0, 0.30);
    // 涡流：绕核心切向 + 噪声扰动
    let a = atan2(y - cy, x - cx) + HALF_PI +
            (noise(x * 0.002, y * 0.002) - 0.5) * 2.0;
    let segs = 4;
    let step = random(16, 54) / segs;
    let c;
    if (random() < 0.035) c = color(246, 188, 122, random(180, 255)); // 少量迸溅的火
    else c = depthColor(t + random(-0.05, 0.05), random(170, 255));
    stroke(c);
    strokeWeight(random(0.9, 2.4));
    noFill();
    let px = x, py = y;
    for (let s = 0; s < segs; s++) {
      let nx = px + cos(a) * step;
      let ny = py + sin(a) * step;
      line(px, py, nx, ny);
      px = nx; py = ny;
      a += (noise(px * 0.004, py * 0.004, 50) - 0.5) * 1.0;
    }
  }
}

/* ---------- 核内主干弧线 ---------- */
function coreArcs(n) {
  noFill();
  strokeCap(ROUND);
  for (let i = 0; i < n; i++) {
    let cx = 800 + (random() - 0.5) * 300;
    let cy = 470 + (random() - 0.5) * 240;
    let r = random(60, 260);
    let start = random(TWO_PI);
    stroke(depthColor(random(0, 0.12), random(120, 220)));
    strokeWeight(random(1.8, 3.6));
    arc(cx, cy, r * 2, r * 2 * random(0.7, 1.3), start, start + random(0.5, 1.6));
  }
}

/* ---------- 核内的呼吸孔洞（负空间） ---------- */
function breathingVoids(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = 800 + (random() + random() - 1) * 420;
    let y = 470 + (random() + random() - 1) * 320;
    let r = random(24, 78);
    for (let k = 4; k >= 1; k--) {
      fill(12, 9, 13, k === 4 ? 120 : 45);
      circle(x, y, (r * k / 4) * 2);
    }
  }
}

/* ---------- 核周围漂浮的暖尘 ---------- */
function warmDust(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let x = 800 + (random() + random() + random() - 1.5) * 700;
    let y = 470 + (random() + random() + random() - 1.5) * 560;
    let d = dist(x, y, 800, 470);
    fill(depthColor(constrain(d / 620, 0, 0.30), random(60, 160)));
    circle(x, y, random(0.6, 1.6));
  }
}

/* ---------- 下坠消散流：线碎成点，暖色冷却 ---------- */
function fallingStream(n) {
  strokeCap(ROUND);
  for (let i = 0; i < n; i++) {
    let y = 580 + pow(random(), 1.35) * 1400; // 偏向上方（靠近核）
    let t = map(y, 480, 1980, 0, 1);
    let x = driftX(y) + (random() - 0.5) * 2 * spreadOf(y);

    // 越深越溶成碎点
    if (random() < map(y, 620, 1900, 0.05, 0.88)) {
      noStroke();
      fill(depthColor(t, random(55, 150)));
      let s = random(0.8, 2.4) * map(y, 500, 1980, 1.25, 0.55);
      circle(x, y, s);
      continue;
    }

    // 越深方向越乱（熵增），笔画越短
    let len = map(y, 500, 1950, 26, 5) * random(0.6, 1.35);
    let entropy = map(y, 500, 1980, 0.5, 2.6);
    let a = HALF_PI + (noise(x * 0.003, y * 0.003, 40) - 0.5) * entropy;
    stroke(depthColor(t, random(110, 215)));
    strokeWeight(random(0.7, 1.7));
    let segs = y < 1100 ? 3 : 2;
    let step = len / segs;
    let px = x, py = y;
    for (let s = 0; s < segs; s++) {
      let nx = px + cos(a) * step;
      let ny = py + sin(a) * step;
      line(px, py, nx, ny);
      px = nx; py = ny;
      a += (noise(px * 0.004, py * 0.004, 90) - 0.5) * 0.9;
    }
  }
}

/* ---------- 贯穿到底的长丝：最后一点连贯被拉走 ---------- */
function threads(n) {
  for (let i = 0; i < n; i++) {
    let x0 = 800 + (random() - 0.5) * 430;
    let y0 = 600 + random() * 130;
    let y1 = 1800 + random() * 180;
    let ph = random() * 100;
    let px = x0, py = y0;
    strokeWeight(random(0.6, 1.0));
    for (let y = y0 + 14; y <= y1; y += 14) {
      let x = x0 + (noise(ph, y * 0.0012) - 0.5) * 170;
      stroke(depthColor(map(y, 480, 1980, 0, 1), map(y, y0, y1, 140, 35)));
      line(px, py, x, y);
      px = x; py = y;
    }
  }
}

/* ---------- 灰烬微粒 ---------- */
function ashSpecks(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    let y = 520 + pow(random(), 1.5) * 1460;
    let t = map(y, 480, 1980, 0, 1);
    let x = driftX(y) + (random() - 0.5) * 2 * spreadOf(y) * 1.15;
    let c = lerpColor(depthColor(t, 255), color(128, 116, 108), 0.22);
    c.setAlpha(random(35, 105));
    fill(c);
    circle(x + (random() - 0.5) * 34, y + (random() - 0.5) * 34, random(0.7, 1.8));
  }
}

// 《归寂》 —— 1600 x 2000 静态图像
// 死亡本身：一颗曾燃烧的光核呼出自己，余烬沉降、冷却、归于底部的灰。

let W, H, coreX, coreY;

const BG_STOPS = [
  [0.00, 20, 13, 10],
  [0.28, 42, 27, 16],
  [0.46, 31, 21, 17],
  [0.70, 14, 14, 18],
  [1.00, 5, 6, 10]
];

const EMBER_STOPS = [
  [0.00, 255, 178, 96],
  [0.20, 226, 139, 80],
  [0.45, 138, 100, 82],
  [0.70, 86, 88, 96],
  [1.00, 50, 58, 74]
];

function gradAt(stops, t) {
  t = constrain(t, 0, 1);
  for (let i = 0; i < stops.length - 1; i++) {
    let a = stops[i], b = stops[i + 1];
    if (t <= b[0]) {
      let u = (t - a[0]) / (b[0] - a[0]);
      return [lerp(a[1], b[1], u), lerp(a[2], b[2], u), lerp(a[3], b[3], u)];
    }
  }
  let e = stops[stops.length - 1];
  return [e[1], e[2], e[3]];
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  W = 1600;
  H = 2000;
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  coreX = W / 2;
  coreY = 620;
}

function draw() {
  background(6, 6, 8);
  bgGradient();
  veils();
  coreGlow();
  coreBody();
  wisps();
  risers();
  emberStreams();
  dustMotes();
  sediment();
  settledEmbers();
  grain();
}

// ---------- 背景：由暖入冷的垂直渐变 ----------
function bgGradient() {
  noStroke();
  for (let y = 0; y < H; y++) {
    let c = gradAt(BG_STOPS, y / H);
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 1);
  }
}

// ---------- 深处的暗云帷幕 ----------
function veils() {
  push();
  noStroke();
  let defs = [
    [210, 1420, 660, 500, 110],
    [1380, 1010, 540, 720, 100],
    [680, 1800, 800, 320, 85],
    [1490, 390, 380, 540, 70],
    [120, 520, 320, 460, 60]
  ];
  for (let d = 0; d < defs.length; d++) {
    let v = defs[d];
    for (let i = 0; i < 14; i++) {
      let t = i / 13;
      let rx = v[2] * (1 - t * 0.9);
      let ry = v[3] * (1 - t * 0.9);
      let a = v[4] * t / 14;
      fill(7, 7, 11, a);
      ellipse(v[0], v[1], rx * 2, ry * 2);
    }
  }
  pop();
}

// ---------- 光核的辉光 ----------
function glowLayers(x, y, R, cr, cg, cb, peakA, rings, pw) {
  for (let i = rings; i > 0; i--) {
    let f = i / rings;
    let rr = R * f;
    let a = peakA * pow(1 - f, pw);
    if (a < 0.5) continue;
    fill(cr, cg, cb, a);
    ellipse(x, y, rr * 2, rr * 2);
  }
}

function coreGlow() {
  push();
  blendMode(ADD);
  noStroke();
  glowLayers(coreX, coreY, 1000, 255, 122, 52, 120, 40, 1.5);
  glowLayers(coreX, coreY, 430, 255, 165, 88, 255, 34, 4.5);
  glowLayers(coreX, coreY, 210, 255, 205, 125, 255, 24, 3.5);
  glowLayers(coreX, coreY, 64, 255, 246, 222, 210, 12, 3);
  pop();
  blendMode(BLEND);
}

// ---------- 核本体：上缘完整，下缘溶解拉长 ----------
function coreR(th, scale) {
  let down = (sin(th) + 1) / 2;
  let w1 = noise(cos(th) * 1.4 + 3.3, sin(th) * 1.4 + 3.3);
  let w2 = noise(cos(th) * 2.8 + 9.1, sin(th) * 2.8 + 9.1);
  let r = 112 * scale;
  r *= 1 + (w1 - 0.5) * 0.5 + down * down * 0.55 + (w2 - 0.5) * 1.1 * down;
  return r;
}

function drawCoreLayer(scale, cr, cg, cb, a) {
  fill(cr, cg, cb, a);
  beginShape();
  let n = 160;
  for (let i = 0; i <= n; i++) {
    let th = i / n * TWO_PI;
    let rr = coreR(th, scale);
    vertex(cos(th) * rr, sin(th) * rr);
  }
  endShape(CLOSE);
}

function coreBody() {
  push();
  noStroke();
  translate(coreX, coreY);
  drawCoreLayer(1.16, 205, 105, 46, 165);
  drawCoreLayer(0.95, 255, 168, 90, 220);
  drawCoreLayer(0.62, 255, 232, 190, 255);
  pop();
}

// ---------- 核下缘的剥离拉丝 ----------
function wisps() {
  push();
  noFill();
  for (let i = 0; i < 16; i++) {
    let ang = random(HALF_PI * 0.55, HALF_PI * 1.45);
    let r0 = random(88, 128);
    let x0 = coreX + cos(ang) * r0;
    let y0 = coreY + sin(ang) * r0;
    let len = random(150, 340);
    let x1 = x0 + cos(ang) * random(60, 200) + random(-70, 70);
    let y1 = y0 + len;
    stroke(255, 158, 84, random(20, 55));
    strokeWeight(random(1.0, 3.2));
    bezier(x0, y0,
           x0 + random(-60, 60), y0 + len * 0.35,
           x1 + random(-70, 70), y1 - len * 0.4,
           x1, y1);
  }
  pop();
}

// ---------- 上升的余温细丝 ----------
function risers() {
  push();
  noFill();
  for (let i = 0; i < 120; i++) {
    let x = coreX + random(-85, 85);
    let y = coreY - random(30, 95);
    let nSteps = floor(random(6, 13));
    let vx = random(-0.6, 0.6);
    stroke(255, 205, 150, random(18, 60));
    strokeWeight(random(0.6, 1.4));
    beginShape();
    vertex(x, y);
    for (let s = 0; s < nSteps; s++) {
      x += vx + (noise(x * 0.008, y * 0.008, i * 0.13) - 0.5) * 9;
      y -= random(26, 44);
      vertex(x, y);
    }
    endShape();
  }
  pop();
}

// ---------- 下沉的余烬流 ----------
function emberStreams() {
  push();
  blendMode(ADD);
  noFill();
  let N = 950;
  for (let i = 0; i < N; i++) {
    let ang = random(QUARTER_PI * 0.75, PI - QUARTER_PI * 0.75);
    let r0 = random(95, 155) * (1 + 0.25 * sin(ang));
    let x = coreX + cos(ang) * r0;
    let y = coreY + sin(ang) * r0;
    let vx = cos(ang) * random(0.2, 0.9);
    let ph = random(1000);
    let vy0 = random(2.0, 4.6);
    let life = floor(random(160, 460));
    let pts = [];
    for (let s = 0; s < life; s++) {
      let depth = constrain((y - coreY) / (H - 78 - coreY), 0, 1);
      let n1 = noise(x * 0.0017, y * 0.0017, ph * 0.012);
      let n2 = noise(x * 0.006, y * 0.006, ph * 0.03);
      let drift = (n1 - 0.5) * 2 + (n2 - 0.5);
      vx += (x - coreX) * 0.00011;
      vx += drift * 0.5 * (1 - depth * 0.7);
      vx *= 0.965;
      vx = constrain(vx, -5.5, 5.5);
      let vy = (vy0 + n1 * 1.4) * (1 - depth * 0.38) + 0.3;
      x += vx;
      y += vy;
      if (y > H - 78) break;
      if (x < -40 || x > W + 40) break;
      pts.push(x, y);
    }
    let total = pts.length / 2;
    if (total < 4) continue;
    let segs = 6;
    let per = max(1, floor(total / segs));
    let w0 = random(1.2, 2.9);
    for (let k = 0; k < segs; k++) {
      let i0 = k * per;
      let i1 = (k === segs - 1) ? (total - 1) : min(total - 1, i0 + per);
      if (i1 <= i0) break;
      let jMid = floor((i0 + i1) / 2);
      let ym = pts[2 * jMid + 1];
      let t = constrain((ym - coreY) / (H - 78 - coreY), 0, 1);
      let c = gradAt(EMBER_STOPS, t);
      let a = lerp(100, 15, pow(t, 0.85));
      a *= lerp(1, 0.5, k / (segs - 1));
      let sw = lerp(w0, 0.6, t);
      stroke(c[0], c[1], c[2], a);
      strokeWeight(sw);
      beginShape();
      vertex(pts[2 * i0], pts[2 * i0 + 1]);
      for (let j = i0 + 1; j <= i1; j++) {
        vertex(pts[2 * j], pts[2 * j + 1]);
      }
      endShape();
    }
  }
  pop();
  blendMode(BLEND);
}

// ---------- 已散的远景微尘 ----------
function dustMotes() {
  push();
  noStroke();
  for (let i = 0; i < 1600; i++) {
    let depth = pow(random(), 1.15);
    let y = lerp(coreY + 140, H - 90, depth);
    let spreadW = lerp(150, 620, depth);
    let g = (random(-1, 1) + random(-1, 1)) * 0.5;
    let x = coreX + g * spreadW;
    x += (noise(i * 0.37, y * 0.0015) - 0.5) * 380;
    if (x < 10 || x > W - 10) continue;
    let c = gradAt(EMBER_STOPS, constrain(depth * 1.05, 0, 1));
    let a = lerp(46, 7, depth);
    let sz = lerp(2.4, 0.8, depth) * random(0.6, 1.3);
    fill(c[0], c[1], c[2], a);
    ellipse(x, y, sz, sz);
  }
  pop();
}

// ---------- 底部的沉降灰层 ----------
function sedTopY(x) {
  let thick = 60 * exp(-pow((x - coreX) / 560, 2));
  return 1938 - thick + (noise(x * 0.0045 + 40, 12.3) - 0.5) * 64;
}

function sediment() {
  push();
  noStroke();
  fill(17, 15, 14);
  beginShape();
  vertex(-30, H + 30);
  for (let x = -30; x <= W + 30; x += 10) {
    vertex(x, sedTopY(x));
  }
  vertex(W + 30, H + 30);
  endShape(CLOSE);

  fill(10, 9, 9);
  beginShape();
  vertex(-30, H + 30);
  for (let x = -30; x <= W + 30; x += 10) {
    let thick = 26 * exp(-pow((x - coreX) / 420, 2));
    let y = 1972 - thick + (noise(x * 0.006 + 90, 5.1) - 0.5) * 40;
    vertex(x, y);
  }
  vertex(W + 30, H + 30);
  endShape(CLOSE);

  // 灰面上一线极弱的微光
  noFill();
  stroke(120, 96, 80, 26);
  strokeWeight(1.2);
  beginShape();
  for (let x = -30; x <= W + 30; x += 10) {
    vertex(x, sedTopY(x));
  }
  endShape();
  pop();
}

// ---------- 落定在灰上、尚未熄尽的最后几粒 ----------
function settledEmbers() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 30; i++) {
    let x = coreX + (random(-1, 1) + random(-1, 1)) * 0.5 * 480;
    let y = sedTopY(x) + random(-6, 10);
    if (random() < 0.55) {
      fill(255, 140, 70, random(28, 80));
      ellipse(x, y, random(1.2, 2.6));
    } else {
      fill(200, 120, 80, random(14, 40));
      ellipse(x, y, random(0.8, 1.6));
    }
  }
  pop();
  blendMode(BLEND);
}

// ---------- 细颗粒 ----------
function grain() {
  push();
  noStroke();
  for (let i = 0; i < 7000; i++) {
    let x = random(W);
    let y = random(H);
    if (random() < 0.55) {
      fill(255, 240, 220, random(3, 9));
    } else {
      fill(0, 0, 0, random(4, 12));
    }
    rect(x, y, 1.3, 1.3);
  }
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  render();
}

const CX = 800;   // 余烬中心
const CY = 1248;

function render() {
  noStroke();
  drawBackdrop();
  drawFog();
  drawGrain();
  drawRuins();
  drawStardust();
  drawSmoke();
  drawAshfield();
  drawEmber();
  drawSparks();
  drawBuriedGlow();
  drawVignette();
  drawFinalGrain();
}

/* 背景：上深蓝黑、下暖黑的呼吸 */
function drawBackdrop() {
  const top = color(5, 6, 12);
  const mid = color(9, 9, 10);
  const bot = color(22, 17, 11);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = (t < 0.55) ? lerpColor(top, mid, t / 0.55)
                       : lerpColor(mid, bot, (t - 0.55) / 0.45);
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();
}

/* 黑暗不是空的：大尺度深浅起伏 */
function drawFog() {
  for (let i = 0; i < 420; i++) {
    let x = random(width), y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    if (n > 0.53)      fill(26, 30, 38, 5);
    else if (n < 0.42) fill(0, 0, 0, 12);
    else continue;
    circle(x, y, random(90, 260));
  }
}

/* 底层颗粒 */
function drawGrain() {
  for (let i = 0; i < 8000; i++) {
    let x = random(width), y = random(height);
    if (random() < 0.5) fill(88, 86, 84, random(2, 7));
    else                fill(0, 0, 0, random(2, 8));
    circle(x, y, random(0.8, 2.2));
  }
}

/* 远处的残迹：已熄的冷痕 */
function drawRuins() {
  blendMode(ADD);
  const ruins = [
    [392, 528, 132], [1218, 764, 92], [1058, 282, 66], [552, 986, 50],
  ];
  for (let ri = 0; ri < ruins.length; ri++) {
    let rx = ruins[ri][0], ry = ruins[ri][1], rr = ruins[ri][2];
    for (let i = 0; i < 46; i++) {
      let t = i / 45;
      let a = (2 + t * 9) * (0.7 + noise(i * 0.33, rx) * 0.6);
      fill(40, 48, 60, a);
      circle(rx, ry, rr * 2 * (1 - t) + 8);
    }
    fill(64, 74, 88, 24);
    circle(rx, ry, 9 + random(0, 5));
  }
  blendMode(BLEND);
}

/* 顶部散逸的微尘：烟的归处之一 */
function drawStardust() {
  for (let i = 0; i < 240; i++) {
    let y = pow(random(), 1.5) * 1150;
    let x = (random() < 0.45)
      ? 800 + (random() + random() - 1) * 640
      : random(width);
    fill(140, 146, 158, random(5, 22));
    circle(x, y, random(0.7, 2.1));
  }
}

/* 烟的骨架：蜿蜒上升 */
function spineX(y) {
  let h = (1180 - y) / 1180;
  return 800 + (noise(523, y * 0.0026) - 0.5) * (120 + h * 330);
}

/* 烟：最后一次上升、舒展、散掉 */
function drawSmoke() {
  const BASE = 1178;
  for (let i = 0; i < 34000; i++) {
    let y = BASE - random() * 1060;
    let h = (BASE - y) / BASE;
    let spread = 24 + (BASE - y) * 0.15;
    let g = random() + random() + random() - 1.5;
    let x = spineX(y) + g * spread * 0.9;
    let sgn = random() < 0.5 ? -1 : 1;
    if (y < 720) {
      let f = (720 - y) / 720;
      x += sgn * f * f * (170 + random() * 160);
    }
    x += (noise(x * 0.006, y * 0.006) - 0.5) * 42;
    let w = min(h * 1.25, 1);
    let cr = lerp(118, 92, w), cg = lerp(102, 100, w), cb = lerp(90, 112, w);
    let a = (7 + random() * 16) * (1 - h * 0.8);
    if (a < 1.5) continue;
    fill(cr, cg, cb, a);
    circle(x, y, 1.6 + random() * 3.4);
  }
}

/* 灰原表面 */
function ashSurface(x) {
  let d = x - 800;
  let lift = 20 * Math.exp(-(d * d) / 45000);
  return 1862 - noise(x * 0.0021, 33.7) * 105
              + (noise(x * 0.012, 91.2) - 0.5) * 30 - lift;
}

/* 灰烬原：光沉降为地 */
function drawAshfield() {
  for (let i = 0; i < 17000; i++) {
    let x = random(width);
    let sy = ashSurface(x);
    let y = (sy - 12) + pow(random(), 1.6) * 190;
    if (y > height - 1) continue;
    let band = noise(x * 0.0035, 12.3);
    let lm = 0.8 + band * 0.5;
    let fresh = y < sy + 3;
    let t = random();
    let br, bg, bb, a;
    if (fresh)          { br = 108;      bg = 101;      bb = 93;      a = random(55, 100); }
    else if (t < 0.04)  { br = 84 * lm;  bg = 78 * lm;  bb = 71 * lm; a = random(40, 75); }
    else if (t < 0.5)   { br = 56 * lm;  bg = 51 * lm;  bb = 46 * lm; a = random(30, 70); }
    else                { br = 39 * lm;  bg = 36 * lm;  bb = 33 * lm; a = random(26, 60); }
    fill(br, bg, bb, a);
    circle(x, y, 1 + random() * 2.2);
  }
  /* 灰里埋着未冷的暗红 */
  blendMode(ADD);
  for (let i = 0; i < 42; i++) {
    let px = 800 + (random() + random() - 1) * 560;
    let py = ashSurface(px) + random(3, 70);
    fill(150, 50, 16, random(22, 62));
    circle(px, py, random(1.5, 3.4));
  }
  blendMode(BLEND);
}

/* 余烬在不同方向上被侵蚀后的半径 */
function emberMaxR(th) {
  return 140 + pow(noise(cos(th) * 1.25 + 80, sin(th) * 1.25 + 80), 1.6) * 320;
}

/* 余烬：正在被黑暗收回的光 */
function drawEmber() {
  blendMode(ADD);
  noStroke();

  /* 侵蚀状的层叠底晕 */
  for (let layer = 0; layer < 60; layer++) {
    let t = layer / 59;
    let fade = pow(1 - t, 1.4);
    if (fade < 0.03) continue;
    let a = 3 + t * 12;
    let k = pow(t, 0.8);
    fill(lerp(64, 178, k), lerp(14, 72, k), lerp(5, 26, k), a);
    beginShape();
    for (let j = 0; j <= 48; j++) {
      let th = (j / 48) * TWO_PI;
      let wob = noise(cos(th) * 2.4 + 31, sin(th) * 2.4 + 31, t * 3.0);
      let rr = emberMaxR(th) * fade * (0.72 + wob * 0.46);
      vertex(CX + cos(th) * rr, CY + sin(th) * rr);
    }
    endShape(CLOSE);
  }

  /* 碎光粒子：边缘正在剥落 */
  for (let i = 0; i < 4600; i++) {
    let th = random(TWO_PI);
    let maxR = emberMaxR(th);
    let r = pow(random(), 2.0) * maxR;
    let x = CX + cos(th) * r + (random() - 0.5) * 12;
    let y = CY + sin(th) * r + (random() - 0.5) * 12;
    let t = r / maxR;
    let cr, cg, cb, a;
    if (t < 0.28) {
      let u = t / 0.28;
      cr = lerp(255, 205, u); cg = lerp(160, 80, u); cb = lerp(70, 22, u);
      a = lerp(38, 20, u);
    } else {
      let u = (t - 0.28) / 0.72;
      cr = lerp(205, 80, u); cg = lerp(80, 18, u); cb = lerp(22, 5, u);
      a = lerp(20, 6, u);
    }
    fill(cr, cg, cb, a);
    circle(x, y, lerp(5.5, 1.8, t) + random() * 1.6);
  }

  /* 碎裂的热核：正在裂开的最后一点热 */
  const blobs = [
    [-16, -7, 21], [11, -14, 16], [18, 9, 19], [-7, 15, 14], [1, 1, 27],
  ];
  for (let bi = 0; bi < blobs.length; bi++) {
    let dx = blobs[bi][0], dy = blobs[bi][1], r = blobs[bi][2];
    for (let j = 0; j < 26; j++) {
      let u = j / 25;
      fill(lerp(185, 255, u), lerp(62, 214, u), lerp(18, 150, u), 12 + u * 18);
      circle(CX + dx, CY + dy, (r * (1 - u) + 3) * 2);
    }
  }
  fill(255, 240, 212, 190);
  circle(CX - 2, CY - 2, 9);
  fill(255, 198, 128, 80);
  circle(CX - 2, CY - 2, 24);

  blendMode(BLEND);
}

/* 剥落的火星：向外、向下、坠落 */
function drawSparks() {
  blendMode(ADD);
  for (let i = 0; i < 300; i++) {
    let th = random(TWO_PI);
    let maxR = emberMaxR(th);
    let r0 = maxR * random(0.5, 0.98);
    let sx = CX + cos(th) * r0;
    let sy = CY + sin(th) * r0;

    if (random() < 0.38) {
      /* 长程沉降弧 */
      let vx = cos(th) * random(60, 190) + (random() - 0.5) * 120;
      let ty = ashSurface(sx + vx) - random(0, 14);
      let totY = ty - sy;
      let steps = 30;
      for (let k2 = 0; k2 < steps; k2++) {
        let u = k2 / (steps - 1);
        let px = sx + vx * u;
        let py = sy + totY * (u * u * 0.62 + u * 0.38);
        fill(255, 118, 40, lerp(34, 6, u * u));
        circle(px, py, lerp(2.6, 1.0, u));
      }
      fill(200, 88, 30, 38);
      circle(sx + vx, ty, 2.2);
    } else {
      /* 短程剥落拖尾 */
      let len = random(30, 110);
      let dx = cos(th) * len * 0.8 + (random() - 0.5) * 40;
      let dy = sin(th) * len * 0.5 + len * 0.9;
      for (let k2 = 0; k2 < 9; k2++) {
        let u = k2 / 8;
        fill(255, 130, 45, lerp(44, 5, u * u));
        circle(sx + dx * u, sy + dy * u, lerp(3.4, 1.1, u));
      }
    }
  }
  blendMode(BLEND);
}

/* 余温透进灰里：热正在成为它将归的地方 */
function drawBuriedGlow() {
  blendMode(ADD);
  let gy = ashSurface(800) + 55;
  for (let i = 0; i < 34; i++) {
    let u = i / 33;
    fill(110, 38, 12, 3 + u * 9);
    circle(800, gy, lerp(280, 24, u) * 2);
  }
  blendMode(BLEND);
}

/* 暗角 */
function drawVignette() {
  blendMode(BLEND);
  noStroke();
  for (let y = 0; y < 130; y++) {
    fill(2, 3, 6, (1 - y / 130) * 55);
    rect(0, y, width, 1);
  }
  for (let y = 0; y < 190; y++) {
    fill(3, 2, 2, (y / 190) * 42);
    rect(0, height - 190 + y, width, 1);
  }
  for (let x = 0; x < 110; x++) {
    let a = (1 - x / 110) * 36;
    fill(2, 3, 6, a);
    rect(x, 0, 1, height);
    rect(width - 1 - x, 0, 1, height);
  }
}

/* 最后的颗粒 */
function drawFinalGrain() {
  for (let i = 0; i < 9000; i++) {
    let x = random(width), y = random(height);
    if (random() < 0.5) fill(120, 115, 108, random(2, 6));
    else                fill(0, 0, 0, random(2, 6));
    circle(x, y, random(0.6, 1.8));
  }
}

// 《归还》—— 一枚曾被完整围绕的中心，正在被松开：
// 余烬剥落、坠下、归于下方无差别的均匀，与一条几乎看不见的水平线。

const CX = 760;            // 环心
const CY = 545;
const R  = 242;
const GAP  = 0.7853982;    // 断口方向（右下）
const CORE = GAP + PI;     // 最完整、最亮的方向（左上）

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  drawSky();          // 夜色底
  drawGhostOrbits();  // 更大轨道的残迹
  drawHaze();         // 尘雨间的呼吸
  drawDust(0);        // 远层尘埃
  drawRing();         // 断环
  drawDust(1);        // 近层尘埃
  drawShards();       // 先离开的碎片
  drawFloor();        // 均匀与水平线
  drawGrain();        // 全画颗粒
}

// ---------- 帮助 ----------
function mixA(c1, c2, t, al) {
  t = constrain(t, 0, 1);
  return color(c1[0] + (c2[0] - c1[0]) * t,
               c1[1] + (c2[1] - c1[1]) * t,
               c1[2] + (c2[2] - c1[2]) * t, al);
}

const SKY = [
  { y: 0,    c: [26, 29, 37] },
  { y: 560,  c: [19, 21, 28] },
  { y: 1250, c: [14, 15, 21] },
  { y: 2000, c: [12, 13, 18] },
];

function skyAt(y) {
  for (let i = 0; i < SKY.length - 1; i++) {
    if (y >= SKY[i].y && y <= SKY[i + 1].y) {
      const t = (y - SKY[i].y) / (SKY[i + 1].y - SKY[i].y);
      return [lerp(SKY[i].c[0], SKY[i + 1].c[0], t),
              lerp(SKY[i].c[1], SKY[i + 1].c[1], t),
              lerp(SKY[i].c[2], SKY[i + 1].c[2], t)];
    }
  }
  return SKY[SKY.length - 1].c;
}

// ---------- 底色：从微暖的夜空沉入均匀 ----------
function drawSky() {
  for (let y = 0; y < height; y++) {
    const c = skyAt(y);
    const n = (noise(3.1, y * 0.015) - 0.5) * 3;   // 极轻的水平肌理
    stroke(c[0] + n, c[1] + n, c[2] + n);
    strokeWeight(1);
    line(0, y, width, y);
  }
  noStroke();
}

// ---------- 上方：更大轨道的残迹 ----------
function drawGhostOrbits() {
  strokeCap(ROUND);
  const orbits = [
    { r: 385, a0: -1.25, a1: 0.55, al: 20 },
    { r: 385, a0: 2.35, a1: 3.35, al: 15 },
    { r: 545, a0: 1.85, a1: 3.55, al: 13 },
    { r: 545, a0: 4.35, a1: 5.25, al: 10 },
    { r: 730, a0: 3.90, a1: 4.65, al: 9 },
    { r: 730, a0: 0.15, a1: 1.05, al: 7 },
    { r: 980, a0: 0.90, a1: 1.62, al: 6 },
  ];
  for (const o of orbits) {
    const steps = int((o.a1 - o.a0) / 0.012);
    strokeWeight(1.4);
    for (let i = 0; i < steps; i++) {
      const a  = o.a0 + (o.a1 - o.a0) * (i / steps);
      const a2 = a + 0.014;
      const er = noise(a * 6.0 + o.r * 0.01);
      if (er < 0.36) continue;                     // 侵蚀出的缺口
      stroke(80, 86, 100, o.al * map(er, 0.36, 0.85, 0.3, 1));
      line(CX + o.r * cos(a), CY + o.r * sin(a),
           CX + o.r * cos(a2), CY + o.r * sin(a2));
    }
  }
}

// ---------- 尘雨之间大而软的雾团 ----------
function softBlob(x, y, d, col, maxA) {
  noStroke();
  const L = 5;
  for (let i = L; i >= 1; i--) {
    fill(col[0], col[1], col[2], maxA / (L * 1.7));
    ellipse(x, y, d * i / L, d * i / L * 0.75);
  }
}

function drawHaze() {
  for (let i = 0; i < 95; i++) {
    const x = CX + random(-430, 430);
    const y = random(600, 1650);
    const n = noise(x * 0.0022, y * 0.0022);
    const d = random(130, 430);
    if (n > 0.5) softBlob(x, y, d, [42, 46, 57], random(14, 26));
    else         softBlob(x, y, d, [8, 9, 12],  random(12, 22));
  }
}

// ---------- 环的“存活度”：从最完整到完全散尽 ----------
function ringAlive(a) {
  let al = 0.5 + 0.5 * cos(a - CORE);
  al += (noise(a * 5.3) - 0.5) * 0.22;
  return constrain(al, 0, 1);
}

function ringSeg(a, dl) {
  line(CX + R * cos(a), CY + R * sin(a),
       CX + R * cos(a + dl), CY + R * sin(a + dl));
}

// ---------- 断环 ----------
function drawRing() {
  strokeCap(ROUND);
  // 余温的光晕，只裹着还亮的那一段
  const halo = [{ w: 46, al: 12 }, { w: 92, al: 6 }, { w: 150, al: 3 }];
  for (const h of halo) {
    strokeWeight(h.w);
    stroke(124, 70, 40, h.al);
    for (let a = CORE - 1.5; a < CORE + 1.5; a += 0.02) {
      if (ringAlive(a) < 0.55) continue;
      ringSeg(a, 0.026);
    }
  }
  // 主体：一段实弧，一段碎裂，一段只剩散尘
  for (let a = 0; a < TWO_PI; a += 0.0045) {
    const alive = ringAlive(a);
    if (alive > 0.58) {
      const heat = pow(alive, 1.6) * (0.45 + 0.55 * max(0, cos(a - (CORE - 0.25))));
      const w = map(alive, 0.58, 1, 2.5, 13);
      stroke(mixA([98, 58, 36], [216, 152, 96], heat, 235));
      strokeWeight(w);
      ringSeg(a, 0.0052);
      if (heat > 0.42) {                            // 亮的内芯
        stroke(mixA([198, 118, 68], [248, 206, 152], heat, 220));
        strokeWeight(w * 0.45);
        ringSeg(a, 0.0052);
      }
    } else if (alive > 0.22) {                      // 正在剥落的区段
      if (noise(a * 7.3 + 50) > 0.42) {
        stroke(mixA([68, 50, 42], [152, 90, 54], alive * 0.55, 200));
        strokeWeight(map(alive, 0.22, 0.58, 1.2, 4));
        ringSeg(a, 0.004);
      }
      if (random() < alive * 0.5) {                 // 带着小坠尾的碎屑
        const px = CX + R * cos(a) + random(-8, 8) + random(30) * cos(a);
        const py = CY + R * sin(a) + random(4, 44) + random(18) * sin(a);
        stroke(mixA([58, 52, 50], [134, 82, 48], random(), random(30, 130)));
        strokeWeight(random(1, 2.4));
        line(px, py - random(2, 9), px, py);
      }
    } else {                                        // 断口处残余的稀尘
      if (random() < 0.1 + alive * 0.3) {
        const px = CX + (R + random(6, 70)) * cos(a);
        const py = CY + (R + random(0, 44)) * sin(a) + random(0, 50);
        stroke(74, 76, 84, random(14, 60));
        strokeWeight(random(0.8, 1.8));
        point(px, py);
      }
    }
  }
}

// ---------- 尘雨 ----------
function fadeY(y) {
  return map(y, 400, 780, 0.75, 1, true) * map(y, 1450, 1860, 1, 0, true);
}

function drawDust(layer) {
  strokeCap(ROUND);
  const N = layer === 0 ? 2100 : 2500;
  const segs = layer === 0 ? 3 : 6;
  for (let i = 0; i < N; i++) {
    const a = random(-0.55, 2.75);                  // 源自环的下缘
    const rr = R + random(-16, 30);
    const x0 = CX + rr * cos(a) + random(-14, 14);
    const y0 = CY + rr * sin(a) + random(-6, 30);
    const len = layer === 0 ? random(30, 320) : random(60, 640);
    const spread = random(-1, 1) * random(30, 320); // 缓缓散开
    const depth = random();
    const warmA = 0.5 + 0.5 * cos(a - 3.4);         // 离亮段越近越暖
    let lastX = x0;
    for (let s = 1; s <= segs; s++) {
      const t1 = s / segs;
      const y1 = y0 + len * t1;
      const yP = y0 + len * (s - 1) / segs;
      const ease = 1 - pow(1 - t1, 2.2);
      const nx = x0 + spread * ease + (noise(a * 4.0 + t1 * 2.5, i * 0.03) - 0.5) * 46;
      const warm = warmA * pow(1 - t1, 1.8) * (layer === 0 ? 0.5 : 0.85);
      const br = 0.4 + 0.6 * depth;
      const al = (layer === 0 ? 46 : 92) * br * fadeY(y1) * (0.45 + 0.55 * pow(1 - t1, 0.6));
      stroke(mixA([40, 43, 52], [126, 76, 46], warm * br + random(0, 0.08), al));
      strokeWeight(layer === 0 ? 1 : (1.3 + 1.3 * depth * (1 - t1)));
      line(lastX, yP, nx, y1);
      lastX = nx;
    }
    if (layer === 1 && depth > 0.94 && warmA > 0.2) { // 少数未熄的火种
      stroke(226, 158, 98, random(90, 170) * fadeY(y0));
      strokeWeight(random(1.6, 2.6));
      point(x0 + random(-4, 4), y0 + random(0, 14));
    }
  }
}

// ---------- 最先离开的几块碎片 ----------
function drawShards() {
  const shards = [
    { a: 0.55, off: 34, len: 560, w: 4.2 },
    { a: 1.35, off: 48, len: 700, w: 3.4 },
    { a: 1.85, off: 22, len: 430, w: 2.6 },
    { a: 0.05, off: 62, len: 520, w: 3.0 },
  ];
  strokeCap(ROUND);
  for (const s of shards) {
    const x0 = CX + (R + s.off) * cos(s.a);
    const y0 = CY + (R + s.off) * sin(s.a);
    const drift = random(-90, 90);
    const segs = 14;
    let lx = x0, ly = y0;
    for (let i = 1; i <= segs; i++) {
      const t = i / segs;
      const x = x0 + drift * t * t + (noise(s.a * 3.0 + t * 2.0, 7.7) - 0.5) * 30 * t;
      const y = y0 + s.len * t;
      const heat = pow(t, 1.4);                     // 前端最亮，坠向下
      stroke(mixA([68, 46, 38], [240, 174, 110], heat, 40 + 210 * heat * fadeY(y)));
      strokeWeight(0.8 + s.w * heat);
      line(lx, ly, x, y);
      lx = x; ly = y;
    }
    noStroke();
    fill(246, 208, 150, 235 * fadeY(ly));
    ellipse(lx, ly, 5.5, 9);
    fill(255, 238, 204, 120 * fadeY(ly));
    ellipse(lx, ly, 2.5, 4.5);
  }
}

// ---------- 底部：压平、沉积与那条水平线 ----------
function drawFloor() {
  noStroke();
  for (let y = 1560; y < height; y += 2) {          // 差异被缓缓抹去
    const k = map(y, 1560, 1900, 0, 1, true);
    fill(12, 13, 17, k * 235);
    rect(0, y, width, 2);
  }
  for (let i = 0; i < 20000; i++) {                 // 均匀的沉积颗粒
    const y = random() < 0.55 ? random(1712, 1860) : random(1860, 1996);
    const x = random(width);
    const depth = map(y, 1712, 1996, 1, 0.45);
    let c = mixA([30, 32, 38], [58, 60, 68], random() * depth, random(18, 70) * depth);
    if (y < 1802 && random() < 0.06) {              // 一点未散尽的温
      c = mixA([56, 44, 36], [96, 62, 42], random(), random(20, 60));
    }
    fill(c);
    rect(x, y, random(1, 2.3), random(1, 2.3));
  }
  const LY = 1856;                                  // 一切沉降的终点
  for (const dy of [0, -5, 4]) {
    const step = dy === 0 ? 3 : 4;
    for (let x = 0; x < width; x += step) {
      const n = noise(x * 0.012 + dy * 31, 9.7);
      if (n < (dy === 0 ? 0.36 : 0.5)) continue;
      const al = dy === 0 ? map(n, 0.36, 0.9, 5, 30) : map(n, 0.5, 0.95, 3, 13);
      stroke(86, 90, 101, al);
      strokeWeight(dy === 0 ? 1.3 : 1);
      line(x, LY + dy, x + step + 0.6, LY + dy);
    }
  }
}

// ---------- 全画面颗粒：像版画的呼吸 ----------
function drawGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = (random() * 2 - 1) * 5.5;
    let v = pixels[i] + g;     pixels[i]     = v < 0 ? 0 : (v > 255 ? 255 : v);
    v = pixels[i + 1] + g;     pixels[i + 1] = v < 0 ? 0 : (v > 255 ? 255 : v);
    v = pixels[i + 2] + g;     pixels[i + 2] = v < 0 ? 0 : (v > 255 ? 255 : v);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const W = 1600, H = 2000;
  const cx = 800;
  const groundY = 1560;
  const ctx = drawingContext;

  // ---------- background ----------
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0.0, '#020207');
  g.addColorStop(0.42, '#090916');
  g.addColorStop(0.72, '#100e1c');
  g.addColorStop(1.0, '#171221');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // distant dust
  noStroke();
  for (let i = 0; i < 380; i++) {
    const x = random(W), y = random(H * 0.72);
    const b = random(120, 255);
    fill(random() < 0.85 ? b : 255, b, 255, random(3, 16));
    circle(x, y, random(0.6, 2.4));
  }

  // nebula wisps near the top
  radialGlow(cx - 150, 260, 520, color(110, 85, 190, 10));
  radialGlow(cx + 180, 430, 420, color(85, 65, 150, 9));
  radialGlow(cx, 300, 460, color(255, 190, 110, 26));
  radialGlow(cx, 300, 240, color(255, 225, 175, 40));

  // faint light shaft from the eclipse down toward the figure
  let shaft = ctx.createLinearGradient(0, 320, 0, 1500);
  shaft.addColorStop(0, 'rgba(255,215,160,0.07)');
  shaft.addColorStop(1, 'rgba(255,215,160,0)');
  ctx.fillStyle = shaft;
  ctx.beginPath();
  ctx.moveTo(cx - 46, 322);
  ctx.lineTo(cx + 46, 322);
  ctx.lineTo(cx + 330, 1500);
  ctx.lineTo(cx - 330, 1500);
  ctx.closePath();
  ctx.fill();

  // horizon glow
  radialGlow(cx, groundY, 950, color(255, 175, 105, 13));
  radialGlow(cx, groundY, 480, color(255, 205, 140, 12));
  noStroke();
  fill(255, 215, 160, 7);
  ellipse(cx, groundY, 1050, 30);
  fill(255, 225, 180, 10);
  ellipse(cx, groundY, 520, 14);

  // ---------- the figure (offscreen so its top can dissolve) ----------
  const fig = createGraphics(W, H);
  drawFigure(fig, fig.color(255, 198, 128, 150), -7, 0); // rim light
  drawFigure(fig, fig.color(5, 5, 9), 0, 0);              // body
  fig.drawingContext.globalCompositeOperation = 'destination-out';
  const eg = fig.drawingContext.createLinearGradient(0, 758, 0, 1035);
  eg.addColorStop(0, 'rgba(0,0,0,1)');
  eg.addColorStop(0.6, 'rgba(0,0,0,0.55)');
  eg.addColorStop(1, 'rgba(0,0,0,0)');
  fig.drawingContext.fillStyle = eg;
  fig.drawingContext.fillRect(0, 758, W, 1035 - 758);
  fig.drawingContext.globalCompositeOperation = 'source-over';

  image(fig, 0, 0);

  // reflection of the figure on the dark ground
  push();
  translate(0, groundY * 2);
  scale(1, -1);
  globalAlpha(0.10);
  image(fig, 0, 0);
  globalAlpha(1);
  pop();

  // ---------- particles: the dissolved self ----------
  const parts = [];
  let tries = 0;
  while (parts.length < 1050 && tries < 30000) {
    tries++;
    const x = random(cx - 150, cx + 150);
    const y = random(772, 1090);
    if (!inUpperBody(x, y)) continue;
    const maxR = random() < 0.7 ? random(240, 760) : random(760, 1330);
    const roll = random();
    const col = roll < 0.62 ? [255, 203, 138] : roll < 0.8 ? [255, 240, 212] : [172, 198, 255];
    parts.push({
      sx: x, sy: y, rise: random(30, maxR), maxR: maxR,
      sway: random(0.5, 2.4), nOff: random(10000),
      s: random(1.1, 4.6), col: col, tw: random(TWO_PI)
    });
  }

  // particle reflections on the ground (before the ground fade)
  for (const p of parts) {
    const py = p.sy - p.rise;
    const ry = groundY + (groundY - py) * 0.22;
    if (ry > H - 4) continue;
    noStroke();
    fill(p.col[0], p.col[1], p.col[2], 16);
    circle(particleX(p), ry, p.s * 0.7);
  }

  // ground fade
  let gf = ctx.createLinearGradient(0, groundY, 0, H);
  gf.addColorStop(0, 'rgba(6,5,11,0.25)');
  gf.addColorStop(1, 'rgba(3,2,7,0.88)');
  ctx.fillStyle = gf;
  ctx.fillRect(0, groundY, W, H - groundY);

  // mist
  noStroke();
  for (let i = 0; i < 7; i++) {
    fill(220, 225, 240, random(4, 9));
    ellipse(cx + random(-260, 260), groundY + random(-6, 90), random(520, 1500), random(26, 64));
  }

  // soft glow around the dissolve zone
  radialGlow(cx, 990, 300, color(255, 200, 140, 12));

  // ---------- the eclipse ----------
  noStroke();
  fill(2, 2, 7);
  circle(cx, 300, 292);
  noFill();
  stroke(255, 216, 152, 210);
  strokeWeight(3.5);
  circle(cx, 300, 297);
  stroke(255, 185, 105, 70);
  strokeWeight(13);
  circle(cx, 300, 301);
  stroke(255, 165, 85, 24);
  strokeWeight(36);
  circle(cx, 300, 307);

  // ---------- rising particles ----------
  for (const p of parts) {
    const py = p.sy - p.rise;
    const px = particleX(p);
    let a = 150 + 95 * sin(p.tw + p.rise * 0.02);
    if (py < 540) a *= map(py, 540, 290, 1, 0.22, true);
    if (p.s > 3.3) {
      radialGlow(px, py, p.s * 6.5, color(p.col[0], p.col[1], p.col[2], a * 0.32));
    }
    noStroke();
    fill(p.col[0], p.col[1], p.col[2], a);
    circle(px, py, p.s);
  }

  // ---------- vignette ----------
  const vg = ctx.createRadialGradient(W / 2, H * 0.46, H * 0.22, W / 2, H * 0.5, H * 0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  // ---------- grain ----------
  noStroke();
  for (let i = 0; i < 22000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) fill(255, 255, 255, random(2, 7));
    else fill(0, 0, 0, random(3, 9));
    rect(x, y, 1.2, 1.2);
  }
}

function particleX(p) {
  const k = p.rise / p.maxR;
  return p.sx + (noise(p.nOff, p.rise * 0.008) - 0.5) * 70 * p.sway + (800 - p.sx) * 0.45 * k;
}

function radialGlow(x, y, r, c) {
  const ctx = drawingContext;
  const rg = ctx.createRadialGradient(x, y, 0, x, y, r);
  rg.addColorStop(0, 'rgba(' + round(red(c)) + ',' + round(green(c)) + ',' + round(blue(c)) + ',' + (alpha(c) / 255) + ')');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function inEllipse(x, y, ex, ey, rx, ry) {
  const dx = (x - ex) / rx, dy = (y - ey) / ry;
  return dx * dx + dy * dy <= 1;
}

function inUpperBody(x, y) {
  return inEllipse(x, y, 800, 850, 62, 72) ||
         inEllipse(x, y, 800, 1005, 120, 138) ||
         inEllipse(x, y, 686, 1065, 27, 155) ||
         inEllipse(x, y, 914, 1065, 27, 155);
}

function drawFigure(pg, col, dx, dy) {
  pg.noStroke();
  pg.fill(col);
  const cx = 800 + dx;
  // legs
  pg.ellipse(cx - 42, 1372, 58, 300);
  pg.ellipse(cx + 42, 1372, 58, 300);
  // feet
  pg.ellipse(cx - 50, 1548, 74, 26);
  pg.ellipse(cx + 50, 1548, 74, 26);
  // hips
  pg.ellipse(cx, 1240, 190, 70);
  // torso
  pg.beginShape();
  pg.vertex(cx - 106, 952);
  pg.bezierVertex(cx - 120, 1065, cx - 96, 1165, cx - 88, 1235);
  pg.vertex(cx + 88, 1235);
  pg.bezierVertex(cx + 96, 1165, cx + 120, 1065, cx + 106, 952);
  pg.bezierVertex(cx + 58, 926, cx - 58, 926, cx - 106, 952);
  pg.endShape(CLOSE);
  // neck
  pg.rect(cx - 21, 892, 42, 62);
  // head
  pg.ellipse(cx, 850, 106, 126);
  // arms
  pg.push();
  pg.translate(cx - 113, 962);
  pg.rotate(0.17);
  pg.ellipse(0, 195, 42, 385);
  pg.pop();
  pg.push();
  pg.translate(cx + 113, 962);
  pg.rotate(-0.17);
  pg.ellipse(0, 195, 42, 385);
  pg.pop();
}

const W = 1600, H = 2000;

// silhouette of a seated figure, built from soft ellipses
const SHAPES = [
  { x: 800, y: 905,  rx: 66,  ry: 74,  a: 0    },  // head
  { x: 800, y: 1000, rx: 55,  ry: 45,  a: 0    },  // neck
  { x: 800, y: 1045, rx: 170, ry: 70,  a: 0    },  // shoulders
  { x: 800, y: 1180, rx: 115, ry: 140, a: 0    },  // torso
  { x: 800, y: 1330, rx: 200, ry: 110, a: 0    },  // hips
  { x: 800, y: 1400, rx: 270, ry: 90,  a: 0    },  // folded base
  { x: 640, y: 1170, rx: 40,  ry: 125, a: 0.32 },  // left arm
  { x: 960, y: 1170, rx: 40,  ry: 125, a: -0.32 }  // right arm
];

function ellipseHit(x, y, s) {
  const dx = x - s.x, dy = y - s.y;
  const c = cos(s.a), sn = sin(s.a);
  const lx = dx * c + dy * sn, ly = -dx * sn + dy * c;
  return (lx * lx) / (s.rx * s.rx) + (ly * ly) / (s.ry * s.ry) < 1;
}

function inFigure(x, y) {
  for (const s of SHAPES) if (ellipseHit(x, y, s)) return true;
  return false;
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
}

function draw() {
  noLoop();
  const ctx = drawingContext;

  // ---- night sky ----
  let sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0, '#07070d');
  sky.addColorStop(0.55, '#0d0c16');
  sky.addColorStop(1, '#131019');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  // ---- distant stars ----
  noStroke();
  for (let i = 0; i < 260; i++) {
    const y = random(0, H * 0.55);
    fill(255, 255, 255, random(20, 130) * (1 - y / (H * 0.6)));
    circle(random(0, W), y, random(0.6, 2.2));
  }

  // ---- the pale void (moon / halo) ----
  let glow = ctx.createRadialGradient(800, 920, 60, 800, 920, 660);
  glow.addColorStop(0, 'rgba(178,171,190,0.55)');
  glow.addColorStop(0.5, 'rgba(160,153,175,0.25)');
  glow.addColorStop(1, 'rgba(150,143,168,0)');
  ctx.fillStyle = glow;
  ctx.beginPath(); ctx.arc(800, 920, 660, 0, TWO_PI); ctx.fill();

  let disc = ctx.createRadialGradient(800, 920, 80, 800, 920, 365);
  disc.addColorStop(0, 'rgba(188,181,201,0.85)');
  disc.addColorStop(0.75, 'rgba(172,165,188,0.72)');
  disc.addColorStop(1, 'rgba(160,153,178,0)');
  ctx.fillStyle = disc;
  ctx.beginPath(); ctx.arc(800, 920, 365, 0, TWO_PI); ctx.fill();

  // ---- ground ----
  let gr = ctx.createLinearGradient(0, 1350, 0, H);
  gr.addColorStop(0, 'rgba(10,9,14,0)');
  gr.addColorStop(0.35, '#0b0a10');
  gr.addColorStop(1, '#050408');
  ctx.fillStyle = gr;
  ctx.fillRect(0, 1350, W, H - 1350);

  let gg = ctx.createRadialGradient(800, 1420, 20, 800, 1420, 430);
  gg.addColorStop(0, 'rgba(190,180,170,0.10)');
  gg.addColorStop(1, 'rgba(190,180,170,0)');
  ctx.fillStyle = gg;
  ctx.beginPath(); ctx.ellipse(800, 1420, 430, 130, 0, TWO_PI); ctx.fill();

  noFill();
  for (let i = 0; i < 7; i++) {
    stroke(200, 190, 180, 5 + i * 3);
    strokeWeight(1.5);
    ellipse(800, 1470 + i * 72, 500 + i * 260, (500 + i * 260) * 0.16);
  }

  // ---- warm halo behind the figure's upper body ----
  let halo = ctx.createRadialGradient(800, 990, 30, 800, 990, 430);
  halo.addColorStop(0, 'rgba(255,222,175,0.10)');
  halo.addColorStop(1, 'rgba(255,222,175,0)');
  ctx.fillStyle = halo;
  ctx.beginPath(); ctx.arc(800, 990, 430, 0, TWO_PI); ctx.fill();

  // ---- dissolving particles (drawn before the body so origins hide inside it) ----
  const parts = [];
  let attempts = 0;
  while (parts.length < 1700 && attempts < 300000) {
    attempts++;
    const sx = random(430, 1170), sy = random(690, 1410);
    if (!inFigure(sx, sy) || sy > 1300) continue;
    const edge = !inFigure(sx + (random() < 0.5 ? 24 : -24), sy)
              || !inFigure(sx, sy - 24)
              || !inFigure(sx, sy + 24);
    if (!edge && random() < 0.72) continue;           // dissolve happens at the boundary
    const hf = constrain((1300 - sy) / 640, 0, 1);     // 1 near the head
    const drift = pow(random(), 1.7) * (160 + hf * 820);
    const lat = (noise(sx * 0.004 + 37.7, sy * 0.004) - 0.5) * drift * 1.3 + drift * 0.12;
    const px = sx + lat, py = sy - drift;
    if (py < -60) continue;
    let c;
    if (py > 560) {  // over the pale void: deep amber
      c = lerpColor(color(255, 196, 120), color(210, 138, 68), random());
    } else {         // in the dark sky: white gold to pale blue
      c = random() < 0.75
        ? lerpColor(color(255, 248, 236), color(255, 224, 168), random())
        : color(185, 205, 255);
    }
    const fade = pow(constrain(map(py, 1250, 280, 0, 1), 0, 1), 0.8);
    const al = (0.35 + random() * 0.6) * fade;
    if (al < 0.03) continue;
    parts.push({
      x: px, y: py,
      d: random(1, 4.2) * (1 - hf * 0.4) * 2 + (edge ? 0.8 : 0),
      r: red(c), g: green(c), b: blue(c), al: al * 255
    });
  }

  noStroke();
  for (const p of parts) {
    fill(p.r, p.g, p.b, p.al);
    circle(p.x, p.y, p.d);
  }

  // ---- a few larger glowing embers ----
  for (let i = 0; i < 70; i++) {
    const p = parts[floor(random(parts.length))];
    if (p.y > 780) continue;
    let eg = ctx.createRadialGradient(p.x, p.y, 0, p.x, p.y, p.d * 4);
    eg.addColorStop(0, `rgba(${p.r},${p.g},${p.b},${p.al * 0.35})`);
    eg.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = eg;
    ctx.beginPath(); ctx.arc(p.x, p.y, p.d * 4, 0, TWO_PI); ctx.fill();
  }

  // ---- the body itself: dark silhouette against the void ----
  fill(8, 8, 13);
  noStroke();
  for (const s of SHAPES) {
    push();
    translate(s.x, s.y);
    rotate(s.a);
    ellipse(0, 0, s.rx * 2, s.ry * 2);
    pop();
  }
  noFill();
  stroke(205, 195, 215, 36);
  strokeWeight(2);
  for (const s of SHAPES) {
    push();
    translate(s.x, s.y);
    rotate(s.a);
    ellipse(0, 0, s.rx * 2, s.ry * 2);
    pop();
  }

  // ---- falling ash ----
  noStroke();
  for (let i = 0; i < 140; i++) {
    fill(160, 158, 168, random(15, 60));
    circle(random(0, W), random(0, H), random(1, 3));
  }

  // ---- film grain ----
  for (let i = 0; i < 9000; i++) {
    const g = random();
    fill(g < 0.5 ? 255 : 0, 255, 255, random(3, 9));
    rect(random(W), random(H), 1.4, 1.4);
  }

  // ---- vignette ----
  let vg = ctx.createRadialGradient(800, 950, 480, 800, 1000, 1300);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

