function distSeg(px, py, x1, y1, x2, y2) {
  let dx = x2 - x1, dy = y2 - y1;
  let l2 = dx * dx + dy * dy;
  let t = ((px - x1) * dx + (py - y1) * dy) / l2;
  t = max(0, min(1, t));
  return dist(px, py, x1 + t * dx, y1 + t * dy);
}

function inFigure(x, y) {
  let e = ((x - 800) / 95) * ((x - 800) / 95) + ((y - 610) / 115) * ((y - 610) / 115);
  if (e <= 1) return true;                                            // head
  if (abs(x - 800) < 46 && y > 690 && y < 835) return true;           // neck
  e = ((x - 800) / 185) * ((x - 800) / 185) + ((y - 1010) / 270) * ((y - 1010) / 270);
  if (e <= 1) return true;                                            // torso
  if (distSeg(x, y, 700, 830, 638, 1180) < 42) return true;           // left arm
  if (distSeg(x, y, 900, 830, 985, 685) < 40) return true;            // right upper arm
  if (distSeg(x, y, 985, 685, 1040, 500) < 30) return true;           // raised forearm
  if (distSeg(x, y, 752, 1240, 732, 1530) < 58) return true;          // left leg
  if (distSeg(x, y, 848, 1240, 868, 1530) < 58) return true;          // right leg
  return false;
}

function root(x, y, ang, len, w, depth) {
  if (depth <= 0 || w < 0.7) {
    noStroke();
    fill(232, 202, 142, 80);
    ellipse(x, y, 2.6, 2.6);
    return;
  }
  let nx = x + cos(ang) * len;
  let ny = y + sin(ang) * len;
  let c = lerpColor(color(50, 37, 25), color(160, 118, 72), depth / 7);
  stroke(red(c), green(c), blue(c), 215);
  strokeWeight(w);
  line(x, y, nx, ny);
  let n = random() < 0.35 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    root(nx, ny, ang + random(-0.75, 0.75), len * random(0.68, 0.85), w * 0.7, depth - 1);
  }
}

function draw() {
  // sky / earth gradient
  for (let y = 0; y < height; y++) {
    let c;
    if (y < 1560) {
      let t = y / 1560;
      let top = color(7, 9, 24), mid = color(46, 33, 86), low = color(18, 13, 26);
      c = t < 0.55 ? lerpColor(top, mid, t / 0.55) : lerpColor(mid, low, (t - 0.55) / 0.45);
    } else {
      let t = (y - 1560) / (height - 1560);
      c = lerpColor(color(25, 19, 23), color(9, 7, 6), t);
    }
    stroke(c);
    line(0, y, width, y);
  }
  noStroke();

  // nebula clouds
  for (let i = 0; i < 90; i++) {
    let x = random(width), y = random(-120, 1150), r = random(140, 460);
    let p = random();
    let c = p < 0.5 ? color(72, 54, 132, 13) : p < 0.8 ? color(42, 62, 122, 11) : color(122, 82, 152, 9);
    fill(c);
    ellipse(x, y, r, r * random(0.5, 0.9));
  }

  // stars
  for (let i = 0; i < 1100; i++) {
    let y = pow(random(1), 1.7) * 1500;
    let x = random(width);
    let s = random(0.6, 2.6);
    let a = random(80, 255);
    let p = random();
    let c = p < 0.7 ? color(235, 240, 255, a) : p < 0.9 ? color(170, 195, 255, a) : color(255, 220, 170, a);
    if (random() < 0.05) {
      fill(200, 215, 255, 26);
      ellipse(x, y, s * 7, s * 7);
    }
    fill(c);
    ellipse(x, y, s, s);
  }

  // light beam from moon to earth
  let mx = 800, my = 350, mr = 200;
  for (let i = 0; i < 8; i++) {
    fill(244, 236, 220, 4);
    beginShape();
    vertex(mx - 65 + random(-8, 8), my + mr * 0.55);
    vertex(mx + 65 + random(-8, 8), my + mr * 0.55);
    vertex(800 + 430 + random(-30, 30), 1580);
    vertex(800 - 430 + random(-30, 30), 1580);
    endShape(CLOSE);
  }

  // moon
  for (let r = 540; r > mr; r -= 10) {
    fill(244, 236, 220, map(r, mr, 540, 42, 2));
    ellipse(mx, my, r, r);
  }
  fill(246, 239, 226, 235);
  ellipse(mx, my, mr, mr);
  fill(120, 110, 140, 26);
  ellipse(mx + 50, my + 62, mr * 1.7, mr * 1.5);
  fill(150, 140, 165, 18);
  ellipse(mx - 55, my - 35, 55, 46);
  ellipse(mx + 28, my + 70, 72, 54);
  ellipse(mx + 62, my - 80, 36, 30);
  noFill();
  stroke(244, 236, 220, 18);
  strokeWeight(2);
  ellipse(mx, my, mr + 40, mr + 40);
  noStroke();

  // horizon mist
  for (let i = 0; i < 6; i++) {
    fill(240, 232, 214, 5);
    ellipse(800, 1560, random(900, 1500), random(40, 90));
  }

  // figure soft core
  fill(238, 229, 210, 15);
  ellipse(800, 1010, 370, 540);
  fill(238, 229, 210, 16);
  ellipse(800, 610, 190, 230);

  // figure dissolving into particles (solid below, scattering upward)
  for (let i = 0; i < 26000; i++) {
    let x = random(590, 1010), y = random(460, 1540);
    if (!inFigure(x, y)) continue;
    let d = constrain(map(y, 1540, 700, 1, 0), 0, 1);
    d = constrain(pow(d, 1.3) * (0.55 + 0.45 * noise(x * 0.01, y * 0.01)), 0, 1);
    if (random() > d) continue;
    let s = random(1, 4.2);
    let c = lerpColor(color(239, 231, 214), color(216, 179, 106), random());
    fill(red(c), green(c), blue(c), random(50, 170) * d + 25);
    ellipse(x, y, s, s);
  }

  // rising motes drifting into the moon
  for (let i = 0; i < 2600; i++) {
    let t = random(1);
    let y = lerp(1500, 150, t);
    let spread = lerp(50, 430, pow(t, 1.5));
    let x = 800 + random(-spread, spread) + noise(i * 0.1, t * 5) * 40 - 20;
    x = lerp(x, mx, t * t * 0.65);
    let s = random(0.8, 3);
    let c = lerpColor(color(244, 236, 220), color(255, 214, 150), random());
    fill(red(c), green(c), blue(c), random(40, 150) * (1 - t * 0.4));
    ellipse(x, y, s, s);
  }

  // roots into the earth
  strokeCap(ROUND);
  root(800, 1500, PI / 2 + random(-0.15, 0.15), 60, 11, 7);
  root(735, 1510, PI / 2 + random(-0.3, 0.3), 55, 10, 7);
  root(865, 1510, PI / 2 + random(-0.3, 0.3), 55, 10, 7);
  for (let i = 0; i < 5; i++) {
    root(760 + random(-40, 40), 1520, PI / 2 + random(-0.5, 0.5), 42, 5, 5);
  }
  noStroke();

  // grass silhouettes
  stroke(62, 50, 36, 90);
  strokeWeight(1.6);
  for (let i = 0; i < 160; i++) {
    let x = random(width), y0 = random(1620, 2000), h = random(15, 80);
    line(x, y0, x + random(-14, 14), y0 - h);
  }
  noStroke();

  // film grain
  for (let i = 0; i < 26000; i++) {
    let x = random(width), y = random(height);
    if (random() < 0.5) fill(255, 255, 255, random(2, 6));
    else fill(0, 0, 0, random(3, 8));
    ellipse(x, y, 1, 1);
  }

  // vignette
  let vg = drawingContext.createRadialGradient(800, 980, 500, 800, 1000, 1350);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.55)');
  drawingContext.fillStyle = vg;
  drawingContext.fillRect(0, 0, width, height);
}

