function draw(){
  let ctx = drawingContext;
  background(12, 10, 18);

  // sky: pale dying light above, deepening dark below
  for(let y = 0; y < height; y++){
    let t = y / height;
    let c = lerpColor(color(226, 212, 188), color(12, 10, 18), pow(t, 1.7));
    stroke(c);
    line(0, y, width, y);
  }

  // the last glow around the void
  let g = ctx.createRadialGradient(800, 740, 40, 800, 740, 780);
  g.addColorStop(0.00, 'rgba(255, 238, 200, 0.95)');
  g.addColorStop(0.30, 'rgba(246, 214, 160, 0.50)');
  g.addColorStop(0.62, 'rgba(210, 170, 140, 0.16)');
  g.addColorStop(1.00, 'rgba(210, 170, 140, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // faint halo rings
  noFill();
  for(let r = 372; r < 580; r += 6){
    let a = map(r, 372, 580, 26, 0);
    stroke(255, 230, 190, a);
    strokeWeight(1.4);
    circle(800, 740, r * 2);
  }

  // rising embers / dissolving sparks
  for(let i = 0; i < 1600; i++){
    let x = width/2 + (random(-1, 1) + random(-1, 1)) * 0.5 * 950;
    let y = random(0, height);
    let d = dist(x, y, 800, 740);
    let near = constrain(map(d, 520, 60, 0, 1), 0, 1);
    let fade = 1 - (y / height) * 0.75;
    let a = (30 + random(130)) * fade * (0.35 + 0.65 * near);
    if(a < 4) continue;
    let col = lerpColor(color(255, 214, 150), color(235, 238, 255), random(1));
    stroke(red(col), green(col), blue(col), a);
    strokeWeight(random(1, 2.6));
    let len = 4 + random(16) * (0.4 + near);
    line(x, y, x + (noise(i * 0.01) - 0.5) * 10, y - len);
  }

  // the void itself
  noStroke();
  fill(7, 5, 11);
  circle(800, 740, 660);

  // corona: light leaking around the edge
  for(let i = 0; i < 900; i++){
    let ang = random(TWO_PI);
    let r0 = 332;
    let len = 6 + pow(noise(i * 0.02, 3), 2) * 90 + random(18);
    let a = 20 + random(120) * (0.5 + 0.5 * noise(i * 0.05));
    stroke(255, 232, 190, a);
    strokeWeight(random(0.6, 2.2));
    line(800 + cos(ang) * r0, 740 + sin(ang) * r0,
         800 + cos(ang) * (r0 + len), 740 + sin(ang) * (r0 + len));
  }

  // bright rim across the top of the void
  noFill();
  for(let i = 0; i < 70; i++){
    let ang = map(i, 0, 70, PI * 1.15, PI * 1.55);
    let a = map(i, 0, 70, 170, 15);
    stroke(255, 244, 220, a);
    strokeWeight(2.6);
    arc(800, 740, 666 + i * 0.6, 666 + i * 0.6, ang, ang + 0.05);
  }

  // one tilted orbit ring passing in front
  noFill();
  stroke(255, 235, 200, 22);
  strokeWeight(1.2);
  push();
  translate(800, 740);
  rotate(-0.35);
  ellipse(0, 0, 980, 300);
  pop();

  // distant hills
  noStroke();
  fill(28, 23, 36);
  beginShape();
  vertex(0, height);
  vertex(0, 1680);
  for(let x = 0; x <= width; x += 10){
    vertex(x, 1680 + noise(x * 0.004, 7) * 90 - 40);
  }
  vertex(width, height);
  endShape(CLOSE);

  // near ground
  fill(10, 8, 15);
  beginShape();
  vertex(0, height);
  vertex(0, 1800);
  for(let x = 0; x <= width; x += 8){
    vertex(x, 1800 + noise(x * 0.006, 13) * 160 - 60);
  }
  vertex(width, height);
  endShape(CLOSE);

  // last light at the horizon
  let gh = ctx.createLinearGradient(0, 1620, 0, 1720);
  gh.addColorStop(0, 'rgba(255, 230, 180, 0)');
  gh.addColorStop(0.5, 'rgba(255, 230, 180, 0.20)');
  gh.addColorStop(1, 'rgba(255, 230, 180, 0)');
  ctx.fillStyle = gh;
  ctx.fillRect(0, 1620, width, 100);

  // film grain
  noStroke();
  for(let i = 0; i < 26000; i++){
    fill(random(1) > 0.5 ? 255 : 0, random(3, 12));
    rect(random(width), random(height), random(0.6, 1.8), random(0.6, 1.8));
  }

  // vignette
  let vg = ctx.createRadialGradient(800, 900, 500, 800, 1000, 1350);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const W = width, H = height;
  const cx = W / 2;
  const hy = H * 0.62;          // horizon line
  const sx = cx, sy = hy - 55;  // the sinking light

  background(6, 7, 14);

  // --- sky gradient, painterly bands ---
  noStroke();
  for (let y = 0; y < hy; y += 3) {
    const t = y / hy;
    const n = (noise(y * 0.0016, 7.7) - 0.5) * 16;
    fill(lerp(20, 10, t) + n, lerp(21, 10, t) + n, lerp(42, 20, t) + n * 1.6);
    rect(0, y, W, 3);
  }

  // --- nebula clouds ---
  for (let i = 0; i < 800; i++) {
    const x = random(W);
    const y = random(hy);
    const s = random(60, 340);
    const w = random();
    const a = random(3, 8);
    if (w < 0.22) fill(255, 196, 148, a);
    else if (w < 0.55) fill(96, 72, 156, a);
    else fill(44, 62, 122, a);
    ellipse(x, y, s, s * random(0.35, 0.75));
  }

  // --- stars ---
  for (let i = 0; i < 300; i++) {
    fill(222, 228, 255, random(15, 130));
    const s = random(0.5, 2.4);
    ellipse(random(W), random(hy * 0.92), s, s);
  }

  // --- the light: layered glow ---
  noStroke();
  for (let r = 420; r > 0; r -= 4) {
    const f = 1 - r / 420;
    fill(255, 205, 150, 55 * pow(f, 2.4));
    ellipse(sx, sy, r * 2, r * 2);
  }
  for (let r = 170; r > 0; r -= 3) {
    const f = 1 - r / 170;
    fill(255, 236, 200, 130 * pow(f, 2));
    ellipse(sx, sy, r * 2, r * 2);
  }
  for (let r = 70; r > 0; r -= 2) {
    const f = 1 - r / 70;
    fill(255, 250, 236, 210 * pow(f, 2));
    ellipse(sx, sy, r * 2, r * 2);
  }

  // --- still water: occludes the lower half of the light ---
  for (let y = hy; y < H; y += 3) {
    const n = (noise(y * 0.01, 3.3) - 0.5) * 10;
    noStroke();
    fill(4 + n * 0.3, 5 + n * 0.3, 12 + n, 235);
    rect(0, y, W, 3);
  }

  // --- sheen along the horizon ---
  for (let i = 0; i < 260; i++) {
    const x = cx + randomGaussian() * 560;
    const a = 34 * (1 - min(1, abs(x - cx) / 560)) * random(0.3, 1);
    stroke(255, 214, 168, a);
    strokeWeight(random(1, 2.5));
    line(x, hy + random(-2, 2), x + random(-26, 26), hy + random(-2, 2));
  }

  // --- broken reflection of the light on the water ---
  for (let i = 0; i < 520; i++) {
    const y = hy + 4 + random(H - hy - 8);
    const spread = 40 + ((y - hy) / (H - hy)) * 380;
    const x = cx + randomGaussian() * spread;
    const len = random(10, 70) * (1 - (y - hy) / (H - hy) * 0.55);
    const a = random(5, 26) * (1 - (y - hy) / (H - hy) * 0.55);
    stroke(255, 216, 172, a);
    strokeWeight(random(1, 3.6));
    line(x, y, x + random(-4, 4), y - len);
  }

  // --- fading ripples: the last disturbance on the surface ---
  const rcx = cx, rcy = hy + 26;
  const RINGS = 64;
  for (let i = RINGS; i >= 1; i--) {
    const f = i / RINGS; // 1 outer → 0 inner
    const rw = 120 + pow(1 - f, 1.55) * 1450;
    const rh = rw * 0.16;
    const col = lerpColor(color(92, 100, 152), color(255, 214, 160), pow(1 - f, 1.5));
    stroke(red(col), green(col), blue(col), lerp(6, 64, pow(1 - f, 2.0)));
    strokeWeight(lerp(1, 5, pow(1 - f, 2)));
    noFill();
    beginShape();
    const steps = 160;
    for (let s = 0; s <= steps; s++) {
      const ang = (s / steps) * PI; // lower half only: ripples live on the water
      const wob = 1 + 0.06 * noise(cos(ang) * 1.6 + rw * 0.003, sin(ang) * 1.6, i * 0.31)
                    + 0.025 * noise(cos(ang) * 4 + i, sin(ang) * 4);
      vertex(rcx + cos(ang) * rw * wob, rcy + sin(ang) * rh * wob);
    }
    endShape();
  }

  // --- the light dissolving into drifting sparks rising to the dark ---
  const P = 1500;
  for (let i = 0; i < P; i++) {
    const a = random(TWO_PI);
    const t = pow(random(), 0.75); // age of the spark: 0 at the core → 1 far away
    const spread = 60 + t * random(500, 1050);
    const rise = t * t * random(500, 980);
    const x = sx + cos(a) * spread * (0.5 + 0.5 * t) + (noise(i * 0.11, t * 3) - 0.5) * 90 * t;
    const y = sy + sin(a) * spread * 0.35 - rise;
    const warmF = pow(max(0, 1 - t * 1.15), 1.5);
    const col = lerpColor(color(105, 116, 178), color(255, 222, 178), warmF);
    const al = pow(1 - t, 1.7) * 175 * (0.35 + 0.65 * noise(i * 0.7, 1));
    const s = lerp(6, 0.7, t) * random(0.6, 1.5);
    noStroke();
    fill(red(col), green(col), blue(col), al);
    ellipse(x, y, s, s * random(0.6, 1.4));
    if (t > 0.5 && random() < 0.35) {
      stroke(red(col), green(col), blue(col), al * 0.45);
      strokeWeight(max(0.5, s * 0.45));
      line(x, y, x + random(-5, 5), y - random(12, 46));
    }
  }

  // --- a few sparks that fall toward the water and die there ---
  for (let i = 0; i < 160; i++) {
    const t = random();
    const x = sx + randomGaussian() * (80 + t * 420);
    const y = hy + random(10, 260);
    noStroke();
    fill(255, 210, 160, random(8, 40) * (1 - t));
    ellipse(x, y, random(1, 4), random(1, 4));
  }

  // --- film grain ---
  noStroke();
  for (let i = 0; i < 9000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) fill(255, 255, 255, random(2, 7));
    else fill(0, 0, 0, random(3, 9));
    rect(x, y, random(0.5, 1.7), random(0.5, 1.7));
  }

  // --- vignette ---
  const diag = dist(0, 0, W, H) / 2;
  noFill();
  for (let r = 0; r < diag; r += 8) {
    const a = map(r, diag * 0.45, diag, 0, 125, true);
    stroke(3, 3, 10, a);
    strokeWeight(8);
    ellipse(W / 2, H / 2, r * 2, r * 2);
  }
}

// p5.js 1.11 — 无外部资源
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  const ctx = drawingContext;

  // 深水底色
  const bg = ctx.createLinearGradient(0, 0, 300, height);
  bg.addColorStop(0, "#24383b");
  bg.addColorStop(0.48, "#142c30");
  bg.addColorStop(1, "#091c22");
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  // 像旧颜料一样沉积的水色
  noStroke();
  for (let i = 0; i < 12500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.003);
    fill(79 + n * 30, 101 + n * 22, 98 + n * 18, random(2, 8));
    ellipse(x, y, random(12, 95), random(2, 15));
  }

  eclipse(1080, 405, 153);

  // 水面的低声部
  for (let i = 0; i < 4600; i++) {
    const x = random(-80, width + 80);
    const y = random(490, height);
    const n = noise(x * 0.003, y * 0.006);
    const perspective = map(y, 490, height, 0.35, 1.6);
    stroke(103, 128, 123, random(5, 18) * n);
    strokeWeight(random(0.5, 1.5));
    noFill();
    beginShape();
    const len = random(8, 75) * perspective;
    for (let j = 0; j <= 5; j++) {
      vertex(x + len * j / 5,
             y + (noise(x * 0.01 + j * 0.3, y * 0.01) - 0.5) * 7);
    }
    endShape();
  }

  // 日蚀的倒影：越向下，越难拼回完整的圆
  for (let i = 0; i < 1200; i++) {
    const t = random();
    const y = 590 + t * 1160;
    const spread = 22 + 155 * pow(t, 0.7);
    const x = 1080 + sin(t * 16) * 27 + randomGaussian() * spread;
    const a = (1 - t) * random(4, 27);
    stroke(188, 166, 112, a);
    strokeWeight(random(0.6, 2));
    line(x, y, x + random(3, 29) * (0.5 + t), y);
  }

  // 船旁几乎静止的涟漪
  push();
  translate(795, 1190);
  rotate(-0.34);
  noFill();
  for (let k = 0; k < 12; k++) {
    stroke(136, 153, 141, 17 - k);
    strokeWeight(1);
    for (let side = 0; side < 2; side++) {
      beginShape();
      const start = side === 0 ? -1.1 : 1.9;
      for (let a = start; a < start + 1.25; a += 0.025) {
        let rx = 270 + k * 14;
        let ry = 540 + k * 19;
        vertex(cos(a) * rx + noise(a * 4, k) * 5,
               sin(a) * ry);
      }
      endShape();
    }
  }

  // 船下的阴影
  noStroke();
  for (let i = 25; i > 0; i--) {
    fill(2, 11, 14, 3);
    ellipse(25, 30, 460 + i * 8, 1000 + i * 7);
  }
  pop();

  boat(795, 1190, -0.34);

  // 前景的枯苇，像尚未被擦去的笔迹
  reeds();

  // 暗角
  ctx.save();
  const vignette = ctx.createRadialGradient(
    810, 910, 450, 800, 1000, 1260
  );
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.68, "rgba(0,8,12,0.08)");
  vignette.addColorStop(1, "rgba(0,6,10,0.57)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();

  // 纸面颗粒；只修改颜色，不叠加任何文字
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = random(-3.2, 3.2);
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

function eclipse(x, y, r) {
  const ctx = drawingContext;
  ctx.save();

  const halo = ctx.createRadialGradient(x, y, r * 0.85, x, y, r * 2.3);
  halo.addColorStop(0, "rgba(207,180,120,0.11)");
  halo.addColorStop(0.38, "rgba(167,151,104,0.045)");
  halo.addColorStop(1, "rgba(167,151,104,0)");
  ctx.fillStyle = halo;
  ctx.fillRect(x - r * 2.3, y - r * 2.3, r * 4.6, r * 4.6);

  noStroke();
  fill("#b5a47d");
  ellipse(x, y, r * 2);

  for (let i = 0; i < 1800; i++) {
    let a = random(TWO_PI);
    let rr = random(r - 11, r + 2);
    stroke(220, 201, 152, random(12, 60));
    strokeWeight(random(0.4, 1.2));
    line(x + cos(a) * rr, y + sin(a) * rr,
         x + cos(a + 0.009) * rr, y + sin(a + 0.009) * rr);
  }

  const dark = ctx.createRadialGradient(
    x - 45, y - 65, 10, x, y, r
  );
  dark.addColorStop(0, "#223236");
  dark.addColorStop(1, "#172a2e");
  ctx.fillStyle = dark;
  ctx.beginPath();
  ctx.ellipse(x + 4, y - 5, r - 4, r - 4, 0, 0, Math.PI * 2);
  ctx.fill();

  noFill();
  stroke(218, 198, 151, 100);
  strokeWeight(0.8);
  arc(x, y, r * 2 + 2, r * 2 + 2, 0.6, 2.85);
  ctx.restore();
}

function boat(x, y, angle) {
  push();
  translate(x, y);
  rotate(angle);
  const ctx = drawingContext;

  const hull = new Path2D(
    "M 0 -495 " +
    "C 139 -399 221 -182 222 34 " +
    "C 224 229 133 404 0 492 " +
    "C -143 393 -226 202 -219 12 " +
    "C -217 -201 -133 -403 0 -495 Z"
  );

  const inner = new Path2D(
    "M 0 -453 " +
    "C 114 -352 190 -166 188 32 " +
    "C 188 203 110 369 0 446 " +
    "C -116 356 -192 185 -187 10 " +
    "C -183 -181 -112 -362 0 -453 Z"
  );

  const wood = ctx.createLinearGradient(-230, 0, 230, 0);
  wood.addColorStop(0, "#655c48");
  wood.addColorStop(0.15, "#3e4339");
  wood.addColorStop(0.55, "#343a33");
  wood.addColorStop(0.9, "#625b47");
  wood.addColorStop(1, "#8b7b59");
  ctx.fillStyle = wood;
  ctx.fill(hull);

  ctx.save();
  ctx.clip(hull);
  for (let i = 0; i < 330; i++) {
    const xx = random(-225, 225);
    const yy = random(-500, 490);
    stroke(169, 147, 99, random(7, 25));
    strokeWeight(random(0.4, 1.3));
    noFill();
    bezier(xx, yy,
           xx + random(-9, 9), yy + 25,
           xx + random(-8, 8), yy + 60,
           xx + random(-5, 5), yy + random(65, 170));
  }
  ctx.restore();

  ctx.fillStyle = "#101f22";
  ctx.fill(inner);

  ctx.save();
  ctx.clip(inner);

  // 舱底的木板和横肋
  for (let i = -3; i <= 3; i++) {
    stroke(98, 93, 69, 45);
    strokeWeight(1.4);
    line(i * 48, -470, i * 48, 470);
  }
  for (let yy = -310; yy < 410; yy += 145) {
    stroke(68, 69, 53, 100);
    strokeWeight(9);
    noFill();
    bezier(-195, yy - 20, -70, yy + 12,
           70, yy + 12, 195, yy - 20);
    stroke(137, 122, 85, 35);
    strokeWeight(1);
    bezier(-195, yy - 24, -70, yy + 8,
           70, yy + 8, 195, yy - 24);
  }
  ctx.restore();

  ctx.strokeStyle = "rgba(184,160,108,0.43)";
  ctx.lineWidth = 2;
  ctx.stroke(hull);
  ctx.strokeStyle = "rgba(151,135,94,0.35)";
  ctx.lineWidth = 1.5;
  ctx.stroke(inner);

  // 空白的裹布：轮廓保留了重量，内部没有身体
  const cloth = new Path2D(
    "M -44 -337 " +
    "C -98 -350 -130 -293 -121 -233 " +
    "C -160 -183 -146 -108 -157 -55 " +
    "C -173 20 -139 79 -142 144 " +
    "C -148 212 -93 276 -93 328 " +
    "C -66 355 -32 335 -9 375 " +
    "C 12 340 47 371 68 330 " +
    "C 104 295 85 248 113 199 " +
    "C 136 144 110 89 137 29 " +
    "C 151 -31 121 -85 130 -142 " +
    "C 134 -210 97 -246 92 -288 " +
    "C 85 -332 31 -354 -4 -332 " +
    "C -18 -320 -29 -323 -44 -337 Z"
  );

  ctx.save();
  ctx.shadowColor = "rgba(0,0,0,0.65)";
  ctx.shadowBlur = 24;
  ctx.shadowOffsetX = 13;
  ctx.shadowOffsetY = 18;

  const linen = ctx.createLinearGradient(-165, -100, 145, 100);
  linen.addColorStop(0, "#828d80");
  linen.addColorStop(0.22, "#c1c3ac");
  linen.addColorStop(0.46, "#e2ddc4");
  linen.addColorStop(0.64, "#c9cbb5");
  linen.addColorStop(0.83, "#e8e0c8");
  linen.addColorStop(1, "#8b978a");
  ctx.fillStyle = linen;
  ctx.fill(cloth);
  ctx.restore();

  ctx.save();
  ctx.clip(cloth);

  // 不规则的纵向褶皱
  noFill();
  for (let i = 0; i < 95; i++) {
    const base = random(-155, 145);
    stroke(51, 75, 70, random(5, 22));
    strokeWeight(random(1, 7));
    beginShape();
    for (let yy = -360; yy <= 390; yy += 10) {
      let xx = base
        + sin(yy * 0.011 + base * 0.035) * 15
        + (noise(base * 0.02 + 10, yy * 0.007 + 10) - 0.5) * 27;
      curveVertex(xx, yy);
    }
    endShape();
  }

  // 斜向塌陷的折面
  for (let i = 0; i < 15; i++) {
    let yy = -220 + i * 39;
    let side = i % 2 === 0 ? -1 : 1;
    stroke(52, 76, 71, 24);
    strokeWeight(random(3, 8));
    bezier(side * 165, yy - 30,
           side * 95, yy - 5,
           side * 70, yy + 30,
           side * 12, yy + 66);
    stroke(247, 239, 212, 50);
    strokeWeight(1.5);
    bezier(side * 165, yy - 34,
           side * 95, yy - 9,
           side * 70, yy + 26,
           side * 12, yy + 62);
  }

  // 亚麻纤维
  for (let i = 0; i < 6500; i++) {
    let xx = random(-165, 150);
    let yy = random(-355, 380);
    stroke(255, 248, 218, random(5, 24));
    strokeWeight(0.5);
    line(xx, yy, xx + random(-0.5, 0.5), yy + random(2, 12));
  }
  ctx.restore();

  // 布口：不是脸，而是一处深陷的空缺
  noStroke();
  fill(54, 73, 67, 155);
  beginShape();
  vertex(-54, -302);
  bezierVertex(-26, -284, 25, -281, 62, -302);
  bezierVertex(43, -265, -14, -260, -54, -302);
  endShape();

  noFill();
  stroke(238, 228, 202, 160);
  strokeWeight(3);
  bezier(-63, -306, -25, -281, 29, -281, 66, -305);

  flower(28, -139);

  // 红线跨过船沿，在水中中断
  noFill();
  stroke(38, 21, 20, 95);
  strokeWeight(4);
  bezier(24, -94, -24, 20, -140, 68, -212, 103);

  stroke("#9c5141");
  strokeWeight(2);
  beginShape();
  vertex(24, -96);
  bezierVertex(-9, -32, -34, 25, -104, 50);
  bezierVertex(-174, 76, -193, 44, -213, 103);
  bezierVertex(-239, 184, -289, 211, -308, 294);
  bezierVertex(-318, 330, -345, 355, -369, 364);
  endShape();

  stroke("#ad6250");
  strokeWeight(1.3);
  bezier(-388, 376, -434, 394, -412, 443, -477, 455);

  // 断端的细纤维
  stroke(190, 111, 83, 150);
  strokeWeight(0.7);
  line(-369, 364, -375, 366);
  line(-369, 364, -372, 370);
  line(-388, 376, -383, 372);
  line(-388, 376, -382, 376);

  pop();
}

function flower(x, y) {
  push();
  translate(x, y);
  rotate(0.28);

  noFill();
  stroke(70, 80, 60);
  strokeWeight(2.2);
  bezier(0, 3, -17, 43, 5, 87, -20, 128);

  noStroke();
  fill(105, 108, 76);
  beginShape();
  vertex(-7, 63);
  bezierVertex(-40, 59, -39, 38, -36, 31);
  bezierVertex(-15, 36, -17, 49, -7, 63);
  endShape();

  for (let ring = 0; ring < 3; ring++) {
    const count = 9 - ring;
    for (let i = 0; i < count; i++) {
      push();
      rotate(TWO_PI * i / count + ring * 0.43);
      const len = 28 - ring * 7;
      fill(193 + ring * 15, 184 + ring * 13, 148 + ring * 15);
      stroke(111, 109, 81, 85);
      strokeWeight(0.7);
      beginShape();
      vertex(-4, 3);
      bezierVertex(-17, -8, -13, -len, -3, -len);
      bezierVertex(9, -len - 2, 13, -10, 4, 4);
      endShape(CLOSE);
      pop();
    }
  }
  noStroke();
  fill("#8b8054");
  ellipse(0, 0, 10, 9);
  for (let i = 0; i < 17; i++) {
    fill(204, 182, 111, 160);
    ellipse(random(-4, 4), random(-4, 4), 1.4, 1.4);
  }
  pop();
}

function reeds() {
  noFill();
  for (let i = 0; i < 87; i++) {
    const right = i < 56;
    const x = right ? random(1290, 1690) : random(-90, 150);
    const y = random(2020, 2160);
    const h = random(135, 530);
    const lean = right ? random(-155, 30) : random(-15, 100);

    stroke(5, 17, 20, random(110, 220));
    strokeWeight(random(1.1, 3.3));
    bezier(x, y,
           x + lean * 0.1, y - h * 0.32,
           x + lean * 0.45, y - h * 0.82,
           x + lean, y - h);

    if (i % 3 === 0) {
      stroke(84, 89, 66, 65);
      strokeWeight(0.8);
      bezier(x + 2, y,
             x + lean * 0.1 + 2, y - h * 0.32,
             x + lean * 0.45 + 2, y - h * 0.82,
             x + lean + 1, y - h);
    }

    if (i % 4 === 0) {
      const tx = x + lean;
      const ty = y - h;
      stroke(29, 40, 34, 190);
      for (let j = 0; j < 11; j++) {
        const yy = ty + j * 5;
        const reach = sin(j / 11 * PI) * 17;
        strokeWeight(1.1);
        line(tx, yy, tx - reach, yy - 13);
        line(tx, yy, tx + reach * 0.6, yy - 10);
      }
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(15, 25, 28);
  water();
  shore();
  driftingLeaves();

  // 舟下的阴影
  push();
  translate(800, 1040);
  rotate(-0.14);
  noStroke();
  for (let i = 30; i > 0; i--) {
    fill(2, 9, 12, 5);
    ellipse(0, 30, 550 + i * 10, 1450 + i * 12);
  }
  pop();

  push();
  translate(800, 1000);
  rotate(-0.14);
  boat();
  shroud();
  skull(0, -405);
  branch();
  pop();

  // 极少的悬浮微光
  noStroke();
  for (let i = 0; i < 95; i++) {
    let x = random(420, 1200);
    let y = random(280, 1660);
    fill(199, 174, 109, random(15, 65));
    circle(x, y, random(1, 3));
  }

  grain();
}

function water() {
  strokeWeight(1);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let light = 9 * sin(t * PI);
    stroke(12 + light, 23 + light, 27 + light);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 2500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);
    fill(54, 79, 72, 2 + n * 6);
    ellipse(x, y, random(25, 180), random(3, 20));
  }

  // 不闭合的水纹，像逐渐消失的年轮
  noFill();
  for (let k = 0; k < 48; k++) {
    let rx = 265 + k * 15;
    let ry = 620 + k * 19;
    stroke(107, 130, 117, random(10, 34));
    strokeWeight(random(0.7, 1.7));
    let start = random(TWO_PI);
    let span = random(0.55, 2.5);
    beginShape();
    for (let a = start; a < start + span; a += 0.018) {
      let wobble = 10 * noise(cos(a) * 3 + 10,
                              sin(a) * 3 + 10, k * 0.11);
      let x = (rx + wobble) * cos(a);
      let y = (ry + wobble) * sin(a);
      vertex(800 + x * cos(-0.14) - y * sin(-0.14),
             1030 + x * sin(-0.14) + y * cos(-0.14));
    }
    endShape();
  }

  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(height);
    stroke(128, 148, 129, random(3, 17));
    line(x, y, x + random(4, 38), y + random(-2, 2));
  }
}

function shore() {
  // 边缘的枯苇不形成实在的岸线
  for (let side of [-1, 1]) {
    for (let i = 0; i < 66; i++) {
      let x = side < 0 ? random(-100, 260) : random(1360, 1700);
      let y = side < 0 ? random(1400, 2150) : random(-160, 650);
      let length = random(150, 500);
      let direction = side < 0 ? -1 : 1;
      let lean = random(-100, 110);
      stroke(47, 58, 46, random(70, 160));
      strokeWeight(random(1, 3));
      noFill();
      bezier(x, y,
             x + lean * 0.2, y + direction * length * 0.35,
             x + lean, y + direction * length * 0.75,
             x + lean * 1.4, y + direction * length);
      if (i % 3 === 0) {
        stroke(105, 103, 68, 65);
        strokeWeight(4);
        line(x + lean * 1.3, y + direction * length * 0.9,
             x + lean * 1.4, y + direction * length);
      }
    }
  }
}

function driftingLeaves() {
  for (let i = 0; i < 31; i++) {
    let a = random(TWO_PI);
    let r = random(0.85, 1.55);
    let x = 800 + cos(a) * 430 * r;
    let y = 1000 + sin(a) * 700 * r;
