function branch() {
  // 一根纤细的枝条从胸口延伸出去
  noStroke();
  fill(51, 65, 52, 160);
  ellipse(16, -198, 26, 11);

  noFill();
  stroke(102, 94, 56);
  strokeWeight(5);
  bezier(13, -199, 61, -311, 77, -481, 146, -638);
  stroke(178, 148, 81);
  strokeWeight(2);
  bezier(12, -200, 55, -318, 83, -489, 146, -638);

  let twigs = [
    [44, -302, -3, -348],
    [63, -382, 121, -422],
    [84, -468, 42, -530],
    [110, -548, 166, -576],
    [134, -607, 112, -652]
  ];

  for (let t of twigs) {
    stroke(148, 126, 70);
    strokeWeight(1.6);
    line(t[0], t[1], t[2], t[3]);
    push();
    translate(t[2], t[3]);
    rotate(atan2(t[3] - t[1], t[2] - t[0]) + HALF_PI);
    leaf(0, -12, random(10, 16), random(30, 44),
         color(random(164, 205), random(133, 163), 76));
    pop();
  }

  push();
  translate(146, -640);
  rotate(0.3);
  leaf(0, -13, 11, 38, color(205, 170, 94));
  pop();
}

function leaf(x, y, w, h, c) {
  noStroke();
  fill(c);
  beginShape();
  vertex(x, y - h / 2);
  bezierVertex(x + w, y - h / 4,
               x + w * 0.6, y + h / 3, x, y + h / 2);
  bezierVertex(x - w * 0.7, y + h / 5,
               x - w * 0.5, y - h / 3, x, y - h / 2);
  endShape(CLOSE);
  stroke(65, 65, 39, 100);
  strokeWeight(0.8);
  line(x, y - h * 0.37, x, y + h * 0.42);
}

function grain() {
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let i = 4 * (y * width + x);
      let g = random(-4, 4);
      let dx = (x - width / 2) / (width / 2);
      let dy = (y - height / 2) / (height / 2);
      let vignette = 1 - 0.16 * pow(min(1.5, dx * dx + dy * dy), 1.2);
      pixels[i] = constrain(pixels[i] * vignette + g, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] * vignette + g, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] * vignette + g, 0, 255);
    }
  }
  updatePixels();
}

// p5.js 1.11 — 无需外部资源
function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
  paint();
}

function paint() {
  background(12, 23, 27);
  paintWater();
  paintMoon();
  paintReflections();

  // 舟下的阴影：边缘在水中逐层消失。
  push();
  translate(815, 1165);
  rotate(0.13);
  noStroke();
  for (let i = 28; i > 0; i--) {
    fill(2, 10, 14, 3);
    ellipse(0, 55, 550 + i * 11, 1320 + i * 10);
  }
  pop();

  paintWake();

  push();
  translate(815, 1135);
  rotate(0.13);
  paintBoat();
  paintSheet();
  paintThread();
  pop();

  paintDust();
  paintVignette();
}

function paintWater() {
  noFill();
  strokeWeight(2);
  for (let y = 0; y < height; y += 2) {
    const t = y / height;
    const glow = exp(-sq((t - 0.48) / 0.34));
    stroke(11 + glow * 10, 22 + glow * 17, 27 + glow * 17);
    line(0, y, width, y);
  }

  // 潮水的笔触，长而不连续。
  for (let i = 0; i < 11000; i++) {
    const x = random(-100, width + 100);
    const y = random(height);
    const n = noise(x * 0.0024, y * 0.003);
    const len = random(5, 95) * (0.45 + y / height);
    const light = random() < 0.43;

    stroke(
      light ? 60 : 4,
      light ? 81 : 15,
      light ? 79 : 20,
      random(8, 29)
    );
    strokeWeight(random(0.5, 2.4));
    const bend = (n - 0.5) * 11;
    bezier(
      x, y,
      x + len * 0.3, y + bend,
      x + len * 0.7, y - bend,
      x + len, y + random(-2, 2)
    );
  }

  noStroke();
  for (let i = 0; i < 26000; i++) {
    const x = random(width);
    const y = random(height);
    fill(107, 123, 111, random(2, 10));
    ellipse(x, y, random(0.6, 2), random(0.6, 3));
  }
}

function paintMoon() {
  const x = 1125, y = 278, r = 107;

  noStroke();
  for (let k = 14; k > 0; k--) {
    fill(166, 161, 126, 1.7);
    circle(x, y, r * 2 + k * 10);
  }

  const moon = new Path2D();
  moon.arc(x, y, r, 0, TWO_PI);

  const ctx = drawingContext;
  ctx.save();
  ctx.clip(moon);

  fill(179, 176, 148);
  rect(x - r, y - r, r * 2, r * 2);

  for (let i = 0; i < 4700; i++) {
    const px = random(x - r, x + r);
    const py = random(y - r, y + r);
    const n = noise(px * 0.035, py * 0.035);
    fill(72, 84, 74, 8 + n * 35);
    circle(px, py, random(0.8, 4));
  }

  // 偏心的暗面，留下薄薄一侧旧银。
  fill(13, 25, 29);
  ellipse(x - 31, y - 13, 204, 213);
  ctx.restore();
}

function paintReflections() {
  for (let i = 0; i < 680; i++) {
    const y = random(400, 1630);
    const t = (y - 400) / 1230;
    const spread = 13 + t * 125;
    const x = 1138 + sin(y * 0.008) * 17 +
      randomGaussian(0, spread);
    const fade = pow(1 - t, 1.6);

    stroke(174, 163, 121, random(3, 28) * fade);
    strokeWeight(random(0.6, 2));
    line(x, y, x + random(3, 39), y);
  }
}

function paintWake() {
  noFill();
  for (let i = 0; i < 24; i++) {
    const d = i * 9;
    stroke(102, 125, 115, 18 - i * 0.5);
    strokeWeight(random(0.6, 1.5));

    bezier(
      850, 455 - d * 0.2,
      388 - d, 720,
      293 - d, 1480,
      690, 1870 + d * 0.25
    );

    bezier(
      933, 505,
      1195 + d, 850,
      1170 + d, 1530,
      730, 1870 + d * 0.25
    );
  }
}

function hullPath() {
  const p = new Path2D();
  p.moveTo(0, -680);
  p.bezierCurveTo(180, -525, 294, -205, 270, 180);
  p.bezierCurveTo(252, 432, 117, 614, 0, 690);
  p.bezierCurveTo(-157, 563, -284, 281, -275, -65);
  p.bezierCurveTo(-269, -330, -154, -548, 0, -680);
  p.closePath();
  return p;
}

function paintBoat() {
  const ctx = drawingContext;
  const hull = hullPath();

  ctx.save();
  ctx.fillStyle = "#675c43";
  ctx.fill(hull);
  ctx.lineWidth = 3;
  ctx.strokeStyle = "#8d7b56";
  ctx.stroke(hull);
  ctx.restore();

  push();
  scale(0.945, 0.973);

  ctx.save();
  ctx.clip(hull);

  const g = ctx.createLinearGradient(-280, 0, 280, 0);
  g.addColorStop(0, "#3b3b31");
  g.addColorStop(0.13, "#171f1f");
  g.addColorStop(0.56, "#0b1518");
  g.addColorStop(0.88, "#202925");
  g.addColorStop(1, "#504a37");
  ctx.fillStyle = g;
  ctx.fillRect(-320, -720, 640, 1450);

  // 暗木的纵纹。
  noFill();
  for (let i = 0; i < 210; i++) {
    const x = random(-280, 280);
    const y = random(-680, 650);
    stroke(153, 128, 82, random(5, 27));
    strokeWeight(random(0.4, 1.4));
    bezier(
      x, y,
      x - 15, y + 70,
      x + 20, y + 170,
      x + random(-8, 8), y + random(180, 400)
    );
  }

  // 船骨，只在床单两侧露出。
  for (let y = -455; y < 620; y += 112) {
    stroke(89, 78, 54, 80);
    strokeWeight(8);
    bezier(-270, y, -105, y + 47, 111, y + 47, 275, y);
    stroke(12, 17, 17, 150);
    strokeWeight(3);
    bezier(-270, y + 6, -105, y + 53, 111, y + 53, 275, y + 6);
  }

  ctx.restore();
  pop();

  noFill();
  stroke(181, 158, 105, 72);
  strokeWeight(1.5);
  bezier(0, -669, 174, -500, 286, -160, 252, 215);
  stroke(143, 127, 89, 55);
  bezier(-259, -67, -266, 262, -142, 544, 0, 676);
}

function sheetPath() {
  const p = new Path2D();
  p.moveTo(-127, -445);
  p.bezierCurveTo(-75, -466, 67, -460, 131, -427);
  p.bezierCurveTo(172, -353, 142, -251, 174, -125);
  p.bezierCurveTo(195, -23, 159, 101, 180, 214);
  p.bezierCurveTo(194, 328, 115, 400, 126, 481);
  p.bezierCurveTo(131, 535, 67, 575, 12, 608);
  p.lineTo(35, 547);
  p.bezierCurveTo(-4, 572, -47, 557, -76, 576);
  p.lineTo(-64, 510);
  p.bezierCurveTo(-153, 475, -161, 406, -171, 314);
  p.bezierCurveTo(-196, 201, -149, 90, -173, -29);
  p.bezierCurveTo(-195, -172, -169, -353, -127, -445);
  p.closePath();
  return p;
}

function paintSheet() {
  const ctx = drawingContext;
  const sheet = sheetPath();

  // 厚实但柔软的投影。
  ctx.save();
  ctx.translate(15, 19);
  ctx.fillStyle = "rgba(0,5,9,0.72)";
  ctx.shadowColor = "rgba(0,5,9,0.8)";
  ctx.shadowBlur = 26;
  ctx.fill(sheet);
  ctx.restore();

  ctx.save();
  ctx.clip(sheet);

  const g = ctx.createLinearGradient(-200, -150, 205, 100);
  g.addColorStop(0, "#777f72");
  g.addColorStop(0.2, "#c6c8b0");
  g.addColorStop(0.44, "#e2dfc5");
  g.addColorStop(0.64, "#c7cab5");
  g.addColorStop(0.85, "#a6b09f");
  g.addColorStop(1, "#687b72");
  ctx.fillStyle = g;
  ctx.fillRect(-240, -490, 480, 1150);

  // 中央是凹陷而非隆起：人已经不在这里。
  noStroke();
  for (let i = 40; i > 0; i--) {
    fill(49, 70, 66, 2.5);
    ellipse(12, -35, 64 + i * 3.2, 260 + i * 8);
  }

  noFill();
  for (let i = 0; i < 115; i++) {
    const x = random(-185, 185);
    const y = random(-440, 490);
    const len = random(55, 245);
    stroke(48, 75, 70, random(6, 24));
    strokeWeight(random(1, 7));
    bezier(
      x, y,
      x - 23, y + len * 0.3,
      x + 27, y + len * 0.7,
      x + random(-22, 22), y + len
    );
  }

  // 几道决定织物重量的主褶。
  fold(-139, -270, -81, -125, -152, 112, -110, 329, 12);
  fold(135, -241, 76, -43, 151, 136, 105, 342, 14);
  fold(-104, 272, -48, 385, -43, 450, -64, 510, 10);
  fold(140, 266, 62, 368, 84, 473, 12, 608, 16);
  fold(-50, 431, -8, 468, 53, 477, 35, 547, 8);

  // 织物颗粒。
  noStroke();
  for (let i = 0; i < 16500; i++) {
    const x = random(-200, 200);
    const y = random(-470, 620);
    fill(random() < 0.5 ? 244 : 64,
         random() < 0.5 ? 232 : 94, 160, random(3, 13));
    rect(x, y, random(0.4, 1.3), random(1, 4));
  }

  ctx.restore();
  paintPillow();
}

function fold(x1, y1, x2, y2, x3, y3, x4, y4, w) {
  noFill();
  stroke(47, 70, 65, 33);
  strokeWeight(w);
  bezier(x1, y1, x2, y2, x3, y3, x4, y4);
  stroke(65, 82, 73, 53);
  strokeWeight(w * 0.25);
  bezier(x1, y1, x2, y2, x3, y3, x4, y4);
  stroke(244, 237, 210, 95);
  strokeWeight(2);
  bezier(x1 - 5, y1, x2 - 6, y2, x3 - 5, y3, x4 - 3, y4);
}

function paintPillow() {
  const p = new Path2D();
  p.moveTo(-111, -418);
  p.bezierCurveTo(-43, -435, 55, -424, 114, -402);
  p.bezierCurveTo(100, -355, 113, -303, 98, -271);
  p.bezierCurveTo(24, -283, -53, -274, -122, -296);
  p.bezierCurveTo(-105, -337, -124, -386, -111, -418);
  p.closePath();

  const ctx = drawingContext;
  ctx.save();
  ctx.shadowColor = "rgba(22,40,36,0.55)";
  ctx.shadowBlur = 15;
  ctx.shadowOffsetY = 10;
  ctx.fillStyle = "#d2d2b9";
  ctx.fill(p);
  ctx.restore();

  ctx.save();
  ctx.clip(p);

  noStroke();
  for (let i = 30; i > 0; i--) {
    fill(64, 84, 76, 3.5);
    ellipse(-2, -352, 48 + i * 3.4, 17 + i * 1.7);
  }

  noFill();
  for (let i = 0; i < 42; i++) {
    const x = random(-125, 125);
    stroke(93, 111, 94, random(15, 44));
    strokeWeight(random(0.5, 1.5));
    bezier(x, -429, x - 6, -411, x + 4, -391, x * 0.85, -381);
  }

  for (let i = 0; i < 1800; i++) {
    stroke(242, 237, 208, random(7, 27));
    point(random(-125, 125), random(-435, -270));
  }
  ctx.restore();

  noFill();
  stroke(237, 230, 201, 130);
  strokeWeight(1.6);
  bezier(-108, -414, -36, -428, 53, -417, 109, -399);
}

function paintThread() {
  noFill();
  stroke(174, 139, 75, 145);
  strokeWeight(1.7);

  bezier(-107, -307, -191, -311, -193, -406, -275, -416);
  bezier(-275, -416, -350, -426, -358, -356, -422, -397);

  // 两段之间留有无法接回的距离。
  stroke(202, 169, 100, 150);
  bezier(-454, -422, -502, -457, -465, -541, -530, -575);
  bezier(-530, -575, -554, -587, -578, -572, -586, -592);

  stroke(234, 212, 155, 135);
  strokeWeight(0.6);
  bezier(-107, -308, -191, -312, -193, -407, -275, -417);

  // 断口处极细的纤维。
  stroke(189, 160, 101, 110);
  line(-422, -397, -415, -395);
  line(-422, -397, -419, -390);
  line(-454, -422, -450, -415);
}

function paintDust() {
  noStroke();
  for (let i = 0; i < 46000; i++) {
    const bright = random() < 0.5;
    fill(bright ? 221 : 2,
         bright ? 213 : 8,
         bright ? 183 : 12,
         random(3, 12));
    const s = random(0.5, 1.8);
    rect(random(width), random(height), s, s);
  }
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(
    800, 1050, 420,
    800, 1050, 1250
  );
  g.addColorStop(0, "rgba(0,6,10,0)");
  g.addColorStop(0.62, "rgba(0,6,10,0.04)");
  g.addColorStop(1, "rgba(0,5,9,0.57)");

  ctx.save();
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
  ctx.restore();
}

// p5.js 1.11
// 无外部资源；运行后生成一张静态图像。

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  angleMode(RADIANS);
}

function draw() {
  atmosphere();
  moon();
  distantLand();
  water();
  banks();
  reflection();
  oar();
  boat();
  branch();
  shroud();
  boatRim();
  lastLeaf();
  surfaceMarks();
  grain();
}

function atmosphere() {
  const top = color(18, 29, 36);
  const bottom = color(102, 112, 110);

  for (let y = 0; y < height; y++) {
    let t = constrain(y / 1190, 0, 1);
    let c = lerpColor(top, bottom, pow(t, 1.65));
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 15000; i++) {
    let x = random(width);
    let y = random(1200);
    let n = noise(x * 0.002, y * 0.003);
    fill(155, 160, 145, random(2, 8) * n);
    ellipse(x, y, random(15, 110), random(1, 5));
  }

  // 疏淡的竖向颜料痕。
  for (let i = 0; i < 470; i++) {
    let x = random(width);
    let y = random(1150);
    stroke(6, 20, 28, random(3, 12));
    strokeWeight(random(0.4, 2));
    line(x, y, x + random(-4, 4), y + random(20, 180));
  }
}

function moon() {
  const cx = 780, cy = 585, r = 318;
  noStroke();

  for (let k = 30; k > 0; k--) {
    fill(213, 204, 169, 0.7);
    circle(cx, cy, r * 2 + k * 5);
  }

  fill(207, 200, 173);
  circle(cx, cy, r * 2);

  const ctx = drawingContext;
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, r, 0, TWO_PI);
  ctx.clip();

  for (let y = cy - r; y < cy + r; y += 2) {
    let t = (y - cy + r) / (2 * r);
    stroke(238, 222, 179, 22 * (1 - t));
    strokeWeight(2);
    line(cx - r, y, cx + r, y);
  }

  noStroke();
  for (let i = 0; i < 19000; i++) {
    let x = random(cx - r, cx + r);
    let y = random(cy - r, cy + r);
    let n = noise(x * 0.012, y * 0.012);
    fill(75, 86, 80, 3 + 24 * n);
    ellipse(x, y, random(0.6, 5), random(0.5, 2.5));
  }

  for (let i = 0; i < 230; i++) {
    let y = random(cy - r, cy + r);
    stroke(118, 126, 113, random(6, 19));
    strokeWeight(random(0.4, 1.3));
    let x = random(cx - r, cx + r);
    line(x, y, x + random(15, 150), y + random(-1, 1));
  }
  ctx.restore();

  // 月缘并非机械的圆线，而是磨损的色粉。
  noFill();
  for (let i = 0; i < 1100; i++) {
    let a = random(TWO_PI);
    let rr = r + random(-2.5, 2.5);
    stroke(182, 181, 157, random(10, 50));
    strokeWeight(random(0.5, 2));
    point(cx + cos(a) * rr, cy + sin(a) * rr);
  }
}

function distantLand() {
  noStroke();
  fill(48, 65, 68, 180);
  beginShape();
  vertex(0, 1100);
  for (let x = 0; x <= width; x += 8) {
    let y = 1016 + noise(x * 0.003, 9) * 72;
    vertex(x, y);
  }
  vertex(width, 1170);
  vertex(0, 1170);
  endShape(CLOSE);

  for (let i = 0; i < 1700; i++) {
    let x = random(width);
    let y = random(1055, 1130);
    stroke(181, 175, 144, random(2, 12));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(5, 80), y);
  }
}

function water() {
  const a = color(63, 83, 87);
  const b = color(9, 25, 34);

  for (let y = 1110; y < height; y++) {
    let t = (y - 1110) / 890;
    stroke(lerpColor(a, b, pow(t, 0.7)));
    strokeWeight(1);
    line(0, y, width, y);
  }

  for (let i = 0; i < 14500; i++) {
    let y = random(1112, 2000);
    let x = random(width);
    let t = (y - 1110) / 890;
    let n = noise(x * 0.005, y * 0.018);
    stroke(125, 145, 137, random(3, 20) * n);
    strokeWeight(random(0.4, 1.5));
    let len = random(3, 24) * (0.5 + t * 2);
