function twig(x, y, a, len, w, depth) {
  let nx = x + cos(a) * len;
  let ny = y + sin(a) * len;
  let bend = random(-12, 12);

  noFill();
  stroke(28, 36, 34);
  strokeWeight(w);
  bezier(
    x, y,
    x + cos(a) * len * 0.34 + bend,
    y + sin(a) * len * 0.34,
    x + cos(a) * len * 0.72,
    y + sin(a) * len * 0.72,
    nx, ny
  );

  stroke(153, 141, 104, 65);
  strokeWeight(max(0.5, w * 0.16));
  line(x - 1, y, nx - 1, ny);

  if (depth > 0) {
    twig(nx, ny, a + random(-0.19, 0.2),
         len * random(0.65, 0.78), w * 0.68, depth - 1);
    if (depth > 1) {
      twig(
        x + (nx - x) * 0.7,
        y + (ny - y) * 0.7,
        a + (depth % 2 ? -1 : 1) * random(0.48, 0.85),
        len * random(0.39, 0.57),
        w * 0.43,
        depth - 2
      );
    }
  }
}

