function paintWater() {
  noStroke();

  // 暗水中的缓慢色层。
  for (let y = 0; y < height; y += 8) {
    for (let x = 0; x < width; x += 8) {
      let n = noise(x * 0.0028, y * 0.0028);
      let light = exp(
        -sq((x - 780) / 660) - sq((y - 930) / 1000)
      );
      fill(
        9 + n * 13 + light * 5,
        18 + n * 20 + light * 7,
        23 + n * 23 + light * 6
      );
      rect(x, y, 8, 8);
    }
  }

  // 细小横向笔触，不形成规则网格。
  for (let i = 0; i < 23000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.004, y * 0.007);
    stroke(104, 128, 127, random(3, 15));
    strokeWeight(random(0.5, 1.6));
    let w = random(3, 30) * (0.5 + n);
    line(x, y, x + w, y + random(-1.5, 1.5));
  }

  // 上方被水吞没的倒影。
  noFill();
  for (let i = 0; i < 210; i++) {
    let x = random(180, 1450);
    let y = random(-120, 540);
    stroke(5, 13, 18, random(6, 24));
    strokeWeight(random(1, 6));
    bezier(
      x, y,
      x - 35, y + 80,
      x + 40, y + 190,
      x + random(-70, 70), y + random(230, 510)
    );
  }
}

