function paintBoat() {
  push();
  translate(815, 1110);
  rotate(-0.14);

  // 船缘是一条磨损的赭色轮廓。
  boatPath();
  drawingContext.fillStyle = '#392f29';
  drawingContext.fill();
  drawingContext.lineWidth = 5;
  drawingContext.strokeStyle = '#74634a';
  drawingContext.stroke();

  drawingContext.save();
  boatPath();
  drawingContext.clip();

  noStroke();
  for (let x = -250; x < 250; x += 3) {
    let v = noise(x * 0.035 + 20);
    fill(24 + v * 20, 24 + v * 11, 23 + v * 6);
    rect(x, -690, 3, 1400);
  }

  for (let i = 0; i < 460; i++) {
    let x = random(-235, 235);
    let y = random(-660, 670);
    stroke(145, 111, 69, random(6, 26));
    strokeWeight(random(0.5, 1.7));
    line(x, y, x + random(-5, 5), y + random(15, 180));
  }

  // 舱底横木。
  for (let y of [-570, -290, 70, 380, 565]) {
    stroke(8, 14, 16, 150);
    strokeWeight(18);
    line(-230, y, 230, y);
    stroke(135, 102, 65, 45);
    strokeWeight(2);
    line(-230, y - 9, 230, y - 9);
  }

  noStroke();
  for (let i = 13; i > 0; i--) {
    fill(0, 5, 8, 8);
    ellipse(13, 20, 290 + i * 6, 1050 + i * 9);
  }
  drawingContext.restore();

  // 裹布的完整轮廓及其内部色层。
  clothPath();
  drawingContext.fillStyle = '#b5b5a6';
  drawingContext.fill();

  drawingContext.save();
  clothPath();
  drawingContext.clip();

  noStroke();
  for (let y = -535; y < 500; y += 5) {
    for (let x = -180; x < 180; x += 5) {
      let n = noise(x * 0.017 + 30, y * 0.009 + 20);
      let ridge = exp(-sq((x + 38 + sin(y * 0.007) * 27) / 95));
      let v = 133 + ridge * 67 + n * 20;
      fill(v + 8, v + 6, v - 8);
      rect(x, y, 5, 5);
    }
  }

  // 柔软却沉重的纵向褶皱。
  noFill();
  for (let i = 0; i < 110; i++) {
    let x = random(-165, 165);
    let y = random(-330, 300);
