    strokeWeight(0.7);
    line(x, y, x + random(-1, 1), y + random(2, 9));
  }
  drawingContext.restore();

  // 面孔退入布的阴影，没有朝向观者的目光。
  push();
  translate(-3, -421);
  noStroke();
  fill(91, 100, 94, 110);
  ellipse(4, 7, 126, 168);
  fill(158, 162, 147);
  beginShape();
  vertex(-43, -54);
  bezierVertex(-17, -78, 28, -73, 45, -43);
  bezierVertex(57, -9, 40, 52, 8, 70);
  bezierVertex(-22, 65, -49, 18, -43, -54);
  endShape(CLOSE);

  noFill();
  stroke(67, 78, 75, 155);
  strokeWeight(2.2);
  bezier(-32, -4, -25, 1, -18, 2, -10, -2);
  bezier(10, -2, 18, 3, 27, 2, 33, -2);
  stroke(101, 111, 101, 110);
  bezier(2, -4, 1, 8, 8, 20, 1, 25);
  stroke(96, 103, 94, 130);
  line(-9, 40, 12, 41);
  pop();

  // 收拢于脚边的细绳。
  noFill();
  stroke(91, 85, 64, 150);
  strokeWeight(2.3);
  bezier(-74, 410, -30, 429, 34, 432, 76, 414);
  bezier(-72, 417, -22, 438, 30, 435, 73, 422);
  bezier(24, 429, 36, 465, 14, 493, 31, 519);

