function paintReeds() {
  // 前景的枯茎让视线停在岸上。
  for (let i = 0; i < 76; i++) {
    let left = random() < 0.64;
    let x = left ? random(-90, 430) : random(1260, 1690);
    let y = random(1960, 2180);
    let len = random(170, 650);
    let bend = left ? random(-120, 120) : random(-160, 55);
    let tx = x + bend;
    let ty = y - len;

    noFill();
    stroke(7, 17, 20, random(150, 235));
    strokeWeight(random(2, 5));
    bezier(x, y, x - bend * 0.2, y - len * 0.4, tx, ty + 70, tx, ty);

    if (i % 3 === 0) {
      stroke(78, 83, 65, 95);
      strokeWeight(1);
      bezier(x + 2, y, x - bend * 0.2 + 2, y - len * 0.4,
             tx + 2, ty + 70, tx + 2, ty);
    }

    stroke(9, 18, 20, 210);
    strokeWeight(1.4);
    for (let j = 0; j < 7; j++) {
      let yy = ty + j * 9;
      line(tx, yy + 15, tx - random(8, 26), yy - random(5, 18));
      line(tx, yy + 15, tx + random(8, 23), yy - random(4, 15));
    }
  }
}

