function finishSurface() {
  // 细颗粒与暗角，将所有元素压入同一张画面。
  strokeWeight(1);
  for (let i = 0; i < 105000; i++) {
    let x = random(width);
    let y = random(height);
    if (random() < 0.5) {
      stroke(225, 221, 195, random(3, 13));
    } else {
      stroke(0, 5, 9, random(5, 19));
    }
    point(x, y);
  }

  let c = drawingContext;
  let vignette = c.createRadialGradient(
    800, 1000, 470, 800, 1000, 1270
  );
  vignette.addColorStop(0, 'rgba(0,0,0,0)');
  vignette.addColorStop(1, 'rgba(0,5,10,0.55)');
  c.fillStyle = vignette;
  c.fillRect(0, 0, width, height);
}

const CX = 820, CY = 1040, ANG = -0.22;
let parts = [];

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  // 人形轮廓（局部坐标）：[ax, ay, bx, by, r]
  parts = [
    [0, -395, 0, -330, 42],          // 颈
    [-115, -285, 115, -285, 58],      // 肩
    [0, -260, 0, 40, 112],            // 躯干
    [-135, -275, -205, -25, 46],      // 左上臂
    [-205, -25, -222, 190, 38],       // 左前臂
    [-222, 190, -228, 245, 34],       // 左手
    [135, -275, 195, -70, 46],        // 右上臂
    [195, -70, 50, 10, 38],           // 右前臂（搭在腹上）
    [50, 10, -10, 15, 34],            // 右手
    [-72, 60, 72, 60, 92],            // 髋
    [-62, 90, -92, 380, 66],          // 左大腿
    [-92, 380, -112, 620, 50],        // 左小腿
    [-112, 620, -150, 680, 34],       // 左脚
    [62, 90, 112, 370, 66],           // 右大腿
    [112, 370, 152, 600, 50],         // 右小腿
    [152, 600, 200, 655, 34]          // 右脚
  ];
}

function capsule(px, py, ax, ay, bx, by, r) {
  let pax = px - ax, pay = py - ay, bax = bx - ax, bay = by - ay;
  let h = constrain((pax * bax + pay * bay) / (bax * bax + bay * bay), 0, 1);
  let dx = pax - bax * h, dy = pay - bay * h;
  return Math.sqrt(dx * dx + dy * dy) - r;
}

function smin(a, b, k) {
  let h = constrain(0.5 + 0.5 * (b - a) / k, 0, 1);
  return b * (1 - h) + a * h - k * h * (1 - h);
}

function bodySDF(u, v) {
  let d = Math.sqrt(u * u + (v + 475) * (v + 475)) - 88; // 头
  for (let p of parts) d = smin(d, capsule(u, v, p[0], p[1], p[2], p[3], p[4]), 28);
  return d;
}

function fieldD(x, y) {
  let dx = x - CX, dy = y - CY;
  let c = Math.cos(-ANG), s = Math.sin(-ANG);
  let u = dx * c - dy * s, v = dx * s + dy * c;
  return bodySDF(u, v) + (noise(x * 0.012, y * 0.012) - 0.5) * 38;
}

function lightAt(x, y) {
  return constrain(1.18 - (x * 0.45 + y * 0.55) / 1800 * 0.55, 0.6, 1.2);
}

function blade(x, y, ang, len, w, c1, c2, bend) {
  let tx = x + Math.cos(ang) * len, ty = y + Math.sin(ang) * len;
  let mx = (x + tx) / 2 - Math.sin(ang) * bend * len;
  let my = (y + ty) / 2 + Math.cos(ang) * bend * len;
  stroke(c1); strokeWeight(w);
  line(x, y, mx, my);
  stroke(c2); strokeWeight(w * 0.6);
  line(mx, my, tx, ty);
}

function draw() {
  // 地面底色
  noStroke();
  for (let y = 0; y < height; y += 6) {
    for (let x = 0; x < width; x += 6) {
      let d = fieldD(x, y);
      let n = noise(x * 0.006, y * 0.006);
      let L = lightAt(x, y);
      let t = constrain(map(d, 10, -30, 0, 1), 0, 1);
      let r = lerp(30 + n * 34, 118 + n * 50, t) * L;
      let g = lerp(34 + n * 30, 108 + n * 44, t) * L;
      let b = lerp(16 + n * 12, 70 + n * 28, t) * L;
      fill(r, g, b);
      rect(x, y, 6, 6);
    }
  }

  let bodyAng = Math.atan2(Math.cos(ANG), -Math.sin(ANG));
  let standing = [];

  // 被压倒的草
  for (let i = 0; i < 140000; i++) {
    let x = random(-20, width + 20), y = random(-20, height + 20);
    let d = fieldD(x, y);
    if (d < 0) {
      let rec = noise(x * 0.004 + 50, y * 0.004 + 20);
      let p = map(d, -160, 0, 0.04, 0.45, true) + (rec > 0.56 ? 0.3 : 0);
      if (random() < p) { standing.push([x, y, d, true]); continue; }
      let L = lightAt(x, y);
      let n = noise(x * 0.02, y * 0.02);
      let a = bodyAng + (noise(x * 0.005 + 9, y * 0.005) - 0.5) * 1.8 + random(-0.15, 0.15);
      if (random() < 0.2) a += PI;
      let len = random(28, 62);
      let base = lerpColor(color(150, 140, 92), color(176, 176, 140), n);
      let c1 = color(red(base) * L, green(base) * L, blue(base) * L, 210);
      let c2 = color(min(255, red(base) * L * 1.18), min(255, green(base) * L * 1.15), min(255, blue(base) * L * 1.1), 220);
      blade(x, y, a, len, random(1.2, 2.4), c1, c2, random(-0.12, 0.12));
    } else {
      standing.push([x, y, d, false]);
    }
  }

  standing.sort((a, b) => a[1] - b[1]);

  // 站着的草，以及正在重新站起来的草
  for (let s of standing) {
    let [x, y, d, rising] = s;
    let L = lightAt(x, y);
    let n = noise(x * 0.01 + 3, y * 0.01);
    let ang = noise(x * 0.003, y * 0.003) * TWO_PI * 1.3 + random(-0.6, 0.6);
    let len = random(6, 22);
    let bend = random(-0.2, 0.2);
    if (!rising && d < 70) {
      let gx = fieldD(x + 2, y) - fieldD(x - 2, y);
      let gy = fieldD(x, y + 2) - fieldD(x, y - 2);
      ang = Math.atan2(gy, gx) + random(-0.5, 0.5);
      len = map(d, 0, 70, 48, 14) * random(0.7, 1.1);
    }
    let c1, c2;
    if (rising) {
      len *= 0.7;
      c1 = color(92 * L, 104 * L, 52 * L);
      c2 = color(min(255, 168 * L), min(255, 178 * L), 104 * L);
    } else {
      c1 = color((34 + n * 20) * L, (42 + n * 18) * L, 20 * L);
      let tip = lerpColor(color(108, 116, 50), color(198, 164, 82), noise(x * 0.004 + 70, y * 0.004));
      c2 = color(min(255, red(tip) * L), min(255, green(tip) * L), min(255, blue(tip) * L));
    }
    blade(x, y, ang, len, random(1.1, 2.3), c1, c2, bend);
  }

  // 野花
  noStroke();
  for (let i = 0; i < 420; i++) {
    let x = random(width), y = random(height);
    if (fieldD(x, y) < 25) continue;
    let L = lightAt(x, y);
    let sz = random(3, 6);
    fill(240 * L, 232 * L, 205 * L, 230);
    for (let k = 0; k < 5; k++) {
      let a = k * TWO_PI / 5 + random(0.3);
      ellipse(x + Math.cos(a) * sz, y + Math.sin(a) * sz, sz * 1.3, sz * 1.3);
    }
    fill(214 * L, 170 * L, 60 * L);
    ellipse(x, y, sz * 1.1, sz * 1.1);
  }

  // 散落在轮廓里的花瓣
  for (let i = 0; i < 70; i++) {
    let x = random(400, 1250), y = random(400, 1800);
    if (fieldD(x, y) > -15) continue;
    let L = lightAt(x, y);
    fill(244 * L, 236 * L, 214 * L, 220);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, random(6, 10), random(3, 5));
    pop();
  }
  // 手边的几朵花
  let hx = CX + 10, hy = CY - 10;
  for (let i = 0; i < 9; i++) {
    let x = hx + random(-55, 55), y = hy + random(-45, 45);
    fill(246, 238, 216, 235);
    for (let k = 0; k < 5; k++) {
      let a = k * TWO_PI / 5 + random(0.4);
      ellipse(x + Math.cos(a) * 5, y + Math.sin(a) * 5, 7, 6);
    }
    fill(210, 166, 58);
    ellipse(x, y, 5, 5);
  }

  // 暖光
  let ctx = drawingContext;
  let g1 = ctx.createRadialGradient(250, 150, 50, 250, 150, 1500);
  g1.addColorStop(0, 'rgba(255,205,130,0.20)');
  g1.addColorStop(1, 'rgba(255,205,130,0)');
  fill(0);
  ctx.fillStyle = g1;
  ctx.fillRect(0, 0, width, height);

  // 暗角
  let g2 = ctx.createRadialGradient(800, 1020, 520, 800, 1020, 1400);
  g2.addColorStop(0, 'rgba(8,6,3,0)');
  g2.addColorStop(1, 'rgba(8,6,3,0.72)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, 0, width, height);
}

const W = 1600, H = 2000, HZ = 820;
const SUNX = 1040;
let edge = [], wetEdge = [];

function smoothstep(a, b, v) {
  let t = constrain((v - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}
function mix3(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function skyCol(y) {
  let t = constrain(y / HZ, 0, 1);
  const s = [[0, [20, 24, 56]], [0.45, [68, 60, 108]], [0.78, [192, 122, 126]], [1, [250, 192, 152]]];
  for (let i = 0; i < s.length - 1; i++) {
    if (t <= s[i + 1][0]) {
      let u = (t - s[i][0]) / (s[i + 1][0] - s[i][0]);
      return mix3(s[i][1], s[i + 1][1], u);
    }
  }
  return s[s.length - 1][1];
}

const SOLE = [[0, 48], [14, 42], [17, 20], [15, 0], [19, -20], [18, -35], [8, -42], [-6, -40],
  [-14, -30], [-12, -10], [-10, 10], [-14, 30], [-10, 44]];
const TOES = [[-10, -53, 11, 13], [-1, -56, 8, 10], [6, -55, 7, 9], [12, -51, 6, 8], [16, -45, 5, 7]];

function drawSole(ox, oy, k) {
  beginShape();
  let n = SOLE.length;
  for (let i = -1; i <= n + 1; i++) {
    let p = SOLE[(i + n) % n];
    curveVertex(ox + p[0] * k, oy + p[1] * k);
  }
  endShape(CLOSE);
}

function foot(x, y, s, side, a, wet) {
  push();
  translate(x, y);
  rotate(side * 0.07);
  scale(s * side, s * 0.42);
  noStroke();
  fill(80, 62, 70, 210 * a);
  drawSole(0, 0, 1);
  for (let t of TOES) ellipse(t[0], t[1], t[2], t[3]);
  if (wet) fill(222, 168, 150, 170 * a);
  else fill(160, 130, 120, 170 * a);
  drawSole(1, 6, 0.8);
  for (let t of TOES) ellipse(t[0] + 0.5, t[1] + 2, t[2] * 0.6, t[3] * 0.6);
  pop();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();

  for (let x = 0; x < W; x++) {
    edge[x] = 1235 + (noise(x * 0.0025) - 0.5) * 110 + sin(x * 0.012) * 8;
    wetEdge[x] = edge[x] + 170 + (noise(x * 0.004, 50) - 0.5) * 90;
  }

  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      let c;
      if (y < HZ) {
        c = skyCol(y);
        let n = noise(x * 0.0011, y * 0.006);
        let band = smoothstep(0.52, 0.72, n) * smoothstep(80, 300, y) * (1 - smoothstep(740, 815, y));
        let t = y / HZ;
        let cc = mix3([92, 68, 96], [228, 146, 128], pow(t, 1.6));
        c = mix3(c, cc, band * 0.75);
        let dx = x - SUNX, dy = y - (HZ + 15);
        let d = sqrt(dx * dx + dy * dy);
        let g = exp(-d / 230) * 0.9 + exp(-d / 70) * 0.6;
        c = [c[0] + g * 85, c[1] + g * 52, c[2] + g * 28];
        if (d < 48) c = mix3(c, [255, 230, 196], smoothstep(48, 44, d));
      } else if (y < edge[x]) {
        let dy = y - HZ;
        let d = constrain(dy / (1240 - HZ), 0, 1);
        c = mix3([206, 156, 148], [46, 56, 86], pow(d, 0.6));
        let WX = (x - SUNX) / (dy + 3), WZ = 1 / (dy + 3);
        let rip = noise(WX * 10 + 50, WZ * 12000);
        let sh = (rip - 0.5) * 60 * (0.35 + d);
        c = [c[0] + sh, c[1] + sh, c[2] + sh * 1.1];
        let w = 40 + dy * 0.9;
        let gx = exp(-sq((x - SUNX) / w));
        let spark = smoothstep(0.5, 0.72, rip) * gx * (1 - d * 0.5);
        c = [c[0] + 255 * spark * 0.8 + gx * 40, c[1] + 195 * spark * 0.8 + gx * 24, c[2] + 150 * spark * 0.8 + gx * 12];
        let wash = edge[x] - 100;
        if (y > wash) {
          let tt = (y - wash) / 100;
          c = mix3(c, [160, 132, 134], tt * 0.6);
        }
      } else if (y < wetEdge[x]) {
        let tt = (y - edge[x]) / (wetEdge[x] - edge[x]);
        let my = HZ - (y - HZ) * 0.35;
        let refl = skyCol(my);
        c = mix3(refl, [108, 86, 84], 0.42 + tt * 0.42);
        let w = 50 + (y - HZ) * 0.5;
        let gx = exp(-sq((x - SUNX) / w));
        let streak = noise(x * 0.05, y * 0.004);
        let k = gx * smoothstep(0.4, 0.75, streak) * (1 - tt) * 0.9;
        c = [c[0] + 240 * k, c[1] + 175 * k, c[2] + 135 * k];
        let gloss = exp(-(y - edge[x]) / 10) * 0.35;
        c = mix3(c, [240, 210, 195], gloss);
      } else {
        let u = constrain((y - 1350) / 650, 0, 1);
        c = mix3([182, 150, 136], [110, 92, 97], u);
        let Z = 1 / (y - HZ);
        let rp = sin(Z * 200000 + noise(x * 0.004, y * 0.004) * 6);
        let sh = rp * 6;
        c = [c[0] + sh, c[1] + sh, c[2] + sh];
        let damp = 1 - smoothstep(0, 40, y - wetEdge[x]);
        c = mix3(c, [120, 98, 94], damp * 0.6);
      }
      let gr = random(-6, 6);
      let i = 4 * (y * W + x);
      pixels[i] = c[0] + gr;
      pixels[i + 1] = c[1] + gr;
      pixels[i + 2] = c[2] + gr;
      pixels[i + 3] = 255;
    }
  }
  updatePixels();

  // footprints
  let i = 0;
  for (let z = 1.12; z < 4; z += 0.13, i++) {
    let y = HZ + 1250 / z;
    let side = i % 2 === 0 ? 1 : -1;
    let wx = -150 + 60 * sin(i * 0.4) + side * 42;
    let x = 800 + wx / z;
    let xi = constrain(floor(x), 0, W - 1);
    if (y < edge[xi] + 4) break;
    let a = constrain(map(y, wetEdge[xi] + 120, edge[xi], 1, 0.12), 0.12, 1);
    let wet = y < wetEdge[xi] + 10;
    foot(x, y, 1.15 / z, side, a, wet);
  }

  // breaking wave further out
  for (let x = 0; x < W; x++) {
    let wy = edge[x] - 115 + noise(x * 0.004, 9) * 30;
    stroke(36, 46, 72, 55);
    strokeWeight(1);
    line(x, wy + 2, x, wy + 12);
    if (noise(x * 0.01, 3) > 0.42) {
      stroke(250, 236, 226, 120 + 80 * noise(x * 0.05, 4));
      strokeWeight(2 + 2 * noise(x * 0.03, 5));
      point(x, wy);
    }
  }
  // thin foam streaks in the wash
  for (let k = 1; k < 4; k++) {
    noFill();
    stroke(245, 230, 222, 70 - k * 15);
    strokeWeight(1.5);
    beginShape();
    for (let x = 0; x < W; x += 4) {
      let yy = edge[x] - k * 18 - noise(x * 0.006, k * 10) * 22;
      vertex(x, yy);
    }
    endShape();
  }
  // lace foam along the tideline
  noStroke();
  for (let n = 0; n < 14000; n++) {
    let x = random(W);
    let xi = floor(x);
    let off = random() * random() * 75;
    let y = edge[xi] - off + random(-4, 8);
    if (noise(x * 0.02, y * 0.05) > 0.47) {
      fill(255, 242, 232, random(30, 120) * (1 - off / 80));
      let sz = 1 + (y - HZ) / 800;
      ellipse(x, y, random(1.5, 5) * sz, random(1, 3) * sz);
    }
  }
  // bright edge line
  noFill();
  stroke(252, 240, 230, 210);
  strokeWeight(3);
  beginShape();
  for (let x = 0; x < W; x += 3) vertex(x, edge[x] + 1);
  endShape();
  stroke(252, 240, 230, 80);
  strokeWeight(7);
  beginShape();
  for (let x = 0; x < W; x += 3) vertex(x, edge[x] - 3);
  endShape();

  // vignette
  noFill();
  strokeWeight(3);
  for (let v = 0; v < 160; v++) {
    stroke(12, 12, 28, map(v, 0, 160, 9, 0));
    rect(v * 1.5, v * 1.5, W - v * 3, H - v * 3);
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function sstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function draw() {
  drawSky();
  drawStars();
  drawLedge();
  drawShadow();
  drawCandle();
  drawSmoke();
  drawEmber();
  drawVignette();
}

function drawSky() {
  let c0 = color(3, 4, 10);
  let c1 = color(16, 20, 36);
  for (let y = 0; y < 1650; y++) {
    let t = pow(y / 1650, 1.7);
    stroke(lerpColor(c0, c1, t));
    line(0, y, width, y);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 1500; i++) {
    let x = random(width);
    let y = pow(random(), 1.9) * 1300;
    let big = random() < 0.025;
    let s = big ? random(2.4, 4) : random(0.6, 1.8);
    let a = map(y, 0, 1300, 230, 30) * random(0.35, 1);
    if (big) {
      fill(200, 210, 255, a * 0.12);
      circle(x, y, s * 6);
      fill(210, 218, 255, a * 0.25);
      circle(x, y, s * 3);
    }
    fill(225, 228, 255, a);
    circle(x, y, s);
  }
}

function drawLedge() {
  let top = 1650;
  let c0 = color(26, 22, 22);
  let c1 = color(6, 5, 6);
  for (let y = top; y < height; y++) {
    let t = (y - top) / (height - top);
    stroke(lerpColor(c0, c1, pow(t, 0.7)));
    line(0, y, width, y);
  }
  // stone texture
  for (let i = 0; i < 260; i++) {
    let y = random(top + 4, height);
    let x = random(-200, width);
    let len = random(80, 500);
    stroke(255, 255, 255, random(2, 6));
    strokeWeight(random(0.5, 1.5));
    noFill();
    beginShape();
    for (let d = 0; d < len; d += 10) {
      vertex(x + d, y + (noise((x + d) * 0.01, y * 0.02) - 0.5) * 6);
    }
    endShape();
  }
  // front edge light
  stroke(120, 130, 160, 40);
  strokeWeight(2);
  line(0, top, width, top);
  strokeWeight(1);
}

function drawShadow() {
  noStroke();
  for (let i = 0; i < 14; i++) {
    fill(0, 0, 0, 14);
    ellipse(800 + 230, 1688, 640 - i * 36, 50 - i * 2.5);
  }
}

function drawCandle() {
  let cx = 800, top = 1400, bot = 1676, r = 76;
  // body
  for (let x = -r; x <= r; x++) {
    let u = x / r;
    let curve = sqrt(max(0, 1 - u * u));
    let light = pow(map(u, -1, 1, 1, 0.12), 1.4);
    let b = 55 + light * 165;
    stroke(b * 0.93, b * 0.94, b * 0.98);
    line(cx + x, top + 16 * curve, cx + x, bot + 14 * curve);
  }
  // drips
  noStroke();
  let drips = [[-58, 70], [-34, 120], [-8, 46], [22, 88], [52, 60]];
  for (let d of drips) {
    let u = d[0] / r;
    let light = pow(map(u, -1, 1, 1, 0.12), 1.4);
    let b = 70 + light * 175;
    fill(b * 0.93, b * 0.94, b * 0.98, 220);
    let y0 = top + 16 * sqrt(1 - u * u) - 4;
    rect(cx + d[0] - 6, y0, 12, d[1], 6);
    circle(cx + d[0], y0 + d[1], 14);
  }
  // top pool
  fill(112, 114, 122);
  ellipse(cx, top, r * 2, 34);
  fill(82, 84, 92);
  ellipse(cx + 3, top + 2, r * 1.6, 24);
  noFill();
  stroke(210, 214, 228, 120);
  strokeWeight(2);
  arc(cx, top, r * 2, 34, PI * 0.9, PI * 1.9);
  strokeWeight(1);
  // wick
  stroke(18, 16, 16);
  strokeWeight(4);
  noFill();
  bezier(cx, top + 2, cx - 1, top - 18, cx + 7, top - 26, cx + 6, top - 40);
  strokeWeight(1);
}

function drawEmber() {
  let ctx = drawingContext;
  let x = 806, y = 1360;
  let g = ctx.createRadialGradient(x, y, 0, x, y, 60);
  g.addColorStop(0, 'rgba(255,120,50,0.35)');
  g.addColorStop(0.3, 'rgba(200,60,30,0.10)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(x - 60, y - 60, 120, 120);
  noStroke();
  fill(255, 150, 70);
  circle(x, y, 5);
  fill(255, 220, 160);
  circle(x, y, 2);
}

function drawSmoke() {
  blendMode(ADD);
  let N = 110;
  let sx = 806, sy = 1358;
  for (let k = 0; k < N; k++) {
    let x = sx + randomGaussian() * 0.7;
    let y = sy;
    let px = x, py = y;
    let seed = k * 0.005;
    let spread = (k - N / 2) / N;
    while (y > 40) {
      let t = (sy - y) / (sy - 40);
      let n1 = noise(y * 0.0024, seed, 3.7);
      let n2 = noise(y * 0.011, seed * 4, 9.1);
      let n3 = noise(y * 0.004, k * 0.06, 21.3);
      let dx = (n1 - 0.5) * (0.6 + t * 3.6)
             + (n2 - 0.5) * (0.2 + t * 2.0)
             + (n3 - 0.5) * sstep(0.2, 0.7, t) * 3.2
             + spread * t * 1.6;
      dx += (sx - x) * 0.0016;
      x += dx;
      y -= 2.5;

      let a = 15 * (1 - sstep(0.3, 0.72, t)) * (0.6 + 0.4 * sstep(0, 0.05, t));
      if (a > 0.3) {
        stroke(165, 172, 192, a);
        strokeWeight(1 + t * 1.6);
        line(px, py, x, y);
      }
      let p = 0.016 * sstep(0.35, 0.8, t);
      if (random() < p) {
        noStroke();
        let s = random(0.7, 2.3);
        let aa = random(60, 190) * (0.5 + 0.5 * sstep(0.4, 0.9, t));
        fill(150, 160, 200, aa * 0.15);
        circle(x + random(-4, 4), y, s * 4);
        fill(215, 220, 250, aa);
        circle(x, y, s);
      }
      px = x;
      py = y;
    }
  }
  blendMode(BLEND);
  strokeWeight(1);
}

function drawVignette() {
