  let g = ctx.createRadialGradient(800, 1150, 300, 800, 1000, 1400);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.7)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

