function vGrad(x, y, w, h, c1, c2) {
  for (let i = 0; i < h; i++) {
    stroke(lerpColor(c1, c2, i / h));
    line(x, y + i, x + w, y + i);
  }
}

function drawWall() {
  vGrad(0, 0, width, 1700, color(58, 44, 36), color(34, 25, 21));
  strokeWeight(2);
  for (let k = 0; k < 30000; k++) {
    let x = random(width), y = random(1700);
    let n = noise(x * 0.004, y * 0.004);
    stroke(n > 0.5 ? 255 : 0, 7);
    line(x, y, x + random(-6, 6), y + random(-6, 6));
