  strokeWeight(1);
}

function drawWindow() {
  let wx = 330, wy = 220, ww = 760, wh = 900;
  let top = color(22, 30, 64), mid = color(78, 80, 124), bot = color(214, 140, 112);
  for (let i = 0; i < wh; i++) {
    let t = i / wh;
    let c = t < 0.6 ? lerpColor(top, mid, t / 0.6) : lerpColor(mid, bot, (t - 0.6) / 0.4);
    stroke(c);
    line(wx, wy + i, wx + ww, wy + i);
  }
  // first star
  noStroke();
  for (let r = 30; r > 0; r -= 3) {
    fill(255, 235, 210, 6);
    circle(wx + 560, wy + 150, r);
  }
  fill(255, 245, 230, 230);
  circle(wx + 560, wy + 150, 4);

  // distant rooftops
  let base = wy + wh;
  let lit = [];
  fill(34, 30, 44);
  beginShape();
  vertex(wx, base);
  let x = wx;
  while (x < wx + ww) {
    let bw = random(50, 130);
    let bh = random(70, 230);
    vertex(x, base - bh);
    vertex(min(x + bw, wx + ww), base - bh);
    if (random() < 0.3) lit.push([x + random(10, bw - 20), base - bh + random(20, bh - 30)]);
    x += bw;
  }
  vertex(wx + ww, base);
  endShape(CLOSE);
  // a window lighting up far away
  for (let p of lit) {
    fill(240, 185, 100, 40);
    rect(p[0] - 6, p[1] - 6, 22, 26);
    fill(240, 190, 110);
    rect(p[0], p[1], 10, 14);
  }
  // glass sheen
  stroke(255, 255, 255, 10);
  strokeWeight(40);
  line(wx + 80, wy + wh, wx + 480, wy);
  strokeWeight(14);
  line(wx + 200, wy + wh, wx + 600, wy);
  strokeWeight(1);

  // frame
  noStroke();
  fill(66, 48, 36);
  rect(wx - 30, wy - 30, ww + 60, 30);
  rect(wx - 30, wy + wh, ww + 60, 30);
  rect(wx - 30, wy, 30, wh);
  rect(wx + ww, wy, 30, wh);
  rect(wx + ww / 2 - 9, wy, 18, wh);
  rect(wx, wy + wh * 0.42, ww, 18);
  fill(90, 66, 50);
  rect(wx - 60, wy + wh + 26, ww + 120, 26);
  fill(30, 22, 18, 120);
  rect(wx - 60, wy + wh + 52, ww + 120, 10);
  // light onto wall below window
  for (let k = 0; k < 6; k++) {
    fill(150, 145, 180, 6);
    quad(wx + k * 10, wy + wh + 62, wx + ww - k * 10, wy + wh + 62,
         wx + ww + 200 - k * 15, 1350, wx + 120 + k * 15, 1350);
  }
}

