function drawCup(cx, cy) {
  noStroke();
  fill(15, 10, 8, 70);
  ellipse(cx + 70, cy + 52, 320, 52);
  fill(196, 191, 186);
  ellipse(cx, cy + 40, 280, 58);
  fill(226, 222, 215);
  ellipse(cx, cy + 35, 250, 44);
  fill(205, 200, 194);
  ellipse(cx, cy + 37, 150, 22);

  // handle
  noFill();
  stroke(200, 195, 188);
  strokeWeight(16);
  bezier(cx + 84, cy - 70, cx + 155, cy - 82, cx + 155, cy + 8, cx + 70, cy + 6);
  stroke(140, 132, 130);
  strokeWeight(4);
  bezier(cx + 86, cy - 62, cx + 140, cy - 70, cx + 140, cy, cx + 72, cy);

  // body
  noStroke();
  fill(222, 218, 210);
  beginShape();
  vertex(cx - 88, cy - 95);
  bezierVertex(cx - 90, cy - 20, cx - 70, cy + 25, cx - 40, cy + 32);
  vertex(cx + 40, cy + 32);
  bezierVertex(cx + 70, cy + 25, cx + 90, cy - 20, cx + 88, cy - 95);
  endShape(CLOSE);
  for (let k = 0; k < 6; k++) {
    fill(60, 50, 62, 18);
    let sx = cx - 20 + k * 16;
    beginShape();
    vertex(sx, cy - 95);
    vertex(sx - 4, cy + 32);
    vertex(cx + 40, cy + 32);
    bezierVertex(cx + 70, cy + 25, cx + 90, cy - 20, cx + 88, cy - 95);
    endShape(CLOSE);
  }
  noFill();
  stroke(255, 255, 255, 110);
  strokeWeight(6);
  bezier(cx - 70, cy - 80, cx - 72, cy - 30, cx - 60, cy + 5, cx - 45, cy + 18);

  // rim and tea
  noStroke();
  fill(240, 236, 228);
  ellipse(cx, cy - 95, 178, 38);
  fill(92, 50, 22);
  ellipse(cx, cy - 93, 156, 29);
  fill(170, 110, 60, 90);
  ellipse(cx - 30, cy - 96, 50, 8);
}

function drawSteam(cx, cy) {
  for (let s = 0; s < 9; s++) {
    let x = cx + random(-55, 55);
    let y = cy - 100;
    let seed = random(1000);
    let steps = 460;
    let px = x, py = y;
    for (let i = 0; i < steps; i++) {
      let t = i / steps;
      x += (noise(seed, i * 0.008) - 0.5) * 5 - 1.0 * t;
      y -= 1.8;
      let a = 8 * (1 - t) * min(1, i / 40);
      noStroke();
      fill(235, 232, 242, a);
      circle(x, y, 4 + t * 44);
      let wob = sin(i * 0.05 + seed) * 3;
      stroke(245, 244, 250, 55 * (1 - t) * (1 - t) * min(1, i / 30));
      strokeWeight(1.5);
      line(px + wob, py, x + wob, y);
      px = x;
      py = y;
    }
  }
  strokeWeight(1);
}

