function smoothstep(a, b, x) {
  let t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function drawSky() {
  let top = color(3, 4, 12);
  let bot = color(20, 24, 40);
  for (let y = 0; y < 1700; y++) {
    stroke(lerpColor(top, bot, pow(y / 1700, 1.6)));
    line(0, y, width, y);
  }
  // 极淡的暖色余晖，围绕刚熄灭的蜡烛
  noStroke();
  for (let r = 520; r > 0; r -= 8) {
    fill(70, 40, 20, 1.6);
    ellipse(WX, WY + 60, r * 1.6, r * 1.4);
  }
}

function drawBgStars() {
  noStroke();
  for (let i = 0; i < 1100; i++) {
    let y = pow(random(), 2.4) * 1550;
    let x = random(width);
    let s = random(0.5, 1.8);
    let a = random(30, 150) * (1 - y / 1700);
    fill(215, 222, 240, a);
    circle(x, y, s);
  }
  // 少量带光晕的远星
  for (let i = 0; i < 25; i++) {
    let y = pow(random(), 2) * 900;
    let x = random(width);
    drawingContext.shadowBlur = 14;
    drawingContext.shadowColor = 'rgba(200,215,255,0.7)';
    fill(230, 235, 255, 180);
    circle(x, y, random(1.8, 3));
  }
  drawingContext.shadowBlur = 0;
}

function drawTable() {
  let c1 = color(20, 16, 16);
  let c2 = color(5, 4, 5);
  for (let y = 1700; y < height; y++) {
    stroke(lerpColor(c1, c2, (y - 1700) / 300));
    line(0, y, width, y);
  }
  // 木纹
  noFill();
  for (let k = 0; k < 40; k++) {
    let y0 = random(1705, 2000);
    stroke(40, 30, 26, random(8, 22));
    strokeWeight(random(0.6, 1.6));
    beginShape();
    for (let x = 0; x <= width; x += 20) {
      vertex(x, y0 + (noise(x * 0.002, k) - 0.5) * 14);
    }
    endShape();
  }
  // 桌沿的一线冷光
  stroke(90, 95, 115, 40);
  strokeWeight(1.5);
  line(0, 1700, width, 1700);
  strokeWeight(1);
}

function drawSmoke() {
  const strands = 170;
  const N = 320;
  strokeWeight(1.1);
  for (let i = 0; i < strands; i++) {
    let px = null, py = null;
    for (let s = 0; s <= N; s++) {
      let t = s / N;
      let y = WY - pow(t, 0.92) * 1360;
      let shared = (noise(t * 2.2, 10) - 0.5) * 720 * pow(t, 1.3)
                 + sin(t * 9 + noise(t * 3, 20) * 4) * 55 * t;
      let indiv = (noise(i * 0.035, t * 3.5, 5) - 0.5) * 950 * pow(t, 2.1);
      let x = WX + shared + indiv;

      if (px !== null) {
        let a = 20 * (1 - smoothstep(0.5, 0.88, t)) * min(1, t / 0.02);
        let col = lerpColor(color(175, 182, 200), color(150, 165, 200), t);
        stroke(red(col), green(col), blue(col), a);
        line(px, py, x, y);
      }
      // 烟在上升中逐渐散成星
      if (t > 0.42 && random() < 0.05 * smoothstep(0.42, 1.0, t)) {
        smokeStars.push({
          x: x + random(-18, 18) * t,
          y: y + random(-18, 18) * t,
          t: t
        });
      }
      px = x; py = y;
    }
  }
}

function drawSmokeStars() {
  noStroke();
  for (let st of smokeStars) {
    let k = smoothstep(0.42, 1.0, st.t);
    let r = lerp(170, 255, k);
    let g = lerp(180, 238, k);
    let b = lerp(205, 205, k);
    let sz = random(0.8, 2.4) * (0.5 + st.t);
    let a = lerp(90, 230, k);
    if (random() < 0.07) {
      drawingContext.shadowBlur = 18 + 14 * k;
      drawingContext.shadowColor = 'rgba(255,235,205,' + (0.5 + 0.4 * k) + ')';
      sz *= 1.6;
    } else {
      drawingContext.shadowBlur = 4;
      drawingContext.shadowColor = 'rgba(220,225,240,0.4)';
    }
    fill(r, g, b, a);
    circle(st.x, st.y, sz);
  }
  drawingContext.shadowBlur = 0;
}

function candleTop(x) {
  let u = (x - 800) / 60;
  return 1490 + 9 * (1 - u * u) + (noise(x * 0.06, 3) - 0.5) * 8;
}

function candleColor(x) {
  let u = (x - 800) / 60; // -1..1
  let lit = constrain(1 - abs(u + 0.35) * 0.9, 0, 1);
  return lerpColor(color(48, 44, 46), color(196, 186, 168), pow(lit, 1.3));
}

function drawCandle() {
  strokeWeight(1);
  for (let x = 740; x <= 860; x++) {
    stroke(candleColor(x));
    line(x, candleTop(x), x, 1700);
  }
  // 蜡泪
  let drips = [[752, 60, 8], [771, 28, 6], [826, 85, 9], [849, 40, 6]];
  noStroke();
  for (let d of drips) {
    let c = candleColor(d[0]);
    fill(min(red(c) + 18, 255), min(green(c) + 16, 255), min(blue(c) + 12, 255));
    let y0 = candleTop(d[0]);
    rect(d[0] - d[2] / 2, y0, d[2], d[1]);
    ellipse(d[0], y0 + d[1], d[2] * 1.15, d[2] * 1.4);
  }
  // 凝固的蜡池
  fill(120, 112, 102);
  ellipse(800, 1497, 112, 18);
  fill(95, 88, 82);
  ellipse(802, 1499, 70, 10);
  // 灯芯
  noFill();
  stroke(18, 14, 14);
  strokeWeight(4);
  beginShape();
  curveVertex(800, 1504);
  curveVertex(800, 1500);
  curveVertex(801, 1482);
  curveVertex(806, 1463);
  curveVertex(810, 1455);
  endShape();
  strokeWeight(1);
  // 底部阴影
  noStroke();
  fill(0, 0, 0, 90);
  ellipse(800, 1702, 150, 12);
}

function drawCandleReflection() {
  noStroke();
  for (let y = 1700; y < 1800; y++) {
    let a = 22 * (1 - (y - 1700) / 100);
    fill(150, 140, 125, a);
    rect(742, y, 116, 1);
  }
}

function drawEmber() {
  noStroke();
