function drawGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = random(-6, 6);
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);

  // 1. 绘制深邃的背景与微光
  drawBackground();

  // 2. 绘制远景的星尘与虚空纹理
  drawVoidTexture();

  // 3. 绘制核心：生命的解构与消散（流场粒子）
  drawDissolution();

  // 4. 绘制游离的灵魂微粒（上升的光点）
  drawAscendingEmbers();

  // 5. 添加全局的质感与暗角
  applyVignetteAndGrain();
}

function drawBackground() {
  background(240, 35, 4);

  // 使用大幅度的半透明圆叠加出深邃的幽暗渐变
  noStroke();
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height);
    let r = random(400, 1200);

    // 底部偏暖暗红/焦茶色（泥土与肉身），顶部偏冷青/深蓝（虚空与以太）
    let ratio = y / height;
    let h = lerp(210, 15, pow(ratio, 1.5));
    let s = lerp(40, 60, ratio);
    let b = lerp(6, 12, sin(ratio * PI));

    fill(h, s, b, 0.03);
    circle(x, y, r);
  }

  // 核心光源的微弱底光
  for (let r = 1000; r > 50; r -= 20) {
    fill(35, 50, 25, 0.008);
    ellipse(width * 0.5, height * 0.65, r * 0.8, r * 1.2);
  }
}

function drawVoidTexture() {
  // 垂直的微弱线条，像时间的雨幕或重力场
  strokeWeight(1);
  for (let i = 0; i < 3000; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(50, 400);
    let alpha = random(0.005, 0.02);

    // 越往上越偏向青白色
    let h = map(y, 0, height, 195, 240);
    stroke(h, 20, 60, alpha);
    line(x, y, x, y + len);
  }
}

function drawDissolution() {
  // 混合模式改为叠加，产生发光与灵魂出窍的质感
  blendMode(ADD);

  let numStrands = 22000;
  let centerX = width * 0.5;
  let coreY = height * 0.68;

  for (let i = 0; i < numStrands; i++) {
    // 决定粒子的起始位置：大部分集中在下半部分的“生命核心”
    // 使用高斯分布的变体让中心更密集
    let angle = random(TWO_PI);
    let radius = pow(random(), 1.8) * 320;

    // 将圆形挤压变形，使其更像一个茧或心脏
    let x = centerX + cos(angle) * radius * 0.85;
    let y = coreY + sin(angle) * radius * 1.15;

    // 还有一部分从核心底部向下延伸，像枯萎的根系
    if (random() < 0.2) {
      x = centerX + randomGaussian() * 120;
      y = random(coreY, height * 0.92);
    }

    let maxSteps = int(random(60, 280));

    // 粒子属性
    let isGold = random() < 0.35; // 一部分是纯粹的黄金（精神），一部分是灰烬与血肉

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;

      // 高度比例 (0在顶部，1在底部)
      let heightRatio = constrain(y / height, 0, 1);
      // 消散程度：越往上、步数越多，越消散
      let dissipation = constrain(map(y, coreY + 100, height * 0.1, 0, 1), 0, 1);

      // 计算噪声流场
      let nScale1 = 0.0025;
      let nScale2 = 0.01;
      let n1 = noise(x * nScale1, y * nScale1);
      let n2 = noise(x * nScale2 + 100, y * nScale2 + 100);

      // 基础流向：向上（-HALF_PI）
      let baseAngle = -HALF_PI;

      // 在核心区域，线条缠绕旋转（生命的纠葛）
      // 在上方区域，线条随风飘散（死亡的解脱）
      let distToCore = dist(x, y, centerX, coreY);
      let swirlFactor = constrain(map(distToCore, 0, 400, 1, 0), 0, 1);

      let flowAngle;
      if (swirlFactor > 0.2) {
        // 核心处的漩涡与纠缠
        let angleToCenter = atan2(y - coreY, x - centerX);
        let swirlDir = (i % 2 === 0) ? 1 : -1;
        flowAngle = angleToCenter + HALF_PI * swirlDir * 0.8 + (n1 - 0.5) * PI * 2;
        // 依然带有向上的趋势
        flowAngle = lerp(flowAngle, baseAngle + (n2 - 0.5) * PI, 1 - swirlFactor);
      } else {
        // 外部的消散流场
        let spread = map(y, coreY, 0, 0.5, 2.2);
        flowAngle = baseAngle + (n1 - 0.5) * PI * spread + (n2 - 0.5) * 0.8;
      }

      // 色彩演变
      let h, s, b, alpha;

      if (isGold) {
        // 黄金 -> 苍白青光
        h = lerp(42, 190, pow(dissipation, 1.2));
        s = lerp(85, 15, dissipation);
        b = lerp(100, 70, dissipation);
        alpha = sin(progress * PI) * lerp(0.08, 0.015, dissipation);
      } else {
        // 绯红/焦土 -> 幽暗紫蓝 -> 虚无灰
        h = lerp(12, 230, pow(dissipation, 0.9));
        s = lerp(75, 30, dissipation);
        b = lerp(60, 40, dissipation);
        alpha = sin(progress * PI) * lerp(0.05, 0.01, dissipation);
      }

      // 距离中心极近的地方增加亮度，形成“内核”
      if (distToCore < 150) {
        b = min(100, b * 1.5);
      }

      stroke(h, s, b, alpha);

      // 笔触粗细随消散而变细
      let sw = map(progress, 0, 1, 2.2, 0.3) * map(dissipation, 0, 1, 1.2, 0.5);
      strokeWeight(sw);

      let stepSize = map(dissipation, 0, 1, 1.5, 4.5);
      let nextX = x + cos(flowAngle) * stepSize;
      let nextY = y + sin(flowAngle) * stepSize;

      // 在高处，线条断裂成点（灰烬化）
      if (dissipation > 0.4 && random() < dissipation * 0.7) {
        if (random() < 0.2) {
          strokeWeight(sw * 1.5);
          point(x, y);
        }
      } else {
        line(x, y, nextX, nextY);
      }

      x = nextX;
      y = nextY;

      // 超出画布则停止
      if (x < 0 || x > width || y < 0 || y > height) break;
    }
  }

  // 恢复默认混合模式，绘制内部的“空洞”与暗影结构，增加体积感
  blendMode(BLEND);
  for (let i = 0; i < 1500; i++) {
    let angle = random(TWO_PI);
    let r = pow(random(), 2) * 260;
    let x = centerX + cos(angle) * r * 0.8;
    let y = coreY + 40 + sin(angle) * r * 1.1; // 偏下一点，制造底部的沉重感

    noFill();
    stroke(240, 40, 5, random(0.05, 0.15)); // 极暗的线条，像是枯木或裂痕
    strokeWeight(random(0.5, 2.5));

    beginShape();
    for (let j = 0; j < 20; j++) {
      vertex(x, y);
      let n = noise(x * 0.008, y * 0.008);
      x += cos(n * TWO_PI * 2) * 3;
      y += sin(n * TWO_PI * 2) * 3;
    }
    endShape();
  }
}

function drawAscendingEmbers() {
  blendMode(ADD);
  noStroke();

  let centerX = width * 0.5;
  let coreY = height * 0.68;

  // 绘制从核心剥落、向上漂浮的光尘
  for (let i = 0; i < 4500; i++) {
    // 越往上越宽广的分布（漏斗形扩散）
    let y = pow(random(), 0.8) * (coreY + 200);
    let heightProgress = map(y, coreY + 200, 0, 0, 1);

    let spread = map(heightProgress, 0, 1, 150, 650);
    let x = centerX + randomGaussian() * spread;

    // 利用噪声让光尘形成聚落，而不是均匀分布
    let clusterNoise = noise(x * 0.004, y * 0.004);
    if (clusterNoise < 0.42) continue;

    // 大小与颜色
    let isBright = random() < 0.08;
    let r = isBright ? random(2.5, 6) : random(0.5, 2.5);

    // 随高度增加，尺寸变小，逐渐消失在顶部
    r *= map(heightProgress, 0, 1, 1.2, 0.2);

    let h = lerp(38, 195, pow(heightProgress, 0.7)) + random(-10, 10);
    let s = lerp(80, 10, heightProgress);
    let b = lerp(100, 60, heightProgress);

    // 顶部渐渐完全透明
    let fadeOut = constrain(map(y, 0, 300, 0, 1), 0, 1);
    let alpha = random(0.1, 0.6) * fadeOut;

    if (isBright) {
      // 绘制带有光晕的粒子
      for (let glow = 3; glow > 0; glow--) {
        fill(h, s, b, alpha * 0.15);
        circle(x, y, r * glow * 2.5);
      }
      fill(h, s * 0.3, 100, alpha * 1.5);
      circle(x, y, r);
    } else {
      fill(h, s, b, alpha * 0.7);
      circle(x, y, r);
    }
  }

  // 极少数最后消散在高处的微弱游丝
  strokeWeight(0.6);
  for (let i = 0; i < 300; i++) {
    let x = centerX + randomGaussian() * 400;
    let y = random(100, coreY - 200);
    let len = random(10, 40);

    stroke(195, 15, 80, random(0.02, 0.08));
    noFill();
    beginShape();
    for (let s = 0; s < len; s++) {
      vertex(x, y);
      let n = noise(x * 0.01, y * 0.01);
      x += sin(n * TWO_PI) * 1.5;
      y -= 1.5;
    }
    endShape();
  }

  blendMode(BLEND);
}

function applyVignetteAndGrain() {
  loadPixels();
  let d = pixelDensity();
  let halfW = width * 0.5;
  let halfH = height * 0.5;
  let maxDist = dist(0, 0, halfW, halfH);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let index = 4 * (y * width + x);

      // 计算暗角 (Vignette)，顶部更暗，营造深不见底的虚空感
      let dy = (y < halfH) ? (y - halfH) * 1.2 : (y - halfH) * 0.9;
      let distFromCenter = dist(x, y, halfW, halfH + dy * 0.2);
      let vig = constrain(map(distFromCenter, maxDist * 0.35, maxDist * 1.05, 1, 0.15), 0.15, 1);

      // 胶片颗粒感 (Film Grain)
      let grain = random(-10, 10);

      let r = pixels[index];
      let g = pixels[index + 1];
      let b = pixels[index + 2];

      // 应用暗角和颗粒，同时稍微提升暗部的蓝紫色调
      r = constrain(r * vig + grain, 0, 255);
      g = constrain(g * vig + grain, 0, 255);
      b = constrain(b * pow(vig, 0.85) + grain, 0, 255);

      pixels[index] = r;
      pixels[index + 1] = g;
      pixels[index + 2] = b;
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Deep Void Background
  background(7, 8, 14);

  // 2. Background Nebula / Atmospheric Wash
  drawAtmosphere();

  // 3. The Horizon of Passing (Subtle eclipse/halo in the upper center)
  drawVoidHalo(800, 520, 460);

  // 4. The Unspooling (Life form dissolving into the void)
  drawTheUnspooling();

  // 5. Lingering Memories (Bokeh & fine ash)
  drawEchoes();

  // 6. Texture & Vignette (Aged canvas & framing)
  applyVignetteAndGrain();
}

function drawAtmosphere() {
  noStroke();
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let r = map(n, 0, 1, 100, 600);

    let yRatio = y / height;
    let c;
    if (yRatio < 0.45) {
      // Upper void: deep obsidian blue & subtle violet
      c = lerpColor(color(10, 12, 24, 6), color(28, 18, 38, 4), n);
    } else if (yRatio < 0.75) {
      // Transition zone: muted warmth & bruised indigo
      c = lerpColor(color(28, 18, 38, 5), color(55, 32, 36, 6), (yRatio - 0.45) / 0.3);
    } else {
      // Lower earth/vessel: heavy slate & cold bone shadow
      c = lerpColor(color(16, 22, 32, 8), color(8, 10, 16, 15), (yRatio - 0.75) / 0.25);
    }

    fill(c);
    circle(x, y, r);
  }
}

function drawVoidHalo(hx, hy, radius) {
  push();
  blendMode(ADD);
  noStroke();

  // Outer glow of the eclipse
  for (let r = radius * 2.5; r > radius * 0.8; r -= 4) {
    let norm = map(r, radius * 0.8, radius * 2.5, 0, 1);
    let alpha = pow(1 - abs(norm - 0.25) * 1.3, 3) * 1.8;
    if (alpha > 0) {
      fill(190, 145, 105, alpha);
      circle(hx, hy, r * 2);
    }
  }

  // Fine concentric rings (ripples in eternity)
  noFill();
  for (let i = 0; i < 120; i++) {
    let r = radius * random(0.95, 1.8);
    let aStart = random(TWO_PI);
    let aEnd = aStart + random(PI * 0.1, PI * 0.6);
    strokeWeight(random(0.5, 2.0));
    stroke(220, 185, 145, random(2, 10));
    arc(hx, hy, r * 2, r * 2, aStart, aEnd);
  }
  pop();

  // The dark core of the eclipse
  noStroke();
  for (let r = radius; r > 0; r -= 2) {
    let inter = map(r, 0, radius, 1, 0);
    let alpha = pow(inter, 1.5) * 18;
    fill(6, 7, 12, alpha);
    circle(hx, hy, r * 2);
  }
}

function drawTheUnspooling() {
  let numStrands = 3400;

  // Define palettes
  let cDeepBone   = color(35, 48, 68);
  let cMidSlate   = color(75, 98, 122);
  let cPaleBone   = color(215, 210, 200);
  let cDyingEmber = color(205, 115, 85);
  let cSpiritGold = color(245, 200, 140);
  let cVoidDust   = color(110, 95, 130);

  for (let i = 0; i < numStrands; i++) {
    // Concentrate origins at the bottom center like a monolithic vessel or mountain
    let u = random(-1, 1);
    let spread = pow(abs(u), 1.35) * (u < 0 ? -1 : 1);
    let x = width * 0.5 + spread * 680;
    let y = height + random(-60, 80);

    let strandSeed = random(10000);
    let isGoldenVein = random() < 0.18;
    let maxSteps = int(random(500, 1450));

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;
      let yRatio = constrain(y / height, 0, 1);

      // Dissolution factor: 0 at bottom (solid), 1 at top (completely dissolved)
      let dissolve = constrain(map(yRatio, 0.88, 0.12, 0, 1), 0, 1);
      dissolve = pow(dissolve, 1.4);

      // Multi-scale curl/flow field
      let n1 = noise(x * 0.002, y * 0.002, strandSeed * 0.01);
      let n2 = noise(x * 0.008, y * 0.008, i * 0.005);

      // Base angle points upward (-HALF_PI)
      // At the bottom, tight architectural/organic weaving; at the top, wide turbulent drifting
      let angleOffset = map(n1, 0, 1, -PI * 0.45, PI * 0.45) * (0.25 + dissolve * 1.1) 
                      + map(n2, 0, 1, -PI * 0.25, PI * 0.25) * dissolve;
      let angle = -HALF_PI + angleOffset;

      // Pull inwards slightly at the "neck" of the vessel (around yRatio = 0.65)
      let centerDist = (width * 0.5 - x) / (width * 0.5);
      if (yRatio > 0.45 && yRatio < 0.85) {
        angle += centerDist * 0.35 * sin(map(yRatio, 0.45, 0.85, 0, PI));
      }
      // Subtle attraction/swirl around the eclipse halo
      if (yRatio <= 0.45) {
        let dx = x - 800;
        let dy = y - 520;
        let d = sqrt(dx * dx + dy * dy);
        if (d < 500) {
          let tangent = atan2(dy, dx) + HALF_PI;
          angle = lerp(angle, tangent, map(d, 500, 0, 0, 0.35));
        }
      }

      let stepSize = map(dissolve, 0, 1, 1.8, 4.2);
      x += cos(angle) * stepSize;
      y += sin(angle) * stepSize;

      // Quantum/dust scatter as it dies/ascends
      let drawX = x;
      let drawY = y;
      if (dissolve > 0.15) {
        let scatterRadius = pow(dissolve - 0.15, 2.2) * 260;
        let sAngle = noise(step * 0.1, strandSeed) * TWO_PI * 4;
        let sRad = random(0, scatterRadius);
        drawX += cos(sAngle) * sRad;
        drawY += sin(sAngle) * sRad;
      }

      // Skip drawing randomly at high dissolution to create airy dust
      if (random() < dissolve * 0.72) continue;

      // Color evolution from heavy matter to ethereal light
      let col;
      if (isGoldenVein) {
        if (dissolve < 0.4) {
          col = lerpColor(cDeepBone, cDyingEmber, dissolve / 0.4);
        } else {
          col = lerpColor(cDyingEmber, cSpiritGold, (dissolve - 0.4) / 0.6);
        }
      } else {
        if (dissolve < 0.3) {
          col = lerpColor(cDeepBone, cMidSlate, dissolve / 0.3);
        } else if (dissolve < 0.65) {
          col = lerpColor(cMidSlate, cPaleBone, (dissolve - 0.3) / 0.35);
        } else {
          col = lerpColor(cPaleBone, cVoidDust, (dissolve - 0.65) / 0.35);
        }
      }

      // Alpha and weight calculation
      let fadeEnds = sin(progress * PI);
      let baseAlpha = map(dissolve, 0, 1, 55, 14) * fadeEnds;
      let sw = map(dissolve, 0, 1, 2.4, 0.75) * map(n2, 0, 1, 0.6, 1.5);

      // Occasional bright sparks of released soul/energy in the upper half
      if (dissolve > 0.35 && random() < 0.008) {
        push();
        blendMode(ADD);
        noStroke();
        let glowSize = random(4, 18);
        fill(255, 220, 175, random(15, 45));
        circle(drawX, drawY, glowSize);
        fill(255, 245, 230, random(80, 160));
        circle(drawX, drawY, glowSize * 0.3);
        pop();
      } else {
        stroke(red(col), green(col), blue(col), baseAlpha);
        strokeWeight(sw);
        point(drawX, drawY);
      }

      // Stop if out of bounds
      if (drawY < -50 || drawX < -50 || drawX > width + 50) break;
    }
  }

  // Add structural negative-space cracks/fissures at the base (erosion of the body)
  drawFissures();
}

function drawFissures() {
  for (let i = 0; i < 180; i++) {
    let x = width * 0.5 + random(-550, 550);
    let y = random(height * 0.65, height);
    let len = int(random(80, 300));

    for (let s = 0; s < len; s++) {
      let n = noise(x * 0.005, y * 0.005, i);
      let a = -HALF_PI + map(n, 0, 1, -PI * 0.4, PI * 0.4);
      x += cos(a) * 1.5;
      y += sin(a) * 1.5;

      let progress = sin((s / len) * PI);
      stroke(8, 10, 16, progress * 65);
      strokeWeight(map(n, 0, 1, 0.8, 3.5));
      point(x, y);
    }
  }
}

function drawEchoes() {
  // Soft out-of-focus memory orbs and floating ash in the upper void
  push();
  noStroke();
  for (let i = 0; i < 900; i++) {
    let x = random(width);
    let y = random(height * 0.85);

    // Bias towards the central ascending column and the halo
    let distFromCenter = abs(x - width * 0.5) / (width * 0.5);
    if (random() < distFromCenter * 0.7) continue;

    let yRatio = y / height;
    let sz = random(1, 5);

    if (random() < 0.06 && yRatio < 0.6) {
      // Soft bokeh orb
      blendMode(ADD);
      let orbSize = random(12, 55);
      for (let r = orbSize; r > 0; r -= 3) {
        fill(235, 195, 150, map(r, 0, orbSize, 4, 0.2));
        circle(x, y, r);
      }
    } else {
      // Fine ash speck
      blendMode(BLEND);
      let isWarm = random() < 0.4;
      if (isWarm) {
        fill(240, 205, 165, random(20, 110) * (1 - yRatio * 0.5));
      } else {
        fill(180, 195, 210, random(15, 70));
      }
      circle(x, y, sz);
    }
  }
  pop();
}

function applyVignetteAndGrain() {
  // Subtle organic canvas texture & film grain
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);

  for (let i = 0; i < totalPixels; i += 4) {
    let idx = i / 4;
    let px = (idx % (width * d)) / d;
    let py = floor(idx / (width * d)) / d;

    // Distance from center for vignette
    let dx = (px - width * 0.5) / (width * 0.5);
    let dy = (py - height * 0.5) / (height * 0.5);
    let distSq = dx * dx + dy * dy;
    let vig = constrain(map(distSq, 0.5, 1.8, 1.0, 0.28), 0.28, 1.0);

    // Fine grain
    let grain = random(-10, 10);

    pixels[i]     = constrain(pixels[i] * vig + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] * vig + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] * vig + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);
  background(240, 65, 4);

  // 1. 绘制深空背景与星云层次
  drawBackgroundNebula();

  // 2. 绘制远景星辰
  drawStars(2500);

  // 3. 绘制水面/虚空边界的基底高光
  drawHorizonGlow();

  // 4. 绘制向上升腾的灵魂丝线与光流
  blendMode(ADD);
  drawSoulStreams();

  // 5. 绘制正在消散的物质躯壳（沉睡者）
  blendMode(BLEND);
  drawDissolvingBody();

  // 6. 绘制从躯体剥离并升空的发光微粒与余烬
  blendMode(ADD);
  drawAscendingEmbers();

  // 7. 绘制画面顶部的神圣归宿之光（天顶光晕）
  drawZenithLight();

  // 8. 绘制底部静谧的暗水倒影与虚空纹理
  blendMode(BLEND);
  drawAbyssWater();

  // 9. 全局胶片颗粒与暗角，增加绘画质感
  drawVignetteAndGrain();
}

// 获取沉睡躯体的轮廓高度
function getBodyY(x) {
  let base = 1650;
  if (x < 250 || x > 1350) return base;

  // 头部与肩部 (左侧)
  let head = -95 * exp(-pow((x - 420) / 75, 2));
  let neck = 25 * exp(-pow((x - 510) / 45, 2));
  // 胸腔 (核心区)
  let chest = -135 * exp(-pow((x - 660) / 140, 2));
  // 腰腹与臀部
  let waist = 15 * exp(-pow((x - 830) / 70, 2));
  let hip = -85 * exp(-pow((x - 950) / 110, 2));
  // 腿部延伸与脚尖 (右侧)
  let legs = -55 * exp(-pow((x - 1140) / 140, 2));
  let feet = -35 * exp(-pow((x - 1270) / 45, 2));

  // 叠加细微的岩石/枯木肌理噪波
  let n = (noise(x * 0.015, 10) - 0.5) * 18;

  return base + head + neck + chest + waist + hip + legs + feet + n;
}

function drawBackgroundNebula() {
  noStroke();
  for (let y = 0; y < height; y += 4) {
    let t = y / height;
    // 从顶部的幽邃紫蓝到底部的死寂暗青
    let h = lerp(255, 215, t);
    let s = lerp(60, 45, t);
    let b = lerp(12, 3, pow(t, 0.7));
    fill(h, s, b);
    rect(0, y, width, 5);
  }

  // 绘制背景中的模糊光云
  blendMode(ADD);
  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(height * 0.85);
    let n = noise(x * 0.002, y * 0.002);
    let r = random(150, 500) * n;

    // 越靠近中心轴线越亮
    let distToCenter = abs(x - 750) / (width * 0.5);
    let alpha = map(distToCenter, 0, 1, 0.025, 0.002) * n;

    let hueVal = map(y, 0, height, 270, 195) + random(-15, 15);
    fill(hueVal, 55, 60, alpha);
    circle(x, y, r);
  }
  blendMode(BLEND);
}

function drawStars(count) {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < count; i++) {
    let x = random(width);
    let y = random(height * 0.82);
    let fade = map(y, 0, height * 0.82, 1, 0.1);
    let sz = pow(random(1), 4) * 4.5 + 0.5;
    let b = random(40, 100);
    let s = random(0, 40);
    let h = random(190, 260);

    fill(h, s, b, random(0.2, 0.8) * fade);
    circle(x, y, sz);

    // 少数亮星带有十字星芒
    if (sz > 3.8 && random() < 0.3) {
      stroke(h, s * 0.5, 100, 0.3 * fade);
      strokeWeight(0.8);
      let flare = sz * 5;
      line(x - flare, y, x + flare, y);
      line(x, y - flare, x, y + flare);
      noStroke();
    }
  }
}

function drawHorizonGlow() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 60; i++) {
    let w = map(i, 0, 60, width * 0.9, width * 0.2);
    let h = map(i, 0, 60, 300, 20);
    fill(205, 60, 40, 0.012);
    ellipse(780, 1650, w, h);
  }
}

function drawSoulStreams() {
  noFill();
  let numStreams = 1600;

  for (let i = 0; i < numStreams; i++) {
    // 使用正态分布让大部分丝线从躯体核心（胸腔、头部）升起
    let startX = constrain(randomGaussian(730, 210), 340, 1280);
    let startY = getBodyY(startX) + random(5, 45);

    let x = startX;
    let y = startY;
    let steps = int(random(120, 420));

    // 决定丝线的色彩倾向：金色（余温）、青色（灵体）、幽紫（宇宙）
    let colorType = random();
    let baseHue = colorType < 0.25 ? random(30, 50) : (colorType < 0.75 ? random(185, 215) : random(250, 280));

    strokeWeight(random(0.4, 2.2));

    let px = x;
    let py = y;

    for (let s = 0; s < steps; s++) {
      let progress = s / steps;
      let altitude = map(y, 1650, 0, 0, 1);

      // 流体噪波场控制上升轨迹
      let n1 = noise(x * 0.0025, y * 0.0025, i * 0.0005);
      let n2 = noise(x * 0.008, y * 0.008, 50);

      // 向上聚拢再散开的S型趋势
      let pullToCenter = (760 - x) * 0.0018 * sin(altitude * PI);
      let angle = - HALF_PI + (n1 - 0.5) * 1.4 + (n2 - 0.5) * 0.5 + pullToCenter;

      let speed = map(progress, 0, 1, 2.5, 5.5);
      x += cos(angle) * speed;
      y += sin(angle) * speed;

      // 颜色随高度演变：从底部的暖金/苍白，过渡到高空的冷青与亮白
      let h = lerp(baseHue, 220, altitude * 0.6);
      let sat = lerp(65, 15, pow(altitude, 1.5));
      let bri = lerp(70, 100, altitude);

      // 两端渐隐
      let alpha = sin(progress * PI) * map(altitude, 0, 1, 0.06, 0.02);

      stroke(h, sat, bri, alpha);
      line(px, py, x, y);

      px = x;
      py = y;

      if (y < 80) break;
    }
  }
}

function drawDissolvingBody() {
  // 通过数万个细密的笔触/碎片构建半解体的躯壳
  let startX = 320;
  let endX = 1300;

  for (let x = startX; x <= endX; x += 1.5) {
    let topY = getBodyY(x);
    let bottomY = 1655;

    if (topY >= bottomY) continue;

    for (let y = topY; y <= bottomY; y += 2.5) {
      let depth = (y - topY) / (bottomY - topY); // 0为表皮，1为基底
      let n = noise(x * 0.02, y * 0.02);
      let fineN = noise(x * 0.08, y * 0.08);

      // 顶部边缘和高处（如胸口、面部）正在剧烈消散，产生空洞
      let dissolveThreshold = map(depth, 0, 0.6, 0.65, 0.1) + map(topY, 1500, 1650, 0.25, -0.1);

      if (n * 0.7 + fineN * 0.3 > dissolveThreshold) {
        // 躯体内部沉重、冰冷，类似黑曜石或灰烬
        let h = 230 + (n - 0.5) * 30;
        let s = map(depth, 0, 1, 25, 45);
        let b = map(depth, 0, 1, 22, 4) * fineN * 1.5;

        noStroke();
        fill(h, s, b, 0.85);

        // 用微小的不规则多边形或椭圆模拟斑驳的物质感
        let w = random(2, 6);
        let hRect = random(1.5, 4);
        push();
        translate(x + random(-1, 1), y + random(-1, 1));
        rotate((n - 0.5) * 0.8);
        rect(0, 0, w, hRect);
        pop();
      } else if (depth < 0.28 && random() < 0.35) {
        // 在剥落的边缘处，露出内部温暖的生命余烬（金橘色与青白色微光）
        let isGold = random() < 0.65;
        let glowH = isGold ? random(25, 48) : random(185, 205);
        let glowS = isGold ? 80 : 40;
        fill(glowH, glowS, 95, random(0.3, 0.8));
        noStroke();
        circle(x + random(-2, 2), y + random(-2, 2), random(1, 3.5));
      }
    }
  }
}

function drawAscendingEmbers() {
  noStroke();

  // 1. 贴近躯体表面正在剥离的物质碎片与余烬
  for (let i = 0; i < 4500; i++) {
    let x = constrain(randomGaussian(740, 220), 330, 1290);
    let bodyY = getBodyY(x);
    // 分布在躯体上方不远处
    let offset = pow(random(1), 2.5) * 550;
    let y = bodyY - offset + random(-10, 20);

    let n = noise(x * 0.01, y * 0.01);
    let size = map(offset, 0, 550, random(1.5, 5.5), random(0.5, 2.5));

    // 越靠近身体越偏向沉暗的灰烬或赤金，越往上越明亮通透
    if (offset < 120 && random() < 0.4) {
      // 飘起的暗色灰烬（切换到BLEND模式绘制一小部分）
      blendMode(BLEND);
      fill(230, 30, 12, map(offset, 0, 120, 0.8, 0));
      push();
      translate(x + (n - 0.5) * 40, y);
      rotate(random(TWO_PI));
      rect(0, 0, size * 1.2, size * 0.7);
      pop();
      blendMode(ADD);
    } else {
      // 发光的灵魂微粒
      let h = lerp(35, 195, constrain(offset / 350, 0, 1)) + random(-15, 15);
      let s = map(offset, 0, 550, 80, 30);
      let alpha = map(offset, 0, 550, 0.7, 0.1) * n;

      fill(h, s, 100, alpha);
      circle(x + (n - 0.5) * 60, y, size);

      // 微粒的柔和光晕
      if (size > 2.5) {
        fill(h, s, 90, alpha * 0.25);
        circle(x + (n - 0.5) * 60, y, size * 3.5);
      }
    }
  }

  // 2. 贯穿整个画面的高空升腾光尘（连接凡躯与苍穹）
  for (let i = 0; i < 3500; i++) {
    let y = random(60, 1600);
    let altitude = map(y, 1600, 60, 0, 1);

    // 宽度随高度先收拢后向宇宙扩散
    let spread = lerp(210, 90, sin(altitude * PI)) + pow(altitude, 3) * 280;
    let x = randomGaussian(760, spread);

    // 叠加流体位移，使其与丝线轨迹吻合
    let n = noise(x * 0.004, y * 0.004);
    x += (n - 0.5) * 180;

    let sz = pow(random(1), 3) * 5 + 0.8;
    let h = lerp(40, 210, pow(altitude, 0.6)) + random(-20, 20);
    let s = lerp(70, 10, altitude);
    let a = random(0.1, 0.6) * (1 - pow(altitude, 4));

    fill(h, s, 100, a);
    circle(x, y, sz);

    if (sz > 3.5) {
      fill(h, s * 0.5, 100, a * 0.2);
      circle(x, y, sz * 4);
    }
  }
}

function drawZenithLight() {
  // 画面上方象征“大本源”或“彼岸”的柔和辉光
  noStroke();
  let cx = 760;
  let cy = 220;

  for (let r = 900; r > 10; r -= 12) {
    let t = map(r, 10, 900, 1, 0);
    let h = lerp(240, 195, t);
    let s = lerp(50, 5, pow(t, 2));
    let alpha = map(pow(t, 2.5), 0, 1, 0.001, 0.035);

    fill(h, s, 100, alpha);
    ellipse(cx, cy, r * 1.3, r * 0.9);
  }

  // 从天顶垂下的极淡光幕/神圣几何韵律（无形之门）
  strokeWeight(1);
  for (let i = 0; i < 120; i++) {
    let x = randomGaussian(cx, 160);
    let len = random(200, 700);
    let alpha = random(0.01, 0.04) * exp(-pow((x - cx) / 200, 2));
    stroke(200, 20, 100, alpha);
    line(x, 0, x + (x - cx) * 0.15, len);
  }
}

function drawAbyssWater() {
  let horizon = 1650;

  // 底部深渊暗水基底
  noStroke();
  for (let y = horizon; y < height; y += 2) {
    let t = (y - horizon) / (height - horizon);
    fill(235, 65, lerp(5, 1, pow(t, 0.6)), 0.95);
    rect(0, y, width, 3);
  }

  // 水面上的微弱光影倒影（灵魂升腾在尘世留下的最后一瞥）
  blendMode(ADD);
  for (let y = horizon + 2; y < height; y += 3) {
    let t = (y - horizon) / (height - horizon);
    let spread = lerp(240, 80, t);
    let numRipples = int(lerp(45, 8, t));

    for (let i = 0; i < numRipples; i++) {
      let x = randomGaussian(750, spread);
      let n = noise(x * 0.02, y * 0.08);

      if (n > 0.42) {
        let w = random(15, 90) * (1 - t * 0.5);
        let h = random(0.8, 2.2);

        // 混合金色余温与青色微光的倒影
        let hueVal = random() < 0.4 ? 40 : 200;
        let alpha = (1 - pow(t, 0.5)) * 0.05 * n;

        fill(hueVal, 50, 85, alpha);
        ellipse(x, y, w, h);
      }
    }
  }

  // 躯体与水面交界处的沉静暗影与薄雾
  blendMode(BLEND);
  for (let i = 0; i < 80; i++) {
    let x = random(100, 1500);
    let y = horizon + random(-8, 25);
    let w = random(100, 350);
    let h = random(8, 25);
    fill(235, 55, 3, random(0.1, 0.3));
    ellipse(x, y, w, h);
  }
}

function drawVignetteAndGrain() {
  // 1. 四周暗角，聚焦视线于中央的升华过程
  noFill();
  for (let r = 0; r < 450; r += 5) {
    let alpha = map(r, 0, 450, 0, 0.025);
    stroke(240, 80, 2, alpha);
    strokeWeight(8);
    rect(r * 0.5, r * 0.5, width - r, height - r, 200);
  }

  // 2. 细腻的画布/胶片颗粒感，消除数码生硬感
  loadPixels();
  let d = pixelDensity();
  let totalPixels = 4 * (width * d) * (height * d);

  for (let i = 0; i < totalPixels; i += 4) {
    // 产生微小的明度噪波
    let grain = (random() - 0.5) * 14;
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
      createCanvas(1600, 2000);
      randomSeed(1);
      noiseSeed(1);
      noLoop();

      // 1. 绘制深空与深渊背景
      drawBackground();

      // 2. 绘制远景的星云与消散的以太
      drawNebula();

      // 3. 绘制核心视觉：从固态解离并上升的灵魂流光
      drawAscensionStreams();

      // 4. 绘制底部的沉降物：骨骼/枯木般的生命遗骸结构
      drawCalcifiedRemains();

      // 5. 绘制悬停在渡口的苍白光环（彼岸的入口）
      drawPortalEclipse();

      // 6. 绘制飘散的余烬与微尘
      drawFloatingSpores();

      // 7. 全局颗粒感与暗角，赋予画面古典油画与版画质感
      applyPostProcessing();
    }

    function drawBackground() {
      for (let y = 0; y < height; y++) {
        let inter = map(y, 0, height, 0, 1);
        let c;
        if (inter < 0.6) {
          c = lerpColor(color(6, 8, 14), color(16, 20, 30), inter / 0.6);
        } else {
          c = lerpColor(color(16, 20, 30), color(8, 6, 5), (inter - 0.6) / 0.4);
        }
        stroke(c);
        line(0, y, width, y);
      }
    }

    function drawNebula() {
      blendMode(SCREEN);
      noStroke();
      for (let i = 0; i < 400; i++) {
        let x = random(width * 0.1, width * 0.9);
        let y = random(height * 0.05, height * 0.75);
        // 越靠近中心轴线越密集
        x = lerp(x, width / 2, random(0.2, 0.7));

        let n = noise(x * 0.002, y * 0.002);
        let r = map(n, 0, 1, 50, 350);

        let progress = map(y, height * 0.75, height * 0.05, 0, 1);
        let col1 = color(45, 35, 30, 3); // 底部尘土色
        let col2 = color(30, 50, 70, 4); // 中部幽蓝色
        let col3 = color(90, 75, 55, 3); // 顶部微光金

        let c = progress < 0.5 ? lerpColor(col1, col2, progress * 2) : lerpColor(col2, col3, (progress - 0.5) * 2);
        fill(c);
        circle(x, y, r);
      }
      blendMode(BLEND);
    }

    function drawPortalEclipse() {
      let cx = width * 0.5;
      let cy = height * 0.28;
      let radius = 260;

      // 外发光
      blendMode(ADD);
      noStroke();
      for (let r = radius * 2.5; r > radius * 0.8; r -= 4) {
        let alpha = map(r, radius * 2.5, radius * 0.8, 0, 3.5);
        fill(210, 195, 175, alpha);
        circle(cx, cy, r * 2);
      }

      // 纤细的几何光环，象征秩序与法则
      noFill();
      for (let i = 0; i < 150; i++) {
        let angle1 = random(TWO_PI);
        let angle2 = angle1 + random(PI * 0.1, PI * 0.8);
        let rOffset = random(-15, 40) * pow(random(), 2);
        stroke(240, 225, 200, random(10, 50));
        strokeWeight(random(0.5, 1.5));
        arc(cx, cy, (radius + rOffset) * 2, (radius + rOffset) * 2, angle1, angle2);
      }

      // 内部深渊（虚无之核）
      blendMode(BLEND);
      noStroke();
      for (let r = radius; r > 0; r -= 2) {
        let inter = map(r, 0, radius, 1, 0);
        let c = lerpColor(color(14, 17, 24, 255), color(6, 7, 10, 255), pow(inter, 0.5));
        fill(c);
        circle(cx, cy, r * 2);
      }

      // 边缘极亮的一线生机/死寂
      blendMode(ADD);
      noFill();
      stroke(255, 245, 230, 120);
      strokeWeight(1.5);
      circle(cx, cy, radius * 2);
      blendMode(BLEND);
    }

    function drawAscensionStreams() {
      let numStreams = 2200;

      for (let i = 0; i < numStreams; i++) {
        // 起点集中在画面中下部，呈倒三角或沙漏状底座
        let spread = pow(random(), 1.5) * 450;
        let startX = width / 2 + (random() > 0.5 ? spread : -spread);
        let startY = random(height * 0.55, height * 0.92);

        let x = startX;
        let y = startY;
        let steps = random(150, 550);

        // 决定这根线条是“灰烬（暗）”还是“灵魂（亮）”
        let isLuminescent = random() < 0.35;

        noFill();
        for (let s = 0; s < steps; s++) {
          let progress = s / steps;

          // 噪声场控制流动方向
          let n1 = noise(x * 0.0025, y * 0.0025);
          let n2 = noise(x * 0.01, y * 0.01, 100);

          // 基础方向向上(-HALF_PI)，受噪声扰动
          let angle = -HALF_PI + map(n1, 0, 1, -PI * 0.55, PI * 0.55);

          // 向中心日食聚集的引力，随后向高空发散
          let distToCenter = (width / 2) - x;
          if (y > height * 0.3) {
            angle += distToCenter * 0.0008;
          } else {
            angle -= distToCenter * 0.0005; // 穿过渡口后散开
          }

          let speed = map(progress, 0, 1, 1.5, 4.5);
          let nx = x + cos(angle) * speed;
          let ny = y + sin(angle) * speed;

          // 颜色与透明度计算
          let alpha = sin(progress * PI) * map(y, height * 0.05, height * 0.9, 10, 140);

          if (isLuminescent) {
            blendMode(ADD);
            let c1 = color(180, 130, 90, alpha * 0.5); // 琥珀金
            let c2 = color(220, 235, 255, alpha * 0.35); // 幽魂蓝白
            stroke(lerpColor(c1, c2, progress));
            strokeWeight(map(progress, 0, 1, 1.8, 0.3));
          } else {
            blendMode(BLEND);
            let c1 = color(25, 22, 20, alpha * 1.5); // 焦炭黑
            let c2 = color(85, 80, 75, alpha * 0.8); // 骨灰白
            stroke(lerpColor(c1, c2, progress));
            strokeWeight(map(n2, 0, 1, 0.5, 2.5) * (1 - progress * 0.7));
          }

          line(x, y, nx, ny);

          // 偶尔产生断裂感（解离感）
          if (random() < 0.03) {
            nx += random(-8, 8);
            ny += random(-8, 8);
          }

          x = nx;
          y = ny;

          if (y < height * 0.03 || x < 50 || x > width - 50) break;
        }
      }
      blendMode(BLEND);
    }

    function drawCalcifiedRemains() {
      // 在画面底部绘制如同干枯树根、珊瑚或骨骼化石般的纠缠结构，象征肉体与尘世的凝固
      let branches = [];
      for (let i = 0; i < 45; i++) {
        branches.push({
          x: width / 2 + random(-550, 550),
          y: height + random(10, 100),
          angle: -HALF_PI + random(-0.4, 0.4),
          r: random(15, 45),
          life: 1.0,
          decay: random(0.003, 0.007)
        });
      }

      while (branches.length > 0) {
        for (let i = branches.length - 1; i >= 0; i--) {
          let b = branches[i];

          let n = noise(b.x * 0.005, b.y * 0.005);
          b.angle += map(n, 0, 1, -0.18, 0.18);
          // 强制向上生长但带有扭曲
          b.angle = lerp(b.angle, -HALF_PI, 0.04);

          let speed = b.r * 0.15 + 1;
          b.x += cos(b.angle) * speed;
          b.y += sin(b.angle) * speed;
          b.life -= b.decay;

          let currentR = b.r * pow(b.life, 0.7);

          // 绘制具有立体感的骨骼/枯木切片
          noStroke();
          // 阴影面
          fill(10, 9, 11, 200);
          circle(b.x + currentR * 0.15, b.y + currentR * 0.1, currentR * 2);

          // 本体面（苍白、钙化的质感）
          let boneColor = lerpColor(color(35, 32, 30), color(140, 130, 120), pow(1 - b.life, 1.5));
          fill(boneColor);
          circle(b.x, b.y, currentR * 1.9);

          // 顶部受光面（来自上方日食的微光）
          if (random() < 0.6) {
            fill(190, 180, 170, 60);
            circle(b.x - currentR * 0.2, b.y - currentR * 0.2, currentR * 1.1);
          }

          // 分叉逻辑
          if (b.life > 0.3 && random() < 0.022 && branches.length < 280) {
            branches.push({
              x: b.x,
              y: b.y,
              angle: b.angle + random([-1, 1]) * random(0.3, 0.7),
              r: currentR * random(0.6, 0.85),
              life: b.life * 0.9,
              decay: b.decay * random(1.1, 1.4)
            });
          }

          // 在末端碎裂成飞灰
          if (b.life <= 0.15 && random() < 0.3) {
            fill(200, 170, 140, random(50, 150));
            circle(b.x + random(-20, 20), b.y - random(10, 50), random(1, 4));
          }

          if (b.life <= 0.02 || b.y < height * 0.45) {
            branches.splice(i, 1);
          }
        }
      }

      // 底部深渊遮罩，使根部融入绝对的黑暗
      for (let y = height * 0.85; y <= height; y++) {
        let alpha = map(y, height * 0.85, height, 0, 255);
        stroke(5, 5, 7, alpha);
        line(0, y, width, y);
      }
    }

    function drawFloatingSpores() {
      blendMode(ADD);
      noStroke();

      // 1. 细碎的星尘与灵魂微粒
      for (let i = 0; i < 4500; i++) {
        let x = random(width);
        let y = random(height);

        // 密度受高度和中心距离影响
        let distFromCenter = abs(x - width / 2) / (width / 2);
        if (random() < distFromCenter * 0.6) continue;

        let n = noise(x * 0.004, y * 0.004);
        if (n > 0.35) {
          let size = pow(random(), 4) * 7 + 0.8;
          let alpha = map(y, 0, height, 180, 30) * random(0.2, 1);

          if (random() < 0.7) {
            fill(235, 200, 150, alpha); // 暖金微尘
          } else {
            fill(170, 205, 240, alpha); // 冷蓝星火
          }
          circle(x, y, size);

          // 为较大颗粒添加光晕
          if (size > 4.5) {
            fill(255, 230, 200, alpha * 0.2);
            circle(x, y, size * 4);
          }
        }
      }

      // 2. 垂直上升的微弱光丝（时间的流逝感）
      strokeWeight(0.7);
      for (let i = 0; i < 300; i++) {
        let x = width / 2 + random(-500, 500) * pow(random(), 1.2);
        let y = random(height * 0.1, height * 0.85);
        let len = random(15, 90);
        let alpha = random(15, 70);

        stroke(220, 210, 195, alpha);
        line(x, y, x, y - len);

        // 光丝顶端亮点
        noStroke();
        fill(255, 245, 230, alpha * 1.5);
        circle(x, y - len, random(1.5, 3));
      }
      blendMode(BLEND);
    }

    function applyPostProcessing() {
      // 1. 四周暗角 (Vignette)，强化肃穆与内省的氛围
      noFill();
      let maxDist = dist(0, 0, width / 2, height / 2);
      for (let r = maxDist * 0.55; r < maxDist * 1.1; r += 4) {
        let alpha = map(r, maxDist * 0.55, maxDist * 1.1, 0, 180);
        stroke(4, 5, 7, alpha);
        strokeWeight(6);
        ellipse(width / 2, height / 2, r * 2 * (width / height), r * 2);
      }

      // 2. 像素级胶片/画布颗粒感
      loadPixels();
      let d = pixelDensity();
      let totalPixels = 4 * (width * d) * (height * d);
      for (let i = 0; i < totalPixels; i += 4) {
        let grain = random(-10, 10);
        pixels[i] = constrain(pixels[i] + grain, 0, 255);
        pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
        pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
      }
      updatePixels();
    }

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. 绘制深邃的背景渐变（从底部的虚无之黑到顶部的以太之蓝）
  drawBackground();

  // 2. 绘制背景中的星云与尘埃（使用柔和的发光叠加）
  blendMode(ADD);
  drawNebula();

  // 3. 绘制核心的“灵魂/能量”上升流（千万条细微的轨迹）
  drawAscendingStreams();

  // 4. 绘制底部的“躯壳/实体”与正在崩解的边缘
  blendMode(BLEND);
  drawVesselAndFragments();

  // 5. 绘制最终升华的光点与消散的余烬
  blendMode(ADD);
  drawEmbers();

  // 6. 覆盖一层微妙的画布纹理，赋予其古典油画般的质感
  blendMode(OVERLAY);
  drawCanvasTexture();
}

function drawBackground() {
  noFill();
  for (let y = 0; y < height; y++) {
    let inter = map(y, 0, height, 0, 1);
    // 顶部是极暗的冷青色，中部是深邃的午夜蓝，底部是死寂的纯黑
    let c;
    if (inter < 0.6) {
      c = lerpColor(color(12, 18, 28), color(6, 8, 14), map(inter, 0, 0.6, 0, 1));
    } else {
      c = lerpColor(color(6, 8, 14), color(2, 2, 4), map(inter, 0.6, 1, 0, 1));
    }
    stroke(c);
    line(0, y, width, y);
  }
}

function drawNebula() {
  noStroke();
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height * 0.85);
    // 越靠近中心轴线，光晕越密集
    let distFromCenter = abs(x - width / 2);
    if (random(width / 2) < distFromCenter * 0.8) continue;

    let n = noise(x * 0.002, y * 0.002);
    let r = map(n, 0, 1, 50, 350);

    // 颜色在冷青色与暗金色之间交替
    let col;
    if (random() < map(y, 0, height, 0.8, 0.2)) {
      col = color(20, 45, 65, 2.5); // 以太青
    } else {
      col = color(70, 45, 20, 2.5); // 记忆金
    }

    fill(col);
    circle(x, y, r);
  }
}

function drawAscendingStreams() {
  let numStreams = 3500;

  for (let i = 0; i < numStreams; i++) {
    // 起点集中在画面中下方的“躯壳”中心附近
    let startX = randomGaussian(width / 2, 220);
    let startY = randomGaussian(height * 0.78, 80);

    // 限制范围
    startX = constrain(startX, 100, width - 100);
    startY = constrain(startY, height * 0.5, height * 0.95);

    let x = startX;
    let y = startY;

    let steps = random(200, 900);
    let isGold = random() < 0.35;

    // 决定线条的基础色调
    let baseR = isGold ? random(200, 255) : random(80, 140);
    let baseG = isGold ? random(140, 190) : random(160, 210);
    let baseB = isGold ? random(60, 100) : random(200, 255);

    strokeWeight(random(0.4, 1.8));

    for (let s = 0; s < steps; s++) {
      let progress = s / steps;

      // 透明度随上升先增后减，最终消散于无形
      let alpha = sin(progress * PI) * map(y, height, 0, 25, 4);
      stroke(baseR, baseG, baseB, alpha);

      let prevX = x;
      let prevY = y;

      // 柏林噪声控制流动的形态
      let n = noise(x * 0.0025, y * 0.0025, i * 0.0005);
      // 角度始终倾向上方 (-PI/2)，但带有柔和的涡流摆动
      let angle = -HALF_PI + map(n, 0, 1, -PI * 0.45, PI * 0.45);

      // 越往上，受到向心或离心的扩散力
      let centerPull = (width / 2 - x) * 0.0008 * sin(y * 0.005);

      x += cos(angle) * 2.2 + centerPull;
      y += sin(angle) * 2.2 - 0.8; // 恒定的上升升力

      line(prevX, prevY, x, y);

      if (y < 0 || x < 0 || x > width) break;
    }
  }
}

function drawVesselAndFragments() {
  // 绘制底部沉重的暗影基座（象征大地与肉身的重力）
  noStroke();
  for (let y = height * 0.7; y < height; y += 2) {
    let alpha = map(y, height * 0.7, height, 0, 255);
    fill(3, 3, 6, alpha);
    beginShape();
    vertex(0, height);
    for (let x = 0; x <= width; x += 20) {
      let n = noise(x * 0.004, y * 0.01);
      // 形成中间微微隆起、两侧低垂的祭坛/躯壳形态
      let arch = sin(map(x, 0, width, 0, PI)) * 120;
      let yOffset = y - arch + map(n, 0, 1, -60, 60);
      vertex(x, yOffset);
    }
    vertex(width, height);
    endShape(CLOSE);
  }

  // 绘制正在剥落、碎裂并向上漂浮的实体碎片（生与死的交界）
  for (let i = 0; i < 1800; i++) {
    let t = random(1);
    // 使用幂函数让碎片集中在底部交界处，越往上越稀疏
    let y = map(pow(t, 0.35), 0, 1, height * 0.15, height * 0.92);

    // 碎片的水平分布呈沙漏/烟柱状
    let spread = map(y, height * 0.15, height * 0.9, 500, 320);
    let x = randomGaussian(width / 2, spread * 0.6);

    // 根据高度决定碎片的大小：底部是沉重的巨石，顶部是微小的灰烬
    let size = map(y, height * 0.15, height * 0.9, 1.5, 45) * random(0.4, 1.6);

    // 越往上越透明，仿佛正在被光吞噬
    let alpha = map(y, height * 0.15, height * 0.85, 20, 255);

    push();
    translate(x, y);
    rotate(noise(x * 0.01, y * 0.01) * TWO_PI);

    // 碎片本体（深邃的死寂之色）
    fill(6, 7, 12, alpha);
    noStroke();

    // 为部分靠近光源的碎片勾勒出金色的裂痕边缘（象征光从内部破壳而出）
    if (random() < 0.3 && y > height * 0.45) {
      stroke(220, 160, 80, alpha * 0.6);
      strokeWeight(random(0.5, 1.5));
    }

    beginShape();
    let sides = int(random(3, 7));
    for (let a = 0; a < TWO_PI; a += TWO_PI / sides) {
      let r = size * random(0.4, 1.0);
      vertex(cos(a) * r, sin(a) * r);
    }
    endShape(CLOSE);
    pop();
  }
}

function drawEmbers() {
  // 绘制挣脱束缚后自由升腾的灵魂光点
  for (let i = 0; i < 900; i++) {
    let y = random(height * 0.02, height * 0.85);
    let spread = map(y, 0, height, 600, 200);
    let x = randomGaussian(width / 2, spread * 0.5);

    // 结合噪声，让光点聚集在刚才的气流轨迹上
    let n = noise(x * 0.005, y * 0.005);
    if (n < 0.42) continue;

    let r = random(1.5, 7);
    let isBrightGold = random() < 0.7;

    // 绘制多层光晕，营造呼吸感
    noStroke();
    for (let glow = 4; glow >= 1; glow--) {
      let glowRadius = r * glow * (glow * 0.6);
      let alpha = map(glow, 1, 4, 180, 8) * map(y, 0, height, 0.3, 1);

      if (isBrightGold) {
        fill(255, 200, 120, alpha);
      } else {
        fill(140, 220, 255, alpha);
      }
      circle(x, y, glowRadius);
    }

    // 极亮的核心
    fill(255, 255, 255, 200 * map(y, 0, height, 0.2, 1));
    circle(x, y, r * 0.6);
  }

  // 顶部的一抹微弱天光，象征回归宇宙的终极平静
  for (let r = 800; r > 0; r -= 20) {
    fill(18, 30, 45, 1.2);
    circle(width / 2, 0, r * 2);
  }
}

function drawCanvasTexture() {
  // 使用极细微的线条模拟画布的纹理与时间的斑驳感
  noFill();
  for (let i = 0; i < 40000; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(2, 12);

    if (random() < 0.5) {
      stroke(255, 250, 240, 4);
    } else {
      stroke(0, 0, 0, 8);
    }
    strokeWeight(0.5);

    // 纹理主要呈垂直方向，呼应上升与坠落的主题
    line(x, y, x + random(-1, 1), y + len);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  drawSky();
  drawClouds();
  drawStars();
  drawMoon();
  drawRidges();
  drawHorizonGlow();
  drawWater();
  drawReflections();
  drawMist();
  drawBoat();
  drawOar();
  drawSparks();
  drawBirds();
  drawShore();
  drawReeds();
  drawFlowers();
  drawGrain();
  drawVignette();
}

function drawSky() {
  for (let y = 0; y < 1240; y++) {
    let t = y / 1240;
    let n = noise(y * 0.004, 0.2);
    let r = lerp(7, 74, pow(t, 1.35)) + n * 6;
    let g = lerp(5, 32, pow(t, 1.1)) + n * 4;
    let b = lerp(18, 52, t);
    if (t > 0.68) {
      let u = pow((t - 0.68) / 0.32, 1.15);
      r = lerp(r, 176, u);
      g = lerp(g, 68, u * 0.85);
      b = lerp(b, 42, u * 0.45);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

function drawClouds() {
  noStroke();
  for (let i = 0; i < 18; i++) {
    let x = random(width);
    let y = random(760, 1080);
    let w = random(180, 520);
    let h = random(18, 46);
    fill(120, 70, 58, random(8, 18));
    ellipse(x, y, w, h);
    ellipse(x + w * 0.2, y + 6, w * 0.6, h * 0.7);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = random(width);
    let y = random(20, 980);
    let s = random(0.4, 2.4);
    let a = random(30, 170);
    if (dist(x, y, 1080, 250) < 150) continue;
    fill(232, 224, 206, a);
    circle(x, y, s);
    if (random() < 0.07) {
      fill(255, 220, 170, 18);
      circle(x, y, s * 9);
    }
  }
}

function drawMoon() {
  let x = 1080;
  let y = 250;
  noStroke();
  for (let i = 18; i > 0; i--) {
    fill(230, 190, 130, 4);
    circle(x, y, 220 + i * 28);
  }
  fill(236, 222, 196);
  circle(x, y, 210);
  fill(214, 198, 168, 80);
  ellipse(x - 36, y - 18, 46, 38);
  ellipse(x + 28, y + 30, 62, 28);
  ellipse(x + 8, y - 48, 24, 18);
  fill(226, 210, 182, 50);
  ellipse(x - 20, y + 42, 30, 22);
}

function drawRidges() {
  ridge(1035, 90, color(92, 58, 62), 1.2, 0.4);
  ridge(1095, 130, color(48, 32, 44), 4.1, 1.3);
  ridge(1168, 78, color(18, 14, 20), 8.4, 2.2);
}

function ridge(base, amp, col, ox, oy) {
  noStroke();
  fill(col);
  beginShape();
  vertex(0, base + 30);
  for (let x = 0; x <= width; x += 6) {
    let n = noise(x * 0.0022 + ox, oy);
    let n2 = noise(x * 0.009 + ox, oy + 2.5);
    vertex(x, base - n * amp - n2 * amp * 0.22);
  }
  vertex(width, base + 30);
  endShape(CLOSE);
}

function drawHorizonGlow() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    fill(214, 118, 58, 3.2);
    rect(0, 1060 + i * 1.4, width, 3);
  }
  for (let i = 0; i < 30; i++) {
    fill(255, 196, 120, 2);
    ellipse(860, 1128, 700 + i * 18, 40 + i);
  }
}

function drawWater() {
  for (let y = 1124; y < height; y++) {
    let t = (y - 1124) / (height - 1124);
    let n = noise(0.4, y * 0.012);
    let r = lerp(42, 5, pow(t, 0.65)) + n * 7;
    let g = lerp(26, 9, t) + n * 3;
    let b = lerp(34, 14, t);
    stroke(r, g, b);
    line(0, y, width, y);
  }
  for (let i = 0; i < 640; i++) {
    let y = random(1148, 1860);
    let x = random(-20, width);
    stroke(190, 146, 92, random(6, 26));
    strokeWeight(1);
    line(x, y, x + random(16, 150), y);
  }
}

function drawReflections() {
  noStroke();
  for (let y = 1160; y < 1780; y += 3) {
    let t = (y - 1160) / 620;
    let flicker = noise(y * 0.018, 3.3);
    if (flicker < 0.22) continue;
    let w = lerp(10, 108, t) * flicker;
    let x = 852 + (noise(y * 0.01, 1.7) - 0.5) * 36;
    fill(226, 164, 86, lerp(42, 8, t) * flicker);
    ellipse(x, y, w, 3.5);
  }
  for (let y = 1175; y < 1500; y += 7) {
    let t = (y - 1175) / 325;
    if (noise(y * 0.03, 6) < 0.35) continue;
    fill(230, 214, 186, lerp(34, 0, t));
    ellipse(1080 + sin(y * 0.05) * 8, y, lerp(16, 4, t), 3);
  }
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    fill(180, 150, 130, random(6, 14));
    ellipse(random(200, 1400), random(1100, 1320), random(260, 700), random(20, 50));
  }
}

function drawBoat() {
  let x = 690;
  let y = 1402;
  noStroke();
  fill(16, 12, 12, 50);
  ellipse(x + 42, y + 46, 168, 16);

  fill(16, 11, 10);
  beginShape();
  vertex(x - 74, y);
  bezierVertex(x - 36, y + 38, x + 124, y + 38, x + 156, y);
  bezierVertex(x + 118, y + 8, x - 16, y + 8, x - 74, y);
  endShape(CLOSE);

  stroke(96, 62, 40, 90);
  strokeWeight(1.6);
  noFill();
  bezier(x - 62, y + 2, x + 4, y + 12, x + 86, y + 12, x + 146, y + 1);

  noStroke();
  fill(10, 8, 12);
  beginShape();
  vertex(x + 24, y - 4);
  vertex(x + 6, y - 74);
  vertex(x + 34, y - 96);
  vertex(x + 60, y - 72);
  vertex(x + 46, y - 4);
  endShape(CLOSE);
  fill(36, 28, 30);
  ellipse(x + 34, y - 106, 15, 18);
  stroke(186, 112, 62, 110);
  strokeWeight(1.4);
  line(x + 52, y - 78, x + 58, y - 36);
}

function drawOar() {
  push();
  translate(838, 1448);
  rotate(-0.42);
  noStroke();
  fill(54, 38, 28, 170);
  rect(0, 0, 78, 3, 1);
  ellipse(78, 1.5, 12, 18);
  pop();
}

function drawSparks() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    let t = i / 90;
    let x = 724 + noise(i * 0.13, 5) * 46;
    let y = 1290 - t * 460 - random(16);
    fill(232, 176, 104, lerp(130, 0, t));
    circle(x, y, lerp(2.6, 0.35, t));
  }
}

function drawBirds() {
  let pts = [
    [748, 1210, 20],
    [786, 1072, 15],
    [824, 930, 12],
    [878, 790, 10],
    [948, 650, 8],
    [1012, 520, 6.5],
    [1076, 404, 5]
  ];
  noFill();
  stroke(46, 34, 32, 170);
  for (let p of pts) {
    strokeWeight(1.15);
    let x = p[0];
    let y = p[1];
