function drawShore() {
  noStroke();
  fill(7, 9, 8);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 8) {
    vertex(x, 1768 + noise(x * 0.0035, 9) * 42 + noise(x * 0.01, 3) * 10);
  }
  vertex(width, height);
  endShape(CLOSE);
}

function drawReeds() {
  stroke(28, 36, 26, 150);
  for (let i = 0; i < 70; i++) {
    let x = random(40, 1560);
    let y = 1810 + noise(x * 0.01, 4) * 30;
    let h = random(40, 130);
    strokeWeight(random(0.6, 1.3));
    bezier(x, y, x - 8, y - h * 0.4, x + 10, y - h * 0.7, x - 2, y - h);
  }
}

function drawFlowers() {
  let spots = [
    [180, 1860, 16],
    [250, 1895, 22],
    [430, 1872, 14],
    [980, 1888, 18],
    [1120, 1855, 13],
    [1290, 1902, 24],
    [1410, 1868, 15],
    [620, 1910, 12]
  ];
