function drawDoorLight() {
  const L = 1040;
  const R = 1380;
  const T = 280;
  const B = 1500;
  const VX = 1210;
  const VY = 980;

  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.rect(L, T, R - L, B - T);
  drawingContext.clip();

  for (let y = T; y < VY + 20; y++) {
    let t = (y - T) / (VY - T);
    stroke(lerp(168, 236, t), lerp(178, 226, t), lerp(186, 208, t));
    line(L, y, R, y);
  }
  for (let y = VY; y <= B; y++) {
    let t = (y - VY) / (B - VY);
    let left = lerp(VX, L, t);
    let right = lerp(VX, R, t);
    stroke(lerp(210, 150, 1 - t), lerp(206, 146, 1 - t), lerp(188, 128, 1 - t));
    line(L, y, R, y);
    stroke(lerp(248, 214, 1 - t), lerp(240, 200, 1 - t), lerp(224, 176, 1 - t));
    line(left, y, right, y);
  }

  noStroke();
  for (let i = 0; i < 7; i++) {
    let y = lerp(VY + 30, B - 20, i / 6);
    let t = (y - VY) / (B - VY);
    let left = lerp(VX, L, t);
    let right = lerp(VX, R, t);
    let side = 18 + i * 10;
    fill(46, 52, 44, 150 - i * 8);
    treeClump(left - side * 0.2, y - 10, side);
    treeClump(right + side * 0.15, y - 16, side * 1.05);
  }
  for (let i = 8; i >= 1; i--) {
    fill(255, 244, 226, 7);
    ellipse(VX, VY + 10, 40 + i * 70, 24 + i * 36);
  }
  drawingContext.restore();

  noStroke();
  fill(18, 15, 13);
  rect(L - 34, T - 28, 34, B - T + 34);
  rect(R, T - 28, 34, B - T + 34);
  rect(L - 34, T - 28, R - L + 68, 28);
  fill(42, 34, 28);
  rect(L - 8, T, 8, B - T);
  rect(R, T, 8, B - T);

  drawOpenPanel(L, T, B);

  noStroke();
  for (let i = 6; i >= 1; i--) {
    fill(255, 214, 170, 4);
    ellipse((L + R) / 2, (T + B) / 2, (R - L) + i * 90, (B - T) + i * 40);
  }

  fill(255, 236, 208, 16);
  quad(L, B, R, B, 1560, 1960, 620, 1860);
  fill(255, 228, 190, 22);
  quad(L + 30, B, R - 20, B, 1320, 1840, 860, 1760);
  fill(255, 244, 228, 230);
  rect(L, B - 4, R - L, 8);
  fill(255, 250, 242, 160);
  rect(L + 16, B - 2, R - L - 32, 3);
  fill(255, 220, 180, 28);
  ellipse((L + R) / 2, B + 18, R - L, 22);
}

function treeClump(x, y, s) {
