function skyAt(y) {
  const stops = [
    { y: 0, c: [8, 6, 18] },
    { y: 360, c: [14, 11, 34] },
    { y: 700, c: [34, 18, 48] },
    { y: 980, c: [72, 30, 42] },
    { y: 1180, c: [142, 58, 38] },
    { y: 1276, c: [214, 132, 68] },
    { y: 1310, c: [28, 18, 18] }
  ];
  let i = 0;
  while (i < stops.length - 2 && y > stops[i + 1].y) i++;
  const a = stops[i];
  const b = stops[i + 1];
  let t = constrain((y - a.y) / (b.y - a.y), 0, 1);
  t = t * t * (3 - 2 * t);
  return color(
    lerp(a.c[0], b.c[0], t),
    lerp(a.c[1], b.c[1], t),
    lerp(a.c[2], b.c[2], t)
  );
}

function drawSky() {
  for (let y = 0; y < 1340; y++) {
    stroke(skyAt(y));
    line(0, y, width, y);
  }
}

function drawClouds() {
  noStroke();
  for (let i = 0; i < 9; i++) {
    const x = noise(i * 1.7, 1.2) * width;
    const y = 60 + noise(i * 1.3, 2.4) * 620;
    const w = 280 + noise(i, 3.1) * 560;
    for (let k = 10; k > 0; k--) {
      fill(5, 4, 12, 7);
      ellipse(x, y, (w * k) / 7, 28 + k * 9);
    }
  }
}

function drawHorizonLight() {
  noStroke();
  for (let i = 46; i > 0; i--) {
    fill(196, 92, 40, 3);
    ellipse(1140, 1288, 760 + i * 26, 36 + i * 7);
  }
  for (let i = 22; i > 0; i--) {
    fill(236, 176, 96, 5);
    ellipse(1168, 1284, 380 + i * 12, 5 + i * 1.15);
  }
  // a seam, not a sun: the day reduced to a line
  for (let i = 8; i > 0; i--) {
    fill(255, 214, 160, 8);
    ellipse(1188, 1282, 180 + i * 8, 2 + i * 0.35);
  }
}

function drawWater() {
  for (let y = 1296; y < height; y++) {
    const t = (y - 1296) / (height - 1296);
    stroke(lerp(16, 5, t), lerp(14, 6, t), lerp(18, 10, t));
    line(0, y, width, y);
  }

  // broken reflection of the last light
  noFill();
  for (let i = 0; i < 70; i++) {
    const y = 1310 + i * 7.2;
    const a = 34 - i * 0.42;
    stroke(214, 156, 86, a);
    beginShape();
    for (let x = 860; x <= 1460; x += 8) {
      const n = noise(x * 0.004, i * 0.17);
      vertex(x, y + n * 7);
    }
    endShape();
  }

  // wide, slow ripples — something has already left the surface
  for (let i = 1; i <= 8; i++) {
    stroke(190, 150, 108, 28 - i * 2.4);
    strokeWeight(1);
    arc(980, 1376, 70 + i * 62, 16 + i * 12, 0, PI);
  }
}

function landY(x) {
  return 1116 + noise(x * 0.004, 3) * 86 + x * 0.34;
}

function drawLand() {
  noStroke();
  fill(8, 7, 11);
  beginShape();
  vertex(0, height);
  vertex(0, 1040);
  for (let x = 0; x <= 590; x += 8) vertex(x, landY(x) - 20);
  vertex(590, height);
  endShape(CLOSE);

  fill(5, 4, 8);
  beginShape();
  vertex(0, height);
  vertex(0, 1560);
  for (let x = 0; x <= 430; x += 10) {
    vertex(x, 1600 + noise(x * 0.007, 9) * 36 - x * 0.12);
  }
  vertex(400, height);
  endShape(CLOSE);

  // a few dark stones where shore meets water
  fill(7, 6, 9);
  ellipse(470, 1368, 54, 16);
  ellipse(512, 1388, 28, 10);
  ellipse(438, 1394, 22, 8);
}

let tips = [];

function drawTree(rootX) {
  tips = [];
  const rootY = landY(rootX) - 18;
  strokeCap(ROUND);
  grow(rootX, rootY, -HALF_PI + 0.34, 168, 7);
}

function grow(x, y, ang, len, depth) {
  if (depth === 0 || len < 10) {
    tips.push({ x: x, y: y });
    return;
  }
  const n = noise(x * 0.008, y * 0.008, depth * 0.4);
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  stroke(12, 9, 13, 235);
  strokeWeight(map(depth, 1, 7, 1.1, 13));
  line(x, y, x2, y2);
  const spread = 0.32 + n * 0.42;
  // lean toward the open water, as if reaching after what left
  grow(x2, y2, ang - spread * 0.42, len * (0.72 + n * 0.06), depth - 1);
  grow(x2, y2, ang + spread * 1.05, len * 0.6, depth - 1);
}

function drawBoat(x, y) {
  noStroke();
  fill(0, 0, 0, 36);
  ellipse(x + 8, y + 34, 250, 16);

  fill(14, 11, 13);
  beginShape();
  vertex(x - 148, y);
  bezierVertex(x - 126, y + 34, x - 36, y + 56, x + 12, y + 56);
  bezierVertex(x + 74, y + 56, x + 138, y + 28, x + 162, y - 2);
  vertex(x + 148, y + 8);
  bezierVertex(x + 116, y + 28, x + 42, y + 38, x + 8, y + 38);
  bezierVertex(x - 28, y + 38, x - 108, y + 22, x - 136, y + 6);
  endShape(CLOSE);

  // pale empty interior: the subject is the absence
  fill(214, 180, 146, 46);
  beginShape();
  vertex(x - 68, y + 8);
  bezierVertex(x - 16, y + 26, x + 52, y + 26, x + 102, y + 6);
  bezierVertex(x + 44, y + 16, x - 8, y + 16, x - 68, y + 8);
  endShape(CLOSE);

  stroke(224, 170, 98, 120);
  strokeWeight(1.5);
  noFill();
  beginShape();
  vertex(x - 148, y);
  bezierVertex(x - 50, y - 12, x + 72, y - 10, x + 162, y - 2);
  endShape();

  // shattered reflection
  for (let i = 0; i < 22; i++) {
    const yy = y + 22 + i * 4.2;
    const wob = noise(i * 0.22, 4.4) * 14 - 7;
    stroke(20, 16, 16, map(i, 0, 22, 46, 0));
    strokeWeight(1.6);
    line(x - 108 + wob, yy, x + 118 - wob * 0.4, yy);
  }
}

function drawDepartingLight() {
  noStroke();
  // motes leaving the bare branches
  for (let t = 0; t < tips.length; t++) {
    const tip = tips[t];
    const count = 5;
    for (let i = 0; i < count; i++) {
      const rise = random(8, 420);
      const px = tip.x + random(-10, 26) + noise(t, i) * 10;
      const py = tip.y - rise;
      const a = random(18, 110) * (1 - rise / 520);
      fill(236, 198, 146, a);
      circle(px, py, random(0.8, 2.8));
    }
  }

  // a quiet column rising from the empty boat
  for (let i = 0; i < 200; i++) {
    const rise = random(0, 980);
    const px = 980 + random(-46, 46) + (noise(i * 0.08, 6) - 0.5) * 36;
    const py = 1340 - rise;
    const a = map(rise, 0, 980, 130, 8) * random(0.45, 1);
    fill(244, 220, 188, a);
    circle(px, py, random(0.8, 3.4));
  }

  blendMode(ADD);
  for (let i = 24; i > 0; i--) {
    fill(36, 22, 8, 2);
    ellipse(992, 860, 16 + i * 2.4, 980);
  }
  blendMode(BLEND);
}

function drawStars() {
  noStroke();
