function drawSky(H) {
  for (let y = 0; y < H; y++) {
    const t = y / H;
    const n = noise(y * 0.006, 0.3) * 14;
    let r, g, b;
    if (t < 0.55) {
      const u = t / 0.55;
      r = lerp(7, 62, u * u) + n * 0.3;
      g = lerp(9, 32, u) + n * 0.15;
      b = lerp(20, 48, u);
    } else if (t < 0.82) {
      const u = (t - 0.55) / 0.27;
      r = lerp(62, 168, u) + n;
      g = lerp(32, 78, u);
      b = lerp(48, 52, u * (1 - u) + 0.2);
    } else {
      const u = (t - 0.82) / 0.18;
      r = lerp(168, 92, u);
      g = lerp(78, 42, u);
      b = lerp(52, 40, u);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }
}

