function drawSun(x, y) {
  noStroke();
  for (let r = 460; r > 0; r -= 3) {
    const t = r / 460;
    const a = pow(1 - t, 2) * 15;
    fill(214, 118 + (1 - t) * 70, 54, a);
    circle(x, y, r * 2);
  }
  for (let r = 78; r > 0; r -= 2) {
    fill(255, 214, 168, 9);
    circle(x, y - 6, r * 2);
  }
}

function drawHill(H, freq, base, amp, cr, cg, cb, a) {
  noStroke();
  fill(cr, cg, cb, a);
  beginShape();
