function drawTree(x, y, len, ang, depth, w, alpha) {
  if (depth === 0 || len < 2.4) return;
  const n = noise(x * 0.0027, y * 0.0027);
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  stroke(24 + n * 22, 18, 20, alpha);
  strokeCap(ROUND);
  strokeWeight(max(w, 0.55));
  line(x, y, x2, y2);
  if (w > 7) {
    stroke(62, 42, 36, alpha * 0.28);
    strokeWeight(max(w * 0.28, 0.6));
    line(x + 1.4, y, x2 + 0.6, y2);
  }
  const left = 0.3 + n * 0.32;
  const right = 0.24 + noise(y * 0.004, depth * 0.2) * 0.3;
  const wind = 0.075;
  drawTree(x2, y2, len * 0.735, ang - left + wind, depth - 1, w * 0.7, alpha * 0.97);
  drawTree(x2, y2, len * 0.705, ang + right + wind, depth - 1, w * 0.67, alpha * 0.97);
  if (depth > 6 && random() < 0.16) {
    drawTree(x2, y2, len * 0.58, ang + wind * 1.4, depth - 3, w * 0.48, alpha * 0.9);
  }
  if (depth <= 2 && random() < 0.32) {
    noStroke();
    fill(214, 164, 96, alpha * 0.22);
    circle(x2, y2, random(1.2, 2.8));
  }
}

