function paintCandle(cx, base) {
  let h = 188;
  let top = base - h;
  for (let i = 0; i < h; i++) {
    let n = noise(i * 0.045, 9.2);
    let wob = (n - 0.5) * 2.4;
    for (let x = -12; x <= 12; x++) {
      let u = (x + 12) / 24;
      let shade = n * 16;
      let r = lerp(244, 150, u) - shade;
      let g = lerp(232, 126, u) - shade;
      let b = lerp(208, 96, u) - shade * 0.5;
      stroke(r, g, b);
      strokeWeight(1.4);
      point(cx + x + wob, top + i);
    }
  }
  noStroke();
  fill(228, 208, 178);
  ellipse(cx, top + 5, 28, 11);
  fill(196, 160, 112, 80);
  ellipse(cx + 4, top + 6, 16, 7);
  fill(36, 26, 22);
  ellipse(cx + 0.5, top + 2, 4.5, 3.5);
  stroke(22, 16, 14);
  strokeWeight(1.7);
  noFill();
  bezier(cx + 0.5, top, cx + 3, top - 8, cx - 3, top - 16, cx + 1, top - 23);
  noStroke();
  fill(48, 18, 14, 160);
  ellipse(cx + 1, top - 23, 2.6, 2.6);

  drip(cx + 11, top + 28, 74, 2.1);
  drip(cx - 10, top + 46, 48, 8.4);
  drip(cx + 8, top + 90, 36, 5.5);

  fill(206, 184, 150, 180);
  ellipse(cx - 16, base - 6, 8, 5);
  ellipse(cx + 20, base - 2, 6, 4);
}

function drip(x, y, len, seed) {
  noStroke();
  for (let i = 0; i < len; i++) {
    let w = lerp(5.2, 1.4, i / len);
    let j = (noise(i * 0.12, seed) - 0.5) * 2.4;
    fill(214, 192, 160, 210);
    ellipse(x + j, y + i, w, w);
  }
  fill(226, 206, 176, 230);
  ellipse(x, y + len, 7.5, 9);
  fill(160, 120, 82, 50);
  ellipse(x + 1, y + len + 1, 3, 3);
}

function paintSmoke(cx, y0) {
  noStroke();
  let x = cx + 1;
  let y = y0;
  for (let i = 0; i < 1280; i++) {
    let n = noise(i * 0.007, 2.4);
    let n2 = noise(i * 0.004, 12.0);
    x += (n - 0.42) * 6.4;
    y -= 1.08;
    if (y < 30) break;
    let t = constrain((y0 - y) / 1200, 0, 1);
    let a = lerp(42, 0, Math.pow(t, 0.85));
    let s = lerp(5, 34, t) * (0.65 + n2 * 0.7);
    let r = lerp(186, 168, t);
    let g = lerp(170, 184, t);
    let b = lerp(150, 206, t);
    fill(r, g, b, a * 0.45);
    ellipse(x, y, s, s * 1.35);
    fill(r, g, b, a * 0.22);
    ellipse(x + (n2 - 0.5) * 28, y + 6, s * 0.7, s);
    if (i % 3 === 0) {
      stroke(230, 222, 206, a * 1.1);
      strokeWeight(1);
      point(x + (noise(i * 0.08, 3) - 0.5) * s, y);
      noStroke();
    }
  }

  let bx = cx + 8;
  let by = y0 - 40;
  for (let i = 0; i < 700; i++) {
    let n = noise(i * 0.01, 18.5);
    bx += (n - 0.58) * 5.5;
    by -= 1.35;
    if (by < 80) break;
    let a = lerp(18, 0, i / 700);
    fill(176, 186, 198, a);
    ellipse(bx, by, lerp(4, 18, i / 700), lerp(8, 26, i / 700));
  }
}

