function drawTree(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 4) return;

  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;

  stroke(7, 8, 11, 255);
  strokeWeight(w);
  strokeCap(ROUND);
  line(x, y, x2, y2);

  if (len > 30) {
    const spread = 0.45 + noise(x * 0.005, y * 0.005, depth) * 0.38;
    let branches = 2;
    if (len > 140 && random() > 0.68) branches = 3;

    for (let i = 0; i < branches; i++) {
      let side = i === 0 ? -1 : (i === 1 ? 1 : (random() > 0.5 ? -1 : 1));
      let na = angle + side * spread * random(0.55, 1.08);
      let nl = len * random(0.62, 0.8);
      let nw = max(0.6, w * random(0.55, 0.73));
      drawTree(x2, y2, na, nl, nw, depth - 1);
    }
  } else {
    for (let i = 0; i < 3; i++) {
      let na = angle + random(-0.95, 0.95);
      let tl = len * random(0.55, 0.95);
      stroke(7, 8, 11, 225);
      strokeWeight(max(0.5, w * 0.42));
      line(x2, y2, x2 + cos(na) * tl, y2 + sin(na) * tl);
    }
  }
}

