function branch(x, y, len, angle, depth, w) {
  stroke(6, 7, 9, 235);
  strokeWeight(w);
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  line(x, y, x2, y2);

  if (depth <= 0 || len < 8) return;

  let taper = max(0.7, w * 0.62);
  for (let dir = -1; dir <= 1; dir += 2) {
    let na = angle + dir * random(0.12, 0.4);
    let nl = len * random(0.66, 0.81);
    branch(x2, y2, nl, na, depth - 1, taper);
  }
}

