    let t = i / (total - 1);
    let px = bezierPoint(x0, c1x, c2x, x1, t);
    let py = bezierPoint(y0, c1y, c2y, y1, t);
    let spread = map(t, 0, 1, 80, 180);
    let bx = px + random(-spread, spread) * 0.6;
    let by = py + random(-spread, spread) * 0.3;
    let sz = lerp(14, 3, t) * random(0.6, 1.35);
    let alpha = lerp(235, 75, t);
    stroke(225, 232, 244, alpha);
    strokeWeight(max(0.8, sz * 0.15));
    noFill();
    beginShape();
    vertex(bx - sz, by - sz * 0.25);
    quadraticVertex(bx - sz * 0.55, by - sz * 0.85, bx, by - sz * 0.30);
    quadraticVertex(bx + sz * 0.55, by - sz * 0.85, bx + sz, by - sz * 0.25);
    endShape();
  }
}

