function drawDissolvingTop() {
  noStroke();

  for (let i = 0; i < 360; i++) {
    let t = random(1);
    let y = lerp(470, 170, t);
    let spread = lerp(25, 280, t * t);
    let x = 800 + (noise(i * 0.01, t * 2) - 0.5) * spread;
    let s = lerp(8, 1.5, t);
    let a = lerp(28, 0, t);
    fill(178, 186, 205, a);
    ellipse(x, y, s, s);
  }
}

function drawVignette() {
  drawingContext.save();
  let grd = drawingContext.createRadialGradient(W / 2, H * 0.45, 200, W / 2, H * 0.45, 1350);
  grd.addColorStop(0, 'rgba(0,0,0,0)');
  grd.addColorStop(1, 'rgba(0,0,0,0.72)');
  drawingContext.fillStyle = grd;
  drawingContext.fillRect(0, 0, W, H);
  drawingContext.restore();
}

function insideFigure(x, y) {
  if (dist(x, y, 800, 610) < 95) return true;

  if (y >= 610 && y < 690 && abs(x - 800) < 58) return true;

  if (y >= 690 && y < 1100) {
    let t = (y - 690) / 410;
    let half;
    if (t < 0.2) {
      half = lerp(58, 240, t / 0.2);
    } else {
      half = lerp(240, 80, (t - 0.2) / 0.8);
    }
    return abs(x - 800) < half;
  }

  return false;
}

