function drawTree(){
  push();
  translate(800, 1540);
  branch(190, 24, 16);
  pop();
}

function branch(len, angle, weight){
  if(weight > 10){
    stroke(62, 50, 41, 245);
  } else {
    stroke(30, 26, 24, 230);
  }
  strokeWeight(weight);
  line(0, 0, 0, -len);
  translate(0, -len);

  if(len > 14){
    let spread = random(18, 34);
    let nextLen = len * random(0.72, 0.78);
    let nextWeight = max(weight * 0.7, 0.5);

    push();
    rotate(random(spread * 0.5, spread));
    branch(nextLen, spread, nextWeight);
    pop();

    push();
    rotate(-random(spread * 0.5, spread));
    branch(nextLen * random(0.90, 1.0), spread, nextWeight);
    pop();

    if(random() < 0.45){
      push();
      rotate(random(-12, 12));
      branch(nextLen * random(0.70, 0.85), spread * 0.6, nextWeight * 0.7);
      pop();
    }
  } else {
    stroke(70, 58, 48, 190);
    strokeWeight(max(weight * 0.7, 0.4));
    line(0, 0, random(-10, 10), -random(20, 48));
  }
}

