  stroke(214, 223, 238, 34);
  strokeWeight(3);
  beginShape();
  vertex(bx - 438, by - 46);
  bezierVertex(bx - 320, by + 92, bx + 320, by + 92, bx + 438, by - 46);
  endShape();

  stroke(226, 232, 244, 14);
  strokeWeight(7);
  beginShape();
  vertex(bx - 438, by - 46);
  bezierVertex(bx - 320, by + 92, bx + 320, by + 92, bx + 438, by - 46);
  endShape();
  noStroke();

  fill(224, 228, 237, 205);
  beginShape();
  vertex(bx - 250, by - 24);
  bezierVertex(bx - 130, by - 95, bx + 110, by - 100, bx + 260, by - 26);
  bezierVertex(bx + 130, by - 56, bx - 120, by - 56, bx - 250, by - 24);
  endShape(CLOSE);

  fill(228, 231, 239, 190);
  ellipse(bx - 190, by - 62, 60, 44);

  stroke(112, 122, 148, 42);
  strokeWeight(2.2);
  noFill();
  for (let i = 0; i < 8; i++) {
