function draw() {}

let W = 1600, H = 2000;

const WHALE = [
  [-545, 8], [-505, -38], [-430, -88], [-330, -122], [-215, -142],
  [-90, -150], [30, -144], [150, -124], [260, -92], [355, -52],
  [430, -16], [515, -48], [640, -110], [556, -4], [652, 98],
  [512, 38], [400, 42], [300, 76], [170, 110], [20, 128],
  [-140, 128], [-290, 110], [-410, 76], [-505, 40]
];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  noStroke();

  paintBackground();
  paintLightShafts();
  paintCaustics();
  paintSnow(0.55);
  paintRings();
  paintSeafloor();
  paintWhale();
  paintBubbles();
  paintSoulStream();
  paintFish();
  paintSnow(1);
  paintVignette();
  grain();
}

function paintBackground() {
  noStroke();
  let top = color(16, 60, 92);
  let mid = color(8, 34, 56);
  let bot = color(2, 7, 15);
  for (let y = 0; y < H; y += 2) {
    let t = y / H;
    let c = t < 0.42 ? lerpColor(top, mid, t / 0.42) : lerpColor(mid, bot, (t - 0.42) / 0.58);
    let n = noise(y * 0.012);
    c = lerpColor(c, color(30, 82, 108), (n - 0.5) * 0.16);
    fill(c);
    rect(0, y, W, 2);
  }
  blendMode(SOFT_LIGHT);
  for (let i = 0; i < 26; i++) {
    let x = random(W), y = random(H), r = random(250, 720);
    fill(random() < 0.5 ? color(42, 92, 112) : color(4, 14, 28), random(18, 42));
    ellipse(x, y, r, r * random(0.55, 1.05));
  }
  blendMode(BLEND);
}

function paintLightShafts() {
  let g = createGraphics(W, H);
  g.pixelDensity(1);
  g.clear();
  let ctx = g.drawingContext;
  let grad = ctx.createRadialGradient(430, -40, 40, 430, -40, 950);
  grad.addColorStop(0, 'rgba(175,224,242,0.55)');
  grad.addColorStop(0.5, 'rgba(120,190,220,0.18)');
  grad.addColorStop(1, 'rgba(120,190,220,0)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, W, H);
  g.push();
  g.translate(450, -160);
  g.rotate(0.28);
  g.noStroke();
  let beams = [
    { x: -190, w: 90, a: 18 }, { x: -40, w: 150, a: 30 },
    { x: 130, w: 80, a: 22 }, { x: 260, w: 185, a: 26 },
    { x: 430, w: 110, a: 20 }, { x: 590, w: 70, a: 14 }
  ];
  for (let b of beams) {
    for (let y = 0; y < 1700; y += 10) {
      let f = pow(1 - y / 1700, 1.6);
      let fl = 0.75 + 0.5 * noise(b.x * 0.13 + y * 0.008);
      g.fill(160, 216, 240, b.a * f * fl);
      g.rect(b.x - b.w / 2, y, b.w, 10);
    }
  }
  g.pop();
  g.filter(BLUR, 22);
  blendMode(ADD);
  image(g, 0, 0);
  blendMode(BLEND);
}

function paintCaustics() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 7; i++) {
    stroke(150, 212, 236, 13);
    strokeWeight(1.5);
    let y0 = random(50, 260);
    beginShape();
    for (let x = 0; x <= W; x += 40) {
      vertex(x, y0 + sin(x * 0.01 + i * 1.7) * 18 + noise(x * 0.01, i) * 26);
    }
    endShape();
  }
  blendMode(BLEND);
}

function paintSnow(m) {
  noStroke();
  let n = Math.floor(430 * m);
  for (let i = 0; i < n; i++) {
    let x = random(W), y = random(H);
    let s = random(0.8, 2.6) * m;
    fill(190, 216, 231, random(10, 40) * m);
    ellipse(x, y, s, s);
  }
}

function paintRings() {
  blendMode(ADD);
  noFill();
  stroke(110, 195, 225, 9);
  strokeWeight(2.4);
  ellipse(840, 920, 1230, 1310);
  stroke(110, 195, 225, 5);
  strokeWeight(1.6);
  ellipse(840, 920, 1560, 1660);
  blendMode(BLEND);
}

function radialGlow(x, y, r, c, a) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + red(c) + ',' + green(c) + ',' + blue(c) + ',' + (a / 255) + ')');
  g.addColorStop(1, 'rgba(' + red(c) + ',' + green(c) + ',' + blue(c) + ',0)');
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function paintSeafloor() {
  let cols = [color(7, 15, 25), color(4, 10, 18), color(2, 6, 12)];
  noStroke();
  for (let k = 0; k < 3; k++) {
    let base = H - 260 + k * 70;
    fill(cols[k]);
    beginShape();
    vertex(0, H);
    for (let x = 0; x <= W; x += 20) {
      let y = base - noise(x * 0.0016 + k * 7.7) * 150 + noise(x * 0.02 + k * 3) * 20;
      vertex(x, y);
    }
    vertex(W, H);
    endShape(CLOSE);
  }
  blendMode(ADD);
  radialGlow(700, 1930, 430, color(255, 190, 120), 24);
  radialGlow(700, 1905, 220, color(255, 222, 175), 28);
  for (let i = 0; i < 70; i++) {
    let x = random(W * 0.1, W * 0.9);
    let y = random(H - 230, H - 26);
    let s = random(1.5, 4);
    let c = random() < 0.72 ? color(110, 225, 215) : color(255, 205, 140);
    noStroke();
    fill(red(c), green(c), blue(c), 24);
    ellipse(x, y, s * 4, s * 4);
    fill(red(c), green(c), blue(c), 120);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 10; i++) {
    let bx = i < 5 ? random(520, 880) : random(W * 0.12, W * 0.88);
    let by = random(H - 200, H - 36);
    let nF = floor(random(6, 11));
    for (let f = 0; f < nF; f++) {
      let ang = -HALF_PI + random(-0.55, 0.55);
      let len = random(30, 85);
      let ex = bx + cos(ang) * len + random(-8, 8);
      let ey = by + sin(ang) * len;
      let cx = bx + cos(ang) * len * 0.5 + random(-14, 14);
      let cy = by + sin(ang) * len * 0.5;
      stroke(70, 150, 150, 90);
      strokeWeight(1.6);
      noFill();
      bezier(bx, by, cx, cy, cx + (ex - cx) * 0.4, cy + (ey - cy) * 0.6, ex, ey);
      noStroke();
      fill(150, 245, 235, 30);
      ellipse(ex, ey, 8, 8);
      fill(150, 245, 235, 140);
      ellipse(ex, ey, 2.6, 2.6);
    }
  }
  blendMode(BLEND);
}

function whaleBody(s) {
  beginShape();
