    noFill();
    beginShape();
    curveVertex(backPts[0][0], backPts[0][1] + 2);
    for (let p of backPts) curveVertex(p[0], p[1] + 2);
    curveVertex(backPts[backPts.length - 1][0], backPts[backPts.length - 1][1] + 2);
    endShape();
  }
  stroke(150, 220, 245, 30);
  strokeWeight(2);
  noFill();
  beginShape();
  curveVertex(505, -46);
  curveVertex(515, -48);
  curveVertex(640, -110);
  curveVertex(655, -100);
  endShape();
  stroke(140, 205, 230, 26);
  strokeWeight(1.8);
  beginShape();
  curveVertex(-310, 52);
  curveVertex(-310, 52);
  curveVertex(-262, 96);
  curveVertex(-206, 158);
  curveVertex(-140, 212);
  curveVertex(-118, 222);
  endShape();
  blendMode(BLEND);

  pop();
}

function paintBubbles() {
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 9; i++) {
    let t = i / 8;
    let x = 332 - t * 60 + random(-12, 12);
    let y = 1112 - t * 190 + random(-8, 8);
    let r = 2.5 + t * 8 + random(2);
    stroke(180, 226, 246, 34 + t * 66);
    strokeWeight(1.4);
    ellipse(x, y, r * 2, r * 2);
    stroke(235, 250, 255, 80);
    strokeWeight(1.2);
    arc(x, y, r * 2, r * 2, PI * 1.15, PI * 1.6);
  }
  blendMode(BLEND);
}

function soulPt(t) {
  let P0 = { x: 420, y: 1040 }, P1 = { x: 300, y: 780 };
  let P2 = { x: 560, y: 470 }, P3 = { x: 400, y: 105 };
  let u = 1 - t;
  let x = u * u * u * P0.x + 3 * u * u * t * P1.x + 3 * u * t * t * P2.x + t * t * t * P3.x;
  let y = u * u * u * P0.y + 3 * u * u * t * P1.y + 3 * u * t * t * P2.y + t * t * t * P3.y;
  x += (noise(t * 3.1, 7.7) - 0.5) * 60 * t;
  y += (noise(t * 2.3, 3.3) - 0.5) * 40 * t;
  return { x: x, y: y };
}

function paintSoulStream() {
  blendMode(ADD);
  noFill();
  for (let pass = 0; pass < 2; pass++) {
    stroke(200, 230, 250, pass ? 18 : 8);
    strokeWeight(pass ? 3 : 14);
    beginShape();
    for (let t = 0; t <= 1.001; t += 0.02) {
      let p = soulPt(t);
      vertex(p.x, p.y);
    }
    endShape();
  }
  noStroke();
  for (let i = 0; i < 520; i++) {
    let t = pow(random(), 1.35);
    let p = soulPt(t);
    let spread = 14 + 150 * t;
    let a = random(TWO_PI);
    let rr = random() * spread * (0.3 + 0.7 * random());
    let x = p.x + cos(a) * rr;
    let y = p.y + sin(a) * rr * 0.9;
    let s = random() < 0.08 ? random(4, 8) : random(1, 3.4);
    s *= 1 - t * 0.35;
    let warm = random() < 0.45;
    let al = random(60, 190) * (1 - t * 0.45);
    if (warm) fill(255, 214, 150, al); else fill(170, 225, 250, al);
    ellipse(x, y, s, s);
    if (s > 4.4) {
      if (warm) fill(255, 214, 150, al * 0.22); else fill(170, 225, 250, al * 0.22);
      ellipse(x, y, s * 3.2, s * 3.2);
    }
  }
  for (let i = 0; i < 14; i++) {
    let t = random();
    let p = soulPt(t);
    let x = p.x + random(-80, 80) * (0.4 + t);
    let y = p.y + random(-60, 60);
    let L = random(5, 12);
    stroke(255, 235, 190, 120);
    strokeWeight(1.2);
    line(x - L, y, x + L, y);
    line(x, y - L, x, y + L);
  }
  blendMode(BLEND);
}

function drawFish(x, y, a, s) {
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(16, 28, 40, 215);
  beginShape();
  vertex(s, 0);
  bezierVertex(s * 0.5, -s * 0.42, -s * 0.4, -s * 0.3, -s * 0.8, 0);
  bezierVertex(-s * 0.4, s * 0.3, s * 0.5, s * 0.42, s, 0);
  endShape(CLOSE);
  triangle(-s * 0.7, 0, -s * 1.25, -s * 0.35, -s * 1.25, s * 0.35);
  stroke(130, 190, 215, 42);
  strokeWeight(1);
  line(-s * 0.6, -s * 0.05, s * 0.6, -s * 0.12);
  pop();
}

function paintFish() {
  for (let i = 0; i < 18; i++) {
    let x = random(110, 560);
    let y = random(560, 1070);
    let s = random(8, 19);
    let dir = atan2(1100 - y, 300 - x) + random(-0.45, 0.45);
    drawFish(x, y, dir, s);
  }
}

function paintVignette() {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(W * 0.5, H * 0.45, 520, W * 0.5, H * 0.45, 1500);
  g.addColorStop(0, 'rgba(1,4,9,0)');
  g.addColorStop(0.72, 'rgba(1,4,9,0.22)');
  g.addColorStop(1, 'rgba(0,2,6,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  let g2 = ctx.createLinearGradient(0, H - 500, 0, H);
  g2.addColorStop(0, 'rgba(0,3,8,0)');
  g2.addColorStop(1, 'rgba(0,2,5,0.55)');
  ctx.fillStyle = g2;
  ctx.fillRect(0, H - 500, W, 500);
}

function grain() {
  loadPixels();
  let d = pixels;
  for (let i = 0; i < d.length; i += 4) {
    let n = (random() - 0.5) * 24;
    d[i] += n;
    d[i + 1] += n;
    d[i + 2] += n;
  }
  updatePixels();
}

const W = 1600, H = 2000;
const NS = 96;
let head, axisV, nrmV, L0, topPts, botPts;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
  paint();
}

function paint() {
  drawBackground();
  drawAtmosphere();
  raysPass(1.0);
  glow(790, 1060, 640, [36, 84, 104], 13);
  glow(700, 1150, 300, [30, 70, 90], 8);
  drawSnow(360);
  drawWhale();
  drawFish();
  drawRisingLights();
  drawBreathBubbles();
  drawSeabed();
  raysPass(0.28);
  drawVignette();
  drawGrain();
  drawSnow(430);
}

/* ---------- helpers ---------- */

function glow(x, y, r, col, target) {
  push();
  blendMode(ADD);
  noStroke();
  const n = 26;
  for (let i = n; i >= 1; i--) {
    fill(col[0], col[1], col[2], target / n);
    ellipse(x, y, 2 * r * i / n, 2 * r * i / n);
  }
  pop();
}

/* ---------- water ---------- */

function drawBackground() {
  noStroke();
  const stops = [
    [0.00, 21, 47, 64],
    [0.10, 13, 32, 47],
    [0.26, 7, 19, 31],
    [0.52, 3, 10, 18],
    [0.78, 2, 5, 10],
    [1.00, 1, 2, 5]
  ];
  for (let y = 0; y < H; y++) {
    const t = y / H;
    let c = null;
    for (let i = 0; i < stops.length - 1; i++) {
      if (t <= stops[i + 1][0]) {
        const u = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        c = [
          lerp(stops[i][1], stops[i + 1][1], u),
          lerp(stops[i][2], stops[i + 1][2], u),
          lerp(stops[i][3], stops[i + 1][3], u)
        ];
        break;
      }
    }
    if (!c) c = [stops[stops.length - 1][1], stops[stops.length - 1][2], stops[stops.length - 1][3]];
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 1.5);
  }
}

function drawAtmosphere() {
  noStroke();
  for (let i = 0; i < 5; i++) {
    const x = random(W), y = random(H * 0.25, H * 0.95);
    const r = random(300, 620);
    fill(1, 4, 8, 4);
    for (let k = 10; k >= 1; k--) ellipse(x, y, 2 * r * k / 10, 2 * r * k / 10);
  }
  glow(240, 1700, 420, [20, 60, 70], 8);
  glow(830, -40, 900, [70, 140, 165], 20);
  glow(830, -80, 520, [110, 190, 205], 16);
}

function rayPt(O, ang, d) {
  return createVector(O.x + Math.sin(ang) * d, O.y + Math.cos(ang) * d);
}

function raysPass(mult) {
  push();
  blendMode(ADD);
  noStroke();
  const O = createVector(845, -300);
  const defs = [
    [-0.335, 0.030, 1500, 2.6],
    [-0.215, 0.052, 1750, 3.6],
    [-0.085, 0.040, 1900, 3.0],
    [0.035, 0.062, 2050, 4.2],
    [0.155, 0.038, 1800, 3.2],
    [0.285, 0.055, 1550, 2.7],
    [0.375, 0.026, 1300, 2.0]
  ];
  const S = 42;
  for (const def of defs) {
    const A = def[0], w0 = def[1], len = def[2], al0 = def[3];
    for (let j = 0; j < S; j++) {
      const t0 = j / S, t1 = (j + 1) / S;
      const shimmer = 0.75 + 0.5 * noise(j * 0.18 + A * 9);
      const al = al0 * mult * Math.pow(1 - t0, 1.7) * shimmer;
      const wA0 = w0 * (0.35 + t0 * 1.1), wA1 = w0 * (0.35 + t1 * 1.1);
      const p1 = rayPt(O, A - wA0, t0 * len), p2 = rayPt(O, A + wA0, t0 * len);
      const p3 = rayPt(O, A + wA1, t1 * len), p4 = rayPt(O, A - wA1, t1 * len);
      fill(105, 185, 205, al);
      beginShape();
      vertex(p1.x, p1.y); vertex(p2.x, p2.y);
      vertex(p3.x, p3.y); vertex(p4.x, p4.y);
      endShape(CLOSE);
    }
  }
  pop();
}

function drawSnow(n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    const x = random(W), y = random(H);
    const a = random(5, 20) * (1 - (y / H) * 0.4);
    fill(182, 214, 229, a);
    const r = random(0.8, 2.4);
    ellipse(x, y, r * 2, r * 2);
    if (random() < 0.05) {
      fill(182, 214, 229, a * 0.3);
      ellipse(x, y, r * 6, r * 6);
    }
  }
}

/* ---------- whale ---------- */

function smooth01(x) { x = constrain(x, 0, 1); return x * x * (3 - 2 * x); }
function bendAt(s) { return -42 * Math.sin(PI * Math.pow(s, 0.92)); }

function whaleGeom() {
  head = createVector(330, 1330);
  const tail = createVector(1290, 775);
  axisV = p5.Vector.sub(tail, head);
  L0 = axisV.mag();
  axisV.normalize();
  nrmV = createVector(-axisV.y, axisV.x);
  topPts = []; botPts = [];
  for (let i = 0; i <= NS; i++) {
    const s = i / NS, c = centerAt(s), w = whaleW(s);
    topPts.push(p5.Vector.sub(c, p5.Vector.mult(nrmV, w)));
    botPts.push(p5.Vector.add(c, p5.Vector.mult(nrmV, w)));
  }
}

function centerAt(s) {
  return p5.Vector.add(
    p5.Vector.add(head, p5.Vector.mult(axisV, s * L0)),
    p5.Vector.mult(nrmV, bendAt(s))
  );
}

function whaleW(s) {
  if (s < 0.30) return 132 * lerp(0.56, 1.0, smooth01(s / 0.30));
  const t = (s - 0.30) / 0.70;
  return 132 * lerp(1.0, 0.05, Math.pow(t, 1.28));
}

function contourLine(offFrac, i0, i1) {
  beginShape();
  for (let i = i0; i <= i1; i += 2) {
    const s = i / NS;
    const p = p5.Vector.add(centerAt(s), p5.Vector.mult(nrmV, whaleW(s) * offFrac));
    vertex(p.x, p.y);
  }
  endShape();
}

function contourTop(i0, i1) {
  beginShape();
  for (let i = i0; i <= i1; i++) vertex(topPts[i].x, topPts[i].y);
  endShape();
}

function drawWhale() {
  whaleGeom();
  noStroke();
  fill(4, 7, 12);
  beginShape();
  const tip = p5.Vector.add(p5.Vector.add(head, p5.Vector.mult(axisV, -46)), p5.Vector.mult(nrmV, -6));
  vertex(tip.x, tip.y);
  for (let i = 0; i <= NS; i++) vertex(topPts[i].x, topPts[i].y);
  for (let i = NS; i >= 0; i--) vertex(botPts[i].x, botPts[i].y);
  endShape(CLOSE);

  drawFlukes();
  drawDorsalFin();
  drawPectoralFin();
  innerShading();

  // the last warmth: a faint light where the heart was
  const hg = p5.Vector.add(centerAt(0.30), p5.Vector.mult(nrmV, 4));
  glow(hg.x, hg.y, 225, [255, 183, 115], 26);
  glow(hg.x, hg.y, 85, [255, 214, 168], 22);

  bioSpecks();
  rimLight();
  eyeLine();
}

function drawFlukes() {
  const ped = centerAt(1.0);
  const P = function(a, n) {
    return p5.Vector.add(p5.Vector.add(ped, p5.Vector.mult(axisV, a)), p5.Vector.mult(nrmV, n));
  };
  noStroke();
  fill(4, 7, 12);
  beginShape();
  let p = P(4, -14); vertex(p.x, p.y);
  p = P(168, -196); bezierVertex(P(58, -64).x, P(58, -64).y, P(118, -148).x, P(118, -148).y, p.x, p.y);
  p = P(128, -4); bezierVertex(P(132, -116).x, P(132, -116).y, P(120, -46).x, P(120, -46).y, p.x, p.y);
  p = P(186, 182); bezierVertex(P(122, 52).x, P(122, 52).y, P(138, 124).x, P(138, 124).y, p.x, p.y);
  p = P(4, 14); bezierVertex(P(124, 116).x, P(124, 116).y, P(58, 58).x, P(58, 58).y, p.x, p.y);
  endShape(CLOSE);

  noFill();
  stroke(150, 204, 222, 44); strokeWeight(1.8);
  beginShape();
  vertex(P(4, -14).x, P(4, -14).y);
  bezierVertex(P(58, -64).x, P(58, -64).y, P(118, -148).x, P(118, -148).y, P(168, -196).x, P(168, -196).y);
  endShape();
  stroke(90, 150, 175, 26); strokeWeight(1.6);
  beginShape();
  vertex(P(128, -4).x, P(128, -4).y);
  bezierVertex(P(122, 52).x, P(122, 52).y, P(138, 124).x, P(138, 124).y, P(186, 182).x, P(186, 182).y);
  endShape();
}

function drawDorsalFin() {
  const bf = p5.Vector.sub(centerAt(0.775), p5.Vector.mult(nrmV, whaleW(0.775) + 2));
  const br = p5.Vector.sub(centerAt(0.862), p5.Vector.mult(nrmV, whaleW(0.862) + 2));
  const tp = p5.Vector.sub(p5.Vector.add(centerAt(0.845), p5.Vector.mult(axisV, 30)), p5.Vector.mult(nrmV, whaleW(0.845) + 42));
  noStroke(); fill(4, 7, 12);
  beginShape();
  vertex(bf.x, bf.y);
  quadraticVertex(tp.x, tp.y, br.x, br.y);
  endShape(CLOSE);
  noFill();
  stroke(150, 200, 220, 34); strokeWeight(1.6);
  beginShape();
  vertex(bf.x, bf.y);
  quadraticVertex(tp.x, tp.y, br.x, br.y);
  endShape();
}

function drawPectoralFin() {
  const b1 = p5.Vector.add(centerAt(0.155), p5.Vector.mult(nrmV, whaleW(0.155) * 0.8));
  const b2 = p5.Vector.add(centerAt(0.245), p5.Vector.mult(nrmV, whaleW(0.245) * 0.88));
  const tp = p5.Vector.add(p5.Vector.add(centerAt(0.235), p5.Vector.mult(nrmV, whaleW(0.235) + 122)), p5.Vector.mult(axisV, 46));
  noStroke(); fill(7, 12, 18);
  beginShape();
  vertex(b1.x, b1.y);
  quadraticVertex(tp.x, tp.y, b2.x, b2.y);
  endShape(CLOSE);
  noFill();
  stroke(120, 175, 200, 26); strokeWeight(1.4);
  beginShape();
  vertex(b1.x, b1.y);
  quadraticVertex(tp.x, tp.y, b2.x, b2.y);
  endShape();
}

function innerShading() {
  noFill();
  stroke(44, 74, 94, 12); strokeWeight(9);
  contourLine(-0.62, 8, NS - 6);
  stroke(26, 46, 62, 10); strokeWeight(14);
  contourLine(-0.35, 10, NS - 6);
  stroke(2, 4, 7, 34); strokeWeight(22);
  contourLine(0.72, 14, NS - 8);
  stroke(2, 4, 7, 22); strokeWeight(30);
  contourLine(0.9, 20, NS - 10);

  // throat pleats
  stroke(30, 52, 68, 16); strokeWeight(1.8);
  for (let g = 0; g < 7; g++) contourLine(0.55 + g * 0.062, 4, 30);

  // mouth line
  stroke(30, 50, 64, 40); strokeWeight(2);
  beginShape();
  const mp0 = p5.Vector.add(p5.Vector.add(head, p5.Vector.mult(axisV, 4)), p5.Vector.mult(nrmV, 24));
  vertex(mp0.x, mp0.y);
  for (let i = 6; i <= 16; i += 2) {
    const s = i / NS;
    const p = p5.Vector.add(centerAt(s), p5.Vector.mult(nrmV, whaleW(s) * 0.62));
    vertex(p.x, p.y);
  }
  endShape();
}

function bioSpecks() {
  push();
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 70; i++) {
    const s = random(0.35, 0.99);
    const p = p5.Vector.add(centerAt(s), p5.Vector.mult(nrmV, whaleW(s) * random(0.25, 0.98)));
    const r = random(1.2, 3.4);
    fill(120, 235, 215, random(18, 70));
    ellipse(p.x, p.y, r * 2, r * 2);
    if (random() < 0.3) {
      fill(120, 235, 215, 8);
      ellipse(p.x, p.y, r * 7, r * 7);
    }
  }
  pop();
}

function rimLight() {
  noFill();
  push(); blendMode(ADD);
  stroke(70, 130, 160, 10); strokeWeight(8);
  contourTop(2, 88);
  stroke(95, 165, 195, 14); strokeWeight(4);
  contourTop(2, 88);
  pop();
  stroke(168, 216, 232, 78); strokeWeight(2.2);
  contourTop(1, 87);
  push(); blendMode(ADD);
  stroke(150, 205, 225, 40); strokeWeight(3);
  beginShape();
  const tip = p5.Vector.add(p5.Vector.add(head, p5.Vector.mult(axisV, -46)), p5.Vector.mult(nrmV, -6));
  vertex(tip.x, tip.y);
  vertex(topPts[1].x, topPts[1].y);
  endShape();
  stroke(255, 180, 115, 12); strokeWeight(4);
  contourLine(0.98, 12, 40);
  pop();
}

function eyeLine() {
  const ep = p5.Vector.add(p5.Vector.add(centerAt(0.075), p5.Vector.mult(nrmV, whaleW(0.075) * 0.52)), p5.Vector.mult(axisV, 8));
  noFill();
  stroke(150, 200, 215, 66); strokeWeight(2);
  arc(ep.x, ep.y, 26, 13, PI * 0.12, PI * 0.88, OPEN);
}

/* ---------- life gathering ---------- */

function drawFish() {
  const cc = centerAt(0.46);
  for (let i = 0; i < 95; i++) {
    const s = random(0.06, 0.98);
    const c = centerAt(s);
    const side = random() < 0.55 ? -1 : 1;
    const dist = whaleW(s) + random(20, 250);
    const p = p5.Vector.add(c, p5.Vector.mult(nrmV, side * dist));
    p.add(p5.Vector.mult(axisV, random(-100, 100)));
    if (p.x < 20 || p.x > W - 20 || p.y < 40 || p.y > H - 40) continue;
    const rel = p5.Vector.sub(p, cc);
    let tan = createVector(-rel.y, rel.x).setMag(1);
    if (random() < 0.5) tan.mult(-1);
    const len = random(8, 20);
    const bright = random() < 0.2;
    const al = random(40, 120);
    const cr = bright ? 175 : 110, cg = bright ? 236 : 178, cb = bright ? 245 : 198;
    stroke(cr, cg, cb, al);
    strokeWeight(random(1.3, 2.8));
    noFill();
    const q1 = p5.Vector.add(p, p5.Vector.mult(tan, len * 0.5));
    const q2 = p5.Vector.add(p, p5.Vector.mult(tan, len));
    q2.add(createVector(random(-2.5, 2.5), random(-2.5, 2.5)));
    beginShape();
    vertex(p.x, p.y);
    quadraticVertex(q1.x + random(-3, 3), q1.y + random(-3, 3), q2.x, q2.y);
    endShape();
    noStroke();
    fill(cr, cg, cb, al * 0.9);
    ellipse(q2.x, q2.y, 2.6, 2.6);
  }
}

function drawRisingLights() {
  push();
  blendMode(ADD);
  noStroke();
  for (let k = 0; k < 430; k++) {
    const s = 0.04 + 0.95 * Math.pow(random(), 0.82);
    const c = centerAt(s);
    const w = whaleW(s);
    const p = p5.Vector.add(c, p5.Vector.mult(nrmV, -w * random(0.1, 1.08)));
    const warm = random() < 0.74;
    const col = warm ? [255, 206, 150] : [152, 228, 236];
    const steps = Math.floor(random(18, 86));
    const baseA = random(24, 72);
    const r0 = random(0.9, 2.7);
    const nx = random(1000);
    for (let j = 0; j < steps; j++) {
      const t = j / steps;
      p.y -= 6.4 * (0.6 + 0.75 * (1 - t));
      p.x += (noise(nx + p.y * 0.006, p.x * 0.0035) - 0.5) * 9;
      if (p.y < 50) break;
      if (random() < 0.7) {
        const a = baseA * (1 - t) * (0.55 + 0.45 * Math.sin(PI * Math.min(1, t * 1.6)));
        fill(col[0], col[1], col[2], a);
        const rr = r0 * (1 - t * 0.55);
        ellipse(p.x, p.y, rr * 2, rr * 2);
        if (random() < 0.08) {
          fill(col[0], col[1], col[2], a * 0.16);
          ellipse(p.x, p.y, rr * 8, rr * 8);
        }
      }
    }
  }
  // spirit orbs
  for (let k = 0; k < 15; k++) {
    const s = random(0.1, 0.9);
    const c = centerAt(s);
    let p = p5.Vector.add(c, p5.Vector.mult(nrmV, -whaleW(s) * random(0.2, 1.0)));
    const rise = random(420, 900);
    const wob = random(1000);
    for (let j = 0; j < rise; j += 7) {
      p.y -= 7;
      p.x += (noise(wob + j * 0.01) - 0.5) * 10;
      if (p.y < 70) break;
    }
    const r = random(2.6, 5.6);
    const a = random(40, 85);
    fill(255, 224, 180, a * 0.5); ellipse(p.x, p.y, r * 2, r * 2);
    fill(255, 206, 150, a * 0.22); ellipse(p.x, p.y, r * 4.6, r * 4.6);
    fill(255, 240, 220, a * 0.8); ellipse(p.x, p.y, r * 1.1, r * 1.1);
  }
  pop();
}

function drawBreathBubbles() {
