let ctx;
const W = 1600, H = 2000;
const ANG = -0.5, NX = 320, NY = 1290;
const CC = Math.cos(ANG), SS = Math.sin(ANG);
let fishPts = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  ctx = drawingContext;
  paint();
}

function wx(x, y) { return NX + x * CC - y * SS; }
function wy(x, y) { return NY + x * SS + y * CC; }

function topLocalY(x) {
  x = Math.max(4, Math.min(1272, x));
  if (x < 310) return lerp(-8, -160, Math.sqrt((x - 4) / 306));
  if (x < 1018) return lerp(-160, -21, (x - 310) / 708) - 16 * Math.sin(PI * (x - 310) / 708);
  return lerp(-21, -168, (x - 1018) / 254);
}

function bellyLocal(x) {
  x = Math.max(255, Math.min(1012, x));
  if (x < 620) return lerp(176, 152, (x - 255) / 365);
  return lerp(152, 24, (x - 620) / 392);
}

function whalePath() {
  const p = new Path2D();
  p.moveTo(4, -6);
  p.bezierCurveTo(90, -72, 190, -150, 310, -160);
  p.bezierCurveTo(470, -172, 650, -140, 780, -96);
  p.bezierCurveTo(880, -64, 966, -36, 1018, -21);
  p.bezierCurveTo(1076, -6, 1180, -92, 1272, -168);
  p.bezierCurveTo(1236, -110, 1182, -62, 1160, -36);
  p.bezierCurveTo(1150, -16, 1202, 40, 1252, 102);
  p.bezierCurveTo(1152, 72, 1062, 34, 1014, 24);
  p.bezierCurveTo(906, 54, 760, 122, 620, 152);
  p.bezierCurveTo(500, 176, 360, 184, 255, 176);
  p.bezierCurveTo(160, 166, 70, 128, 26, 88);
  p.bezierCurveTo(8, 60, 0, 24, 4, -6);
  p.closePath();
  return p;
}

function topEdgePath() {
  const p = new Path2D();
  p.moveTo(4, -6);
  p.bezierCurveTo(90, -72, 190, -150, 310, -160);
  p.bezierCurveTo(470, -172, 650, -140, 780, -96);
  p.bezierCurveTo(880, -64, 966, -36, 1018, -21);
  p.bezierCurveTo(1076, -6, 1180, -92, 1272, -168);
  return p;
}

function bellyEdgePath() {
  const p = new Path2D();
  p.moveTo(1014, 24);
  p.bezierCurveTo(906, 54, 760, 122, 620, 152);
  p.bezierCurveTo(500, 176, 360, 184, 255, 176);
  p.bezierCurveTo(160, 166, 70, 128, 26, 88);
  return p;
}

function glowDot(x, y, r, cr, cg, cb, a) {
  noStroke();
  for (let k = 1; k <= 3; k++) {
    fill(cr, cg, cb, a / (k * 2.2));
    circle(x, y, r * 2 * (2 + k * 2.2));
  }
  fill(min(cr + 70, 255), min(cg + 40, 255), min(cb + 30, 255), min(a * 1.5, 255));
  circle(x, y, r * 1.6);
}

function paint() {
  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0d3b50');
  g.addColorStop(0.26, '#08293c');
  g.addColorStop(0.52, '#051624');
  g.addColorStop(0.78, '#030c15');
  g.addColorStop(1, '#01040a');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  let rg = ctx.createRadialGradient(340, -160, 60, 340, -160, 1500);
  rg.addColorStop(0, 'rgba(126,205,214,0.20)');
  rg.addColorStop(0.55, 'rgba(80,150,162,0.06)');
  rg.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = rg;
  ctx.fillRect(0, 0, W, H);

  lightRays();
  snowBack();
  seabed();
  skeleton();
  whale();
  bubbles();
  swarm();
  biolume();
  snowFront();
  vignette();
  grain();
}

function lightRays() {
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  const beams = [
    [150, 150, 210, 960, 0.085],
    [400, 112, 290, 1120, 0.105],
    [620, 86, 300, 930, 0.075],
    [880, 150, 380, 1180, 0.06]
  ];
  for (const b of beams) {
    const x0 = b[0], w0 = b[1], drift = b[2], len = b[3], a = b[4];
    for (const L of [[1.75, 0.30], [1.0, 0.55], [0.45, 0.95]]) {
      const wT = w0 * L[0], wB = w0 * 0.5 * L[0];
      const g = ctx.createLinearGradient(0, -20, 0, len);
      g.addColorStop(0, 'rgba(152,226,232,' + (a * L[1]).toFixed(3) + ')');
      g.addColorStop(0.72, 'rgba(118,198,208,' + (a * L[1] * 0.28).toFixed(3) + ')');
      g.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = g;
      ctx.beginPath();
      ctx.moveTo(x0 - wT / 2, -20);
      ctx.lineTo(x0 + wT / 2, -20);
      ctx.lineTo(x0 + drift + wB / 2, len);
      ctx.lineTo(x0 + drift - wB / 2, len);
      ctx.closePath();
      ctx.fill();
    }
  }
  ctx.restore();
}

function snowBack() {
  noStroke();
