    let x = random(W), y = random(H);
    x += (noise(x * 0.0015, y * 0.0015) - 0.5) * 170;
    if (x < 0) x += W; if (x >= W) x -= W;
    const d = y / H;
    const s = (0.7 + random(1.7)) * (1.15 - d * 0.5);
    fill(186, 214, 220, (10 + random(38)) * (1 - d * 0.45));
    circle(x, y, s * 2);
  }
  for (let i = 0; i < 20; i++) {
    const x = random(W), y = random(H * 0.8), r = 6 + random(9);
    fill(168, 206, 216, 9 + random(10));
    circle(x, y, r * 2);
  }
}

function seabed() {
  noStroke();
  fill(4, 8, 13);
  beginShape();
  vertex(0, H + 10);
  for (let x = 0; x <= W; x += 36) {
    vertex(x, 1896 + noise(8.3 + x * 0.0021) * 66 - 18 * Math.sin(x * 0.0045));
