function skeleton() {
  noFill();
  stroke(110, 150, 158, 58);
  strokeWeight(9);
  bezier(205, 1898, 380, 1902, 560, 1916, 772, 1924);
  const ribs = [];
  for (let i = 0; i < 7; i++) {
    const t = i / 6;
    const bx = lerp(240, 700, t), by = lerp(1896, 1922, t) + noise(i * 3.1) * 6;
    const h = (92 + 74 * Math.sin(PI * (i + 0.5) / 7)) * (0.92 + noise(i * 7.7) * 0.18);
    ribs.push([bx, by, h]);
    stroke(116, 156, 164, 44 + random(26));
    strokeWeight(5.5 + noise(i * 2.2) * 2);
    bezier(bx + 10, by + 8, bx - 44, by - h * 0.42, bx - 60, by - h * 0.86, bx - 16, by - h);
  }
  noStroke();
  fill(104, 144, 152, 46);
  beginShape();
  vertex(212, 1899);
  bezierVertex(150, 1880, 86, 1868, 58, 1876);
  bezierVertex(40, 1882, 44, 1896, 66, 1902);
  bezierVertex(120, 1916, 180, 1918, 214, 1914);
  endShape(CLOSE);
  stroke(30, 50, 58, 60);
  strokeWeight(2.5);
  line(62, 1890, 205, 1906);
  noStroke();
  for (let i = 0; i < 4; i++) {
    fill(104, 144, 152, 40 - i * 6);
    ellipse(796 + i * 40, 1928 + i * 3, 26 - i * 3, 18 - i * 2);
  }
  fill(3, 7, 12);
  beginShape();
  vertex(90, H + 10);
  for (let x = 90; x <= 860; x += 26) {
    vertex(x, 1934 + noise(40 + x * 0.012) * 22);
  }
  vertex(860, H + 10);
  endShape(CLOSE);
  push();
  blendMode(ADD);
  for (let i = 0; i < ribs.length; i++) {
    const bx = ribs[i][0], by = ribs[i][1], h = ribs[i][2];
    const n = 2 + (i % 2);
    for (let k = 0; k < n; k++) {
      const u = random(0.35, 0.95);
      glowDot(lerp(bx + 10, bx - 16, u) + random(-10, 10), lerp(by + 8, by - h, u) + random(-8, 8),
        random(1.2, 2.4), 150, 240, 222, random(90, 170));
    }
  }
  for (let k = 0; k < 5; k++) {
    glowDot(96 + random(60), 1882 + random(14), random(1, 2), 160, 244, 226, random(80, 150));
  }
  pop();
}

function whale() {
  push();
  translate(NX, NY);
  rotate(ANG);
  const body = whalePath();
  const g = ctx.createLinearGradient(0, -200, 0, 200);
  g.addColorStop(0, '#1d4152');
  g.addColorStop(0.34, '#0e2130');
  g.addColorStop(0.68, '#071119');
  g.addColorStop(1, '#04080e');
  ctx.fillStyle = g;
  ctx.fill(body);

  ctx.save();
  ctx.clip(body);
  noStroke();
  for (let i = 0; i < 430; i++) {
    const x = random(20, 1265);
    const ty = topLocalY(x);
    const y = ty + 6 + random(random(130));
    const r = 2.5 + random(9);
    fill(72, 120, 138, 6 + random(18));
    ellipse(x, y, r * 2.4, r * 1.7);
  }
  for (let i = 0; i < 90; i++) {
    const x = random(60, 1100);
    const ty = topLocalY(x);
    fill(150, 198, 206, 5 + random(10));
    ellipse(x, ty + 4 + random(46), 3.2, 2.4);
  }
  let bg = ctx.createLinearGradient(0, 40, 0, 195);
  bg.addColorStop(0, 'rgba(2,5,9,0)');
  bg.addColorStop(1, 'rgba(1,3,7,0.6)');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 30, 1320, 180);
  noFill();
  stroke(158, 198, 205, 30);
  strokeWeight(2.4);
  for (let i = 0; i < 7; i++) {
    const oy = i * 12;
    bezier(40 + i * 7, 98 + oy, 130, 142 + oy * 0.8, 268, 160 + oy * 0.6, 468, 152 + oy * 0.5);
  }
  stroke(2, 6, 10, 150);
  strokeWeight(3);
  bezier(12, 30, 70, 84, 170, 106, 300, 118);
  noStroke();
  fill(5, 9, 13);
  circle(172, 58, 11);
  fill(140, 205, 212, 80);
  circle(170, 56, 3.4);
  ctx.restore();

  const top = topEdgePath();
  ctx.save();
  ctx.globalCompositeOperation = 'lighter';
  ctx.lineJoin = 'round';
  ctx.lineCap = 'round';
  const P = [[17, 'rgba(105,190,200,0.07)'], [8, 'rgba(150,224,228,0.15)'], [2.8, 'rgba(216,248,246,0.32)']];
  for (const s of P) {
    ctx.lineWidth = s[0];
    ctx.strokeStyle = s[1];
    ctx.stroke(top);
  }
  ctx.lineWidth = 7;
  ctx.strokeStyle = 'rgba(80,190,180,0.05)';
  ctx.stroke(bellyEdgePath());
  ctx.restore();

  fill(7, 14, 20);
  noStroke();
  beginShape();
  vertex(300, 150);
  bezierVertex(362, 192, 458, 260, 508, 302);
  bezierVertex(448, 274, 330, 206, 252, 178);
  endShape(CLOSE);
  noFill();
  stroke(150, 216, 222, 44);
  strokeWeight(2);
  bezier(300, 150, 362, 192, 458, 260, 508, 302);
  pop();

  push();
  blendMode(ADD);
  translate(wx(600, -150), wy(600, -150));
  rotate(ANG);
  noStroke();
  fill(130, 214, 220, 20);
  ellipse(0, 0, 420, 110);
  fill(150, 228, 230, 16);
  ellipse(10, -6, 250, 64);
  pop();
}

function bubbles() {
  noFill();
  for (let i = 0; i < 11; i++) {
    const t = i / 10;
    const x = wx(130, -158) - 64 * t + Math.sin(t * 7.4 + 0.8) * 24;
    const y = wy(130, -158) - 520 * t;
