}

function fish(x, y, s, a, alpha) {
  if (alpha === undefined) alpha = 235;
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(3, 8, 12, alpha);
  ellipse(0, 0, s * 2.3, s * 0.95);
  triangle(-s * 1.05, 0, -s * 1.95, -s * 0.6, -s * 1.95, s * 0.6);
  pop();
}

function swarm() {
  fishPts = [];
  for (let i = 0; i < 38; i++) {
    const t = random();
    const lx = lerp(300, 990, t);
    const bl = bellyLocal(lx);
    const off = 46 + random(240);
    const x = wx(lx, bl + off) + random(-34, 34);
    const y = wy(lx, bl + off) + random(-34, 34);
    fish(x, y, 4.5 + random(9), ANG + random(-0.45, 0.45) + (random() < 0.5 ? PI : 0));
    fishPts.push([x, y]);
  }
  for (let i = 0; i < 6; i++) {
    const x = 360 + random(260), y = 1330 + random(180);
    fish(x, y, 3.5 + random(6), random(TWO_PI));
    fishPts.push([x, y]);
  }
  for (let i = 0; i < 5; i++) {
    fish(240 + random(480), 1806 + random(66), 3 + random(5), random(TWO_PI));
  }
  for (let i = 0; i < 6; i++) {
    fish(1050 + random(430), 330 + random(520), 2.5 + random(4), random(TWO_PI), 90);
  }
  for (let i = 0; i < 4; i++) {
    fish(1080 + random(300), 1500 + random(220), 3 + random(5), random(TWO_PI), 200);
  }
  push();
  blendMode(ADD);
  for (let i = 0; i < fishPts.length; i++) {
    if (i % 2 === 0) {
      glowDot(fishPts[i][0] + random(-4, 4), fishPts[i][1] + random(2, 6), 1.1, 150, 238, 226, random(70, 150));
    }
