    glowDot(wx(lx, bl + off), wy(lx, bl + off), random(0.9, 2.4), 140, 232, 220, random(60, 190));
  }
  for (let i = 0; i < 18; i++) {
    glowDot(wx(random(20, 200), random(60, 180)), wy(random(20, 200), random(60, 180)),
      random(0.8, 2), 150, 240, 224, random(50, 140));
  }
  pop();
}

function snowFront() {
  noStroke();
  for (let i = 0; i < 380; i++) {
    let x = random(W), y = random(H);
