function vignette() {
  let g = ctx.createRadialGradient(800, 920, 420, 800, 1000, 1560);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.62, 'rgba(1,4,9,0.16)');
