/* ---------- 地平线 ---------- */
function horizonY(x) {
  const base = 700 + (noise(x * 0.0012 + 3.7) - 0.5) * 44;
  const bump = 52 * Math.exp(-Math.pow((x - 810) / 190, 2)); // 坟丘
  return base - bump;
}

/* ---------- 天空 ---------- */
function skyPal(t) {
  const s = [
    [0.00, 6, 8, 24], [0.35, 16, 22, 58], [0.62, 46, 36, 84],
    [0.80, 96, 60, 96], [0.92, 168, 92, 80], [1.00, 224, 142, 88]
  ];
  t = constrain(t, 0, 1);
  for (let i = 0; i < s.length - 1; i++) {
    if (t <= s[i + 1][0]) {
      const k = (t - s[i][0]) / (s[i + 1][0] - s[i][0]);
      return [lerp(s[i][1], s[i + 1][1], k), lerp(s[i][2], s[i + 1][2], k), lerp(s[i][3], s[i + 1][3], k)];
    }
  }
  return [s[5][1], s[5][2], s[5][3]];
}
