/* ---------- 大地 ---------- */
function earthPal(t) {
  const s = [
    [0.00, 46, 30, 46], [0.06, 32, 20, 34], [0.25, 20, 13, 25],
    [0.60, 12, 7, 17], [1.00, 5, 3, 9]
  ];
  t = constrain(t, 0, 1);
  for (let i = 0; i < s.length - 1; i++) {
    if (t <= s[i + 1][0]) {
      const k = (t - s[i][0]) / (s[i + 1][0] - s[i][0]);
      return [lerp(s[i][1], s[i + 1][1], k), lerp(s[i][2], s[i + 1][2], k), lerp(s[i][3], s[i + 1][3], k)];
    }
  }
  return [s[4][1], s[4][2], s[4][3]];
}
