/* ---------- 遗骨（蜷成种子的形状） ---------- */
function bc(k) { return [232 * k + random(-6, 6), 222 * k + random(-6, 6), 198 * k + random(-6, 6)]; }
function boneSeg(x1, y1, x2, y2, w, al) {
  if (al === undefined) al = 1;
  strokeCap(ROUND);
  stroke(10, 6, 12, 80 * al); strokeWeight(w + 1.5); line(x1 + 5, y1 + 7, x2 + 5, y2 + 7);
  const c = bc(1); stroke(c[0], c[1], c[2], 246 * al); strokeWeight(w); line(x1, y1, x2, y2);
}
function boneDot(x, y, r, al) {
  if (al === undefined) al = 1;
  noStroke();
  fill(10, 6, 12, 80 * al); circle(x + 4, y + 6, r * 2 + 2);
  const c = bc(1); fill(c[0], c[1], c[2], 246 * al); circle(x, y, r * 2);
}
function boneOval(x, y, rx, ry, rot, al) {
  if (al === undefined) al = 1;
  push(); translate(x, y); rotate(rot);
  noStroke();
  fill(10, 6, 12, 80 * al); ellipse(4, 6, rx + 4, ry + 4);
  const c = bc(1); fill(c[0], c[1], c[2], 244 * al); ellipse(0, 0, rx, ry);
  pop();
}
function bez(P, t) {
  const u = 1 - t;
  return {
    x: u * u * u * P[0][0] + 3 * u * u * t * P[1][0] + 3 * u * t * t * P[2][0] + t * t * t * P[3][0],
    y: u * u * u * P[0][1] + 3 * u * u * t * P[1][1] + 3 * u * t * t * P[2][1] + t * t * t * P[3][1]
  };
}
