/* ---------- 根：自上而下的迎接 ---------- */
function growRoot(px, py, tx, ty, w, maxStep, depth, main) {
  let ang = HALF_PI + random(-0.25, 0.25);
  for (let s = 0; s < maxStep; s++) {
    const want = Math.atan2(ty - py, tx - px);
    ang += (want - ang) * 0.05 + (noise(px * 0.008, py * 0.008) - 0.5) * 0.5;
    const st = 6.5;
    const nx = px + Math.cos(ang) * st, ny = py + Math.sin(ang) * st;
    strokeCap(ROUND);
    stroke(196, 152, 92, main ? 26 : 18); strokeWeight(w * 3); line(px, py, nx, ny);
    stroke(224, 213, 184, main ? 235 : 190); strokeWeight(w); line(px, py, nx, ny);
    if (main && w > 1.6 && s % 2 === 0) RP.push([nx, ny]);
    px = nx; py = ny; w *= 0.9955;
    if (Math.hypot(px - tx, py - ty) < 26) {
      if (main) { ENDPTS.push([px, py]); glowNode(px, py); }
      return;
    }
    if (depth < 2 && w > 1.4 && random() < 0.05) {
      growRoot(px, py, tx + random(-230, 230), ty + random(-40, 170), w * 0.55, 70, depth + 1, false);
    }
  }
  if (main) { ENDPTS.push([px, py]); glowNode(px, py); }
}
function glowNode(x, y) {
  noStroke();
  fill(255, 198, 110, 36); circle(x, y, 22);
  fill(255, 208, 128, 200); circle(x, y, 7);
}
