  for (let i = 0; i < 5; i++) {
    growRoot(bases[i], horizonY(bases[i]) + 6, targets[i][0], targets[i][1], 4.6, 320, 0, true);
  }
}
function drawDeepRoots() { // 更深处，还有东西被妥善安放
  growRoot(896, 1486, 832, 1856, 2.6, 260, 0, false);
  growRoot(758, 1502, 786, 1882, 2.2, 260, 0, false);
  const P = [[826, 1868], [792, 1886], [852, 1846]];
