  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  buildTree();
  paintSky();
  paintMoon();
  paintLandAndWater();
  paintReflection();
  paintWaterMarks();
  paintTree();
  paintLeavesAndRelease();
  paintWitness();
  paintForeground();
  paintSurfaceGrain();
}

function buildTree() {
  growBranch(800, ROOT_Y, 270, -HALF_PI, 8, 72);
}

function growBranch(x, y, len, angle, depth, weight) {
  const a = angle + random(-0.11, 0.11);
  const x2 = x + cos(a) * len;
  const y2 = y + sin(a) * len;
  const bend = random(-0.18, 0.18) * len;
  const cx = (x + x2) * 0.5 - sin(a) * bend;
  const cy = (y + y2) * 0.5 + cos(a) * bend;

  branches.push({ x1: x, y1: y, x2, y2, cx, cy, w: weight, d: depth });

  if (depth <= 0 || len < 15) {
    tips.push({ x: x2, y: y2, a });
    return;
  }

  let continuing = a + random(-0.23, 0.23);
  continuing = lerp(continuing, -HALF_PI, 0.035);

  growBranch(
    x2,
    y2,
    len * random(0.70, 0.79),
    continuing,
    depth - 1,
    weight * random(0.64, 0.72)
  );

  const side = random() < 0.5 ? -1 : 1;
  growBranch(
    x2,
    y2,
    len * random(0.55, 0.72),
    a + side * random(0.43, 0.83),
    depth - 1,
    weight * random(0.49, 0.61)
  );

  if (depth > 5 && random() < 0.2) {
    growBranch(
      x2,
      y2,
      len * random(0.48, 0.62),
      a - side * random(0.55, 0.9),
      depth - 2,
      weight * 0.43
    );
  }
}

function paintSky() {
  const top = color(15, 25, 30);
  const middle = color(54, 65, 62);
  const bottom = color(14, 24, 27);

  noStroke();
  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    let c;
    if (t < 0.72) {
      c = lerpColor(top, middle, t / 0.72);
    } else {
      c = lerpColor(middle, bottom, (t - 0.72) / 0.28);
    }
    fill(c);
    rect(0, y, W, 5);
  }

  for (let i = 0; i < 9000; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.003, y * 0.003);
    stroke(190, 198, 181, random(2, 9) * n);
    strokeWeight(random(0.4, 1.5));
    point(x, y);
  }
}

function paintMoon() {
  push();
  for (let i = 85; i > 0; i--) {
    noFill();
    stroke(190, 192, 169, map(i, 85, 1, 0.2, 1.6));
    strokeWeight(3);
    ellipse(805, 680, 1005 + i * 3, 1005 + i * 3);
  }

  noStroke();
  fill(199, 196, 173, 232);
  ellipse(805, 680, 1000, 1000);

  drawingContext.beginPath();
  drawingContext.arc(805, 680, 498, 0, TWO_PI);
  drawingContext.clip();

  for (let i = 0; i < 5200; i++) {
    const x = random(300, 1310);
    const y = random(175, 1185);
    const n = noise(x * 0.006, y * 0.006);
    if (n > 0.36) {
      stroke(54, 72, 68, random(2, 12));
      strokeWeight(random(0.5, 2.2));
      line(x, y, x + random(-30, 30), y + random(-2, 2));
    }
  }

  for (let i = 0; i < 75; i++) {
    const y = random(220, 1150);
    stroke(235, 226, 194, random(2, 8));
    strokeWeight(random(3, 16));
    line(random(260, 620), y, random(990, 1360), y + random(-8, 8));
  }
  pop();

  for (let i = 0; i < 13; i++) {
    const y = 1100 + i * 25 + random(-10, 10);
    stroke(173, 181, 164, 3);
    strokeWeight(random(15, 35));
    line(-50, y, W + 50, y + random(-18, 18));
  }
}

function paintLandAndWater() {
  noStroke();
  fill(18, 29, 29);
  beginShape();
  vertex(0, 1455);
  for (let x = 0; x <= W; x += 35) {
    const y = 1450 + noise(x * 0.0025, 4.2) * 70 + sin(x * 0.004) * 12;
    vertex(x, y);
  }
  vertex(W, H);
  vertex(0, H);
  endShape(CLOSE);

  fill(8, 19, 23);
  ellipse(805, 1690, 1300, 450);

  noFill();
  stroke(105, 121, 108, 32);
  strokeWeight(2);
  arc(805, 1688, 1290, 440, PI + 0.08, TWO_PI - 0.08);

  noStroke();
  fill(29, 39, 36, 150);
  beginShape();
  vertex(0, 1490);
  bezierVertex(260, 1460, 480, 1515, 690, 1500);
  bezierVertex(480, 1550, 230, 1540, 0, 1580);
  endShape(CLOSE);
}

function paintReflection() {
  push();
  drawingContext.beginPath();
  drawingContext.ellipse(805, 1690, 645, 222, 0, 0, TWO_PI);
  drawingContext.clip();

  translate(0, ROOT_Y * 1.27);
  scale(1, -0.27);

  noFill();
  for (const b of branches) {
    const alpha = b.w > 18 ? 25 : b.w > 5 ? 15 : 9;
    stroke(143, 157, 139, alpha);
    strokeWeight(max(0.8, b.w * 0.85));
    bezier(b.x1, b.y1, b.cx, b.cy, b.cx, b.cy, b.x2, b.y2);
  }

  noStroke();
  for (let i = 0; i < tips.length; i += 3) {
    const t = tips[i];
    fill(157, 158, 130, 7);
    ellipse(t.x, t.y, random(25, 70), random(20, 55));
  }
  pop();
}

function paintWaterMarks() {
  for (let i = 0; i < 1650; i++) {
    const x = random(165, 1445);
    const y = random(1465, 1915);
    const ex = (x - 805) / 650;
    const ey = (y - 1690) / 225;
    if (ex * ex + ey * ey > 1) continue;

    const len = random(8, 105) * (1 - abs(ey) * 0.35);
    if (abs(x - 805) < 270 && random() < 0.42) {
      stroke(190, 185, 156, random(7, 27));
    } else {
      stroke(105, 129, 119, random(5, 24));
    }
    strokeWeight(random(0.5, 2));
    line(x - len * 0.5, y, x + len * 0.5, y + random(-1.5, 1.5));
  }

  noFill();
  for (let i = 0; i < 7; i++) {
    stroke(152, 157, 135, 18 - i * 1.7);
    strokeWeight(1.2);
    arc(800, 1530 + i * 8, 240 + i * 100, 32 + i * 13, 0.12, PI - 0.12);
  }
}

function paintTree() {
  noStroke();
  fill(4, 12, 14, 130);
  ellipse(800, 1530, 260, 44);

  noFill();
  for (let i = 0; i < 15; i++) {
    const side = i % 2 === 0 ? -1 : 1;
    const ex = 800 + side * random(70, 285);
    const ey = ROOT_Y + random(12, 75);
    stroke(10, 18, 19, 235);
    strokeWeight(random(5, 18));
    bezier(
      800 + random(-18, 18),
      ROOT_Y - random(15, 85),
      800 + side * random(25, 80),
      ROOT_Y + random(-5, 30),
      ex - side * 50,
      ey,
      ex,
      ey
    );
  }

  for (const b of branches) {
    noFill();
    stroke(9, 17, 19, 248);
    strokeWeight(max(0.8, b.w));
    bezier(b.x1, b.y1, b.cx, b.cy, b.cx, b.cy, b.x2, b.y2);

    if (b.w > 4) {
      stroke(91, 101, 87, b.w > 20 ? 45 : 28);
      strokeWeight(max(0.55, b.w * 0.085));
      bezier(b.x1, b.y1, b.cx, b.cy, b.cx, b.cy, b.x2, b.y2);
    }
  }

  noStroke();
  fill(8, 16, 18);
  ellipse(800, 1517, 95, 32);
}

function paintLeavesAndRelease() {
  const palette = [
    color(130, 107, 73),
    color(89, 105, 90),
    color(185, 169, 126),
    color(71, 86, 78),
    color(151, 133, 94)
  ];

  for (const t of tips) {
    const rightness = constrain(map(t.x, 730, 1270, 0, 1), 0, 1);
    const highness = constrain(map(t.y, 1080, 280, 0, 1), 0, 1);
    const dissolution = constrain(rightness * 0.78 + highness * 0.28, 0, 0.94);
    const count = floor(random(5, 12));

    for (let j = 0; j < count; j++) {
      const x = t.x + randomGaussian() * 48;
      const y = t.y + randomGaussian() * 38;
      if (random() < dissolution) continue;
      drawLeaf(
        x,
        y,
        random(4, 12),
        random(TWO_PI),
        random(palette),
        random(105, 220)
      );
    }
  }

  for (let i = 0; i < 1750; i++) {
    const t = random(tips);
    if (t.x < 620 && random() < 0.8) continue;

    const travel = pow(random(), 1.15) * 540;
    const x = t.x + travel * random(0.42, 1.05) + randomGaussian() * 35;
    const y = t.y - travel * random(0.28, 1.05) + randomGaussian() * 32;

    if (x < 20 || x > W - 20 || y < 35 || y > 1450) continue;

    const s = map(travel, 0, 540, 5.5, 0.8, true);
    const alpha = map(travel, 0, 540, 145, 28, true);
    if (random() < 0.55) {
      noStroke();
      fill(190, 184, 151, alpha * random(0.55, 1));
      ellipse(x, y, s, s * random(0.5, 1.3));
    } else {
      stroke(151, 157, 135, alpha);
      strokeWeight(max(0.5, s * 0.32));
      line(x, y, x + s * 1.8, y - s * 0.8);
    }
  }

  for (let i = 0; i < 27; i++) {
    const t = (i + random(0.1, 0.9)) / 27;
    const x = constrain(955 + t * 555 + randomGaussian() * 75, 850, 1530);
    const y = constrain(735 - t * 525 + randomGaussian() * 90, 95, 940);
    const s = map(t, 0, 1, 15, 6) * random(0.72, 1.18);
    const inside = sq(x - 805) + sq(y - 680) < sq(500);
    drawBird(
      x,
      y,
      s,
      random(-0.35, 0.22),
      inside ? color(34, 47, 44) : color(171, 176, 151)
    );
  }

  drawLeaf(552, 1248, 13, -0.55, color(155, 63, 43), 225);
}

function drawLeaf(x, y, s, angle, c, alpha = 190) {
  push();
  translate(x, y);
  rotate(angle);
  noStroke();
  fill(red(c), green(c), blue(c), alpha);
  beginShape();
  vertex(0, -s);
  bezierVertex(s * 0.72, -s * 0.35, s * 0.62, s * 0.6, 0, s);
  bezierVertex(-s * 0.62, s * 0.6, -s * 0.72, -s * 0.35, 0, -s);
  endShape(CLOSE);
  pop();
}

function drawBird(x, y, s, angle, c) {
  push();
  translate(x, y);
  rotate(angle);
  noFill();
  stroke(red(c), green(c), blue(c), 175);
  strokeWeight(max(0.8, s * 0.13));
  bezier(0, 0, -s * 0.28, -s * 0.56, -s * 0.83, -s * 0.62, -s * 1.25, -s * 0.16);
  bezier(0, 0, s * 0.28, -s * 0.56, s * 0.83, -s * 0.62, s * 1.25, -s * 0.16);
  pop();
}

