      stroke(225, 222, 194, random(2, 8));
    } else {
      stroke(0, 7, 9, random(2, 9));
    }
    strokeWeight(random(0.35, 1.1));
    point(x, y);
  }

  for (let i = 0; i < 240; i++) {
    const x = random(W);
    const y = random(H);
    stroke(214, 210, 181, random(1, 4));
    strokeWeight(random(0.4, 1));
    line(x, y, x + random(-45, 45), y + random(-3, 3));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  angleMode(RADIANS);
  noLoop();
}

function draw() {
  drawBackground();
  drawHalo();
  drawBackBotanicals();
  drawSkull();
  drawEarth();
  drawRoots();
  drawFrontBotanicals();
  drawMothsAndPetals();
  drawSurfaceGrain();
}

function drawBackground() {
  const g = drawingContext.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, "#0d171b");
  g.addColorStop(0.48, "#192321");
  g.addColorStop(1, "#121816");
  drawingContext.fillStyle = g;
  noStroke();
  rect(0, 0, width, height);

  for (let i = 0; i < 1500; i++) {
    const x = random(width);
    const y = random(height);
    const a = map(y, 0, height, 25, 7);
    stroke(190, 194, 170, random(2, a));
    strokeWeight(random(0.5, 1.8));
    point(x, y);
  }

  noFill();
  for (let i = 0; i < 90; i++) {
    const y = random(250, 1550);
    stroke(118, 139, 125, random(2, 8));
    strokeWeight(random(1, 4));
    const x = random(-200, 1400);
    bezier(x, y, x + 180, y - 25, x + 360, y + 30, x + random(420, 850), y);
  }
}

function drawHalo() {
  push();
  translate(800, 735);

  noStroke();
  fill(173, 150, 102, 9);
  ellipse(0, 0, 1110, 1110);

  noFill();
  for (let j = 0; j < 4; j++) {
    stroke(190, 166, 112, 52 - j * 9);
    strokeWeight(j === 0 ? 2.2 : 1);
    beginShape();
    for (let i = 0; i <= 360; i++) {
      const a = i * TWO_PI / 360;
      const n = noise(cos(a) * 2 + j * 4, sin(a) * 2 + 8);
      const r = 548 + j * 14 + (n - 0.5) * 9;
      vertex(cos(a) * r, sin(a) * r);
    }
    endShape(CLOSE);
  }

  for (let i = 0; i < 650; i++) {
    const a = random(TWO_PI);
    const r = random(538, 600);
    stroke(210, 184, 126, random(8, 42));
    strokeWeight(random(0.5, 1.6));
    point(cos(a) * r, sin(a) * r);
  }
  pop();
}

