function drawCheekLines() {
  for (let m = 0; m < 2; m++) {
    push();
    if (m === 1) {
      translate(1600, 0);
      scale(-1, 1);
    }
    noFill();
    stroke(230, 214, 177, 100);
    strokeWeight(5);
    bezier(554, 958, 585, 1008, 655, 1028, 711, 1000);
    stroke(75, 78, 66, 100);
    strokeWeight(2);
    bezier(560, 1000, 600, 1060, 625, 1080, 635, 1145);
