function rootBranch(x, y, len, a, depth, w) {
  if (depth <= 0 || len < 5) return;

  const x2 = x + cos(a) * len + random(-12, 12);
  const y2 = y + sin(a) * len;
  stroke(165, 151, 111, map(depth, 0, 8, 18, 95));
  strokeWeight(w);
  noFill();
  bezier(
    x, y,
    x + cos(a - 0.2) * len * 0.35, y + sin(a - 0.2) * len * 0.35,
    x2 - cos(a) * len * 0.25, y2 - sin(a) * len * 0.25,
    x2, y2
  );

  rootBranch(x2, y2, len * random(0.65, 0.79), a + random(0.18, 0.48), depth - 1, w * 0.7);
  rootBranch(x2, y2, len * random(0.65, 0.79), a - random(0.18, 0.48), depth - 1, w * 0.7);

  if (depth > 4 && random() < 0.28) {
    rootBranch(x2, y2, len * 0.58, a + random(-0.15, 0.15), depth - 2, w * 0.55);
  }
}

