function stem(x0, y0, x1, y1, x2, y2, x3, y3, col, leafCount, leafSize) {
  noFill();
  stroke(col);
  strokeWeight(3);
  bezier(x0, y0, x1, y1, x2, y2, x3, y3);

  stroke(red(col), green(col), blue(col), alpha(col) * 0.45);
  strokeWeight(0.8);
  bezier(x0 + 4, y0, x1 + 4, y1, x2 + 4, y2, x3 + 4, y3);

  for (let i = 0; i < leafCount; i++) {
    const t = (i + 1) / (leafCount + 2);
    const x = bezierPoint(x0, x1, x2, x3, t);
    const y = bezierPoint(y0, y1, y2, y3, t);
    const tx = bezierTangent(x0, x1, x2, x3, t);
    const ty = bezierTangent(y0, y1, y2, y3, t);
    const a = atan2(ty, tx);
    const side = i % 2 === 0 ? -1 : 1;
    const s = leafSize * random(0.68, 1.08);
    leaf(x, y, a + side * random(0.72, 1.1), s, s * random(0.22, 0.31), col);
  }
}

function leaf(x, y, a, len, w, col) {
  push();
  translate(x, y);
  rotate(a);
  fill(red(col), green(col), blue(col), alpha(col) * 0.62);
  stroke(red(col), green(col), blue(col), alpha(col));
  strokeWeight(1.2);
  beginShape();
  vertex(0, 0);
  bezierVertex(len * 0.22, -w, len * 0.78, -w * 0.75, len, 0);
  bezierVertex(len * 0.72, w * 0.82, len * 0.2, w * 0.62, 0, 0);
  endShape(CLOSE);
  noFill();
  stroke(190, 187, 145, 65);
  line(2, 0, len * 0.82, 0);
  pop();
}

function poppy(x, y, s, rot, col) {
