    const ps = s * random(0.82, 1.1);
    fill(red(col) + random(-10, 10), green(col) + random(-8, 8),
         blue(col) + random(-8, 8), random(155, 215));
    stroke(62, 62, 51, 110);
    strokeWeight(1.2);
    beginShape();
    vertex(0, 0);
    bezierVertex(-ps * 0.4, -ps * 0.18, -ps * 0.72, -ps * 0.72, -ps * 0.15, -ps);
    bezierVertex(ps * 0.22, -ps * 1.12, ps * 0.72, -ps * 0.65, ps * 0.4, -ps * 0.2);
    bezierVertex(ps * 0.25, -ps * 0.04, ps * 0.1, 0, 0, 0);
    endShape(CLOSE);

    noFill();
    stroke(224, 205, 159, 40);
    bezier(0, -4, -ps * 0.08, -ps * 0.35, ps * 0.05, -ps * 0.65, 0, -ps * 0.85);
    pop();
  }

  noStroke();
  fill(32, 38, 32, 230);
  ellipse(0, 0, s * 0.38, s * 0.32);
  for (let i = 0; i < 18; i++) {
    const a = i * TWO_PI / 18;
    stroke(189, 158, 91, 150);
    strokeWeight(1);
    line(cos(a) * s * 0.12, sin(a) * s * 0.1,
         cos(a) * s * 0.25, sin(a) * s * 0.22);
    fill(197, 168, 99, 180);
    noStroke();
    ellipse(cos(a) * s * 0.25, sin(a) * s * 0.22, 3, 3);
  }
  pop();
}

