const WATER_Y = 1420;
const MOON_X = 990;
const MOON_Y = 535;
const MOON_R = 315;
let treeLayer;
let tips = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  drawBackground();
  drawMoon();
  drawWater();

  treeLayer = createGraphics(width, height);
  treeLayer.pixelDensity(1);
  treeLayer.clear();
  makeTree(treeLayer);

  push();
  translate(0, WATER_Y * 1.58);
  scale(1, -0.58);
  tint(255, 255, 255, 64);
  image(treeLayer, 0, 0);
  pop();
  noTint();

  disturbReflection();
  drawBank();

  paintLeaf(treeLayer, 862, 1090, 12, 1.08, color(126, 105, 67, 150));
  paintLeaf(treeLayer, 954, 1215, 18, 1.42, color(178, 144, 79, 225));
  paintLeaf(treeLayer, 1018, 1338, 10, 0.82, color(125, 111, 79, 135));
  paintLeaf(treeLayer, 1085, 1587, 20, 0.16, color(169, 137, 76, 220));
  image(treeLayer, 0, 0);

  drawRipples();
  drawGrain();
  drawVignette();
}

function drawBackground() {
  const top = color(7, 10, 19);
  const middle = color(27, 33, 41);
  const lower = color(10, 16, 23);

  for (let y = 0; y < height; y++) {
    let c;
    if (y < 1370) {
      let t = y / 1370;
      t = t * t * (3 - 2 * t);
      c = lerpColor(top, middle, t);
    } else {
      c = lerpColor(middle, lower, (y - 1370) / 630);
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 55; i++) {
    const x = random(-250, width + 250);
    const y = random(-100, 1390);
    const r = random(180, 590);
    fill(91, 101, 106, random(1, 4));
    ellipse(x, y, r * 2.2, r * 0.8);
  }

  for (let i = 0; i < 330; i++) {
    const x = random(width);
    const y = random(80, 1330);
    const a = random(5, 25);
    stroke(190, 194, 184, a);
    strokeWeight(random(0.5, 1.5));
    point(x, y);
  }
}

function drawMoon() {
  noStroke();
  for (let i = 26; i >= 1; i--) {
    fill(187, 193, 181, 1.6);
    circle(MOON_X, MOON_Y, MOON_R * 2 + i * 18);
  }

  const center = color(220, 215, 195);
  const edge = color(140, 149, 149);

  for (let r = MOON_R; r > 0; r -= 2) {
    const t = pow(r / MOON_R, 0.72);
    fill(lerpColor(center, edge, t));
    circle(MOON_X, MOON_Y, r * 2);
  }

  for (let i = 0; i < 95; i++) {
    const rad = random(24, 100);
    const rr = (MOON_R - rad - 5) * sqrt(random());
    const a = random(TWO_PI);
    const x = MOON_X + cos(a) * rr;
    const y = MOON_Y + sin(a) * rr;
    fill(45, 57, 61, random(2, 8));
    ellipse(x, y, rad * random(1.1, 2.1), rad * random(0.65, 1.3));
  }

  for (let i = 0; i < 8500; i++) {
    const a = random(TWO_PI);
    const rr = MOON_R * sqrt(random());
    const x = MOON_X + cos(a) * rr;
    const y = MOON_Y + sin(a) * rr;
    const n = noise(x * 0.009, y * 0.009);
    if (n > 0.4) {
      const s = random(1, 11);
      fill(48, 59, 61, random(2, 13));
      ellipse(x, y, s * 1.7, s);
    }
  }

  noFill();
  stroke(229, 222, 199, 32);
  strokeWeight(2);
  circle(MOON_X, MOON_Y, MOON_R * 2);
}

function drawWater() {
  const near = color(24, 33, 40);
  const far = color(5, 10, 16);

  for (let y = 1360; y < height; y++) {
    const t = (y - 1360) / (height - 1360);
    stroke(lerpColor(near, far, t));
    line(0, y, width, y);
  }

  for (let i = 0; i < 620; i++) {
    const y = random(WATER_Y, height);
    const x = random(-80, width);
    const len = random(12, 190) * (0.6 + (y - WATER_Y) / 900);
    stroke(105, 123, 127, random(2, 13));
    strokeWeight(random(0.5, 1.6));
    line(x, y, x + len, y + random(-1.2, 1.2));
  }

  for (let i = 0; i < 180; i++) {
    const y = random(WATER_Y + 12, height);
    const spread = 35 + (y - WATER_Y) * 0.19;
    const x = randomGaussian(MOON_X, spread);
    const len = random(8, 90);
    stroke(185, 186, 166, random(2, 11));
    strokeWeight(random(0.6, 1.5));
    line(x - len / 2, y, x + len / 2, y);
  }
}

function makeTree(g) {
  g.strokeCap(ROUND);
  g.strokeJoin(ROUND);
  tips = [];

  g.noFill();
  for (let i = 0; i < 10; i++) {
    const dir = i % 2 === 0 ? -1 : 1;
    const reach = random(65, 225);
    g.stroke(14, 17, 18, 245);
    g.strokeWeight(random(7, 20));
    g.bezier(
      570, 1438,
      570 + dir * random(12, 45), 1424,
      570 + dir * reach * 0.55, random(1440, 1475),
      570 + dir * reach, random(1450, 1485)
    );
  }

  branch(g, 570, 1442, 285, -1.43, 8, 62);

  let candidates = tips.filter(t =>
    t.x > 45 && t.x < width - 45 && t.y > 350 && t.y < 1290
  );

  for (let i = 0; i < 18 && candidates.length > 0; i++) {
    const index = floor(random(candidates.length));
    const t = candidates.splice(index, 1)[0];
    const c = random() < 0.25
      ? color(155, 131, 82, 175)
      : color(100, 88, 63, 150);
    paintLeaf(g, t.x, t.y, random(9, 17), t.a + random(-1, 1), c);
  }
}

function branch(g, x, y, len, a, depth, w) {
  const ex = x + cos(a) * len;
  const ey = y + sin(a) * len;
  const nx = -sin(a);
  const ny = cos(a);
  const bend = random(-0.16, 0.16) * len;

  const c1x = x + cos(a) * len * 0.32 + nx * bend * 0.35;
  const c1y = y + sin(a) * len * 0.32 + ny * bend * 0.35;
  const c2x = x + cos(a) * len * 0.72 + nx * bend;
  const c2y = y + sin(a) * len * 0.72 + ny * bend;

  g.noFill();
  g.stroke(13 + depth * 0.65, 16 + depth * 0.55, 18 + depth * 0.45, 255);
  g.strokeWeight(w);
  g.bezier(x, y, c1x, c1y, c2x, c2y, ex, ey);

  if (w > 4) {
    const off = -w * 0.17;
    g.stroke(128, 119, 98, 20);
    g.strokeWeight(max(0.65, w * 0.075));
    g.bezier(
      x + nx * off, y + ny * off,
      c1x + nx * off, c1y + ny * off,
      c2x + nx * off, c2y + ny * off,
      ex + nx * off, ey + ny * off
    );
  }

  if (depth <= 0 || len < 7) {
    tips.push({ x: ex, y: ey, a: a });
    return;
  }

  branch(
    g, ex, ey,
    len * random(0.69, 0.79),
    a + random(-0.19, 0.19),
    depth - 1,
    w * random(0.64, 0.73)
  );

  if (depth > 2) {
    const side = random() < 0.5 ? -1 : 1;
    branch(
      g, ex, ey,
      len * random(0.47, 0.65),
      a + side * random(0.48, 0.92),
      depth - 1,
      w * random(0.42, 0.56)
    );
  }
}

function paintLeaf(g, x, y, s, a, c) {
  g.push();
  g.translate(x, y);
  g.rotate(a);
  g.noStroke();
  g.fill(c);
  g.beginShape();
  g.vertex(0, 0);
  g.bezierVertex(s * 0.25, -s * 0.52, s * 0.88, -s * 0.38, s, 0);
  g.bezierVertex(s * 0.76, s * 0.46, s * 0.22, s * 0.4, 0, 0);
  g.endShape(CLOSE);
  g.stroke(208, 179, 116, 65);
  g.strokeWeight(0.7);
  g.line(0, 0, s * 0.84, 0);
  g.pop();
}

function disturbReflection() {
  for (let i = 0; i < 410; i++) {
    const y = random(WATER_Y + 3, height);
    const x = random(-120, width);
    const len = random(30, 310);
    stroke(13, 22, 29, random(18, 72));
    strokeWeight(random(1, 4));
    line(x, y, x + len, y + random(-1, 1));
