function drawFigureParticles() {
  noStroke();

  for (let i = 0; i < 105000; i++) {
    let x = random(390, 1190);
    let y = random(345, 1755);

    if (!insideFigure(x, y)) continue;

    let n = noise(x * 0.007, y * 0.007);
    let upper = 1 - constrain((y - 350) / 1400, 0, 1);
    let right = constrain((x - 620) / 540, 0, 1);
    let dissolution = constrain(
      0.08 + 0.48 * upper + 0.26 * right + 0.40 * (n - 0.5),
      0.02,
      0.93
    );

    if (random() > dissolution) {
      let warmth = Math.exp(-dist(x, y, 835, 875) / 180);
      let a = random(24, 105) * (1 - dissolution * 0.35);
      let choice = random();

      if (random() < 0.025 + 0.14 * warmth) {
        fill(211, 169, 104, a * 1.1);
      } else if (choice < 0.28) {
        fill(59, 79, 91, a);
      } else if (choice < 0.68) {
        fill(105, 125, 132, a);
      } else {
        fill(157, 166, 160, a * 0.8);
      }

      let s = random(0.8, 3.4);
      if (random() < 0.035) s = random(3.5, 7);
      ellipse(x, y, s, s * random(0.65, 1.45));
    } else if (random() < 0.32) {
      let travel = random(25, 260) * (0.5 + dissolution);
      let px = x + travel * random(0.35, 0.95) + randomGaussian() * 12;
      let py = y - travel * random(0.2, 0.9) + randomGaussian() * 12;

      if (px > 0 && px < width && py > 0 && py < height) {
        let a = random(8, 38);
        if (random() < 0.04) {
          fill(203, 163, 103, a);
        } else {
          fill(119, 137, 139, a);
        }
        let s = random(0.6, 2.3);
        ellipse(px, py, s, s);
      }
    }
  }
}

