function insideFigure(x, y) {
  if (sq((x - 790) / 112) + sq((y - 505) / 148) <= 1) {
    return true;
  }

  if (y >= 610 && y <= 710) {
    let half = map(y, 610, 710, 62, 82);
    if (abs(x - 790) < half) return true;
  }

  if (y >= 650 && y <= 1270) {
    let cx = 790 + 10 * sin(y * 0.004);
    if (abs(x - cx) < torsoHalfWidth(y)) return true;
  }

  if (capsule(x, y, 555, 735, 500, 1020, 62)) return true;
  if (capsule(x, y, 500, 1020, 520, 1280, 43)) return true;
  if (capsule(x, y, 1025, 735, 1080, 1020, 62)) return true;
  if (capsule(x, y, 1080, 1020, 1060, 1270, 43)) return true;

  if (capsule(x, y, 710, 1190, 685, 1450, 94)) return true;
  if (capsule(x, y, 685, 1450, 650, 1715, 68)) return true;
  if (capsule(x, y, 870, 1190, 900, 1450, 94)) return true;
  if (capsule(x, y, 900, 1450, 940, 1715, 68)) return true;

  return false;
}

function torsoHalfWidth(y) {
  if (y < 760) return map(y, 650, 760, 210, 245);
  if (y < 960) return map(y, 760, 960, 245, 192);
  if (y < 1160) return map(y, 960, 1160, 192, 174);
  return map(y, 1160, 1270, 174, 205);
}

function capsule(x, y, x1, y1, x2, y2, r) {
  let dx = x2 - x1;
  let dy = y2 - y1;
  let t = constrain(
    ((x - x1) * dx + (y - y1) * dy) / (dx * dx + dy * dy),
    0,
    1
  );
  return dist(x, y, x1 + t * dx, y1 + t * dy) < r;
}

