  for (let i = 0; i < 42; i++) {
    const a = random(TWO_PI);
    const rr = sqrt(random()) * (R - 125);
    const x = cx + cos(a) * rr;
    const y = cy + sin(a) * rr;
    fill( sixty(), 70, 64, random(3, 10));
    ellipse(x, y, random(35, 155), random(25, 115));
  }

  for (let i = 0; i < 16500; i++) {
    const a = random(TWO_PI);
    const rr = sqrt(random()) * R;
    const x = cx + cos(a) * rr;
    const y = cy + sin(a) * rr;
    const n = noise(x * 0.011, y * 0.011);
    if (n < 0.5) {
      stroke(66, 72, 65, random(4, 16));
    } else {
      stroke(255, 245, 213, random(3, 11));
