function drawRisingAsh() {
  const darkAsh = color(99, 91, 72);
  const paleAsh = color(239, 216, 165);

  noStroke();
  for (let i = 0; i < 1250; i++) {
    const t = pow(random(), 1.38);
    const u = 1 - t;

    let x =
      u * u * u * 860 +
      3 * u * u * t * 1470 +
      3 * u * t * t * 1250 +
      t * t * t * 810;
    let y =
      u * u * u * 1450 +
      3 * u * u * t * 1170 +
      3 * u * t * t * 460 +
      t * t * t * 280;

    const spread = 18 + 155 * sin(PI * t);
    x += randomGaussian() * spread * 0.43;
    y += randomGaussian() * spread * 0.25;

    const c = lerpColor(darkAsh, paleAsh, constrain(t * 0.78 + random(0.28), 0, 1));
    const alpha = random(65, 185) * (1 - 0.42 * t);
    let s = random(2, 8.5) * (1 - 0.55 * t);
    if (random() < 0.08) s *= 1.8;

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(red(c), green(c), blue(c), alpha);

    if (random() < 0.72) {
      beginShape();
      vertex(0, -s);
      vertex(s * 0.46, -s * 0.08);
      vertex(s * 0.08, s);
      vertex(-s * 0.38, s * 0.18);
      endShape(CLOSE);
    } else {
      ellipse(0, 0, s * 0.75, s * 1.45);
    }
    pop();
  }

  for (let i = 0; i < 34; i++) {
    const t = random(0.18, 0.91);
    const u = 1 - t;
    const x =
      u * u * u * 860 +
      3 * u * u * t * 1470 +
      3 * u * t * t * 1250 +
      t * t * t * 810 +
      randomGaussian() * 75;
    const y =
      u * u * u * 1450 +
      3 * u * u * t * 1170 +
      3 * u * t * t * 460 +
      t * t * t * 280 +
      randomGaussian() * 45;
    const s = random(7, 15) * (1 - t * 0.35);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(229, 202, 148, random(70, 145));
    beginShape();
    vertex(0, -s);
    bezierVertex(s * 0.75, -s * 0.45, s * 0.65, s * 0.45, 0, s);
    bezierVertex(-s * 0.35, s * 0.4, -s * 0.35, -s * 0.45, 0, -s);
    endShape(CLOSE);
    pop();
  }
}

