  for (let i = 0; i < 42; i++) {
    const p = random(plants);
    const sx = random(585, 925);
    const sy = random(1720, 1755);
    noFill();
    stroke(184, 151, 94, random(15, 43));
    strokeWeight(random(0.8, 2));
    bezier(
      sx,
      sy,
      sx + random(-90, 90),
      sy + random(30, 100),
      p.x + random(-80, 80),
      p.y - random(10, 70),
      p.x,
      p.y
    );
  }

  plants.sort((a, b) => a.y - b.y);
  for (const p of plants) {
    drawFlower(p.x, p.y, p.h, p.lean, p.s, p.a);
  }
}

function drawFlower(x, y, h, lean, s, alpha) {
  noFill();
  stroke(126, 148, 119, alpha * 0.7);
  strokeWeight(random(1.2, 2.4));
  bezier(0 + x, y, x + lean * 0.1, y - h * 0.4, x + lean * 0.8, y - h * 0.72, x + lean, y - h);

  push();
  translate(x + lean * 0.36, y - h * 0.47);
  rotate(lean > 0 ? -0.65 : 0.65);
  noStroke();
  fill(91, 119, 91, alpha * 0.42);
  ellipse(0, 0, s * 2.1, s * 0.72);
  pop();

  push();
  translate(x + lean, y - h);
  rotate(random(TWO_PI));
  for (let k = 0; k < 5; k++) {
    push();
    rotate(k * TWO_PI / 5);
    noStroke();
    fill(229, 222, 194, alpha);
    ellipse(0, -s * 0.72, s * 0.82, s * 1.45);
    pop();
  }
  fill(197, 157, 87, alpha);
  circle(0, 0, s * 0.72);
  pop();
}

function drawForeground() {
  noFill();
  for (let i = 0; i < 180; i++) {
    const x = random(width);
    if (x > 390 && x < 1170 && random() < 0.67) continue;

    const y = random(1920, 2070);
    const h = random(55, 250);
    const lean = random(-75, 75);
    stroke(3, 10, 10, random(90, 205));
    strokeWeight(random(2, 6));
    bezier(x, y, x + lean * 0.1, y - h * 0.35, x + lean * 0.75, y - h * 0.72, x + lean, y - h);
  }
}

// 《一炷》：为亡者点的香。竖幅 1600×2000，宣纸底，静物 + 消散的烟。
// 渲染（粒子模拟）约需数秒钟，请耐心等待。
function setup() {
  randomSeed(1);
  noiseSeed(1);

  const W = 1600, H = 2000;
  createCanvas(W, H);
  noLoop();

  const PX = 800;      // 香的位置（中轴）
  const FIRE_Y = 1550; // 火点高度
  const ctx = drawingContext;

  // ---------- 1. 宣纸 ----------
  background(236, 231, 219);
  noStroke();
  for (let i = 0; i < 4200; i++) {
    const x = random(W), y = random(H), r = random(0.4, 1.7), c = random();
    if (c < 0.4)      fill(184, 173, 148, random(4, 10));
    else if (c < 0.8) fill(150, 140, 118, random(4, 10));
    else              fill(206, 196, 172, random(4, 10));
    circle(x, y, r);
  }
  stroke(150, 140, 118, 4);
  strokeWeight(0.6);
  for (let i = 0; i < 90; i++) { // 纸的短纤维
    const x = random(W), y = random(H);
    const a = random(TWO_PI), l = random(6, 26);
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }

  // ---------- 2. 桌沿 ----------
  const deskY = 1858;
  strokeCap(ROUND);
  for (let x = 140; x <= 1460; x += 9) {
    const n1 = noise(x * 0.01, 50), n2 = noise((x + 9) * 0.01, 50);
    stroke(110, 102, 86, 24 + n1 * 26);
    strokeWeight(1.5 + n1 * 2.2);
    line(x, deskY + (n1 - 0.5) * 3, x + 9, deskY + (n2 - 0.5) * 3);
  }
  noStroke();
  const deskG = ctx.createLinearGradient(0, deskY, 0, H);
  deskG.addColorStop(0, 'rgba(120,110,92,0)');
  deskG.addColorStop(1, 'rgba(108,98,80,0.16)');
  ctx.fillStyle = deskG;
  ctx.fillRect(0, deskY, W, H - deskY);

  // ---------- 3. 火光洒在纸上（烟之下） ----------
  const glowG = ctx.createRadialGradient(PX, FIRE_Y, 0, PX, FIRE_Y, 470);
  glowG.addColorStop(0, 'rgba(214,112,58,0.14)');
  glowG.addColorStop(0.45, 'rgba(214,112,58,0.05)');
  glowG.addColorStop(1, 'rgba(214,112,58,0)');
  ctx.fillStyle = glowG;
  ctx.fillRect(0, 0, W, H);

  // ---------- 4. 香灰堆 ----------
  const AY = 1752;
  noStroke();
  for (let i = 0; i < 3; i++) { // 投影
    fill(120, 110, 95, 7);
    ellipse(PX, 1802 + i * 9, 560 - i * 80, 60 - i * 12);
  }
  fill(163, 153, 133); ellipse(PX, AY, 330, 90);
  fill(150, 140, 121); ellipse(PX, AY - 4, 286, 72);
  for (let i = 0; i < 2600; i++) { // 灰的颗粒
    const u = random(TWO_PI), v = Math.pow(random(), 0.6);
    const px = PX + cos(u) * v * 163;
    const py = AY + sin(u) * v * 43 - v * 9;
    const d = random();
    if (d < 0.55)      fill(168, 158, 138, random(40, 90));
    else if (d < 0.85) fill(140, 130, 111, random(40, 80));
    else               fill(198, 190, 172, random(40, 80));
    circle(px, py, random(1, 2.6));
  }
  for (let i = 0; i < 300; i++) { // 香脚旁的新灰
    fill(206, 198, 180, random(60, 110));
    circle(PX + random(-42, 42), AY - 6 + random(-15, 13), random(0.8, 2));
  }

  // 燃尽的旧香脚
  function spent(x0, y0, len, tilt) {
    const x1 = x0 + sin(tilt) * len, y1 = y0 - cos(tilt) * len;
    stroke(88, 80, 70); strokeWeight(5); strokeCap(ROUND);
    line(x0, y0, x1, y1);
    stroke(122, 112, 98); strokeWeight(1.5);
    line(x0 - 1.2, y0, x1 - 1.2, y1);
    stroke(205, 197, 180); strokeWeight(5); // 顶端的白灰壳
    line(lerp(x0, x1, 0.9), lerp(y0, y1, 0.9), x1, y1);
    noStroke();
  }
  spent(738, 1748, 46, -0.08);
  spent(872, 1750, 33, 0.14);

  // 横躺的一根燃尽之香
  stroke(84, 76, 66); strokeWeight(5); strokeCap(ROUND);
  line(688, 1782, 744, 1788);
  line(744, 1788, 810, 1784);
  line(810, 1784, 852, 1786);
  stroke(60, 54, 46); strokeWeight(5.5);
  line(688, 1782, 700, 1783);
  stroke(116, 106, 92); strokeWeight(1.4);
  line(689, 1780, 744, 1786);
  line(744, 1786, 810, 1782);
  noStroke();
  fill(120, 110, 95, 12); ellipse(770, 1794, 180, 10);

  // ---------- 5. 燃着的这炷香 ----------
  const ITOP = 1558, IBOT = 1745;
  fill(213, 197, 158); rect(PX - 3.5, ITOP + 32, 3.5, IBOT - ITOP - 32); // 亮面
  fill(178, 158, 116); rect(PX, ITOP + 32, 3.5, IBOT - ITOP - 32);       // 暗面
  fill(58, 51, 42);    rect(PX - 3.5, ITOP, 7, 34);                       // 炭化段
  for (let i = 0; i < 46; i++) { // 炭段毛糙边缘
    fill(72, 63, 50, random(60, 150));
    circle(PX + random(-4.6, 4.6), ITOP + 2 + random(0, 32), random(1, 3));
  }
  for (let i = 0; i < 70; i++) { // 香身纹理
    fill(148, 128, 92, random(18, 60));
    circle(PX + random(-3, 3), random(ITOP + 42, IBOT - 6), random(0.5, 1.4));
  }
  for (let i = 0; i < 130; i++) { // 香与灰的交界
    const d = random();
    fill(d < 0.5 ? 202 : 162, d < 0.5 ? 194 : 152, d < 0.5 ? 176 : 132, random(60, 120));
    circle(PX + random(-17, 17), 1738 + random(0, 13), random(1, 2.4));
  }
  push(); // 掉落的一小截炭灰
  translate(PX + 14, 1728); rotate(0.4);
  fill(62, 55, 46); rect(-5, -2, 10, 4);
  pop();
  for (let i = 0; i < 8; i++) {
    fill(150, 142, 126, random(50, 100));
    circle(PX + 12 + random(-14, 14), 1726 + random(-6, 12), random(0.8, 1.8));
  }

  // ---------- 6. 烟 ----------
  const g = createGraphics(W, H);
  const TOP_H = 1000;
  // 烟的流场：上升越高，越散、越乱、越向右
  function fieldX(x, y, t) {
    const s = constrain((FIRE_Y - y) / TOP_H, 0, 1);
    const drift = (noise(x * 0.0016, y * 0.0013, 5.5) - 0.5) * 3.0 * s;
    const turb  = (noise(x * 0.03, y * 0.011, t) - 0.5) * 1.5 * (0.35 + s);
    return drift + turb + s * 0.4 - 0.07;
  }
  // 消散线：烟到达此处即归于无（随横向起伏，参差消散）
  function ceilingY(x) {
    return 430 + 340 * noise(x * 0.0018 + 7, 3.3);
  }

  // 6a. 丝缕（沿流场积分的细线，给烟以“缕”的质感）
  g.noFill();
  g.strokeCap(ROUND);
  for (let i = 0; i < 30; i++) {
    let x = PX + random(-13, 13);
    let y = FIRE_Y + 2 - random(0, 10);
    const wt = random(0.7, 1.5);
    const a0 = random(10, 22);
    let px = x, py = y, step = 0;
    while (y > 300 && step < 900) {
      x += fieldX(x, y, 3.0) * 1.7;
      y -= 2.4;
      step++;
      const s = constrain((FIRE_Y - y) / TOP_H, 0, 1);
      const fade = constrain((y - ceilingY(x)) / 260, 0, 1);
      if (fade <= 0.02) break;
      const a = a0 * pow(1 - s * 0.82, 1.4) * fade;
      if (a > 0.4) {
        g.stroke(72, 68, 60, a);
        g.strokeWeight(wt * (1 - s * 0.35) + 0.4);
        g.line(px, py, x, y);
      }
      px = x; py = y;
    }
  }

  // 6b. 雾状烟体（一次性粒子模拟，累积成烟）
  g.noStroke();
  const parts = [];
  const STEPS = 800, PER = 5;
  for (let step = 0; step < STEPS; step++) {
    const t = 1.2 + step * 0.004;
    for (let i = 0; i < PER; i++) {
      parts.push({
        x: PX + random(-2.6, 2.6),
        y: FIRE_Y + 4 + random(-4, 2),
        vy: -random(1.5, 2.3),
        age: 0,
        maxAge: 520 + random(320),
      });
    }
    for (let k = parts.length - 1; k >= 0; k--) {
      const p = parts[k];
      p.age++;
      if (p.age > p.maxAge) { parts.splice(k, 1); continue; }
      p.x += fieldX(p.x, p.y, t) + (random() - 0.5) * 0.32;
      p.y += p.vy;
      const s = constrain((FIRE_Y - p.y) / TOP_H, 0, 1);
      const ceil = ceilingY(p.x);
      const fade = constrain((p.y - ceil) / 240, 0, 1);
      if (fade <= 0.004 || p.y < ceil - 60) { parts.splice(k, 1); continue; }
      const lifeFade = constrain((p.maxAge - p.age) / 110, 0, 1);
      const birth = constrain(p.age / 25, 0, 1);
      const a = 11 * pow(1 - s * 0.8, 1.6) * fade * lifeFade * birth;
      if (a > 0.35) {
        const cr = lerp(70, 132, s);
        g.fill(cr, cr - 3, cr - 12, a);
        g.circle(p.x, p.y, (1.5 + s * 5.5) * 2);
      }
    }
  }
  image(g, 0, 0);

  // ---------- 7. 消散处的余雾 ----------
  for (let i = 0; i < 4; i++) {
    const mx = 940 + random(-170, 190);
    const my = 590 + random(-100, 130);
    const mr = random(110, 210);
    const mg = ctx.createRadialGradient(mx, my, 0, mx, my, mr);
    mg.addColorStop(0, 'rgba(142,136,122,0.05)');
    mg.addColorStop(1, 'rgba(142,136,122,0)');
    ctx.fillStyle = mg;
    ctx.fillRect(mx - mr, my - mr, mr * 2, mr * 2);
  }

  // ---------- 8. 火光透层（照穿烟与香） ----------
  const lt = ctx.createRadialGradient(PX, FIRE_Y, 0, PX, FIRE_Y, 115);
  lt.addColorStop(0, 'rgba(235,140,70,0.10)');
  lt.addColorStop(1, 'rgba(235,140,70,0)');
  ctx.fillStyle = lt;
  ctx.fillRect(PX - 120, FIRE_Y - 120, 240, 240);
  const lt2 = ctx.createRadialGradient(PX, FIRE_Y, 0, PX, FIRE_Y, 200);
  lt2.addColorStop(0, 'rgba(230,138,64,0.05)');
  lt2.addColorStop(1, 'rgba(230,138,64,0)');
  ctx.fillStyle = lt2;
  ctx.fillRect(PX - 200, FIRE_Y - 100, 400, 300);

  // ---------- 9. 火芯 ----------
  noStroke();
  fill(212, 92, 44, 235);   circle(PX, 1552, 21);
  fill(236, 132, 60, 240);  circle(PX, 1551, 13);
  fill(250, 180, 96, 245);  circle(PX, 1550, 8);
  fill(255, 226, 168, 252); ellipse(PX, 1548, 5, 10);
  // 随烟上扬的微火星
  fill(224, 106, 52, 190); circle(PX + 6, 1508, 4.5);
  fill(228, 122, 66, 150); circle(PX - 4, 1480, 3.2);
  fill(230, 130, 74, 110); circle(PX + 12, 1532, 2.8);

  // ---------- 10. 散尽前最后的浮尘 ----------
  for (let i = 0; i < 70; i++) {
    const x = PX + random(-260, 380);
    const y = ceilingY(x) - random(15, 230);
    if (y > 80) {
      fill(112, 106, 96, random(6, 18));
      circle(x, y, random(0.8, 1.8));
    }
  }

  // ---------- 11. 暗角 ----------
  const vg = ctx.createRadialGradient(W / 2, H / 2, 520, W / 2, H / 2, 1380);
  vg.addColorStop(0, 'rgba(108,98,78,0)');
  vg.addColorStop(1, 'rgba(108,98,78,0.10)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  const W = 1600, H = 2000;
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  const HX = 830;                     // 人形水平中心
  const heart = { x: 812, y: 1580 };  // 心口
  const cluster = { x: 980, y: 345 }; // 升成的新星团
  const ctx = drawingContext;

  // 高斯随机
  const ga = () => {
    let u = 0, v = 0;
    while (u === 0) u = random();
    while (v === 0) v = random();
    return sqrt(-2 * log(u)) * cos(TAU * v);
  };

  // 地面：noise 起伏，并在人所在处贴合坐姿
  const groundRaw = x => 1712 + 110 * (noise(x * 0.0016 + 7) - 0.5)
                              + 44 * (noise(x * 0.005 + 3) - 0.5);
  const gAt = groundRaw(HX);
  const groundY = x => groundRaw(x) + (1690 - gAt) * exp(-((x - HX) * (x - HX)) / (2 * 420 * 420));
  const hillY = x => groundY(x) - 80 - 48 * noise(x * 0.0009 + 11);

  // Catmull-Rom 采样
  function catmull(pts, t) {
    const n = pts.length - 1;
    let f = t * n, i = floor(f), u = f - i;
    if (i >= n) { i = n - 1; u = 1; }
    const p0 = pts[max(i - 1, 0)], p1 = pts[i],
          p2 = pts[min(i + 1, n)], p3 = pts[min(i + 2, n)];
    const u2 = u * u, u3 = u2 * u;
    return {
      x: 0.5 * (2 * p1.x + (-p0.x + p2.x) * u + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * u2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * u3),
      y: 0.5 * (2 * p1.y + (-p0.y + p2.y) * u + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * u2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * u3)
    };
  }

  // ---------- 1. 夜空 ----------
  const sky = ctx.createLinearGradient(0, 0, 0, H);
  sky.addColorStop(0.00, '#04060d');
  sky.addColorStop(0.45, '#0a1322');
  sky.addColorStop(0.80, '#18233a');
  sky.addColorStop(1.00, '#080c16');
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, W, H);

  // ---------- 2. 远丘 ----------
  blendMode(BLEND);
  noStroke();
  fill(17, 25, 43);
  beginShape();
  vertex(-20, H + 20);
  for (let x = -20; x <= W + 20; x += 8) vertex(x, hillY(x));
  vertex(W + 20, H + 20);
  endShape(CLOSE);

  // ---------- 3. 天光（加色混合） ----------
  blendMode(ADD);

  // 地平线余温
  for (let i = 0; i < 34; i++) {
    fill(232, 192, 150, 3 + random() * 4);
    ellipse(260 + random() * 1080, 1605 + random() * 45,
            280 + random() * 380, 24 + random() * 36);
  }

  // 微光雾带
  const f0 = { x: 1240, y: 120 }, f1 = { x: 600, y: 1560 };
  let dxn = -(f1.y - f0.y), dyn = f1.x - f0.x;
  const dl = sqrt(dxn * dxn + dyn * dyn);
  dxn /= dl; dyn /= dl;
  for (let i = 0; i < 520; i++) {
    const t = random();
    const off = ga() * 170;
    const px = lerp(f0.x, f1.x, t) + dxn * off;
    const py = lerp(f0.y, f1.y, t) + dyn * off;
    const fall = 1 - constrain(abs(off) / 420, 0, 1);
    const warm = noise(t * 5 + 2);
    fill(lerp(255, 150, warm), lerp(236, 178, warm), lerp(200, 218, warm),
         2.5 + random() * 6.5 * fall);
    ellipse(px, py, 25 + random() * 55, 18 + random() * 40);
  }
  for (let i = 0; i < 420; i++) {
    const t = random();
    const off = ga() * 130;
    const px = lerp(f0.x, f1.x, t) + dxn * off;
    const py = lerp(f0.y, f1.y, t) + dyn * off;
    fill(250, 232, 205, 5 + random() * 13);
    ellipse(px, py, 2 + random() * 5, 2 + random() * 5);
  }

  // 疏星
  for (let i = 0; i < 720; i++) {
    const y = pow(random(), 1.6) * 1460 + 40;
    const x = random() * W;
    const r0 = 0.5 + random() * 1.4;
    const al = 45 + random() * 205;
    if (random() < 0.15) fill(255, 236, 206, al);
    else fill(233, 238, 252, al);
    ellipse(x, y, r0, r0);
  }
  for (let i = 0; i < 18; i++) {
    const y = pow(random(), 1.6) * 1300 + 60;
    const x = random() * W;
    const s = 6 + random() * 9;
    fill(255, 250, 240, 255);
    ellipse(x, y, 2, 2);
    stroke(255, 248, 230, 95);
    strokeWeight(0.9);
    line(x - s, y, x + s, y);
    line(x, y - s, x, y + s);
    noStroke();
  }

  // 星团：人升成的新星
  for (let i = 0; i < 26; i++) {
    const px = cluster.x + ga() * 135;
    const py = cluster.y + ga() * 115;
    const r0 = 1.4 + random() * 1.2;
    fill(255, 236, 196, 26);
    ellipse(px, py, r0 * 4.5, r0 * 4.5);
    fill(255, 244, 222, 215 + random() * 40);
    ellipse(px, py, r0, r0);
    if (random() < 0.3) {
      const s = 5 + random() * 7;
      stroke(255, 238, 200, 80);
      strokeWeight(0.8);
      line(px - s, py, px + s, py);
      line(px, py - s, px, py + s);
      noStroke();
    }
  }

  // ---------- 4. 近地 ----------
  blendMode(BLEND);
  noStroke();
  fill(8, 12, 22);
  beginShape();
  vertex(-20, H + 20);
  for (let x = -20; x <= W + 20; x += 8) vertex(x, groundY(x));
  vertex(W + 20, H + 20);
  endShape(CLOSE);
  for (let i = 0; i < 900; i++) {
    const x = random() * W;
    const y = groundY(x) + random() * (H - groundY(x));
    fill(28, 38, 58, 8 + random() * 22);
    ellipse(x, y, 1 + random() * 2, 1 + random() * 2);
  }

  // ---------- 5. 归还于土的光 ----------
  blendMode(ADD);

  // 脚边光尘
  for (let i = 0; i < 600; i++) {
    const x = constrain(HX + ga() * 230, 150, 1480);
    const y = groundY(x) + 2 + random() * 15;
    const bri = exp(-((x - HX) * (x - HX)) / (2 * 280 * 280));
    fill(244, 208, 150, (8 + random() * 50) * (0.35 + 0.65 * bri));
    ellipse(x, y, 0.5 + random() * 1.4, 0.5 + random() * 1.4);
  }
  // 落地的光种
  for (let i = 0; i < 7; i++) {
    const px = constrain(HX + ga() * 190, 220, 1400);
    const py = groundY(px) + 3 + random() * 8;
    fill(255, 236, 196, 30);
    ellipse(px, py, 16, 16);
    fill(255, 244, 222, 230);
    ellipse(px, py, 2.6, 2.6);
  }
  // 地缘微光
  strokeWeight(1.5);
  for (let x = 150; x <= 1450; x += 5) {
    const y = groundY(x);
    const b = 26 + 95 * exp(-((x - HX) * (x - HX)) / (2 * 200 * 200));
    stroke(242, 204, 148, b);
    point(x, y);
  }
  noStroke();
  // 下沉的光
  for (let i = 0; i < 240; i++) {
    const x0 = constrain(830 + ga() * 110, 640, 1000);
    const y0 = 1590 + random() * 70;
    const gy = groundY(x0);
    const t = random();
    const px = x0 + ga() * 8 * t + 26 * t * noise(t * 3 + x0 * 0.01);
    const py = lerp(y0, gy + 3, t);
    fill(226, 190, 140, 90 * (1 - 0.6 * t));
    ellipse(px, py, 0.8 + random() * 1.3, 0.8 + random() * 1.3);
  }

  // ---------- 6. 上升的光流 ----------
  const flows = [
    { pts: [{x:852,y:1494},{x:925,y:1350},{x:1005,y:1160},{x:1065,y:940},{x:1040,y:700},{x:985,y:520},{x:980,y:385}], n: 720, a: 215, seed: 3.1 },
    { pts: [{x:812,y:1580},{x:778,y:1460},{x:716,y:1310},{x:688,y:1120},{x:700,y:910},{x:765,y:670},{x:890,y:480},{x:968,y:395}], n: 780, a: 220, seed: 7.7 },
    { pts: [{x:795,y:1328},{x:768,y:1190},{x:758,y:1030},{x:790,y:860},{x:865,y:650},{x:935,y:470}], n: 430, a: 160, seed: 12.3 }
  ];
  for (const f of flows) {
    const s0 = f.pts[0];
    for (let i = 0; i < 150; i++) {
      fill(255, 242, 214, 90 + random() * 160);
      ellipse(s0.x + ga() * 20, s0.y + ga() * 20, 0.9 + random() * 1.8, 0.9 + random() * 1.8);
    }
    for (let i = 0; i < f.n; i++) {
      const t = random();
      const p = catmull(f.pts, t);
      const q = catmull(f.pts, min(t + 0.02, 1));
      let tx = q.x - p.x, ty = q.y - p.y;
      const L = sqrt(tx * tx + ty * ty) || 1;
      tx /= L; ty /= L;
      const nx = -ty, ny = tx;
      let amp = 16 + 190 * t * t;
      let sgn = (noise(t * 4.5 + f.seed) - 0.5) * 2;
      let burst = false;
      if (random() < 0.12) { burst = true; amp *= 2.6; sgn = (random() < 0.5 ? -1 : 1) * (0.4 + random()); }
      let px = p.x + nx * sgn * amp + (random() - 0.5) * 8;
      let py = p.y + ny * sgn * amp + (random() - 0.5) * 8;
      if (t > 0.85) {
        const k = (t - 0.85) / 0.15;
        px = lerp(px, cluster.x + ga() * 95, k);
        py = lerp(py, cluster.y + ga() * 95, k);
      }
      const al = (f.a * pow(1 - t, 1.25) + 16) * (burst ? 0.55 : 1);
      const cw = random();
      fill(255, lerp(212, 246, cw), lerp(137, 228, cw), al);
      const r0 = 0.8 + random() * 1.7 * (1 - 0.4 * t);
      ellipse(px, py, r0, r0);
    }
  }

  // ---------- 7. 由光尘聚成的人 ----------
  const disks = [];
  const addDisk = (x, y, r) => disks.push({ x, y, r });
  addDisk(830, 1672, 54);                                  // 骨盆
  { // 躯干（弓背曲线）
    const A = { x: 830, y: 1672 }, C = { x: 860, y: 1568 }, B = { x: 812, y: 1476 };
    for (let i = 1; i <= 12; i++) {
      const t = i / 12, u = 1 - t;
      addDisk(u * u * A.x + 2 * u * t * C.x + t * t * B.x,
              u * u * A.y + 2 * u * t * C.y + t * t * B.y,
              lerp(52, 34, t));
    }
  }
  addDisk(808, 1442, 20);                                  // 颈
  addDisk(796, 1378, 56);                                  // 头
  addDisk(786, 1394, 44);                                  // 面部
  addDisk(806, 1356, 46);                                  // 头顶后侧
  for (let i = 0; i <= 7; i++) {                           // 大腿（蜷起）
    const t = i / 7;
    addDisk(lerp(830, 706, t), lerp(1672, 1632, t), lerp(36, 26, t));
  }
  for (let i = 1; i <= 6; i++) {                           // 小腿
    const t = i / 6;
    addDisk(lerp(706, 768, t), lerp(1632, 1676, t), lerp(24, 15, t));
  }
  addDisk(796, 1684, 13);                                  // 脚
  for (let i = 0; i <= 4; i++) {                           // 上臂
    const t = i / 4;
    addDisk(lerp(812, 748, t), lerp(1476, 1562, t), lerp(21, 15, t));
  }
  for (let i = 1; i <= 4; i++) {                           // 前臂（环抱膝上）
    const t = i / 4;
    addDisk(lerp(748, 688, t), lerp(1562, 1624, t), lerp(15, 11, t));
  }
  addDisk(686, 1628, 12);                                  // 手

  for (const d of disks) {
    const n = max(10, round(d.r * d.r * 0.06));
    for (let i = 0; i < n; i++) {
      const a = TAU * random();
      const rr = d.r * sqrt(random());
      let px = d.x + cos(a) * rr;
      let py = d.y + sin(a) * rr;
      let edge = 1e9;
      for (const e of disks) {
        const dd = dist(px, py, e.x, e.y) / e.r;
        if (dd < edge) edge = dd;
      }
      const core = constrain(1 - edge, 0, 1);
      const h = constrain((1620 - py) / 340, 0, 1);
      const df = constrain((edge - 0.5) / 0.5, 0, 1) * h * h;   // 越靠上、越靠体缘，越消散
      px += (noise(px * 0.003, py * 0.003) - 0.5) * 2 * df * 150;
      py += -df * (50 + 140 * df) + (noise(px * 0.004 + 40) - 0.5) * 70 * df;
      const al = constrain((90 + 170 * core * core) * (1 - 0.45 * df), 0, 255);
      const cw = pow(core, 1.4);
      fill(lerp(224, 255, cw), lerp(178, 242, cw), lerp(112, 216, cw), al);
      const r0 = 0.8 + 1.7 * random() + core * 0.9;
      ellipse(px, py, r0, r0);
    }
  }

  // 头周呼吸般的浮尘
  for (let i = 0; i < 150; i++) {
    const a = TAU * random();
    const rr = 85 + random() * 165;
    const px = 796 + cos(a) * rr * 0.95;
    const py = 1378 + sin(a) * rr * 0.78 - random() * 100;
    fill(236, 212, 168, 10 + random() * 30);
    ellipse(px, py, 0.8 + random() * 1.7, 0.8 + random() * 1.7);
  }

  // 心口最后的光
  fill(255, 238, 208, 20); ellipse(heart.x, heart.y, 64, 64);
  fill(255, 242, 220, 60); ellipse(heart.x, heart.y, 22, 22);
  fill(255, 250, 238, 255); ellipse(heart.x, heart.y, 5, 5);

  // ---------- 8. 暗角 ----------
  blendMode(BLEND);
  ctx.save();
  const vg = ctx.createRadialGradient(800, 860, 480, 800, 860, 1580);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.55, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.5)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
  const lg = ctx.createLinearGradient(0, 1500, 0, H);
  lg.addColorStop(0, 'rgba(0,0,0,0)');
  lg.addColorStop(1, 'rgba(0,0,0,0.35)');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 1500, W, H - 1500);
  ctx.restore();
}

function draw() {}

randomSeed(1);
noiseSeed(1);

const W = 1600, H = 2000, WL = 1650; // 画布与水面线

function setup() {
  createCanvas(W, H);
  noLoop();
  paint();
}

function draw() {}

function paint() {
  drawSky();                 // 夜空、残月、颗粒
  const pg = buildSubject(); // 枯茎 + 倒垂莲蓬 + 空中莲子
  drawReflection(pg);        // 水中倒影
  drawRipples();             // 涟漪
  drawWaterLines();          // 水面波纹、月光带
  drawFadeMask();            // 深处渐隐
  drawDeepShadows();         // 水下沉叶残影
  drawLeaf();                // 左侧倒伏残叶
  image(pg, 0, 0);           // 主体
  drawFallenSeed();          // 破水的莲子与远处漂浮的莲子
  drawDust();                // 浮尘
}

// ---------- 夜空与残月 ----------
function gradAt(st, y) {
  for (let i = 0; i < st.length - 1; i++) {
    if (y <= st[i + 1][0]) {
      const a = st[i], b = st[i + 1];
      let u = (y - a[0]) / (b[0] - a[0]);
      u = 0.5 - 0.5 * Math.cos(u * Math.PI);
      return [lerp(a[1], b[1], u), lerp(a[2], b[2], u), lerp(a[3], b[3], u)];
    }
  }
  const l = st[st.length - 1];
  return [l[1], l[2], l[3]];
}

function drawSky() {
  noStroke();
  const stops = [[0, 6, 8, 9], [550, 10, 13, 13], [1200, 12, 16, 15], [1650, 9, 13, 12], [2000, 2, 4, 4]];
  for (let y = 0; y < H; y += 4) {
    const c = gradAt(stops, y);
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 4.3);
  }
  // 极暗的残月与月晕
  for (let i = 0; i < 45; i++) { noStroke(); fill(52, 64, 58, 3); ellipse(260, 380, 330 - i * 3.4, 330 - i * 3.4); }
  for (let i = 0; i < 38; i++) { noStroke(); fill(7, 9, 10, 4); ellipse(306, 424, 150 - i * 3.2, 150 - i * 3.2); }
  for (let i = 0; i < 26; i++) { noStroke(); fill(20, 30, 26, 2); ellipse(260, 380, 1000 - i * 30, 820 - i * 24); }
  // 颗粒
  for (let i = 0; i < 12000; i++) {
    const x = random() * W, y = random() * H;
    if (random() < 0.5) fill(60, 74, 66, random() * 22);
    else fill(0, 0, 0, random() * 26);
    ellipse(x, y, 0.5 + random() * 1.4, 0.5 + random() * 1.4);
  }
}

// ---------- 主体图层 ----------
function buildSubject() {
  const g = createGraphics(W, H);
  g.noStroke();
  drawStem(g);
  drawPod(g);
  airSeeds(g);
  return g;
}

function drawStem(g) {
  const A = [1120, -80], C1 = [1075, 300], C2 = [1075, 540], B = [1082, 760];
  const C3 = [1000, 830], C4 = [912, 980], E = [868, 1260];
  const pts = [];
  const seg = (P0, P1, P2, P3, n) => {
    for (let i = (n === 150 ? 0 : 1); i <= n; i++) {
      const t = i / n;
      pts.push([bezierPoint(P0[0], P1[0], P2[0], P3[0], t),
                bezierPoint(P0[1], P1[1], P2[1], P3[1], t)]);
    }
  };
  seg(A, C1, C2, B, 150);
  seg(B, C3, C4, E, 120);
  const N = pts.length;
  const nrm = [];
  for (let i = 0; i < N; i++) {
    const a = pts[Math.max(0, i - 1)], b = pts[Math.min(N - 1, i + 1)];
    let dx = b[0] - a[0], dy = b[1] - a[1];
    const l = Math.hypot(dx, dy) || 1; dx /= l; dy /= l;
    nrm.push([-dy, dx]);
  }
  const foldS = 150 / (N - 1);
  g.noStroke();
  for (let i = 0; i < N; i++) {
    const s = i / (N - 1);
    let w = lerp(16.5, 8.5, s);
    w += 2.0 * Math.exp(-Math.pow((s - foldS) / 0.035, 2)); // 折点微鼓
    const p = pts[i], n = nrm[i];
    g.fill(24, 17, 10);
    g.ellipse(p[0] - n[0] * w * 0.32, p[1] - n[1] * w * 0.32, w * 0.95, w * 0.95);
    const nb = noise(p[0] * 0.01, p[1] * 0.008);
    const bs = 0.85 + 0.3 * (nb - 0.5);
    g.fill(52 * bs, 41 * bs, 27 * bs);
    g.ellipse(p[0], p[1], w * 1.15, w * 1.15);
    g.fill(88, 70, 46);
    g.ellipse(p[0] + n[0] * w * 0.30, p[1] + n[1] * w * 0.30, w * 0.82, w * 0.82);
    if (i % 2 === 0) { // 左缘冷光
      g.fill(126, 146, 134, 135);
      g.ellipse(p[0] + n[0] * w * 0.55, p[1] + n[1] * w * 0.55, 2, 2);
    }
  }
  // 残留的细刺
  for (let i = 8; i < N; i += 5 + floor(random() * 4)) {
    const p = pts[i], n = nrm[i];
    const side = random() < 0.5 ? 1 : -1;
    const w = lerp(16.5, 8.5, i / (N - 1));
    g.fill(175, 186, 175, 150);
    g.ellipse(p[0] + n[0] * w * 0.52 * side, p[1] + n[1] * w * 0.52 * side, 1.6, 1.6);
  }
  // 茎节横纹
  g.stroke(15, 10, 6, 70); g.strokeWeight(1);
  for (let i = 10; i < N; i += 9) {
    const p = pts[i], n = nrm[i];
    const w = lerp(16.5, 8.5, i / (N - 1));
    g.line(p[0] + n[0] * w * 0.6, p[1] + n[1] * w * 0.6, p[0] - n[0] * w * 0.62, p[1] - n[1] * w * 0.62);
  }
  g.noStroke();
  // 折痕受光
  for (let k = 0; k < 7; k++) { g.fill(150, 128, 96, 26 - k * 3); g.ellipse(1080, 758, 34 - k * 4, 34 - k * 4); }
  // 两个断裂的侧枝
  twig(g, 1081, 400, 1128, 432, 4.6);
  twig(g, 984, 886, 897, 952, 5.0);
}

function twig(g, x0, y0, x1, y1, w0) {
  const steps = 14;
  g.noStroke();
  for (let i = 0; i <= steps; i++) {
    const t = i / steps;
    const x = lerp(x0, x1, t) + Math.sin(t * 3.2) * 5;
    const y = lerp(y0, y1, t);
    const w = lerp(w0, 0.5, t);
    g.fill(46, 36, 23);
    g.ellipse(x, y, w * 2, w * 2);
  }
  g.fill(160, 140, 105, 130); // 断口发白
  g.ellipse(x1, y1, 3, 3);
}

function bellHalf(t) {
  const ks = [[0, 15], [0.22, 62], [0.55, 93], [0.85, 98], [1, 88]];
  for (let i = 0; i < ks.length - 1; i++) {
    if (t <= ks[i + 1][0]) {
      const a = ks[i], b = ks[i + 1];
      let u = (t - a[0]) / (b[0] - a[0]);
      u = 0.5 - 0.5 * Math.cos(u * Math.PI);
      return lerp(a[1], b[1], u);
    }
  }
  return 88;
}

function drawPod(g) {
  g.push();
  g.translate(868, 1260);
  g.rotate(0.09);
  const y0 = 24, y1 = 232;
  // 颈
  g.noStroke();
  for (let y = 0; y <= 26; y += 2) {
    const w = lerp(6, 16, y / 26);
    const sh = lerp(0.5, 0.66, y / 26);
    g.fill(56 * sh, 44 * sh, 29 * sh);
    g.ellipse(0, y, w * 2, 3.2);
  }
  // 钟形体：横向切片渐变
  g.rectMode(CENTER);
  const NX = 24;
  for (let y = y0; y <= y1; y += 3.2) {
    const t = (y - y0) / (y1 - y0);
    const wB = bellHalf(t);
    const dip = 13 * Math.exp(-Math.pow((t - 0.78) / 0.13, 2)); // 右侧干瘪凹陷
    const wL = wB, wR = wB - dip;
    const segW = (wL + wR) / (NX - 1);
    for (let i = 0; i < NX; i++) {
      const u = i / (NX - 1);
      const x = lerp(-wL, wR, u);
      let sh = lerp(1.0, 0.30, Math.pow(u, 0.9));
      sh *= lerp(1.06, 0.62, t);
      const n1 = noise(x * 0.045 + 31, y * 0.05 + 7);
      const n2 = noise(x * 0.25 + 80, y * 0.25 + 40);
      const m = 0.84 + 0.3 * (n1 - 0.5) + 0.12 * (n2 - 0.5);
      let rc = 58 * sh * m, gc = 45 * sh * m, bc = 29 * sh * m;
      if (t > 0.82) {
        const k = (t - 0.82) / 0.18;
        rc = lerp(rc, 92 * sh, k); gc = lerp(gc, 72 * sh, k); bc = lerp(bc, 44 * sh, k);
      }
      g.fill(rc, gc, bc);
      g.rect(x, y, segW * 1.5, 3.8);
    }
  }
  // 左缘冷光轮廓
  g.noFill(); g.stroke(122, 142, 132, 115); g.strokeWeight(2.2);
  g.beginShape();
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    g.vertex(-bellHalf(t) - 1.5, y0 + t * (y1 - y0));
  }
  g.endShape();
  // 右缘暗轮廓
  g.noFill(); g.stroke(8, 6, 4, 80); g.strokeWeight(2);
  g.beginShape();
  for (let i = 0; i <= 24; i++) {
    const t = i / 24;
    const dip = 13 * Math.exp(-Math.pow((t - 0.78) / 0.13, 2));
    g.vertex(bellHalf(t) - dip + 1.5, y0 + t * (y1 - y0));
  }
  g.endShape();
  // 枯斑
  g.noStroke();
  for (let i = 0; i < 16; i++) {
    const t = 0.12 + random() * 0.8;
    const u = (random() * 2 - 1) * 0.65;
    g.fill(14, 10, 6, 30 + random() * 50);
    g.ellipse(u * bellHalf(t), y0 + t * (y1 - y0), 3 + random() * 8, 3 + random() * 7);
  }
  // 朝下的孔面
  const FY = 246, FRX = 98, FRY = 32;
  g.noFill(); g.stroke(44, 34, 21); g.strokeWeight(13);
  g.ellipse(0, FY, (FRX + 10) * 2, (FRY + 8) * 2);
  g.noStroke();
  g.fill(86, 68, 42);
  g.ellipse(0, FY, FRX * 2, FRY * 2);
  g.fill(54, 41, 25, 175);
  g.ellipse(FRX * 0.42, FY + 4, FRX * 1.02, FRY * 1.02);
  g.fill(114, 94, 58, 125);
  g.ellipse(-FRX * 0.38, FY - 4, FRX * 0.74, FRY * 0.74);
  // 蜂窝孔：多数已空，四粒犹在
  hole(g, 0, FY, 9.4, true, 150);
  for (let k = 0; k < 6; k++) {
    const a = k / 6 * TWO_PI + 0.3;
    hole(g, Math.cos(a) * 32, FY + Math.sin(a) * 10.5, 8.1, (k === 0 || k === 3), 140);
  }
  for (let k = 0; k < 11; k++) {
    const a = k / 11 * TWO_PI + 0.15;
    hole(g, Math.cos(a) * 68, FY + Math.sin(a) * 22, 7.2, (k === 5), 130);
  }
  for (let i = 0; i < 6; i++) {
    g.fill(40, 30, 18, 35);
    g.ellipse(-70 + random() * 140, FY - 12 + random() * 24, 3 + random() * 5, 2 + random() * 3);
  }
  g.pop();
}

function hole(g, hx, hy, r, hasSeed, lit) {
  if (!hasSeed) {
    g.fill(13, 9, 6);
    g.ellipse(hx, hy, r * 2, r * 0.84);
    g.noFill();
    g.stroke(96, 76, 46, lit * 0.55);
    g.strokeWeight(1.3);
    g.arc(hx, hy, r * 2 - 1, r * 0.84 - 0.6, 0.2, Math.PI * 0.8);
    g.noStroke();
  } else {
    g.fill(18, 13, 8);
    g.ellipse(hx, hy, r * 1.95, r * 0.8);
    g.fill(110, 92, 56);
    g.ellipse(hx, hy, r * 1.6, r * 0.95);
    g.fill(205, 186, 132, 190);
    g.ellipse(hx - r * 0.4, hy - r * 0.28, r * 0.55, r * 0.3);
    g.fill(36, 27, 16, 150);
    g.ellipse(hx + r * 0.42, hy + r * 0.26, r * 0.7, r * 0.36);
  }
}

// ---------- 落下的莲子 ----------
function seedBall(g, x, y, r, trail) {
  if (trail) {
    g.stroke(150, 140, 110, 26);
    g.strokeWeight(1.6);
    g.line(x, y - r * 2.6, x, y - r * 1.15);
  }
  g.noStroke();
  g.fill(106, 90, 55);
  g.ellipse(x, y, r * 2, r * 2.25);
  g.noFill();
  g.stroke(28, 20, 11, 140);
  g.strokeWeight(r * 0.42);
  g.arc(x, y, r * 1.78, r * 2.0, 0.15, 1.35);
  g.noStroke();
  g.fill(205, 186, 132, 175);
  g.ellipse(x - r * 0.38, y - r * 0.5, r * 0.62, r * 0.42);
}

function airSeeds(g) {
  seedBall(g, 940, 1560, 12.5, true);
  seedBall(g, 825, 1600, 11, true);
  seedBall(g, 985, 1632, 9.5, false);
}

// ---------- 倒影 ----------
function drawReflection(pg) {
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.rect(0, WL, W, H - WL);
  drawingContext.clip();
  push();
  translate(0, WL * 1.45);
  scale(1, -0.45);
  tint(200, 215, 205, 58);
  image(pg, 0, 0);
  noTint();
  pop();
  drawingContext.restore();
}

// ---------- 水面 ----------
function ripple(cx, cy, n, a0) {
  noFill();
  for (let k = 0; k < n; k++) {
    const r = 22 + k * 40;
    stroke(150, 175, 162, a0 * (1 - k / n));
    strokeWeight(lerp(2.4, 0.8, k / max(1, n - 1)));
    ellipse(cx, cy, r * 2, r * 0.7);
  }
}

function drawRipples() {
  ripple(890, 1652, 5, 150); // 破水处
  ripple(360, 1712, 3, 45);  // 残叶旁
