function leafR(k) {
  let rr = 205 * (0.8 + noise(k * 0.22 + 7) * 0.25);
  if (k >= 14 && k <= 17) rr *= 0.45; // 破损缺口
  return rr;
}

function drawLeaf() {
  push();
  translate(360, 1708);
  const K = 42;
  noStroke();
  fill(28, 21, 14, 215);
  beginShape();
  for (let k = 0; k < K; k++) {
    const a = k / K * TWO_PI;
    vertex(Math.cos(a) * leafR(k), Math.sin(a) * leafR(k) * 0.30);
  }
  endShape(CLOSE);
  fill(15, 10, 7, 200);
  ellipse(14, 3, 190, 50);
  fill(10, 7, 5, 160);
  ellipse(14, 3, 120, 32);
  stroke(54, 41, 26, 90); strokeWeight(1.6);
  for (let k = 2; k < K; k += 5) {
    if (k >= 13 && k <= 18) continue;
    const a = k / K * TWO_PI;
    const rr = leafR(k) * 0.85;
    line(12, 2, 12 + Math.cos(a) * rr, 2 + Math.sin(a) * rr * 0.30);
  }
  noFill(); stroke(90, 106, 95, 60); strokeWeight(3);
  beginShape();
  for (let k = 21; k <= 31; k++) {
    const a = k / K * TWO_PI;
    const rr = leafR(k) + 4;
    vertex(Math.cos(a) * rr, Math.sin(a) * rr * 0.30);
  }
  endShape();
  noStroke(); fill(3, 5, 4, 110);
  ellipse(0, 52, 392, 84);
  pop();
}

