/* ---------- 枯树 ---------- */
function painterlyPath(pts, w0, w1, col, layers) {
  noFill();
  for (let L = 0; L < layers; L++) {
    let off = (L - (layers - 1) / 2) * max(1.3, w0 * 0.09);
    for (let i = 0; i < pts.length - 1; i++) {
      let t = (i + 1) / (pts.length - 1);
      let w = lerp(w0, w1, t) * (L === layers - 1 ? 1 : 0.68);
      strokeWeight(max(0.9, w));
      if (L === layers - 1) stroke(col[0], col[1], col[2], 232);
      else stroke(col[0], col[1], col[2], 60 + random(35));
      let jx = off * 0.5 + random(-1.6, 1.6), jy = random(-1.6, 1.6);
      line(pts[i].x + jx, pts[i].y + jy, pts[i + 1].x + jx, pts[i + 1].y + jy);
    }
  }
}
function drawTwig(pts, w0, w1) {
  noFill(); stroke(27, 21, 16, 205);
  for (let i = 0; i < pts.length - 1; i++) {
    let t = (i + 1) / (pts.length - 1);
    strokeWeight(max(0.7, lerp(w0, w1, t)));
    line(pts[i].x, pts[i].y, pts[i + 1].x, pts[i + 1].y);
  }
}
function snowOnBranch(pts) {
  noStroke();
  let n = 2 + int(random(3));
  for (let k = 0; k < n; k++) {
    let p = pts[int(random(pts.length))];
    fill(236, 233, 227, random(45, 110));
    circle(p.x + random(-2, 2), p.y + 2 + random(2), random(1.6, 3.6));
  }
}
function leafAt(x, y, a) {
  push(); translate(x, y); rotate(a + random(-0.6, 0.6));
  let s = 6 + random(9);
  let c = random() < 0.6 ? [122, 79, 46] : [87, 56, 31];
  noStroke(); fill(c[0], c[1], c[2], random(120, 215));
  beginShape();
  vertex(0, 0);
  quadraticVertex(s * 0.5, -s * 0.34, s, 0);
  quadraticVertex(s * 0.5, s * 0.34, 0, 0);
  endShape(CLOSE);
  pop();
}
function branch(x, y, ang, len, w, depth) {
  if (depth <= 0 || len < 5 || w < 0.6) return;
  let segs = max(3, int(len / 26));
  let pts = [{ x: x, y: y }];
  let a = ang, cx = x, cy = y;
  for (let i = 0; i < segs; i++) {
    a += (noise(cx * 0.0016 + 3.1, cy * 0.0016, depth * 2.3) - 0.5) * 0.55;
    a += (random() - 0.5) * 0.1;
    let step = len / segs;
    cx += cos(a) * step; cy += sin(a) * step;
    pts.push({ x: cx, y: cy });
  }
  drawTwig(pts, w, w * 0.55);
  if (w < 7 && random() < 0.42) snowOnBranch(pts);
  if (depth <= 2 && random() < 0.2) leafAt(cx, cy, a);
  let n = depth > 6 ? 2 : (random() < 0.7 ? 2 : 3);
  if (random() < 0.1) n = 1;
  for (let i = 0; i < n; i++) {
    let spread = lerp(0.95, 0.4, random());
    let na = a + (i - (n - 1) / 2) * 2 * spread;
    na += (random() - 0.5) * 0.22;
    na = lerp(na, -HALF_PI, 0.06);
    if (cx < 160) na += 0.3;
    if (cx > 1440) na -= 0.3;
    branch(cx, cy, na, len * lerp(0.83, 0.68, random()), w * 0.62, depth - 1);
  }
}
function whiskers(bx, by, n) {
  for (let k = 0; k < n; k++) {
    let a = -HALF_PI + (k - (n - 1) / 2) * 0.45 + random(-0.15, 0.15);
    let l = 14 + random(22);
    stroke(INK[0], INK[1], INK[2], 215); strokeWeight(1.6);
    line(bx, by, bx + cos(a) * l, by + sin(a) * l);
  }
}
function rootStroke(ax, ay, ang, len, w0) {
  let pts = [{ x: ax, y: ay }];
  let a = ang, x = ax, y = ay;
  for (let i = 0; i < 5; i++) {
    a += (noise(ax * 0.013 + i * 3.3, ay * 0.011) - 0.5) * 0.6;
    x += cos(a) * len / 5; y += sin(a) * len / 5;
    pts.push({ x: x, y: y });
  }
  painterlyPath(pts, w0, 2.5, INK, 1);
}
function tree() {
