// ---------- 工具 ----------
function lit(x, y) { // 统一光照因子：离光源越近越亮越暖
  return constrain(1 - dist(x, y, LX, LY) / 950, 0, 1);
}
function bez(x0, y0, x1, y1, x2, y2, x3, y3, n) { // 三次贝塞尔采样
  let pts = [];
  for (let i = 0; i <= n; i++) {
    let t = i / n, u = 1 - t;
    pts.push([
      u*u*u*x0 + 3*u*u*t*x1 + 3*u*t*t*x2 + t*t*t*x3,
      u*u*u*y0 + 3*u*u*t*y1 + 3*u*t*t*y2 + t*t*t*y3
    ]);
  }
  return pts;
}

// ---------- 背景 ----------
function paintBackground() {
  // 第一遍：大笔触，围绕光源的涡流
  for (let i = 0; i < 3200; i++) {
    let x = random(-60, W + 60), y = random(-60, H + 60);
    let ang = atan2(y - LY, x - LX) + HALF_PI + (noise(x * 0.0022, y * 0.0022) - 0.5) * 1.7;
    let len = random(50, 150);
    let l = lit(x, y);
    stroke(lerp(214, 40, pow(l, 1.4)), lerp(15, 10, l),
           6.5 + l * 15 + (noise(x * 0.004, y * 0.004) - 0.5) * 5, random(45, 80));
    strokeWeight(random(7, 16));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  // 第二遍：细笔触，增加密度
  for (let i = 0; i < 2800; i++) {
    let x = random(-40, W + 40), y = random(-40, H + 40);
    let ang = atan2(y - LY, x - LX) + HALF_PI + (noise(x * 0.003, y * 0.003, 7.7) - 0.5) * 2.2;
    let len = random(18, 60);
    let l = lit(x, y);
    stroke(lerp(212, 42, pow(l, 1.4)), lerp(14, 11, l),
           8 + l * 13 + random(-2, 3), random(30, 60));
    strokeWeight(random(2, 5));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  // 光晕：光源周围的微弱同心弧
  noFill();
  for (let i = 0; i < 620; i++) {
    let r = random(50, 640);
    let a0 = random(TWO_PI);
    let span = random(0.15, 0.55);
    stroke(40, 13, 13 + 15 * (1 - r / 640), random(26, 55));
    strokeWeight(random(7, 17));
    beginShape();
    for (let k = 0; k <= 5; k++) {
      let a = a0 + span * k / 5;
      vertex(LX + cos(a) * r, LY + sin(a) * r);
    }
    endShape();
  }
}

