// ---------- 次株：断茎与空壳残花 ----------
function paintDeadPlant() {
  let pts = bez(1248, 1985, 1252, 1700, 1210, 1350, 1186, 1085, 64);
  for (let i = 0; i < pts.length; i++) {
    let t = i / (pts.length - 1);
    let q = pts[i], d = pts[min(i + 1, pts.length - 1)];
    let ang = atan2(d[1] - q[1], d[0] - q[0]) + HALF_PI;
    let w = lerp(16, 9, t);
    let l = lit(q[0], q[1]) * 0.35;
    stroke(30, 24, 11 + l * 9 + random(-1.5, 1.5), 95);
    strokeWeight(w);
    line(q[0] - cos(ang) * w / 2, q[1] - sin(ang) * w / 2,
         q[0] + cos(ang) * w / 2, q[1] + sin(ang) * w / 2);
  }
  noFill();
  for (let i = 4; i < pts.length - 6; i += 5) { // 枯皱
    let q = pts[i], d2 = pts[i + 5];
    let a = atan2(d2[1] - q[1], d2[0] - q[0]) + HALF_PI;
    let off = (noise(i * 0.3, 5.5) - 0.5) * 10;
    stroke(28, 26, 7, 70);
    strokeWeight(1.8);
    line(q[0] + cos(a) * off, q[1] + sin(a) * off, d2[0] + cos(a) * off, d2[1] + sin(a) * off);
  }
  drawDeadHead(1150, 1042, 76, 63);
}

function drawDeadHead(cx, cy, rx, ry) {
  for (let i = 0; i < 16; i++) { // 枯苞片
    let a = i / 16 * TWO_PI + random(-0.12, 0.12);
    let rIn = rx * 0.95;
    let bx = cx + cos(a) * rIn, by = cy + sin(a) * rIn * (ry / rx);
    let ex = cx + cos(a) * (rIn + random(35, 70));
    let ey = cy + sin(a) * (rIn + random(35, 70)) * (ry / rx) - 8;
    let nx = cos(a + HALF_PI), ny = sin(a + HALF_PI);
    noStroke();
    fill(48, 20, 11, 92);
    beginShape();
    vertex(bx + nx * 16, by + ny * 16);
    quadraticVertex((bx + ex) / 2, (by + ey) / 2, ex, ey);
    quadraticVertex((bx + ex) / 2 - nx * 8, (by + ey) / 2 - ny * 8, bx - nx * 16, by - ny * 16);
    endShape(CLOSE);
  }
  noStroke();
  fill(24, 32, 10, 96); // 空壳盘底
  ellipse(cx, cy, rx * 2, ry * 2);
  drawSeeds(cx, cy, rx, ry, 320, rx * 0.78, 0.45, true); // 稀疏灰暗的残存种子
  for (let i = 0; i < 3; i++) { // 几片残瓣
    drawPetal(cx, cy, rx * 0.9, ry / rx, random(TWO_PI), random(38, 62), 16, 0.4, true);
  }
}

// ---------- 主茎 ----------
function paintStem() {
  let pts = bez(885, 1988, 918, 1500, 838, 780, 812, 520, 110);
  for (let i = 0; i < pts.length; i++) { // 横向笔触堆出茎身
    let t = i / (pts.length - 1);
    let q = pts[i], d = pts[min(i + 1, pts.length - 1)];
    let ang = atan2(d[1] - q[1], d[0] - q[0]) + HALF_PI;
    let w = lerp(46, 25, t) * (0.88 + noise(i * 0.09, 3.3) * 0.24);
    let l = lit(q[0], q[1]);
    stroke(lerp(102, 46, t), lerp(12, 36, t), 19 + l * 10 + noise(i * 0.13, 8.1) * 6, 93);
    strokeWeight(w);
    line(q[0] - cos(ang) * w / 2, q[1] - sin(ang) * w / 2,
         q[0] + cos(ang) * w / 2, q[1] + sin(ang) * w / 2);
  }
  noFill();
  for (let i = 0; i < pts.length - 9; i += 4) { // 纵向纤维
    let wseg = lerp(46, 25, i / (pts.length - 1));
    let off = (noise(i * 0.06, 9.9) - 0.5) * wseg * 0.8;
    let q = pts[i], d = pts[min(i + 7, pts.length - 1)];
    let a = atan2(d[1] - q[1], d[0] - q[0]) + HALF_PI;
    let l = lit(q[0], q[1]);
    stroke(lerp(95, 40, i / pts.length), 30, 10 + l * 7, 60);
    strokeWeight(2);
    line(q[0] + cos(a) * off, q[1] + sin(a) * off, d[0] + cos(a) * off, d[1] + sin(a) * off);
  }
  for (let i = 0; i < pts.length - 9; i += 3) { // 受光侧高光（光源在左）
    let wseg = lerp(46, 25, i / (pts.length - 1));
    let q = pts[i], d = pts[min(i + 6, pts.length - 1)];
    let a = atan2(d[1] - q[1], d[0] - q[0]) + HALF_PI;
    let off = -wseg * 0.26;
    let l = lit(q[0], q[1]);
    stroke(lerp(100, 50, i / pts.length), 20, 27 + l * 9, 45);
    strokeWeight(3);
    line(q[0] + cos(a) * off, q[1] + sin(a) * off, d[0] + cos(a) * off, d[1] + sin(a) * off);
  }
}

// ---------- 枯叶 ----------
function drawLeaves() {
  drawLeaf(866, 1088, 435, 1300, 640, 1120, 72, 11.1, 55, 40, 22, true);  // 左叶：半枯余绿
  drawLeaf(896, 1338, 1232, 1452, 1060, 1290, 52, 27.7, 38, 46, 17, false); // 右叶：焦褐近枯
}

function drawLeaf(bx, by, tipx, tipy, cx, cy, wMax, seedId, hC, sC, bC, hasGreen) {
  let N = 30;
  let mid = [], nrm = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N, u = 1 - t;
    mid.push([u * u * bx + 2 * u * t * cx + t * t * tipx, u * u * by + 2 * u * t * cy + t * t * tipy]);
  }
  for (let i = 0; i <= N; i++) {
    let a = (i == 0) ? 1 : i - 1;
    let b = (i == N) ? N - 1 : i + 1;
    let dx = mid[b][0] - mid[a][0], dy = mid[b][1] - mid[a][1];
    let L = max(0.0001, sqrt(dx * dx + dy * dy));
    nrm.push([-dy / L, dx / L]);
  }
  let wl = [], wr = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N;
    let w = wMax * pow(sin(min(1, t * 1.05) * PI), 0.55);
    w *= 0.72 + 0.28 * noise(t * 6, seedId);
    if (noise(t * 9, seedId + 31) > 0.63) w *= 0.22;   // 破损缺刻
    let asym = 0.3 + 0.4 * noise(t * 3.2, seedId + 60); // 干卷不对称
    wl.push(w * asym * 1.5);
    wr.push(w * (1 - asym) * 1.5);
  }
  let l = lit(mid[15][0], mid[15][1]);
  noStroke();
  fill(hC, sC, bC + l * 7, 96);
  beginShape();
  for (let i = 0; i <= N; i++) vertex(mid[i][0] + nrm[i][0] * wl[i], mid[i][1] + nrm[i][1] * wl[i]);
  for (let i = N; i >= 0; i--) vertex(mid[i][0] - nrm[i][0] * wr[i], mid[i][1] - nrm[i][1] * wr[i]);
  endShape(CLOSE);
  noFill();
  stroke(hC - 8, sC - 10, bC + 14 + l * 6, 75); // 主脉
  strokeWeight(3);
  beginShape();
  for (let i = 0; i <= N; i++) vertex(mid[i][0], mid[i][1]);
  endShape();
  stroke(hC - 5, sC - 8, bC + 8, 55); // 侧脉
  strokeWeight(1.4);
  for (let i = 4; i <= N - 3; i += 4) {
    for (let s = -1; s <= 1; s += 2) {
      let ww = (s < 0 ? wr[i] : wl[i]) * 0.75;
      line(mid[i][0], mid[i][1], mid[i][0] + nrm[i][0] * ww * s, mid[i][1] + nrm[i][1] * ww * s);
    }
  }
  if (hasGreen) { // 根部残绿
    noStroke();
    fill(95, 26, 20 + l * 6, 60);
    ellipse(mid[3][0], mid[3][1], wMax * 1.5, wMax * 0.8);
  }
  noStroke(); // 枯斑
  for (let k = 0; k < 6; k++) {
    let i = floor(random(6, N - 2));
    fill(22, 48, 10 + l * 5, random(35, 60));
    ellipse(mid[i][0] + (random() - 0.5) * wMax, mid[i][1] + (random() - 0.5) * wMax * 0.6,
            random(16, 42), random(8, 20));
  }
  noFill(); // 尖端锈枯
  stroke(30, 55, 14 + l * 6, 65);
  strokeWeight(9);
  beginShape();
  for (let i = floor(N * 0.68); i <= N; i++) vertex(mid[i][0], mid[i][1]);
  endShape();
  stroke(hC - 4, sC, bC + 20, 40); // 受光边
  strokeWeight(2);
  beginShape();
  for (let i = 2; i <= N - 2; i++)
    vertex(mid[i][0] - nrm[i][0] * wr[i] * 0.85, mid[i][1] - nrm[i][1] * wr[i] * 0.85);
  endShape();
}

// ---------- 主花头 ----------
function drawBackPetals() {
  for (let i = 0; i < 26; i++) { // 枯黄苞片
    drawBract(i / 26 * TWO_PI + random(-0.09, 0.09));
  }
  for (let i = 0; i < 22; i++) { // 后层花瓣（暗，含断瓣）
    let a = i / 22 * TWO_PI + random(-0.14, 0.14);
    let broken = (i % 6 == 3);
    let len = broken ? random(42, 62) : random(95, 175);
    drawPetal(HX, HY, DISC_RX * 0.9, 0.86, a, len, random(26, 34), 0.55, broken);
  }
}

function drawBract(a) {
  let rIn = DISC_RX * 0.97, sq = 0.86;
  let bx = HX + cos(a) * rIn, by = HY + sin(a) * rIn * sq;
  let len = random(64, 118);
  let ex = HX + cos(a) * (rIn + len), ey = HY + sin(a) * (rIn + len) * sq - 14;
  let nx = cos(a + HALF_PI), ny = sin(a + HALF_PI);
  let l = lit(bx, by);
  noStroke();
  fill(56 - l * 8, 33, 14 + l * 10 + random(0, 5), 96);
  beginShape();
  vertex(bx + nx * 23, by + ny * 23 * 0.86);
  quadraticVertex((bx + ex) / 2 + nx * 8, (by + ey) / 2 + ny * 8, ex + random(-9, 9), ey);
  quadraticVertex((bx + ex) / 2 - nx * 8, (by + ey) / 2 - ny * 8, bx - nx * 23, by - ny * 23 * 0.86);
  endShape(CLOSE);
}

function drawPetal(cx, cy, r0, sq, a, len, wMax, shade, broken) {
  let bx = cx + cos(a) * r0;
  let by = cy + sin(a) * r0 * sq;
  let droop = broken ? random(6, 18) : random(14, 55) + (sin(a) > 0 ? 26 : 4); // 垂坠
  let bend = (noise(a * 2.7, 4.4) - 0.5) * 1.1; // 枯卷弯折
  let na = a + bend * 0.55;
  let ex = bx + cos(na) * len;
  let ey = by + sin(na) * len * sq + droop;
  let mx = (bx + ex) / 2 + cos(a + HALF_PI) * bend * 68;
  let my = (by + ey) / 2 + sin(a + HALF_PI) * bend * 68 + droop * 0.3;
  let l = lit(bx, by);
  let tones = [[30, 62, 52], [23, 68, 40], [14, 62, 34], [45, 36, 48]];
  let tone = tones[floor(random(4))];
  let hC = tone[0] + l * 6;
  let sC = tone[1];
  let bC = tone[2] * shade + l * 9 + random(-3, 3);
  let N = 16;
  let Lp = [], Rp = [];
  for (let i = 0; i <= N; i++) {
    let t = i / N, u = 1 - t;
    let px = u * u * bx + 2 * u * t * mx + t * t * ex;
    let py = u * u * by + 2 * u * t * my + t * t * ey;
    let dx = 2 * u * (mx - bx) + 2 * t * (ex - mx);
    let dy = 2 * u * (my - by) + 2 * t * (ey - my);
    let dl = max(0.001, sqrt(dx * dx + dy * dy));
    let nx = -dy / dl, ny = dx / dl;
    let w = wMax * pow(sin(min(1, t * 1.12) * PI), 0.72);
    w *= 0.82 + 0.36 * noise(t * 5.5, a * 3.7);
    Lp.push([px + nx * w, py + ny * w]);
    Rp.push([px - nx * w, py - ny * w]);
  }
  noStroke();
  fill(hC, sC, bC, 96);
  beginShape();
  for (let p of Lp) vertex(p[0], p[1]);
  for (let i = N; i >= 0; i--) vertex(Rp[i][0], Rp[i][1]);
  endShape(CLOSE);
  fill(hC - 6, sC + 8, bC * 0.62, 78); // 根部暗
  beginShape();
  vertex(bx, by);
  vertex(Lp[3][0], Lp[3][1]);
  vertex((Lp[6][0] + Rp[6][0]) / 2, (Lp[6][1] + Rp[6][1]) / 2);
  vertex(Rp[3][0], Rp[3][1]);
  endShape(CLOSE);
  noFill(); // 纵纹
  stroke(hC, sC, bC - 12, 55);
  strokeWeight(1.6);
  for (let k = 0; k < 3; k++) {
    let f = k / 2;
    beginShape();
    for (let i = 3; i <= N - 2; i++)
      vertex(lerp(Rp[i][0], Lp[i][0], f), lerp(Rp[i][1], Lp[i][1], f));
    endShape();
  }
  stroke(hC + 4, sC - 8, bC + 12, 42); // 受光棱
  strokeWeight(1.8);
  beginShape();
  for (let i = 3; i <= N - 2; i++)
    vertex(lerp(Rp[i][0], Lp[i][0], 0.22), lerp(Rp[i][1], Lp[i][1], 0.22));
  endShape();
  if (random() < 0.5 && !broken) { // 枯焦尖
    noStroke();
    fill(hC - 10, sC + 10, bC * 0.55, 80);
    beginShape();
    vertex(Lp[N - 4][0], Lp[N - 4][1]);
    vertex(ex, ey);
    vertex(Rp[N - 4][0], Rp[N - 4][1]);
    endShape(CLOSE);
  }
}

function drawDisc() {
  noStroke();
  fill(20, 55, 8, 92); // 盘下前缘厚度
  ellipse(HX, HY + DISC_RY - 12, DISC_RX * 2 * 0.98, 56);
  for (let i = 0; i < 46; i++) { // 盘体层叠
    let k = 1 - i / 46;
    fill(24, 56, 13 + random(0, 7), 88);
    ellipse(HX + (noise(i, 2.2) - 0.5) * 16, HY + (noise(i, 5.5) - 0.5) * 12,
            DISC_RX * 2 * k * 1.02, DISC_RY * 2 * k * 1.02);
  }
  for (let i = 0; i < 420; i++) { // 盘缘枯萎管状花
    let a = random(TWO_PI);
    let r0 = DISC_RX * random(0.7, 0.96);
    let x0 = HX + cos(a) * r0, y0 = HY + sin(a) * r0 * 0.86;
    let l = lit(x0, y0);
    stroke(27 + random(0, 12), 60, 15 + l * 14 + random(0, 9), 82);
    strokeWeight(random(3, 7));
    let r1 = r0 + random(16, 52);
    line(x0, y0, HX + cos(a) * r1, HY + sin(a) * r1 * 0.86 + random(3));
  }
  drawSeeds(HX, HY, DISC_RX, DISC_RY, 830, DISC_RX * 0.78, 1, false);
  for (let i = 0; i < 40; i++) { // 盘左上缘受光亮笔
    let a = random(-PI * 0.8, -PI * 0.3);
    let r = DISC_RX * random(0.9, 0.98);
    let x = HX + cos(a) * r, y = HY + sin(a) * r * 0.86;
    stroke(35, 60, 34, 40);
    strokeWeight(random(4, 9));
    line(x, y, x + cos(a) * random(10, 26), y + sin(a) * random(10, 26) * 0.86);
  }
}

function drawSeeds(cx, cy, rx, ry, count, maxR, dim, sparse) {
  const GA = 137.50776 * PI / 180; // 黄金角
  let sq = ry / rx;
  for (let i = 1; i <= count; i++) {
    if (sparse && noise(i * 0.9, 41.3) < 0.45) continue;
    let r = maxR * sqrt(i / count);
    let a = i * GA;
    let x = cx + cos(a) * r + (noise(i * 0.7, 1.1) - 0.5) * 7;
    let y = cy + sin(a) * r * sq + (noise(i * 0.7, 6.6) - 0.5) * 7;
    let size = lerp(8.5, 14.5, r / maxR);
    let l = lit(x, y);
    let bBase = lerp(10, 24, r / maxR);
    push();
    translate(x, y);
    rotate(a + (noise(i, 3.3) - 0.5) * 0.5);
    noStroke();
    fill(27 + (1 - dim) * 6, 60 * dim + 6, (bBase + l * 18) * dim + 4, 96);
    ellipse(0, 0, size, size * 0.62);
    fill(35, 55 * dim + 8, (bBase + 15 + l * 12) * dim + 6, 62);
    ellipse(-size * 0.16, -size * 0.12, size * 0.42, size * 0.26);
    pop();
  }
}

function drawFrontPetals() { // 前层：下半圈垂坠的亮瓣
  for (let i = 0; i < 16; i++) {
    let a = PI * (0.1 + 0.8 * (i / 15)) + random(-0.1, 0.1);
    drawPetal(HX, HY, DISC_RX * 0.9, 0.86, a, random(130, 215), random(30, 38), 1, false);
  }
}

