function drawSeedShape(x, y, ang, s, br) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(26, 58, br + random(0, 6));
  beginShape();
  vertex(-s * 0.8, 0);
  quadraticVertex(-s * 0.3, -s * 0.62, s * 0.55, -s * 0.25);
  quadraticVertex(s, -s * 0.05, s, 0);
  quadraticVertex(s, s * 0.05, s * 0.55, s * 0.25);
  quadraticVertex(-s * 0.3, s * 0.62, -s * 0.8, 0);
  endShape(CLOSE);
  stroke(24, 60, br * 0.55, 70);
  strokeWeight(1.5);
  line(-s * 0.7, 0, s * 0.5, 0);
  line(-s * 0.4, -s * 0.18, s * 0.4, -s * 0.05);
  line(-s * 0.4, s * 0.18, s * 0.4, s * 0.05);
  noStroke();
  fill(35, 45, br + 18, 80);
  ellipse(-s * 0.25, -s * 0.2, s * 0.6, s * 0.22);
  pop();
}

function drawSprout() { // 根旁唯一的新绿
  let bx = 648, by = 1952;
  noStroke(); // 湿润土痕
  for (let i = 0; i < 18; i++) {
    fill(30, 24, 13, 45);
    ellipse(bx + random(-58, 58), by + random(-14, 8), random(24, 64), random(4, 10));
  }
  noFill(); // 嫩茎
  stroke(105, 45, 36, 95);
  strokeWeight(5);
  beginShape();
  curveVertex(bx, by); curveVertex(bx, by);
  curveVertex(bx - 5, by - 46);
  curveVertex(bx - 13, by - 88);
  curveVertex(bx - 14, by - 96); curveVertex(bx - 14, by - 96);
  endShape();
  drawCotyledon(bx - 14, by - 96, -2.55, 60, 22);
  drawCotyledon(bx - 14, by - 96, -0.6, 52, 19);
