}

function drawCotyledon(x, y, ang, len, w) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(102, 42, 40, 95);
  beginShape();
  vertex(0, 0);
  quadraticVertex(len * 0.5, -w, len, -w * 0.2);
  quadraticVertex(len * 0.5, w * 0.2, 0, 0);
  endShape(CLOSE);
  noFill();
  stroke(95, 40, 55, 90);
  strokeWeight(1.8);
  beginShape();
  vertex(2, -2);
  quadraticVertex(len * 0.5, -w * 0.95, len * 0.9, -w * 0.18);
  endShape();
  pop();
}

function drawShellHalf(x, y, ang) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(26, 50, 20, 95);
  beginShape();
  vertex(-11, 0);
  quadraticVertex(0, -7, 9, 0);
  quadraticVertex(0, 3, -11, 0);
  endShape(CLOSE);
  pop();
}

