function vignette() {
  for (let i = 0; i < 520; i++) {
    let side = random(4);
    let x, y;
    if (side < 1) { x = random(W); y = random(150); }
    else if (side < 2) { x = random(W); y = H - random(150); }
    else if (side < 3) { x = random(160); y = random(H); }
    else { x = W - random(160); y = random(H); }
    stroke(215, 24, 3, random(18, 42));
    strokeWeight(random(10, 26));
    line(x, y, x + random(60, 170), y + random(-14, 14));
