}

randomSeed(1);
noiseSeed(1);

const W = 1600, H = 2000;
let leafCols = [];
let terminals = [];

function setup() {
  createCanvas(W, H);
  noLoop();
  leafCols = [
    color(226, 148, 56),
    color(200, 98, 44),
    color(242, 182, 82),
    color(164, 76, 40),
    color(124, 64, 38)
  ];
}

function draw() {
  drawSky();
  drawStars();
  drawSun();
  drawBirds();
  drawHills();
  drawMist();
  drawGround();
  drawRoots();
  drawTree();
  drawTreeLeaves();
  drawFallingLeaves();
  drawMounds();
  drawLitter();
  grade();
}

function drawSky() {
  const stops = [
    [0.00, color(13, 15, 30)],
    [0.42, color(46, 42, 74)],
    [0.68, color(110, 72, 82)],
    [0.88, color(196, 118, 74)],
    [1.00, color(232, 152, 88)]
  ];
  noStroke();
  for (let y = 0; y <= 1660; y += 3) {
    let t = y / 1660;
    let c = stops[stops.length - 1][1];
    for (let i = 0; i < stops.length - 1; i++) {
      let t0 = stops[i][0], t1 = stops[i + 1][0];
      if (t >= t0 && t <= t1) {
        c = lerpColor(stops[i][1], stops[i + 1][1], (t - t0) / (t1 - t0));
        break;
      }
    }
    stroke(c);
    line(0, y, W, y);
  }
}

function drawStars() {
  noStroke();
  for (let i = 0; i < 110; i++) {
    let x = random(W), y = random(0, 520);
    if (x > 560 && x < 1100 && y > 330 && y < 870) continue;
    fill(230, 235, 255, random(30, 110));
    rect(x, y, random(1, 2.4), random(1, 2.4));
  }
}

function drawSun() {
  noStroke();
  for (let r = 380; r >= 130; r -= 8) {
    fill(240, 214, 170, map(r, 380, 130, 0, 55));
    circle(830, 600, r * 2);
  }
  fill(247, 233, 206);
  circle(830, 600, 270);
  fill(252, 242, 220, 200);
  circle(830, 600, 230);
}

function drawBirds() {
  stroke(210, 205, 225, 80);
  strokeWeight(3);
  noFill();
  for (let i = 0; i < 6; i++) {
    let bx = random(80, 520), by = random(140, 560), s = random(7, 15);
    arc(bx - s, by, s * 2, s * 1.1, PI, TWO_PI);
    arc(bx + s, by, s * 2, s * 1.1, PI, TWO_PI);
  }
}

function drawHills() {
  noStroke();
  fill(44, 38, 64, 220);
  beginShape();
  vertex(0, 1660);
  for (let x = 0; x <= W; x += 30) vertex(x, 1590 + noise(x * 0.0025, 9) * 60);
  vertex(W, 1660);
  endShape(CLOSE);
  fill(34, 30, 54);
  beginShape();
  vertex(0, 1660);
  for (let x = 0; x <= W; x += 30) vertex(x, 1630 + noise(x * 0.003, 21) * 40);
  vertex(W, 1660);
  endShape(CLOSE);
}

function drawMist() {
  noStroke();
  for (let i = 0; i < 9; i++) {
    fill(226, 196, 176, random(6, 14));
    ellipse(random(W), random(1580, 1650), random(420, 900), random(26, 58));
  }
}

function drawGround() {
  noStroke();
  fill(30, 25, 44);
  beginShape();
  vertex(0, H);
  vertex(0, 1660);
  for (let x = 0; x <= W; x += 20) vertex(x, 1655 + noise(x * 0.004, 3) * 26 - 13);
  vertex(W, 1660);
  vertex(W, H);
  endShape(CLOSE);
  for (let y = 1660; y <= H; y += 4) {
    stroke(8, 6, 16, map(y, 1660, H, 0, 70));
    line(0, y, W, y);
  }
}

function drawRoots() {
  stroke(8, 8, 12);
  strokeCap(ROUND);
  strokeWeight(18); line(800, 1662, 726, 1706);
  strokeWeight(13); line(800, 1662, 884, 1708);
  strokeWeight(10); line(800, 1662, 802, 1716);
  strokeWeight(8);  line(800, 1662, 668, 1700);
  strokeWeight(8);  line(800, 1662, 936, 1702);
}

function branchTree(x, y, ang, len, w, depth) {
  if (depth === 0 || len < 7) {
    terminals.push({ x: x, y: y });
    return;
  }
  let x2 = x + cos(ang) * len;
  let y2 = y + sin(ang) * len;
  strokeWeight(max(w, 0.8));
  line(x, y, x2, y2);
  let spread = random(0.30, 0.62);
  for (let i = -1; i <= 1; i += 2) {
    let na = ang + i * spread + random(-0.14, 0.14);
    branchTree(x2, y2, na, len * random(0.70, 0.80), w * random(0.62, 0.72), depth - 1);
  }
}

function drawTree() {
  terminals = [];
  stroke(9, 8, 13);
  strokeCap(ROUND);
  branchTree(800, 1668, -HALF_PI - 0.05, 250, 38, 11);
}

function drawLeaf(x, y, s, col, rot, streak) {
  if (streak) {
    stroke(red(col), green(col), blue(col), 46);
    strokeWeight(1.5);
    line(x + random(-4, 4), y - s * 1.8, x, y);
  }
  push();
  translate(x, y);
  rotate(rot);
  noStroke();
  fill(col);
  ellipse(0, 0, s, s * 0.42);
  stroke(red(col) * 0.55, green(col) * 0.55, blue(col) * 0.55, 160);
  strokeWeight(1);
  line(-s * 0.38, 0, s * 0.38, 0);
  pop();
}

function drawTreeLeaves() {
  for (let t of terminals) {
    if (random() < 0.075) {
      let n = 1 + floor(random(3));
      for (let k = 0; k < n; k++) {
        drawLeaf(t.x + random(-9, 9), t.y + random(-9, 9),
                 random(6, 11), random(leafCols), random(TWO_PI), false);
      }
    }
  }
}

function drawFallingLeaves() {
  for (let i = 0; i < 150; i++) {
    let x = random() < 0.65 ? random(250, 1350) : random(60, W - 60);
    let y = random(220, 1560);
    drawLeaf(x, y, random(9, 19), random(leafCols), random(TWO_PI), random() < 0.25);
  }
  for (let i = 0; i < 45; i++) {
    let a = random(TWO_PI), r = random(60, 420);
    drawLeaf(800 + cos(a) * r * 1.4, 1500 + sin(a) * r * 0.35 + random(60),
             random(8, 15), random(leafCols), random(TWO_PI), false);
  }
}

function drawMounds() {
  noStroke();
  for (let i = 0; i < 7; i++) {
    fill(lerpColor(random(leafCols), color(15, 10, 16), 0.35), 200);
    ellipse(800 + random(-220, 220), 1685 + random(-8, 40),
            random(140, 300), random(34, 64));
  }
}

function drawLitter() {
  for (let i = 0; i < 1000; i++) {
    let x = 800 + (random() + random() + random() - 1.5) / 1.5 * 720;
    let y = 1660 + noise(x * 0.008, 7) * 22 + random() * 330;
    if (y > 1995) y = random(1660, 1995);
    let c = lerpColor(random(leafCols), color(20, 14, 20), random(0.15, 0.45));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(c, random(180, 240));
    ellipse(0, 0, random(4, 11), random(2, 5));
    pop();
  }
}

function grade() {
  noStroke();
  fill(16, 20, 50, 14);
  rect(0, 0, W, H);
  for (let r = 760; r > 0; r -= 14) {
    fill(232, 140, 80, map(r, 760, 0, 0, 14));
    ellipse(830, 1650, r * 2, r * 1.1);
  }
  noStroke();
  for (let i = 0; i < 6500; i++) {
    let x = random(W), y = random(H), a = random(5, 16);
    if (random() < 0.5) fill(0, 0, 0, a);
    else fill(255, 255, 255, a);
    rect(x, y, random(1, 2.6), random(1, 2.6));
  }
  noFill();
  for (let r = 700; r <= 1300; r += 8) {
    stroke(4, 4, 10, map(r, 700, 1300, 0, 75));
    strokeWeight(9);
    ellipse(W / 2, H / 2, r * 2, r * 2);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function petalShape(x, y, ang, s, col) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, -s * 0.34);
  bezierVertex(s * 0.44, -s * 0.30, s * 0.56, s * 0.12, s * 0.26, s * 0.30);
  bezierVertex(s * 0.08, s * 0.44, -s * 0.14, s * 0.42, -s * 0.28, s * 0.16);
  bezierVertex(-s * 0.52, s * 0.02, -s * 0.46, -s * 0.24, 0, -s * 0.34);
  endShape(CLOSE);
  pop();
}

function drip(x, y, w, len, col) {
  noStroke();
  fill(col);
  rect(x - w / 2, y, w, len);
  ellipse(x, y + len, w, w * 0.9);
}

function leafAt(x, y, ang, len, col) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(col);
  beginShape();
  vertex(0, 0);
  bezierVertex(len * 0.35, -len * 0.30, len * 0.75, -len * 0.26, len, 0);
  bezierVertex(len * 0.75, len * 0.20, len * 0.30, len * 0.24, 0, 0);
  endShape(CLOSE);
  pop();
}

function flameLayer(x, yb, h, w, col) {
  noStroke();
  fill(col);
  beginShape();
  vertex(x - w / 2, yb);
  bezierVertex(x - w / 2 - 2, yb - h * 0.42, x - w * 0.16 + 6, yb - h * 0.74, x + 7, yb - h);
  bezierVertex(x + w * 0.24 + 7, yb - h * 0.68, x + w / 2, yb - h * 0.38, x + w / 2, yb);
  endShape(CLOSE);
}

function draw() {
  // background
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let t = y / height;
    fill(lerpColor(color(8, 10, 19), color(24, 18, 29), t));
    rect(0, y, width, 2);
  }

  // table
  for (let y = 1490; y < height; y += 2) {
    let t1 = constrain((y - 1490) / 90, 0, 1);
    let t2 = constrain((y - 1580) / (height - 1580), 0, 1);
    let c = lerpColor(color(24, 18, 29), color(58, 43, 38), t1);
    c = lerpColor(c, color(14, 11, 18), t2);
    fill(c);
    rect(0, y, width, 2);
  }

  // ambient glows
  blendMode(ADD);
  let gA = drawingContext.createRadialGradient(620, 905, 30, 620, 905, 800);
  gA.addColorStop(0, 'rgba(255,198,122,0.55)');
  gA.addColorStop(0.35, 'rgba(255,162,82,0.17)');
  gA.addColorStop(1, 'rgba(255,150,70,0)');
  drawingContext.fillStyle = gA;
  drawingContext.fillRect(0, 0, width, height);

  let gB = drawingContext.createRadialGradient(620, 905, 120, 620, 905, 1300);
  gB.addColorStop(0, 'rgba(255,170,90,0.13)');
  gB.addColorStop(1, 'rgba(255,150,70,0)');
  drawingContext.fillStyle = gB;
  drawingContext.fillRect(0, 0, width, height);

  push();
  translate(650, 1625);
  scale(1, 0.32);
  let gP = drawingContext.createRadialGradient(0, 0, 20, 0, 0, 560);
  gP.addColorStop(0, 'rgba(255,192,112,0.38)');
  gP.addColorStop(1, 'rgba(255,170,80,0)');
  drawingContext.fillStyle = gP;
  drawingContext.fillRect(-600, -600, 1200, 1200);
  pop();
  blendMode(BLEND);

  // shadows on table
  noStroke();
  fill(0, 0, 0, 95);
  ellipse(700, 1594, 230, 34);
  fill(0, 0, 0, 55);
  ellipse(1060, 1602, 270, 30);

  // candle reflection
  for (let y = 1566; y < 1860; y += 3) {
    let t = (y - 1566) / 294;
    let wob = noise(y * 0.045) * 16;
    fill(255, 190, 110, 30 * (1 - t));
    rect(570 + wob - 6, y, 100 - wob, 3);
  }

  // candle body
  let cx = 620, cw = 112, top = 985, bottom = 1566;
  for (let i = 0; i <= cw; i += 2) {
    let t = i / cw;
    let d = (t - 0.42) / 0.30;
    let b = exp(-d * d);
    fill(lerp(72, 240, b), lerp(58, 210, b), lerp(56, 178, b * 0.95));
    rect(cx - cw / 2 + i, top, 2.2, bottom - top);
  }
  fill(236, 210, 180);
  ellipse(cx, top, cw, 27);
  fill(168, 132, 106);
  ellipse(cx, top + 2, cw * 0.74, 17);
  fill(96, 74, 62);
  ellipse(cx, top + 3, cw * 0.42, 9);
  drip(cx - 40, top + 4, 16, 96, color(228, 200, 170));
  drip(cx + 34, top + 4, 13, 62, color(222, 194, 164));
  drip(cx + 6, top + 4, 11, 34, color(232, 206, 176));
  fill(226, 198, 168);
  ellipse(cx - cw / 2 + 5, top + 150, 12, 30);
  ellipse(cx + cw / 2 - 4, top + 215, 10, 24);

  // wick
  stroke(28, 22, 22);
  strokeWeight(4);
  line(cx + 1, top + 2, cx + 4, top - 36);
  noStroke();

  // flame
  flameLayer(cx + 4, top - 36, 108, 42, color(255, 138, 38, 165));
  flameLayer(cx + 4, top - 36, 80, 29, color(255, 204, 92, 215));
  flameLayer(cx + 5, top - 36, 54, 18, color(255, 247, 216, 245));
  fill(112, 152, 255, 95);
  ellipse(cx + 4, top - 42, 15, 10);

  blendMode(ADD);
  let gC = drawingContext.createRadialGradient(cx + 5, top - 80, 4, cx + 5, top - 80, 190);
  gC.addColorStop(0, 'rgba(255,240,200,0.75)');
  gC.addColorStop(0.4, 'rgba(255,190,110,0.25)');
  gC.addColorStop(1, 'rgba(255,170,90,0)');
  drawingContext.fillStyle = gC;
  drawingContext.fillRect(0, 0, width, height);
  blendMode(BLEND);

  // smoke
  noFill();
  for (let k = 0; k < 3; k++) {
    stroke(185, 185, 195, 30 - k * 8);
    strokeWeight(7 - k * 2);
    beginShape();
    for (let y = top - 150; y > 520; y -= 22) {
      vertex(cx + 8 + (noise(y * 0.012 + k * 9.7) - 0.5) * 130, y);
    }
    endShape();
  }
  noStroke();

  // flower stem
  noFill();
  stroke(66, 76, 52);
  strokeWeight(12);
  beginShape();
  vertex(1002, 1570);
  bezierVertex(1010, 1400, 1075, 1295, 1150, 1240);
  bezierVertex(1190, 1210, 1205, 1225, 1196, 1252);
  endShape();
  stroke(116, 126, 92);
  strokeWeight(4);
  beginShape();
  vertex(997, 1566);
  bezierVertex(1006, 1398, 1070, 1296, 1145, 1241);
  endShape();
  noStroke();

  leafAt(1052, 1372, PI - 0.55, 128, color(64, 76, 50));
  leafAt(1122, 1262, 0.62, 112, color(86, 96, 64));
  leafAt(1012, 1492, PI - 0.35, 96, color(58, 70, 46));

  // sepals
  push();
  translate(1196, 1288);
  fill(76, 90, 60);
  noStroke();
  for (let i = 0; i < 5; i++) {
    let a = -PI / 2 + (i - 2) * 0.5;
    push();
    translate(cos(a) * 46, sin(a) * 46);
    rotate(a + PI / 2);
    ellipse(0, 0, 12, 30);
    pop();
  }
  pop();

  // rose head, nodding
  push();
  translate(1196, 1288);
  rotate(0.45);
  for (let i = 0; i < 9; i++) {
    let a = (i / 9) * TWO_PI + 0.3;
    push();
    rotate(a);
    fill(138, 98, 120, 240);
    ellipse(36, 0, 54, 31);
    pop();
  }
  for (let i = 0; i < 7; i++) {
    let a = (i / 7) * TWO_PI + 0.85;
    push();
    rotate(a);
    fill(166, 124, 144, 245);
    ellipse(23, 0, 41, 25);
    pop();
  }
  for (let i = 0; i < 5; i++) {
    let a = (i / 5) * TWO_PI + 1.3;
    push();
    rotate(a);
    fill(192, 152, 166);
    ellipse(12, 0, 28, 17);
    pop();
  }
  noFill();
  stroke(108, 72, 92);
  strokeWeight(3);
  for (let r = 5; r < 17; r += 4) {
    arc(0, 0, r * 2, r * 2, 0.4, 0.4 + PI * 1.5);
  }
  pop();
  noStroke();

  // fallen petals
  fill(0, 0, 0, 70);
  ellipse(902, 1612, 48, 12);
  ellipse(1258, 1652, 44, 11);
  ellipse(1082, 1728, 40, 10);
  ellipse(762, 1668, 34, 9);
  petalShape(900, 1602, 0.8, 46, color(158, 116, 138));
  petalShape(1255, 1644, 2.2, 42, color(150, 108, 130));
  petalShape(1080, 1720, 5.0, 38, color(166, 124, 144));
  petalShape(760, 1660, 1.3, 32, color(146, 104, 126));

  // drifting petals
  petalShape(830, 1180, 0.9, 26, color(160, 118, 140, 200));
  petalShape(520, 1320, 2.4, 22, color(155, 112, 134, 185));
  petalShape(985, 985, 4.1, 20, color(165, 122, 142, 175));
  petalShape(705, 760, 1.8, 16, color(170, 128, 148, 160));
  petalShape(1120, 1080, 5.6, 18, color(158, 116, 136, 165));

  // moth
  push();
  translate(792, 848);
  rotate(-0.55);
  fill(205, 185, 150, 215);
  noStroke();
  ellipse(-15, -5, 32, 17);
  ellipse(15, -5, 32, 17);
  fill(188, 166, 132, 225);
  ellipse(-12, 9, 23, 12);
  ellipse(12, 9, 23, 12);
  fill(122, 102, 82);
  ellipse(0, 3, 9, 24);
  stroke(150, 130, 105);
  strokeWeight(1.5);
  line(0, -8, -8, -20);
  line(0, -8, 8, -20);
  pop();
  noStroke();

  // dust motes in the light
  for (let i = 0; i < 160; i++) {
    let a = random(TWO_PI);
    let r = random(40, 620);
    let x = 620 + cos(a) * r;
    let y = 905 + sin(a) * r * 0.9;
    fill(255, 224, 180, random(20, 85));
    ellipse(x, y, random(1, 3.2), random(1, 3.2));
  }

  // grain
  for (let i = 0; i < 10000; i++) {
    let g = random(255);
    fill(g, g, g, random(2, 7));
    rect(random(width), random(height), 1.4, 1.4);
  }

  // vignette
  let v = drawingContext.createRadialGradient(800, 980, 420, 800, 980, 1250);
  v.addColorStop(0, 'rgba(4,4,9,0)');
  v.addColorStop(0.7, 'rgba(4,4,9,0.28)');
  v.addColorStop(1, 'rgba(3,3,8,0.85)');
  drawingContext.fillStyle = v;
  drawingContext.fillRect(0, 0, width, height);
}

let STARS = [];
let PETALS = [];
let RIPPLES = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  for (let i = 0; i < 220; i++) {
    STARS.push({ x: random(width), y: random(0, 1230), r: random(0.6, 2.2), a: random(40, 200) });
  }

  let petalCols = [color(245, 234, 210), color(245, 234, 210), color(232, 180, 160), color(217, 164, 65)];
  for (let i = 0; i < 170; i++) {
    let t = pow(random(), 0.62);
    PETALS.push({
      x: lerp(545, 1065, t) + random(-1, 1) * (50 + t * 200),
      y: lerp(1395, 590, t) + random(-1, 1) * (40 + t * 110) - t * random(0, 170),
      s: random(3, 9) * (1 - t * 0.35),
      r: random(TWO_PI),
      c: random(petalCols),
      a: map(t, 0, 1, 195, 35)
    });
  }

  for (let i = 0; i < 160; i++) {
    RIPPLES.push({ x: random(width), y: random(1312, 1990), w: random(30, 160), a: random(5, 24) });
  }
}

function draw() {
  // sky gradient
  for (let y = 0; y < 1300; y += 2) {
    let t = y / 1300;
    stroke(lerpColor(color(13, 18, 44), color(5, 7, 16), t));
    line(0, y, width, y + 1);
  }

  // stars
  noStroke();
  for (let i = 0; i < STARS.length; i++) {
    let s = STARS[i];
    fill(235, 240, 255, s.a);
    circle(s.x, s.y, s.r * 2);
  }

  // moon glow
  for (let i = 9; i > 0; i--) {
    fill(242, 230, 200, 6);
    circle(1140, 470, 510 + i * 85);
  }
  // moon body
  fill(243, 233, 205);
  circle(1140, 470, 510);
  // craters
  fill(222, 210, 180, 55);
  circle(1052, 402, 95);
  circle(1232, 545, 125);
  circle(1118, 585, 62);
  circle(1205, 382, 48);
  noFill();
  stroke(243, 233, 205, 40);
  strokeWeight(2);
  circle(1140, 470, 528);
  noStroke();

  // distant mountains
  fill(16, 20, 38);
  beginShape();
  vertex(0, 1300);
  for (let x = 0; x <= width; x += 25) {
    vertex(x, 1300 - 40 - noise(x * 0.004, 7.3) * 150);
  }
  vertex(width, 1300);
  endShape(CLOSE);

  fill(9, 11, 22);
  beginShape();
  vertex(0, 1306);
  for (let x = 0; x <= width; x += 20) {
    vertex(x, 1306 - 10 - noise(x * 0.006, 2.1) * 90);
  }
  vertex(width, 1306);
  endShape(CLOSE);

  // water gradient
  for (let y = 1300; y < height; y += 2) {
    let t = (y - 1300) / 700;
    stroke(lerpColor(color(11, 15, 30), color(3, 4, 10), t));
    line(0, y, width, y + 1);
  }

  // ripples
  strokeWeight(2);
  for (let i = 0; i < RIPPLES.length; i++) {
    let r = RIPPLES[i];
    stroke(150, 170, 210, r.a);
    line(r.x, r.y, r.x + r.w, r.y);
  }

  // moon reflection on water
  strokeWeight(4);
  for (let y = 1315; y < 1985; y += 13) {
    let w = 24 + noise(y * 0.045, 3.3) * 130;
    let x = 1140 + (noise(y * 0.06, 9.1) - 0.5) * 130;
    let a = map(y, 1315, 1985, 95, 8);
    stroke(240, 226, 188, a);
    line(x - w / 2, y, x + w / 2, y);
  }

  // mist above horizon
  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(180, 195, 225, 6);
    ellipse(random(width), 1292 + random(-12, 12), random(400, 900), random(28, 58));
  }

  // petals rising from the boat toward the moon
  for (let i = 0; i < PETALS.length; i++) {
    let p = PETALS[i];
    push();
    translate(p.x, p.y);
    rotate(p.r);
    fill(red(p.c), green(p.c), blue(p.c), p.a);
    ellipse(0, 0, p.s * 1.9, p.s);
    pop();
  }

  // boat reflection
  fill(0, 0, 5, 95);
  ellipse(505, 1514, 270, 22);

  // lantern light reflection
  strokeWeight(3);
  for (let y = 1472; y < 1640; y += 10) {
    stroke(230, 190, 110, map(y, 1472, 1640, 60, 5));
    line(610 + random(-4, 4), y, 618 + random(-4, 4), y + 6);
  }

  // hull
  noStroke();
  fill(8, 9, 15);
  beginShape();
  vertex(378, 1436);
  bezierVertex(410, 1494, 560, 1502, 632, 1430);
  vertex(612, 1424);
  bezierVertex(545, 1460, 455, 1462, 398, 1428);
  endShape(CLOSE);

  // figure (seated, cloaked)
  fill(6, 7, 12);
  beginShape();
  vertex(505, 1392);
  bezierVertex(478, 1412, 476, 1438, 484, 1452);
  bezierVertex(500, 1461, 524, 1459, 532, 1450);
  bezierVertex(536, 1430, 528, 1408, 520, 1394);
  endShape(CLOSE);
  circle(511, 1384, 27);
  // conical hat
  beginShape();
  vertex(486, 1378);
  vertex(511, 1352);
  vertex(536, 1378);
  endShape(CLOSE);

  // punting pole
  stroke(6, 7, 12);
  strokeWeight(7);
  line(546, 1414, 622, 1548);

  // lantern at the bow
  noStroke();
  fill(255, 210, 120, 16);
  circle(618, 1416, 74);
  fill(255, 220, 140, 42);
  circle(618, 1416, 42);
  fill(255, 238, 185);
  circle(618, 1416, 18);

  // foreground reeds
  for (let i = 0; i < 9; i++) {
    let x0 = 30 + i * 28 + random(-10, 10);
    let tipX = x0 + random(-80, 80);
    let tipY = random(1660, 1815);
    stroke(4, 5, 10);
    strokeWeight(random(3, 7));
    noFill();
    curve(x0, 2010, x0, 1905, tipX + random(-30, 30), tipY + 90, tipX, tipY);
    noStroke();
    fill(4, 5, 10);
    ellipse(tipX, tipY, 10, 26, random(-0.4, 0.4));
  }
  for (let i = 0; i < 8; i++) {
    let x0 = 1570 - i * 27 + random(-10, 10);
    let tipX = x0 + random(-70, 70);
    let tipY = random(1690, 1850);
    stroke(4, 5, 10);
    strokeWeight(random(3, 6));
    noFill();
    curve(x0, 2010, x0, 1910, tipX + random(-25, 25), tipY + 85, tipX, tipY);
    noStroke();
    fill(4, 5, 10);
    ellipse(tipX, tipY, 9, 24, random(-0.4, 0.4));
  }

  // film grain
  noStroke();
  for (let i = 0; i < 4200; i++) {
    if (random() < 0.5) fill(255, 255, 255, random(2, 6));
    else fill(0, 0, 0, random(2, 6));
    rect(random(width), random(height), 1.6, 1.6);
  }

  // vignette
  let ctx = drawingContext;
  let vg = ctx.createRadialGradient(800, 880, 480, 800, 1000, 1280);
  vg.addColorStop(0, "rgba(0,0,0,0)");
  vg.addColorStop(1, "rgba(2,3,8,0.62)");
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);
}

randomSeed(1);
noiseSeed(1);

let leavesOn = [];
let tips = [];
let leafPalette = [];

function setup() {
  createCanvas(1600, 2000);
  noLoop();
  leafPalette = [
    color(150, 82, 46),
    color(178, 112, 52),
    color(122, 56, 42),
    color(198, 142, 72),
    color(104, 52, 58)
  ];
}

function draw() {
  paintSky();
  paintStars();
  paintMoon();
  paintMist();
  paintHills();
  paintDistantTrees();
  paintGroundDetails();
  paintFallenLeaves();
  paintTreeGlow();
  paintTree();
  paintLeavesOnTree();
  paintEmbers();
  paintForegroundGrass();
  grain(SCREEN, 255, 55, 0.05);
  grain(MULTIPLY, 255, 45, 0.06);
  paintVignette();
}

function paintSky() {
  const stops = [
    [0.00, color(10, 7, 26)],
    [0.30, color(30, 20, 62)],
    [0.55, color(72, 41, 94)],
    [0.72, color(142, 78, 88)],
    [0.84, color(206, 128, 88)],
    [1.00, color(233, 166, 105)]
  ];
  noStroke();
  for (let y = 0; y < height; y++) {
    const t = y / height;
    let c = stops[stops.length - 1][1];
    for (let i = 0; i < stops.length - 1; i++) {
      const a = stops[i][0], b = stops[i + 1][0];
      if (t >= a && t <= b) {
        c = lerpColor(stops[i][1], stops[i + 1][1], (t - a) / (b - a));
        break;
      }
    }
    fill(c);
    rect(0, y, width, 1);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 300; i++) {
    const x = random(width);
    const y = random(height * 0.58);
    const fade = 1 - y / (height * 0.62);
    fill(255, 242, 220, random(15, 130) * fade);
    circle(x, y, random(1, 3));
  }
  for (let i = 0; i < 24; i++) {
    const x = random(width);
    const y = random(height * 0.4);
    fill(255, 245, 225, 40);
    circle(x, y, random(7, 12));
    fill(255, 245, 225, random(120, 200));
    circle(x, y, random(2, 3.6));
  }
}

function paintMoon() {
  const mx = 1160, my = 430, r = 135;
  const ctx = drawingContext;
  let g = ctx.createRadialGradient(mx, my, r * 0.2, mx, my, r * 3.2);
  g.addColorStop(0, 'rgba(250, 230, 200, 0.28)');
  g.addColorStop(1, 'rgba(250, 230, 200, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(mx, my, r * 3.2, 0, TWO_PI);
  ctx.fill();

  g = ctx.createRadialGradient(mx - r * 0.3, my - r * 0.3, r * 0.1, mx, my, r);
  g.addColorStop(0, 'rgba(252, 244, 222, 1)');
  g.addColorStop(0.8, 'rgba(244, 230, 200, 0.98)');
  g.addColorStop(1, 'rgba(238, 222, 190, 0)');
  ctx.fillStyle = g;
  ctx.beginPath();
  ctx.arc(mx, my, r * 1.12, 0, TWO_PI);
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(mx, my, r * 0.97, 0, TWO_PI);
  ctx.clip();
  noStroke();
  for (let i = 0; i < 16; i++) {
    const a = random(TWO_PI);
    const d = random(r * 0.8);
    fill(205, 188, 162, random(25, 65));
    circle(mx + cos(a) * d, my + sin(a) * d, random(8, r * 0.24));
  }
  fill(255, 250, 235, 30);
  circle(mx - r * 0.25, my - r * 0.2, r * 0.9);
  ctx.restore();
}

function paintMist() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 1260, 0, 1640);
  g.addColorStop(0, 'rgba(232, 150, 92, 0)');
  g.addColorStop(0.55, 'rgba(232, 150, 92, 0.16)');
  g.addColorStop(1, 'rgba(232, 150, 92, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1260, width, 380);
}

function hill(baseY, amp, col, freq, seedOff) {
  noStroke();
  fill(col);
  beginShape();
  vertex(0, height);
  for (let x = 0; x <= width; x += 16) {
    vertex(x, baseY - noise(x * freq, seedOff) * amp);
  }
  vertex(width, height);
  endShape(CLOSE);
}

function paintHills() {
  hill(1490, 80, color(66, 43, 84), 0.0015, 3.1);
  hill(1580, 100, color(35, 23, 56), 0.0021, 7.7);
  hill(1690, 120, color(15, 11, 30), 0.0028, 12.9);
}

function paintDistantTrees() {
  stroke(40, 27, 60);
  strokeWeight(2);
  for (let i = 0; i < 46; i++) {
    const x = random(width);
    const gy = 1490 - noise(x * 0.0015, 3.1) * 80;
    line(x, gy, x + random(-3, 3), gy - random(7, 24));
  }
}

function groundY(x) {
  return 1690 - noise(x * 0.0028, 12.9) * 120;
}

function paintGroundDetails() {
  for (let i = 0; i < 420; i++) {
    const x = random(width);
    const gy = groundY(x) + random(2, 60);
    const h = random(10, 48);
    if (random() < 0.16) {
      stroke(150, 96, 58, 110);
    } else {
      stroke(9, 7, 20, 200);
    }
    strokeWeight(random(1.5, 3));
    line(x, gy, x + random(-6, 6), gy - h);
  }
}

function paintFallenLeaves() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    const x = random(200, 760);
    const y = groundY(x) + random(6, 70);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    fill(random(leafPalette), random(150, 220));
    ellipse(0, 0, random(7, 14), random(3.5, 6.5));
    pop();
  }
}

function paintTreeGlow() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(540, 1080, 40, 540, 1080, 560);
  g.addColorStop(0, 'rgba(255, 175, 95, 0.14)');
  g.addColorStop(1, 'rgba(255, 175, 95, 0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || len < 9) {
    tips.push({ x: x, y: y });
    return;
  }
  const drift = noise(x * 0.01, depth * 0.7) * 0.22 - 0.08;
  const x2 = x + cos(angle + drift) * len;
  const y2 = y + sin(angle + drift) * len;
  stroke(27, 18, 26);
  strokeWeight(max(w, 0.9));
  strokeCap(ROUND);
  line(x, y, x2, y2);
  if (depth <= 3 && random() < 0.85) {
    leavesOn.push({
      x: lerp(x, x2, random(0.35, 1)),
      y: lerp(y, y2, random(0.35, 1))
    });
  }
  const n = depth > 4 ? (random() < 0.72 ? 2 : 3) : 2;
  for (let i = 0; i < n; i++) {
    const dir = (i - (n - 1) / 2) * random(0.45, 0.85) + random(-0.16, 0.16);
    branch(x2, y2, angle + drift + dir + 0.045, len * random(0.66, 0.8), w * 0.66, depth - 1);
  }
}

function paintTree() {
  leavesOn = [];
  tips = [];
  noStroke();
  fill(15, 11, 30);
  ellipse(430, 1705, 620, 140);
  branch(430, 1680, -HALF_PI + 0.06, 235, 30, 7);
  branch(430, 1680, -HALF_PI - 0.30, 150, 17, 5);
  branch(430, 1680, -HALF_PI + 0.38, 140, 15, 5);
}

function drawLeafShape(x, y, s, col, a) {
  push();
  translate(x, y);
  rotate(random(TWO_PI));
  noStroke();
  fill(col, a);
  ellipse(0, 0, s, s * 0.45);
  pop();
}

function paintLeavesOnTree() {
  for (const p of leavesOn) {
    drawLeafShape(p.x, p.y, random(8, 16), random(leafPalette), random(180, 240));
  }
  for (const p of tips) {
    const k = int(random(1, 3));
    for (let i = 0; i < k; i++) {
      drawLeafShape(p.x + random(-8, 8), p.y + random(-8, 8), random(7, 13), random(leafPalette), random(170, 235));
    }
  }
}

function paintEmbers() {
  noStroke();
  const x0 = 500, y0 = 1010, x1 = 1115, y1 = 505;
  for (let i = 0; i < 190; i++) {
    const t = pow(random(1), 0.85);
    const bx = lerp(x0, x1, t);
    const by = lerp(y0, y1, t) - sin(t * PI) * 150;
    const x = bx + (noise(i * 0.33, t * 5.0) - 0.5) * 280;
    const y = by + (noise(i * 0.33 + 40, t * 5.0) - 0.5) * 180;
    const s = random(2.2, 7) * (1 - t * 0.35) + 1;
    const a = random(90, 225) * (1 - t * 0.5) + 25;
    if (i % 6 === 0) {
      push();
      translate(x, y);
      rotate(noise(x * 0.02, y * 0.02) * TWO_PI + t * 3);
      fill(240, 175, 95, a * 0.22);
      ellipse(0, 0, s * 3.4, s * 1.7);
      fill(255, 205, 120, a);
      ellipse(0, 0, s * 1.7, s * 0.8);
      pop();
    } else {
      fill(255, 172, 82, a * 0.22);
      circle(x, y, s * 4.2);
      fill(255, 218, 145, a);
      circle(x, y, s);
    }
  }
}

function paintForegroundGrass() {
  stroke(7, 5, 15);
  strokeCap(ROUND);
  for (let i = 0; i < 14; i++) {
    const x = random(-40, 260);
    strokeWeight(random(5, 10));
    bezier(x, height + 20, x + random(-40, 40), height - random(140, 340),
      x + random(-90, 90), height - random(260, 460),
      x + random(-120, 120), height - random(360, 560));
  }
  for (let i = 0; i < 12; i++) {
    const x = random(width - 280, width + 40);
    strokeWeight(random(5, 9));
    bezier(x, height + 20, x + random(-40, 40), height - random(120, 300),
      x + random(-80, 80), height - random(240, 420),
      x + random(-110, 110), height - random(320, 520));
  }
}

function grain(mode, base, amt, alpha) {
  const g = createGraphics(800, 1000);
  g.loadPixels();
  for (let i = 0; i < g.pixels.length; i += 4) {
    const v = constrain(base + random(-amt, amt), 0, 255);
    g.pixels[i] = v;
    g.pixels[i + 1] = v;
    g.pixels[i + 2] = v;
    g.pixels[i + 3] = 255;
  }
  g.updatePixels();
  push();
  blendMode(mode);
  drawingContext.globalAlpha = alpha;
  image(g, 0, 0, width, height);
  drawingContext.globalAlpha = 1;
  pop();
}

function paintVignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(width * 0.5, height * 0.46, height * 0.22,
    width * 0.5, height * 0.52, height * 0.78);
  g.addColorStop(0, 'rgba(4, 3, 12, 0)');
  g.addColorStop(1, 'rgba(4, 3, 12, 0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

let endpoints = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();

  // ---- sky gradient ----
  const topC = color(7, 9, 22);
  const midC = color(22, 20, 44);
  const botC = color(38, 30, 54);
  noStroke();
  for (let y = 0; y < height; y += 2) {
    const t = y / height;
    const c = t < 0.55 ? lerpColor(topC, midC, t / 0.55) : lerpColor(midC, botC, (t - 0.55) / 0.45);
    fill(c);
    rect(0, y, width, 2);
  }

  // ---- stars ----
  for (let i = 0; i < 320; i++) {
    const x = random(width), y = random(height * 0.55);
    const s = random(0.6, 2.6), a = random(50, 220);
    fill(random() < 0.8 ? color(255, 255, 255, a) : color(255, 232, 200, a));
    circle(x, y, s);
  }
  for (let i = 0; i < 10; i++) {
    const x = random(width), y = random(height * 0.4), s = random(2, 3.5);
    fill(255, 255, 255, 36);
    circle(x, y, s * 6);
    fill(255, 255, 255, 230);
    circle(x, y, s);
  }

  // ---- moon ----
  const mx = 1230, my = 430, mr = 150;
  for (let r = 460; r > mr; r -= 8) {
    fill(248, 236, 205, map(r, mr, 460, 34, 0));
    circle(mx, my, r * 2);
  }
  fill(247, 239, 218);
  circle(mx, my, mr * 2);
  fill(213, 203, 183, 70);
  circle(mx - 45, my - 30, 46);
  circle(mx + 38, my + 42, 34);
  circle(mx + 10, my - 62, 24);
  circle(mx - 18, my + 72, 20);

  // ---- distant hill ----
  fill(20, 24, 44);
  beginShape();
  vertex(0, 1420);
  for (let x = 0; x <= width; x += 16) vertex(x, 1400 + noise(x * 0.004, 100) * 140);
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  // ---- moonlight wash on ground ----
  for (let i = 0; i < 14; i++) {
    fill(240, 226, 190, 5);
    ellipse(mx + random(-40, 40), 1560 + i * 34, 130 + i * 22, 30);
  }

  // ---- back mist ----
  drawMist(1440, 280, 26);

  // ---- near ground ----
  fill(11, 13, 26);
  beginShape();
  vertex(0, height);
  vertex(0, 1560);
  for (let x = 0; x <= width; x += 16) vertex(x, groundY(x));
  vertex(width, height);
  endShape(CLOSE);

  // ---- bare tree ----
  endpoints = [];
  strokeCap(ROUND);
  branch(690, groundY(690) + 8, -HALF_PI + random(-0.06, 0.06), 290, 30, 8);
  stroke(15, 16, 27);
  for (let i = -2; i <= 2; i++) {
    strokeWeight(10 - Math.abs(i) * 2);
    line(690, groundY(690) + 8, 690 + i * 58 + random(-8, 8), groundY(690) + 26 + Math.abs(i) * 6);
  }

  // ---- falling leaves dissolving into light ----
  for (let i = 0; i < 150; i++) {
    const e = random(endpoints);
    const sx = e[0] + random(-70, 70);
    const sy = e[1] + random(-50, 30);
    const t = random(1);
    const gy = groundY(sx) + 12;
    const yy = lerp(sy, gy, t);
    const xx = sx + sin(t * 6 + i) * 40 * t + t * random(-70, 70);
    const size = lerp(11, 6, t) * random(0.7, 1.3);
    if (t > 0.72) {
      const glow = map(t, 0.72, 1, 0, 1);
      noStroke();
      fill(255, 214, 140, 26 + 40 * glow);
      circle(xx, yy, size * 4);
      fill(255, 228, 165, 70 + 160 * glow);
      circle(xx, yy, size * (1.2 + glow));
    } else {
      const c = lerpColor(color(148, 82, 56), color(222, 164, 76), random(0.2, 1));
      fill(red(c), green(c), blue(c), random(150, 230));
      push();
      translate(xx, yy);
      rotate(t * 5 + i * 0.7 + sin(i) * 2);
      ellipse(0, 0, size, size * 0.45);
      pop();
    }
  }

  // ---- seated figure with warm inner glow ----
  const fx = 850;
  const fy = groundY(850);
  noStroke();
  for (let r = 300; r > 20; r -= 10) {
    fill(255, 172, 84, map(r, 20, 300, 46, 0));
    circle(fx, fy - 95, r * 2);
  }
  fill(9, 9, 15);
  beginShape();
  vertex(fx, fy - 128);
  bezierVertex(fx - 46, fy - 112, fx - 62, fy - 52, fx - 54, fy - 4);
  vertex(fx + 56, fy - 4);
  bezierVertex(fx + 64, fy - 52, fx + 48, fy - 112, fx, fy - 128);
  endShape(CLOSE);
  ellipse(fx, fy - 142, 58, 62);
  fill(3, 3, 8);
  ellipse(fx, fy - 138, 32, 36);

  // rim light
  noFill();
  stroke(255, 205, 130, 170);
  strokeWeight(3.5);
  bezier(fx + 2, fy - 172, fx + 34, fy - 150, fx + 52, fy - 90, fx + 56, fy - 6);
  stroke(255, 205, 130, 110);
  arc(fx, fy - 142, 52, 58, -1.3, 0.8);
  noStroke();

  // rising embers
  for (let i = 0; i < 16; i++) {
    const h = random(20, 220);
    fill(255, 190, 110, map(h, 20, 220, 160, 0));
    circle(fx + random(-14, 14) + random(-h * 0.15, h * 0.15), fy - 150 - h, random(2, 5));
  }

  // ---- front mist ----
  drawMist(1560, 420, 30);

  // ---- fireflies ----
  for (let i = 0; i < 24; i++) {
    fill(255, 220, 150, random(60, 180));
    circle(random(width), random(1100, 1760), random(1.5, 4));
  }

  // ---- vignette ----
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(width / 2, height * 0.42, 420, width / 2, height * 0.5, 1250);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(2,3,10,0.6)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  // ---- film grain ----
  for (let i = 0; i < 1800; i++) {
    fill(random() < 0.5 ? color(255, 255, 255, 4) : color(0, 0, 0, 5));
    circle(random(width), random(height), random(0.5, 1.6));
  }
}

function groundY(x) {
  return 1540 + noise(x * 0.003, 200) * 170;
}

function drawMist(y0, h, n) {
  noStroke();
  for (let i = 0; i < n; i++) {
    fill(175, 195, 225, random(4, 11));
    ellipse(random(width), y0 + random(h), random(220, 640), random(28, 78));
  }
}

function branch(x, y, ang, len, w, depth) {
  if (depth === 0 || len < 7) {
    endpoints.push([x, y]);
    return;
  }
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  const mxp = (x + x2) / 2 + cos(ang + HALF_PI) * random(-len * 0.18, len * 0.18);
  const myp = (y + y2) / 2 + sin(ang + HALF_PI) * random(-len * 0.18, len * 0.18);
  stroke(15, 16, 27);
  strokeWeight(w);
  noFill();
  quadraticCurve(mxp, myp, x2, y2);
  const kids = depth > 5 ? 2 : (random() < 0.72 ? 2 : 1);
  for (let i = 0; i < kids; i++) {
    const spread = kids === 1 ? random(-0.3, 0.3) : map(i, 0, kids - 1, -0.6, 0.6);
    branch(x2, y2, ang + spread + random(-0.22, 0.22), len * random(0.66, 0.8), Math.max(w * 0.62, 0.7), depth - 1);
  }
  if (depth <= 2) endpoints.push([x2, y2]);
}

// p5.js 1.11 — image fixe, sans ressources externes.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  noStroke();

  peindreFond();
  tracesDuFond();
  ombre();
  couronne();
  fibres();
  effritement();
  poussiere();
  grainFinal();
}

const TAU = Math.PI * 2;

function melange(a, b, t) {
  t = constrain(t, 0, 1);
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function poser(c, a) {
  fill(c[0], c[1], c[2], a);
}

// Une surface mate, légèrement plus froide dans l'ouverture.
function peindreFond() {
  background(15, 23, 30);
  loadPixels();

  for (let y = 0; y < height; y += 4) {
    for (let x = 0; x < width; x += 4) {
      let n = noise(x * 0.0024, y * 0.0024);
      let m = noise(90 + x * 0.011, y * 0.009);
      let chaleur = pow(y / height, 3);
      let centre = exp(
        -sq((x - 820) / 390) - sq((y - 860) / 690)
      );
      let bord = constrain(
        sq((x - 800) / 1050) + sq((y - 1000) / 1450),
        0, 1
      );

      let r = 15 + 14 * n + 12 * chaleur - 9 * centre - 5 * bord;
      let g = 22 + 17 * n + 5 * chaleur - 9 * centre - 6 * bord;
      let b = 29 + 20 * n - 7 * chaleur - 8 * centre - 7 * bord;
      let variation = (m - 0.5) * 7 + random(-1.5, 1.5);

      for (let yy = y; yy < min(y + 4, height); yy++) {
        for (let xx = x; xx < min(x + 4, width); xx++) {
          let i = 4 * (yy * width + xx);
          pixels[i] = r + variation;
          pixels[i + 1] = g + variation;
          pixels[i + 2] = b + variation;
          pixels[i + 3] = 255;
        }
      }
    }
  }
  updatePixels();
}

function tracesDuFond() {
  for (let i = 0; i < 18000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.005, y * 0.004);

    if (random() < 0.55) {
      fill(125, 137, 139, random(2, 8));
    } else {
      fill(5, 13, 21, random(5, 15));
    }

    let longueur = random(2, 18) * (0.4 + n);
    push();
    translate(x, y);
    rotate(-0.15 + n * 0.3);
    rect(0, 0, longueur, random(0.4, 1.8));
    pop();
  }
}

// k = 0 : bord intérieur ; k = 1 : bord extérieur.
// Les deux bords sont irréguliers et ne partagent pas tout à fait un axe.
function pointAnneau(t, k) {
  let s = sin(t);
  let c = cos(t);

  let n = noise(5 + c * 1.6, 5 + s * 1.6);
  let m = noise(19 + c * 4.2, 19 + s * 4.2);
  let largeur = 1 + 0.15 * sin(3 * t + 0.8);

  let rx = 253 + 182 * k * largeur;
  let ry = 535 + 172 * k;

  let x = s * (rx + (n - 0.5) * 65)
    + (m - 0.5) * (7 + 13 * k);
  let y = -c * (ry + (n - 0.5) * 77)
    + 16 * sin(2 * t + k);

  // Une légère inclinaison, sans symétrie monumentale.
  return {
    x: 806 + x + y * 0.105 + 18 * sin(t * 2),
    y: 905 + y
  };
}

function teinte(t, k) {
  const os = [220, 208, 166];
  const ocre = [176, 125, 57];
  const terre = [112, 57, 36];

  let c = k < 0.38
    ? melange(os, ocre, k / 0.38)
    : melange(ocre, terre, (k - 0.38) / 0.62);

  let lumiere = constrain(0.57 - 0.48 * sin(t), 0.14, 1);
  c = melange([49, 43, 36], c, lumiere);

  let bas = pow(max(0, -cos(t)), 5);
  c = melange(c, [133, 130, 111], bas * 0.58);
  return c;
}

function ombre() {
  noFill();
  for (let j = 0; j < 8; j++) {
    stroke(3, 8, 13, 8);
    strokeWeight(20 + j * 13);
    beginShape();
    for (let t = 0.49; t < 6.03; t += 0.025) {
      let p = pointAnneau(t, 0.5);
      vertex(p.x + 14, p.y + 20);
    }
    endShape();
  }
  noStroke();
}

// Des couches de pigment se chevauchent plutôt qu'un aplat vectoriel.
function couronne() {
  const bandes = 88;
  const segments = 235;

  for (let j = bandes - 1; j >= 0; j--) {
    let k = j / bandes;
    let debut = 0.43 + 0.085 * sin(k * 13) + 0.10 * k;
    let fin = 6.055 - 0.075 * sin(k * 17 + 1);
    let dt = (fin - debut) / segments;

    for (let i = 0; i < segments; i++) {
      let t = debut + i * dt;
      let bas = pow(max(0, -cos(t)), 8);
      let manque = 0.015 + bas * (0.05 + k * 0.24);

      if (random() < manque) continue;

      let c = teinte(t, k);
      let v = random(-10, 10);
      let extremite = min(
        constrain((t - debut) / 0.20, 0, 1),
        constrain((fin - t) / 0.17, 0, 1)
      );

      fill(c[0] + v, c[1] + v, c[2] + v,
           random(145, 220) * extremite);

      let a = pointAnneau(t, k);
      let b = pointAnneau(t + dt * 1.06, k);
      let d = pointAnneau(t, k + 1.5 / bandes);
      let e = pointAnneau(t + dt * 1.06, k + 1.5 / bandes);

      quad(a.x, a.y, b.x, b.y, e.x, e.y, d.x, d.y);
    }
  }
}

function fibres() {
  noFill();

  for (let i = 0; i < 4700; i++) {
    let t = random(0.53, 5.98);
    let k = random(0.015, 0.99);
    let c = teinte(t, k);
    let clair = random() < 0.56;
    let delta = clair ? random(9, 36) : -random(12, 32);

    stroke(c[0] + delta, c[1] + delta, c[2] + delta,
           random(15, 65));
    strokeWeight(random(0.45, 2.2));

    let longueur = random(0.006, 0.075);
    beginShape();
    for (let u = 0; u <= 5; u++) {
      let p = pointAnneau(
        t + longueur * u / 5,
        k + 0.008 * sin(u + i)
      );
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Quelques fêlures sombres, très fines, dans la matière seulement.
  for (let i = 0; i < 105; i++) {
    let t = random(0.8, 5.8);
    let depart = random(0.12, 0.65);
    stroke(23, 25, 25, random(35, 90));
    strokeWeight(random(0.5, 1.2));

    beginShape();
    for (let j = 0; j < 12; j++) {
      let k = depart + j * 0.022;
      let p = pointAnneau(t + 0.008 * sin(j * 1.8 + i), k);
      vertex(p.x, p.y);
    }
    endShape();
  }
  noStroke();
}

function effritement() {
  for (let i = 0; i < 29000; i++) {
    let t = random(0.38, 6.09);
    let k = random(-0.06, 1.13);
    let p = pointAnneau(t, k);
    let c = teinte(t, constrain(k, 0, 1));
    let horsBord = k < 0 || k > 1;

    if (horsBord && random() < 0.65) continue;
    if (t < 0.58 && random() < 0.72) continue;
    if (t > 5.94 && random() < 0.68) continue;

    let grain = random() < 0.06 ? random(3, 7) : random(0.5, 2.6);
    let v = random(-32, 35);
    fill(c[0] + v, c[1] + v, c[2] + v,
         horsBord ? random(12, 60) : random(25, 110));

    ellipse(p.x + random(-4, 4), p.y + random(-4, 4),
            grain, grain * random(0.45, 1.5));
  }
}

function poussiere() {
  // Le contour inférieur cesse progressivement d'être un contour.
  for (let i = 0; i < 16500; i++) {
    let t = random(2.12, 4.20);
    let k = random(0.35, 1.1);
    let p = pointAnneau(t, k);
    let chute = pow(random(), 2.15) * 475;
    let dispersion = 8 + chute * 0.24;

    let x = p.x + randomGaussian() * dispersion
      - 0.14 * chute;
    let y = p.y + chute;
    if (y > 1935 || x < 90 || x > 1510) continue;

    let c = melange(teinte(t, constrain(k, 0, 1)),
                    [77, 82, 78], chute / 540);
    let a = random(12, 95) * (1 - chute / 570);
    poser(c, a);

    let taille = random(0.7, 3.8) * (1 - chute / 760);
    if (random() < 0.025) {
      push();
      translate(x, y);
      rotate(random(TAU));
      rect(0, 0, taille * 3.8, taille);
      pop();
    } else {
      ellipse(x, y, taille, taille * random(0.6, 1.5));
    }
  }

  // Sédiments presque effacés, sans ligne d'horizon.
  for (let i = 0; i < 3400; i++) {
    let x = randomGaussian(755, 310);
    let y = randomGaussian(1845, 67);
    if (x < 100 || x > 1500 || y > 1950) continue;
    fill(146, 131, 99, random(3, 18));
    rect(x, y, random(1, 11), random(0.4, 1.4));
  }
}

function grainFinal() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = random(-2.8, 2.8);
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

// p5.js 1.11 — image fixe, sans ressources externes.

const W = 1600;
const H = 2000;
const M = 48;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
  paint();
}

function upper(x) {
  return 815
    + 150 * sin(x / W * PI * 1.28 - 0.48)
    + 52 * noise(x * 0.0022, 7);
}

function lower(x) {
  return upper(x)
    + 295
    + 108 * sin(PI * x / W)
    + 24 * noise(x * 0.003, 19);
}

function blend(a, b, t) {
  t = constrain(t, 0, 1);
  return [
    lerp(a[0], b[0], t),
    lerp(a[1], b[1], t),
    lerp(a[2], b[2], t)
  ];
}

function pigment(x, y) {
  const a = upper(x);
  const b = lower(x);
  const n = noise(x * 0.0038, y * 0.0038);
  const fine = noise(x * 0.025, y * 0.025);

  if (y < a) {
    const axis = 350 + 0.32 * y
      + 55 * sin(y * 0.005);
    const light = exp(-pow((x - axis) / 360, 2));
    let c = blend([22, 48, 48], [80, 105, 91], n);
    c = blend(c, [216, 203, 166],
      light * (0.68 + 0.31 * n));
    c = blend(c, [237, 223, 186],
      light * max(0, fine - 0.40) * 0.65);
    const rust = max(0, noise(x * 0.007, y * 0.004, 8) - 0.56);
    c = blend(c, [143, 76, 45], rust * 1.7);
    return c;
  }

  if (y > b) {
    const heat = exp(
      -pow((x - 1100) / 620, 2)
      -pow((y - 1630) / 450, 2)
    );
    let c = blend([36, 52, 50], [79, 88, 73], n);
    c = blend(c, [153, 75, 47], heat * (0.52 + n * 0.48));
    const chalk = max(0, noise(x * 0.004, y * 0.012, 5) - 0.57);
    return blend(c, [181, 159, 113], chalk * 1.25);
  }

  const t = (y - a) / (b - a);
  return blend(
    [9, 17, 19],
    [24, 24, 24],
    0.23 * n + 0.25 * pow(abs(t - 0.5) * 2, 3)
  );
}

function clipRegion(region) {
  const c = drawingContext;
  c.beginPath();

  if (region === "upper") {
    c.moveTo(M, M);
    c.lineTo(W - M, M);
    c.lineTo(W - M, upper(W - M));
    for (let x = W - M; x >= M; x -= 6) {
      c.lineTo(x, upper(x));
    }
  } else if (region === "lower") {
    c.moveTo(M, H - M);
    c.lineTo(W - M, H - M);
    c.lineTo(W - M, lower(W - M));
    for (let x = W - M; x >= M; x -= 6) {
      c.lineTo(x, lower(x));
    }
  } else {
    c.moveTo(M, upper(M));
    for (let x = M; x <= W - M; x += 6) {
      c.lineTo(x, upper(x));
    }
    c.lineTo(W - M, lower(W - M));
    for (let x = W - M; x >= M; x -= 6) {
      c.lineTo(x, lower(x));
    }
  }

  c.closePath();
  c.clip();
}

function paint() {
  background(208, 199, 177);

  // Trame du support, visible dans la réserve périphérique.
  strokeWeight(0.7);
  for (let i = 0; i < 18000; i++) {
    const x = random(W);
    const y = random(H);
    stroke(random() < 0.5 ? 245 : 111, random(7, 21));
    line(x, y, x + random(1, 7), y + random(-0.4, 0.4));
  }

  push();
  drawingContext.beginPath();
  drawingContext.rect(M, M, W - M * 2, H - M * 2);
  drawingContext.clip();

  // Sous-couche : variations de pigments plutôt qu'un dégradé lisse.
  noStroke();
  for (let y = M; y < H - M; y += 7) {
    for (let x = M; x < W - M; x += 7) {
      const c = pigment(x + 3, y + 3);
      const d = random(-4, 4);
      fill(c[0] + d, c[1] + d, c[2] + d);
      rect(x, y, 8, 8);
    }
  }

  // Frottis superposés.
  for (let i = 0; i < 43000; i++) {
    const x = random(M, W - M);
    const y = random(M, H - M);
    const c = pigment(x, y);
    const inGap = y >= upper(x) && y <= lower(x);
    const d = random(-17, 18) * (inGap ? 0.12 : 1);

    stroke(c[0] + d, c[1] + d, c[2] + d, random(18, 65));
    strokeWeight(random(0.5, inGap ? 2 : 4));

    const angle = y < upper(x)
      ? PI / 2 + random(-0.35, 0.35)
      : random(-0.18, 0.18);
    const len = random(2, inGap ? 12 : 25);

    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }

  upperBody();
  lowerBody();
  interruption();
  wornEdges();

  // Grain final commun aux couches de peinture.
  noStroke();
  for (let i = 0; i < 24000; i++) {
    const x = random(M, W - M);
    const y = random(M, H - M);
    const gap = y > upper(x) && y < lower(x);
    const bright = random() < 0.48;
    fill(bright ? 242 : 7, bright ? 226 : 13,
         bright ? 193 : 14, gap ? 3 : random(4, 15));
    ellipse(x, y, random(0.5, 2.1), random(0.5, 3));
  }
  pop();

  // Bord irrégulier de la couche picturale.
  noFill();
  strokeWeight(1);
  for (let i = 0; i < 4; i++) {
    stroke(62, 61, 49, 16);
    rect(M + i * 0.6, M + i * 0.6,
         W - 2 * M - i * 1.2, H - 2 * M - i * 1.2);
  }
}

function upperBody() {
  push();
  clipRegion("upper");
  noFill();
  strokeCap(ROUND);

  // Grandes veines liées : chacune est tranchée par la même absence.
  for (let i = 0; i < 1050; i++) {
    const x0 = random(55, 1510);
    const y0 = random(-160, 510);
    const length = random(420, 1360);
    const phase = random(TWO_PI);
    const drift = random(25, 135);
    const col = pigment(x0, max(M, y0));
    const light = exp(-pow((x0 - 510) / 430, 2));

    const c = random() < 0.72
      ? blend(col, [244, 226, 179], 0.22 + light * 0.4)
      : blend(col, [28, 52, 49], 0.56);

    stroke(c[0], c[1], c[2], random(12, 48));
    strokeWeight(random() < 0.13 ? random(7, 20) : random(0.6, 3.2));

    beginShape();
    for (let j = 0; j <= 85; j++) {
      const t = j / 85;
      const y = y0 + t * length;
      const x = x0 + drift * t
        + 24 * sin(t * 4.5 + phase)
        + 17 * (noise(x0 * 0.008, y * 0.003) - 0.5);
      vertex(x, y);
    }
    endShape();
  }

  // Écailles épaisses dans les zones éclairées.
  noStroke();
  for (let i = 0; i < 2100; i++) {
    const x = random(130, 1000);
    const y = random(70, 1060);
    const axis = 350 + 0.32 * y;
    if (random() > exp(-pow((x - axis) / 300, 2))) continue;

    const c = blend(pigment(x, y), [238, 218, 171], random(0.1, 0.62));
    fill(c[0], c[1], c[2], random(20, 88));

    const w = random(1, 9);
    const h = random(5, 38);
    beginShape();
    vertex(x, y);
    vertex(x + w, y - random(1, 5));
    vertex(x + w * 0.65 + 3, y + h);
    vertex(x - 1, y + h * 0.75);
    endShape(CLOSE);
  }

  // Quelques réseaux très fins, jamais refermés en figure.
  noFill();
  for (let i = 0; i < 140; i++) {
    const x = random(260, 890);
    const y = random(170, 790);
    stroke(239, 222, 181, random(20, 65));
    strokeWeight(random(0.45, 1.3));
    bezier(x - random(15, 55), y - random(30, 100),
           x - 18, y + 8,
           x + 18, y + 27,
           x + random(25, 65), y + random(90, 190));
  }
  pop();
}

function lowerBody() {
  push();
  clipRegion("lower");
  noFill();
  strokeCap(SQUARE);

  // La même matière, désormais en bancs disjoints.
  for (let i = 0; i < 1250; i++) {
    const x = random(-180, W);
    const y = random(1120, H);
    const length = random(22, 440);
    const c = pigment(constrain(x, M, W - M), y);
    const target = random() < 0.46
      ? [193, 151, 96] : [31, 48, 46];
    const ink = blend(c, target, random(0.15, 0.65));

    stroke(ink[0], ink[1], ink[2], random(15, 68));
    strokeWeight(random(0.7, 9));

    beginShape();
    for (let j = 0; j <= 24; j++) {
      const xx = x + length * j / 24;
      const yy = y
        + 26 * (noise(xx * 0.004, y * 0.006, 12) - 0.5)
        + 0.035 * (xx - x);
      vertex(xx, yy);
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 1900; i++) {
    const x = random(M, W - M);
    const y = random(1180, H - M);
    const c = blend(
      pigment(x, y),
      random() < 0.35 ? [210, 190, 145] : [94, 67, 47],
      random(0.2, 0.75)
    );
    fill(c[0], c[1], c[2], random(22, 100));

    const w = random(2, 19);
    const h = random(1, 7);
    beginShape();
    vertex(x, y);
    vertex(x + w * 0.7, y - h);
    vertex(x + w, y + h * 0.2);
    vertex(x + w * 0.25, y + h);
    endShape(CLOSE);
  }

  // Glacis froid près de la rupture.
  noFill();
  for (let j = 0; j < 95; j++) {
    stroke(17, 40, 40, map(j, 0, 95, 22, 0));
    strokeWeight(2.5);
    beginShape();
    for (let x = M; x <= W - M; x += 8) {
      vertex(x, lower(x) + j * 1.25);
    }
    endShape();
  }
  pop();
}

function interruption() {
  push();
  clipRegion("gap");

  // Un noir mat, sans astres, sans horizon intérieur.
  noFill();
  strokeWeight(4);
  for (let j = 0; j <= 200; j++) {
    const t = j / 200;
    const edge = pow(abs(2 * t - 1), 5);
    stroke(9 + edge * 4, 15 + edge * 3, 17 + edge * 3, 185);
    beginShape();
    for (let x = M; x <= W - M + 8; x += 8) {
      vertex(x, lerp(upper(x), lower(x), t));
    }
    endShape();
  }

  strokeWeight(0.6);
  for (let i = 0; i < 6500; i++) {
    const x = random(M, W - M);
    const y = random(upper(x), lower(x));
    stroke(random() < 0.5 ? 32 : 3, 27, 26, random(4, 13));
    line(x, y, x + random(1, 9), y + random(-0.5, 0.5));
  }
  pop();
}

function wornEdges() {
  noFill();
  strokeCap(ROUND);

  // La lumière s'arrête au bord ; elle ne dessine pas un passage.
  for (let i = 0; i < 170; i++) {
    const x = random(M + 5, W - M - 40);
    const len = random(4, 43);
    const c = blend(pigment(x, upper(x) - 7), [225, 201, 151], 0.33);
    stroke(c[0], c[1], c[2], random(22, 88));
    strokeWeight(random(0.6, 2.2));
    beginShape();
    for (let xx = x; xx <= x + len; xx += 3) {
      vertex(xx, upper(xx) - 2 - noise(xx * 0.06) * 4);
    }
    endShape();
  }

  // Menues morsures, comme une peinture raclée jusqu'au fond.
  noStroke();
  for (let i = 0; i < 1100; i++) {
    const x = random(M, W - M);
    const top = random() < 0.68;
    const y = top ? upper(x) : lower(x);
    fill(10, 17, 18, random(35, 150));
    const w = random(0.5, 4.2);
    const h = random(1, 12);
    triangle(x - w, y, x + w, y,
             x + random(-2, 2), y + (top ? -h : h));
  }
}

// p5.js 1.11 — sketch autonome
const W = 1600, H = 2000;
const pigments = [
  [155, 79, 45],
  [188, 130, 65],
  [211, 174, 106],
  [73, 112, 111],
  [44, 73, 81],
  [104, 67, 65],
  [187, 174, 144]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(W, H);
  noLoop();
}

function draw() {
  fond();
  strates();
  ecoulements();
  enceinte();
  fragments();
  glacis();
  grain();
}

function fond() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 0, 1050, H);
  g.addColorStop(0, "#ddd0ad");
  g.addColorStop(0.36, "#beb394");
  g.addColorStop(0.69, "#827d6b");
  g.addColorStop(1, "#343f40");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  noStroke();
  for (let i = 0; i < 17000; i++) {
    const x = random(W), y = random(H);
    const n = noise(x * 0.003, y * 0.003);
    const light = random() < 0.56;
    fill(
      light ? 233 : 55,
      light ? 220 : 63,
      light ? 183 : 59,
      random(2, 11) * n
    );
    ellipse(x, y, random(8, 65), random(2, 22));
  }

  // Reprises verticales, comme sur un enduit ancien.
  for (let i = 0; i < 700; i++) {
    const x = random(W), y = random(H);
    stroke(235, 220, 182, random(3, 14));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(-4, 4), y + random(15, 150));
  }

  const haze = ctx.createRadialGradient(780, 820, 250, 780, 820, 1020);
  haze.addColorStop(0, "rgba(31,35,34,0.28)");
  haze.addColorStop(0.7, "rgba(42,43,38,0.08)");
  haze.addColorStop(1, "rgba(42,43,38,0)");
  ctx.fillStyle = haze;
  ctx.fillRect(0, 0, W, H);
}

function strates() {
  noFill();
  for (let i = 0; i < 1100; i++) {
    const y = random(1460, 2050);
    const x = random(-200, 1450);
    const length = random(60, 640);
    const p = random(pigments);
    const alpha = map(y, 1460, 2000, 7, 42, true);
    stroke(p[0], p[1], p[2], random(0.3, 1) * alpha);
    strokeWeight(random(1, 12));
    beginShape();
    for (let j = 0; j <= 18; j++) {
      const xx = x + length * j / 18;
      const yy = y + 24 * (noise(xx * 0.003, y * 0.008) - 0.5);
      vertex(xx, yy);
    }
    endShape();
  }

  // Quelques affleurements clairs, très éloignés du centre.
  for (let i = 0; i < 160; i++) {
    const x = random(W), y = random(1710, 1980);
    stroke(218, 199, 151, random(10, 48));
    strokeWeight(random(0.6, 2.5));
    line(x, y, x + random(15, 190), y + random(-3, 3));
  }
}

function contour(t, s) {
  const wobble =
    1 +
    0.018 * sin(5 * t + 0.8) +
    0.012 * sin(11 * t) +
    0.027 * (noise(3 + cos(t) * 1.8, 3 + sin(t) * 1.8) - 0.5);

  const ex = cos(t) * 410 * (1 + 0.12 * sin(t)) * s * wobble;
  const ey = sin(t) * 665 * s * wobble;

  return {
    x: 820 + ex + ey * 0.085,
    y: 825 + ey
  };
}

function chemin(s) {
  const ctx = drawingContext;
  ctx.beginPath();
  for (let i = 0; i <= 400; i++) {
    const p = contour(TWO_PI * i / 400, s);
    if (i === 0) ctx.moveTo(p.x, p.y);
    else ctx.lineTo(p.x, p.y);
  }
  ctx.closePath();
}

function ecoulements() {
  noFill();
  for (let i = 0; i < 680; i++) {
    const t = random(0.19 * PI, 0.83 * PI);
    const p = contour(t, random(0.96, 1.12));
    const col = random(pigments);
    const endY = random(1570, 2020);
    const drift = random(-350, 350);

    stroke(col[0], col[1], col[2], random(8, 36));
    strokeWeight(random(0.7, 6));

    beginShape();
    for (let k = 0; k <= 35; k++) {
      const u = k / 35;
      const x = p.x + drift * u * u +
        (noise(i * 0.08, u * 3) - 0.5) * 42 * u;
      const y = lerp(p.y, endY, u);
      vertex(x, y);
    }
    endShape();
  }
}

function enceinte() {
  const ctx = drawingContext;

  // Une ombre sèche, sans contour parfaitement fermé.
  for (let i = 0; i < 19; i++) {
    chemin(1.21 - i * 0.005);
    ctx.fillStyle = "rgba(43,43,38,0.025)";
    ctx.fill();
  }

  const stops = [
    { s: 1.125, c: [105, 106, 89] },
    { s: 1.085, c: [90, 83, 64] },
    { s: 1.035, c: [157, 109, 58] },
    { s: 0.995, c: [174, 126, 64] },
    { s: 0.955, c: [99, 61, 43] },
    { s: 0.900, c: [47, 38, 35] },
    { s: 0.845, c: [20, 24, 26] }
  ];

  for (let k = 0; k < stops.length - 1; k++) {
    const a = stops[k], b = stops[k + 1];
    for (let j = 0; j < 12; j++) {
      const u = j / 12;
      const s = lerp(a.s, b.s, u);
      const r = lerp(a.c[0], b.c[0], u);
      const g = lerp(a.c[1], b.c[1], u);
      const bl = lerp(a.c[2], b.c[2], u);
      chemin(s);
      ctx.fillStyle = `rgb(${r},${g},${bl})`;
      ctx.fill();
    }
  }

  chemin(0.85);
  const dark = ctx.createLinearGradient(460, 350, 1120, 1460);
  dark.addColorStop(0, "#20272a");
  dark.addColorStop(0.46, "#121a1e");
  dark.addColorStop(1, "#222124");
  ctx.fillStyle = dark;
  ctx.fill();

  // Une modulation presque imperceptible : rien à déchiffrer.
  ctx.save();
  chemin(0.846);
  ctx.clip();
  noStroke();
  for (let i = 0; i < 2200; i++) {
    fill(56, 57, 61, random(1, 5));
    ellipse(random(420, 1210), random(220, 1470),
            random(15, 90), random(2, 16));
  }
  ctx.restore();

  // Pigments déposés tangentiellement sur la paroi.
  noFill();
  for (let i = 0; i < 12500; i++) {
    const t = random(TWO_PI);
    const s = random(0.86, 1.125);

    // La matière se raréfie vers l'ouverture inférieure.
    if (t > 0.32 * PI && t < 0.72 * PI && random() < 0.76) continue;

    const p = contour(t, s);
    const q = contour(t + random(0.003, 0.035), s);
    let col = random(pigments);

    if (s < 0.92 && random() < 0.65) col = [62, 49, 42];
    if (cos(t) < -0.3 && s > 1.01 && random() < 0.4) {
      col = [218, 181, 107];
    }

    stroke(col[0], col[1], col[2], random(15, 85));
    strokeWeight(random(0.5, 3.8));
    line(p.x, p.y, q.x, q.y);
  }

  // Des fissures irrégulières ; aucune symétrie emblématique.
  for (let i = 0; i < 39; i++) {
    const t = random(TWO_PI);
    stroke(27, 32, 31, random(55, 140));
    strokeWeight(random(0.6, 2.3));
    beginShape();
    for (let j = 0; j <= 12; j++) {
      const s = lerp(0.91, random(1.06, 1.13), j / 12);
      const p = contour(t + (noise(i, j * 0.3) - 0.5) * 0.045, s);
      vertex(p.x, p.y);
    }
    endShape();
  }

  // Le bas de l'enceinte devient le terrain, par touches disjointes.
  noStroke();
  for (let i = 0; i < 1700; i++) {
    const t = random(0.30 * PI, 0.73 * PI);
    const s = random(0.91, 1.14);
    const p = contour(t, s);
    const probability = pow(max(0, sin(t)), 9);
    if (random() > probability) continue;

    const col = random([
      [113, 111, 91], [126, 121, 96],
      [91, 98, 86], [143, 130, 99], [70, 82, 77]
    ]);
    fill(col[0], col[1], col[2], random(30, 105));
    push();
    translate(p.x + random(-8, 8), p.y + random(-6, 20));
    rotate(random(-0.25, 0.25));
    ellipse(0, 0, random(3, 22), random(8, 45));
    pop();
  }
}

function fragments() {
  noStroke();
  for (let i = 0; i < 1900; i++) {
    const u = random();
    const y = 1390 + u * 550;
    const x = randomGaussian(865, 75 + u * 240);
    if (x < 80 || x > 1520) continue;

    const col = random(pigments);
    fill(col[0], col[1], col[2], random(18, 115));
    const w = random(1, 8) * (1 + u);
    const h = random(2, 13);

    push();
    translate(x, y);
    rotate(random(-0.7, 0.7) * (1 - u));
    beginShape();
    vertex(-w, -h * 0.25);
    vertex(w * 0.4, -h);
    vertex(w, h * 0.3);
    vertex(-w * 0.5, h);
    endShape(CLOSE);
    pop();
  }

  // Quelques restes d'or : ni lumière surnaturelle, ni constellation.
  for (let i = 0; i < 95; i++) {
    const x = randomGaussian(820, 190);
    const y = random(1500, 1840);
    stroke(219, 180, 103, random(30, 100));
    strokeWeight(random(0.6, 1.8));
    line(x, y, x + random(3, 17), y + random(-2, 2));
  }
}

function glacis() {
  const ctx = drawingContext;
  const g = ctx.createLinearGradient(0, 1500, 0, H);
  g.addColorStop(0, "rgba(28,45,48,0)");
  g.addColorStop(1, "rgba(25,42,46,0.29)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 1500, W, 500);

  // Bords assourdis plutôt qu'un cadre.
  const v = ctx.createRadialGradient(790, 940, 600, 790, 940, 1370);
  v.addColorStop(0, "rgba(34,32,27,0)");
  v.addColorStop(1, "rgba(34,32,27,0.23)");
  ctx.fillStyle = v;
  ctx.fillRect(0, 0, W, H);
}

function grain() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = 4 * (y * W + x);
      const tooth = random(-3.5, 3.5);
      const weave = ((x % 3 === 0) ? 0.65 : -0.2) +
                    ((y % 4 === 0) ? 0.45 : -0.15);
      pixels[i] += tooth + weave;
      pixels[i + 1] += tooth + weave;
      pixels[i + 2] += tooth * 0.85 + weave;
    }
  }
  updatePixels();
}

const W = 1600, H = 2000;
const CX = 825, CY = 865;
const chalk = [193, 181, 147];
const ash = [115, 126, 117];
const rust = [139, 71, 43];
const verdigris = [57, 100, 94];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  background(31, 37, 36);
  noStroke();

  // Une préparation irrégulière, comme un fond travaillé au chiffon.
  for (let y = -20; y < H + 20; y += 14) {
    for (let x = -20; x < W + 20; x += 14) {
      const n = noise(x * 0.0024, y * 0.0024);
      const warmth = exp(
        -sq((x - 340) / 590) - sq((y - 630) / 920)
      );
      fill(
        24 + n * 39 + warmth * 28,
        31 + n * 35 + warmth * 10,
        31 + n * 30,
        145
      );
      ellipse(x + random(-9, 9), y + random(-9, 9),
              random(23, 51), random(22, 47));
    }
  }

  for (let i = 0; i < 7600; i++) {
    const x = random(W), y = random(H);
    const n = noise(x * 0.003, y * 0.003);
    const c = n > 0.58 ? ash : n < 0.37 ? rust : verdigris;
    brush(x, y, random(20, 125), random(3, 19),
          random(-0.4, 0.4), c, random(3, 13));
  }

  // Des dépôts, sans horizon net.
  for (let i = 0; i < 3100; i++) {
    const x = random(-80, W + 80);
    const y = random(1430, H + 60);
    const bend = 90 * sin(x / W * PI);
    const c = random() < 0.57 ? rust : ash;
    brush(x, y + bend, random(25, 240), random(2, 15),
          random(-0.07, 0.09), c, random(6, 27));
  }

  // La matière s'épaissit autour d'une forme qu'elle ne peut fermer.
  for (let i = 0; i < 14500; i++) {
    const t = random(TWO_PI);
    const r = 1 + pow(random(), 2.1) * 0.76;
    const p = contour(t, r);
    if (p.x < -40 || p.x > W + 40 || p.y > 1640) continue;

    const left = constrain((CX - p.x) / 510, 0, 1);
    const upper = constrain((CY - p.y) / 700, 0, 1);
    const strength = 0.12 + 0.77 * left + 0.18 * upper;
    if (random() > strength) continue;

    const q = contour(t + 0.012, r);
    const angle = atan2(q.y - p.y, q.x - p.x);
    let c;
    const choice = random();
    if (choice < 0.47 * left + 0.12) c = chalk;
    else if (choice < 0.69) c = rust;
    else c = verdigris;

    brush(
      p.x + random(-12, 12),
      p.y + random(-14, 14),
      random(7, 66),
      random(2, 17),
      angle + random(-0.23, 0.23),
      c,
      random(8, 39) * (1.35 - r * 0.35)
    );
  }

  // Quelques longues traces de peinture sèche, jamais des anneaux fermés.
  for (let j = 0; j < 155; j++) {
    const r = random(1.035, 1.52);
    const start = random(2.05, 4.4);
    const end = start + random(0.07, 0.65);
    const c = random() < 0.65 ? chalk : rust;
    noFill();
    stroke(c[0], c[1], c[2], random(12, 43));
    strokeWeight(random(0.5, 2.3));
    beginShape();
    for (let t = start; t <= end; t += 0.012) {
      const p = contour(t, r);
      vertex(p.x + random(-2, 2), p.y + random(-2, 2));
    }
    endShape();
  }

  // Le bord est absorbé plutôt que découpé.
  noStroke();
  for (let k = 22; k >= 1; k--) {
    fill(17, 23, 24, 12);
    voidShape(1 + k * 0.0038);
  }
  fill(17, 23, 24);
  voidShape(1);

  // Dans le vide : seulement la résistance sourde du pigment.
  for (let i = 0; i < 13500; i++) {
    const x = random(CX - 440, CX + 440);
    const y = random(CY - 700, CY + 700);
    const dx = (x - CX) / 365;
    const dy = (y - CY) / 635;
    if (dx * dx + dy * dy < 0.77) {
      fill(43, 50, 48, random(2, 10));
      ellipse(x, y, random(1, 5), random(1, 9));
    }
  }

  // Des éclats restent au bord, sans reconstruire une silhouette.
  for (let i = 0; i < 1150; i++) {
    const t = random(2.25, 4.9);
    const p = contour(t, random(1.005, 1.065));
    if (noise(p.x * 0.012, p.y * 0.009) < 0.47) continue;
    const q = contour(t + 0.01, 1.03);
    brush(p.x, p.y, random(3, 25), random(0.8, 4),
          atan2(q.y - p.y, q.x - p.x),
          chalk, random(15, 75));
  }

  // La matière libérée devient poussière et sédiment.
  for (let i = 0; i < 2500; i++) {
    const u = random();
    const y = 1400 + pow(u, 0.7) * 570;
    const x = 790 + randomGaussian() * (70 + u * 360);
    if (x < 60 || x > W - 60) continue;
    const c = random() < 0.73 ? rust : chalk;
    brush(x, y, random(2, 12) + u * random(2, 34),
          random(0.7, 3.5), random(-0.2, 0.2),
          c, random(9, 49));
  }

  for (let i = 0; i < 170; i++) {
    const y = random(1730, 1980);
    const x = random(110, 1490);
    brush(x, y, random(45, 250), random(0.6, 2.3),
          random(-0.025, 0.025), [20, 27, 27], random(20, 75));
  }

  grain();
}

function contour(t, r) {
  const waviness =
    1 + 0.033 * sin(3 * t + 0.7)
      + 0.018 * sin(7 * t - 0.8)
      + 0.025 * (noise(3 + cos(t) * 1.8,
                            3 + sin(t) * 1.8) - 0.5);
  return {
    x: CX + 365 * r * waviness * cos(t) + 42 * sin(t),
    y: CY + 635 * r * waviness * sin(t)
  };
}

function voidShape(r) {
  beginShape();
  for (let t = 0; t < TWO_PI; t += TWO_PI / 300) {
    const p = contour(t, r);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function brush(x, y, length, width, angle, c, opacity) {
  const dx = cos(angle), dy = sin(angle);
  strokeCap(SQUARE);
  stroke(c[0], c[1], c[2], opacity);
  strokeWeight(width);
  line(x - dx * length * 0.5, y - dy * length * 0.5,
       x + dx * length * 0.5, y + dy * length * 0.5);

  strokeWeight(max(0.45, width * 0.12));
  for (let k = 0; k < 3; k++) {
    const offset = random(-width * 0.5, width * 0.5);
    const a = random(-0.55, -0.2) * length;
    const b = random(0.2, 0.55) * length;
    stroke(c[0] + 9, c[1] + 8, c[2] + 5, opacity * 0.5);
    line(x + dx * a - dy * offset, y + dy * a + dx * offset,
         x + dx * b - dy * offset, y + dy * b + dx * offset);
  }
  noStroke();
}

function grain() {
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = 4 * (y * W + x);
      const g = random(-3.8, 3.8);
      const vignette = 1 - 0.17 * pow(
        constrain(sq((x - W / 2) / (W / 2)) *
                  0.5 + sq((y - H / 2) / (H / 2)) * 0.5, 0, 1),
        1.5
      );
      pixels[i] = pixels[i] * vignette + g;
      pixels[i + 1] = pixels[i + 1] * vignette + g;
      pixels[i + 2] = pixels[i + 2] * vignette + g;
    }
  }
  updatePixels();
}

// p5.js 1.11 — image fixe, sans ressources externes.

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();

  const ctx = drawingContext;
  const W = width;
  const H = height;

  // Le support : charbon, ardoise et terre.
  const fond = ctx.createLinearGradient(0, 0, W, H);
  fond.addColorStop(0, "#777363");
  fond.addColorStop(0.34, "#555c57");
  fond.addColorStop(0.68, "#343f43");
  fond.addColorStop(1, "#202b31");
  ctx.fillStyle = fond;
  ctx.fillRect(0, 0, W, H);

  function nuage(x, y, rx, ry, rgb, opacite) {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(rx, ry);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, 1);
    g.addColorStop(0, `rgba(${rgb},${opacite})`);
    g.addColorStop(0.55, `rgba(${rgb},${opacite * 0.38})`);
    g.addColorStop(1, `rgba(${rgb},0)`);
    ctx.fillStyle = g;
    ctx.fillRect(-1, -1, 2, 2);
    ctx.restore();
  }

  nuage(190, 410, 940, 1050, "196,169,117", 0.58);
  nuage(270, 1370, 540, 780, "126,69,43", 0.35);
  nuage(1380, 800, 670, 1100, "78,113,121", 0.42);
  nuage(1140, 1840, 950, 530, "17,26,31", 0.72);
  nuage(620, 100, 690, 420, "211,196,155", 0.22);

  // Une lacune asymétrique, sans perspective ni éclairage intérieur.
  const manque = new Path2D();
  manque.moveTo(791, 401);
  manque.bezierCurveTo(897, 377, 1009, 436, 1066, 547);
  manque.bezierCurveTo(1128, 666, 1099, 757, 1092, 842);
  manque.bezierCurveTo(1085, 927, 1120, 1011, 1085, 1116);
  manque.bezierCurveTo(1053, 1221, 1001, 1300, 917, 1371);
  manque.bezierCurveTo(843, 1434, 754, 1496, 656, 1471);
  manque.bezierCurveTo(581, 1453, 521, 1400, 501, 1320);
  manque.bezierCurveTo(481, 1237, 509, 1147, 534, 1062);
  manque.bezierCurveTo(567, 951, 546, 852, 558, 749);
  manque.bezierCurveTo(572, 638, 611, 537, 683, 468);
  manque.bezierCurveTo(715, 437, 752, 411, 791, 401);
  manque.closePath();

  const noir = ctx.createLinearGradient(500, 400, 1100, 1490);
  noir.addColorStop(0, "#111719");
  noir.addColorStop(0.48, "#0d1215");
  noir.addColorStop(1, "#101619");
  ctx.fillStyle = noir;
  ctx.fill(manque);

  // Tout ce qui suit appartient à la matière restante.
  const dehors = new Path2D();
  dehors.rect(0, 0, W, H);
  dehors.addPath(manque);

  ctx.save();
  ctx.clip(dehors, "evenodd");

  const terres = [
    [194, 174, 131],
    [150, 119, 77],
    [110, 85, 61],
    [204, 198, 171],
    [111, 133, 132],
    [65, 84, 91],
    [155, 91, 57]
  ];

  // Empâtements interrompus : petits dépôts irréguliers.
  for (let i = 0; i < 26500; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.0038, y * 0.0038);
    const c = random(terres);
    const a = random(0.015, 0.10) * (0.35 + n);
    const longueur = random(2, 23) * (0.5 + n);
    const epaisseur = random(0.5, 5.5);

    ctx.save();
    ctx.translate(x, y);
    ctx.rotate(-0.47 + 0.65 * n + random(-0.25, 0.25));
    ctx.fillStyle = `rgba(${c[0]},${c[1]},${c[2]},${a})`;
    ctx.fillRect(-longueur / 2, 0, longueur, epaisseur);
    ctx.restore();
  }

  // Des mouvements traversent le tableau ; ils ne contournent pas le manque.
  function trajectoire(t, niveau, phase, amplitude) {
    const x = -310 + 2230 * t;
    const y =
      niveau +
      440 * t +
      amplitude * Math.sin(t * 4.0 + phase) +
      42 * Math.sin(t * 8.7 + niveau * 0.0017);
    return { x, y };
  }

  function fibre(niveau, phase, amplitude, debut, fin, couleur, alpha, poids) {
    ctx.beginPath();
    const segments = Math.max(8, Math.ceil((fin - debut) * 95));
    for (let j = 0; j <= segments; j++) {
      const t = lerp(debut, fin, j / segments);
      const p = trajectoire(t, niveau, phase, amplitude);
      const tremblement =
        (noise(t * 28, niveau * 0.008 + 30) - 0.5) * 8;
      if (j === 0) ctx.moveTo(p.x, p.y + tremblement);
      else ctx.lineTo(p.x, p.y + tremblement);
    }
    ctx.strokeStyle =
      `rgba(${couleur[0]},${couleur[1]},${couleur[2]},${alpha})`;
    ctx.lineWidth = poids;
    ctx.lineCap = "butt";
    ctx.stroke();
  }

  // Couche profonde : larges traces presque effacées.
  for (let i = 0; i < 390; i++) {
    fibre(
      random(-700, 2150),
      random(-0.7, 0.7),
      random(70, 180),
      random(0, 0.12),
      random(0.82, 1),
      random(terres),
      random(0.018, 0.075),
      random(7, 37)
    );
  }

  // Couche sèche : réseaux fins, inégalement conservés.
  for (let i = 0; i < 2100; i++) {
    const niveau = random(-650, 2100);
    const debut = random(0, 0.7);
    const fin = Math.min(1, debut + random(0.08, 0.63));
    const c = random(terres);

    fibre(
      niveau,
      random(-0.35, 0.35),
      random(90, 155),
      debut,
      fin,
      c,
      random(0.045, 0.23),
      random(0.35, 1.8)
    );
  }

  // Une concentration de lumière usée, à gauche.
  for (let i = 0; i < 470; i++) {
    const niveau = random(50, 1130);
    fibre(
      niveau,
      random(-0.15, 0.15),
      random(110, 142),
      random(0.04, 0.16),
      random(0.36, 0.65),
      random([[216, 204, 169], [180, 148, 94], [226, 217, 189]]),
      random(0.05, 0.23),
      random(0.4, 2.1)
    );
  }

  // Restes de pigment : aucune nouvelle figure ne se reconstitue.
  for (let i = 0; i < 6100; i++) {
    const x = randomGaussian(1010, 360);
    const y = randomGaussian(1540, 245);
    if (x < 0 || x > W || y < 0 || y > H) continue;

    const c = random(terres);
    const taille = random(0.6, 4.5);
    const a = random(0.07, 0.35);
    ctx.fillStyle = `rgba(${c[0]},${c[1]},${c[2]},${a})`;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + taille * random(0.5, 2.3), y + random(-2, 2));
    ctx.lineTo(x + taille * 0.6, y + taille * random(0.4, 1.5));
    ctx.closePath();
    ctx.fill();
  }

  // Raclures ponctuelles du couteau.
  for (let i = 0; i < 190; i++) {
    const x = random(W);
    const y = random(H);
    const longueur = random(7, 75);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + longueur, y + longueur * random(0.12, 0.32));
    ctx.strokeStyle = random() < 0.65
      ? `rgba(224,216,188,${random(0.06, 0.22)})`
      : `rgba(19,29,31,${random(0.12, 0.32)})`;
    ctx.lineWidth = random(0.35, 1.2);
    ctx.stroke();
  }

  ctx.restore();

  // L'ensemble reste mat : ni halo autour du noir, ni bordure.
  const ombre = ctx.createRadialGradient(
    730, 890, 410,
    800, 1000, 1370
  );
  ombre.addColorStop(0, "rgba(5,10,13,0)");
  ombre.addColorStop(0.65, "rgba(5,10,13,0.04)");
  ombre.addColorStop(1, "rgba(5,10,13,0.35)");
  ctx.fillStyle = ombre;
  ctx.fillRect(0, 0, W, H);

  // Grain commun au support et à la lacune : le noir reste de la peinture.
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const grain = random(-2.8, 2.8);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain * 0.9, 0, 255);
  }
  updatePixels();
}

const W = 1600, H = 2000;
const CX = 800, CY = 1180, RX = 330, RY = 520;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

// Couleur du fond en tout point : la même fonction sert au fond et à la dissolution
function bgCol(x, y) {
  let t = constrain(y / H, 0, 1);
  let k = pow(t, 1.4);
  let r = lerp(236, 194, k);
  let g = lerp(231, 186, k);
  let b = lerp(221, 180, k);
  let n = noise(x * 0.0015, y * 0.0015) - 0.5;
  return [r + n * 18, g + n * 15, b + n * 22];
}

// Distance normalisée à la forme (< 1 = intérieur) : une graine, une flamme debout
function formField(x, y) {
  let dy = y - CY;
  let ry = dy < 0 ? RY * 1.15 : RY * 0.75;
  let narrow = 1 - 0.38 * constrain(-dy / (RY * 1.15), 0, 1);
  let nx = (x - CX) / (RX * narrow);
  let ny = dy / ry;
  let d = sqrt(nx * nx + ny * ny);
  d += (noise(x * 0.004, y * 0.004, 2) - 0.5) * 0.25;
  return d;
}

function brush(x, y, ang, len, w, r, g, b, al) {
  let ca = cos(ang), sa = sin(ang);
  let dx = ca * len * 0.5, dy = sa * len * 0.5;
  let px = -sa, py = ca;
  let n = 3;
  for (let i = 0; i < n; i++) {
    let o = (i / (n - 1) - 0.5) * w;
    let j = random(-0.15, 0.15) * len;
    stroke(r + random(-7, 7), g + random(-7, 7), b + random(-7, 7), al * random(0.55, 1));
    strokeWeight(random(0.8, 1.8) * (w / 4 + 0.5));
    line(x - dx + px * o + j * ca, y - dy + py * o + j * sa,
         x + dx + px * o, y + dy + py * o);
  }
}

function draw() {
  // 1. Fond : dégradé de base
  for (let y = 0; y < H; y++) {
    let c = bgCol(W / 2, y);
    stroke(c[0], c[1], c[2]);
    line(0, y, W, y);
  }

  // 2. Texture du fond : touches qui suivent un champ lent
  for (let i = 0; i < 38000; i++) {
    let x = random(-20, W + 20), y = random(-20, H + 20);
    let c = bgCol(x, y);
    let ang = noise(x * 0.001, y * 0.001, 9) * TWO_PI * 1.5;
    let v = random(-6, 6);
    brush(x, y, ang, random(14, 34), random(3, 7), c[0] + v, c[1] + v, c[2] + v, 55);
  }

  // 3. Ombre légère sous la forme : le sol qui la portait
  noStroke();
  for (let i = 0; i < 40; i++) {
    fill(120, 108, 104, 4);
    ellipse(CX, 1585, 1000 - i * 18, 110 - i * 2);
  }

  // 4. La forme et sa dissolution
  let count = 0;
  while (count < 72000) {
    let x = random(CX - RX * 1.15, CX + RX * 1.15);
    let y = random(520, 1620);
    let d = formField(x, y);
    if (d >= 1) continue;
    count++;

    // couleur du corps : bord sombre, cœur chaud, une lueur intérieure basse
    let inner = pow(constrain(1 - d, 0, 1), 0.8);
    let r = lerp(74, 172, inner);
    let g = lerp(30, 70, inner);
    let b = lerp(36, 42, inner);
    let gx = x - CX, gy = y - (CY + 70);
    let glow = exp(-(gx * gx + gy * gy) / (2 * 115 * 115));
    r = lerp(r, 230, glow * 0.85);
    g = lerp(g, 166, glow * 0.85);
    b = lerp(b, 96, glow * 0.85);

    // degré de retour au fond : croît vers le haut et vers le bord
    let up = constrain(map(y, CY + 320, CY - 640, 0, 1), 0, 1);
    let a = pow(up, 1.5);
    if (d > 0.78) a += (d - 0.78) * 1.6 * (0.25 + up);
    a = constrain(a, 0, 1);

    // déplacement : la matière s'en va vers le haut et s'écarte
    let drift = (noise(x * 0.003, y * 0.003, 5) - 0.5) * 2;
    let px = x + drift * 380 * a;
    let py = y - a * a * 520 * random(0.35, 1);

    let c = bgCol(px, py);
    let fr = lerp(r, c[0], a);
    let fg = lerp(g, c[1], a);
    let fb = lerp(b, c[2], a);

    // direction : épouse le contour, puis se tourne vers le haut
    let around = atan2(y - CY, x - CX) + HALF_PI + (noise(x * 0.01, y * 0.01) - 0.5) * 1.2;
    let rising = -HALF_PI + drift * 0.9;
    let ang = lerp(around, rising, a);

    let len = lerp(16, 30, a) * random(0.7, 1.3);
    let w = lerp(5.5, 2.2, a);
    let al = lerp(190, 110, a);
    brush(px, py, ang, len, w, fr, fg, fb, al);
  }

  // 5. Au-dessus : ce qui s'est rendu au fond, à peine plus clair
  for (let i = 0; i < 7000; i++) {
    let x = CX + randomGaussian() * 260;
    let y = random(80, 760);
    let c = bgCol(x, y);
    let lift = map(y, 760, 80, 9, 3);
    let ang = -HALF_PI + (noise(x * 0.002, y * 0.002, 7) - 0.5) * 2;
    brush(x, y, ang, random(18, 40), random(1.5, 3.5),
          c[0] + lift, c[1] + lift, c[2] + lift * 0.7, 60);
  }

  // 6. Grain de toile
  for (let i = 0; i < 60000; i++) {
    let x = random(W), y = random(H);
    let v = random() < 0.5 ? 0 : 255;
    stroke(v, 10);
    strokeWeight(random(0.6, 1.4));
    point(x, y);
  }
}

const W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  paintGround();
  paintBrushwork();
  paintDust();

  blendMode(ADD);
  warmSource(W * 0.44, H + 60);

  const ghosts = [
    { x: W * 0.18, yEnd: H * 0.52, off: 40 },
    { x: W * 0.80, yEnd: H * 0.38, off: 90 },
    { x: W * 0.64, yEnd: H * 0.62, off: 150 },
    { x: W * 0.28, yEnd: H * 0.72, off: 210 }
  ];
  for (const g of ghosts) {
    const p = makePath(g.x, H + 40, g.yEnd, g.off, 1.6);
    drawThread(p, { bright: 0.14, scale: 1.3, d: 0.3, pk: 3, warm: 0.35 });
  }

  const main = makePath(W * 0.44, H + 40, H * 0.31, 7, 1.6);
  drawThread(main, { bright: 1, scale: 3.2, d: 0.68, pk: 7, warm: 1 });

  blendMode(BLEND);
  vignette();
  grain();
}

// ---------- fond ----------
function paintGround() {
  const top = color(5, 6, 15), mid = color(11, 11, 27), bot = color(24, 16, 24);
  strokeWeight(1);
  for (let y = 0; y < H; y++) {
    const t = y / H;
    const c = t < 0.55 ? lerpColor(top, mid, t / 0.55) : lerpColor(mid, bot, (t - 0.55) / 0.45);
    stroke(c);
    line(0, y, W, y);
  }
}

function paintBrushwork() {
  const pal = [[22, 24, 52], [34, 24, 48], [8, 10, 22], [44, 28, 38], [16, 20, 40]];
  noFill();
  for (let k = 0; k < 7000; k++) {
    let x = random(-50, W + 50), y = random(-50, H + 50);
    const c = random(pal);
    stroke(c[0], c[1], c[2], random(5, 14));
    strokeWeight(random(1, 7));
    const len = floor(random(10, 40));
    beginShape();
    for (let s = 0; s < len; s++) {
      vertex(x, y);
      const a = noise(x * 0.0012, y * 0.0012, 3) * TWO_PI * 2;
      x += cos(a) * 4;
      y += sin(a) * 4;
    }
    endShape();
  }
}

function paintDust() {
  noStroke();
  for (let k = 0; k < 5500; k++) {
    const x = random(W), y = H * pow(random(), 1.6);
    const a = random(8, 55) * (1 - 0.5 * y / H);
    if (random() < 0.25) fill(230, 190, 160, a);
    else fill(170, 170, 205, a);
    circle(x, y, random(0.6, 2.4));
  }
}

function warmSource(x, y) {
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, 700);
  g.addColorStop(0, 'rgba(255,170,90,0.22)');
  g.addColorStop(0.4, 'rgba(180,90,60,0.07)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

// ---------- fil ----------
function makePath(x0, y0, yEnd, off, step) {
  const pts = [];
  let x = x0, y = y0, i = 0;
  while (y > yEnd && i < 6000) {
    let a = -HALF_PI + (noise(off + i * 0.004) - 0.5) * PI * 1.5;
    a += (noise(off + 100 + i * 0.02) - 0.5) * 0.5;
    if (x < 300) a += (300 - x) * 0.002;
    if (x > W - 300) a -= (x - (W - 300)) * 0.002;
    x += cos(a) * step;
    y += sin(a) * step;
    pts.push({ x, y });
    i++;
  }
  return pts;
}

function smoothStep(e0, e1, x) {
  const t = constrain((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

function solidity(t, d) {
  if (t < d) return 1;
  const q = (t - d) / (1 - d);
  return pow(1 - q, 1.4);
}

function profile(t) {
  const r = smoothStep(0, 0.22, t);
  return (0.3 + 0.7 * r) * (0.85 + 0.3 * noise(t * 6, 50));
}

function threadColor(t, warm) {
  const a = [255, 236, 214], b = [255, 206, 130], c = [250, 150, 120];
  let col;
  if (t < 0.5) col = [0, 1, 2].map(k => lerp(a[k], b[k], t / 0.5));
  else col = [0, 1, 2].map(k => lerp(b[k], c[k], (t - 0.5) / 0.5));
  const cool = [200, 190, 220];
  return [0, 1, 2].map(k => lerp(cool[k], col[k], warm));
}

function drawThread(pts, o) {
  const n = pts.length;
  noStroke();
  const layers = [[48, 30], [26, 45], [12, 80], [5, 140], [1.8, 255]];
  for (const L of layers) {
    for (let i = 0; i < n; i++) {
      const t = i / n;
      const s = solidity(t, o.d);
      if (s <= 0.02) continue;
      if (t > o.d && random() > s) continue;
      const w = max(1, profile(t) * L[0] * o.scale * (0.6 + 0.4 * s));
      const c = threadColor(t, o.warm);
      const a = min(255, L[1] * 1.6 / w * o.bright * (0.4 + 0.6 * s));
      fill(c[0], c[1], c[2], a);
      circle(pts[i].x, pts[i].y, w);
    }
  }
  for (let i = floor(n * o.d); i < n; i++) {
    const t = i / n;
    const u = 1 - solidity(t, o.d);
    const cnt = u * o.pk;
    const k = floor(cnt) + (random() < cnt % 1 ? 1 : 0);
    for (let j = 0; j < k; j++) {
      driftParticle(pts[i].x + random(-3, 3), pts[i].y + random(-3, 3), u, threadColor(t, o.warm), o.bright);
    }
  }
}

function driftParticle(x, y, u, c, b) {
  const steps = floor(random(10, 60) + u * random(40, 220));
  const dust = [175, 172, 210];
  const sz = random(1.2, 3.4) * (1 - 0.4 * u);
  noStroke();
  for (let s = 0; s < steps; s++) {
    const p = s / steps;
    const a = -HALF_PI + (noise(x * 0.0025, y * 0.0025, 11) - 0.5) * PI * 2.4;
    x += cos(a) * 2.2;
    y += sin(a) * 2.2;
    if (s % 2 === 0) {
      fill(lerp(c[0], dust[0], p), lerp(c[1], dust[1], p), lerp(c[2], dust[2], p), (1 - p) * 9 * b);
      circle(x, y, sz * (1 - 0.5 * p));
    }
  }
  fill(lerp(c[0], dust[0], 0.85), lerp(c[1], dust[1], 0.85), lerp(c[2], dust[2], 0.85), random(60, 160) * b);
  circle(x, y, sz * 0.7);
}

// ---------- finitions ----------
function vignette() {
  const g = drawingContext.createRadialGradient(W / 2, H * 0.55, W * 0.3, W / 2, H * 0.55, H * 0.78);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.6)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function grain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = random(-7, 7);
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();
}

// Ce qui retourne — p5.js 1.11
function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  // --- Fond : nuit froide en haut, terre sombre et tiède en bas ---
  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.0, '#06070d');
  bg.addColorStop(0.5, '#0e1019');
  bg.addColorStop(0.8, '#17131a');
  bg.addColorStop(1.0, '#1f1510');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  const cx = 800, cy = 1420;

  // --- Halo du foyer ---
  let halo = ctx.createRadialGradient(cx, cy, 0, cx, cy, 760);
  halo.addColorStop(0.0, 'rgba(255,170,95,0.20)');
  halo.addColorStop(0.35, 'rgba(200,110,70,0.08)');
  halo.addColorStop(1.0, 'rgba(0,0,0,0)');
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, width, height);

  // --- La poussière : le champ dont tout vient et où tout retourne ---
  noStroke();
  for (let i = 0; i < 52000; i++) {
    let x = random(width);
    let y = pow(random(), 1.7) * height;
    let a = random(8, 55) * (1 - y / height * 0.7);
    fill(188, 198, 214, a);
    let s = random() < 0.97 ? random(0.8, 1.8) : random(2, 3.2);
    circle(x, y, s);
  }

  // --- La forme : un tourbillon de lumière qui se tient, puis se délie ---
  blendMode(ADD);
  for (let i = 0; i < 2600; i++) {
    let a = random(TWO_PI);
    let r = sqrt(random()) * 380;
    let x = cx + cos(a) * r * 0.85;
    let y = cy + sin(a) * r;
    let px = x, py = y;
    let life = floor(random(260, 540));

    for (let s = 0; s < life; s++) {
      // degré de dissolution selon la hauteur, frontière organique
      let n = noise(x * 0.0025, y * 0.0025, 7);
      let t = constrain(map(y, cy - 140, 260, 0, 1) + (n - 0.5) * 0.5, 0, 1);

      // champ ordonné : rotation autour du foyer, retenue vers un anneau
      let dx = x - cx, dy = y - cy;
      let d = sqrt(dx * dx + dy * dy) + 1;
      let ox = -dy / d, oy = dx / d;
      let pull = (d - 360) / 360;
      ox -= (dx / d) * pull * 0.6;
      oy -= (dy / d) * pull * 0.6;
      oy -= 0.35; // lente ascension

      // champ libre : dérive de la poussière
      let ca = noise(x * 0.006, y * 0.006, 3) * TWO_PI * 3;
      let chx = cos(ca), chy = sin(ca) - 0.6;

      let vx = lerp(ox, chx, t), vy = lerp(oy, chy, t);
      let m = sqrt(vx * vx + vy * vy) + 1e-6;
      let sp = 2.2 + t * 3.2;
      x += (vx / m) * sp;
      y += (vy / m) * sp;

      if (x < -20 || x > width + 20 || y < -20 || y > height + 20) break;

      // couleur : braise -> poussière
      let cr = lerp(255, 186, t);
      let cg = lerp(178, 197, t);
      let cb = lerp(105, 216, t);

      if (t < 0.42) {
        stroke(cr, cg, cb, (1 - t) * 13 + 3);
        strokeWeight(1.1);
        line(px, py, x, y);
      } else if (random() < 0.10 * (1 - t) + 0.025) {
        stroke(cr, cg, cb, 70 * (1 - t * 0.55));
        strokeWeight(random(1.0, 2.4));
        point(x, y);
      }
      px = x; py = y;
    }
  }
  blendMode(BLEND);

  // --- Vignette ---
  let vig = ctx.createRadialGradient(width / 2, height * 0.55, 500, width / 2, height * 0.55, 1350);
  vig.addColorStop(0, 'rgba(0,0,0,0)');
  vig.addColorStop(1, 'rgba(0,0,0,0.6)');
  ctx.fillStyle = vig;
  ctx.fillRect(0, 0, width, height);

  // --- Grain de toile ---
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = random(-7, 7);
    pixels[i] = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  paintGround();
  paintField();
  paintHalo(800, 640);
  paintKnot(800, 640, 250);
  paintSmallKnot(1190, 1790, 26);
  paintVignette();
  paintGrain();
}

// Fond : nuit indigo qui s'éclaircit vers le bas
function paintGround() {
  const top = color(14, 16, 30);
  const mid = color(28, 30, 48);
  const bot = color(46, 54, 72);
  strokeWeight(1);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c = t < 0.55 ? lerpColor(top, mid, t / 0.55) : lerpColor(mid, bot, (t - 0.55) / 0.45);
    stroke(c);
    line(0, y, width, y);
  }
}

// La trame : d'innombrables fils calmes, indistincts
function paintField() {
  noFill();
  for (let i = 0; i < 320; i++) {
    let y0 = map(i, 0, 319, 1060, 2040) + random(-4, 4);
    let depth = map(y0, 1060, 2040, 0, 1);
    stroke(120, 138, 165, 10 + depth * 30);
    strokeWeight(random(0.6, 1.4));
    beginShape();
    for (let x = -20; x <= width + 20; x += 12) {
      let n = noise(x * 0.0016, y0 * 0.01, i * 0.05);
      vertex(x, y0 + (n - 0.5) * 60 * (0.4 + depth));
    }
    endShape();
  }
}

// Chaleur résiduelle autour de la forme
function paintHalo(cx, cy) {
  noStroke();
  for (let r = 700; r > 0; r -= 6) {
    fill(190, 80, 45, 1.6);
    ellipse(cx, cy + r * 0.08, r * 2, r * 2.1);
  }
}

// Le nœud : une forme singulière qui se desserre par le bas
function paintKnot(cx, cy, R) {
  const warmA = color(236, 98, 54);
  const warmB = color(246, 196, 120);
  const cool = color(124, 142, 170);
  const N = 170;
  const perTurn = 160;

  for (let i = 0; i < N; i++) {
    let pts = [];
    let phase = random(TWO_PI);
    let turns = random(3, 7);
    let dir = random() < 0.5 ? 1 : -1;
    let released = random() < 0.62;
    let knotSteps = floor(turns * perTurn);
    let seed = random(1000);
    let tilt = random(0.6, 1.0);
    let rot = random(TWO_PI);

    let k = 0;
    let maxK = knotSteps + 400;
    while (true) {
      let a = phase + (dir * k / perTurn) * TWO_PI;
      let n = noise(seed, k * 0.008);
      let r = R * (0.25 + 0.85 * n);
      let x = cos(a) * r;
      let y = sin(a) * r * tilt;
      let xr = x * cos(rot) - y * sin(rot);
      let yr = x * sin(rot) + y * cos(rot);
      if (yr > 0) yr *= 1.25; // le nœud s'affaisse vers le bas
      pts.push(createVector(cx + xr, cy + yr));
      k++;
      if (k >= knotSteps) {
        if (!released) break;
        if (cy + yr > cy + R * 0.3 || k >= maxK) break;
      }
    }
    let K = pts.length;

    if (released) {
      let p = pts[K - 1].copy();
      let v = p5.Vector.sub(p, pts[K - 2]).setMag(3.5);
      let targetY = random(1150, 1980);
      let side = random() < 0.5 ? -1 : 1;
      if (p.x < cx - 40) side = -1;
      else if (p.x > cx + 40) side = 1;
      for (let s = 0; s < 1100; s++) {
        let dy = targetY - p.y;
        let down = constrain(dy / 300, -0.3, 1);
        let desired = createVector(side * (1 - abs(down)) + side * 0.15, down);
        desired.setMag(3.5);
        let wob = (noise(seed + 50, s * 0.01) - 0.5) * (0.6 * max(0, 1 - s / 500) + 0.08);
        desired.rotate(wob);
        v.lerp(desired, 0.03);
        v.setMag(3.5);
        p.add(v);
        pts.push(p.copy());
        if (p.x < -30 || p.x > width + 30 || p.y > height + 30) break;
      }
    }

    // Dessin du fil, segment par segment
    for (let j = 1; j < pts.length; j++) {
      let p0 = pts[j - 1];
      let p1 = pts[j];
      let c, alpha, w;
      if (j < K) {
        let d = dist(p1.x, p1.y, cx, cy) / (R * 1.2);
        c = lerpColor(warmB, warmA, constrain(d, 0, 1));
        alpha = 150;
        w = 1.5;
      } else {
        let t = constrain((j - K) / 350, 0, 1);
        let warm = lerpColor(warmB, warmA, 0.8);
        c = lerpColor(warm, cool, t);
        alpha = lerp(150, 38, t);
        w = lerp(1.6, 0.9, t);
      }
      stroke(red(c), green(c), blue(c), alpha);
      strokeWeight(w);
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
}

// Ailleurs, faiblement, autre chose se noue
function paintSmallKnot(cx, cy, R) {
  noFill();
  for (let i = 0; i < 14; i++) {
    let phase = random(TWO_PI);
    let seed = random(1000);
    let rot = random(TWO_PI);
    let tilt = random(0.6, 1.0);
    stroke(230, 170, 110, 45);
    strokeWeight(0.9);
    beginShape();
    for (let k = 0; k < 400; k++) {
      let a = phase + (k / 100) * TWO_PI;
      let r = R * (0.3 + 0.8 * noise(seed, k * 0.02));
      let x = cos(a) * r;
      let y = sin(a) * r * tilt;
      vertex(cx + x * cos(rot) - y * sin(rot), cy + x * sin(rot) + y * cos(rot));
    }
    endShape();
  }
  // un fil de la trame qui y entre
  stroke(170, 150, 140, 40);
  strokeWeight(0.9);
  beginShape();
  for (let x = width + 20; x > cx + R * 0.6; x -= 8) {
    let y = cy + 30 * (x - cx) / (width - cx) + (noise(x * 0.004, 7) - 0.5) * 14;
    vertex(x, y);
  }
  endShape();
}

function paintVignette() {
  noFill();
  strokeWeight(6);
  for (let i = 0; i < 120; i++) {
    stroke(6, 6, 14, map(i, 0, 120, 40, 0));
    rect(i * 3, i * 3, width - i * 6, height - i * 6);
  }
}

function paintGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let g = random(-10, 10);
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();
}

// Le courant reprend — p5.js 1.11
const CX = 800, CY = 780, R = 420;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 100);
  noLoop();
}

function sstep(e0, e1, x) {
  let t = constrain((x - e0) / (e1 - e0), 0, 1);
  return t * t * (3 - 2 * t);
}

function angDiff(a, b) {
  return ((a - b + PI * 3) % TWO_PI) - PI;
}

// Degré d'appartenance au tourbillon (1 = dedans, 0 = le courant)
function inner(x, y) {
  let dx = x - CX, dy = y - CY;
  let d = sqrt(dx * dx + dy * dy);
  let a = atan2(dy, dx);
  let da = angDiff(a, HALF_PI);
  let br = exp(-da * da / 0.3); // la brèche, en bas
  let edge = R * (1 - 0.18 * br) +
    (noise(cos(a) * 1.5 + 3, sin(a) * 1.5 + 3) - 0.5) * 90;
  let s = 1 - sstep(edge - 70, edge + 30, d);
  s *= 1 - 0.9 * br * sstep(R * 0.35, R * 0.95, d);
  return constrain(s, 0, 1);
}

// Le grand courant : il descend
function fieldAngle(x, y) {
  let n = noise(x * 0.0011, y * 0.0011);
  return HALF_PI + (n - 0.5) * 2.2 + 0.15 * sin(y * 0.004 + x * 0.001);
}

function dir(x, y, s) {
  let fa = fieldAngle(x, y);
  let a = atan2(y - CY, x - CX);
  let ta = a + HALF_PI + 0.04 + (noise(x * 0.004, y * 0.004, 5) - 0.5) * 0.6;
  let vx = s * cos(ta) + (1 - s) * cos(fa);
  let vy = s * sin(ta) + (1 - s) * sin(fa);
  return atan2(vy, vx);
}

function drawChunk(pts, m, s, w, alpha) {
  let hue = lerp(218, 396, m) % 360;
  let g = 4 * s * (1 - s);
  let sat = lerp(48, 58, m) * (1 - 0.65 * g);
  let bri = lerp(26, 86, m) + g * 14 + random(-7, 7);
  stroke(hue, constrain(sat, 0, 100), constrain(bri, 0, 100), alpha);
  strokeWeight(w);
  beginShape();
  for (let p of pts) vertex(p[0], p[1]);
  endShape();
}

function flow(x, y, steps, len, w, baseAlpha, m0, decay) {
  let m = m0;
  let px = x, py = y;
  let pts = [[px, py]];
  for (let i = 0; i < steps; i++) {
    let s = inner(px, py);
    m = max(s, m * decay);
    let v = dir(px, py, s);
    px += cos(v) * len;
    py += sin(v) * len;
    pts.push([px, py]);
    if (pts.length >= 6 || i === steps - 1) {
      let t = i / steps;
      let taper = sin(PI * constrain(t, 0.02, 0.98));
      drawChunk(pts, m, s, w, baseAlpha * (0.35 + 0.65 * taper));
      pts = [[px, py]];
    }
    if (px < -50 || px > width + 50 || py < -50 || py > height + 50) break;
  }
}

function radialGlow(x, y, r, rgba0) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, rgba0);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function draw() {
  // Fond : nuit profonde
  strokeWeight(1);
  for (let y = 0; y < height; y++) {
    let t = y / height;
    stroke(lerp(234, 222, t), lerp(58, 46, t), lerp(8, 17, t));
    line(0, y, width, y);
  }
  noFill();

  // Lueurs sous-jacentes
  radialGlow(CX, CY, 620, 'rgba(120,70,110,0.22)');
  radialGlow(CX, CY + R * 0.8, 520, 'rgba(230,160,110,0.20)');
  radialGlow(CX - 60, CY + R * 1.8, 700, 'rgba(110,80,130,0.10)');

  // 1. Le courant
  for (let i = 0; i < 10000; i++) {
    let x = random(-40, width + 40);
    let y = random(-200, height);
    flow(x, y, 50, 4, random(0.8, 3.2), random(30, 60), 0, 0.95);
  }

  // 2. Le tourbillon
  for (let i = 0; i < 7000; i++) {
    let r = R * sqrt(random()) * 1.02;
    let a = random(TWO_PI);
    let x = CX + cos(a) * r, y = CY + sin(a) * r;
    flow(x, y, 80, 4, random(0.8, 2.8), random(35, 70), inner(x, y), 0.97);
  }

  // 3. Ce qui s'en va : la fuite par la brèche
  for (let i = 0; i < 2000; i++) {
    let x = CX + randomGaussian() * 110;
    let y = CY + random(R * 0.45, R * 0.95);
    flow(x, y, 200, 4, random(0.6, 2.2), random(30, 60), 1, 0.993);
  }

  // Éclat au point de rupture
  blendMode(ADD);
  radialGlow(CX - 20, CY + R * 0.78, 220, 'rgba(255,200,150,0.18)');
  radialGlow(CX - 20, CY + R * 0.78, 80, 'rgba(255,230,200,0.22)');
  blendMode(BLEND);

  // Vignette
  let ctx = drawingContext;
  let vg = ctx.createRadialGradient(width / 2, height * 0.45, height * 0.3,
                                    width / 2, height * 0.45, height * 0.85);
  vg.addColorStop(0, 'rgba(5,5,15,0)');
  vg.addColorStop(1, 'rgba(5,5,15,0.65)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, width, height);

  // Grain de toile
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 14;
    pixels[i] = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Fond : Le vide cosmique et la terre profonde
  background(7, 9, 14);
  drawAtmosphere();

  // 2. La Chaleur résiduelle (L'âme / L'énergie vitale)
  drawVitalGlow();

  // 3. Le Tissu de l'Être (Ce qui se dénoue)
  drawUnravelingForm();

  // 4. La Cendre et les Spores (La matière qui reste et celle qui s'élève)
  drawAshAndStardust();

  // 5. Texture picturale (Le grain du temps)
  applyCanvasTexture();
}

function drawAtmosphere() {
  noStroke();
  // Dégradé subtil du bas (dense, terrestre) vers le haut (infini, éthéré)
  for (let y = 0; y < height; y += 2) {
    let n = noise(y * 0.002);
    let ratio = y / height;

    // Haut : bleu nuit profond / Bas : terre d'ombre brûlée presque noire
    let r = lerp(10, 22, pow(ratio, 2)) + n * 5;
    let g = lerp(14, 15, ratio) + n * 5;
    let b = lerp(24, 12, pow(ratio, 0.5)) + n * 5;

    fill(r, g, b, 150);
    rect(0, y, width, 4);
  }

  // Nuages de nébuleuse / brume d'oubli
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.001, y * 0.001);
    let rad = random(100, 500) * n;

    let ratio = y / height;
    if (ratio < 0.6) {
      fill(20, 30, 48, 3); // Brume froide en haut
    } else {
      fill(40, 22, 15, 4); // Brume chaude/terreuse en bas
    }
    ellipse(x, y, rad, rad * 0.6);
  }
}

function drawVitalGlow() {
  blendMode(ADD);
  noStroke();

  // Le cœur de la forme (situé au tiers inférieur)
  let cx = width * 0.5;
  let cy = height * 0.68;

  // Halo d'or et de sang séché
  for (let i = 0; i < 300; i++) {
    let angle = random(TWO_PI);
    let dist = abs(randomGaussian(0, 180));
    let x = cx + cos(angle) * dist * 0.8;
    let y = cy + sin(angle) * dist * 1.2;
    let rad = random(50, 300);

    let c = lerpColor(color(180, 60, 20, 4), color(220, 160, 60, 2), dist / 400);
    fill(c);
    ellipse(x, y, rad, rad);
  }

  // Le seuil lumineux (la paix blanche au centre de la dissolution)
  for (let i = 0; i < 150; i++) {
    let x = cx + randomGaussian(0, 60);
    let y = cy - 150 + randomGaussian(0, 120);
    let rad = random(20, 150);
    fill(200, 220, 255, 3);
    ellipse(x, y, rad, rad * 1.5);
  }

  blendMode(BLEND);
}

function drawUnravelingForm() {
  // Des milliers de fils représentent la complexité d'une vie.
  // En bas, ils sont serrés, noués, colorés (sang, or, os).
  // En montant, ils se séparent, ralentissent, pâlissent et deviennent transparents.

  let numStrands = 3200;
  let cx = width * 0.5;
  let startY = height * 0.72;

  for (let i = 0; i < numStrands; i++) {
    // Origine dans le "nœud" de l'existence
    let angle = random(TWO_PI);
    let radius = abs(randomGaussian(0, 140));
    let x = cx + cos(angle) * radius;
    let y = startY + sin(angle) * radius * 0.7;

    // Choix de la couleur initiale (la matière vivante)
    let colorSeed = random(1);
    let startCol;
    if (colorSeed < 0.3) {
      startCol = color(140, 35, 25); // Sang profond / Cramoisi
    } else if (colorSeed < 0.6) {
      startCol = color(210, 145, 55); // Or / Ambre (Mémoire)
    } else if (colorSeed < 0.85) {
      startCol = color(230, 215, 195); // Os / Ivoire
    } else {
      startCol = color(40, 25, 20); // Ombre interne
    }

    // Couleur finale (l'éther)
    let endCol = color(140, 175, 210);
    if (random(1) < 0.3) endCol = color(240, 248, 255);

    let maxSteps = int(random(150, 750));
    let strandWeight = random(0.4, 2.2);

    // Certains fils tombent (le corps), la plupart montent (l'essence)
    let isFalling = random(1) < 0.22;

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;

      // Champ de force
      let nScale = 0.0025;
      let n = noise(x * nScale, y * nScale, i * 0.0005);

      let prevX = x;
      let prevY = y;

      if (isFalling) {
        // Gravité : s'effondre vers le bas et s'étale
        let fallAngle = HALF_PI + map(n, 0, 1, -0.9, 0.9);
        x += cos(fallAngle) * 2;
        y += sin(fallAngle) * 2.5;

        let c = lerpColor(startCol, color(15, 12, 10), pow(progress, 0.7));
        let alpha = sin(progress * PI) * 120 * (1 - progress * 0.5);
        stroke(red(c), green(c), blue(c), alpha);
        strokeWeight(strandWeight * (1 - progress * 0.5));
      } else {
        // Ascension : d'abord tourbillonnant et serré, puis vertical, puis dispersé
        let heightRatio = constrain(map(y, startY, 100, 0, 1), 0, 1);

        // Force de rappel vers le centre au début (le "soi" qui résiste)
        let pullToCenter = (cx - x) * 0.008 * pow(1 - heightRatio, 3);

        // Dérive éthérée en haut (dissolution dans le tout)
        let wind = map(noise(x * 0.001, y * 0.001, 10), 0, 1, -1, 1) * pow(heightRatio, 1.5) * 6;

        let upAngle = -HALF_PI + map(n, 0, 1, -1.6, 1.6) * (1 - heightRatio * 0.4);

        x += cos(upAngle) * 2.5 + pullToCenter + wind;
        y += sin(upAngle) * 2.2 - (heightRatio * 1.5);

        let c = lerpColor(startCol, endCol, pow(heightRatio, 0.8));

        // L'opacité s'évanouit à mesure que le fil monte
        let baseAlpha = map(heightRatio, 0, 1, 160, 15);
        let alpha = sin(progress * PI) * baseAlpha;

        stroke(red(c), green(c), blue(c), alpha);
        strokeWeight(strandWeight * (1 - progress * 0.8));
      }

      line(prevX, prevY, x, y);

      // Brisure occasionnelle du fil (fragmentation)
      if ( !isFalling && random(1) < 0.005 * (1 - (y / height)) ) {
        step += 20; // Saut dans le tracé
        x += random(-5, 5);
        y -= random(5, 15);
      }
    }
  }
}

function drawAshAndStardust() {
  noStroke();
  let cx = width * 0.5;

  // 1. Poussière lumineuse qui s'échappe (les derniers soupirs)
  blendMode(ADD);
  for (let i = 0; i < 4000; i++) {
    // Distribution en colonne évasée vers le haut
    let y = random(50, height * 0.8);
    let heightRatio = map(y, height * 0.8, 50, 0, 1);

    let spread = map(pow(heightRatio, 1.6), 0, 1, 120, 650);
    let x = cx + randomGaussian(0, spread);

    // Décalage par le bruit pour suivre les courants
    let n = noise(x * 0.003, y * 0.003);
    x += map(n, 0, 1, -80, 80);

    let sz = random(0.5, 3.5) * (1 - heightRatio * 0.5);

    if (random(1) < 0.2) {
      // Éclats d'or (souvenirs intacts)
      fill(255, 200, 120, random(30, 150) * (1 - heightRatio * 0.6));
    } else {
      // Lumière pâle
      fill(190, 220, 255, random(10, 100) * (1 - heightRatio * 0.3));
    }

    ellipse(x, y, sz, sz);

    // Quelques halos autour des particules les plus grandes
    if (sz > 2.5 && random(1) < 0.3) {
      fill(180, 210, 255, 12);
      ellipse(x, y, sz * 6, sz * 6);
    }
  }
  blendMode(BLEND);

  // 2. Cendres lourdes et matière sombre (ce qui retourne à la terre)
  for (let i = 0; i < 3000; i++) {
    let y = random(height * 0.55, height * 0.98);
    let depthRatio = map(y, height * 0.55, height * 0.98, 0, 1);

    let spread = map(depthRatio, 0, 1, 130, 500);
    let x = cx + randomGaussian(0, spread);

    let sz = random(1, 5);
    let alpha = sin(depthRatio * PI) * random(50, 180);

    if (random(1) < 0.7) {
      fill(12, 10, 12, alpha); // Charbon / Ombre
    } else {
      fill(90, 50, 35, alpha * 0.6); // Terre sèche
    }

    // Petits fragments irréguliers
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    rect(0, 0, sz, sz * random(0.4, 1.8));
    pop();
  }

  // 3. Le silence du haut : quelques étoiles très lointaines, immobiles
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let alpha = (1 - (y / (height * 0.5))) * random(20, 120);
    fill(220, 235, 255, alpha);
    let sz = random(0.5, 1.8);
    ellipse(x, y, sz, sz);
  }
}

function applyCanvasTexture() {
  // Ajoute une patine organique et un grain de peinture à l'huile / fusain
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Trame subtile de toile
      let weave = (sin(x * 0.8) + sin(y * 0.8)) * 1.5;

      // Grain aléatoire
      let grain = random(-6, 6);

      // Vignette douce pour fermer l'espace
      let d = dist(x, y, width * 0.5, height * 0.55);
      let maxD = dist(0, 0, width * 0.5, height * 0.55);
      let vignette = map(pow(d / maxD, 2.5), 0, 1, 0, -25);

      let mod = weave + grain + vignette;

      pixels[idx] = constrain(pixels[idx] + mod, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + mod, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + mod, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Toiles de fond : du vide profond (bas) vers l'éther lumineux (haut)
  drawBackground();

  // 2. L'horizon de passage (halo de dissolution)
  drawThresholdGlow();

  // 3. L'architecture du vivant (la forme ancrée qui s'effrite)
  drawLivingStructure();

  // 4. Le dénouement (les courants d'âme / entropie douce)
  drawUnravelingStreams();

  // 5. Poussière d'éther et grain pictural
  drawEtherealDust();
  applyCanvasTexture();
}

function drawBackground() {
  noStroke();
  let cTop = color(238, 235, 226);     // Ivoire lumineux, silence blanc
  let cUpperMid = color(165, 175, 178); // Brume céleste pâle
  let cLowerMid = color(45, 58, 68);    // Bleu de Prusse sourd
  let cBottom = color(12, 10, 16);      // Noir d'ivoire / terre d'ombre

  for (let y = 0; y < height; y++) {
    let n = y / height;
    let c;
    if (n < 0.45) {
      let t = map(n, 0, 0.45, 0, 1);
      c = lerpColor(cTop, cUpperMid, pow(t, 1.3));
    } else if (n < 0.78) {
      let t = map(n, 0.45, 0.78, 0, 1);
      c = lerpColor(cUpperMid, cLowerMid, pow(t, 0.9));
    } else {
      let t = map(n, 0.78, 1.0, 0, 1);
      c = lerpColor(cLowerMid, cBottom, pow(t, 1.1));
    }

    // Légère modulation horizontale pour un aspect peint
    fill(c);
    rect(0, y, width, 1);
  }

  // Nuages de glacis subtils dans le fond
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height);
    let n = y / height;
    let rad = random(100, 500);

    if (n < 0.5) {
      fill(245, 242, 235, random(2, 6));
    } else {
      fill(15, 20, 28, random(3, 8));
    }
    ellipse(x, y, rad, rad * random(0.4, 0.8));
  }
}

function drawThresholdGlow() {
  // Une lueur dorée éteinte là où la forme se défait (autour de y = 1350)
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 150; i++) {
    let x = width * 0.5 + randomGaussian() * 220;
    let y = 1350 + randomGaussian() * 180;
    let r = random(100, 600);
    fill(180, 145, 110, random(1, 3));
    ellipse(x, y, r, r * 0.7);
  }
  blendMode(BLEND);
}

function drawLivingStructure() {
  // La forme incarnée en bas : dense, complexe, géométrique mais organique,
  // comme une architecture de racines, de vaisseaux et de mémoire.
  push();
  for (let i = 0; i < 4500; i++) {
    let progress = i / 4500; 
    // Plus on monte (vers y=1150), plus la structure se fragmente
    let y = map(pow(random(), 0.75), 0, 1, 1960, 1150);
    let spread = map(y, 1960, 1150, 380, 160);

    // Courbure légère de la colonne de vie
    let centerOffset = sin(y * 0.004) * 40;
    let x = width * 0.5 + centerOffset + randomGaussian() * spread;

    // Distance au centre pour densifier le noyau
    let dCenter = abs(x - (width * 0.5 + centerOffset));
    if (random() > map(dCenter, 0, spread * 1.5, 1.0, 0.1)) continue;

    let n = noise(x * 0.008, y * 0.008);
    let angle = map(n, 0, 1, -PI, PI);

    // Palette de la matière vivante : sang séché, ocre, charbon, or ancien
    let choice = random();
    let c;
    let alpha = map(y, 1960, 1150, 220, 20);

    if (choice < 0.45) {
      c = color(18, 14, 20, alpha); // Charbon profond
    } else if (choice < 0.70) {
      c = color(95, 35, 30, alpha * 0.9); // Cramoisi sourd / vie
    } else if (choice < 0.90) {
      c = color(160, 110, 55, alpha * 0.85); // Ocre d'or
    } else {
      c = color(60, 85, 95, alpha * 0.8); // Gris-bleu de cendre
    }

    // Coups de pinceau structurés (liens, tensions)
    stroke(c);
    strokeWeight(random(1, 5) * map(y, 1960, 1150, 1.5, 0.4));

    let len = random(15, 70) * map(y, 1960, 1150, 1.2, 0.5);

    // En bas, les traits sont horizontaux/entrelacés (stabilité). 
    // En montant, ils s'orientent vers le haut (aspiration).
    let verticality = map(y, 1960, 1150, 0.2, 0.9);
    let finalAngle = lerp(angle, -HALF_PI + random(-0.4, 0.4), verticality);

    let x2 = x + cos(finalAngle) * len;
    let y2 = y + sin(finalAngle) * len;

    line(x, y, x2, y2);

    // Petits noeuds d'ancrage dans la partie basse
    if (y > 1450 && random() < 0.15) {
      noStroke();
      fill(c);
      ellipse(x, y, random(3, 9), random(3, 9));
    }
  }
  pop();
}

function drawUnravelingStreams() {
  // Les fils de l'être qui se défont et montent dans l'espace ouvert
  noFill();

  let numStreams = 2200;
  for (let i = 0; i < numStreams; i++) {
    // Point de départ ancré dans la structure vivante
    let startY = random(1200, 1850);
    let spread = map(startY, 1850, 1200, 320, 130);
    let centerOffset = sin(startY * 0.004) * 40;
    let x = width * 0.5 + centerOffset + randomGaussian() * spread * 0.85;
    let y = startY;

    // Couleur initiale du fil (héritée de la matière)
    let cStart;
    let r = random();
    if (r < 0.35) cStart = color(120, 45, 38);     // Vermillon sombre
    else if (r < 0.65) cStart = color(195, 145, 80); // Or pâle
    else if (r < 0.85) cStart = color(50, 75, 90);   // Bleu ardoise
    else cStart = color(25, 20, 28);                 // Ombre

    // Couleur finale : fusion avec la lumière haute
    let cEnd = color(240, 238, 230);

    let maxSteps = floor(random(150, 650));
    let weightStart = random(0.6, 2.8);
    let noiseScale = random(0.0015, 0.0035);
    let streamId = i * 0.01;

    for (let step = 0; step < maxSteps; step++) {
      let t = step / maxSteps;
      let heightFactor = constrain(map(y, 1600, 150, 0, 1), 0, 1);

      // Champ de force : monte toujours, mais s'évase en haut
      let nAngle = noise(x * noiseScale, y * noiseScale, streamId);

      // Dérive latérale douce qui s'amplifie en montant (libération)
      let drift = map(nAngle, 0, 1, -1, 1) * map(heightFactor, 0, 1, 0.6, 2.2);

      // Légère force centrifuge en haut de la toile (expansion dans le tout)
      let fromCenter = (x - width * 0.5) / (width * 0.5);
      let expansion = fromCenter * pow(heightFactor, 2) * 0.8;

      let angle = -HALF_PI + drift + expansion;
      let speed = map(heightFactor, 0, 1, 2.0, 4.5);

      let nx = x + cos(angle) * speed;
      let ny = y + sin(angle) * speed;

      // Évolution de la couleur et de l'opacité (dissolution)
      let c = lerpColor(cStart, cEnd, pow(heightFactor, 0.85));

      // Apparition progressive puis évanouissement total
      let alpha = sin(t * PI) * map(heightFactor, 0, 1, 140, 18);
      c.setAlpha(alpha);

      stroke(c);
      strokeWeight(lerp(weightStart, 0.2, t));
      line(x, y, nx, ny);

      x = nx;
      y = ny;

      // Rupture occasionnelle du fil (discontinuité du souffle)
      if (y < 900 && random() < 0.015) {
        x += random(-8, 8);
        y -= random(10, 30);
      }

      if (y < 40 || x < 40 || x > width - 40) break;
    }
  }
}

function drawEtherealDust() {
  // Particules de matière devenue lumière, flottant dans le silence supérieur
  noStroke();
  for (let i = 0; i < 3500; i++) {
    let y = pow(random(), 1.4) * 1650 + 50;
    let spread = map(y, 1700, 100, 200, 700);
    let x = width * 0.5 + randomGaussian() * spread;

    if (x < 0 || x > width) continue;

    let heightFactor = map(y, 1700, 100, 0, 1);

    if (random() < 0.7) {
      // Poussière lumineuse
      let alpha = map(heightFactor, 0, 1, 90, 15) * random(0.3, 1);
      fill(245, 240, 225, alpha);
    } else {
      // Derniers éclats d'ocre et de cendre
      let alpha = map(heightFactor, 0, 1, 110, 5);
      fill(175, 130, 85, alpha);
    }

    let sz = random(0.8, 3.5) * map(heightFactor, 0, 1, 1.2, 0.5);
    ellipse(x, y, sz, sz);
  }

  // Quelques halos très doux en haut (présence diffuse)
  for (let i = 0; i < 60; i++) {
    let x = random(width * 0.15, width * 0.85);
    let y = random(80, 900);
    let r = random(30, 160);
    fill(250, 248, 242, random(3, 8));
    ellipse(x, y, r, r);
  }
}

function applyCanvasTexture() {
  // Grain pictural subtil sur toute l'œuvre pour unifier la matière
  loadPixels();
  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Trame fine de lin + bruit organique
      let weave = (sin(x * 0.9) + sin(y * 0.9)) * 1.5;
      let grain = random(-6, 6) + weave;

      pixels[idx]     = constrain(pixels[idx] + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Fond : Le grand tout, l'océan cosmique du néant fertile
  drawBackground();

  // 2. Nébuleuses et profondeurs d'arrière-plan
  drawDeepNebula();

  // 3. L'Arche / Le Seuil : Une structure monolithique subtile, la porte du silence
  drawThreshold();

  // 4. Le Nœud d'Existence : La forme dense et chaude qui commence à se défaire
  drawLivingCore();

  // 5. La Transmutation : Les courants d'âme qui s'élèvent et se dispersent
  drawDissolutionStreams();

  // 6. Cendres et Étoiles : La poussière de ce qui fut, redevenant univers
  drawStardust();

  // 7. Texture picturale : Grain de toile et glaçis final
  applyCanvasTexture();
}

function drawBackground() {
  loadPixels();
  let cTop = color(6, 9, 18);       // Nuit abyssale
  let cMid = color(16, 24, 38);     // Bleu de Prusse très sombre
  let cBot = color(28, 18, 24);     // Lie-de-vin / Terre d'ombre brûlée

  for (let y = 0; y < height; y++) {
    let ny = y / height;
    let baseCol;
    if (ny < 0.65) {
      baseCol = lerpColor(cTop, cMid, pow(ny / 0.65, 1.2));
    } else {
      baseCol = lerpColor(cMid, cBot, pow((ny - 0.65) / 0.35, 0.9));
    }

    let rBase = red(baseCol);
    let gBase = green(baseCol);
    let bBase = blue(baseCol);

    for (let x = 0; x < width; x++) {
      let n = noise(x * 0.0015, y * 0.0015);
      let nFine = noise(x * 0.01, y * 0.01);
      let mod = (n - 0.5) * 28 + (nFine - 0.5) * 10;

      let idx = (y * width + x) * 4;
      pixels[idx]     = constrain(rBase + mod, 0, 255);
      pixels[idx + 1] = constrain(gBase + mod, 0, 255);
      pixels[idx + 2] = constrain(bBase + mod * 1.2, 0, 255);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();
}

function drawDeepNebula() {
  noStroke();
  // Nuages d'arrière-plan par couches de pinceau sec
  for (let i = 0; i < 4500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);

    // Concentration autour de la diagonale d'ascension et du centre
    let distToCenter = dist(x, y, width * 0.5, height * 0.55);
    if (random(1) < pow(1 - constrain(distToCenter / 1100, 0, 1), 1.5)) {
      let r = map(y, height, 0, 90, 20) + random(-15, 15);
      let g = map(y, height, 0, 45, 55) + random(-15, 15);
      let b = map(y, height, 0, 50, 95) + random(-15, 15);

      fill(r, g, b, random(2, 6));
      push();
      translate(x, y);
      rotate(noise(x * 0.003, y * 0.003) * TWO_PI * 2);
      let w = random(80, 400) * n;
      let h = random(20, 120) * n;
      ellipse(0, 0, w, h);
      pop();
    }
  }
}

function drawThreshold() {
  // Une grande forme géométrique spectrale, presque effacée, symbolisant le passage
  let cx = width * 0.5;
  let cy = height * 0.52;
  let archW = 680;
  let archH = 1100;

  noFill();
  for (let i = 0; i < 1200; i++) {
    let t = random(1);
    let angle = random(PI, TWO_PI);
    let px, py;

    // Soit sur l'arc supérieur, soit sur les piliers qui s'effacent vers le bas
    if (random(1) < 0.5) {
      let spread = randomGaussian(0, 25);
      px = cx + cos(angle) * (archW * 0.5 + spread);
      py = (cy - 150) + sin(angle) * (archW * 0.5 + spread);
    } else {
      let side = random(1) < 0.5 ? -1 : 1;
      let spread = randomGaussian(0, 30);
      px = cx + side * (archW * 0.5) + spread;
      py = random(cy - 150, height * 0.9);
    }

    let alpha = map(py, cy - 500, height * 0.9, 18, 0);
    stroke(160, 175, 195, constrain(alpha, 0, 20));
    strokeWeight(random(0.5, 2.5));

    // Coups de pinceau verticaux pour un effet architectural solennel
    let len = random(30, 180);
    line(px, py - len * 0.5, px + random(-3, 3), py + len * 0.5);
  }

  // Halo intérieur du seuil (lumière d'outre-monde)
  noStroke();
  for (let r = 600; r > 0; r -= 8) {
    let inter = map(r, 600, 0, 0, 1);
    fill(190, 210, 225, inter * 1.8);
    ellipse(cx, cy - 120, r * 1.1, r * 1.6);
  }
}

function drawLivingCore() {
  // En bas au centre : l'enchevêtrement de la vie, chaud, lourd, complexe, qui s'ouvre
  let cx = width * 0.5;
  let cy = height * 0.74;

  // Ombre d'ancrage sous le noyau (le poids du corps)
  noStroke();
  for (let i = 0; i < 600; i++) {
    let a = random(TWO_PI);
    let d = abs(randomGaussian(0, 220));
    let x = cx + cos(a) * d * 1.4;
    let y = cy + 80 + sin(a) * d * 0.6;
    fill(8, 5, 10, random(10, 25));
    ellipse(x, y, random(40, 180), random(20, 90));
  }

  // Fibres denses de la matière vivante (ocres, terres, ors sombres, carmins)
  let coreColors = [
    color(140, 45, 30),   // Carmin de garance
    color(185, 85, 35),   // Terre de Sienne brûlée
    color(215, 145, 55),  // Ocre d'or
    color(90, 25, 35),    // Sang séché / Ombre
    color(245, 205, 135)  // Lumière intérieure
  ];

  for (let i = 0; i < 3200; i++) {
    let progress = i / 3200;
    let angle = random(TWO_PI);
    // Plus on avance, plus on resserre vers le cœur lumineux
    let radius = random(20, 320) * (1 - progress * 0.6);

    // Déformation organique
    let x = cx + cos(angle) * radius * 1.15;
    let y = cy + sin(angle) * radius * 0.75;

    let colIdx = floor(pow(random(1), 1.6) * coreColors.length);
    let c = coreColors[colIdx];

    stroke(red(c), green(c), blue(c), random(15, 55));
    strokeWeight(random(1, 5) * (1 - progress * 0.5));
    noFill();

    // Courbes enchevêtrées qui commencent à s'ouvrir vers le haut
    beginShape();
    let px = x;
    let py = y;
    for (let step = 0; step < 12; step++) {
      vertex(px, py);
      let n = noise(px * 0.008, py * 0.008, i * 0.01);
      // Force tangentielle (le nœud) + force ascendante (la mort qui libère)
      let tangAngle = atan2(py - cy, px - cx) + HALF_PI;
      let upAngle = -HALF_PI + (n - 0.5) * 1.8;

      // Le haut du noyau se défait vers le ciel
      let releaseFactor = constrain(map(py, cy + 100, cy - 200, 0.1, 0.85), 0, 1);
      let finalAngle = lerp(tangAngle, upAngle, releaseFactor);

      px += cos(finalAngle) * 12;
      py += sin(finalAngle) * 12;
    }
    endShape();
  }
}

function drawDissolutionStreams() {
  // Les milliers de fils d'existence qui quittent le noyau et s'évaporent dans la hauteur
  let cx = width * 0.5;
  let cy = height * 0.72;

  let numStreams = 4200;

  for (let i = 0; i < numStreams; i++) {
    // Point de départ dans le noyau ou sur ses bords
    let spreadX = randomGaussian(0, 170);
    let spreadY = randomGaussian(0, 90);
    let x = cx + spreadX;
    let y = cy + spreadY;

    // Chaque fil a sa propre longévité et sa propre trajectoire
    let maxSteps = floor(random(120, 480));
    let weight = random(0.4, 2.6);

    // Couleur de départ : chaude (vie)
    let cStart = lerpColor(
      color(210, 110, 45),
      color(250, 220, 160),
      constrain(1 - abs(spreadX) / 220, 0, 1)
    );

    // Couleur de milieu : transmutation (ivoire, opale, bleu pâle, cendre)
    let cMid = random(1) < 0.65
      ? color(165, 200, 215) // Bleu d'âme / Éther
      : color(225, 215, 205); // Ivoire / Os / Lumière pâle

    // Couleur de fin : dissolution dans le cosmos (indigo profond ou lueur céleste)
    let cEnd = color(65, 95, 135);

    noFill();
    let prevX = x;
    let prevY = y;

    // Paramètre d'identité du fil pour varier la physique
    let streamId = i * 0.003;
    let driftSide = spreadX > 0 ? 1 : -1;

    for (let s = 0; s < maxSteps; s++) {
      let t = s / maxSteps; // 0 (vie) -> 1 (dissipation complète)
      let globalHeightFactor = constrain(map(y, cy, height * 0.08, 0, 1), 0, 1);

      // Champ de vecteurs à plusieurs échelles (turbulence fluide)
      let nMacro = noise(x * 0.0015, y * 0.0015);
      let nMicro = noise(x * 0.007, y * 0.007, streamId);

      // Au départ, aspiration vers l'axe central (le passage du seuil), puis ouverture en corolle tout en haut
      let distFromCenter = x - cx;
      let pullToCenter = -distFromCenter * 0.0025 * sin(globalHeightFactor * PI);
      let bloomOut = (distFromCenter * 0.004) * pow(globalHeightFactor, 2.5);

      let angle = -HALF_PI
                + (nMacro - 0.5) * 1.6
                + (nMicro - 0.5) * 0.9 * t
                + pullToCenter
                + bloomOut;

      let stepLen = 3.2;
      x += cos(angle) * stepLen;
      y += sin(angle) * stepLen;

      // Calcul de la couleur selon l'élévation
      let col;
      if (globalHeightFactor < 0.45) {
        col = lerpColor(cStart, cMid, globalHeightFactor / 0.45);
      } else {
        col = lerpColor(cMid, cEnd, (globalHeightFactor - 0.45) / 0.55);
      }

      // Opacité : apparaît, brille au passage du seuil, puis s'évanouit doucement
      let alphaEnv = sin(t * PI);
      let alpha = alphaEnv * map(globalHeightFactor, 0, 1, 45, 12);

      stroke(red(col), green(col), blue(col), alpha);
      strokeWeight(weight * (1 - t * 0.7));
      line(prevX, prevY, x, y);

      // Parfois, le fil lâche une micro-particule de lumière (l'effritement de l'être)
      if (random(1) < 0.0045 && globalHeightFactor > 0.25) {
        noStroke();
        fill(235, 240, 250, alpha * 2.5);
        let pSize = random(1.5, 4.5);
        ellipse(x + random(-8, 8), y + random(-8, 8), pSize, pSize);
      }

      prevX = x;
      prevY = y;

      if (y < 40 || x < 40 || x > width - 40) break;
    }
  }
}

function drawStardust() {
  // Au sommet de la toile, les fils dissous deviennent une brume d'étoiles silencieuses
  let cx = width * 0.5;

  // Brume lumineuse au cœur du passage (l'instant du lâcher-prise)
  noStroke();
  for (let i = 0; i < 350; i++) {
    let x = cx + randomGaussian(0, 180);
    let y = height * 0.48 + randomGaussian(0, 220);
    let d = dist(x, y, cx, height * 0.5);
    let a = map(d, 0, 450, 7, 0);
    if (a > 0) {
      fill(220, 230, 245, a);
      ellipse(x, y, random(30, 140), random(40, 180));
    }
  }

  // Particules d'or pâle et de cendre céleste qui dérivent vers le haut
  for (let i = 0; i < 2800; i++) {
    let y = pow(random(1), 1.3) * height * 0.85;
    let spread = map(y, height * 0.8, 0, 160, 650);
    let x = cx + randomGaussian(0, spread);

    if (x > 0 && x < width && y > 0 && y < height) {
      let n = noise(x * 0.005, y * 0.005);
      let sz = random(0.8, 3.2) * (n + 0.5);

      // Plus on est haut, plus les particules sont froides et cristallines
      let cWarm = color(245, 200, 140);
      let cCool = color(210, 230, 255);
      let c = lerpColor(cWarm, cCool, map(y, height * 0.75, 0, 0, 1, true));

      let alpha = random(20, 160) * sin(map(y, 0, height * 0.85, 0.15, PI));
      noStroke();
      fill(red(c), green(c), blue(c), alpha);
      ellipse(x, y, sz, sz);

      // Quelques étoiles ont un léger halo de diffusion
      if (random(1) < 0.06) {
        fill(red(c), green(c), blue(c), alpha * 0.2);
        ellipse(x, y, sz * 5, sz * 5);
      }
    }
  }
}

function applyCanvasTexture() {
  // Simule le grain d'une toile de lin et l'empâtement de la peinture à l'huile
  loadPixels();
  for (let y = 0; y < height; y++) {
    // Trame horizontale et verticale subtile (fils de lin)
    let weaveY = sin(y * 1.4) * 2.5;
    for (let x = 0; x < width; x++) {
      let weaveX = sin(x * 1.4) * 2.5;
      let grain = (random(-1, 1) * 5.5) + (weaveX + weaveY) * 0.6;

      // Vignette douce pour fermer la composition dans le recueillement
      let dx = (x - width * 0.5) / (width * 0.5);
      let dy = (y - height * 0.5) / (height * 0.5);
      let distSq = dx * dx + dy * dy;
      let vignette = 1 - constrain(pow(distSq, 1.4) * 0.28, 0, 0.5);

      let idx = (y * width + x) * 4;
      pixels[idx]     = constrain((pixels[idx] + grain) * vignette, 0, 255);
      pixels[idx + 1] = constrain((pixels[idx + 1] + grain) * vignette, 0, 255);
      pixels[idx + 2] = constrain((pixels[idx + 2] + grain) * vignette, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 100);

  // 1. LE FOND : L'immensité silencieuse et la terre profonde
  drawVoidBackground();

  // 2. LA BRUME : L'atmosphère de transition
  drawNebula();

  // 3. LA TRAME : La forme complexe de la vie qui se défait
  drawUnravelingForm();

  // 4. LE NOYAU : La dernière tension de l'être et sa fracture
  drawCoreAndFracture();

  // 5. LA POUSSIÈRE : La dispersion finale dans le tout
  drawStardust();

  // 6. LA TEXTURE : Le grain de la toile et du temps
  applyCanvasTexture();
}

function drawVoidBackground() {
  noStroke();
  let cTop = color(235, 35, 92);    // Aube pâle, infini calme
  let cMid1 = color(250, 50, 55);   // Crépuscule de transition
  let cMid2 = color(275, 65, 22);   // Profondeur pourpre
  let cBot = color(290, 80, 6);     // Obscurité fertile, le sol

  for (let y = 0; y < height; y++) {
    let normY = y / height;
    let c;
    if (normY < 0.35) {
      c = lerpColor(cTop, cMid1, map(normY, 0, 0.35, 0, 1));
    } else if (normY < 0.7) {
      c = lerpColor(cMid1, cMid2, map(normY, 0.35, 0.7, 0, 1));
    } else {
      c = lerpColor(cMid2, cBot, map(normY, 0.7, 1, 0, 1));
    }
    fill(c);
    rect(0, y, width, 1);
  }

  // Halo lumineux subtil au sommet (l'appel du vide)
  blendMode(SCREEN);
  for (let r = 1400; r > 0; r -= 15) {
    let alpha = map(r, 0, 1400, 1.5, 0);
    fill(210, 20, 100, alpha);
    ellipse(width * 0.5, 100, r * 1.3, r * 0.9);
  }
  blendMode(BLEND);
}

function drawNebula() {
  noStroke();
  for (let i = 0; i < 1200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.002, y * 0.002);

    let normY = y / height;
    let rad = map(n, 0, 1, 40, 350);

    let h = map(normY, 0, 1, 210, 340) + random(-15, 15);
    let s = map(normY, 0, 1, 25, 70);
    let b = map(normY, 0, 1, 95, 25);
    let a = random(0.5, 2.5);

    // Concentration de chaleur autour du centre de gravité (le cœur)
    let dToCore = dist(x, y, width * 0.5, height * 0.72);
    if (dToCore < 450) {
      h = lerp(h, 25, map(dToCore, 0, 450, 0.8, 0));
      s = lerp(s, 85, map(dToCore, 0, 450, 0.8, 0));
      b = lerp(b, 80, map(dToCore, 0, 450, 0.5, 0));
      a *= 1.5;
    }

    fill((h + 360) % 360, s, b, a);
    ellipse(x, y, rad, rad * random(0.6, 1.4));
  }
}

function drawUnravelingForm() {
  let numStrands = 5500;
  let coreX = width * 0.5;
  let coreY = height * 0.75;

  for (let i = 0; i < numStrands; i++) {
    // Naissance du fil dans la région dense (la vie incarnée)
    let angle = random(TWO_PI);
    let r = sqrt(random(1)) * 260;
    let x = coreX + cos(angle) * r * 1.1;
    let y = coreY + sin(angle) * r * 0.7;

    let strandType = random(1);
    let maxSteps = int(random(150, 750));
    let stepSize = random(1.5, 3.0);

    // Palette de la vie : sang, ambre, or, mémoire, cendre
    let hStart, sStart, bStart;
    if (strandType < 0.35) { 
      hStart = random(345, 375) % 360; // Cramoisi / Sang
      sStart = random(75, 95);
      bStart = random(40, 85);
    } else if (strandType < 0.75) { 
      hStart = random(25, 50);         // Or / Ambre / Lumière vitale
      sStart = random(70, 90);
      bStart = random(75, 100);
    } else if (strandType < 0.9) { 
      hStart = random(180, 210);       // Souffle / Cyan éthéré
      sStart = random(30, 60);
      bStart = random(70, 95);
    } else { 
      hStart = random(270, 300);       // Ombre / Structure osseuse
      sStart = random(50, 80);
      bStart = random(10, 30);
    }

    // Couleur de fin : se fond dans l'éther supérieur
    let hEnd = random(215, 245);
    let sEnd = random(10, 35);
    let bEnd = random(85, 100);

    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;
      let normY = constrain(y / height, 0, 1);

      // L'ordre (en bas) cède la place à la dérive (en haut)
      let orderFactor = pow(normY, 2.2); // Très structuré en bas, libre en haut

      // Force 1 : Tourbillon géométrique (la tension qui maintient le corps)
      let dx = x - coreX;
      let dy = y - coreY;
      let distCore = sqrt(dx * dx + dy * dy);
      let swirlAngle = atan2(dy, dx) + HALF_PI + sin(distCore * 0.025) * 0.6;

      // Attraction vers une symétrie axiale (forme quasi-humaine ou végétale)
      let spinePull = (coreX - x) * 0.008 * orderFactor;

      // Force 2 : Le champ de bruit (le vent de l'entropie)
      let nScale = map(normY, 1, 0, 0.003, 0.0012);
      let nVal = noise(x * nScale, y * nScale, i * 0.0005);
      let windAngle = map(nVal, 0, 1, -PI * 1.2, -PI * -0.2) - HALF_PI;

      // Combinaison des forces : de la forme close vers l'ouverture
      let finalAngle;
      if (distCore < 280 && y > coreY - 180) {
        let localOrder = map(distCore, 0, 280, 0.85, 0.2);
        finalAngle = lerpAngle(windAngle, swirlAngle, localOrder);
      } else {
        finalAngle = lerpAngle(windAngle, -HALF_PI, 0.25);
      }

      // Déplacement
      let vx = cos(finalAngle) * stepSize + spinePull;
      let vy = sin(finalAngle) * stepSize;

      // Accélération douce vers le haut à mesure que la matière s'allège
      vy -= (1 - normY) * 1.2;

      // Turbulence de dissolution (les bords s'effilochent)
      let fray = pow(1 - normY, 2.5) * 4.5;
      vx += random(-fray, fray);
      vy += random(-fray, fray);

      let nextX = x + vx;
      let nextY = y + vy;

      // Évolution de la couleur et de l'opacité
      let cMix = pow(progress, 0.85);
      let h = lerpHue(hStart, hEnd, cMix);
      let s = lerp(sStart, sEnd, cMix);
      let b = lerp(bStart, bEnd, cMix);

      let alpha = sin(progress * PI) * map(normY, 0, 1, 4, 22);
      let sw = map(progress, 0, 1, random(1.2, 2.8), 0.3);

      stroke(h, s, b, alpha);
      strokeWeight(sw);
      line(x, y, nextX, nextY);

      // Éclatement sporadique en spores/particules lors de la montée
      if (random(1) < 0.004 && normY < 0.65) {
        noStroke();
        fill(h, s * 0.7, 100, alpha * 3);
        let pSize = random(1.5, 4.5);
        ellipse(nextX + random(-15, 15), nextY + random(-15, 15), pSize, pSize);
      }

      x = nextX;
      y = nextY;

      if (y < -50 || x < -50 || x > width + 50) break;
    }
  }
}

function drawCoreAndFracture() {
  let coreX = width * 0.5;
  let coreY = height * 0.75;

  // Les racines d'ombre (l'ancrage terrestre qui se détache)
  for (let i = 0; i < 350; i++) {
    let x = coreX + random(-180, 180);
    let y = coreY + random(-40, 150);
    stroke(285, 85, 5, random(15, 45));
    strokeWeight(random(1, 5));
    noFill();
    beginShape();
    for (let j = 0; j < 40; j++) {
      vertex(x, y);
      let n = noise(x * 0.008, y * 0.008, i);
      x += cos(n * TWO_PI) * 4;
      y += sin(n * TWO_PI) * 3 + 2.5; // Coule vers le bas
    }
    endShape();
  }

  // Le vaisseau fracturé : des anneaux d'or et de cendre brisés au cœur
  noFill();
  for (let i = 0; i < 450; i++) {
    let r = random(15, 240);
    let a1 = random(TWO_PI);
    let a2 = a1 + random(0.05, 0.9);

    // Décalage vertical pour donner une forme de chrysalide ou de cage thoracique
    let yOff = map(r, 15, 240, 0, -60) + random(-25, 25);
    let xOff = random(-20, 20);

    // L'ouverture au sommet : les arcs supérieurs sont brisés et absents
    if (sin((a1 + a2) * 0.5) < -0.3 && r > 60 && random(1) < 0.75) continue;

    let isGold = random(1) < 0.4;
    if (isGold) {
      stroke(random(30, 50), random(60, 90), random(80, 100), random(15, 50));
      strokeWeight(random(0.8, 2.5));
    } else {
      stroke(275, 75, 8, random(30, 70));
      strokeWeight(random(1.5, 4.5));
    }

    arc(coreX + xOff, coreY + yOff, r * 2.1, r * 1.5, a1, a2);
  }

  // L'étincelle centrale : le dernier point de conscience avant l'expansion
  blendMode(ADD);
  noStroke();
  for (let r = 180; r > 0; r -= 4) {
    let a = map(r, 0, 180, 12, 0);
    fill(38, 75, 100, a);
    ellipse(coreX, coreY - 20, r * 1.2, r * 0.9);
  }

  // La brèche blanche (la rupture silencieuse)
  stroke(45, 20, 100, 70);
  strokeWeight(1.5);
  noFill();
  for (let i = 0; i < 12; i++) {
    let x = coreX + random(-10, 10);
    let y = coreY + random(-10, 10);
    beginShape();
    for (let s = 0; s < 60; s++) {
      vertex(x, y);
      x += random(-6, 6) + (coreX - x) * 0.02;
      y -= random(2, 8);
    }
    endShape();
  }
  blendMode(BLEND);
}

function drawStardust() {
  // Particules libérées qui montent et peuplent le silence
  noStroke();
  for (let i = 0; i < 4500; i++) {
    let normY = pow(random(1), 1.4); // Plus dense vers le haut et le milieu
    let y = normY * height;

    // Répartition en sablier / colonne ascendante qui s'évase
    let spread = map(normY, 0, 1, width * 0.65, 220);
    let x = width * 0.5 + randomGaussian() * spread * 0.55;

    if (x < 0 || x > width) continue;

    let n = noise(x * 0.005, y * 0.005);
    if (random(1) > n * 1.4) continue;

    let size = random(0.8, 3.8);
    let isBright = random(1) < 0.15;

    if (isBright) {
      // Poussière d'or et d'étoiles
      let h = lerp(40, 210, 1 - normY);
      let s = lerp(80, 15, 1 - normY);
      let a = map(normY, 0, 1, 70, 95) * random(0.4, 1);

      // Petit halo autour des particules les plus pures
      fill(h, s, 100, a * 0.25);
      ellipse(x, y, size * 4, size * 4);

      fill(h, s * 0.5, 100, a);
      ellipse(x, y, size, size);
    } else {
      // Cendres douces et matière apaisée
      let h = map(normY, 0, 1, 225, 350);
      let b = map(normY, 0, 1, 95, 40);
      fill(h, 30, b, random(15, 50));
      ellipse(x, y, size * 0.8, size * 0.8);
    }
  }
}

function applyCanvasTexture() {
  // Grain pictural subtil pour lier toutes les couches
  loadPixels();
  for (let x = 0; x < width; x++) {
    for (let y = 0; y < height; y++) {
      let idx = (x + y * width) * 4;

      // Trame de lin légère + bruit organique
      let grain = (random(-1, 1) + sin(x * 0.8) * 0.3 + cos(y * 0.8) * 0.3) * 5.5;

      pixels[idx] = constrain(pixels[idx] + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + grain, 0, 255);
    }
  }
  updatePixels();
}

// Fonctions utilitaires pour des transitions harmonieuses
function lerpAngle(a, b, t) {
  let diff = b - a;
  while (diff < -PI) diff += TWO_PI;
  while (diff > PI) diff -= TWO_PI;
  return a + diff * t;
}

function lerpHue(h1, h2, t) {
  let diff = h2 - h1;
  if (diff > 180) diff -= 360;
  if (diff < -180) diff += 360;
  return (h1 + diff * t + 360) % 360;
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Le Vide Fondamental (Fond)
  drawAbyss();

  // 2. Brumes d'arrière-plan et profondeur cosmique
  drawVeils(140);

  // 3. Le Seuil (L'horizon silencieux entre présence et absence)
  drawThreshold();

  // 4. Le Nœud d'Existence et son Effilochement (Cœur de l'œuvre)
  drawUnravelingCore();

  // 5. L'Architecture Éphémère (Fractures et géométrie qui s'efface)
  drawFadingStructure();

  // 6. Cendres d'Or et Spores de Mémoire
  drawSpores(2200);

  // 7. Texture picturale (Grain de toile et patine)
  applyCanvasTexture();
}

function drawAbyss() {
  // Dégradé vertical du vide : de l'outremer abyssal vers l'obsidienne chaude
  loadPixels();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    // Courbe douce pour la transition
    let easeT = t * t * (3 - 2 * t);

    // Haut : Bleu nuit d'éther (8, 12, 24)
    // Milieu : Gris-violet de cendre (22, 20, 28)
    // Bas : Terre d'ombre brûlée presque noire (10, 7, 6)
    let r, g, b;
    if (t < 0.65) {
      let mt = map(t, 0, 0.65, 0, 1);
      r = lerp(6, 24, mt);
      g = lerp(10, 21, mt);
      b = lerp(22, 30, mt);
    } else {
      let mt = map(t, 0.65, 1, 0, 1);
      r = lerp(24, 8, mt);
      g = lerp(21, 6, mt);
      b = lerp(30, 5, mt);
    }

    for (let x = 0; x < width; x++) {
      // Vignette subtile et variation organique
      let dx = (x - width * 0.5) / (width * 0.5);
      let dy = (y - height * 0.55) / (height * 0.55);
      let distSq = dx * dx + dy * dy;
      let vignette = constrain(1.0 - distSq * 0.35, 0.2, 1.0);

      let n = (noise(x * 0.003, y * 0.003) - 0.5) * 14;

      let idx = (x + y * width) * 4;
      pixels[idx]     = constrain((r + n) * vignette, 0, 255);
      pixels[idx + 1] = constrain((g + n) * vignette, 0, 255);
      pixels[idx + 2] = constrain((b + n) * vignette, 0, 255);
      pixels[idx + 3] = 255;
    }
  }
  updatePixels();
}

function drawVeils(layers) {
  noStroke();
  for (let i = 0; i < layers; i++) {
    let y = random(height * 0.1, height * 0.95);
    let x = random(width * 0.1, width * 0.9);

    // Plus concentré autour de la colonne centrale de dissolution
    x = lerp(x, width * 0.5 + randomGaussian(0, 250), 0.6);

    let w = random(200, 900);
    let h = random(80, 400);
    let angle = (noise(x * 0.002, y * 0.002) - 0.5) * PI * 0.4;

    push();
    translate(x, y);
    rotate(angle);

    // Couleurs selon la hauteur : chaud et dense en bas, froid et éthéré en haut
    let t = y / height;
    if (t > 0.6) {
      fill(65, 38, 28, random(2, 6)); // Ocre sombre / Sang séché
    } else if (t > 0.35) {
      fill(160, 145, 130, random(2, 5)); //Os / Cendre tiède
    } else {
      fill(80, 105, 130, random(2, 6)); // Brume d'éther
    }

    // Forme organique douce
    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.2) {
      let radNoise = noise(cos(a) * 1.5 + i, sin(a) * 1.5 + i);
      let rx = cos(a) * w * 0.5 * radNoise;
      let ry = sin(a) * h * 0.5 * radNoise;
      curveVertex(rx, ry);
    }
    endShape(CLOSE);
    pop();
  }
}

function drawThreshold() {
  // Une lueur horizontale diffuse où la forme bascule dans l'informe
  let horizonY = height * 0.64;

  blendMode(ADD);
  for (let i = 0; i < 180; i++) {
    let y = horizonY + randomGaussian(0, 80);
    let x = width * 0.5 + randomGaussian(0, 350);
    let w = random(100, 700);
    let h = random(4, 35);

    let distFromCenter = abs(x - width * 0.5) / (width * 0.5);
    let alpha = (1 - distFromCenter) * random(1.5, 4.5);

    if (random() < 0.6) {
      fill(210, 165, 105, alpha); // Or pâle
    } else {
      fill(130, 150, 175, alpha); // Argent froid
    }
    noStroke();
    ellipse(x, y, w, h);
  }
  blendMode(BLEND);
}

function drawUnravelingCore() {
  // Des milliers de fils représentant la trame d'une vie qui se dénoue vers le haut
  let numStrands = 3400;
  let coreX = width * 0.5;
  let coreY = height * 0.68;

  for (let i = 0; i < numStrands; i++) {
    // Origine dans le "nœud" dense inférieur
    let angle = random(TWO_PI);
    let radius = abs(randomGaussian(0, 140));
    let startX = coreX + cos(angle) * radius * 1.1;
    let startY = coreY + sin(angle) * radius * 0.65;

    let x = startX;
    let y = startY;

    // Propriétés du fil
    let maxSteps = int(random(80, 420));
    let isGolden = random() < 0.22;
    let isDarkVein = random() < 0.18;
    let strandSeed = random(10000);

    noFill();

    for (let s = 0; s < maxSteps; s++) {
      let progress = s / maxSteps;
      let prevX = x;
      let prevY = y;

      // Champ de force :
      // Près du cœur, force centripète / tourbillonnaire (la vie qui retient)
      // Plus on monte ou s'éloigne, plus la dérive verticale et le bruit dominent (la mort qui délie)
      let dx = x - coreX;
      let dy = y - coreY;
      let distCore = sqrt(dx * dx + dy * dy);

      let n1 = noise(x * 0.0025, y * 0.0025, strandSeed * 0.01);
      let n2 = noise(x * 0.008 + 500, y * 0.008 + 500);

      // Angle de flux vers le haut avec turbulence
      let flowAngle = -HALF_PI + (n1 - 0.5) * PI * 1.9 + (n2 - 0.5) * 0.8;

      // Tension circulaire autour du noyau si proche
      let orbitAngle = atan2(dy, dx) + HALF_PI * (i % 2 === 0 ? 1 : -1);
      let pullFactor = constrain(map(distCore, 0, 260, 0.75, 0), 0, 0.75);
      pullFactor *= (1.0 - progress * 0.8); // Se relâche avec le temps

      // Combinaison des vecteurs
      let vx = lerp(cos(flowAngle), cos(orbitAngle), pullFactor);
      let vy = lerp(sin(flowAngle), sin(orbitAngle), pullFactor);

      // Accélération douce vers le haut (lévitation / évaporation)
      vy -= (1.0 - pullFactor) * 0.45;
      // Légère expansion latérale en haut
      if (y < coreY - 150) {
        vx += (dx / width) * 0.6;
      }

      let stepLen = map(progress, 0, 1, 1.8, 3.8);
      x += vx * stepLen;
      y += vy * stepLen;

      // Couleur et opacité évoluant le long du fil
      let alpha = sin(progress * PI); // Apparaît et s'évanouit
      let heightFactor = constrain(map(y, height * 0.85, height * 0.1, 0, 1), 0, 1);

      let r, g, b, a;
      if (isDarkVein) {
        // Les ombres intimes, le poids de la matière qui reste en bas
        r = lerp(18, 45, heightFactor);
        g = lerp(12, 38, heightFactor);
        b = lerp(15, 48, heightFactor);
        a = alpha * (1 - heightFactor * 0.7) * 55;
      } else if (isGolden) {
        // L'étincelle vitale, la mémoire précieuse qui se change en lumière froide
        r = lerp(235, 160, heightFactor);
        g = lerp(175, 195, heightFactor);
        b = lerp(95, 220, heightFactor);
        a = alpha * 42;
      } else {
        // Le souffle d'ivoire et de cendre
        r = lerp(150, 225, pow(heightFactor, 0.7));
        g = lerp(125, 220, pow(heightFactor, 0.7));
        b = lerp(110, 230, pow(heightFactor, 0.7));
        a = alpha * 28;
      }

      stroke(r, g, b, a);
      strokeWeight(map(progress, 0, 1, 1.9, 0.35));
      line(prevX, prevY, x, y);
    }
  }

  // Halo de silence au centre même du déliement (ni plein, ni vide)
  noStroke();
  for (let r = 280; r > 0; r -= 4) {
    let t = r / 280;
    // Cœur sombre mais nimbé d'ivoire
    if (t > 0.35) {
      fill(235, 220, 195, (1 - t) * 3.5);
    } else {
      fill(14, 11, 15, (1 - t / 0.35) * 18);
    }
    ellipse(coreX, coreY + 15, r * 1.3, r * 0.95);
  }
}

function drawFadingStructure() {
  // Des arcs géométriques très fins, comme les vestiges d'une cathédrale ou d'un corps mesuré,
  // interrompus et dissous par le passage.
  let cx = width * 0.5;
  let cy = height * 0.68;

  noFill();
  for (let i = 0; i < 16; i++) {
    let rad = 90 + i * 48 + random(-15, 15);
    let weight = random(0.4, 1.2);
    strokeWeight(weight);

    // Dessiner l'anneau par petits segments discontinus
    let a = 0;
    while (a < TWO_PI) {
      let segLen = random(0.02, 0.25);
      // Moins de structure dans la partie supérieure (là où la mort a déjà dissous la forme)
      let midA = a + segLen * 0.5;
      let isTop = sin(midA) < -0.2;

      if (random() < (isTop ? 0.25 : 0.65)) {
        let alpha = map(i, 0, 16, 45, 8) * random(0.5, 1.2);
        if (isTop) alpha *= 0.4;
        stroke(215, 198, 175, alpha);

        beginShape();
        for (let sa = a; sa < a + segLen; sa += 0.02) {
          // Légère déformation par le bruit
          let n = noise(cos(sa) * 2 + i, sin(sa) * 2 + i) * 18;
          let x = cx + cos(sa) * (rad + n);
          let y = cy + sin(sa) * (rad * 0.85 + n) - (isTop ? pow(abs(sin(sa)), 3) * i * 12 : 0);
          vertex(x, y);
        }
        endShape();
      }
      a += segLen + random(0.05, 0.35);
    }
  }

  // Quelques lignes d'aplomb (gravité, temps) qui s'effacent
  for (let i = 0; i < 45; i++) {
    let x = cx + randomGaussian(0, 280);
    let y1 = random(height * 0.2, height * 0.85);
    let len = random(40, 280);
    let y2 = y1 + len;

    let distC = abs(x - cx) / 500;
    let alpha = constrain((1 - distC) * random(8, 30), 0, 35);

    stroke(200, 190, 175, alpha);
    strokeWeight(random(0.3, 0.9));

    // Ligne pointillée organique
    for (let y = y1; y < y2; y += 3) {
      if (noise(x * 0.01, y * 0.02) > 0.38) {
        point(x + (noise(y * 0.05, i) - 0.5) * 3, y);
      }
    }
  }
}

function drawSpores(count) {
  // Poussière d'or, cendres blanches et éclats d'âme s'élevant dans le calme
  noStroke();
  for (let i = 0; i < count; i++) {
    // Distribution en colonne évasée vers le haut (forme de calice ou de sablier ouvert)
    let y = random(height * 0.04, height * 0.92);
    let t = 1.0 - (y / height); // 0 en bas, 1 en haut

    let spread = lerp(160, 520, pow(t, 1.4));
    let x = width * 0.5 + randomGaussian(0, spread);

    // Déplacement par le même champ de bruit pour la cohérence
    let n = noise(x * 0.003, y * 0.003);
    x += (n - 0.5) * 120;

    let sz = random(0.8, 3.8);
    let isBright = random() < 0.12;

    if (isBright) {
      // Lueur diffuse autour des particules d'or/mémoire
      let glowR = sz * random(4, 10);
      fill(240, 200, 130, random(8, 22));
      ellipse(x, y, glowR, glowR);
      fill(255, 245, 220, random(140, 230));
      ellipse(x, y, sz * 1.2, sz * 1.2);
    } else {
      // Cendre douce ou brume
      let c = lerpColor(color(180, 145, 115), color(210, 225, 240), t);
      fill(red(c), green(c), blue(c), random(20, 110) * (1 - abs(x - width*0.5)/(width*0.55)));
      ellipse(x, y, sz, sz * random(0.8, 1.6));
    }
  }

  // Racines d'ombre en bas : la matière lourde qui retourne à l'humus
  stroke(8, 5, 4, 40);
  noFill();
  for (let i = 0; i < 450; i++) {
    let x = width * 0.5 + randomGaussian(0, 260);
    let y = random(height * 0.66, height * 0.96);
    strokeWeight(random(0.6, 2.5));
    beginShape();
    for (let s = 0; s < 35; s++) {
      vertex(x, y);
      let angle = HALF_PI + (noise(x * 0.006, y * 0.006, i) - 0.5) * 2.2;
      x += cos(angle) * 3;
      y += sin(angle) * 3;
    }
    endShape();
  }
}

function applyCanvasTexture() {
  // Donne la matérialité d'une peinture à l'huile et à la cendre sur toile
  loadPixels();
  let w = width;
  let h = height;

  for (let y = 0; y < h; y++) {
    // Trame horizontale subtile de la toile
    let weaveY = sin(y * 1.5) * 2.2;
    for (let x = 0; x < w; x++) {
      let weaveX = sin(x * 1.5) * 2.2;
      let grain = (random() - 0.5) * 12 + (weaveX + weaveY) * 0.6;

      let idx = (x + y * w) * 4;
      pixels[idx]     = constrain(pixels[idx] + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(HSB, 360, 100, 100, 100);
