function draw() {
  randomSeed(1);
  noiseSeed(1);
  field();
  dayRemains();
  encroaching();
  presence();
  hold();
  threads();
  threshold();
  motes();
  buried();
  sediment();
  lastContour();
  glazes();
  grain();
  edges();
}

function spineX(y) {
  let t = constrain((y - 300) / 1120, 0, 1);
  return 760 - t * 90 + sin(t * 2.1) * 22;
}

function halfWidth(t) {
  if (t < 0.07) return lerp(0, 46, t / 0.07);
  if (t < 0.2) return lerp(46, 96, (t - 0.07) / 0.13);
  if (t < 0.46) return lerp(96, 108, (t - 0.2) / 0.26);
  if (t < 0.6) return lerp(108, 40, (t - 0.46) / 0.14);
  return lerp(40, 300, pow((t - 0.6) / 0.4, 0.72));
}

function field() {
  for (let y = 0; y < height; y++) {
    let t = y / (height - 1);
    let n = noise(0.2, y * 0.0032);
    let u = constrain(t + (n - 0.5) * 0.02, 0, 1);
    let h, s, b;
    if (u < 0.46) {
      let k = u / 0.46;
      h = lerp(36, 10, k);
      s = lerp(9, 24, pow(k, 0.9));
      b = lerp(95, 52, pow(k, 1.05));
    } else if (u < 0.72) {
      let k = (u - 0.46) / 0.26;
      h = lerp(10, 262, k);
      s = lerp(24, 30, k);
      b = lerp(52, 12, pow(k, 0.95));
    } else {
      let k = (u - 0.72) / 0.28;
      h = lerp(262, 26, k * 0.65);
      s = lerp(30, 18, k);
      b = lerp(12, 4.2, k);
    }
    stroke(h, s, b, 100);
    strokeWeight(1);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = random(height * 0.5);
    let n = noise(x * 0.0016, y * 0.0022);
    fill(28 + n * 18, 8 + n * 14, 88 - n * 22, 1.6);
    ellipse(x, y, random(50, 220), random(6, 28));
  }
}

function dayRemains() {
  noStroke();
  for (let i = 0; i < 46; i++) {
    fill(34, 12, 94, 2.4);
    ellipse(430 + random(-30, 30), 250 + random(-20, 20), random(380, 760), random(260, 520));
  }
  for (let i = 0; i < 18; i++) {
    fill(12, 18, 78, 1.8);
    ellipse(1180, 210, random(200, 480), random(80, 180));
  }
  for (let i = 0; i < 90; i++) {
    let y = random(80, 860);
    let fade = constrain(1 - (y - 520) / 340, 0, 1);
    stroke(32, 16, 90, 3.5 * fade);
    strokeWeight(random(0.6, 2.2));
    let x1 = random(0, 80);
    line(x1, y, x1 + random(180, 620) * fade, y + random(-1, 1));
  }
  noStroke();
  for (let i = 0; i < 30; i++) {
    fill(22, 20, 86, 1.5);
    ellipse(180, lerp(200, 980, i / 29), random(160, 340), random(40, 120));
  }
}

function encroaching() {
  noStroke();
  for (let i = 0; i < 40; i++) {
    fill(248, 22, 8, 2.8);
    ellipse(width + 40 - i * 6, 760 + random(-80, 220), 780 + i * 16, 1280 + random(-40, 40));
  }
  blendMode(MULTIPLY);
  fill(255, 18, 48, 22);
  ellipse(1120, 980, 980, 760);
  fill(230, 16, 42, 18);
  ellipse(860, 1320, 1280, 560);
  blendMode(BLEND);
}

function presence() {
  noFill();
  for (let i = 0; i < 3600; i++) {
    let t = pow(random(), 0.9);
    let y = lerp(300, 1460, t);
    let cx = spineX(y);
    let hw = halfWidth(t);
    let side = random(-1, 1);
    side = Math.sign(side) * pow(abs(side), 0.72);
    let x = cx + side * hw * random(0.08, 1);
    let rightness = constrain((x - cx) / (hw + 0.001), -1, 1);
    let fail = constrain(pow(t, 1.05) * 0.85 + max(0, rightness) * 0.5, 0, 1);
    let a = lerp(15, 0.35, pow(fail, 1.1));
    a *= lerp(1, 0.22, max(0, rightness));
    if (t < 0.09) a *= t / 0.09;
    let h = lerp(36, 268, pow(t, 1.15) * 0.5);
    if (rightness > 0.15) h = lerp(h, 255, rightness * fail);
    let s = lerp(14, 24, t);
    let b = lerp(98, 20, pow(fail, 0.92));
    let len = random(12, 40) * lerp(1.1, 0.35, t);
    stroke(h, s, b, a);
    strokeWeight(random(0.45, 2.3));
    let ang = -HALF_PI + (noise(x * 0.008, y * 0.008) - 0.5) * (0.35 + t * 1.5);
    ang += max(0, rightness) * t * 0.8;
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  for (let i = 0; i < 420; i++) {
    let t = random(0.12, 0.52);
    let y = lerp(300, 1460, t);
    let cx = spineX(y);
    let x = cx - halfWidth(t) * random(0.5, 1.05);
    stroke(8, 24, 30, random(1.6, 5.5));
    strokeWeight(random(1, 3.2));
    line(x, y, x + random(-8, 3), y + random(14, 36));
  }

  noStroke();
  for (let i = 0; i < 80; i++) {
    let t = random(0.08, 0.5);
    let y = lerp(300, 1460, t);
    let cx = spineX(y);
    let hw = halfWidth(t);
    fill(34, 12, 96, random(1.1, 2.8));
    ellipse(cx + random(-hw * 0.25, hw * 0.12), y, hw * random(0.7, 1.45), random(36, 100));
  }
  for (let i = 0; i < 16; i++) {
    let y = lerp(430, 760, i / 15);
    fill(6, 26, 62, 2.2);
    ellipse(spineX(y) - 18, y, random(36, 80), random(40, 90));
  }
}

function hold() {
  let x = spineX(545);
  let y = 548;
  noStroke();
  for (let i = 0; i < 22; i++) {
    fill(36, 10, 99, 4.2);
    ellipse(x + random(-10, 10), y + random(-16, 14), random(28, 86), random(36, 100));
  }
  for (let i = 0; i < 10; i++) {
    fill(8, 30, 68, 3.4);
    ellipse(x - 20 + random(-8, 8), y + 12, random(18, 46), random(22, 54));
  }
  for (let i = 0; i < 8; i++) {
    fill(40, 8, 100, 5);
    ellipse(x + random(-4, 4), y + random(-6, 4), random(8, 18), random(16, 34));
  }
}

function threads() {
  for (let i = 0; i < 56; i++) {
    let x = spineX(530) + random(-30, 22);
    let y = 530 + random(-10, 24);
    for (let s = 0; s < 46; s++) {
      let t = s / 45;
      let a = lerp(11, 0, pow(t, 0.85)) * random(0.7, 1);
      stroke(lerp(36, 250, t * 0.7), lerp(18, 16, t), lerp(92, 24, t), a);
      strokeWeight(lerp(1.15, 0.25, t));
      let drift = (noise(i * 0.2, t * 1.8) - 0.42) * lerp(6, 34, pow(t, 1.2));
      let x2 = x + drift + t * 1.4;
      let y2 = y + lerp(10, 26, t);
      line(x, y, x2, y2);
      x = x2;
      y = y2;
      if (y > 1680) break;
    }
  }
}

function threshold() {
  noStroke();
  for (let i = 0; i < 24; i++) {
    fill(32, 10, 72, 1.7);
    ellipse(760, 1160 + i * 2, 1500 - i * 18, 70 + i * 8);
  }
  for (let i = 0; i < 10; i++) {
    fill(255, 12, 16, 2.4);
    ellipse(980, 1210, 700, 90 + i * 10);
  }
}

function motes() {
  noStroke();
  for (let i = 0; i < 12000; i++) {
    let t = pow(random(), 0.7);
    let y = lerp(1000, 1972, t);
    let spread = lerp(24, 860, pow(t, 0.62));
    let cx = lerp(spineX(1040), 740, t);
    let x = cx + random(-1, 1) * spread * (0.2 + random() * 0.8);
    if (random() < t * 0.64) x = random(24, width - 24);
    x = constrain(x, 6, width - 6);
    let h = lerp(40, 236, pow(t, 0.8));
    let s = lerp(34, 12, t);
    let b = lerp(88, 9, pow(t, 0.76));
    let a = lerp(20, 2.4, t) * random(0.35, 1);
    if (t < 0.32 && random() < 0.07) {
      b = 96;
      a = 16;
    }
    fill(h, s, b, a);
    let d = lerp(2.5, 0.55, t) * random(0.55, 1.35);
    ellipse(x, y, d, d * random(0.65, 1.55));
  }
  for (let i = 0; i < 180; i++) {
    fill(38, 26, random(36, 62), random(4, 9));
    ellipse(random(80, width - 80), random(1500, 1940), random(0.8, 1.8), random(0.8, 1.8));
  }
}

function buried() {
  noStroke();
  let spots = [
    [380, 1690, 280, 74],
    [690, 1768, 340, 90],
    [1010, 1710, 250, 66],
    [1240, 1830, 300, 86],
    [230, 1855, 190, 52],
    [860, 1904, 460, 74],
    [540, 1636, 160, 42],
    [1080, 1608, 140, 36]
  ];
  for (let s = 0; s < spots.length; s++) {
    let p = spots[s];
    for (let i = 0; i < 9; i++) {
      fill(26, 18, random(8, 15), random(3.5, 6.5));
      ellipse(p[0] + random(-14, 14), p[1] + random(-6, 6), p[2] * random(0.82, 1.06), p[3] * random(0.75, 1.12));
    }
  }
}

function sediment() {
  for (let i = 0; i < 170; i++) {
    let t = i / 169;
    let y = lerp(1520, 1970, pow(t, 0.8)) + (noise(i * 0.17, 11) - 0.5) * 7;
    let longMark = random() > 0.35;
    let x1 = longMark ? random(-10, 160) : random(40, width - 200);
    let x2 = longMark ? random(width * 0.45, width + 10) : x1 + random(40, 280);
    stroke(lerp(30, 22, t), lerp(16, 10, t), lerp(20, 6, t), lerp(4, 13, t) * random(0.6, 1));
    strokeWeight(random(0.6, 2.8));
    line(x1, y, x2, y + random(-1.5, 1.5));
  }
}

function lastContour() {
  let cx = 690;
  let cy = 1496;
  let rx = 228;
  let ry = 72;
  for (let a = 0.5; a < 4.7; a += 0.01) {
    let nearGap = a > 2.05 && a < 2.95;
    if (nearGap && random() < 0.86) continue;
    if (random() < 0.18) continue;
    let jx = noise(a * 2.2, 3.1) * 18 - 9;
    let jy = noise(a * 2.2, 6.4) * 14 - 7;
    let fade = 1;
    if (a < 0.95) fade = (a - 0.5) / 0.45;
    if (a > 4.15) fade = (4.7 - a) / 0.55;
    if (a > 1.75 && a <= 2.05) fade *= (2.05 - a) / 0.3;
    if (a >= 2.95 && a < 3.3) fade *= (a - 2.95) / 0.35;
    stroke(38, 18, 76, 14 * fade * random(0.5, 1));
    strokeWeight(random(0.7, 1.7));
    let a2 = a + 0.028;
    line(cx + cos(a) * rx + jx, cy + sin(a) * ry + jy, cx + cos(a2) * rx + jx * 0.9, cy + sin(a2) * ry + jy * 0.9);
  }
}

function glazes() {
  noStroke();
  for (let i = 0; i < 18; i++) {
    fill(random(18, 42), random(6, 16), random(30, 80), random(0.8, 2.2));
    ellipse(random(width), random(height), random(180, 640), random(320, 1100));
  }
  blendMode(SCREEN);
  fill(34, 8, 70, 5);
  ellipse(520, 520, 420, 640);
  blendMode(BLEND);
}

function grain() {
  for (let i = 0; i < 28000; i++) {
    stroke(random(16, 46), random(4, 18), random(8, 92), random(1.6, 6.5));
    strokeWeight(random(0.35, 1.25));
    point(random(width), random(height));
  }
}

function edges() {
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 5; i++) {
    fill(225, 12, 58, 9);
    ellipse(-90, -30, 1200, 900);
    ellipse(width + 70, -10, 1080, 820);
    ellipse(-120, height + 30, 1500, 980);
    ellipse(width + 90, height + 10, 1400, 1040);
  }
  blendMode(BLEND);
  noStroke();
  for (let y = 1880; y < height; y++) {
    let k = (y - 1880) / (height - 1880);
    stroke(24, 16, lerp(8, 3, k), 18);
    line(0, y, width, y);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  underpaint();
  paintField();
  membrane();
  erased();
  lastLight();
  glow();
  descent();
  closing();
  shroud();
  sediment();
  knife();
  dustSkin();
  fissures();
  vignette();
  ash();
  sheen();
}

function underpaint() {
  noFill();
  for (let y = 0; y < height; y++) {
    let ny = y / height;
    let r = lerp(8, 24, ny);
    let g = lerp(9, 14, ny);
    let b = lerp(16, 11, ny);
    let band = Math.exp(-Math.pow((y - 860) / 260, 2));
    r += band * 26;
    g += band * 12;
    b += band * 3;
    stroke(r, g, b);
    line(0, y, width, y);
  }
  noStroke();
}

function paintField() {
  noStroke();
  for (let i = 0; i < 1100; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0011, y * 0.0011);
    let ny = y / height;
    let r = 14 + n * 20 + ny * 16;
    let g = 11 + n * 12 + ny * 6;
    let b = 16 + (1 - ny) * 14;
    if (x > width * 0.62) {
      r -= 4;
      b += 6;
    }
    if (ny > 0.66) {
      r += (ny - 0.66) * 36;
      g += (ny - 0.66) * 12;
    }
    fill(r, g, b, 14 + random(20));
    push();
    translate(x, y);
    rotate(random(-0.4, 0.4));
    ellipse(0, 0, random(90, 420), random(28, 160));
    pop();
  }
}

function membrane() {
  noStroke();
  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = 820 + (noise(x * 0.002, i * 0.01) - 0.5) * 180;
    let fall = Math.abs(y - 850) / 240;
