function lastLight() {
  noStroke();
  let cx = 720;
  let cy = 880;
  for (let i = 0; i < 2400; i++) {
    let ang = random(TWO_PI);
    let rad = Math.pow(random(), 0.52) * 250;
    let x = cx + Math.cos(ang) * rad * random(0.65, 1.3);
    let y = cy + Math.sin(ang) * rad * 0.66 + Math.pow(random(), 2) * 80;
