    let s = lerp(26, 3.5, bright) + random(1, 12);
    ellipse(x, y, s * random(0.55, 1.7), s * random(0.3, 0.85));
  }
  for (let i = 0; i < 480; i++) {
    fill(232, 218, 190, random(8, 24));
    ellipse(cx + randomGaussian() * 30, cy + randomGaussian() * 16, random(5, 18), random(2, 8));
