    let a = 6 + n * 10;
    fill(188 + n * 20, 190 + n * 12, 178, a);
    brush(x, y, random(40, 220), random(1.2, 3.2), random(-0.08, 0.08));
  }

  for (let i = 0; i < 160; i++) {
    let x = random(180, 1420);
    let y = random(860, 1280);
    fill(150, 148, 140, random(4, 11));
    brush(x, y, random(30, 160), random(8, 28), random(-0.2, 0.2));
  }

  for (let i = 0; i < 70; i++) {
    let x = random(width);
    let y = random(1280, 1920);
    let k = random();
    fill(70 + k * 30, 36 + k * 10, 28, random(8, 16));
    brush(x, y, random(80, 260), random(24, 70), random(-0.15, 0.15));
  }

  for (let i = 0; i < 520; i++) {
    let y = random(460, 1180);
    let gy = 1180;
    let t = constrain((y - 460) / 720, 0, 1);
    let cx = 628 + (noise(y * 0.004, 4.2) - 0.5) * 46;
    let x = cx + random(-1, 1) * (20 + (1 - t) * 70);
    let len = lerp(18, 90, t) * random(0.6, 1);
    fill(206, 202, 190, lerp(4, 32, t * t));
    brush(x, y, random(1.2, 3.4), len, HALF_PI + random(-0.08, 0.08));
    gy = gy;
  }

  for (let i = 0; i < 9800; i++) {
    let u = random();
    let y = lerp(740, 1480, Math.pow(u, 0.7));
    let nearEarth = constrain((y - 760) / 680, 0, 1);
    let x;
    if (random() < 0.22) {
      x = random(width);
    } else {
      let cx = lerp(740, 610, nearEarth);
      let spread = lerp(680, 86, nearEarth);
      x = cx + random(-spread, spread);
    }
    let warm = random() < nearEarth * 0.78;
    let s = lerp(1.1, 3.6, nearEarth) * random(0.45, 1.15);
    if (warm) {
      fill(108 + random(48), 54 + random(22), 36 + random(10), random(36, 120));
    } else {
      fill(164 + random(36), 162 + random(24), 152 + random(16), random(16, 72) * lerp(0.45, 1, nearEarth));
    }
    rect(x, y, s, s * random(0.7, 1.5));
  }

  for (let i = 0; i < 1400; i++) {
    let y = random(900, 1360);
    let x = 600 + random(-40, 220) + (y - 900) * random(0.05, 0.35);
    let a = random(20, 70) * constrain((1360 - y) / 460, 0, 1);
    fill(150, 142, 130, a);
    brush(x, y, random(1, 2.2), random(8, 34), HALF_PI + random(0.1, 0.55));
  }

  for (let i = 0; i < 700; i++) {
    let x = 548 + random(-20, 54) * random();
    let y = groundY(610) + random(-8, 30);
    let s = random(1.4, 4.2);
    fill(118 + random(36), 62 + random(16), 42, random(50, 140));
    rect(x, y, s * random(1, 2.4), s);
  }
  for (let i = 0; i < 380; i++) {
    let x = 610 + random(0, 150) * random();
    let y = groundY(640) + random(0, 48);
    fill(132, 96, 72, random(18, 55));
    rect(x, y, random(1, 2.4), random(1.4, 3.6));
  }

  for (let i = 0; i < 2400; i++) {
    let x = random(width);
    let gy = groundY(x);
    let y = gy + random(8, 520) * random();
    if (y > height - 10) continue;
    let roll = random();
    if (roll < 0.18) fill(28, 16, 14, random(40, 100));
    else if (roll < 0.55) fill(92, 48, 34, random(30, 90));
    else fill(64, 36, 28, random(24, 70));
    rect(x, y, random(1.5, 5), random(1.2, 3.5));
  }

  for (let i = 0; i < 640; i++) {
    let x = random(width);
    let gy = groundY(x);
    let y = gy + random(-5, 12);
    if (random() < 0.72) fill(154, 150, 140, random(16, 46));
    else fill(96, 58, 42, random(20, 54));
    rect(x, y, random(8, 34), random(1, 2.2));
  }

  for (let i = 0; i < 180; i++) {
    let x = random(200, 1500);
    let y = random(1500, 1860);
    let dx = (x - 990) / 240;
    let dy = (y - 1640) / 200;
    if (dx * dx + dy * dy > 1) continue;
    fill(124, 58, 40, random(6, 14));
    brush(x, y, random(40, 120), random(16, 40), random(-0.4, 0.4));
  }

  for (let i = 0; i < 420; i++) {
    let x = random(width);
    let y = random(height);
    let dx = (x - 760) / 820;
    let dy = (y - 820) / 1040;
    let d = dx * dx * 0.85 + dy * dy;
    if (d < 0.42) continue;
    fill(6, 5, 7, random(10, 28));
    brush(x, y, random(60, 220), random(40, 140), random(-0.2, 0.2));
  }
}

function brush(x, y, len, thick, ang) {
  push();
  translate(x, y);
  rotate(ang);
  rectMode(CENTER);
  rect(0, 0, len, thick, thick);
  pop();
  rectMode(CORNER);
}

function groundY(x) {
  let n1 = noise(x * 0.0014, 2.2);
  let n2 = noise(x * 0.0058, 7.4);
  let n3 = noise(x * 0.019, 1.3);
  let rough = x < 860 ? 1 : lerp(1, 0.22, constrain((x - 860) / 620, 0, 1));
  let ridge = Math.exp(-Math.pow((x - 590) / 460, 2)) * 130;
  let shelf = Math.exp(-Math.pow((x - 1120) / 260, 2)) * 28;
  return 1340 - n1 * 64 - rough * (n2 * 42 + n3 * 18) - ridge - shelf;
}

function columnMask(x, y) {
  let cx = 628 + (noise(y * 0.0035, 4.2) - 0.5) * 50;
  let wid = 54 + Math.max(0, 1120 - y) * 0.11;
  let dx = x - cx;
  return Math.exp(-(dx * dx) / (2 * wid * wid));
}

function fieldColor(x, y) {
  let yn = y / 2000;
  let xn = x / 1600;
  let n = noise(x * 0.0013, y * 0.0013);
  let n2 = noise(x * 0.0036 + 9.0, y * 0.0024 + 3.0);
  let gy = groundY(x);
  let topDark = smoothstep(0.2, 0.0, yn);
  let pale = smoothstep(0.06, 0.18, yn) * smoothstep(0.48, 0.28, yn);
  let col = columnMask(x, y);

  let r = 16;
  let g = 15;
  let b = 18;
  r = lerp(r, 8, topDark * 0.85);
  g = lerp(g, 10, topDark * 0.7);
  b = lerp(b, 16, topDark * 0.9);

  let paleAmt = constrain(pale * (0.42 + 0.38 * n + 0.28 * col), 0, 1);
  r = lerp(r, 196 + n2 * 22, paleAmt);
  g = lerp(g, 198 + n * 14, paleAmt);
  b = lerp(b, 186 + n2 * 8, paleAmt);

  let below = smoothstep(gy - 18, gy + 70, y);
  let depth = smoothstep(gy + 40, 1980, y);
  let er = lerp(96 + n * 26, 24, depth);
  let eg = lerp(52 + n2 * 12, 16, depth);
  let eb = lerp(40 + n * 6, 14, depth);
  let pocket = Math.exp(-Math.pow((x - 990) / 240, 2) - Math.pow((y - 1640) / 200, 2));
  er += pocket * 42 * (1 - depth * 0.5);
  eg += pocket * 12;
  eb += pocket * 4;
  r = lerp(r, er, below * 0.92);
  g = lerp(g, eg, below * 0.92);
  b = lerp(b, eb, below * 0.92);

  let rim = Math.exp(-Math.pow((y - gy) / 22, 2)) * below * (0.45 + 0.55 * n2);
  r = lerp(r, 148, rim * 0.28);
  g = lerp(g, 146, rim * 0.32);
  b = lerp(b, 136, rim * 0.38);

  if (y < gy) {
    let rise = constrain((gy - y) / 760, 0, 1);
    let strength = col * (1 - rise) * (1 - rise);
    r = lerp(r, 214, strength * 0.42);
    g = lerp(g, 210, strength * 0.4);
    b = lerp(b, 196, strength * 0.36);
  } else {
    let seam = col * Math.exp(-Math.max(0, y - gy) / 80);
    r = lerp(r, r * 0.55, seam * 0.65);
    g = lerp(g, g * 0.5, seam * 0.7);
    b = lerp(b, b * 0.52, seam * 0.6);
  }

  let floor = smoothstep(0.9, 1, yn);
  r = lerp(r, 6, floor * 0.75);
  g = lerp(g, 5, floor * 0.75);
  b = lerp(b, 6, floor * 0.75);

  let vx = (xn - 0.48) * 1.2;
  let vy = (yn - 0.4) * 1.15;
  let vig = constrain(vx * vx + vy * vy, 0, 1);
  vig = vig * vig;
  r *= 1 - vig * 0.55;
  g *= 1 - vig * 0.55;
  b *= 1 - vig * 0.5;

  let grain = (hash(x, y) - 0.5) * 10;
  return {
    r: constrain(r + grain, 0, 255),
    g: constrain(g + grain * 0.9, 0, 255),
    b: constrain(b + grain * 0.8, 0, 255)
  };
}

function smoothstep(edge0, edge1, x) {
  let t = constrain((x - edge0) / (edge1 - edge0), 0, 1);
  return t * t * (3 - 2 * t);
}

function hash(x, y) {
  let n = Math.sin(x * 127.1 + y * 311.7) * 43758.5453;
  return n - Math.floor(n);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();
}

function seamX(y) {
  let slow = noise(y * 0.00135, 3.7);
  let mid = noise(y * 0.0065, 1.15);
  return 900 + (slow - 0.5) * 78 + (mid - 0.5) * 26 + sin(y * 0.0027) * 14;
}

function coolOf(c) {
  let avg = (c[0] + c[1] + c[2]) / 3;
  return [avg * 0.32 + 46, avg * 0.36 + 54, avg * 0.48 + 68];
}

function draw() {
  background(6, 5, 8);
  drawField();
  drawLeftWarmth();
  drawMasses();
  drawKnots();
  drawShadows();
  drawFibers();
  drawRightVeil();
  drawSeam();
  drawMotes();
  drawVignette();
  drawGrain();
}

function drawField() {
