    let n2 = noise(y * 0.0016, 2.4);
    stroke(20 + n * 16, 12 + n * 8, 9 + n * 5);
    line(0, y, sx, y);
    stroke(7 + n2 * 6, 9 + n2 * 7, 15 + n2 * 11);
    line(sx, y, width, y);
  }
}

