function drawMasses() {
  let masses = [
    [280, 260, 250, 180, 58, 64, 36, 520],
    [500, 540, 300, 210, 116, 60, 32, 760],
    [210, 880, 210, 270, 100, 34, 30, 640],
    [540, 1000, 250, 200, 156, 122, 88, 700],
    [350, 1380, 310, 230, 82, 46, 28, 740],
    [650, 1640, 230, 160, 136, 98, 48, 480],
    [190, 1740, 240, 130, 30, 40, 32, 420],
    [860, 430, 260, 310, 132, 64, 54, 860],
    [905, 1020, 168, 540, 122, 74, 52, 1200],
    [845, 1480, 290, 210, 144, 94, 44, 720],
