    [1340, 1320, 190, 150, 74, 84, 94, 200]
  ];
  for (let i = 0; i < masses.length; i++) {
    let m = masses[i];
    drawMass(m[0], m[1], m[2], m[3], [m[4], m[5], m[6]], m[7]);
  }
}

function drawMass(cx, cy, rx, ry, col, count) {
  for (let i = 0; i < count; i++) {
    let ang = random(TWO_PI);
    let rad = pow(random(), 0.6);
    let x = cx + cos(ang) * rx * rad * random(0.84, 1.1);
    let y = cy + sin(ang) * ry * rad * random(0.88, 1.08);
    if (x < 6 || x > width - 6 || y < 6 || y > height - 6) continue;
    let sx = seamX(y);
    let left = x <= sx;
    if (!left && random() > 0.36) continue;
    let c = left ? col : coolOf(col);
    let a = left ? 14 : 10;
    if (left) {
      let prox = constrain(1 - (sx - x) / 150, 0, 1);
      c = [
        lerp(c[0], 214, prox * 0.38),
        lerp(c[1], 176, prox * 0.22),
        lerp(c[2], 140, prox * 0.12)
      ];
      a += prox * 9;
    }
    let jx = (noise(x * 0.007, y * 0.007) - 0.5) * 18;
    let jy = (noise(x * 0.007 + 5, y * 0.007) - 0.5) * 12;
    noStroke();
    fill(c[0], c[1], c[2], a * (0.55 + 0.6 * (1 - rad)));
    ellipse(x + jx, y + jy, random(8, 28) * (left ? 1 : 0.62), random(4, 14) * (left ? 1 : 0.7));
  }
}

function drawKnots() {
  let knots = [
    [390, 340, 46, 150, 110, 70],
    [600, 700, 34, 170, 90, 50],
    [280, 1040, 40, 140, 48, 36],
    [730, 1100, 62, 220, 170, 120],
    [460, 1460, 38, 160, 100, 48],
    [250, 1660, 28, 90, 70, 40]
  ];
  noStroke();
  for (let k = 0; k < knots.length; k++) {
    let kx = knots[k][0];
    let ky = knots[k][1];
    let kr = knots[k][2];
    let col = [knots[k][3], knots[k][4], knots[k][5]];
    for (let i = 0; i < 180; i++) {
      let ang = random(TWO_PI);
      let r = pow(random(), 0.5) * kr;
      let x = kx + cos(ang) * r * 1.35;
      let y = ky + sin(ang) * r;
      if (x > seamX(y) - 4) continue;
      let fall = 1 - r / kr;
      fill(col[0], col[1], col[2], 6 + fall * 16);
      ellipse(x, y, 4 + fall * 12, 3 + fall * 7);
    }
  }
}

function drawShadows() {
  noStroke();
  let spots = [
    [320, 720, 160, 70],
    [480, 1180, 130, 55],
    [200, 1320, 150, 48],
    [620, 860, 90, 40]
  ];
  for (let s = 0; s < spots.length; s++) {
    for (let i = 0; i < 36; i++) {
      fill(5, 4, 4, 12);
      ellipse(
        spots[s][0] + random(-spots[s][2], spots[s][2]),
        spots[s][1] + random(-spots[s][3], spots[s][3]),
        random(18, 70),
        random(6, 20)
      );
    }
  }
}

function drawFibers() {
  strokeCap(ROUND);
  for (let i = 0; i < 2800; i++) {
    let x = random(width);
    let y = random(height);
    let sx = seamX(y);
    let left = x < sx - 6;
    if (!left && random() > 0.2) continue;
    let ang = left ? random(-0.9, 0.9) + (noise(x * 0.004, y * 0.004) - 0.5) * 1.4 : random(-0.3, 0.3);
    let len = left ? random(8, 34) : random(3, 12);
    if (left) stroke(100 + random(50), 58 + random(28), 32, random(8, 20));
    else stroke(86, 96, 108, random(4, 11));
    strokeWeight(left ? random(0.5, 1.5) : random(0.3, 0.9));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len * 0.55);
  }
}

function drawRightVeil() {
  noStroke();
  for (let i = 0; i < 20; i++) {
    fill(4, 6, 11, 6);
    rect(1060 + i * 22, 0, width, height);
  }
}

function drawSeam() {
  strokeCap(ROUND);
  for (let y = 0; y < height; y += 2) {
    let sx = seamX(y);
    let pulse = 0.38 + 0.62 * pow(sin((y / height) * PI), 0.8);
    let n = noise(y * 0.011, 5.6);
    let half = 3 + n * 13;
    strokeWeight(half * 3.4);
    stroke(186, 196, 204, 7 * pulse);
    line(sx, y, sx, y + 2);
    strokeWeight(half * 1.35);
    stroke(228, 210, 184, 18 * pulse);
    line(sx, y, sx, y + 2);
    strokeWeight(1.5);
    stroke(246, 240, 228, 78 * pulse);
    line(sx, y, sx, y + 2);
    strokeWeight(3);
    stroke(0, 0, 0, 22 * pulse);
    line(sx + half * 0.42, y, sx + half * 0.42, y + 2);
    if (n > 0.8) {
      stroke(176, 90, 68, 36 * pulse);
      strokeWeight(1.6);
      line(sx - 1.5, y, sx + 1, y + 2);
    }
    if (noise(y * 0.047, 9.2) > 0.74) {
      let len = 7 + noise(y * 0.07, 2.2) * 34;
      stroke(206, 164, 122, 16 * pulse);
      strokeWeight(0.7);
      line(sx, y, sx - len, y + (noise(y * 0.02, 1.4) - 0.5) * 7);
    }
    if (noise(y * 0.047, 12.4) > 0.9) {
      let len = 4 + noise(y * 0.08, 3.3) * 14;
      stroke(150, 160, 170, 10 * pulse);
      strokeWeight(0.5);
      line(sx, y, sx + len, y + (noise(y * 0.02, 4.2) - 0.5) * 4);
    }
  }
}

function drawMotes() {
  noStroke();
  for (let i = 0; i < 640; i++) {
    let y = random(40, height - 40);
    let sx = seamX(y);
    let x = sx + random(-30, 210);
    if (x > width - 20) continue;
    let t = constrain((x - sx) / 200, 0, 1);
    let r = lerp(214, 120, t);
    let g = lerp(168, 132, t);
    let b = lerp(118, 148, t);
    fill(r, g, b, lerp(42, 0, t) * random(0.35, 1));
    ellipse(x, y, random(1.1, 3.2), random(1.1, 3.2));
  }
}

function drawVignette() {
  strokeCap(SQUARE);
  for (let i = 0; i < 200; i++) {
    let a = map(i, 0, 200, 30, 0);
    stroke(0, 0, 0, a);
    strokeWeight(1);
    line(0, i, width, i);
    line(0, height - 1 - i, width, height - 1 - i);
    line(i, 0, i, height);
    line(width - 1 - i, 0, width - 1 - i, height);
  }
}

function drawGrain() {
  strokeWeight(1);
  for (let i = 0; i < 42000; i++) {
    if (random() < 0.5) stroke(255, 246, 232, random(3, 8));
    else stroke(0, 0, 0, random(4, 13));
    point(random(width), random(height));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noLoop();

  paintGround();
  paintWarmth();
  paintNight();
  paintHolding();
  paintContour();
  paintFilaments();
  paintExpanse();
  paintEmbers();
  paintGrain();
  paintVignette();
}

function spineX(y) {
  let t = constrain((y - 260) / 1500, 0, 1);
  let x = 730 + (noise(y * 0.00255, 2.2) - 0.5) * 120;
  x += Math.sin(t * 5.1) * 24 * (1 - t * 0.35);
  x += t * t * 70;
  return x;
}

function paintGround() {
  loadPixels();
  const d = pixelDensity();
  const w = width * d;
  const h = height * d;
  for (let y = 0; y < h; y += 2) {
    for (let x = 0; x < w; x += 2) {
      const nx = x / w;
      const ny = y / h;
      const n = noise(x * 0.00135, y * 0.0017);
      const warm = Math.pow(Math.max(0, 1 - ny * 1.12), 1.45) * (1 - nx * 0.58);
      const dusk = Math.max(0, 1 - Math.abs(nx - 0.28) * 1.7) * Math.max(0, 1 - ny * 2.05);
      let r = 7 + n * 9 + warm * 34 + dusk * 52;
      let g = 8 + n * 7 + warm * 15 + dusk * 20;
      let b = 14 + n * 11 + warm * 5 + dusk * 8 + ny * (1 - warm) * 12;
      const sink = ny * 0.55 + Math.max(0, nx - 0.5) * 0.5;
      r *= 1 - sink * 0.64;
      g *= 1 - sink * 0.56;
      b *= 1 - sink * 0.3;
      for (let dy = 0; dy < 2 && y + dy < h; dy++) {
        for (let dx = 0; dx < 2 && x + dx < w; dx++) {
          const i = 4 * ((y + dy) * w + (x + dx));
          pixels[i] = r;
          pixels[i + 1] = g;
          pixels[i + 2] = b;
          pixels[i + 3] = 255;
        }
      }
    }
  }
  updatePixels();
}

function paintWarmth() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    let x = random(60, 920);
    let y = random(30, 620);
    fill(random(150, 205), random(72, 118), random(28, 58), random(3, 9));
    ellipse(x, y, random(160, 620), random(36, 170));
  }
  for (let i = 0; i < 2600; i++) {
    let y = random(16, 760);
    let x = random(20, 1100);
    let nx = x / width;
    let t = y / 860;
    if (random() < nx * 0.45) continue;
    let n = noise(x * 0.0028, y * 0.0036, 5);
    let heat = (1 - t) * (1 - nx * 0.62) * (0.3 + n);
    stroke(150 + heat * 90, 64 + heat * 55, 26 + n * 18, 5 + heat * 20);
    strokeWeight(random(1.2, 6.5));
    let ang = -0.22 + n * 0.55;
    let len = random(24, 170);
    line(x, y, x + Math.cos(ang) * len, y + Math.sin(ang) * len);
  }
}

function paintNight() {
  for (let i = 0; i < 1100; i++) {
    let x = width * 0.56 + random(width * 0.48);
    let y = random(-30, height + 20);
    let ny = y / height;
    let nx = x / width;
    let a = 4 + Math.max(0, nx - 0.52) * 42 + ny * 7;
    stroke(3, 4, 9, a);
    strokeWeight(random(8, 42));
    line(x, y, x + random(-18, 6), y + random(70, 340));
  }
}

function paintHolding() {
  for (let i = 0; i < 2800; i++) {
    let y = random(150, 1160);
    let t = (y - 150) / 1010;
    let edge = spineX(y);
    let x = random(36, Math.max(40, edge - 8));
    let near = 1 - constrain((edge - x) / 300, 0, 1);
    let fade = (1 - t) * (0.3 + near * 0.7);
    if (fade < 0.08) continue;
    if (random() < t * 0.4 && near < 0.35) continue;
    stroke(108 + fade * 100, 52 + fade * 48, 30, 5 + fade * 18);
    strokeWeight(random(0.8, 3.1));
    let h = random(14, 96) * (1 - t * 0.45);
    line(x + random(-1, 1), y, x + random(-2.5, 2.5), y + h);
  }
}

function paintContour() {
  for (let pass = 0; pass < 32; pass++) {
    let prev = null;
    let off = (noise(pass * 0.29, 9.4) - 0.5) * 34;
    for (let y = 250; y <= 1760; y += 4) {
      let t = (y - 250) / 1510;
      let x = spineX(y) + off + (noise(y * 0.009, pass * 0.17) - 0.5) * (6 + t * 46);
      let fray = noise(x * 0.011, y * 0.008, 1.3 + pass * 0.05);
      if (fray < t * 0.52 + Math.abs(off) / 90 * 0.18) {
        prev = null;
        continue;
      }
      let lit = Math.pow(1 - t, 1.18) * (0.5 + noise(pass * 0.4, y * 0.0027));
      stroke(
        lerp(26, 218, lit),
        lerp(24, 158, lit * 0.78),
        lerp(30, 84, lit * 0.42),
        lerp(6, 34, lit) * (1 - t * 0.55)
      );
      strokeWeight(lerp(2.8, 0.35, t) * lerp(0.55, 1.45, noise(pass * 0.33, 3.1)));
      if (prev) line(prev[0], prev[1], x, y);
      prev = [x, y];
    }
  }
}

function paintFilaments() {
  for (let i = 0; i < 900; i++) {
    let y = lerp(300, 1680, Math.pow(random(), 0.85));
    let t = constrain((y - 300) / 1380, 0, 1);
    let x = spineX(y) + random(-8, 14);
    if (random() < t * 0.5) continue;
    let len = lerp(16, 260, t) * random(0.35, 1);
    let drift = random(0.15, 1);
    let x2 = x + len * drift;
    let y2 = y + len * random(-0.05, 0.62);
    let lit = (1 - t) * random(0.35, 1);
    stroke(170 + lit * 50, 96 + lit * 40, 42, 6 + lit * 16);
    strokeWeight(random(0.4, 1.7));
    line(x, y, x2, y2);
    if (random() < 0.45) {
      stroke(150, 110, 70, lit * 10);
      line(x2, y2, x2 + random(8, 40), y2 + random(0, 18));
    }
  }
}

function paintExpanse() {
  noStroke();
  for (let i = 0; i < 28; i++) {
    fill(14, 22, 36, 5);
    ellipse(random(180, 1420), random(1480, 1960), random(420, 1200), random(70, 240));
  }
  for (let i = 0; i < 2200; i++) {
    let y = random(1240, 1975);
    let t = (y - 1240) / 735;
    let x = random(-20, width);
    let n = noise(x * 0.0018, y * 0.012, 4.4);
    stroke(20 + n * 18, 28 + n * 16, 40 + n * 14, 7 + n * 12);
    strokeWeight(random(0.5, 1.8));
    let len = random(50, 280) * (0.55 + t * 0.8);
    let y2 = y + (noise(x * 0.01, y * 0.01) - 0.5) * 5;
    line(x, y, x + len, y2);
  }
  for (let i = 0; i < 700; i++) {
    let y = random(1420, 1880);
    let t = (y - 1420) / 460;
    if (random() < t * 0.62) continue;
    let x = spineX(Math.min(y, 1700)) + random(-30, 40) * (1 + t * 2.4);
    stroke(168, 122, 74, (1 - t) * 16);
    strokeWeight(random(0.4, 1.5));
    line(x, y, x + random(12, 84), y + random(-1.2, 1.2));
  }
}

function paintEmbers() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    let t = Math.pow(random(), 0.72);
    let y = lerp(460, 1840, t);
    let spread = lerp(18, 460, t);
    let x = spineX(y) + random(-spread * 0.25, spread);
    let life = (1 - t) * (0.25 + random() * 0.75);
    if (random() < t * 0.5) life *= 0.22;
    fill(198, 112, 46, life * 16);
    ellipse(x, y, random(3, 12) * (1 - t * 0.45), random(2, 8));
    fill(230, 198, 150, life * 24);
    ellipse(x, y, random(0.8, 2.4), random(0.8, 2.4));
  }
}

function paintGrain() {
  for (let i = 0; i < 36000; i++) {
    stroke(random(255), random(7, 20));
    strokeWeight(1);
    point(random(width), random(height));
  }
}

function paintVignette() {
  noFill();
  for (let i = 0; i < 150; i++) {
    let a = i < 50 ? 11 : 5;
    stroke(0, 0, 0, a);
    strokeWeight(2);
    rect(i, i, width - i * 2, height - i * 2);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(5, 6, 14);

  noStroke();
  for (let y = 0; y < height; y++) {
    let t = y / height;
    stroke(lerp(12, 4, t), lerp(14, 5, t), lerp(30, 9, t));
    line(0, y, width, y);
  }

  const cx = width / 2;
  const cy = height * 0.48;

  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  for (let i = 0; i < 3200; i++) {
    const y = random(0, height);
    const wScale = pow(sin(PI * y / height), 0.65);
    const spread = width * 0.09 * wScale + 12;
    const x = cx + randomGaussian() * spread;
    const r = random(2, 6) * (0.45 + wScale);
    const alpha = random(6, 30) * (0.4 + wScale);
    fill(190, 205, 240, alpha);
    ellipse(x, y, r, r);
  }

  for (let i = 0; i < 700; i++) {
    const y = random(height * 0.55, height * 0.95);
    const wScale = pow(sin(PI * y / height), 0.65);
    const spread = width * 0.07 * wScale + 15;
    const x = cx + randomGaussian() * spread;
    const r = random(1, 3.5);
    fill(205, 170, 120, random(5, 22));
    ellipse(x, y, r, r);
  }

  drawingContext.globalCompositeOperation = 'source-over';
  for (let i = 0; i < 900; i++) {
    const y = random(height * 0.2, height * 0.85);
    const x = random(width);
    const len = random(40, 260);
    stroke(160, 170, 200, random(2, 10));
    strokeWeight(random(0.3, 1.1));
    line(x, y, x + (random() - 0.5) * len * 2, y + random(-6, 6));
  }

  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  for (let i = 0; i < 3500; i++) {
    const x = cx + randomGaussian() * 200 * (0.3 + 0.7 * pow(random(), 0.5));
    const y = random(0, height);
    const r = random(0.5, 2.5);
    fill(200, 215, 255, random(8, 45));
    ellipse(x, y, r, r);
  }

  drawingContext.globalCompositeOperation = 'source-over';
  for (let i = 0; i < 6000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.005, y * 0.005) * 255;
    stroke(n, n, n, random(2, 9));
    strokeWeight(random(1, 2));
    point(x, y);
  }

  const grad = drawingContext.createRadialGradient(cx, cy, 160, cx, cy, 1050);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(0.7, 'rgba(0,0,0,0.55)');
  grad.addColorStop(1, 'rgba(0,0,0,0.92)');
  drawingContext.fillStyle = grad;
  drawingContext.fillRect(0, 0, width, height);

  drawingContext.globalCompositeOperation = 'lighter';
  noStroke();
  for (let i = 0; i < 120; i++) {
    const y = random(150, 1850);
    const x = cx + randomGaussian() * 6;
    const h = random(120, 600);
    const w = random(0.5, 2.5);
    fill(225, 232, 255, random(20, 80));
    ellipse(x, y, w, h);
  }

  drawingContext.globalCompositeOperation = 'source-over';
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(RGB, 255);
  randomSeed(1);
  noiseSeed(1);
  noiseDetail(4, 0.5);
}

function draw() {
  background(0);

  // Background gradient
  let bgGrad = drawingContext.createLinearGradient(0, 0, 0, height);
  bgGrad.addColorStop(0, '#0a0d13');
  bgGrad.addColorStop(0.45, '#050609');
  bgGrad.addColorStop(1, '#0b0708');
  drawingContext.fillStyle = bgGrad;
  drawingContext.fillRect(0, 0, width, height);

  blendMode(ADD);

  // Faint atmospheric mottling
  noStroke();
  for (let i = 0; i < 220; i++) {
    let rx = random(width);
    let ry = random(height);
    let rr = random(60, 320);
    fill(18, 24, 38, random(1, 4));
    ellipse(rx, ry, rr, rr * random(0.5, 1.25));
  }

  let cx = width * 0.5;
  let cy = height * 0.44;

  // Soft central glow
  let glow = drawingContext.createRadialGradient(cx, cy, 0, cx, cy, 900);
  glow.addColorStop(0, 'rgba(195,210,240,0.16)');
  glow.addColorStop(0.3, 'rgba(130,155,195,0.07)');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = glow;
  drawingContext.beginPath();
  drawingContext.ellipse(cx, cy, 900, 1400, 0, 0, Math.PI * 2);
  drawingContext.fill();

  // Main vertical column: threadlike strokes
  noFill();
  for (let i = 0; i < 650; i++) {
    let yStart = random(height);
    let yNorm = yStart / height;
    let colW = 60 + Math.pow(1 - yNorm, 1.3) * 360;
    let x = cx + randomGaussian() * colW * 0.22;
    x = constrain(x, 0, width);
    let len = random(110, 680) * (0.5 + (1 - yNorm) * 0.6);
    let alpha = random(5, 20);
    let wgt = random(0.3, 1.7);
    let r = lerp(225, 105, yNorm);
    let g = lerp(232, 58, yNorm);
    let b = lerp(248, 45, yNorm);
    stroke(r, g, b, alpha);
    strokeWeight(wgt);

    beginShape();
    let steps = int(len / 14);
    for (let s = 0; s <= steps; s++) {
      let yy = yStart - (s / steps) * len;
      if (yy < 0) break;
      if (yy > height) continue;
      let wobble = (noise(i * 0.06, s * 0.1) - 0.5) * 46;
      let drift = (noise(i * 0.01, yy * 0.007) - 0.5) * 18;
      vertex(x + wobble + drift, yy);
    }
    endShape();
  }

  // Brighter central filaments
  for (let i = 0; i < 240; i++) {
    let yStart = random(height);
    let yNorm = yStart / height;
    let colW = 20 + Math.pow(1 - yNorm, 1.1) * 200;
    let x = cx + randomGaussian() * colW * 0.16;
    x = constrain(x, 0, width);
    let len = random(120, 450);
    let r = lerp(225, 160, yNorm);
    let g = lerp(240, 120, yNorm);
    let b = lerp(252, 85, yNorm);
    stroke(r, g, b, random(20, 50));
    strokeWeight(random(0.2, 0.9));
    line(x, yStart, x + random(-3, 3), yStart - len);
  }

  // Dissolving particles around the column
  noStroke();
  for (let i = 0; i < 1600; i++) {
    let y = random(height);
    let yNorm = y / height;
    let colW = 80 + Math.pow(1 - yNorm, 1.2) * 400;
    let x = cx + randomGaussian() * colW * 0.45;
    x = constrain(x, 0, width);
    let alpha = random(4, 18);
    let size = random(0.4, 2.2);
    let r = lerp(220, 120, yNorm);
    let g = lerp(232, 95, yNorm);
    let b = lerp(248, 80, yNorm);
    fill(r, g, b, alpha);
    ellipse(x, y, size, size);
  }

  // Dark embers at the base
  for (let i = 0; i < 200; i++) {
    let y = height * 0.80 + random(height * 0.20);
    let yNorm = (y - height * 0.80) / (height * 0.20);
    let x = cx + randomGaussian() * 90 * (1 - yNorm * 0.5);
    x = constrain(x, 0, width);
    fill(180 - yNorm * 70, 85 - yNorm * 25, 55, random(10, 35));
    ellipse(x, y, random(0.5, 1.8), random(0.6, 2.4));
  }

  // Fine grain over the whole canvas
  for (let i = 0; i < 700; i++) {
    fill(255, 255, 255, random(1, 4));
    ellipse(random(width), random(height), 0.6, 0.6);
  }

  blendMode(BLEND);
  noLoop();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  drawBackground();
  drawBrushTexture();
  drawMists();
  drawPassage();
  drawParticles();
  drawVignette();
}

function drawBackground() {
  const ctx = drawingContext;
  const grad = ctx.createLinearGradient(0, 0, 0, height);
  grad.addColorStop(0, '#0b0d18');
  grad.addColorStop(0.5, '#161019');
  grad.addColorStop(1, '#0a0606');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
}

function drawBrushTexture() {
  blendMode(BLEND);
  noStroke();
  for (let i = 0; i < 1400; i++) {
    let x = random(width);
    let y = random(height);
    let w = random(1, 6);
    let h = random(15, 50);
    let angle = random(PI);
    let alpha = random(2, 10);
    let gray = random(20, 80);
    fill(gray, gray, gray + random(-8, 4), alpha);
    push();
    translate(x, y);
    rotate(angle);
    rect(0, 0, w, h);
    pop();
  }
}

function drawMists() {
  const layers = [
    { r: 150, g: 155, b: 170, a: 10, count: 80, step: 5, steps: 300, w: 1.0, off: 0.0 },
    { r: 110, g: 115, b: 140, a: 12, count: 70, step: 4, steps: 400, w: 0.8, off: 1.3 },
    { r: 180, g: 160, b: 140, a: 8, count: 50, step: 6, steps: 250, w: 1.4, off: 2.7 },
    { r: 140, g: 140, b: 160, a: 6, count: 60, step: 3, steps: 500, w: 0.6, off: 4.1 }
  ];

  for (let L of layers) {
    stroke(L.r, L.g, L.b, L.a);
    strokeWeight(L.w);
    noFill();
    for (let i = 0; i < L.count; i++) {
      let x = random(width);
      let y = random(height);
      beginShape();
      for (let s = 0; s < L.steps; s++) {
        let angle = noise(x * 0.0025, y * 0.0025, L.off) * TWO_PI * 2.5 - PI / 2;
        x += cos(angle) * L.step;
        y += sin(angle) * L.step;
        if (x < -120 || x > width + 120 || y < -120 || y > height + 120) break;
        vertex(x, y);
      }
      endShape();
    }
  }
}

function drawPassage() {
  // Aura lumineuse
  blendMode(ADD);
  noStroke();
  for (let y = 260; y <= 1740; y += 6) {
    let t = (y - 260) / (1740 - 260);
    let taper = sin(t * PI);
    let w = taper * 260 + 15;
    let alpha = (taper * 0.08 + 0.015) * 255;
    let col = lerpColor(color(255, 210, 170), color(160, 190, 255), t);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(800, y, w * 1.6, 24);
  }

  for (let y = 350; y <= 1650; y += 4) {
    let t = (y - 350) / (1650 - 350);
    let taper = sin(t * PI);
    let w = taper * 90 + 6;
    let alpha = (taper * 0.35 + 0.05) * 255;
    let col = lerpColor(color(255, 235, 210), color(200, 215, 255), t);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(800, y, w, 10);
  }
  blendMode(BLEND);

  // Vide central
  noStroke();
  fill(4, 4, 7, 225);
  beginShape();
  vertex(800, 300);
  bezierVertex(920, 700, 920, 1300, 800, 1700);
  bezierVertex(680, 1300, 680, 700, 800, 300);
  endShape(CLOSE);

  // Liseré lumineux
  blendMode(ADD);
  noFill();
  strokeWeight(2);
  for (let i = 0; i < 7; i++) {
    let o = i * 3 - 9;
    let alpha = 70 - i * 9;
    stroke(255, 220, 180, alpha);
    beginShape();
    vertex(800, 300);
    bezierVertex(920 + o, 700, 920 + o, 1300, 800, 1700);
    endShape();
    stroke(180, 200, 240, alpha);
    beginShape();
    vertex(800, 300);
    bezierVertex(680 - o, 700, 680 - o, 1300, 800, 1700);
    endShape();
  }
  blendMode(BLEND);
}

function drawParticles() {
  blendMode(ADD);
  noStroke();

  for (let i = 0; i < 900; i++) {
    let radius = random(60, 700);
    let angle = random(TWO_PI);
    let x = 800 + cos(angle) * radius;
    let y = 1000 + sin(angle) * radius * 1.25;
    if (x < 0 || x > width || y < 0 || y > height) continue;
    let size = random(0.5, 2.5);
    let alpha = random(15, 110);
    let t = constrain((y + radius * 0.5) / 2000, 0, 1);
    let col = lerpColor(color(255, 220, 180), color(180, 200, 230), t);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(x, y, size, size);
  }

  for (let i = 0; i < 350; i++) {
    let side = random() < 0.5 ? -1 : 1;
    let x = 800 + side * random(90, 380);
    let y = random(650, 1900);
    let size = random(1, 3.5);
    let alpha = random(30, 150);
    let col = lerpColor(color(255, 230, 190), color(170, 190, 255), y / 2000);
    fill(red(col), green(col), blue(col), alpha);
    ellipse(x, y, size, size);
  }

  blendMode(BLEND);
}

function drawVignette() {
  const ctx = drawingContext;
  const grad = ctx.createRadialGradient(800, 1000, 250, 800, 1000, 1350);
  grad.addColorStop(0, 'rgba(0,0,0,0)');
  grad.addColorStop(0.55, 'rgba(0,0,0,0)');
  grad.addColorStop(1, 'rgba(0,0,0,0.55)');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  background(5, 5, 15);

  // Radial gradient to darken center
  noStroke();
  for (let r = 0; r < 800; r += 5) {
    let alpha = map(r, 0, 800, 235, 0);
    fill(0, 0, 0, alpha);
    ellipse(width / 2, height / 2, r * 2, r * 2);
  }

  let centerX = width / 2;
  let centerY = height / 2;
  let numParticles = 250;

  strokeWeight(0.5);
  for (let i = 0; i < numParticles; i++) {
    let angle = random(TWO_PI);
    let radius = random(600, 1000);
    let x = centerX + radius * cos(angle);
    let y = centerY + radius * sin(angle);

    for (let step = 0; step < 800; step++) {
      let dx = centerX - x;
      let dy = centerY - y;
      let distToCenter = sqrt(dx * dx + dy * dy);
      if (distToCenter < 10) break;

      let nx = dx / distToCenter;
      let ny = dy / distToCenter;
      let px = -ny;
      let py = nx;
      let noiseVal = noise(x * 0.002, y * 0.002) - 0.5;

      let vx = nx * 1.2 + px * 0.8 + noiseVal * 1.5;
      let vy = ny * 1.2 + py * 0.8 + noiseVal * 1.5;
      let newX = x + vx;
      let newY = y + vy;

      let alpha = map(step, 0, 800, 180, 5);
      stroke(200, 210, 230, alpha);
      line(x, y, newX, newY);

      x = newX;
      y = newY;
    }
  }

  // Small bright dots (sparks)
  strokeWeight(1);
  for (let i = 0; i < 150; i++) {
    let x = random(width);
    let y = random(height);
    let d = dist(x, y, centerX, centerY);
    if (d > 200) {
      let alpha = map(d, 200, 1200, 200, 50);
      stroke(255, 255, 255, alpha);
      point(x, y);
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  const cx = width / 2;
  const cy = height * 0.52;

  for (let y = 0; y < height; y++) {
    let t = y / height;
    let c;
    if (t < 0.5) {
      c = lerpColor(color(235, 228, 215), color(135, 122, 125), t / 0.5);
    } else {
      c = lerpColor(color(135, 122, 125), color(10, 8, 12), (t - 0.5) / 0.5);
    }
    stroke(c);
    line(0, y, width, y);
  }

  noStroke();
  for (let i = 0; i < 8000; i++) {
    let y = pow(random(), 1.35) * height;
    let x = random(width);
    let alpha = random(4, 30);
    if (y < height * 0.5) {
      fill(color(215, 205, 190, alpha));
    } else {
      fill(color(50, 38, 40, alpha));
    }
    let r = random(1, 28);
    ellipse(x, y, r, r * random(0.25, 1.1));
  }

  noStroke();
  for (let i = 0; i < 90; i++) {
    let y = random(height * 0.18, height * 0.82);
    let side = i % 2 === 0 ? -1 : 1;
    let t = y / height;
    let base = 230 * sin(t * PI) + 60;
    let x = cx + side * (base + random(30, 280));
    let radX = random(50, 220);
    let radY = random(80, 260);
    fill(color(18, 13, 18, random(2, 8)));
    ellipse(x, y, radX, radY);
  }

  noFill();
  for (let i = 0; i < 2200; i++) {
    let angle = random(TWO_PI);
    let r = random(160, 720);
    let x = cx + cos(angle) * r;
    let y = cy + sin(angle) * r * 1.3;
    if (y < 0 || y > height || x < 0 || x > width) continue;
    let n = noise(x * 0.003, y * 0.003);
    let dx = (cx - x) * 0.22 + (n - 0.5) * 380;
    let dy = (cy - y) * 0.22 + (n - 0.5) * 380;
    let ex = cx + random(-50, 50);
    let ey = cy + random(-50, 50);
    stroke(color(100, 90, 88, random(4, 32)));
    strokeWeight(random(0.3, 1.2));
    beginShape();
    vertex(x, y);
    bezierVertex(x + dx, y + dy, cx + (n - 0.5) * 260, cy + (n - 0.5) * 260, ex, ey);
    endShape();
  }

  noStroke();
  for (let i = 0; i < 1200; i++) {
    let y = random(height * 0.12, height * 0.88);
    let t = y / height;
    let w = 250 * sin(t * PI) + noise(y * 0.007, i) * 100;
    let x = cx + (noise(y * 0.004, i) - 0.5) * w * 0.8;
    let alpha = 15 + 105 * sin(t * PI);
    fill(color(6, 5, 8, alpha));
    let sz = random(8, 60);
    ellipse(x, y, sz, sz * random(0.35, 1.3));
  }

  noStroke();
  fill(color(7, 5, 8, 235));
  beginShape();
  for (let y = height * 0.12; y < height * 0.88; y += 6) {
    let t = y / height;
    let w = 245 * sin(t * PI) + noise(y * 0.009) * 80;
    vertex(cx - w, y);
  }
  for (let y = height * 0.88; y > height * 0.12; y -= 6) {
    let t = y / height;
    let w = 245 * sin(t * PI) + noise(y * 0.009 + 400) * 80;
    vertex(cx + w, y);
  }
  endShape(CLOSE);

  blendMode(ADD);
  for (let i = 0; i < 750; i++) {
    let y = random(height * 0.12, height * 0.88);
    let t = y / height;
    let side = random() > 0.5 ? -1 : 1;
    let w = 240 * sin(t * PI) + noise(y * 0.011) * 75;
    let x = cx + side * (w + random(-40, 60));
    let alpha = random(10, 80) * (1 - abs(t - 0.5) * 0.7);
    stroke(color(245, 232, 200, alpha));
    strokeWeight(random(0.4, 2.4));
    line(x, y, x + side * random(10, 90), y - random(2, 28));
  }
  blendMode(BLEND);

  noStroke();
  for (let i = 0; i < 4200; i++) {
    let y = random(height);
    let t = y / height;
    let x = random(width);
    let n = noise(x * 0.0015, y * 0.0015);
    let alpha;
    if (t < 0.45) {
      alpha = random(20, 80) * (1 - t);
    } else {
      alpha = random(3, 14);
    }
    fill(color(235, 225, 205, alpha));
    let s = random(0.3, 2.6) * (0.6 + n);
    ellipse(x, y, s, s);
  }

  for (let i = 0; i < 700; i++) {
    let x = random(width);
    let y = random(height * 0.72, height);
    let n = noise(x * 0.002, y * 0.002);
    stroke(color(4, 3, 6, 8 + n * 28));
    strokeWeight(random(0.8, 3.8));
    line(x, y, x + random(-100, 100), y - random(5, 80));
  }
}

