// « Le Chemin sans nombre » — peinture statique, p5.js 1.11
// Un soleil noir, une plaine cendrée, un chemin de pierres pâles
// qui entre dans l'eau et se dissout sous le disque sans reflet.

let W = 1600, H = 2000;
let HZ = 1260;              // horizon
let SX = 800, SY = 545, SR = 225; // le soleil noir

const NOIR    = [4, 5, 8];
const ARDOISE = [26, 32, 40];
const OS      = [214, 209, 195];
const OSCLAIR = [233, 228, 213];
const CENDRE  = [150, 156, 162];
const OR      = [233, 222, 192];

function setup() {
  createCanvas(W, H);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  peindre();
}

function rgba(c, a) {
  return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')';
}
function mixc(a, b, t) {
  return [lerp(a[0], b[0], t), lerp(a[1], b[1], t), lerp(a[2], b[2], t)];
}
function vgrad(y0, y1, stops) {
  const g = drawingContext.createLinearGradient(0, y0, 0, y1);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  drawingContext.fillStyle = g;
  noStroke();
  rect(0, y0, W, y1 - y0);
}
function pathCx(y) {
  return 800 + Math.sin((y - 1580) * 0.006) * 16 + (noise(y * 0.013) - 0.5) * 44;
}

function peindre() {
  // ---- LE CIEL ----
  vgrad(0, HZ, [
    [0, '#04050a'], [0.32, '#0a0d14'], [0.58, '#141922'],
    [0.78, '#242a33'], [0.90, '#4b5058'], [0.965, '#8e939a'], [1, '#c9c3b4']
  ]);

  // touches horizontales, de plus en plus claires vers l'horizon
  for (let i = 0; i < 2600; i++) {
    const y = random(0, HZ - 4);
    const lum = Math.pow(y / HZ, 3.2);
    const c = mixc(mixc(NOIR, ARDOISE, noise(i * 0.011)), OS, lum * 0.85);
    stroke(rgba(c, random(0.05, 0.16)));
    strokeWeight(random(0.7, 2.6));
    const x = random(-40, W);
    const L = random(24, 150) * (0.5 + y / HZ);
    line(x, y + random(-2, 2), x + L, y + random(-2, 2));
  }

  // brumes basses
  for (let i = 0; i < 26; i++) {
    const y = HZ - random(20, 150);
    noStroke();
    fill(rgba(mixc(ARDOISE, OS, random(0.2, 0.5)), random(0.03, 0.07)));
    ellipse(random(W), y, random(220, 620), random(14, 42));
  }

  // halo du disque
  let g = drawingContext.createRadialGradient(SX, SY, SR * 0.7, SX, SY, SR + 560);
  g.addColorStop(0, 'rgba(210,205,188,0.20)');
  g.addColorStop(0.45, 'rgba(160,166,172,0.08)');
  g.addColorStop(1, 'rgba(160,166,172,0)');
  drawingContext.fillStyle = g;
  noStroke();
  rect(0, 0, W, HZ);

  // cendres montant vers le disque
  for (let i = 0; i < 90; i++) {
    let x, y;
    do { x = random(40, W - 40); y = random(30, HZ - 40); }
    while (dist(x, y, SX, SY) < 310);
    noFill();
    stroke(rgba(OS, random(0.04, 0.11)));
    strokeWeight(random(0.8, 1.6));
    beginShape();
    for (let s = 0; s < 12; s++) {
      vertex(x, y);
      const vers = Math.atan2(SY - y, SX - x);
      const wob = (noise(x * 0.004, y * 0.004) - 0.5) * 2.2;
      x += Math.cos(vers + wob) * random(6, 16);
      y += Math.sin(vers + wob) * random(6, 16);
    }
    endShape();
  }
  for (let i = 0; i < 420; i++) {
    const a = random(TWO_PI), r = random(250, 950);
    const x = SX + Math.cos(a) * r, y = SY + Math.sin(a) * r * 0.85;
    if (y < -20 || y > HZ - 8) continue;
    noStroke();
    fill(rgba(OS, random(0.05, 0.35) * (1 - r / 1100)));
    const s = random(0.8, 3);
    ellipse(x, y, s, s);
  }

  // couronne froide, puis le disque parfait
  for (let i = 0; i < 340; i++) {
    const a = random(TWO_PI);
    const r0 = SR + random(1, 4);
    const L = random(6, 26) + (random() < 0.12 ? random(30, 70) : 0);
    const jit = (noise(i * 0.3) - 0.5) * 0.12;
    const c = random() < 0.7 ? OSCLAIR : OR;
    stroke(rgba(c, random(0.08, 0.5)));
    strokeWeight(random(0.6, 2.0));
    line(SX + Math.cos(a) * r0, SY + Math.sin(a) * r0,
         SX + Math.cos(a + jit) * (r0 + L), SY + Math.sin(a + jit) * (r0 + L));
  }
  noFill();
  stroke(rgba(OSCLAIR, 0.85)); strokeWeight(2.2); ellipse(SX, SY, SR * 2 + 3);
  stroke(rgba(OS, 0.25)); strokeWeight(5); ellipse(SX, SY, SR * 2 + 10);
  noStroke(); fill(1, 1, 2); ellipse(SX, SY, SR * 2, SR * 2);

  // ---- L'EAU ----
  vgrad(HZ, H, [
    [0, '#8e8a7d'], [0.05, '#3c3f41'], [0.16, '#101318'],
    [0.5, '#07090d'], [1, '#04050a']
  ]);

  for (let i = 0; i < 2400; i++) {
    const y = HZ + random(2, H - HZ);
    const pres = Math.pow(1 - (y - HZ) / (H - HZ), 3);
    const c = mixc(mixc(NOIR, ARDOISE, random(0.3, 0.9)), OS, pres * 0.8);
    stroke(rgba(c, random(0.03, 0.05 + 0.13 * pres)));
    strokeWeight(random(0.7, 2.4));
    const x = random(-30, W);
    const L = random(30, 220) * (0.35 + pres);
    line(x, y, x + L, y + random(-1, 1));
  }

  // lisière brillante de l'horizon — absente sous le disque
  for (let i = 0; i < 160; i++) {
    const x = random(0, W);
    if (Math.abs(x - SX) < 180 && random() < 0.85) continue;
    const y = HZ + random(-2, 7);
    stroke(rgba(OSCLAIR, random(0.1, 0.5)));
    strokeWeight(random(0.8, 2.2));
    const L = random(40, 380);
    line(x - L / 2, y, x + L / 2, y);
  }

  // la colonne d'absence : le reflet qui n'existe pas
  const specs = [[340, 0.5], [220, 0.5], [120, 0.55]];
  for (const [wd, al] of specs) {
    const cg = drawingContext.createLinearGradient(0, HZ - 4, 0, HZ + 430);
    cg.addColorStop(0, 'rgba(2,3,6,' + al + ')');
    cg.addColorStop(1, 'rgba(2,3,6,0)');
    drawingContext.fillStyle = cg;
    noStroke();
    rect(SX - wd / 2, HZ - 4, wd, 434);
  }

  // ondes à l'entrée du chemin — quelque chose vient de passer
  noFill();
  for (let k = 0; k < 3; k++) {
    const d0 = 120 + k * 90 + random(-10, 10);
    stroke(rgba(OS, 0.05 + 0.05 * (2 - k)));
    strokeWeight(1.3);
    arc(SX + random(-6, 6), 1584, d0, d0 * 0.32, 0, PI);
  }

  // le chemin sur l'eau : clarté qui s'amincit puis s'arrête, bue
  for (let y = 1576; y > 1312; y -= random(7, 12)) {
    const t = (1576 - y) / 264;
    const cx = pathCx(y);
    const n = 1 + Math.floor(random(0, 2));
    for (let k = 0; k < n; k++) {
      const L = lerp(110, 14, t) * random(0.6, 1.3);
      const x = cx + random(-lerp(40, 6, t), lerp(40, 6, t));
      const c = mixc(OS, CENDRE, t * 0.7);
      stroke(rgba(c, lerp(0.4, 0.02, t) * random(0.5, 1.1)));
      strokeWeight(lerp(6, 1.6, t));
      line(x - L / 2, y + random(-1, 1), x + L / 2, y + random(-1, 1));
    }
  }

  // ---- LA RIVE ----
  vgrad(1552, H, [
    [0, 'rgba(10,12,15,0)'], [0.1, '#0a0c0f'],
    [0.45, '#07080c'], [1, '#030407']
  ]);
  for (let i = 0; i < 1500; i++) {
    const y = random(1576, H);
    const c = mixc(NOIR, ARDOISE, noise(i * 0.02) * 0.7);
    stroke(rgba(c, random(0.1, 0.3)));
    strokeWeight(random(1, 3.5));
    const x = random(-30, W);
    const L = random(30, 200);
    line(x, y, x + L, y + random(-2, 2));
  }

  // cailloux épars près du chemin
  for (let i = 0; i < 170; i++) {
    const y = random(1600, 1996);
    const t = (2000 - y) / 420;
    const cx = pathCx(y), w = lerp(470, 112, t);
    const side = random() < 0.5 ? -1 : 1;
    noStroke();
    fill(rgba(OS, random(0.05, 0.2)));
    ellipse(cx + side * (w / 2 + random(6, 120)), y, random(2, 7), random(1, 3.5));
  }

  // les pierres pâles du chemin, du bas du tableau vers l'eau
  let y = 1996;
  while (y > 1584) {
    const t = (2000 - y) / 420;
    const cx = pathCx(y);
    const w = lerp(470, 112, t);
    const step = lerp(100, 26, t);
    for (let x = cx - w / 2 + random(0, step * 0.5); x < cx + w / 2; x += step * random(0.75, 1.3)) {
      if (random() < 0.14) continue;
      const L = lerp(76, 17, t) * random(0.6, 1.4);
      const hh = lerp(28, 7, t) * random(0.55, 1.15);
      const c = mixc(OS, CENDRE, random(0, 0.4));
      noStroke();
      fill(rgba(c, random(0.16, 0.5) * (1 - t * 0.35)));
      ellipse(x + random(-4, 4), y + random(-3, 3), L, hh);
    }
    y -= lerp(30, 10, t) * random(0.8, 1.2);
  }

  // ---- VOILE ET GRAIN ----
  let vg = drawingContext.createRadialGradient(800, 930, 560, 800, 930, 1500);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.42)');
  drawingContext.fillStyle = vg;
  noStroke();
  rect(0, 0, W, H);
  vg = drawingContext.createLinearGradient(0, 0, 0, 260);
  vg.addColorStop(0, 'rgba(0,0,0,0.4)');
  vg.addColorStop(1, 'rgba(0,0,0,0)');
  drawingContext.fillStyle = vg;
  rect(0, 0, W, 260);

  noStroke();
  for (let i = 0; i < 9000; i++) {
    const x = random(W), yy = random(H);
    fill(random() < 0.5
      ? 'rgba(255,255,255,' + random(0.015, 0.05) + ')'
      : 'rgba(0,0,0,' + random(0.03, 0.09) + ')');
    rect(x, yy, random(0.7, 1.8), random(0.7, 1.8));
  }
}

const W = 1600, H = 2000;

const WARM = ['#7e1f22', '#9c3122', '#b8502a', '#d1853c', '#dfb46d', '#8c2b30', '#5e1a1f', '#e5d6b6', '#3d5c57'];
const ASH  = ['#6d675f', '#585a5e', '#454b52', '#333a41', '#262d34', '#4e5459'];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noLoop();
  paint();
}

function draw() {}

function smoothstep(a, b, y) {
  const t = constrain((y - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}
function coh(y) { return 1 - smoothstep(360, 1480, y); }
function xc(y)  { return 800 + (noise(3.7 + y * 0.0016) - 0.5) * 300; }
function hw(y)  { return y <= 545 ? 0 : 470 * pow(min(1, (y - 545) / 1250), 0.82); }

function glow(cx, cy, rx, ry, r, g, b, a, blur) {
  const ctx = drawingContext;
  ctx.save();
  ctx.shadowBlur = blur;
  ctx.shadowColor = 'rgba(' + r + ',' + g + ',' + b + ',' + min(1, a / 255 * 3).toFixed(3) + ')';
  noStroke();
  fill(r, g, b, a);
  ellipse(cx, cy, rx * 2, ry * 2);
  ctx.restore();
}

function paint() {
  ground();
  washes();
  river();
  weave();
  weft();
  fallen();
  knot();
  shimmer();
  motes();
  bands();
  grain();
  vignette();
}

function ground() {
  noStroke();
  const top = color('#2a1215'), mid = color('#150f13'), bot = color('#090d12');
  for (let y = 0; y < H; y++) {
    const t = y / H;
    const c = t < 0.55 ? lerpColor(top, mid, t / 0.55) : lerpColor(mid, bot, (t - 0.55) / 0.45);
    fill(c);
    rect(0, y, W, 1.5);
  }
  for (let i = 0; i < 7000; i++) {
    const x = random(W), y = random(H);
    const v = noise(x * 0.004, y * 0.004);
    if (v > 0.5) fill(226, 214, 190, random(2, 6));
    else fill(6, 8, 11, random(3, 8));
    rect(x, y, random(1, 2.6), random(1, 2.6));
  }
}

function washes() {
  glow(1150, 250, 560, 400, 172, 82, 40, 16, 170);
  glow(380, 430, 600, 440, 122, 32, 36, 15, 170);
  glow(820, 1830, 950, 420, 26, 38, 50, 22, 190);
  glow(1330, 1020, 380, 520, 64, 48, 58, 9, 150);
}

function river() {
  for (let y = 560; y < H + 40; y += 34) {
    const cx = xc(y), h = hw(y);
    glow(cx, y, h * 0.92 + 26, 48, 7, 9, 13, 18, 55);
    if (h > 70) glow(cx, y, h * 0.38, 30, 60, 80, 100, 6, 42);
  }
}

function threadColor(y) {
  const t = smoothstep(430, 1500, y);
  let c = lerpColor(color(random(WARM)), color(random(ASH)), t);
  if (random() < 0.05) {
    c = lerpColor(color(random() < 0.5 ? '#eadfc6' : '#46695f'), color(random(ASH)), t * 0.55);
  }
  return c;
}

function fieldAngle(x, y, c, droop) {
  const n = noise(x * 0.0024, y * 0.0029);
  let a = (n - 0.5) * 2 * lerp(2.5, 0.26, c);
  a = lerp(a, HALF_PI, min(1, (1 - c) * 0.42 + droop * 0.8));
  return a;
}

function thread(x, y, len, wgt, col, alp, c, droop) {
  const steps = max(3, floor(len / 5));
  let a = fieldAngle(x, y, c, droop);
  stroke(red(col), green(col), blue(col), alp);
  strokeWeight(wgt);
  noFill();
  beginShape();
  vertex(x, y);
  let px = x, py = y;
  for (let s = 0; s < steps; s++) {
    a += (noise(px * 0.012, py * 0.012, 40.3) - 0.5) * lerp(0.95, 0.3, c);
    a = lerp(a, HALF_PI, 0.035 + droop * 0.06);
    px += cos(a) * 5;
    py += sin(a) * 5;
    vertex(px, py);
  }
  endShape();
}

function weave() {
  for (let i = 0; i < 19000; i++) {
    const y = random() < 0.14 ? random(1350, 1985) : pow(random(), 1.35) * 1820;
    const x = random(-30, W + 30);
    const cx = xc(y), h = hw(y);
    const d = abs(x - cx) - h;
    if (d < 0) {
      if (random() < 0.04) {
        noStroke();
        fill(150, 168, 180, random(7, 18));
        ellipse(x, y, random(1, 2.3), random(1, 2.3));
      }
      continue;
    }
    const c = coh(y);
    const edge = constrain(d / 170, 0, 1);
    const droop = h > 0 ? pow(1 - edge, 1.25) : 0;
    const alphaMul = h > 0 ? lerp(0.22, 1, edge) : 1;
    let len = random(18, 60) * (0.7 + 0.8 * c);
    if (c < 0.35 && random() < 0.18) len += random(50, 120);
    const wgt = random(0.8, 2.4) * (0.55 + 0.6 * c);
    const col = threadColor(y);
    const alp = random(85, 200) * (0.45 + 0.55 * c) * alphaMul;
    thread(x, y, len, wgt, col, alp, c, droop);
  }
}

function weft() {
  for (let i = 0; i < 2400; i++) {
    const y = random(28, 540), x = random(W);
    const col = lerpColor(color(random(WARM)), color(random(ASH)), 0.3);
    stroke(red(col), green(col), blue(col), random(12, 30));
    strokeWeight(random(0.7, 1.5));
    noFill();
    let a = HALF_PI + (noise(x * 0.01, y * 0.01) - 0.5) * 0.6;
    let px = x, py = y;
    beginShape();
    vertex(px, py);
    const steps = floor(random(5, 13));
    for (let s = 0; s < steps; s++) {
      a += (noise(px * 0.02, py * 0.02, 11.7) - 0.5) * 0.3;
      px += cos(a) * 5;
      py += sin(a) * 5;
      vertex(px, py);
    }
    endShape();
  }
}

function fallen() {
  for (let i = 0; i < 150; i++) {
    const y0 = 590 + pow(random(), 1.2) * 1300;
    const side = random() < 0.5 ? -1 : 1;
    const x0 = xc(y0) + side * (hw(y0) + random(2, 60));
    if (x0 < 15 || x0 > W - 15) continue;
    const len = random(70, 320);
    const col = lerpColor(color(random(ASH)), color('#8b939b'), random(0.35));
    stroke(red(col), green(col), blue(col), random(24, 80));
    strokeWeight(random(0.7, 1.5));
    noFill();
    let a = HALF_PI + (random() - 0.5) * 0.3;
    let px = x0, py = y0;
    beginShape();
    vertex(px, py);
    const steps = floor(len / 6);
    for (let s = 0; s < steps; s++) {
      a += (noise(px * 0.008, py * 0.008, 9.1) - 0.5) * 0.34;
      a = lerp(a, HALF_PI, 0.14);
      px += cos(a) * 6;
      py += sin(a) * 6;
      vertex(px, py);
    }
    endShape();
  }
}

function knot() {
  const kx = xc(550), ky = 550;
  glow(kx, ky, 92, 72, 214, 130, 54, 26, 90);
  glow(kx, ky, 46, 38, 236, 182, 104, 22, 60);
  for (let i = 0; i < 2200; i++) {
    let rr = 4 + pow(random(), 1.6) * 132;
    let th = random(TWO_PI);
    const dir = random() < 0.5 ? -1 : 1;
    const col = lerpColor(color('#e08a3e'), color('#565b62'), constrain(rr / 136, 0, 1));
    const alp = map(rr, 4, 136, 185, 60) * random(0.6, 1);
    stroke(red(col), green(col), blue(col), alp);
    strokeWeight(random(0.6, 1.7));
    noFill();
    let px = kx + cos(th) * rr, py = ky + sin(th) * rr * 0.85;
    beginShape();
    vertex(px, py);
    const steps = floor(random(4, 9));
    for (let s = 0; s < steps; s++) {
      th += dir * random(0.1, 0.2);
      rr = max(2, rr * 0.982 - 0.15);
      px = kx + cos(th) * rr;
      py = ky + sin(th) * rr * 0.85;
      vertex(px, py);
    }
    endShape();
  }
}

function shimmer() {
  for (let i = 0; i < 850; i++) {
    const y = pow(random(), 1.3) * 340, x = random(W);
    stroke(232, 198, 124, random(12, 44));
    strokeWeight(random(0.7, 1.6));
    line(x, y, x + random(4, 16), y + random(-1.5, 1.5));
  }
}

function motes() {
  noStroke();
  for (let i = 0; i < 420; i++) {
    let x, y;
    if (random() < 0.55) { y = random(1320, 1985); x = random(W); }
    else { y = random(800, 1985); const h = hw(y); x = xc(y) + random(-h * 0.85, h * 0.85); }
    const a = random() < 0.08 ? random(30, 52) : random(7, 22);
    fill(158, 176, 190, a);
    const s = random(1, 2.6);
    ellipse(x, y, s, s);
  }
}

function bands() {
  noStroke();
  for (let b = 0; b < 20; b++) {
    const y = 1668 + b * 15 + random(-4, 4);
    drawingContext.save();
    drawingContext.shadowBlur = 22;
    drawingContext.shadowColor = 'rgba(138,150,162,0.35)';
    fill(138, 150, 162, random(3, 6.5));
    rect(90, y, W - 180, random(5, 12));
    drawingContext.restore();
  }
}

function grain() {
  noStroke();
  for (let i = 0; i < 13000; i++) {
    const x = random(W), y = random(H);
    if (random() < 0.5) fill(0, 0, 0, random(5, 12));
    else fill(230, 224, 210, random(3, 9));
    rect(x, y, 1, 1);
  }
}

function vignette() {
  noStroke();
  for (let i = 0; i < 620; i++) {
    const e = floor(random(4));
    let x, y;
    if (e === 0) { x = random(-60, W + 60); y = random(-70, 70); }
    else if (e === 1) { x = random(-60, W + 60); y = random(H - 70, H + 70); }
    else if (e === 2) { x = random(-70, 70); y = random(-40, H + 40); }
    else { x = random(W - 70, W + 70); y = random(-40, H + 40); }
    const r = random(140, 360);
    glow(x, y, r, r * random(0.7, 1.1), 4, 6, 9, random(5, 11), 80);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  colorMode(HSB, 360, 100, 100, 1);
  noLoop();

  const ctx = drawingContext;

  let bg = ctx.createLinearGradient(0, 0, 0, height);
  bg.addColorStop(0.00, 'hsl(46, 12%, 88%)');
  bg.addColorStop(0.20, 'hsl(40, 14%, 76%)');
  bg.addColorStop(0.46, 'hsl(23, 28%, 47%)');
  bg.addColorStop(0.68, 'hsl(9, 40%, 20%)');
  bg.addColorStop(1.00, 'hsl(252, 52%, 4%)');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, width, height);

  let glow = ctx.createRadialGradient(width * 0.5, height * 0.22, 0, width * 0.5, height * 0.22, 880);
  glow.addColorStop(0, 'hsla(48, 20%, 97%, 0.58)');
  glow.addColorStop(0.35, 'hsla(42, 14%, 84%, 0.24)');
  glow.addColorStop(1, 'hsla(42, 14%, 84%, 0)');
  ctx.fillStyle = glow;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let layer = 0; layer < 18; layer++) {
    let t = layer / 17;
    let baseY = height * (0.60 + t * 0.10);
    let h = lerp(14, 254, t);
    let s = lerp(40, 55, t);
    let b = lerp(18, 3, t);
    fill(h, s, b, 0.13);

    beginShape();
    vertex(-60, height + 60);
    for (let x = -60; x <= width + 60; x += 14) {
      let n1 = noise(x * 0.0012 + layer * 9.7, layer * 0.35);
      let n2 = noise(x * 0.0045 + layer * 3.1, 77.7);
      let y = baseY + (n1 - 0.5) * 560 + (n2 - 0.5) * 110;
      vertex(x, y);
    }
    vertex(width + 60, height + 60);
    endShape(CLOSE);
  }

  push();
  blendMode(SCREEN);
  noFill();
  strokeWeight(2.4);
  stroke(46, 10, 98, 0.16);
  beginShape();
  for (let x = -60; x <= width + 60; x += 12) {
    let n1 = noise(x * 0.0012, 0);
    let n2 = noise(x * 0.0045, 77.7);
    let y = height * 0.60 + (n1 - 0.5) * 560 + (n2 - 0.5) * 110;
    vertex(x, y);
  }
  endShape();
  pop();

  push();
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i < 2600; i++) {
    let t = i / 2600;
    let y = t * height;
    let x = width * 0.5 + (noise(41.2, y * 0.0016) - 0.5) * 360 + Math.sin(y * 0.0021) * 52;
    let rw = map(noise(73.8, y * 0.0022), 0, 1, 30, 520);
    let rh = random(18, 130);
    let hue = lerp(16, 255, t);
    let alpha = map(noise(94.6, y * 0.0031), 0, 1, 0.008, 0.055);
    fill(hue, 58, 4, alpha);
    ellipse(x, y, rw, rh);
  }
  pop();

  push();
  blendMode(MULTIPLY);
  noFill();
  for (let i = 0; i < 90; i++) {
    let startX = random(width);
    let startY = random(height * 0.16, height * 0.72);
    let len = random(180, 980);
    for (let k = 0; k < 4; k++) {
      stroke(random(6, 18), random(32, 68), random(16, 52), 0.028);
      strokeWeight(random(0.5, 4.8));
      beginShape();
      for (let s = 0; s <= len; s += 24) {
        let x = startX + (noise(i * 0.19, s * 0.0024, k * 0.63) - 0.5) * 300;
        let y = startY + s;
        vertex(x, y);
      }
      endShape();
    }
  }
  pop();

  push();
  blendMode(SCREEN);
  strokeWeight(1);
  for (let i = 0; i < 140; i++) {
    let y = random(height);
    let alpha = map(noise(5.2, y * 0.0011), 0, 1, 0.004, 0.065);
    stroke(47, 8, 96, alpha);
    let y2 = y + random(-60, 60);
    line(0, y, width, y2);
  }
  pop();

  push();
  blendMode(SCREEN);
  noStroke();
  for (let i = 0; i < 4200; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0014, y * 0.0014);
    let r = map(n, 0, 1, 0.35, 4.8);
    let t = y / height;
    if (t < 0.26) {
      fill(47, 10, 98, random(0.008, 0.050));
    } else if (t < 0.58) {
      fill(16, 55, 62, random(0.008, 0.050));
    } else {
      fill(226, 12, 76, random(0.006, 0.045));
    }
    ellipse(x, y, r, r);
  }
  pop();

  let vignette = ctx.createRadialGradient(width / 2, height * 0.42, height * 0.08, width / 2, height * 0.52, height * 0.82);
  vignette.addColorStop(0, 'rgba(0,0,8,0)');
  vignette.addColorStop(1, 'rgba(0,0,8,0.35)');
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  background(3, 4, 7);

  // ---------- Fond : de la ténèbre chaude vers l'immobilité absolue
  let cTop = color(21, 13, 9);
  let cMid = color(15, 17, 26);
  let cLow = color(9, 12, 19);
  let cAbyss = color(2, 2, 5);
  for (let y = 0; y < 2000; y++) {
    let c;
    if (y < 700) c = lerpColor(cTop, cMid, pow(y / 700, 1.15));
    else if (y < 1300) c = lerpColor(cMid, cLow, (y - 700) / 600);
    else c = lerpColor(cLow, cAbyss, pow((y - 1300) / 700, 0.8));
    let d = (noise(y * 0.045) - 0.5) * 7;
    stroke(red(c) + d, green(c) + d, blue(c) + d);
    strokeWeight(1);
    line(0, y + 0.5, 1600, y + 0.5);
  }

  // ---------- Le cœur de braise où la foule des vies se presse
  for (let i = 0; i < 150; i++) {
    let t = i / 149;
    let r = lerp(660, 24, pow(t, 0.85));
    let wob = (noise(i * 0.31, 7.7) - 0.5) * 110 * (1 - t);
    noStroke();
    let cc = lerpColor(color(186, 88, 46), color(242, 176, 98), noise(i * 0.13, 2.2));
    fill(red(cc), green(cc), blue(cc), 0.6);
    ellipse(800 + (noise(i * 0.21) - 0.5) * 60 * (1 - t),
            374 + (noise(i * 0.21, 3.3) - 0.5) * 46 * (1 - t),
            r * 2 + wob, r * 1.66 + wob);
  }

  let warm = ['#f2b266', '#dd8f47', '#c96b36', '#a34a28', '#e9d3a8', '#f5e6c8', '#b95f33', '#8f3d2a'].map(h => color(h));
  let cool = ['#8b90a4', '#5d6376', '#414759', '#2e3344', '#70768a'].map(h => color(h));

  // ---------- Vies lointaines dans les vides
  for (let i = 0; i < 170; i++) {
    let x = random(1600), y = random(720);
    if (noise(x * 0.0013, y * 0.0013) >= 0.34) continue;
    stroke(212, 216, 228, random(9, 28));
    strokeWeight(random(0.5, 1.5));
    point(x, y);
  }

  // ---------- La nuée : chaque trait est une vie portée par le courant
  for (let i = 0; i < 7800; i++) {
    let x = random(1600);
    let y = 46 + pow(random(), 1.85) * 1218;
    if (noise(x * 0.0013, y * 0.0013) < 0.34) continue;
    if (y > 640 && random() > map(y, 640, 1264, 0.9, 0.06)) continue;
    let f = constrain(norm(y, 420, 1264), 0, 1); // facteur d'apaisement
    let ang = noise(x * 0.0017, y * 0.0017) * TWO_PI * 2;
    let dx = cos(ang), dy = sin(ang) * (1 - 0.8 * f);
    let m = max(0.0001, sqrt(dx * dx + dy * dy));
    dx /= m; dy /= m;
    let L = lerp(30, 6, f) * random(0.45, 1.5);
    let cA = warm[floor(noise(x * 0.004 + 3.1, y * 0.004) * warm.length) % warm.length];
    let cB = cool[floor(noise(x * 0.004 + 9.2, y * 0.004) * cool.length) % cool.length];
    let c = lerpColor(cA, cB, pow(f, 1.1) * 0.92);
    stroke(red(c), green(c), blue(c), lerp(150, 20, f) * random(0.5, 1.05));
    strokeWeight(lerp(2.6, 0.7, f) * random(0.6, 1.35));
    line(x, y, x + dx * L, y + dy * L);
  }

  // ---------- Les cendres : le mouvement perd sa direction et descend
  for (let i = 0; i < 1000; i++) {
    let x = random(1600);
    let y = random(610, 1296);
    let g = norm(y, 610, 1296);
    if (random() > map(g, 0, 1, 0.75, 0.25)) continue;
    let L = random(5, 20) * (1 - 0.4 * g);
    let ang = HALF_PI + random(-0.22, 0.22);
    let c = lerpColor(cool[i % cool.length], warm[2], 0.15 * (1 - g));
    stroke(red(c), green(c), blue(c), random(15, 52) * (1 - 0.5 * g));
    strokeWeight(random(0.7, 1.5));
    line(x, y, x + cos(ang) * L, y + sin(ang) * L);
  }

  // ---------- L'eau d'en bas : presque rien, presque tout
  for (let i = 0; i < 540; i++) {
    let y = 1306 + pow(random(), 1.6) * 686;
    let x = random(1600);
    let L = random(50, 300);
    let near = 1 - norm(y, 1306, 1992);
    stroke(120, 132, 158, random(3, 8) + 4 * near);
    strokeWeight(random(0.6, 1.3));
    line(x - L / 2, y, x + L / 2, y);
  }

  // ---------- Le seuil : une seule ligne, à peine lumineuse
  for (let x = 0; x <= 1600; x += 6) {
    let b = Math.exp(-sq((x - 800) / 430));
    stroke(206, 206, 216, 10 + 36 * b);
    strokeWeight(1.1);
    let jy = (noise(x * 0.02) - 0.5) * 1.6;
    line(x, 1299 + jy, x + 6, 1299 + jy);
  }

  // ---------- Le disque pâle, à moitié passé déjà
  noFill();
  for (let i = 0; i < 70; i++) {
    let t = i / 69;
    let r = 214 + t * 130;
    stroke(226, 214, 188, 2.4 * (1 - t));
    strokeWeight(1.4);
    arc(800, 1300, r * 2, r * 2, PI, TWO_PI);
  }
  noStroke();
  fill(228, 224, 210);
  arc(800, 1300, 424, 424, PI, TWO_PI, CHORD);
  for (let i = 0; i < 26; i++) {
    for (let tries = 0; tries < 40; tries++) {
      let rr = random(0.15, 0.8) * 212;
      let ang = random(PI + 0.3, TWO_PI - 0.3);
      let px = 800 + cos(ang) * rr;
      let py = 1300 + sin(ang) * rr;
      let s = random(18, 86);
      if (py + s * 0.4 < 1297 && dist(px, py, 800, 1300) + s / 2 < 200) {
        fill(186, 182, 172, 9);
        ellipse(px, py, s, s * 0.8);
        break;
      }
    }
  }
  noFill();
  for (let i = 1; i <= 6; i++) {
    stroke(228, 224, 210, 7);
    strokeWeight(2);
    arc(800, 1300, 424 + i * 7, 424 + i * 7, PI, TWO_PI);
  }

  // ---------- Pas de reflet : la forme se défait en ondes
  for (let i = 0; i < 26; i++) {
    let y = 1303 + i * 4.2;
    let w = 420 * (1 - i / 26) * random(0.7, 1);
    stroke(216, 210, 196, 8 * (1 - i / 26));
    strokeWeight(1);
    line(800 - w / 2, y, 800 + w / 2, y);
  }
  for (let k = 0; k < 9; k++) {
    let t = k / 8;
    let rx = 64 + pow(t, 1.35) * 640;
    let ry = 9 + pow(t, 1.5) * 150;
    stroke(214, 212, 200, lerp(44, 5, t));
    strokeWeight(lerp(1.6, 0.7, t));
    beginShape();
    for (let a2 = 0; a2 <= PI + 0.001; a2 += 0.045) {
      let wob = (noise(cos(a2) * 1.4 + k * 3.7, sin(a2) * 1.4 + k * 1.3) - 0.5) * 26 * t;
      vertex(800 + cos(a2) * (rx + wob), 1301 + sin(a2) * (ry + wob * 0.4));
    }
    endShape();
  }

  // ---------- Le grain du temps
  for (let i = 0; i < 9000; i++) {
    let x = random(1600), y = random(2000);
    let b = random() < 0.5 ? 255 : 0;
    stroke(b, b, b, random(3, 11));
    strokeWeight(random(0.6, 1.4));
    point(x, y);
  }

  // ---------- La nuit qui se referme sur les bords
  blendMode(MULTIPLY);
  noStroke();
  for (let i = 0; i <= 70; i++) {
    let t = i / 70;
    let dd = lerp(3400, 1500, t);
    let v = lerp(148, 255, pow(t, 1.6));
    fill(v, v, lerp(v, 255, 0.3));
    ellipse(800, 1000, dd * 0.82, dd);
  }
  blendMode(BLEND);
}

let W = 1600;
let H = 2000;
let CX = W * 0.5;
let CY = H * 0.485;
let VOID_W = 640;
let VOID_H = 1680;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  noLoop();

  paintBackground();
  paintFields();
  paintStrata();
  paintVoid();
  paintThreshold();
  paintInterruptions();
  paintAsh();
  paintGrainAndVignette();
}

function paintBackground() {
  background(8, 9, 12);
  let cTop = color(14, 17, 25);
  let cUpper = color(30, 29, 40);
  let cHeart = color(41, 33, 33);
  let cLower = color(19, 16, 17);
  let cBottom = color(5, 6, 8);

  for (let y = 0; y < H; y++) {
    let t = y / H;
    let c;
    if (t < 0.22) c = lerpColor(cTop, cUpper, t / 0.22);
    else if (t < 0.52) c = lerpColor(cUpper, cHeart, (t - 0.22) / 0.30);
    else if (t < 0.80) c = lerpColor(cHeart, cLower, (t - 0.52) / 0.28);
    else c = lerpColor(cLower, cBottom, (t - 0.80) / 0.20);

    let n = (noise(y * 0.013) - 0.5) * 26;
    stroke(
      constrain(red(c) + n, 0, 255),
      constrain(green(c) + n * 0.8, 0, 255),
      constrain(blue(c) + n * 1.15, 0, 255),
      255
    );
    strokeWeight(1);
    line(0, y, W, y);
  }
}

function paintFields() {
  noStroke();
  rectMode(CENTER);

  for (let i = 0; i < 95; i++) {
    let x = random(-220, W + 220);
    let y = random(-350, H + 350);
    let w = random(90, 760);
    let h = random(260, 1900);
    let a = random(4, 16);
    let p = random();

    push();
    translate(x, y);
    rotate(random(-0.09, 0.09));

    if (p < 0.34) fill(52 + random(30), 60 + random(34), 88 + random(36), a);
    else if (p < 0.62) fill(92 + random(40), 78 + random(30), 58 + random(26), a);
    else if (p < 0.84) fill(58 + random(26), 36 + random(20), 32 + random(18), a);
    else fill(126 + random(46), 116 + random(40), 100 + random(36), a * 0.65);

    rect(0, 0, w, h, random(120, 700));
    pop();
  }

  blendMode(SCREEN);
  for (let i = 0; i < 35; i++) {
    let x = random(W);
    let y = random(H);
    let w = random(50, 360);
    let h = random(180, 1100);

    fill(146 + random(56), 140 + random(50), 126 + random(46), random(2.5, 8));

    push();
    translate(x, y);
    rotate(random(-0.14, 0.14));
    rect(0, 0, w, h, random(100, 600));
    pop();
  }
  blendMode(BLEND);
}

function paintStrata() {
  strokeCap(ROUND);
  let y = -80;

  while (y < H + 80) {
    y += random(7, 26);

    let n = noise(y * 0.006);
    let warm = n * 80;
    let alpha = map(noise(y * 0.011 + 20), 0, 1, 7, 52);
    let weight = random(0.4, 2.5);
    let amp = map(noise(y * 0.003 + 70), 0, 1, 18, 140);
    let edge = noise(y * 0.008 + 11) * 180;
    let verticalT = abs(y - CY) / (VOID_H * 0.55);

    if (verticalT < 1) {
      let gapHalf = (VOID_W * 0.5 + edge) * constrain(map(verticalT, 0, 1, 1, 0.12), 0, 1);
      drawStratum(-60, CX - gapHalf, y, amp, warm, alpha, weight);
      drawStratum(CX + gapHalf, W + 60, y, amp, warm, alpha, weight);
    } else {
      drawStratum(-60, W + 60, y, amp, warm, alpha, weight);
    }
  }
}

function drawStratum(x0, x1, baseY, amp, warm, alpha, weight) {
  if (x1 <= x0) return;

  stroke(78 + warm, 70 + warm * 0.72, 64 + warm * 0.42, alpha);
  strokeWeight(weight);
  noFill();

  beginShape();
  for (let x = x0; x <= x1; x += 18) {
    let yy = baseY + (noise(x * 0.0017, baseY * 0.0043) - 0.5) * amp;
    vertex(x, yy);
  }
  endShape();
}

function paintVoid() {
  noStroke();

  for (let i = 0; i < 36; i++) {
    let t = i / 35;
    let rx = VOID_W * 0.70 + (1 - t) * 230;
    let ry = VOID_H * 0.58 + (1 - t) * 320;
    fill(7, 7, 11, 0.8 + t * 1.8);
    drawVoidBlob(rx, ry, 24 - t * 12, t * 7.31);
  }

  let layers = 125;
  for (let i = 0; i < layers; i++) {
    let t = i / (layers - 1);
    let ease = pow(t, 1.25);
    let rx = lerp(VOID_W * 0.70, 24, ease);
    let ry = lerp(VOID_H * 0.58, 90, ease);
    let alpha = lerp(2.0, 30, pow(t, 1.55));
    let nShift = noise(i * 0.035) * 14;

    fill(5 + nShift * 0.2, 5 + nShift * 0.14, 8 + nShift * 0.32, alpha);
    drawVoidBlob(rx, ry, map(t, 0, 1, 18, 4), i * 0.061);
  }

  for (let i = 0; i < 1600; i++) {
    let x = random(CX - VOID_W * 0.60, CX + VOID_W * 0.60);
    let y0 = random(CY - VOID_H * 0.60, CY + VOID_H * 0.60);
    let nx = (x - CX) / (VOID_W * 0.54);
    let ny = (y0 - CY) / (VOID_H * 0.56);
    let d = nx * nx + ny * ny;

    if (d > 1) continue;

    let len = random(20, 320);
    let a = random(3, 22) * map(d, 0, 1, 1, 0.35);
    let g = 4 + random(12);

    stroke(g, g, g + random(8), a);
    strokeWeight(random(0.5, 5));

    let drift = random(-16, 16);
    line(x, y0, x + drift, y0 + len);
  }

  blendMode(SCREEN);
  for (let i = 0; i < 24; i++) {
    let ang = random(TWO_PI);
    let rr = random(0.15, 0.8);
    let x = CX + cos(ang) * VOID_W * 0.28 * rr;
    let y = CY + sin(ang) * VOID_H * 0.34 * rr;

    if (i % 4 === 0) fill(72, 48, 44, random(1.5, 5));
    else fill(52, 60, 78, random(1.5, 5));

    noStroke();
    ellipse(x, y, random(40, 220), random(120, 560));
  }
  blendMode(BLEND);
}

function drawVoidBlob(rx, ry, jitter, seedOffset) {
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.045) {
    let ca = cos(a);
    let sa = sin(a);
    let n = noise(ca * 1.25 + seedOffset, sa * 1.25 + seedOffset, seedOffset * 0.12) - 0.5;
    let m = 1 + n * jitter * 0.02;
    vertex(CX + ca * rx * m, CY + sa * ry * m);
  }
  endShape(CLOSE);
}

function paintThreshold() {
  strokeCap(ROUND);
  blendMode(SCREEN);

  let edgeRX = VOID_W * 0.70;
  let edgeRY = VOID_H * 0.58;

  for (let i = 0; i < 460; i++) {
    let ang = random(TWO_PI);
    let radial = random(0.94, 1.12);
    let ca = cos(ang);
    let sa = sin(ang);
    let n = noise(ca * 1.6 + 31, sa * 1.6 + 17, i * 0.001) - 0.5;

    let rx = edgeRX * radial * (1 + n * 0.22);
    let ry = edgeRY * radial * (1 + n * 0.12);
    let x = CX + ca * rx;
    let y = CY + sa * ry;
    let tang = ang + HALF_PI + random(-0.25, 0.25);
    let len = random(8, 120);
    let a = random(2, 15);

    if (random() < 0.15) stroke(156, 110, 88, a * 0.8);
    else stroke(168, 176, 190, a);

    strokeWeight(random(0.4, 2.8));
    line(
      x - cos(tang) * len * 0.5,
      y - sin(tang) * len * 0.5,
      x + cos(tang) * len * 0.5,
      y + sin(tang) * len * 0.5
    );
  }

  for (let k = 0; k < 3; k++) {
    stroke(190, 188, 182, random(6, 14));
    strokeWeight(random(0.6, 1.6));
    noFill();

    let active = false;

    for (let a = 0; a <= TWO_PI + 0.1; a += 0.03) {
      let gate = noise(a * 1.7 + k * 37.7, k * 11.3);

      if (gate > 0.46) {
        if (!active) {
          beginShape();
          active = true;
        }

        let n = noise(cos(a) * 1.4 + k * 9, sin(a) * 1.4 + k * 4) - 0.5;
        let rx = edgeRX * (1 + n * 0.18);
        let ry = edgeRY * (1 + n * 0.10);
        vertex(CX + cos(a) * rx, CY + sin(a) * ry);
      } else {
        if (active) {
          endShape();
          active = false;
        }
      }
    }

    if (active) endShape();
  }

  blendMode(BLEND);
}

function paintInterruptions() {
  noFill();
  strokeCap(ROUND);

  let yBase = H * 0.38;
  let stopX = CX - VOID_W * 0.72 - 20;

  stroke(118, 38, 32, 95);
  strokeWeight(2.1);

  beginShape();
  for (let x = -30; x < stopX; x += 12) {
    vertex(x, yBase + (noise(x * 0.002, 3.3) - 0.5) * 130);
  }
  let endY = yBase + (noise(stopX * 0.002, 3.3) - 0.5) * 130;
  vertex(stopX, endY);
  endShape();

  for (let i = 0; i < 28; i++) {
    stroke(118, 38, 32, random(10, 55));
    strokeWeight(random(0.4, 1.6));
    let ang = random(-0.8, 0.8);
    let len = random(6, 70);
    line(stopX, endY, stopX + cos(ang) * len, endY + sin(ang) * len * 0.35);
  }

  yBase = H * 0.64;
  let stopR = CX + VOID_W * 0.72 + 20;

  stroke(172, 166, 154, 70);
  strokeWeight(1.5);

  beginShape();
  for (let x = W + 30; x > stopR; x -= 12) {
    vertex(x, yBase + (noise(x * 0.0018, 9.1) - 0.5) * 160);
  }
  let endRY = yBase + (noise(stopR * 0.0018, 9.1) - 0.5) * 160;
  vertex(stopR, endRY);
  endShape();

  for (let i = 0; i < 20; i++) {
    stroke(172, 166, 154, random(8, 40));
    strokeWeight(random(0.3, 1.3));
    let ang = random(PI - 0.7, PI + 0.7);
    let len = random(5, 50);
    line(stopR, endRY, stopR + cos(ang) * len, endRY + sin(ang) * len * 0.3);
  }

  for (let i = 0; i < 26; i++) {
    let x = random(W);
    if (abs(x - CX) < VOID_W * 0.72 + 30) continue;

    let y0 = random(H * 0.1, H * 0.9);
    let len = random(60, 420);
    let a = random(8, 38);

    if (random() < 0.2) stroke(104, 46, 38, a);
    else stroke(142, 140, 136, a);

    strokeWeight(random(0.5, 2.2));
    line(x, y0, x + random(-12, 12), y0 + len);

    if (random() < 0.6) {
      let gap = random(10, 40);
      line(
        x + random(-12, 12),
        y0 + len + gap,
        x + random(-18, 18),
        y0 + len + gap + random(10, 100)
      );
    }
  }
}

function paintAsh() {
  strokeCap(ROUND);

  for (let i = 0; i < 18000; i++) {
    let x = random(W);
    let y = random(H);

    let nx = (x - CX) / (VOID_W * 0.72);
    let ny = (y - CY) / (VOID_H * 0.60);
    let d = nx * nx + ny * ny;

    if (d < 1 && random() < 0.82) continue;

    let p = random();
    let a = random(3, 26);
    if (d < 1.35) a *= 0.45;

    let r, g, b;

    if (p < 0.72) {
      let v = 90 + random(70);
      r = v;
      g = v * 0.97;
      b = v * 0.92;
    } else if (p < 0.90) {
      r = 136 + random(60);
      g = 124 + random(52);
      b = 104 + random(46);
    } else if (p < 0.97) {
      r = 94 + random(46);
      g = 42 + random(26);
      b = 36 + random(22);
    } else {
      r = 176 + random(50);
      g = 172 + random(46);
      b = 160 + random(42);
      a *= 1.3;
    }

    stroke(r, g, b, a);
    strokeWeight(random(0.4, 2.6));
    point(x, y);

    if (random() < 0.04) {
      strokeWeight(random(0.3, 1.1));
      line(x, y, x + random(-14, 14), y + random(-30, 30));
    }
  }
}

function paintGrainAndVignette() {
  for (let i = 0; i < 130; i++) {
    let x = random(W);
    let y = random(H);
    let vertical = random() < 0.7;
    let ang = vertical ? HALF_PI + random(-0.16, 0.16) : random(-0.25, 0.25);
    let len = random(30, 500);
    let a = random(2, 12);

    if (random() < 0.5) stroke(190, 186, 178, a);
    else stroke(10, 10, 12, a);

    strokeWeight(random(0.3, 1.4));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }

  for (let i = 0; i < 12000; i++) {
    let x = random(W);
    let y = random(H);
    let v = random();

    if (v < 0.5) stroke(0, 0, 0, random(3, 12));
    else stroke(200, 195, 185, random(2, 8));

    strokeWeight(random(0.3, 1.5));
    point(x, y);
  }

  noFill();

  for (let x = 0; x < 260; x++) {
    let a = map(x, 0, 260, 58, 0);
    stroke(4, 5, 8, a);
    strokeWeight(1);
    line(x, 0, x, H);
    line(W - x, 0, W - x, H);
  }

  for (let y = 0; y < 320; y++) {
    let a = map(y, 0, 320, 65, 0);
    stroke(4, 5, 8, a);
    line(0, y, W, y);
    line(0, H - y, W, H - y);
  }
}

const CX = 825;
const CY = 1010;
const RX = 350;
const RY = 555;

const WARM = [
  [220, 205, 172],
  [186, 148, 99],
  [148, 91, 63],
  [121, 139, 133],
  [203, 184, 149]
];

const COOL = [
  [104, 133, 145],
  [73, 98, 116],
  [157, 165, 153],
  [200, 194, 172],
  [101, 119, 117]
];

const EARTH = [
  [171, 78, 57],
  [188, 116, 73],
  [211, 173, 123],
  [112, 110, 102],
  [105, 131, 132]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  colorMode(RGB, 255);
  angleMode(RADIANS);
  smooth();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  background(12);

  const ground = drawingContext.createLinearGradient(0, 0, 1600, 2000);
  ground.addColorStop(0, "#1a2024");
  ground.addColorStop(0.46, "#17191a");
  ground.addColorStop(1, "#090d11");
  drawingContext.fillStyle = ground;
  drawingContext.fillRect(0, 0, width, height);

  wash(260, 530, 980, "rgba(128,91,57,0.22)", "rgba(128,91,57,0)");
  wash(1120, 1560, 980, "rgba(36,71,80,0.22)", "rgba(36,71,80,0)");
  wash(540, 1740, 780, "rgba(121,49,38,0.14)", "rgba(121,49,38,0)");
  wash(1370, 300, 700, "rgba(107,119,113,0.09)", "rgba(107,119,113,0)");

  for (let i = 0; i < 950; i++) {
    const x = random(-80, width + 80);
    const y = random(-50, height);
    const c = x < CX ? [190, 160, 120] : [100, 130, 140];
    const n = noise(x * 0.002, y * 0.002);
    stroke(c[0], c[1], c[2], random(2, 8) * (0.4 + n));
    strokeWeight(random(1, 8));
    line(x, y, x + random(-34, 34), y + random(20, 180));
  }

  for (let i = 0; i < 38000; i++) {
    const x = random(width);
    const y = random(height);
    const a = random(2, 8);
    if (random() > 0.5) {
      stroke(225, 216, 197, a);
    } else {
      stroke(0, 0, 0, a);
    }
    strokeWeight(random(0.35, 1.25));
    point(x, y);
  }

  for (let i = 0; i < 130; i++) {
    const a = random(TWO_PI);
    drawCurrent(
      a,
      random(1.18, 3.35),
      random(-0.16, 0.16),
      random(6, 42),
      random(5, 22),
      pigmentFor(a),
      72,
      true
    );
  }

  for (let i = 0; i < 1650; i++) {
    const a = random(TWO_PI);
    const gate = noise(4 + cos(a) * 1.4, 9 + sin(a) * 1.4);

    if (random() > 0.48 + gate * 0.75) continue;
    if (cos(a) > 0.3 && random() < 0.28) continue;

    drawCurrent(
      a,
      random(1.1, 3.35),
      random(-0.12, 0.12),
      random(0.45, 2.25),
      random(28, 138),
      pigmentFor(a),
      50,
      random() < 0.22
    );
  }

  for (let i = 0; i < 210; i++) {
    const a = random(TWO_PI);
    drawCurrent(
      a,
      random(1.35, 2.8),
      random(-0.07, 0.07),
      random(0.4, 1.05),
      random(70, 155),
      pigmentFor(a),
      44,
      true
    );
  }

  for (let i = 0; i < 10500; i++) {
    const a = random(TWO_PI);
    const r = random(1.035, 3.1);
    const p = fieldPoint(a, r);

    if (p.x < 0 || p.x > width || p.y < 0 || p.y > height) continue;

    const distance = constrain((r - 1) / 1.2, 0, 1);
    if (random() > 0.16 + distance * 0.68) continue;

    const c = pigmentFor(a);
    const alpha = random(8, 48) * (0.35 + distance * 0.65);
    stroke(c[0], c[1], c[2], alpha);
    strokeWeight(random(0.4, 2.1));

    const len = random(0, 3.6);
    line(
      p.x,
      p.y,
      p.x + cos(a + HALF_PI) * len,
      p.y + sin(a + HALF_PI) * len
    );
  }

  const vignette = drawingContext.createRadialGradient(
    800, 1000, 500,
    800, 1000, 1350
  );
  vignette.addColorStop(0, "rgba(0,0,0,0)");
  vignette.addColorStop(0.72, "rgba(0,0,0,0.08)");
  vignette.addColorStop(1, "rgba(0,0,0,0.48)");
  drawingContext.fillStyle = vignette;
  drawingContext.fillRect(0, 0, width, height);

  noStroke();
  fill(7, 9, 11);
  beginShape();
  for (let i = 0; i < 360; i++) {
    const p = fieldPoint((i / 360) * TWO_PI, 1);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function wash(x, y, radius, inner, outer) {
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, inner);
  g.addColorStop(1, outer);
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - radius, y - radius, radius * 2, radius * 2);
}

function boundary(a) {
  return 1
    + 0.055 * sin(3 * a + 0.7)
    + 0.035 * sin(5 * a - 1.4)
    + 0.018 * sin(9 * a + 2.1);
}

function fieldPoint(a, r) {
  const b = boundary(a);
  const x = RX * r * b * cos(a);
  const y = RY * r * b * sin(a);

  return {
    x: CX + x + 0.17 * y,
    y: CY + y
  };
}

function pigmentFor(a) {
  if (cos(a) < -0.2 && sin(a) < 0.35) return random(WARM);
  if (sin(a) > 0.2) return random(EARTH);
  return random(COOL);
}

function drawCurrent(a, outerRadius, drift, weight, alpha, c, steps, ragged) {
  const phase = random(TWO_PI);
  let previous = null;

  for (let j = 0; j <= steps; j++) {
    const t = j / steps;
    const r = lerp(outerRadius, 1.018, t)
      + 0.035 * sin(PI * t) * sin(phase + t * 5);

    const aa = a
      + drift * sin(PI * t)
      + 0.018 * sin(phase + t * 9) * sin(PI * t);

    const p = fieldPoint(aa, r);

    if (previous !== null && !(ragged && random() < 0.12)) {
      const tm = (j - 0.5) / steps;
      const envelope = pow(sin(PI * tm), 0.75) * pow(1 - tm, 0.35);
      const localAlpha = alpha * envelope * random(0.78, 1);

      stroke(c[0], c[1], c[2], localAlpha);
      strokeWeight(weight * (0.3 + envelope * 0.7) * random(0.78, 1.16));
      line(previous.x, previous.y, p.x, p.y);
    }

    previous = p;
  }
}

const W = 1600;
const H = 2000;
const CX = 790;
const CY = 920;
const VRX = 268;
const VRY = 354;

let driftEnds = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  driftEnds = [];
  paintGround();
  paintFarCurrents();
  paintHalo();
  paintUndercontours();
  paintContours();
  paintUnraveling();
  paintDust();
  paintVoid();
}

function paintGround() {
  const ctx = drawingContext;
  ctx.save();

  const g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, "#151a1e");
  g.addColorStop(0.4, "#252525");
  g.addColorStop(0.72, "#14191c");
  g.addColorStop(1, "#080d12");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();

  radialStops(630, 650, 1050, [
    [0, "rgba(139,124,103,0.10)"],
    [0.55, "rgba(108,103,91,0.045)"],
    [1, "rgba(0,0,0,0)"]
  ]);

  for (let i = 0; i < 42000; i++) {
    const x = random(W);
    const y = random(H);
    if (random() < 0.54) {
      stroke(194, 184, 163, random(2, 9));
    } else {
      stroke(0, 4, 9, random(3, 12));
    }
    strokeWeight(random(0.35, 1.3));
    point(x, y);
  }

  for (let i = 0; i < 1300; i++) {
    const x = random(W);
    const y = random(H);
    const len = random(8, 95);
    stroke(151, 148, 135, random(2, 8));
    strokeWeight(random(0.4, 1.4));
    line(x, y, x + random(-4, 4), y + len);
  }
}

function radialStops(x, y, r, stops) {
  const ctx = drawingContext;
  ctx.save();
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (const s of stops) g.addColorStop(s[0], s[1]);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

function paintFarCurrents() {
  noFill();
  for (let i = 0; i < 135; i++) {
    const x0 = random(-120, W + 120);
    const y0 = random(-350, H);
    const len = random(250, 1050);
    const pale = random() < 0.6;

    if (pale) stroke(128, 132, 125, random(2, 7));
    else stroke(2, 7, 12, random(4, 12));

    strokeWeight(random(0.5, 2.2));
    beginShape();
    for (let j = 0; j <= 42; j++) {
      const y = y0 + len * j / 42;
      const x = x0
        + 100 * (noise(x0 * 0.001 + 4, y * 0.0012) - 0.5)
        + 22 * sin(y * 0.003 + x0 * 0.004);
      vertex(x, y);
    }
    endShape();
  }
}

function paintHalo() {
  radialStops(700, 805, 900, [
    [0, "rgba(178,156,122,0.20)"],
    [0.42, "rgba(151,134,110,0.12)"],
    [0.78, "rgba(114,112,103,0.035)"],
    [1, "rgba(0,0,0,0)"]
  ]);

  radialStops(1050, 1510, 850, [
    [0, "rgba(125,132,126,0.07)"],
    [0.55, "rgba(100,111,111,0.025)"],
    [1, "rgba(0,0,0,0)"]
  ]);
}

function organicPoint(a, rx, ry, seed = 0, rough = 0) {
  const ca = cos(a);
  const sa = sin(a);
  const n0 = noise(ca * 1.25 + 3.1, sa * 1.25 + 8.7);
  const n1 = noise(
    ca * 4.2 + seed * 0.017 + 13,
    sa * 4.2 + 17,
    seed * 0.006
  );

  const w = 1
    + 0.055 * sin(3 * a + 0.7)
    + 0.027 * sin(7 * a - 0.4)
    + (n0 - 0.5) * 0.11
    + (n1 - 0.5) * rough;

  const xx = rx * w * ca;
  const yy = ry * w * sa;

  return {
    x: CX + xx + 0.12 * yy + 22 * sa * sa + (rx - VRX) * 0.025,
    y: CY + yy - 0.04 * xx + 16 * cos(2 * a) - (ry - VRY) * 0.018
  };
}

function traceOrganic(a0, arc, rx, ry, seed, rough) {
  const steps = max(8, floor(arc * 46));
  beginShape();
  for (let j = 0; j <= steps; j++) {
    const a = a0 + arc * j / steps;
    const p = organicPoint(a, rx, ry, seed, rough);
    vertex(p.x, p.y);
  }
  endShape();
}

function organicShape(scale, seed = 0, rough = 0) {
  beginShape();
  for (let j = 0; j <= 240; j++) {
    const a = TWO_PI * j / 240;
    const p = organicPoint(a, VRX * scale, VRY * scale, seed, rough);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function paintUndercontours() {
  noFill();
  for (let i = 0; i < 65; i++) {
    const t = random();
    const rx = VRX + 30 + pow(t, 1.3) * 690;
    const ry = VRY + 35 + pow(t, 1.25) * 740;
    const a0 = random() < 0.7
      ? random(PI * 0.85, PI * 1.45)
      : random(TWO_PI);

    if (random() < 0.25) stroke(161, 126, 101, random(3, 9));
    else stroke(181, 170, 145, random(2, 8));

    strokeWeight(random(8, 28));
    traceOrganic(a0, random(0.5, 2.4), rx, ry, i * 0.7, 0.06);
  }
}

function paintContours() {
  noFill();

  for (let i = 0; i < 330; i++) {
    const t = i / 329;
    const rx = VRX + 18 + pow(t, 1.35) * 720;
    const ry = VRY + 18 + pow(t, 1.28) * 770;

    let a0;
    let arc;

    if (i < 100 && random() < 0.72) {
      a0 = random(PI * 0.92, PI * 1.44);
      arc = random(0.65, 1.65);
    } else {
      a0 = random() < 0.62
        ? random(PI * 0.82, PI * 1.52)
        : random(TWO_PI);
      arc = random(0.18, 1.55);
    }

    if (random() < 0.045) arc = TWO_PI;

    const q = random();
    let c;
    if (q < 0.14) c = [164, 130, 105];
    else if (q < 0.34) c = [112, 133, 138];
    else c = [199, 185, 157];

    let alpha = random(12, 52) * (1 - 0.5 * t);
    let weight = random(0.45, 1.45);

    if (i % 19 === 0) {
      alpha *= 1.45;
      weight = random(1.4, 2.2);
    }

    stroke(c[0], c[1], c[2], alpha);
    strokeWeight(weight);
    traceOrganic(a0, arc, rx, ry, i * 0.83, random(0.015, 0.065));
  }
}

function paintUnraveling() {
  for (let i = 0; i < 185; i++) {
    const outwardFlow = i < 150;
    const a = outwardFlow ? random(-0.25, 2.05) : random(TWO_PI);
    const rx = VRX + random(80, 430);
    const ry = VRY + random(90, 520);
    const p0 = organicPoint(a, rx, ry, i * 0.41, 0.04);

    let nx = p0.x - CX;
    let ny = (p0.y - CY) * 0.8;
    const m = max(1, sqrt(nx * nx + ny * ny));
    nx /= m;
    ny /= m;

    const len = random(180, 720) * (outwardFlow ? 1 : 0.55);
    const sway = random(-120, 120);
    const fall = random(0.25, 0.9);
    const baseAlpha = random(12, 43);
    const baseWeight = random(0.55, 1.8);
    const c = random() < 0.22
      ? [128, 143, 142]
      : [190, 174, 145];

    let prev = p0;
    let p = p0;

    for (let j = 1; j <= 38; j++) {
      const t = j / 38;
      p = {
        x: p0.x
          + nx * len * 0.55 * t
          + sway * t * t
          + 24 * sin(t * 4 + a) * t,
        y: p0.y
          + ny * len * 0.18 * t
          + len * fall * t
          + 16 * sin(t * 3 + a) * t
      };

      stroke(c[0], c[1], c[2], baseAlpha * pow(1 - t, 0.65));
      strokeWeight(max(0.25, baseWeight * (1 - 0.8 * t)));
      line(prev.x, prev.y, p.x, p.y);
      prev = p;
    }

    driftEnds.push(p);
  }
}

function paintDust() {
  for (let i = 0; i < 2700; i++) {
    const e = driftEnds[floor(random(driftEnds.length))];
    const x = e.x + randomGaussian(0, 92) + random(-20, 105);
    const y = e.y + randomGaussian(0, 76) + random(0, 110);

    if (x < 0 || x > W || y < 0 || y > H) continue;

    const c = random() < 0.25
      ? [122, 139, 140]
      : [190, 177, 151];
    const alpha = random(7, 47);
    const size = random() < 0.93 ? random(0.5, 1.9) : random(2, 4.2);

    if (random() < 0.13) {
      stroke(c[0], c[1], c[2], alpha);
      strokeWeight(random(0.4, 1));
      line(x, y, x + random(-7, 7), y + random(2, 13));
    } else {
      noStroke();
      fill(c[0], c[1], c[2], alpha);
      circle(x, y, size);
    }
  }

  for (let i = 0; i < 750; i++) {
    const a = random(-0.1, 2);
    const r = random(410, 1080);
    const x = CX + cos(a) * r * 0.86 + randomGaussian(0, 65);
    const y = CY + sin(a) * r + r * 0.12 + randomGaussian(0, 70);

    if (x < 0 || x > W || y < 0 || y > H) continue;

    noStroke();
    fill(177, 169, 149, random(4, 25));
    circle(x, y, random(0.5, 2.2));
  }
}

function paintVoid() {
  noStroke();

  for (let k = 34; k >= 1; k--) {
    fill(2, 5, 8, 3.2);
    organicShape(1 + k * 0.0035, k * 0.13, 0.035);
  }

  fill(3, 5, 8, 255);
  organicShape(1, 0, 0);

  for (let i = 0; i < 130; i++) {
    const a = random(-0.1, 1.85);
    const sc = random(1.002, 1.055);
    const p = organicPoint(a, VRX * sc, VRY * sc, i * 0.2, 0.025);
    fill(3, 5, 8, random(20, 90));
    circle(p.x, p.y, random(1.5, 8));
  }

  noFill();

  for (let i = 0; i < 105; i++) {
    const highlight = random() < 0.72;
    const a0 = highlight
      ? random(PI * 0.94, PI * 1.49)
      : random(TWO_PI);
    const arc = random(0.012, 0.075);
    const sc = random(1.006, 1.032);

    if (highlight) {
      stroke(216, 200, 167, random(16, 70));
    } else {
      stroke(106, 121, 122, random(5, 24));
    }

    strokeWeight(random(0.45, 1.5));
    traceOrganic(a0, arc, VRX * sc, VRY * sc, 0, 0);
  }
}

const W = 1600;
const H = 2000;
let inks = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  inks = [
    color(226, 214, 179),
    color(196, 153, 82),
    color(157, 87, 59),
    color(83, 126, 124),
    color(53, 75, 77),
    color(177, 177, 153)
  ];
}

function draw() {
  paintGround();
  paintSediment();
  paintWeave();
  paintMotes();
  paintPatina();
  paintAbsence();
}

function paintGround() {
  const high = color(190, 184, 163);
  const middle = color(83, 94, 89);
  const deep = color(20, 29, 34);

  for (let y = 0; y < H; y++) {
    const t = y / H;
    let c;

    if (t < 0.56) {
      let u = t / 0.56;
      u = u * u * (3 - 2 * u);
      c = lerpColor(high, middle, u);
    } else {
      let u = (t - 0.56) / 0.44;
      u = u * u * (3 - 2 * u);
      c = lerpColor(middle, deep, u);
    }

    stroke(c);
    line(0, y, W, y);
  }

  const washes = [
    color(218, 194, 148),
    color(58, 93, 94),
    color(120, 77, 58),
    color(210, 211, 190)
  ];

  noStroke();
  for (let i = 0; i < 180; i++) {
    const c = washes[floor(random(washes.length))];
    fill(red(c), green(c), blue(c), random(3, 9));
    ellipse(
      random(-200, W + 200),
      random(-150, 1550),
      random(180, 940),
      random(90, 650)
    );
  }
}

function paintSediment() {
  for (let i = 0; i < 760; i++) {
    const d = pow(random(), 0.82);
    const yy = 1130 + d * 900;
    const xx = random(-180, W + 80);
    const len = random(80, 760) * (1 - 0.35 * d);
    const c = lerpColor(
      color(128, 124, 107),
      color(43, 57, 61),
      d
    );

    stroke(
      red(c),
      green(c),
      blue(c),
      random(12, 62) * (1 - 0.55 * d)
    );
    strokeWeight(random(0.4, 2.6));
    noFill();

    const amp = random(1, 10) * (1 - 0.5 * d);
    const phase = random(TWO_PI);
    const frequency = random(0.004, 0.015);

    beginShape();
    for (let k = 0; k <= 26; k++) {
      const x = xx + len * k / 26;
      const y = yy
        + sin(x * frequency + phase) * amp
        + (noise(x * 0.003, yy * 0.004) - 0.5) * 5;
      vertex(x, y);
    }
    endShape();
  }

  noStroke();
  for (let i = 0; i < 2600; i++) {
    const d = random();
    const y = 1160 + pow(d, 0.8) * 840;
    const c = lerpColor(
      color(145, 137, 113),
      color(52, 65, 66),
      d
    );
    fill(red(c), green(c), blue(c), random(8, 42) * (1 - d * 0.6));
    circle(random(W), y, random(0.5, 2.8));
  }
}

function paintWeave() {
  for (let i = 0; i < 180; i++) {
    const x1 = random(-80, W + 80);
    const y1 = random(-50, 950);
    const x2 = random(-80, W + 80);
    const y2 = random(50, 1100);
    const c = random() < 0.55 ? inks[4] : inks[0];

    stroke(red(c), green(c), blue(c), random(10, 34));
    strokeWeight(random(0.4, 1.2));
    noFill();
    bezier(
      x1, y1,
      random(W), random(100, 800),
      random(W), random(200, 1000),
      x2, y2
    );
  }

  for (let i = 0; i < 740; i++) {
    let x = random(-150, W + 150);
    let y = random(-320, 720);
    const steps = floor(random(35, 155));
    const limit = random(940, 1260);
    const phase = random(1000);
    const drift = random(-0.7, 0.7);
    const c = inks[floor(random(inks.length))];
    const alpha = random(25, 115);

    stroke(red(c), green(c), blue(c), alpha);
    strokeWeight(random(0.4, 1.8));
    noFill();
    beginShape();

    for (let j = 0; j < steps; j++) {
      if (y > limit || x < -260 || x > W + 260) break;

      vertex(x, y);

      const n = noise(x * 0.0018, y * 0.0024, phase);
      const n2 = noise(y * 0.003, phase);
      x += (n - 0.5) * 8.5
        + sin(y * 0.004 + phase) * 0.55
        + drift;
      y += 2 + n2 * 4.2;
    }

    endShape();
  }

  for (let i = 0; i < 42; i++) {
    const x0 = random(-100, W + 100);
    const y0 = random(-250, 80);
    const x3 = random(50, W - 50);
    const y3 = random(800, 1250);
    const x1 = x0 + random(-420, 420);
    const y1 = random(180, 520);
    const x2 = x3 + random(-520, 520);
    const y2 = random(480, 930);
    const phase = random(TWO_PI);
    const c = inks[floor(random(4))];
    const baseWidth = random(1.2, 3.8);
    const baseAlpha = random(75, 155);

    let px = x0;
    let py = y0;

    for (let k = 1; k <= 120; k++) {
      const t = k / 120;
      const envelope = sin(PI * t);
      const x = cubic(x0, x1, x2, x3, t)
        + sin(t * 13 + phase) * 5 * envelope;
      const y = cubic(y0, y1, y2, y3, t)
        + cos(t * 9 + phase) * 2 * envelope;

      stroke(
        red(c),
        green(c),
        blue(c),
        baseAlpha * (0.25 + 0.75 * envelope)
      );
      strokeWeight(baseWidth * (0.45 + 0.55 * envelope));
      line(px, py, x, y);
      px = x;
      py = y;
    }
  }
}

function paintMotes() {
  noStroke();

  for (let i = 0; i < 3600; i++) {
    const x = random(-20, W + 20);
    const y = pow(random(), 1.1) * 1260 - 30;
    const c = inks[floor(random(inks.length))];
    const fade = map(constrain(y, 0, 1240), 0, 1240, 1, 0.25);
    const a = random(18, 110) * fade;
    const r = random(0.5, 3.4);

    fill(red(c), green(c), blue(c), a);

    if (random() < 0.16) {
      push();
      translate(x, y);
      rotate(random(TWO_PI));
      ellipse(0, 0, r * 3.2, r * 0.65);
      pop();
    } else {
      circle(x, y, r);
    }
  }
}

function paintPatina() {
  for (let i = 0; i < 58000; i++) {
    const light = random() < 0.48;
    if (light) {
      stroke(226, 216, 188, random(3, 15));
    } else {
      stroke(13, 24, 28, random(3, 17));
    }
    strokeWeight(random(0.35, 1.25));
    point(random(W), random(H));
  }

  for (let i = 0; i < 1300; i++) {
    const x = random(W);
    const y = random(H);
    const len = random(1, 9);
    stroke(222, 210, 179, random(3, 12));
    strokeWeight(random(0.3, 0.8));
    line(x, y, x + len, y + random(-1.2, 1.2));
  }
}

function paintAbsence() {
  noStroke();

  for (let k = 12; k >= 1; k--) {
    fill(10, 16, 19, 4);
    absenceShape(1 + k * 0.004);
  }

  fill(10, 15, 18);
  absenceShape(1);
}

function absenceShape(s) {
  beginShape();

  for (let i = 0; i <= 240; i++) {
    const a = TWO_PI * i / 240;
    const wobble = 1
      + 0.016 * sin(3 * a + 0.4)
      + 0.008 * sin(7 * a);
    const x = 800 + cos(a) * 700 * s * wobble;
    const y = 1035
      + sin(a) * 176 * s * (1 + 0.035 * cos(2 * a - 0.2))
      + 9 * sin(2 * a);
    vertex(x, y);
  }

  endShape(CLOSE);
}

function cubic(a, b, c, d, t) {
  const u = 1 - t;
  return u * u * u * a
    + 3 * u * u * t * b
    + 3 * u * t * t * c
    + t * t * t * d;
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  angleMode(RADIANS);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  paintGround();
  paintHush();
  paintWovenForm();
  paintRelease();
  paintStillWater();
  paintGrain();
  paintVignette();
}

function paintGround() {
  background(7, 10, 11);

  const high = color(7, 10, 12);
  const middle = color(25, 33, 32);
  const low = color(6, 11, 13);

  noStroke();
  for (let y = 0; y < H; y += 3) {
    const t = y / H;
    let c;

    if (t < 0.63) {
      c = lerpColor(high, middle, pow(t / 0.63, 1.18));
    } else {
      c = lerpColor(middle, low, (t - 0.63) / 0.37);
    }

    const n = (noise(2.1, y * 0.006) - 0.5) * 7;
    fill(red(c) + n, green(c) + n, blue(c) + n);
    rect(0, y, W, 4);
  }

  for (let i = 0; i < 150; i++) {
    const warm = random() < 0.18;
    if (warm) {
      fill(88, 69, 43, random(1, 4));
    } else {
      fill(61, 82, 75, random(1, 4.5));
    }
    ellipse(
      random(-250, W + 250),
      random(-100, H + 100),
      random(220, 950),
      random(70, 430)
    );
  }

  for (let i = 0; i < 420; i++) {
    const x = random(W);
    const y = random(H);
    stroke(99, 105, 91, random(1, 4));
    strokeWeight(random(1, 15));
    line(x, y, x + random(-14, 14), y + random(35, 460));
  }
}

function paintHush() {
  noStroke();

  for (let i = 0; i < 100; i++) {
    const t = 1 - i / 100;
    fill(67, 73, 60, 0.72);
    ellipse(800, 875, 1200 * t, 1540 * t);
  }

  for (let i = 0; i < 74; i++) {
    const t = 1 - i / 74;
    fill(2, 6, 7, 0.86);
    ellipse(790, 820, 525 * t, 790 * t);
  }
}

function formPoint(u, q, phase, drift) {
  u = constrain(u, 0, 1);

  const envelope = pow(max(0, sin(PI * u)), 0.72);
  const breadth = 312 * envelope * (0.82 + 0.28 * u);
  const release = pow(constrain((u - 0.48) / 0.52, 0, 1), 1.55);
  const centerX = 790 + 32 * sin(u * PI * 1.25) - 20 * u;

  let x = centerX + q * breadth;
  x += (noise(phase * 0.07, u * 3.2) - 0.5) * (8 + 28 * release);
  x += release * drift * 190 + release * release * 55;

  const y = 438 + 822 * u + release * 38 * sin(phase + u * 5);
  return { x, y };
}

function paintWovenForm() {
  for (let i = 0; i < 430; i++) {
    const theta = random(TAU);
    const q = cos(theta);
    const depth = sin(theta);
    const phase = random(1000);
    const drift = random(-1, 1);
    const startU = random(0, 0.045);
    const endU = random(0.78, 1.02);
    const weight = random(0.5, 1.45);

    let baseAlpha;
    let tone = random();

    if (depth < -0.1) {
      stroke(65, 83, 78);
      baseAlpha = random(10, 29);
    } else if (tone < 0.18) {
      baseAlpha = random(20, 54);
    } else {
      baseAlpha = random(23, 70);
    }

    let previous = null;
    let previouslyVisible = false;
    const steps = 140;

    for (let j = 0; j <= steps; j++) {
      const u = lerp(startU, endU, j / steps);
      const p = formPoint(u, q, phase, drift);
      const erosion = constrain((u - 0.5) / 0.5, 0, 1);
      const gate = noise(phase * 0.013, u * 19);
      const visible = u < 0.56 || gate > erosion * 0.79;
      const a = baseAlpha *
        (0.65 + 0.35 * sin(PI * constrain(u, 0, 1))) *
        (1 - erosion * 0.75);

      if (depth < -0.1) {
        stroke(65, 83, 78, a);
      } else if (tone < 0.18) {
        stroke(154, 128, 84, a);
      } else {
        stroke(194, 191, 167, a);
      }

      strokeWeight(weight * (1 - erosion * 0.25));

      if (previous && visible && previouslyVisible) {
        line(previous.x, previous.y, p.x, p.y);
      }

      previous = p;
      previouslyVisible = visible;
    }
  }
}

function paintRelease() {
  for (let i = 0; i < 1850; i++) {
    const u = random(0.55, 1.04);
    const side = random() < 0.5 ? -1 : 1;
    const q = side * random(0.25, 1.08);
    const p = formPoint(
      min(u, 1),
      q,
      random(1000),
      random(-1, 1)
    );

    const d = constrain((u - 0.55) / 0.45, 0, 1);
    const x = p.x + randomGaussian() * (8 + 165 * d) + 70 * d * d;
    const y = p.y +
      randomGaussian() * (5 + 35 * d) +
      random(0, 125) * d;

    if (x < 50 || x > W - 50 || y > 1510) continue;

    const warm = random() < 0.16;
    const a = random(9, 55) * (1 - 0.58 * d);

    if (warm) {
      stroke(161, 134, 89, a);
    } else {
      stroke(183, 185, 163, a);
    }

    if (random() < 0.74) {
      strokeWeight(random(0.45, 1.65));
      line(
        x,
        y,
        x + random(-2, 4) + random(0, 7) * d,
        y + random(1, 5 + 7 * d)
      );
    } else {
      strokeWeight(random(0.7, 2.3));
      point(x, y);
    }
  }

  for (let i = 0; i < 170; i++) {
    const y = random(1280, 1500);
    const d = (y - 1280) / 220;
    const x = 855 + randomGaussian() * (115 + 175 * d);
    stroke(154, 158, 139, random(3, 18) * (1 - d * 0.5));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + random(1, 7) * d, y + random(1, 5));
  }
}

function paintStillWater() {
  for (let i = 0; i < 390; i++) {
    const y = random(1465, H);
    const x = random(-100, W);
    const depth = (y - 1465) / (H - 1465);
    const len = random(20, 270) * (0.55 + depth);

