function paintVignette() {
  const ctx = drawingContext;
  ctx.save();

  const g = ctx.createRadialGradient(
    W * 0.5, H * 0.45, 180,
    W * 0.5, H * 0.48, 1180
  );
  g.addColorStop(0, "rgba(0,0,0,0)");
  g.addColorStop(0.62, "rgba(0,0,0,0.025)");
  g.addColorStop(1, "rgba(0,0,0,0.53)");

  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
  ctx.restore();
}

const W = 1600;
const H = 2000;
const CX = 950;
const CY = 885;
const RX = 292;
const RY = 500;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  paintGround();
  paintEarth();
  paintCurrents();
  paintFraying();
  paintAbsence();
}

function paintGround() {
  const top = color(139, 153, 148);
  const middle = color(211, 201, 177);
  const bottom = color(105, 94, 76);

  noStroke();
  for (let y = 0; y < H; y += 4) {
    const t = y / H;
    let c;
    if (t < 0.58) {
      c = lerpColor(top, middle, pow(t / 0.58, 0.82));
    } else {
      c = lerpColor(middle, bottom, pow((t - 0.58) / 0.42, 0.9));
    }
    fill(c);
    rect(0, y, W, 5);
  }

  for (let i = 0; i < 280; i++) {
    const x = random(-250, W + 250);
    const y = random(-150, H + 150);
    if (random() < 0.56) {
      fill(179, 139, 96, random(1.5, 5));
    } else {
      fill(55, 82, 80, random(1.5, 5));
    }
    ellipse(x, y, random(180, 900), random(90, 520));
  }

  strokeCap(SQUARE);
  for (let i = 0; i < 28000; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.0021, y * 0.0021);
    const len = random(3, 62);
    const a = random(-0.16, 0.16) + 0.18 * sin(y * 0.003);

    if (n < 0.34) {
      stroke(239, 230, 207, random(4, 13));
    } else if (n < 0.67) {
      stroke(68, 76, 67, random(3, 10));
    } else {
      stroke(126, 91, 65, random(3, 11));
    }

    strokeWeight(random(0.35, 1.8));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  for (let i = 0; i < 2400; i++) {
    const x = random(W);
    const y = random(H);
    stroke(232, 221, 196, random(3, 10));
    strokeWeight(random(0.4, 1.2));
    line(x, y, x + random(-2, 2), y + random(5, 38));
  }
}

function paintEarth() {
  noStroke();
  for (let j = 0; j < 13; j++) {
    const base = 1435 + j * 18;
    fill(45 + j * 1.8, 48 + j * 1.4, 40 + j, 12);
    beginShape();
    vertex(0, H);
    vertex(0, base);
    for (let x = 0; x <= W; x += 40) {
      const y = base
        + (noise(x * 0.0027, j * 0.73) - 0.5) * 155
        + sin(x * 0.004 + j) * 24;
      vertex(x, y);
    }
    vertex(W, H);
    endShape(CLOSE);
  }

  const earthColors = [
    [39, 45, 40],
    [80, 66, 50],
    [130, 102, 68],
    [159, 132, 91],
    [70, 83, 75]
  ];

  for (let i = 0; i < 6500; i++) {
    const x = random(W);
    const y = 1430 + pow(random(), 0.62) * 620;
    const len = random(5, 74);
    const a = -HALF_PI + random(-1.15, 1.15);
    const c = pick(earthColors);
    stroke(c[0], c[1], c[2], random(8, 35));
    strokeWeight(random(0.4, 2.4));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  noFill();
  for (let i = 0; i < 150; i++) {
    const x = random(W);
    const y = random(1710, 2070);
    const c = pick(earthColors);
    stroke(c[0], c[1], c[2], random(14, 42));
    strokeWeight(random(0.5, 2));
    bezier(
      x, y,
      x + random(-90, 90), y - random(50, 180),
      x + random(-220, 220), random(1480, 1640),
      x + random(-260, 260), random(1390, 1560)
    );
  }
}

function paintCurrents() {
  strokeCap(ROUND);
  const currentColors = [
    [78, 91, 84],
    [103, 82, 64],
    [142, 102, 69],
    [66, 86, 86],
    [164, 142, 105],
    [100, 105, 91],
    [91, 67, 57]
  ];

  noFill();
  for (let i = 0; i < 340; i++) {
    const col = i % 31 === 0
      ? [121, 55, 45]
      : pick(currentColors);
    const p = makeCurrent(col);
    const broad = i < 20;

    if (broad) {
      stroke(col[0], col[1], col[2], 4.5);
      strokeWeight(random(30, 95));
      drawCurrent(p, 0, i + 1);
    }

    const hairs = broad ? 15 : 1;
    for (let h = 0; h < hairs; h++) {
      const offset = broad ? randomGaussian() * 14 : random(-1.5, 1.5);
      const alpha = broad ? random(8, 22) : random(16, 51);
      stroke(col[0], col[1], col[2], alpha);
      strokeWeight(broad ? random(0.5, 2.3) : random(0.45, 1.75));
      drawCurrent(p, offset, i * 19 + h + 3);
    }
  }

  const thread = {
    p0: createVector(170, 2020),
    p1: createVector(245, 1640),
    p2: createVector(580, 1510),
    p3: contourPoint(2.06, 1.035)
  };

  stroke(116, 48, 40, 105);
  strokeWeight(4.2);
  drawCurrent(thread, 0, 811);
  stroke(151, 75, 54, 125);
  strokeWeight(1.35);
  drawCurrent(thread, -1.5, 812);
}

function makeCurrent(col) {
  const r = random();
  let a;

  if (r < 0.72) {
    a = random(1.30, 3.68);
  } else if (r < 0.89) {
    a = random(3.68, 5.05);
  } else {
    a = random(TAU);
  }

  const end = contourPoint(a, random(1.025, 1.22));
  const side = random();
  let start;
  let control;

  if (side < 0.57) {
    start = createVector(random(-180, -30), random(260, 1840));
    control = createVector(
      start.x + random(180, 610),
      start.y + random(-360, 360)
    );
  } else if (side < 0.86) {
    start = createVector(random(-80, 1370), random(2010, 2140));
    control = createVector(
      start.x + random(-310, 310),
      start.y - random(220, 650)
    );
  } else {
    start = createVector(random(-80, W + 80), random(-150, -30));
    control = createVector(
      start.x + random(-320, 320),
      start.y + random(180, 520)
    );
  }

  const inward = atan2(CY - end.y, CX - end.x);
  const reach = random(190, 570);
  const beforeEnd = createVector(
    end.x - cos(inward) * reach,
    end.y - sin(inward) * reach
  );

  return {
    p0: start,
    p1: control,
    p2: beforeEnd,
    p3: createVector(end.x, end.y),
    col: col
  };
}

function drawCurrent(p, offset, seed) {
  beginShape();
  for (let k = 0; k <= 92; k++) {
    const t = k / 92;
    const q = cubicPoint(p.p0, p.p1, p.p2, p.p3, t);
    const wave = (noise(seed * 0.17 + t * 4, seed * 0.031) - 0.5) * 13;
    vertex(
      q.x + offset * 0.55 + wave,
      q.y + offset + wave * 0.35
    );
  }
  endShape();
}

function cubicPoint(p0, p1, p2, p3, t) {
  const u = 1 - t;
  const a = u * u * u;
  const b = 3 * u * u * t;
  const c = 3 * u * t * t;
  const d = t * t * t;
  return {
    x: a * p0.x + b * p1.x + c * p2.x + d * p3.x,
    y: a * p0.y + b * p1.y + c * p2.y + d * p3.y
  };
}

function paintFraying() {
  const frayColors = [
    [59, 68, 61],
    [105, 83, 63],
    [161, 133, 94],
    [222, 211, 184],
    [82, 99, 94]
  ];

  for (let i = 0; i < 1050; i++) {
    const a = random(TAU);
    const s = 1.006 + pow(random(), 2.1) * 0.22;
    const p = contourPoint(a, s);
    const q = contourPoint(
      a + random(-0.022, 0.022),
      s + random(-0.006, 0.022)
    );
    const c = pick(frayColors);
    stroke(c[0], c[1], c[2], random(10, 48));
    strokeWeight(random(0.35, 1.9));
    line(
      p.x + random(-2, 2),
      p.y + random(-2, 2),
      q.x + random(-5, 5),
      q.y + random(-5, 5)
    );
  }

  for (let i = 0; i < 95; i++) {
    const a = random(1.2, 3.9);
    const p = contourPoint(a, random(1.01, 1.12));
    const c = pick(frayColors);
    stroke(c[0], c[1], c[2], random(8, 25));
    strokeWeight(random(2, 5));
    line(
      p.x,
      p.y,
      p.x + random(-20, 20),
      p.y + random(-20, 20)
    );
  }
}

function paintAbsence() {
  noStroke();

  for (let i = 10; i >= 1; i--) {
    fill(224, 214, 190, 1.35);
    absenceShape(1.015 + i * 0.007);
  }

  for (let i = 36; i >= 1; i--) {
    fill(25, 36, 34, 1.65 + (36 - i) * 0.012);
    absenceShape(1 + i * 0.0042);
  }

  fill(14, 21, 22);
  absenceShape(1.001);

  drawingContext.save();
  traceAbsence(drawingContext, 1.002);
  drawingContext.clip();

  const upper = color(27, 38, 37);
  const lower = color(5, 10, 12);

  noStroke();
  for (let y = CY - RY * 1.2; y < CY + RY * 1.2; y += 4) {
    const t = constrain((y - (CY - RY)) / (2 * RY), 0, 1);
    const c = lerpColor(upper, lower, pow(t, 0.68));
    fill(c);
    rect(CX - RX * 1.25, y, RX * 2.5, 5);
  }

  for (let i = 0; i < 950; i++) {
    const x = random(CX - RX, CX + RX);
    const y = random(CY - RY, CY + RY);
    stroke(91, 103, 93, random(0.8, 3.2));
    strokeWeight(random(0.5, 3.5));
    line(x, y, x + random(-7, 7), y + random(18, 150));
  }

  noStroke();
  for (let i = 60; i > 0; i--) {
    fill(2, 7, 9, 1.45);
    ellipse(
      CX + 35,
      CY + 55,
      90 + i * 12,
      130 + i * 17
    );
  }

  drawingContext.restore();

  for (let i = 0; i < 900; i++) {
    const a = random(TAU);
    const p = contourPoint(a, random(0.998, 1.004));
    const q = contourPoint(
      a + random(-0.012, 0.012),
      random(1, 1.008)
    );
    stroke(9, 16, 17, random(28, 105));
    strokeWeight(random(0.4, 2.8));
    line(p.x, p.y, q.x, q.y);
  }
}

function contourPoint(a, s = 1) {
  const sn = sin(a);
  const cs = cos(a);
  const r = 1
    + 0.026 * sin(3 * a + 0.8)
    + 0.018 * sin(7 * a - 1.2)
    + 0.011 * sin(13 * a + 0.4);
  const taper = 0.93 + 0.07 * sn;

  return {
    x: CX
      + cs * RX * s * r * taper
      + 18 * sin(2 * a + 0.3) * s,
    y: CY
      + sn * RY * s * r
      + 12 * sin(3 * a) * s
  };
}

function absenceShape(s) {
  beginShape();
  for (let i = 0; i < 200; i++) {
    const p = contourPoint((i / 200) * TAU, s);
    vertex(p.x, p.y);
  }
  endShape(CLOSE);
}

function traceAbsence(ctx, s) {
  ctx.beginPath();
  for (let i = 0; i < 200; i++) {
    const p = contourPoint((i / 200) * TAU, s);
    if (i === 0) {
      ctx.moveTo(p.x, p.y);
    } else {
      ctx.lineTo(p.x, p.y);
    }
  }
  ctx.closePath();
}

function pick(arr) {
  return arr[floor(random(arr.length))];
}

// Toile fixe 1600 x 2000 — tout est peint une seule fois, dans setup().

const W = 1600;
const H = 2000;

// Ancrages du fil unique (spline de Catmull-Rom passant par ces points).
const CTRL = [
  [665, 150],
  [560, 470],
  [945, 890],
  [640, 1255],
  [925, 1490],
  [872, 1690]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
  paint();
}

function paint() {
  background(11, 14, 19);
  baseGradient();
  fogs();
  weave();
  echoThreads();
  fieldOfEnds();
  branches();
  thread();
  dissolution();
  emergence();
  endPoint();
  imprint();
  grain();
  vignette();
}

/* ---------- géométrie et utilitaires ---------- */

function smoothstep(a, b, x) {
  const t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function spline(t) {
  const n = CTRL.length;
  const s = constrain(t, 0, 1) * (n - 1);
  let i = Math.floor(s);
  if (i >= n - 1) i = n - 2;
  const u = s - i;
  const p0 = CTRL[Math.max(0, i - 1)];
  const p1 = CTRL[i];
  const p2 = CTRL[i + 1];
  const p3 = CTRL[Math.min(n - 1, i + 2)];
  const u2 = u * u;
  const u3 = u2 * u;
  return {
    x: 0.5 * (2 * p1[0] + (-p0[0] + p2[0]) * u +
        (2 * p0[0] - 5 * p1[0] + 4 * p2[0] - p3[0]) * u2 +
        (-p0[0] + 3 * p1[0] - 3 * p2[0] + p3[0]) * u3),
    y: 0.5 * (2 * p1[1] + (-p0[1] + p2[1]) * u +
        (2 * p0[1] - 5 * p1[1] + 4 * p2[1] - p3[1]) * u2 +
        (-p0[1] + 3 * p1[1] - 3 * p2[1] + p3[1]) * u3)
  };
}

function bez(ax, ay, cx, cy, bx, by, u) {
  const v = 1 - u;
  return { x: v * v * ax + 2 * v * u * cx + u * u * bx,
           y: v * v * ay + 2 * v * u * cy + u * u * by };
}

function fog(x, y, r, cr, cg, cb, a) {
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + cr + ',' + cg + ',' + cb + ',' + a + ')');
  g.addColorStop(1, 'rgba(' + cr + ',' + cg + ',' + cb + ',0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, 2 * r, 2 * r);
}

// Couleur du fil : ambre chaud -> gris-bleu froid.
function threadRGB(t) {
  const cool = smoothstep(0.45, 0.95, t);
  return [lerp(246, 168, cool), lerp(222, 188, cool), lerp(178, 214, cool)];
}

// Épaisseur du fil : naît fin, s'épaissit (plein de la vie), s'effile, se délie.
function thick(t) {
  let e;
  if (t < 0.34)      e = 3.5 + 14.5 * Math.pow(t / 0.34, 0.85);
  else if (t < 0.62) e = lerp(18, 3.2, smoothstep(0.34, 0.62, t));
  else               e = lerp(3.2, 0.8, smoothstep(0.62, 0.96, t));
  e *= 0.86 + 0.28 * noise(t * 22 + 7.3);
  return e;
}

/* ---------- couches ---------- */

function baseGradient() {
  const g = drawingContext.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#141922');
  g.addColorStop(0.45, '#0f131a');
  g.addColorStop(0.8, '#0b0e13');
  g.addColorStop(1, '#090b0f');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function fogs() {
  for (let i = 0; i < 7; i++) { // brumes claires : le domaine des formes
    const x = random() * W, y = 60 + random() * 720;
    fog(x, y, 260 + random() * 320, 96, 108, 128, 0.035 + random() * 0.03);
  }
  for (let i = 0; i < 8; i++) { // brumes sombres : l'indifférencié
    const x = random() * W, y = 1250 + random() * 780;
    fog(x, y, 300 + random() * 380, 3, 5, 9, 0.05 + random() * 0.05);
  }
  const pv = spline(0.38); // chaleur diffuse de la présence
  fog(pv.x, pv.y, 430, 176, 138, 82, 0.05);
  const pw = spline(0.55);
  fog(pw.x, pw.y, 320, 150, 118, 76, 0.04);
}

function weave() { // trame textile de la toile
  noFill();
  strokeWeight(1);
  for (let y = 10; y < H; y += 15) {
    stroke(150, 162, 182, 2.2 + 1.8 * smoothstep(1200, 1900, y));
    beginShape();
    for (let x = 0; x <= W; x += 50) {
      vertex(x, y + (noise(x * 0.0035, y * 0.02) - 0.5) * 6);
    }
    endShape();
  }
  stroke(150, 162, 182, 1.6);
  for (let x = 12; x < W; x += 26) {
    beginShape();
    for (let y = 0; y <= H; y += 60) {
      vertex(x + (noise(x * 0.02, y * 0.0035) - 0.5) * 5, y);
    }
    endShape();
  }
}

function echoThreads() { // traces fantômes d'autres parcours
  noFill();
  for (let i = 0; i < 6; i++) {
    const off = (random() - 0.5) * 260;
    stroke(112, 126, 150, 2 + random() * 3);
    strokeWeight(1 + random() * 1.6);
    beginShape();
    for (let t = 0.06; t <= 0.72; t += 0.02) {
      const p = spline(t);
      vertex(p.x + off + noise(t * 3 + i * 10) * 30 - 15, p.y);
    }
    endShape();
  }
}

function fieldOfEnds() { // le champ : innombrables fils déjà éteints
  noFill();
  for (let i = 0; i < 1500; i++) {
    const y = 1430 + 560 * Math.pow(random(), 0.62);
    const x0 = random() * W;
    const len = 50 + Math.pow(random(), 2) * 420;
    const bend = (noise(x0 * 0.01, y * 0.05) - 0.5) * 30;
    const a = 2.5 + random() * 8;
    if (random() < 0.12) stroke(120, 106, 84, a * 0.8);
    else stroke(84, 95, 112, a);
    strokeWeight(0.8 + random() * 0.9);
    bezier(x0, y, x0 + len * 0.3, y + bend * 0.2,
           x0 + len * 0.7, y + bend * 0.8, x0 + len, y + bend);
  }
  for (let i = 0; i < 160; i++) { // rares traces partout, pas seulement en bas
    const y = 150 + random() * 1300;
    const x0 = random() * W;
    const len = 40 + random() * 130;
    stroke(84, 95, 112, 1.5 + random() * 2);
    strokeWeight(0.8);
    line(x0, y, x0 + len, y + (random() - 0.5) * 8);
  }
}

function branches() { // les attaches : chacune s'évanouit à sa façon
  const brs = [
    [0.10, -1, 150], [0.19, 1, 115], [0.30, -1, 225],
    [0.415, 1, 185], [0.54, -1, 130], [0.665, 1, 95]
  ];
  noFill();
  for (let b = 0; b < brs.length; b++) {
    const bt = brs[b][0], side = brs[b][1], len = brs[b][2];
    const A = spline(bt);
    const e = thick(bt);
    const tipX = A.x + side * len * (0.85 + random() * 0.25);
    const tipY = A.y + 35 + len * 0.5;
    const cx = A.x + side * len * 0.35;
    const cy = A.y - 26 - len * 0.12;
    for (let j = 0; j < 34; j++) {
      const u = j / 34;
      const q1 = bez(A.x, A.y, cx, cy, tipX, tipY, u);
      const q2 = bez(A.x, A.y, cx, cy, tipX, tipY, (j + 1) / 34);
      const cool = Math.min(1, smoothstep(0.45, 0.95, bt) + 0.35 + 0.4 * u);
      stroke(lerp(246, 150, cool), lerp(210, 168, cool), lerp(170, 192, cool),
             lerp(150, 25, u));
      strokeWeight(lerp(e * 0.55, 0.4, Math.pow(u, 0.8)));
      line(q1.x, q1.y, q2.x, q2.y);
    }
    noStroke();
    for (let k = 0; k < 14; k++) { // poussière au bout de la branche
      const ang = random() * TWO_PI;
      const d = Math.pow(random(), 0.6) * 24;
      fill(160, 175, 200, 12 + random() * 55);
      circle(tipX + cos(ang) * d, tipY + sin(ang) * d * 0.8 + random() * 14,
             0.7 + random() * 1.8);
    }
    noFill();
  }
}

function thread() { // le fil : aura, corps, lumière
  noFill();
  const N = 1500;
  const TMAX = 0.952;
  for (let i = 0; i < N; i++) { // aura
    const t = i / N * TMAX;
    const p1 = spline(t), p2 = spline(Math.min(TMAX, (i + 1) / N * TMAX));
    const cool = smoothstep(0.45, 0.95, t);
    stroke(lerp(205, 110, cool), lerp(158, 130, cool), lerp(92, 160, cool),
           (11 - 6 * smoothstep(0.5, 0.92, t)) * (0.7 + 0.6 * noise(t * 26 + 3.1)));
    strokeWeight(thick(t) * 2.6 + 9);
    line(p1.x, p1.y, p2.x, p2.y);
  }
  for (let i = 0; i < N; i++) { // corps
    const t = i / N * TMAX;
    const p1 = spline(t), p2 = spline(Math.min(TMAX, (i + 1) / N * TMAX));
    const jit = smoothstep(0.55, 0.93, t) * 7;
    const jx = (noise(t * 55 + 31.7) - 0.5) * 2 * jit;
    const jy = (noise(t * 55 + 77.3) - 0.5) * 2 * jit;
    const c = threadRGB(t);
    const dim = 0.82 + 0.18 * noise(t * 34 + 9.9);
    stroke(c[0] * dim, c[1] * dim, c[2] * dim,
           240 - 160 * smoothstep(0.60, 0.94, t));
    strokeWeight(thick(t));
    line(p1.x + jx, p1.y + jy, p2.x + jx, p2.y + jy);
  }
  for (let i = 0; i < N; i++) { // lumière : reflets discontinus
    const t = i / N * TMAX;
    if (t < 0.72 && noise(t * 41 + 201) > 0.42) {
      const bell = Math.exp(-Math.pow((t - 0.34) / 0.3, 2));
      const p1 = spline(t), p2 = spline(Math.min(TMAX, (i + 1) / N * TMAX));
      stroke(255, 246, 224, (60 + 80 * noise(t * 23 + 55)) * (0.4 + 0.6 * bell));
      strokeWeight(Math.max(0.8, thick(t) * 0.3));
      line(p1.x, p1.y, p2.x, p2.y);
    }
  }
}

function dissolution() { // le fil se délie : dispersion, refroidissement, chute
  noStroke();
  for (let i = 0; i < 1000; i++) {
    const t = 0.60 + Math.pow(random(), 0.85) * 0.44;
    const p = spline(Math.min(1, t));
    const prog = smoothstep(0.60, 1.04, t);
    const spread = lerp(4, 60, prog);
    const ang = random() * TWO_PI;
    const d = Math.pow(random(), 0.75) * spread;
    const x = p.x + cos(ang) * d;
    const y = p.y + sin(ang) * d * 0.72 + prog * 100 * random();
    const sz = (0.6 + random() * 2.3) * (1 - 0.45 * prog);
    const al = (12 + random() * 80) * (1 - 0.72 * prog);
    if (random() < 0.16 && prog < 0.6) {
      fill(205 + random() * 40, 158, 96, al * 0.85); // braises refroidies
    } else {
      const cool = Math.min(1, 0.35 + prog);
      fill(lerp(210, 150, cool), lerp(200, 168, cool), lerp(185, 195, cool), al);
    }
    circle(x, y, sz);
    if (random() < 0.05) {
      fill(120, 132, 152, al * 0.16);
      circle(x, y, sz * 2.6);
    }
  }
  for (let i = 0; i < 260; i++) { // retombées presque éteintes
    const p = spline(0.75 + random() * 0.25);
    fill(120, 132, 152, 4 + random() * 16);
    circle(p.x + (random() - 0.5) * 130,
           p.y + 20 + Math.pow(random(), 1.6) * 180,
           0.6 + random() * 1.6);
  }
}

function emergence() { // le point d'où le fil sort : même froideur qu'à la fin
  const E = spline(0);
  fog(E.x, E.y, 150, 118, 132, 158, 0.10);
  fog(E.x, E.y, 54, 168, 183, 210, 0.16);
  noStroke();
  fill(238, 244, 252, 235);
  circle(E.x, E.y, 5);
  fill(200, 214, 236, 55);
  circle(E.x, E.y, 11);
  for (let i = 0; i < 18; i++) {
    const ang = random() * TWO_PI;
    const d = 8 + Math.pow(random(), 0.5) * 30;
    fill(160, 174, 198, 8 + random() * 26);
    circle(E.x + cos(ang) * d, E.y + sin(ang) * d * 0.8, 0.6 + random() * 1.4);
  }
}

function endPoint() { // le lieu de la rendue : ponctuation froide, pas une âme
  const F = spline(1);
  fog(F.x, F.y, 150, 148, 162, 192, 0.10);
  fog(F.x, F.y, 52, 178, 192, 222, 0.15);
  noFill();
  stroke(205, 220, 245, 26);
  strokeWeight(1);
  circle(F.x, F.y, 22);
  noStroke();
  fill(218, 230, 248, 200);
  circle(F.x, F.y, 3.6);
  fill(185, 200, 228, 55);
  circle(F.x, F.y, 9);
  for (let i = 0; i < 26; i++) {
    const ang = random() * TWO_PI;
    const d = 6 + Math.pow(random(), 0.5) * 34;
    fill(150, 162, 185, 8 + random() * 30);
    circle(F.x + cos(ang) * d, F.y + sin(ang) * d * 0.8, 0.6 + random() * 1.5);
  }
}

function imprint() { // le fil achevé se dépose sur le champ des fins
  const F = spline(1);
  noFill();
  for (let i = 0; i < 110; i++) {
    const r = 26 + Math.pow(random(), 0.55) * 250;
    const ang = random() * TWO_PI;
    const x = F.x + cos(ang) * r * 1.5;
    const y = F.y + sin(ang) * r * 0.85;
    const l2 = 18 + random() * 95;
    const bend = (noise(x * 0.01, y * 0.05) - 0.5) * 18;
    if (random() < 0.14) stroke(128, 110, 84, 3 + random() * 4);
    else stroke(90, 102, 120, 3 + random() * 7);
    strokeWeight(0.8 + random() * 0.8);
    bezier(x, y, x + l2 * 0.3, y + bend * 0.3,
           x + l2 * 0.7, y + bend * 0.7, x + l2, y + bend);
  }
}

function grain() { // matière de la toile
  noStroke();
  for (let i = 0; i < 24000; i++) {
    const x = random() * W, y = random() * H;
    if (random() < 0.5) fill(196, 208, 226, 2 + random() * 2.5);
    else fill(0, 0, 0, 2.5 + random() * 3);
    circle(x, y, 0.5 + random() * 0.9);
  }
  for (let i = 0; i < 4000; i++) {
    fill(210, 220, 235, 1.2);
    circle(random() * W, random() * H, 1 + random() * 1.2);
  }
}

function vignette() {
  const g = drawingContext.createRadialGradient(W / 2, H * 0.46, 500,
                                                W / 2, H * 0.46, 1520);
  g.addColorStop(0, 'rgba(4,6,10,0)');
  g.addColorStop(1, 'rgba(4,6,10,0.58)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
  const g2 = drawingContext.createLinearGradient(0, 1620, 0, H);
  g2.addColorStop(0, 'rgba(6,8,12,0)');
  g2.addColorStop(1, 'rgba(6,8,12,0.38)');
  drawingContext.fillStyle = g2;
  drawingContext.fillRect(0, 1620, W, H - 1620);
}

// Le Dénouement
// La mort non comme un personnage, mais comme un processus :
// le tourbillon du vivant se délie, retombe en poussière, se dépose.

let W = 1600, H = 2000;
let CX = 800, CY = 680;
let SY = 0.76;   // aplatissement vertical du tourbillon
let RMAX = 580;  // rayon de la lisière

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  noLoop();
  paint();
}

function draw() {}

function paint() {
  backGradient();
  glows();
  stratumBase();
  whirl();
  release();
  haze();
  fragments();
  stratumSurface();
  embers();
  vignette();
  grain();
}

// ---------- utilitaires ----------

function g2() { return random() + random() + random() - 1.5; }

function lerpc(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function floorY(x) { return 1852 + 56 * noise(x * 0.0016, 40.2); }

function tangentAt(th) {
  let tx = -sin(th), ty = SY * cos(th);
  let m = Math.sqrt(tx * tx + ty * ty);
  return [tx / m, ty / m];
}

// ---------- fond ----------

function backGradient() {
  let g = drawingContext.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#141a26');
  g.addColorStop(0.42, '#0a0e17');
  g.addColorStop(0.8, '#06080d');
  g.addColorStop(1, '#04060a');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function radialGlow(x, y, r, cr, cg, cb, a) {
  let g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, 'rgba(' + cr + ',' + cg + ',' + cb + ',' + a + ')');
  g.addColorStop(1, 'rgba(' + cr + ',' + cg + ',' + cb + ',0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, r * 2, r * 2);
}

function glows() {
  radialGlow(CX, CY, 860, 222, 216, 202, 0.085);
  radialGlow(CX, CY, 330, 255, 226, 184, 0.16);
}

// ---------- le tourbillon (le vivant) ----------

function sampleR() {
  const r0 = 60, k = 235;
  const E = 1 - Math.exp(-(RMAX - r0) / k);
  return r0 - k * Math.log(1 - random() * E);
}

function whirl() {
  noFill();
  // cœur incandescent
  for (let i = 0; i < 1600; i++) {
    let r = 24 + 116 * Math.pow(random(), 1.4);
    let th = random(TWO_PI);
    let x = CX + r * cos(th), y = CY + SY * r * sin(th);
    let t = tangentAt(th);
    let L = 3.5 + random() * 8;
    let col = lerpc([255, 236, 200], [243, 233, 212], r / 140);
    strokeWeight(1.1 + random() * 1.3);
    stroke(col[0], col[1], col[2], 70 + 150 * (1 - r / 150) * random() + 20 * random());
    line(x, y, x + t[0] * L, y + t[1] * L);
  }
  // traits d'énergie
  for (let i = 0; i < 52; i++) {
    let r = 180 + random() * 300;
    let th = random(TWO_PI);
    let x = CX + r * cos(th), y = CY + SY * r * sin(th);
    let t = tangentAt(th);
    let L = 30 + random() * 34;
    let a = 40 + random() * 60;
    strokeWeight(1.5 + random() * 0.8);
    stroke(238, 233, 222, a);
    line(x, y, x + t[0] * L, y + t[1] * L);
    stroke(238, 233, 222, a * 0.35);
    line(x - t[0] * L * 0.5, y - t[1] * L * 0.5, x, y);
  }
  // champ tournoyant
  for (let i = 0; i < 9200; i++) fieldStroke();
}

function fieldStroke() {
  let r = sampleR();
  let th;
  if (random() < 0.68) {
    let arm = floor(random(3)) * TWO_PI / 3;
    th = arm + 4.4 * Math.log(r / 60) + g2() * 0.7;
  } else {
    th = random(TWO_PI);
  }
  th += (noise(cos(th) * 2.6 + 5, sin(th) * 2.6 + 5, r * 0.007) - 0.5) * 1.3;
  let cl = 0.30 + 0.85 * noise(cos(th) * 2.3 + 11, sin(th) * 2.3 + 11, r * 0.012);
  if (random() > 0.25 + 0.75 * cl) return;

  let x = CX + r * cos(th);
  let y = CY + SY * r * sin(th);
  let t = tangentAt(th);
  let tilt = constrain(map(r, 150, 520, -0.5, 0.6), -0.5, 0.6) + g2() * 0.09;
  let ca = cos(tilt), sa = sin(tilt);
  let tx = t[0] * ca - t[1] * sa, ty = t[0] * sa + t[1] * ca;

  let tt = Math.pow(r / RMAX, 1.35);
  let col = lerpc([255, 240, 214], [172, 178, 190], tt);
  let L = lerp(13, 7, tt) + random() * 10 * (1 - tt * 0.4);
  let a = (16 + 148 * Math.exp(-(r - 60) / 250)) * (0.45 + 0.75 * random()) * cl;
  strokeWeight(lerp(1.6, 0.7, tt) + random() * 0.4);
  stroke(col[0], col[1], col[2], a);
  if (r > 430 && random() < 0.4) {
    // la frange se défait : traits rompus
    line(x, y, x + tx * L * 0.55, y + ty * L * 0.55);
    let x2 = x + tx * L * 0.85, y2 = y + ty * L * 0.85;
    line(x2, y2, x2 + tx * L * 0.3, y2 + ty * L * 0.3);
  } else {
    line(x, y, x + tx * L, y + ty * L);
  }
}

// ---------- le lâcher : trajectoires qui quittent la forme ----------

function release() {
  for (let i = 0; i < 430; i++) {
    let rr = 400 + random() * 195;
    let th = random(TWO_PI);
    let x = CX + rr * cos(th);
    let y = CY + SY * rr * sin(th);
    let outx = cos(th), outy = sin(th);
    let tanv = tangentAt(th);
    let sp = 3.0 + random() * 5.4;
    let lift = random() * 2.8 * constrain(map(y, 260, 640, 0.1, 1), 0.1, 1);
    let vx = outx * sp * 0.75 + tanv[0] * 2.4;
    let vy = outy * sp * 0.55 + tanv[1] * 2.4 - lift;
    if (vy < 0) {
      let maxUp = lerp(0.8, 3.4, constrain(map(y, 150, 430, 0, 1), 0, 1));
      if (-vy > maxUp) vy = -maxUp;
    }
    let a0 = 50 + random() * 110;
    let sd = random() * 100;
    let acc = 0, lastX = x, lastY = y, steps = 0;
    while (steps < 1200) {
      steps++;
      vy += 0.058;
      vx *= 0.991; vy *= 0.991;
      if (vy > 2.3) vy = 2.3 + (vy - 2.3) * 0.03;
      if (vy < -2.6) vy = -2.6;
      vx += (noise(x * 0.004, y * 0.004, sd) - 0.5) * 0.42;
      x += vx; y += vy;
      if (x < -60 || x > W + 60 || y < 12) break;
      let fy = floorY(x);
      if (y >= fy) {
        noStroke();
        fill(168, 175, 184, 60); ellipse(x, fy - 1, 3.4, 3.4);
        fill(140, 147, 156, 30); ellipse(x, fy - 2, 6, 4.5);
        break;
      }
      let speed = Math.sqrt(vx * vx + vy * vy);
      acc += speed;
      let need = speed > 2.8 ? 2.0 : 4.2 + Math.min(7, steps * 0.0055);
      if (acc >= need) {
        acc = 0;
        let age = constrain(steps / 900, 0, 1);
        let cool = constrain(age * 1.25 + constrain((dist(x, y, CX, CY) - 500) / 700, 0, 0.6), 0, 1);
        let col = lerpc([238, 234, 222], [146, 152, 163], cool);
        let a = a0 * Math.pow(1 - age, 1.5) + 14;
        if (speed > 2.8) {
          noFill();
          stroke(col[0], col[1], col[2], a);
          strokeWeight(1.0 + random() * 0.5);
          line(lastX, lastY, x, y);
        } else {
          noStroke();
          fill(col[0], col[1], col[2], a);
          let s = lerp(2.2, 1.1, age);
          ellipse(x, y, s, s);
        }
        lastX = x; lastY = y;
      }
    }
  }
}

// ---------- la pluie de poussière ----------

function haze() {
  noStroke();
  for (let i = 0; i < 3400; i++) {
    let yy = 1130 + Math.pow(random(), 0.85) * 690;
    let d = (yy - 1130) / 690;
    let spread = 300 + 340 * d;
    let xx = random() < 0.78 ? CX + g2() * spread * 0.75 : random(W);
    let s = 0.8 + random() * 1.3;
    fill(148, 154, 164, 5 + random() * 14);
    ellipse(xx, yy, s, s);
    if (random() < 0.06) {
      fill(190, 196, 205, 10 + random() * 14);
      ellipse(xx, yy, 1.5, 1.5);
    }
  }
  // grumeaux : des liens qui tiennent encore un peu
  for (let i = 0; i < 40; i++) {
    let yy = 1200 + random() * 600;
    let xx = CX + g2() * 430;
    let n = 6 + floor(random() * 9);
    let sz = 5 + random() * 14;
    let base = 8 + random() * 14;
    for (let k = 0; k < n; k++) {
      fill(150, 156, 166, base + random() * 12);
      let s = 0.8 + random() * 1.4;
      ellipse(xx + g2() * sz, yy + g2() * sz * 0.7, s, s);
    }
  }
}

// fragments encore alignés : le geste se souvient
function fragments() {
  noFill();
  for (let i = 0; i < 14; i++) {
    let yy = 1180 + random() * 620;
    let xx = CX + g2() * 420;
    let ang = random(TWO_PI);
    let n = 14 + floor(random() * 10);
    let cool = constrain((yy - 1000) / 900, 0, 1);
    let col = lerpc([224, 221, 214], [140, 146, 156], cool);
    for (let k = 0; k < n; k++) {
      let ox = g2() * 26, oy = g2() * 16;
      let L = 3 + random() * 6;
      stroke(col[0], col[1], col[2], 14 + random() * 26);
      strokeWeight(0.7 + random() * 0.6);
      line(xx + ox, yy + oy, xx + ox + cos(ang) * L, yy + oy + sin(ang) * L);
    }
  }
}

// ---------- le banc de cendre (ce qui reste) ----------

function stratumBase() {
  noStroke();
  for (let i = 0; i < 190; i++) {
    let xx = random(-80, W + 80);
    let yy = floorY(xx) + 20 + random() * 46;
    fill(56, 62, 72, 6 + random() * 9);
    ellipse(xx, yy, 100 + random() * 150, 30 + random() * 52);
  }
  for (let i = 0; i < 120; i++) {
    let xx = random(-80, W + 80);
    let yy = floorY(xx) + 55 + random() * 40;
    fill(30, 34, 42, 8 + random() * 12);
    ellipse(xx, yy, 140 + random() * 180, 40 + random() * 60);
  }
  noFill();
  for (let i = 0; i < 4300; i++) {
    let xx = random(-30, W + 30);
    let u = random();
    let fy = floorY(xx);
    let yy = fy + Math.pow(u, 1.5) * 100;
    let len = 7 + random() * 26;
    let t3 = random();
    let col = t3 < 0.35 ? [80, 86, 96] : (t3 < 0.7 ? [98, 104, 114] : [116, 122, 132]);
    stroke(col[0], col[1], col[2], (10 + 20 * (1 - u)) * (0.5 + 0.6 * random()));
    strokeWeight(0.8 + random() * 1.2);
    let slope = (noise(xx * 0.008, yy * 0.01) - 0.5) * 5;
    line(xx, yy, xx + len, yy + slope);
  }
  noStroke();
  // brume au-dessus du banc
  for (let i = 0; i < 260; i++) {
    let xx = random(-10, W + 10);
    let yy = floorY(xx) - 6 - random() * 44;
    fill(140, 147, 158, 4 + random() * 8);
    ellipse(xx, yy, 2 + random() * 3, 2 + random() * 3);
  }
}

function stratumSurface() {
  noStroke();
  // lisière éclairée par ce qui fut au-dessus
  for (let i = 0; i < 1900; i++) {
    let xx = random(-10, W + 10);
    let yy = floorY(xx) - 2 + random() * 9;
    let s = 0.7 + random() * 1.1;
    fill(158, 165, 176, 12 + 48 * Math.pow(random(), 2.4));
    ellipse(xx, yy, s, s);
  }
  // dernières poussières suspendues
  for (let i = 0; i < 14; i++) {
    let xx = random(60, W - 60);
    let fy = floorY(xx);
