const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  paint();
}

function draw() {}

function paint() {
  baseField();   // le grand champ sombre et le champ chaud d'en bas
  presence();    // la présence immense, presque invisible
  darkClouds();  // respiration lente de la nuit
  plumeShaft();  // faible colonne de montée
  afterglow();   // mémoire chaude à la frontière
  embers();      // les braises qui montent et s'éteignent
  dust();        // poussière en suspens
