  grain();       // matière de peinture
  vignette();    // cadre d'ombre
  lastMote();    // la dernière braise
}

function lerpC(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function clampC(c) {
  return [constrain(c[0], 0, 255), constrain(c[1], 0, 255), constrain(c[2], 0, 255)];
}

function radial(x, y, r, stops) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, r);
  for (let i = 0; i < stops.length; i++) {
    const s = stops[i];
    g.addColorStop(s[0], 'rgba(' + s[1][0] + ',' + s[1][1] + ',' + s[1][2] + ',' + s[1][3] + ')');
  }
  ctx.fillStyle = g;
  ctx.fillRect(x - r, y - r, r * 2, r * 2);
}

function baseField() {
  const stops = [
    [0.00, [5, 6, 12]],
    [0.26, [9, 11, 20]],
    [0.50, [13, 16, 27]],
    [0.64, [21, 21, 29]],
    [0.73, [36, 26, 23]],
    [0.87, [54, 34, 26]],
    [1.00, [44, 26, 20]]
  ];
  noStroke();
  for (let y = 0; y < H; y++) {
    const t = y / (H - 1);
    let c = stops[stops.length - 1][1];
    for (let i = 0; i < stops.length - 1; i++) {
      if (t >= stops[i][0] && t <= stops[i + 1][0]) {
        const u = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
        c = lerpC(stops[i][1], stops[i + 1][1], u);
        break;
      }
    }
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 1);
  }
}

function presence() {
  const cx = 800, cy = 520, R = 460;
  const lifts = [1.0, 0.78, 0.56];
  const alphas = [0.30, 0.26, 0.20];
  for (let k = 0; k < 3; k++) {
    radial(cx, cy, R * lifts[k], [
      [0.0, [27, 31, 50, alphas[k]]],
      [0.62, [21, 25, 42, alphas[k] * 0.45]],
      [1.0, [14, 17, 30, 0]]
    ]);
  }
  for (let i = 0; i < 160; i++) {
    const a = random(TWO_PI);
    const rr = R + random(-80, 70);
    const x = cx + cos(a) * rr;
    const y = cy + sin(a) * rr * 0.97;
    const r = random(50, 120);
    if (random() < 0.55) {
      radial(x, y, r, [[0, [30, 35, 56, random(0.05, 0.1)]], [1, [30, 35, 56, 0]]]);
    } else {
      radial(x, y, r, [[0, [3, 4, 9, random(0.06, 0.12)]], [1, [3, 4, 9, 0]]]);
    }
  }
  radial(cx, cy + R * 0.6, 250, [[0, [120, 66, 40, 0.06]], [1, [120, 66, 40, 0]]]);
}

