      x = random(-60, W + 60);
      y = 1435 + random() * 565;
    }

    let fray = 0;
    if (y < 1610) fray = constrain(map(y, 1610, 1440, 0, 1), 0, 1);

    let wgt = random(2, 13);
    let len = map(wgt, 2, 13, 95, 28) * random(0.55, 1.35);
    wgt *= 1 - fray * 0.45;
    len *= 1 - fray * 0.62;

    let c = wlist[floor(random(wlist.length))].slice();
    const dC = dist(x, y, 840, 1990);
    let b = map(y, 1440, 2000, 0.55, 1.06) * map(dC, 0, 880, 1.06, 0.5);
    b *= random(0.88, 1.12);
    c = [c[0] * b, c[1] * b, c[2] * b];
    if (fray > 0) c = lerpC(c, [27, 31, 45], fray * 0.5);
    c = clampC(c);
    const alp = random(34, 82) * (1 - fray * 0.4);

    let ang = flowAngle(x, y);
    if (fray > 0.1 && random() < fray * 0.55) {
      ang = -HALF_PI + (random() - 0.5) * 0.9;
    }

    noFill();
    stroke(c[0], c[1], c[2], alp);
    strokeWeight(wgt);

    let px = x, py = y;
    const steps = max(2, floor(random(2, 5)));
    const seg = len / steps;
    for (let s = 0; s < steps; s++) {
      const a2 = flowAngle(px, py);
      const nx = px + cos(a2) * seg;
      const ny = py + sin(a2) * seg;
      line(px, py, nx, ny);
      px = nx;
