function setup() {
  randomSeed(1);
  noiseSeed(1);

  const W = 1600, H = 2000;
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();

  /* ————— LE FOND : LE SILENCE, PARTOUT LE MÊME ————— */
  background(238, 235, 227);

  /* ————— OUTILS ————— */
  const doux = (v, a, b) => {
    const t = constrain((v - a) / (b - a), 0, 1);
    return t * t * (3 - 2 * t);
  };
  const gauss = () =>
    (random() + random() + random() + random() + random() + random() - 3) * 0.7071;

  // voile doux à bords fondus
  const voile = (x, y, rx, ry, al, r, g, b) => {
    noStroke();
    for (let k = 0; k < 6; k++) {
      fill(r, g, b, al / 6);
      ellipse(x, y, rx * (1 - k / 9.6), ry * (1 - k / 9.6));
    }
  };

  const COEUR = { x: W * 0.42, y: H * 0.86 }; // foyer de la matière

  // Champ de courants : la matière monte, l'agitation s'apaise en altitude,
  // et tourbillonne autour du foyer.
  const courant = (x, y) => {
    const alt = constrain((H - y) / H, 0, 1);
    const amp = lerp(1.9, 0.28, alt);
    let a = -HALF_PI
      + (noise(x * 0.0013, y * 0.0013, 7.7) - 0.5) * amp * 2
      + (noise(x * 0.006, y * 0.006, 3.1) - 0.5) * amp * 0.7;
    const dx = x - COEUR.x, dy = y - COEUR.y;
    const w = Math.exp(-(dx * dx + dy * dy) / (2 * 430 * 430)) * 0.65;
    const tang = Math.atan2(dy, dx) + HALF_PI;
    return Math.atan2(Math.sin(a) * (1 - w) + Math.sin(tang) * w,
                      Math.cos(a) * (1 - w) + Math.cos(tang) * w);
  };

  const CHAIR = [ // palette du bas : terre, sang, braise
    [126, 34, 28], [172, 70, 38], [152, 100, 46], [96, 66, 44],
    [58, 42, 34], [128, 110, 76], [186, 120, 52],
  ];
  const CENDRE = [ // palette du haut : ce qui reste
    [160, 150, 138], [174, 168, 160], [168, 142, 134], [146, 146, 148],
  ];
  const teinte = (y, jit = 14) => {
    const t = doux(constrain((H - y) / H, 0, 1), 0.16, 0.72);
    const A = random(CHAIR), B = random(CENDRE);
    return [lerp(A[0], B[0], t) + random(-jit, jit),
            lerp(A[1], B[1], t) + random(-jit, jit),
            lerp(A[2], B[2], t) + random(-jit, jit)];
  };

  // grappes de matière dense
  const grappes = [];
  for (let i = 0; i < 14; i++) {
    grappes.push({ x: random(90, W - 90), y: random(H * 0.78, H * 0.98), r: random(180, 380) });
  }
  grappes.push({ x: COEUR.x, y: COEUR.y, r: 340 });

  const masse = (x, y, r, col, al) => { // tache organique sombre
    fill(col[0], col[1], col[2], al);
    beginShape();
    for (let i = 0; i <= 30; i++) {
      const a = (i / 30) * TWO_PI;
      const rr = r * (0.72 + 0.5 * noise(x * 0.01 + Math.cos(a) * 1.3, y * 0.01 + Math.sin(a) * 1.3, 4.2));
      vertex(x + Math.cos(a) * rr, y + Math.sin(a) * rr);
    }
    endShape(CLOSE);
  };

  const strate = (base, a1, a2, col, al, gr) => { // sédiment au bord bruité
    fill(col[0], col[1], col[2], al);
    beginShape();
    vertex(-20, H + 20);
    for (let i = 0; i <= 70; i++) {
      const x = -20 + (i / 70) * (W + 40);
      vertex(x, base - a1 * noise(i * 0.11, gr) - a2 * noise(i * 0.33, gr + 5));
    }
    vertex(W + 20, H + 20);
    endShape(CLOSE);
  };

  // respiration du vide : nappes presque imperceptibles dans le silence
  for (let i = 0; i < 4; i++) {
    voile(random(250, W - 250), random(150, 640),
          random(260, 460), random(150, 260), 10, 214, 208, 196);
  }

  /* ————— LE TEMPS SÉDIMENTÉ ————— */
  strate(H - 540, 120, 70, [54, 42, 34], 26, 11);
  strate(H - 350, 100, 60, [42, 31, 25], 64, 37);
  strate(H - 165, 90, 55, [29, 21, 17], 232, 71);

  /* ————— LES PROFONDEURS ————— */
  for (let i = 0; i < 13; i++) {
    const g = random(grappes);
    masse(g.x + gauss() * g.r * 0.45, g.y + gauss() * g.r * 0.3,
          random(110, 300), [33, 25, 21], random(38, 80));
  }
  for (let i = 0; i < 4; i++) {
    masse(COEUR.x + gauss() * 140, COEUR.y + gauss() * 90,
          random(130, 230), [20, 14, 12], random(55, 90));
  }

  /* ————— LA BRUME DE DISSOLUTION ————— */
  for (let i = 0; i < 14; i++) {
    voile(random(120, W - 120), lerp(1060, 1700, random()),
          random(380, 720), random(90, 200), random(5, 13), 122, 108, 97);
  }
  for (let i = 0; i < 6; i++) {
    voile(random(120, W - 120), lerp(760, 1060, random()),
          random(280, 520), random(70, 150), 4, 142, 134, 126);
  }

  /* ————— LA CHAIR : DOUZE MILLE TOUCHES ————— */
  strokeCap(ROUND);
  for (let i = 0; i < 12000; i++) {
    // hauteur : dense en bas, raréfaction exponentielle, rien au-dessus de 300
    const y = 300 + (H - 300) * Math.pow(random(), 0.3);
    const alt = (H - y) / H;
    const t = doux(alt, 0.16, 0.72);
    let x;
    if (random() < 0.75) {
      const g = random(grappes);
      x = g.x + gauss() * g.r * (0.55 + 1.3 * alt); // colonnes au-dessus des grappes
    } else {
      x = random(50, W - 50);
    }
    x = constrain(x, 20, W - 20);
    const a = courant(x, y);
    const len = lerp(10, 95, Math.pow(alt, 1.15)) * random(0.55, 1.3);
    const wgt = lerp(7.5, 1.2, t) * random(0.5, 1.3);
    let al = lerp(54, 15, t) * random(0.55, 1.2);
    if (y < 700) al *= map(y, 300, 700, 0.22, 1); // les fantômes sont pâles
    const c = teinte(y);
    if (y > H * 0.72 && random() < 0.025) { // rare braise dans la chair
      c[0] = 205 + random(30); c[1] = 118 + random(30); c[2] = 45 + random(20);
    }
    stroke(c[0], c[1], c[2], al);
    strokeWeight(wgt);
    line(x - Math.cos(a) * len * 0.5, y - Math.sin(a) * len * 0.5,
         x + Math.cos(a) * len * 0.5, y + Math.sin(a) * len * 0.5);
  }

  /* ————— LES BRAISES ————— */
  const foyers = [];
  for (let i = 0; i < 3; i++) foyers.push({ x: COEUR.x + random(-70, 70), y: COEUR.y + random(-50, 50) });
  for (let i = 0; i < 6; i++) {
    const g = random(grappes);
    foyers.push({ x: g.x + random(-60, 60), y: g.y + random(-40, 40) });
  }
  for (let i = 0; i < 360; i++) {
    const f = random(foyers);
    const x = f.x + gauss() * 95, y = f.y + gauss() * 60;
    if (y > H - 25 || y < H * 0.62) continue;
    const s = random(1.5, 4.5);
    noStroke();
    if (random() < 0.12) fill(228, 142, 58, random(45, 85));
    else fill(198, 108, 44, random(16, 46));
    ellipse(x, y, s, s);
  }

  /* ————— L'EXHALAISON : FILAMENTS QUI MONTENT ET RENONCENT ————— */
  const nouvelle = (g, fine) => ({
    x: g.x + gauss() * g.r * 0.35,
    y: g.y - random(0, g.r * (fine ? 0.9 : 0.45)),
    w: fine ? random(0.8, 2) : random(2.2, 5.5),
    al: fine ? random(10, 22) : random(30, 62),
    yMin: fine ? random(380, 720) : 300 + 850 * Math.pow(random(), 0.5), // altitude du renoncement
    seed: random(1000),
  });
  let tetes = [];
  for (let i = 0; i < 150; i++) tetes.push(nouvelle(random(grappes), false));
  for (let i = 0; i < 55; i++) tetes.push(nouvelle(random(grappes), true));

  let total = tetes.length;
  let tours = 0;
  while (tetes.length > 0 && tours < 420) {
    tours++;
    const suite = [];
    for (const f of tetes) {
      const tc = doux(constrain((H - f.y) / H, 0, 1), 0.15, 0.75);
      const cr = lerp(98, 173, tc) + random(-8, 8);
      const cg = lerp(66, 164, tc) + random(-8, 8);
      const cb = lerp(52, 155, tc) + random(-8, 8);
      const a = courant(f.x, f.y) + (noise(f.x * 0.004, f.y * 0.004, f.seed) - 0.5) * 0.9;
      const nx = f.x + Math.cos(a) * 7, ny = f.y + Math.sin(a) * 7;
      stroke(cr, cg, cb, f.al);
      strokeWeight(Math.max(f.w, 0.3));
      line(f.x, f.y, nx, ny);
      f.x = nx; f.y = ny;
      f.w *= 0.982; f.al *= 0.978; // affinement, fondu
      if (f.y < f.yMin || f.w < 0.34 || f.al < 3.5 || f.y < 235 || f.x < -40 || f.x > W + 40) {
        noStroke(); // dernier souffle
        fill(cr, cg, cb, f.al * 0.9);
        const d = Math.max(f.w * 1.7, 1.1);
        ellipse(f.x, f.y, d, d);
        continue; // le filament renonce
      }
      if (total < 430 && f.w > 1.5 && random() < 0.007) { // rare division
        suite.push({ x: f.x, y: f.y, w: f.w * 0.6, al: f.al * 0.8, yMin: f.yMin, seed: random(1000) });
        total++;
        f.w *= 0.65; f.al *= 0.85;
      }
      suite.push(f);
    }
    tetes = suite;
  }

  /* ————— LES DERNIERS GRAINS ————— */
  noStroke();
  for (let i = 0; i < 130; i++) {
    const y = 320 + 430 * Math.pow(random(), 1.6);
    let x;
    if (random() < 0.6) { const g = random(grappes); x = g.x + gauss() * 260; }
    else x = random(70, W - 70);
    fill(166, 156, 146, random(5, 15));
    const s = random(1, 3);
    ellipse(x, y, s, s);
  }
  for (let i = 0; i < 8; i++) { // les tout derniers atomes
    fill(170, 162, 152, random(3, 6));
    ellipse(random(100, W - 100), random(235, 330), random(1, 1.8), random(1, 1.8));
  }

  /* ————— GRAIN DE TOILE ————— */
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = (random() - 0.5) * 7;
    pixels[i]     = constrain(pixels[i] + g, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + g, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + g, 0, 255);
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);

  const W = 1600, H = 2000;
  const CX = 800;        // axe du tableau
  const CY = 620;        // le cœur : la chaleur rassemblée
  const FLOOR = 1832;    // la ligne commune
  const STOP = FLOOR - 26;

  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  colorMode(RGB, 255, 255, 255, 255);
  const ctx = drawingContext;

  // gaussienne déterministe (dépend de randomSeed)
  const gauss = () =>
    Math.sqrt(-2 * Math.log(1 - random())) * Math.cos(TWO_PI * random());

  const radial = (x, y, r, stops) => {
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    for (const s of stops) g.addColorStop(s[0], s[1]);
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  };

  const softBand = (x, y, w, h, col) => {
    ctx.save();
    ctx.translate(x, y);
    ctx.scale(1, h / w);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, w / 2);
    g.addColorStop(0, col);
    g.addColorStop(1, 'rgba(0,0,0,0)');
    ctx.fillStyle = g;
    ctx.fillRect(-w / 2, -w / 2, w, w);
    ctx.restore();
  };

  // ---------- fond : obscurité qui s'épaissit vers le bas ----------
  const bg = ctx.createLinearGradient(0, 0, 0, H);
  bg.addColorStop(0.0, '#06070b');
  bg.addColorStop(0.32, '#0a0c14');
  bg.addColorStop(0.6, '#080a10');
  bg.addColorStop(1.0, '#020308');
  ctx.fillStyle = bg;
  ctx.fillRect(0, 0, W, H);

  blendMode(ADD);

  // profondeur froide derrière tout
  radial(CX, 950, 1100, [
    [0.0, 'rgba(34,42,68,0.30)'],
    [0.55, 'rgba(22,28,46,0.13)'],
    [1.0, 'rgba(0,0,0,0)']
  ]);

  // strates : sédimentation de ce qui fut dissous avant
  const strata = [960, 1105, 1265, 1420, 1575, 1705];
  for (let k = 0; k < strata.length; k++) {
    softBand(CX, strata[k], 1500, 110, 'rgba(96,106,132,' + (0.05 - k * 0.006) + ')');
  }

  // ---------- étoiles lointaines, indifférentes ----------
  noStroke();
  for (let i = 0; i < 300; i++) {
    const x = random(W);
    const y = random(H * 0.88);
    const d = dist(x, y, CX, CY);
    let a = random(7, 36);
    if (d < 420) a *= map(d, 0, 420, 0.12, 1);
    const s = random(0.7, 1.9);
    fill(188, 198, 218, a);
    ellipse(x, y, s, s);
    if (random() < 0.15) {
      fill(160, 175, 205, a * 0.22);
      ellipse(x, y, s * 3.4, s * 3.4);
    }
  }

  // brume posée au-dessus de la ligne
  softBand(CX, FLOOR - 60, 1560, 320, 'rgba(110,122,148,0.10)');
  softBand(CX, FLOOR - 18, 1150, 150, 'rgba(130,140,166,0.10)');

  // ---------- le cœur : de la lumière rassemblée ----------
  radial(CX, CY, 380, [
    [0.0, 'rgba(255,196,130,0.15)'],
    [0.4, 'rgba(212,126,96,0.09)'],
    [0.75, 'rgba(112,68,92,0.04)'],
    [1.0, 'rgba(0,0,0,0)']
  ]);
  radial(CX, CY, 150, [
    [0.0, 'rgba(255,218,158,0.52)'],
    [0.55, 'rgba(255,166,94,0.20)'],
    [1.0, 'rgba(0,0,0,0)']
  ]);
  radial(CX, CY, 58, [
    [0.0, 'rgba(255,250,236,0.95)'],
    [0.5, 'rgba(255,228,175,0.5)'],
    [1.0, 'rgba(0,0,0,0)']
  ]);

  // éclats rassemblés
  for (let i = 0; i < 340; i++) {
    const x = CX + gauss() * 48;
    const y = CY + gauss() * 42;
    const dd = dist(x, y, CX, CY);
    const a = random(60, 220) * (1 - min(dd / 170, 1)) + 25;
    fill(255, 240, 214, a);
    ellipse(x, y, random(0.7, 2.4), random(0.7, 2.4));
  }
  for (let i = 0; i < 16; i++) {
    const x = CX + gauss() * 55;
    const y = CY + gauss() * 46;
    fill(255, 232, 200, 95);
    ellipse(x, y, random(4, 6), random(4, 6));
    fill(255, 196, 120, 40);
    ellipse(x, y, random(9, 13), random(9, 13));
  }

  // ---------- la frontière : tenue en haut, déchirée en bas ----------
  const R = 176;
  noFill();
  const disp = (ang, uu) => {
    const t = pow(uu, 2.1);
    const n1 = noise(cos(ang) * 1.9 + 11, sin(ang) * 1.9 + 37);
    const n2 = noise(cos(ang) * 3.1 + 71, sin(ang) * 3.1 + 5, uu * 2.4 + 1);
    const rG = R * (1 + t * (0.25 + 0.9 * n1));
    return {
      x: CX + cos(ang) * rG + (n1 - 0.5) * 70 * uu,
      y: CY + sin(ang) * rG + t * (25 + 250 * n2)
    };
  };
  for (let i = 0; i < 560; i++) {
    const a = (i / 560) * TWO_PI;
    const u = (1 + sin(a)) / 2; // 0 en haut, 1 en bas
    const keep = u < 0.2 ? 1 : max(0.05, 1 - (u - 0.2) * 1.15);
    if (random() > keep) continue;
    const p1 = disp(a, u);
    const p2 = disp(a + 0.05 * (1 - 0.5 * u), u);
    const al = 115 * pow(1 - u, 0.75) * (0.55 + 0.45 * random());
    stroke(255 - 60 * u, 210 - 42 * u, 180 + 10 * u, al);
    strokeWeight(1.7 * (1 - 0.5 * u));
    line(p1.x, p1.y, p2.x, p2.y);
  }

  // ---------- le dernier souffle : brève ascension qui se dissipe ----------
  strokeCap(ROUND);
  for (let i = 0; i < 120; i++) {
    let x = CX + gauss() * 55;
    let y = CY - random(4, 50);
    let vx = gauss() * 0.22;
    const rise = random(0.9, 2.1);
    const life = random(30, 130);
    for (let s = 0; s < life; s++) {
      const f = s / life;
      const a = 30 * (1 - f) * (0.5 + 0.5 * random());
      stroke(252 - 55 * f, 236 - 30 * f, 216, a);
      strokeWeight(1.5 * (1 - f) + 0.4);
      const ny = y - rise * random(0.75, 1.25);
      const nx = x + vx;
      line(x, y, nx, ny);
      x = nx;
      y = ny;
      vx += (noise(x * 0.007, y * 0.007) - 0.5) * 0.22;
      vx *= 0.965;
    }
  }

  // ---------- la chute : se refroidir, s'espacer, se taire ----------
  const pal = [
    [0.0, 255, 228, 182],
    [0.3, 232, 202, 166],
    [0.6, 172, 168, 158],
    [0.85, 110, 116, 134],
    [1.0, 66, 74, 92]
  ];
  const palC = (t) => {
    t = constrain(t, 0, 1);
    for (let k = 0; k < pal.length - 1; k++) {
      if (t <= pal[k + 1][0]) {
        const f = (t - pal[k][0]) / (pal[k + 1][0] - pal[k][0]);
        return [
          lerp(pal[k][1], pal[k + 1][1], f),
          lerp(pal[k][2], pal[k + 1][2], f),
          lerp(pal[k][3], pal[k + 1][3], f)
        ];
      }
    }
    return [pal[4][1], pal[4][2], pal[4][3]];
  };

  const settle = (x, y, strong) => {
    noStroke();
    const r = strong ? 3.5 : random(2, 4);
    fill(150, 158, 178, strong ? 60 : 32);
    ellipse(x, y, r, r);
    fill(150, 158, 178, strong ? 22 : 12);
    ellipse(x, y, strong ? 12 : random(7, 11), strong ? 12 : random(7, 11));
  };

  for (let i = 0; i < 540; i++) {
    let x = CX + gauss() * 52;
    let y = CY + gauss() * 44;
    if (y > CY + 140) y = CY + 140;
    const bx = gauss() * 0.25;
    const spd = random(0.8, 1.25);
    const bMul = random(0.55, 1.15);
    while (y < STOP) {
      const depth = constrain((y - CY) / (FLOOR - CY), 0, 1);
      const flow = noise(x * 0.0016, y * 0.0012) - 0.5;
      const vx = (x - CX) * 0.0025 + flow * (0.6 + 1.5 * depth) + bx;
      const vy = lerp(2.6, 1.3, depth) * spd;
      const nx = x + vx;
      const ny = y + vy;
      const c = palC(depth);
      const a = (165 - 150 * depth) * (0.55 + 0.45 * random()) * bMul;
      if (a > 1 && random() < 0.92) {
        stroke(c[0], c[1], c[2], a);
        strokeWeight(lerp(2.5, 1.0, depth) * random(0.7, 1.3));
        line(x, y, nx, ny);
      }
      if (random() < 0.0022 && depth > 0.08) {
        // une braise se rappelle, puis se rend
        noStroke();
        fill(min(c[0] + 45, 255), min(c[1] + 32, 255), min(c[2] + 20, 255), 95);
        ellipse(nx, ny, 4.5, 4.5);
        fill(255, 236, 208, 40);
        ellipse(nx, ny, 10, 10);
      }
      x = nx;
      y = ny;
      if (x < 30 || x > W - 30) break;
      if (random() < 0.003 + 0.0036 * depth) {
        settle(x, y, false);
        break;
      }
    }
    if (y >= STOP) {
      // un fil a rejoint le commun
      settle(x, min(y, FLOOR - 3), true);
      noStroke();
      fill(202, 212, 230, 90);
      ellipse(x, FLOOR, 2.2, 2.2);
    }
  }

  // ---------- la ligne commune ----------
  for (let s = 0; s < 160; s++) {
    const x0 = s * 10;
    const edge = pow(abs(x0 + 5 - CX) / (W / 2), 1.7);
    const a = 62 * (0.35 + 0.65 * noise(x0 * 0.004, 900)) * (1 - 0.9 * edge);
    if (a < 1.5) continue;
    stroke(182, 192, 210, a);
    strokeWeight(2.4);
    line(
      x0, FLOOR + (noise(x0 * 0.012, 500) - 0.5) * 4,
      x0 + 10, FLOOR + (noise((x0 + 10) * 0.012, 500) - 0.5) * 4
    );
  }

  // poussière posée
  noStroke();
  for (let i = 0; i < 230; i++) {
    const x = CX + gauss() * 430;
    const yy = FLOOR - pow(random(), 1.7) * 60 - 1;
    fill(162, 172, 194, random(12, 42));
    ellipse(x, yy, random(1, 2.6), random(1, 2.6));
  }

  // ---------- vignettage ----------
  blendMode(BLEND);
  const vg = ctx.createRadialGradient(CX, 900, 380, CX, 980, 1500);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.62, 'rgba(1,2,5,0.13)');
  vg.addColorStop(1, 'rgba(0,1,3,0.45)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);

  // ---------- grain ----------
  noStroke();
  for (let i = 0; i < 34000; i++) {
    fill(205, 214, 228, random(2, 8));
    rect(random(W), random(H), 1, 1);
  }
  for (let i = 0; i < 15000; i++) {
    fill(0, 0, 0, random(3, 10));
    rect(random(W), random(H), 1, 1);
  }
}

const W = 1600, H = 2000;
const FIG_X = 520;
const DISSOLVE_Y = 1010;
const LIGHT_X = 1060;
const HEAD = { x: 520, y: 775, r: 100 };

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ctx = drawingContext;

  let g = ctx.createLinearGradient(0, 0, 0, H);
  g.addColorStop(0, '#0a0908');
  g.addColorStop(0.55, '#110f0b');
  g.addColorStop(1, '#171310');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  paintBrushField();
  paintStrata();
  paintLight();
  paintFigureHalo();
  paintGround();
  paintShadow();
  paintFigureSolid();
  paintDissolution();
  paintThreads();
  paintAsh();
  paintMotes();
  paintEmbers();
  paintCracks();
  paintGrain();
  paintVignette();
}

function torsoHW(y) {
  if (y < 905) return 42;
  if (y < 970) return lerp(42, 196, (y - 905) / 65);
  if (y < 1180) return lerp(196, 150, (y - 970) / 210);
  if (y < 1330) return lerp(150, 106, (y - 1180) / 150);
  if (y < 1470) return lerp(106, 154, (y - 1330) / 140);
  return 154;
}

function paintBrushField() {
  noStroke();
  for (let i = 0; i < 260; i++) {
    push();
    translate(random(W), random(H));
    rotate(random(-0.5, 0.5));
    if (random() < 0.6) fill(6, 5, 4, 7);
    else fill(36, 29, 22, 6);
    ellipse(0, 0, random(120, 420), random(26, 90));
    pop();
  }
}

function paintStrata() {
  noFill();
  for (let k = 0; k < 7; k++) {
    let y0 = 260 + k * 240 + random(-40, 40);
    if (k % 2 === 0) stroke(0, 0, 0, 12);
    else stroke(54, 46, 35, 14);
    strokeWeight(random(1.5, 3.5));
    beginShape();
    for (let x = -20; x <= W + 20; x += 36) {
      vertex(x, y0 + noise(x * 0.004, k * 7.3) * 70 - 35);
    }
    endShape();
  }
  noStroke();
}

function paintLight() {
  noStroke();
  for (let i = 70; i >= 0; i--) {
    let t = i / 70;
    fill(232, 222, 196, 3 + 11 * (1 - t));
    ellipse(LIGHT_X, 1000, (60 + t * 430) * 2, (790 + t * 330) * 2);
  }
  for (let i = 40; i >= 0; i--) {
    let t = i / 40;
    fill(240, 233, 210, 4 + 16 * (1 - t));
    ellipse(LIGHT_X, 1000, (30 + t * 135) * 2, (710 + t * 510) * 2);
  }
  for (let i = 18; i >= 0; i--) {
    let t = i / 18;
    fill(248, 243, 226, 8 + 30 * (1 - t));
    ellipse(LIGHT_X, 1000, (8 + t * 42) * 2, (560 + t * 770) * 2);
  }
  for (let i = 0; i < 260; i++) {
    let y = random(140, 1880);
    let spread = 40 + (1 - abs(y - 1000) / 950) * 230;
    let x = LIGHT_X + (random() * 2 - 1) * spread;
    let len = random(30, 210);
    stroke(238, 229, 204, random(5, 16));
    strokeWeight(random(1, 3.5));
    line(x - len / 2, y + random(-3, 3), x + len / 2, y + random(-3, 3));
  }
  noStroke();
}

function paintFigureHalo() {
  noStroke();
  for (let i = 0; i < 8; i++) {
    fill(28, 21, 15, 9);
    ellipse(FIG_X, 1260, 780 - i * 62, 1520 - i * 125);
  }
}

function paintGround() {
  noStroke();
  for (let i = 0; i < 520; i++) {
    let y = random(1690, H);
    let c = lerpColor(color(9, 7, 5), color(40, 31, 23), random());
    fill(red(c), green(c), blue(c), random(25, 70));
    ellipse(random(-100, W + 100), y, random(40, 260), random(3, 9));
  }
  for (let i = 0; i < 5; i++) {
    fill(222, 211, 180, 5 + i * 2);
    ellipse(LIGHT_X, 1830 + i * 8, 640 - i * 95, 130 - i * 15);
  }
  for (let i = 0; i < 90; i++) {
    stroke(230, 220, 190, random(4, 12));
    strokeWeight(random(1, 3));
    let y = random(1720, 1960);
    let x = LIGHT_X + (random() * 2 - 1) * random(60, 380);
    let len = random(30, 180);
    line(x - len / 2, y, x + len / 2, y);
  }
  noStroke();
}

function paintShadow() {
  noStroke();
  fill(0, 0, 0, 60);
  ellipse(FIG_X, 1772, 820, 95);
  fill(0, 0, 0, 110);
  ellipse(FIG_X, 1772, 560, 60);
}

function paintFigureSolid() {
  noStroke();
  for (let y = DISSOLVE_Y; y <= 1470; y += 4) {
    let hw = torsoHW(y);
    let jx = (noise(y * 0.05) - 0.5) * 8;
    let c = lerpColor(color(16, 12, 9), color(31, 25, 19), noise(y * 0.02));
    fill(red(c), green(c), blue(c), 235);
    ellipse(FIG_X + jx, y, hw * 2 + 6, 9);
  }
  for (let y = 1460; y <= 1768; y += 4) {
    let t = (y - 1460) / 308;
    let lw = lerp(74, 30, t);
    let c = lerpColor(color(15, 11, 8), color(27, 21, 15), noise(y * 0.03 + 5));
    fill(red(c), green(c), blue(c), 235);
    ellipse(FIG_X - 62 + (noise(y * 0.04) - 0.5) * 6, y, lw * 2, 9);
    ellipse(FIG_X + 62 + (noise(y * 0.04 + 9) - 0.5) * 6, y, lw * 2, 9);
  }
  noFill();
  stroke(222, 208, 170, 16);
  strokeWeight(14);
  beginShape();
  for (let y = DISSOLVE_Y; y <= 1460; y += 8) vertex(FIG_X + torsoHW(y) + 4, y);
  endShape();
  stroke(235, 224, 192, 65);
  strokeWeight(3.5);
  beginShape();
  for (let y = DISSOLVE_Y; y <= 1460; y += 8) vertex(FIG_X + torsoHW(y) + 3, y);
  endShape();
  stroke(235, 224, 192, 45);
  strokeWeight(3);
  beginShape();
  for (let y = 1460; y <= 1768; y += 10) vertex(FIG_X + 65 + lerp(74, 30, (y - 1460) / 308), y);
  endShape();
  noStroke();
}

function spawnMote(x, y, s) {
  let d = dist(x, y, LIGHT_X, 1000);
  let lp = 1 - constrain(d / 750, 0, 1);
  let t = constrain(s * 0.75 + lp * 0.45, 0, 1);
  let c;
  if (random() < 0.04 && t > 0.45) c = color(219, 162, 92);
  else c = lerpColor(color(38, 30, 22), color(239, 230, 207), t);
  let size = lerp(5, 1.1, s) * random(0.5, 1.5);
  fill(red(c), green(c), blue(c), map(t, 0, 1, 30, 235) * random(0.55, 1));
  ellipse(x, y, size, size * random(0.7, 1.3));
}

function paintDissolution() {
  noStroke();
  for (let i = 0; i < 70; i++) {
    fill(42, 33, 24, 6);
    ellipse(FIG_X + random(-160, 320), random(560, 1030), random(40, 130), random(30, 90));
  }
  for (let y = 880; y < DISSOLVE_Y; y += 3) {
    let s = map(y, DISSOLVE_Y, 880, 0, 1);
    let hw = torsoHW(y);
    let count = floor(hw * (0.5 + s * 2.4) / 4);
    for (let i = 0; i < count; i++) {
      let px = FIG_X + (random() * 2 - 1) * hw * (1 + s * 2.4) + s * s * random(140, 460);
      let py = y - s * random(0, 190) + random(-6, 6);
      spawnMote(px, py, s * random(0.7, 1));
    }
  }
  for (let i = 0; i < 950; i++) {
    let ang = random(TWO_PI);
    let rad = sqrt(random()) * 180;
    let px = HEAD.x + cos(ang) * rad + rad * random(0.3, 1.1);
    let py = HEAD.y + sin(ang) * rad * 0.92 - rad * random(0, 0.5);
    spawnMote(px, py, 0.35 + (rad / 180) * 0.8);
  }
}

function paintThreads() {
