function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

const W = 1600, H = 2000;
const CX = 800;
const HEAD_Y = 680;
const HEART_Y = 1000;
const FLOOR_Y = 1565;

function bodyField(x, y) {
  let f = -1;
  let a = (x - CX) / 118, b = (y - HEAD_Y) / 135;
  f = max(f, 1 - (a * a + b * b));
  a = (x - CX) / 62; b = (y - 850) / 72;
  f = max(f, 1 - (a * a + b * b));
  a = (x - CX) / 170; b = (y - 905) / 100;
  f = max(f, 1 - (a * a + b * b));
  a = (x - CX) / 205; b = (y - 1160) / 385;
  f = max(f, 1 - (a * a + b * b));
  return f;
}

function paint() {
  const ctx = drawingContext;

  // fond : dégradé vertical profond
  const cTop = color(5, 7, 16), cMid = color(10, 13, 30), cBot = color(5, 7, 17);
  for (let y = 0; y < H; y++) {
    const t = y / H;
    stroke(t < 0.55 ? lerpColor(cTop, cMid, t / 0.55) : lerpColor(cMid, cBot, (t - 0.55) / 0.45));
    line(0, y, W, y);
  }

  // strates très faibles
  noFill();
  for (let i = 0; i < 42; i++) {
    const y0 = random(H);
    stroke(40, 50, 88, random(4, 11));
    strokeWeight(1);
    beginShape();
    for (let x = 0; x <= W; x += 80) vertex(x, y0 + (noise(x * 0.0022, i * 0.7) - 0.5) * 46);
    endShape();
  }

  // poussière d'arrière-plan
  strokeWeight(1);
  for (let i = 0; i < 2600; i++) {
    const x = random(W), y = random(H);
    if (dist(x, y, CX, HEART_Y) < 520 && random() < 0.5)
      stroke(255, 212, 152, random(4, 14));
    else
      stroke(170, 185, 225, random(3, 12));
    point(x, y);
  }

  // silhouette sombre et floue : l'absence
  noStroke();
  for (let i = 14; i >= 0; i--) {
    fill(2, 3, 9, 16);
    ellipse(CX, HEAD_Y, 300 + i * 16, 340 + i * 17);
    ellipse(CX, 1160, 500 + i * 20, 860 + i * 20);
  }

  // ligne du sol
  stroke(120, 132, 182, 16);
  strokeWeight(1);
  line(0, FLOOR_Y, W, FLOOR_Y);

  ctx.save();
  ctx.globalCompositeOperation = 'lighter';

  // aura chaude au cœur
  let g = ctx.createRadialGradient(CX, HEART_Y, 10, CX, HEART_Y, 560);
  g.addColorStop(0, 'rgba(255,186,105,0.30)');
  g.addColorStop(0.35, 'rgba(216,152,162,0.12)');
  g.addColorStop(0.7, 'rgba(112,112,192,0.05)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // mare de lumière sur le sol
  ctx.save();
  ctx.translate(CX, FLOOR_Y + 10);
  ctx.scale(1, 0.16);
  let g2 = ctx.createRadialGradient(0, 0, 10, 0, 0, 720);
  g2.addColorStop(0, 'rgba(255,196,120,0.15)');
  g2.addColorStop(0.6, 'rgba(150,140,220,0.06)');
  g2.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g2;
  ctx.fillRect(-740, -740, 1480, 1480);
  ctx.restore();

  // anneaux autour de la tête
  noFill();
  stroke(255, 214, 150, 20); strokeWeight(2);
  ellipse(CX, HEAD_Y, 252, 288);
  stroke(225, 230, 255, 24); strokeWeight(1.6);
  ellipse(CX, HEAD_Y, 374, 426);
  stroke(200, 206, 246, 11); strokeWeight(1.2);
  ellipse(CX, HEAD_Y, 504, 570);

  // palette de la lumière
  const warmC = color(255, 198, 122), roseC = color(226, 150, 178);
  const violC = color(150, 138, 235), blueC = color(96, 116, 205);
  function shade(t) {
    if (t < 0.3) return lerpColor(warmC, roseC, t / 0.3);
    if (t < 0.6) return lerpColor(roseC, violC, (t - 0.3) / 0.3);
    return lerpColor(violC, blueC, (t - 0.6) / 0.4);
  }

  const P = [];

  // le corps de lumière
  let attempts = 0;
  while (P.length < 50000 && attempts < 600000) {
    attempts++;
    const x = random(W), y = random(500, 1635);
    const f = bodyField(x, y) + (noise(x * 0.006, y * 0.006) - 0.5) * 0.95;
    const p = constrain(f, 0, 1);
    if (random() < p * p * 1.15) {
      const t = constrain(dist(x, y, CX, HEART_Y) / 720, 0, 1);
      const c = shade(t);
      const bright = 0.45 + 0.55 * constrain(f * 1.6, 0, 1);
      P.push({
        x, y,
        r: red(c) * bright, g: green(c) * bright, b: blue(c) * bright,
        a: (50 + random(130)) * bright,
        s: f > 0.45 ? random(2.2, 4.2) : random(1.2, 2.6),
        refl: y > 950
      });
    }
  }

  // particules échappées qui dérivent vers le haut et le noir
  for (let i = 0; i < 3800; i++) {
    let x, y, tries = 0;
    do { x = CX + random(-1, 1) * 270; y = random(540, 1580); tries++; }
    while (bodyField(x, y) < -0.15 && tries < 20);
    if (bodyField(x, y) < -0.15) continue;
    const steps = int(random(6, 30)), sp = random(2.5, 6.5);
    const warmStart = dist(x, y, CX, HEART_Y) < 280;
    for (let s = 0; s < steps; s++) {
      const a = noise(x * 0.0028, y * 0.0028) * TWO_PI * 3;
      x += cos(a) * sp;
      y += (sin(a) - 0.42) * sp;
      if (y < 30 || y > H - 8 || x < 8 || x > W - 8) break;
      const k = 1 - s / steps;
      const c = warmStart && s < 4 ? warmC : shade(constrain(dist(x, y, CX, HEART_Y) / 760, 0, 1));
      P.push({ x, y, r: red(c), g: green(c), b: blue(c), a: 8 + 60 * k * k, s: random(0.8, 2.0), refl: false });
    }
  }

  // filet de lumière qui s'élève au-dessus de la tête
  for (let i = 0; i < 2400; i++) {
    let x = CX + random(-1, 1) * 105 * sqrt(random());
    let y = HEAD_Y + random(-1, 1) * 115 * sqrt(random());
    const steps = int(random(8, 48)), sp = random(2, 5);
    for (let s = 0; s < steps; s++) {
      const a = -HALF_PI + (noise(x * 0.004, y * 0.004) - 0.5) * 1.7;
      x += cos(a) * sp + (noise(x * 0.01, y * 0.01) - 0.5) * 1.5;
      y += sin(a) * sp;
      if (y < 22) break;
      const k = 1 - s / steps;
      P.push({
        x, y, r: 198 + 44 * k, g: 206 + 32 * k, b: 250,
        a: (6 + 42 * k * k) * (0.4 + 0.6 * noise(x * 0.01, y * 0.01)),
        s: random(0.7, 1.8), refl: false
      });
    }
  }

  // reflet sur le sol
  const all = P.slice();
  for (let i = 0; i < P.length; i++) {
    const p = P[i];
    if (!p.refl || random() < 0.55) continue;
    const ry = FLOOR_Y + (FLOOR_Y - p.y) * 0.42;
    all.push({ x: p.x + random(-2.5, 2.5), y: ry, r: p.r, g: p.g, b: p.b, a: p.a * 0.10, s: p.s * 1.7 });
    if (random() < 0.5)
      all.push({ x: p.x + random(-2, 2), y: (FLOOR_Y + ry) / 2 + random(-3, 3), r: p.r, g: p.g, b: p.b, a: p.a * 0.05, s: p.s * 1.4 });
  }

  // dessin additif par seaux de couleur
  const buckets = new Map();
  for (const p of all) {
    const key = [round(p.r / 24), round(p.g / 24), round(p.b / 24), round(p.a / 36), p.s > 2.8 ? 2 : p.s > 1.9 ? 1 : 0].join(',');
    let arr = buckets.get(key);
    if (!arr) { arr = []; buckets.set(key, arr); }
    arr.push(p);
  }
  for (const arr of buckets.values()) {
    const p0 = arr[0];
    stroke(constrain(p0.r, 0, 255), constrain(p0.g, 0, 255), constrain(p0.b, 0, 255), constrain(p0.a, 0, 255));
    strokeWeight(p0.s > 2.8 ? 3.4 : p0.s > 1.9 ? 2.3 : 1.4);
    beginShape(POINTS);
    for (const p of arr) vertex(p.x, p.y);
    endShape();
  }

  ctx.restore();

  // grain de toile
  strokeWeight(1);
  for (let i = 0; i < 15000; i++) {
    const v = random(255);
    stroke(v, v, constrain(v + random(-10, 10), 0, 255), random(2, 7));
    point(random(W), random(H));
  }

  // vignettage
  const vg = ctx.createRadialGradient(CX, 950, 260, CX, 950, 1260);
  vg.addColorStop(0, 'rgba(0,0,6,0)');
  vg.addColorStop(0.72, 'rgba(0,0,6,0.26)');
  vg.addColorStop(1, 'rgba(0,0,8,0.62)');
  ctx.fillStyle = vg;
  ctx.fillRect(0, 0, W, H);
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  const W = 1600, H = 2000;
  const cx = W / 2;
  const cy = H * 0.42;
  const R = 430;
  const ctx = drawingContext;

  // fond : dégradé vertical profond
  const topC = color(9, 11, 22);
  const botC = color(36, 24, 27);
  for (let y = 0; y < H; y++) {
    stroke(lerpColor(topC, botC, y / H));
    line(0, y, W, y);
  }

  // nébuleuse : grandes taches sombres organiques
  noStroke();
  for (let i = 0; i < 900; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.0011, y * 0.0011);
    const r = 60 + n * 260;
    const c = lerpColor(color(15, 17, 33), color(50, 34, 38), n);
    fill(red(c), green(c), blue(c), random(4, 12));
    ellipse(x, y, r * 2, r * 1.4);
  }

  // halo autour du disque
  noStroke();
  for (let r = R * 2.1; r > R; r -= 8) {
    const t = map(r, R, R * 2.1, 1, 0);
    fill(232, 224, 205, 9 * t * t);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // anneaux concentriques, à peine visibles
  noFill();
  for (let r = R + 60; r < R + 560; r += 34) {
    const a = map(r, R + 60, R + 560, 22, 2);
    stroke(168, 158, 198, a);
    strokeWeight(1.5);
    ellipse(cx, cy, r * 2, r * 2);
  }

  // disque principal, dégradé vertical, rogné par un masque circulaire
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, R, 0, TWO_PI);
  ctx.clip();
  for (let y = cy - R; y <= cy + R; y++) {
    const t = (y - (cy - R)) / (2 * R);
    stroke(lerpColor(color(252, 248, 235), color(214, 204, 190), t));
    line(0, y, W, y);
  }
  // ombre interne sur la moitié inférieure
  noStroke();
  for (let i = 0; i < 320; i++) {
    const a = random(PI * 0.12, PI * 0.88);
    const rr = R * random(0.72, 1.0);
    fill(58, 48, 70, random(8, 26));
    ellipse(cx + cos(a) * rr, cy + sin(a) * rr, random(20, 95), random(14, 60));
  }
  ctx.restore();

  // liseré lumineux sur le bord supérieur
  noFill();
  stroke(255, 252, 240, 150);
  strokeWeight(3);
  arc(cx, cy, R * 2 - 5, R * 2 - 5, PI * 1.05, PI * 1.95);

  // érosion : le bord inférieur se désagrège
  noStroke();
  for (let i = 0; i < 2600; i++) {
    const a = random(PI);
    const edge = R * (0.84 + random(0.16));
    const t = pow(random(1), 2) * 95;
    const x = cx + cos(a) * (edge + t);
    const y = cy + sin(a) * (edge + t * 0.9);
    const s = random(2, 13) + t * 0.12;
    const dark = lerpColor(color(11, 12, 23), color(40, 28, 31), noise(x * 0.004, y * 0.004));
    fill(red(dark), green(dark), blue(dark), random(40, 130));
    ellipse(x, y, s, s * random(0.6, 1.2));
  }

  // gros fragments qui tombent
  for (let i = 0; i < 26; i++) {
    const a = random(PI);
    const d = random(20, 280);
    const x = cx + cos(a) * (R + d);
    const y = cy + sin(a) * (R + d * 0.7) + d * 0.35;
    const s = random(6, 20);
    fill(232, 224, 205, random(60, 150));
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    beginShape();
    const k = 5 + floor(random(3));
    for (let j = 0; j <= k; j++) {
      const ang = (j / k) * TWO_PI;
      const rr = s * random(0.5, 1.1);
      vertex(cos(ang) * rr, sin(ang) * rr * 0.7);
    }
    endShape(CLOSE);
    pop();
  }

  // poussière qui descend
  noStroke();
  for (let i = 0; i < 2200; i++) {
    const a = random(PI);
    const t = pow(random(1), 1.6);
    const dist = t * 640;
    const x = cx + cos(a) * (R * 0.92 + dist * random(0.85, 1.15)) + (noise(i * 0.013, 3.7) - 0.5) * 70;
    const y = cy + sin(a) * (R * 0.92 + dist * 0.8) + t * t * 280;
    const s = lerp(7, 0.6, t) * random(0.6, 1.4);
    const p = random(1);
    let c;
    if (p < 0.55) c = color(238, 230, 212);
    else if (p < 0.85) c = color(150, 130, 175);
    else c = color(214, 178, 122);
    fill(red(c), green(c), blue(c), lerp(210, 12, t) * random(0.6, 1));
    ellipse(x, y, s, s * random(0.7, 1.3));
  }

  // brume basse
  noStroke();
  for (let i = 0; i < 120; i++) {
    const x = random(W);
    const y = H * 0.80 + random(H * 0.20);
    fill(190, 175, 200, random(3, 9));
    ellipse(x, y, random(120, 430), random(24, 70));
  }

  // vignettage
  const g = ctx.createRadialGradient(cx, cy, R * 0.6, cx, cy, Math.max(W, H) * 0.78);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(4,4,10,0.55)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);

  // grain de pellicule
  loadPixels();
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = (y * W + x) * 4;
      const gv = (noise(x * 0.012, y * 0.012) - 0.5) * 26 + (random() - 0.5) * 10;
      pixels[i]     = constrain(pixels[i] + gv, 0, 255);
      pixels[i + 1] = constrain(pixels[i + 1] + gv, 0, 255);
      pixels[i + 2] = constrain(pixels[i + 2] + gv * 0.9, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  const ink    = color(9, 9, 17);
  const violet = color(30, 25, 46);
  const gold   = color(255, 203, 118);
  const ember  = color(255, 228, 172);
  const ivory  = color(255, 249, 232);

  const cx    = width * 0.5;
  const topY  = height * 0.10;
  const botY  = height * 0.90;
  const midY  = (topY + botY) / 2;
  const baseW = 170;

  rectMode(CENTER);
  background(ink);
  noStroke();

  // nuit profonde, matiere de toile
  for (let i = 0; i < 520; i++) {
    const x = random(width), y = random(height);
    const s = random(180, 760);
    const n = noise(x * 0.0012, y * 0.0012, i * 0.013);
    const c = lerpColor(ink, violet, n);
    fill(red(c), green(c), blue(c), random(7, 20));
    ellipse(x, y, s, s * random(0.45, 1));
  }
  // coups de pinceau horizontaux
  for (let i = 0; i < 240; i++) {
    const x = random(-100, width), y = random(height);
    const len = random(90, 520);
    if (random() < 0.62) stroke(4, 4, 10, random(8, 16));
    else stroke(64, 55, 92, random(6, 12));
    strokeWeight(random(6, 24));
    line(x, y, x + len, y + random(-10, 10));
  }
  noStroke();

  // lune voilee en haut a gauche
  const mx = width * 0.20, my = height * 0.115;
  for (let r = 190; r > 30; r -= 8) {
    fill(214, 222, 248, map(r, 30, 190, 26, 2));
    circle(mx, my, r * 2);
  }
  fill(228, 233, 250, 60);
  circle(mx, my, 74);

  // assombrir le bas, le sol
  for (let i = 0; i < 46; i++) {
    const t = i / 45;
    fill(3, 3, 8, 12 * t);
    rect(width / 2, lerp(botY - 80, height, t), width, (height - botY + 80) / 46 + 2);
  }

  // ombres des montants autour du seuil
  for (let i = 0; i < 130; i++) {
    const t = i / 129;
    const y = lerp(topY - 60, botY + 60, t);
    const h = (botY - topY + 120) / 130 + 3;
    const nL = noise(t * 4, 11.1), nR = noise(t * 4, 22.2);
    const wL = baseW * (1.6 + nL * 1.3);
    const wR = baseW * (1.6 + nR * 1.3);
    fill(4, 4, 9, 24);
    rect(cx - baseW * 0.85 - wL / 2, y, wL, h, wL * 0.4);
    rect(cx + baseW * 0.85 + wR / 2, y, wR, h, wR * 0.4);
  }

  // le seuil de lumiere lui-meme
  function colonne(wF, alpha, cA, cB, tranches, etendue) {
    for (let i = 0; i < tranches; i++) {
      const t = i / (tranches - 1);
      const y = lerp(topY, botY, t);
      const bord = noise(t * 3.2, 7.7);
      const sway = (noise(t * 2.1, 3.3) - 0.5) * 52;
      const pincement = sin(PI * t);
      const elargissement = 1 + etendue * t;
      const w = baseW * wF * (0.60 + bord * 0.55) * (0.34 + 0.66 * pincement) * elargissement;
      const c = lerpColor(cA, cB, noise(t * 6, 1.1));
      fill(red(c), green(c), blue(c), alpha);
      rect(cx + sway, y, w, (botY - topY) / tranches + 3, w * 0.5);
    }
  }

  blendMode(ADD);
  for (let l = 11; l >= 1; l--) {
    colonne(0.5 + l * 0.45, map(l, 1, 11, 24, 3), gold, ember, 80, 0.55);
  }
  colonne(0.36, 62, ivory, ember, 130, 0.25);
  colonne(0.13, 130, color(255, 255, 250), ivory, 110, 0.10);
  blendMode(BLEND);

  // lumiere qui fuit par le bas
  for (let i = 0; i < 34; i++) {
    const t = i / 33;
    const w = baseW * (0.5 + t * 1.9) * (0.7 + noise(i * 0.4, 2) * 0.6);
    fill(255, 226, 168, 30 * (1 - t));
    ellipse(cx + (noise(i * 0.3, 5) - 0.5) * 40, lerp(botY, botY + 130, t), w, 13);
  }

  // reflet au sol
  for (let i = 0; i < 170; i++) {
    const t = i / 169;
    const y = lerp(botY + 4, height, t);
    const fade = pow(1 - t, 1.7);
    const w = baseW * random(1.1, 4.6) * (0.35 + fade);
    fill(255, 214, 150, 24 * fade + random(0, 7));
    ellipse(cx + (noise(i * 0.08, 9) - 0.5) * 100, y, w, random(2, 7));
  }

  // aretes du seuil, filet de lumiere
  noFill();
  for (let i = 0; i < 320; i++) {
    const t = i / 319;
    const y = lerp(topY, botY, t);
    const e = noise(t * 5, 5.5);
    const wBord = baseW * 0.36 * (0.65 + e * 0.6) * (0.4 + 0.6 * sin(PI * t));
    stroke(255, 240, 210, random(36, 120));
    strokeWeight(random(1.5, 4));
    point(cx - wBord + (noise(t * 9, 1) - 0.5) * 8, y + (noise(t * 9, 2) - 0.5) * 7);
    point(cx + wBord + (noise(t * 9, 3) - 0.5) * 8, y + (noise(t * 9, 4) - 0.5) * 7);
  }
  noStroke();

  // spirale de poussieres attiree par la lumiere
  for (let i = 0; i < 680; i++) {
    const t = i / 680;
    const ang = t * TWO_PI * 7 + noise(i * 0.03, 3) * 1.3;
    const rad = 26 + pow(t, 1.15) * 780;
    const x = cx + cos(ang) * rad * 0.72;
    const y = midY + sin(ang) * rad * 0.98;
    if (x < -8 || x > width + 8 || y < -8 || y > height + 8) continue;
    const a = pow(1 - t, 1.45) * 205;
    const s = map(t, 0, 1, 5.5, 1.1);
    if (random() < 0.78) fill(255, 232, 190, a);
    else fill(205, 216, 255, a * 0.85);
    circle(x, y, s);
  }

  // poussieres dans tout le champ
  for (let i = 0; i < 850; i++) {
    const x = random(width), y = random(height);
    const prox = 1 - constrain(abs(x - cx) / 720, 0, 1);
    const a = 10 + prox * prox * 150 + random(0, 26);
    const s = random(1, 2.6) * (1 + prox * 1.7);
    fill(255, 235, 205, a);
    circle(x, y, s);
  }

  // halos flottants pres de l'ouverture
  for (let i = 0; i < 26; i++) {
    const y = lerp(topY - 70, botY + 90, random());
    const x = cx + (noise(i * 0.7, 8) - 0.5) * 460 * (0.3 + random());
    fill(255, 224, 170, random(12, 38));
    circle(x, y, random(9, 28));
  }

  // vignette
  noFill();
  const rMax = dist(0, 0, width, height);
  for (let r = rMax; r > width * 0.52; r -= 34) {
    stroke(2, 2, 6, map(r, width * 0.52, rMax, 0, 62));
    strokeWeight(34);
    ellipse(width / 2, height / 2, r, r * (height / width));
  }
  noStroke();

  // grain de la toile
  for (let i = 0; i < 12000; i++) {
    fill(random() < 0.5 ? 255 : 0, random(3, 12));
    rect(random(width), random(height), random(1, 2.2), random(1, 2.2));
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
}

function smoothstep(a, b, x) {
  const t = constrain((x - a) / (b - a), 0, 1);
  return t * t * (3 - 2 * t);
}

function boundaryY(x) {
  return height * 0.66 + (noise(x * 0.0011, 3.7) - 0.5) * height * 0.14;
}

function draw() {
  const W = width;
  const H = height;
  background(15, 12, 11);

  const topC = color(228, 226, 218);
  const botC = color(14, 11, 10);
  noStroke();
  for (let y = 0; y < H; y += 2) {
    const t = y / H;
    const c = lerpColor(topC, botC, smoothstep(0.2, 1.0, t));
    const n = (noise(y * 0.012, 7.3) - 0.5) * 16;
    fill(constrain(red(c) + n, 0, 255),
         constrain(green(c) + n, 0, 255),
         constrain(blue(c) + n - 2, 0, 255));
    rect(0, y, W, 2);
  }

  let g = drawingContext.createRadialGradient(W * 0.5, H * 0.15, 30, W * 0.5, H * 0.15, H * 0.55);
  g.addColorStop(0, 'rgba(236,239,242,0.30)');
  g.addColorStop(0.45, 'rgba(228,231,234,0.12)');
  g.addColorStop(1, 'rgba(224,228,230,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);

  g = drawingContext.createRadialGradient(W * 0.5, H * 1.02, 20, W * 0.5, H * 1.02, H * 0.55);
  g.addColorStop(0, 'rgba(122,72,42,0.12)');
  g.addColorStop(1, 'rgba(122,72,42,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);

  for (let i = 0; i < 260; i++) {
    const x = random(W);
    const by = boundaryY(x);
    const depth = random();
    const y = by + depth * (H - by);
    const r = random(26, 120) * (0.7 + 0.6 * depth);
    noStroke();
    fill(8 + random(16), 7 + random(11), 6 + random(9), random(10, 26));
    ellipse(x, y, r * 2, r * random(0.5, 0.95));
  }

  for (let i = 0; i < 240; i++) {
    const x = random(-60, W);
    const by = boundaryY(x + 60);
    const y = by + random(0, H - by);
    stroke(58 + random(52), 38 + random(30), 22 + random(18), random(6, 20));
    strokeWeight(random(1, 5));
    line(x, y, x + random(40, 240), y + random(-9, 9));
  }

  for (let i = 0; i < 16000; i++) {
    const x = random(W);
    const by = boundaryY(x);
    const r = random();
    let y;
    if (r < 0.55) y = by + random(0, H - by);
    else if (r < 0.9) y = Math.max(0, by - random(0, H * 0.3));
    else y = random(0, by);
    const above = by - y;
    const depth = constrain((y - by) / (H - by), 0, 1);
    let s = map(depth, 0, 1, 3, 15) + random(0, 6);
    let a = map(depth, 0, 1, 130, 235) + random(0, 45);
    if (above > 0) {
      s = Math.max(0.6, s * Math.exp(-above / 240));
      a = a * Math.exp(-above / 190);
    }
    const t = constrain(y / H, 0, 1);
    const k = Math.pow(t, 1.3);
    let cr = lerp(224, 24, k) + random(-18, 18);
    let cg = lerp(222, 20, k) + random(-18, 18);
    let cb = lerp(216, 17, k) + random(-16, 16);
    if (depth > 0.3 && random() < 0.15) { cr += 42; cg += 24; cb += 8; }
    noStroke();
    fill(constrain(cr, 0, 255), constrain(cg, 0, 255), constrain(cb, 0, 255), constrain(a, 0, 255));
    if (random() < 0.3) rect(x, y, s, s * random(0.6, 1.5));
    else ellipse(x, y, s, s * random(0.5, 1.15));
  }

  for (let i = 0; i < 70; i++) {
    const x = random(W);
    const y = random(0, H * 0.5);
    noStroke();
    fill(236, 238, 234, random(4, 11));
    ellipse(x, y, random(160, 520), random(60, 200));
  }

  for (let i = 0; i < 900; i++) {
    const x = random(W);
    const y = random(0, H * 0.5);
    const a = random(8, 60) * (1 - y / (H * 0.55));
    if (a <= 0.5) continue;
    noStroke();
    fill(232 + random(-12, 12), 232 + random(-12, 12), 228 + random(-12, 12), a);
    ellipse(x, y, random(0.6, 2.6), random(0.6, 2.2));
  }

  for (let i = 0; i < 520; i++) {
    const y = random(H);
    const t = y / H;
    const lum = lerp(232, 26, Math.pow(smoothstep(0.15, 1, t), 1.2));
    const darker = random() < 0.5;
    const base = lum + (darker ? -random(8, 28) : random(8, 24));
    stroke(constrain(base, 0, 255),
           constrain(base - 2, 0, 255),
           constrain(base - 7, 0, 255),
           random(5, 15));
    strokeWeight(random(1, 4));
    noFill();
    const x0 = random(-120, W);
    const len = random(90, 620);
    beginShape();
    for (let px = 0; px <= len; px += 22) {
      vertex(x0 + px, y + (noise(px * 0.012, y * 0.008) - 0.5) * 16);
    }
    endShape();
  }

  for (let i = 0; i < 90; i++) {
    const y = H * random(0.8, 1.0);
    stroke(92 + random(42), 70 + random(30), 48 + random(20), random(4, 13));
    strokeWeight(random(1, 3));
    noFill();
    beginShape();
    for (let x = 0; x <= W; x += 42) {
      vertex(x, y + (noise(x * 0.004, y * 0.01) - 0.5) * 20);
    }
    endShape();
  }

  const vg = drawingContext.createRadialGradient(W * 0.5, H * 0.46, H * 0.16, W * 0.5, H * 0.5, H * 0.78);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(0.68, 'rgba(0,0,0,0.10)');
  vg.addColorStop(1, 'rgba(6,5,7,0.52)');
  drawingContext.fillStyle = vg;
  drawingContext.fillRect(0, 0, W, H);

  for (let i = 0; i < 42000; i++) {
    const x = random(W);
    const y = random(H);
    const w = random() < 0.5;
    noStroke();
    fill(w ? 255 : 0, w ? 255 : 0, w ? 255 : 0, random(4, 13));
    rect(x, y, random(1, 2.4), random(1, 2.4));
  }
}

// p5.js 1.11 — image fixe, sans ressources externes.

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();

  paintAtmosphere();
  paintMoon();
  paintShore();
  paintWater();
  paintReflections();
  paintBoat();
  paintShroud();
  paintReeds();
  finishSurface();
}

function paintAtmosphere() {
  noStroke();

  // Sous-couche : bleu de suie, terre verte et lumière trouble.
  for (let y = 0; y < height; y += 8) {
    for (let x = 0; x < width; x += 8) {
      const mist = exp(
        -sq((x - 950) / 680) - sq((y - 760) / 460)
      );
      const cloud =
        noise(x * 0.0028, y * 0.0035) * 18 +
        noise(x * 0.018, y * 0.018) * 5;

      fill(
        13 + cloud * 0.65 + mist * 32,
        23 + cloud * 0.85 + mist * 35,
        29 + cloud + mist * 24
      );
      rect(x, y, 8, 8);
    }
  }

  // Brossage irrégulier de la couche atmosphérique.
  for (let i = 0; i < 19000; i++) {
    const x = random(width);
    const y = random(1090);
    const n = noise(x * 0.004, y * 0.005);
    stroke(118, 130, 118, random(2, 10));
    strokeWeight(random(0.5, 2.5));
    const len = random(5, 40);
    line(x, y, x + len, y + (n - 0.5) * 10);
  }
}

function paintMoon() {
  const cx = 1010;
  const cy = 462;
  const r = 151;

  noStroke();
  for (let d = 760; d > 290; d -= 9) {
    fill(194, 157, 89, 1.4);
    ellipse(cx, cy, d, d * 1.05);
  }

  const orb = new Path2D();
  orb.arc(cx, cy, r, 0, TWO_PI);

  push();
  drawingContext.clip(orb);

  const g = drawingContext.createLinearGradient(
    cx - r, cy - r, cx + r, cy + r
  );
  g.addColorStop(0, "#e8d5a0");
  g.addColorStop(0.48, "#c9b77f");
  g.addColorStop(1, "#958d68");
  drawingContext.fillStyle = g;
  drawingContext.fillRect(cx - r, cy - r, r * 2, r * 2);

  for (let i = 0; i < 6500; i++) {
    const x = random(cx - r, cx + r);
    const y = random(cy - r, cy + r);
    const n = noise(x * 0.025, y * 0.025);
    stroke(65, 75, 60, 7 + n * 17);
    strokeWeight(random(0.4, 2));
    line(x, y, x + random(2, 13), y + random(-1, 1));
  }

  // Une usure du bord, plutôt qu'un disque parfaitement découpé.
  noFill();
  for (let i = 0; i < 200; i++) {
    const a = random(TWO_PI);
    const rr = r - random(0, 5);
    stroke(224, 209, 164, random(15, 65));
    strokeWeight(random(0.5, 2.3));
    arc(cx, cy, rr * 2, rr * 2, a, a + random(0.01, 0.08));
  }
  pop();
}

function paintShore() {
  noStroke();
  for (let layer = 0; layer < 5; layer++) {
    const base = 970 + layer * 27;
    fill(27 - layer * 2, 43 - layer * 2, 44 - layer, 110);

    beginShape();
    vertex(0, 1160);
    for (let x = 0; x <= width; x += 12) {
      const h = noise(x * 0.003, layer * 1.8);
      vertex(x, base - h * (100 - layer * 12));
    }
    vertex(width, 1160);
    endShape(CLOSE);
  }

  // Arbres lointains : des présences sans feuillage.
  for (let i = 0; i < 26; i++) {
    const x = i < 15 ? random(-30, 440) : random(1260, 1640);
    const y = random(1000, 1100);
    const h = random(140, 460);
    bareBranch(x, y, h, -HALF_PI + random(-0.14, 0.14), 5, 4);
  }

  // Voile bas, partiellement posé sur les troncs.
  for (let i = 0; i < 1300; i++) {
    const x = random(width);
    const y = random(925, 1105);
    stroke(111, 125, 111, random(2, 8));
    strokeWeight(random(1, 4));
    line(x, y, x + random(20, 150), y);
  }
}

function bareBranch(x, y, len, angle, weight, depth) {
  const ex = x + cos(angle) * len;
  const ey = y + sin(angle) * len;
  stroke(15, 29, 32, 145);
  strokeWeight(weight);
  noFill();
  bezier(
    x, y,
    x + cos(angle + 0.09) * len * 0.35,
    y + sin(angle + 0.09) * len * 0.35,
    ex - 3, ey + len * 0.15,
    ex, ey
  );

  if (depth > 0) {
    bareBranch(
      ex, ey, len * random(0.48, 0.67),
      angle + random(-0.24, 0.24), weight * 0.62, depth - 1
    );
    const t = random(0.45, 0.78);
    bareBranch(
      lerp(x, ex, t), lerp(y, ey, t),
      len * random(0.25, 0.48),
      angle + random([-1, 1]) * random(0.4, 0.85),
      weight * 0.48, depth - 1
    );
  }
}

function paintWater() {
  noStroke();
  for (let y = 1080; y < height; y += 4) {
    const t = (y - 1080) / 920;
    fill(25 - t * 12, 42 - t * 20, 44 - t * 18);
    rect(0, y, width, 4);
  }

  for (let i = 0; i < 15500; i++) {
    const y = random(1080, height);
    const x = random(width);
    const depth = (y - 1080) / 920;
    const n = noise(x * 0.005, y * 0.018);
    stroke(
      62 + n * 23,
      83 + n * 19,
      79 + n * 14,
      random(4, 22)
    );
    strokeWeight(random(0.5, 1.7 + depth));
    const len = random(4, 28 + depth * 70);
    line(x, y, x + len, y + random(-1.5, 1.5));
  }
}

function paintReflections() {
  // Reflet lunaire, discontinu et décentré par les rides de l'eau.
  for (let i = 0; i < 4100; i++) {
    const y = random(1080, 1970);
    const t = (y - 1080) / 890;
    const center = 1010 + sin(t * 8) * 23 - t * 110;
    const spread = 36 + t * 125;
    const x = center + randomGaussian(0, spread);
    const fade = exp(-sq((x - center) / spread) * 0.8);

    stroke(190, 169, 112, random(4, 32) * fade * (1 - t * 0.65));
    strokeWeight(random(0.5, 2.8));
    line(x, y, x + random(3, 29 + t * 28), y);
  }

  // Le suaire laisse une rémanence pâle sous la coque.
  for (let i = 0; i < 1800; i++) {
    const y = random(1410, 1740);
    const t = (y - 1410) / 330;
    const x = random(430 + t * 110, 1190 - t * 130);
    const pulse = noise(x * 0.013, y * 0.025);
    stroke(159, 162, 138, (1 - t) * pulse * random(3, 23));
    strokeWeight(random(0.5, 2.3));
    line(x, y, x + random(4, 45), y);
  }

  noFill();
  for (let i = 0; i < 14; i++) {
    stroke(109, 130, 117, 15 - i * 0.6);
    strokeWeight(1);
    arc(817, 1400, 1030 + i * 41, 120 + i * 18, 0.05, PI - 0.1);
  }
}

function paintBoat() {
  const hull = new Path2D();
  hull.moveTo(255, 1301);
  hull.bezierCurveTo(583, 1377, 1118, 1270, 1380, 1191);
  hull.bezierCurveTo(1300, 1354, 1150, 1402, 898, 1430);
  hull.bezierCurveTo(584, 1463, 372, 1414, 255, 1301);
  hull.closePath();

  const g = drawingContext.createLinearGradient(600, 1290, 650, 1445);
  g.addColorStop(0, "#292e28");
  g.addColorStop(0.32, "#171e1d");
  g.addColorStop(1, "#090f13");
  drawingContext.fillStyle = g;
  drawingContext.fill(hull);

  push();
  drawingContext.clip(hull);
  noFill();

  for (let i = 0; i < 160; i++) {
    const y = random(1270, 1460);
    stroke(100, 91, 63, random(3, 19));
    strokeWeight(random(0.5, 2));
    bezier(250, y, 550, y + 100, 1080, y - 7, 1410, y - 125);
  }

  for (let i = 0; i < 2600; i++) {
    const x = random(260, 1380);
    const y = random(1240, 1460);
    stroke(133, 123, 87, random(2, 11));
    strokeWeight(1);
    line(x, y, x + random(2, 18), y - random(0, 3));
  }
  pop();

  // La lèvre arrière disparaît par endroits dans l'obscurité.
  noFill();
  stroke(123, 113, 79, 95);
  strokeWeight(3);
  bezier(264, 1303, 593, 1376, 1126, 1269, 1373, 1197);
}

function makeShroud() {
  const p = new Path2D();
  p.moveTo(435, 1249);
  p.bezierCurveTo(411, 1225, 420, 1181, 453, 1162);
  p.bezierCurveTo(479, 1148, 514, 1155, 540, 1171);
  p.bezierCurveTo(600, 1131, 646, 1123, 705, 1148);
  p.bezierCurveTo(780, 1176, 850, 1167, 927, 1167);
  p.bezierCurveTo(1005, 1166, 1048, 1192, 1100, 1184);
  p.bezierCurveTo(1153, 1175, 1189, 1185, 1248, 1202);
  p.bezierCurveTo(1165, 1242, 1083, 1268, 967, 1288);
  p.bezierCurveTo(786, 1332, 568, 1324, 435, 1249);
  p.closePath();
  return p;
}

function paintShroud() {
  const cloth = makeShroud();

  // Ombre portée étroite, sans halo numérique.
  push();
  drawingContext.translate(5, 13);
  drawingContext.fillStyle = "rgba(2, 9, 12, 0.7)";
  drawingContext.fill(cloth);
  pop();

  const g = drawingContext.createLinearGradient(640, 1130, 710, 1330);
  g.addColorStop(0, "#ded7b9");
  g.addColorStop(0.28, "#c8c8ae");
  g.addColorStop(0.64, "#a2ad9b");
  g.addColorStop(1, "#526e68");
  drawingContext.fillStyle = g;
  drawingContext.fill(cloth);

  push();
  drawingContext.clip(cloth);
  noFill();

  const folds = [
    [454, 1168, 503, 1159, 533, 1214, 500, 1274],
    [478, 1164, 534, 1178, 550, 1242, 543, 1296],
    [548, 1172, 569, 1208, 583, 1267, 649, 1321],
    [596, 1147, 604, 1201, 656, 1245, 722, 1327],
    [639, 1138, 652, 1197, 735, 1254, 831, 1313],
    [687, 1146, 712, 1189, 820, 1244, 920, 1302],
    [737, 1160, 812, 1202, 917, 1208, 1018, 1279],
    [823, 1171, 903, 1187, 988, 1230, 1091, 1257],
    [923, 1170, 1000, 1189, 1080, 1202, 1169, 1231],
    [1031, 1184, 1100, 1199, 1160, 1189, 1240, 1204]
  ];

  for (const f of folds) {
    for (let k = 0; k < 7; k++) {
      stroke(43, 67, 63, 4 + k);
      strokeWeight(24 - k * 3);
      bezier(...f);
    }
    for (let k = 0; k < 4; k++) {
      stroke(238, 228, 194, 14);
      strokeWeight(7 - k * 1.5);
      bezier(
        f[0] - 7, f[1],
        f[2] - 9, f[3],
        f[4] - 8, f[5],
        f[6] - 6, f[7]
      );
    }
  }

  // La tête demeure entièrement couverte.
  stroke(229, 221, 192, 110);
  strokeWeight(2);
  bezier(434, 1207, 431, 1170, 476, 1146, 508, 1174);
  stroke(69, 87, 78, 75);
  strokeWeight(4);
  bezier(441, 1232, 457, 1211, 477, 1218, 502, 1245);

  // Trame cassée et petites touches de pigment.
  for (let i = 0; i < 12500; i++) {
    const x = random(410, 1255);
    const y = random(1130, 1335);
    const n = noise(x * 0.037, y * 0.037);
    if (random() < 0.57) {
      stroke(242, 233, 202, random(4, 23) * n);
    } else {
      stroke(54, 79, 72, random(3, 18));
    }
    strokeWeight(random(0.4, 1.5));
    line(x, y, x + random(2, 10), y + random(0, 3));
  }
  pop();

  // Un rameau sec, posé sur la poitrine.
  noFill();
  stroke(88, 70, 40, 210);
  strokeWeight(2);
  bezier(631, 1212, 702, 1199, 776, 1225, 876, 1220);

  for (let i = 0; i < 7; i++) {
    const x = 666 + i * 27;
    const y = 1210 + sin(i * 0.43) * 8;
    const sign = i % 2 === 0 ? -1 : 1;
    push();
    translate(x, y);
    rotate(sign * 0.65);
    noStroke();
    fill(144 + i * 3, 112 + i * 2, 61, 205);
    beginShape();
    vertex(0, 0);
    bezierVertex(4, -9, 19, -11, 29, -3);
    bezierVertex(17, 2, 9, 4, 0, 0);
    endShape(CLOSE);
    stroke(77, 73, 44, 130);
    strokeWeight(0.7);
    line(1, 0, 24, -3);
    pop();
  }

  // Quelques éclats sur le bord avant de la coque.
  noFill();
  stroke(111, 111, 81, 120);
  strokeWeight(2);
  bezier(355, 1353, 632, 1411, 1083, 1329, 1288, 1258);
  stroke(191, 173, 116, 90);
  strokeWeight(1);
  bezier(919, 1353, 1068, 1326, 1216, 1285, 1288, 1258);
}

function paintReeds() {
  // Le premier plan reste ouvert au centre.
  for (let i = 0; i < 105; i++) {
    const left = random() < 0.62;
    const x = left ? random(-30, 290) : random(1410, 1640);
    const y = random(1810, 2080);
    const h = random(80, 390);
    const bend = left ? random(-45, 70) : random(-90, 30);

    noFill();
    stroke(8, 18, 22, random(130, 240));
    strokeWeight(random(1, 3.5));
    bezier(
      x, y,
      x + bend * 0.2, y - h * 0.4,
      x + bend, y - h * 0.8,
      x + bend * 0.8, y - h
    );

    if (random() < 0.3) {
      stroke(49, 55, 40, 160);
      strokeWeight(3);
      line(
        x + bend * 0.8, y - h,
        x + bend * 0.84 + 2, y - h - random(12, 27)
      );
    }
  }
}

function finishSurface() {
  // Grain mat et assombrissement des bords, intégrés aux pigments.
  loadPixels();

  for (let y = 0; y < height; y++) {
    const vy = sq((y - 940) / 1250);
    for (let x = 0; x < width; x++) {
      const index = 4 * (y * width + x);
      const vx = sq((x - 810) / 1040);
      const vignette = 1 - 0.20 * constrain(vx + vy, 0, 1.65);
      const grain = random(-3.5, 3.5);
      const weave =
        (x % 3 === 0 ? 0.65 : -0.2) +
        (y % 4 === 0 ? 0.55 : -0.15);

      pixels[index] = constrain(
        pixels[index] * vignette + grain + weave, 0, 255
      );
      pixels[index + 1] = constrain(
        pixels[index + 1] * vignette + grain + weave, 0, 255
      );
      pixels[index + 2] = constrain(
        pixels[index + 2] * vignette + grain * 0.85 + weave, 0, 255
      );
    }
  }

  updatePixels();
}

// p5.js 1.11 — image fixe, sans ressources externes.
function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function tintColor(hex, alpha) {
  const c = color(hex);
  c.setAlpha(alpha);
  return c;
}

function path(d) {
  return new Path2D(d);
}

function fillPath(p, hex, alpha = 255) {
  drawingContext.fillStyle = tintColor(hex, alpha).toString();
  drawingContext.fill(p);
}

function clipPath(p, fn) {
  push();
  drawingContext.clip(p);
  fn();
  pop();
}

function halo(x, y, radius, rgb, strength) {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(x, y, 0, x, y, radius);
  g.addColorStop(0, `rgba(${rgb},${strength})`);
  g.addColorStop(0.45, `rgba(${rgb},${strength * 0.28})`);
  g.addColorStop(1, `rgba(${rgb},0)`);
  ctx.fillStyle = g;
  ctx.fillRect(x - radius, y - radius, radius * 2, radius * 2);
}

function paint() {
  const ctx = drawingContext;

  // Fond de toile : une nuit verte, traversée d'une chaleur de cendre.
  const sky = ctx.createLinearGradient(0, 0, 0, height);
  sky.addColorStop(0, "#101e23");
  sky.addColorStop(0.32, "#344747");
  sky.addColorStop(0.49, "#69706a");
  sky.addColorStop(0.58, "#394d4c");
  sky.addColorStop(0.8, "#1a3539");
  sky.addColorStop(1, "#091b23");
  ctx.fillStyle = sky;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 21000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.002, y * 0.003);
    fill(tintColor(n > 0.5 ? "#a7a18a" : "#082b32", random(2, 9)));
    ellipse(x, y, random(15, 95), random(4, 35));
