  // Un corps entièrement enveloppé ; aucune blessure, aucun visage.
  const shroud = path(
    "M 490 1308 " +
    "C 493 1276 508 1253 531 1239 " +
    "C 546 1202 584 1187 618 1201 " +
    "C 642 1210 650 1223 661 1232 " +
    "C 699 1194 737 1184 780 1198 " +
    "C 826 1211 853 1237 904 1249 " +
    "C 959 1261 988 1261 1031 1277 " +
    "C 1072 1291 1110 1287 1142 1308 " +
    "L 1188 1340 " +
    "C 1140 1358 1085 1368 1029 1371 " +
    "C 949 1390 891 1390 817 1378 " +
