    g.addColorStop(0.76, "#9d9f8c");
    g.addColorStop(1, "#637e78");
    ctx.fillStyle = g;
    ctx.fillRect(470, 1170, 750, 250);

    // Trame fine et pigments irréguliers du tissu.
    noStroke();
    for (let i = 0; i < 9500; i++) {
      const x = random(480, 1200);
      const y = random(1180, 1400);
      fill(tintColor(
        noise(x * 0.019, y * 0.019) > 0.47 ? "#fff0c9" : "#536e69",
        random(3, 22)
      ));
