  bezier(0, -5, -3, -11, -6, -12, -7, -11);
  bezier(1, -5, 4, -12, 7, -13, 8, -12);
  pop();

  // Vernis sombre sur les bords.
  const vignette = ctx.createRadialGradient(810, 1040, 350, 810, 1040, 1320);
  vignette.addColorStop(0, "rgba(2,12,18,0)");
  vignette.addColorStop(0.62, "rgba(2,12,18,0.08)");
  vignette.addColorStop(1, "rgba(2,12,18,0.63)");
  ctx.fillStyle = vignette;
  ctx.fillRect(0, 0, width, height);

  // Grain final : irrégularités du pigment et fibres de la toile.
  noStroke();
  for (let i = 0; i < 78000; i++) {
    const x = random(width);
