  strokeWeight(0.5);
  for (let x = 2; x < width; x += 5) {
    stroke(tintColor("#bfb89d", random(1, 4)));
    line(x, 0, x, height);
  }
  for (let y = 3; y < height; y += 6) {
    stroke(tintColor("#050f16", random(2, 5)));
    line(0, y, width, y);
  }
}

// p5.js 1.11 — sketch autonome
function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();

  ciel();
  soleil();
  rivage();
  eau();
  barque();
  roseaux();
  feuille();
  patine();
}

function ciel() {
  noStroke();
  for (let y = 0; y < height; y += 4) {
    const t = constrain(y / 1120, 0, 1);
    fill(lerp(19, 79, t), lerp(29, 84, t), lerp(40, 83, t));
    rect(0, y, width, 4);
  }

  // Lavis irréguliers, sans contours fermés.
  for (let i = 0; i < 19000; i++) {
    const x = random(width);
    const y = random(1100);
    const n = noise(x * 0.003, y * 0.004);
    const l = 30 + n * 70;
    stroke(l * 0.88, l, l * 1.08, random(3, 12));
    strokeWeight(random(1, 7));
    const d = random(9, 67);
    line(x, y, x + d, y + random(-5, 5));
  }

  // Nuages bas, frottés dans la couleur encore humide.
  for (let i = 0; i < 2200; i++) {
    const x = random(-100, 1650);
    const y = random(775, 1070);
    stroke(29, 43, 49, random(3, 13));
    strokeWeight(random(2, 14));
    line(x, y, x + random(35, 180), y + random(-4, 4));
  }
}

function disqueIrregulier(cx, cy, r, seed) {
  beginShape();
  for (let a = 0; a < TWO_PI; a += TWO_PI / 240) {
    const n = noise(
      seed + cos(a) * 1.7,
      seed + sin(a) * 1.7
    );
    const rr = r + (n - 0.5) * 13;
    vertex(cx + cos(a) * rr, cy + sin(a) * rr);
  }
  endShape(CLOSE);
}

function soleil() {
  const cx = 810;
  const cy = 610;

  noStroke();
  for (let r = 451; r > 353; r -= 3) {
    fill(169, 150, 109, 2.8);
    disqueIrregulier(cx, cy, r, 12);
  }

  fill(72, 72, 62);
  disqueIrregulier(cx, cy, 352, 12);
  fill(13, 22, 28);
  disqueIrregulier(cx, cy, 346, 12);

  // Le disque garde une matière, plutôt qu'un noir numérique.
  for (let i = 0; i < 6800; i++) {
    const x = random(cx - 340, cx + 340);
    const y = random(cy - 340, cy + 340);
    if (sq(x - cx) + sq(y - cy) < sq(337)) {
      stroke(45, 51, 49, random(3, 12));
      strokeWeight(random(1, 4));
      line(x, y, x + random(-5, 5), y + random(2, 12));
    }
  }

  // Quelques éclats de pigment sur la seule lèvre éclairée.
  for (let i = 0; i < 440; i++) {
    const a = random(0.12, 2.85);
    const r = random(348, 354);
    const x = cx + cos(a) * r;
    const y = cy + sin(a) * r;
    stroke(163, 144, 101, random(8, 35));
    strokeWeight(random(0.5, 2));
    line(x, y, x + random(-3, 3), y + random(1, 5));
  }
}

function rivage() {
  noStroke();
  fill(31, 43, 45);
  beginShape();
  vertex(0, 1115);
  for (let x = 0; x <= width; x += 8) {
    const y = 1045 - 39 * noise(x * 0.003, 8);
    vertex(x, y);
  }
