  c.bezierCurveTo(-379, -63, -368, -132, -329, -154);
  c.bezierCurveTo(-299, -176, -258, -159, -244, -128);
  c.bezierCurveTo(-230, -111, -211, -118, -188, -136);
  c.bezierCurveTo(-119, -190, -13, -187, 72, -148);
  c.bezierCurveTo(164, -108, 254, -107, 315, -68);
  c.bezierCurveTo(354, -47, 393, -31, 411, -9);
  c.bezierCurveTo(306, 20, 242, 7, 169, 32);
  c.bezierCurveTo(71, 50, -12, 15, -110, 34);
  c.bezierCurveTo(-206, 41, -323, 8, -401, -35);
