    [-63, -171, -45, -113, 1, -57, -24, 33, 24],
    [25, -161, 19, -99, 67, -52, 103, 34, 17],
    [107, -132, 89, -86, 149, -41, 168, 25, 16],
    [194, -104, 161, -52, 229, -20, 244, 18, 21],
    [279, -83, 267, -48, 319, -29, 335, 7, 12]
