function patine() {
  // Grain du support et assombrissement doux des bords.
  loadPixels();
  for (let y = 0; y < height; y++) {
    const ny = (y - height * 0.48) / (height * 0.72);
    for (let x = 0; x < width; x++) {
      const nx = (x - width * 0.5) / (width * 0.72);
      const vignette = 1 - 0.20 * (nx * nx + ny * ny);
      const grain = random(-5, 5);
      const weave = (x % 3 === 0 ? 0.8 : 0) +
                    (y % 4 === 0 ? -0.8 : 0);
      const p = 4 * (y * width + x);
      pixels[p] = constrain(pixels[p] * vignette + grain + weave, 0, 255);
      pixels[p + 1] = constrain(pixels[p + 1] * vignette + grain + weave, 0, 255);
      pixels[p + 2] = constrain(pixels[p + 2] * vignette + grain + weave, 0, 255);
    }
  }
  updatePixels();
}

