function pigment(path, base, colors, amount, box, length = 35) {
  const ctx = drawingContext;
  push();
  ctx.fillStyle = base;
  ctx.fill(path);
  ctx.clip(path);

  for (let i = 0; i < amount; i++) {
    let x = random(box[0], box[2]);
    let y = random(box[1], box[3]);
    let col = color(random(colors));
    col.setAlpha(random(15, 75));
    stroke(col);
    strokeWeight(random(0.7, 4.8));
    let a = noise(x * 0.004, y * 0.004) * 1.8 - 0.9;
    let len = random(4, length);
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
  pop();
}

function curveStroke(points, col, weight) {
  noFill();
  stroke(col);
  strokeWeight(weight);
  bezier(...points);
}

