function atmosphere() {
  noFill();

  // Un fond de glacis presque noirs.
  for (let y = 0; y < height; y += 3) {
    const t = y / height;
    stroke(
      22 + 7 * sin(t * PI),
      33 + 12 * sin(t * PI),
      36 + 11 * sin(t * PI),
      220
    );
    strokeWeight(4);
    line(0, y, width, y);
  }

  // Empreintes de brosse, sans horizon net.
  for (let i = 0; i < 17000; i++) {
    const x = random(width);
    const y = random(height);
    const n = noise(x * 0.0025, y * 0.003);
    const warm = random() < 0.18;
    stroke(
      warm ? 91 : 34 + n * 22,
      warm ? 75 : 48 + n * 22,
      warm ? 49 : 50 + n * 20,
      random(3, 15)
    );
    strokeWeight(random(1, 8));
    const d = random(8, 95);
    line(x, y, x + d, y + random(-5, 5));
  }

  // Ombres périphériques en voiles translucides.
  noStroke();
  for (let i = 0; i < 90; i++) {
    fill(5, 13, 17, 2);
    ellipse(-160, 1050, 520 + i * 8, 2450);
    ellipse(1790, 950, 530 + i * 7, 2500);
  }
}

function moon() {
  const cx = 539;
  const cy = 423;
  const r = 185;

  noStroke();
  for (let k = 44; k > 0; k--) {
    fill(174, 163, 116, 1.2);
    ellipse(cx, cy, r * 2 + k * 5, r * 2 + k * 5);
  }

  fill(184, 180, 150);
  beginShape();
  for (let a = 0; a < TWO_PI; a += 0.018) {
    const rr = r + (noise(cos(a) * 3 + 9, sin(a) * 3 + 9) - 0.5) * 9;
    vertex(cx + cos(a) * rr, cy + sin(a) * rr);
  }
  endShape(CLOSE);

  const ctx = drawingContext;
  ctx.save();
  ctx.beginPath();
  ctx.arc(cx, cy, r - 1, 0, TWO_PI);
  ctx.clip();

  for (let i = 0; i < 12000; i++) {
    const x = random(cx - r, cx + r);
    const y = random(cy - r, cy + r);
    const n = noise(x * 0.018, y * 0.018);
    stroke(100 + n * 115, 103 + n * 103, 85 + n * 88, random(9, 48));
    strokeWeight(random(0.6, 3.5));
    line(x, y, x + random(2, 19), y + random(-2, 2));
  }

  // La matière obscure mord dans le disque.
  noStroke();
  for (let i = 0; i < 17; i++) {
    fill(27, 41, 43, 17);
    ellipse(cx + 106 + i * 1.1, cy - 80, 260, 350);
  }
  ctx.restore();
}

function water() {
  for (let i = 0; i < 15500; i++) {
    const y = random(680, 2000);
    const x = random(-60, 1660);
    const depth = map(y, 680, 2000, 0.25, 1);
    const n = noise(x * 0.004, y * 0.013);
    stroke(45 + n * 27, 63 + n * 24, 63 + n * 23, random(5, 24));
    strokeWeight(random(0.5, 2.6));
    const len = random(9, 100) * depth;
    line(x, y, x + len, y + random(-1.5, 1.5));
  }

  // De longues rides interrompues.
  noFill();
  for (let i = 0; i < 110; i++) {
    const y = random(830, 2000);
    const x = random(100, 1450);
    stroke(111, 121, 106, random(5, 16));
    strokeWeight(random(0.5, 1.5));
    bezier(
      x, y,
      x + 55, y - 4,
      x + 120, y + 4,
      x + random(130, 290), y
    );
  }
}

function banks() {
  noStroke();
  fill(13, 24, 25, 210);
  beginShape();
  vertex(0, 870);
  bezierVertex(120, 1040, 93, 1250, 180, 1450);
  bezierVertex(250, 1680, 210, 1840, 390, 2000);
  vertex(0, 2000);
  endShape(CLOSE);

  fill(12, 23, 24, 215);
  beginShape();
  vertex(1600, 630);
  bezierVertex(1490, 960, 1550, 1220, 1445, 1520);
  bezierVertex(1380, 1730, 1450, 1870, 1320, 2000);
  vertex(1600, 2000);
  endShape(CLOSE);

  // Des tiges desséchées, davantage gravées que dessinées.
  noFill();
  for (let i = 0; i < 240; i++) {
    const right = random() < 0.5;
    const x = right ? random(1470, 1640) : random(-40, 155);
    const y = random(1100, 2130);
    const h = random(80, 440);
    const bend = random(-70, 70);
    stroke(71, 72, 52, random(18, 65));
    strokeWeight(random(0.7, 2.1));
    bezier(x, y, x - 15, y - h * 0.35,
           x + bend, y - h * 0.8, x + bend, y - h);
    if (random() < 0.4) {
      line(x + bend, y - h, x + bend - 9, y - h + 34);
    }
  }
}

function reflection() {
  for (let i = 0; i < 2400; i++) {
    const y = random(660, 1840);
    const t = (y - 660) / 1180;
    const center = 530 + 95 * t + 20 * sin(t * 13);
    const spread = 15 + t * 135;
    const x = center + randomGaussian() * spread;
    if (random() < 0.28 + t * 0.4) continue;
    stroke(166, 156, 111, random(4, 25) * (1 - t * 0.45));
    strokeWeight(random(0.6, 2));
    line(x, y, x + random(3, 33), y + random(-0.8, 0.8));
  }
}

function hullPath() {
  const c = drawingContext;
  c.beginPath();
  c.moveTo(-627, -56);
  c.bezierCurveTo(-354, 16, 317, 18, 603, -89);
  c.bezierCurveTo(474, 105, 312, 176, 34, 187);
  c.bezierCurveTo(-274, 197, -485, 116, -627, -56);
  c.closePath();
}

function clothPath() {
  const c = drawingContext;
  c.beginPath();
  c.moveTo(-384, -37);
  c.bezierCurveTo(-342, -68, -306, -97, -234, -105);
  c.bezierCurveTo(-177, -172, -63, -174, 20, -133);
  c.bezierCurveTo(94, -118, 178, -142, 246, -112);
  c.bezierCurveTo(300, -91, 316, -40, 405, -14);
  c.bezierCurveTo(319, 6, 242, 24, 160, 13);
  c.bezierCurveTo(55, 39, -26, 2, -104, 13);
  c.bezierCurveTo(-205, 28, -311, 3, -384, -37);
  c.closePath();
}

function boat() {
  // Ombre et halo d'eau autour de la coque.
  noStroke();
  for (let i = 35; i > 0; i--) {
    fill(3, 12, 15, 4);
    ellipse(806, 1533, 1150 + i * 10, 120 + i * 5);
  }

  push();
  translate(810, 1408);
  rotate(-0.065);
  const ctx = drawingContext;

  hullPath();
  ctx.fillStyle = '#101b1c';
  ctx.fill();

  ctx.save();
  hullPath();
  ctx.clip();

  for (let i = 0; i < 5800; i++) {
    const x = random(-650, 640);
    const y = random(-100, 205);
    const n = noise(x * 0.01 + 20, y * 0.016 + 20);
    stroke(38 + n * 28, 43 + n * 22, 36 + n * 14, random(9, 36));
    strokeWeight(random(0.6, 3));
    line(x, y, x + random(6, 75), y + random(-3, 3));
  }

  noFill();
  for (let j = 0; j < 5; j++) {
    stroke(103, 86, 54, 24);
    strokeWeight(1.3);
    bezier(-600, -21 + j * 20, -260, 120 + j * 12,
           310, 116 + j * 10, 600, -54 + j * 12);
  }
  ctx.restore();

  // L'intérieur n'offre aucune destination au regard.
  noStroke();
  fill(6, 15, 17);
  beginShape();
  vertex(-593, -48);
  bezierVertex(-290, -97, 309, -119, 570, -79);
  bezierVertex(337, 5, -292, 30, -593, -48);
  endShape(CLOSE);

  noFill();
  stroke(128, 108, 67, 130);
  strokeWeight(3);
  bezier(-620, -55, -270, 33, 300, 24, 599, -88);
  stroke(157, 132, 82, 65);
  strokeWeight(1);
  bezier(-590, -60, -230, -104, 290, -124, 565, -85);

  // Le linge, lourd et vide.
  clothPath();
  ctx.fillStyle = '#bcb9a2';
  ctx.fill();

  ctx.save();
  clothPath();
  ctx.clip();

  for (let i = 0; i < 11000; i++) {
    const x = random(-400, 430);
    const y = random(-185, 45);
    const n = noise(x * 0.013 + 40, y * 0.02 + 40);
    const light = constrain(map(y, -160, 35, 1, 0.3), 0.3, 1);
    stroke(
      130 + n * 61 + light * 31,
      132 + n * 52 + light * 27,
      117 + n * 43 + light * 22,
      random(12, 48)
    );
    strokeWeight(random(0.5, 2.2));
    line(x, y, x + random(3, 24), y + random(-6, 4));
  }

  noFill();
  for (let j = 0; j < 24; j++) {
    const x = -320 + j * 29;
    stroke(61, 75, 70, random(20, 55));
    strokeWeight(random(1, 5));
    bezier(x, -120, x - 58, -71, x + 26, -17, x + 71, 33);
    stroke(226, 219, 186, random(35, 90));
    strokeWeight(random(0.7, 2.5));
    bezier(x + 5, -125, x - 49, -70, x + 33, -15, x + 79, 33);
  }
  ctx.restore();

  // Une ouverture : la présence n'est plus que son contour.
  noStroke();
  fill(48, 61, 57);
  beginShape();
  vertex(-172, -99);
  bezierVertex(-119, -133, -43, -133, 28, -96);
  bezierVertex(-41, -109, -95, -91, -172, -99);
  endShape(CLOSE);

  noFill();
  stroke(229, 220, 185, 150);
  strokeWeight(2);
  bezier(-232, -104, -177, -161, -62, -166, 20, -133);

  stroke(231, 220, 180, 90);
  strokeWeight(1.5);
  bezier(33, -126, 117, -101, 195, -141, 251, -106);
  pop();

  // Rides au premier plan.
  for (let i = 0; i < 100; i++) {
    const y = random(1625, 1750);
    const x = random(330, 1200);
    stroke(110, 119, 100, random(4, 18));
    strokeWeight(1);
    line(x, y, x + random(20, 140), y);
  }
}

