function patina() {
  // Grain final de toile et poussière de pigment.
  strokeWeight(1);
  for (let i = 0; i < 100000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.52) {
      stroke(219, 209, 170, random(3, 16));
    } else {
      stroke(1, 8, 11, random(5, 24));
    }
    point(x, y);
  }

  for (let x = 0; x < width; x += 4) {
    stroke(200, 192, 155, random(1, 4));
    line(x, 0, x, height);
  }
  for (let y = 0; y < height; y += 5) {
    stroke(2, 9, 12, random(2, 6));
    line(0, y, width, y);
  }
}

const W = 1600, H = 2000;
let M;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  buildMask();
  noLoop();
}

function buildMask() {
  let g = createGraphics(400, 500);
  g.pixelDensity(1);
  g.background(0);
  g.noStroke();
  g.scale(0.25);
  g.fill(255);
  g.quad(240, 2000, 1290, 2000, 940, 1380, 590, 1380);
  g.fill(0);
  g.beginShape();
  g.vertex(650, 2000); g.vertex(668, 1880); g.vertex(680, 1760);
  g.vertex(672, 1680); g.vertex(678, 1610); g.vertex(690, 1562);
  g.vertex(722, 1540); g.vertex(750, 1530); g.vertex(780, 1530);
  g.vertex(808, 1540); g.vertex(840, 1562); g.vertex(852, 1610);
  g.vertex(858, 1680); g.vertex(850, 1760); g.vertex(862, 1880);
  g.vertex(880, 2000); g.vertex(792, 2000); g.vertex(765, 1900);
  g.vertex(738, 2000);
  g.endShape(CLOSE);
  g.ellipse(765, 1496, 60, 54);
  g.rect(752, 1515, 26, 22);
  g.loadPixels();
  let a = new Float32Array(400 * 500);
  for (let i = 0; i < a.length; i++) a[i] = g.pixels[i * 4] / 255;
  blurArr(a, 400, 500, 2);
  blurArr(a, 400, 500, 2);
  M = a;
}

function blurArr(a, w, h, r) {
  let t = new Float32Array(a.length);
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      let s = 0;
      for (let k = -r; k <= r; k++) s += a[y * w + constrain(x + k, 0, w - 1)];
      t[y * w + x] = s / (2 * r + 1);
    }
  for (let y = 0; y < h; y++)
    for (let x = 0; x < w; x++) {
      let s = 0;
      for (let k = -r; k <= r; k++) s += t[constrain(y + k, 0, h - 1) * w + x];
      a[y * w + x] = s / (2 * r + 1);
    }
}

function maskAt(x, y) {
  let ix = constrain(floor(x / 4), 0, 399);
  let iy = constrain(floor(y / 4), 0, 499);
  return M[iy * 400 + ix];
}

function baseCol(x, y) {
  let hz = 720 + (noise(x * 0.003) - 0.5) * 14;
  let r, g, b;
  let dd = dist(x, y, 820, 700);
  if (y < hz) {
    let t = y / hz;
    r = lerp(203, 236, t); g = lerp(207, 233, t); b = lerp(217, 228, t);
    let hl = 690 - 70 * noise(x * 0.0018 + 5) - 25 * noise(x * 0.006 + 9);
    if (y > hl) {
      let k = constrain((y - hl) / 20, 0, 1) * 0.6;
      r -= 11 * k; g -= 10 * k; b -= 6 * k;
    }
    let n = noise(x * 0.0015, y * 0.003) - 0.5;
    r += n * 16; g += n * 16; b += n * 13;
    let gl = exp(-dd / 420) * 0.92;
    r += (255 - r) * gl; g += (249 - g) * gl; b += (238 - b) * gl;
  } else {
    let t = constrain((y - hz) / (2000 - hz), 0, 1);
    let tt = pow(t, 0.6);
    r = lerp(234, 146, tt); g = lerp(231, 159, tt); b = lerp(226, 190, tt);
    let n = noise(x * 0.003, y * 0.012 * (1.3 - t));
    let sh = (n - 0.5) * 34 * tt;
    r += sh; g += sh; b += sh * 0.8;
    let gl = exp(-dd / 380) * 0.75;
    r += (252 - r) * gl; g += (246 - g) * gl; b += (236 - b) * gl;
    let la = maskAt(x, y) * (0.5 + 0.5 * constrain((y - 1380) / 620, 0, 1));
    r += (255 - r) * 0.62 * la;
    g += (204 - g) * 0.55 * la;
    b += (146 - b) * 0.62 * la;
  }
  return [r, g, b];
}

function pathX(d) {
  return 820 + (150 + 140 * sin(d * 0.3)) / d;
}

function branch(x, y, len, ang, depth, col, w) {
  if (depth <= 0 || len < 3) return;
  let x2 = x + cos(ang) * len, y2 = y + sin(ang) * len;
  stroke(col[0], col[1], col[2], 200);
  strokeWeight(max(0.6, w));
  line(x, y, x2, y2);
  branch(x2, y2, len * random(0.72, 0.84), ang + random(-0.18, 0.18), depth - 1, col, w * 0.72);
  let n = floor(random(1, 3));
  for (let i = 0; i < n; i++) {
    branch(x2, y2, len * random(0.5, 0.7), ang + random(0.35, 0.8) * (random() < 0.5 ? -1 : 1), depth - 1, col, w * 0.6);
  }
}

function draw() {
  noStroke();
  for (let y = 0; y < H; y += 4) {
    for (let x = 0; x < W; x += 4) {
      let c = baseCol(x + 2, y + 2);
      fill(c[0], c[1], c[2]);
      rect(x, y, 4, 4);
    }
  }

  for (let i = 0; i < 110000; i++) {
    let x = random(W), y = random(H);
    let c = baseCol(x, y);
    let j = random(-7, 7);
    stroke(c[0] + j + random(-3, 3), c[1] + j + random(-3, 3), c[2] + j + random(-3, 3), 140);
    let ground = y > 720;
    let depth = ground ? constrain((y - 720) / 1280, 0.05, 1) : 0.6;
    let len = random(5, 20) * (ground ? 0.35 + depth : 1.2);
    let ang = ground ? (noise(x * 0.004, y * 0.004) - 0.5) * 0.6 : (noise(x * 0.002, y * 0.002) - 0.5) * 1.2;
    strokeWeight(random(1.5, 5) * (ground ? 0.5 + depth * 0.7 : 1));
    line(x - cos(ang) * len / 2, y - sin(ang) * len / 2, x + cos(ang) * len / 2, y + sin(ang) * len / 2);
  }

  let trees = [[1290, 832, 120, 0.8], [1435, 800, 80, 0.87], [230, 792, 70, 0.9], [1150, 760, 50, 0.93]];
  for (let t of trees) {
    let fc = baseCol(t[0], t[1] - t[2]);
    let col = [lerp(85, fc[0], t[3]), lerp(85, fc[1], t[3]), lerp(92, fc[2], t[3])];
    branch(t[0], t[1], t[2], -HALF_PI + random(-0.05, 0.05), 8, col, t[2] / 14);
  }

  let ds = [1.05, 1.5, 2.3, 3.2, 4.3, 5.6, 7.2, 9, 11.5, 14.5, 18];
  let tops = [];
  for (let d of ds) {
    let x = 820 + (-700 + 40 * sin(d * 0.7)) / d;
    let yb = 720 + 1280 / d;
    let h = 330 / d, w = max(1.5, 26 / d);
    let fc = baseCol(x, yb - h * 0.5);
    let f = constrain(1 - exp(-(d - 1) / 5), 0, 0.96);
    let pc = [lerp(58, fc[0], f), lerp(52, fc[1], f), lerp(54, fc[2], f)];
    let lean = random(-0.05, 0.05) * h;
    noStroke();
    fill(pc[0], pc[1], pc[2]);
    quad(x - w / 2, yb, x + w / 2, yb, x + w / 2 + lean, yb - h, x - w / 2 + lean, yb - h);
    fill(pc[0] * 0.85, pc[1] * 0.85, pc[2] * 0.88, 120);
    quad(x + w * 0.1, yb, x + w / 2, yb, x + w / 2 + lean, yb - h, x + w * 0.1 + lean, yb - h);
    let gc = baseCol(x, yb);
    fill(min(255, gc[0] + 14), min(255, gc[1] + 14), min(255, gc[2] + 12));
    ellipse(x, yb, w * 2.6, w * 0.7);
    fill(lerp(240, fc[0], f * 0.5), lerp(242, fc[1], f * 0.5), lerp(246, fc[2], f * 0.5));
    ellipse(x + lean, yb - h, w * 1.35, w * 0.55);
    tops.push([x + lean * 0.72, yb - h * 0.72, d, pc]);
  }
  noFill();
  for (let i = 0; i < tops.length - 1; i++) {
    let a = tops[i], b = tops[i + 1];
    let sag = 26 / ((a[2] + b[2]) / 2);
    stroke(b[3][0], b[3][1], b[3][2], 170);
    strokeWeight(max(0.7, 2.4 / a[2]));
    bezier(a[0], a[1], lerp(a[0], b[0], 0.33), lerp(a[1], b[1], 0.33) + sag,
      lerp(a[0], b[0], 0.66), lerp(a[1], b[1], 0.66) + sag, b[0], b[1]);
  }

  let side = 1;
  noStroke();
  for (let d = 1.12; d < 26; d += 0.26) {
    let vis = pow(constrain(1 - (d - 1.5) / 17, 0, 1), 1.25);
    if (vis < 0.02) break;
    let x = pathX(d) + side * 22 / d + random(-3, 3) / d;
    let y = 720 + 1280 / d;
    let w = 40 / d;
    let h = max(1.2, 1280 * 0.075 / (d * d));
    let c = baseCol(x, y);
    let k = 0.55 * vis;
    let sc = [lerp(c[0], 92, k), lerp(c[1], 102, k), lerp(c[2], 140, k)];
    let fl = [lerp(c[0], 150, k * 0.6), lerp(c[1], 160, k * 0.6), lerp(c[2], 190, k * 0.6)];
    if (h > 6) {
      fill(min(255, c[0] + 18 * vis), min(255, c[1] + 18 * vis), min(255, c[2] + 16 * vis));
      ellipse(x, y - h * 0.22, w * 1.18, h * 0.7);
      ellipse(x, y + h * 0.33, w * 0.98, h * 0.46);
      fill(sc[0], sc[1], sc[2], 235);
      ellipse(x, y - h * 0.2, w, h * 0.6);
      ellipse(x, y + h * 0.33, w * 0.8, h * 0.38);
      fill(fl[0], fl[1], fl[2], 200);
      ellipse(x, y - h * 0.26, w * 0.7, h * 0.36);
      ellipse(x, y + h * 0.29, w * 0.55, h * 0.2);
      fill(255, 255, 255, 40 * vis);
      for (let s = 0; s < 6; s++) circle(x + random(-w, w), y + random(-h * 0.6, h * 0.6), random(1, 3));
    } else {
      fill(sc[0], sc[1], sc[2], 220 * vis + 20);
      ellipse(x, y, w, h);
    }
    side *= -1;
  }

  noStroke();
  for (let i = 0; i < 320; i++) {
    let y = 760 + randomGaussian() * 95;
    let x = random(-200, W + 200);
    let fc = baseCol(constrain(x, 0, W - 1), constrain(y, 0, H - 1));
    fill(min(255, fc[0] + 8), min(255, fc[1] + 8), min(255, fc[2] + 8), 10);
    ellipse(x, y, random(200, 600), random(18, 60));
  }

  let ctx = drawingContext;
  let gr = ctx.createRadialGradient(820, 700, 0, 820, 700, 520);
  gr.addColorStop(0, 'rgba(255,250,240,0.35)');
