// Le manteau encore tiède — p5.js 1.11
const W = 1600, H = 2000, FLOOR = 1450;
const VP = { x: 1180, y: 1000 };
const HX = 540, HY = 600;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  paintWall();
  paintFloor();
  paintBaseboard();
  paintDoorway();
  paintLightSpill();
  coatShadow();
  paintCoat();
  paintHook();
  paintShoes();
  paintBeam();
  paintDust();
  vignette();
  grain();
}

function draw() {}

// ---------- helpers ----------
function sampleClosed(pts, steps) {
  const out = [];
  const n = pts.length;
  for (let i = 0; i < n; i++) {
    const p0 = pts[(i - 1 + n) % n], p1 = pts[i], p2 = pts[(i + 1) % n], p3 = pts[(i + 2) % n];
    for (let s = 0; s < steps; s++) {
      const t = s / steps;
      out.push({
        x: curvePoint(p0[0], p1[0], p2[0], p3[0], t),
        y: curvePoint(p0[1], p1[1], p2[1], p3[1], t)
      });
    }
  }
  return out;
}

function drawPoly(poly) {
  beginShape();
  for (const p of poly) vertex(p.x, p.y);
  endShape(CLOSE);
}

function clipPoly(poly) {
  const c = drawingContext;
  c.save();
  c.beginPath();
  c.moveTo(poly[0].x, poly[0].y);
  for (let i = 1; i < poly.length; i++) c.lineTo(poly[i].x, poly[i].y);
  c.closePath();
  c.clip();
}

function unclip() { drawingContext.restore(); }

function coatPoly(dx, dy) {
  const raw = [
    [0, 0], [-55, 28], [-140, 85], [-182, 150], [-192, 320], [-200, 520], [-192, 705],
    [-110, 722], [-20, 712], [70, 728], [150, 708], [196, 694], [200, 500], [190, 320],
    [178, 150], [138, 85], [55, 28]
  ].map(p => [p[0] + HX + dx, p[1] + HY + dy]);
  return sampleClosed(raw, 12);
}

// ---------- wall ----------
function paintWall() {
  for (let y = 0; y < FLOOR; y++) {
    const t = y / FLOOR;
    stroke(lerpColor(color(34, 31, 28), color(66, 55, 42), t));
    line(0, y, W, y);
  }
  noFill();
  for (let i = 0; i < 9000; i++) {
    const x = random(W), y = random(FLOOR);
    const n = noise(x * 0.003, y * 0.003);
    const l = map(n, 0, 1, -22, 22);
    stroke(58 + l, 50 + l, 40 + l * 0.8, random(8, 22));
    strokeWeight(random(2, 7));
    const a = noise(x * 0.001 + 50, y * 0.001) * TWO_PI * 2;
    const len = random(20, 70);
    line(x, y, x + cos(a) * len, y + sin(a) * len * 0.3);
  }
  // warm glow on wall near the doorway
  blendMode(ADD);
  noStroke();
  for (let r = 900; r > 40; r -= 15) {
    fill(16, 11, 6, 3);
    ellipse(1180, 900, r * 1.3, r * 1.9);
  }
  blendMode(BLEND);
}

// ---------- floor ----------
function paintFloor() {
  for (let y = FLOOR; y < H; y++) {
    const t = (y - FLOOR) / (H - FLOOR);
    stroke(lerpColor(color(30, 23, 18), color(52, 39, 28), t));
    line(0, y, W, y);
  }
  // planks in perspective
  strokeWeight(3);
  for (let xb = -3000; xb < 5000; xb += 150) {
    const xf = VP.x + (xb - VP.x) * (FLOOR - VP.y) / (H - VP.y);
    stroke(15, 11, 8, 120);
    line(xf, FLOOR, xb, H);
  }
  // grain
  for (let i = 0; i < 5000; i++) {
    const x = random(-200, W + 200), y = random(FLOOR + 5, H);
    let dx = VP.x - x, dy = VP.y - y;
    const m = sqrt(dx * dx + dy * dy);
    dx /= m; dy /= m;
    const len = random(15, 60) * map(y, FLOOR, H, 0.4, 1.2);
    const l = random(-12, 14);
    stroke(48 + l, 36 + l, 26 + l, random(15, 40));
    strokeWeight(random(1, 3));
    line(x, y, x + dx * len, y + dy * len);
  }
}

function paintBaseboard() {
