// ---------- doorway ----------
function qp(FT, HT, FB, HB, u, v) {
  const tx = lerp(FT[0], HT[0], u), ty = lerp(FT[1], HT[1], u);
  const bx = lerp(FB[0], HB[0], u), by = lerp(FB[1], HB[1], u);
  return [lerp(tx, bx, v), lerp(ty, by, v)];
}

function paintDoorway() {
  noStroke();
  // casing
  fill(42, 31, 24);
  rect(955, 300, 510, FLOOR - 300);
  stroke(80, 60, 42, 90);
  strokeWeight(2);
  noFill();
  rect(962, 308, 496, FLOOR - 308);

