  g.addColorStop(1, 'rgb(238,206,156)');
  c.fillStyle = g;
  c.fillRect(1000, 350, 420, FLOOR - 350);
  // soft unreadable shimmer beyond
  noStroke();
  for (let i = 0; i < 400; i++) {
    const x = random(1005, 1415), y = random(360, FLOOR);
    fill(255, random(235, 252), random(200, 235), random(10, 35));
    ellipse(x, y, random(10, 40), random(30, 120));
  }

  // door panel, swung inward
  const FT = [1240, 318], HT = [1420, 350], FB = [1240, 1495], HB = [1420, FLOOR];
  const panel = [{ x: FT[0], y: FT[1] }, { x: HT[0], y: HT[1] }, { x: HB[0], y: HB[1] }, { x: FB[0], y: FB[1] }];
  noStroke();
  fill(46, 34, 26);
  drawPoly(panel);
  clipPoly(panel);
  for (let i = 0; i < 1500; i++) {
    const x = random(1235, 1425), y = random(310, 1500);
    const l = random(-10, 10);
    stroke(48 + l, 35 + l, 26 + l, 40);
    strokeWeight(random(1, 3));
    line(x, y, x + random(-1, 1), y + random(20, 60));
  }
  // darker toward hinge
  noStroke();
  for (let k = 0; k < 20; k++) {
    fill(10, 8, 6, 8);
    const u = map(k, 0, 20, 0.3, 1);
    const a = qp(FT, HT, FB, HB, u, 0), b = qp(FT, HT, FB, HB, u, 1);
    quad(a[0], a[1], HT[0], HT[1], HB[0], HB[1], b[0], b[1]);
