  noStroke();
  fill(160, 118, 78);
  quad(1240, 318, 1226, 322, 1226, 1490, 1240, 1495);
  stroke(255, 225, 170, 200);
  strokeWeight(3);
  line(1226, 322, 1226, 1490);
