  scale(-s, s);
  const pts = [[-112, 0], [-104, -30], [-62, -46], [0, -56], [40, -76], [96, -72], [112, -40], [106, 0], [0, 8]];
  noStroke();
  fill(46, 31, 22);
  beginShape();
  curveVertex(pts[pts.length - 1][0], pts[pts.length - 1][1]);
  for (const p of pts) curveVertex(p[0], p[1]);
  curveVertex(pts[0][0], pts[0][1]);
  curveVertex(pts[1][0], pts[1][1]);
  endShape();
  // sole
  stroke(22, 16, 12);
  strokeWeight(7);
  noFill();
  beginShape();
  curveVertex(-110, -6); curveVertex(-110, -2); curveVertex(-40, 6); curveVertex(50, 6); curveVertex(106, 0); curveVertex(106, -4);
  endShape();
  // opening
  noStroke();
  fill(12, 9, 7);
  ellipse(60, -66, 74, 20);
  // creases
  stroke(26, 18, 13, 200);
  strokeWeight(3);
  line(-30, -48, -10, -24);
  line(-12, -52, 6, -30);
  // toe highlight
  noFill();
  stroke(200, 160, 110, lit);
  strokeWeight(4);
  arc(-82, -18, 70, 50, PI * 1.05, PI * 1.6);
  stroke(255, 215, 160, lit * 0.6);
  strokeWeight(2);
  arc(-40, -32, 90, 40, PI * 1.1, PI * 1.55);
  pop();
}

