// ---------- utilitaires ----------
function mix(a, b, t) {
  t = constrain(t, 0, 1);
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}
function mul(c, k) { return [c[0] * k, c[1] * k, c[2] * k]; }
function rgba(c, a) {
  return 'rgba(' + (constrain(c[0], 0, 255) | 0) + ',' + (constrain(c[1], 0, 255) | 0) + ',' +
    (constrain(c[2], 0, 255) | 0) + ',' + constrain(a, 0, 1).toFixed(3) + ')';
}
function dab(x, y, len, wt, ang, c, a) {
  ctx.fillStyle = rgba(c, a);
  ctx.beginPath();
  ctx.ellipse(x, y, max(len / 2, 0.5), max(wt / 2, 0.5), ang, 0, TWO_PI);
  ctx.fill();
}
function tracePoly(poly) {
  ctx.beginPath();
  ctx.moveTo(poly[0][0], poly[0][1]);
  for (let i = 1; i < poly.length; i++) ctx.lineTo(poly[i][0], poly[i][1]);
  ctx.closePath();
}
function fillPoly(poly, c, a) { ctx.fillStyle = rgba(c, a); tracePoly(poly); ctx.fill(); }
function strokePoly(poly, c, a, w) { ctx.strokeStyle = rgba(c, a); ctx.lineWidth = w; tracePoly(poly); ctx.stroke(); }
function inPoly(x, y, poly) {
  let c = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const xi = poly[i][0], yi = poly[i][1], xj = poly[j][0], yj = poly[j][1];
    if (((yi > y) != (yj > y)) && (x < (xj - xi) * (y - yi) / (yj - yi) + xi)) c = !c;
  }
  return c;
}
function bbox(poly) {
  let x0 = 1e9, y0 = 1e9, x1 = -1e9, y1 = -1e9;
  for (const p of poly) { x0 = min(x0, p[0]); y0 = min(y0, p[1]); x1 = max(x1, p[0]); y1 = max(y1, p[1]); }
  return [x0, y0, x1, y1];
}
function paintPoly(poly, n, colFn, len, wt, angFn, alpha) {
  const b = bbox(poly);
  ctx.save();
  tracePoly(poly);
  ctx.clip();
  let placed = 0, tries = 0;
  while (placed < n && tries < n * 10) {
    tries++;
    const x = random(b[0], b[2]), y = random(b[1], b[3]);
    if (!inPoly(x, y, poly)) continue;
    const c = colFn(x, y);
    const j = random(-9, 9);
    dab(x, y, len * random(0.6, 1.3), wt * random(0.6, 1.2), angFn(x, y) + random(-0.12, 0.12),
      [c[0] + j, c[1] + j * 0.9, c[2] + j * 0.8], alpha * random(0.55, 1));
    placed++;
  }
  ctx.restore();
}
