// ---------- fenêtre ----------
function swallow(x, y, s) {
  ctx.fillStyle = rgba([30, 24, 40], 0.9);
  ctx.beginPath();
  ctx.moveTo(x, y);
  ctx.quadraticCurveTo(x - 10 * s, y - 7 * s, x - 22 * s, y - 2 * s);
  ctx.quadraticCurveTo(x - 10 * s, y - 1 * s, x, y + 3 * s);
  ctx.quadraticCurveTo(x + 10 * s, y - 1 * s, x + 22 * s, y - 8 * s);
  ctx.quadraticCurveTo(x + 10 * s, y - 7 * s, x, y);
  ctx.fill();
}
function skyline(col, hmin, hmax, wmin, wmax) {
  ctx.fillStyle = rgba(col, 1);
  ctx.beginPath();
  ctx.moveTo(WIN.x0 - 10, WIN.y1);
  let x = WIN.x0 - 10;
  while (x < WIN.x1 + 10) {
    const bw = random(wmin, wmax), bh = random(hmin, hmax);
    ctx.lineTo(x, bh);
    const r = random();
    if (r < 0.35) {
      ctx.lineTo(x + bw * 0.5, bh - random(20, 45));
    } else if (r < 0.6) {
      const cxp = x + bw * random(0.2, 0.7), ch = random(10, 22);
      ctx.lineTo(cxp, bh); ctx.lineTo(cxp, bh - ch); ctx.lineTo(cxp + 8, bh - ch); ctx.lineTo(cxp + 8, bh);
    }
    ctx.lineTo(x + bw, bh);
    x += bw;
  }
  ctx.lineTo(WIN.x1 + 10, WIN.y1);
  ctx.closePath();
  ctx.fill();
}
