// ---------- tache de lumière ----------
function patchPt(u, v) {
  const tx = lerp(PA[0], PB[0], u), ty = lerp(PA[1], PB[1], u);
  const bx = lerp(PD[0], PC[0], u), by = lerp(PD[1], PC[1], u);
  return [lerp(tx, bx, v), lerp(ty, by, v)];
}
function patchLight(u, v) {
  const pen = 0.015 + 0.05 * v;
  let e = constrain(min(min(u, 1 - u), min(v, 1 - v)) / pen, 0, 1);
  e = e * e * (3 - 2 * e);
  const mu = constrain((abs(u - 0.5) - 0.012) / (0.012 + 0.02 * v), 0, 1);
  const mv = constrain((abs(v - 0.55) - 0.012) / (0.012 + 0.02 * v), 0, 1);
  return e * (0.25 + 0.75 * mu * mv);
}
function paintLightPatch() {
  ctx.save();
  ctx.filter = 'blur(10px)';
  fillPoly([PA, PB, PC, PD], [150, 90, 50], 0.22);
  ctx.restore();
  blendMode(ADD);
  for (let i = 0; i < 11000; i++) {
    const u = random(), v = random();
    const L = patchLight(u, v);
    if (L <= 0.01) continue;
    const p = patchPt(u, v);
    dab(p[0], p[1], random(25, 55), random(8, 16), atan2(p[1] - VP.y, p[0] - VP.x), [86, 50, 23], 0.16 * L * (1 - v * 0.35));
  }
  blendMode(BLEND);
}

