const VELVET = [78, 104, 100];
function velvet(x, y, k) {
  const side = constrain(1 - (x - 990) / 520, 0, 1);
  let c = mix([30, 44, 48], VELVET, 0.35 + side * 0.45);
  c = mul(c, k);
  c = mix(c, [22, 30, 34], noise(x * 0.02, y * 0.02) * 0.3);
  return mix(c, [210, 140, 85], chairLight(x, y) * 0.6);
}
