  const skirt = [[995, 1625], [1250, 1642], [1505, 1625], [1505, 1712], [1250, 1728], [995, 1712]];
  fillPoly(skirt, [34, 48, 50], 1);
  paintPoly(skirt, 4000, (x, y) => velvet(x, y, 0.7), 16, 6, () => HALF_PI, 0.42);
  const armCol = (x, y) => {
