  };
  const rarm = [[1404, 1640], [1404, 1385], [1418, 1345], [1458, 1328], [1498, 1342], [1510, 1385], [1506, 1640]];
  fillPoly(rarm, [40, 56, 58], 1);
  paintPoly(rarm, 4000, armCol, 18, 6, () => HALF_PI, 0.42);
  const larm = [[994, 1640], [990, 1385], [1002, 1345], [1042, 1328], [1080, 1342], [1094, 1385], [1094, 1640]];
