  paintPoly(sleeve, 1600, (x, y) => col(x, y, 0.85), 8, 4, knit, 0.6);
  const cuff = [[980, 1660], [978, 1690], [954, 1700], [946, 1688], [950, 1655]];
  paintPoly(cuff, 300, (x, y) => col(x, y, 0.7), 6, 3, () => HALF_PI, 0.7);
  const body = [[982, 1345], [1010, 1322], [1050, 1316], [1090, 1330], [1108, 1352], [1102, 1420], [1110, 1500], [1104, 1575], [1085, 1600], [1062, 1588], [1040, 1606], [1012, 1592], [990, 1604], [978, 1520], [984, 1430]];
  fillPoly(body, [118, 76, 72], 1);
  paintPoly(body, 4500, (x, y) => col(x, y, 1), 8, 4, knit, 0.6);
  for (let i = 0; i <= 40; i++) {
    const t = i / 40;
    dab(lerp(1052, 1062, t), lerp(1330, 1595, t), 9, 5, HALF_PI, mix([180, 120, 108], [240, 170, 120], chairLight(1055, 1450) * 0.4), 0.5);
  }
  for (const by of [1400, 1470, 1540]) {
    const bx = lerp(1052, 1062, (by - 1330) / 265);
    dab(bx + 2, by + 2, 11, 11, 0, [40, 24, 24], 0.5);
    dab(bx, by, 10, 10, 0, [215, 195, 170], 1);
    dab(bx - 1.5, by - 1.5, 4, 4, 0, [255, 235, 210], 0.8);
  }
  ctx.strokeStyle = rgba([60, 34, 36], 0.35); ctx.lineWidth = 3;
  ctx.beginPath(); ctx.moveTo(1000, 1342); ctx.bezierCurveTo(990, 1420, 1004, 1500, 996, 1592); ctx.stroke();
  ctx.beginPath(); ctx.moveTo(1082, 1340); ctx.bezierCurveTo(1094, 1420, 1086, 1500, 1092, 1592); ctx.stroke();
  strokePoly(body, [30, 18, 20], 0.4, 1.5);
  strokePoly(sleeve, [30, 18, 20], 0.4, 1.5);
}

// ---------- feuille tombée dans la lumière ----------
function paintLeaf() {
  ctx.save(); ctx.filter = 'blur(2px)';
  dab(626, 1707, 46, 18, 0.4, [50, 32, 24], 0.5);
  ctx.restore();
  dab(620, 1700, 46, 18, 0.4, [196, 148, 62], 1);
  dab(616, 1698, 30, 8, 0.4, [230, 185, 100], 0.6);
  ctx.strokeStyle = rgba([130, 90, 40], 0.9); ctx.lineWidth = 1.5;
  ctx.beginPath(); ctx.moveTo(600, 1691); ctx.lineTo(648, 1712); ctx.stroke();
}

// ---------- rayon et poussière ----------
function paintBeam() {
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, 1600, 2000);
  ctx.rect(WIN.x0 - 24, WIN.y0 - 24, WIN.x1 - WIN.x0 + 48, WIN.y1 - WIN.y0 + 24);
  ctx.clip('evenodd');
  blendMode(ADD);
  const h = beamHull();
  let cx = 0, cy = 0;
  for (const p of h) { cx += p[0]; cy += p[1]; }
  cx /= h.length; cy /= h.length;
  for (let k = 0; k < 16; k++) {
    const s = k / 16 * 0.55;
    fillPoly(h.map(p => [lerp(p[0], cx, s), lerp(p[1], cy, s)]), [150, 95, 55], 0.022);
  }
  ctx.lineCap = 'round';
  for (let i = 0; i < 8; i++) {
    const u = random();
    const e = patchPt(u, random(0.4, 1));
    ctx.strokeStyle = rgba([160, 100, 55], 0.025);
    ctx.lineWidth = random(20, 50);
    ctx.beginPath(); ctx.moveTo(lerp(WIN.x0, WIN.x1, u), random(500, 1000)); ctx.lineTo(e[0], e[1]); ctx.stroke();
  }
  blendMode(BLEND);
  ctx.restore();
}
function paintDust() {
  blendMode(ADD);
  const hull = beamHull();
  let n = 0;
  while (n < 650) {
    const x = random(200, 1220), y = random(700, 1880);
    if (!inPoly(x, y, hull)) continue;
    n++;
    const big = random() > 0.9;
    const r = big ? random(4, 8) : random(0.8, 2.6);
    dab(x, y, r * 2, r * 2, 0, [255, 205, 150], big ? random(0.03, 0.08) : random(0.15, 0.6));
  }
  blendMode(BLEND);
}

// ---------- vignette et grain ----------
function vignetteAndGrain() {
  blendMode(BLEND);
  const g = ctx.createRadialGradient(820, 1150, 450, 820, 1150, 1400);
  g.addColorStop(0, 'rgba(12,8,12,0)');
  g.addColorStop(1, 'rgba(12,8,12,0.7)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1600, 2000);
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const idx = i >> 2;
    const x = idx % 1600, y = (idx / 1600) | 0;
    const n = (random() - 0.5) * 16 + sin(x * 1.3) * sin(y * 1.3) * 3;
    pixels[i] += n;
    pixels[i + 1] += n;
    pixels[i + 2] += n * 0.9;
  }
  updatePixels();
}

const W = 1600, H = 2000;
const HX = 760, HY = 1150;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function draw() {
  paintSky();
  paintStars();
  paintGlow(1150, 1420, 900, [255, 170, 110], 0.35);
  paintHills();
  paintMeadow();
  paintStem();
  paintGlow(HX, HY, 300, [255, 215, 170], 0.14);
  paintHead();
  paintDrift();
  paintLanded();
  paintFrontGrass();
  paintVignette();
  paintGrain();
}

// ---------- utilitaires ----------
function smooth01(a, b, t) {
  const x = constrain((t - a) / (b - a), 0, 1);
  return x * x * (3 - 2 * x);
}

function paintGlow(x, y, r, c, a) {
  const g = drawingContext.createRadialGradient(x, y, 0, x, y, r);
  g.addColorStop(0, `rgba(${c[0]},${c[1]},${c[2]},${a})`);
  g.addColorStop(1, `rgba(${c[0]},${c[1]},${c[2]},0)`);
  drawingContext.fillStyle = g;
  drawingContext.fillRect(x - r, y - r, 2 * r, 2 * r);
}

function skyCol(y) {
  const s = [
    [0, 8, 10, 30],
    [700, 24, 28, 68],
    [1150, 68, 50, 98],
    [1330, 165, 95, 98],
    [1420, 240, 168, 110],
    [2000, 240, 168, 110]
  ];
  y = constrain(y, 0, 2000);
  for (let i = 0; i < s.length - 1; i++) {
    if (y <= s[i + 1][0]) {
      const t = (y - s[i][0]) / (s[i + 1][0] - s[i][0]);
      return [
        lerp(s[i][1], s[i + 1][1], t),
        lerp(s[i][2], s[i + 1][2], t),
        lerp(s[i][3], s[i + 1][3], t)
      ];
    }
  }
  return [240, 168, 110];
}

// ---------- ciel ----------
function paintSky() {
  strokeWeight(1);
  for (let y = 0; y < H; y++) {
    const c = skyCol(y);
    stroke(c[0], c[1], c[2]);
    line(0, y, W, y);
  }
  for (let i = 0; i < 28000; i++) {
    const x = random(-20, W + 20), y = random(-20, 1500);
    const c = skyCol(y + random(-40, 40));
    const j = (noise(x * 0.0025, y * 0.0025) - 0.5) * 40;
    stroke(
      c[0] + j + random(-6, 6),
      c[1] + j * 0.7 + random(-6, 6),
      c[2] + j * 0.9 + random(-6, 6),
      38
    );
    strokeWeight(random(2, 7));
    const a = (noise(x * 0.0015 + 50, y * 0.0015) - 0.5) * 0.9;
    const L = random(12, 46);
    line(x, y, x + cos(a) * L, y + sin(a) * L);
  }
}

function paintStars() {
  noStroke();
  for (let i = 0; i < 650; i++) {
    const x = random(W), y = pow(random(), 1.7) * 1300;
    const a = map(y, 0, 1300, 200, 20) * random(0.3, 1);
    fill(255, 245, 225, a);
    circle(x, y, random(1, 2.8));
  }
}

// ---------- paysage ----------
function paintHills() {
  noStroke();
  fill(70, 52, 82);
  beginShape();
  vertex(0, H);
  for (let x = 0; x <= W; x += 6) vertex(x, 1410 + noise(x * 0.0018) * 90 - 30);
  vertex(W, H);
  endShape(CLOSE);

  fill(34, 28, 44);
  beginShape();
  vertex(0, H);
  for (let x = 0; x <= W; x += 6) vertex(x, 1460 + noise(x * 0.003 + 100) * 70 - 20);
  vertex(W, H);
  endShape(CLOSE);
}

function blade(x, y, h, lean, w, c) {
  stroke(c[0], c[1], c[2], c[3]);
  strokeWeight(w);
  noFill();
  beginShape();
  vertex(x, y);
  quadraticVertex(x + lean * h * 0.25, y - h * 0.6, x + lean * h, y - h);
  endShape();
}

function paintMeadow() {
  strokeWeight(1);
  for (let y = 1440; y < H; y++) {
    stroke(6, 8, 12, map(y, 1440, H, 0, 210));
    line(0, y, W, y);
  }
  const bl = [];
  for (let i = 0; i < 9000; i++) bl.push([random(-40, W + 40), random(1470, H + 20)]);
  bl.sort((a, b) => a[1] - b[1]);
  for (const [x, y] of bl) {
    const d = map(y, 1470, H, 0, 1, true);
    const h = lerp(14, 150, d) * random(0.6, 1.3);
    const lean = (noise(x * 0.004, y * 0.004) - 0.4) * 1.1 + 0.15;
    let c = [
      lerp(52, 10, d) + random(-6, 6),
      lerp(44, 16, d) + random(-6, 6),
      lerp(60, 18, d) + random(-6, 6),
      200
    ];
    if (random() < 0.07) c = [lerp(170, 70, d), lerp(110, 50, d), lerp(90, 40, d), 160];
    blade(x, y, h, lean, lerp(1, 3.2, d), c);
  }
}

// ---------- pissenlit ----------
function stemPt(t) {
  return [
    bezierPoint(560, 535, 830, HX, t),
    bezierPoint(2070, 1700, 1420, HY + 14, t)
  ];
}

function paintStem() {
  noStroke();
  for (let i = 0; i <= 400; i++) {
    const t = i / 400;
    const [x, y] = stemPt(t);
    fill(30, 38, 34);
    circle(x, y, lerp(15, 7, t));
  }
  for (let i = 0; i <= 400; i++) {
    const t = i / 400;
    const [x, y] = stemPt(t);
    const w = lerp(15, 7, t);
    fill(200, 130, 95, map(t, 0, 1, 30, 120));
    circle(x + w * 0.28, y, w * 0.3);
  }
}

function drawSeed(x, y, len, ang, al, sc) {
  const dx = cos(ang), dy = sin(ang);
  const ax = x + dx * len * 0.2, ay = y + dy * len * 0.2;
  const tx = x + dx * len, ty = y + dy * len;
  stroke(115, 88, 64, al);
  strokeWeight(2.4 * sc);
  line(x, y, ax, ay);
  stroke(235, 228, 212, al * 0.75);
  strokeWeight(0.9 * sc);
  line(ax, ay, tx, ty);
  const n = 20, pr = len * 0.42;
  for (let k = 0; k < n; k++) {
    const a = ang + map(k, 0, n - 1, -1.45, 1.45) + random(-0.06, 0.06);
    const r = pr * random(0.85, 1.05);
    const ex = tx + cos(a) * r, ey = ty + sin(a) * r;
    stroke(248, 242, 230, al * 0.5);
    strokeWeight(0.7 * sc);
    line(tx, ty, ex, ey);
    noStroke();
    fill(255, 250, 240, al * 0.6);
    circle(ex, ey, 1.6 * sc);
  }
}

function paintHead() {
  const seeds = [];
  for (let i = 0; i < 220; i++) {
    const a = random(PI * 0.28, PI * 1.52);
    const p = 1 - pow(abs(a - PI * 0.9) / (PI * 0.62), 2);
    if (random() > p * 0.9 + 0.08) continue;
    seeds.push([a, random(0.45, 1), random()]);
  }
  seeds.sort((a, b) => a[2] - b[2]);
  for (const [a, f, z] of seeds) {
    const bx = HX + cos(a) * 13, by = HY + sin(a) * 13;
    drawSeed(bx, by, 95 * f, a + random(-0.05, 0.05), lerp(120, 255, z), 1);
  }
  noStroke();
  fill(95, 72, 55);
  ellipse(HX, HY, 30, 28);
  fill(150, 115, 85);
  ellipse(HX + 3, HY - 3, 18, 16);
  fill(60, 45, 35);
  for (let i = 0; i < 22; i++) {
    const a = random(-PI * 0.7, PI * 0.2), r = random(3, 12);
    circle(HX + cos(a) * r, HY + sin(a) * r, 2);
  }
}

// ---------- envol ----------
function paintDrift() {
  const N = 170;
  for (let i = 0; i < N; i++) {
    const t = constrain(i / (N - 1) + random(-0.02, 0.02), 0, 1);
    let x = HX + 50 + t * 560 + sin(t * PI * 1.3) * 140;
    let y = HY - 40 - t * 1060;
    x += randomGaussian() * (12 + t * 360);
    y += randomGaussian() * (8 + t * 150);
    x += (noise(i * 0.3, 1) - 0.5) * 80 * t;
    x = constrain(x, 50, W - 50);
    y = constrain(y, 40, H);
    const s = lerp(0.85, 0.28, t);
    const sa = 255 * (1 - smooth01(0.45, 0.85, t));
    const ga = smooth01(0.35, 0.9, t);
    const ang = -HALF_PI + (noise(i * 0.5, 7) - 0.5) * 0.9 + 0.2;
    if (sa > 3) drawSeed(x, y, 70 * s, ang, sa, max(s, 0.55));
    if (ga > 0.01) {
      const cx = x + cos(ang) * 70 * s, cy = y + sin(ang) * 70 * s;
      paintGlow(cx, cy, 26 * ga + 6, [255, 238, 205], 0.5 * ga);
      noStroke();
      fill(255, 250, 235, 255 * ga);
      circle(cx, cy, lerp(1.5, 4, ga) * random(0.7, 1.2));
    }
  }
}

function paintLanded() {
  const pts = [[1140, 1790, -0.3], [1310, 1870, 0.25], [990, 1930, -0.1], [1430, 1760, 0.4], [880, 1840, 0.15]];
  for (const [x, y, t] of pts) {
    paintGlow(x, y - 30, 40, [255, 220, 180], 0.08);
    drawSeed(x, y, 38, -HALF_PI + t, 150, 0.6);
  }
}

function paintFrontGrass() {
  for (let i = 0; i < 1300; i++) {
    const x = random(-40, W + 40), y = random(1840, H + 30);
    const h = random(60, 190);
    const lean = (noise(x * 0.004, y * 0.004 + 30) - 0.4) * 1.1 + 0.15;
    blade(x, y, h, lean, random(2, 4), [random(6, 14), random(10, 18), random(10, 16), 230]);
  }
}

// ---------- finitions ----------
function paintVignette() {
  const g = drawingContext.createRadialGradient(800, 1000, 500, 800, 1000, 1400);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.55)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, W, H);
}

function paintGrain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    const g = random(-7, 7);
    pixels[i] += g;
    pixels[i + 1] += g;
    pixels[i + 2] += g;
  }
  updatePixels();
}

// Les pas qui se remplissent de ciel
const W = 1600, H = 2000;
const HY = 780;   // horizon
const SX = 800;   // soleil couché / point de fuite

const SKY = [
  [0.00, [16, 18, 44]],
  [0.30, [40, 38, 86]],
  [0.58, [105, 72, 122]],
  [0.80, [200, 118, 118]],
  [1.00, [246, 176, 132]]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
}

function lerpArr(a, b, t) {
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function grad(st, t) {
  for (let i = 0; i < st.length - 1; i++) {
    if (t <= st[i + 1][0]) {
      const u = (t - st[i][0]) / (st[i + 1][0] - st[i][0]);
      return lerpArr(st[i][1], st[i + 1][1], u);
    }
  }
  return st[st.length - 1][1].slice();
}

function wl(x) {
  return 1000 + 12 * sin(x * 0.003 + 1) + 18 * (noise(x * 0.002, 50) - 0.5);
}

function skyCol(x, y) {
  const t = constrain(y / HY, 0, 1);
  let c = grad(SKY, t);
  const d = dist(x, y * 1.6, SX, HY * 1.6 + 60);
  const g = exp(-d / 420);
  return lerpArr(c, [255, 214, 168], g * 0.75);
}

function seaCol(x, y) {
  const my = HY - (y - HY) * 1.7;
  let c = skyCol(x, max(my, 0));
  const n = noise(x * 0.003, y * 0.06);
  c = [c[0] * 0.55 + 10, c[1] * 0.55 + 12, c[2] * 0.62 + 22];
  const dx = abs(x - SX) / (60 + (y - HY) * 0.9);
  const p = exp(-dx * dx) * (0.5 + 0.8 * n) * map(y, HY, 1000, 1, 0.4, true);
  c = lerpArr(c, [255, 205, 160], constrain(p, 0, 0.85));
  const s = (n - 0.5) * 40;
  return [c[0] + s, c[1] + s, c[2] + s];
}

function sandCol(x, y) {
  const w0 = wl(x);
  let w = constrain(map(y, w0, 1580, 1, 0), 0, 1);
  w = constrain(pow(w, 0.8) * (0.75 + 0.5 * noise(x * 0.004, y * 0.01)), 0, 1);
  const my = HY - (y - HY) * 0.7;
  let r = skyCol(x, max(my, 0));
  r = [r[0] * 0.82, r[1] * 0.8, r[2] * 0.85];
  const dry = lerpArr([118, 96, 100], [66, 52, 62], map(y, 1300, 2000, 0, 1, true));
  const n = (noise(x * 0.02, y * 0.05) - 0.5) * 18;
  const c = lerpArr(dry, r, w * 0.85);
  return [c[0] + n, c[1] + n, c[2] + n];
}

function baseColor(x, y) {
  if (y < HY) return skyCol(x, y);
  if (y < wl(x)) return seaCol(x, y);
  return sandCol(x, y);
}

function foot(side, Wd, L) {
  ellipse(0, L * 0.30, Wd * 0.62, L * 0.36);                 // talon
  ellipse(side * Wd * 0.12, L * 0.02, Wd * 0.48, L * 0.40);   // voûte (côté extérieur)
  ellipse(-side * Wd * 0.03, -L * 0.20, Wd * 0.86, L * 0.34); // plante
  for (let k = 0; k < 5; k++) {                               // orteils
    const tx = side * (-0.30 + k * 0.16) * Wd;
    const ty = -L * (0.43 - k * 0.035);
    const s = k === 0 ? 0.26 : 0.17 - k * 0.015;
    ellipse(tx, ty, Wd * s, L * s * 0.75);
  }
}

function draw() {
  // --- fond peint au pixel ---
  loadPixels();
  for (let y = 0; y < H; y += 2) {
    for (let x = 0; x < W; x += 2) {
      const c = baseColor(x, y);
      for (let dy = 0; dy < 2; dy++) {
        for (let dx = 0; dx < 2; dx++) {
          const idx = 4 * ((y + dy) * W + (x + dx));
          pixels[idx] = c[0];
          pixels[idx + 1] = c[1];
          pixels[idx + 2] = c[2];
          pixels[idx + 3] = 255;
        }
      }
    }
  }
  updatePixels();

  // --- touches de pinceau ---
  for (let i = 0; i < 90000; i++) {
    const x = random(W), y = random(H);
    const c = baseColor(x, y);
    const j = random(-10, 10);
    let len, ang, wgt;
    if (y < HY) {
      len = random(14, 48);
      ang = random(-0.06, 0.06) + (noise(x * 0.001, y * 0.003) - 0.5) * 0.3;
      wgt = random(2, 6);
    } else if (y < wl(x)) {
      len = random(20, 70); ang = random(-0.02, 0.02); wgt = random(1, 3);
    } else {
      len = random(6, 22); ang = random(-0.15, 0.15); wgt = random(1.5, 4);
    }
    stroke(c[0] + j, c[1] + j, c[2] + j * 1.2, random(50, 110));
    strokeWeight(wgt);
    const cx = cos(ang) * len / 2, cy = sin(ang) * len / 2;
    line(x - cx, y - cy, x + cx, y + cy);
  }

  // --- étoiles ---
  noStroke();
  for (let i = 0; i < 40; i++) {
    const x = random(W), y = random(HY * 0.45);
    fill(230, 225, 255, random(70, 190));
    circle(x, y, random(1.2, 3));
  }
  // l'étoile du soir
  for (let r = 40; r > 0; r -= 2) {
    fill(255, 240, 225, map(r, 40, 0, 0, 30));
    circle(1180, 420, r);
  }
  fill(255, 248, 238);
  circle(1180, 420, 5);

  // --- ligne d'horizon lumineuse ---
  for (let k = 0; k < 6; k++) {
    stroke(255, 205, 165, 40 - k * 6);
    strokeWeight(1 + k * 2);
    line(0, HY, W, HY);
  }

  // --- empreintes ---
  const pathX = (zz) => 60 + 170 * sin(zz * 0.75) - 170 * sin(0.75);
  const prints = [];
  let i = 0;
  for (let z = 1.08; z < 8; z += 0.19, i++) {
    const side = i % 2 === 0 ? -1 : 1;
    const x = SX + (pathX(z) + side * 34) / z;
    const y = HY + 1180 / z;
    if (y < wl(x) + 14) break;
    const z2 = z + 0.02;
    const xa = SX + pathX(z) / z, ya = HY + 1180 / z;
    const xb = SX + pathX(z2) / z2, yb = HY + 1180 / z2;
    const a = atan2(xb - xa, -(yb - ya));
    prints.push({ x, y, z, side, a });
  }

  const n = prints.length;
  for (let k = 0; k < n; k++) {
    const p = prints[k];
    const f = n > 1 ? k / (n - 1) : 1;
    const Wd = 58 / p.z, L = 145 / pow(p.z, 1.55);
    const base = sandCol(p.x, p.y);
    const refl = skyCol(p.x, max(HY - (p.y - HY) * 0.7, 0));
    const fade = f > 0.7 ? map(f, 0.7, 1, 1, 0.45) : 1;

    push();
    translate(p.x, p.y);
    rotate(p.a);
    noStroke();

    // bord de sable relevé
    fill(base[0] + 28, base[1] + 24, base[2] + 22, 120 * fade);
    foot(p.side, Wd * 1.14, L * 1.14);

    // ombre intérieure
    fill(base[0] * 0.5, base[1] * 0.45, base[2] * 0.55, 200 * fade);
    foot(p.side, Wd, L);

    // remplissage : sable humide -> ciel
    const damp = [base[0] * 0.72, base[1] * 0.68, base[2] * 0.74];
    const sky = [
      min(255, refl[0] * 1.12 + 18),
      min(255, refl[1] * 1.12 + 16),
      min(255, refl[2] * 1.10 + 14)
    ];
    const c = lerpArr(damp, sky, pow(f, 1.2));
    if (f > 0.3) {
      drawingContext.shadowBlur = (30 / p.z + 10) * f;
      drawingContext.shadowColor =
        'rgba(' + (sky[0] | 0) + ',' + (sky[1] | 0) + ',' + (sky[2] | 0) + ',' + (0.8 * f) + ')';
    }
    fill(c[0], c[1], c[2], 235 * fade);
    push();
    translate(0, L * 0.05);
    foot(p.side, Wd * 0.9, L * 0.88);
    pop();
    drawingContext.shadowBlur = 0;

    // reflets
    if (f > 0.15) {
      fill(255, 235, 210, 90 * f * fade);
      ellipse(-p.side * Wd * 0.03, -L * 0.15, Wd * 0.4, L * 0.1);
      ellipse(0, L * 0.3, Wd * 0.3, L * 0.08);
    }
    pop();
  }

  // --- écume et crêtes ---
  noFill();
  for (let k = 0; k < 4; k++) {
    const off = k === 0 ? 0 : -(k * 28 + random(-5, 5));
    for (let pass = 0; pass < 3; pass++) {
      stroke(245, 225, 220, (k === 0 ? 140 : 70 - k * 12) / (pass + 1));
      strokeWeight((k === 0 ? 4 : 2) * (pass * 1.8 + 1));
      let drawing = false;
      for (let x = -10; x <= W + 10; x += 8) {
        const y = wl(x) + off + (noise(x * 0.01, k * 10) - 0.5) * 6 * (k + 1) * 0.6;
        const on = k === 0 ? true : noise(x * 0.004, k * 7) > 0.45;
        if (on && !drawing) { beginShape(); drawing = true; }
        if (on) vertex(x, y);
        if (!on && drawing) { endShape(); drawing = false; }
      }
      if (drawing) endShape();
    }
  }

  // --- grain ---
  strokeWeight(1);
  for (let g = 0; g < 120000; g++) {
    stroke(random() < 0.5 ? 0 : 255, 12);
    point(random(W), random(H));
  }

  // --- vignette ---
  noFill();
  for (let v = 0; v < 40; v++) {
    stroke(12, 8, 22, 6);
    strokeWeight(v * 14);
    rect(0, 0, W, H);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);

  // 1. Fond abyssal et texturé
  background(230, 35, 6);
  drawBackgroundNebula();

  // 2. Le grand halo d'au-delà (L'éther)
  drawHalo(800, 650, 1100);

  // 3. Les courants d'ascension (L'âme qui se dissout)
  drawSoulStreams();

  // 4. L'horizon d'eau calme (Le Styx / Le miroir)
  drawWaterHorizon(1550);

  // 5. Le Monolithe / Cénotaphe qui s'effrite
  drawCrumblingMonolith(800, 1050, 280, 600);

  // 6. Les braises de mémoire (Particules d'or et de cendre)
  drawEmbersAndAsh();

  // 7. Voiles de brume au premier plan
  drawForegroundMist();

  // 8. Grain de toile final et vignettage
  applyCanvasTexture();
}

function drawBackgroundNebula() {
  noStroke();
  for (let i = 0; i < 4000; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);

    // Transition de couleur : bleu nuit en haut, terre d'ombre en bas
    let hue = lerp(220, 260, y / height) + random(-10, 10);
    let sat = lerp(40, 20, n);
    let bri = lerp(5, 18, n * (1 - y / height * 0.5));

    fill(hue, sat, bri, 0.08);
    let r = random(50, 300) * n;
    ellipse(x, y, r, r * random(0.5, 1.5));
  }
}

function drawHalo(cx, cy, maxR) {
  noStroke();
  // Cercles concentriques organiques
  for (let r = maxR; r > 0; r -= 4) {
    let progress = 1 - (r / maxR);
    let hue = lerp(225, 42, pow(progress, 1.8));
    let sat = lerp(35, 15, pow(progress, 2));
    let bri = lerp(10, 95, pow(progress, 2.5));

    fill(hue, sat, bri, 0.03);

    beginShape();
    for (let a = 0; a < TWO_PI; a += 0.1) {
      let n = noise(cos(a) * 1.5 + r * 0.005, sin(a) * 1.5 + r * 0.005);
      let rad = r + map(n, 0, 1, -60, 60) * (1 - progress * 0.5);
      let x = cx + cos(a) * rad;
      let y = cy + sin(a) * rad * 1.15; // Légèrement ovale verticalement
      curveVertex(x, y);
    }
    endShape(CLOSE);
  }

  // Rayons subtils d'obscurité et de lumière
  for (let i = 0; i < 600; i++) {
    let angle = random(TWO_PI);
    let len = random(200, maxR * 1.2);
    strokeWeight(random(1, 8));
    if (random() > 0.3) {
      stroke(40, 20, 90, random(0.005, 0.02));
    } else {
      stroke(230, 40, 8, random(0.01, 0.03));
    }
    line(cx, cy, cx + cos(angle) * len, cy + sin(angle) * len);
  }
}

function drawSoulStreams() {
  // Des milliers de fils qui montent du monolithe vers le halo
  let numStreams = 3500;

  for (let i = 0; i < numStreams; i++) {
    // Origine concentrée autour du monolithe et du centre
    let startX = randomGaussian(800, 160);
    let startY = random(650, 1600);

    let x = startX;
    let y = startY;

    let steps = random(50, 250);
    let isGold = random() < 0.18;
    let isDark = random() < 0.25;

    noFill();
    beginShape();
    for (let s = 0; s < steps; s++) {
      let progress = s / steps;

      // Champ de force qui attire vers le centre du halo (800, 500) puis disperse en haut
      let angleToCenter = atan2(400 - y, 800 - x);
      let n = noise(x * 0.003, y * 0.003, i * 0.001);
      let flowAngle = -HALF_PI + map(n, 0, 1, -PI * 0.45, PI * 0.45);

      // Mélange entre montée naturelle et attraction vers la lumière
      let angle = lerp(flowAngle, angleToCenter, 0.25 * (1 - progress));

      x += cos(angle) * 3.5;
      y += sin(angle) * 3.5;

      let alpha = sin(progress * PI) * 0.25;

      if (isGold) {
        stroke(random(35, 48), random(40, 75), random(80, 100), alpha * 1.4);
        strokeWeight(lerp(2.5, 0.3, progress));
      } else if (isDark) {
        stroke(230, 40, 10, alpha * 1.2);
        strokeWeight(lerp(4, 0.5, progress));
      } else {
        // Couleur os / ivoire
        stroke(40, random(10, 25), random(75, 95), alpha * 0.8);
        strokeWeight(lerp(1.8, 0.2, progress));
      }

      vertex(x, y);

      // Arrêter si on sort trop loin
      if (y < 50) break;
    }
    endShape();
  }
}

function drawCrumblingMonolith(cx, topY, w, h) {
  let bottomY = topY + h;

  // Construction du monolithe couche par couche (style peinture au couteau)
  for (let y = topY; y < bottomY; y += 1.5) {
    let progressY = (y - topY) / h; // 0 en haut (dissous), 1 en bas (dense)

    // Le haut du monolithe est très érodé, le bas est plus stable
    let erosion = pow(1 - progressY, 1.6);

    let leftEdge = cx - (w * 0.5) * lerp(0.4, 1.1, progressY);
    let rightEdge = cx + (w * 0.5) * lerp(0.4, 1.1, progressY);

    // Perturbation des bords par le bruit
    leftEdge += map(noise(y * 0.01, 10), 0, 1, -60, 60) * (erosion + 0.2);
    rightEdge += map(noise(y * 0.01, 20), 0, 1, -60, 60) * (erosion + 0.2);

    // Nombre de coups de pinceau sur cette ligne horizontale
    let strokesCount = floor(map(progressY, 0, 1, 15, 70));

    for (let i = 0; i < strokesCount; i++) {
      // Sauter des morceaux en haut pour créer l'effet d'effritement
      if (random() < erosion * 0.65) continue;

      let t = random();
      let x = lerp(leftEdge, rightEdge, t);

      // Éclairage : lumière venant du haut et légèrement de la gauche
      let light = (1 - t) * 0.6 + (1 - progressY) * 0.4;
      light += map(noise(x * 0.03, y * 0.03), 0, 1, -0.25, 0.25);
      light = constrain(light, 0, 1);

      let hue = lerp(230, 38, pow(light, 0.8));
      let sat = lerp(35, 18, light);
      let bri = lerp(8, 88, pow(light, 1.4));

      // Assombrir considérablement la base qui plonge dans l'eau
      if (progressY > 0.75) {
        let sink = map(progressY, 0.75, 1, 1, 0.15);
        bri *= sink;
      }

      fill(hue, sat, bri, random(0.3, 0.85));
      noStroke();

      // Coup de couteau vertical / bloc de matière
      let bw = random(4, 22);
      let bh = random(8, 45) * (1 + erosion * 0.8);

      push();
      translate(x, y);
      rotate(random(-0.08, 0.08) * erosion);
      rectMode(CENTER);
      rect(0, 0, bw, bh, 2);
      pop();
    }
  }

  // Fissures d'or interne (Kintsugi de l'âme qui s'échappe du corps)
  for (let i = 0; i < 90; i++) {
    let fx = cx + random(-w * 0.35, w * 0.35);
    let fy = random(topY, topY + h * 0.65);

    stroke(42, 70, 95, random(0.2, 0.6));
    strokeWeight(random(0.8, 2.5));
    noFill();

    beginShape();
    for (let s = 0; s < 25; s++) {
      vertex(fx, fy);
      let n = noise(fx * 0.02, fy * 0.02, i);
      fx += map(n, 0, 1, -8, 8);
      fy -= random(3, 12); // Monte vers la lumière
    }
    endShape();
  }
}

function drawWaterHorizon(horizonY) {
  // L'eau sombre au bas de la toile
  for (let y = horizonY; y < height; y += 2) {
    let progress = (y - horizonY) / (height - horizonY);

    for (let i = 0; i < 80; i++) {
      let x = random(width);
      let distFromCenter = abs(x - 800) / 800;

      // Reflet central de la lumière du halo et du monolithe
      let reflection = (1 - distFromCenter) * (1 - progress * 0.7);
      reflection *= noise(x * 0.005, y * 0.05);

      let hue = lerp(230, 40, reflection * 0.8);
      let sat = lerp(40, 25, reflection);
      let bri = lerp(4, 55, pow(reflection, 1.5));

      stroke(hue, sat, bri, random(0.1, 0.4));
      strokeWeight(random(1, 3.5));

      let lineLen = random(30, 250) * (1 - distFromCenter * 0.5);
      line(x - lineLen / 2, y, x + lineLen / 2, y);
    }
  }

  // Ligne d'horizon subtile et brumeuse
  for (let i = 0; i < 300; i++) {
    let x = random(width);
    let y = horizonY + randomGaussian(0, 15);
    let w = random(50, 300);
    let h = random(5, 25);
    noStroke();
    fill(40, 15, 70, 0.015);
    ellipse(x, y, w, h);
  }
}

function drawEmbersAndAsh() {
  // Particules qui s'élèvent (fragments de mémoire, poussière d'os, étincelles)
  for (let i = 0; i < 2200; i++) {
    // Concentration plus forte au centre et autour du sommet du monolithe
    let x = randomGaussian(800, 320);
    let y = random(80, 1650);

    let distToMonumentTop = dist(x, y, 800, 950);
    if (random() > map(distToMonumentTop, 0, 900, 0.95, 0.15)) continue;

    let size = random(1.5, 9);
    let isDarkAsh = random() < 0.45;

    noStroke();
    push();
    translate(x, y);
    rotate(random(TWO_PI));

    if (isDarkAsh) {
      // Cendre sombre qui se découpe sur la lumière
      fill(230, 35, random(8, 22), random(0.3, 0.8));
      beginShape();
      for (let a = 0; a < TWO_PI; a += PI / 2) {
        let r = size * random(0.4, 1.2);
        vertex(cos(a) * r, sin(a) * r);
      }
      endShape(CLOSE);
    } else {
      // Poussière d'or et d'ivoire
      let glow = random() < 0.25;
      if (glow) {
        fill(42, 80, 100, 0.15);
        ellipse(0, 0, size * 4, size * 4);
      }
      fill(random(35, 48), random(20, 70), random(85, 100), random(0.4, 0.9));
      ellipse(0, 0, size, size * random(0.5, 1.5));
    }
    pop();
  }
}

function drawForegroundMist() {
  noStroke();
  for (let i = 0; i < 250; i++) {
    let x = random(width);
    let y = random(1200, 1800);
    let w = random(200, 700);
    let h = random(40, 150);

    let n = noise(x * 0.002, y * 0.002);
    let hue = lerp(230, 40, n * 0.5);
    let bri = lerp(8, 35, n);

    fill(hue, 25, bri, 0.025);
    ellipse(x, y, w, h);
  }
}

function applyCanvasTexture() {
  // 1. Trame de lin fine
  strokeWeight(1);
  for (let x = 0; x < width; x += 3) {
    stroke(40, 10, 90, 0.012);
    line(x, 0, x, height);
  }
  for (let y = 0; y < height; y += 3) {
    stroke(230, 30, 5, 0.018);
    line(0, y, width, y);
  }

  // 2. Manipulation directe des pixels pour le grain pictural et le vignettage
  loadPixels();
  let cx = width / 2;
  let cy = height * 0.42;
  let maxDist = dist(0, 0, cx, height);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Grain organique
      let grain = random(-10, 10);

      // Vignettage doux pour enfermer le regard
      let d = dist(x, y, cx, cy);
      let vignette = map(pow(d / maxDist, 1.6), 0, 1, 1.05, 0.35);
      vignette = constrain(vignette, 0, 1);

      pixels[idx]     = constrain(pixels[idx] * vignette + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vignette + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vignette + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  colorMode(HSB, 360, 100, 100, 1.0);
  background(225, 35, 6);

  // 1. Fond atmosphérique : strates d'éther et d'ombre
  for (let i = 0; i < 3500; i++) {
    let x = random(-200, width + 200);
    let y = random(-200, height + 200);
    let n = noise(x * 0.0012, y * 0.0012);
    let h = map(y, 0, height, 42, 235) + map(n, 0, 1, -18, 18);
    let s = map(y, 0, height, 25, 45) * n;
    let b = map(pow(1 - y / height, 1.6), 0, 1, 5, 82) * (0.4 + 0.6 * n);

    let r = random(120, 550);
    noStroke();
    fill(h, s, b, 0.014);

    push();
    translate(x, y);
    rotate(n * TWO_PI);
    ellipse(0, 0, r, r * random(0.3, 0.8));
    pop();
  }

  // 2. La source de l'au-delà : vide lumineux au sommet
  let lightX = width * 0.5;
  let lightY = height * 0.22;
  for (let r = 1400; r > 0; r -= 5) {
    let inter = map(r, 0, 1400, 1, 0);
    let h = map(inter, 0, 1, 215, 45);
    let s = map(pow(inter, 0.5), 0, 1, 35, 8);
    let b = map(pow(inter, 2.2), 0, 1, 10, 98);
    fill(h, s, b, 0.025);
    let wobble = noise(r * 0.01) * 60;
    ellipse(lightX + wobble - 30, lightY, r * 1.15, r * 1.4);
  }

  // 3. Le Styx : les eaux silencieuses au bas de la toile
  let horizon = height * 0.78;
  for (let y = horizon; y < height; y += 1.5) {
    let progress = map(y, horizon, height, 0, 1);
    let b = map(pow(progress, 0.6), 0, 1, 16, 3);
    let s = map(progress, 0, 1, 30, 55);

    stroke(225, s, b, 0.45);
    strokeWeight(random(1, 5));
    let xOff = noise(y * 0.04) * 150;
    line(0, y, width, y + random(-3, 3));

    // Reflets dorés mourants sur l'eau
    if (random() < 0.45) {
      let refW = map(progress, 0, 1, 120, 650) * random(0.4, 1.3);
      let refX = lightX + random(-refW * 0.3, refW * 0.3);
      stroke(42, 25, map(progress, 0, 1, 55, 8), random(0.05, 0.18));
      strokeWeight(random(1, 3.5));
      line(refX - refW / 2 + (xOff - 75) * 0.4, y, refX + refW / 2 + (xOff - 75) * 0.4, y);
    }
  }

  // Brume d'horizon
  for (let i = 0; i < 500; i++) {
    let x = random(width);
    let y = horizon + random(-50, 50);
    fill(210, 20, 35, 0.015);
    noStroke();
    ellipse(x, y, random(200, 700), random(10, 45));
  }

  // 4. Le Monolithe / Le Linceul : la forme corporelle qui s'efface
  let baseW = 360;
  let topW = 90;
  let monoTop = height * 0.38;
  let monoBot = height * 0.86;

  for (let y = monoTop; y < monoBot; y += 0.8) {
    let py = map(y, monoTop, monoBot, 0, 1);
    let w = map(pow(py, 0.75), 0, 1, topW, baseW);
    let centerX = width * 0.5 + (noise(y * 0.004) - 0.5) * 70;

    let density = map(py, 0, 0.35, 0.1, 1.0, true);
    let numPoints = floor(w * 0.7 * density);

    for (let i = 0; i < numPoints; i++) {
      let normX = randomGaussian(0, 0.38);
      if (abs(normX) > 1.2) continue;

      let x = centerX + normX * (w / 2);

      // Érosion des bords supérieurs
      if (py < 0.55 && random() > py * 1.7 + 0.1) {
        x += random(-1, 1) * pow(1 - py, 2) * 280;
      }

      let n = noise(x * 0.015, y * 0.015);
      let h = 230 + n * 25;
      let s = map(py, 0, 1, 20, 45);
      let b = map(py, 0, 1, 18, 4) * (0.4 + 0.6 * n);

      // Lumière rasante (rim light) sur les flancs du monolithe
      if (abs(normX) > 0.55 && py < 0.75) {
        let rim = map(abs(normX), 0.55, 1.1, 0, 1, true);
        h = lerp(h, 42, rim);
        s = lerp(s, 30, rim);
        b = lerp(b, 75 * (1 - py * 0.8), rim);
      }

      noStroke();
      fill(h, s, b, random(0.15, 0.55));
      ellipse(x, y + random(-4, 4), random(2, 9), random(4, 18));
    }
  }

  // Ombre engloutie du monolithe dans l'eau
  for (let y = monoBot; y < height; y += 2) {
    let py = map(y, monoBot, height, 0, 1);
    let w = baseW * (1 + py * 0.6);
    stroke(235, 50, 3, map(py, 0, 1, 0.5, 0.05));
    strokeWeight(3);
    let cx = width * 0.5 + (noise(y * 0.025) - 0.5) * 45;
    line(cx - w / 2, y, cx + w / 2, y);
  }

  // 5. La Transmigration : les fils de l'âme qui se défont et montent
  let numThreads = 1400;
  for (let i = 0; i < numThreads; i++) {
    let startY = random(monoTop - 40, monoBot - 120);
    let py = map(startY, monoTop, monoBot, 0, 1, true);
    let w = map(pow(py, 0.75), 0, 1, topW, baseW);
    let startX = width * 0.5 + random(-w * 0.48, w * 0.48);

    let x = startX;
    let y = startY;
    let steps = random(80, 420);

    let isGold = random() < 0.28;
    let baseH = isGold ? random(32, 48) : random(205, 235);
    let baseS = isGold ? random(35, 65) : random(10, 28);

    for (let s = 0; s < steps; s++) {
      let stepProg = s / steps;

      // Champ de force : monte et s'ouvre en corolle vers la lumière
      let angle = -HALF_PI + (noise(x * 0.0025, y * 0.0025, i * 0.01) - 0.5) * PI * 1.15;
      let distFromCenter = x - width * 0.5;
      angle += map(distFromCenter, -width * 0.5, width * 0.5, -0.45, 0.45) * stepProg;

      x += cos(angle) * 2.6;
      y += sin(angle) * 2.6;

      let b = map(stepProg, 0, 1, 12, isGold ? 96 : 85);
      let alpha = sin(stepProg * PI) * (isGold ? 0.28 : 0.14);

      noStroke();
      fill(baseH, baseS * (1 - stepProg * 0.5), b, alpha);
      let rad = map(stepProg, 0, 1, 5.5, 0.8);
      circle(x, y, rad);
    }
  }

  // 6. Cendres et poussière d'or : les derniers fragments de mémoire
  for (let i = 0; i < 2400; i++) {
    let y = random(height * 0.04, monoBot);
    let py = map(y, height * 0.04, monoBot, 0, 1);
    let spread = map(pow(1 - py, 1.8), 0, 1, 140, 750);
    let x = width * 0.5 + randomGaussian(0, spread * 0.45);

    let distToLight = dist(x, y, lightX, lightY);
    if (random() > map(distToLight, 0, 950, 0.92, 0.05, true)) continue;

    let sz = random(1, 6.5) * map(distToLight, 0, 900, 1.4, 0.4, true);
    let isBright = random() < 0.35;

    noStroke();
    if (isBright) {
      fill(42, random(15, 50), random(85, 100), random(0.3, 0.85));
    } else {
      fill(225, 35, random(5, 22), random(0.25, 0.65));
    }

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    ellipse(0, 0, sz, sz * random(0.35, 1));
    pop();
  }

  // 7. Le Souffle : anneaux de résonance autour du cœur de la dissolution
  noFill();
  for (let i = 0; i < 65; i++) {
    let r = random(80, 920);
    let a1 = random(TWO_PI);
    let a2 = a1 + random(0.15, PI * 0.65);
    stroke(42, 18, 92, random(0.01, 0.045));
    strokeWeight(random(0.5, 2.2));
    arc(lightX, monoTop + 40, r, r * 1.15, a1, a2);
  }

  // 8. Patine du temps : grain de toile et craquelures subtiles
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-10, 10);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();

  // Fines griffures verticales (pluie immobile ou usure du temps)
  for (let i = 0; i < 450; i++) {
    let x = random(width);
    let y = random(height);
    let len = random(30, 260);
    stroke(40, 15, 75, random(0.01, 0.035));
    strokeWeight(0.6);
    line(x, y, x + random(-2, 2), y + len);
  }
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();

  // 1. Le Vide (Fond)
  drawBackground();

  // 2. La Brume de l'Au-delà (Nébuleuse)
  drawNebula();

  // 3. L'Horizon des Événements (L'eau calme)
  drawWater();

  // 4. Le Monolithe (La Forme qui se dissout)
  drawMonolithAndSoul();

  // 5. Le Souffle (Fils de lumière)
  drawSpiritThreads();

  // 6. Les Cendres d'Or (Étoiles et poussière)
  drawAshAndStars();

  // 7. Le Linceul du Temps (Texture de toile et grain)
  applyCanvasTexture();
}

function drawBackground() {
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let inter = map(y, 0, height, 0, 1);
    let c1 = color(5, 7, 12);     // Nuit profonde en haut
    let c2 = color(18, 22, 28);   // Bleu d'encre au milieu
    let c3 = color(8, 6, 10);     // Abîme en bas

    let c = inter < 0.7 ? lerpColor(c1, c2, inter / 0.7) : lerpColor(c2, c3, (inter - 0.7) / 0.3);
    fill(c);
    rect(0, y, width, 2);
  }
}

function drawNebula() {
  noStroke();
  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height * 0.8);
    let distToCenter = abs(x - width / 2);

    // Concentrer la lumière vers le centre vertical
    if (random(width / 2) > distToCenter * 0.8) {
      let n = noise(x * 0.002, y * 0.002);
      let r = map(n, 0, 1, 50, 350);

      // Couleurs de deuil et d'éternité : vieux rose éteint, or pâle, bleu de Prusse
      let colChoice = random();
      if (colChoice < 0.5) fill(25, 35, 45, 4);
      else if (colChoice < 0.8) fill(70, 55, 50, 3);
      else fill(180, 150, 110, 2);

      circle(x, y, r);
    }
  }

  // Lueur centrale (L'accueil)
  for (let r = 800; r > 0; r -= 10) {
    fill(220, 200, 170, map(r, 800, 0, 0, 3));
    circle(width / 2, height * 0.45, r);
  }
}

function drawWater() {
  let horizon = height * 0.78;

  // Base de l'eau
  fill(6, 8, 12, 200);
  rect(0, horizon, width, height - horizon);

  // Reflets et ondulations
  for (let y = horizon; y < height; y += 1.5) {
    let progress = map(y, horizon, height, 0, 1);
    let alpha = map(progress, 0, 1, 40, 5);
    let strokeW = map(progress, 0, 1, 0.5, 3);

    strokeWeight(strokeW);
    for (let x = 0; x < width; x += random(20, 80)) {
      let n = noise(x * 0.005, y * 0.05);
      let len = n * 120 * (1 - progress * 0.5);

      // Reflet central doré, bords sombres
      let distFromCenter = abs(x - width / 2);
      let spread = map(progress, 0, 1, 100, 500);

      if (distFromCenter < spread && random() < 0.4) {
        stroke(180, 150, 110, alpha * (1 - distFromCenter / spread));
      } else {
        stroke(20, 28, 35, alpha);
      }

      line(x - len / 2, y, x + len / 2, y);
    }
  }
}

function drawMonolithAndSoul() {
  let baseX = width / 2;
  let baseY = height * 0.78;
  let particles = [];

  // Création de la forme à la base (le corps / le tombeau)
  for (let y = baseY; y > height * 0.1; y -= 2) {
    let progress = map(y, baseY, height * 0.1, 0, 1); // 0 en bas, 1 en haut

    // La largeur rétrécit puis s'évase en fumée
    let w;
    if (progress < 0.35) {
      w = map(progress, 0, 0.35, 140, 30);
    } else {
      w = map(progress, 0.35, 1, 30, 600) * pow(progress, 1.5);
    }

    let density = map(progress, 0, 1, 120, 15);

    for (let i = 0; i < density; i++) {
      let angle = random(TWO_PI);
      let rad = randomGaussian(0, w * 0.4);
      let px = baseX + cos(angle) * rad;
      let py = y + sin(angle) * (rad * 0.2);

      // Déformation par le bruit de Perlin (le vent de l'au-delà)
      let n = noise(px * 0.004, py * 0.004);
      let wind = map(n, 0, 1, -1, 1.5) * pow(progress, 2) * 350;
      px += wind;
      py -= abs(wind) * 0.2;

      // Couleur : du noir d'obsidienne vers l'or pâle et le blanc d'ivoire
      let c;
      let alpha;
      if (progress < 0.25) {
        // Matière sombre et dense
        c = lerpColor(color(5, 5, 8), color(25, 22, 28), progress / 0.25);
        alpha = random(150, 250);
      } else if (progress < 0.45) {
        // Transition, embrasement
        c = lerpColor(color(25, 22, 28), color(190, 140, 90), (progress - 0.25) / 0.2);
        alpha = random(40, 120);
      } else {
        // Dissolution dans la lumière
        c = lerpColor(color(190, 140, 90), color(240, 235, 225), (progress - 0.45) / 0.55);
        alpha = map(progress, 0.45, 1, 60, 0) * random(0.5, 1.5);
      }

      noStroke();
      fill(red(c), green(c), blue(c), alpha);
      let sz = map(progress, 0, 1, random(4, 15), random(1, 6));

      // Dessiner des coups de pinceau verticaux pour la matière, ronds pour l'esprit
      if (progress < 0.3) {
        ellipse(px, py, sz * 0.6, sz * 2.5);
      } else {
        circle(px, py, sz);
      }
    }
  }

  // Ombre portée sur l'eau
  for (let y = baseY; y < baseY + 180; y += 2) {
    let p = map(y, baseY, baseY + 180, 0, 1);
    let w = map(p, 0, 1, 140, 20);
    stroke(4, 4, 6, map(p, 0, 1, 200, 0));
    strokeWeight(2);
    let n = (noise(y * 0.1) - 0.5) * 30 * p;
    line(baseX - w + n, y, baseX + w + n, y);
  }
}

function drawSpiritThreads() {
  // Des milliers de fils ultra-fins qui montent du monolithe
  let baseX = width / 2;
  let baseY = height * 0.75;

  noFill();
  for (let i = 0; i < 1200; i++) {
    let startP = random(0.1, 0.6);
    let y = map(startP, 0, 1, baseY, height * 0.1);
    let spread = map(startP, 0, 1, 60, 20);
    let x = baseX + randomGaussian(0, spread);

    // Décalage initial pour correspondre à la courbe du monolithe
    let nInit = noise(x * 0.004, y * 0.004);
    x += map(nInit, 0, 1, -1, 1.5) * pow(startP, 2) * 350;

    let steps = random(50, 250);
    let isGold = random() < 0.3;

    beginShape();
    for (let s = 0; s < steps; s++) {
      let stepP = s / steps;
      let alpha = sin(stepP * PI) * map(startP, 0.1, 0.6, 15, 45);

      if (isGold) {
        stroke(255, 235, 200, alpha);
        strokeWeight(0.8);
      } else if (startP < 0.3) {
        stroke(15, 15, 20, alpha * 3); // Fils d'ombre
        strokeWeight(1.2);
      } else {
        stroke(180, 150, 120, alpha);
        strokeWeight(0.5);
      }

      vertex(x, y);

      // Champ de force vers le haut et la droite
      let angle = map(noise(x * 0.003, y * 0.003, i * 0.001), 0, 1, -PI * 0.85, -PI * 0.15);
      x += cos(angle) * 3;
      y += sin(angle) * 3;
    }
    endShape();
  }
}

function drawAshAndStars() {
  // Poussière d'étoiles et braises mourantes
  let baseX = width / 2;

  for (let i = 0; i < 2500; i++) {
    let y = random(height * 0.05, height * 0.78);
    let p = map(y, height * 0.78, height * 0.05, 0, 1);

    // Suivre la trajectoire du souffle
    let wind = pow(p, 2) * 150;
    let x = baseX + wind + randomGaussian(0, map(p, 0, 1, 50, 450));

    if (x > 0 && x < width) {
      let sz = random(0.5, 3.5);
      noStroke();

      if (random() < 0.15 && p > 0.3) {
        // Lueurautour des grandes particules (les âmes)
        fill(255, 220, 170, 15);
        circle(x, y, sz * 6);
        fill(255, 240, 220, 40);
        circle(x, y, sz * 3);
      }

      // Cendres sombres en bas, poussière d'or en haut
      if (p < 0.3 && random() < 0.7) {
        fill(10, 10, 14, random(100, 220));
      } else {
        fill(255, 245, 230, random(50, 200) * (1 - p * 0.5));
      }
      circle(x, y, sz);
    }
  }

  // Quelques gouttes de lumière tombant dans l'eau (les larmes)
  for (let i = 0; i < 80; i++) {
    let x = baseX + randomGaussian(0, 120);
    let y = random(height * 0.65, height * 0.85);
    stroke(220, 190, 150, random(20, 80));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x, y + random(5, 25));
  }
}

function applyCanvasTexture() {
  // 1. Trame de la toile (lin ancien)
  strokeWeight(1);
  for (let x = 0; x < width; x += 3) {
    stroke(255, 250, 240, random(1, 4));
    line(x, 0, x, height);
  }
  for (let y = 0; y < height; y += 3) {
    stroke(0, 0, 0, random(2, 6));
    line(0, y, width, y);
  }

  // 2. Grain pictural et vignettage (le poids du silence)
  loadPixels();
  let cx = width / 2;
  let cy = height * 0.45;
  let maxDist = dist(0, 0, cx, height);

  for (let y = 0; y < height; y++) {
    for (let x = 0; x < width; x++) {
      let idx = (x + y * width) * 4;

      // Distance pour le vignettage
      let d = dist(x, y, cx, cy);
      let vig = map(pow(d / maxDist, 1.8), 0, 1, 1, 0.15);

      // Bruit organique
      let grain = random(-10, 10);

      pixels[idx]     = constrain(pixels[idx] * vig + grain, 0, 255);
      pixels[idx + 1] = constrain(pixels[idx + 1] * vig + grain, 0, 255);
      pixels[idx + 2] = constrain(pixels[idx + 2] * vig + grain, 0, 255);
    }
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
  colorMode(HSB, 360, 100, 100, 1.0);

  // 1. Fond : Du gouffre céleste au silence terrestre
  drawBackground();

  // 2. Nébuleuses de l'au-delà (L'accueil de l'éther)
  drawNebulae();

  // 3. L'Horizon / Le Voile (La frontière du Styx)
  drawVeil();

  // 4. L'Enveloppe Charnelle (La forme gisante qui se dissout)
  drawShroudAndVessel();

  // 5. L'Ascension (Les courants d'âme qui s'élèvent)
  drawSoulAscension();

  // 6. La Poussière (Les cendres qui retournent au sol)
  drawFallingAsh();

  // 7. Texture de toile et grain pictural
  applyCanvasTexture();
}

function drawBackground() {
  noStroke();
  for (let y = 0; y < height; y += 2) {
    let n = y / height;
    // De l'indigo abyssal en haut vers un brun sépia très sombre en bas
    let h = lerp(230, 25, pow(n, 1.5));
    let s = lerp(65, 40, n);
    let b = lerp(6, 3, pow(n, 0.8));

    // Légère lueur vers l'horizon (y = 1400)
    let distHorizon = abs(y - 1400);
    if (distHorizon < 500) {
      let glow = pow(1 - distHorizon / 500, 2);
      h = lerp(h, 200, glow * 0.4);
      s = lerp(s, 30, glow * 0.5);
      b += glow * 12;
    }

    fill(h, s, b);
    rect(0, y, width, 2);
  }
}

function drawNebulae() {
  blendMode(SCREEN);
  noStroke();

  // Grandes taches de lumière diffuse dans la partie supérieure
  for (let i = 0; i < 400; i++) {
    let x = random(width);
    let y = random(height * 0.75);

    // Concentration vers le centre vertical (le chemin de l'âme)
    let centerBias = 1 - abs(x - width / 2) / (width / 2);
    if (random() > pow(centerBias, 0.7)) continue;

    let n = noise(x * 0.002, y * 0.002);
    let r = map(n, 0, 1, 50, 350) * (1 - (y / height) * 0.5);

    let h = map(y, 0, height * 0.75, 220, 40) + random(-15, 15);
    let s = map(y, 0, height * 0.75, 40, 60);
    let b = map(n, 0, 1, 5, 20);
    let a = random(0.005, 0.02);

    fill(h, s, b, a);
    drawSoftPolygon(x, y, r, 12);
  }
  blendMode(BLEND);
}

function drawVeil() {
  // Brume horizontale séparant le monde d'en bas et l'éther
  for (let i = 0; i < 1500; i++) {
    let x = random(-100, width + 100);
    let y = random(1250, 1550);
    let n = noise(x * 0.003, y * 0.01);

    let w = random(100, 400) * n;
    let h_rect = random(2, 15);

    let distCenter = abs(y - 1400) / 150;
    let alpha = (1 - distCenter) * 0.04 * n;

    let hue = lerp(195, 35, (y - 1250) / 300);
    fill(hue, 25, 45, alpha);
    noStroke();
    ellipse(x, y, w, h_rect);
  }
}

function drawShroudAndVessel() {
  // La forme abstraite d'un corps allongé sur une barque ou un autel de pierre
  let cy = 1420;
  let startX = 350;
  let endX = 1250;

  // L'ombre portée en dessous (le vide sous le corps)
  noStroke();
  for (let i = 0; i < 800; i++) {
    let t = random();
    let x = lerp(startX - 50, endX + 50, t);
    let yOffset = sin(t * PI) * 80;
    let y = cy + random(0, 180) + yOffset * 0.3;
    let r = random(20, 100);
    fill(240, 50, 2, random(0.05, 0.15));
    ellipse(x, y, r * 2, r * 0.5);
  }

  // La structure du corps / linceul en coups de pinceau texturés
  for (let x = startX; x < endX; x += 1.5) {
    let t = map(x, startX, endX, 0, 1);

    // Profil abstrait d'un gisant (Tête à gauche, thorax, jambes qui s'effacent à droite)
    let head = exp(-pow((t - 0.12) * 14, 2)) * 55;
    let chest = exp(-pow((t - 0.36) * 6, 2)) * 85;
    let knees = exp(-pow((t - 0.68) * 7, 2)) * 45;
    let feet = exp(-pow((t - 0.88) * 18, 2)) * 30;
    let base = sin(t * PI) * 30;

    let profileH = head + chest + knees + feet + base;

    // Perturbation par le bruit (la matière qui se défait)
    let decay = noise(x * 0.015, t * 5);
    // Plus on va vers le centre (le coeur), plus la matière est dissoute
    let dissolution = exp(-pow((t - 0.38) * 4, 2)); 

    let topY = cy - profileH * (0.4 + 0.6 * decay);
    let bottomY = cy + base * 1.2 + noise(x * 0.02) * 40;

    // Dessiner les strates de matière (argile, cendre, os, linceul)
    let steps = floor((bottomY - topY) / 3);
    for (let s = 0; s < steps; s++) {
      let py = lerp(topY, bottomY, s / steps);
      let n = noise(x * 0.02, py * 0.02);

      // Si la matière est dissoute, on saute des points (créant des vides)
      if (random() < dissolution * 0.65 && s < steps * 0.6) continue;

      let shade = map(py, topY, bottomY, 1, 0); // Lumière venant d'en haut

      let h = lerp(30, 210, n); // Oscille entre ocre/terre et bleu grisâtre (froid de la mort)
      let sat = lerp(15, 45, 1 - shade);
      let bri = lerp(5, 75, pow(shade, 1.5) * n);

      // Touches d'or sur le rebord supérieur (la transmutation)
      if (s < 4 && random() < 0.4) {
        h = 42;
        sat = 70;
        bri = 90;
      }

      strokeWeight(random(1, 5));
      stroke(h, sat, bri, random(0.1, 0.5));

      // Coup de pinceau orienté selon les plis du linceul
      let angle = map(n, 0, 1, -PI/6, PI/6);
      if (s < steps * 0.3) angle -= dissolution * PI/3; // S'élève vers le haut au niveau du coeur

      let len = random(5, 25);
      line(x, py, x + cos(angle) * len, py + sin(angle) * len);
    }
  }
}

function drawSoulAscension() {
  // Des milliers de filaments et particules s'élevant du corps vers le cosmos
  let startX = 400;
  let endX = 1150;
  let baseY = 1400;

  // 1. Les grands courants éthérés (voiles d'âme)
  blendMode(ADD);
  noFill();
  for (let i = 0; i < 2200; i++) {
    // Concentration des départs autour du thorax/coeur et de la tête
    let r = random();
    let t;
    if (r < 0.6) {
      t = randomGaussian(0.36, 0.12); // Coeur
    } else if (r < 0.85) {
      t = randomGaussian(0.12, 0.06); // Tête
    } else {
      t = random(0.1, 0.9); // Reste du corps
    }
    t = constrain(t, 0.05, 0.95);

    let x = lerp(350, 1250, t);
    let y = baseY - random(10, 80) * sin(t * PI);

    // Couleur initiale du filament : Or pâle, cyan spirituel ou blanc pur
    let colorType = random();
    let h, s, b;
    if (colorType < 0.5) {
      h = random(35, 50); // Or
      s = random(40, 80);
      b = random(60, 100);
    } else if (colorType < 0.85) {
      h = random(185, 215); // Bleu céleste / Cyan doux
      s = random(30, 60);
      b = random(50, 90);
    } else {
      h = 40; // Blanc chaud
      s = 10;
      b = 100;
    }

    let maxSteps = random(100, 650);
    // Les courants du coeur montent le plus haut
    if (abs(t - 0.36) < 0.15) maxSteps *= 1.6; 

    beginShape();
    for (let step = 0; step < maxSteps; step++) {
      let progress = step / maxSteps;

      // Alpha qui apparaît, brille, puis s'évanouit dans le cosmos
      let alpha = sin(progress * PI) * map(maxSteps, 100, 1000, 0.01, 0.05);

      // Évolution de la couleur en montant (vers le bleu nuit / violet cosmique)
      let currentH = lerp(h, 220, pow(progress, 1.5));
      let currentS = lerp(s, 70, progress);

      stroke(currentH, currentS, b, alpha);
      strokeWeight(map(progress, 0, 1, random(1, 3.5), 0.3));

      vertex(x, y);

      // Champ de force (Flow field) pour le mouvement ascendant
      let n1 = noise(x * 0.0025, y * 0.0025, i * 0.0005);
      let n2 = noise(x * 0.008, y * 0.008, 100);

      // Angle globalement vers le haut (-PI/2), avec des volutes
      let angle = -PI / 2 + map(n1, 0, 1, -PI * 0.45, PI * 0.45);
      angle += map(n2, 0, 1, -0.3, 0.3);

      // Force centripète douce vers le haut (rassemblement de l'âme) puis dispersion tout en haut
      let centerPull = (width * 0.48 - x) * 0.0015 * sin(progress * PI);

      let speed = map(progress, 0, 1, 1.5, 3.5);
      x += cos(angle) * speed + centerPull;
      y += sin(angle) * speed;

      // Si ça redescend trop, on corrige vers le haut
      if (sin(angle) > 0.2) y -= 1.5; 
    }
    endShape();
  }

  // 2. Les braises d'or et poussières d'étoiles (Les souvenirs/l'essence pure)
  noStroke();
  for (let i = 0; i < 4500; i++) {
    let progress = pow(random(), 1.4); // Plus dense près du corps, plus rare en haut
    let y = map(progress, 0, 1, 1400, 50);

    // Largeur du cône d'ascension qui s'évase puis se resserre et s'évase à nouveau
    let spread = map(y, 1400, 50, 350, 600) * (0.6 + 0.4 * sin(y * 0.005));
    let centerX = width * 0.48 + sin(y * 0.003) * 60;
    let x = randomGaussian(centerX, spread * 0.45);

    // Vérifier la cohérence avec le bruit ambiant pour les regrouper en nuages
    let n = noise(x * 0.006, y * 0.006);
    if (random() > n * 1.4) continue;

    let sz = random(0.8, 4.5) * (1 - progress * 0.6);

    // Certaines particules brillent intensément (étoiles naissantes)
    let isStar = random() < 0.03;
    if (isStar) sz *= random(1.5, 3);

    let h = lerp(42, 195, pow(progress, 1.2) + random(-0.2, 0.2));
    let s = isStar ? 20 : random(40, 80);
    let b = 100;
    let a = random(0.1, 0.7) * (1 - progress * 0.5);

    if (isStar) {
      // Halo de l'étoile
      fill(h, 60, 100, a * 0.15);
      ellipse(x, y, sz * 6, sz * 6);
      fill(h, 40, 100, a * 0.4);
      ellipse(x, y, sz * 2.5, sz * 2.5);
    }

    fill(h, s, b, a);
    ellipse(x, y, sz, sz);
  }

  blendMode(BLEND);
}

function drawFallingAsh() {
  // Ce qui est lourd retourne à la terre (dissolution vers le bas)
  let startX = 350;
  let endX = 1250;
  let baseY = 1430;

  for (let i = 0; i < 3000; i++) {
    let t = random();
    let x = lerp(startX, endX, t);
    let maxFall = sin(t * PI) * 450 + random(50, 200);
    let y = baseY + random(0, maxFall);

    let progress = (y - baseY) / maxFall;
    if (progress > 1 || progress < 0) continue;

    let n = noise(x * 0.01, y * 0.005);
    x += map(n, 0, 1, -30, 30) * progress; // Dérive lente

    // Couleurs de cendre, de terre humide, d'ombre et quelques reflets d'ocre éteint
    let h = random(20, 40);
    let s = random(10, 40);
    let b = lerp(35, 3, pow(progress, 0.7)) * n;
    let a = (1 - progress) * random(0.1, 0.5);

    stroke(h, s, b, a);
    strokeWeight(random(0.5, 3));

    // Traînées verticales lourdes (la gravité)
    let len = random(5, 40) * (1 - progress * 0.5);
    line(x, y, x, y + len);
  }
}

function drawSoftPolygon(x, y, r, sides) {
  beginShape();
  for (let i = 0; i < sides; i++) {
    let angle = map(i, 0, sides, 0, TWO_PI);
    let nr = r * (0.6 + 0.6 * noise(x * 0.01 + cos(angle), y * 0.01 + sin(angle)));
    vertex(x + cos(angle) * nr, y + sin(angle) * nr);
  }
  endShape(CLOSE);
}

function applyCanvasTexture() {
  // 1. Fines craquelures et grain par-dessus l'oeuvre
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let pIndex = i / 4;
    let x = pIndex % width;
    let y = floor(pIndex / width);

    // Grain de toile subtil (trame orthogonale très fine + bruit aléatoire)
    let canvasWeave = (sin(x * 1.5) + sin(y * 1.5)) * 1.5;
    let grain = random(-7, 7) + canvasWeave;

    // Vignette douce pour fermer la composition (assombrir les bords)
    let dx = (x - width / 2) / (width / 2);
    let dy = (y - height / 2) / (height / 2);
    let distCenter = sqrt(dx * dx + dy * dy);
    let vignette = map(pow(distCenter, 2.2), 0, 1.8, 1, 0.35);
    vignette = constrain(vignette, 0, 1);

    pixels[i] = constrain((pixels[i] + grain) * vignette, 0, 255);
    pixels[i + 1] = constrain((pixels[i + 1] + grain) * vignette, 0, 255);
    pixels[i + 2] = constrain((pixels[i + 2] + grain) * vignette, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  pixelDensity(1);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  colorMode(HSB, 360, 100, 100, 1.0);
  background(225, 45, 5);

  // 1. Fond atmosphérique : strates du vide et du silence
  noStroke();
  for (let i = 0; i < 6500; i++) {
    let x = random(width);
    let y = random(height);
    let n = noise(x * 0.0012, y * 0.0012);
    let yNorm = y / height;

    // Transition chromatique du bleu abysse vers un sépia sombre et terreux
    let h = lerp(218, 25, pow(yNorm, 1.4)) + map(n, 0, 1, -12, 12);
    let s = lerp(35, 55, yNorm) * n;
    let b = lerp(22, 4, pow(yNorm, 0.75)) * (0.4 + 0.6 * n);

    // Clair-obscur : lueur dorée au coeur de la transmutation
    let dCenter = dist(x, y, width * 0.5, height * 0.45);
    if (dCenter < 750) {
      let glow = pow(map(dCenter, 0, 750, 1, 0), 2.2);
      h = lerp(h, 38, glow * 0.65);
      b += glow * 26;
      s = lerp(s, 45, glow * 0.5);
    }

    fill(h, s, b, random(0.015, 0.05));
    let w = random(80, 450);
    let hRect = random(30, 200);

    push();
    translate(x, y);
    rotate(map(n, 0, 1, -0.35, 0.35));
    ellipse(0, 0, w, hRect);
    pop();
  }

  // 2. Rayons de l'au-delà : géométrie sacrée et silencieuse
  strokeWeight(1);
  for (let i = 0; i < 450; i++) {
    let x = width * 0.5 + randomGaussian(0, 260);
    let y1 = random(0, height * 0.6);
    let y2 = y1 + random(150, 900);
    let alpha = map(abs(x - width * 0.5), 0, 650, 0.045, 0);
    if (alpha > 0) {
      stroke(40, 20, 95, alpha);
      line(x, y1, x, y2);
    }
  }

  let cx = width * 0.5;
  let cy = height * 0.64;
  let radius = 330;

  // 3. L'Ancre terrestre : les racines d'ombre sous le monolithe
  for (let i = 0; i < 4000; i++) {
    let angle = random(0, PI);
    let r = sqrt(random(0.1, 1)) * radius;
    let x = cx + cos(angle) * r * 0.92;
    let y = cy + sin(angle) * r * 1.1;

    let drop = pow(random(), 2.2) * (height - y);
    stroke(18, 65, 6, random(0.03, 0.12));
    strokeWeight(random(1, 5));
    line(x, y, x + random(-15, 15), y + drop);
  }

  // 4. Le Vaisseau (Le Corps / La Mémoire) : sphère fracturée au point de rupture
  noStroke();
  for (let i = 0; i < 38000; i++) {
    let angle = random(TWO_PI);
    let r = sqrt(random()) * radius;
    let x = cx + cos(angle) * r * 0.92;
    let y = cy + sin(angle) * r * 1.18;

    let n = noise(x * 0.007, y * 0.007);
    let nFine = noise(x * 0.03, y * 0.03);

    // Érosion de la partie supérieure : la mort qui dissout la forme
    let yRel = (y - (cy - radius * 1.18)) / (radius * 2.36);
    let erosionThreshold = map(yRel, 0, 0.75, 0.88, 0.12);

    if (n < erosionThreshold - 0.18) continue;

    let h = map(n, 0, 1, 8, 42);
    let s = map(yRel, 0, 1, 35, 78);
    let b = map(yRel, 0, 1, 75, 10) * map(nFine, 0, 1, 0.5, 1.3);

    // Bordure incandescente sur la faille de dissolution
    let isEdge = abs(n - (erosionThreshold - 0.18)) < 0.075;
    if (isEdge && yRel < 0.72) {
      h = 44;
      s = 25;
      b = 98;
    }

    fill(h, s, b, random(0.12, 0.45));
    let sz = random(2, 16);
    push();
    translate(x, y);
    rotate(n * TWO_PI);
    rect(0, 0, sz, sz * random(0.25, 0.8));
    pop();
  }

  // 5. La Transmutation : l'âme / le souffle s'élevant en courants d'or et de cendre
  noFill();
  for (let i = 0; i < 11000; i++) {
    // Naissance des flux principalement dans la zone de fracture supérieure
    let angle = random(PI * 0.85, TWO_PI * 1.075);
    let r = random(0.15, 1.0) * radius;
    let px = cx + cos(angle) * r * 0.88;
    let py = cy + sin(angle) * r * 1.05;

    let steps = int(random(35, 220));
    let isGold = random() < 0.25;
    let isAsh = !isGold && random() < 0.45;

    let hBase = isGold ? random(38, 48) : (isAsh ? random(205, 225) : random(15, 32));
    let sBase = isGold ? random(15, 45) : (isAsh ? random(8, 25) : random(45, 70));
    let bBase = isGold ? random(88, 100) : (isAsh ? random(45, 75) : random(25, 55));

    strokeWeight(random(0.4, 2.6));

    beginShape();
    for (let s = 0; s < steps; s++) {
      let progress = s / steps;
      let alpha = sin(progress * PI) * (isGold ? 0.28 : 0.11);

      stroke(hBase, sBase * (1 - progress * 0.5), bBase, alpha);
      vertex(px, py);

      // Champ de force ascensionnel et tourbillonnaire
      let n1 = noise(px * 0.0022, py * 0.0022, i * 0.0001);
      let n2 = noise(px * 0.009, py * 0.009);

      let flowAngle = -HALF_PI + map(n1, 0, 1, -PI * 0.52, PI * 0.52) + map(n2, 0, 1, -0.35, 0.35);

      // Convergence douce vers une colonne céleste au sommet
      let distToCenter = cx - px;
      flowAngle += distToCenter * 0.00045;

      let speed = map(py, height, 0, 1.8, 5.5);
      px += cos(flowAngle) * speed;
      py += sin(flowAngle) * speed;
    }
    endShape();
  }

  // 6. Braises d'éternité : poussière de lumière suspendue
  noStroke();
  for (let i = 0; i < 3200; i++) {
    let t = pow(random(), 1.5);
    let y = map(t, 0, 1, cy + 80, 30);
    let spread = map(y, cy + 80, 0, radius * 0.75, width * 0.48);
    let x = cx + randomGaussian(0, spread * 0.52);

    let d = dist(x, y, cx, cy - 220);
    let sz = map(d, 0, 1100, 4.8, 0.6) * random(0.4, 1.6);

    if (sz > 0.4) {
      let alpha = map(y, 0, height, 0.1, 0.85) * random(0.2, 1.0);
      // Halo
      fill(42, 35, 100, alpha * 0.22);
      circle(x, y, sz * 3.5);
      // Coeur lumineux
      fill(45, 12, 100, alpha);
      circle(x, y, sz);
    }
  }

  // 7. Le Souffle Blanc : le dernier fil ténu reliant la matière à l'éther
  noFill();
  for (let i = 0; i < 160; i++) {
    let px = cx + random(-55, 55);
    let py = cy - radius * 0.35 + random(-35, 35);
    stroke(45, 8, 100, random(0.06, 0.22));
    strokeWeight(random(0.3, 1.3));

    beginShape();
    for (let s = 0; s < 340; s++) {
      vertex(px, py);
      let n = noise(px * 0.0035, py * 0.0035, i * 0.08);
      let a = -HALF_PI + map(n, 0, 1, -0.65, 0.65);
      px += cos(a) * 3.2;
      py += sin(a) * 3.2;
    }
    endShape();
  }

  // 8. Patine et grain de toile : matérialité picturale
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let grain = random(-11, 11);
    pixels[i] = constrain(pixels[i] + grain, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + grain, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + grain, 0, 255);
  }
  updatePixels();
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  field();
  rift();
  ash();
  earth();
  roots();
  cloth();
  bury();
  grains();
  gestures();
  vignette();
}

function riftX(y) {
  return 830 + sin(y * 0.0042) * 26 + (noise(y * 0.0047, 2.2) - 0.5) * 46;
}

function riftW(y) {
  let t = constrain((y - 470) / 1100, 0, 1);
  let w = pow(sin(t * PI), 0.78) * 92;
  w += (noise(y * 0.012, 8.4) - 0.5) * 16;
  if (y > 1400) w *= constrain(map(y, 1400, 1560, 1, 0.15), 0.15, 1);
  return max(0.4, w);
}

function field() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    let n = noise(y * 0.0022, 12);
    let r, g, b;
    if (t < 0.5) {
      r = lerp(5, 18, t * 2) + n * 5;
      g = lerp(7, 16, t * 2) + n * 3;
      b = lerp(14, 24, t * 2) + n * 2;
    } else {
      let u = (t - 0.5) * 2;
      r = lerp(18, 36, u) + n * 8;
      g = lerp(14, 24, u) + n * 4;
      b = lerp(16, 14, u);
    }
    stroke(r, g, b);
    line(0, y, width, y);
  }
  noStroke();
  for (let i = 0; i < 520; i++) {
    let x = random(width);
    let y = random(height);
    let s = random(60, 480);
    if (y < height * 0.52) fill(random(8, 26), random(10, 24), random(16, 36), random(4, 12));
    else fill(random(22, 54), random(12, 30), random(8, 20), random(5, 14));
    ellipse(x, y, s, s * random(0.35, 1.15));
  }
  for (let i = 0; i < 14000; i++) {
    stroke(random(30, 70), random(3, 14));
    point(random(width), random(height));
  }
}

function rift() {
  for (let y = 430; y < 1600; y++) {
    let x = riftX(y);
    let w = riftW(y);
    stroke(0, 0, 0, 12);
    strokeWeight(w * 3.2 + 78);
    line(x, y, x, y + 1);
  }
  for (let y = 455; y < 1570; y++) {
    let x = riftX(y);
    let w = riftW(y);
    let t = constrain((y - 455) / 1115, 0, 1);
    let bright = pow(sin(t * PI), 0.55);
    stroke(120 + bright * 50, 62 + bright * 28, 28, 8 + bright * 14);
    strokeWeight(w * 2.5 + 26);
    line(x, y, x, y + 1);
    stroke(186, 132, 62, 14 + bright * 22);
    strokeWeight(w + 7);
    line(x, y, x, y + 1);
    stroke(214 + bright * 28, 208 + bright * 22, 196 + bright * 14, 28 + bright * 55);
    strokeWeight(max(0.5, w * 0.7));
    line(x, y, x, y + 1);
    stroke(186, 198, 206, 10 + bright * 28);
    strokeWeight(max(0.3, w * 0.18));
    line(x + 1, y, x + 1, y + 1);
  }
  for (let y = 480; y < 1540; y += 2) {
    let x = riftX(y);
    let w = riftW(y);
    let side = random() < 0.5 ? -1 : 1;
    let len = random(6, 42) * (0.4 + noise(y * 0.02, side + 3));
    stroke(random(36, 78), random(20, 40), random(12, 26), random(50, 130));
    strokeWeight(random(0.5, 2.4));
    let x1 = x + side * w * random(0.35, 0.7);
    line(x1, y, x1 + side * len, y + random(-8, 10));
    if (random() < 0.25) {
      stroke(210, 170, 110, random(20, 70));
      strokeWeight(random(0.4, 1.4));
      line(x + side * w * 0.3, y, x + side * (w * 0.3 + random(4, 16)), y + random(-3, 3));
    }
  }
  for (let k = 0; k < 90; k++) {
    let y = 455 - k * 3.6;
    let x = riftX(455) + (noise(k * 0.08, 5) - 0.5) * k * 1.1;
    stroke(200, 188, 170, map(k, 0, 90, 22, 0));
    strokeWeight(map(k, 0, 90, 3.2, 0.3));
    point(x, y);
  }
}

function ash() {
  noStroke();
  for (let i = 0; i < 4200; i++) {
    let y0 = random(500, 1480);
    let w = riftW(y0);
    let x0 = riftX(y0) + random(-w, w) * 0.8;
    let life = random();
    let rise = life * random(40, 640);
    let yy = y0 - rise;
    let xx = x0 + (noise(i * 0.007, 9) - 0.42) * (80 + rise * 0.35);
    if (yy < 40) continue;
    fill(206, 196, 180, (1 - life) * 46);
    ellipse(xx, yy, random(0.8, 2.6), random(0.8, 2.6));
  }
}

function earth() {
  noStroke();
  for (let i = 0; i < 3800; i++) {
    let x = random(420, 1240);
    let y = random(1420, 1960);
    let buryAmt = constrain(map(y, 1420, 1700, 0, 1), 0, 1);
    if (random() > 0.25 + buryAmt * 0.75 && y < 1680) continue;
    fill(random(16, 42), random(10, 26), random(7, 16), random(18, 72));
    ellipse(x, y, random(10, 56), random(4, 18));
  }
  for (let i = 0; i < 30; i++) {
    fill(32, 20, 12, 8);
    ellipse(random(500, 1150), random(1550, 1900), random(200, 520), random(40, 120));
  }
}

function roots() {
  noFill();
  for (let i = 0; i < 9; i++) {
    let y = random(1340, 1545);
    let xL = riftX(y) - random(70, 240);
    let xR = riftX(y) + random(60, 230);
    stroke(22 + random(10), 14, 10, random(90, 160));
    strokeWeight(random(0.8, 2.6));
    beginShape();
    curveVertex(xL, y + random(-12, 12));
    curveVertex(xL, y + random(-12, 12));
    curveVertex(riftX(y) - random(10, 40), y + random(-16, 14));
    curveVertex(riftX(y) + random(8, 36), y + random(-12, 18));
    curveVertex(xR, y + random(-18, 16));
    curveVertex(xR, y + random(-18, 16));
    endShape();
    if (random() < 0.7) {
      let x = riftX(y) + random(-20, 20);
      stroke(26, 16, 12, 100);
      strokeWeight(0.8);
      line(x, y, x + random(-30, 30), y + random(12, 36));
    }
  }
}

function cloth() {
  noStroke();
  for (let x = 640; x <= 1090; x += 2) {
    let n = noise(x * 0.007, 30);
    let y = 1504 + n * 30 + sin(x * 0.018) * 8;
    let fold = 40 + noise(x * 0.018, 31) * 38;
    fill(36, 28, 22, 18);
    ellipse(x, y + fold * 0.46, 14, fold * 0.5);
    fill(216, 208, 196, 20);
    ellipse(x, y, 16, fold);
    fill(236, 230, 220, 9);
    ellipse(x - 1, y - fold * 0.16, 7, fold * 0.32);
  }
  noFill();
  stroke(132, 118, 104, 40);
  strokeWeight(1);
  beginShape();
  for (let x = 660; x <= 1070; x += 6) curveVertex(x, 1500 + noise(x * 0.012, 44) * 16);
  endShape();
  noStroke();
  for (let x = 700; x <= 1040; x += 3) {
    let y = 1558 + noise(x * 0.01, 50) * 18;
    fill(206, 198, 186, 12);
    ellipse(x, y, 14, 18 + noise(x * 0.02, 51) * 16);
  }
}

function bury() {
  noStroke();
  for (let i = 0; i < 600; i++) {
    fill(28, 18, 12, random(8, 28));
    ellipse(random(600, 1120), random(1565, 1680), random(12, 36), random(4, 10));
  }
}

function grains() {
  noStroke();
  for (let i = 0; i < 520; i++) {
    fill(196, 180, 154, random(16, 70));
    ellipse(random(560, 1120), random(1520, 1880), random(1, 2.8), random(1, 2.2));
  }
  for (let i = 0; i < 6; i++) {
    let x = random(620, 1040);
    let y = random(1620, 1840);
    let s = random(8, 18);
    fill(168, 152, 128, 50);
    ellipse(x, y, s * random(1.2, 2.1), s * random(0.5, 0.9));
    fill(210, 198, 176, 30);
    ellipse(x - s * 0.15, y - 1, s * 0.7, s * 0.35);
  }
}

function gestures() {
  for (let i = 0; i < 240; i++) {
    let x = random(80, 1520);
    let y = random(80, 1920);
    let len = random(20, 140);
    let ang = random(-0.5, 0.5);
    stroke(random(20, 50), random(12, 28), random(10, 24), random(8, 22));
    strokeWeight(random(0.4, 1.6));
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

function vignette() {
  noStroke();
  for (let i = 0; i < 160; i++) {
    fill(0, 0, 0, 1.05);
    rect(0, 0, i * 1.3, height);
    rect(width - i * 1.3, 0, i * 1.3, height);
    rect(0, 0, width, i * 0.85);
    rect(0, height - i * 1.15, width, i * 1.15);
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  createCanvas(1600, 2000);
  noLoop();
}

function draw() {
  sky();
  stars();
  clouds();
  farHill();
  sun();
  water();
  reflection();
  mist();
  headland();
  trees();
  shore();
  cloth();
  roots();
  figure();
  seeds();
  flowers();
  grain();
