}

function sky() {
  for (let y = 0; y < 1260; y++) {
    const t = y / 1260;
    const glow = pow(t, 2.5);
    for (let x = 0; x < width; x += 16) {
      const n = noise(x * 0.0014, y * 0.005);
      let r = lerp(6, 26, t) + n * 12;
      let g = lerp(8, 18, t) + n * 6;
      let b = lerp(18, 34, t) + n * 8;
      r = lerp(r, 188, glow);
      g = lerp(g, 76, glow);
      b = lerp(b, 50, glow);
      stroke(r, g, b);
      line(x, y, x + 16, y);
    }
  }
}

function stars() {
  for (let i = 0; i < 160; i++) {
    const x = random(width);
    const y = random(0, 720);
    const fade = constrain(map(y, 0, 720, 1, 0.15), 0, 1);
    stroke(232, 226, 210, random(30, 170) * fade);
    strokeWeight(random(0.4, 1.5));
    point(x, y);
  }
}

function clouds() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    const x = random(width);
    const y = random(20, 760);
    const opening = dist(x, y, 900, 460);
    const a = opening < 240 ? random(2, 6) : random(7, 16);
    fill(26 + random(24), 24 + random(10), 42 + random(16), a);
    ellipse(x, y, random(160, 560), random(24, 86));
  }
}

function farHill() {
  noStroke();
  fill(46, 34, 50, 170);
  beginShape();
  vertex(820, 1260);
  vertex(990, 1168);
  vertex(1160, 1210);
  vertex(1360, 1136);
  vertex(1600, 1204);
  vertex(1600, 1260);
  endShape(CLOSE);
  fill(30, 24, 38, 130);
  beginShape();
  vertex(940, 1260);
  vertex(1120, 1194);
  vertex(1340, 1238);
  vertex(1540, 1178);
  vertex(1600, 1210);
  vertex(1600, 1260);
  endShape(CLOSE);
}

function sun() {
  noStroke();
  for (let r = 280; r > 88; r -= 8) {
    const t = (r - 88) / 192;
    fill(255, 140 + (1 - t) * 50, 60, 4 + (1 - t) * 9);
    ellipse(1080, 1234, r * 2.15, r * 1.35);
  }
  for (let r = 84; r > 0; r -= 2) {
    const t = r / 84;
    fill(255, lerp(220, 112, t), lerp(176, 38, t), 210);
    ellipse(1080, 1234, r * 2, r * 2);
  }
  fill(62, 32, 36, 46);
  ellipse(1038, 1192, 78, 34);
  fill(255, 236, 200, 40);
  ellipse(1102, 1248, 28, 16);
}

function water() {
  for (let y = 1260; y < height; y++) {
    const t = (y - 1260) / (height - 1260);
    const n = noise(y * 0.007, 2.4);
    stroke(lerp(34, 6, t) + n * 8, lerp(28, 9, t) + n * 4, lerp(36, 14, t) + n * 5);
    line(0, y, width, y);
  }
}

function reflection() {
  for (let y = 1272; y < 1880; y += 3) {
    const t = (y - 1272) / (1880 - 1272);
    if (noise(y * 0.07, 4) < 0.32) continue;
    const w = lerp(34, 3, t) * (0.35 + noise(y * 0.03) * 1.15);
    const x = 1080 + (noise(y * 0.02, 1) - 0.5) * 36 * t;
    stroke(232, 168, 86, lerp(100, 0, t));
    strokeWeight(1.3);
    line(x - w, y, x + w, y);
  }
  for (let i = 0; i < 520; i++) {
    const y = random(1280, 1980);
    const x = random(width);
    stroke(170, 145, 120, random(6, 22));
    strokeWeight(1);
    line(x, y, x + random(16, 120), y);
  }
}

