function tree(x, y, len) {
  grow(x, y, len, -HALF_PI, 0);
}

function grow(x, y, len, ang, d) {
  if (d > 8 || len < 5) return;
  const j = (noise(x * 0.01, y * 0.01, d) - 0.5) * 0.45;
  const x2 = x + cos(ang) * len;
  const y2 = y + sin(ang) * len;
  stroke(18, 14, 16, 220);
  strokeWeight(max(0.45, (8 - d) * 0.8));
  line(x, y, x2, y2);
  grow(x2, y2, len * 0.73, ang - 0.46 + j, d + 1);
  grow(x2, y2, len * 0.69, ang + 0.42 + j, d + 1);
  if (d < 3 && random() < 0.65) grow(x2, y2, len * 0.58, ang + j * 0.3, d + 1);
}

