function shoreY(x) {
  const pts = [
    [0, 1720], [160, 1660], [360, 1610], [560, 1568], [700, 1536],
    [860, 1578], [1040, 1688], [1280, 1820], [1600, 1888]
  ];
  for (let i = 0; i < pts.length - 1; i++) {
    if (x >= pts[i][0] && x <= pts[i + 1][0]) {
      const u = (x - pts[i][0]) / (pts[i + 1][0] - pts[i][0]);
      return lerp(pts[i][1], pts[i + 1][1], u);
    }
  }
  return 1900;
}

