      if (s > 10 && random() < 0.45) {
        stroke(86, 118, 74, 170);
        strokeWeight(0.8);
        const lx = x2 + random(-8, 8);
        const ly = y2 - random(8, 20);
        line(x2, y2, lx, ly);
        noStroke();
        fill(122, 146, 96, 150);
        ellipse(lx, ly, random(3, 6), random(2, 4));
      }
      x = x2;
      y = y2;
    }
  }
}

function figure() {
  noStroke();
  fill(0, 36);
  ellipse(706, 1558, 210, 28);

  for (let i = 0; i < 5200; i++) {
    const u = random();
    const y = lerp(1116, 1536, u);
    let half;
    if (u < 0.08) half = lerp(16, 26, u / 0.08);
    else if (u < 0.14) half = lerp(11, 20, (u - 0.08) / 0.06);
    else if (u < 0.26) half = lerp(20, 82, (u - 0.14) / 0.12);
    else if (u < 0.82) half = lerp(82, 46, (u - 0.26) / 0.56);
    else half = lerp(46, 74, (u - 0.82) / 0.18);
    const dissolve = constrain(map(u, 0, 0.2, 0.18, 1), 0, 1);
    if (random() > dissolve) continue;
    const nx = random(-1, 1);
    if (abs(nx) > 0.78 && random() < 0.62) continue;
    const cx = 676 + u * 8 + (noise(u * 4) - 0.5) * 6;
    const x = cx + nx * half;
    if (u > 0.22 && y > shoreY(x) + 2) continue;
    const edge = abs(nx);
    stroke(lerp(224, 138, u) - edge * 30, lerp(208, 122, u) - edge * 24, lerp(186, 104, u) - edge * 18, random(28, 92));
    strokeWeight(random(0.5, 1.7));
    line(x, y + random(-1, 1), x + random(-1.2, 1.2), y + random(2, 7));
  }

  limb(648, 1224, 592, 1368, 16, 5, false);
  limb(724, 1212, 990, 1328, 15, 2, true);

  noStroke();
  for (let i = 0; i < 36; i++) {
    fill(196, 84, 42, random(8, 26));
    ellipse(686 + random(-7, 7), 1292 + random(-9, 9), random(3, 11));
  }
}

function limb(x1, y1, x2, y2, bulk, endBulk, releasing) {
  for (let i = 0; i < 700; i++) {
    const t = random();
    if (releasing && random() > lerp(1, 0.15, t)) continue;
    const x = lerp(x1, x2, t) + random(-1, 1) * lerp(bulk, endBulk, t);
    const y = lerp(y1, y2, t) + random(-1, 1) * lerp(bulk, endBulk, t) * 0.45;
    const warm = releasing ? t : 0;
    stroke(lerp(196, 236, warm), lerp(176, 176, warm), lerp(150, 110, warm), random(24, 80));
    strokeWeight(random(0.5, 1.5));
    line(x, y, x + random(-1, 1), y + random(1, 5));
  }
}

function seeds() {
