    const x = lerp(688, 1040, t) + (noise(i * 0.04) - 0.5) * 90;
    const y = lerp(1130, 260, t) + random(-24, 24);
    stroke(255, lerp(214, 160, random()), lerp(188, 100, random()), lerp(150, 16, t));
    strokeWeight(random(0.5, 2.2));
    if (random() < 0.55) point(x, y);
    else line(x, y, x + random(-4, 10), y + random(-12, 2));
  }
  for (let i = 0; i < 70; i++) {
    stroke(206, 184, 154, random(16, 54));
    strokeWeight(random(0.5, 1.3));
