function bloom(x, y, s, col) {
  noStroke();
  for (let k = 0; k < 7; k++) {
    const a = (k / 7) * TWO_PI + 0.3;
    fill(col[0], col[1], col[2], 156);
    ellipse(x + cos(a) * s * 0.72, y + sin(a) * s * 0.42, s, s * 0.66);
  }
  fill(42, 30, 22, 190);
  ellipse(x, y, s * 0.32, s * 0.32);
}

