function shoreY(x) {
  return 1510 - x * 0.11 + noise(x * 0.0035, 8.0) * 36;
}

function skyAt(t) {
  const stops = [
    [0.0, 9, 11, 28],
    [0.28, 22, 22, 54],
    [0.5, 58, 34, 68],
    [0.7, 122, 52, 68],
    [0.86, 196, 104, 86],
    [0.95, 236, 176, 124],
    [1.0, 248, 214, 176]
  ];
  let i = 0;
  while (i < stops.length - 2 && t > stops[i + 1][0]) i++;
  const a = stops[i];
  const b = stops[i + 1];
  const u = constrain((t - a[0]) / (b[0] - a[0]), 0, 1);
  return color(
    lerp(a[1], b[1], u),
    lerp(a[2], b[2], u),
    lerp(a[3], b[3], u)
  );
}

function paintSky() {
  for (let y = 0; y < 1280; y++) {
    const t = constrain(y / 1160, 0, 1);
    const n = noise(y * 0.012, 0.4);
    const col = skyAt(t);
    stroke(
      red(col) + (n - 0.5) * 12,
      green(col) + (n - 0.5) * 8,
      blue(col) + (n - 0.5) * 14
    );
    line(0, y, width, y);
  }
}

function paintClouds() {
  noStroke();
  for (let i = 0; i < 2200; i++) {
    const x = random(width);
    const y = random(20, 1080);
    const n = noise(x * 0.0016, y * 0.0024);
    const t = y / 1160;
    const w = 50 + n * 220;
    const h = 8 + (1 - t) * 18;
    if (t < 0.62) {
      fill(18 + n * 24, 20 + n * 16, 42 + n * 20, 10 + n * 16);
    } else {
      fill(170 + n * 40, 90 + n * 30, 70, 8 + n * 14);
    }
    push();
    translate(x, y);
    rotate(-0.18 + n * 0.5);
    ellipse(0, 0, w, h);
    pop();
  }
}

