    const y = lerp(1152, 1475, t);
    const flicker = noise(i * 0.45, 2.2);
    const w = lerp(8, 42, t) * (0.35 + flicker);
    const a = lerp(58, 6, t) * (flicker > 0.32 ? 1 : 0.12);
    fill(238, 198, 142, a);
    ellipse(1060 + (noise(i * 0.8, 4) - 0.5) * 22, y, w, 3 + t * 5);
