function paintGhost() {
  const x = 1048;
  const foot = 1112;
  noStroke();
  for (let i = 0; i < 120; i++) {
    const t = i / 120;
    const y = foot - t * 210;
    let w = lerp(34, 5, t) * (0.65 + noise(i * 0.22, 7));
    if (t > 0.74 && t < 0.9) w += 12;
    fill(246, 222, 194, lerp(34, 0, t));
    ellipse(x + (noise(i * 0.31, 3) - 0.5) * 20, y, w, 18);
  }
  for (let i = 0; i < 30; i++) {
    const t = i / 30;
    stroke(236, 210, 180, 16 * (1 - t));
    strokeWeight(1);
    const y = foot - t * 180;
    line(x - 6, y, x + 6, y - 16);
