function paintCypress() {
  const x = 1324;
  const base = shoreY(x) + 8;
  const top = base - 780;
  noStroke();
  for (let i = 0; i < 100; i++) {
    const t = i / 100;
    const y = lerp(base, top, t);
    const w = lerp(180, 14, Math.pow(t, 0.68));
    const j = (noise(i * 0.16, 6) - 0.5) * 28;
    fill(7 + t * 8, 13 + t * 6, 11, 64);
    ellipse(x + j, y, w * (0.72 + noise(i * 0.28) * 0.42), 16 + (1 - t) * 24);
  }
  fill(12, 9, 8, 230);
  rect(x - 5, base - 170, 11, 186, 3);
