    const h = 16 + noise(i * 0.37, 2.2) * 78;
    stroke(32, 24, 16, 150);
    strokeWeight(0.8 + noise(i, 0.2) * 1.3);
    bezier(
      x,
      y,
      x + 5,
      y - h * 0.35,
      x - 7,
      y - h * 0.72,
      x + (noise(i * 0.5) - 0.5) * 10,
      y - h
    );
  }
  noStroke();
}

function paintFigure() {
