function cypress(x, base, h, w) {
  noStroke();
  for (let i = 0; i < 20; i++) {
    let t = i / 19;
    let yy = base - h * (0.06 + t * 0.92);
    let ww = w * (0.22 + (1 - t) * 0.95) * (0.82 + noise(i * 0.31, x * 0.01) * 0.36);
    let hh = h * 0.15 * (1.12 - t * 0.45);
    fill(6 + t * 4, 10 + t * 3, 9);
    ellipse(x + (noise(i, x) - 0.5) * 10, yy, ww, hh);
