// p5.js 1.11 — still image, 1600 × 2000

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  randomSeed(1);
  noiseSeed(1);
  colorMode(RGB, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);

  drawWall();
  drawFloor();
  drawWindow();
  drawBeam();
  drawFloorLight();
  drawChair();
  drawCloth();
  drawBook();
  drawCandle();
  drawSmoke();
  drawDust();
