}

function drawWall() {
  background(14, 12, 12);
  for (let y = 0; y < 1320; y++) {
    let n = noise(y * 0.006, 1.7);
    let lift = noise(y * 0.02, 4.2) * 6;
    stroke(16 + n * 10 + lift, 13 + n * 6, 12 + n * 5);
    line(0, y, width, y);
  }
  for (let i = 0; i < 9000; i++) {
    let x = random(width);
    let y = random(1280);
    stroke(255, random(3, 11));
    strokeWeight(random(0.4, 1.4));
    line(x, y, x + random(-1.5, 1.5), y + random(6, 28));
  }
  noStroke();
  for (let i = 0; i < 18; i++) {
    fill(0, 0, 0, 8);
    rect(0, 0, 280 - i * 8, height);
    rect(width - (220 - i * 6), 0, 220, height);
  }
  fill(70, 68, 64, 16);
  ellipse(900, 640, 180, 460);
}

function drawFloor() {
  for (let y = 1272; y < height; y++) {
    let t = (y - 1272) / 728;
    let n = noise(0.4, y * 0.012);
    stroke(30 + t * 22 + n * 8, 22 + t * 14 + n * 4, 16 + t * 8);
    line(0, y, width, y);
  }
  let vpX = 860;
  let vpY = 1272;
  for (let i = -14; i <= 14; i++) {
    stroke(16, 11, 9, 55);
    strokeWeight(1.4);
    line(vpX + i * 5, vpY, vpX + i * 145, height + 40);
  }
  noStroke();
  fill(0, 0, 0, 36);
  rect(0, 1272, width, 36);
  fill(92, 58, 36, 14);
  ellipse(560, 1500, 320, 70);
}

function drawWindow() {
  let gx = 1004;
  let gy = 214;
  let gw = 408;
  let gh = 790;

  for (let i = 0; i < gh; i++) {
    let t = i / gh;
    let n = noise(i * 0.015, 3.3) * 7;
    stroke(
      lerp(54, 22, t) + n,
      lerp(68, 30, t) + n * 0.55,
      lerp(94, 48, t) + n * 0.35
    );
    line(gx, gy + i, gx + gw, gy + i);
  }

  noStroke();
  fill(12, 18, 28, 210);
  beginShape();
  vertex(gx, gy + gh);
  for (let x = gx; x <= gx + gw; x += 8) {
    vertex(x, gy + gh - 70 - noise(x * 0.01, 6) * 78);
  }
  vertex(gx + gw, gy + gh);
  endShape(CLOSE);

  for (let i = 0; i < 28; i++) {
    let sx = random(gx + 12, gx + gw - 12);
    let sy = random(gy + 16, gy + 280);
    if (dist(sx, sy, 1160, 392) > 96) {
      stroke(245, 242, 230, random(40, 140));
      strokeWeight(random(0.6, 1.6));
      point(sx, sy);
    }
  }

  drawCrescent(1160, 392, 70);

  // sash
  noStroke();
  fill(18, 16, 16, 230);
  rect(1266, gy, 9, gh);
  fill(186, 176, 160, 50);
  rect(1266, gy, 2, gh);

  // room reflected faintly in the glass
  for (let i = 0; i < 70; i++) {
    stroke(8, 7, 8, 16);
    line(gx + i, gy, gx + i, gy + gh);
  }

  // frame
  noStroke();
  fill(28, 24, 22);
  rect(968, 176, 36, 860);
  rect(1412, 176, 36, 828);
  rect(968, 176, 480, 38);
  fill(58, 52, 46);
  rect(1000, 210, 8, 798);
  rect(1404, 210, 10, 786);
  rect(1004, 210, 408, 8);
  fill(120, 110, 98, 70);
  rect(1402, 214, 3, 780);

  // sill
  fill(104, 96, 86);
  rect(938, 984, 548, 20);
  fill(46, 38, 32);
  rect(938, 1004, 548, 34);
  stroke(196, 186, 170, 90);
  strokeWeight(1.5);
  line(944, 985, 1478, 985);
  noStroke();
}

function drawCrescent(cx, cy, r) {
  noStroke();
  for (let i = 6; i >= 1; i--) {
    fill(214, 210, 196, 7);
    ellipse(cx, cy, r * 2 + i * 26, r * 2 + i * 26);
  }
  let s = floor(r * 5);
  let g = createGraphics(s, s);
  g.clear();
  g.noStroke();
  g.fill(236, 230, 216);
  g.ellipse(s / 2, s / 2, r * 2, r * 2);
  g.erase();
  g.ellipse(s / 2 + r * 0.5, s / 2 - r * 0.04, r * 1.6, r * 1.72);
  g.noErase();
  image(g, cx - s / 2, cy - s / 2);

  noFill();
  stroke(255, 250, 240, 90);
  strokeWeight(1.5);
  arc(cx - 1, cy, r * 2 - 6, r * 2 - 6, 0.7 * PI, 1.35 * PI);
  noStroke();
}

