    px = constrain(px, 1278, 1388);
    py -= 4.35;
    let w = 8 + t * 64;
    let h = 7 + t * 20;
    let a = (1 - t) * (1 - t) * 40;
    fill(188 + t * 28, 192 + t * 22, 198 + t * 14, a);
    ellipse(px, py, w, h);
    fill(220, 222, 224, a * 0.28);
    ellipse(px - w * 0.12, py - 1, w * 0.4, h * 0.45);
  }
