function applyPaintTexture() {
  loadPixels();
  for (let i = 0; i < 50000; i++) {
    let px = int(random(width));
    let py = int(random(height));
    let index = (py * width + px) * 4;
    let noiseVal = noise(px * 0.01, py * 0.01);
    let r = pixels[index] + (noiseVal - 0.5) * 40;
    let g = pixels[index+1] + (noiseVal - 0.5) * 30;
    let b = pixels[index+2] + (noiseVal - 0.5) * 20;
    pixels[index] = constrain(r, 0, 255);
    pixels[index+1] = constrain(g, 0, 255);
    pixels[index+2] = constrain(b, 0, 255);
    pixels[index+3] = 255;
  }
  updatePixels();
}

let W = 1600;
let H = 2000;

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  let ctx = drawingContext;
  let rad = ctx.createRadialGradient(W * 0.5, H * 0.45, 80, W * 0.5, H * 0.5, W * 0.72);
  rad.addColorStop(0, color(58, 42, 32));
  rad.addColorStop(0.55, color(26, 17, 14));
  rad.addColorStop(1, color(7, 4, 3));
  ctx.fillStyle = rad;
  ctx.fillRect(0, 0, W, H);

  drawDrapery();
  drawLightBeam();
  drawTable();
  drawShadows();
  drawRose();
  drawCandle(1200, 1440, 360, 130);
  drawSkull(800, 1120, 1.25);
  drawSmoke(1200, 1040);
  drawMoth(600, 780);
  drawVignette();
  drawTextureOverlay();
}

function drawDrapery() {
  noStroke();
  for (let i = 0; i < 90; i++) {
    let x = random(80, W - 80);
