    strokeWeight(random(1, 5));
    noFill();
    bezier(x, -50, x + amp, 500, x - amp * 0.7, 1200, x + random(-80, 80), H + 50);
  }
  for (let i = 0; i < 40; i++) {
    let x = random(100, W - 100);
    stroke(60, 40, 35, random(10, 40));
    strokeWeight(random(1, 3));
    noFill();
    bezier(x, -50, x + random(-60, 60), 600, x + random(-60, 60), 1400, x + random(-40, 40), H + 50);
