function drawSmoke(x, y) {
  noFill();
  for (let i = 0; i < 22; i++) {
    let t = i / 22;
    let yy = y - t * 320;
    let xx = x + sin(t * 3.0 * PI) * 110 * t + noise(t * 10) * 30 - 15;
    stroke(160, 150, 145, map(t, 0, 1, 60, 0));
    strokeWeight(map(t, 0, 1, 10, 2));
    point(xx, yy);
  }

  for (let i = 0; i < 10; i++) {
    let yy = y - i * 30;
    let xx = x + sin(i * 0.9) * 70 + random(-20, 20);
    stroke(170, 160, 155, random(4, 12));
    strokeWeight(random(6, 16));
    noFill();
    bezier(xx, yy, xx + random(-50, 50), yy - 30, xx + random(-50, 50), yy - 60, xx + random(-20, 20), yy - 90);
  }
}

