  beginShape();
  vertex(cx + 60 * s, cy - 300 * s);
  bezierVertex(cx + 170 * s, cy - 220 * s, cx + 180 * s, cy - 80 * s, cx + 150 * s, cy + 30 * s);
  bezierVertex(cx + 130 * s, cy - 20 * s, cx + 120 * s, cy - 140 * s, cx + 60 * s, cy - 300 * s);
