function drawSocket(x, y, w, h) {
  beginShape();
  vertex(x - w * 0.55, y + h * 0.1);
  bezierVertex(x - w * 0.55, y - h * 0.5, x + w * 0.55, y - h * 0.5, x + w * 0.55, y + h * 0.1);
  bezierVertex(x + w * 0.3, y + h * 0.7, x - w * 0.3, y + h * 0.7, x - w * 0.55, y + h * 0.1);
  endShape(CLOSE);
}

function drawMoth(x, y) {
  push();
  translate(x, y);
  rotate(-0.35);
  noStroke();

  fill(145, 135, 130);
  beginShape();
  vertex(0, 0);
  bezierVertex(-55, -50, -85, -25, -50, 15);
  bezierVertex(-25, 30, 0, 20, 0, 0);
  endShape(CLOSE);
  beginShape();
  vertex(0, 0);
  bezierVertex(55, -50, 85, -25, 50, 15);
  bezierVertex(25, 30, 0, 20, 0, 0);
  endShape(CLOSE);

  fill(115, 105, 100);
  beginShape();
  vertex(0, 5);
  bezierVertex(-45, 25, -50, 60, -25, 75);
  bezierVertex(-5, 82, 0, 40, 0, 5);
  endShape(CLOSE);
  beginShape();
  vertex(0, 5);
  bezierVertex(45, 25, 50, 60, 25, 75);
  bezierVertex(5, 82, 0, 40, 0, 5);
