function drawVignette() {
  let ctx = drawingContext;
  let grd = ctx.createRadialGradient(W * 0.5, H * 0.45, H * 0.45, W * 0.5, H * 0.5, H * 0.75);
  grd.addColorStop(0, color(0, 0, 0, 0));
  grd.addColorStop(1, color(0, 0, 0, 170));
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, W, H);
}

function drawTextureOverlay() {
  noStroke();
  for (let i = 0; i < 2500; i++) {
    fill(0, random(0, 10), random(0, 5), random(1, 4));
    rect(random(W), random(H), random(1, 4), random(1, 3));
  }

  for (let i = 0; i < 800; i++) {
    let x = random(W);
    let y = random(H);
    stroke(255, 240, 220, random(1, 5));
    strokeWeight(random(1, 2));
    line(x, y, x + random(-2, 2), y + random(-2, 2));
  }

  for (let i = 0; i < 200; i++) {
    let x = random(W);
    let y = random(H);
    let angle = random(TWO_PI);
    let len = random(10, 60);
    stroke(0, 0, 0, random(2, 7));
    strokeWeight(random(3, 10));
    line(x, y, x + cos(angle) * len, y + sin(angle) * len);
  }
}

function setup() {
  createCanvas(1600, 2000);
  noLoop();
  randomSeed(1);
  noiseSeed(1);
  drawPainting();
}

function drawPainting() {
  drawBackground();
  drawLightBeam();
  drawTableCloth();
  drawCandleAndSmoke();
  drawMoth();
  drawSkull();
  drawWiltedRoses();
  drawGrainAndVignette();
}

function drawBackground() {
  for (let y = 0; y < height; y++) {
    let t = y / height;
    stroke(lerpColor(color(15, 10, 8), color(42, 28, 22), t));
    strokeWeight(1);
    line(0, y, width, y);
  }

  for (let i = 0; i < 260; i++) {
    let x = random(width);
    let y = random(height);
    let rad = random(180, 650);
    fill(0, 0, 0, random(2, 10));
    noStroke();
    ellipse(x, y, rad);
  }

  for (let i = 0; i < 1300; i++) {
    let x = random(width);
    let y = random(height);
    let w = random(6, 20);
    let len = random(30, 130);
    stroke(20 + random(-12, 14), 15 + random(-6, 10), 10 + random(-5, 8), random(3, 18));
    strokeWeight(random(1, 3));
    line(x, y, x + random(-len, len), y + random(-len, len));
  }
}

function drawLightBeam() {
  noStroke();
  for (let i = 0; i < 80; i++) {
    let t = i / 80;
    let alpha = 7 * (1 - t);
    fill(255, 244, 220, alpha);
    beginShape();
    vertex(300 + t * 80, -50 + i * 25);
    vertex(700 + t * 50, -20 + i * 28);
    vertex(1050 + t * 80, 400 + i * 28);
    vertex(450 + t * 60, 300 + i * 25);
    endShape(CLOSE);
  }

  for (let i = 0; i < 220; i++) {
    let x = 300 + random() * 760;
    let y = random(-50, 2000);
    let d = random(2, 7);
    fill(255, 244, 220, random(5, 40));
    ellipse(x, y, d);
  }
}

function drawTableCloth() {
  fill(22, 15, 13);
  noStroke();
  rect(0, 1430, width, height - 1430);

  fill(48, 20, 18, 220);
  noStroke();
  beginShape();
  for (let x = 0; x <= width; x += 20) {
    let y = 1410 + (noise(x * 0.002, 0.5) - 0.5) * 50;
    vertex(x, y);
  }
  vertex(width, height);
  vertex(0, height);
  endShape(CLOSE);

  for (let i = 0; i < 140; i++) {
    let x = random(width);
    let yBase = random(1420, 1900);
    stroke(0, 0, 0, random(5, 25));
    strokeWeight(random(3, 8));
    noFill();
    bezier(
      x, yBase,
      x + random(-50, 50), yBase + random(-100, 100),
      x + random(-70, 70), yBase + random(80, 250),
      x + random(-40, 40), yBase + random(200, 500)
    );
  }

  for (let i = 0; i < 90; i++) {
    let x = random(width);
    let y = random(1440, 1900);
    stroke(120, 60, 50, random(4, 15));
    strokeWeight(random(1, 5));
    line(x, y, x + random(-50, 50), y + random(100, 400));
  }
}

function drawCandleAndSmoke() {
  let x = 370;
  let topY = 1180;
  let bottomY = 1415;
  let w = 75;

  fill(0, 0, 0, 90);
  noStroke();
  ellipse(x, 1420, 180, 45);

  drawSmoke(x, topY);

  fill(232, 224, 204);
  stroke(70, 50, 38);
  strokeWeight(5);
  beginShape();
  vertex(x - w / 2, bottomY);
  vertex(x - w / 2, topY);
  bezierVertex(x - w / 2, topY - 22, x + w / 2, topY - 22, x + w / 2, topY);
  vertex(x + w / 2, bottomY);
  endShape(CLOSE);

  noStroke();
  fill(180, 165, 145, 160);
  rect(x, topY, w / 2, bottomY - topY);

  fill(210, 195, 170, 100);
  rect(x - 10, topY + 80, 14, bottomY - topY - 100);
  rect(x + 10, topY + 120, 10, bottomY - topY - 150);

  fill(232, 224, 204);
  noStroke();
  beginShape();
  vertex(x - 18, topY + 30);
  bezierVertex(x - 32, topY + 120, x - 38, topY + 240, x - 28, topY + 360);
  bezierVertex(x - 20, topY + 330, x - 10, topY + 260, x - 6, topY + 40);
  endShape();

  beginShape();
  vertex(x + 28, topY + 40);
