function drawSmoke(x, y) {
  noFill();
  for (let s = 0; s < 28; s++) {
    let startX = x + random(-8, 8);
    let startY = y - random(10, 30);
    for (let i = 0; i < 20; i++) {
      let t = i / 20;
      let t2 = (i + 1) / 20;
      let yy1 = startY - t * 520;
      let yy2 = startY - t2 * 520;
      let drift1 = noise(startX * 0.01, t * 2.5 + s * 0.7) * 90 - 40;
      let drift2 = noise(startX * 0.01, t2 * 2.5 + s * 0.7) * 90 - 40;
      let xx1 = startX + drift1 + sin(t * PI * 1.2) * 25;
      let xx2 = startX + drift2 + sin(t2 * PI * 1.2) * 25;
      stroke(220, 214, 205, random(3, 12));
      strokeWeight(random(2, 8));
      line(xx1, yy1, xx2, yy2);
    }
  }
}

