function drawSkull() {
  let ctx = drawingContext;

  fill(0, 0, 0, 110);
  noStroke();
  ellipse(800, 1510, 500, 70);

  ctx.save();
  skullPath(ctx);
  ctx.clip();

  let grad = ctx.createLinearGradient(800, 500, 800, 1550);
  grad.addColorStop(0, '#f4ecd8');
  grad.addColorStop(0.55, '#dccdb3');
  grad.addColorStop(1, '#b19c84');
  ctx.fillStyle = grad;
  ctx.fillRect(0, 0, width, height);

  for (let i = 0; i < 260; i++) {
    let x = random(480, 1120);
    let y = random(450, 1600);
    let r = random(30, 220);
    ctx.fillStyle = `rgba(0,0,0,${random(0.02, 0.08)})`;
    ctx.beginPath();
    ctx.arc(x, y, r, 0, Math.PI * 2);
    ctx.fill();
  }

  for (let i = 0; i < 1200; i++) {
    let x = random(520, 1080);
    let y = random(480, 1580);
    let w = random(1, 6);
    let len = random(5, 40);
    let ang = random(TWO_PI);
    let col = random(200, 255);
    ctx.strokeStyle = `rgba(${col}, ${col - 10}, ${col - 25}, ${random(0.03, 0.12)})`;
    ctx.lineWidth = w;
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.lineTo(x + cos(ang) * len, y + sin(ang) * len);
    ctx.stroke();
  }

  ctx.strokeStyle = 'rgba(40, 28, 24, 0.3)';
  ctx.lineWidth = 2;
  for (let i = 0; i < 12; i++) {
    let x = random(620, 980);
    let y = random(560, 1100);
    ctx.beginPath();
    ctx.moveTo(x, y);
    ctx.bezierCurveTo(
      x + random(-50, 50), y + random(-40, 80),
      x + random(-60, 60), y + random(70, 150),
      x + random(-70, 70), y + random(140, 220)
    );
    ctx.stroke();
  }

  ctx.restore();

  ctx.save();
  skullPath(ctx);
  ctx.strokeStyle = 'rgba(55, 36, 30, 0.85)';
  ctx.lineWidth = 9;
  ctx.stroke();
  ctx.restore();

  drawSkullFeatures();
}

function skullPath(ctx) {
