  ctx.bezierCurveTo(535, 1020, 585, 1200, 650, 1340);
  ctx.lineTo(650, 1470);
  ctx.bezierCurveTo(730, 1530, 870, 1530, 950, 1470);
  ctx.lineTo(950, 1340);
  ctx.bezierCurveTo(1015, 1200, 1065, 1020, 1010, 810);
  ctx.bezierCurveTo(990, 610, 900, 540, 800, 540);
  ctx.bezierCurveTo(700, 540, 610, 610, 590, 810);
  ctx.closePath();
}

