function drawTeeth() {
  let ctx = drawingContext;
  let x1 = 680;
  let x2 = 920;
  let yTop = 1350;
  let yGap = 1420;
  let yBot = 1480;

  ctx.fillStyle = 'rgb(18, 12, 10)';
  ctx.fillRect(x1, yGap, x2 - x1, 8);

  ctx.fillStyle = 'rgb(225, 212, 188)';
  ctx.fillRect(x1, yTop, x2 - x1, yGap - yTop);
  ctx.fillRect(x1, yGap + 8, x2 - x1, yBot - yGap - 8);

  ctx.strokeStyle = 'rgba(70, 50, 35, 0.75)';
  ctx.lineWidth = 3;
  for (let i = 0; i <= 7; i++) {
    let x = x1 + 12 + i * ((x2 - x1 - 24) / 7);
    ctx.beginPath();
    ctx.moveTo(x, yTop);
    ctx.lineTo(x, yGap);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(x, yGap + 8);
    ctx.lineTo(x, yBot);
    ctx.stroke();
  }
}

