function drawVignette() {
  noStroke();
  let g = drawingContext.createRadialGradient(800, 1000, 500, 800, 1000, 1500);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(0,0,0,0.75)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);
}

function addTexture() {
  noStroke();

  for (let i = 0; i < 600; i++) {
    let x = random(width);
    let y = random(height);
    let alpha = random(3, 10);
    let c = floor(random(3));
    if (c === 0) fill(255, 255, 255, alpha);
    else if (c === 1) fill(0, 0, 0, alpha);
    else fill(150, 110, 90, alpha);
    ellipse(x, y, random(1, 3));
  }

  for (let i = 0; i < 180; i++) {
    let x = random(width);
    let y = random(height);
    let w = random(40, 140);
    let h = random(8, 22);
    let a = random(PI);
    let alpha = random(2, 8);
    fill(255, 240, 220, alpha);
    push();
    translate(x, y);
    rotate(a);
    ellipse(0, 0, w, h);
    pop();
  }

  for (let i = 0; i < 120; i++) {
    let x = random(width);
    let y = random(height);
    let w = random(30, 100);
    let h = random(6, 18);
    let a = random(PI);
    let alpha = random(2, 6);
    fill(30, 15, 10, alpha);
    push();
    translate(x, y);
    rotate(a);
    ellipse(0, 0, w, h);
    pop();
  }
}

function setup() {
  createCanvas(1600, 2000);
  randomSeed(1);
  noiseSeed(1);
  noLoop();
}

function draw() {
  drawSky();
  drawMoon(800, 430, 240);
  drawBirds();
  drawMountains();
  drawWater();
  drawBank();
  drawBackGlow();
  drawTree();
  drawBoatAndFigure();
  drawScythe();
  drawMist();
  drawGrain();
}

function drawSky() {
  noStroke();
  for (let y = 0; y < 1100; y++) {
    let t = y / 1100;
    let c = lerpColor(color(18, 27, 48), color(2, 3, 7), t);
    stroke(c);
    line(0, y, width, y);
  }
}

function drawMoon(cx, cy, r) {
  noStroke();
  for (let i = r * 2; i > 0; i -= 2) {
    let a = map(i, 0, r * 2, 0, 24);
    fill(215, 220, 215, a);
    ellipse(cx, cy, r * 2 + i, r * 2 + i);
  }
  fill(232, 230, 218, 255);
  ellipse(cx, cy, r * 2, r * 2);
  fill(205, 205, 195, 60);
  ellipse(cx - 60, cy - 30, 50, 40);
  ellipse(cx + 50, cy + 60, 70, 55);
  ellipse(cx + 30, cy - 90, 40, 35);
}

function drawBirds() {
  stroke(3, 4, 7, 220);
