  noFill();
  line(300, 300, 320, 288);
  line(300, 300, 280, 294);
  line(370, 340, 390, 328);
  line(370, 340, 350, 334);
  line(250, 360, 270, 348);
  line(250, 360, 230, 354);
}

function drawMountains() {
  noStroke();
  fill(20, 25, 36, 230);
  beginShape();
  vertex(0, 1100);
  for (let x = 0; x <= width; x += 8) {
    let y = 1100 - noise(x * 0.002) * 280 - 40;
    vertex(x, y);
  }
  vertex(width, 1100);
  endShape(CLOSE);

  fill(12, 16, 25, 240);
  beginShape();
  vertex(0, 1100);
  for (let x = 0; x <= width; x += 8) {
    let y = 1100 - noise(100 + x * 0.003) * 180 - 20;
    vertex(x, y);
  }
  vertex(width, 1100);
  endShape(CLOSE);
}

function drawWater() {
  noStroke();
  for (let y = 1100; y < height; y++) {
    let t = (y - 1100) / (height - 1100);
    let c = lerpColor(color(11, 16, 24), color(1, 2, 5), t);
    stroke(c);
    line(0, y, width, y);
  }

  for (let i = 0; i < 420; i++) {
    let y = random(1100, height);
    let x = 800 + random(-160, 160);
    let len = random(30, 120);
    let alpha = map(abs(x - 800), 0, 180, 55, 5);
    stroke(210, 220, 230, alpha * random(0.4, 1));
    strokeWeight(1);
    line(x, y, x + random(-1, 1) * len, y + random(-1, 1));
