function drawBank() {
  fill(6, 8, 12, 250);
  noStroke();
  beginShape();
  vertex(0, 1080);
  vertex(280, 1080);
  vertex(300, 1120);
  vertex(260, 1150);
  vertex(0, 1170);
  endShape(CLOSE);
}

function drawBackGlow() {
  noStroke();
  for (let i = 0; i < 10; i++) {
    fill(190, 200, 210, map(i, 0, 10, 12, 0));
    ellipse(800, 1220, 320 + i * 30, 420 + i * 40);
  }
}

function drawTree() {
  stroke(5, 7, 10, 235);
  noFill();
  branch(200, 1100, 190, -PI / 2, 8);
}

function branch(x, y, len, angle, depth) {
  if (depth <= 0 || len < 4) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  strokeWeight(map(depth, 0, 8, 0.5, 8));
  stroke(7, 9, 12, 220);
  line(x, y, x2, y2);

  let n = int(random(2, 4));
  for (let i = 0; i < n; i++) {
    let spread = random(0.3, 0.75);
    let newAngle = angle + random(-spread, spread);
    if (newAngle > -0.3) newAngle = -0.3;
    if (newAngle < -PI + 0.3) newAngle = -PI + 0.3;
    let newLen = len * random(0.55, 0.78);
    branch(x2, y2, newLen, newAngle, depth - 1);
  }
}

