// Vanité : crâne, cire mourante, fumée — clair-obscur peint au geste.
const CX = 1042, CTOP = 706, CBASE = 1498, CW = 80;
const BX = CX - 2, BY = CTOP - 38;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  noLoop();
  pixelDensity(1);
  strokeCap(ROUND);

  const W = 1600, H = 2000;
  background(6, 7, 11);
  noStroke();

  // --- fond : nuit peinte, réchauffée seulement près de la flamme ---
  for (let i = 0; i < 2600; i++) {
    let x = random(W), y = random(H * 0.84);
    let n = noise(x * 0.0012, y * 0.0012);
    let d = dist(x, y, BX, BY - 40);
    let warm = constrain(1 - d / 1150, 0, 1); warm *= warm;
    let c = mix3([11 + n * 9, 13 + n * 9, 21 + n * 11], [54, 31, 14], warm * 0.9);
    daub(x, y, random(70, 190), random(14, 42),
      (noise(x * 0.002, y * 0.002) - 0.5) * 0.9, c, 9 + warm * 16);
  }

  // --- table ---
  for (let i = 0; i < 1500; i++) {
    let x = random(W), y = random(1522, H);
    let d1 = dist(x, y, CX, 1500);
    let warm = constrain(1 - d1 / 820, 0, 1); warm *= warm;
    let n = noise(x * 0.003, y * 0.004);
    let c = mix3([13 + n * 8, 10 + n * 6, 9], [98, 60, 25], warm);
    daub(x, y, random(70, 220), random(8, 22),
      (noise(x * 0.004, y * 0.004) - 0.5) * 0.25, c, 16 + warm * 22);
  }
  for (let x = 0; x < W; x += random(8, 20)) {
    let warm = constrain(1 - abs(x - CX) / 760, 0, 1);
    daub(x, 1520 + random(-3, 3), random(16, 34), random(4, 8), 0,
      mix3([24, 20, 18], [192, 142, 80], warm * warm), 26 + warm * 60);
  }

  // --- ombres portées, vers la gauche (la lumière vient de la droite) ---
  for (let i = 0; i < 120; i++) {
    daub(random(300, 640), random(1496, 1540), random(60, 160), random(10, 26), 0, [3, 3, 5], 16 + random(14));
  }
  for (let i = 0; i < 90; i++) {
    daub(random(820, 1030), random(1516, 1560), random(50, 140), random(8, 20), 0, [3, 3, 5], 14 + random(10));
  }

  // --- crâne : masses ---
  fill(88, 79, 71); ellipse(560, 1278, 356, 336);
  fill(80, 72, 64); ellipse(560, 1400, 252, 170);
  fill(74, 66, 60); ellipse(560, 1462, 192, 112);

  // --- crâne : modelé, côté droit allumé par la flamme ---
  for (let i = 0; i < 2300; i++) {
    let a = random(TWO_PI);
    let rr = pow(random(), 0.5);
    let x = 560 + cos(a) * 178 * rr;
    let y = 1278 + sin(a) * 168 * rr;
    let lit = constrain(0.5 + cos(a) * 0.75 + (1278 - y) / 400 * 0.25, 0, 1);
    let c = lit > 0.55
      ? mix3([120, 104, 88], [234, 206, 166], map(lit, 0.55, 1, 0, 1))
      : mix3([14, 15, 22], [120, 104, 88], map(lit, 0, 0.55, 0, 1));
    daub(x, y, random(14, 34), random(5, 12), a + HALF_PI + (random() - 0.5) * 0.4, c, 20 + random(20));
  }
  for (let i = 0; i < 900; i++) {
    let a = random(TWO_PI), rr = pow(random(), 0.5);
    let x = 560 + cos(a) * 120 * rr, y = 1408 + sin(a) * 96 * rr;
    let lit = constrain(0.5 + cos(a) * 0.7, 0, 1);
    let c = lit > 0.5
      ? mix3([110, 96, 82], [208, 180, 142], map(lit, 0.5, 1, 0, 1))
      : mix3([12, 13, 19], [110, 96, 82], map(lit, 0, 0.5, 0, 1));
    daub(x, y, random(10, 26), random(4, 10), a + HALF_PI, c, 18 + random(18));
  }
  // liseré froid sur le bord gauche, reflet de la nuit
  for (let i = 0; i < 90; i++) {
    let a = random(PI * 0.7, PI * 1.35);
    daub(560 + cos(a) * 176, 1278 + sin(a) * 166, random(10, 22), random(4, 8), a + HALF_PI, [64, 76, 104], 20);
  }

  // orbites, nez, dents
  socket(502, 1306, 76, 62);
  socket(630, 1300, 70, 56);
  fill(12, 12, 14);
  triangle(564, 1344, 544, 1392, 584, 1392);
  ellipse(554, 1374, 24, 38); ellipse(576, 1374, 24, 38);
  fill(46, 38, 34); ellipse(560, 1462, 176, 52);
  for (let k = 0; k < 8; k++) {
    let tx = 486 + k * 21;
    let lit = map(tx, 480, 650, 0.15, 1);
    let c = mix3([52, 46, 42], [224, 200, 164], lit);
    fill(c[0], c[1], c[2]); rect(tx, 1444, 16, random(30, 40), 7);
    fill(16, 14, 14); rect(tx + 16, 1446, 3, 30);
  }
  // fêlure du sommet
  let fx0 = 598, fy0 = 1116;
  for (let s = 0; s < 26; s++) {
    fx0 += (noise(s * 0.35) - 0.5) * 9 + 1.2;
    fy0 += 6.2;
    daub(fx0, fy0, random(3, 5.5), random(6, 11), 0.2, [18, 16, 16], 90);
  }

  // --- bougeoir et cierge ---
  fill(24, 18, 14); ellipse(CX, 1516, 336, 78);
  fill(34, 26, 18); ellipse(CX, 1508, 300, 62);
  for (let i = 0; i < 60; i++) {
    let a = random(-0.6, 1.1);
    daub(CX + cos(a) * 158, 1512 + sin(a) * 34, random(14, 30), random(4, 8), a * 0.3, [198, 142, 74], 40 + random(30));
  }
  for (let i = 0; i < 1600; i++) {
    let y = random(CTOP + 6, CBASE);
    let xo = random() * 2 - 1;
    let x = CX + xo * CW;
    let edge = 1 - abs(xo);
    let hgt = map(y, CTOP, CBASE, 1, 0.12);
    let br = constrain((0.3 + 0.7 * edge) * (0.25 + 0.75 * hgt), 0, 1);
    daub(x, y, random(9, 20), random(34, 86), (random() - 0.5) * 0.06,
      mix3([30, 26, 26], [240, 222, 186], br), 26 + br * 34);
  }
  for (let i = 0; i < 220; i++) {
    let y = random(CTOP, CTOP + 300);
    let sx2 = random() < 0.5 ? CX - CW + random(8) : CX + CW - random(8);
    let fade = map(y, CTOP, CTOP + 300, 1, 0);
    daub(sx2, y, random(6, 12), random(20, 60), 0, [255, 214, 150], 10 + 30 * fade);
  }
  drip(CX - CW + 7, CTOP + 22, 190, 24);
  drip(CX + CW - 9, CTOP + 48, 120, 19);
  drip(CX - CW + 26, CTOP + 10, 84, 15);
  drip(CX + CW - 30, CTOP + 16, 60, 13);
  fill(214, 196, 160); ellipse(CX, CTOP, CW * 2 + 10, 50);
  fill(255, 238, 196); ellipse(CX, CTOP + 2, CW * 2 - 16, 36);
  fill(255, 224, 150, 120); ellipse(CX, CTOP + 3, CW * 1.3, 24);

  // mèche
  stroke(28, 20, 16); strokeWeight(7);
  line(CX, CTOP - 2, BX, BY + 4);
  noStroke();
  fill(255, 150, 60, 220); ellipse(BX, BY + 2, 7, 7);

  // --- halos (lumière qui respire sur les objets) ---
  blendMode(ADD);
  glow(BX - 8, 600, 680, [255, 120, 40], 16);
  glow(BX - 8, 600, 360, [255, 170, 70], 22);
  glow(BX - 4, 620, 170, [255, 214, 120], 30);
  glow(CX, 1516, 300, [255, 150, 60], 10);
  glow(660, 1330, 260, [255, 140, 60], 7);
  blendMode(BLEND);

  // --- flamme ployée, déjà penchée vers sa fin ---
  push();
  translate(BX, BY); rotate(-0.20);
  noStroke();
  fill(233, 96, 20, 200); ellipse(0, 2, 54, 40);
  tear(0, 0, 60, 152, [255, 118, 24], 235);
  tear(0, -4, 46, 128, [255, 160, 40], 230);
  tear(0, -9, 33, 102, [255, 203, 84], 240);
  tear(0, -13, 21, 76, [255, 238, 168], 245);
  tear(0, -16, 11, 48, [255, 251, 226], 255);
  fill(96, 124, 205, 150); ellipse(0, 6, 34, 26);
  fill(156, 186, 240, 130); ellipse(0, 4, 20, 15);
  pop();
  fill(255, 160, 70, 120); ellipse(BX - 46, 470, 11, 11);
  fill(255, 196, 96, 210); ellipse(BX - 46, 470, 5, 5);

  // --- fumée : le souffle qui monte et se délie ---
  let tx0 = 1010, ty0 = 520, yy = ty0;
  for (let i = 0; i < 230 && yy > -60; i++) {
    yy -= random(2.0, 3.4);
    let t = constrain((ty0 - yy) / (ty0 + 90), 0, 1);
    let wob = (noise(i * 0.05) - 0.5) * 2;
    let big = sin(t * 5.2 + 0.6) * (30 + t * 110);
    let x = tx0 + wob * (14 + t * 120) + big * t;
    let wdt = 6 + t * 86;
    let c = mix3([168, 150, 132], [96, 106, 124], constrain(t * 1.6, 0, 1));
    daub(x, yy, wdt, wdt * random(0.5, 0.8), (noise(i * 0.1) - 0.5) * 1.4, c, (1 - t) * 34 + 4);
  }
  wisp(tx0 + 46, ty0 - 180, 1, 62);
  wisp(tx0 - 72, ty0 - 330, -1, 78);

  // poussières et cendres en suspens
  for (let i = 0; i < 160; i++) {
    let x = random(W), y = random(H * 0.75);
    let d = dist(x, y, BX, 600);
    if (random() < 0.5 && d > 500) continue;
    let warm = constrain(1 - d / 700, 0, 1);
    let c = mix3([120, 126, 138], [255, 180, 90], warm);
    fill(c[0], c[1], c[2], 14 + warm * 70 * random());
    ellipse(x, y, random(1.2, 4.2));
  }

  // --- vignettage profond ---
  noStroke();
  for (let i = 0; i < 110; i++) {
    let t = i / 110;
    let a = 11 * (1 - t) * (1 - t);
    fill(2, 3, 6, a);
    rect(0, 0, W, t * 340);
    rect(0, H - t * 300, W, t * 300);
    rect(0, 0, t * 260, H);
    rect(W - t * 260, 0, t * 260, H);
  }
  darkCorner(0, 0, 700, 120);
  darkCorner(W, 0, 700, 120);
  darkCorner(0, H, 620, 90);
  darkCorner(W, H, 620, 90);

  // --- grain de toile ---
  for (let i = 0; i < 8000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.5) fill(255, 250, 240, random(3, 9));
    else fill(0, 0, 5, random(4, 12));
    rect(x, y, random(1, 2.6), random(1, 2.6));
  }
}

function mix3(a, b, t) {
  t = constrain(t, 0, 1);
  return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t];
}

function daub(x, y, w, h, ang, c, a) {
  push();
  translate(x, y); rotate(ang);
  noStroke(); fill(c[0], c[1], c[2], a);
  ellipse(0, 0, w, h);
  pop();
}

function glow(x, y, r, c, aMax) {
  noStroke();
  let prev = r;
  for (let rr = r; rr > 4; rr *= 0.93) {
    let a = aMax * (sq(1 - rr / r) - sq(1 - prev / r));
    fill(c[0], c[1], c[2], constrain(a, 0, 255));
    ellipse(x, y, rr * 2, rr * 2);
    prev = rr;
  }
}

function darkCorner(x, y, r, aMax) {
  let prev = r;
  for (let rr = r; rr > 20; rr *= 0.94) {
    let a = aMax * (sq(1 - rr / r) - sq(1 - prev / r));
    fill(2, 3, 6, constrain(a, 0, 255));
    ellipse(x, y, rr * 2, rr * 2);
    prev = rr;
  }
}

function tear(x, y, w, h, c, a) {
  fill(c[0], c[1], c[2], a);
  beginShape();
  vertex(x, y);
  bezierVertex(x - w * 0.66, y - h * 0.30, x - w * 0.52, y - h * 0.66, x - w * 0.06, y - h);
  bezierVertex(x + w * 0.10, y - h * 0.98, x + w * 0.55, y - h * 0.62, x + w * 0.62, y - h * 0.28);
  bezierVertex(x + w * 0.55, y - h * 0.10, x + w * 0.30, y, x, y);
  endShape(CLOSE);
}

function socket(x, y, w, h) {
  fill(9, 9, 12);
  ellipse(x, y, w, h);
  for (let k = 0; k < 14; k++) {
    let a = random(0.15, 0.85) * PI;
    daub(x + cos(a) * w * 0.5 * random(0.85, 1.02),
      y + sin(a) * h * 0.5 * random(0.85, 1.02),
      random(8, 16), random(3, 6), a, [168, 138, 104], 26 + random(20));
  }
}

function drip(x, y0, len, w) {
  let y = y0;
  while (y < y0 + len) {
    let t = (y - y0) / len;
    let ww = w * (1 - t * 0.55);
    let br = map(y, CTOP, CBASE, 1, 0.2);
    daub(x + (noise(y * 0.05) - 0.5) * 4, y, ww, random(12, 20), 0,
      mix3([40, 34, 32], [244, 226, 192], br), 120);
    y += random(6, 10);
  }
  daub(x, y0 + len, w * 0.95, w * 0.8, 0,
    mix3([46, 40, 36], [248, 232, 198], map(y0 + len, CTOP, CBASE, 0.95, 0.3)), 160);
}

function wisp(x, y, dir, size) {
  for (let k = 0; k < 26; k++) {
    let a = k * 0.22 * dir + 1.2;
    let rr = size * (k / 26);
    daub(x + cos(a) * rr, y + sin(a) * rr * 0.8 - k * 1.2,
      10 + k * 1.1, 7 + k * 0.7, a, [110, 118, 132], 22 - k * 0.6);
  }
}

// « La lumière qui reste » — huile numérique sur toile, 1600 × 2000 (p5.js 1.11)
let W = 1600, H = 2000;
let ctx;
const FL = [300, 1418], FR = [1335, 1348], BR = [1295, 1252], BL = [345, 1318];

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();
  ctx = drawingContext;
  noStroke();

  baseWash();
  smoke();
  ground();
  slab();
  drape();
  body();
  skull();
  petalsGround();
  lightShaft();
  dust();
  driftingPetal();
  vignette();
  grain();
  cracks();
}

function rgba(c, a) { return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a + ')'; }
function mixc(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function lerp2(a, b, d, c, t, u) { return lerp(lerp(a, b, t), lerp(d, c, t), u); }
function lightAt(x) { return Math.exp(-Math.pow((x - 560) / 300, 2)); }

function dab(x, y, w, h, ang, c, a) {
  if (w <= 0.2 || h <= 0.2) return;
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(ang);
  ctx.fillStyle = rgba(c, a);
  ctx.beginPath();
  ctx.ellipse(0, 0, w, h, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();
}

function brush(x, y, ang, len, w, c, a) {
  const n = Math.max(2, Math.floor(len / Math.max(6, w * 1.2)));
  const nx = x * 0.013, ny = y * 0.011;
  for (let i = 0; i <= n; i++) {
    const t = i / n;
    const j = (noise(nx + t * 2.1, ny) - 0.5) * w * 0.9;
    const px = x + Math.cos(ang) * len * t - Math.sin(ang) * j;
    const py = y + Math.sin(ang) * len * t + Math.cos(ang) * j;
    const ww = w * (0.65 + 0.55 * noise(t * 3.7 + nx, ny + 4.2));
    const col = mixc(c, [Math.min(255, c[0] + 16), Math.min(255, c[1] + 14), Math.min(255, c[2] + 12)], noise(t * 5 + nx, ny));
    dab(px, py, ww, ww * (0.4 + 0.35 * noise(t * 4 + ny, nx)), ang + (noise(t * 6, nx) - 0.5) * 0.6, col, a * (0.55 + 0.55 * noise(t * 7 + ny, nx)));
  }
}

function poly(pts, c) {
  ctx.beginPath();
  ctx.moveTo(pts[0][0], pts[0][1]);
  for (let i = 1; i < pts.length; i++) ctx.lineTo(pts[i][0], pts[i][1]);
  ctx.closePath();
  ctx.fillStyle = rgba(c, 1);
  ctx.fill();
}

function baseWash() {
  ctx.fillStyle = 'rgb(10,9,11)';
  ctx.fillRect(0, 0, W, H);
  for (let i = 0; i < 480; i++) {
    const x = random(W), y = random(H * 0.76);
    const l = Math.max(0, 1 - Math.hypot(x - 240, y - 80) / 1900);
    const ang = (noise(x * 0.002, y * 0.002) - 0.5) * 0.9;
    const col = mixc([14, 12, 15], [46, 44, 52], l * (0.5 + noise(x * 0.003, y * 0.003) * 0.5));
    brush(x, y, ang, random(120, 360), random(26, 60), col, random(0.05, 0.12));
  }
  for (let i = 0; i < 60; i++) {
    const r = random(60, 420), a = random(Math.PI * 2);
    dab(170 + Math.cos(a) * r * 0.8, 40 + Math.sin(a) * r * 0.5, random(30, 80), random(18, 40), random(-0.4, 0.4), [150, 155, 165], 0.012);
  }
}

function smoke() {
  const starts = [[330, 1290], [420, 1268], [515, 1250], [260, 1310]];
  for (let s = 0; s < starts.length; s++) {
    let x = starts[s][0], y = starts[s][1];
    for (let i = 0; i < 130 && y > 50; i++) {
      const t = i / 130;
      x += (noise(x * 0.004, y * 0.004) - 0.5) * 17;
      y -= random(4, 8);
      dab(x, y, random(6, 15) * (1 + t * 2.4), random(4, 9) * (1 + t * 2), (noise(x * 0.01, y * 0.01) - 0.5) * 2, [122, 124, 132], 0.02 * (1 - t * 0.65));
    }
  }
}

function ground() {
  const hor = 1400;
  for (let i = 0; i < 60; i++) brush(random(W), hor + random(-16, 22), random(-0.15, 0.15), random(120, 300), random(10, 18), [64, 62, 66], 0.05);
  for (let i = 0; i < 480; i++) {
    const y = hor + Math.pow(random(), 1.4) * (H - hor);
    const x = random(W);
    const depth = (y - hor) / (H - hor);
    const col = mixc([24, 20, 17], [58, 47, 36], noise(x * 0.004, y * 0.004) * (0.35 + depth * 0.4));
    brush(x, y, (noise(x * 0.003, y * 0.005) - 0.5) * 0.5, random(60, 170) * (0.6 + depth), random(12, 22), col, random(0.08, 0.2));
  }
  for (let i = 0; i < 90; i++) dab(random(120, 360), random(1480, 1720), random(20, 50), random(8, 16), random(-0.2, 0.2), [150, 150, 148], 0.02);
}

function slab() {
  poly([FL, FR, [FR[0], FR[1] + 112], [FL[0], FL[1] + 112]], [26, 22, 20]);
  poly([FL, FR, BR, BL], [44, 38, 33]);
  const angBase = Math.atan2(FR[1] - FL[1], FR[0] - FL[0]);
  for (let i = 0; i < 380; i++) {
    const t = random(), u = random();
    const x = lerp2(FL[0], FR[0], BL[0], BR[0], t, u);
    const y = lerp2(FL[1], FR[1], BL[1], BR[1], t, u);
    const lit = lightAt(x);
    const col = mixc([38, 33, 29], [98, 92, 82], Math.min(1, lit * 0.85 * (0.4 + noise(x * 0.01, y * 0.01)) + 0.08));
    brush(x, y, angBase + (noise(x * 0.01, y * 0.01) - 0.5) * 0.4, random(40, 150), random(7, 14), col, random(0.06, 0.16));
  }
  for (let i = 0; i < 200; i++) {
    const t = random();
    const x = lerp(FL[0], FR[0], t);
    const y = lerp(FL[1], FR[1], t) + random(8, 106);
    brush(x, y, 0.03 + (noise(x * 0.02, y * 0.02) - 0.5) * 0.3, random(30, 110), random(7, 13), mixc([20, 17, 15], [46, 38, 32], noise(x * 0.01, y * 0.01) * 0.6), random(0.08, 0.18));
  }
  for (let t = 0.05; t < 0.6; t += 0.012) {
    const x = lerp(FL[0], FR[0], t), y = lerp(FL[1], FR[1], t);
    const lit = lightAt(x);
    if (lit > 0.1) dab(x, y, 8, 3, 0, [172, 170, 160], 0.15 * lit);
  }
  for (let i = 0; i < 150; i++) {
    const t = random();
    const x = lerp(FL[0] - 30, FR[0] + 20, t);
    const y = lerp(FL[1], FR[1], t) + 112 + random(-6, 26);
    dab(x, y, random(20, 60), random(6, 14), 0, [8, 7, 8], 0.12);
  }
  for (let i = 0; i < 90; i++) {
    const t = random();
    brush(1330 + t * 250, lerp(1470, 1560, t) + random(-20, 60), 0.32, random(80, 200), random(10, 20), [6, 5, 6], 0.12);
  }
}

function drape() {
  const x0 = 470, x1 = 1160;
  const topY = x => lerp(FL[1], FR[1], (x - FL[0]) / (FR[0] - FL[0]));
  const hemLen = x => 110 + 60 * noise(x * 0.02) + 26 * Math.sin(x * 0.045);
  ctx.beginPath();
  ctx.moveTo(x0, topY(x0) - 4);
  for (let x = x0; x <= x1; x += 14) ctx.lineTo(x, topY(x) + hemLen(x) + 8);
  ctx.lineTo(x1, topY(x1) - 4);
  ctx.closePath();
  ctx.fillStyle = 'rgba(48,41,35,0.92)';
  ctx.fill();
  for (let x = x0 + 6; x < x1; x += 7) {
    const lit = lightAt(x);
    const bright = noise(x * 0.05) > 0.55;
    const len = hemLen(x);
    for (let y = topY(x) + 2; y < topY(x) + len; y += 6) {
      const tt = (y - topY(x)) / len;
      const sway = Math.sin(y * 0.05 + x) * 2;
      let col = mixc([34, 28, 24], [80, 70, 58], noise(x * 0.1, y * 0.05));
      if (bright) col = mixc(col, [150, 140, 122], 0.45);
      col = mixc(col, [202, 198, 184], lit * 0.55 * (1 - tt * 0.4));
      dab(x + sway, y, 4.6, 7.5, 0.06 * Math.sin(x + y * 0.02), col, 0.28);
    }
    dab(x, topY(x) + len + 5, 6, 3, 0, [10, 8, 8], 0.2);
  }
}

function body() {
  const HX = 415, HY = 1352, FX = 1240, FY = 1300;
  const hProf = x => {
    const g = (c, s, h) => h * Math.exp(-Math.pow((x - c) / s, 2));
    return 16 + g(470, 50, 78) + g(660, 62, 84) + g(800, 70, 55) + g(890, 55, 62) + g(1000, 80, 40) + g(1120, 80, 26) + g(1215, 30, 46);
  };
  const baseY = x => lerp(HY + 20, FY + 14, (x - HX) / (FX - HX));
  for (let i = 0; i < 90; i++) {
    const a = random(Math.PI * 2), r = Math.sqrt(random());
    const px = HX - 10 + Math.cos(a) * 78 * r, py = HY + 28 + Math.sin(a) * 26 * r;
    dab(px, py, random(10, 22), random(6, 12), random(-0.3, 0.3), mixc([58, 48, 40], [112, 98, 80], noise(px * 0.05, py * 0.05)), 0.25);
  }
  for (let x = 400; x < 1240; x += 8) dab(x + 4, baseY(x) + 6, 14, 4, -0.05, [8, 7, 7], 0.25);
  for (let x = 398; x <= 1244; x += 3.2) {
    const h = hProf(x), by = baseY(x), lit = lightAt(x), amb = 0.28 + 0.72 * lit;
    const nd = Math.max(6, Math.floor(h / 5.5));
    for (let j = 0; j <= nd; j++) {
      const t = j / nd;
      const py = by - h * Math.sin(t * Math.PI / 2);
      const px = x + (noise(x * 0.05, j * 0.7) - 0.5) * 4;
      let sh = Math.min(1, (0.08 + 0.85 * Math.pow(t, 1.5)) * amb + (noise(x * 0.03, j * 0.37) - 0.5) * 0.12);
      let col = mixc([22, 18, 16], [122, 112, 98], sh);
      col = mixc(col, [232, 226, 208], Math.min(0.9, Math.max(0, sh - 0.78) * 3.2));
      dab(px, py, 5.2, 6.5, (noise(x * 0.02, j) - 0.5) * 0.9, col, 0.5);
    }
  }
  for (let x = 410; x < 1240; x += 7) {
    const lit = lightAt(x);
    dab(x + (noise(x) - 0.5) * 6, baseY(x) - hProf(x) + 3, 6, 3.4, (noise(x * 0.1) - 0.5) * 0.8, mixc([140, 132, 118], [236, 230, 214], lit), 0.16 + 0.34 * lit);
  }
  const folds = [[500, 0.9], [620, -0.7], [700, 0.8], [830, -0.6], [920, 0.75], [1050, -0.5], [1140, 0.6], [1195, -0.4]];
  for (const f of folds) {
    const xF = f[0], dir = f[1], h = hProf(xF);
    for (let j = 0; j < 16; j++) {
      const t = j / 15;
      dab(xF + t * 26 * dir + (noise(j * 0.8) - 0.5) * 5, baseY(xF) - h * Math.sin(t * Math.PI / 2), 4, 6, dir * 0.5, [20, 16, 14], 0.16);
    }
  }
  for (let i = 0; i < 40; i++) {
    const a = random(Math.PI * 2), r = Math.sqrt(random());
    dab(452 + Math.cos(a) * 24 * r, 1302 + Math.sin(a) * 32 * r, random(6, 14), random(6, 12), 0, [16, 13, 12], 0.08);
  }
  for (let i = 0; i < 22; i++) {
    const a = Math.PI + i / 21 * 1.4;
    dab(468 + Math.cos(a) * 46, baseY(470) - hProf(470) + 30 + Math.sin(a) * 34, 7, 4, a, [212, 210, 198], 0.22 * lightAt(470) + 0.05);
  }
}

function skull() {
  const cx = 1112, cy = 1650;
  for (let i = 0; i < 34; i++) dab(cx + random(-16, 34), cy + 30 + random(10), random(16, 42), random(4, 8), 0, [6, 5, 6], 0.16);
  const shape = [[0, -20, 52, 44], [0, 10, 34, 22], [-30, 2, 20, 26], [30, 4, 19, 24]];
  for (const s of shape) {
    for (let i = 0; i < 70; i++) {
      const a = random(Math.PI * 2), r = Math.sqrt(random());
      const px = s[0] + Math.cos(a) * s[2] * r, py = s[1] + Math.sin(a) * s[3] * r;
      const side = constrain(0.8 - (px + 26) / 95, 0, 1);
      dab(cx + px, cy + py, random(4, 9), random(4, 8), random(-0.4, 0.4), mixc([34, 30, 26], [196, 188, 168], 0.22 + 0.6 * side), 0.5);
    }
  }
  const eyes = [[-19, -18, 13, 11], [17, -14, 12, 10]];
  for (const e of eyes) {
    for (let i = 0; i < 26; i++) {
      const a = random(Math.PI * 2), r = Math.sqrt(random());
      dab(cx + e[0] + Math.cos(a) * e[2] * r, cy + e[1] + Math.sin(a) * e[3] * r, random(3, 7), random(3, 6), 0, [9, 7, 7], 0.5);
    }
  }
  for (let i = 0; i < 14; i++) dab(cx - 1 + (noise(i * 0.9) - 0.5) * 6, cy + 4 + i * 0.8, Math.max(1.5, 4 - i * 0.15), 4, 0, [10, 8, 8], 0.5);
  for (let i = 0; i < 7; i++) {
    const tx = cx - 21 + i * 6.6;
    dab(tx, cy + 26, 2.6, 5.5, 0, [150, 142, 126], 0.6);
    dab(tx, cy + 31, 2.2, 2.6, 0, [22, 18, 16], 0.5);
  }
  for (let i = 0; i < 26; i++) {
    const a = Math.PI + i / 25 * 1.2;
    dab(cx + Math.cos(a) * 50, cy - 20 + Math.sin(a) * 42, 5, 3, a, [186, 190, 196], 0.18);
  }
}

function petal(x, y, ang, s) {
  for (let i = 0; i < 14; i++) {
    const t = i / 13;
    const w = Math.max(1, s * Math.sin(Math.PI * (0.15 + 0.85 * t)));
    dab(x + Math.cos(ang) * t * s * 2.2, y + Math.sin(ang) * t * s * 2.2, w, w * 0.6, ang + (noise(i * 0.7 + x) - 0.5), mixc([92, 26, 20], [152, 62, 40], noise(x * 0.1 + i)), 0.8);
  }
}

function petalsGround() {
  const spots = [[420, 1680], [520, 1760], [660, 1700], [760, 1830], [900, 1740], [1240, 1780], [300, 1820], [1400, 1700], [980, 1600], [560, 1560], [1180, 1880]];
  for (const s of spots) petal(s[0] + random(-14, 14), s[1] + random(-8, 8), random(-0.8, 0.8), random(10, 17));
  petal(1020, 1330, 0.4, 10);
  petal(760, 1368, -0.3, 9);
}

function lightShaft() {
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  const layers = [
    { p: [[60, -40], [520, -40], [720, 1400], [390, 1360]], a: 0.05 },
    { p: [[120, -40], [470, -40], [690, 1390], [430, 1365]], a: 0.06 },
    { p: [[180, -40], [420, -40], [650, 1380], [470, 1370]], a: 0.07 },
    { p: [[240, -40], [380, -40], [610, 1375], [500, 1372]], a: 0.08 }
  ];
  for (const L of layers) {
    ctx.beginPath();
    ctx.moveTo(L.p[0][0], L.p[0][1]);
    for (let i = 1; i < L.p.length; i++) ctx.lineTo(L.p[i][0], L.p[i][1]);
    ctx.closePath();
    ctx.fillStyle = 'rgba(190,198,208,' + L.a + ')';
    ctx.fill();
  }
  ctx.restore();
}

function dust() {
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 240; i++) {
    const t = random();
    const y = t * 1400;
    const cL = lerp(290, 555, t);
    const wd = lerp(440, 320, t);
    const x = cL + (random() - 0.5) * wd;
    ctx.fillStyle = 'rgba(215,220,228,' + (0.05 + 0.3 * Math.pow(random(), 3)) + ')';
    ctx.beginPath();
    ctx.arc(x, y, random(0.8, 2.6), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
}

function driftingPetal() {
  ctx.save();
  ctx.globalCompositeOperation = 'screen';
  for (let i = 0; i < 26; i++) {
    const a = random(Math.PI * 2), r = Math.sqrt(random()) * 30;
    ctx.fillStyle = 'rgba(205,210,220,0.045)';
    ctx.beginPath();
    ctx.arc(468 + Math.cos(a) * r, 640 + Math.sin(a) * r, random(4, 9), 0, Math.PI * 2);
    ctx.fill();
  }
  ctx.restore();
  petal(468, 640, 0.7, 12);
}

function vignette() {
  const g = ctx.createRadialGradient(W / 2, H * 0.46, H * 0.25, W / 2, H * 0.46, H * 0.85);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(1, 'rgba(2,2,4,0.82)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function grain() {
  for (let i = 0; i < 5200; i++) {
    const x = random(W), y = random(H);
    ctx.fillStyle = random() < 0.5 ? 'rgba(255,250,240,0.028)' : 'rgba(0,0,0,0.05)';
    ctx.fillRect(x, y, random(1, 2.4), random(1, 2.4));
  }
}

function cracks() {
  ctx.lineWidth = 0.7;
  ctx.strokeStyle = 'rgba(0,0,0,0.06)';
  for (let i = 0; i < 34; i++) {
    let x = random(W), y = random(H);
    let a = random(Math.PI * 2);
    ctx.beginPath();
    ctx.moveTo(x, y);
    const steps = Math.floor(random(8, 26));
    for (let s = 0; s < steps; s++) {
      a += (noise(x * 0.01, y * 0.01) - 0.5) * 1.6;
      x += Math.cos(a) * random(6, 16);
      y += Math.sin(a) * random(6, 16);
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
}

let MOON_X = 1060, MOON_Y = 430, MOON_R = 200;
let HORIZON = 1300;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  colorMode(RGB, 255);
  noLoop();
  background(6, 4, 6);

  skyBase();
  horizonGlow();
  skyVeils();
  moon();
  distantTreeline();
  ground();
  moonlightOnGround();
  backMist();
  graveyard();
  tree();
  frontMist();
  flock();
  fallenLeaves();
  ashMotes();
  vignette();
  grain();
}

function sampleStops(stops, t) {
  if (t <= stops[0][0]) return stops[0][1];
  for (let i = 0; i < stops.length - 1; i++) {
    if (t >= stops[i][0] && t <= stops[i + 1][0]) {
      let u = (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]);
      return lerpColor(stops[i][1], stops[i + 1][1], u);
    }
  }
  return stops[stops.length - 1][1];
}

function skyBase() {
  let stops = [
    [0.00, color(3, 2, 6)],
    [0.30, color(11, 7, 12)],
    [0.58, color(31, 13, 17)],
    [0.82, color(72, 23, 26)],
    [0.94, color(96, 34, 33)],
