function tree() {
  strokeCap(ROUND);
  strokeJoin(ROUND);
  for (let i = 0; i < 10; i++) {
    let side = i % 2 === 0 ? 1 : -1;
    let a = side > 0 ? random(0.12, 0.95) : PI - random(0.12, 0.95);
    rootStroke(640 + random(-26, 26), 1580 + random(-8, 8), a, random(80, 210), random(8, 19));
  }
  branch(640, 1580, -HALF_PI + 0.05, 340, 46, 0);
}

function rootStroke(x, y, ang, len, w) {
  let steps = 10;
  let px = x, py = y, pa = ang, cw = w;
  for (let i = 0; i < steps; i++) {
    let t = (i + 1) / steps;
    pa = lerp(pa, HALF_PI, 0.16) + random(-0.05, 0.05);
    let sl = len / steps;
    let nx = px + cos(pa) * sl, ny = py + sin(pa) * sl;
    cw = lerp(w, w * 0.15, t);
    barkSegment(px, py, nx, ny, cw);
    px = nx; py = ny;
  }
}

function branch(x, y, ang, len, w, depth) {
  let steps = max(4, round(len / 15));
  let px = x, py = y, pa = ang, cw = w;
  for (let i = 0; i < steps; i++) {
    let t = (i + 1) / steps;
    pa += (noise(px * 0.004, py * 0.004, depth * 13.7) - 0.5) * 0.6 + random(-0.05, 0.05);
    let sl = len / steps;
    let nx = px + cos(pa) * sl, ny = py + sin(pa) * sl;
    cw = lerp(w, w * 0.64, t);
    barkSegment(px, py, nx, ny, cw);
    px = nx; py = ny;
  }
  if (w > 16 && random() < 0.5) {
    noStroke();
    fill(6, 4, 5, 160);
    ellipse(px, py, w * 0.9, w * 0.7);
    noFill();
  }
  if (depth >= 2 && depth <= 7 && random() < 0.3) hangStrand(px, py);
  if (w < 3.2 || depth > 9) return;
  let n = w > 15 ? 3 : 2;
  if (random() < 0.16) n += 1;
  let spread = map(w, 46, 3, 0.30, 0.85);
  for (let k = 0; k < n; k++) {
    let off = n === 1 ? 0 : (k / (n - 1)) * 2 - 1;
    let ca = pa + off * spread * random(0.55, 1.15) + random(-0.10, 0.10);
    ca = lerp(ca, -HALF_PI, 0.10);
    branch(px, py, ca, len * random(0.62, 0.80), w * random(0.50, 0.62), depth + 1);
  }
  if (random() < 0.35) {
    let da = pa + (random() < 0.5 ? -1 : 1) * random(0.8, 1.5);
    branch(px, py, da, len * 0.45, w * 0.36, depth + 2);
  }
}

function barkSegment(x1, y1, x2, y2, cw) {
  stroke(13, 9, 11, 240);
  strokeWeight(cw);
  line(x1, y1, x2, y2);
  stroke(30, 21, 23, 70);
  strokeWeight(max(0.7, cw * 0.4));
  line(x1 + random(-1, 1) * cw * 0.1, y1 + random(-1, 1) * cw * 0.1,
       x2 + random(-1, 1) * cw * 0.1, y2 + random(-1, 1) * cw * 0.1);
  let mx = (x1 + x2) / 2, my = (y1 + y2) / 2;
  let d = dist(mx, my, MOON_X, MOON_Y) + 0.001;
  let ox = (MOON_X - mx) / d * cw * 0.34;
  let oy = (MOON_Y - my) / d * cw * 0.34;
  stroke(152, 143, 128, 24);
  strokeWeight(max(0.7, cw * 0.2));
  line(x1 + ox, y1 + oy, x2 + ox, y2 + oy);
}

function hangStrand(x, y) {
  let len = random(50, 160);
  let ph = random(100);
  stroke(10, 7, 9, 200);
  strokeWeight(random(0.8, 1.6));
