function band(y0, y1, c0, c1, n) {
  noStroke();
  fill(c0);
  beginShape();
  for (let x = -60; x <= W + 60; x += 60) vertex(x, edgeY(y0, x));
  for (let x = W + 60; x >= -60; x -= 60) vertex(x, edgeY(y1, x));
  endShape(CLOSE);
  for (let i = 0; i < n; i++) {
    let x = random(-20, W + 20);
    let ya = edgeY(y0, x), yb = edgeY(y1, x);
    let y = random(ya + 8, yb - 8);
    let t = constrain((y - ya) / (yb - ya), 0, 1);
    let c = lerpColor(c0, c1, t);
    let v = random(-22, 22);
    stroke(red(c) + v, green(c) + v * 0.8, blue(c) + v * 0.6, random(28, 80));
    strokeWeight(random(2.5, 6.5));
    let l = random(18, 110);
    let sl = (noise(x * 0.01, y * 0.01) - 0.5) * 10;
    line(x - l / 2, y + sl, x + l / 2, y - sl * 0.5);
  }
}

