    stroke(210, 200, 180, 26);
    strokeWeight(1.5);
    arc(x, y - s * 0.1, s * 1.1, s * 0.8, PI + 0.4, TWO_PI - 0.4);
  }
  ammonite(1245, 1815, 86, 0.30);
  ammonite(330, 1905, 52, -0.22);
  ammonite(1430, 890, 34, 1.1);
  let spots = [[520, 1740], [980, 1690], [1180, 1560], [660, 1880], [1460, 1780], [240, 1650]];
  for (let s of spots) {
    push();
    translate(s[0], s[1]);
    rotate(random(-1, 1));
    fill(214, 204, 182, random(90, 140));
    noStroke();
    let L = random(40, 90), wd = random(10, 20);
    rect(-L / 2, -wd / 2, L, wd, wd);
    ellipse(-L / 2, 0, wd * 1.6, wd * 1.9);
    ellipse(L / 2, 0, wd * 1.5, wd * 1.7);
    pop();
  }
}

function ammonite(cx, cy, R, rot) {
  push();
  translate(cx, cy);
  rotate(rot);
  let b = 0.20, th = 0, r = 2.5;
  noFill();
  while (r < R) {
    let x = cos(th) * r, y = sin(th) * r;
    stroke(222, 210, 186, random(50, 110));
    strokeWeight(map(r, 2.5, R, 1.2, 3.4));
    point(x, y);
    point(x + random(-1, 1), y + random(-1, 1));
    th += 0.09;
    r = 2.5 * exp(b * th);
  }
  for (let t2 = 3; t2 < th; t2 += 0.55) {
    let r1 = 2.5 * exp(b * t2), r2 = 2.5 * exp(b * (t2 + TWO_PI));
    if (r2 > R) break;
    stroke(222, 210, 186, 40);
    strokeWeight(1);
    line(cos(t2) * r1, sin(t2) * r1, cos(t2) * r2, sin(t2) * r2);
  }
  pop();
}

function insideBody(x, y) {
  for (let b of BODY) {
    let dx = x - b[0], dy = y - b[1];
    let u = (dx * cos(b[4]) + dy * sin(b[4])) / (b[2] / 2);
    let v = (-dx * sin(b[4]) + dy * cos(b[4])) / (b[3] / 2);
    if (u * u + v * v <= 1) return true;
  }
  return false;
}

function figure() {
  let cx = 770, cy = 1330;
  noStroke();
  for (let r = 520; r > 150; r -= 12) {
    let t = map(r, 520, 150, 0, 1);
    fill(214, 178, 108, 2.5 + t * 4.5);
    ellipse(cx, cy - 10, r * 2, r * 1.78);
  }
  push();
  translate(cx, cy);
  noStroke();
  for (let b of BODY) {
    fill(236, 228, 208, 55);
    push();
    translate(b[0], b[1]);
    rotate(b[4]);
    ellipse(0, 0, b[2] * 1.1, b[3] * 1.1);
    pop();
  }
  for (let pass = 0; pass < 3; pass++) {
    for (let b of BODY) {
      let rr = random(-8, 6);
      fill(232 + rr, 224 + rr, 205 + rr, pass === 2 ? 235 : 110);
      push();
      translate(b[0] + random(-4, 4), b[1] + random(-4, 4));
      rotate(b[4] + random(-0.05, 0.05));
      ellipse(0, 0, b[2] * random(0.96, 1.03), b[3] * random(0.96, 1.03));
      pop();
    }
  }
  noStroke();
  fill(158, 120, 80, 46);
  push();
  translate(52, -86);
  rotate(0.3);
  ellipse(0, 0, 150, 66);
  pop();
  for (let i = 0; i < 850; i++) {
    let x = random(-210, 200), y = random(-230, 300);
    if (!insideBody(x, y)) continue;
    let d = x + y * 0.45;
    let col;
    if (d < -60) col = random() < 0.75 ? [126, 90, 58] : [88, 86, 114];
    else if (d > 70) col = [253, 248, 233];
    else col = [210, 196, 170];
    stroke(col[0], col[1], col[2], random(16, 42));
    strokeWeight(random(1.6, 3.6));
    let l = random(7, 24), a = 0.55 + random(-0.25, 0.25);
    line(x, y, x + cos(a) * l, y + sin(a) * l);
  }
  noFill();
  stroke(120, 82, 50, 84);
  strokeWeight(2.6);
  bezier(-176, 64, -152, -72, -40, -164, 66, -200);
  stroke(120, 82, 50, 60);
  strokeWeight(2.2);
  bezier(18, 58, 74, 84, 86, 132, 58, 176);
  stroke(96, 68, 46, 140);
  strokeWeight(2.6);
  arc(112, -146, 30, 26, PI * 0.15, PI * 0.85);
  pop();
  for (let i = 0; i < 300; i++) {
    let b = random(BODY);
    let a = random(TWO_PI);
    let rx = cx + b[0] + cos(a) * b[2] * 0.5;
    let ry = cy + b[1] + sin(a) * b[3] * 0.5;
    let t = random();
    stroke(lerp(60, 110, t), lerp(38, 68, t), lerp(22, 32, t), random(50, 130));
    strokeWeight(random(2, 5));
    let l = random(6, 20), aa = a + random(-0.7, 0.7);
    line(rx, ry, rx + cos(aa) * l, ry + sin(aa) * l);
  }
}

function buildStalks() {
  for (let i = 0; i < 150; i++) {
    let x = random(-10, 1610);
    let gy = groundY(x) + random(-2, 4);
    let h = random(100, 250) * (noise(i * 0.7) * 0.6 + 0.7);
    let lean = (noise(i * 1.3) - 0.5) * 0.9;
    STALKS.push({ x: x, gy: gy, h: h, lean: lean, glow: random() < 0.3, ci: floor(random(3)) });
  }
  let bi = 0, bd = 1e9;
  for (let i = 0; i < STALKS.length; i++) {
    let d = abs(STALKS[i].x - 800);
    if (d < bd) { bd = d; bi = i; }
  }
  STALKS[bi].glow = true;
  STALKS[bi].h = max(STALKS[bi].h, 210);
}

function wheatRoots() {
  for (let s of STALKS) {
    for (let k = 0; k < 3; k++) {
      stroke(196, 178, 140, 55);
      strokeWeight(1.2);
      noFill();
      let a = HALF_PI + random(-0.7, 0.7);
      let rl = random(24, 60);
      bezier(s.x, s.gy,
        s.x + cos(a) * rl * 0.4, s.gy + sin(a) * rl * 0.5,
        s.x + cos(a) * rl * 0.7, s.gy + sin(a) * rl * 0.8,
        s.x + cos(a) * rl, s.gy + sin(a) * rl * 0.9);
    }
  }
}

function mycelium() {
  let cx = 770, cy = 1330;
  let origins = [
    [70, -10, -0.35], [104, -118, -1.05], [-30, -150, -1.95], [-160, -40, 2.95],
    [-150, 150, 2.45], [30, 240, 1.45], [150, 190, 0.85], [130, 10, -0.15],
    [-80, 230, 1.9], [170, -60, -0.6]
  ];
  for (let o of origins) {
    tendril(cx + o[0], cy + o[1], o[2] + random(-0.3, 0.3), random(200, 420), random(2.4, 3.6), 3);
  }
  for (let i = 0; i < 6; i++) {
    strandUp(cx + random(-160, 160), cy + random(-160, 60), random(120, 1480));
  }
  strandUp(cx + 40, cy - 60, 800);
  for (let i = 0; i < 4; i++) {
    tendril(cx + random(-140, 140), cy + random(120, 240), HALF_PI + random(-0.5, 0.5), random(260, 430), random(2, 3), 2);
  }
}

function tendril(x, y, ang, len, w, depth) {
  let pts = [];
  let px = x, py = y, a = ang;
  let step = 7, n = ceil(len / step);
  for (let i = 0; i < n; i++) {
    a += (noise(px * 0.006, py * 0.006) - 0.5) * 0.85;
    px += cos(a) * step;
    py += sin(a) * step;
    pts.push([px, py]);
    if (py < 560 || py > 1990 || px < 10 || px > 1590) break;
  }
  drawTendril(pts, w);
  if (depth > 0 && pts.length > 6) {
    let nb = random() < 0.75 ? 2 : 1;
    for (let k = 0; k < nb; k++) {
      let idx = floor(random(pts.length * 0.3, pts.length * 0.95));
      let tp = pts[idx];
      if (!tp) continue;
      let side = random() < 0.5 ? -1 : 1;
      tendril(tp[0], tp[1], a + side * random(0.5, 1.2), len * random(0.45, 0.6), w * 0.62, depth - 1);
    }
  }
  noStroke();
  for (let i = 6; i < pts.length; i += 9) {
    if (random() < 0.3) {
      fill(238, 206, 130, random(80, 170));
      ellipse(pts[i][0], pts[i][1], random(2.5, 5), random(2.5, 5));
    }
  }
}

function drawTendril(pts, w) {
  for (let i = 1; i < pts.length; i++) {
    let t = i / pts.length;
    stroke(216, 169, 78, 30 * (1 - t * 0.5));
    strokeWeight(w * 3.2 * (1 - t * 0.5));
    line(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]);
    stroke(240, 206, 128, 210 * (1 - t * 0.6));
    strokeWeight(max(0.7, w * (1 - t * 0.6)));
    line(pts[i - 1][0], pts[i - 1][1], pts[i][0], pts[i][1]);
  }
}

function strandUp(x, y, tx) {
  let pts = [];
  let px = x, py = y;
  let steps = ceil((y - 560) / 6);
  for (let i = 0; i < steps; i++) {
    px += (tx - px) * 0.02 + (noise(px * 0.005, py * 0.005) - 0.5) * 7;
    py -= 6;
    pts.push([px, py]);
    if (py <= 566) break;
  }
  if (pts.length === 0) return;
  drawTendril(pts, 2.2);
  let e = pts[pts.length - 1];
  noStroke();
  fill(240, 210, 135, 60);
  ellipse(e[0], e[1], 18, 18);
  fill(240, 210, 135, 200);
  ellipse(e[0], e[1], 7, 7);
}

function wheatStalks() {
  noStroke();
  for (let i = 0; i < 26; i++) {
    fill(190, 150, 80, 6);
    rect(0, groundY(800) - 40 + i * 2, W, 3);
  }
  for (let i = 0; i < 260; i++) {
    let x = random(W), gy = groundY(x) + random(2, 10);
    let h = random(26, 90), ln = random(-0.4, 0.4);
    stroke(20, 22, 12, random(120, 200));
    strokeWeight(random(1, 2.4));
    noFill();
    bezier(x, gy, x + ln * h * 0.3, gy - h * 0.4, x + ln * h * 0.7, gy - h * 0.8, x + ln * h, gy - h);
  }
  for (let s of STALKS) {
    let tipX = s.x + s.lean * s.h, tipY = s.gy - s.h;
    let c = WCOLS[s.ci];
    stroke(c[0], c[1], c[2]);
    strokeWeight(random(1.8, 2.8));
    noFill();
    bezier(s.x, s.gy, s.x + s.lean * s.h * 0.2, s.gy - s.h * 0.35, s.x + s.lean * s.h * 0.6, s.gy - s.h * 0.75, tipX, tipY);
    let ang = atan2((tipY - 14) - (s.gy - s.h * 0.72), tipX - (s.x + s.lean * s.h * 0.6));
    if (s.glow) {
      noStroke();
      fill(230, 190, 100, 26);
      ellipse(tipX, tipY - 16, 62, 84);
    }
    let nG = floor(random(6, 9));
    for (let gI = 0; gI < nG; gI++) {
      let t = gI / nG;
      let bx = lerp(s.x + s.lean * s.h * 0.6, tipX, t);
      let by = lerp(s.gy - s.h * 0.72, tipY - 14, t);
      let side = (gI % 2 === 0) ? 1 : -1;
      let gcol = s.glow ? color(233, 198, 116, 235) : lerpColor(color(170, 140, 70), color(214, 178, 98), random());
      push();
      translate(bx, by);
      rotate(ang + HALF_PI + side * 0.62);
      noStroke();
      fill(gcol);
      ellipse(0, -4, 6.5, 15);
      stroke(red(gcol), green(gcol), blue(gcol), 140);
      strokeWeight(0.9);
      line(0, -8, side * 3, -8 - random(16, 30));
      pop();
    }
  }
}

function sprouts() {
  let spots = [[430, 1120], [1210, 1080], [260, 1500], [1380, 1420], [600, 1760], [1080, 1700], [870, 940], [180, 980]];
  for (let s of spots) {
    let x = s[0], y = s[1];
    noStroke();
    fill(60, 40, 24, 220);
    ellipse(x, y, 14, 10);
    fill(226, 214, 150, 50);
    ellipse(x, y - 6, 26, 26);
    stroke(188, 208, 150, 200);
    strokeWeight(1.8);
    noFill();
    let h = random(50, 110), sw = random(-20, 20);
    bezier(x, y - 4, x + sw * 0.3, y - h * 0.4, x + sw * 0.7, y - h * 0.75, x + sw, y - h);
    push();
    translate(x + sw, y - h);
    rotate(sw > 0 ? 0.5 : -0.5);
    fill(196, 214, 158, 210);
    noStroke();
    ellipse(0, -4, 7, 16);
    pop();
  }
}

function spores() {
  for (let i = 0; i < 90; i++) {
    let cl = random() < 0.6;
    let x = cl ? randomGaussian(790, 220) : random(W);
    let y = cl ? random(300, 1300) : random(560, 1200);
    x = constrain(x, 10, 1590);
    let s = random(2, 5.5), a = random(60, 200);
    noStroke();
    fill(238, 206, 128, a);
    ellipse(x, y, s, s);
    if (random() < 0.18) {
      stroke(238, 206, 128, a * 0.5);
      strokeWeight(0.8);
      line(x - s * 2.4, y, x + s * 2.4, y);
      line(x, y - s * 2.4, x, y + s * 2.4);
    }
  }
}

function finish() {
  noStroke();
  for (let i = 0; i < 60; i++) {
    let a = i / 60;
    fill(8, 6, 10, a * a * 26);
    rect(0, i * 10, W, 12);
    rect(0, H - i * 10 - 12, W, 12);
  }
  for (let i = 0; i < 40; i++) {
    let a = i / 40;
    fill(8, 6, 10, a * a * 20);
    rect(i * 10, 0, 12, H);
    rect(W - i * 10 - 12, 0, 12, H);
  }
  for (let i = 0; i < 4200; i++) {
    let x = random(W), y = random(H);
    let v = random() < 0.5 ? 0 : 255;
    fill(v, v, v, random(4, 13));
    rect(x, y, random(1, 2.2), random(1, 2.2));
  }
}

let W = 1600, H = 2000;
let MX = 980, MY = 520, MR = 150;   // lune éclipsée
let HZ = 1150;                       // ligne d'horizon

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  strokeCap(ROUND);
  strokeJoin(ROUND);

  base();
  skyStrokes();
  moon();
  birds();
  horizonGlow();
  water();
  reflection();
  barque();
  shore();
  vignette();
  grain();
}

function base() {
  noStroke();
  for (let y = 0; y <= HZ + 40; y += 2) {
    let t = constrain(y / HZ, 0, 1);
    fill(lerpColor(color(6, 7, 10), color(31, 41, 53), pow(t, 1.5)));
    rect(0, y, W, 2.5);
  }
  for (let y = HZ; y < H; y += 2) {
    let t = (y - HZ) / (H - HZ);
    fill(lerpColor(color(17, 23, 31), color(4, 4, 6), pow(t, 0.8)));
    rect(0, y, W, 2.5);
  }
}

function skyStrokes() {
  for (let i = 0; i < 5200; i++) {
    let x = random(-30, W + 30);
    let y = random(HZ + 20);
    let dx = x - MX, dy = y - MY;
    let d = sqrt(dx * dx + dy * dy);
    let infl = constrain(map(d, 130, 640, 1, 0), 0, 1);
    let baseA = (noise(x * 0.0016, y * 0.0021) - 0.5) * 1.5;
    let tang = atan2(dy, dx) + HALF_PI;
    let ang = lerp(baseA, tang, infl * 0.8);
    let len = random(26, 92) * (0.7 + infl * 0.9);
    let t = y / HZ;
    let r0 = random();
    let c;
    if (r0 < 0.60) c = lerpColor(color(11, 13, 17), color(40, 52, 66), t * random(0.55, 1));
    else if (r0 < 0.84) c = lerpColor(color(26, 32, 40), color(62, 76, 90), random());
    else if (r0 < 0.94) c = color(112, 120, 126);
    else c = lerpColor(color(78, 34, 27), color(116, 62, 40), random());
    if (d < 330) c = lerpColor(c, color(214, 208, 194), constrain(map(d, 330, 150, 0, 0.65), 0, 0.65));
    brush(x, y, ang, len, random(2.2, 7.5), c, random(24, 66));
  }
}

function moon() {
  noFill();
  for (let r = MR + 10; r < MR + 250; r += 7) {
    stroke(226, 220, 206, map(r, MR + 10, MR + 250, 15, 2));
    strokeWeight(5.5);
    let wob = noise(r * 0.05) * 8;
    ellipse(MX, MY, (r + wob) * 2, (r + wob) * 2);
  }
  noStroke();
  fill(231, 225, 210, 242);
  ellipse(MX, MY, MR * 2, MR * 2);
  for (let i = 0; i < 90; i++) {
    let a = random(TWO_PI), rr = sqrt(random()) * MR * 0.92;
    fill(200, 194, 178, random(10, 30));
    ellipse(MX + cos(a) * rr, MY + sin(a) * rr, random(6, 30));
  }
  fill(9, 11, 15, 252);
  ellipse(MX - 54, MY - 36, MR * 2.06, MR * 2.06);
  noFill();
  stroke(244, 239, 226, 210);
  strokeWeight(3.4);
  arc(MX, MY, MR * 2 - 3, MR * 2 - 3, -0.9, 2.35);
  stroke(244, 239, 226, 60);
  strokeWeight(9);
  arc(MX, MY, MR * 2 + 10, MR * 2 + 10, -0.7, 2.2);
}

function birds() {
  let B = [[300, 296, 30], [408, 244, 25], [512, 330, 21], [604, 258, 18],
           [698, 348, 15], [788, 296, 12], [864, 386, 9]];
  for (let i = 0; i < B.length; i++) {
    bird(B[i][0], B[i][1], B[i][2], map(i, 0, B.length - 1, 235, 140));
  }
}

function bird(x, y, s, a) {
  noFill();
  stroke(233, 227, 213, a);
  strokeWeight(max(1.7, s * 0.11));
  beginShape();
  vertex(x - s, y - s * 0.34);
  quadraticVertex(x - s * 0.3, y + s * 0.34, x, y);
  quadraticVertex(x + s * 0.3, y + s * 0.34, x + s, y - s * 0.34);
  endShape();
}

function horizonGlow() {
  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(160, 170, 176, 5);
    ellipse(MX, HZ, 900 + i * 130, 40 + i * 8);
  }
  for (let x = 0; x < W; x += 5) {
    let yy = HZ + (noise(x * 0.01) - 0.5) * 8;
    stroke(4, 5, 7, 150);
    strokeWeight(3.5);
    line(x, yy, x + 4, yy + random(-1, 1));
  }
}

function water() {
  for (let i = 0; i < 6000; i++) {
    let x = random(-20, W + 20);
    let y = random(HZ + 4, H - 200);
    let t = (y - HZ) / (H - HZ);
    let ang = (noise(x * 0.0022, y * 0.006) - 0.5) * 0.24;
    let len = random(16, 62) * (0.55 + t * 1.7);
    let refl = constrain(map(abs(x - MX), 0, 210 + t * 280, 1, 0), 0, 1);
    let r0 = random();
    let c, a = random(22, 56);
    if (r0 < 0.78) c = lerpColor(color(10, 13, 18), color(30, 38, 48), random() * (0.4 + t));
    else if (r0 < 0.93) c = lerpColor(color(44, 54, 64), color(74, 86, 96), random());
    else c = color(150, 156, 150);
    if (refl > 0.15) {
      c = lerpColor(c, color(228, 222, 208), refl * 0.7);
      a += refl * 30;
    }
    brush(x, y, ang, len, random(1.8, 5.4), c, a);
  }
}

function reflection() {
  for (let i = 0; i < 850; i++) {
    let t = pow(random(), 1.1);
    let y = lerp(HZ + 12, H - 270, t);
    let half = lerp(24, 185, t);
    let x = MX + random(-half, half);
    let ang = (noise(x * 0.02, y * 0.02) - 0.5) * 0.35;
    let len = random(9, 26 + t * 34);
    let c = lerpColor(color(188, 184, 172), color(236, 231, 217), random());
    brush(x, y, ang, len, random(1.6, 4.2), c, random(34, 120) * (1 - t * 0.3));
  }
}

function barque() {
  let BX = 700, BY = HZ + 20;
  noStroke();
  fill(3, 3, 5, 120);
  ellipse(BX, BY + 18, 430, 34);
  fill(5, 5, 7);
  beginShape();
  vertex(BX - 192, BY - 16);
  bezierVertex(BX - 120, BY + 28, BX + 120, BY + 28, BX + 202, BY - 22);
  vertex(BX + 186, BY - 8);
  bezierVertex(BX + 108, BY + 14, BX - 108, BY + 14, BX - 176, BY - 4);
  endShape(CLOSE);
  noFill();
  stroke(172, 170, 158, 85);
  strokeWeight(2.2);
  beginShape();
  vertex(BX - 60, BY + 12);
  bezierVertex(BX + 60, BY + 20, BX + 150, BY + 2, BX + 200, BY - 20);
  endShape();
  fill(6, 6, 8);
  noStroke();
  beginShape();
  vertex(BX + 22, BY + 8);
  bezierVertex(BX + 26, BY - 46, BX + 30, BY - 92, BX + 40, BY - 118);
  vertex(BX + 56, BY - 116);
  bezierVertex(BX + 60, BY - 84, BX + 62, BY - 40, BX + 60, BY + 8);
  endShape(CLOSE);
  ellipse(BX + 49, BY - 131, 24, 26);
  stroke(200, 196, 182, 90);
  strokeWeight(2);
  line(BX + 57, BY - 112, BX + 61, BY + 2);
  arc(BX + 49, BY - 131, 24, 26, -HALF_PI - 0.5, HALF_PI - 0.4);
  stroke(7, 7, 9, 235);
  strokeWeight(3.4);
  line(BX + 74, BY - 104, BX + 104, BY + 46);
  stroke(180, 176, 164, 60);
  strokeWeight(1.4);
  line(BX + 75.5, BY - 103, BX + 105, BY + 44);
  for (let r = 30; r > 3; r -= 3) {
    fill(216, 122, 48, map(r, 30, 3, 4, 42));
    noStroke();
    ellipse(BX + 198, BY - 26, r * 2, r * 2);
  }
  fill(255, 205, 132, 235);
  ellipse(BX + 198, BY - 26, 9, 9);
  for (let i = 0; i < 26; i++) {
    let yy = BY + 8 + i * random(4, 10);
    brush(BX + 198 + random(-10, 10), yy, 0, random(8, 26), random(1.5, 3),
          color(206, 122, 58), random(20, 70) * (1 - i / 30));
  }
}

function shore() {
  noStroke();
  fill(7, 7, 9);
  beginShape();
  vertex(0, H);
  for (let x = 0; x <= W; x += 14) {
    let y = shoreEdge(x);
    vertex(x, y);
  }
  vertex(W, H);
  endShape(CLOSE);
  for (let i = 0; i < 2400; i++) {
    let x = random(W);
    let topY = shoreEdge(x);
    let y = random(topY + 3, H);
    let r0 = random();
    let c, a = random(20, 60);
    if (r0 < 0.72) c = lerpColor(color(12, 12, 14), color(34, 34, 38), random());
    else if (r0 < 0.9) c = lerpColor(color(70, 68, 62), color(110, 106, 96), random());
    else { c = color(196, 190, 176); a = random(50, 150); }
    let ang = (noise(x * 0.004, y * 0.004) - 0.5) * 0.8;
    brush(x, y, ang, random(8, 34), random(1.4, 4), c, a);
  }
  for (let i = 0; i < 110; i++) {
    let x = random(W);
    let topY = shoreEdge(x);
    let y = random(topY + 10, H - 8);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(222, 216, 200, random(60, 190));
    let fragL = random(4, 20), fragW = fragL * random(0.25, 0.55);
    ellipse(0, 0, fragL, fragW);
    pop();
  }
}

function shoreEdge(x) {
  return 1748 + (noise(x * 0.0028) - 0.5) * 90 + (noise(x * 0.02) - 0.5) * 16;
}

function vignette() {
  strokeWeight(2.4);
  for (let y = 0; y < 240; y += 2) {
    stroke(3, 3, 5, pow(1 - y / 240, 1.6) * 96);
    line(0, y, W, y);
  }
  for (let y = H; y > H - 300; y -= 2) {
    stroke(2, 2, 4, pow(1 - (H - y) / 300, 1.5) * 80);
    line(0, y, W, y);
  }
  for (let x = 0; x < 200; x += 2) {
    stroke(3, 3, 5, pow(1 - x / 200, 1.7) * 70);
    line(x, 0, x, H);
  }
  for (let x = W; x > W - 200; x -= 2) {
    stroke(3, 3, 5, pow(1 - (W - x) / 200, 1.7) * 70);
    line(x, 0, x, H);
  }
}

function grain() {
  noStroke();
  for (let i = 0; i < 8000; i++) {
    let x = random(W), y = random(H);
    if (random() < 0.5) fill(240, 236, 226, random(5, 16));
    else fill(0, 0, 0, random(8, 24));
    ellipse(x, y, random(0.8, 2.1), random(0.8, 2.1));
  }
}

function brush(x, y, ang, len, wgt, c, a) {
  push();
  translate(x, y);
  rotate(ang);
  noFill();
  stroke(red(c), green(c), blue(c), a);
  for (let i = 0; i < 2; i++) {
    strokeWeight(wgt * random(0.55, 1.15));
    let oy = random(-wgt * 0.35, wgt * 0.35);
    let bend = random(-len * 0.09, len * 0.09);
    beginShape();
    vertex(-len / 2, oy);
    quadraticVertex(0, oy + bend, len / 2, oy + random(-2, 2));
    endShape();
  }
  pop();
}

let tips = [];

function setup() {
