    );
  }

  noStroke();
  fill(16, 18, 20, 232);
  beginShape();
  vertex(0, 1510);
  bezierVertex(280, 1460, 430, 1545, 690, 1518);
  bezierVertex(990, 1480, 1270, 1515, 1600, 1440);
