  fill(24, 21, 20, 205);
  beginShape();
  vertex(0, 1650);
  bezierVertex(370, 1580, 640, 1685, 920, 1615);
  bezierVertex(1200, 1550, 1410, 1635, 1600, 1580);
  vertex(1600, 2000);
  vertex(0, 2000);
  endShape(CLOSE);

  for (let i = 0; i < 230; i++) {
    let y = random(1430, 1840);
    let x = random(-120, 1510);
    stroke(127, 105, 78, random(3, 14));
    strokeWeight(random(0.6, 3.2));
    line(x, y, x + random(30, 500), y + random(-4, 4));
