  noStroke();
  fill(4, 6, 8, 120);
  ellipse(805, 1630, 480, 82);

  for (let i = 0; i < 14; i++) {
    rootlet(
      795 + random(-38, 38),
      1605 + random(-8, 22),
      random(85, 165),
      random(0.25, PI - 0.25),
      5,
      random(5, 13)
    );
  }

  tips = [];
  limb(790, 1620, 330, -HALF_PI - 0.035, 9, 78);

  let sources = tips.filter(p => p.x > 700 && p.y < 1260);

  if (sources.length > 0) {
