        ex,
        ey
      );
    }

    noStroke();
    for (let i = 0; i < 5400; i++) {
      let p = sources[floor(random(sources.length))];
      let t = pow(random(), 1.28);
      let spread = 3 + 29 * t;
      let x =
        p.x +
        t * random(150, 790) +
