    point(random(width), random(height));
  }

  for (let i = 0; i < 1700; i++) {
    let x = random(width);
    let y = random(height);
    stroke(203, 190, 163, random(1.5, 6));
    strokeWeight(random(0.35, 0.9));
    line(x, y, x + random(4, 34), y + random(-1, 1));
  }

  noFill();
  for (let i = 0; i < 80; i++) {
    let q = i * 3;
    stroke(3, 5, 8, 2.2);
    strokeWeight(14);
    rect(
      -80 + q,
      -80 + q,
      width + 160 - 2 * q,
      height + 160 - 2 * q,
      42
    );
  }
}

function limb(x, y, len, a, d, w) {
  let bend = random(-0.16, 0.16) * len;
  let x2 = x + cos(a) * len;
  let y2 = y + sin(a) * len;

  let c1x = x + cos(a) * len * 0.32 - sin(a) * bend;
  let c1y = y + sin(a) * len * 0.32 + cos(a) * bend;
  let c2x = x + cos(a) * len * 0.72 + sin(a) * bend * 0.45;
  let c2y = y + sin(a) * len * 0.72 - cos(a) * bend * 0.45;

  let age = 9 - d;
  noFill();
  strokeCap(ROUND);
  stroke(
    10 + age * 1.3,
    13 + age * 1.25,
    16 + age * 1.1,
    245
  );
  strokeWeight(w);
  bezier(x, y, c1x, c1y, c2x, c2y, x2, y2);

  if (w > 0.8) {
    stroke(157, 140, 111, d < 4 ? 58 : 24);
    strokeWeight(max(0.45, w * 0.075));
    bezier(
      x - w * 0.07,
      y,
      c1x - w * 0.05,
      c1y,
      c2x - w * 0.025,
      c2y,
      x2,
      y2
    );
  }

  if (d <= 0 || len < 13) {
    tips.push({ x: x2, y: y2 });
    return;
  }

  let vanish = 0;
  if (x2 > 790 && y2 < 1160) {
    let horizontal = map(x2, 790, 1510, 0.03, 0.76, true);
    let vertical = 1 - constrain((y2 - 300) / 860, 0, 1);
    vanish = horizontal * (0.35 + 0.65 * vertical);
  }

  if (d < 7 && random() < vanish) {
    tips.push({ x: x2, y: y2 });
    return;
  }

  let spread = random(0.26, 0.5);

  limb(
    x2,
    y2,
    len * random(0.69, 0.79),
    a - spread * random(0.8, 1.2) + random(-0.05, 0.05),
    d - 1,
    w * 0.69
  );

  limb(
    x2,
    y2,
    len * random(0.68, 0.78),
    a + spread * random(0.8, 1.2) + random(-0.05, 0.05),
    d - 1,
    w * 0.68
  );

  if (d > 5 && random() < 0.16) {
    limb(
      x2,
      y2,
      len * random(0.45, 0.59),
      a + random(-0.18, 0.18),
      d - 2,
      w * 0.43
    );
  }
}

function rootlet(x, y, len, a, d, w) {
  if (y > 1990 || x < -40 || x > 1640) {
    return;
  }

  let x2 = x + cos(a) * len;
  let y2 = y + sin(a) * len * 0.65;
  let bend = random(-0.25, 0.25) * len;

  noFill();
  stroke(100, 77, 54, 12 + d * 4);
  strokeWeight(w);
  bezier(
    x,
    y,
    x + cos(a) * len * 0.35 - sin(a) * bend,
    y + sin(a) * len * 0.25,
    x + cos(a) * len * 0.72 + sin(a) * bend * 0.4,
    y + sin(a) * len * 0.5,
    x2,
    y2
  );

  if (d <= 0) {
    return;
  }

  rootlet(
    x2,
    y2,
    len * random(0.62, 0.76),
    a + random(-0.48, 0.48),
    d - 1,
    w * 0.67
  );

  if (random() < 0.72) {
    rootlet(
      x2,
      y2,
      len * random(0.45, 0.67),
      a + random(-0.85, 0.85),
      d - 1,
      w * 0.52
    );
  }
}

const W = 1600;
const H = 2000;
const CX = 790;
const CY = 650;
const R = 405;

const SKY = [
  [0.00, [22, 32, 39]],
  [0.25, [46, 62, 64]],
  [0.46, [98, 109, 99]],
  [0.58, [176, 166, 137]],
  [0.64, [201, 184, 148]],
  [0.70, [119, 119, 91]],
  [1.00, [35, 45, 39]]
];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  strokeJoin(ROUND);
  noLoop();
}

function draw() {
  paintSky();
  paintHalo();
  paintBlackSun();
  paintHorizon();
  paintGround();
  paintMeadow();
  paintDrift();
  paintSurface();
}

function sampleStops(t, stops) {
  for (let i = 0; i < stops.length - 1; i++) {
    if (t <= stops[i + 1][0]) {
      const u = constrain(
        (t - stops[i][0]) / (stops[i + 1][0] - stops[i][0]),
        0,
        1
      );
      const a = stops[i][1];
      const b = stops[i + 1][1];
      return [
        lerp(a[0], b[0], u),
        lerp(a[1], b[1], u),
        lerp(a[2], b[2], u)
      ];
    }
  }
  return stops[stops.length - 1][1];
}

function paintSky() {
  noStroke();
  for (let y = 0; y < H; y += 4) {
    const c = sampleStops(y / H, SKY);
    fill(c[0], c[1], c[2]);
    rect(0, y, W, 5);
  }

  for (let i = 0; i < 750; i++) {
    const x = random(-180, W + 180);
    const y = random(0, 1370);
    const c = sampleStops(y / H, SKY);
    const j = random(-18, 20);
    fill(c[0] + j, c[1] + j, c[2] + j * 0.7, random(2, 7));
    ellipse(x, y, random(90, 520), random(16, 105));
  }

  for (let i = 0; i < 4800; i++) {
    const x = random(-100, W);
    const y = random(H);
    const c = sampleStops(y / H, SKY);
    const n = noise(x * 0.003, y * 0.003) - 0.5;
    const j = random(-13, 13);
    stroke(
      c[0] + j + n * 12,
      c[1] + j + n * 10,
      c[2] + j * 0.7,
      random(4, 15)
    );
    strokeWeight(random(0.7, 7));
    const len = random(25, 280);
    line(x, y, x + len, y + random(-3, 3));
  }
}

function paintHalo() {
  noStroke();
  for (let rr = R * 1.34; rr > R * 0.965; rr -= 3.5) {
    const u = (rr - R * 0.965) / (R * 1.34 - R * 0.965);
    fill(198, 172, 117, lerp(11, 0.55, u));
    ellipse(CX, CY, rr * 2, rr * 1.97);
  }

  for (let i = 0; i < 1700; i++) {
    const a = random(TWO_PI);
    const rr = R + random(-2, 145);
    const fade = 1 - (rr - R) / 145;
    const x = CX + cos(a) * rr;
    const y = CY + sin(a) * rr * 0.985;
    const len = random(3, 27);
    stroke(
      211,
      185,
      128,
      random(4, 25) * (0.35 + 0.65 * fade)
    );
    strokeWeight(random(0.5, 3.5));
    line(
      x + sin(a) * len * 0.5,
      y - cos(a) * len * 0.5,
      x - sin(a) * len * 0.5,
      y + cos(a) * len * 0.5
    );
  }
}

function edgeRadius(a) {
  return R
    + 18 * (noise(4 + cos(a) * 1.8, 4 + sin(a) * 1.8) - 0.5)
    + 3.5 * sin(a * 9)
    + 2 * sin(a * 17);
}

function paintBlackSun() {
  noStroke();
  fill(11, 17, 19);
  beginShape();
  for (let i = 0; i < 420; i++) {
    const a = i * TWO_PI / 420;
    const rr = edgeRadius(a);
    vertex(CX + cos(a) * rr, CY + sin(a) * rr * 0.985);
  }
  endShape(CLOSE);

  let placed = 0;
  while (placed < 5200) {
    const x = random(CX - R, CX + R);
    const y = random(CY - R, CY + R);
    const len = random(12, 118);
    const d = dist(x, y, CX, CY);

    if (d < R - len * 0.55 - 10) {
      const n = noise(x * 0.004, y * 0.004);
      if (random() < 0.7) {
        stroke(
          35 + n * 21,
          46 + n * 20,
          48 + n * 18,
          random(4, 18)
        );
      } else {
        stroke(3, 8, 11, random(5, 22));
      }

      strokeWeight(random(0.5, 5.5));
      if (random() < 0.2) {
        line(
          x,
          y - len * 0.35,
          x + random(-4, 4),
          y + len * 0.65
        );
      } else {
        line(
          x - len * 0.5,
          y,
          x + len * 0.5,
          y + random(-3, 3)
        );
      }
      placed++;
    }
  }

  for (let i = 0; i < 1100; i++) {
    const a = random(TWO_PI);
    const rr = edgeRadius(a) + random(-2, 2);
    const x = CX + cos(a) * rr;
    const y = CY + sin(a) * rr * 0.985;
    const len = random(2, 18);

    if (random() < 0.82) {
      stroke(198, 174, 119, random(12, 72));
    } else {
      stroke(82, 94, 86, random(10, 45));
    }

    strokeWeight(random(0.4, 2.2));
    line(
      x + sin(a) * len * 0.5,
      y - cos(a) * len * 0.5,
      x - sin(a) * len * 0.5,
      y + cos(a) * len * 0.5
    );
  }
}

function paintHorizon() {
  for (let i = 0; i < 1300; i++) {
    const x = random(-150, W);
    const y = random(1090, 1400);
    if (random() < 0.7) {
      stroke(224, 205, 165, random(2, 15));
    } else {
      stroke(70, 82, 71, random(2, 11));
    }
    strokeWeight(random(1, 9));
    line(x, y, x + random(20, 280), y + random(-2, 2));
  }
}

function paintGround() {
  for (let i = 0; i < 3300; i++) {
    const x = random(-80, W);
    const y = random(1260, H);
    const c = sampleStops(y / H, SKY);
    const j = random(-20, 20);
    stroke(c[0] + j, c[1] + j, c[2] + j * 0.6, random(7, 27));
    strokeWeight(random(0.7, 6));
    line(x, y, x + random(15, 190), y + random(-4, 4));
  }

  for (let i = 0; i < 1900; i++) {
    const d = pow(random(), 0.72);
    const y = 1260 + d * 790;
    const x = random(-40, W + 40);
    const sc = lerp(0.15, 1.25, d);
    const h = random(12, 85) * sc;
    const lean = random(-22, 22) * sc;

    if (random() < 0.68) {
      stroke(36, 52, 42, random(25, 95));
    } else {
      stroke(142, 137, 96, random(18, 70));
    }

    strokeWeight(max(0.45, sc * 0.8));
    noFill();
    bezier(
      x, y,
      x + lean * 0.1, y - h * 0.4,
      x + lean * 0.8, y - h * 0.7,
      x + lean, y - h
    );
  }
}

function paintMeadow() {
  const plants = [];

  for (let i = 0; i < 820; i++) {
    const d = pow(random(), 1.38);
    plants.push({
      x: random(-70, W + 70),
      y: 1260 + d * 790,
      d: d,
      bend: random(-1, 1),
      dry: random() < 0.22,
      accent: false
    });
  }

  plants.push({
    x: 1130,
    y: 1930,
    d: 1,
    bend: -0.25,
    dry: false,
    accent: true
  });

  plants.sort((a, b) => a.y - b.y);

  for (const p of plants) {
    paintPlant(p);
  }
}

function paintPlant(p) {
  const sc = lerp(0.22, 1.35, p.d);
  const h = p.accent ? 280 : random(58, 145) * sc;
  const lean = p.accent
    ? -55
    : (CX - p.x) * 0.009 * sc + p.bend * 30 * sc;
  const hx = p.x + lean;
  const hy = p.y - h;
  const alpha = lerp(65, 220, p.d);
  const stem = p.dry ? [126, 117, 81] : [83, 99, 75];

  noFill();
  stroke(stem[0], stem[1], stem[2], alpha * 0.75);
  strokeWeight(max(0.6, 1.35 * sc));
  bezier(
    p.x, p.y,
    p.x - lean * 0.08, p.y - h * 0.35,
    hx - lean * 0.25, hy + h * 0.25,
    hx, hy
  );

  if (p.d > 0.35) {
    stroke(157, 151, 111, alpha * 0.18);
    strokeWeight(max(0.35, 0.45 * sc));
    bezier(
      p.x + 1, p.y,
      p.x - lean * 0.08 + 1, p.y - h * 0.35,
      hx - lean * 0.25 + 1, hy + h * 0.25,
      hx + 1, hy
    );
  }

  if (p.d > 0.28 && random() < 0.7) {
    const count = random() < 0.35 ? 2 : 1;
    for (let j = 0; j < count; j++) {
      const t = random(0.25, 0.58);
      const lx = lerp(p.x, hx, t * 0.7);
      const ly = p.y - h * t;
      const dir = random() < 0.5 ? -1 : 1;
      const ex = lx + dir * random(10, 28) * sc;
      const ey = ly - random(4, 16) * sc;
      stroke(stem[0], stem[1], stem[2], alpha * 0.5);
      strokeWeight(max(0.45, sc * 0.65));
      line(lx, ly, ex, ey);
      line(lx, ly, ex - dir * 3 * sc, ey + 5 * sc);
    }
  }

  const r = p.accent ? 20 : random(3.2, 6.4) * sc;
  const petal = p.dry ? [163, 145, 102] : [225, 218, 188];

  push();
  translate(hx, hy);
  rotate(p.bend * 0.25);

  if (sc < 0.43 && !p.accent) {
    noStroke();
    fill(petal[0], petal[1], petal[2], alpha * 0.8);
    ellipse(0, 0, r * 2.6, r * 1.6);
    fill(153, 141, 99, alpha * 0.5);
    ellipse(0, 0, max(0.8, r * 0.45));
  } else if (p.accent) {
    drawAccentBloom(r, alpha);
  } else {
    drawUmbel(r, alpha, p.dry);
  }

  pop();
}

function drawUmbel(r, alpha, dry) {
  const count = dry ? 5 : 7;
  const petal = dry ? [163, 145, 102] : [225, 218, 188];

  for (let k = 0; k < count; k++) {
    const a = k * TWO_PI / count + random(-0.18, 0.18);
    const rr = r * random(0.7, 1.35);
    const px = cos(a) * rr;
    const py = sin(a) * rr * 0.48;

    stroke(155, 154, 119, alpha * 0.35);
    strokeWeight(0.55);
    line(0, r * 0.45, px, py);

    noStroke();
    fill(
      petal[0],
      petal[1],
      petal[2],
      alpha * random(0.65, 1)
    );
    const sz = max(1.2, r * random(0.4, 0.7));
    ellipse(px, py, sz * 1.25, sz * 0.8);
  }

  fill(169, 151, 105, alpha * 0.65);
  ellipse(0, 0, max(1, r * 0.42), max(0.8, r * 0.3));
}

function drawAccentBloom(r, alpha) {
  noStroke();

  for (let k = 0; k < 5; k++) {
    push();
    rotate(k * TWO_PI / 5 + 0.12);
    fill(
      142 + random(-10, 14),
      73 + random(-7, 8),
      49 + random(-5, 7),
      alpha * 0.88
    );
    ellipse(0, -r * 0.43, r * 0.95, r * 1.25);
    pop();
  }

  fill(43, 42, 31, alpha);
  ellipse(0, 0, r * 0.72, r * 0.5);

  fill(191, 143, 78, alpha * 0.6);
  for (let k = 0; k < 7; k++) {
    const a = k * TWO_PI / 7;
    ellipse(cos(a) * r * 0.2, sin(a) * r * 0.12, 2.2, 2.2);
  }
}

function paintDrift() {
  for (let i = 0; i < 96; i++) {
    const t = pow(random(), 0.82);
    const y = 1370 - t * 905;
    const x = 820
      + 155 * sin(t * 5.1 - 0.4)
      + randomGaussian() * (25 + 38 * t);
    const s = random(2.2, 5.2) * (1 - 0.35 * t);
    const alpha = random(70, 180) * (1 - 0.25 * t);

    push();
    translate(x, y);
    rotate(-0.45 + 0.9 * noise(t * 3, 2));

    stroke(229, 218, 180, alpha * 0.65);
    strokeWeight(0.65);
    for (let k = -1; k <= 1; k++) {
      line(0, -s * 0.2, k * s * 0.9, -s * 2.2);
    }
    line(0, 0, s * 0.4, s * 1.8);

    noStroke();
    fill(229, 219, 183, alpha);
    ellipse(0, 0, s * 0.65, s * 1.4);
    pop();
  }
}

function paintSurface() {
  noStroke();
  fill(174, 143, 94, 4);
  rect(0, 0, W, H);

  strokeWeight(1);
  for (let i = 0; i < 26000; i++) {
    const x = random(W);
    const y = random(H);
    if (random() < 0.5) {
      stroke(240, 228, 195, random(2, 9));
    } else {
      stroke(6, 13, 14, random(2, 10));
    }
    point(x, y);
  }

  for (let i = 0; i < 900; i++) {
    const x = random(W);
    const y = random(H);
    const len = random(2, 18);
    if (random() < 0.5) {
      stroke(229, 214, 179, random(2, 8));
    } else {
      stroke(12, 20, 19, random(2, 8));
    }
    strokeWeight(random(0.35, 0.8));
    line(x, y, x + len, y + random(-1, 1));
  }

  noFill();
  for (let i = 0; i < 100; i++) {
    const inset = i * 1.7 + 1.5;
    stroke(7, 13, 14, 0.65);
    strokeWeight(3);
    rect(inset, inset, W - inset * 2, H - inset * 2);
  }
}

const W = 1600;
const H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);

  createCanvas(W, H);
  pixelDensity(1);
  colorMode(RGB, 255, 255, 255, 255);
  angleMode(RADIANS);
  smooth();

  paintBackdrop();
  paintChamber();
  paintHalo();
  paintEarth();
  paintRoots();
  paintHusk();
  paintDissolution();
  paintSettling();
  paintSurface();
  paintVignette();

  noLoop();
}

function draw() {}

function paintBackdrop() {
  const top = color(13, 20, 28);
  const middle = color(24, 29, 32);
  const bottom = color(39, 30, 25);

  for (let y = 0; y < H; y += 3) {
    const t = y / H;
    let c;
    if (t < 0.58) {
      c = lerpColor(top, middle, t / 0.58);
    } else {
      c = lerpColor(middle, bottom, (t - 0.58) / 0.42);
    }
    stroke(c);
    strokeWeight(3.2);
    line(0, y, W, y);
  }

  noStroke();
  for (let r = 1240; r > 140; r -= 16) {
    const t = 1 - r / 1240;
    fill(83, 85, 76, 0.55 + t * 0.35);
    ellipse(790, 900, r * 0.82, r);
  }

  for (let i = 0; i < 700; i++) {
    const x = random(-100, W + 100);
    const y = random(-100, H + 100);
    const n = noise(x * 0.0015, y * 0.0015);
    const a = n * TWO_PI + random(-0.5, 0.5);
    const len = random(50, 240);

    if (n < 0.42) {
      stroke(24, 39, 50, random(2, 7));
    } else if (n < 0.7) {
      stroke(92, 91, 80, random(2, 6));
    } else {
      stroke(91, 69, 53, random(2, 6));
    }

    strokeWeight(random(7, 30));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }

  for (let i = 0; i < 17000; i++) {
    const x = random(W);
    const y = random(H);
    const n = noise(x * 0.003, y * 0.003, 2.7);
    const a = n * TWO_PI * 1.7;
    const len = random(4, 48);
    const light = random() < 0.48;

    if (light) {
      stroke(151, 145, 124, random(2, 10));
    } else {
      stroke(2, 9, 15, random(3, 13));
    }

    strokeWeight(random(0.35, 2.2));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

function chamberPath(offset) {
  const left = 250 + offset;
  const right = 1350 - offset;
  const top = 150 + offset * 0.35;
  const bottom = 1600 - offset * 0.2;

  beginShape();
  vertex(left, bottom);
  vertex(left, 720);
  bezierVertex(left, 405, 465, top, 800, top);
  bezierVertex(1135, top, right, 405, right, 720);
  vertex(right, bottom);
  endShape(CLOSE);
}

function paintChamber() {
  noStroke();
  fill(4, 9, 14, 78);
  chamberPath(0);

  noFill();
  for (let i = 0; i < 14; i++) {
    stroke(128, 127, 111, random(2, 7));
    strokeWeight(random(0.7, 2.4));
    chamberPath(i * 2.1 + random(-2, 2));
  }
}

function paintHalo() {
  for (let j = 0; j < 7; j++) {
    const baseR = 477 + j * 2.2;
    stroke(157, 153, 132, 4.5 + j * 0.45);
    strokeWeight(0.7 + j * 0.12);

    for (let i = 0; i < 470; i++) {
      const a = map(i, 0, 470, 0, TWO_PI);
      if (a > 5.0 && a < 5.65) continue;
      if (random() < 0.08) continue;

      const b = a + random(0.008, 0.019);
      const n1 = noise(cos(a) * 2 + 10, sin(a) * 2 + 10, j * 0.17);
      const n2 = noise(cos(b) * 2 + 10, sin(b) * 2 + 10, j * 0.17);
      const r1 = baseR + (n1 - 0.5) * 15;
      const r2 = baseR + (n2 - 0.5) * 15;

      line(
        800 + cos(a) * r1,
        850 + sin(a) * r1,
        800 + cos(b) * r2,
        850 + sin(b) * r2
      );
    }
  }
}

function paintEarth() {
  noStroke();
  fill(18, 18, 17, 172);
  beginShape();
  vertex(0, H);
  vertex(0, 1445);

  for (let x = 0; x <= W; x += 32) {
    const y = 1438 + (noise(x * 0.006, 8.2) - 0.5) * 42;
    vertex(x, y);
  }

  vertex(W, H);
  endShape(CLOSE);

  for (let i = 0; i < 1050; i++) {
    const x = random(W);
    const y = random(1430, H);
    const len = random(12, 170);
    const warm = random() < 0.55;

    if (warm) {
      stroke(105, 78, 56, random(3, 12));
    } else {
      stroke(84, 92, 91, random(2, 9));
    }

    strokeWeight(random(0.4, 2.8));
    line(x, y, x + len, y + random(-5, 5));
  }
}

function drawPolyline(points) {
  beginShape();
  for (const p of points) {
    vertex(p.x, p.y);
  }
  endShape();
}

function rootBranch(x, y, len, ang, weight, depth) {
  if (depth < 0 || len < 5 || weight < 0.18) return;
  if (y > H + 30 || x < -220 || x > W + 220) return;

  const points = [{ x, y }];
  let px = x;
  let py = y;
  let a = ang;
  const steps = 8;

  for (let s = 0; s < steps; s++) {
    const n = noise(px * 0.006, py * 0.006, depth * 0.09);
    a += (n - 0.5) * 0.24 + random(-0.075, 0.075);
    a = a * 0.96 + HALF_PI * 0.04;
    a = constrain(a, 0.22, PI - 0.22);

    const step = (len / steps) * random(0.82, 1.18);
    px += cos(a) * step;
    py += sin(a) * step;
    points.push({ x: px, y: py });
  }

  noFill();
  stroke(5, 8, 9, 90);
  strokeWeight(weight + 2.1);
  drawPolyline(points);

  stroke(
    133 + depth * 3,
    120 + depth * 2,
    94 + depth,
    27 + depth * 7
  );
  strokeWeight(weight);
  drawPolyline(points);

  if (weight > 1.05) {
    stroke(204, 185, 143, 18 + depth * 2);
    strokeWeight(Math.max(0.35, weight * 0.24));
    drawPolyline(points);
  }

  if (depth < 5) {
    for (let k = 2; k < points.length - 1; k++) {
      if (random() < 0.28) {
        const p = points[k];
        const side = random() < 0.5 ? -1 : 1;
        const hair = random(8, 30);
        stroke(151, 137, 107, 25);
        strokeWeight(0.45);
        line(
          p.x,
          p.y,
          p.x + side * hair,
          p.y + random(5, 20)
        );
      }
    }
  }

  const branches = depth > 4 ? 2 : random() < 0.72 ? 2 : 1;

  for (let b = 0; b < branches; b++) {
    const side = b === 0 ? -1 : 1;
    const nextAngle =
      a + side * random(0.18, 0.62) + random(-0.13, 0.13);

    rootBranch(
      px,
      py,
      len * random(0.58, 0.78),
      nextAngle,
      weight * random(0.55, 0.71),
      depth - 1
    );
  }

  if (depth === 0 && random() < 0.32) {
    noStroke();
    fill(176, 150, 103, 38);
    ellipse(px, py, random(1.2, 2.8));
  }
}

function paintRoots() {
  for (let i = 0; i < 7; i++) {
    rootBranch(
      792 + random(-54, 54),
      1264 + random(-12, 32),
      random(100, 156),
      HALF_PI + random(-0.62, 0.62),
      random(2.3, 4.8),
      7
    );
  }
}

function huskPath(sc, dx, dy) {
  push();
  translate(800 + dx, 960 + dy);
  scale(sc);
  translate(-800, -960);

  beginShape();
  vertex(804, 596);
  bezierVertex(748, 642, 665, 730, 638, 858);
  bezierVertex(602, 1020, 670, 1196, 790, 1318);
  bezierVertex(818, 1300, 922, 1200, 956, 1052);
  bezierVertex(1004, 858, 930, 685, 804, 596);
  endShape(CLOSE);

  pop();
}

function huskBounds(t) {
  const hw =
    175 *
    pow(max(0, sin(PI * t)), 0.72) *
    (0.78 + 0.32 * t);
  const cx = 800 + 20 * sin(t * PI) - 18 * t;
  return { cx, hw };
}

function paintHusk() {
  noStroke();
  fill(0, 0, 0, 105);
  huskPath(1.035, 18, 24);

  noFill();
  for (let i = 24; i >= 0; i--) {
    stroke(189, 184, 157, 1.8 + (24 - i) * 0.08);
    strokeWeight(1);
    huskPath(1 + i * 0.004, 0, 0);
  }

  noStroke();
  fill(172, 174, 160, 218);
  huskPath(1, 0, 0);

  for (let i = 0; i < 38; i++) {
    const t = i / 37;
    const c = lerpColor(
      color(124, 137, 136),
      color(218, 208, 180),
      t
    );
    fill(c, 3.8);
    huskPath(1 - t * 0.2, random(-1.5, 1.5), 0);
  }

  for (let i = 0; i < 2100; i++) {
    const t = random(0.025, 0.982);
    const y = 596 + t * 722;
    const bounds = huskBounds(t);
    const x = bounds.cx + random(-bounds.hw, bounds.hw);
    let len = random(5, 43) * (0.55 + sin(PI * t));

    if (y + len > 1308) len = 1308 - y;
    if (len <= 0) continue;

    const drift =
      (noise(x * 0.012, y * 0.009) - 0.5) * 17;
    const choice = random();

    if (choice < 0.42) {
      stroke(231, 222, 194, random(7, 24));
    } else if (choice < 0.76) {
      stroke(91, 107, 108, random(6, 20));
    } else {
      stroke(151, 129, 99, random(5, 17));
    }

    strokeWeight(random(0.35, 2));
    line(x, y, x + drift, y + len);
  }

  noFill();
  for (let i = 0; i < 28; i++) {
    const t = i / 27;
    stroke(70, 82, 82, 4 + t * 3);
    strokeWeight(random(0.45, 1.15));
    huskPath(0.96 - t * 0.43, 0, 0);
  }

  noStroke();
  fill(14, 22, 24, 166);
  beginShape();
  vertex(790, 1315);
  vertex(778, 1260);
  vertex(786, 1195);
  vertex(774, 1130);
  vertex(789, 1075);
  vertex(784, 1005);
  vertex(798, 952);
  vertex(793, 916);
  vertex(805, 918);
  vertex(810, 968);
  vertex(798, 1020);
  vertex(808, 1084);
  vertex(797, 1138);
  vertex(807, 1200);
  vertex(798, 1260);
  vertex(802, 1305);
  endShape(CLOSE);

  noFill();
  stroke(197, 164, 108, 68);
  strokeWeight(1.15);
  beginShape();
  vertex(802, 1305);
  vertex(798, 1260);
  vertex(807, 1200);
  vertex(797, 1138);
  vertex(808, 1084);
  vertex(798, 1020);
  endShape();

  noFill();
  stroke(224, 215, 185, 48);
  strokeWeight(1.1);
  huskPath(1, 0, 0);

  for (let i = 0; i < 360; i++) {
    const t = random(0.02, 0.96);
    if (t > 0.45 && random() < 0.52) continue;

    const side = random() < 0.72 ? 1 : -1;
    const bounds = huskBounds(t);
    const distance = pow(random(), 2) * 80;
    const x = bounds.cx + side * (bounds.hw + distance);
    const y = 596 + t * 722 + random(-12, 12);
    const s = random(1.2, 7.5) * (1 - distance / 120);

    push();
    translate(x, y);
    rotate(random(TWO_PI));
    noStroke();
    fill(
      random() < 0.2 ? 181 : 203,
      random() < 0.2 ? 151 : 195,
      random() < 0.2 ? 99 : 168,
      random(18, 95) * (1 - distance / 110)
    );
    beginShape();
    vertex(-s, 0);
    vertex(s * 0.35, -s * 0.55);
    vertex(s, s * 0.35);
    vertex(-s * 0.2, s * 0.7);
    endShape(CLOSE);
    pop();
  }
}

function paintDissolution() {
  noFill();

  for (let i = 0; i < 85; i++) {
    const x = random(760, 875);
    const y = random(610, 830);
    const rise = random(160, 480);
    const drift = random(-80, 190);

    stroke(184, 182, 158, random(4, 20));
    strokeWeight(random(0.35, 1.15));
    bezier(
      x,
      y,
      x + random(-80, 70),
      y - rise * 0.3,
      x + drift - random(20, 100),
      y - rise * 0.75,
      x + drift,
      y - rise
    );
  }

  for (let i = 0; i < 1950; i++) {
    const t = pow(random(), 0.78);
    const spread = 20 + 195 * t;
    const x =
      800 +
      randomGaussian() * spread * 0.4 +
      145 * t * t;
    const y =
      640 -
      t * 565 +
      randomGaussian() * (18 + 24 * t);

    if (x < 45 || x > W - 45 || y < 40) continue;

    const choice = random();
    let c;
    if (choice < 0.14) {
      c = color(181, 149, 96);
    } else if (choice < 0.55) {
      c = color(199, 193, 168);
    } else {
      c = color(112, 127, 128);
    }

    const alpha = random(12, 100) * (1 - 0.48 * t);
    const s = random(0.55, 3.5) * (1 - 0.32 * t);

    noStroke();
    fill(red(c), green(c), blue(c), alpha);

    if (random() < 0.16) {
      push();
      translate(x, y);
      rotate(random(-0.8, 0.8));
      ellipse(0, 0, s * 0.65, s * 3.2);
      pop();
    } else {
      ellipse(x, y, s, s * random(0.7, 1.5));
    }
  }
}

function paintSettling() {
  for (let i = 0; i < 310; i++) {
    const angle = random(TWO_PI);
    const radius = pow(random(), 0.62) * 440;
    const x = 800 + cos(angle) * radius;
    const y =
      1320 +
      abs(sin(angle)) * radius * 0.34 +
      random(-22, 85);

    if (y > 1510) continue;

    const s = random(0.7, 4);
    noStroke();

    if (random() < 0.18) {
      fill(177, 143, 91, random(16, 60));
    } else {
      fill(174, 172, 150, random(10, 48));
    }

    ellipse(x, y, s * random(0.7, 1.8), s * 0.55);
  }

  for (let i = 0; i < 42; i++) {
    const x = random(430, 1170);
    const y = random(1430, 1485);
    const len = random(3, 18);

    stroke(151, 132, 99, random(12, 40));
    strokeWeight(random(0.5, 1.4));
    line(x, y, x + len, y + random(-2, 2));
  }
}

function paintSurface() {
  for (let i = 0; i < 3200; i++) {
    const x = random(W);
    const y = random(H);
    const len = random(3, 34);
    const a = random(-0.25, 0.25) + HALF_PI;

    if (random() < 0.5) {
      stroke(225, 213, 183, random(1, 4));
    } else {
      stroke(0, 5, 8, random(1.5, 5));
    }

    strokeWeight(random(0.25, 0.8));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
}

function paintVignette() {
  noFill();

  for (let i = 0; i < 150; i++) {
    const inset = i * 2.4;
    stroke(3, 6, 9, 2.2);
    strokeWeight(5);
    rect(
      inset,
      inset,
      W - inset * 2,
      H - inset * 2
    );
  }
}

let seedSources = [];

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
}

function draw() {
  colorMode(RGB, 255, 255, 255, 255);
  strokeCap(ROUND);
  seedSources = [];

  paintBackdrop();
  paintAura();
  paintEarth();

  limb(735, 850, -1.55, 260, 55, 6, false);
  limb(700, 990, -2.10, 310, 66, 6, false);
  limb(775, 1000, -1.00, 330, 62, 6, true);
  limb(680, 1210, -2.55, 220, 40, 4, false);
  limb(805, 1210, -0.42, 235, 36, 4, true);

  paintTrunk();
