function roughDisc(cx, cy, radius, c, phase) {
  noStroke();
  fill(c);
  beginShape();

  for (let i = 0; i <= 180; i++) {
    let a = (i / 180) * TWO_PI;
    let r = radius +
      (noise(cos(a) * 2 + 20, sin(a) * 2 + 20, phase * 0.07) - 0.5) * 34 +
      random(-2, 2);

    vertex(cx + cos(a) * r, cy + sin(a) * r);
  }

  endShape(CLOSE);
}

