function limb(x, y, a, len, w, depth, dissolving) {
  let ex = x + cos(a) * len;
  let ey = y + sin(a) * len;
  let nx = -sin(a);
  let ny = cos(a);
  let bend = random(-0.16, 0.16) * len;

  let c1x = x + (ex - x) * 0.32 + nx * bend;
  let c1y = y + (ey - y) * 0.32 + ny * bend;
  let c2x = x + (ex - x) * 0.72 + nx * bend * 0.45;
  let c2y = y + (ey - y) * 0.72 + ny * bend * 0.45;

  if (dissolving && depth <= 3) {
    let steps = max(5, floor(len / 7));

    for (let i = 0; i < steps; i++) {
      if (random() < 0.05 + (3 - depth) * 0.1) continue;

      let t0 = i / steps;
      let t1 = min(1, (i + 0.82) / steps);
      let p = curvePoint(x, y, c1x, c1y, c2x, c2y, ex, ey, t0);
      let q = curvePoint(x, y, c1x, c1y, c2x, c2y, ex, ey, t1);
      let amount = map(depth, 0, 3, 0.95, 0.15) * random(0.35, 1);
      let c = lerpColor(color(27, 34, 32), color(193, 151, 77), amount);

      stroke(red(c), green(c), blue(c), random(100, 235));
      strokeWeight(max(0.6, w * random(0.3, 0.85) * (1 - t0 * 0.25)));
      line(p.x, p.y, q.x, q.y);
    }

    if (depth <= 2) {
      seedSources.push({ x: ex, y: ey });
    }
  } else {
    noFill();
    stroke(18, 26, 26, 255);
    strokeWeight(max(0.8, w + 2));
    bezier(x, y, c1x, c1y, c2x, c2y, ex, ey);

    stroke(38, 44, 38, 255);
    strokeWeight(max(0.6, w * 0.8));
    bezier(x, y, c1x, c1y, c2x, c2y, ex, ey);

    stroke(123, 108, 74, 42);
    strokeWeight(max(0.4, w * 0.11));
    bezier(x, y, c1x, c1y, c2x, c2y, ex, ey);
  }

  if (depth > 0) {
    limb(
      ex, ey,
      a - random(0.22, 0.52),
      len * random(0.64, 0.76),
      w * random(0.58, 0.68),
      depth - 1,
      dissolving
    );

    limb(
      ex, ey,
      a + random(0.20, 0.50),
      len * random(0.63, 0.75),
      w * random(0.57, 0.68),
      depth - 1,
      dissolving
    );

    if (depth > 3 && random() < 0.28) {
      limb(
        ex, ey,
        a + random(-0.85, 0.85),
        len * 0.5,
        w * 0.45,
        depth - 2,
        dissolving
      );
    }
  }
}

function curvePoint(x, y, c1x, c1y, c2x, c2y, ex, ey, t) {
  let u = 1 - t;
  return {
    x: u * u * u * x +
      3 * u * u * t * c1x +
      3 * u * t * t * c2x +
      t * t * t * ex,
    y: u * u * u * y +
      3 * u * u * t * c1y +
      3 * u * t * t * c2y +
      t * t * t * ey
  };
}

