function paintRoots() {
  for (let i = 0; i < 28; i++) {
    let sx = 760 + random(-95, 95);
    let sy = random(1580, 1660);
    let dir = random() < 0.5 ? -1 : 1;
    let ex = 760 + dir * random(120, 570) + random(-40, 40);
    let ey = random(1660, 1900);
    let w = random(8, 30);

    let c1x = lerp(sx, ex, 0.25) + random(-40, 40);
    let c1y = sy + random(20, 80);
    let c2x = lerp(sx, ex, 0.7) + random(-30, 30);
    let c2y = ey - random(10, 80);

    for (let k = 0; k < 22; k++) {
      let t0 = k / 22;
      let t1 = (k + 1) / 22;
      let p = curvePoint(sx, sy, c1x, c1y, c2x, c2y, ex, ey, t0);
      let q = curvePoint(sx, sy, c1x, c1y, c2x, c2y, ex, ey, t1);

      stroke(18, 25, 24, 230 * (1 - t0 * 0.55));
      strokeWeight(max(0.6, w * pow(1 - t0, 1.2)));
      line(p.x, p.y, q.x, q.y);

      if (k % 3 === 0) {
        stroke(135, 111, 68, 35);
        strokeWeight(max(0.4, w * 0.16 * (1 - t0)));
        line(p.x, p.y - 1, q.x, q.y - 1);
      }
    }
  }
}

