function scatterSeeds() {
  for (let s of seedSources) {
    let count = floor(random(3, 11));

    for (let i = 0; i < count; i++) {
      let reach = pow(random(), 0.65) * random(160, 680);
      let x = s.x + reach + random(-30, 30);
      let y = s.y - reach * random(0.12, 0.55) + random(-50, 90);

      if (x < 820 || x > 1585 || y < 45 || y > 1570) continue;

      let q = random();
      let c;
      if (q < 0.22) {
        c = color(232, 215, 171);
      } else if (q < 0.76) {
        c = color(187, 147, 78);
      } else {
        c = color(79, 72, 51);
      }

      let size = random(1.1, 4.6) * map(reach, 0, 750, 1, 0.55);
      seedShape(
        x, y,
        size,
        random(-1.35, -0.45),
        c,
        random(80, 215)
      );
    }
  }

  for (let i = 0; i < 1500; i++) {
    let s = seedSources[floor(random(seedSources.length))];
    let reach = pow(random(), 0.6) * 800;
    let x = s.x + reach;
    let y = s.y - reach * random(0.08, 0.48) + random(-90, 110);

    if (x < 830 || x > width || y < 30 || y > 1570) continue;

    stroke(222, 190, 124, random(20, 105));
    strokeWeight(random(0.5, 2.1));
    point(x, y);
  }
}

function seedShape(x, y, s, a, c, alpha) {
  push();
  translate(x, y);
  rotate(a);

  noStroke();
  fill(red(c), green(c), blue(c), alpha);
  beginShape();
  vertex(0, -s * 1.6);
  bezierVertex(s, -s * 0.8, s * 0.9, s * 0.6, 0, s);
  bezierVertex(-s * 0.9, s * 0.6, -s, -s * 0.8, 0, -s * 1.6);
  endShape(CLOSE);

  stroke(red(c), green(c), blue(c), alpha * 0.35);
  strokeWeight(0.6);
  line(0, s * 0.7, 0, s * 2.3);
  pop();
}

