function paintMoon() {
  const mx = 1020;
  const my = 555;
  const r = 340;
  const ctx = drawingContext;

  const halo = ctx.createRadialGradient(mx, my, r * 0.8, mx, my, r * 1.8);
  halo.addColorStop(0, "rgba(201,190,158,0.10)");
  halo.addColorStop(0.48, "rgba(184,178,153,0.035)");
  halo.addColorStop(1, "rgba(170,170,150,0)");
  ctx.fillStyle = halo;
  ctx.fillRect(0, 0, width, 1250);

  const disc = ctx.createRadialGradient(mx - 90, my - 110, 25, mx, my, r);
  disc.addColorStop(0, "#d8cfb4");
  disc.addColorStop(0.58, "#c2bba4");
  disc.addColorStop(0.88, "#a29f8d");
  disc.addColorStop(1, "#85877b");
  ctx.fillStyle = disc;
  ctx.beginPath();
  ctx.arc(mx, my, r, 0, TWO_PI);
  ctx.fill();

  ctx.save();
  ctx.beginPath();
  ctx.arc(mx, my, r - 1, 0, TWO_PI);
  ctx.clip();

  noStroke();
  for (let i = 0; i < 270; i++) {
    const a = random(TWO_PI);
    const rr = r * sqrt(random());
    const x = mx + cos(a) * rr;
    const y = my + sin(a) * rr;
    const s = random(8, 95);
    if (random() < 0.65) {
      fill(48, 61, 64, random(2, 10));
    } else {
      fill(238, 224, 190, random(2, 9));
    }
    ellipse(x, y, s * random(1, 2.8), s * random(0.35, 1.1));
  }

  for (let i = 0; i < 2100; i++) {
    const x = random(mx - r, mx + r);
    const y = random(my - r, my + r);
    if (dist(x, y, mx, my) > r) continue;
    stroke(
      random() < 0.5 ? 54 : 235,
      random() < 0.5 ? 65 : 224,
      random() < 0.5 ? 65 : 197,
      random(3, 15)
    );
    strokeWeight(random(0.5, 2.2));
    point(x, y);
  }
  ctx.restore();

  noFill();
  stroke(223, 211, 179, 42);
  strokeWeight(2);
  arc(mx, my, r * 2 - 4, r * 2 - 4, PI * 1.04, PI * 1.82);

  for (let i = 0; i < 8; i++) {
    const y = random(805, 1080);
    stroke(25, 34, 37, random(10, 25));
    strokeWeight(random(9, 32));
    bezier(
      -100, y,
      350, y - random(15, 50),
      1040, y + random(10, 50),
      1720, y + random(-12, 12)
    );
  }
}

