function makeTree(g) {
  g.noFill();

  branch(g, 614, 1150, 155, -1.02, 28, 5);
  branch(g, 585, 1010, 230, -0.98, 35, 7);
  branch(g, 630, 870, 245, 0.88, 31, 7);
  branch(g, 612, 730, 210, -0.84, 24, 6);
  branch(g, 656, 595, 195, 0.77, 18, 6);
  branch(g, 648, 475, 160, -0.57, 13, 5);
  branch(g, 682, 365, 135, 0.20, 8, 5);

  const trunk = [
    { x: 610, y: 1295, w: 82 },
    { x: 618, y: 1160, w: 68 },
    { x: 585, y: 1010, w: 54 },
    { x: 635, y: 865, w: 42 },
    { x: 612, y: 725, w: 32 },
    { x: 664, y: 590, w: 21 },
    { x: 648, y: 470, w: 11 },
    { x: 688, y: 360, w: 3 }
  ];

  for (let i = 0; i < trunk.length - 1; i++) {
    const p = trunk[i];
    const q = trunk[i + 1];
    const w = (p.w + q.w) * 0.5;
    const c1x = p.x + random(-25, 25);
    const c1y = lerp(p.y, q.y, 0.36);
    const c2x = q.x + random(-25, 25);
    const c2y = lerp(p.y, q.y, 0.74);

    g.stroke(4, 9, 11, 245);
    g.strokeWeight(w + 4);
    g.bezier(p.x, p.y, c1x, c1y, c2x, c2y, q.x, q.y);

    g.stroke(13, 18, 18, 255);
    g.strokeWeight(w);
    g.bezier(p.x, p.y, c1x, c1y, c2x, c2y, q.x, q.y);

    g.stroke(54, 53, 43, 75);
    g.strokeWeight(max(0.8, w * 0.08));
    g.bezier(
      p.x - w * 0.1, p.y,
      c1x - w * 0.08, c1y,
      c2x - w * 0.06, c2y,
      q.x, q.y
    );
  }

  for (let i = 0; i < 15; i++) {
    const ex = 610 + random(-155, 160);
    const ey = 1300 + random(12, 43);
    g.stroke(6, 11, 12, 235);
    g.strokeWeight(random(3, 11));
    g.bezier(
      610 + random(-20, 20), 1285,
      610 + random(-45, 45), 1305,
      ex + random(-25, 25), ey - 8,
      ex, ey
    );
  }
}

function branch(g, x, y, len, ang, w, depth) {
  if (depth <= 0 || len < 4 || w < 0.35) return;

  const ex = x + sin(ang) * len;
  const ey = y - cos(ang) * len;
  const bend = random(-0.23, 0.23);
  const c1x = x + sin(ang + bend) * len * 0.34;
  const c1y = y - cos(ang + bend) * len * 0.34;
  const c2x = x + sin(ang - bend * 0.45) * len * 0.74;
  const c2y = y - cos(ang - bend * 0.45) * len * 0.74;

  g.noFill();
  g.stroke(6, 11, 12, 248);
  g.strokeWeight(w);
  g.bezier(x, y, c1x, c1y, c2x, c2y, ex, ey);

  if (w > 3) {
    g.stroke(50, 50, 42, 62);
    g.strokeWeight(max(0.55, w * 0.075));
    g.bezier(x, y, c1x, c1y, c2x, c2y, ex, ey);
  }

  const side = random() < 0.5 ? -1 : 1;

  branch(
    g, ex, ey,
    len * random(0.68, 0.78),
    ang + random(-0.19, 0.19),
    w * random(0.62, 0.71),
    depth - 1
  );

  branch(
    g, ex, ey,
    len * random(0.54, 0.71),
    ang + side * random(0.38, 0.72),
    w * random(0.43, 0.56),
    depth - 1
  );

  if (depth > 4 && random() < 0.27) {
    const t = random(0.43, 0.7);
    const bx = lerp(x, ex, t);
    const by = lerp(y, ey, t);
    branch(
      g, bx, by,
      len * random(0.34, 0.48),
      ang - side * random(0.65, 0.96),
      w * 0.35,
      depth - 3
    );
  }
}

function paintTreeReflection(tree, baseY) {
  push();
  for (let y = baseY + 2; y < height; y += 5) {
    const sy = baseY - (y - baseY) / 0.58;
    if (sy < 0) continue;
    const fade = map(y, baseY, height, 78, 6);
    const amount = y - baseY;
    const shift =
      sin(y * 0.037) * (2 + amount * 0.018) +
      sin(y * 0.011) * 5 +
      random(-2.5, 2.5);
    tint(112, 137, 137, fade);
    image(tree, shift, y, width, 6, 0, sy, width, 9);
  }
  noTint();
  pop();
}

