function paintReeds() {
  for (let side = 0; side < 2; side++) {
    const count = side === 0 ? 34 : 25;
    for (let i = 0; i < count; i++) {
      const x = side === 0 ? random(-20, 190) : random(1410, 1620);
      const baseY = random(1960, 2060);
      const h = random(130, 470);
      const tipY = baseY - h;
      const sway = side === 0 ? random(-35, 105) : random(-105, 35);
      const tipX = x + sway;

      noFill();
      stroke(3, 9, 12, random(165, 245));
      strokeWeight(random(2, 6));
      bezier(
        x, baseY,
        x + sway * 0.1, baseY - h * 0.35,
        tipX - sway * 0.25, tipY + h * 0.22,
        tipX, tipY
      );

      if (random() < 0.22) {
        stroke(102, 103, 83, 42);
        strokeWeight(1);
        bezier(
          x + 2, baseY,
          x + sway * 0.1 + 2, baseY - h * 0.35,
          tipX - sway * 0.25 + 2, tipY + h * 0.22,
          tipX + 1, tipY
        );
      }

      if (random() < 0.25) {
        noStroke();
        fill(5, 11, 12, 220);
        ellipse(tipX, tipY + 10, random(3, 6), random(14, 29));
      }
    }
  }
}

