// "Ce qui reste" — une bougie presque éteinte, sa fumée qui monte et se défait.
// p5.js 1.11 — image fixe, 1600 x 2000.

const BX = 780;            // pied de la bougie (x)
const BASE_Y = 1522;       // pied de la bougie (y)
const TOP_X = 762;         // sommet (x, léger penché)
const TOP_Y = 1232;        // sommet (y)
const HW0 = 58;            // demi-largeur à la base
const HW1 = 48;            // demi-largeur au sommet
const FLAME_TIP_X = 766;
const FLAME_TIP_Y = 1150;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();
  paint();
}

function paint() {
  drawBackground();
  drawTable();
  drawAmbientLight();
  drawPool();
  drawCandle();
  drawDrips();
  drawCandleTop();
  drawWick();
  drawFlame();
  drawSmoke();
  drawParticles();
  drawDustMotes();
  drawAsh();
  drawVignette();
  drawGrain();
}

// ---------- primitives ----------

function softEllipse(x, y, r, squash, colStr, a0) {
  push();
  translate(x, y);
  scale(1, squash);
  const g = drawingContext.createRadialGradient(0, 0, 0, 0, 0, r);
  g.addColorStop(0, 'rgba(' + colStr + ',' + a0 + ')');
  g.addColorStop(1, 'rgba(' + colStr + ',0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(-r, -r, r * 2, r * 2);
  pop();
}

function flameShape(cx, baseY, w, h, lean) {
  beginShape();
  vertex(cx - w * 0.5, baseY);
  bezierVertex(cx - w * 0.60, baseY - h * 0.35,
               cx - w * 0.34, baseY - h * 0.75,
               cx + lean, baseY - h);
  bezierVertex(cx + w * 0.30 + lean * 0.4, baseY - h * 0.75,
               cx + w * 0.60, baseY - h * 0.35,
               cx + w * 0.5, baseY);
  endShape(CLOSE);
}

function smokeX(t) {
  return 772 + 85 * pow(t, 1.55) +
         (noise(t * 2.4 + 40) - 0.5) * lerp(40, 340, pow(t, 1.25));
}

// ---------- fond, table, lumière ----------

function drawBackground() {
  const lg = drawingContext.createLinearGradient(0, 0, 0, height);
  lg.addColorStop(0, 'rgb(7,8,11)');
  lg.addColorStop(0.5, 'rgb(10,10,11)');
  lg.addColorStop(1, 'rgb(17,13,10)');
  drawingContext.fillStyle = lg;
  drawingContext.fillRect(0, 0, width, height);

  // matière de toile : longues touches horizontales
  noStroke();
  for (let y = 0; y < height; y += 3) {
    if (random() < 0.72) fill(0, 0, 0, random(0, 9));
    else fill(255, 240, 220, random(0, 4));
    rect(0, y + random(-1.5, 1.5), width, 3.6);
  }
}

function drawTable() {
  const tg = drawingContext.createLinearGradient(0, 1552, 0, height);
  tg.addColorStop(0, 'rgb(26,20,15)');
  tg.addColorStop(0.35, 'rgb(15,12,9)');
  tg.addColorStop(1, 'rgb(5,4,3)');
  drawingContext.fillStyle = tg;
  drawingContext.fillRect(0, 1552, width, height - 1552);

  // arête de la table, frôlée par la lumière
  const eg = drawingContext.createLinearGradient(0, 0, width, 0);
  eg.addColorStop(0, 'rgba(255,200,130,0)');
  eg.addColorStop(0.5, 'rgba(255,200,130,0.22)');
  eg.addColorStop(1, 'rgba(255,200,130,0)');
  drawingContext.fillStyle = eg;
  drawingContext.fillRect(0, 1548, width, 5);

  // clarté qui s'étale sur la surface
  blendMode(ADD);
  softEllipse(770, 1600, 360, 0.30, '255,180,100', 0.16);
  softEllipse(768, 1618, 120, 0.22, '255,200,120', 0.12);
  blendMode(BLEND);
}

function drawAmbientLight() {
  blendMode(ADD);
  softEllipse(766, 1188, 150, 1, '255,180,95', 0.55);
  softEllipse(766, 1188, 430, 1, '255,150,70', 0.20);
  softEllipse(780, 1250, 1150, 1, '190,110,55', 0.08);
