}

// ---------- la cire ----------

function drawPool() {
  noStroke();
  const cx = 770, cy = 1552;
  const layers = 9;
  for (let i = 0; i < layers; i++) {
    const f = i / (layers - 1); // 0 = bord, 1 = centre
    const rx = lerp(205, 58, f) * (0.96 + random() * 0.10);
    const ox = (random() - 0.5) * 14;
    const oy = (random() - 0.5) * 6;
    const c = lerpColor(color(88, 72, 56), color(236, 219, 188), pow(f, 1.25));
    fill(red(c), green(c), blue(c), 95);
    ellipse(cx + ox, cy + oy, rx * 2, rx * 0.34 * 2);
  }
  // lobes irréguliers au pourtour
  for (let i = 0; i < 14; i++) {
    const a = random(TWO_PI);
    const x = cx + cos(a) * 205 * (0.86 + random() * 0.16);
    const y = cy + sin(a) * 205 * 0.34 * (0.86 + random() * 0.16);
    fill(112, 94, 72, 85);
    ellipse(x, y, random(34, 70), random(14, 26));
  }
  // point chaud : cire encore lumineuse près de la mèche
  blendMode(ADD);
  softEllipse(774, 1546, 130, 0.30, '255,214,140', 0.55);
  blendMode(BLEND);
}

function drawCandle() {
  noStroke();
  const shadowC = color(64, 52, 40);
  const litC = color(255, 241, 213);
  for (let y = BASE_Y; y >= TOP_Y; y -= 2) {
    const f = (BASE_Y - y) / (BASE_Y - TOP_Y);
    const cx = lerp(BX, TOP_X, f) + (noise(f * 7 + 30) - 0.5) * 7;
    const hw = lerp(HW0, HW1, f);
    const dF = dist(cx, y, FLAME_TIP_X, FLAME_TIP_Y);
    const li = constrain(1 - dF / 560, 0, 1);
    for (let sx = -hw; sx <= hw; sx += 3.2) {
      const edge = 1 - pow(abs(sx) / hw, 1.5);
      let sh = 0.22 + 0.26 * edge + 0.58 * li * (0.30 + 0.70 * edge);
      sh = constrain(sh + (random() - 0.5) * 0.06, 0, 1);
      fill(lerpColor(shadowC, litC, sh));
      rect(cx + sx - 1.8, y - 1.5, 4.6, 3.2);
    }
  }
}

function drawDrips() {
  drip(726, 1368, 138, 8.5);
  drip(724, 1258, 76, 6.5);
  drip(816, 1398, 92, 7);
  drip(820, 1435, 118, 8);
}

function drip(x, y, len, r) {
  noStroke();
  for (let i = 0; i <= len; i += 3) {
    const t = i / len;
    const rr = lerp(r, r * 0.55, t);
    fill(lerpColor(color(238, 222, 196), color(146, 122, 96), t));
    circle(x + (noise(t * 3 + x) - 0.5) * 3, y + i, rr * 2);
  }
  // goutte figée au bout
  fill(150, 126, 100);
  circle(x, y + len + r * 0.4, r * 2.2);
  fill(255, 238, 210, 140);
  circle(x - r * 0.3, y + len + r * 0.2, r * 0.8);
}

function drawCandleTop() {
  noStroke();
  // rebord fondu, irrégulier, éclairé par le haut
  for (let x = TOP_X - HW1; x <= TOP_X + HW1; x += 5) {
    const bump = (noise(x * 0.045 + 80) - 0.5) * 16;
    fill(255, 243, 216);
    circle(x, TOP_Y + bump, 9);
  }
  // cratère de cire fondue
  fill(52, 40, 30);
  ellipse(TOP_X, TOP_Y + 5, 74, 22);
  fill(255, 186, 105, 200);
  ellipse(TOP_X, TOP_Y + 6, 48, 13);
  blendMode(ADD);
  softEllipse(TOP_X, TOP_Y + 6, 46, 0.35, '255,190,110', 0.5);
  blendMode(BLEND);
}

// ---------- mèche et flamme ----------

function drawWick() {
  stroke(30, 24, 20);
  strokeWeight(4.5);
  noFill();
  bezier(TOP_X - 2, TOP_Y + 8, TOP_X - 6, TOP_Y - 12, 761, 1212, 766, 1204);
  noStroke();
  fill(255, 160, 70);
  circle(766, 1204, 5);
  blendMode(ADD);
  softEllipse(766, 1204, 22, 1, '255,150,60', 0.5);
  blendMode(BLEND);
}

function drawFlame() {
  blendMode(ADD);
  softEllipse(766, 1192, 210, 1, '255,170,80', 0.45);
  softEllipse(766, 1195, 90, 1, '255,200,110', 0.5);
  blendMode(BLEND);
  noStroke();
  fill(96, 132, 255, 110);        // base bleutée
  flameShape(766, 1209, 17, 20, 2);
  fill(255, 122, 30, 240);        // enveloppe
  flameShape(766, 1210, 26, 64, 6);
  fill(255, 204, 92, 250);        // cœur doré
  flameShape(766.5, 1207, 17, 46, 4);
  fill(255, 247, 218);            // cœur blanc
  flameShape(767, 1205, 10, 27, 2);
}

// ---------- la fumée ----------

function drawSmoke() {
  noStroke();
  const srcY = 1146;
  for (let y = srcY; y >= -12; y -= 5) {
    const t = (srcY - y) / (srcY + 12);
    const x = smokeX(t);
    const w = lerp(6, 82, pow(t, 1.12));
    const a = 105 * pow(1 - t, 1.65);
    const tw = constrain(t * 4, 0, 1);
    const cr = lerp(212, 128, tw);
    const cg = lerp(198, 140, tw);
    const cb = lerp(188, 158, tw);
    // brin principal
    fill(cr, cg, cb, a);
    circle(x + random(-2, 2), y + random(-1, 1), w);
    // brin central plus clair
    const x2 = x + (noise(t * 3.3 + 400) - 0.5) * w * 0.8;
    fill(cr + 25, cg + 20, cb + 18, a * 0.85);
    circle(x2, y + random(-1, 1), w * 0.42);
    // brin latéral diffus
    const x3 = x + (noise(t * 2.6 + 800) - 0.5) * w * 1.6 - w * 0.5;
    fill(cr, cg, cb, a * 0.45);
    circle(x3, y, w * 0.55);
  }
}

function drawParticles() {
  noStroke();
  // la fumée se défait en poussière
  for (let i = 0; i < 900; i++) {
    const t = constrain(0.42 + random() * 0.62, 0, 1);
    const y = 1146 * (1 - t);
    const spread = lerp(70, 640, pow(t, 1.5));
    const ang = random(TWO_PI);
    const rr = pow(random(), 0.55);
    const x = smokeX(t) + cos(ang) * rr * spread * 0.5 + sin(ang) * rr * spread * 0.18;
    const sz = lerp(1.6, 7, t) * (0.4 + random());
    const a = 4 + 55 * pow(1 - t, 2.2) * random();
    fill(148, 158, 176, a);
    circle(x, y, sz);
  }
  // poussière dormante dans le vide
  for (let i = 0; i < 420; i++) {
    fill(140, 150, 168, 3 + random() * 6);
    circle(random(width), random(0, 850), 1 + random() * 1.8);
  }
}

// ---------- poussière dans la lumière, cendres ----------

function drawDustMotes() {
  blendMode(ADD);
  noStroke();
  for (let i = 0; i < 130; i++) {
    const ang = random(TWO_PI);
    const rad = pow(random(), 1.6) * 580;
    const x = 766 + cos(ang) * rad;
    const y = 1185 + sin(ang) * rad * 0.85;
    if (y > 1540) continue;
    const a = (10 + random() * 45) * (1 - rad / 620);
    fill(255, 208, 148, max(a, 0));
    circle(x, y, 1 + random() * 2.2);
  }
  blendMode(BLEND);
}

function drawAsh() {
  noStroke();
  for (let i = 0; i < 46; i++) {
    const x = 770 + (random() * 2 - 1) * 270;
    const y = 1556 + (random() * 2 - 1) * 64;
    if (abs(x - 770) < 150 && abs(y - 1552) < 55) continue;
    fill(22, 18, 14, 110 + random() * 120);
    circle(x, y, 1.5 + random() * 3.5);
  }
}

// ---------- finitions ----------

function drawVignette() {
  const vg = drawingContext.createRadialGradient(800, 1030, 480, 800, 1030, 1420);
  vg.addColorStop(0, 'rgba(0,0,0,0)');
  vg.addColorStop(1, 'rgba(0,0,0,0.55)');
  drawingContext.fillStyle = vg;
  drawingContext.fillRect(0, 0, width, height);

  const bgd = drawingContext.createLinearGradient(0, 1650, 0, height);
  bgd.addColorStop(0, 'rgba(0,0,0,0)');
  bgd.addColorStop(1, 'rgba(0,0,0,0.45)');
  drawingContext.fillStyle = bgd;
  drawingContext.fillRect(0, 1650, width, height - 1650);
}

function drawGrain() {
  noStroke();
  for (let i = 0; i < 26000; i++) {
    const x = random(width);
    const y = random(height);
    if (random() < 0.5) fill(255, 238, 220, 2 + random() * 5);
    else fill(0, 0, 0, 3 + random() * 6);
    rect(x, y, 1.6, 1.6);
  }
}

// La Veille — p5.js 1.11
let W = 1600, H = 2000;

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();
  peindre();
}

function draw() {}

function halo(x, y, r, cr, cg, cb, a) {
  noStroke(); fill(cr, cg, cb, a); ellipse(x, y, r * 2, r * 2);
}
function haloEllipse(x, y, rx, ry, cr, cg, cb, a) {
  noStroke(); fill(cr, cg, cb, a); ellipse(x, y, rx * 2, ry * 2);
}

function peindre() {
  // ---------- fond : nuit froide vers pénombre chaude
  noStroke();
  for (let i = 0; i < 90; i++) {
    let t = i / 89;
    fill(lerpColor(color(11, 12, 18), color(28, 21, 15), Math.pow(t, 1.25)));
    rect(0, i * H / 90 - 1, W, H / 90 + 2);
  }

  // ---------- matière sombre, nappes irrégulières
  for (let i = 0; i < 850; i++) {
    let x = random(W), y = random(H);
    let r = 18 + random(85);
    let a = 2.5 + random(6);
    if (noise(x * 0.002, y * 0.002) > 0.55) fill(32, 28, 24, a);
    else fill(3, 3, 6, a + 1.5);
    ellipse(x, y, r * 2, r * 1.35);
  }

  // ---------- brume froide du haut
  haloEllipse(800, 110, 875, 320, 44, 54, 86, 8);
  haloEllipse(800, 160, 675, 240, 44, 54, 86, 8);

  // ---------- table
  noStroke(); fill(25, 18, 13); rect(0, 1745, W, H - 1745);

  // ---------- lueur ambiante de la flamme
  halo(800, 1495, 1000, 255, 148, 66, 4);
  halo(800, 1495, 700, 255, 148, 66, 7);
  halo(800, 1495, 480, 255, 152, 70, 11);
  halo(800, 1495, 320, 255, 156, 72, 16);
  halo(800, 1495, 210, 255, 160, 74, 24);
  halo(800, 1495, 132, 255, 166, 80, 34);
  haloEllipse(800, 1782, 640, 118, 255, 160, 70, 5);
  haloEllipse(800, 1782, 430, 82, 255, 160, 70, 8);
  haloEllipse(800, 1782, 285, 56, 255, 162, 72, 12);
  haloEllipse(800, 1782, 180, 36, 255, 164, 74, 18);
  haloEllipse(800, 1782, 108, 22, 255, 168, 78, 26);
  haloEllipse(800, 1840, 34, 140, 255, 170, 80, 9);

  // ---------- grain du mur, révélé par la lumière
  for (let i = 0; i < 11000; i++) {
    let x = random(W), y = random(1748);
    let wgt = 1 / (1 + dist(x, y, 800, 1495) / 230);
    if (random() > 0.15 + wgt * 0.85) continue;
    let warm = random() < 0.2 + wgt * 0.75;
    let a = (1.2 + random(3.5)) * (0.25 + wgt);
    let ln = 8 + random(24), an = random(TWO_PI);
    stroke(warm ? 72 : 40, warm ? 58 : 42, warm ? 46 : 52, a);
    strokeWeight(0.8 + random(1.6));
    line(x, y, x + Math.cos(an) * ln, y + Math.sin(an) * ln);
  }
  noStroke();

  // ---------- grain du bois
  for (let i = 0; i < 2200; i++) {
    let x = random(W), y = 1752 + random(244);
    let wgt = 1 / (1 + Math.abs(x - 800) / 190);
    if (random() > 0.2 + wgt * 0.8) continue;
    let ln = 50 + random(140), an = random(-0.06, 0.06);
    stroke(64, 46, 30, 2 + random(7) * (0.3 + wgt));
    strokeWeight(1 + random(2));
    line(x, y, x + Math.cos(an) * ln, y + Math.sin(an) * ln);
  }
  noFill();
  for (const py of [1816, 1884, 1950]) {
    stroke(0, 0, 0, 45); strokeWeight(3);
    beginShape();
    for (let x = 0; x <= W; x += 90) vertex(x, py + (noise(x * 0.004, py) - 0.5) * 6);
    endShape();
    stroke(120, 90, 60, 12); strokeWeight(1);
    beginShape();
    for (let x = 0; x <= W; x += 90) vertex(x, py - 3 + (noise(x * 0.004, py) - 0.5) * 6);
    endShape();
  }
  noStroke();

  // ---------- étoiles
  for (let i = 0; i < 420; i++) {
    let y = 1150 * Math.pow(random(), 1.5);
    let x = random(W);
    let b = random();
    noStroke(); fill(238, 236, 226, (14 + 90 * b) * (1 - y / 1500));
    ellipse(x, y, 1 + 2 * b, 1 + 2 * b);
  }
  strokeWeight(1);
  for (let i = 0; i < 14; i++) {
    let x = random(W), y = random(700), l = 6 + random(11);
    stroke(240, 238, 228, 55);
    line(x - l, y, x + l, y); line(x, y - l, x, y + l);
  }
  noStroke();

  // ---------- fumée : colonne, volutes, poussière
  const Y0 = 1430, Y1 = 95;
  let prog = (y) => constrain((Y0 - y) / (Y0 - Y1), 0, 1);
  let colX = (y) => 800 + (noise((Y0 - y) * 0.0012 + 7.7) - 0.5) * 600 * Math.pow(prog(y), 1.35);
  let colW = (y) => 30 + 330 * Math.pow(prog(y), 2.2);

  for (let s = 0; s < 7; s++) {
    for (let y = 1418; y > 110; y -= 5) {
      let p = prog(y);
      let x = colX(y) + (noise(s * 9.1 + (Y0 - y) * 0.0031) - 0.5) * 2 * colW(y) * 0.85;
      let r = 7 + 26 * p + noise(s * 3.3 + y * 0.02) * 5;
      let a = lerp(12, 2.5, p) * (0.6 + 0.7 * noise(s * 5.5 + (Y0 - y) * 0.008));
      noStroke();
      fill(lerp(172, 118, p), lerp(162, 126, p), lerp(152, 150, p), a);
      ellipse(x, y, r * 2, r * 2.3);
    }
  }
  for (let i = 0; i < 1150; i++) {
    let y = 120 + Math.pow(random(), 0.62) * (Y0 - 135);
    let p = prog(y);
    let x = colX(y) + randomGaussian() * colW(y) * 0.55;
    let r = 5 + random(15) + 14 * p;
    noStroke();
    fill(lerp(170, 120, p), lerp(160, 128, p), 150, (2.5 + random(7)) * (1 - p * 0.6));
    ellipse(x, y, r * 2, r * 2);
  }
  for (let i = 0; i < 560; i++) {
    let y = 12 + random(480);
    let x = colX(y) + randomGaussian() * colW(y) * 0.95;
    let a = (16 + random(55)) * (0.5 + 0.5 * noise(x * 0.01, y * 0.01));
    noStroke(); fill(205, 212, 232, a);
    ellipse(x, y, 1 + random(2), 1 + random(2));
  }

  // ---------- poussières et étincelles autour de la flamme
  for (let i = 0; i < 55; i++) {
    let an = random(TWO_PI), rr = 50 + random(300);
    let x = 800 + Math.cos(an) * rr, y = 1495 + Math.sin(an) * rr * 0.9;
    noStroke(); fill(255, 202, 132, (14 + random(52)) * (1 - rr / 380));
    ellipse(x, y, 1 + random(1.8), 1 + random(1.8));
  }
  for (let i = 0; i < 14; i++) {
    let x = 800 + randomGaussian() * 55;
    let y = 1450 + randomGaussian() * 60 - random(180);
    noStroke(); fill(255, 186, 96, 70 + random(110));
    ellipse(x, y, 2 + random(2), 2 + random(2));
    fill(255, 170, 80, 16); ellipse(x, y, 10, 10);
  }

  // ---------- ombres
  noStroke();
  fill(0, 0, 0, 110); ellipse(1015, 1766, 160, 22);
  fill(0, 0, 0, 40); ellipse(1078, 1774, 240, 26);
  fill(0, 0, 0, 90); ellipse(548, 1762, 150, 20);

  // ---------- les deux bougies
  bougie(800, 120, 1560, 1760, true);
  bougie(1015, 88, 1660, 1760, false);

  // ---------- mèche et flammèche
  stroke(18, 14, 12); strokeWeight(4); line(800, 1560, 800, 1543);
  noStroke();
  fill(255, 118, 28, 205); flamme(800, 1442, 1552, 58);
  fill(255, 204, 88, 235); flamme(800, 1464, 1548, 34);
  fill(255, 246, 226, 255); flamme(800, 1484, 1542, 15);
  fill(96, 132, 255, 130); ellipse(800, 1547, 18, 9);
  fill(255, 255, 245, 220); ellipse(800, 1521, 6, 10);

  // ---------- papillons de nuit
  moth(690, 1292, 64, 235, 0.35, true);
  moth(941, 1516, 40, 215, -0.5, true);
  moth(864, 906, 25, 70, 0.9, false);
  moth(315, 1120, 20, 40, -0.7, false);

  // ---------- fleur qui penche, pétales tombés
  fleur();

  // ---------- allumette consumée
  allumette();

  // ---------- vignettage
  noFill();
  for (let r = 850; r < 1520; r += 6) {
    stroke(0, 0, 0, map(r, 850, 1520, 0, 4.5));
    strokeWeight(42);
    ellipse(800, 1000, r * 2, r * 2);
  }
  noStroke();

  // ---------- rehaut final de la flamme
  halo(800, 1497, 120, 255, 176, 84, 50);
  halo(800, 1497, 50, 255, 224, 148, 70);
}

function bougie(x, w, topY, baseY, lit) {
  noStroke();
  fill(lit ? 206 : 112, lit ? 188 : 103, lit ? 156 : 94);
  rect(x - w / 2, topY, w, baseY - topY);
  ellipse(x, baseY, w, 16);
  fill(0, 0, 0, lit ? 70 : 55);
  rect(x - w / 2, topY, w * 0.30, baseY - topY);
  fill(0, 0, 0, lit ? 42 : 34);
  rect(x + w * 0.26, topY, w * 0.24, baseY - topY);
  fill(lit ? 226 : 124, lit ? 206 : 114, lit ? 168 : 103);
  ellipse(x, topY, w, w * 0.22);
  if (!lit) {
    fill(52, 44, 40);
    ellipse(x, topY, w * 0.86, w * 0.18);
    stroke(18, 15, 13); strokeWeight(3); noFill();
    bezier(x, topY - 2, x + 3, topY - 9, x + 7, topY - 12, x + 11, topY - 16);
    noStroke();
  }
  if (lit) {
    fill(255, 150, 60, 46); rect(x - w / 2, topY, w, 46);
    fill(255, 226, 180, 55); rect(x - w * 0.09, topY + 6, w * 0.15, baseY - topY - 30);
    fill(255, 240, 210, 120); ellipse(x, topY - 2, w * 0.8, w * 0.14);
    coulure(x - w * 0.32, topY + 6, 130);
    coulure(x + w * 0.30, topY + 6, 66);
    coulure(x - w * 0.05, topY + 5, 190);
    fill(222, 204, 168); ellipse(x, baseY + 2, w * 1.6, 22);
    fill(238, 220, 184, 130); ellipse(x, baseY, w * 0.9, 14);
  } else {
    fill(255, 150, 70, 22); rect(x - w / 2, topY, w * 0.14, 44);
    fill(255, 160, 80, 20); rect(x - w / 2, topY, w, 8);
    coulureSeche(x + w * 0.26, topY + 6, 42);
  }
}

function coulure(x, y, len) {
  noStroke(); fill(224, 206, 170, 235);
  let steps = Math.max(6, Math.floor(len / 9));
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    let cx = x + Math.sin(x * 0.05 + t * 2.0) * 4;
    let r = 6.5 - t * 2.5;
    ellipse(cx, y + t * len, r * 2, r * 2.2);
  }
  ellipse(x + Math.sin(x * 0.05 + 2.0) * 4, y + len + 3, 12, 14);
}

function coulureSeche(x, y, len) {
  noStroke(); fill(118, 108, 98, 220);
  let steps = Math.max(5, Math.floor(len / 8));
  for (let i = 0; i <= steps; i++) {
    let t = i / steps;
    ellipse(x + Math.sin(x * 0.06 + t * 1.6) * 3, y + t * len, 9 - t * 3, 8 - t * 2);
  }
}

function flamme(cx, ty, by, w) {
  noStroke();
  beginShape();
  vertex(cx, ty);
  bezierVertex(cx + w * 0.55, ty + (by - ty) * 0.38, cx + w * 0.64, by - 6, cx, by);
  bezierVertex(cx - w * 0.64, by - 6, cx - w * 0.55, ty + (by - ty) * 0.38, cx, ty);
  endShape(CLOSE);
}

function moth(x, y, s, al, rot, blur) {
  push(); translate(x, y); rotate(rot);
  if (blur) { push(); translate(6, -7); rotate(0.14); mothShape(s, al * 0.3); pop(); }
  mothShape(s, al);
  pop();
}

function mothShape(s, al) {
  noStroke(); fill(22, 17, 15, al);
  ellipse(0, 0, s * 0.14, s * 0.55);
  beginShape(); vertex(s * 0.05, -s * 0.06);
  bezierVertex(s * 0.58, -s * 0.44, s * 0.64, s * 0.12, s * 0.07, s * 0.12);
  endShape(CLOSE);
  beginShape(); vertex(-s * 0.05, -s * 0.06);
  bezierVertex(-s * 0.58, -s * 0.44, -s * 0.64, s * 0.12, -s * 0.07, s * 0.12);
  endShape(CLOSE);
  beginShape(); vertex(s * 0.05, s * 0.10);
  bezierVertex(s * 0.36, s * 0.26, s * 0.30, s * 0.55, s * 0.06, s * 0.34);
  endShape(CLOSE);
  beginShape(); vertex(-s * 0.05, s * 0.10);
  bezierVertex(-s * 0.36, s * 0.26, -s * 0.30, s * 0.55, -s * 0.06, s * 0.34);
  endShape(CLOSE);
  stroke(22, 17, 15, al); strokeWeight(1.5);
  line(0, -s * 0.24, s * 0.10, -s * 0.46);
  line(0, -s * 0.24, -s * 0.10, -s * 0.46);
  noStroke();
}

function fleur() {
  stroke(58, 56, 38); strokeWeight(6); noFill();
  bezier(548, 1752, 536, 1692, 546, 1632, 576, 1592);
  bezier(576, 1592, 600, 1562, 630, 1560, 642, 1592);
  stroke(150, 128, 82, 70); strokeWeight(2);
  bezier(546, 1750, 534, 1690, 544, 1632, 574, 1594);
  noStroke();
  fill(46, 52, 34, 235);
  beginShape();
  vertex(546, 1728);
  bezierVertex(486, 1700, 462, 1648, 498, 1598);
  bezierVertex(522, 1642, 542, 1688, 546, 1728);
  endShape(CLOSE);
  stroke(150, 128, 82, 50); strokeWeight(2); noFill();
  beginShape();
  vertex(543, 1722);
  bezierVertex(502, 1692, 486, 1652, 503, 1614);
  endShape();
  noStroke();
  petale(642, 1590, 0);
  petale(642, 1590, 0.38);
  petale(642, 1590, -0.38);
  fill(60, 56, 38);
  ellipse(642, 1582, 26, 14);
  petaleTombee(452, 1796, 0.35);
  petaleTombee(608, 1846, -0.5);
}

function petale(cx, cy, rot) {
  push(); translate(cx, cy); rotate(rot);
  fill(122, 34, 44, 240);
  stroke(232, 148, 76, 60); strokeWeight(2);
  beginShape();
  vertex(-9, -6);
  bezierVertex(-22, 26, -14, 62, 0, 78);
  bezierVertex(14, 62, 22, 26, 9, -6);
  endShape(CLOSE);
  pop(); noStroke();
}

function petaleTombee(x, y, rot) {
  push(); translate(x, y); rotate(rot);
  fill(84, 22, 32, 235);
  beginShape();
  vertex(-18, 0);
  bezierVertex(-16, 9, 16, 9, 18, 0);
  bezierVertex(16, -9, -16, -9, -18, 0);
  endShape(CLOSE);
  stroke(220, 140, 74, 55); strokeWeight(1.5);
  line(-15, -1, 15, -1);
  pop(); noStroke();
}

function allumette() {
  stroke(74, 52, 34); strokeWeight(5);
  line(1078, 1832, 1152, 1838);
  stroke(120, 96, 70, 60); strokeWeight(1.5);
  line(1079, 1829, 1150, 1835);
  noStroke();
  fill(24, 21, 19); ellipse(1153, 1838, 13, 11);
  fill(96, 94, 92, 160); ellipse(1156, 1841, 6, 5);
}

/* ================================================================
   « Ce qui demeure » — peinture générative, image fixe, 1600 × 2000
   Un arbre mort au-dessus de la ligne du sol ; en dessous, ses
   racines se changent en un réseau d'or qui nourrit les pousses.
   ================================================================ */

const W = 1600, H = 2000;
const GROUND = 1180;                 // ligne de terre
const ROOTX  = 880;                  // pied de l'arbre
const MX = 400, MY = 300, MR = 95;   // la lune

let rootPts = [];                    // points le long des racines
let canopyTips = [];                 // extrémités de la couronne morte
let seedlingSpots = [];              // pieds des jeunes pousses
let crowSpot = null;                 // perchoir du corbeau

function setup() {
  createCanvas(W, H);
  randomSeed(1);
  noiseSeed(1);
  pixelDensity(1);
  noLoop();

  pickSeedlingSpots();

  sky();
  stars();
  moon();
  cloudVeils();
  horizonGlow();
  mist();

  underground();
  strata();
  glowField();

  roots();         // remplit rootPts
  mycelium();      // le réseau doré

  surfaceRoots();  // racines du pied, visibles
  tree();          // l'arbre mort
  crow();

  treeShadow();
  pebbles();
  twigs();
  deadLeaves();
  grasses();

  seedlings();
  mushrooms();
  spores();

  vignette();
  grain();
}

/* ---------------- le ciel ---------------- */

function sky() {
  const top = color(3, 5, 12);
  const mid = color(10, 17, 31);
  const low = color(24, 34, 52);
  for (let y = 0; y <= GROUND; y++) {
    const t = y / GROUND;
    const c = t < 0.62 ? lerpColor(top, mid, t / 0.62)
                       : lerpColor(mid, low, (t - 0.62) / 0.38);
    stroke(c);
    line(0, y, W, y);
  }
  noStroke();
}

function stars() {
  noStroke();
  for (let i = 0; i < 180; i++) {
    const x = random(W);
    const y = pow(random(1), 1.4) * GROUND * 0.8;
    const b = random(25, 165);
    const r = random(0.4, 1.6);
    fill(214, 227, 244, b);
    circle(x, y, r * 2);
    if (b > 130) {
      fill(190, 208, 235, 16);
      circle(x, y, r * 7);
    }
  }
}

function moon() {
  noStroke();
  for (let i = 10; i >= 1; i--) {            // halo froid
    fill(176, 196, 228, 3);
    circle(MX, MY, MR * 2 + i * 36);
  }
  fill(212, 221, 236);                       // disque
  circle(MX, MY, MR * 2);
  fill(226, 234, 246, 90);                   // relief doux
  circle(MX - 24, MY - 22, MR * 2 - 76);
  const seas = [[-30, -18, 24], [16, 10, 32], [-6, 36, 16], [28, -30, 13], [34, 28, 11]];
  fill(158, 173, 196, 48);                   // mers lunaires
  for (const s of seas) circle(MX + s[0], MY + s[1], s[2] * 2);
  fill(186, 200, 220, 22);                   // grain lunaire
  for (let i = 0; i < 110; i++) {
    const a = random(TWO_PI);
    const r = sqrt(random(1)) * MR * 0.95;
    circle(MX + cos(a) * r, MY + sin(a) * r, random(1.2, 3.2));
  }
}

function cloudVeils() {
  noStroke();
  for (let i = 0; i < 7; i++) {              // brume glissant sur la lune
    const y = MY - 100 + i * 58 + random(36);
    const x = MX - 300 + random(260);
    fill(7, 11, 22, random(55, 95));
    ellipse(x, y, 360 + random(340), 22 + random(26));
  }
  fill(5, 8, 16, 55);
  ellipse(860, 110, 1100, 190);
  fill(4, 7, 14, 70);
  ellipse(240, 700, 900, 200);
  ellipse(1400, 560, 700, 160);
}

function horizonGlow() {
  noStroke();
  for (let i = 0; i < 4; i++) {
    fill(66, 84, 116, 7);
    ellipse(W * 0.5, GROUND - 6, 1750 - i * 180, 300 - i * 55);
  }
}

function mist() {
  noStroke();
  for (let i = 0; i < 30; i++) {
    fill(116, 134, 164, random(5, 13));
    ellipse(random(-150, W + 100), GROUND - random(8, 160),
            random(260, 640), random(22, 58));
  }
}

/* ---------------- le sous-sol ---------------- */

function underground() {
  const a = color(13, 15, 21);
  const b = color(4, 5, 9);
  for (let y = GROUND; y < H; y++) {
    const t = (y - GROUND) / (H - GROUND);
    stroke(lerpColor(a, b, t));
    line(0, y, W, y);
  }
  noStroke();
}

function strata() {
  noFill();
  stroke(30, 35, 47, 38);
  strokeWeight(1.2);
  for (let s = 0; s < 6; s++) {
    const baseY = GROUND + 95 + s * 135;
    beginShape();
    for (let x = -30; x <= W + 30; x += 26) {
      vertex(x, baseY + (noise(x * 0.004 + s * 13.7, s * 7.1) - 0.5) * 62);
    }
    endShape();
  }
  noStroke();
}

function glowField() {                        // lueur dorée du cœur du réseau
  noStroke();
  for (let i = 15; i >= 1; i--) {
    fill(212, 158, 60, 3);
    circle(ROOTX, 1580, 260 + i * 88);
  }
}

/* ---------------- racines mortes, devenues or ---------------- */

function roots() {
  const offs = [-0.82, -0.5, -0.22, 0, 0.26, 0.55, 0.86];
  for (const o of offs) {
    growRoot(ROOTX + o * 14, GROUND - 4, HALF_PI + o,
             235 + random(95), 23 + random(11), 0);
  }
}

function growRoot(x, y, ang, len, wid, d) {
  const steps = 5;
  let px = x, py = y, pa = ang;
  const pts = [{ x: px, y: py, w: wid }];
  for (let i = 1; i <= steps; i++) {
    pa += (noise(px * 0.011, py * 0.011, 40 + d * 5.3) - 0.5) * 0.55;
    pa += (HALF_PI - pa) * 0.07;              // gravité : descendre
    px += cos(pa) * (len / steps);
    py += sin(pa) * (len / steps);
    if (px < 160)  pa = lerp(pa, 0, 0.4);     // rester dans la toile
    if (px > 1440) pa = lerp(pa, PI, 0.4);
    if (py > H - 55) py = H - 55;
    pts.push({ x: px, y: py, w: lerp(wid, wid * 0.55, i / steps) });
  }
  drawRoot(pts);
  for (let i = 1; i < pts.length; i += 2) rootPts.push(pts[i]);
  const wTip = pts[steps].w;
  if (d >= 3 || wTip < 1.4) return;
  const nb = 2 + (random() < 0.45 ? 1 : 0);
  for (let i = 0; i < nb; i++) {
    const off = (i - (nb - 1) / 2) * (0.42 + random(0.34)) + (random() - 0.5) * 0.22;
    growRoot(px, py, pa + off, len * (0.58 + random(0.2)), wTip, d + 1);
  }
}

function drawRoot(pts) {                      // brun épais → or filamentaire
  strokeCap(ROUND);
  noFill();
  for (let i = 1; i < pts.length; i++) {
    const p0 = pts[i - 1], p1 = pts[i];
    const w = (p0.w + p1.w) * 0.5;
    if (w > 7.5) {
      stroke(28, 21, 14); strokeWeight(w);
      line(p0.x, p0.y, p1.x, p1.y);
      stroke(58, 44, 26, 100); strokeWeight(w * 0.38);
      line(p0.x - w * 0.16, p0.y - w * 0.1, p1.x - w * 0.16, p1.y - w * 0.1);
    } else {
      const t = constrain(map(w, 7.5, 1.2, 0, 1), 0, 1);
      if (t > 0.3) {
        stroke(214, 158, 60, 26); strokeWeight(w * 2.6 + 2);
        line(p0.x, p0.y, p1.x, p1.y);
      }
      stroke(lerp(48, 232, t), lerp(36, 178, t), lerp(22, 76, t), lerp(255, 200, t));
      strokeWeight(w);
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
}

/* ---------------- le mycélium ---------------- */

function mycelium() {
  for (const t of seedlingSpots) {           // chaque pousse est atteinte
    for (let k = 0; k < 3; k++) {
      const s = nearestRootPt(t);
      const n = ceil(dist(s.x, s.y, t.x, t.y) / 8 * 1.6) + 6;
      hypha(s.x, s.y, atan2(t.y - s.y, t.x - s.x), n, 0, t);
    }
  }
  for (let i = 0; i < 240; i++) {            // puis le réseau libre
    const s = rootPts[floor(random(rootPts.length))];
    hypha(s.x, s.y, random(TWO_PI), 16 + floor(random(38)), 0, null);
  }
}

function nearestRootPt(t) {
  let best = rootPts[0], bd = Infinity;
  for (let i = 0; i < 10; i++) {
    const p = rootPts[floor(random(rootPts.length))];
    const d = dist(p.x, p.y, t.x, t.y);
    if (d < bd) { bd = d; best = p; }
  }
  return best;
}

function hypha(x, y, ang, n, gen, target) {
  const step = 6.5 + random(3.5);
  let px = x, py = y, pa = ang;
  const pts = [[px, py]];
  let bright = map(dist(px, py, ROOTX, 1560), 0, 720, 135, 55, true)
               + random(-14, 14);
  if (target) bright += 30;
  for (let i = 0; i < n; i++) {
    pa += (noise(px * 0.013, py * 0.013, 90 + gen * 31.7) - 0.5) * 1.15;
    if (target) {
      pa = lerp(pa, atan2(target.y - py, target.x - px), 0.16);
    } else {
      pa = lerp(pa, atan2(py - 1560, px - ROOTX), 0.05);   // fuir le cœur
      pa = lerp(pa, HALF_PI, 0.015);
    }
    px += cos(pa) * step;
    py += sin(pa) * step;
    const minY = target ? target.y - 2 : GROUND + 12;
    if (px < 135)  pa = lerp(pa, 0, 0.6);
    if (px > 1465) pa = lerp(pa, PI, 0.6);
    if (py < minY) pa = lerp(pa, HALF_PI, 0.6);
    if (py > H - 28) pa = lerp(pa, -HALF_PI, 0.6);
    pts.push([px, py]);
    if (gen < 2 && i > 5 && random() < 0.05) {
      hypha(px, py, pa + (random() < 0.5 ? -1 : 1) * (0.5 + random(0.7)),
            floor(n * 0.45), gen + 1, null);
    }
  }
  noFill();
  stroke(214, 160, 66, bright * 0.32); strokeWeight(3);    // halo
  poly(pts);
  stroke(242, 204, 120, bright); strokeWeight(1.15);       // filament
  poly(pts);
  for (let i = 3; i < pts.length; i += 5) {
    if (random() < 0.45) node(pts[i][0], pts[i][1], random(0.9, 2.1), bright);
  }
  if (target) node(pts[pts.length - 1][0], pts[pts.length - 1][1], 2.6, bright + 40);
}

function poly(pts) {
  noFill();
  beginShape();
  for (const p of pts) vertex(p[0], p[1]);
  endShape();
}

function node(x, y, r, a) {                  // spore lumineuse
  noStroke();
  fill(255, 234, 165, a * 0.14);
  circle(x, y, r * 8);
  fill(255, 240, 190, a * 0.32);
  circle(x, y, r * 4.4);
  fill(255, 246, 210, min(255, a + 80));
  circle(x, y, r * 2);
}

/* ---------------- racines du pied, visibles ---------------- */

function qPoint(ax, ay, cx, cy, bx, by, t) {
  const u = 1 - t;
  return [u * u * ax + 2 * u * t * cx + t * t * bx,
          u * u * ay + 2 * u * t * cy + t * t * by];
}

function surfaceRoots() {
  noFill();
  strokeCap(ROUND);
  const offs = [-1.05, -0.62, -0.3, 0.28, 0.66, 1.02];
  for (const o of offs) {
    const spread = 70 + random(90);
    const x1 = ROOTX + (o > 0 ? 1 : -1) * (34 + spread);
    const y1 = GROUND + random(3, 15);
    const cx = ROOTX + o * 40, cy = GROUND - 30;
    for (let s = 0; s < 5; s++) {
      const a = qPoint(ROOTX, GROUND - 85, cx, cy, x1, y1, s / 5);
      const b = qPoint(ROOTX, GROUND - 85, cx, cy, x1, y1, (s + 1) / 5);
      const w = lerp(15 - abs(o) * 5, 2.5, s / 5);
      stroke(33, 30, 26); strokeWeight(w);
      line(a[0], a[1], b[0], b[1]);
      stroke(70, 64, 52, 90); strokeWeight(w * 0.35);
      line(a[0] - w * 0.15, a[1] - w * 0.08, b[0] - w * 0.15, b[1] - w * 0.08);
    }
  }
}

/* ---------------- l'arbre mort ---------------- */

function tree() {
  growTree(ROOTX, GROUND + 8, -HALF_PI + 0.04, 218, 62, 0);
}

function growTree(x, y, ang, len, wid, d) {
  const steps = 4;
  let px = x, py = y, pa = ang;
  const pts = [{ x: px, y: py, w: wid }];
  for (let i = 1; i <= steps; i++) {
    pa += (noise(px * 0.0045, py * 0.0045, d * 11.3) - 0.5) * 0.52;
    pa += 0.008;                                          // vent
    if (d > 4) pa += (HALF_PI - pa) * 0.014 * (d - 4);    // brindilles tombantes
    px += cos(pa) * (len / steps);
    py += sin(pa) * (len / steps);
    pts.push({ x: px, y: py, w: lerp(wid, wid * 0.58, i / steps) });
  }
  drawTree(pts);
  if (d <= 1) bark(pts);
  const wTip = pts[steps].w;
  if (d >= 9 || wTip < 1.15) {
    canopyTips.push({ x: px, y: py });
    return;
  }
  const nb = d < 2 ? 3 : (random() < 0.34 ? 3 : 2);
  for (let i = 0; i < nb; i++) {
    let off = (i - (nb - 1) / 2) * (0.4 + random(0.34)) + (random() - 0.5) * 0.24;
    if (d === 0 && i === 1) off *= 0.3;       // dominante verticale du tronc
    growTree(px, py, pa + off, len * (0.64 + random(0.18)), wTip, d + 1);
  }
  if (d >= 4 && d <= 6 && cos(pa) > 0.35 && px > 1020 && px < 1540 &&
      py > 330 && py < 950) {
    if (!crowSpot || cos(pa) > crowSpot.c) crowSpot = { x: px, y: py, a: pa, c: cos(pa) };
  }
}

function drawTree(pts) {                      // ombre, corps, lumière lunaire
  strokeCap(ROUND);
  noFill();
  for (let i = 1; i < pts.length; i++) {
    const p0 = pts[i - 1], p1 = pts[i];
    const w = (p0.w + p1.w) * 0.5;
    if (w > 4.6) {
      stroke(12, 14, 19); strokeWeight(w);
      line(p0.x + w * 0.11, p0.y + w * 0.09, p1.x + w * 0.11, p1.y + w * 0.09);
      stroke(42, 46, 54); strokeWeight(w);
      line(p0.x, p0.y, p1.x, p1.y);
      stroke(86, 97, 116, 140); strokeWeight(w * 0.36);
      line(p0.x - w * 0.16, p0.y - w * 0.1, p1.x - w * 0.16, p1.y - w * 0.1);
    } else {
      stroke(37, 41, 49, 235); strokeWeight(w);
      line(p0.x, p0.y, p1.x, p1.y);
    }
  }
}

function bark(pts) {                          // stries d'écorce
  noFill();
  for (let i = 1; i < pts.length; i++) {
    const p0 = pts[i - 1], p1 = pts[i];
    const w = (p0.w + p1.w) * 0.5;
    if (w < 9) continue;
    const segA = atan2(p1.y - p0.y, p1.x - p0.x);
    const nx = cos(segA + HALF_PI), ny = sin(segA + HALF_PI);
    const segLen = dist(p0.x, p0.y, p1.x, p1.y);
    for (let k = 0; k < 7; k++) {
      const t = random(1);
      const bx = lerp(p0.x, p1.x, t), by = lerp(p0.y, p1.y, t);
      const off = (random() - 0.5) * w * 0.85;
      const ln = segLen * random(0.3, 0.7);
      if (random() < 0.7) stroke(19, 22, 28, random(55, 130));
      else               stroke(92, 102, 120, random(40, 80));
      strokeWeight(random(0.8, 2.2));
      line(bx + nx * off, by + ny * off,
           bx + nx * off + cos(segA) * ln, by + ny * off + sin(segA) * ln);
    }
  }
}

/* ---------------- le corbeau ---------------- */

function crow() {
  if (!crowSpot) crowSpot = { x: ROOTX + 300, y: 680, a: -0.1 };
  push();
  translate(crowSpot.x, crowSpot.y);
  rotate(crowSpot.a);
  scale(1.25);
  strokeCap(ROUND);
  stroke(9, 10, 14); strokeWeight(2);         // pattes (derrière le corps)
  line(-3, -3, -3, 1);
  line(4, -4, 4, 1);
  noStroke();
  fill(8, 9, 13);                             // queue
  beginShape();
  vertex(4, -6); vertex(34, -22); vertex(41, -16); vertex(11, -2);
  endShape(CLOSE);
  push();                                     // corps
  translate(0, -12);
  rotate(-0.12);
  ellipse(0, 0, 32, 18);
  fill(38, 45, 58, 80);                       // reflet du dos
  ellipse(1, -4, 24, 6);
  pop();
  fill(8, 9, 13);                             // tête
  circle(-13, -21, 13);
  beginShape();                               // bec
  vertex(-18, -23.5); vertex(-30, -20.5); vertex(-18, -18.5);
  endShape(CLOSE);
  fill(46, 54, 70);                           // œil
  circle(-14.5, -22, 1.8);
  pop();
}

/* ---------------- la surface du sol ---------------- */

function treeShadow() {
  noStroke();
  for (let i = 0; i < 3; i++) {
    fill(2, 4, 8, 26);
    ellipse(ROOTX + 120 + i * 26, GROUND + 12 + i * 5, 660 - i * 70, 56 - i * 7);
