}

function deadLeaves() {
  for (let i = 0; i < 36; i++) {
    const x = ROOTX + lerp(-280, 640, random(1)) + random(-50, 50);
    const y = GROUND + lerp(2, 36, random(1));
    deadLeaf(x, y, random(PI), random(8, 15));
  }
}

function deadLeaf(x, y, a, s) {
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(3, 5, 8, 55);
  ellipse(1, 2.6, s * 1.7, s * 0.7);
  const cols = [[122, 84, 46], [97, 65, 38], [138, 97, 53], [84, 58, 40], [148, 105, 61]];
  const c = cols[floor(random(cols.length))];
  fill(c[0], c[1], c[2], 245);
  ellipse(0, 0, s * 1.55, s * 0.72);
  stroke(58, 41, 26, 200); strokeWeight(1.1);
  line(s * 0.65, 0, s * 1.05, 0);             // pétiole
  stroke(66, 48, 32, 120); strokeWeight(0.7);
  line(-s * 0.65, 0, s * 0.55, 0);            // nervure
  pop();
