function grasses() {
  noFill();
  for (let i = 0; i < 15; i++) {
    const x = i < 10 ? ROOTX + random(-520, 620) : random(80, W - 80);
    tuft(x, GROUND + random(0, 28), 7 + floor(random(8)), 24 + random(36));
  }
  noStroke();
}

function tuft(x, y, n, hMax) {
  for (let i = 0; i < n; i++) {
    const bx = x + random(-17, 17);
    const h = hMax * random(0.4, 1);
    const lean = random(0.12, 0.5) * (random() < 0.72 ? 1 : -1);
    stroke(110 + random(55), 104 + random(48), 78 + random(40), 205);
    strokeWeight(random(0.8, 1.6));
    beginShape();
    vertex(bx, y);
    quadraticVertex(bx + lean * h * 0.45, y - h * 0.55, bx + lean * h * 1.7, y - h);
    endShape();
  }
}

/* ---------------- ce qui germe ---------------- */

function pickSeedlingSpots() {
  const xs = [420, 590, 730, 1010, 1150, 1265, 860, 1345];
  for (const x of xs) {
    seedlingSpots.push({ x: x + random(-16, 16), y: GROUND - random(0, 5) });
  }
}

function seedlings() {
  for (const t of seedlingSpots) seedling(t.x, t.y);
}

function seedling(x, y) {
  const h = 24 + random(32);
  const bend = random(-0.65, 0.65);
  const x2 = x + bend * h * 0.85;
  const y2 = y - h;
  noFill();
  stroke(122, 156, 94, 235);
  strokeWeight(2);
  beginShape();
  vertex(x, y);
  quadraticVertex(x + bend * h * 0.4, y - h * 0.55, x2, y2);
  endShape();
  seedLeaf(x + bend * h * 0.22, y - h * 0.5, -1.75 + bend * 0.4, 11 + random(3));
  seedLeaf(x2 - bend * 4, y2 + h * 0.2, -2.55 - bend * 0.35, 13 + random(4));
  noStroke();
  fill(216, 190, 96, 30);
  ellipse(x, y + 2, 30, 10);
}

function seedLeaf(x, y, a, len) {
  push();
  translate(x, y);
  rotate(a);
  noStroke();
  fill(126, 168, 94, 240);
  beginShape();
  vertex(0, 0);
  quadraticVertex(len * 0.5, -len * 0.3, len, 0);
  quadraticVertex(len * 0.5,  len * 0.3, 0, 0);
  endShape(CLOSE);
  stroke(82, 114, 62, 165); strokeWeight(0.8);
  line(1.5, 0, len - 2, 0);
  pop();
}

function mushrooms() {                        // anneau fongique autour du pied
  const spots = [];
  const n = 9;
  for (let i = 0; i < n; i++) {
    const a = (i / n) * TWO_PI + random(0.35);
    const r = 92 + random(38);
    spots.push([ROOTX + 10 + cos(a) * r * 1.3, GROUND + 8 + sin(a) * r * 0.3]);
  }
  spots.sort((p, q) => p[1] - q[1]);
  for (const s of spots) mushroom(s[0], s[1], random(6.5, 12));
}

function mushroom(x, y, capW) {
  const capH = capW * 0.55;
  const stH = random(6, 13);
  stroke(210, 194, 158, 235);
  strokeWeight(2.6);
  line(x, y, x, y - stH);
  noStroke();
  fill(200, 158, 86, 245);
  arc(x, y - stH, capW * 2, capH * 2, PI, TWO_PI, CHORD);
  fill(236, 208, 140, 160);
  arc(x, y - stH + 1, capW * 1.95, capH * 0.8, PI, TWO_PI, CHORD);
  fill(242, 228, 192, 210);
  circle(x - capW * 0.4, y - stH - capH * 0.5, 1.7);
  circle(x + capW * 0.3, y - stH - capH * 0.75, 1.3);
}

/* ---------------- ce qui s'élève ---------------- */

function spores() {
  noStroke();
  for (let i = 0; i < 16; i++) {              // s'échappent du bois mort
    const tip = canopyTips.length
      ? canopyTips[floor(random(canopyTips.length))]
      : { x: ROOTX, y: 420 };
    sporeTrail(tip.x, tip.y, 12 + floor(random(12)), 200 + i * 7.3);
  }
  for (let i = 0; i < 7; i++) {               // fuient du sol, près de la ligne
    sporeTrail(ROOTX + random(-320, 330), GROUND + 14, 8 + floor(random(8)), 300 + i * 5.1);
  }
}

function sporeTrail(x, y, n, seed) {
  let px = x, py = y;
  let pa = -HALF_PI + random(-0.6, 0.6);
  for (let s = 0; s < n; s++) {
    pa += (noise(px * 0.01, py * 0.01, seed) - 0.5) * 0.9;
    pa = lerp(pa, -HALF_PI, 0.3);
    px += cos(pa) * 10;
    py += sin(pa) * 10;
    const t = s / n;
    const r = lerp(2.1, 0.5, t);
    fill(255, 222, 146, 12 * (1 - t) + 3);
    circle(px, py, r * 9);
    fill(255, 224, 150, 150 * (1 - t) + 12);
    circle(px, py, r * 2);
  }
}

/* ---------------- finitions ---------------- */

function vignette() {
  const ctx = drawingContext;
  const g = ctx.createRadialGradient(W * 0.5, H * 0.44, H * 0.3,
                                     W * 0.5, H * 0.44, H * 0.8);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.72, 'rgba(0,0,0,0.08)');
  g.addColorStop(1, 'rgba(0,0,0,0.42)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, W, H);
}

function grain() {                            // grain de toile
  noStroke();
  for (let i = 0; i < 16000; i++) {
    const v = random() < 0.5 ? 0 : 255;
    fill(v, random(4, 10));
    rect(random(W), random(H), 1, 1);
  }
}

// ============================================================
// EXTINCTION
// Une chandelle au bout de sa cire : la flamme tient encore,
// la fumée a déjà commencé de monter.
// Toile fixe 1600 x 2000 — p5.js 1.11
// ============================================================

const W = 1600, H = 2000;

const FX = 690;                 // flamme, x
const FY = 1315;                // flamme, centre lumineux
const FLAME_BX = 690;           // pied de la flamme (bout de la mèche)
const FLAME_BY = 1356;
const FLAME_H = 84;

const CANDLE_CX = 700;
const CANDLE_TOP = 1400;
const CANDLE_BOTTOM = 1548;
const CANDLE_HW = 58;           // demi-largeur de la chandelle

const TABLE_Y = 1548;           // ligne de la table

const SMOKE_TOP = 130;          // où la fumée se dissout
const SMOKE_START_Y = 1272;     // pointe de la flamme

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(W, H);
  pixelDensity(1);
  noLoop();

  paintGround();
  paintWallTexture();
  paintGlow();
  paintCandlePool();
  paintCandle();
  paintMeltedTop();
  paintWick();
  paintFlame();
  paintSmoke();
  paintEmbers();
  paintGrain();
  paintVignette();
}

function draw() {}

// ---------- utilitaires ----------

function gauss() {
  return (random() + random() + random() + random() - 2) * 1.73;
}

function smokeY(s) {
  return SMOKE_START_Y - s * (SMOKE_START_Y - SMOKE_TOP);
}

function smokeX(s) {
  const ramp = s / (s + 0.06);   // ancre le filet sur la pointe de la flamme
  return 702
       + ramp * (130 * (noise(s * 2.1 + 90) - 0.5) + 46 * s)
       + 60 * sin(s * 6.3 + 1.7) * pow(s, 0.55);
}

function smokeW(s) { return 9 + 150 * pow(s, 1.7); }
function smokeA(s) { return lerp(58, 7, pow(s, 0.65)); }

// ---------- fond : mur glacé, table qui s'enfonce ----------

function paintGround() {
  noStroke();
  for (let y = 0; y < TABLE_Y; y += 2) {
    const t = pow(y / TABLE_Y, 0.85);
    fill(lerp(8, 15, t), lerp(10, 13, t), lerp(19, 13, t));
    rect(0, y, W, 2);
  }
  for (let y = TABLE_Y; y < H; y += 2) {
    const t = pow((y - TABLE_Y) / (H - TABLE_Y), 0.75);
    fill(lerp(13, 4, t), lerp(11, 4, t), lerp(10, 6, t));
    rect(0, y, W, 2);
  }
}

// ---------- matière : glacis sur le mur, stries sur la table ----------

function paintWallTexture() {
  for (let i = 0; i < 24000; i++) {
    const x = random(W);
    const y = random(H);
    const onWall = y < TABLE_Y;
    const n = noise(x * 0.0016, y * 0.0016);
    const tt = onWall
      ? pow(y / TABLE_Y, 0.85)
      : pow((y - TABLE_Y) / (H - TABLE_Y), 0.75);
    let r, g, b;
    if (onWall) { r = lerp(8, 15, tt); g = lerp(10, 13, tt); b = lerp(19, 13, tt); }
    else        { r = lerp(13, 4, tt); g = lerp(11, 4, tt); b = lerp(10, 6, tt); }
    const d = (n - 0.5) * 12 + random(-5, 5);
    r += d; g += d; b += d * (onWall ? 1.3 : 1);
    const ang = onWall
      ? HALF_PI + (noise(x * 0.002, y * 0.002) - 0.5) * 1.4
      : (noise(x * 0.002, y * 0.002) - 0.5) * 0.35;
    const len = 6 + 12 * random();
    stroke(r, g, b, random(4, 10));
    strokeWeight(1 + random());
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
}

// ---------- la lueur : halo sur le mur, clarté ramassée sur la table ----------

function paintGlow() {
  blendMode(ADD);
  noStroke();
  const ctx = drawingContext;

  // lueur du mur, arrêtée net au plan de la table
  ctx.save();
  ctx.beginPath();
  ctx.rect(0, 0, W, TABLE_Y);
  ctx.clip();

  for (let r = 640; r > 26; r -= 9) {
    const t = 1 - (r - 26) / 614;
    fill(210 + 45 * t, 95 + 60 * t, 30 + 25 * t, 5 * pow(t, 2.4));
    ellipse(FX, FY, 2 * r, 2 * r);
  }
  // vibration : coups de pinceau qui fuient du centre
  for (let i = 0; i < 2600; i++) {
    const ang = random(TWO_PI);
    const d = 40 + pow(random(), 0.65) * 600;
    const x = FX + cos(ang) * d;
    const y = FY + sin(ang) * d;
    if (y > TABLE_Y) continue;
    const t = 1 - d / 640;
    const len = 8 + 55 * t;
    stroke(140 + 115 * t, 55 + 95 * t, 18 + 40 * t, 4 + 7 * t);
    strokeWeight(1 + 2.2 * t);
    line(x, y, x + cos(ang) * len, y + sin(ang) * len);
  }
  // poussières en suspension dans la lumière
  for (let i = 0; i < 160; i++) {
    const ang = random(TWO_PI);
    const d = 30 + pow(random(), 1.6) * 380;
    const x = FX + cos(ang) * d;
    const y = FY + sin(ang) * d * 0.9;
    if (y > TABLE_Y) continue;
    const t = 1 - d / 420;
    fill(255, 210, 150, 4 + 8 * t * random());
    ellipse(x, y, 1 + random() * 1.6, 1 + random() * 1.6);
  }
  ctx.restore();

  // lueur de la table
  noStroke();
  for (let i = 0; i < 34; i++) {
    const t = i / 34;
    fill(215, 105, 45, 1.9 * (1 - t));
    ellipse(FX, TABLE_Y + 34 + 26 * t, 2 * (62 + 470 * (1 - t)), 58 + 46 * t);
  }
  for (let i = 0; i < 700; i++) {
    const ang = random(TWO_PI);
    const d = pow(random(), 0.75) * 420;
    const x = FX + cos(ang) * d;
    const y = TABLE_Y + 18 + random(85) + sin(ang) * d * 0.1;
    const t = 1 - d / 420;
    const len = 12 + 60 * t;
    stroke(200, 95, 42, 3 + 6 * t);
    strokeWeight(1 + 1.6 * t);
    line(x - len * 0.5, y, x + len * 0.5, y + gauss() * 2);
  }
  blendMode(BLEND);
}

// ---------- au pied : ombre portée et cire figée ----------

function paintCandlePool() {
