    const x = CANDLE_CX + cos(a) * rr * 150;
    const y = TABLE_Y + 2 + sin(a) * rr * 34 + gauss() * 2;
    let lum = pow(1 - rr, 0.9) + (noise(x * 0.02, y * 0.05) - 0.5) * 0.3;
    lum = constrain(lum, 0, 1);
    const j = random(-12, 12);
    fill(lerp(92, 214, lum) + j, lerp(80, 192, lum) + j, lerp(68, 150, lum) + j,
         random(35, 90));
    const s = 3 + random(6);
    ellipse(x, y, s, s * 0.6);
  }
}

// ---------- la chandelle : la lumière tombe d'en haut ----------

function paintCandle() {
  noStroke();
  const bodyH = CANDLE_BOTTOM - CANDLE_TOP;

  const halfWAt = (y) => {
    const s = (y - CANDLE_TOP) / bodyH;
    let w = CANDLE_HW - 5 + 6 * noise(y * 0.02 + 7);
    if (s > 0.78) w += pow((s - 0.78) / 0.22, 2) * 36;   // pied évasé
    return w;
  };

  // corps : stries verticales de coulures
  for (let i = 0; i < 11000; i++) {
    const y = CANDLE_TOP + random(bodyH);
    const w = halfWAt(y);
    const x = CANDLE_CX + gauss() * 0.45 * w;
    if (abs(x - CANDLE_CX) > w) continue;
    const s = (y - CANDLE_TOP) / bodyH;
    const edge = abs(x - CANDLE_CX) / w;
    let lum = pow(1 - s, 1.05) * (1 - 0.28 * pow(edge, 2.2))
            + (noise(x * 0.012, y * 0.012) - 0.5) * 0.25;
    lum = constrain(lum, 0, 1);
    const j = random(-10, 10);
    fill(lerp(82, 255, lum) + j, lerp(72, 222, lum) + j, lerp(62, 164, lum) + j,
         random(45, 100));
    rect(x, y, 1.6 + random(1.2), 5 + random(9));
  }

  // coulures figées le long des flancs
  const drips = [
    { x0: CANDLE_CX - 40, len: 66,  w: 10, seed: 11 },
    { x0: CANDLE_CX + 44, len: 42,  w: 7,  seed: 23 },
    { x0: CANDLE_CX + 26, len: 132, w: 13, seed: 47 },
    { x0: CANDLE_CX - 24, len: 30,  w: 6,  seed: 63 },
  ];
  for (const d of drips) {
    for (let i = 0; i < 800; i++) {
      const s = pow(random(), 0.7);
      const y = CANDLE_TOP + 4 + s * d.len;
      const sway = (noise(d.seed + s * 1.6) - 0.5) * 12;
      const ww = d.w * (1 - 0.3 * s);
      const x = d.x0 + sway + gauss() * ww * 0.5;
      let lum = 0.5 + 0.5 * (1 - s) + (noise(x * 0.03, y * 0.02) - 0.5) * 0.3;
      lum = constrain(lum, 0, 1);
      const j = random(-9, 9);
      fill(lerp(140, 252, lum) + j, lerp(126, 236, lum) + j, lerp(106, 196, lum) + j,
           random(55, 105));
      rect(x, y, 2 + random(2), 5 + random(9));
    }
  }

  // goutte suspendue au bord du sommet
  const gx = CANDLE_CX - 55, gy = CANDLE_TOP + 8;
  for (let i = 0; i < 320; i++) {
    const u = random();
    const yy = gy + u * 26;
    const wAt = 3 + 7 * pow(u, 0.7);
    const xx = gx + gauss() * wAt * 0.45;
    let lum = 0.85 - abs(xx - gx) / 9 - u * 0.25 + random(-0.06, 0.06);
    lum = constrain(lum, 0, 1);
    fill(lerp(120, 255, lum), lerp(106, 244, lum), lerp(88, 210, lum),
         random(50, 100));
    ellipse(xx, yy, 2.6, 4);
  }
}

