// ---------- la flamme : point chaud de toute la toile ----------

function paintFlame() {
  const bx = FLAME_BX, by = FLAME_BY, Hf = FLAME_H;

  // u = 0 a la base (mèche), u = 1 a la pointe
  const cxAt = (u) => bx - 2 + 13 * pow(u, 1.7) + (noise(u * 3.1 + 40) - 0.5) * 7;
  const halfWAt = (u) => 17 * sin(PI * pow(u, 0.62)) * (0.85 + 0.3 * (1 - u)) + 3 * (1 - u);

  blendMode(ADD);
  noStroke();

  // halo serré
  for (let r = 130; r > 6; r -= 6) {
    const t = 1 - (r - 6) / 124;
    fill(255, 150 + 80 * t, 60 + 70 * t, 2 + 7 * t);
    ellipse(bx, by - Hf * 0.45, r * (0.9 + 0.55 * t), r * 1.45);
  }

  // corps : cœur blanc, chair ambrée, peau orange
  for (let i = 0; i < 2600; i++) {
    const u = random();
    const y = by - Hf * u;
    const w = halfWAt(u);
    const d = abs(gauss()) * 0.45;
    if (d > 1) continue;
    const x = cxAt(u) + gauss() * w * 0.42;
    const heat = sin(PI * constrain((u - 0.06) / 0.88, 0, 1));
    const coreT = 0.4 * heat;
    let r, g, b, a;
    if (d < coreT)     { r = 255; g = 246; b = 208; a = 52; }
    else if (d < 0.68) { r = 255; g = 176; b = 58;  a = 34; }
    else               { r = 236; g = 96;  b = 24;  a = 24; }
    a *= 0.5 + 0.5 * heat;
    fill(r, g, b, a);
    const s = 3.4 + random(3.2);
    ellipse(x, y, s, s * 1.3);
  }

  // liseré bleu à la racine
  for (let i = 0; i < 240; i++) {
    const u = random(0.15);
    const y = by - Hf * u;
    const w = halfWAt(u) + 5;
    const x = cxAt(u) + gauss() * w * 0.6;
    fill(80, 115, 215, random(16, 40));
    ellipse(x, y, 2.6 + random(2.2), 3 + random(2.5));
  }

  // échos de vacillement
  for (let k = 0; k < 2; k++) {
    const off = (k === 0 ? -7 : 6);
    for (let i = 0; i < 300; i++) {
      const u = random(0.9);
      const y = by - Hf * u;
      const w = halfWAt(u);
      const x = cxAt(u) + off * (0.4 + u) + gauss() * w * 0.4;
      fill(255, 120, 30, 7);
      ellipse(x, y, 3 + random(3), 5 + random(5));
    }
  }
  blendMode(BLEND);
}

// ---------- la fumée : ce qui monte, ce qui refroidit ----------

function paintSmoke() {
  noStroke();

  // filet dense qui sort de la pointe
  for (let i = 0; i < 1800; i++) {
    const s = random(0.2);
    const y = smokeY(s);
    const x = smokeX(s) + gauss() * (2 + smokeW(s) * 0.4);
    const k = s;
    const j = random(-10, 10);
    fill(lerp(160, 112, k) + j, lerp(146, 122, k) + j, lerp(134, 140, k) + j,
         smokeA(s) * random(0.35, 0.9));
    ellipse(x, y, 2.4 + random(2.4), 4 + random(6));
  }

  // corps montant : gris chaud qui devient gris bleu
  for (let i = 0; i < 7200; i++) {
    const s = random();
    const y = smokeY(s);
    const w = smokeW(s);
    const x = smokeX(s) + gauss() * w * 0.55;
    const j = random(-9, 9);
    fill(lerp(160, 108, s) + j, lerp(146, 118, s) + j, lerp(134, 136, s) + j,
         smokeA(s) * random(0.3, 0.85));
    ellipse(x, y, 4 + 9 * s + random(5), 6 + 13 * s + random(7));
  }

  // volutes
  for (let k = 0; k < 6; k++) {
    const s0 = 0.16 + random() * 0.74;
    const y0 = smokeY(s0);
    const x0 = smokeX(s0);
    const rw = smokeW(s0) * (1.25 + random() * 0.8);
    for (let i = 0; i < 300; i++) {
      const a = random(TWO_PI);
      const rr = pow(random(), 0.7);
      const x = x0 + cos(a) * rr * rw;
      const y = y0 + sin(a) * rr * rw * 0.75 - random(26);
      const s = constrain(s0 + (y0 - y) / (SMOKE_START_Y - SMOKE_TOP), 0, 1);
      const j = random(-8, 8);
      fill(lerp(160, 105, s) + j, lerp(146, 116, s) + j, lerp(134, 134, s) + j,
           smokeA(s) * random(0.3, 0.8));
      ellipse(x, y, 5 + 10 * s + random(6), 4 + 9 * s + random(6));
    }
  }
}

// ---------- dernières étincelles emportées ----------

function paintEmbers() {
