  }
}

// EXHALAISON — peinture sur la mort
// Toile fixe 1600 × 2000 — p5.js 1.11

const CORPS = [
  [655, 1698, 176, 124], // le dos bombé
  [476, 1750,  60,  56], // la tête inclinée, posée
  [592, 1734,  70,  74], // l'épaule
  [738, 1712, 102, 108], // le torse
  [792, 1744,  88,  66], // les cuisses
  [874, 1690,  50, 102], // les genoux repliés
];

function champ(x, y) {
  let m = 1e9;
  for (const e of CORPS) {
    const dx = (x - e[0]) / e[2];
    const dy = (y - e[1]) / e[3];
    const v = dx * dx + dy * dy;
    if (v < m) m = v;
  }
  return sqrt(m);
}

