  background(9, 11, 15);
  noStroke();
  for (let y = 0; y < height; y += 5) {
    for (let x = 0; x < width; x += 5) {
      const n = noise(x * 0.0022, y * 0.003);
      const prof = y / height;
      const a = 3 + n * n * 30 * (0.25 + 0.75 * prof);
      fill(12 + 30 * prof, 15 + 13 * prof, 19 + 6 * prof, a);
      rect(x, y, 5.5, 5.5);
    }
  }
}

