// — le corps : cendre et braises, replié comme au premier jour —
function dessinerCorps() {
  noStroke();
  let n = 0, essais = 0;
  while (n < 26000 && essais < 500000) {
    essais++;
    const x = random(352, 992);
    const y = random(1460, 1814);
    const v = champ(x, y);
    if (v > 1.24) continue;
    let p = v < 0.62 ? 1 : map(v, 0.62, 1.24, 1, 0);
    p *= 0.55 + 0.45 * noise(x * 0.02, y * 0.02);
    if (random() > p) continue;
    n++;
    const coeur = map(v, 0, 1.24, 1, 0);
    const chaleur = coeur * (0.55 + 0.45 * noise(x * 0.013 + 37, y * 0.013 + 11));
    const k = map(y, 1730, 1814, 1, 0.4);
    fill(lerp(58, 208, chaleur) * k,
         lerp(52, 146, chaleur) * k,
         lerp(50, 96, chaleur) * k, 240);
    circle(x, y, random(1.7, 3.3) * (0.85 + 0.5 * coeur));
  }
  // braises : ce qui fut chaud l'est encore
  let b = 0, ess = 0;
  while (b < 130 && ess < 20000) {
    ess++;
    const x = 668 + randomGaussian() * 110;
    const y = 1692 + randomGaussian() * 80;
    if (champ(x, y) > 0.85) continue;
    b++;
    const chaud = random();
    fill(255, 176 + chaud * 40, 96 + chaud * 50, 200 + random(55));
    circle(x, y, random(1.4, 2.8));
    if (random() < 0.3) {
      fill(255, 150, 70, 22);
      circle(x, y, random(6, 12));
    }
  }
}

// — l'exhalaison : le corps se défait, monte, se refroidit, s'efface —
function dessinerCourant() {
  noStroke();
  const cBraise = color(238, 166, 92);
  const cFumee  = color(196, 180, 160);
  const cFroid  = color(168, 178, 194);
  const cPale   = color(210, 220, 234);
  for (let i = 0; i < 14000; i++) {
    const t = pow(random(), 1.3);
    const y = map(t, 0, 1, 1588, 120);
    const axe = lerp(662, 845, t) + (noise(t * 5.3, 7.7) - 0.5) * (130 + 280 * t);
    const etale = 55 + 340 * pow(t, 1.25);
    const g = random() + random() + random() - 1.5;
    let x = axe + g * etale;
    x += (noise(x * 0.0035, y * 0.0035) - 0.5) * 190 * t;

    let c;
    if (t < 0.32)      c = lerpColor(cBraise, cFumee, t / 0.32);
    else if (t < 0.68) c = lerpColor(cFumee, cFroid, (t - 0.32) / 0.36);
    else               c = lerpColor(cFroid, cPale, (t - 0.68) / 0.32);

    const s = map(t, 0, 1, 2.7, 1.0) * random(0.65, 1.35);
    const a = 250 * pow(1 - t, 1.6) * random(0.6, 1);
    fill(red(c) + random(-12, 12), green(c) + random(-12, 12), blue(c) + random(-12, 12), a);
    circle(x, y, s);
    if (t < 0.25 && random() < 0.5) { // halo gazeux près du corps
      fill(red(c), green(c), blue(c), 14);
      circle(x, y, s * 3.2);
    }
  }
  // dernières braises emportées
  for (let i = 0; i < 70; i++) {
    const t = pow(random(), 2) * 0.3;
    const y = map(t, 0, 0.3, 1580, 1180);
    const x = lerp(662, 780, t) + randomGaussian() * (60 + 120 * t);
    fill(255, 140, 60, 20);
    circle(x, y, random(6, 13));
    fill(255, 168, 84, 190 + random(60));
    circle(x, y, random(1.4, 3.2));
  }
}

// — poussières d'or, seules, dans les noirs latéraux —
