function skyColor(t) {
  let stops = [
    [0.00, color(6, 7, 14)],
    [0.35, color(18, 16, 36)],
    [0.62, color(40, 30, 58)],
    [0.82, color(74, 50, 78)],
    [1.00, color(112, 66, 70)]
  ];
  for (let i = 0; i < stops.length - 1; i++) {
    let a = stops[i], b = stops[i + 1];
    if (t >= a[0] && t <= b[0]) {
      return lerpColor(a[1], b[1], (t - a[0]) / (b[0] - a[0]));
    }
  }
  return stops[stops.length - 1][1];
}

