  bezierVertex(-s * 0.75, s * 0.35, -s * 0.75, -s * 0.35, 0, -s);
  endShape(CLOSE);
  pop();
}

function branch(x, y, angle, len, w, depth) {
  if (depth <= 0 || w < 0.7 || len < 6) return;
  let x2 = x + cos(angle) * len;
  let y2 = y + sin(angle) * len;
  strokeCap(ROUND);
  stroke(5, 4, 9, 255);
  strokeWeight(w);
  line(x, y, x2, y2);
  // filet de lumière lunaire sur le côté droit
  stroke(170, 158, 192, 55);
  strokeWeight(max(0.5, w * 0.3));
  line(x + w * 0.22, y - w * 0.16, x2 + w * 0.22, y2 - w * 0.16);
  if (depth === 1 && random() < 0.22) {
    leafAt(x2, y2, random(7, 13), color(150, 70, 40), 225);
  }
  let n = depth > 8 ? 3 : 2;
  for (let i = 0; i < n; i++) {
    let spread = (i - (n - 1) / 2) * (0.5 + random(0.25));
    branch(x2, y2, angle + spread + random(-0.26, 0.26),
      len * random(0.66, 0.8), w * random(0.6, 0.74), depth - 1);
  }
}

