const PAL = {
  bg0: [30, 24, 22],
  bg1: [7, 7, 11],
  moon: [216, 222, 228],
  moonDark: [150, 160, 175],
  robe: [17, 13, 12],
  hood: [26, 20, 17],
  wax: [228, 216, 190],
  sand: [208, 188, 148],
  wood: [74, 52, 36],
