};

function br(x, y, ang, len, w, c, a) {
  push();
  translate(x, y);
  rotate(ang);
  noStroke();
  fill(c[0], c[1], c[2], a);
  ellipse(0, 0, len, w);
  ellipse(len * 0.32, 0, len * 0.55, w * 0.62);
  pop();
}

function draw() {
  noStroke();
  for (let y = 0; y < height; y += 3) {
    let t = y / height;
    let n = noise(y * 0.002, 3.7);
    let base = lerpColor(color(PAL.bg0[0], PAL.bg0[1], PAL.bg0[2]), color(PAL.bg1[0], PAL.bg1[1], PAL.bg1[2]), t);
    fill(red(base) + (n - 0.5) * 18, green(base) + (n - 0.5) * 16, blue(base) + (n - 0.5) * 22);
    rect(0, y, width, 3);
  }

  for (let i = 0; i < 2400; i++) {
    let x = random(width), y = random(height);
    let n = noise(x * 0.0015, y * 0.0015);
    let c = n > 0.63 ? [52, 42, 38] : (n < 0.37 ? [22, 26, 40] : [36, 30, 30]);
    br(x, y, random(TWO_PI), random(40, 170), random(8, 30), c, random(8, 22));
