  g.addColorStop(1, 'rgba(178,188,204,0)');
  drawingContext.fillStyle = g;
  drawingContext.fillRect(0, 0, width, height);

  push();
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.arc(800, 540, 250, 0, TWO_PI);
  drawingContext.clip();
  noStroke();
  fill(PAL.moon[0], PAL.moon[1], PAL.moon[2]);
  ellipse(800, 540, 500, 500);
  for (let i = 0; i < 260; i++) {
    let a = random(TWO_PI), rr = random(0, 245);
    let x = 800 + Math.cos(a) * rr, y = 540 + Math.sin(a) * rr;
    let c = noise(x * 0.01, y * 0.01) > 0.5 ? PAL.moonDark : [232, 236, 240];
    br(x, y, random(TWO_PI), random(20, 90), random(8, 26), c, random(14, 40));
  }
  for (let i = 0; i < 9; i++) {
    let a = random(TWO_PI), rr = random(20, 200);
    fill(140, 150, 168, random(25, 60));
    ellipse(800 + Math.cos(a) * rr, 540 + Math.sin(a) * rr, random(30, 90), random(24, 70));
  }
