function drawBranch(x, y, angle, len, w, depth, rim) {
  if (depth <= 0 || w < 0.5 || len < 8) return;
  const x2 = x + cos(angle) * len;
  const y2 = y + sin(angle) * len;
  const ox = rim ? 4 : 0;
  const oy = rim ? -3 : 0;
  strokeCap(ROUND);
  if (rim) {
    stroke(150, 155, 185, 38);
    strokeWeight(Math.max(0.8, w * 0.3));
  } else {
    stroke(6, 7, 12, 245);
    strokeWeight(w);
  }
  line(x + ox, y + oy, x2 + ox, y2 + oy);
  const n = (depth > 6 && random() < 0.45) ? 3 : 2;
  for (let i = 0; i < n; i++) {
    const spread = random(0.3, 0.8);
    const na = angle + (i - (n - 1) / 2) * spread * 1.6 + random(-0.25, 0.25);
    drawBranch(x2, y2, na, len * random(0.66, 0.8), w * random(0.58, 0.68), depth - 1, rim);
  }
  if (depth <= 2) {
    stroke(rim ? color(150, 155, 185, 38) : color(6, 7, 12, 245));
    strokeWeight(rim ? 1 : Math.max(0.6, w));
    for (let i = 0; i < 3; i++) {
      const ta = angle + random(-1.2, 1.2);
      line(x2 + ox, y2 + oy, x2 + ox + cos(ta) * random(12, 30), y2 + oy + sin(ta) * random(12, 30));
    }
  }
}

function setup() {
  randomSeed(1);
  noiseSeed(1);
  createCanvas(1600, 2000);
  pixelDensity(1);
  noLoop();

  const H = 1180;               // ligne d'horizon
  const mx = 1150, my = 430, mr = 165;  // lune

  // ---- ciel en dégradé ----
  for (let y = 0; y <= H; y += 2) {
    stroke(lerpColor(color(7, 9, 20), color(40, 38, 60), y / H));
    line(0, y, 1600, y);
  }

  // ---- étoiles ----
  noStroke();
  for (let i = 0; i < 260; i++) {
    const x = random(1600);
    const y = random(-20, H - 160);
    const s = random(0.6, 2.6);
    const a = random(40, 200);
    fill(225, 228, 245, a);
    circle(x, y, s);
    if (s > 2 && random() < 0.35) {
      stroke(225, 228, 245, a * 0.5);
      strokeWeight(0.7);
      line(x - s * 3, y, x + s * 3, y);
      line(x, y - s * 3, x, y + s * 3);
      noStroke();
    }
  }

  // ---- halo lunaire ----
  for (let i = 46; i >= 0; i--) {
    fill(232, 224, 200, map(i, 0, 46, 26, 0.01));
    circle(mx, my, (mr + i * 13) * 2);
  }

  // ---- disque de lune ----
  drawingContext.save();
  drawingContext.beginPath();
  drawingContext.arc(mx, my, mr, 0, TWO_PI);
  drawingContext.clip();
  const mg = drawingContext.createRadialGradient(mx - mr * 0.45, my - mr * 0.5, mr * 0.1, mx, my, mr * 1.05);
  mg.addColorStop(0, 'rgba(248,240,220,1)');
  mg.addColorStop(0.65, 'rgba(230,220,196,1)');
  mg.addColorStop(1, 'rgba(168,166,182,1)');
  drawingContext.fillStyle = mg;
  drawingContext.fillRect(mx - mr, my - mr, mr * 2, mr * 2);
  for (let i = 0; i < 16; i++) {
    const bx = mx + random(-mr * 0.85, mr * 0.85);
    const by = my + random(-mr * 0.85, mr * 0.85);
    if (dist(bx, by, mx, my) < mr * 0.88) {
      drawingContext.fillStyle = 'rgba(148,148,168,' + random(0.08, 0.22) + ')';
      drawingContext.beginPath();
      drawingContext.ellipse(bx, by, random(mr * 0.15, mr * 0.5), random(mr * 0.12, mr * 0.4), random(TWO_PI), 0, TWO_PI);
      drawingContext.fill();
    }
  }
  drawingContext.restore();

  // ---- nuages voilant la lune ----
  for (let i = 0; i < 26; i++) {
    const cy = random(120, 780);
    const cx = random(-200, 1800);
    const cw = random(300, 900);
    const ch = random(18, 60);
    fill(16, 18, 34, random(8, 22));
    ellipse(cx, cy, cw, ch);
    fill(210, 214, 235, random(4, 10));
    ellipse(cx + random(-40, 40), cy - ch * 0.4, cw * 0.8, ch * 0.5);
  }

  // ---- eau ----
  for (let y = H; y <= 2000; y += 2) {
    stroke(lerpColor(color(30, 34, 56), color(5, 7, 14), (y - H) / (2000 - H)));
    line(0, y, 1600, y);
  }
  noStroke();
  for (let i = 0; i < 500; i++) {
    fill(140, 150, 190, random(4, 14));
    rect(random(1600), random(H + 10, 1995), random(20, 160), random(1, 2.5));
  }

  // ---- lueur froide derrière l'horizon ----
  fill(90, 100, 140, 10);
  ellipse(700, H, 1000, 160);

  // ---- rive lointaine ----
  fill(11, 13, 26);
  beginShape();
  vertex(0, H + 40);
  for (let x = 0; x <= 1600; x += 32) {
    vertex(x, H - random(0, 8) - noise(x * 0.004, 99) * 90);
  }
  vertex(1600, H + 40);
  endShape(CLOSE);

  // ---- reflet de la lune sur l'eau ----
  noStroke();
  let ry = H + 8;
  while (ry < 1990) {
    const t = (ry - H) / (2000 - H);
    const wob = noise(ry * 0.02, 7) * 80 - 40;
    fill(233, 224, 198, constrain(map(t, 0, 1, 26, 3) + random(-4, 6), 2, 30));
    ellipse(mx + wob, ry, random(24, 150) * (0.5 + t * 1.6), random(2, 4.5));
    ry += random(5, 13);
  }

  // ---- brume ----
  for (let i = 0; i < 9; i++) {
    fill(170, 182, 214, random(6, 14));
    ellipse(random(800), random(H - 60, H + 500), random(1200, 2200), random(40, 110));
  }

  // ---- reflet de l'arbre ----
  for (let i = 0; i < 24; i++) {
    fill(4, 5, 10, random(8, 20));
    ellipse(random(180, 520), random(H + 20, 1900), random(30, 120), random(3, 8));
  }

  // ---- arbre mort (ombre + liseré lunaire) ----
  drawBranch(330, 1985, -HALF_PI - 0.12, 380, 42, 9, false);
  drawBranch(334, 1982, -HALF_PI - 0.12, 380, 42, 9, true);

  // ---- racines dans l'eau ----
  noFill();
  stroke(6, 7, 12, 240);
  for (let i = 0; i < 7; i++) {
    const dx = random(-220, 220);
    strokeWeight(random(3, 9));
    bezier(330, 1950, 330 + dx * 0.3, 1980, 330 + dx * 0.7, 1995, 330 + dx, 2015);
  }

  // ---- barque vide et sa lanterne ----
  const bx = 1060, by = 1420;
  const ly = by - 78;
  for (let i = 0; i < 18; i++) {
    fill(255, 180, 90, random(6, 22) * (1 - i / 22));
    ellipse(bx - 40 + random(-8, 8), by + 22 + i * random(6, 12), random(6, 30) * (1 + i * 0.15), random(1.5, 3));
  }
  fill(9, 10, 15);
  beginShape();
  vertex(bx - 95, by - 6);
  quadraticVertex(bx, by + 42, bx + 95, by - 6);
  quadraticVertex(bx, by + 16, bx - 95, by - 6);
  endShape(CLOSE);
  noFill();
  stroke(200, 205, 225, 40);
  strokeWeight(2);
  beginShape();
  vertex(bx - 95, by - 6);
  quadraticVertex(bx, by + 16, bx + 95, by - 6);
  endShape();
  stroke(8, 8, 12, 255);
  strokeWeight(4);
  line(bx - 40, by - 8, bx - 40, ly - 12);
  noStroke();
  for (let i = 22; i >= 1; i--) {
    fill(255, 182, 92, map(i, 1, 22, 90, 3));
    circle(bx - 40, ly, i * 8);
  }
  fill(255, 205, 120);
  rect(bx - 47, ly - 10, 14, 20, 3);
  fill(60, 40, 20);
  rect(bx - 49, ly - 14, 18, 4, 2);
  fill(255, 190, 100, 35);
  ellipse(bx - 40, by + 2, 60, 10);

  // ---- pétales ----
  const pc = [[242, 226, 226], [238, 218, 224], [246, 236, 224], [226, 200, 208], [244, 240, 230]];
  function petal(x, y, water) {
    const c = random(pc);
    push();
    translate(x, y);
    rotate(random(TWO_PI));
    if (water) {
      noStroke();
      fill(0, 0, 5, 30);
      ellipse(2, 3, 15, 5);
    }
    noStroke();
    fill(c[0], c[1], c[2], water ? random(120, 200) : random(90, 180));
    ellipse(0, 0, random(7, 15), random(4, 8));
    pop();
  }
  for (let i = 0; i < 95; i++) petal(random(60, 1540), random(H + 15, 1985), true);
  for (let i = 0; i < 55; i++) petal(random(60, 1540), random(240, H - 40), false);
  for (let i = 0; i < 40; i++) {
    const ang = random(TWO_PI), rr = random(20, 260);
    petal(bx + cos(ang) * rr * 1.7, by + 12 + sin(ang) * rr * 0.35 + random(40), true);
  }

  // ---- roseaux du premier plan ----
  noFill();
  for (let i = 0; i < 90; i++) {
    const x = random(-20, 1620);
    const h = random(120, 560);
    const lean = random(-140, 140);
    stroke(5, 6, 11, random(180, 255));
    strokeWeight(random(2, 6));
    const tipX = x + lean, tipY = 2010 - h;
    bezier(x, 2010, x + lean * 0.2, 2010 - h * 0.4, x + lean * 0.7, 2010 - h * 0.8, tipX, tipY);
    if (random() < 0.55) {
      noStroke();
      fill(24, 22, 30, random(150, 230));
      ellipse(tipX, tipY, random(5, 9), random(16, 30), lean * 0.01);
