function jcol(r, g, b, a, j) {
  return color(
    constrain(r + random(-j, j), 0, 255),
    constrain(g + random(-j, j), 0, 255),
    constrain(b + random(-j, j), 0, 255),
    a
  );
}

function softShadow(x, y, rx, ry, a) {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
  g.addColorStop(0, 'rgba(0,0,0,' + a + ')');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.save();
  ctx.translate(x, y);
  ctx.scale(1, ry / rx);
  ctx.fillStyle = g;
  ctx.fillRect(-rx, -rx, rx * 2, rx * 2);
  ctx.restore();
}

function paintBackdrop() {
  let ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 0, 0, height);
  g.addColorStop(0, '#2b2115');
  g.addColorStop(0.5, '#1c1510');
  g.addColorStop(1, '#100c09');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);

  let lg = ctx.createRadialGradient(640, 820, 60, 640, 900, 720);
  lg.addColorStop(0, 'rgba(216,180,132,0.15)');
  lg.addColorStop(1, 'rgba(216,180,132,0)');
  ctx.fillStyle = lg;
  ctx.fillRect(0, 0, width, height);

  noStroke();
  for (let i = 0; i < 130; i++) {
    let x = random(-100, width);
    let w = random(30, 150);
    let amp = random(15, 60);
    let dark = random() < 0.55;
    let a = random(12, 42);
    fill(dark ? color(6, 5, 4, a) : color(76, 60, 43, a));
    let pts = [];
    for (let y = -40; y <= height + 40; y += 70) {
      let off = (noise(x * 0.004, y * 0.004) - 0.5) * amp;
      pts.push([x + off, y, x + w + off, y]);
    }
    beginShape();
    for (let k = 0; k < pts.length; k++) vertex(pts[k][0], pts[k][1]);
    for (let k = pts.length - 1; k >= 0; k--) vertex(pts[k][2], pts[k][3]);
    endShape(CLOSE);
  }
}

function paintTable() {
  let ctx = drawingContext;
  let g = ctx.createLinearGradient(0, 1450, 0, height);
  g.addColorStop(0, '#342819');
  g.addColorStop(0.1, '#2a2015');
  g.addColorStop(1, '#0d0906');
  ctx.fillStyle = g;
  ctx.fillRect(0, 1450, width, height - 1450);

  let s = ctx.createLinearGradient(0, 1450, 0, 1525);
  s.addColorStop(0, 'rgba(216,192,152,0.20)');
  s.addColorStop(1, 'rgba(216,192,152,0)');
  ctx.fillStyle = s;
  ctx.fillRect(0, 1450, width, 75);

  noFill();
  for (let i = 0; i < 90; i++) {
    let y = random(1458, height);
    let a = random(6, 22);
    stroke(random() < 0.5 ? color(0, 0, 0, a) : color(122, 96, 66, a));
    strokeWeight(random(1, 3));
    let x = random(-60, width);
    let len = random(160, 520);
    let wob = random(3, 12);
    let ph = random(1, 3);
    beginShape();
    for (let t = 0; t <= 1.001; t += 0.1) {
      vertex(x + t * len, y + sin(t * PI * ph) * wob + (noise(t * 5, y * 0.05) - 0.5) * 6);
    }
    endShape();
  }
  noStroke();
}

function drawHourglass() {
  let cx = 1230, topY = 850, botY = 1450, midY = 1150, halfW = 160, neck = 16;
  softShadow(cx, 1456, 230, 24, 0.55);

  function glassPath() {
    beginShape();
    vertex(cx - halfW, topY + 64);
    bezierVertex(cx - halfW - 10, midY - 170, cx - neck - 16, midY - 95, cx - neck, midY);
    bezierVertex(cx - neck - 16, midY + 95, cx - halfW - 10, midY + 170, cx - halfW, botY - 64);
    vertex(cx + halfW, botY - 64);
    bezierVertex(cx + halfW + 10, midY + 170, cx + neck + 16, midY + 95, cx + neck, midY);
    bezierVertex(cx + neck + 16, midY - 95, cx + halfW + 10, midY - 170, cx + halfW, topY + 64);
    endShape(CLOSE);
  }

  function sandPile() {
    beginShape();
    vertex(cx - halfW + 10, 1382);
    bezierVertex(cx - halfW + 40, midY + 140, cx - 70, 1300, cx, 1266);
    bezierVertex(cx + 70, 1300, cx + halfW - 40, midY + 140, cx + halfW - 10, 1382);
    endShape(CLOSE);
  }

  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(190, 214, 226, 9 + random(6));
    glassPath();
  }

  for (let i = 0; i < 10; i++) {
    fill(jcol(219, 172, 82, 30, 16));
    push(); translate(random(-3, 3), random(-2, 2)); sandPile(); pop();
  }
  fill(214, 166, 76);
  sandPile();

  noFill();
  stroke(246, 216, 136, 120); strokeWeight(7);
  beginShape();
  vertex(cx - halfW + 26, 1360);
  bezierVertex(cx - 90, 1320, cx - 40, 1290, cx, 1272);
  endShape();
  stroke(122, 84, 36, 130); strokeWeight(9);
  beginShape();
  vertex(cx, 1272);
  bezierVertex(cx + 45, 1295, cx + 95, 1325, cx + halfW - 24, 1362);
  endShape();
  noStroke();

  for (let i = 0; i < 260; i++) {
    let x = cx + random(-halfW + 14, halfW - 14);
    let y = random(1280, 1380);
    let wAt = (halfW - 26) * (1382 - y) / (1382 - 1266);
    if (abs(x - cx) < wAt) {
      fill(random() < 0.5 ? color(255, 226, 150, 90) : color(110, 74, 30, 90));
      ellipse(x, y, random(1.5, 3.5), random(1.5, 3));
    }
  }

  noFill();
  stroke(210, 175, 100, 40); strokeWeight(4);
  line(cx - 6, midY - 60, cx - 10, midY - 20);
  line(cx + 8, midY - 80, cx + 4, midY - 30);
  noStroke();

  for (let i = 0; i < 5; i++) {
    fill(jcol(60, 42, 26, 40, 8));
    push(); translate(random(-1.5, 1.5), random(-1.5, 1.5));
    rect(cx - 34, midY - 10, 68, 20, 8);
    pop();
  }
  fill(64, 45, 28);
  rect(cx - 34, midY - 10, 68, 20, 8);

  noFill();
  for (let i = 0; i < 4; i++) {
    stroke(205, 226, 236, 38);
    strokeWeight(3.5);
    push(); translate(random(-1.5, 1.5), random(-1.5, 1.5)); glassPath(); pop();
  }
  stroke(242, 250, 255, 95); strokeWeight(5);
  beginShape();
  vertex(cx - halfW + 8, topY + 76);
  bezierVertex(cx - halfW - 2, midY - 160, cx - neck - 9, midY - 85, cx - neck + 3, midY);
  bezierVertex(cx - neck - 9, midY + 85, cx - halfW - 2, midY + 160, cx - halfW + 8, botY - 76);
  endShape();
  noStroke();

  cap(cx, topY, halfW);
  cap(cx, botY - 64, halfW);
}

function cap(cx, y, halfW) {
  noStroke();
  for (let i = 0; i < 8; i++) {
    fill(jcol(56, 39, 24, 32, 8));
    push(); translate(random(-2, 2), random(-2, 2));
    rect(cx - halfW - 16, y, (halfW + 16) * 2, 64, 16);
    pop();
  }
  fill(62, 43, 27);
  rect(cx - halfW - 16, y, (halfW + 16) * 2, 64, 16);
  noFill();
  stroke(28, 19, 11, 110); strokeWeight(2);
  for (let i = 0; i < 5; i++) {
    let yy = y + random(12, 52);
    line(cx - halfW - 10, yy, cx + halfW + 10, yy + random(-5, 5));
  }
  noStroke();
  fill(126, 94, 56, 80);
  rect(cx - halfW - 16, y, (halfW + 16) * 2, 8, 8);
}

function skullPath(cx, cy, s) {
  beginShape();
  vertex(cx - 0.42 * s, cy - 0.10 * s);
  bezierVertex(cx - 0.56 * s, cy - 0.72 * s, cx + 0.56 * s, cy - 0.72 * s, cx + 0.42 * s, cy - 0.10 * s);
  bezierVertex(cx + 0.40 * s, cy + 0.22 * s, cx + 0.30 * s, cy + 0.40 * s, cx + 0.17 * s, cy + 0.52 * s);
  bezierVertex(cx + 0.11 * s, cy + 0.60 * s, cx + 0.06 * s, cy + 0.63 * s, cx, cy + 0.63 * s);
  bezierVertex(cx - 0.06 * s, cy + 0.63 * s, cx - 0.11 * s, cy + 0.60 * s, cx - 0.17 * s, cy + 0.52 * s);
  bezierVertex(cx - 0.30 * s, cy + 0.40 * s, cx - 0.40 * s, cy + 0.22 * s, cx - 0.42 * s, cy - 0.10 * s);
  endShape(CLOSE);
}

function socket(ex, ey, rot, s) {
  push();
  translate(ex, ey);
  rotate(rot);
  noStroke();
  for (let i = 0; i < 5; i++) {
    fill(jcol(22, 15, 11, 52, 6));
    ellipse(random(-3, 3), random(-3, 3), 0.26 * s - i * 9, 0.30 * s - i * 10);
  }
  fill(12, 9, 7);
  ellipse(0, 0, 0.235 * s, 0.275 * s);
  fill(64, 50, 38, 130);
  ellipse(-0.035 * s, -0.06 * s, 0.10 * s, 0.07 * s);
  pop();
}

function drawSkull() {
  let cx = 640, cy = 1000, s = 560;
  softShadow(cx + 12, 1368, 320, 40, 0.6);

  noStroke();
  for (let i = 0; i < 9; i++) {
    fill(jcol(196, 178, 142, 32, 14));
    push(); translate(random(-4, 4), random(-4, 4)); skullPath(cx, cy, s); pop();
  }
  for (let i = 0; i < 6; i++) {
    fill(jcol(233, 221, 191, 40, 12));
    push(); translate(random(-11, -5), random(-13, -6)); skullPath(cx, cy, s * 0.985); pop();
  }
  for (let i = 0; i < 6; i++) {
    fill(jcol(108, 88, 64, 48, 12));
    push(); translate(random(6, 14), random(6, 14)); skullPath(cx, cy, s * 0.99); pop();
  }
  fill(207, 189, 153);
  skullPath(cx, cy, s);

  for (let i = 0; i < 6; i++) {
    fill(245, 235, 206, 24);
    ellipse(cx - 0.17 * s, cy - 0.40 * s, 0.44 * s - i * 10, 0.30 * s - i * 8);
  }
  for (let i = 0; i < 5; i++) {
    fill(100, 82, 62, 20);
    ellipse(cx - 0.35 * s, cy - 0.06 * s, 0.12 * s, 0.30 * s);
    ellipse(cx + 0.35 * s, cy - 0.06 * s, 0.12 * s, 0.30 * s);
  }
  for (let i = 0; i < 5; i++) {
    fill(122, 100, 76, 20);
    ellipse(cx - 0.29 * s, cy + 0.24 * s, 0.20 * s, 0.28 * s);
    ellipse(cx + 0.29 * s, cy + 0.24 * s, 0.20 * s, 0.28 * s);
  }

  noFill();
  stroke(96, 78, 58, 170); strokeWeight(7);
  arc(cx - 0.185 * s, cy - 0.14 * s, 0.30 * s, 0.17 * s, PI + 0.25, TWO_PI - 0.3);
  arc(cx + 0.185 * s, cy - 0.14 * s, 0.30 * s, 0.17 * s, PI + 0.3, TWO_PI - 0.25);
  noStroke();

  socket(cx - 0.185 * s, cy + 0.02 * s, 0.12, s);
  socket(cx + 0.185 * s, cy + 0.02 * s, -0.12, s);

  noStroke();
  fill(14, 10, 8);
  beginShape();
  vertex(cx - 0.045 * s, cy + 0.17 * s);
  vertex(cx + 0.045 * s, cy + 0.17 * s);
  vertex(cx, cy + 0.31 * s);
  endShape(CLOSE);
  for (let i = 0; i < 4; i++) {
    fill(34, 25, 18, 45);
    triangle(cx - 0.05 * s + random(-3, 3), cy + 0.17 * s, cx + 0.05 * s + random(-3, 3), cy + 0.18 * s, cx + random(-3, 3), cy + 0.30 * s);
  }

  for (let i = 0; i < 5; i++) {
    fill(jcol(152, 132, 102, 42, 10));
    push(); translate(random(-3, 3), random(-2, 2));
    beginShape();
    vertex(cx - 0.17 * s, cy + 0.41 * s);
    vertex(cx + 0.17 * s, cy + 0.41 * s);
    vertex(cx + 0.14 * s, cy + 0.615 * s);
    vertex(cx - 0.14 * s, cy + 0.615 * s);
    endShape(CLOSE);
    pop();
  }

  let n = 8, tw = (0.26 * s) / n;
  for (let i = 0; i < n; i++) {
    let x = cx - 0.13 * s + i * tw;
    for (let k = 0; k < 3; k++) {
      fill(jcol(229, 217, 189, 70, 10));
      rect(x + 1.5, cy + 0.435 * s + random(-1, 1), tw - 3, 0.165 * s, 3);
    }
    stroke(42, 31, 23, 210); strokeWeight(2.5);
    line(x, cy + 0.425 * s, x + random(-1, 1), cy + 0.61 * s);
  }
  noFill();
  stroke(72, 57, 42, 190); strokeWeight(4);
  line(cx - 0.165 * s, cy + 0.428 * s, cx + 0.165 * s, cy + 0.428 * s);

  noFill();
  stroke(58, 46, 34, 130); strokeWeight(2.5);
  beginShape();
  vertex(cx + 0.10 * s, cy - 0.63 * s);
  bezierVertex(cx + 0.17 * s, cy - 0.50 * s, cx + 0.05 * s, cy - 0.42 * s, cx + 0.13 * s, cy - 0.30 * s);
  endShape();
  stroke(58, 46, 34, 90); strokeWeight(2);
  beginShape();
  vertex(cx - 0.31 * s, cy - 0.56 * s);
  bezierVertex(cx - 0.25 * s, cy - 0.46 * s, cx - 0.33 * s, cy - 0.37 * s, cx - 0.27 * s, cy - 0.27 * s);
  endShape();
  noStroke();
}

function drawWatch() {
  let cx = 980, cy = 1428, r = 54;
  softShadow(cx, cy + 8, r + 28, 14, 0.5);
  noStroke();
  for (let i = 0; i < 6; i++) {
    fill(jcol(150, 116, 62, 40, 12));
    push(); translate(random(-2, 2), random(-2, 2)); ellipse(cx, cy, r * 2 + 8); pop();
  }
  fill(162, 128, 72);
  ellipse(cx, cy, r * 2 + 8);
  for (let i = 0; i < 5; i++) {
    fill(jcol(222, 214, 192, 50, 8));
    ellipse(cx + random(-1, 1), cy + random(-1, 1), r * 2 - 6);
  }
  fill(228, 220, 198);
  ellipse(cx, cy, r * 2 - 6);

  noFill();
  stroke(50, 40, 28, 220); strokeWeight(3);
  for (let i = 0; i < 12; i++) {
    let a = i * TWO_PI / 12 - HALF_PI;
    line(cx + cos(a) * (r - 13), cy + sin(a) * (r - 13), cx + cos(a) * (r - 5), cy + sin(a) * (r - 5));
  }
  stroke(30, 24, 18, 240); strokeWeight(5);
  line(cx, cy, cx, cy - (r - 17));
  strokeWeight(4);
  line(cx, cy, cx + (r - 26) * 0.72, cy + (r - 26) * 0.72);
  noStroke();
  fill(30, 24, 18);
  ellipse(cx, cy, 7);
  noFill();
  stroke(255, 255, 255, 40); strokeWeight(6);
  arc(cx, cy, r * 1.7, r * 1.2, PI * 0.95, PI * 1.4);
  noStroke();
}

function leaf(x, y, rot, len) {
  push(); translate(x, y); rotate(rot);
  noStroke();
  for (let i = 0; i < 5; i++) {
    fill(jcol(48, 62, 38, 60, 10));
    beginShape();
    vertex(0, 0);
    bezierVertex(len * 0.3, -len * 0.28, len * 0.75, -len * 0.22, len, 0);
    bezierVertex(len * 0.75, len * 0.22, len * 0.3, len * 0.28, 0, 0);
    endShape(CLOSE);
  }
  noFill();
  stroke(28, 38, 22, 160); strokeWeight(2);
  line(0, 0, len * 0.95, 0);
  noStroke();
  pop();
}

function drawFlower() {
  noFill();
  for (let i = 0; i < 8; i++) {
    stroke(jcol(52, 66, 40, 34, 8));
    strokeWeight(random(9, 13));
    beginShape();
    vertex(330, 2010);
    bezierVertex(430, 1870, 560, 1740, 720, 1640);
    bezierVertex(800, 1610, 830, 1605, 845, 1615);
    endShape();
  }
  stroke(58, 74, 44); strokeWeight(8);
  beginShape();
  vertex(330, 2010);
  bezierVertex(430, 1870, 560, 1740, 720, 1640);
  bezierVertex(800, 1610, 830, 1605, 845, 1615);
  endShape();
  noStroke();

  leaf(520, 1795, -0.55, 95);
  leaf(660, 1685, 0.45, 85);

  let hx = 858, hy = 1622, pcx = hx, pcy = hy - 6;
  for (let i = 0; i < 5; i++) {
    let a = PI * 0.5 + (i - 2) * 0.45;
    fill(jcol(46, 60, 36, 210, 10));
    triangle(hx + cos(a) * 24, hy + sin(a) * 24 + 16, hx + cos(a) * 72, hy + sin(a) * 72 + 50, hx + cos(a + 0.22) * 30, hy + sin(a + 0.22) * 30 + 20);
  }

  for (let layer = 0; layer < 3; layer++) {
    let count = 6 - layer;
    for (let i = 0; i < count; i++) {
      let a = (i / count) * TWO_PI + layer * 0.5 + random(-0.15, 0.15);
      let len = (88 - layer * 22) * random(0.9, 1.1);
      let wdt = 34 - layer * 6;
      let droop = 0.5 + layer * 0.25;
      let tipX = pcx + cos(a) * len;
      let tipY = pcy + sin(a) * len * 0.6 + len * droop * 0.35;
      let mx = pcx + cos(a) * len * 0.55;
      let my = pcy + sin(a) * len * 0.55 + len * 0.12;
      let shade = layer === 2 ? [112, 34, 40] : (layer === 1 ? [88, 24, 30] : [60, 15, 21]);
      for (let k = 0; k < 4; k++) {
        fill(jcol(shade[0], shade[1], shade[2], 55, 12));
        push(); translate(random(-2, 2), random(-2, 2));
        beginShape();
        vertex(pcx, pcy);
        bezierVertex(mx - sin(a) * wdt, my + cos(a) * wdt, tipX - sin(a) * wdt * 0.4, tipY + cos(a) * wdt * 0.4, tipX, tipY);
        bezierVertex(tipX + sin(a) * wdt * 0.4, tipY - cos(a) * wdt * 0.4, mx + sin(a) * wdt, my - cos(a) * wdt, pcx, pcy);
        endShape(CLOSE);
        pop();
      }
    }
  }

  for (let i = 0; i < 6; i++) {
    fill(jcol(30, 8, 12, 50, 6));
    ellipse(pcx + random(-4, 4), pcy + random(-4, 4), 48 - i * 5);
  }
  fill(22, 6, 10);
  ellipse(pcx, pcy, 26);

  for (let i = 0; i < 6; i++) {
    let x = random(920, 1330), y = random(1520, 1850);
    softShadow(x, y + 5, 34, 8, 0.4);
    let a = random(TWO_PI), len = random(30, 55), wdt = random(12, 20);
    push(); translate(x, y); rotate(a);
    for (let k = 0; k < 3; k++) {
      fill(jcol(80, 22, 28, 70, 12));
      beginShape();
      vertex(0, 0);
      bezierVertex(len * 0.4, -wdt, len * 0.9, -wdt * 0.6, len, 0);
      bezierVertex(len * 0.9, wdt * 0.6, len * 0.4, wdt, 0, 0);
      endShape(CLOSE);
    }
    fill(40, 10, 14, 120);
    ellipse(len * 0.55, 0, 16, 10);
    pop();
  }
  noStroke();
}

function drawCandle() {
  let cx = 1480, baseY = 1450, topY = 1235, w = 62;
  softShadow(cx, baseY + 5, 92, 16, 0.55);
  noStroke();
  for (let i = 0; i < 8; i++) {
    fill(jcol(216, 204, 176, 32, 10));
    push(); translate(random(-2, 2), random(-2, 2));
    rect(cx - w / 2, topY, w, baseY - topY, 10);
    pop();
  }
  fill(222, 210, 182);
  rect(cx - w / 2, topY, w, baseY - topY, 10);
  for (let i = 0; i < 5; i++) {
    fill(150, 134, 104, 26);
    rect(cx + w / 2 - 16 + random(-2, 2), topY + 6, 14, baseY - topY - 12, 8);
  }
  for (let i = 0; i < 4; i++) {
    fill(246, 238, 212, 30);
    rect(cx - w / 2 + 4, topY + 8, 8, baseY - topY - 16, 4);
  }
  fill(198, 184, 152);
  ellipse(cx, topY + 3, w + 8, 18);
  fill(170, 152, 120, 150);
  ellipse(cx + 4, topY + 5, w - 18, 10);
  for (let i = 0; i < 4; i++) {
    let dx = (i % 2 === 0 ? -1 : 1) * random(13, 26);
    let dy = random(20, 95);
    for (let k = 0; k < 3; k++) {
      fill(jcol(224, 212, 184, 60, 8));
      ellipse(cx + dx + random(-2, 2), topY + dy, 10, 10 + dy * 0.35);
    }
  }
  noFill();
  stroke(25, 18, 12); strokeWeight(5);
  line(cx, topY + 2, cx + 3, topY - 14);
  noStroke();
  fill(20, 14, 10);
  ellipse(cx + 3, topY - 15, 7, 5);

  let x = cx + 3, y = topY - 20;
  for (let i = 0; i < 46; i++) {
    x += (noise(i * 0.18, 1) - 0.5) * 26 + sin(i * 0.35) * 6 - 0.7;
    y -= random(12, 22);
    let r = 5 + i * 0.75;
    let a = map(i, 0, 46, 55, 0, true);
    fill(202, 202, 208, a);
    ellipse(x, y, r * 2, r * 1.6);
    if (y < 280) break;
  }
  noStroke();
}

function canvasTexture() {
  noFill();
  for (let i = 0; i < 550; i++) {
    let x = random(width), y = random(height);
    let a = noise(x * 0.003, y * 0.003) * TWO_PI * 2;
    let len = random(20, 90);
    if (random() < 0.5) stroke(0, 0, 0, random(4, 10));
    else stroke(255, 240, 220, random(3, 8));
    strokeWeight(random(1, 4));
    line(x, y, x + cos(a) * len, y + sin(a) * len);
  }
  noStroke();
}

function vignette() {
  let ctx = drawingContext;
  let g = ctx.createRadialGradient(800, 950, 250, 800, 1000, 1350);
  g.addColorStop(0, 'rgba(0,0,0,0)');
  g.addColorStop(0.7, 'rgba(0,0,0,0.18)');
  g.addColorStop(1, 'rgba(0,0,0,0.62)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, width, height);
}

function grain() {
  loadPixels();
  for (let i = 0; i < pixels.length; i += 4) {
    let n = (random() - 0.5) * 26;
    pixels[i]     = constrain(pixels[i] + n, 0, 255);
    pixels[i + 1] = constrain(pixels[i + 1] + n, 0, 255);
    pixels[i + 2] = constrain(pixels[i + 2] + n, 0, 255);
  }
  updatePixels();
}
